   Procedure: [dbo].[usp_emailreportsdetailed_Opened_ForExport]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

     
CREATE   PROCEDURE [dbo].[usp_emailreportsdetailed_Opened_ForExport] --33819,null,null,'2021-05-01','2021-07-11',null,null,null,'',''     
(     
 ----@OffsetValue int = 0,     
 ----@PagingSize int = 20,     
 @parentid BIGINT,     
 @campaigntype NVARCHAR(20) =NULL,     
 @campaignname NVARCHAR(100)=NULL,     
 @fromdate DATE =NULL,     
 @todate DATE =NULL,     
 @mail_source NVARCHAR(200)=NULL,     
 @batchid BIGINT =NULL,     
 @reporttype NVARCHAR(50) =NULL,     
 @Recipient NVARCHAR(500),     
 @LastOpenedDate NVARCHAR(100)  
 )  
AS     
BEGIN     
--declare  
-- @parentid BIGINT,     
-- @campaigntype NVARCHAR(20) =NULL,     
-- @campaignname NVARCHAR(100)=NULL,     
-- @fromdate DATE =NULL,     
-- @todate DATE =NULL,     
-- @mail_source NVARCHAR(200)=NULL,     
-- @batchid BIGINT =NULL,     
-- @reporttype NVARCHAR(50) =NULL,     
-- @Recipient NVARCHAR(500),     
-- @LastOpenedDate NVARCHAR(100)  
-- select  @parentid=39699,@campaigntype=N'Bulk Mail Campaign'  
--  ,@campaignname=N'Aug 28 2023  3:51PM_119316713',@fromdate=N'2023-08-23',@todate=N'2023-08-29'  
--  ,@mail_source=N'',@batchid=119316713,@reporttype=N'',@Recipient=N'',@LastOpenedDate=N''  
IF @batchid=0     
BEGIN     
SET @batchid=NULL;     
END;     
IF @campaigntype=''     
BEGIN     
SET @campaigntype=NULL;     
END;     
IF @campaignname=''     
BEGIN     
SET @campaignname=NULL;     
END;     
IF @fromdate=''     
BEGIN     
SET @fromdate=NULL;     
END;     
IF @todate=''     
BEGIN     
SET @todate=NULL;     
END;     
IF @mail_source=''     
BEGIN     
SET @mail_source=NULL;     
END;     
IF @reporttype=''     
BEGIN     
SET @reporttype=NULL;     
END;     
IF @fromdate=NULL     
BEGIN     
SET @fromdate=CAST( DATEADD( m, DATEDIFF( m, 0, GETDATE( ) ), 0 ) AS DATE );     
SET @todate=CAST( GETDATE( ) AS DATE );     
END;     
  
drop table if exists #batchids     
  
CREATE TABLE #batchids     
(     
 batchid BIGINT);     
IF @mail_source IS NOT NULL     
BEGIN     
INSERT INTO #batchids     
(batchid)     
 SELECT batchid     
 FROM mysms.dbo.BatchEmail_Infos with (nolock)     
 WHERE userid=@parentid     
 AND mail_source=@mail_source     
 AND ISNULL( scheduleddate, batchinserttime ) BETWEEN @fromdate AND @todate;     
END;     
IF @batchid IS NOT NULL     
BEGIN     
INSERT INTO #batchids     
(batchid)     
 SELECT @batchid;     
END;     
DROP TABLE IF EXISTS #batch;     
DROP TABLE IF EXISTS #invalidmails;     
DROP TABLE IF EXISTS #sent;     
DROP TABLE IF EXISTS #karixreport;     
DROP TABLE IF EXISTS #kopened;     
--drop table if exists #kclicked     
DROP TABLE IF EXISTS #awsreport;     
--drop table if exists #unsubscribed     
SELECT b.batchid,     
 mail_source,     
 COALESCE( t.cname, c.campaignname,     
 CASE     
 WHEN mail_source IN( 'emails', 'csv' )     
 THEN CAST( ISNULL( scheduleddate, batchinserttime ) AS NVARCHAR(50) )+'_'+CAST( b.batchid AS NVARCHAR )     
 ELSE 'CRM_'+mail_source     
 END )     
AS campaignname,     
 CASE     
 WHEN t.id IS NOT NULL     
 THEN 'Triggered Campaign'     
 WHEN c.id IS NOT NULL     
 AND ISNULL( c.IsScheduled, 0 )=1     
 THEN 'Scheduled Campaign'     
 WHEN c.id IS NOT NULL     
 AND ISNULL( c.IsScheduled, 0 )=0     
 THEN 'Event Based Campaign'     
 WHEN mail_source IN( 'emails', 'csv' )     
 THEN 'Bulk Mail Campaign'     
 ELSE 'CRM Mails'     
 END     
AS campaigntype,     
 CAST( ISNULL( scheduleddate, batchinserttime ) AS DATE ) CampaignDate,     
 TotalRecords,     
 scheduleddate,     
 batchinserttime     
INTO #batch     
FROM mysms.dbo.BatchEmail_Infos b with (nolock)     
JOIN     
mysms.dbo.user_detail u with (nolock)     
ON u.User_ID=b.UserID     
 LEFT JOIN     
 mysms.dbo.usercampaignmaster c with (nolock)     
 ON c.ParentID=u.parentid     
 AND b.mail_source LIKE 'campaign%'     
 AND CAST( c.ID AS NVARCHAR )=replace( b.mail_source, 'Campaign :', '' )     
 LEFT JOIN     
 mysms.dbo.triggeredcampaigns t with (nolock)     
 ON c.eventid=t.eventid     
 AND t.mailcampaignid=c.id     
 LEFT JOIN     
 #batchids bd     
 ON b.batchid=bd.BatchID     
WHERE u.ParentID=@parentid     
 AND ISNULL( bd.batchid, 0 )=CASE     
 WHEN @mail_source IS NOT NULL     
 OR @batchid IS NOT NULL     
 THEN bd.batchid     
 ELSE 0     
 END     
 AND CAST( ISNULL( scheduleddate, batchinserttime ) AS DATE ) BETWEEN @fromdate AND @todate;     
  
  
SELECT e.batchid,     
 to_email,    
 COUNT( 1 )     
AS OpenedTimes,     
 MAX( CAST( event_date+' '+event_time AS DATETIME ) ) LastOpened     
INTO #kopened     
FROM mysms.dbo.EngagementEventOpenClick e with (nolock)     
JOIN     
#batch b     
ON e.BatchID=b.BatchID     
 AND ISNUMERIC( e.BatchID )=1     
 AND ISNUMERIC( b.BatchID )=1     
WHERE ISNULL( e.destination_url, '' )=''     
GROUP BY e.batchid,     
 to_email;     
     
/* start leadid and img handling */     
SELECT v.leadno,     
 ISNULL( personname, '' ) personname,     
 ISNULL( ProfileImgFileName, '' ) ProfileImgFileName,     
 email,     
 u.ID     
AS LeadID     
INTO #tbllead     
FROM mysms.dbo.Userleads_Mobile_Email v with (nolock)     
JOIN     
mysms.dbo.userleads u with (nolock)     
ON u.id=v.ulme_id    
WHERE v.parentid=@parentid  and u.parentid=@parentid   
 AND email<>'1';     
  
SELECT v.enquiryid,     
 ISNULL( personname, '' ) personname,     
 ISNULL( ProfileImgFileName, '' ) ProfileImgFileName,     
 email     
INTO #tblEnquiry     
FROM mysms.dbo.Userenquiry_Mobile_Email v with (nolock)     
JOIN     
mysms.dbo.userenquiry u with (nolock)     
ON v.enquiryid=u.enquiryid     
WHERE v.parentid=@parentid and u.parentid=@parentid     
 AND email<>'1'   
 and v.enquiryid=  
 (select max(enquiryid) from mysms.dbo.Userenquiry_Mobile_Email with (nolock) where parentid=@parentid and email<>'1'  and email=v.email)  
   
 ;     
/* end leadid and img handling */     
IF @LastOpenedDate<>''     
BEGIN     
SELECT COUNT( batchid ) OVER( )     
AS TotalRow,     
 CampaignDate,     
 campaigntype,     
 campaignname,     
 batchid,     
 SentTime,     
 Mail_ToEmail,     
 OpenedTimes,     
 LastOpened,     
 entity,     
 entityid,     
 image,     
 Personname,     
 LeadID     
FROM     
(     
 SELECT CampaignDate,     
 campaigntype,     
 campaignname,     
 b.batchid,     
 ISNULL( scheduleddate, batchinserttime )     
 AS SentTime,     
 to_email Mail_ToEmail,     
 ko.OpenedTimes,     
 ko.LastOpened,     
 CASE     
 WHEN leadno IS NOT NULL     
 THEN 'lead'     
 WHEN enquiryid IS NOT NULL     
 THEN 'enquiry'     
 ELSE ''     
 END     
 AS entity,     
 COALESCE( leadno, enquiryid, 0 ) entityid,     
 COALESCE( tbllead.ProfileImgFileName, tblenq.ProfileImgFileName, '' ) image,     
 COALESCE( tbllead.personname, tblenq.personname, '' ) Personname,     
 tblLead.LeadID     
 FROM #batch b     
  LEFT JOIN     
 #kopened ko     
 ON ko.BatchID=b.BatchID     
  LEFT JOIN     
 #tblEnquiry tblEnq     
 ON to_email=tblEnq.Email     
 LEFT JOIN     
 #tblLead tblLead     
 ON to_email=tblLead.Email     
   
) a     
WHERE Mail_ToEmail LIKE '%'+@Recipient+'%'     
 AND campaigntype=CASE     
 WHEN @campaigntype IS NULL     
 THEN campaigntype     
 ELSE @campaigntype     
 END     
 AND campaignname=CASE     
 WHEN @campaignname IS NULL     
 THEN campaignname     
 ELSE @campaignname     
 END     
 AND LastOpened IS NOT NULL     
 AND CONVERT( DATE, LastOpened )=CONVERT( DATE, @LastOpenedDate )     
--group by CampaignDate,campaigntype,campaignname,mail_source     
ORDER BY CampaignDate DESC , Mail_ToEmail asc;     
--OFFSET @OffsetValue Rows FETCH NEXT @PagingSize ROWS ONLY     
END;     
 ELSE     
BEGIN     
SELECT COUNT( batchid ) OVER( )     
AS TotalRow,     
 CampaignDate,     
 campaigntype,     
 campaignname,     
 batchid,     
 SentTime,     
 Mail_ToEmail,     
 OpenedTimes,     
 LastOpened,     
 entity,     
 entityid,     
 image,     
 Personname,     
 LeadID     
FROM     
(     
 SELECT CampaignDate,     
 campaigntype,     
 campaignname,     
 b.batchid,     
 ISNULL( scheduleddate, batchinserttime )     
 AS SentTime,     
 ko.to_email Mail_ToEmail,     
 ko.OpenedTimes,     
 ko.LastOpened,     
 CASE     
 WHEN leadno IS NOT NULL     
 THEN 'lead'     
 WHEN enquiryid IS NOT NULL     
 THEN 'enquiry'     
 ELSE ''     
 END     
 AS entity,     
 COALESCE( leadno, enquiryid, 0 ) entityid,     
 COALESCE( tbllead.ProfileImgFileName, tblenq.ProfileImgFileName, '' ) image,     
 COALESCE( tbllead.personname, tblenq.personname, '' ) Personname,     
 tblLead.LeadID     
 FROM #batch b     
 --LEFT JOIN     
 --#sent s     
 --ON b.BatchID=s.batchid     
 LEFT JOIN     
 #kopened ko     
 ON ko.BatchID=b.BatchID     
 LEFT JOIN     
 #tblEnquiry tblEnq     
 ON to_email=tblEnq.Email     
 LEFT JOIN     
 #tblLead tblLead     
 ON to_email=tblLead.Email     
) a     
WHERE Mail_ToEmail LIKE '%'+@Recipient+'%'     
 AND campaigntype=CASE     
 WHEN @campaigntype IS NULL     
 THEN campaigntype     
 ELSE @campaigntype     
 END     
 AND campaignname=CASE     
 WHEN @campaignname IS NULL     
 THEN campaignname     
 ELSE @campaignname     
 END     
 AND LastOpened IS NOT NULL     
--group by CampaignDate,campaigntype,campaignname,mail_source     
ORDER BY CampaignDate DESC , Mail_ToEmail asc;;     
--OFFSET @OffsetValue Rows FETCH NEXT @PagingSize ROWS ONLY     
END;     
DROP TABLE IF EXISTS #batch;     
DROP TABLE IF EXISTS #invalidmails;     
DROP TABLE IF EXISTS #sent;     
DROP TABLE IF EXISTS #karixreport;     
DROP TABLE IF EXISTS #kopened;     
--drop table if exists #kclicked     
DROP TABLE IF EXISTS #awsreport;     
--drop table if exists #unsubscribed     
DROP TABLE IF EXISTS #tblEnquiry;     
DROP TABLE IF EXISTS #tbllead;     
drop table if exists #batchids  
END; 


GO

