CREATE   PROCEDURE [dbo].[usp_emailreportsdetailed_Opened_suffix] --0,20,39008,null,null,'2022-06-16','2022-06-17',null,89400860,null,'',''   
(   
 @OffsetValue INT =0,   
 @PagingSize INT =20,   
 @parentid BIGINT,   
 @campaigntype NVARCHAR(20) =NULL,   
 @campaignname NVARCHAR(100)=NULL,   
 @fromdate DATE =NULL,   
 @todate DATE =NULL,   
 @mail_source NVARCHAR(200)=NULL,   
 @batchid BIGINT =NULL,   
 @reporttype NVARCHAR(50) =NULL,   
 @Recipient NVARCHAR(500),   
 @LastOpenedDate NVARCHAR(100))   
AS   
BEGIN   
   
 --declare --@parentid bigint=335,   
 --@campaigntype nvarchar(20)=null,   
 --@campaignname nvarchar(100)=null,   
 --@fromdate date='2022-06-16',   
