IF @campaigntype=''   
BEGIN   
SET @campaigntype=NULL;   
END;   
IF @campaignname=''   
BEGIN   
SET @campaignname=NULL;   
END;   
IF @fromdate=''   
BEGIN   
SET @fromdate=NULL;   
END;   
IF @todate=''   
BEGIN   
SET @todate=NULL;   
END;   
IF @mail_source=''   
BEGIN   
