--left join #batch b   
--on t.batchid=b.BatchID   
--where t.UserID=@parentid and Status='Unsubscribed'   
--group by emails,isnull(t.batchid,0),userid   
SELECT e.BatchID,   
 e.cust_ref_id,   
 event_status,   
 event_desc,   
 Reason   
AS Description,   
 CAST( event_time AS DATETIME )   
AS Delivereddate   
INTO #karixreport   
FROM mysms.dbo.EmailDeliveryStatus e with (nolock)   
JOIN   
#batch b   
ON e.BatchID=b.BatchID   
WHERE event_status='001'  
   
   
--select 'k',count(1) from #karixreport   
   
CREATE TABLE #awsreport   
(   
 batchid BIGINT,   
 apiheader NVARCHAR(100),   
 mailstatus NVARCHAR(50),   
 description NVARCHAR(200),   
 eventdate DATETIME);   
INSERT INTO #awsreport   
(batchid,   
 apiheader,   
 mailstatus,   
 description,   
 eventdate)   
 SELECT e.batchid,   
 APIHeader,   
 'Delivered'   
 AS mailstatus,   
 ''   
 AS description,   
 Delivereddate   
 FROM mysms.dbo.Maildeliveries e with (nolock)   
 JOIN   
 #batch b   
 ON e.BatchID=b.BatchID   
 UNION   
 SELECT e.batchid,   
 apiheader,   
 'Bounced'   
 AS mailstatus,   
 CAST( bouncetype AS NVARCHAR(20) )+'- '+BounceSubType   
 AS Description,   
 createdon   
 FROM mysms.dbo.Mailbounces e with (nolock)   
 JOIN   
 #batch b   
 ON e.BatchID=b.BatchID;   
   
 --select 'a',count(1) from #awsreport   
   
drop table if exists #sent   
SELECT e.mail_batchid batchid,e.mail_guid,   
 e.Mail_ToEmail,   
 CASE   
 WHEN smtpserver='aws'   
 THEN a.mailstatus   
 WHEN smtpserver='karix'   
 THEN k.event_desc   
 ELSE 'Sent'   
 END   
AS MailStatus,   
 CASE   
 WHEN smtpserver='aws'   
 THEN a.description   
 WHEN smtpserver='karix'   
 THEN k.description   
 END   
AS Description,   
 CASE   
 WHEN smtpserver='aws'   
 THEN a.eventdate   
 WHEN smtpserver='karix'   
 THEN k.Delivereddate   
 END   
AS delivereddate,   
 smtpserver   
INTO #sent   
  FROM 
     --mysmstrans.dbo.emailsreportsent e with (nolock)   
         (
		  select cast(guid as nvarchar(100)) as mail_guid,email_id as mail_toemail,e.batchid as mail_batchid , '' as smtpserver from     
		    ClientEmails e with (nolock)     
			union all     
			select cast(guid as nvarchar(100)),email_id,e.batchid , '' as smtpserver from     
			ThirtyDaysClientEmails e with (nolock)     
		)     
		e
JOIN   
#batch b   
ON e.Mail_BatchID=b.BatchID   
 LEFT JOIN   
 #karixreport k   
 ON k.BatchID=e.Mail_BatchID   
 AND k.cust_ref_id=e.Mail_GUID   
 LEFT JOIN   
 #awsreport a   
 ON a.BatchID=e.Mail_BatchID   
 AND a.apiheader=e.Mail_GUID;   
   
--select 's',count(1) from #sent   
   
   
SELECT e.mail_batchid batchid,   
 e.Mail_ToEmail,   
 'Not Sent'   
AS mailstatus   
INTO #invalidmails   
 FROM
  -- mysmstrans.dbo.invalid_mail_emailsreport e with (nolock)   
   tbl_InvalidEmailID_KarixAPI e with (nolock)   
JOIN   
#batch b   
ON e.Mail_BatchID=b.BatchID;   
   
--select 'i',count(1) from #invalidmails   
   
   
SELECT  e.batchid,   
 to_email,   
 COUNT(distinct to_email )   
AS OpenedTimes,   
 MAX( CAST( event_date+' '+event_time AS DATETIME ) ) LastOpened   
INTO #kopened   
FROM mysms.dbo.EngagementEventOpenClick e with (nolock)   
JOIN   
#batch b   
ON e.BatchID=b.BatchID   
 AND ISNUMERIC( e.BatchID )=1   
 AND ISNUMERIC( b.BatchID )=1   
WHERE ISNULL( e.destination_url, '' )='' 
and cast(e.CreatedOn as date)  between @fromdate and @todate 
GROUP BY e.batchid,   
 to_email;   
   
--select 'o',count(1) from #kopened   
   
--order by cast((event_date + ' '+event_time) as datetime)   
--select e.batchid,e.customer_reference_id ,   
--max(cast((event_date + ' '+event_time) as datetime)) LastClickedTime   
--into #kclicked   
--from   
--mysms.dbo.[EngagementEventOpenClick] e with (nolock)   
--join #batch b on e.BatchID=b.BatchID   
--where isnull(e.destination_url,'')<>''   
--group by e.batchid,e.customer_reference_id   
----order by cast((event_date + ' '+event_time) as datetime) desc   
/* start leadid and img handling */   
   
drop table if exists #tbllead   
SELECT v.leadno,   
 ISNULL( personname, '' ) personname,   
 ISNULL( ProfileImgFileName, '' ) ProfileImgFileName,   
 email,   
 u.ID   
AS LeadID   
INTO #tbllead   
FROM mysms.dbo.Userleads_Mobile_Email v with (nolock)   
JOIN   
mysms.dbo.userleads u with (nolock)   
ON u.parentid=v.parentid   
 AND v.leadno=u.LeadNo   
WHERE v.parentid=@parentid   
 AND email<>'1'
  and v.ulme_id=(select max(ulme_id) from mysms.dbo.Userleads_Mobile_Email with (nolock) where email=v.email )

 ;   
   
drop table if exists #tblenquiry   
SELECT v.enquiryid,   
 ISNULL( personname, '' ) personname,   
 ISNULL( ProfileImgFileName, '' ) ProfileImgFileName,   
 email   
INTO #tblEnquiry   
FROM mysms.dbo.Userenquiry_Mobile_Email v with (nolock)   
JOIN   
mysms.dbo.userenquiry u with (nolock)   
ON u.parentid=v.parentid   
 AND v.enquiryid=u.enquiryid   
WHERE v.parentid=@parentid   
 AND email<>'1'
   and v.enquiryid=(select max(enquiryid) from mysms.dbo.Userenquiry_Mobile_Email with (nolock) where email=v.email )

 ;   
/* end leadid and img handling */   
   
IF @LastOpenedDate<>''   
BEGIN   
SELECT COUNT( batchid ) OVER( )   
AS TotalRow,   
 CampaignDate,   
 campaigntype,   
 campaignname,   
 batchid,   
 SentTime,   
 Mail_ToEmail,   
 OpenedTimes,   
 LastOpened,   
 entity,   
 entityid,   
 image,   
 Personname,   
 LeadID   
FROM   
(   
 SELECT CampaignDate,   
 campaigntype,   
 campaignname,   
 b.batchid,   
 ISNULL( scheduleddate, batchinserttime )   
 AS SentTime,   
 ISNULL( s.Mail_ToEmail, i.Mail_ToEmail ) Mail_ToEmail,   
 ko.OpenedTimes,   
 ko.LastOpened,   
 CASE   
 WHEN leadno IS NOT NULL   
 THEN 'lead'   
 WHEN enquiryid IS NOT NULL   
 THEN 'enquiry'   
 ELSE ''   
 END   
 AS entity,   
 COALESCE( leadno, enquiryid, 0 ) entityid,   
 COALESCE( tbllead.ProfileImgFileName, tblenq.ProfileImgFileName, '' ) image,   
 COALESCE( tbllead.personname, tblenq.personname, '' ) Personname,   
 tblLead.LeadID   
 FROM #batch b   
 LEFT JOIN   
 #sent s   
 ON b.BatchID=s.batchid   
 LEFT JOIN   
 #kopened ko   
 ON ko.BatchID=b.BatchID and ko.batchid=s.batchid and ko.to_email=s.Mail_ToEmail   
 --left join #kclicked kc on kc.BatchID=b.BatchID   
 LEFT JOIN   
 #invalidmails i   
 ON i.batchid=b.BatchID and ko.batchid=s.batchid   
 --left join #unsubscribed u on u.Batchid=b.BatchID   
 LEFT JOIN   
 #tblEnquiry tblEnq   
 ON ISNULL( s.Mail_ToEmail, i.Mail_ToEmail )=tblEnq.Email   
 LEFT JOIN   
 #tblLead tblLead   
 ON ISNULL( s.Mail_ToEmail, i.Mail_ToEmail )=tblLead.Email   
 --union   
 --select CampaignDate,mail_source ,campaigntype,campaignname,b.batchid,isnull(scheduleddate,batchinserttime) as SentTime,   
 --s.Mail_ToEmail,s.MailStatus,null as OpenedTimes,null as LastOpened   
 --from   
 --#batch b   
 --left join #invalidmails s on s.batchid=b.BatchID   
) a   
WHERE   
 Mail_ToEmail LIKE '%'+@Recipient+'%'   
 AND campaigntype=CASE   
 WHEN @campaigntype IS NULL   
 THEN campaigntype   
 ELSE @campaigntype   
 END   
 AND campaignname=CASE   
 WHEN @campaignname IS NULL   
 THEN campaignname   
 ELSE @campaignname   
 END   
 AND LastOpened IS NOT NULL   
 AND CONVERT( DATE, LastOpened )=CONVERT( DATE, @LastOpenedDate )   
--group by a.BatchID,CampaignDate,campaigntype,campaignname--,mail_source   
   
--group by CampaignDate,   
-- campaigntype,   
-- campaignname,   
-- batchid,   
-- SentTime,   
-- Mail_ToEmail,   
-- OpenedTimes,   
-- LastOpened,   
-- entity,   
-- entityid,   
-- image,   
-- Personname,   
-- LeadID   
ORDER BY CampaignDate DESC   
OFFSET @OffsetValue ROWS FETCH NEXT @PagingSize ROWS ONLY;   
END;   
 ELSE   
BEGIN   
SELECT COUNT( batchid ) OVER( )   
AS TotalRow,   
 CampaignDate,   
 campaigntype,   
 campaignname,   
 batchid,   
 SentTime,   
 Mail_ToEmail,   
 OpenedTimes,   
 LastOpened,   
 entity,   
 entityid,   
 image,   
 Personname,   
 LeadID   
FROM   
(   
 SELECT distinct CampaignDate,   
 campaigntype,   
 campaignname,   
 b.batchid,   
 ISNULL( scheduleddate, batchinserttime )   
 AS SentTime,   
 ISNULL( s.Mail_ToEmail, i.Mail_ToEmail ) Mail_ToEmail,   
 ko.OpenedTimes,   
 ko.LastOpened,   
 CASE   
 WHEN leadno IS NOT NULL   
 THEN 'lead'   
 WHEN enquiryid IS NOT NULL   
 THEN 'enquiry'   
 ELSE ''   
 END   
 AS entity,   
 COALESCE( leadno, enquiryid, 0 ) entityid,   
 COALESCE( tbllead.ProfileImgFileName, tblenq.ProfileImgFileName, '' ) image,   
 COALESCE( tbllead.personname, tblenq.personname, '' ) Personname,   
 tblLead.LeadID   
 FROM #batch b   
 LEFT JOIN   
 #sent s   
 ON b.BatchID=s.batchid   
 LEFT JOIN   
 #kopened ko   
 ON ko.BatchID=b.BatchID and ko.batchid=s.batchid and ko.to_email=s.Mail_ToEmail   
 --left join #kclicked kc on kc.BatchID=b.BatchID   
  LEFT JOIN   
   #invalidmails i   
  ON i.batchid=b.BatchID and i.batchid=s.batchid     
 --left join #unsubscribed u on u.Batchid=b.BatchID   
 LEFT JOIN   
 #tblEnquiry tblEnq   
 ON ISNULL( s.Mail_ToEmail, i.Mail_ToEmail )=tblEnq.Email   
 LEFT JOIN   
 #tblLead tblLead   
 ON ISNULL( s.Mail_ToEmail, i.Mail_ToEmail )=tblLead.Email   
   
   
 --union   
 --select CampaignDate,mail_source ,campaigntype,campaignname,b.batchid,isnull(scheduleddate,batchinserttime) as SentTime,   
 --s.Mail_ToEmail,s.MailStatus,null as OpenedTimes,null as LastOpened   
 --from   
 --#batch b   
 --left join #invalidmails s on s.batchid=b.BatchID   
) a   
WHERE Mail_ToEmail LIKE '%'+@Recipient+'%'   
 AND campaigntype=CASE   
 WHEN @campaigntype IS NULL   
 THEN campaigntype   
 ELSE @campaigntype   
 END   
 AND campaignname=CASE   
 WHEN @campaignname IS NULL   
 THEN campaignname   
 ELSE @campaignname   
 END   
 AND LastOpened IS NOT NULL   
--group by a.BatchID,CampaignDate,campaigntype,campaignname --,mail_source   
--group by CampaignDate,   
-- campaigntype,   
-- campaignname,   
-- batchid,   
-- SentTime,   
-- Mail_ToEmail,   
-- OpenedTimes,   
-- LastOpened,   
-- entity,   
-- entityid,   
-- image,   
-- Personname,   
-- LeadID   
   
ORDER BY CampaignDate DESC   
OFFSET @OffsetValue ROWS FETCH NEXT @PagingSize ROWS ONLY;   
END;   
   
DROP TABLE IF EXISTS #batch;   
DROP TABLE IF EXISTS #invalidmails;   
DROP TABLE IF EXISTS #sent;   
DROP TABLE IF EXISTS #karixreport;   
DROP TABLE IF EXISTS #kopened;   
--drop table if exists #kclicked   
DROP TABLE IF EXISTS #awsreport;   
--drop table if exists #unsubscribed   
DROP TABLE IF EXISTS #tblEnquiry;   
DROP TABLE IF EXISTS #tbllead;   
END;   


