--if @reporttype='unsubscribe'                
--begin        
IF @UnsubscribedFromDate<>''
   AND @UnsubscribedToDate<>''
BEGIN
SELECT COUNT( u.BatchID ) OVER( )
AS                                                                           TotalRow, 
