       ISNULL( personname, '' )         personname, 
       ISNULL( ProfileImgFileName, '' ) ProfileImgFileName, 
       email, 
       u.ID
AS                                      LeadID
INTO #tbllead
FROM mysms.dbo.Userleads_Mobile_Email v( NOLOCK )
JOIN
mysms.dbo.userleads( NOLOCK ) u
ON u.parentid=v.parentid
   AND v.leadno=u.LeadNo
WHERE v.parentid=@parentid
      AND email<>'1';
SELECT v.enquiryid, 
       ISNULL( personname, '' )         personname, 
       ISNULL( ProfileImgFileName, '' ) ProfileImgFileName, 
       email
INTO #tblEnquiry
FROM mysms.dbo.Userenquiry_Mobile_Email v( NOLOCK )
JOIN
mysms.dbo.userenquiry( NOLOCK ) u
ON u.parentid=v.parentid
