CREATE   PROCEDURE [dbo].[usp_emailreportssummary_ListViewPagination_ForExport] --335,null,null,'2021-06-01','2021-07-09' 
( 
 --@OffsetValue int = 0, 
 --@PagingSize int = 20, 
 @parentid BIGINT, 
 @campaigntype NVARCHAR(20) =NULL, 
 @campaignname NVARCHAR(100)=NULL, 
 @fromdate DATE =NULL, 
 @todate DATE =NULL) 
AS 
BEGIN 
--declare @parentid bigint=335, 
--@campaigntype nvarchar(20)=null, 
--@campaignname nvarchar(100)=null, 
--@fromdate date='2021-07-01', 
--@todate date='2021-07-09' 
IF @campaigntype='' 
BEGIN 
SET @campaigntype=NULL; 
END; 
IF @campaignname='' 
BEGIN 
SET @campaignname=NULL; 
END; 
IF @fromdate='' 
BEGIN 
SET @fromdate=NULL; 
END; 
IF @todate='' 
BEGIN 
SET @todate=NULL; 
END; 
IF @fromdate=NULL 
BEGIN 
SET @fromdate=CAST( DATEADD( m, DATEDIFF( m, 0, GETDATE( ) ), 0 ) AS DATE ); 
SET @todate=CAST( GETDATE( ) AS DATE ); 
END; 
DROP TABLE IF EXISTS #batcht; 
DROP TABLE IF EXISTS #batch; 
DROP TABLE IF EXISTS #invalidmails; 
DROP TABLE IF EXISTS #sent; 
DROP TABLE IF EXISTS #kdelivered; 
DROP TABLE IF EXISTS #kbounced; 
DROP TABLE IF EXISTS #kopened; 
DROP TABLE IF EXISTS #kclicked; 
DROP TABLE IF EXISTS #adstatus; 
DROP TABLE IF EXISTS #abstatus; 
DROP TABLE IF EXISTS #dateinvalidmails; 
DROP TABLE IF EXISTS #datesent; 
DROP TABLE IF EXISTS #datekdelivered; 
DROP TABLE IF EXISTS #datekbounced; 
DROP TABLE IF EXISTS #datekopened; 
DROP TABLE IF EXISTS #datekclicked; 
DROP TABLE IF EXISTS #dateadstatus; 
DROP TABLE IF EXISTS #dateabstatus; 
DROP TABLE IF EXISTS #unsubscribed; 
SELECT b.batchid, 
 mail_source, 
 CAST( ISNULL( scheduleddate, batchinserttime ) AS DATE ) batchinserttime, 
 COALESCE( t.cname, c.campaignname, 
 CASE 
 WHEN mail_source IN( 'emails', 'csv' ) 
 THEN CAST( ISNULL( scheduleddate, batchinserttime ) AS NVARCHAR(50) )+'_'+CAST( b.batchid AS NVARCHAR ) 
 ELSE 'CRM_'+mail_source 
 END ) 
AS campaignname, 
 CASE 
 WHEN t.id IS NOT NULL 
 THEN 'Triggered Campaign' 
 WHEN c.id IS NOT NULL 
 AND ISNULL( c.IsScheduled, 0 )=1 
 THEN 'Scheduled Campaign' 
 WHEN c.id IS NOT NULL 
 AND ISNULL( c.IsScheduled, 0 )=0 
 THEN 'Event Based Campaign' 
 WHEN mail_source IN( 'emails', 'csv' ) 
 THEN 'Bulk Mail Campaign' 
 ELSE 'CRM Mails' 
 END 
AS campaigntype, 
 CAST( ISNULL( scheduleddate, batchinserttime ) AS DATE ) CampaignDate, 
 TotalRecords--,Delivered,Bounced,TotalSent 
INTO #batcht 
FROM MySMS.dbo.BatchEmail_Infos b with (nolock) 
JOIN 
MySMS.dbo.user_detail u with (nolock) 
ON u.User_ID=b.UserID 
 LEFT JOIN 
 MySMS.dbo.usercampaignmaster c with (nolock) 
 ON c.ParentID=u.parentid 
 AND b.mail_source LIKE 'campaign%' 
 AND CAST( c.ID AS NVARCHAR )=replace( b.mail_source, 'Campaign :', '' ) 
 LEFT JOIN 
 MySMS.dbo.triggeredcampaigns t with (nolock) 
 ON c.eventid=t.eventid 
 AND t.mailcampaignid=c.id 
WHERE u.ParentID=@parentid 
 AND CAST( ISNULL( scheduleddate, batchinserttime ) AS DATE ) BETWEEN @fromdate AND @todate; 
SELECT * 
INTO #batch 
FROM #batcht 
WHERE campaigntype=CASE 
 WHEN @campaigntype IS NULL 
 THEN campaigntype 
 ELSE @campaigntype 
 END 
 AND campaignname=CASE 
 WHEN @campaignname IS NULL 
 THEN campaignname 
 ELSE @campaignname 
 END; 
SELECT t.batchid, 
 COUNT( 1 ) 
AS TotalUnsubscribed 
INTO #unsubscribed 
FROM MySMS.dbo.tbl_subscription t with (nolock) 
JOIN 
#batch b 
ON b.BatchID=t.batchid 
GROUP BY t.batchid; 
SELECT e.BatchID, 
 COUNT( 1 ) KDelivered, 
 CAST( ISNULL( e.event_time, createdon ) AS DATE ) event_time 
INTO #datekdelivered 
FROM MySMS.dbo.EmailDeliveryStatus e with (nolock) 
JOIN 
#batch b 
ON e.BatchID=b.BatchID 
WHERE event_status='001' 
GROUP BY e.batchid, 
 CAST( ISNULL( e.event_time, createdon ) AS DATE ); 
SELECT e.BatchID, 
 SUM( kdelivered ) KDelivered 
INTO #kdelivered 
FROM #datekdelivered e 
GROUP BY e.batchid; 
SELECT e.BatchID, 
 COUNT( 1 ) KBounced, 
 CAST( ISNULL( NULLIF( NULLIF( LTRIM( RTRIM( e.event_time ) ), '' ), 'null' ), createdon ) AS DATE ) event_time 
INTO #datekbounced 
FROM MySMS.dbo.EmailDeliveryStatus e with (nolock) 
JOIN 
#batch b 
ON e.BatchID=b.BatchID 
WHERE event_status<>'001' 
GROUP BY e.batchid, 
 CAST( ISNULL( NULLIF( NULLIF( LTRIM( RTRIM( e.event_time ) ), '' ), 'null' ), createdon ) AS DATE ); 
SELECT e.BatchID, 
 SUM( Kbounced ) KBounced 
INTO #kbounced 
FROM #datekbounced e 
GROUP BY e.batchid; 
SELECT e.batchid, 
 COUNT( 1 ) Delivered, 
 CAST( DATEADD( mi, 330, e.Delivereddate ) AS DATE ) Delivereddate 
INTO #Dateadstatus 
FROM MySMS.dbo.Maildeliveries e with (nolock) 
JOIN 
#batch b 
ON e.BatchID=b.BatchID 
GROUP BY e.batchid, 
 CAST( DATEADD( mi, 330, e.Delivereddate ) AS DATE ); 
SELECT e.batchid, 
 SUM( delivered ) Delivered 
INTO #adstatus 
FROM #Dateadstatus e 
GROUP BY e.batchid; 
SELECT e.batchid, 
 COUNT( 1 ) bounced, 
 CAST( e.createdon AS DATE ) createdon 
INTO #dateabstatus 
FROM MySMS.dbo.Mailbounces e with (nolock) 
JOIN 
#batch b 
ON e.BatchID=b.BatchID 
GROUP BY e.batchid, 
 CAST( e.createdon AS DATE ); 
SELECT e.batchid, 
 SUM( bounced ) bounced 
INTO #abstatus 
FROM #dateabstatus e 
GROUP BY e.batchid; 
SELECT e.mail_batchid batchid, 
 COUNT( 1 ) Sent, 
 0 NotSent, 
 CAST( e.Mail_InsertedDate AS DATE ) Mail_InsertedDate 
--sum(case when Mail_Error='sent' then 1 else 0 end) Sent 
--,sum(case when Mail_Error<>'sent' then 1 else 0 end) NotSent 
INTO #datesent 
FROM mysmstrans.dbo.emailsreportsent e with (nolock) 
JOIN 
#batch b 
ON e.Mail_BatchID=b.BatchID 
GROUP BY e.Mail_BatchID, 
 CAST( e.Mail_InsertedDate AS DATE ); 
--select * from #batch 
--select * from #datesent 
SELECT batchid, 
 SUM( Sent ) Sent, 
 SUM( notsent ) NotSent 
--sum(case when Mail_Error='sent' then 1 else 0 end) Sent 
--,sum(case when Mail_Error<>'sent' then 1 else 0 end) NotSent 
INTO #sent 
FROM #datesent e 
GROUP BY e.BatchID; 
SELECT e.mail_batchid batchid, 
 COUNT( 1 ) InvalidNotSent, 
 CAST( e.Mail_InsertedDate AS DATE ) Mail_InsertedDate 
INTO #dateinvalidmails 
FROM mysmstrans.dbo.invalid_mail_emailsreport e with (nolock) 
JOIN 
#batch b 
ON e.Mail_BatchID=b.BatchID 
GROUP BY e.Mail_BatchID, 
 CAST( e.Mail_InsertedDate AS DATE ); 
SELECT batchid, 
 SUM( invalidnotsent ) InvalidNotSent 
INTO #invalidmails 
FROM #dateinvalidmails e 
GROUP BY e.BatchID; 
SELECT e.batchid, 
 COUNT( e.customer_reference_id ) Opened, 
 e.event_date 
INTO #datekopened 
FROM MySMS.dbo.EngagementEventOpenClick e with (nolock) 
JOIN 
#batch b 
ON e.BatchID=b.BatchID 
 AND ISNUMERIC( e.BatchID )=1 
 AND ISNUMERIC( b.BatchID )=1 
WHERE ISNULL( e.destination_url, '' )='' 
GROUP BY e.batchid, 
 e.event_date; 
SELECT e.batchid, 
 COUNT( DISTINCT e.customer_reference_id ) Opened 
INTO #kopened 
FROM MySMS.dbo.EngagementEventOpenClick e with (nolock) 
JOIN 
#batch b 
ON e.BatchID=b.BatchID 
 AND ISNUMERIC( e.BatchID )=1 
 AND ISNUMERIC( b.BatchID )=1 
WHERE ISNULL( e.destination_url, '' )='' 
GROUP BY e.batchid; 
SELECT e.batchid, 
 COUNT( e.customer_reference_id ) Clicked, 
 e.event_date 
INTO #datekclicked 
FROM MySMS.dbo.EngagementEventOpenClick e with (nolock) 
JOIN 
#batch b 
ON e.BatchID=b.BatchID 
 AND ISNUMERIC( e.BatchID )=1 
 AND ISNUMERIC( b.BatchID )=1 
WHERE ISNULL( e.destination_url, '' )<>'' 
GROUP BY e.batchid, 
 e.event_date; 
SELECT e.batchid, 
 COUNT( DISTINCT e.customer_reference_id ) Clicked 
INTO #kclicked 
FROM MySMS.dbo.EngagementEventOpenClick e with (nolock) 
JOIN 
#batch b 
ON e.BatchID=b.BatchID 
 AND ISNUMERIC( e.BatchID )=1 
 AND ISNUMERIC( b.BatchID )=1 
WHERE ISNULL( e.destination_url, '' )<>'' 
GROUP BY e.batchid; 
SELECT b.batchid, 
 COUNT( mail_toemail ) InvalidMails 
INTO #badmails 
FROM mysmstrans.dbo.Bad_Emails e 
JOIN 
#batch b 
ON b.batchid=e.Mail_BatchID 
GROUP BY b.batchid; 
SELECT batchid, 
 inqueue 
INTO #inqueue 
FROM 
( 
 SELECT batchid, 
 COUNT( 1 ) inqueue 
 FROM mysms.dbo.emailsfilter e with (nolock) 
 JOIN 
 #batch b 
 ON b.batchid=e.Mail_BatchID 
 GROUP BY b.BatchID 
 UNION 
 SELECT batchid, 
 COUNT( 1 ) inqueue 
 FROM mysmstrans.dbo.Mail_EmailsReport00 e with (nolock) 
 JOIN 
 #batch b 
 ON b.batchid=e.Mail_BatchID 
 GROUP BY b.BatchID 
 UNION 
 SELECT batchid, 
 COUNT( 1 ) inqueue 
 FROM mysmstrans.dbo.Mail_EmailsReport01 e with (nolock) 
 JOIN 
 #batch b 
 ON b.batchid=e.Mail_BatchID 
 GROUP BY b.BatchID 
 UNION 
 SELECT batchid, 
 COUNT( 1 ) inqueue 
 FROM mysmstrans.dbo.Mail_EmailsReport02 e with (nolock) 
 JOIN 
 #batch b 
 ON b.batchid=e.Mail_BatchID 
 GROUP BY b.BatchID 
 UNION 
 SELECT batchid, 
 COUNT( 1 ) inqueue 
 FROM mysmstrans.dbo.Mail_EmailsReport03 e with (nolock) 
 JOIN 
 #batch b 
 ON b.batchid=e.Mail_BatchID 
 GROUP BY b.BatchID 
 UNION 
 SELECT batchid, 
 COUNT( 1 ) inqueue 
 FROM mysmstrans.dbo.Mail_EmailsReport04 e with (nolock) 
 JOIN 
 #batch b 
 ON b.batchid=e.Mail_BatchID 
 GROUP BY b.BatchID 
 UNION 
 SELECT batchid, 
 COUNT( 1 ) inqueue 
 FROM mysmstrans.dbo.Mail_EmailsReport05 e with (nolock) 
 JOIN 
 #batch b 
 ON b.batchid=e.Mail_BatchID 
 GROUP BY b.BatchID 
 UNION 
 SELECT batchid, 
 COUNT( 1 ) inqueue 
 FROM mysmstrans.dbo.Mail_EmailsReport2 e with (nolock) 
 JOIN 
 #batch b 
 ON b.batchid=e.Mail_BatchID 
 GROUP BY b.BatchID 
 UNION 
 SELECT batchid, 
 COUNT( 1 ) inqueue 
 FROM mysmstrans.dbo.Mail_EmailsReport1 e with (nolock) 
 JOIN 
 #batch b 
 ON b.batchid=e.Mail_BatchID 
 GROUP BY b.BatchID 
) a; 
SELECT COUNT( BatchID ) OVER( ) 
AS TotalRow, 
 batchid, 
 CampaignDate, 
 mail_source, 
 campaigntype, 
 campaignname, 
 SUM( TotalRecords ) 
AS Recipients, 
 SUM( ISNULL( delivered, 0 )+ISNULL( Kdelivered, 0 ) ) 
AS Delivered, 
 SUM( ISNULL( Bounced, 0 )+ISNULL( kBounced, 0 ) ) 
AS bounced, 
 SUM( ISNULL( opened, 0 ) ) 
AS Opened, 
 SUM( ISNULL( clicked, 0 ) ) Clicked, 
 SUM( ISNULL( sent, 0 ) ) Sent, 
 SUM( ISNULL( notsent, 0 )+ISNULL( invalidnotsent, 0 ) ) NotSent, 
 ISNULL( TotalUnsubscribed, 0 ) 
AS TotalUnsubscribed, 
 ISNULL( InvalidMails, 0 ) 
AS BadMails, 
 ISNULL( inqueue, 0 ) 
AS InQueue 
FROM 
( 
 SELECT b.batchid, 
 CampaignDate, 
 mail_source, 
 campaigntype, 
 campaignname, 
 TotalRecords, 
 Sent, 
 NotSent, 
 Delivered, 
 Bounced, 
 Kdelivered, 
 Kbounced, 
 Opened, 
 Clicked, 
 InvalidNotSent, 
 TotalUnsubscribed, 
 e.InvalidMails, 
 q.inqueue 
 FROM #batch b 
 LEFT JOIN 
 #sent s 
 ON b.BatchID=s.batchid 
 LEFT JOIN 
 #abstatus ab 
 ON ab.batchid=b.BatchID 
 LEFT JOIN 
 #adstatus ad 
 ON ad.batchid=b.BatchID 
 LEFT JOIN 
 #kdelivered k 
 ON k.BatchID=b.BatchID 
 LEFT JOIN 
 #kbounced kb 
 ON kb.BatchID=b.BatchID 
 LEFT JOIN 
 #kopened ko 
 ON ko.BatchID=b.BatchID 
 LEFT JOIN 
 #kclicked kc 
 ON kc.BatchID=b.BatchID 
 LEFT JOIN 
 #invalidmails i 
 ON i.batchid=b.BatchID 
 LEFT JOIN 
 #unsubscribed u 
 ON u.batchid=b.BatchID 
 LEFT JOIN 
 #badmails e 
 ON b.batchid=e.BatchID 
 LEFT JOIN 
 #inqueue q 
 ON b.batchid=q.batchid 
) a 
WHERE campaigntype=CASE 
 WHEN @campaigntype IS NULL 
 THEN campaigntype 
 ELSE @campaigntype 
 END 
 AND campaignname=CASE 
 WHEN @campaignname IS NULL 
 THEN campaignname 
 ELSE @campaignname 
 END 
GROUP BY batchid, 
 CampaignDate, 
 campaigntype, 
 campaignname, 
 mail_source, 
 TotalUnsubscribed, 
 InvalidMails, 
 inqueue 
ORDER BY CampaignDate DESC; 
-- OFFSET @OffsetValue Rows FETCH NEXT @PagingSize ROWS ONLY 
DROP TABLE IF EXISTS #batcht; 
DROP TABLE IF EXISTS #batch; 
DROP TABLE IF EXISTS #invalidmails; 
DROP TABLE IF EXISTS #sent; 
DROP TABLE IF EXISTS #kdelivered; 
DROP TABLE IF EXISTS #kbounced; 
DROP TABLE IF EXISTS #kopened; 
DROP TABLE IF EXISTS #kclicked; 
DROP TABLE IF EXISTS #adstatus; 
DROP TABLE IF EXISTS #abstatus; 
DROP TABLE IF EXISTS #unsubscribed; 
DROP TABLE IF EXISTS #dateinvalidmails; 
DROP TABLE IF EXISTS #datesent; 
DROP TABLE IF EXISTS #datekdelivered; 
DROP TABLE IF EXISTS #datekbounced; 
DROP TABLE IF EXISTS #datekopened; 
DROP TABLE IF EXISTS #datekclicked; 
DROP TABLE IF EXISTS #dateadstatus; 
DROP TABLE IF EXISTS #dateabstatus; 
END; 



