CREATE   PROCEDURE [dbo].[usp_emailreportssummary_ListViewPagination_ForExport_KarixAPI] --34594, '', '', '2023-10-14', '2023-10-20'                    
(      
  --@OffsetValue  INT          =0,       
  --@PagingSize   INT          =20,       
  @parentid     BIGINT,       
  @campaigntype NVARCHAR(20) =NULL,       
  @campaignname NVARCHAR(100)=NULL,       
  @fromdate     DATE         =NULL,       
  @todate       DATE         =NULL)      
AS      
BEGIN                    
    
 /*   
 declare     
@OffsetValue  INT          =0,     
@PagingSize   INT          =20,       
@parentid bigint=17977,                        
@campaigntype nvarchar(20)='',                        
@campaignname nvarchar(100)='',                        
@fromdate date='2023-08-19',                        
@todate date='2023-08-25'    


select @parentid=44296,@campaigntype=N'',@campaignname=N'',@fromdate=N'2025-06-11',@todate=N'2025-06-17'    
*/    
IF @campaigntype=''      
BEGIN      
SET @campaigntype=NULL;      
END;      
IF @campaignname=''      
BEGIN      
SET @campaignname=NULL;      
END;      
IF @fromdate=''      
BEGIN      
SET @fromdate=NULL;      
END;      
IF @todate=''      
BEGIN      
SET @todate=NULL;      
END;      
IF @fromdate=NULL      
BEGIN      
SET @fromdate=CAST( DATEADD( m, DATEDIFF( m, 0, GETDATE( ) ), 0 ) AS DATE );      
SET @todate=CAST( GETDATE( ) AS DATE );      
END;      
DROP TABLE IF EXISTS #batcht;      
DROP TABLE IF EXISTS #batch;      
DROP TABLE IF EXISTS #invalidmails;      
DROP TABLE IF EXISTS #sent;      
DROP TABLE IF EXISTS #kdelivered;      
DROP TABLE IF EXISTS #kbounced;      
DROP TABLE IF EXISTS #kopened;      
DROP TABLE IF EXISTS #kclicked;      
DROP TABLE IF EXISTS #adstatus;      
DROP TABLE IF EXISTS #abstatus;      
DROP TABLE IF EXISTS #dateinvalidmails;      
DROP TABLE IF EXISTS #datesent;      
DROP TABLE IF EXISTS #datekdelivered;      
DROP TABLE IF EXISTS #datekstatus;      
DROP TABLE IF EXISTS #datekopened;      
DROP TABLE IF EXISTS #datekclicked;      
DROP TABLE IF EXISTS #dateadstatus;      
DROP TABLE IF EXISTS #dateabstatus;      
DROP TABLE IF EXISTS #unsubscribed;      
 drop table if exists #EnqueNew  
  
SELECT b.batchid,       
       mail_source,       
       CAST( ISNULL( scheduleddate, batchinserttime ) AS DATE ) batchinserttime,       
       COALESCE( t.cname, c.campaignname,      
                            CASE      
                              WHEN mail_source IN( 'emails', 'csv' )      
                              THEN CAST( ISNULL( scheduleddate, batchinserttime ) AS NVARCHAR(50) )+'_'+CAST( b.batchid AS NVARCHAR )      
                              ELSE 'CRM_'+mail_source      
                            END )      
AS                                                              campaignname,      
       CASE      
         WHEN t.id IS NOT NULL      
         THEN 'Triggered Campaign'      
         WHEN c.id IS NOT NULL      
              AND ISNULL( c.IsScheduled, 0 )=1      
         THEN 'Scheduled Campaign'      
         WHEN c.id IS NOT NULL      
              AND ISNULL( c.IsScheduled, 0 )=0      
         THEN 'Event Based Campaign'      
         WHEN mail_source IN( 'emails', 'csv' )      
         THEN 'Bulk Mail Campaign'      
         ELSE 'CRM Mails'      
       END      
AS                                                              campaigntype,       
       CAST( ISNULL( scheduleddate, batchinserttime ) AS DATE ) CampaignDate,       
       TotalRecords--,Delivered,Bounced,TotalSent                        
INTO #batcht      
FROM MySMS.dbo.BatchEmail_Infos  b with (nolock)       
JOIN      
MySMS.dbo.user_detail  u with (nolock)       
ON u.User_ID=b.UserID      
    LEFT JOIN      
    MySMS.dbo.usercampaignmaster  c with (nolock)       
    ON c.ParentID=u.parentid      
       AND b.mail_source LIKE 'campaign%'      
       AND CAST( c.ID AS NVARCHAR )=replace( b.mail_source, 'Campaign :', '' )      
        LEFT JOIN      
        MySMS.dbo.triggeredcampaigns  t with (nolock)       
        ON c.eventid=t.eventid      
           AND t.mailcampaignid=c.id      
WHERE u.ParentID=@parentid      
      AND CAST( ISNULL( scheduleddate, batchinserttime ) AS DATE ) BETWEEN @fromdate AND @todate;      

print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'),': ','#batcht created')





SELECT *      
INTO #batch      
FROM #batcht      
WHERE campaigntype=CASE      
                     WHEN @campaigntype IS NULL      
                     THEN campaigntype      
   ELSE @campaigntype      
                   END      
      AND campaignname=CASE      
                         WHEN @campaignname IS NULL      
                         THEN campaignname      
                         ELSE @campaignname      
                       END;      

print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'),': ','#batch created')    
    
select count(1) TotalUnsubscribed,c.batchid INTO #unsubscribed from mysms.dbo.Unsubscribedmails c with (nolock) JOIN      
#batch b  ON b.BatchID=c.batchid group by c.batchid       

print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'),': ','#unsubscribed created')    


      
   SELECT ef.Mail_BatchID as batchid       
           ,count(1) AS EnteredQueue   
     into #EnqueNew   
     FROM EmailsFilter  ef with (nolock)  
  join #batch b   
      on ef.Mail_BatchID = b.BatchID  
 where  ef.Mail_UserID = @parentid     
   and  cast(ef.Mail_InsertedDate as date ) BETWEEN @fromdate AND @todate     
   group by ef.Mail_BatchID   
  
  
  print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'),': ','#enquenew created')    

  
SELECT e.BatchID,       
       sum(case when e.event_status='001' then 1 else 0 end) Kdelivered,       
    sum(case when e.event_status<>'001' then 1 else 0 end) KBounced       
       --CAST( ISNULL( NULLIF( NULLIF( LTRIM( RTRIM( e.event_time ) ), '' ), 'null' ), createdon ) AS DATE ) event_time      
INTO #datekstatus      
FROM MySMS.dbo.EmailDeliveryStatus  e with (nolock)       
JOIN      
#batch b      
ON e.BatchID=b.BatchID      
GROUP BY e.batchid    


print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'),': ','#datekstatus created')    
    
      
SELECT e.batchid,       
       COUNT( 1 ) Delivered      
INTO #adstatus  from    
MySMS.dbo.Maildeliveries  e with (nolock)       
JOIN      
#batch b      
ON e.BatchID=b.BatchID GROUP BY e.batchid;      

print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'),': ','#adstatus created')    
      
      
SELECT e.batchid,       
       COUNT( 1 ) bounced      
INTO #abstatus      
FROM MySMS.dbo.Mailbounces  e with (nolock)       
JOIN      
#batch b      
ON e.BatchID=b.BatchID GROUP BY e.batchid;      
  
  
print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'),': ','#abstatus created')    

      
SELECT e.batchid batchid,       
  sum(case when tablename='EmailDeliveryStatus' then mailcount else 0 end) AS Sent,       
   --sum(case when tablename='invalid_Mail_EmailsReport' then mailcount else 0 end) AS NotSent,   
      case when (sum(case when tablename='tbl_MailResponse' then mailcount else 0 end)  -   sum(case when tablename='EmailDeliveryStatus' then mailcount else 0 end)) > 0   
           then (sum(case when tablename='tbl_MailResponse' then mailcount else 0 end)  -   sum(case when tablename='EmailDeliveryStatus' then mailcount else 0 end))  
     else 0  
     end  AS NotSent,    
  --sum(case when tablename in ('Mail_EmailsReport00','Mail_EmailsReport01','Mail_EmailsReport02','Mail_EmailsReport03',      
  --'Mail_EmailsReport04','Mail_EmailsReport05','Mail_EmailsReport1','Mail_EmailsReport2') then mailcount else 0 end) AS EnteredQueue,       
       
  /*  
  case when (sum(case when tablename='tbl_MailResponse' then mailcount else 0 end)  -   sum(case when tablename='EmailDeliveryStatus' then mailcount else 0 end)) > 0   
           then (sum(case when tablename='tbl_MailResponse' then mailcount else 0 end)  -   sum(case when tablename='EmailDeliveryStatus' then mailcount else 0 end))  
     else 0  
     end  AS EnteredQueue,  
  */     
  
  --sum(case when tablename='Bad_emails' then mailcount else 0 end) AS InvalidMails,  
    sum(case when tablename='tbl_InvalidEmailID_KarixAPI' then mailcount else 0 end) AS InvalidMails,    
  CAST( e.createdon AS DATE ) Mail_InsertedDate                  
--sum(case when Mail_Error='sent' then 1 else 0 end) Sent                  
--,sum(case when Mail_Error<>'sent' then 1 else 0 end) NotSent                  
INTO #datesent      
FROM emailcountracking  e with (nolock)       
JOIN      
#batch b      
ON e.BatchID=b.BatchID      
GROUP BY e.BatchID,       
         CAST( e.createdon AS DATE );      
--select * from #batch                
--select * from #datesent  

print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'),': ','#datesent created')    



SELECT batchid,       
       SUM( Sent )    Sent,       
       SUM( notsent ) NotSent,      
    SUM( InvalidMails ) InvalidMails--,      
    --SUM( EnteredQueue ) EnteredQueue                
--sum(case when Mail_Error='sent' then 1 else 0 end) Sent                  
--,sum(case when Mail_Error<>'sent' then 1 else 0 end) NotSent                  
INTO #sent      
FROM #datesent e      
GROUP BY e.BatchID;      
 
print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'),': ','#sent created')    
 
      
SELECT e.batchid,       
       COUNT( e.to_email ) Opened,       
       e.event_date      
INTO #datekopened      
FROM MySMS.dbo.EngagementEventOpenClick e with (nolock)      
JOIN      
#batch b      
ON e.BatchID=b.BatchID      
   AND ISNUMERIC( e.BatchID )=1      
   AND ISNUMERIC( b.BatchID )=1      
WHERE ISNULL( e.destination_url, '' )=''      
GROUP BY e.batchid,       
e.event_date; 

print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'),': ','#datekopened created')    

      
SELECT e.batchid,       
       COUNT( DISTINCT e.to_email ) Opened       
    INTO #kopened      
FROM MySMS.dbo.EngagementEventOpenClick e with (nolock)      
JOIN      
#batch b      
ON e.BatchID=b.BatchID      
   AND ISNUMERIC( e.BatchID )=1      
   AND ISNUMERIC( b.BatchID )=1      
WHERE ISNULL( e.destination_url, '' )=''    
--and cast(e.CreatedOn as date) between @fromdate and @todate      
GROUP BY e.batchid;  


print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'),': ','#kopened created')    


      
SELECT e.batchid,       
       COUNT( e.to_email ) Clicked,       
       e.event_date      
INTO #datekclicked      
FROM MySMS.dbo.EngagementEventOpenClick e with (nolock)      
JOIN      
#batch b      
ON e.BatchID=b.BatchID      
   AND ISNUMERIC( e.BatchID )=1      
   AND ISNUMERIC( b.BatchID )=1      
WHERE ISNULL( e.destination_url, '' )<>''      
GROUP BY e.batchid,       
         e.event_date;      

print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'),': ','#datekclicked created')    

      
SELECT e.batchid,       
       COUNT( DISTINCT e.to_email ) Clicked      
INTO #kclicked      
FROM MySMS.dbo.EngagementEventOpenClick e with (nolock)      
JOIN      
#batch b      
ON e.BatchID=b.BatchID      
   AND ISNUMERIC( e.BatchID )=1      
   AND ISNUMERIC( b.BatchID )=1      
WHERE ISNULL( e.destination_url, '' )<>''    
 --and cast(e.CreatedOn  as date ) between @fromdate and @todate      
GROUP BY e.batchid;      
 
 print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'),': ','#kclicked created')    

   
   SELECT 0 as batchid,       
   '' as Mail_ToEmail,       
   'Not Sent'       
    AS mailstatus       
  INTO #invalidmails       
--FROM mysmstrans.dbo.invalid_mail_emailsreport e with (nolock)       
--JOIN       
--#batch b       
--ON e.Mail_BatchID=b.BatchID;  
  
   /*  
  SELECT e.mail_batchid batchid,       
  e.Mail_ToEmail,       
  'Not Sent'       
 AS mailstatus       
 INTO #invalidmails       
 FROM dbo.invalid_mail_emailsreport e with (nolock)       
 JOIN       
 #batch b       
 ON e.Mail_BatchID=b.BatchID;       
   */   
 
 
 print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'),': ','#invalidmails created')    

SELECT COUNT( BatchID ) OVER( )      
AS                                                             TotalRow,       
       batchid,       
       CampaignDate,       
       mail_source,       
       campaigntype,       
       campaignname,       
       SUM( TotalRecords )      
AS                                                             Recipients,       
       SUM( ISNULL( delivered, 0 )+ISNULL( Kdelivered, 0 ) )      
AS                                                             Delivered,       
       SUM( ISNULL( Bounced, 0 )+ISNULL( kBounced, 0 ) )      
AS                                                             bounced,       
       SUM( ISNULL( opened, 0 ) )      
AS                                                             Opened,       
       SUM( ISNULL( clicked, 0 ) )                             Clicked,       
--       SUM( ISNULL( sent, 0 ) )                                Sent,       
--       SUM( ISNULL( notsent, 0 )) NotSent,       
       ISNULL( TotalUnsubscribed, 0 )      
AS             TotalUnsubscribed,       
       ISNULL( invalidmails, 0 )      
AS                                                             InvalidMails,       
       ISNULL( Inqueue, 0 )      
AS                
Inqueue,
case when 
(SUM( TotalRecords )      - SUM( ISNULL( delivered, 0 )+ISNULL( Kdelivered, 0 ) ) -  SUM( ISNULL( Bounced, 0 )+ISNULL( kBounced, 0 ) )- ISNULL( TotalUnsubscribed, 0 ) - ISNULL( invalidmails, 0 ) -
ISNULL( Inqueue, 0 ))>=0 then  (SUM( TotalRecords )      - SUM( ISNULL( delivered, 0 )+ISNULL( Kdelivered, 0 ) ) -  SUM( ISNULL( Bounced, 0 )+ISNULL( kBounced, 0 ) )- ISNULL( TotalUnsubscribed, 0 ) - ISNULL( invalidmails, 0 ) -
ISNULL( Inqueue, 0 )) else 0 end as Unknown

FROM      
(      
  SELECT b.batchid,       
         CampaignDate,       
         mail_source,       
         campaigntype,       
         campaignname,       
         TotalRecords,       
         Sent,       
         NotSent,       
         Delivered,       
         Bounced,       
         Kdelivered,       
         Kbounced,       
         Opened,       
         Clicked,       
         TotalUnsubscribed,       
         InvalidMails,       
         --(enteredqueue-sent) inqueue   
   (enteredqueue) inqueue   
  FROM #batch b    
   Left join #EnqueNew EN on b.BatchID= EN.batchid      
  LEFT JOIN #sent s  ON b.BatchID=s.batchid      
  LEFT JOIN #abstatus ab ON ab.batchid=b.BatchID      
  LEFT JOIN #adstatus ad ON ad.batchid=b.BatchID      
  left join #datekstatus dk on dk.BatchID=b.batchid    
  --LEFT JOIN #kdelivered k ON k.BatchID=b.BatchID      
  --LEFT JOIN #kbounced kb ON kb.BatchID=b.BatchID      
  LEFT JOIN #kopened ko ON ko.BatchID=b.BatchID and ko.batchid=s.batchid       
  LEFT JOIN #kclicked kc ON kc.BatchID=b.BatchID      
  LEFT JOIN #unsubscribed u ON u.batchid=b.BatchID      
  LEFT JOIN #invalidmails inV ON inV.batchid=b.BatchID      
  ) a      
WHERE campaigntype=CASE      
                     WHEN @campaigntype IS NULL      
                     THEN campaigntype      
                     ELSE @campaigntype      
                   END      
      AND campaignname=CASE      
                         WHEN @campaignname IS NULL      
                         THEN campaignname      
                         ELSE @campaignname      
                       END      
GROUP BY batchid,       
         CampaignDate,       
         campaigntype,       
         campaignname,       
         mail_source,       
         TotalUnsubscribed,       
         InvalidMails,       
         inqueue      
ORDER BY CampaignDate DESC      
 --OFFSET @OffsetValue ROWS FETCH NEXT @PagingSize ROWS ONLY;      
  
print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'),': ','Final result')    
  
DROP TABLE IF EXISTS #batcht;      
DROP TABLE IF EXISTS #batch;      
DROP TABLE IF EXISTS #invalidmails;      
DROP TABLE IF EXISTS #sent;      
DROP TABLE IF EXISTS #kdelivered;      
DROP TABLE IF EXISTS #kbounced;      
DROP TABLE IF EXISTS #kopened;      
DROP TABLE IF EXISTS #kclicked;      
DROP TABLE IF EXISTS #adstatus;      
DROP TABLE IF EXISTS #abstatus;      
DROP TABLE IF EXISTS #unsubscribed;      
DROP TABLE IF EXISTS #dateinvalidmails;      
DROP TABLE IF EXISTS #datesent;      
DROP TABLE IF EXISTS #datekdelivered;      
DROP TABLE IF EXISTS #datekbounced;      
DROP TABLE IF EXISTS #datekopened;      
DROP TABLE IF EXISTS #datekclicked;      
DROP TABLE IF EXISTS #dateadstatus;      
DROP TABLE IF EXISTS #dateabstatus;      
DROP TABLE IF EXISTS #badmails;      
drop table if exists #EnqueNew  
  
END;   
  


