CREATE   PROCEDURE [dbo].[usp_emailreportssummary_ListViewPagination_KarixAPI_Temp] --0, 20, 39008, '', '', '2023-12-10', '2023-12-11'                   
(    
  @OffsetValue  INT          =0,     
  @PagingSize   INT          =20,     
  @parentid     BIGINT,     
  @campaigntype NVARCHAR(20) =NULL,     
  @campaignname NVARCHAR(100)=NULL,     
  @fromdate     DATE         =NULL,     
  @todate       DATE         =NULL)    
AS    
BEGIN                  
  
/*  
 declare   
@OffsetValue  INT          =0,   
@PagingSize   INT          =20,     
@parentid bigint=17977,                      
@campaigntype nvarchar(20)='',                      
@campaignname nvarchar(100)='',                      
@fromdate date='2023-08-19',                      
@todate date='2023-08-25'  
*/  
  
