SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE [dbo].[Usp_EngagementEventOpenClickToBeSaved] 
( 
 @API_Header nvarchar(500), 
 @BatchID nvarchar(100), 
 @customer_reference_id nvarchar(200), 
 @message_id nvarchar(200), 
 @action_type nvarchar(100), 
 @to_email nvarchar(500), 
 @from_email nvarchar(500), 
 @replyto_emails nvarchar(500), 
 @ip nvarchar(100), 
 @email_send_date nvarchar(100), 
 @email_send_time nvarchar(100), 
 @event_date nvarchar(100), 
 @event_time nvarchar(100), 
 @file_id nvarchar(200), 
 @destination_url nvarchar(500) 
) 
as 
Begin 
if isnull(@batchid,'')='' or @batchid='null' 
begin 
     --select top 1 @BatchID=mail_batchid from mysmstrans.dbo.EmailsReportSent with (nolock) 
     --   where Mail_GUID=@customer_reference_id order by SentMail_ID desc 


     select top 1 @BatchID=BatchID  from 
	   (
	     select BatchID, Email_Id, UserId from ClientEmails with (nolock) where GUID=@customer_reference_id 
	        union   
          select BatchID, Email_Id, UserId from ThirtyDaysClientEmails with (nolock) where GUID=@customer_reference_id    
	   ) as tbl  


	   if(isnull(@batchid,'')='' or @batchid='null')
	      begin
		       select  @batchid = case when charindex('~',@customer_reference_id) <> 0
	                  then (select  value from fn_split(@customer_reference_id,'~') where Position = 2)
					  else
					     @customer_reference_id 
					  end 
           end

 end 


 insert into EngagementEventOpenClick 
 ( 
 API_Header , 
 BatchID , 
 customer_reference_id , 
 message_id , 
 action_type , 
 to_email , 
 from_email , 
 replyto_emails , 
 ip , 
 email_send_date , 
 email_send_time , 
 event_date , 
 event_time , 
 [file_id] , 
 destination_url 
 
 ) 
 values 
 ( 
 @API_Header , 
 @BatchID , 
 @customer_reference_id , 
 @message_id , 
 @action_type , 
 @to_email , 
 @from_email , 
 @replyto_emails , 
 @ip , 
 @email_send_date , 
 @email_send_time , 
 @event_date , 
 @event_time , 
 @file_id , 
 @destination_url 
 
 ) 
 
 select 'Data Saved' 
 
 
End




