CREATE   PROCEDURE [dbo].[Usp_EngagementEventOpenClickToBeSaved_WithMessageTag]         
(         
 @API_Header nvarchar(500),         
 @BatchID nvarchar(100),         
 @customer_reference_id nvarchar(200),         
 @message_id nvarchar(200),         
 @action_type nvarchar(100),         
 @to_email nvarchar(500),         
 @from_email nvarchar(500),         
 @replyto_emails nvarchar(500),         
 @ip nvarchar(100),         
 @email_send_date nvarchar(100),         
 @email_send_time nvarchar(100),         
 @event_date nvarchar(100),         
 @event_time nvarchar(100),         
 @file_id nvarchar(200),         
 @destination_url nvarchar(500),         
 @message_tag1 nvarchar(500),         
 @message_tag2 nvarchar(500),         
 @message_tag3 nvarchar(500),         
 @message_tag4 nvarchar(500),         
 @message_tag5 nvarchar(500),         
 @message_tag6 nvarchar(500)         
         
)         
as         
Begin         
         
         
 declare @email nvarchar(200) ='' ,@parentid bigint,@userid bigint,@eid bigint,@mailsubject nvarchar(200),@mailsource nvarchar(20)         
 if isnull(@batchid,'')='' or @batchid='null'         
begin         
select  @batchid = case when charindex('~',@customer_reference_id) <> 0    
                   then (select  value from fn_split(@customer_reference_id,'~') where Position = 2)    
       else    
          @customer_reference_id     
       end     
         
 --select top 1 @BatchID=mail_batchid,@email=mail_toemail,@userid=Mail_UserID,@mailsubject=Mail_Subject from mysmstrans.dbo.EmailsReportSent with (nolock)         
 --where Mail_GUID=@customer_reference_id order by SentMail_ID desc         
        
     
 end
 
      select top 1 @email=Email_Id, @userid=UserId from     
    (    
      select top 1 BatchID, Email_Id, UserId from ClientEmails with (nolock) where Email_Id=@to_email and batchid=@batchid 
         union       
          select top 1 BatchID, Email_Id, UserId from ThirtyDaysClientEmails with (nolock) where Email_Id=@to_email  
		   and batchid=@batchid
    ) as tbl         
     
     
 select @parentid=parentid from user_detail with (nolock) where user_id=@userid      
 select top 1 @mailsubject = Email_Subject from BatchEmail_Infos with(nolock) where batchID = @batchid             

         
 insert into EngagementEventOpenClick         
 (         
 API_Header ,         
 BatchID ,         
 customer_reference_id ,         
 message_id ,         
 action_type ,         
 to_email ,         
 from_email ,         
 replyto_emails ,         
 ip ,         
 email_send_date ,         
 email_send_time ,         
 event_date ,         
 event_time ,         
 [file_id] ,         
 destination_url,         
 message_tag1 ,         
 message_tag2 ,         
 message_tag3 ,         
 message_tag4 ,         
 message_tag5 ,         
 message_tag6         
         
         
 )         
 values         
 (         
 @API_Header ,         
 @BatchID ,         
 @customer_reference_id ,         
 @message_id ,         
 @action_type ,         
 @to_email ,         
 @from_email ,         
 @replyto_emails ,         
 @ip ,         
 @email_send_date ,         
 @email_send_time ,         
 @event_date ,         
 @event_time ,         
 @file_id ,         
 @destination_url,         
 @message_tag1 ,         
 @message_tag2 ,         
 @message_tag3 ,         
 @message_tag4 ,         
 @message_tag5 ,         
 @message_tag6         
         
 )         
 select @eid=scope_identity()         
         
select @mailsource=mail_source from BatchEmail_Infos with (nolock) where batchid=@BatchID         
         
 if @mailsource='InternalCRM'         
 begin         
 declare @eventtype nvarchar(50)=(select case when isnull(@destination_url,'')='' then @action_type         
 when @destination_url like '%kitever.in.net/subscription.aspx?%&ReplyTo=%' then 'Unsubscribe'         
 when @destination_url like '%kitever.in.net/subscription.aspx?%' then 'Subscribe'         
 else 'Clicked'         
 end),         
 @eventtime datetime=convert(datetime,@event_date+' '+@event_time)         
 exec usp_insertcrmenagagementactivity @batchid,@to_email,'Mail',@eventtype,'EngagementEventOpenClick',@eid,@eventtime         
 end         
         
         
         
begin try         
if isnull(@destination_url,'') <>'' and isnull(@email,'')<>''         
begin         
declare @entityname nvarchar(50)='',@entityid bigint=0,@eventdescription nvarchar(1000),@ename nvarchar(200),@entityno bigint         
if exists (select 1 from Userleads_Mobile_Email with (nolock) where parentid=@parentid and email=@email)         
begin         
select top 1 @entityname='lead',@entityno=leadno,@entityid=ulme_id from Userleads_Mobile_Email with (nolock) where parentid=@parentid and email=@email         
order by leadno desc         
end         
if exists (select 1 from Userenquiry_Mobile_Email with (nolock) where parentid=@parentid and email=@email)         
begin         
select top 1 @entityname='enquiry',@entityid=enquiryid,@entityno=enquiryid from Userenquiry_Mobile_Email with (nolock) where parentid=@parentid and email=@email         
order by enquiryid desc         
end         
if @entityname<>''         
begin         
select @eventdescription= @entityname + ' no.'+cast(@entityno as nvarchar(20))      
+ ', Name: '+dbo.fn_getentityfullname(@entityname,@entityid)         
+ ' has opened link '+@destination_url+ ' in the mail with subject '+@mailsubject+' : Team Kit19'         
,@ename=@entityname +' visits a mail link'         
         
exec UspSaveEntityActivity_withid @entityname,@entityid,@userid,@parentid,@eventdescription,@ename,'EngagementEventOpenClick',@eid         
end         
end         
end try         
begin catch         
exec usp_InsertErrorInfo         
end catch         
         
select 'Data Saved'         
End         


GO

