/* ============================================================
   Procedure: [dbo].[usp_enqueueemail]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_enqueueemail
@profile_name varchar(100)=null,               
@recipients nvarchar(max),
@copy_recipients nvarchar(max)=null,
@blind_copy_recipients nvarchar(max)=null,
@subject nvarchar(500),
@body nvarchar(max),              
@body_format varchar(100) = null,      
@from_address nvarchar(250)='contactus@kit19.com',   
@query nvarchar(max)=null,                                              
@attach_query_result_as_file int = null,                                              
@query_attachment_filename nvarchar(500)= null,                                              
@query_result_separator nvarchar(10)=null,                                              
@query_result_no_padding int=null,                                              
@query_result_width bigint=null,                                              
@query_result_header int= null      
as
begin
declare @To NVARCHAR(4000),
	@cc NVARCHAR(4000),
	@bcc NVARCHAR(4000),
    @FromAddress NVARCHAR(255) = 'contactus@kit19.com',
    @IsBodyHtml BIT = 0,
    @CsvAttachmentPath NVARCHAR(4000) = NULL

select @to=replace(@recipients,';',','),@cc=replace(@copy_recipients,';',','),
@bcc=replace(@blind_copy_recipients,';',','),@FromAddress=@from_address, 
@IsBodyHtml=case when @body_format='HTML' then 1 else 0 end,@CsvAttachmentPath=@query_attachment_filename

  INSERT INTO dbo.EmailQueue ([To],cc,bcc, Subject, Body, FromAddress, IsBodyHtml, CsvAttachmentPath)
    VALUES (@To,@cc,@bcc, @Subject, @Body, @FromAddress, @IsBodyHtml, @CsvAttachmentPath);
end



GO

/* ============================================================
   Procedure: [dbo].[usp_enquiry_detail]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- exec usp_enquiry_detail 2491784      
-- exec usp_enquiry_detail 4156414        
CREATE   PROCEDURE [dbo].[usp_enquiry_detail]        
(        
    @enqid bigint        
)        
as                                        
begin    
set nocount on                                    
declare @uid bigint                                    
declare @cnt_start int                                      
declare @cnt_max int                                      
declare @grp_id int                                      
declare @out varchar(max)=''                                       
select @uid=parentid from UserEnquiry where EnquiryID=@enqid;                                     
set @cnt_start=0;                                      
select distinct Group_Name, Group_ID into #group from Group_Detail where USER_ID=@uid                                      
select @cnt_max=COUNT(Group_Name) from #group                                      
while (@cnt_start < @cnt_max)                                      
begin                                      
select @grp_id=MAX(group_id) from #group;                                      
if(@cnt_start>0)                                      
begin                                      
select @out=@out+', '+group_name from #group where Group_ID=@grp_id;                                      
end                                      
else                                      
begin                                      
select @out=group_name from #group where Group_ID=@grp_id;                                      
end                                      
delete From #group where Group_ID=@grp_id;                                      
set @cnt_start=@cnt_start+1;                                      
end                                      
drop table #group;                                    
SELECT en.EnquiryID,         
       en.PersonName,         
       en.CompanyName,         
       rtrim(ltrim(ISNULL(en.MobileNo, ''))) AS mobileno,         
       en.emailid,         
       ISNULL(en.city, '') AS city,         
       ISNULL(en.[state], '') AS [state],         
       ISNULL(en.country, '') AS country,         
       ISNULL(en.pincode, '') AS pincode,         
       ISNULL(en.residentialaddress, '') AS residentialaddress,         
       src.[name] AS [source],         
       ISNULL(md.[name], '') AS medium,         
       ISNULL(cmp.[Name], '') AS campaignname,         
       en.InitialRemarks AS remark,         
       CONVERT(VARCHAR(20), en.CreatedDate, 113) AS createdon,         
       ud.user_login AS createdby,         
       @out AS groups,         
       rtrim(ltrim(ISNULL(en.mobileno1, ''))) AS mobileno1,         
       rtrim(ltrim(ISNULL(en.mobileno2, ''))) AS mobileno2,         
       ISNULL(en.emailid1, '') AS emailid1,         
       ISNULL(en.emailid2, '') AS emailid2,         
       en.officeaddress,         
       en.countrycode,         
       en.SourceName AS source_id,         
       en.MediumName AS medium_id,         
       en.CampaignName AS camp_id,         
       ISNULL(en.LeadNo, '') AS LeadNo,         
       (Case when ISNULL(en.LeadNo, 0) > 0 then 0 else 1 end) as IsOpen,         
       ltrim(ISNULL(en.countrycode, '') + ' ' + ISNULL(en.MobileNo, '')) + CASE        
                                                                  WHEN rtrim(ltrim(ISNULL(en.MobileNo1, ''))) <> ''        
                                                                  THEN ', ' + ltrim(ISNULL(en.countrycode1, '') + ' ' + rtrim(ltrim(ISNULL(en.MobileNo1, ''))))        
                                                                  ELSE ''        
                                                              END + CASE        
                                                                        WHEN rtrim(ltrim(ISNULL(en.MobileNo2, ''))) <> '        
'        
                                                                  THEN ', ' + ltrim(ISNULL(en.countrycode2, '') + ' ' + rtrim(ltrim(ISNULL(en.MobileNo2, ''))))        
                                                                        ELSE ''        
                                                                    END AS phones,         
       ISNULL(en.CountryCode1, '') AS CountryCode1,         
       ISNULL(en.CountryCode2, '') AS CountryCode2,         
       ISNULL(en.EmailID, '') + CASE        
                                    WHEN ISNULL(en.EmailID1, '') <> ''        
                                    THEN ', ' + ISNULL(en.EmailID1, '')        
                                    ELSE ''        
                                END + CASE        
                                   WHEN ISNULL(en.EmailID2, '') <> ''        
                                          THEN ', ' + ISNULL(en.EmailID2, '')        
                                          ELSE ''        
                                      END AS emails,      
ltrim(en.Countrycode + ' ' + rtrim(ltrim(en.Mobileno))) + case when rtrim(ltrim(isnull(en.Mobileno1,''))) <> '' then ', ...' else '' end as Mobile,      
ltrim(en.EmailId) + case when isnull(en.EmailId1,'') <> '' then ', ...' else '' end as Email,      
IsConflictWithLead=dbo.ufn_IsEnquiryConflictsLead(en.EnquiryID),    
IsLeadDeleted=case when isnull(en.LeadNo,0) > 0 then ~dbo.ufn_IsLeadExists(en.LeadNo,en.ParentID) else cast(0 as bit) end,  
en.whereAddress,   
en.latitude,   
en.longitude,  
( select STRING_AGG(tm.Tag, ',') from EntityTagMapping(nolock) etm inner join   
 TagMaster(nolock) tm on etm.TagID = tm.Id where Entity = 'enquiry' and EntityID = @enqid   
) as TagNames,
   ISNULL(en.ProfileImgFileName,'') as ProfileImgFileName      
FROM UserEnquiry en        
     LEFT JOIN user_detail ud ON en.CreatedBy = ud.user_id        
     LEFT JOIN usersourcesettings src ON en.sourcename = src.sourceid        
     LEFT JOIN usermediumsettings md ON en.mediumname = md.mediumid        
     LEFT JOIN UserCampaignSettings cmp ON en.campaignname = cmp.CampaignID        
 WHERE en.EnquiryID = @enqid;        
        
end 



GO

