/* ============================================================
   Procedure: [dbo].[Usp_EnquiryScoreDatatableFromJSON]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

------------------------------------------------

CREATE   PROCEDURE [dbo].[Usp_EnquiryScoreDatatableFromJSON]   
(  
  @JSON nvarchar(max)  
)  
as  
Begin  
  
     SELECT Attribute,Operator,Value  
FROM  
    OPENJSON(@JSON)  
    WITH  
        (  
  EventName nvarchar(50),  
        Conditions NVARCHAR(MAX) AS JSON,  
  Operation nvarchar(50),  
  Points int  
        ) AS a  
  cross apply  
  openjson(Conditions)  
  with  
  (  
  Attribute nvarchar(50),Operator nvarchar(50),Value nvarchar(max)  
  )  
  
End  



GO

/* ============================================================
   Procedure: [dbo].[Usp_EntityCustomFields]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[Usp_EntityCustomFields] 
	@entityType varchar(50),
	@entityId Bigint,
	@parentId Bigint
AS
BEGIN

	drop table if exists #tpCF  

	select * into #tpCF from customfields(nolock)   
	where ParentID = @parentID and isActive = 1  

	declare @CustomFieldsJson  NVARCHAR(MAX)=''
	if @entityType= 'lead'
	begin
		Set @CustomFieldsJson =
		(select * from (select distinct [field_ID],   
		               [ParentID],   
		               [fieldname],   
		               (CASE datatype  
		                    WHEN 'd'  
		                    THEN 'Date'  
		                    WHEN 'f'  
		                    THEN 'Numeric'  
		                    WHEN 'v'  
		                    THEN 'Text'  
		                    WHEN 'r'  
		                    THEN 'Radio'  
		                    WHEN 'm'  
		                    THEN 'Multiline'  
		                    WHEN 's'  
		                    THEN 'Select'  
		                    WHEN 'c'  
		                    THEN 'Checkbox'  
		                    WHEN 'e'  
		                    THEN 'Expression'  
		                    WHEN 'l'  
		                    THEN 'List'  
		                END) AS [datatype],   
		               [sequence],   
		               [minvalue] = CASE [datatype]  
		                                WHEN 'd'  
		                                THEN IIF([minvalue] IN('0', ''), '01/JAN/1900', FORMAT(CAST( ISNULL([minvalue], '01/01/1900') AS DATETIME), 'dd-MMM-yyyy' ))  
		                                WHEN 'f'  
		                                THEN ISNULL([minvalue], -2222222222222222)  
		                                WHEN 'v'  
		                                THEN ISNULL([minvalue], '')  
		                                ELSE [minvalue]  
		                            END,   
		               [maxvalue] = CASE [datatype]  
		                                WHEN 'd'  
		                                THEN IIF([maxvalue] IN('0', ''), '01/JAN/9999', FORMAT(CAST( ISNULL([maxvalue], '01/01/9999') AS DATETIME), 'dd-MMM-yyyy' ))  
		                                WHEN 'f'  
		                                THEN ISNULL([maxvalue], 2222222222222222)  
		                                WHEN 'v'  
		                                THEN ISNULL([maxvalue], '')  
		                                ELSE [maxvalue]  
		                            END,   
		               [addedon],   
		               [isActive],   
		               [isMandatory],   
		               [defaultValue],   
		               [currentDate],   
		               tooltip,   
		               choices,   
		        (  
		            SELECT m.id,   
		                   m.fParamId,   
		                   m.ParamName,   
		                   m.ParamType,   
		                   m.ParamValue,   
		                   m.fieldId  
		            FROM tbl_customFieldFormulaParamMapping(NOLOCK) m  
		            WHERE m.fieldId = cf.field_ID FOR JSON PATH  
		        ) AS [ParamList]  
				,cfv.fieldvalue,
			  [cf].[ParentFieldId],  
			   (  
				select STRING_AGG(p.field_ID, ',') from #tpCF p where p.ParentFieldId = cf.field_ID  
			   ) as [ChildFieldId],
			   (  
					select fieldvalue from customfieldLeadvalue(nolock) p 
						where p.fieldID = cf.ParentFieldId  and p.LeadID = @entityId
			   ) as [ParentFieldValue]
		from [customfields] (NOLOCK) cf 
		left join customfieldLeadvalue (NOLOCK) cfv on cf.field_id = cfv.fieldid and cfv.leadid=@entityId
		where cf.parentid= @parentId and cf.isActive=1 
		)  CFJSon order by CFJSon.[sequence] FOR JSON AUTO , Include_NULL_Values )
		select @CustomFieldsJson CustomFieldsJson 
	END

	else if @entityType='enquiry'
	BEGIN
		Set @CustomFieldsJson =
		(Select * from (
		SELECT distinct [field_ID],   
		               [ParentID],   
		               [fieldname],   
		               (CASE datatype  
		                    WHEN 'd'  
		                    THEN 'Date'  
		                    WHEN 'f'  
		                    THEN 'Numeric'  
		                    WHEN 'v'  
		                    THEN 'Text'  
		                    WHEN 'r'  
		                    THEN 'Radio'  
		                    WHEN 'm'  
		                    THEN 'Multiline'  
		                    WHEN 's'  
		                    THEN 'Select'  
		                    WHEN 'c'  
		                    THEN 'Checkbox'  
		                    WHEN 'e'  
		                    THEN 'Expression'  
		                    WHEN 'l'  
		                    THEN 'List'  
		                END) AS [datatype],   
		               [sequence],   
		               [minvalue] = CASE [datatype]  
		                                WHEN 'd'  
		                                THEN IIF([minvalue] IN('0', ''), '01/JAN/1900', FORMAT(CAST( ISNULL([minvalue], '01/01/1900') AS DATETIME), 'dd-MMM-yyyy' ))  
		                                WHEN 'f'  
		                                THEN ISNULL([minvalue], -2222222222222222)  
		                                WHEN 'v'  
		                                THEN ISNULL([minvalue], '')  
		                                ELSE [minvalue]  
		                            END,   
		               [maxvalue] = CASE [datatype]  
		                                WHEN 'd'  
		                                THEN IIF([maxvalue] IN('0', ''), '01/JAN/9999', FORMAT(CAST( ISNULL([maxvalue], '01/01/9999') AS DATETIME), 'dd-MMM-yyyy' ))  
		                                WHEN 'f'  
		                                THEN ISNULL([maxvalue], 2222222222222222)  
		                                WHEN 'v'  
		                                THEN ISNULL([maxvalue], '')  
		                                ELSE [maxvalue]  
		                            END,   
		               [addedon],   
		               [isActive],   
		               [isMandatory],   
		               [defaultValue],   
		               [currentDate],   
		               tooltip,   
		               choices,   
		        (  
		            SELECT m.id,   
		                   m.fParamId,   
		                   m.ParamName,   
		                   m.ParamType,   
		                   m.ParamValue,   
		                   m.fieldId  
		            FROM tbl_customFieldFormulaParamMapping(NOLOCK) m  
		            WHERE m.fieldId = cf.field_ID FOR JSON PATH  
		        ) AS [ParamList]  
				,cfv.fieldvalue,
			  [cf].[ParentFieldId],  
			   (  
				select STRING_AGG(p.field_ID, ',') from #tpCF p where p.ParentFieldId = cf.field_ID  
			   ) as [ChildFieldId],
			   (  
					select fieldvalue from customfieldenquiryvalue(nolock) p 
						where p.fieldID = cf.ParentFieldId  and p.EnquiryID = @entityId
			   ) as [ParentFieldValue]
		from [customfields] (NOLOCK) cf 
		left join customfieldenquiryvalue (NOLOCK) cfv on cf.field_id = cfv.fieldid and cfv.EnquiryID=@entityId
		where cf.parentid= @parentId and cf.isActive=1 
		)  CFJSon order by CFJSon.[sequence] FOR JSON AUTO , Include_NULL_Values )
		select @CustomFieldsJson CustomFieldsJson 
	END
END



GO

