/* ============================================================
   Procedure: [dbo].[usp_es_AddProductView]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE  usp_es_AddProductView      
@CustomerId bigint,      
@ProductId bigint,       
@Review nvarchar(max),      
@Rate int      
as      
begin      
 declare @Name nvarchar(500)    
 declare @Email nvarchar(1000),@leadid bigint,@user_id bigint ,@productname nvarchar(200)    ,@reviewId bigint
 
  select @productname=[name] from products(nolock) where productid=@productid   
 select @Name = First_Name , @Email = Email,@leadid=leadid,@user_id=user_id from Customers(nolock) where CustomerID = @CustomerId;    
  

 if(exists(select 1 from Review(nolock) where CustomerID = @CustomerId and ProductID = @ProductId))  
 begin  
 select top 1 @reviewId=reviewid from Review(nolock) where CustomerID = @CustomerId and ProductID = @ProductId order by reviewid desc
 update Review set Rate = @Rate,  
 Review = Review + ' ' + @Review  
  where CustomerID = @CustomerId and ProductID = @ProductId  
 end  
 else  
 begin  
 INSERT INTO Review ( CustomerID, ProductID, Name, Email, Review,Rate, DateTime, isDelete)      
  values (@CustomerId, @ProductId, @Name, @Email, @Review, @Rate, GETDATE(), 0)  
  select @reviewId=scope_identity()
  end
 
   if @leadid>0  
  begin  
  declare @leadname nvarchar(100)=(select isnull(nullif(personname,''),'Lead No. '+cast(leadno as nvarchar)) from userleads(nolock) where id=@leadid)  
  
      
   Begin try      
   declare @evntMessage nvarchar(max) = @leadname +' reviewed product '+@productname +' and left a '+cast(@rate as nvarchar)+' rating with review comment '+ cast(@review as nvarchar) ,@eventname nvarchar(100)='Lead reviewed product'     
   exec UspSaveLeadActivity_withid @LeadID,@User_ID,@User_Id,@evntMessage, @eventname,'Review',@reviewId  
   end try      
   Begin catch      
     exec usp_insertErrorInfo      
   End Catch      
   --select * from activitymaster where eventtype='eshop' 
   /*End Lead Activity  subscribes/unsubscribes newsletter */      
  end  
  
  
    
end 


GO

