/* ============================================================
   Procedure: [dbo].[usp_es_CreateReturnRequest]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_es_CreateReturnRequest  
@OrderId bigint,  
@ProductId bigint,  
@Variant nvarchar(1000),  
@RepVariant nvarchar(1000),  
@QuantityReturn int,  
@Remarks nvarchar(1000),  
@Reason nvarchar(1000),  
@ExpectedOutcome nvarchar(1000),  
@UserId bigint  
as  
begin  
 print 'enter'  
 declare @ReturnRequestNo nvarchar(250) = REPLACE('Req_'+ trim(str(@UserId)) +'_' + trim(str(@OrderId)), ' ', '')  
 declare @ProductName nvarchar(2000) = ''  
 declare @OrderDetailId bigint = 0,@leadid bigint,@user_id bigint ,@orderno nvarchar(100),@orderdate date
 print  'ReturnRequestNo : ' + @ReturnRequestNo  
 select @ProductName = od.ProductName, @OrderDetailId = od.OrderDetailsID,@orderno=o.OrderNo,@orderdate=cast(o.OrderDate as nvarchar(20)) from [Order] o  
             INNER JOIN OrderDetails od ON o.OrderId = od.OrderID   
    where od.OrderID = @OrderId and od.ProductID = @ProductId and od.User_ID = @UserId  
  
 declare @CurrentData datetime = GETDATE()  
 declare @ReturnId bigint = 0  
 declare @StageName nvarchar(50) = 'Return Requested'  
  
 set @Reason = IIF(ISNULL(@Reason, '') = '', 'Reason', @Reason)  
  
 begin try  
  begin transaction  
   insert into eshop_Order_Return(ReturnRequestNo, OrderID, ProductName, Variant, Quantity_Return, ReturnInitiatedDate, StageDate, Remarks, Reason, Expected_Outcome, User_ID, Stage_Name, OrderDetailsID, Rep_Variant)  
    values ( @ReturnRequestNo, @OrderId, @ProductName, @Variant, @QuantityReturn, @CurrentData, @CurrentData, @Remarks, @Reason, @ExpectedOutcome, @UserId, @StageName, @OrderDetailId, @RepVariant)  
  
    set @ReturnId = SCOPE_IDENTITY();  
      
    exec eshop_order_return_request_stage @ReturnId, @OrderId, @StageName, @Reason, @ExpectedOutcome, @UserId, @CurrentData  
  
    select 1  
  commit transaction  
 end try  
 begin catch  
    
  rollback transaction  
  select 0  
 end catch
 
    if @leadid>0  
  begin  
  declare @leadname nvarchar(100)=(select isnull(nullif(personname,''),'Lead No. '+cast(leadno as nvarchar)) from userleads(nolock) where id=@leadid)  
  
      
   Begin try      
   declare @evntMessage nvarchar(max) = @leadname +' requested item return with requestno '+@ReturnRequestNo +' for product '+@productname +' placed through orderno '+cast(@orderno as nvarchar)+' dated '+ cast(@orderdate as nvarchar) ,@eventname nvarchar(100)='Lead requested return'     
   exec UspSaveLeadActivity_withid @LeadID,@User_ID,@User_Id,@evntMessage, @eventname,'eshop_Order_Return',@ReturnId  
   end try      
   Begin catch      
     exec usp_insertErrorInfo      
   End Catch      
   --select * from activitymaster where eventtype='eshop' 
   /*End Lead Activity  subscribes/unsubscribes newsletter */      
  end
   
end  


GO

/* ============================================================
   Procedure: [dbo].[usp_es_CustomerActionByMode]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON




-- exec usp_es_CustomerActionByMode 1, 'window', '1234568', '412563', '74589231', 'set'
-- exec usp_es_CustomerActionByMode 1, '', '', '', '', 'get'
CREATE   PROCEDURE usp_es_CustomerActionByMode
@C_UserId BIGINT = '0',
@MachineName NVARCHAR(MAX) = '',
@DeviceId	NVARCHAR(MAX) = '',
@MACAddress	NVARCHAR(MAX) = '',
@OTP	NVARCHAR(MAX) = '',
@Mode NVARCHAR(100) = 'get'
AS
Begin
	If(@Mode = 'get')
	Begin
		SELECT * FROM tbl_es_CustomerLoginDetail where CustomerId = @C_UserId
	End

	If(@Mode = 'set')
	Begin
		If(not exists(select 1 from tbl_es_CustomerLoginDetail where CustomerId = @C_UserId))
			Begin
				insert into tbl_es_CustomerLoginDetail (CustomerId, MachineName, DeviceId, MACAddress, OTP ) values ( @C_UserId, @MachineName, @DeviceId, @MACAddress, @OTP )
				print 'inserted'
			End
		else
			Begin
				update tbl_es_CustomerLoginDetail 
					set 
						MachineName  = IIF(isnull(@MachineName, '') = '', MachineName, @MachineName),
						DeviceId  = IIF(isnull(@DeviceId, '') = '', DeviceId, @DeviceId),
						MACAddress  = IIF(isnull(@MACAddress, '') = '', MACAddress, @MACAddress),
						OTP  = IIF(isnull(@OTP, '') = '', OTP, OTP)
							where CustomerId = @C_UserId
				print 'updated'
			End
	End
End



GO

/* ============================================================
   Procedure: [dbo].[usp_es_CustomerLoginCheck]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON



-- exec usp_es_CustomerLoginCheck  @Customer_Id = 1, @Mode = 'GetData'
-- exec usp_es_CustomerLoginCheck @UserName = 'Abhi03', @Password = '12345', @Url = 'localhost', @Device_Id='002596FFFE123456'
CREATE   PROCEDURE usp_es_CustomerLoginCheck
	@UserName varchar(25)=null,    
	@Password varchar(15)=null,    
	@Url varchar(50)=null,    
	@Customer_Id bigint=null,    
	@Device_Id varchar(1000)=null,
	@Mode varchar(50)='Authenticate' -- GetData   
AS
BEGIN
	 If(@Mode = 'Reset' or @Mode = 'Authenticate')    
	 Begin    
		  If(@UserName is null or @Password is null or @Url is null)    
		  Begin    
			   print 'A3.3:- Invalid ' + @Mode + ' parameters'    
			   SELECT -1 as MsgId, 'Invalid ' + @Mode + ' parameters' as MsgText    
			Return
		  End
	 End   

	If(@Mode = 'Authenticate')    
	Begin
	  If (isnull(@Device_Id,'') != '' and len(isnull(@Device_Id,'')) > 20)   
	  Begin
		If(exists (select * from ( SELECT c.CustomerID, c.First_Name, c.Last_Name, c.UserName, c.Password, c.Age, c.Gender, c.DateofBirth, c.Organization, c.Country_Name, c.State_Name, c.City_Name, c.PostalCode, c.Email, c.AltEmail, c.Phone1, c.Phone2, c.Mobile1, c.Mobile2, c.Address1, c.Address2, c.Picture, c.status, c.LastLogin, c.Created, c.Notes, c.User_ID, c.LeadID, cl.MachineName, cl.DeviceId, cl.MACAddress, cl.OTP, cl.LastUpdatedOn FROM Customers c 
					inner join eshop_client_domain d on c.User_ID = d.User_Id
					left join tbl_es_CustomerLoginDetail cl on c.CustomerID = cl.CustomerId ) Cus where CustomerID = @Customer_Id and DeviceID!=@Device_Id and isnull(DeviceID,'')!=''
					))
			Begin
				SELECT -3 as MsgId, 'Device Already Logged In' as MsgText
				Return
			End
		End
	End

	If(@Mode = 'GetData')    
	Begin    
		print 'A3.6.0'    
		If(@Customer_Id is null)    
			Begin    
				print 'A3.6.1:- Invalid Get parameters'    
				SELECT -4 as MsgId, 'Invalid Get parameters' as MsgText    
				RETURN    
			End
		ELSE
			Begin
				SELECT Top 1 c.CustomerID, c.First_Name, c.Last_Name, c.UserName, c.Password, c.Age, c.Gender, c.DateofBirth, c.Organization, c.Country_Name, c.State_Name, c.City_Name, c.PostalCode, c.Email, c.AltEmail, c.Phone1, c.Phone2, c.Mobile1, c.Mobile2, c.Address1, c.Address2, c.Picture, c.status, c.LastLogin, c.Created, c.Notes, c.User_ID, c.LeadID, cl.MachineName, cl.DeviceId, cl.MACAddress, cl.OTP, cl.LastUpdatedOn FROM Customers c 
					inner join eshop_client_domain d on c.User_ID = d.User_Id
					left join tbl_es_CustomerLoginDetail cl on c.CustomerID = cl.CustomerId
						Where c.CustomerID = @Customer_Id
				RETURN
			End
	End    




	

IF ( @Mode = 'Reset'  OR  @Mode = 'Authenticate' ) 
    BEGIN
        PRINT 'A3.7.0';
        IF ( @Customer_Id IS NOT NULL
             AND 
             ISNULL(@Device_Id , '') != '' ) 
            BEGIN
                IF ( LEN(@Device_Id) > 20 )-- DeviceId   
                    BEGIN

						UPDATE tbl_es_CustomerLoginDetail
                               SET DeviceId = '' , OTP = '' WHERE DeviceID = @Device_Id;
                        
						EXEC usp_es_CustomerActionByMode  @C_UserId = @Customer_Id, @DeviceId = @Device_Id, @Mode = 'set'
                        
						
						PRINT 'A3.7.1:- ';
                        EXEC usp_insertloginhistory @Customer_Id , NULL , NULL , @Device_Id , 'Login' , NULL;

                END;
                    ELSE--MACAddress  
                    BEGIN
						
						EXEC usp_es_CustomerActionByMode  @C_UserId = @Customer_Id, @MACAddress = @Device_Id, @Mode = 'set'


                        PRINT 'A3.7.2:- ';
                        EXEC usp_insertloginhistory @Customer_Id , NULL , NULL , NULL , 'Login' , @Device_Id;
                        PRINT 'A3.7.21:- ';
                END;
        END;
            ELSE
            BEGIN
                IF ( @UserName IS NOT NULL AND  ISNULL(@Device_Id , '') != '' ) 
                    BEGIN
                        IF ( LEN(@Device_Id) > 20 )-- DeviceId   
                            BEGIN
								SELECT @Customer_Id = CustomerID FROM Customers  WHERE UserName = @UserName
								UPDATE tbl_es_CustomerLoginDetail SET DeviceID = '' , Otp = '' WHERE DeviceID = @Device_Id;

								EXEC usp_es_CustomerActionByMode  @C_UserId = @Customer_Id, @DeviceId = @Device_Id, @Mode = 'set'

                                PRINT 'A3.7.3:- ';
                                EXEC usp_insertloginhistory @Customer_Id , NULL , NULL , @Device_Id , 'Login' , NULL;
                                PRINT 'A3.7.31:- ';
                        END;
                            ELSE--MACAddress  
                            BEGIN
								SELECT @Customer_Id = CustomerID FROM Customers  WHERE UserName = @UserName
                                

								EXEC usp_es_CustomerActionByMode  @C_UserId = @Customer_Id, @MACAddress = @Device_Id, @Mode = 'set'

                                PRINT 'A3.7.4:- ';
                                EXEC usp_insertloginhistory @Customer_Id , NULL , NULL , NULL , 'Login' , @Device_Id;
                                PRINT 'A3.7.41:- ';
                        END;
                END;
        END;
END;




	 If(@Mode = 'Authenticate' or @Mode = 'Reset' or @Mode = 'GetData')
	 Begin
		SELECT c.CustomerID, c.First_Name, c.Last_Name, c.UserName, c.Password, c.Age, c.Gender, c.DateofBirth, c.Organization, c.Country_Name, c.State_Name, c.City_Name, c.PostalCode, c.Email, c.AltEmail, c.Phone1, c.Phone2, c.Mobile1, c.Mobile2, c.Address1, c.Address2, c.Picture, c.status, c.LastLogin, c.Created, c.Notes, c.User_ID, c.LeadID, 
		cl.MachineName, cl.DeviceId, cl.MACAddress, cl.OTP, cl.LastUpdatedOn
		FROM Customers c 
			inner join eshop_client_domain d on c.User_ID = d.User_Id
			left join tbl_es_CustomerLoginDetail cl on c.CustomerID = cl.CustomerId 
				Where  CAST(c.UserName AS varbinary) = CAST(@UserName AS varbinary) and
					CAST(c.Password AS varbinary) = CAST(@Password AS varbinary) and
					d.Domain = @Url --and
					--c.User_ID = @Customer_Id


		SELECT @Customer_Id = CustomerID FROM Customers  WHERE UserName = @UserName
			EXEC usp_es_CustomerActionByMode  @C_UserId = @Customer_Id, @MACAddress = @Device_Id, @Mode = 'set'

	 End				
END



GO

/* ============================================================
   Procedure: [dbo].[usp_es_EshopSetup]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- Exec usp_es_EshopSetup @User_ID=36826,@Domain='fabcoglobal.nowconnect.co.in'
-- Exec usp_es_EshopSetup @User_ID=36430,@Domain='goldyproteins.nowconnect.co.in'
CREATE   PROC [dbo].[usp_es_EshopSetup]
(                                    
	@User_ID int,
	@Domain varchar(100) = ''
)
as
begin
Declare @Msg varchar(200)='Eshop setup UnSuccessfull'

If (@Domain = 'default' or isnull(@Domain,'') = '')
Begin 
	set @Msg = 'Domain Name cannot be blank'
End
Else
Begin
	If exists(select * from eshop_client_domain(NOLOCK) where User_Id != @User_ID and Domain=@Domain)
	begin
		set @Msg = 'Domain Name not available'
	End
	Else
	Begin
		If (@Domain = 'localhost')
		Begin
			set @Msg = 'Domain Name not available'
		End
		Else
		Begin
			If exists(Select * From eshop_client_domain(NOLOCK) where User_Id=@User_ID)
			Begin
				update eshop_client_domain set Domain = @Domain where User_Id = @User_ID
			end
			Else
			Begin
				insert into eshop_client_domain(User_Id,Domain) values(@User_ID,@Domain)
			end

			If not exists (select '*' from [tbl_es_PageTheme](NOLOCK) where User_ID = @User_ID)
			Begin
				insert into [tbl_es_PageTheme] (PageName,Theme,Color,User_Id,IsActive,CreatedDate)
				select PageName,Theme,Color,User_Id=@User_ID,IsActive,CreatedDate=GETDATE()
				From [tbl_es_PageTheme]
				Where User_Id=33097

				insert into [tbl_es_PageSection] (SectionCode,SectionName,User_Id,IsActive,CreatedDate)
				Select	SectionCode,SectionName,User_Id=@User_ID,IsActive,CreatedDate=GETDATE()
				From	tbl_es_PageSection(nolock)
				Where	User_Id=33097

				insert into [tbl_es_PageSectionDetail] (Page_Id,SectionCode,SectionUrl,SectionContent,SectionTitle,User_Id,IsActive,CreatedDate)
				Select	B.Page_Id,C.SectionCode,C.SectionUrl,C.SectionContent,C.SectionTitle,User_Id=@User_ID,C.IsActive,CreatedDate=GetDate()
				From	
				(Select * From [tbl_es_PageTheme] Where User_Id=33097) A
				inner join
				(Select * From [tbl_es_PageTheme] Where User_Id=@User_ID) B
				on	A.PageName=B.PageName and A.Theme=B.Theme
				inner join	tbl_es_PageSectionDetail(nolock) C
				on	A.Page_Id=C.Page_Id and A.User_Id=C.User_Id
			End

			If not exists (select '*' from default_setting(NOLOCK) where User_ID = @User_ID)
			Begin
				insert into [default_setting] (PageName,Title,Meta_description,Tags,Returnable_days,Exchangable_days,User_ID,default_image,Text,Shippable,Meta_Tags,IncludeTax)
				select PageName,Title,Meta_description,Tags,Returnable_days,Exchangable_days,User_ID=@User_ID,default_image,Text,Shippable,Meta_Tags,IncludeTax
				From [default_setting]
				Where User_Id=33097
			End

			if not exists (select '*' from eshop_notification (NOLOCK) where User_ID = @User_ID)
			begin
				insert into eshop_notification(User_ID,Activity_Desc,subject,Messagebody,smsbody,Active,ActiveSMS)
				select User_ID=@User_ID,Activity_Desc,subject,Messagebody,smsbody,Active,ActiveSMS
				from eshop_notification (nolock)
				where User_ID = 335
			end

			if not exists (select '*' from Return_Stage (NOLOCK) where User_ID = @User_ID)
			begin
				insert into Return_Stage
				select SeqNo,Stage_Name,StageDesc,@User_ID from Return_Stage (NOLOCK) where User_ID = 335
			end

			if not exists (select '*' from eshop_tax_master (NOLOCK) where User_ID = @User_ID)
			begin
				insert into eshop_tax_master
				select TaxName,TaxPercent,Status,CategoryId,State_level,@User_ID,HSNCode,
				CategoryName,ChapterCode,EffectiveDate,Country from eshop_tax_master (NOLOCK) where User_id = 335
			end

			if not exists (select '*' from Paymenttype (NOLOCK) where User_ID = @User_ID)
			begin
				insert into Paymenttype(TypeName,Description,Online,Offline,User_ID)
				select TypeName,Description,Online,Offline,@User_ID from Paymenttype (NOLOCK) where User_ID = 33097
			end

			if not exists (select '*' from eshoppaymentgateway (NOLOCK) where User_ID = @User_ID)
			begin
				insert into eshoppaymentgateway(User_ID,PaymentsGateWayName,IsDefault,CreatedOn,status,PaymentGatewayDescription)
				select @User_ID,PaymentsGateWayName,IsDefault,getdate(),status,PaymentGatewayDescription
				from eshoppaymentgateway (NOLOCK) where User_ID = 33097
			end

			if not exists (select '*' from eshop_order_number_setting(NOLOCK) where User_ID = @User_ID)
			begin
				insert into eshop_order_number_setting(User_ID,Prefix,Suffix,StartNumber,LastUpdatedNumber,MinimumOrderValue,MaximumOrderValue,InvoicePrefix,
				InvoiceSuffix,InvoiceStartNo,ReceiptPrefix,ReceiptSuffix,ReceiptStartNo)
				values(@User_ID,'Eshop','OD',1,0,null,null,'EShop','Inv',1,'Eshop','Rec',1)
			end

			if not exists (select '*' from categories (NOLOCK) where User_ID = @User_ID)
			begin
				insert into categories(Name,Description,isActive,User_ID,IsPublished,SortOrder,ParentCategory,ParentCategoryName)
				select Name,Description,isActive,@User_ID,IsPublished,SortOrder,ParentCategory=null,ParentCategoryName=null
				from categories (NOLOCK) where User_ID = 335
			end

			if not exists (select '*' from collection (NOLOCK) where User_ID = @User_ID)
			begin
				insert into collection(name,description,ProductID,isfeatured,isactive,User_ID,Collection_Image,Thumbnail_Image,SortOrder, Datecreated, CollectionTags, FeaturedName,criteriatype,Title,Meta_description,Meta_Tags,PageName)
				select name,description,ProductID,isfeatured,isactive,@User_ID,Collection_Image,Thumbnail_Image,SortOrder,getdate(), CollectionTags, FeaturedName,criteriatype,Title,Meta_description,Meta_Tags,PageName from collection (NOLOCK)
				where User_ID = 335

				insert into collection_criteria(collectionid,Op1,Operator,Op2,Conjunction,Active)
				/*select distinct collectionid,Op1,Operator,Op2,Conjunction,Active from collection_criteria (NOLOCK)
				where collectionid = (select id from collection (NOLOCK) where User_ID =@User_ID)*/
				select B.id,C.Op1,C.Operator,C.Op2,C.Conjunction,C.Active
				from 
				(select * from collection(NOLOCK) where User_ID =335) A
				inner join
				(select * from collection(NOLOCK) where User_ID =@User_ID) B
				on A.name=B.name
				inner join collection_criteria(NOLOCK) C
				on A.id=C.collectionid
			end

			if not exists (select '*' from return_reason(NOLOCK) where User_ID = @User_ID)
			begin
				insert into return_reason(Reason,Reason_Desc,IsActive,User_ID)
				select Reason,Reason_Desc,IsActive,@User_ID from return_reason (NOLOCK) where User_ID = 335
			end

			if not exists (select '*' from Suppliers (NOLOCK) where User_ID = @User_ID)
			begin
				insert into Suppliers(CompanyName,ContactName,ContactTitle,Address,Mobile,Email,City_Name,Country_Name,User_ID,GSTNumber, PANNumber,State_Name)
				select CompanyName,ContactName,ContactTitle,Address,Mobile,Email,City_Name,Country_Name,@User_ID,GSTNumber, PANNumber,State_Name 
				from Suppliers (NOLOCK) where User_ID = 335
			end

			if not exists(select '*' from Products (nolock) where User_ID = @User_ID)
			begin
				Insert into Products( Name,SupplierID,CategoryID,UnitPrice,OldPrice,UnitWeight,UnitInStock,ProductAvailable,ImageURL,AltText,
				Picture1,StockKeepingUnit,Barcode,HarmonizedSystemCode,PublicationStartDate,Country_Name,User_ID,CreatedDate,Return_days,
				Exchange_days,Shipped_days,TaxName1,Tax1,isActive,TotalPrice,Title,Meta_description,Meta_Tags,PageName,ReOrderLevel,minorderquantity, maxorderquantity)
				select Name,SupplierID,CategoryID,UnitPrice,OldPrice,UnitWeight,UnitInStock,ProductAvailable,ImageURL,Name, Picture1,StockKeepingUnit,Barcode,HarmonizedSystemCode,PublicationStartDate,Country_Name,@User_ID,CreatedDate=Getdate(),Return_days,
				Exchange_days,Shipped_days,TaxName1,Tax1,isActive,TotalPrice,Name,Meta_description,Name,Name,ReOrderLevel,minorderquantity,maxorderquantity from Products where USer_ID = 335
			end

			--if not exists(select '*' from genMainSlider (nolock) where User_ID = @User_ID)
			--begin
			--	insert into genMainSlider (ImageURL,User_ID)
			--	select ImageURL,@User_ID from genMainSlider where User_ID = 335
			--end

			if not exists(select '*' from eshop_Policy (nolock) where User_ID = @User_ID)
			begin
				insert into eshop_Policy (User_Id,PolicyName,Description,Title,Meta_description,Meta_Tags,PageName,Active)
				select User_Id=@User_ID,PolicyName,Description,Title,Meta_description,Meta_Tags,PageName,Active
				from eshop_Policy where User_ID = 33097
			end			

			if not exists(select '*' from GenLogo (nolock) where User_ID = @User_ID)
			begin
				insert into GenLogo (LogoUrl,User_ID)
				select LogoUrl,@User_ID from GenLogo where User_ID = 335
			end

			if not exists(select '*' from eshop_customer_social_link (nolock) where User_ID = @User_ID)
			begin
				insert into eshop_customer_social_link (LinkName,Logo,LinkText,LinkURL,isActive,User_ID)
				select LinkName,Logo,LinkText,LinkURL,isActive,@User_ID from eshop_customer_social_link where User_ID = 335
			end

			set @Msg='Eshop setup Successfull'
		End
	End
End
	Select @Msg as Msg
end 



GO

/* ============================================================
   Procedure: [dbo].[usp_es_GetApplicableCoupon]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- exec usp_es_GetApplicableCoupon @UserName='Keshav.gautam@pelsoftlabs.in', @UserId=37540    
-- exec usp_es_GetApplicableCoupon @UserName='vicky.123@gmail.com', @UserId=37540    
-- exec usp_es_GetApplicableCoupon @UserName='anita.baghel@pelsoftlabs.in', @UserId=37540    
CREATE   PROC usp_es_GetApplicableCoupon
(    
 @UserName varchar(50),    
 @UserId bigint    
)    
AS    
BEGIN    
 --declare @UserName varchar(50)='Keshav.gautam@pelsoftlabs.in', @UserId bigint=37540    
 --declare @UserName varchar(50)='vicky.123@gmail.com', @UserId bigint=37540    
 if object_id('tempdb..#tbl_Coupon') is not null begin drop table #tbl_Coupon end        
 if object_id('tempdb..#tbl_CouponProductList') is not null begin drop table #tbl_CouponProductList end        
 if object_id('tempdb..#tbl_CouponCollection') is not null begin drop table #tbl_CouponCollection end        
 if object_id('tempdb..#tbl_Leads') is not null begin drop table #tbl_Leads end        
 if object_id('tempdb..#tbl_Segment') is not null begin drop table #tbl_Segment end        
 if object_id('tempdb..#tbl_Cart') is not null begin drop table #tbl_Cart end        
 if object_id('tempdb..#tbl_CartCoupons') is not null begin drop table #tbl_CartCoupons end        
    
 declare @CouponID bigint, @IsDiscount bit, @IsFreebee bit, @IsOthers bit, @CouponName varchar(50), @CouponCode varchar(50),    
   @SelectionCriteria varchar(50), @CriteriaApplyTo varchar(50), @CriteriaDetail varchar(max),     
   @IncludedSegment varchar(50), @SelectedSegment varchar(50), @csvSegment varchar(max), @csvSegmentEmail varchar(max),     
   @csvSegmentMobile varchar(max), @ApplyToBillAmtType varchar(50), @MinBillAmt numeric(18,2),     
   @MaxBillAmt numeric(18,2), @DiscAmt numeric(18,2), @DiscPerc numeric(18,2), @DiscOther varchar(500),    
   @StartDate datetime, @ExpiryDate datetime, @ReuseCount int=1
 declare @RowId int=1, @CouponCnt int=0, @RNo int=1, @CollCnt int=0, @CollectionId int=0, @SegRowId int=1, @SegRowCnt int=0,    
   @SegmentId bigint=0    
 declare @Email varchar(50)='', @CouponJson nvarchar(max)=''    
    
 CREATE TABLE #tbl_Coupon    
 (    
  [RowID] [bigint] IDENTITY(1,1) NOT NULL,    
  [CouponID] [bigint] NOT NULL,    
  [IsDiscount] [bit] NOT NULL,    
  [IsFreebee] [bit] NOT NULL,    
  [IsOthers] [bit] NOT NULL,    
  [CouponName] [varchar](50) NOT NULL,    
  [CouponCode] [varchar](50) NOT NULL,    
  [CouponDescription] [varchar](200) NOT NULL,    
  [SelectionCriteria] [varchar](50) NOT NULL,    
  [CriteriaApplyTo] [varchar](10) NOT NULL,    
  [CriteriaDetail] [varchar](max) NULL,    
  [IncludedSegment] [varchar](10) NOT NULL,    
  [SelectedSegment] [varchar](10) NULL,    
  [csvSegment] [nvarchar](max) NULL,    
  [csvSegmentEmail] [nvarchar](max) NULL,    
  [csvSegmentMobile] [nvarchar](max) NULL,    
  [ApplyToBillAmtType] [varchar](10) NOT NULL,    
  [MinBillAmt] [numeric](18, 2) NULL,    
  [MaxBillAmt] [numeric](18, 2) NULL,    
  [DiscAmt] [numeric](18, 2) NULL,    
  [DiscPerc] [numeric](18, 2) NULL,    
  [DiscOther] [varchar](500) NULL,    
  [StartDate] [datetime] NULL,    
  [ExpiryDate] [datetime] NULL,
  [ParentID] [bigint] NOT NULL,
  [ReuseCount] [int] NOT NULL
 )    
    
 Create Table #tbl_CouponProductList    
 (    
  [RowID] [int] IDENTITY(1,1) NOT NULL,    
  ProductID int NOT NULL    
 )    
    
 Create table #tbl_CouponCollection    
 (    
  RNo int identity(1,1),    
  CollectionId int    
 )    
    
 CREATE TABLE #tbl_Leads    
 (    
  RowID int identity(1,1),    
  personname VARCHAR(200),    
  companyname VARCHAR(200),    
  mobileno VARCHAR(100),    
  mobileno1 VARCHAR(100),    
  mobileno2 VARCHAR(100),    
  emailid VARCHAR(100),    
  emailid1 VARCHAR(100),    
  emailid2 VARCHAR(100),    
  city VARCHAR(100),    
  STATE VARCHAR(100),    
  country VARCHAR(100),    
  pincode VARCHAR(50),    
  residentialaddress VARCHAR(500),    
  officeaddress VARCHAR(500),    
  sourcename VARCHAR(200) COLLATE sql_latin1_general_cp1_ci_as,    
  mediumname VARCHAR(200) COLLATE sql_latin1_general_cp1_ci_as,    
  campaignname VARCHAR(200) COLLATE sql_latin1_general_cp1_ci_as,    
  initialremarks VARCHAR(1000) collate SQL_Latin1_General_CP1_CI_AS,    
  SearchId bigint,    
  ParentId bigint,    
  CampaignId bigint    
 )    
    
 create table #tbl_Segment    
  (    
  RowId int identity(1,1),    
  Id bigint    
  )    
    
 Create table #tbl_Cart    
 (    
  RowId int identity(1,1),    
  Cartid int,    
  UserName varchar(50),    
  ProductName varchar(150),    
  Variant varchar(50),    
  Quantity int,    
  Price numeric(18,2),    
  ProductID int,    
  TotalAmount decimal(18,2),    
  ImageURL varchar(500),    
  OrderID int,    
  OrderDate datetime,    
  User_ID bigint,    
  fulfillmentstatus varchar(100)    
 )    
    
 Create table #tbl_CartCoupons    
 (    
  RowId int identity(1,1),    
  ProductID int,    
  ProductName varchar(150),    
  CouponJson nvarchar(max) default('')    
 )    
    
 If exists (Select * From eshop_cart_items(nolock) Where User_ID=@UserId and UserName=@UserName)    
 Begin    
    
  insert into #tbl_CartCoupons    
  Select ProductId,ProductName,'' as CouponJson    
  From eshop_cart_items(nolock)     
  Where User_ID=@UserId and UserName=@UserName    
    
  Insert into #tbl_Coupon    
  Select CouponID, IsDiscount, IsFreebee, IsOthers, CouponName, CouponCode, CouponDescription, SelectionCriteria,    
    CriteriaApplyTo, CriteriaDetail, IncludedSegment, SelectedSegment, csvSegment, csvSegmentEmail, csvSegmentMobile,    
    ApplyToBillAmtType, MinBillAmt, MaxBillAmt, DiscAmt, DiscPerc, DiscOther, StartDate, ExpiryDate, ParentID, ReuseCount   
  from tbl_es_Coupon(nolock)     
  Where ParentID=@UserId and (GETDATE() between StartDate and ExpiryDate) and Status=1    
    
  Select @CouponCnt=count(*) from #tbl_Coupon    
  print '@CouponCnt: ' + cast(@CouponCnt as varchar)    
    
  While(@RowId <= @CouponCnt)    
  Begin    
   Select @CouponID=CouponID, @IsDiscount=IsDiscount, @IsFreebee=IsFreebee, @IsOthers=IsOthers, @CouponName=CouponName,    
     @CouponCode=CouponCode, @SelectionCriteria=SelectionCriteria, @CriteriaApplyTo=CriteriaApplyTo,    
     @CriteriaDetail=CriteriaDetail, @IncludedSegment=IncludedSegment, @SelectedSegment=SelectedSegment,    
     @csvSegment=csvSegment, @csvSegmentEmail=csvSegmentEmail, @csvSegmentMobile=csvSegmentMobile,    
     @ApplyToBillAmtType=ApplyToBillAmtType, @MinBillAmt=MinBillAmt, @MaxBillAmt=MaxBillAmt, @DiscAmt=DiscAmt,    
     @DiscPerc=DiscPerc, @DiscOther=DiscOther, @StartDate=StartDate, @ExpiryDate=ExpiryDate, @ReuseCount=ReuseCount   
   from #tbl_Coupon    
   Where RowID=@RowId    
    
   print '@RowId: ' + cast(@RowId as varchar) + ' -----------------------------------------------------'    
   print '@CouponCode: ' + @CouponCode    
   print '@SelectionCriteria: ' + @SelectionCriteria    
   print '@CriteriaApplyTo: ' + @CriteriaApplyTo    
   print '@CriteriaDetail: ' + @CriteriaDetail    
   print '@IncludedSegment: ' + @IncludedSegment    
   print '@SelectedSegment: ' + @SelectedSegment    
   print '@csvSegment: ' + @csvSegment    
   print '@ApplyToBillAmtType: ' + @ApplyToBillAmtType    
   print '@MinBillAmt: ' + cast(@MinBillAmt as varchar)    
   print '@MaxBillAmt: ' + cast(@MaxBillAmt as varchar)    
   print '@ReuseCount: ' + cast(@ReuseCount as varchar)    
    
   If(@SelectionCriteria = 'Product')    
   Begin    
    If(@CriteriaApplyTo = 'Specific')    
    Begin    
     insert into #tbl_CouponProductList    
     select item from dbo.SplitString(@CriteriaDetail,',')    
     --select item from dbo.SplitString('1144,1148',',')    
    End    
    Else--All    
    Begin    
     insert into #tbl_CouponProductList    
     select ProductID from Products where User_Id=@UserId    
     --select ProductID from Products where User_Id=37540    
    End    
   End    
    
   If(@SelectionCriteria = 'Category')    
   Begin    
    If(@CriteriaApplyTo = 'Specific')    
    Begin    
     insert into #tbl_CouponProductList    
     select ProductID     
     from Products     
     where User_Id=@UserId and CategoryID in (select item from dbo.SplitString(@CriteriaDetail,','))    
     --select ProductID from Products where User_Id=37540 and CategoryID in (select item from dbo.SplitString('864,869',','))    
    End    
    Else--All    
    Begin    
     insert into #tbl_CouponProductList    
     select ProductID     
     from Products     
     where User_Id=@UserId and CategoryID in (select CategoryID from Categories where user_id=@UserId)    
     --select ProductID from Products where User_Id=37540 and CategoryID in (select CategoryID from Categories where user_id=37540)    
    End    
   End    
    
   If(@SelectionCriteria = 'Collection')    
   Begin    
    If(@CriteriaApplyTo = 'Specific')    
    Begin    
     insert into  #tbl_CouponCollection    
     select ID as CollectionId    
     from [collection]     
     where Id in (select item from dbo.SplitString(@CriteriaDetail,',')) and isactive=1    
    
     select @CollCnt=count(*) from #tbl_CouponCollection    
     print '@CollCnt: ' + cast(@CollCnt as varchar)    
    
     While(@RNo <= @CollCnt)    
     Begin    
      print '@RNo: ' + cast(@RNo as varchar)    
    
      Select @CollectionId=CollectionId From #tbl_CouponCollection Where RNo=@RNo    
      print '@CollectionId: ' + cast(@CollectionId as varchar)    
         
      insert into #tbl_CouponProductList    
      Exec usp_es_GetCollectionProduct @CollectionId,@UserId    
    
      set @RNo=@RNo+1    
     End    
    End    
    Else--All    
    Begin    
     insert into  #tbl_CouponCollection    
     select ID as CollectionId    
     from [collection]     
     where User_ID = @UserId and isactive=1    
    
     select @CollCnt=count(*) from #tbl_CouponCollection    
     print '@CollCnt: ' + cast(@CollCnt as varchar)    
    
     While(@RNo <= @CollCnt)    
     Begin    
      print '@RNo: ' + cast(@RNo as varchar)    
    
      Select @CollectionId=CollectionId From #tbl_CouponCollection Where RNo=@RNo    
      print '@CollectionId: ' + cast(@CollectionId as varchar)    
         
      insert into #tbl_CouponProductList    
      Exec usp_es_GetCollectionProduct @CollectionId,@UserId    
    
      set @RNo=@RNo+1    
     End    
    End    
   End    
    
   If(@SelectionCriteria = 'Other')    
   Begin    
    insert into #tbl_CouponProductList    
    Exec usp_es_GetCouponProduct @CriteriaDetail,@UserId    
   End    
    
   If(@IncludedSegment = 'Selected')    
   Begin    
    If(@SelectedSegment = 'Lead')    
    Begin    
     insert into #tbl_Segment    
     select item from dbo.SplitString(@csvSegment,',')    
    
     select @SegRowCnt=count(*) from #tbl_Segment    
     print '@SegRowCnt: ' + cast(@SegRowCnt as varchar)    
    
     While(@SegRowId <= @SegRowCnt)    
     Begin    
      print '@SegRowId: ' + cast(@SegRowId as varchar)    
    
      Select @SegmentId=Id from #tbl_Segment Where RowId=@SegRowId    
      print '@SegmentId: ' + cast(@SegmentId as varchar)    
    
      insert into #tbl_Leads    
      Exec usp_ExecuteUserSearch @UserId,@SegmentId         
    
      set @SegRowId=@SegRowId+1    
     End    
    End    
    Else--All    
    Begin    
     print 'All Segment'    
     insert into #tbl_Leads    
     SELECT PersonName, companyname, MobileNo, MobileNo1, MobileNo2, EmailID, EmailID1, EmailID2, City, State,    
       Country, PinCode, ResidentialAddress, OfficeAddress, SourceName, MediumName, CampaignName,    
       InitialRemarks, 0, ParentID, 0    
     FROM    UserLeads    
     WHERE   (ParentID = @UserId)    
    End    
    
    --If(@csvSegmentEmail != '')    
    --Begin    
    -- @csvSegmentEmail    
    --End    
    
    --If(@csvSegmentMobile != '')    
    --Begin    
    -- @csvSegmentMobile    
    --End    
   End    
   Else--Everyone    
   Begin    
    print 'Everyone'    
    insert into #tbl_Leads    
    SELECT PersonName, companyname, MobileNo, MobileNo1, MobileNo2, EmailID, EmailID1, EmailID2, City, State,    
      Country, PinCode, ResidentialAddress, OfficeAddress, SourceName, MediumName, CampaignName,    
      InitialRemarks, 0, ParentID, 0    
    FROM    UserLeads    
    WHERE   (ParentID = @UserId)    
   End    
    
   If exists (Select * From customers(nolock) Where User_ID=@UserId and UserName=@UserName)    
   Begin    
    print 'Customer Exist'    
    
    Select @Email=Email From customers(nolock) Where User_ID=@UserId and UserName=@UserName    
    print '@Email: ' + isnull(@Email,'')    
    
    If exists (Select * From #tbl_Leads Where emailid=@Email or emailid1=@Email or emailid2=@Email)    
    Begin    
     print 'Lead Exist'    
    
     insert into #tbl_Cart    
     Select Cartid,UserName,ProductName,Variant,Quantity,Price,ECI.ProductID,TotalAmount,ECI.ImageURL,    
       OrderID,OrderDate, ECI.User_ID,fulfillmentstatus     
     from #tbl_CouponProductList CPL inner join Products(nolock) P    
     On  CPL.ProductID = P.ProductID inner join eshop_cart_items(nolock) ECI    
     ON  P.Name = ECI.ProductName and P.User_ID=ECI.User_ID    
     Where ECI.User_ID=@UserId and ECI.UserName=@UserName    
    
     IF((Select count(*) from #tbl_Cart) > 0)    
     Begin
      print '#tbl_Cart Created'    
		If ((Select count(*) From tbl_es_invoiceDetail(nolock) ID inner join [Order](nolock) ORD on ID.OrderID=ORD.OrderID inner join customers(nolock) CUST On ORD.CustomerId=CUST.CustomerID  Where CUST.User_ID=@UserId and CUST.UserName=@UserName and isnull(ID.AppliedCouponCode,'') = @CouponCode and ORD.CancelOrder=0)<@ReuseCount)
		Begin
		    print 'Coupon Reuse allowed'
			If(@ApplyToBillAmtType = 'Selected')    
      Begin    
       If exists(Select User_Id, Sum(TotalAmount) from #tbl_Cart Group by User_Id having Sum(TotalAmount) between @MinBillAmt and @MaxBillAmt)    
       Begin    
        print '#tbl_Cart BillAmt in range: ' + cast(@MinBillAmt as varchar) + ' to ' + cast(@MaxBillAmt as varchar)    
    
        Update TCC     
        Set TCC.CouponJson = TCC.CouponJson + iif(TCC.CouponJson = '', '', ',') + @CouponCode    
        from #tbl_CartCoupons TCC inner join #tbl_Cart TC    
        on TCC.ProductID=TC.ProductID    
       End    
      End    
      Else--Any    
      Begin    
       print 'Any bill amt'    
       Update TCC     
       Set TCC.CouponJson = TCC.CouponJson + iif(TCC.CouponJson = '', '', ',') + @CouponCode    
       from #tbl_CartCoupons TCC inner join #tbl_Cart TC    
       on TCC.ProductID=TC.ProductID    
      End    
		End
		Else
		Begin
		    print 'Coupon Reuse not allowed'
		End
     End
    End    
   End    
    
    
   --If(@IsDiscount = 1)    
   --Begin    
   -- @DiscAmt or @DiscPerc    
   --End    
      
   --If(@IsOthers = 1)    
   --Begin    
   -- @DiscOther    
   --End    
      
   --If(@IsFreebee = 1)    
   --Begin    
   -- Select * From eshop_freebeecoupon_product(nolock) Where CouponID=@CouponID    
   --End    
    
   if object_id('tempdb..#tbl_CouponProductList') is not null begin truncate table #tbl_CouponProductList end        
   if object_id('tempdb..#tbl_CouponCollection') is not null begin truncate table #tbl_CouponCollection end        
   if object_id('tempdb..#tbl_Leads') is not null begin truncate table #tbl_Leads end        
   if object_id('tempdb..#tbl_Segment') is not null begin truncate table #tbl_Segment end        
   if object_id('tempdb..#tbl_Cart') is not null begin truncate table #tbl_Cart end        
    
   Set @RowId = @RowId + 1    
   Set @RNo=1    
   Set @CollCnt=0    
   Set @CollectionId=0    
   Set @SegRowId=1    
   Set @SegRowCnt=0    
   Set @SegmentId=0    
    
  End--end while    
    
  set @RowId=1    
  set @CouponCnt=0    
  Select @CouponCnt=count(*) From #tbl_CartCoupons    
    
  While(@RowId <= @CouponCnt)    
  Begin    
   Select @CouponJson=CouponJson From #tbl_CartCoupons Where RowId=@RowId    
    
   If(len(@CouponJson) > 0)    
   Begin    
    set @CouponJson = (    
		select Coupon.*, FreebeeProduct.*, FreebeeProductDetail.ProductID, coalesce(FreebeeProductDetail.ImageURL,
			FreebeeProductDetail.Picture1, FreebeeProductDetail.Picture2, FreebeeProductDetail.Picture3,
			FreebeeProductDetail.Picture4, FreebeeProductDetail.Picture5) as Thumbnail 
		from tbl_es_coupon(nolock) Coupon left join eshop_freebeecoupon_product(nolock) FreebeeProduct
		on Coupon.CouponId=FreebeeProduct.CouponId left join Products FreebeeProductDetail 
		on FreebeeProductDetail.Name = FreebeeProduct.ProductName and FreebeeProductDetail.User_ID = FreebeeProduct.ParentId
		where couponCode in (select item from dbo.SplitString(@CouponJson,',')) for json auto    
     )    
    
    update #tbl_CartCoupons Set CouponJson=@CouponJson Where RowId=@RowId    
   End    
    
   Set @RowId = @RowId + 1    
  End    
    
  Select * From #tbl_CartCoupons    
    
 End--Endif    
    
END 



GO

/* ============================================================
   Procedure: [dbo].[usp_es_GetApplicableCouponDetail]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_es_GetApplicableCouponDetail(
	@tblFilterCoupon tblFilterCoupon readonly
)
as
begin
	select ec.* from @tblFilterCoupon fc 
		inner join tbl_es_Coupon(nolock) ec on ec.CouponCode = fc.CouponCode and ec.ParentID = fc.UserId
end


GO

/* ============================================================
   Procedure: [dbo].[usp_es_GetCartItemCheckOut]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_es_GetCartItemCheckOut(
	@UserName nvarchar(255),
	@UserId bigint
)
as
begin
	--declare @UserName nvarchar(255) = 'anita.baghel@pelsoftlabs.in', @UserId bigint = 37540
	select
		eci.*, 
		COALESCE(p.TaxName1,p.TaxName2, p.TaxName3) as TaxName,
		COALESCE(p.Tax1,p.Tax2, p.Tax3) as Tax
		from eshop_cart_items eci
		inner join  Products p on eci.ProductID = p.ProductID		
		where eci.UserName = @UserName and eci.User_ID = @UserId


end















			


GO

/* ============================================================
   Procedure: [dbo].[usp_es_GetCartListByUsername]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_es_GetCartListByUsername
@Username NVARCHAR(500)  
AS  
    BEGIN  
        SELECT ec.Cartid,   
               ec.UserName,   
               ec.ProductName,   
               ec.Variant,   
               ec.Quantity,   
               ec.Price,   
               ec.ProductID,   
               ec.TotalAmount,   
               COALESCE(p.ImageURL, p.Picture1, p.Picture2, p.Picture3, p.Picture4, p.Picture5) AS [ImageURL],   
               ec.OrderID,   
               ec.OrderDate,   
               p.User_ID,   
               ec.fulfillmentstatus,  
      p.maxorderquantity  
        FROM eshop_cart_items ec  
             INNER JOIN Products p ON ec.ProductID = p.ProductID  
        WHERE ec.UserName  = @Username  
    END;  


GO

/* ============================================================
   Procedure: [dbo].[usp_es_GetCollectionProduct]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- usp_es_GetCollectionProduct 0,37540
-- ufn_es_GetCollectionProduct 9,32222
CREATE   PROC [dbo].[usp_es_GetCollectionProduct]
(
	@CollectionId int=0, 
	@UserId int 
)  
AS  
BEGIN  
    -- declare @CollectionId int=9,  @UserId int=32222  
	if object_id('tempdb..#CollProds') is not null begin drop table #CollProds end    
	DECLARE @ProdStr nvarchar(max)='', @strQuery nvarchar(max)='', @CollCriteria nvarchar(max)=''  
	Create TABLE #CollProds
	(  
	  ProductId int
	)
  
	If(@CollectionId = 0)
	Begin
		Select @ProdStr= @ProdStr + iif(@ProdStr='','',',') + productId 
		from [collection](nolock)
		where isactive=1 and User_ID=@UserId and ISNULL(productId,'') != ''

		--Select * From collection Where isactive=1 and User_ID=32222 and ISNULL(productId,'') != ''

		--Select * From collection_criteria Where CollectionId in (Select Id from [collection] where isactive=1 and User_ID=37540 and ISNULL(productId,'') = '') 
		-- declare @CollCriteria varchar(max)=''
		Select @CollCriteria = @CollCriteria + ' ' + Op1 + ' ' + (case Operator when 'contains' then ' like ''%'+Op2+'%''' when 'is equal to' then '=''' + Op2 + '''' when 'is not equal to' then '!=''' + Op2 + '''' when 'is greater than' then '>' + op2 when 'is less than' then '<' + op2  when 'Starts with' then ' like '''+Op2+'%''' when 'ends with' then ' like ''%'+Op2+'''' when 'does not contain' then ' not like ''%'+Op2+'%''' else '' end) + ' ' + Conjunction 
		From collection_criteria(nolock) 
		Where CollectionId in (Select Id from [collection](nolock) where isactive=1 and User_ID=@UserId and ISNULL(productId,'') = '') and Active=1
		
		insert into #CollProds
		select item from dbo.SplitString(@ProdStr,',')
		print '@ProdStr: ' + @ProdStr
		
		If(len(@CollCriteria) > 0)
		Begin
			set @CollCriteria=left(@CollCriteria, len(@CollCriteria)-3)
			print '@CollCriteria: ' + @CollCriteria

			set @strQuery = N'insert into #CollProds 
			Select ProductID From ( 
			SELECT	PROD.ProductID, PROD.Name, PROD.CategoryID, PROD.UnitPrice, PROD.OldPrice, PROD.TotalPrice,
					(PROD.OldPrice - PROD.UnitPrice) as Discount, isnull(PROD.AltText,'''') as AltText, PROD.LongDescription,
					PROD.CreatedDate, VARI.PRODUCTNAME as Variant, CAT.Name AS CategoryName
			FROM    Products AS PROD WITH (nolock) LEFT OUTER JOIN VARIANTS AS VARI WITH (nolock) 
			ON		PROD.Name = VARI.PRODUCTNAME AND PROD.User_ID = VARI.User_ID LEFT OUTER JOIN Categories AS CAT WITH (nolock) 
			ON		PROD.CategoryID = CAT.CategoryID
			WHERE   (PROD.User_ID = ' + cast(@UserId as nvarchar(max)) + ') and PROD.isActive=1
			) A
			Where	1=1 AND ' + @CollCriteria
			print '@strQuery: ' + @strQuery
			Exec sp_executesql @strQuery
		End

	End
	Else
	Begin
		Select @ProdStr= @ProdStr + iif(@ProdStr='','',',') + productId 
		from [collection](nolock)
		where isactive=1 and id=@CollectionId and ISNULL(productId,'') != ''

		--Select * From collection Where isactive=1 and User_ID=32222 and ISNULL(productId,'') != ''

		--Select * From collection_criteria Where CollectionId in (Select Id from [collection] where isactive=1 and User_ID=37540 and ISNULL(productId,'') = '') 
		-- declare @CollCriteria varchar(max)=''
		Select @CollCriteria = @CollCriteria + ' ' + Op1 + ' ' + (case Operator when 'contains' then ' like ''%'+Op2+'%''' when 'is equal to' then '=''' + Op2 + '''' when 'is not equal to' then '!=''' + Op2 + '''' when 'is greater than' then '>' + op2 when 'is less than' then '<' + op2  when 'Starts with' then ' like '''+Op2+'%''' when 'ends with' then ' like ''%'+Op2+'''' when 'does not contain' then ' not like ''%'+Op2+'%''' else '' end) + ' ' + Conjunction 
		From collection_criteria(nolock) 
		Where CollectionId in (Select Id from [collection](nolock) where isactive=1 and id=@CollectionId and ISNULL(productId,'') = '') and Active=1
		
		insert into #CollProds
		select item from dbo.SplitString(@ProdStr,',')
		--print '@ProdStr: ' + @ProdStr
		
		If(len(@CollCriteria) > 0)
		Begin
			set @CollCriteria=left(@CollCriteria, len(@CollCriteria)-3)
			--print '@CollCriteria: ' + @CollCriteria

			set @strQuery = 'insert into #CollProds 
			Select ProductID From ( 
			SELECT	PROD.ProductID, PROD.Name, PROD.CategoryID, PROD.UnitPrice, PROD.OldPrice, PROD.TotalPrice,
					(PROD.OldPrice - PROD.UnitPrice) as Discount, isnull(PROD.AltText,'''') as AltText, PROD.LongDescription,
					PROD.CreatedDate, VARI.PRODUCTNAME as Variant, CAT.Name AS CategoryName
			FROM    Products AS PROD WITH (nolock) LEFT OUTER JOIN VARIANTS AS VARI WITH (nolock) 
			ON		PROD.Name = VARI.PRODUCTNAME AND PROD.User_ID = VARI.User_ID LEFT OUTER JOIN Categories AS CAT WITH (nolock) 
			ON		PROD.CategoryID = CAT.CategoryID
			WHERE   (PROD.User_ID = ' + cast(@UserId as varchar) + ') and PROD.isActive=1
			) A
			Where	1=1 AND ' + @CollCriteria
			Exec(@strQuery)
			--print '@strQuery: ' + @strQuery
		End
	End

	Select * From #CollProds  
  
END



