/* ============================================================
   Procedure: [dbo].[usp_es_GetCouponProduct]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


-- Exec usp_es_GetCouponProduct 0,37540)
-- Exec usp_es_GetCouponProduct 0,32222)
CREATE   PROCEDURE [dbo].usp_es_GetCouponProduct
(
	@CriteriaDetail varchar(max), 
	@UserId int 
)  
AS  
BEGIN  
    --declare @CriteriaDetail varchar(max)='Name like ''%s%'' AND UnitPrice < ''1000'' ',  @UserId int=32222
    --declare @CriteriaDetail varchar(max)='Categoryname = ''Sports'' or name=''mobile'' ',  @UserId int=32222
	if object_id('tempdb..#CouponProds') is not null begin drop table #CouponProds end    
	if object_id('tempdb..#tbl_Collection') is not null begin drop table #tbl_Collection end    
	DECLARE @ProdStr varchar(max)='', @strQuery varchar(max)='', @CollCriteria varchar(max)='', @RowId int=1, @ColCnt int=0,
			@CollectionName varchar(50)='', @Collectionid int=0

	Create table #CouponProds
	(  
	  ProductId int,
	  CollectionName varchar(50)
	)

	Create TABLE #tbl_Collection
	(  
	  RowId int identity(1,1),
	  ProductId varchar(max),
	  CollectionName varchar(50)
	)
  
	If(@CriteriaDetail != '')
	Begin

		insert into #tbl_Collection
		Select productId, [Name] as CollectionName
		from [collection](nolock)
		where isactive=1 and User_ID=@UserId and ISNULL(productId,'') != ''

		select @ColCnt=count(RowId) from #tbl_Collection

		While(@RowId <= @ColCnt)
		Begin
			Select @ProdStr= @ProdStr + iif(@ProdStr='','',',') + productId, @CollectionName=CollectionName 
			from #tbl_Collection
			where RowId=@RowId

			insert into #CouponProds
			select item as ProductId, @CollectionName as CollectionName
			from dbo.SplitString(@ProdStr,',')
			--print '@ProdStr: ' + @ProdStr

			set @ProdStr=''
			set @CollectionName=''
			Set @RowId = @RowId + 1
		End

		truncate table #tbl_Collection
		set @CollectionName=''
		Set @RowId = 1
		Set @ColCnt = 0

		insert into #tbl_Collection
		Select id as productId, [Name] as CollectionName
		from [collection](nolock)
		where isactive=1 and User_ID=@UserId and ISNULL(productId,'') = ''

		select @ColCnt=count(RowId) from #tbl_Collection

		While(@RowId <= @ColCnt)
		Begin
			Select @Collectionid=productId, @CollectionName=CollectionName 
			from #tbl_Collection
			where RowId=@RowId

			Select @CollCriteria = @CollCriteria + ' ' + Op1 + ' ' + (case Operator when 'contains' then ' like ''%'+Op2+'%''' when 'is equal to' then '=''' + Op2 + '''' when 'is not equal to' then '!=''' + Op2 + '''' when 'is greater than' then '>' + op2 when 'is less than' then '<' + op2  when 'Starts with' then ' like '''+Op2+'%''' when 'ends with' then ' like ''%'+Op2+'''' when 'does not contain' then ' not like ''%'+Op2+'%''' else '' end) + ' ' + Conjunction 
			From collection_criteria(nolock) 
			Where CollectionId = @Collectionid and Active=1

			If(len(@CollCriteria) > 0)
			Begin
				set @CollCriteria=left(@CollCriteria, len(@CollCriteria)-3)
				--print '@CollCriteria: ' + @CollCriteria

				set @strQuery = 'insert into #CouponProds 
				Select distinct ProductID, ''' + @CollectionName + ''' as CollectionName From ( 
				SELECT	PROD.ProductID, PROD.Name, PROD.CategoryID, PROD.UnitPrice, PROD.OldPrice, PROD.TotalPrice,
						(PROD.OldPrice - PROD.UnitPrice) as Discount, isnull(PROD.AltText,'''') as AltText, PROD.LongDescription,
						PROD.CreatedDate, VARI.PRODUCTNAME as Variant, CAT.Name AS CategoryName
				FROM    Products AS PROD WITH (nolock) LEFT OUTER JOIN VARIANTS AS VARI WITH (nolock) 
				ON		PROD.Name = VARI.PRODUCTNAME AND PROD.User_ID = VARI.User_ID LEFT OUTER JOIN Categories AS CAT WITH (nolock) 
				ON		PROD.CategoryID = CAT.CategoryID
				WHERE   (PROD.User_ID = ' + cast(@UserId as varchar) + ') and PROD.isActive=1
				) A
				Where	1=1 AND ' + @CollCriteria 
				
				--print '@strQuery: ' + @strQuery
				Exec(@strQuery)
			End

			set @Collectionid=0
			set @CollectionName=''
			set @CollCriteria=''
			Set @RowId = @RowId + 1
		End

		set @strQuery = 'Select distinct ProductID From ( 
		SELECT	PROD.ProductID, PROD.Name, PROD.CategoryID, PROD.UnitPrice, PROD.OldPrice, PROD.TotalPrice,
				(PROD.OldPrice - PROD.UnitPrice) as Discount, isnull(PROD.AltText,'''') as AltText, PROD.LongDescription,
				PROD.CreatedDate, VARI.PRODUCTNAME as Variant, CAT.Name AS CategoryName, 
				isnull(COLL.CollectionName,'''') as CollectionName
		FROM    Products AS PROD WITH (nolock) LEFT OUTER JOIN VARIANTS AS VARI WITH (nolock) 
		ON		PROD.Name = VARI.PRODUCTNAME AND PROD.User_ID = VARI.User_ID LEFT OUTER JOIN Categories AS CAT WITH (nolock) 
		ON		PROD.CategoryID = CAT.CategoryID Left join #CouponProds COLL
		ON		PROD.ProductID = COLL.ProductID
		WHERE   (PROD.User_ID = ' + cast(@UserId as varchar) + ') and PROD.isActive=1
		) A
		Where	1=1 AND ' + @CriteriaDetail

		--print '@strQuery: ' + @strQuery
		Exec(@strQuery)
	End
  
  
END



GO

/* ============================================================
   Procedure: [dbo].[usp_es_GetData]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- Exec usp_es_GetData @UserId=33097,@Mode='EShopClientDomain'    
-- Exec usp_es_GetData @UserId=0,@Mode='GetUserIdByDomain', @Param1=''   

-- Exec usp_es_GetData @UserId=37540,@Mode='Coupon', @Param1=''        
-- Exec usp_es_GetData @UserId=0,@Mode='FreebeeCouponProduct', @Param1='1'        
-- Exec usp_es_GetData @UserId=0,@Mode='CouponById', @Param1='1'        
-- Exec usp_es_GetData @UserId=33097,@Mode='CollCatProdUrl'    
-- Exec usp_es_GetData @UserId=33097,@Mode='Collection'    
-- Exec usp_es_GetData @UserId=33097,@Mode='PageTheme'    
-- Exec usp_es_GetData @UserId=33097,@Param1='Home',@Mode='PageTheme'    
CREATE   PROC usp_es_GetData    
(      
 @UserId bigint=0,    
 @Param1 varchar(500)='',    
 @Mode varchar(50)    
)    
AS    
Begin    
    
 If(@Mode='EShopClientDomain')    
 Begin    
  Select * From eshop_client_domain(nolock) Where User_Id=@UserId    
 End    
    
 If(@Mode='CollCatProdUrl')    
 Begin    
  Select [Name], 'Collection' as [Type], '/Product/GetProductsByCategory?CollectionName=' + [Name] as [Url], [Id]
  From collection(nolock)     
  Where User_Id=@UserId and IsActive=1    
    
  union    
    
  Select [Name], 'Category' as [Type], '/Product/GetProductsByCategory?CategoryName=' + [Name] as [Url], CategoryId as Id
  From Categories(nolock)     
  Where User_Id=@UserId and IsActive=1    
    
  union    
    
  Select [Name], 'Product' as [Type], '/Product/GetProductsByCategory?ProductName=' + [Name] as [Url], ProductId as Id
  From products(nolock)     
  Where User_Id=@UserId and IsActive=1    
 End    
    
 If(@Mode='Collection')    
 Begin    
  Select *    
  From [Collection](nolock)    
  Where USER_ID=@UserId and IsActive=1    
  Order by SortOrder    
 End    
    
 If(@Mode='PageTheme')    
 Begin    
  Select * From [tbl_es_PageTheme](nolock) Where User_Id=@UserId and PageName=Case When @Param1='' then PageName else @Param1 end    
 End    
  
 IF(@Mode = 'GetUserIdByDomain')  
 Begin    
  Select * From eshop_client_domain(nolock) Where Domain = @Param1  
 End    
 
 If(@Mode='Coupon')    
 Begin    
  Select * From tbl_es_Coupon(nolock) Where ParentId=@UserId    
 End    

 If(@Mode='CouponById')    
 Begin    
  Select * From tbl_es_Coupon(nolock) Where CouponID = @Param1
 End    

 IF(@Mode = 'FreebeeCouponProduct')  
 Begin    
  Select * From eshop_freebeecoupon_product(nolock) Where CouponID = @Param1  
 End    

End 



GO

/* ============================================================
   Procedure: [dbo].[usp_es_GetDetailForPasswordReset]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_es_GetDetailForPasswordReset    
 @Username nvarchar(255),    
 @DomainName nvarchar(255)    
as    
begin    
  -- DECLARE @UserName NVARCHAR(255)= 'kit19delhi@gmail.com', @DomainName NVARCHAR(255)= 'localhost';    
  
  declare @Customerid bigint  = 0  
    
  set @Customerid = ( SELECT CustomerID FROM Customers(NOLOCK) c   
 INNER JOIN eshop_client_domain(NOLOCK) ecd ON c.User_ID = ecd.User_Id    
  WHERE ecd.Domain = @DomainName AND c.UserName = @UserName )  ;  
  
  print @Customerid

  if(@Customerid> 0)  
  begin   
   
  declare @ResetGuid nvarchar(255) = newid();  
  
  if(Exists(select * from tbl_es_CustomerLoginDetail where CustomerId = @Customerid))  
   begin  
    update tbl_es_CustomerLoginDetail set ResetGuid = @ResetGuid, ResetExpired = 0, ResetRequestedOn = GETDATE()  
     WHERE CustomerId = @Customerid  
   end  
  else  
   begin  
    insert into tbl_es_CustomerLoginDetail ( CustomerId, MachineName, DeviceId, MACAddress, OTP, LastUpdatedOn, ResetGuid, ResetRequestedOn, ResetExpired )  
     values ( @Customerid, '', '', '', '', GETDATE(), @ResetGuid,  GETDATE(), 0 )   
   end  
    
  SELECT   
   c.UserName,  
   c.First_Name,  
   c.Last_Name,  
   COALESCE(c.Email, c.AltEmail) as [CustomerEmail],  
   cld.ResetGuid,  
   cld.ResetExpired,  
   cld.ResetRequestedOn,  
   ud.FName + ' ' + ud.LName as FullName,      
      COALESCE(sd.Storename, ud.CompnayName, ud.FName) as CompanyName,      
      gl.LogoUrl,       
      LTRIM(RTRIM(CONCAT(      
    --Address      
    IIF(ISNULL(md.FullAddress, '') = '', '',  ' ' + md.FullAddress),      
     --City      
     IIF(ISNULL(md.FullAddress, '') = '', '',  ' ' + sa.City_Name),      
      --State      
      IIF(ISNULL(sa.City_Name, '') = '', '',  ', ' + sa.State_Name),       
       --Country      
       IIF(ISNULL(sa.State_Name, '') = '', '',  ', ' + sa.Country_Name),      
     --Pincode      
     IIF(ISNULL(null, '') = '', '',  ' ' + '')      
      ))) as FullAddress,   
     sa.Country_Name as CountryName,      
     sa.State_Name as StateName,      
     sa.City_Name as CityName,      
     sa.Mobile as MobileNo,      
     sd.Storename,      
     ud.Email,      
     md.GSTNo,      
     md.PANNo,      
     ud.User_ID as UserId    FROM Customers(NOLOCK) c    
    left JOIN tbl_es_CustomerLoginDetail(NOLOCK) cld on c.CustomerID = cld.CustomerId  
    left JOIN User_Detail(nolock) ud on c.User_ID = ud.User_ID     
    left JOIN eshop_store_address(nolock) sa on sa.User_ID = ud.User_ID           
    LEFT JOIN eshop_store_details(nolock) sd on sd.User_ID = ud.User_ID           
    LEFT JOIN genlogo(nolock) gl on ud.User_ID = gl.User_ID and gl.isDeleted = 0      
    LEFT JOIN tbl_es_MiscellaneousDetail(nolock) md on sd.User_ID = md.User_ID      
    where c.CustomerID = @Customerid  
  end  
end    


GO

/* ============================================================
   Procedure: [dbo].[usp_es_GetFeaturedProduct]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

    
    
-- exec usp_es_GetFeaturedProduct 33097    
CREATE   PROCEDURE usp_es_GetFeaturedProduct 
@UserId bigint    
as    
begin    
if(object_id('tempdb..#tempCollection') is not null ) begin drop table #tempCollection end    
if(object_id('tempdb..#tempFeatureProduct') is not null ) begin drop table #tempFeatureProduct end    
    
declare @tempCollId bigint = 0, @SearchFilter nvarchar(max) = '', @CollectionName nvarchar(1000)
    
select p.ProductID , p.Name , p.SupplierID , p.CategoryID , p.SubCategoryID , p.QuantityPerUnit , p.UnitPrice , p.OldPrice , p.UnitWeight , p.Size , p.Discount , p.UnitInStock , p.UnitOnOrder , p.ProductAvailable , p.ImageURL , p.AltText , p.AddBadge , p.OfferTitle , p.OfferBadgeClass , p.ShortDescription , p.LongDescription , p.Picture1 , p.Picture2 , p.Picture3 , p.Picture4 , p.Note , p.StockKeepingUnit , p.Picture5 , p.Barcode , p.HarmonizedSystemCode , p.PointofSale , p.PublicationStartDate , p.Country_Name , p.User_ID , p.CreatedDate , p.Video , p.ImageURL_T , p.ImageURL_L , p.Picture1_T , p.Picture1_L , p.Picture2_L , p.Picture2_T , p.Picture3_T , p.Picture3_L , p.Picture4_L , p.Picture4_T , p.Picture5_T , p.Picture5_L , p.Return_days , p.Exchange_days , p.Shipped_days , p.TaxName1 , p.TaxName2 , p.TaxName3 , p.Tax1 , p.Tax3 , p.Tax2 , p.isActive , p.TotalSell , p.TotalReturn , p.Totalwish , p.SortOrder , c.Name as [CategoryName] , p.TotalPrice , p.Title , p.Meta_description , p.Meta_Tags , p.PageName , p.ReOrderLevel , p.minorderquantity , p.maxorderquantity, cast('' as nvarchar(500)) as CollectionName into #tempFeatureProduct from  Products AS p INNER JOIN Categories AS c ON p.CategoryID = c.CategoryID    
WHERE p.User_ID = @UserId and 1=2;    

  
    
select id, 0 as isProccesed, name as [CollectionName] into #tempCollection from collection where isfeatured = 1 and USER_ID = @UserId    
    
while(exists( select 1 from #tempCollection where isProccesed = 0))    
begin 
select top 1 @tempCollId = id, @CollectionName = CollectionName from #tempCollection where isProccesed = 0    

set @SearchFilter = N' INSERT INTO #tempFeatureProduct ( ProductID , Name , SupplierID , CategoryID , SubCategoryID , QuantityPerUnit , UnitPrice , OldPrice , UnitWeight , Size , Discount , UnitInStock , UnitOnOrder , ProductAvailable , ImageURL , AltText , AddBadge , OfferTitle , OfferBadgeClass , ShortDescription , LongDescription , Picture1 , Picture2 , Picture3 , Picture4 , Note , StockKeepingUnit , Picture5 , Barcode , HarmonizedSystemCode , PointofSale , PublicationStartDate , Country_Name , User_ID , CreatedDate , Video , ImageURL_T , ImageURL_L , Picture1_T , Picture1_L , Picture2_L , Picture2_T , Picture3_T , Picture3_L , Picture4_L , Picture4_T , Picture5_T , Picture5_L , Return_days , Exchange_days , Shipped_days , TaxName1 , TaxName2 , TaxName3 , Tax1 , Tax3 , Tax2 , isActive , TotalSell , TotalReturn , Totalwish , SortOrder , CategoryName , TotalPrice , Title , Meta_description , Meta_Tags , PageName , ReOrderLevel , minorderquantity , maxorderquantity, CollectionName)    
  select p.ProductID , p.Name , p.SupplierID , p.CategoryID , p.SubCategoryID , p.QuantityPerUnit , p.UnitPrice , p.OldPrice , p.UnitWeight , p.Size , p.Discount , p.UnitInStock , p.UnitOnOrder , p.ProductAvailable , p.ImageURL , p.AltText , p.AddBadge , p.OfferTitle , p.OfferBadgeClass , p.ShortDescription , p.LongDescription , p.Picture1 , p.Picture2 , p.Picture3 , p.Picture4 , p.Note , p.StockKeepingUnit , p.Picture5 , p.Barcode , p.HarmonizedSystemCode , p.PointofSale , p.PublicationStartDate , p.Country_Name , p.User_ID , p.CreatedDate , p.Video , p.ImageURL_T , p.ImageURL_L , p.Picture1_T , p.Picture1_L , p.Picture2_L , p.Picture2_T , p.Picture3_T , p.Picture3_L , p.Picture4_L , p.Picture4_T , p.Picture5_T , p.Picture5_L , p.Return_days , p.Exchange_days , p.Shipped_days , p.TaxName1 , p.TaxName2 , p.TaxName3 , p.Tax1 , p.Tax3 , p.Tax2 , p.isActive , p.TotalSell , p.TotalReturn , p.Totalwish , p.SortOrder , c.Name as [CategoryName] , p.TotalPrice , p.Title , p.Meta_description , p.Meta_Tags , p.PageName , p.ReOrderLevel , p.minorderquantity , p.maxorderquantity, ''' + @CollectionName +'''    
FROM Products AS p INNER JOIN Categories AS c ON p.CategoryID = c.CategoryID    
WHERE p.User_ID = ' + Cast( @UserId  as nvarchar)  


 
 if(object_id('tempdb..#temCollectionCriteria') is not null ) begin drop table #temCollectionCriteria end    
     
 select *, 0 as isProccesed into #temCollectionCriteria from collection_criteria where collectionid = @tempCollId    

 while(exists( select 1 from #temCollectionCriteria where isProccesed = 0))    
 begin    
  declare @Conjunction nvarchar(100), @Op1 nvarchar(100), @Op2 nvarchar(100), @Operator nvarchar(100), @tempCollCriId bigint = 0    
  select top 1 @tempCollCriId = id, @Conjunction = Conjunction, @Op1 = Op1, @Op2 = Op2, @Operator = Operator from #temCollectionCriteria where isProccesed = 0;    
    
  PRINT @Op1    
    
  if(LTRIM(RTRIM(ISNULL(@Op1, ''))) !=  '')    
  begin    
   if(Lower(@Op1) = 'varient')    
   begin    
    set @SearchFilter =  @SearchFilter + ' ' + @Conjunction + '  name in (select PRODUCTNAME from VARIANTS where V_VALUE''' +' '+ @Operator +CASE  WHEN  @Operator = 'like' THEN ' ''%'+@Op2+'%''' ELSE ''''+ @Op2 +''''END +')'+''''     
   end    
   else    
   begin    
    set @SearchFilter =  @SearchFilter + ' ' + @Conjunction + '  ' +     
    CASE WHEN LOWER(@Op1) = 'name'    
      THEN  'p.'+@Op1 + '  '    
       WHEN LOWER(@Op1) = 'categoryname'    
      THEN  'c.name '    
      ELSE    
      ''    
      END    
    + '  ' +      
    CASE     
     WHEN @Operator = 'is equal to'     
      THEN ' = ''' + @Op2 +''''     
     WHEN @Operator = 'is not equal to'    
      THEN ' != ''' + @Op2 +''''             
     WHEN @Operator = 'is greater than'    
      THEN ' > ''' + @Op2 +''''     
     WHEN @Operator = 'is less than'    
      THEN ' < ''' + @Op2 +''''    
     WHEN @Operator = 'Starts with'    
      THEN ' like ''' +@Op2 + '%'''             
     WHEN @Operator = 'ends with'    
      THEN ' like ''%' +@Op2 + ''''    
     WHEN @Operator = 'contains'    
      THEN 'like ''%'+@Op2+'%'''    
     WHEN @Operator = 'does not contain'    
      THEN ' not like ''%' +@Op2 + '%'''    
     end    
   end    
  end    
      
    
      
    
  update #temCollectionCriteria set isProccesed = 1 where id = @tempCollCriId    
 end    
     
print @SearchFilter    
    
    
 EXECUTE sp_executesql @SearchFilter    
     
 update #tempCollection set isProccesed = 1 where id = @tempCollId    
end    
    
    
    
select * from #tempFeatureProduct    
end 


GO

