/* ============================================================
   Procedure: [dbo].[usp_es_GetLoyaltyRedemptionSetting]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- Exec usp_es_GetLoyaltyRedemptionSetting 37540
CREATE   PROC usp_es_GetLoyaltyRedemptionSetting
(  
	@UserId	bigint
)  
As  
BEGIN  
	-- declare @UserId	bigint=37540
	SELECT [Id],[RuleName],[RuleDescription],[ParentId],[Condition],[Points],[Percentage],[FreebeeProducts]
		  ,[IsUserSelected],[IsActive],[RuleSequence],[LastSavedOn]=ISNULL([LastModifiedOn],[CreatedOn])
		  ,[LastSavedBy]=ISNULL([LastModifiedBy],[CreatedBy]), (SELECT STUFF( (SELECT N', ' + [ss].[Name]
			FROM [Products](nolock) AS [ss] INNER JOIN [dbo].[fn_Split]([FreebeeProducts], ',') AS [fs]
			ON [ss].[ProductID] = [fs].[value] FOR XML PATH(''), TYPE
			).value('text()[1]', 'nvarchar(max)'), 1, 2, N'')
			) AS [ProductsName]
	FROM	[dbo].[eshop_redemptionsettings] WITH(NOLOCK)
	WHERE  [ParentId] = @UserId
	Order By [RuleSequence]
 
END  



GO

/* ============================================================
   Procedure: [dbo].[usp_es_GetLoyaltyRewardsSetting]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- Exec usp_es_GetLoyaltyRewardsSetting 37540
CREATE   PROC usp_es_GetLoyaltyRewardsSetting
(  
	@UserId	bigint
)  
As  
BEGIN  
	-- declare @UserId	bigint=37540
	SELECT	[AM].[EventName], [AM].[eventby], isnull([RS].[Id],0) as [Id], isnull([RS].[RuleName],'') as [RuleName], 
			isnull([RS].[RuleDescription],'') as [RuleDescription], isnull([RS].[ParentId],@UserId) as [ParentId],
			isnull([RS].[EventId],[AM].[ID]) as [EventId], isnull([RS].[Condition],'') as [Condition], 
			isnull([RS].[Points],0) as [Points], isnull([RS].[Percentage],0) as [Percentage], 
			isnull([RS].[IsActive],0) as [IsActive], isnull([RS].[RuleSequence],1) as [RuleSequence],
			isnull([RS].[IsPublished],0) as [IsPublished], isnull([RS].[LastModifiedOn], [RS].[CreatedOn]) as LastSavedOn, 
			isnull([RS].[LastModifiedBy], [RS].[CreatedBy]) as LastSavedBy, 
			(case when [RS].[IsActive] is null then 1 else 0 end) as [IsComingSoon],
			(case when [AM].[ID] in (20) then 'Both' else 'Point' end) as [PointPerc]
			-- select * 
	FROM	ActivityMaster AS AM WITH(NOLOCK) LEFT OUTER JOIN eshop_rewardssettings AS RS WITH(NOLOCK)
	ON		[AM].ID = [RS].EventId AND ([RS].[ParentId] = @UserId)
	WHERE  ([AM].[EventType] = 'eshop') and ([AM].[EventBy] = 'Lead') and [AM].[ID] not in (21,34,67,69,71,72,74)
 
END  



GO

/* ============================================================
   Procedure: [dbo].[usp_es_GetMembers]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- exec usp_es_GetMembers @UserId=37540,@SearchText=default,@OrderBy=N'Oldest'
-- exec usp_es_GetMembers @UserId=37540,@SearchText=N'aji',@OrderBy=N'Oldest'
-- exec usp_es_GetMembers @UserId=37540,@SearchText=N'aj',@OrderBy=N'Oldest'
CREATE   PROC usp_es_GetMembers
(
	@UserId bigint,
	@SearchText varchar(500)='',
	@OrderBy varchar(100)=''
)
As
Begin
	-- declare @UserId bigint=37540, @SearchText varchar(500)='ajit', @OrderBy varchar(100)='oldest'
	declare @Str varchar(max)=''

	set @Str = '
	Select * From
	(
	Select Cust.*, isnull((Select top 1 RM.PointsBalance From eshop_rewardsmapping(nolock) RM Where RM.CustomerID = Cust.CustomerID Order By RM.Id Desc),0) as PointsBalance 
	From customers(nolock) Cust
	Where	User_ID = ' + cast(@UserId as varchar)  + ' and 
			(
				UserName like case when ''' + @SearchText + '''='''' then ''%%'' else ''%' + @SearchText + '%'' end
				or
				Email like case when ''' + @SearchText + '''='''' then ''%%'' else ''%' + @SearchText + '%'' end
				or
				mobile1 like case when ''' + @SearchText + '''='''' then ''%%'' else ''%' + @SearchText + '%'' end
			)
	) T
	order by ' + iif(@OrderBy = 'Oldest','created asc',iif(@OrderBy = 'Newest','created desc', iif(@OrderBy ='Points', 'PointsBalance desc', 'CustomerID desc')))

	--print @Str
	Exec(@Str)

End



GO

/* ============================================================
   Procedure: [dbo].[usp_es_GetMemberTransaction]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- Exec usp_es_GetMemberTransaction 689
CREATE   PROC usp_es_GetMemberTransaction
(
	@CustomerId bigint
)
As
Begin
	-- declare @CustomerId bigint=689
	SELECT RM.Id, RM.ActivityId, RM.ActivityType, RM.LoyaltyId, RM.Points, RM.CustomerId, RM.leadid, RM.PointsBalance, 
		   RM.description, RM.CreatedOn, CUST.First_Name, CUST.Last_Name, CUST.UserName, CUST.Age, CUST.Gender, 
		   CUST.DateofBirth, CUST.Mobile1, CUST.Picture, CUST.LastLogin, CUST.Created, CUST.User_ID, CUST.Email, 
		   DATEADD(DD, GS.PointsExpiryDays, RM.CreatedOn) AS ExpiryDate
	FROM   eshop_rewardsmapping AS RM WITH(NOLOCK) INNER JOIN Customers AS CUST WITH(NOLOCK) 
	ON	   RM.CustomerId = CUST.CustomerID INNER JOIN tbl_es_LoyaltyGlobalSetting AS GS WITH(NOLOCK)
	ON	   CUST.User_ID=GS.User_ID
	WHERE  RM.CustomerId = @CustomerId
	ORDER BY RM.CreatedOn DESC;

End



