/* ============================================================
   Procedure: [dbo].[usp_es_GetOrderdetailByOrderId]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- exec usp_es_GetOrderdetailByOrderId @OrderId=599
-- exec usp_es_GetOrderdetailByOrderId @OrderId=600
-- exec usp_es_GetOrderdetailByOrderId @OrderId=601
-- exec usp_es_GetOrderdetailByOrderId @OrderId=602
-- exec usp_es_GetOrderdetailByOrderId @OrderId=603
-- exec usp_es_GetOrderdetailByOrderId @OrderId=604
-- exec usp_es_GetOrderdetailByOrderId @OrderId=605
-- exec usp_es_GetOrderdetailByOrderId @OrderId=606
-- exec usp_es_GetOrderdetailByOrderId @OrderId=608
CREATE   PROCEDURE usp_es_GetOrderdetailByOrderId             
 @OrderId BIGINT            
AS            
    BEGIN            
  declare @UserId bigint = 0;            
  select @UserId  = User_ID from [Order] where OrderID = @OrderId            
            
  print @UserId            
            
  -- If Invoice number not exists in database start             
            
  if( not exists (select 1 from tbl_es_InvoiceDetail where OrderID = @OrderId))            
  begin            
   declare @InvoicePrefix nvarchar(100), @InvoiceSuffix nvarchar(100), @InvoiceStartNo bigint            
            
   select @InvoicePrefix  = ISNULL(InvoicePrefix, ''), @InvoiceSuffix   = ISNULL(InvoiceSuffix, ''), @InvoiceStartNo = ISNULL(InvoiceStartNo, 1) from eshop_order_number_setting --where User_ID =  @UserId            
   declare @InvoiceCount bigint = 0;            
   select @InvoiceCount = (Count(1) + @InvoiceStartNo) from tbl_es_InvoiceDetail where User_ID = @UserId            
            
            
   declare @GenInvioceNo nvarchar(250) = LTRIM(RTRIM(REPLACE(@InvoicePrefix, ' ', ''))) + '_'+LTRIM(RTRIM(REPLACE(str(@InvoiceCount), ' ', ''))) + '_' + LTRIM(RTRIM(REPLACE(@InvoiceSuffix, ' ', '')));            
            
   insert tbl_es_InvoiceDetail (User_ID, OrderID, InvoiceNo, CreatedOn, UpdatedOn)            
    values (@UserId, @OrderId, @GenInvioceNo, getdate(), getdate())            
            
  end            
            
  -- If Invoice number not exists in database end            
            
            
  -- StoreInformation start            
               
  SELECT             
   ud.FName + ' ' + ud.LName as FullName,            
   COALESCE(sd.Storename, ud.CompnayName, ud.FName) as CompanyName,            
   gl.LogoUrl,             
   LTRIM(RTRIM(CONCAT(            
    --Address            
    IIF(ISNULL(md.FullAddress, '') = '', '',  ' ' + md.FullAddress),            
     --City            
     IIF(ISNULL(md.FullAddress, '') = '', '',  ' ' + sa.City_Name),            
      --State            
      IIF(ISNULL(sa.City_Name, '') = '', '',  ', ' + sa.State_Name),             
       --Country            
       IIF(ISNULL(sa.State_Name, '') = '', '',  ', ' + sa.Country_Name),            
        --Pincode            
        IIF(ISNULL(null, '') = '', '',  ' ' + '')            
   ))) as FullAddress,            
            
   sa.Country_Name as CountryName,            
   sa.State_Name as StateName,            
   sa.City_Name as CityName,            
   sa.Mobile as MobileNo,            
   sd.Storename,            
   ud.Email,            
   md.GSTNo,            
   md.PANNo,            
   ud.User_ID as UserId            
   FROM  User_Detail ud             
     left JOIN eshop_store_address sa on sa.User_ID = ud.User_ID                 
     Left JOIN eshop_store_details sd on sd.User_ID = ud.User_ID                 
     Left JOIN genlogo gl on ud.User_ID = gl.User_ID and gl.isDeleted = 0            
     LEFT JOIN tbl_es_MiscellaneousDetail md on ud.User_ID = md.User_ID            
   WHERE ud.User_ID = @UserId            
            
  --StoreInformation end            
            
        --OrderInfo start            
        SELECT            
               c.First_Name AS FirstName,            
               c.Last_Name AS  LastName,            
               o.OrderID AS  OrdeId,            
               o.OrderNo,             
               Convert(nvarchar(15), o.OrderDate, 106) as OrderDate,             
      i.InvoiceNo as InvoiceNumber,            
      Convert(nvarchar(15), o.OrderDate, 106) as InvoiceDate,            
               p.PaymentStatus,             
               p.PaymentMode,             
               CONVERT(NUMERIC(18, 2), o.TotalAmount) AS TotalAmount            
        FROM [Order] AS o INNER JOIN Payment AS p ON o.OrderID = p.OrderNo
    INNER JOIN tbl_es_InvoiceDetail i on o.OrderID = i.OrderID             
    INNER JOIN Customers c on o.CustomerID = c.CustomerID            
        WHERE o.OrderID = @OrderId;            
  --OrderInfo end            
                  --ProductList start            
        IF OBJECT_ID('tempdb..#OrderProducts') = NULL            
            BEGIN            
                DROP TABLE #OrderProducts;            
        END;            
        SELECT ROW_NUMBER() OVER(            
               ORDER BY od.TotalAmount desc) AS SNo,             
               COALESCE(p.ImageURL, p.Picture1, p.Picture2, p.Picture3, p.Picture4, p.Picture5) AS Image,             
               p.Name AS Name,             
               od.Variant AS Variant,             
               '' AS Description,             
               CONVERT(NUMERIC(18, 2), od.UnitPrice) AS UnitPrice,             
      CONVERT(NUMERIC(18, 2), od.Discount) as Discount,            
               od.Quantity,             
      (od.TotalAmount + ISNULL(od.Discount, 0)) AS NetAmount,             
               CONVERT(NUMERIC(18, 2), COALESCE(p.Tax1, p.Tax2, p.Tax3)) AS TaxRate,             
               COALESCE(p.TaxName1, p.TaxName2, p.TaxName3) AS TaxType,             
               --CONVERT(NUMERIC(18, 2), (od.UnitPrice - ISNULL(od.Discount, 0)) * ISNULL(COALESCE(p.Tax1, p.Tax2, p.Tax3), 0) / 100) AS TaxAmount,      
			   CONVERT(NUMERIC(18, 2), isnull(od.TaxAmt,0)) as TaxAmount,
       CONVERT(NUMERIC(18, 2), (od.TotalAmount + ISNULL(od.TaxAmt, 0))) AS TatalAmount,            
      p.User_ID as UserId            
        INTO #OrderProducts            
        FROM OrderDetails AS od            
             INNER JOIN Products AS p ON od.ProductName = p.Name            
                                         AND od.User_ID = p.User_ID            
        WHERE od.OrderID = @OrderId;  
    
  SELECT * FROM #OrderProducts order by TatalAmount desc;            
  --ProductList end            
            
            
        --ShippingAddress start            
        SELECT FirstName,             
               LastName,             
      Mobile,            
               Email,             
               Address,             
               City_Name AS City,             
               State_Name AS State,             
               Country_Name AS Country,             
               PostCode AS Postcode            
        FROM ShippingDetails            
        WHERE OrderID = @OrderId;            
  --ShippingAddress end            
            
        --BillingDetails start            
        SELECT FirstName,             
               LastName,             
      Mobile,            
               Email,             
               Address,             
               City_Name AS City,             
               State_Name AS State,             
               Country_Name AS Country,             
               PostCode AS Postcode            
        FROM BillingDetails            
        WHERE OrderID = @OrderId;            
                   
  declare @TotalOrderAmount numeric(18,2)          
  declare @SippingCharge numeric(18,2), @RedemptionAmt numeric(18,2)

          
   select @TotalOrderAmount = o.TotalAmount, @SippingCharge = sc.Amount from tbl_es_ShippingCharges sc           
    right join [Order] o on  sc.Shipping_Id = o.ShippingID          
     where  o.OrderId = @OrderId          
          
	Select @RedemptionAmt=RedemptionAmt From tbl_es_InvoiceDetail Where OrderId=@OrderId
          
  --Summary start            
        SELECT            
     SUM(ISNULL(NetAmount, 0)) as TotalPrice,            
     SUM(ISNULL(Discount, 0)) as TotalDiscount,            
     SUM(ISNULL(TaxAmount, 0)) as TotalTax,            
     ISNULL(@RedemptionAmt, 0) as RedemptionAmt ,          
     ISNULL(@TotalOrderAmount, 0) as TotalNetAmount ,          
     ISNULL(@SippingCharge, 0) as ShippingCharge          
        FROM #OrderProducts;            
  --Summary end            
    END;            
          
 --select * from [Order] where OrderID = 474


GO

/* ============================================================
   Procedure: [dbo].[usp_es_GetOrderListByCustomerId]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- usp_es_GetOrderListByCustomerId 1      
-- usp_es_GetOrderListByCustomerId 353      
CREATE   PROCEDURE usp_es_GetOrderListByCustomerId 
	@CustomerId BIGINT, 
	@PageNo     BIGINT = 1, 
	@PageSize   BIGINT = 10
AS
    BEGIN
        SELECT *
        FROM
        (
            SELECT DISTINCT 
                   o.OrderID, 
                   o.OrderDate, 
                   o.DeliveryDate, 
                   o.ShippingDate, 
                   o.DispatchedDate, 
                   o.CancelOrder, 
                   o.TotalAmount,          
                   --p.ProductID, p.Name as [ProductName], p.ImageURL, p.Return_days, od.Variant as VariantValue, vd.Variant_Name,          
                   0 AS ProductID, 
                   '' AS [ProductName], 
                   '' AS ImageURL, 
                   0 AS Return_days, 
                   '' AS Variant, 
                   '' AS VariantValue, 
                   '' AS Variant_Name,
				   o.fulfillmentdetails,
                   dbo.ufn_es_GetOrderProductJson(o.OrderID) AS [ProductJson], 
                   o.User_ID, 
                   dbo.udf_es_GetShipingPersonName(o.ShippingID) AS [FullName], 
                   (CASE
                        WHEN ISNULL(eor.ReturnId, 0) > 0
                        THEN 'Refund and Exchange Message goes here'
                        ELSE CASE
                                 WHEN o.CancelOrder = 1
                                 THEN 'This order is canceled.'
                                 WHEN o.Deliver = 1
                                 THEN 'Order is Delivered on ' + CONVERT(NVARCHAR(12), o.DeliveryDate, 106)
                                 WHEN o.Shipped = 1
                                 THEN 'Order is shipped on ' + CONVERT(NVARCHAR(12), o.ShippingDate, 106)
                                 WHEN o.DIspatched = 1
                                 THEN 'Order is dispatchned on ' + CONVERT(NVARCHAR(12), o.DispatchedDate, 106)
                                 ELSE 'Your order is placed on' + CONVERT(NVARCHAR(12), o.OrderDate, 106)
                             END
                    END) AS [OrderStatus], 
                   o.PaymentDetails AS [PaymentStatus], 
                   o.OrderNo,
				   inv.AppliedCouponCode,
				   inv.AppliedCouponJSON,
				   o.Discount,
				   o.Taxes
            FROM [Order](NOLOCK) o           
                 --inner join [OrderDetails] od on o.OrderID = od.OrderID          
                 --inner join [Products] p on od.ProductID = p.ProductID          
                 --left join Variant_detail vd on o.User_ID= vd.User_ID and od.Variant = vd.Variant and p.Name = vd.PRODUCTNAME         
                 LEFT JOIN eshop_Order_Return eor ON o.OrderId = eor.OrderID
                 LEFT JOIN eshop_Order_Return_Stage eors ON eor.ReturnId = eors.ReturnID
				 LEFT JOIN tbl_es_InvoiceDetail inv on o.OrderID = inv.OrderID
            WHERE o.CustomerID = @CustomerId
        ) T
        WHERE T.[ProductJson] IS NOT NULL
        ORDER BY T.OrderID DESC
        --OFFSET((@PageNo - 1) * @PageSize) ROWS FETCH NEXT @PageSize ROWS ONLY;
    END;




GO

