/* ============================================================
   Procedure: [dbo].[usp_es_GetProductByProductId]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

  
-- exec usp_es_GetProductByProductId 1 
  
CREATE   PROCEDURE usp_es_GetProductByProductId 
@ProductId bigint
as  
begin  
	declare @CategoryId bigint  = 0, @UserId bigint = 0;

	select @CategoryId = CategoryID, @UserId = User_ID from Products(nolock) where ProductID = @ProductId


 --Getting Product Table[0]  
 select ProductID, Name, SupplierID, CategoryID, SubCategoryID, QuantityPerUnit, UnitPrice, OldPrice, UnitWeight, Size, Discount, UnitInStock, UnitOnOrder, ProductAvailable, COALESCE(ImageURL, Picture1, Picture2, Picture3, Picture4, Picture5) as ImageURL,
 AltText, AddBadge, OfferTitle, OfferBadgeClass, ShortDescription, LongDescription, Picture1, Picture2, Picture3, Picture4, Note, StockKeepingUnit, Picture5, Barcode, HarmonizedSystemCode, PointofSale, PublicationStartDate, Country_Name, User_ID, CreatedDate, Video, ImageURL_T, ImageURL_L, Picture1_T, Picture1_L, Picture2_L, Picture2_T, Picture3_T, Picture3_L, Picture4_L, Picture4_T, Picture5_T, Picture5_L, Return_days, Exchange_days, Shipped_days, TaxName1,TaxName2, TaxName3, Tax1, Tax3, Tax2, isActive, 
TotalSell, TotalReturn, Totalwish, SortOrder, CategoryName, TotalPrice, Title, Meta_description, Meta_Tags, PageName, ReOrderLevel, minorderquantity, maxorderquantity from Products where ProductID = @ProductId  
   
 --Getting multimedia content Table[1]  
 select * from (  
  select 'image' as [key], ImageURL as [value] from Products where ProductID = @ProductId  
  union  
  select 'image' as [key], Picture1  as [value]from Products where ProductID = @ProductId  
  union  
  select  'image' as [key], Picture2 as [value] from Products where ProductID = @ProductId  
  union  
  select 'image' as [key], Picture3 as [value]  from Products where ProductID = @ProductId  
  union  
  select 'image' as [key], Picture4 as [value] from Products where ProductID = @ProductId  
  union  
  select 'image' as [key], Picture5 as [value] from Products where ProductID = @ProductId  
  union  
  select 'video' as [key], Video as [value] from Products where ProductID = @ProductId  
 ) iv where [value] <> '' and  [value]  is not null  
  
 --Getting default setting Table[2]  
 select top 1 * from default_setting where User_ID = @UserId order by id desc  
  
 --Getting RelatedProduct Table[3]  
 select Top 10 p.Name , p.ProductID , COALESCE(p.ImageURL, p.Picture1, p.Picture2, p.Picture3, p.Picture4, p.Picture5) as ImageURL , p.AltText , p.OldPrice , p.TotalPrice, Count(*) over (order by p.ProductID ) as [NoOfRecod], Count(*) over (order by p.User_ID ) as [TotalResult], p.User_ID from Products p where CategoryID= @CategoryId  order by ProductID desc  
  
 --Getting Product Reviews  Table[4]  
 select * from Review where ProductID = @ProductId  and isDelete = 0  
  
end  
  


GO

/* ============================================================
   Procedure: [dbo].[usp_es_GetProductByProductName]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


-- exec usp_es_GetProductByProductName '#ProductTitle#', 27983

CREATE   PROCEDURE usp_es_GetProductByProductName
@ProductName nvarchar(max),
@UserId bigint
as
begin
	declare @ProductId bigint = 0, @CategoryId bigint = 0;

	if(exists( select 1 from Products where [name]  = @ProductName and User_ID = @UserId))
	begin
		select @ProductId = ProductID, @CategoryId = CategoryID from Products where [name]  = @ProductName and User_ID = @UserId
	end
	else if(exists( select 1 from Products where PageName  = @ProductName and User_ID = @UserId))
	begin
		select @ProductId = ProductID, @CategoryId = CategoryID from Products where PageName  = @ProductName and User_ID = @UserId
	end
	else if(exists( select 1 from Products where AltText  = @ProductName and User_ID = @UserId))
	begin
		select @ProductId = ProductID, @CategoryId = CategoryID from Products where AltText  = @ProductName and User_ID = @UserId
	end
	else if(exists( select 1 from Products where ProductID  =  ISNULL(TRY_PARSE(@ProductName as bigint), 0) and User_ID = @UserId))
	begin
		select @ProductId = ProductID, @CategoryId = CategoryID from Products where PageName  = ISNULL(TRY_PARSE(@ProductName as bigint), 0) and User_ID = @UserId
	end

	--Getting Product Table[0]
	select ProductID, Name, SupplierID, CategoryID, SubCategoryID, QuantityPerUnit, UnitPrice, OldPrice, UnitWeight, Size, Discount, UnitInStock, UnitOnOrder, ProductAvailable, COALESCE(ImageURL, Picture1, Picture2, Picture3, Picture4, Picture5) as ImageURL, AltText, AddBadge, OfferTitle, OfferBadgeClass, ShortDescription, LongDescription, Picture1, Picture2, Picture3, Picture4, Note, StockKeepingUnit, Picture5, Barcode, HarmonizedSystemCode, PointofSale, PublicationStartDate, Country_Name, User_ID, CreatedDate, Video, ImageURL_T, ImageURL_L, Picture1_T, Picture1_L, Picture2_L, Picture2_T, Picture3_T, Picture3_L, Picture4_L, Picture4_T, Picture5_T, Picture5_L, Return_days, Exchange_days, Shipped_days, TaxName1,TaxName2, TaxName3, Tax1, Tax3, Tax2, isActive, TotalSell, TotalReturn, Totalwish, SortOrder, CategoryName, TotalPrice, Title, Meta_description, Meta_Tags, PageName, ReOrderLevel, minorderquantity, maxorderquantity from Products where ProductID = @ProductId
	
	--Getting multimedia content Table[1]
	select * from (
		select 'image' as [key], ImageURL as [value] from Products where ProductID = @ProductId
		union
		select 'image' as [key], Picture1  as [value]from Products where ProductID = @ProductId
		union
		select  'image' as [key], Picture2 as [value] from Products where ProductID = @ProductId
		union
		select 'image' as [key], Picture3 as [value]  from Products where ProductID = @ProductId
		union
		select 'image' as [key], Picture4 as [value] from Products where ProductID = @ProductId
		union
		select 'image' as [key], Picture5 as [value] from Products where ProductID = @ProductId
		union
		select 'video' as [key], Video as [value] from Products where ProductID = @ProductId
	) iv where [value] <> '' and  [value]  is not null

	--Getting default setting Table[2]
	select top 1 * from default_setting where User_ID = @UserId order by id desc

	--Getting RelatedProduct Table[3]
	select Top 10 p.Name , p.ProductID , COALESCE(p.ImageURL, p.Picture1, p.Picture2, p.Picture3, p.Picture4, p.Picture5) as ImageURL , p.AltText , p.OldPrice , p.TotalPrice, Count(*) over (order by p.ProductID ) as [NoOfRecod], Count(*) over (order by p.User_ID ) as [TotalResult], p.User_ID from Products p where CategoryID= @CategoryId and p.ProductID <> @ProductId order by ProductID desc

	--Getting Product Reviews  Table[4]
	select * from Review where ProductID = @ProductId  and isDelete = 0

end





GO

/* ============================================================
   Procedure: [dbo].[usp_es_GetProductList]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON



-- EXEC usp_es_GetProductList 'localhost', 'pipes' , NULL , 0 , 9999999 , '', 20, 1;      
--GO      
      
CREATE   PROCEDURE usp_es_GetProductList       
    @HostName     NVARCHAR(1000),       
	@ProductName  NVARCHAR(1000)  = '',
    @CategoryName NVARCHAR(1000)  = null,       
    @StartPrice   DECIMAL(18 , 2)  ,       
    @EndPrice     DECIMAL(18 , 2) ,       
    @SortBy       NVARCHAR(500) ,       
    @PageSize     INT,       
    @PageNo       INT      
AS      
    BEGIN      
        DECLARE @UserId BIGINT;      
        SELECT @UserId = User_Id FROM eshop_client_domain      
        WHERE Domain = @HostName;      
        DECLARE @SqlQuery NVARCHAR(MAX)= N'SELECT p.Name , p.ProductID , COALESCE(p.ImageURL, p.Picture1, p.Picture2, p.Picture3, p.Picture4, p.Picture5) as ImageURL, p.AltText , p.OldPrice , p.TotalPrice, Count(*) over (order by p.ProductID ) as [NoOfRecod], Count(*) over (order by p.User_ID ) as [TotalResult], p.User_ID  FROM Products AS p INNER JOIN Categories AS c ON p.CategoryID = c.CategoryID WHERE p.User_ID = ' + CAST(@UserId AS VARCHAR);      
        IF ( ISNULL(@CategoryName , '') <> '' )       
            BEGIN      
                SET @SqlQuery = @SqlQuery + ' and c.Name in (' + dbo.udf_es_GetCategoryNameInCsv(@CategoryName,  @UserId) + ')';      
        END;      
      
		IF(ISNULL(@ProductName, '') <> '')
		BEGIN
			SET @SqlQuery = @SqlQuery + ' and p.Name like ''%' + @ProductName + '%''';           
		END

        IF ( @EndPrice > @StartPrice )       
            BEGIN      
                SET @SqlQuery = @SqlQuery + ' and p.TotalPrice BETWEEN ' + CAST(@StartPrice AS VARCHAR) + ' and ' + CAST(@EndPrice AS VARCHAR);      
        END;
		
		
              
  IF(@PageSize <> 0 AND @PageNo <> 0)      
  BEGIN      
   SELECT @SqlQuery = CASE WHEN @SortBy = 'newest'      
        THEN @SqlQuery + '  order by p.CreatedDate desc '      
       WHEN @SortBy = 'oldest'      
        THEN @SqlQuery + ' order by p.CreatedDate asc '      
       ELSE      
        @SqlQuery + ' order by p.ProductID asc '      
       END      
   SET @SqlQuery = @SqlQuery + ' OFFSET ' + CAST((@PageSize * (@PageNo-1)) AS nvarchar) + ' ROWS FETCH NEXT ' + CAST(@PageSize AS NVARCHAR) +' ROW ONLY '      
      
  END      
      
  print @SqlQuery      
      
  EXECUTE sp_executesql @SqlQuery;      
      
      
    END; 


GO

/* ============================================================
   Procedure: [dbo].[usp_es_GetRedeemablePoints]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


-- Exec usp_es_GetRedeemablePoints 'kit19@pelsoftlabs.in',37540
CREATE   PROC usp_es_GetRedeemablePoints
(
	@UserName varchar(50),
	@UserId bigint
)
As
Begin
	-- declare @UserName varchar(50)='ajitajitk6071@gmail.com',@UserId bigint=37540
	-- declare @UserName varchar(50)='kit19@pelsoftlabs.in',@UserId bigint=37540
	-- declare @UserName varchar(50)='kumar@kit19.com',@UserId bigint=37540
	Declare @TotalAmount numeric(18,2)=0, @Points int=0, @Percentage numeric(18,2)=0, @FreebeeProducts nvarchar(max)='',
			@IsUserSelected bit=0, @PointsBalance bigint=0, @CustomerID bigint=0, @OfferredPoints bigint=0,
			@EquivalentPoints int=0, @EquivalentCurrency int=0

	If exists (Select * From eshop_cart_items(nolock) Where User_ID=@UserId and UserName=@UserName)    
	Begin
		print 'Cart Exists'
		Select @CustomerID=CustomerID From Customers(nolock) Where UserName=@UserName and User_ID=@UserId
		
		Select @TotalAmount=Sum(TotalAmount) 
		From eshop_cart_items(nolock) 
		Where User_ID=@UserId and UserName=@UserName
		    
		select top 1 @Points=Points, @Percentage=[Percentage], @FreebeeProducts=FreebeeProducts,@IsUserSelected=IsUserSelected
		from eshop_redemptionsettings(nolock) 
		Where ParentId=@UserId and IsActive=1 
		Order by RuleSequence

		SELECT top 1 @PointsBalance=[PointsBalance]
		FROM [dbo].[eshop_rewardsmapping](nolock)
		Where [CustomerId]=@CustomerID
		order by id desc

		Select @EquivalentPoints=EquivalentQuantity, @EquivalentCurrency=EquivalentCurrency 
		From tbl_es_LoyaltyGlobalSetting(nolock) 
		Where User_ID=@UserId

		If(@Percentage > 0)
		Begin
			Select @OfferredPoints = round(@TotalAmount * @Percentage * 0.01, 0)
		End
		Else
		Begin
			Set @OfferredPoints = @Points
		End

		print '@CustomerID: ' + cast(@CustomerID as varchar)
		print '@TotalAmount: ' + cast(@TotalAmount as varchar)
		print '@Points: ' + cast(@Points as varchar)
		print '@Percentage: ' + cast(@Percentage as varchar)
		print '@FreebeeProducts: ' + @FreebeeProducts
		print '@IsUserSelected: ' + cast(@IsUserSelected as varchar)
		print '@PointsBalance: ' + cast(@PointsBalance as varchar)
		print '@OfferredPoints: ' + cast(@OfferredPoints as varchar)


		Select AvailablePoints=case when @OfferredPoints > @PointsBalance then @PointsBalance else @OfferredPoints end,
			   isnull((SELECT STUFF( (SELECT N', ' + [ss].[Name] + '|' + cast([ss].[ProductID] as varchar)
			FROM [Products](nolock) AS [ss] INNER JOIN [dbo].[fn_Split](@FreebeeProducts, ',') AS [fs]
			ON [ss].[ProductID] = [fs].[value] FOR XML PATH(''), TYPE
			).value('text()[1]', 'nvarchar(max)'), 1, 2, N'')
			), '') AS [FreebeeProducts],
			@EquivalentPoints as EquivalentPoints, @EquivalentCurrency as EquivalentCurrency

	End

End



GO

