CREATE   PROCEDURE usp_es_GetReturnProductInfo @OrderId   BIGINT, 
                                             @ProductId BIGINT
AS
    BEGIN
        SELECT o.OrderID, 
               od.ProductID, 
               od.ProductName, 
               od.UnitPrice, 
               od.TotalAmount, 
               od.Quantity, 
               COALESCE(p.ImageURL, p.Picture1_T, p.Picture2_T, p.Picture3_T, p.Picture4_T, p.Picture5_T) AS ImageURL,
			   o.User_ID,
			   o.OrderNo
        FROM [Order] o
             INNER JOIN OrderDetails od ON o.OrderId = od.OrderID
             INNER JOIN Products p ON od.ProductID = p.ProductID
        WHERE o.OrderID = @OrderId
              AND od.ProductID = @ProductId;
    END;


