/* ============================================================
   Procedure: [dbo].[usp_es_GetSetCustomerBankDetails]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- exec usp_es_GetSetCustomerBankDetails @CustomerId=2,@AccountHolderName=N'',@AccountNo=N'',@BankName=N'',@BankBranch=N'',@BranchAddress=N'',@IFSCCode=N'',@UserId=default,@Mode=N'Get'
-- exec usp_es_GetSetCustomerBankDetails @OrderId=194,@CustomerId=128,@AccountHolderName=N'abcd',@AccountNo=N'76667535877',@BankName=N'sbi',@BankBranch=N'vikaspuri',@BranchAddress=N'pvr complex',@IFSCCode=N'sbin9876v',@UserId=33097,@Mode=N'Set'
CREATE   PROC usp_es_GetSetCustomerBankDetails
(
	@OrderId int=0,
	@CustomerId int=0,
	@AccountHolderName varchar(200)='',
	@AccountNo varchar(50)='',
	@BankName varchar(200)='',
	@BankBranch varchar(200)='',
	@BranchAddress varchar(500)='',
	@IFSCCode varchar(500)='',
	@UserId bigint=0,
	@Mode varchar(3)='Get' --'Set'
)
as
Begin
	If(@Mode = 'Get')
	Begin
		If(@OrderId=0)
		Begin
			Select top 1 * From tbl_es_CustomerBankDetails Where CustomerId=@CustomerId order by CBDet_Id desc
		End
		Else
		Begin
			Select	* 
			From	tbl_es_CustomerBankDetails CBD inner join tbl_es_OrderCustomerBankDetailsMapping OCBDMap
			On		CBD.CBDet_Id=OCBDMap.CBDet_Id
			Where	CBD.CustomerId=@CustomerId and OCBDMap.OrderId=@OrderId
		End
	End
	Else
	Begin
		declare @CBDet_Id int=0
		
		Select @CBDet_Id=CBDet_Id From tbl_es_CustomerBankDetails Where CustomerId=@CustomerId and AccountHolderName=@AccountHolderName and AccountNo=@AccountNo and BankName=@BankName and BankBranch=@BankBranch and BranchAddress=@BranchAddress and IFSCCode=@IFSCCode

		If(@CBDet_Id=0)
		Begin
			Insert into tbl_es_CustomerBankDetails(CustomerId,AccountHolderName,AccountNo,BankName,BankBranch,BranchAddress,IFSCCode,CreatedBy,CreatedDate)
			Values(@CustomerId,@AccountHolderName,@AccountNo,@BankName,@BankBranch,@BranchAddress,@IFSCCode,@UserId,getdate())
			
			Select @CBDet_Id=SCOPE_IDENTITY()
		End

		If (@CBDet_Id > 0 and @OrderId > 0)
		Begin
			insert into tbl_es_OrderCustomerBankDetailsMapping(OrderId,CBDet_Id,CreatedBy,CreatedDate)
			values(@OrderId,@CBDet_Id,@UserId,GETDATE())

			Select @CBDet_Id as CBDet_Id
		End

	End
End



GO

/* ============================================================
   Procedure: [dbo].[usp_es_GetSetShippingCharges]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

    
-- Exec usp_es_GetSetShippingCharges @UserId=335  
CREATE   PROC usp_es_GetSetShippingCharges
(  
    @ShippingId int,
	@UserId bigint=0,
	@ShippingAmt numeric(18,2)=0,
	@Mode varchar(10)='Get'
)  
As  
BEGIN  

	If(@Mode = 'Get')  
	Begin
		Select isnull(Amount,0) as Amount From tbl_es_ShippingCharges Where Shipping_Id=@ShippingId
	End

	If(@Mode = 'Add')  
	Begin
		Insert into tbl_es_ShippingCharges(Shipping_Id,Amount,CreatedBy,CreatedDate)
		Values(@ShippingId,@ShippingAmt,@UserId,Getdate())

		Select SCOPE_IDENTITY()
	End

	If(@Mode = 'Edit')  
	Begin
		Update tbl_es_ShippingCharges set Amount=@ShippingAmt, ModifiedBy=@UserId,ModifiedDate=Getdate()
		Where Shipping_Id=@ShippingId

		Select @@ROWCOUNT
	End
  
END  



GO

/* ============================================================
   Procedure: [dbo].[usp_es_GetSetStoreAddress]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


--exec usp_es_GetSetStoreAddress @UserId = 33097
--go


CREATE   PROCEDURE usp_es_GetSetStoreAddress
	@UserId bigint,
	@LegalName nvarchar(255) = null,
	@FirstName nvarchar(255)  = null,
	@LastName nvarchar(255) = null,
	@GstNumber nvarchar(15) = null,
	@PanNumber nvarchar(10) = null,
	@Mobile nvarchar(12) = null,
	@Address nvarchar(255) = null,
	@CountryName nvarchar(255) = null,
	@StateName nvarchar(255) = null,
	@CityName nvarchar(255) = null,
	@PinCode nvarchar(10) = null,
	@Mode nvarchar(5) = 'GET'
as
begin
	IF(@Mode = 'GET')
	begin
		select
			esa.User_ID as UserId,
			esa.Legalname as LegalName,
			esa.FirstName,
			esa.LastName,
			emd.GSTNo as GstNumber,
			emd.PANNo as PanNumber,
			esa.Mobile,
			emd.FullAddress as [Address],
			esa.Country_Name as CountryName,
			esa.State_Name as StateName,
			esa.City_Name as CityName,
			emd.PinCode
			from eshop_store_address esa
				left join tbl_es_MiscellaneousDetail emd on esa.User_ID = emd.User_ID
	end
	IF(@Mode = 'SET')
	begin
		IF(NOT EXISTS(SELECT 1 FROM eshop_store_address where User_ID = @UserId))
			BEGIN
				insert into eshop_store_address (Legalname, FirstName, LastName, Mobile, Country_Name, State_Name, City_Name, User_ID)
					values (@LegalName, @FirstName, @LastName, @Mobile, @CountryName, @StateName, @CityName, @UserId)
			END
		ELSE
			BEGIN
				update eshop_store_address set
					Legalname = iif(isnull(@LegalName, '')='', Legalname, @LegalName),
					FirstName = iif(isnull(@FirstName, '')='', FirstName, @FirstName),
					LastName = iif(isnull(@LastName, '')='', LastName, @LastName),
					Mobile = iif(isnull(@Mobile, '')='', Mobile, @Mobile),
					Country_Name = iif(isnull(@CountryName, '')='', Country_Name, @CountryName),
					State_Name = iif(isnull(@StateName, '')='', State_Name, @StateName),
					City_Name = iif(isnull(@CityName, '')='', City_Name, @CityName)
						where User_ID = @UserId
			END
		if(not exists(select 1 from tbl_es_MiscellaneousDetail where User_ID = @UserId))
			begin
				insert into tbl_es_MiscellaneousDetail ( User_ID, CreatedOn, UpdatedOn, GSTNo, PANNo, FullAddress, PinCode)
					values(@UserId, getdate(), getdate(), @GstNumber, @PanNumber, @Address, @PinCode)
			end
		else
			begin
				update tbl_es_MiscellaneousDetail set
					UpdatedOn = GETDATE(),
					GSTNo = iif(isnull(@GstNumber, '')='', GSTNo, @GstNumber),
					PANNo = iif(isnull(@PanNumber, '')='', PANNo, @PanNumber),
					FullAddress = iif(isnull(@Address, '')='', FullAddress, @Address),
					PinCode = iif(isnull(@PinCode, '')='', PinCode, @PinCode)
						where User_ID = @UserId
			end
	end
end



GO

