CREATE   PROCEDURE usp_es_GetThemeAndPageSectionByName    
 @DomainName nvarchar(255),    
 @PageName nvarchar(50) = ''    
as    
begin    
 -- declare @DomainName nvarchar(255) = 'localhost', @PageName nvarchar(50) = 'Home'    
    
 DECLARE @UserId bigint = 0;          
 SELECT @UserId = User_Id FROM eshop_client_domain WHERE Domain = @DomainName    

 print @UserId
    
 SELECT * FROM tbl_es_PageTheme WHERE User_Id = @UserId and IsActive = 1    ;     
    
 select PSD.*  from tbl_es_PageSectionDetail(nolock) PSD inner join tbl_es_PageTheme(nolock) PT      
  on  PSD.Page_Id=PT.Page_Id      
  where PSD.IsActive=1 and PSD.user_id=@UserId and SectionCode = 1.00 and PT.PageName = 'Home'    
 union    
 select PSD.*  from tbl_es_PageSectionDetail(nolock) PSD inner join tbl_es_PageTheme(nolock) PT      
  on  PSD.Page_Id=PT.Page_Id      
  where PSD.IsActive=1 and PSD.user_id=@UserId and PT.PageName=@PageName --and PT.Theme=@Theme     
    
select * from Categories where User_ID = @UserId and IsPublished = 1 and isActive = 1          
   order by SortOrder asc  ;     
    
select id as CollectionId, [Name] as CollectionName, [description] as [Description]      
 FROM [collection](nolock)  where User_ID = @UserId and isactive = 1  order by SortOrder asc;      
      
         
   -- StoreInformation start        
           
  SELECT  top 1        
   ud.FName + ' ' + ud.LName as FullName,        
   COALESCE(sd.Storename, ud.CompnayName, ud.FName) as CompanyName,        
   gl.LogoUrl,         
   LTRIM(RTRIM(CONCAT(        
    --Address        
    IIF(ISNULL(md.FullAddress, '') = '', '',  ' ' + md.FullAddress),        
     --City        
     IIF(ISNULL(md.FullAddress, '') = '', '',  ' ' + sa.City_Name),        
      --State        
      IIF(ISNULL(sa.City_Name, '') = '', '',  ', ' + sa.State_Name),         
       --Country        
       IIF(ISNULL(sa.State_Name, '') = '', '',  ', ' + sa.Country_Name),        
        --Pincode        
        IIF(ISNULL(null, '') = '', '',  ' ' + '')        
   ))) as FullAddress,        
        
   sa.Country_Name as CountryName,        
   sa.State_Name as StateName,        
   sa.City_Name as CityName,        
   sa.Mobile as MobileNo,        
   sd.Storename,        
   ud.Email,        
   md.GSTNo,        
   md.PANNo,        
   ud.User_ID as UserId        
   FROM  User_Detail ud         
    Left JOIN eshop_store_address(nolock) sa on sa.User_ID = ud.User_ID             
     Left JOIN eshop_store_details(nolock) sd on sd.User_ID = ud.User_ID             
     Left JOIN genlogo gl(nolock) on ud.User_ID = gl.User_ID and gl.isDeleted = 0        
     LEFT JOIN tbl_es_MiscellaneousDetail(nolock) md on sd.User_ID = ud.User_ID        
   WHERE ud.User_ID = @UserId        
  --StoreInformation end        
        
      
end 



