-- exec usp_es_GetVariantNameValueListByCategoryId 1
CREATE   PROCEDURE usp_es_GetVariantNameValueListByCategoryId
@CategoryId bigint
as
begin
	SELECT DISTINCT NAME AS VariantName ,  Ltrim(Rtrim(UPPER(V_VALUE))) AS VariantValue
			FROM VARIANTS(NOLOCK)
			WHERE PRODUCTNAME IN ( 
				SELECT Name
				FROM Products(NOLOCK)
				WHERE CategoryID = @CategoryId
			) ORDER BY VariantName
end



