CREATE   PROCEDURE usp_es_GetVariantsByProductName  
 @HostName nvarchar(1000),  
 @ProductName nvarchar(1000)  
AS  
BEGIN  
 --declare @HostName nvarchar(1000) = 'localhost'   
 --declare @ProductName nvarchar(1000) = 'Bellies For Women'   
  
 declare @UserId numeric = 0;  

 select @UserId = User_Id from eshop_client_domain where Domain = @HostName  
  
 declare @TaxRate numeric(18,2);

 set @TaxRate = ( select COALESCE(Tax1, Tax2, Tax3)  FROM Products where User_ID = @UserId and Name  = @ProductName  )

 select ID, PRODUCTNAME, NAME, V_VALUE,	 CONVERT(numeric(18,2), (PRICE + (PRICE * @TaxRate / 100))) AS PRICE, StockKeepingUnit, INVENTORY, Barcode, User_ID,Date_Modified from VARIANTS where User_ID = @UserId and PRODUCTNAME  = @ProductName  

END  


