/* ============================================================
   Procedure: [dbo].[usp_es_InsertCustomerSignUpData]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

  
      
CREATE   PROCEDURE usp_es_InsertCustomerSignUpData      
(      
 @FirstName nvarchar(255),      
 @LastName nvarchar(255),      
 @Username nvarchar(255),      
 @Password nvarchar(255),      
 @Email nvarchar(255),      
 @Mobile nvarchar(255),      
 @DomainName nvarchar(1000),  
 @CountryShortName nvarchar(3)  
)      
as      
begin      
 declare @User_ID bigint = 0;      
      
 select @User_ID = User_Id from eshop_client_domain where Domain = @DomainName      
      
 IF( EXISTS (       
   SELECT * from (       
    SELECT UserName   from  Customers WHERE User_ID = @User_ID        
     UNION        
    SELECT User_Login from User_Detail UD INNER JOIN eshop_client_domain ECD on UD.User_ID = ECD.User_Id       
  ) un WHERE Username =  @Username))      
      
 BEGIN      
  SELECT '0' AS [StatusCode], 'Username already exists' AS [Message];      
  RETURN      
 END      
      
 IF(EXISTS (SELECT * FROM Customers WHERE User_ID = @User_ID and Email = @Email))      
 BEGIN      
  SELECT '0' AS [StatusCode], 'Email already exists' AS [Message];      
  RETURN      
 END      
      
 IF(EXISTS (SELECT * FROM Customers WHERE User_ID = @User_ID and Mobile1 = @Mobile))      
 BEGIN      
  SELECT '0' AS [StatusCode], 'Mobile No. already exists' AS [Message];      
  RETURN      
 END      
  
 declare @CountryName nvarchar(max) = null  
 select @CountryName = Country_Name from m_country1 where Shortname = @CountryShortName  
  
      
 INSERT INTO Customers (First_Name, Last_Name, UserName, [Password], Email, Mobile1, User_ID, Country_Name)      
	VALUES (@FirstName, @LastName, @Username, @Password, @Email, @Mobile, @User_Id, @CountryName)      
      
 SELECT '1' AS [StatusCode], 'User registered successfully.' AS [Message];      
    
	exec eshop_insert_customer_lead @FirstName, @LastName, @Email, @Mobile, @User_ID, @Username

END


GO

/* ============================================================
   Procedure: [dbo].[usp_es_IsSignUpDataExists]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

  
-- EXEC usp_es_IsSignUpDataExists 'sandeepydv', 36647, 'username'  
CREATE   PROCEDURE usp_es_IsSignUpDataExists  
@FilterText nvarchar(max),  
@UserId BIGINT,  
@Mode nvarchar(20) = 'username'  
as  
begin  
 IF(@Mode = 'username')  
  BEGIN  
   IF (EXISTS (  
    SELECT * FROM ( select UserName   from  Customers WHERE User_ID = @UserId  
     union  
     select User_Login from User_Detail -- UD INNER JOIN eshop_client_domain ECD on UD.User_ID = ECD.User_Id   
    ) A  
     WHERE A.UserName = @FilterText ))  
    BEGIN  
     SELECT 1  
    END  
   ELSE  
    BEGIN  
     SELECT 0  
    END  
  END  
  
 IF(@Mode = 'mobile1')  
  BEGIN  
   IF (EXISTS ( select UserName   from  Customers WHERE User_ID = @UserId and Mobile1 = @FilterText))  
    BEGIN  
     SELECT 1  
    END  
   ELSE  
    BEGIN  
     SELECT 0  
    END  
  END  
  
 IF(@Mode = 'email')  
  BEGIN  
   IF (EXISTS ( select UserName   from  Customers WHERE User_ID = @UserId and Email = @FilterText))  
    BEGIN  
     SELECT 1  
    END  
   ELSE  
    BEGIN  
     SELECT 0  
    END  
  END  
END  


