/* ============================================================
   Procedure: [dbo].[usp_es_job_ProcessLoyaltyTx]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC usp_es_job_ProcessLoyaltyTx
As
Begin
	
	Declare	@Sno int=1,@RowID bigint,@OrderID bigint,@EventID bigint,@RewardMapId bigint,@User_ID bigint,@RecCnt int,@DeliveryDate datetime


	create table #tbl_ProcessLoyaltyTx
	(
		Sno			int identity(1,1),
		RowID		bigint,
		OrderID		bigint,
		EventID		bigint,
		RewardMapId	bigint,
		User_ID		bigint
	)


	If exists (select * from tbl_es_ProcessLoyaltyTransaction(nolock) where IsProcessed=0)
	Begin
		insert into	#tbl_ProcessLoyaltyTx
		select RowID, OrderID, EventID, RewardMapId, User_ID
		from tbl_es_ProcessLoyaltyTransaction(nolock) where IsProcessed=0

		Select @RecCnt=count(*) From #tbl_ProcessLoyaltyTx

		While @Sno <= @RecCnt
		Begin
			select @RowID=RowID, @OrderID=OrderID, @EventID=EventID, @RewardMapId=RewardMapId, @User_ID=User_ID
			from #tbl_ProcessLoyaltyTx
			where Sno=@Sno

			If exists (Select * From [Order](nolock) Where OrderID=@OrderID and DeliveryDate is not null and PaymentDetails='Paid')
			Begin
				Select @DeliveryDate=DeliveryDate
				From [Order](nolock)
				Where OrderID=@OrderID and DeliveryDate is not null and PaymentDetails='Paid'

				Select @DeliveryDate=max(DateAdd(dd,P.Return_Days,@DeliveryDate))
				From [OrderDetails](nolock) OD inner join Products(nolock) P
				On	 OD.ProductID=P.ProductID
				Where OrderID=@OrderID and CancelOrder=0 and ISNULL(ReturnOrder,0)=0

				If(GETDATE() > @DeliveryDate)
				Begin
					Update eshop_rewardsmapping Set TxStatus='Active' Where ID=@RewardMapId
					Update tbl_es_ProcessLoyaltyTransaction Set IsProcessed=1, ProcessedOn=GETDATE() Where RowID=@RowID
				End

			End

			Set @Sno=@Sno+1
		End
	End

End



GO

