CREATE   PROC usp_es_LoadPageTheme
(  
	@UserId bigint,
	@Page	varchar(100),
	@Theme	varchar(100)
)
AS
Begin
	declare @Page_Id int

	select * from tbl_es_PageTheme(nolock) where user_id=@UserId and PageName=@Page and Theme=@Theme
	
	--select * from tbl_es_PageSection(nolock) where user_id=32198
	
