/* ============================================================
   Procedure: [dbo].[usp_es_NewsLetterSubscriber]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_es_NewsLetterSubscriber         
    @EmailId NVARCHAR(255) ,         
    @Stauts  BIT = 1,        
    @UserId  BIGINT        
AS        
BEGIN     
 declare @SubscriberId bigint  = 0;    
 select @SubscriberId = Id from tbl_es_NewsLetterSubscriber(nolock) where UserId = @UserId and EmailId = @EmailId;    
  declare @customerid bigint=0,@leadid bigint=0
  select @customerid=customerid,@leadid=LeadID from Customers(nolock) where User_ID=@userid and Email=@EmailId
 if(@SubscriberId = 0)    
  begin    
   insert into tbl_es_NewsLetterSubscriber ( EmailId , STATUS, UserId )    
    values ( @EmailId , @Stauts, @UserId );        
	select @SubscriberId=SCOPE_IDENTITY()
 select 1 as [Status], 'You have successfully subscribed to the Newsletter' as [Message]  
  end    
 else    
  begin    
 if(EXISTS(select Id from tbl_es_NewsLetterSubscriber where UserId = @UserId and EmailId = @EmailId and Status =@Stauts and @Stauts=1))    
  begin  
   update tbl_es_NewsLetterSubscriber set Status = @Stauts, UpdateOn = getdate() where Id = @SubscriberId   
   select 0 as [Status], 'Newsletter already subscribed' as [Message]  
  end  
  else if (EXISTS(select Id from tbl_es_NewsLetterSubscriber where UserId = @UserId and EmailId = @EmailId and @Stauts=0))
  begin    
  update tbl_es_NewsLetterSubscriber set Status = @Stauts, UpdateOn = getdate() where Id = @SubscriberId   
  select 0 as [Status], 'You are now unsubsribed from newsletters' as [Message]  
  end
 else  
  begin  
   update tbl_es_NewsLetterSubscriber set Status = @Stauts, UpdateOn = getdate() where Id = @SubscriberId   
   select 1 as [Status], 'You have successfully re-subscribed to the Newsletter' as [Message]  
    end  
  end   

       /*Start Lead Activity  Leads subscribes/unsubscribes newsletter  */    
  if @leadid>0
  begin
  declare @leadname nvarchar(100)=(select isnull(nullif(personname,''),'Lead No. '+cast(leadno as nvarchar)) from userleads(nolock) where id=@leadid)

    
   Begin try    
   declare @evntMessage nvarchar(max) = ''  ,@eventname nvarchar(100)   
   select @evntMessage = @leadname + ' has ' + case when @Stauts=1 then 'subscribed to ' else 'unsubscribed from ' end + ' eshop newsletters'
   select @eventname=case when @Stauts=1 then 'Lead subscribes to newsletter' else 'Lead unsubscribes from newsletter' end        
   exec UspSaveLeadActivity_withid @LeadID,@UserID,@UserId,@evntMessage, @eventname,'tbl_es_NewsLetterSubscriber',@SubscriberId
   end try    
   Begin catch    
     exec usp_insertErrorInfo    
   End Catch    
  
   /*End Lead Activity  subscribes/unsubscribes newsletter */    
  end

END; 




GO

/* ============================================================
   Procedure: [dbo].[usp_es_OrderActionsByMode]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


CREATE   PROC usp_es_OrderActionsByMode
(
	@UserId bigint=0,
	@FromDate varchar(20)='',
	@ToDate varchar(20)='',
	@FilterFlag varchar(100)='',
	@Mode varchar(50)='GetLatestOrdersDateRange'
)
As
Begin
	
	--declare @UserId bigint=33097, @FromDate varchar(20)='2020-06-01 00:00:00', @ToDate varchar(20)='2020-08-31 00:00:00', @FilterFlag varchar(100)='1', @Mode varchar(50)='GetSalesPerDayDateRange'
	--declare @UserId bigint=33097,	@FromDate datetime='2020-06-01 00:00:00',	@ToDate datetime='2020-08-31 00:00:00'
	--select * from [Order] where User_ID=@UserId and OrderDate between @FromDate and @ToDate

	If(@Mode = 'GetLatestOrdersDateRange')
	Begin
		exec sp_executesql N'SELECT TOP (5) 
    [Project1].[OrderID] AS [OrderID], 
    [Project1].[CustomerID] AS [CustomerID], 
    [Project1].[PaymentID] AS [PaymentID], 
    [Project1].[ShippingID] AS [ShippingID], 
    [Project1].[Discount] AS [Discount], 
    [Project1].[Taxes] AS [Taxes], 
    [Project1].[TotalAmount] AS [TotalAmount], 
    [Project1].[isCompleted] AS [isCompleted], 
    [Project1].[OrderDate] AS [OrderDate], 
    [Project1].[DIspatched] AS [DIspatched], 
    [Project1].[DispatchedDate] AS [DispatchedDate], 
    [Project1].[Shipped] AS [Shipped], 
    [Project1].[ShippingDate] AS [ShippingDate], 
    [Project1].[Deliver] AS [Deliver], 
    [Project1].[DeliveryDate] AS [DeliveryDate], 
    [Project1].[Notes] AS [Notes], 
    [Project1].[CancelOrder] AS [CancelOrder], 
    [Project1].[User_ID] AS [User_ID], 
    [Project1].[CustomerName] AS [CustomerName], 
    [Project1].[PaymentDetails] AS [PaymentDetails], 
    [Project1].[fulfillmentdetails] AS [fulfillmentdetails], 
    [Project1].[OrderNo] AS [OrderNo]
    FROM ( SELECT 
        [Extent1].[OrderID] AS [OrderID], 
        [Extent1].[CustomerID] AS [CustomerID], 
        [Extent1].[PaymentID] AS [PaymentID], 
        [Extent1].[ShippingID] AS [ShippingID], 
        [Extent1].[Discount] AS [Discount], 
        [Extent1].[Taxes] AS [Taxes], 
        [Extent1].[TotalAmount] AS [TotalAmount], 
        [Extent1].[isCompleted] AS [isCompleted], 
        [Extent1].[OrderDate] AS [OrderDate], 
        [Extent1].[DIspatched] AS [DIspatched], 
        [Extent1].[DispatchedDate] AS [DispatchedDate], 
        [Extent1].[Shipped] AS [Shipped], 
        [Extent1].[ShippingDate] AS [ShippingDate], 
        [Extent1].[Deliver] AS [Deliver], 
        [Extent1].[DeliveryDate] AS [DeliveryDate], 
        [Extent1].[Notes] AS [Notes], 
        [Extent1].[CancelOrder] AS [CancelOrder], 
        [Extent1].[User_ID] AS [User_ID], 
        [Extent1].[CustomerName] AS [CustomerName], 
        [Extent1].[PaymentDetails] AS [PaymentDetails], 
        [Extent1].[fulfillmentdetails] AS [fulfillmentdetails], 
        [Extent1].[OrderNo] AS [OrderNo]
        FROM [dbo].[Order] AS [Extent1]
        WHERE ([Extent1].[User_ID] = @p__linq__0) AND ([Extent1].[OrderDate] >= @p__linq__1) AND ([Extent1].[OrderDate] <= @p__linq__2)
    )  AS [Project1]
    ORDER BY [Project1].[OrderID] DESC',N'@p__linq__0 bigint,@p__linq__1 datetime2(7),@p__linq__2 datetime2(7)',@p__linq__0=@UserId,@p__linq__1=@FromDate,@p__linq__2=@ToDate
	End

	If(@Mode = 'CountTotalOrdersDateRange')
	Begin
		exec sp_executesql N'SELECT 
		[GroupBy1].[A1] AS [C1]
		FROM ( SELECT 
			COUNT(1) AS [A1]
			FROM [dbo].[Order] AS [Extent1]
			WHERE ([Extent1].[User_ID] = @p__linq__0) AND ([Extent1].[OrderDate] >= @p__linq__1) AND ([Extent1].[OrderDate] <= @p__linq__2)
		)  AS [GroupBy1]',N'@p__linq__0 bigint,@p__linq__1 datetime2(7),@p__linq__2 datetime2(7)',@p__linq__0=@UserId,@p__linq__1=@FromDate,@p__linq__2=@ToDate
	End

	If(@Mode = 'GetTotalOrdersDateRange')
	Begin
		exec sp_executesql N'SELECT *
			FROM [dbo].[Order] AS [Extent1]
			WHERE ([Extent1].[User_ID] = @p__linq__0) AND ([Extent1].[OrderDate] >= @p__linq__1) AND ([Extent1].[OrderDate] <= @p__linq__2)
		 Order By [Extent1].[OrderID] Desc',N'@p__linq__0 bigint,@p__linq__1 datetime2(7),@p__linq__2 datetime2(7)',@p__linq__0=@UserId,@p__linq__1=@FromDate,@p__linq__2=@ToDate
	End

	If(@Mode = 'GetByFulfillmentDateRange')
	Begin
		exec sp_executesql N'SELECT *
			FROM [dbo].[Order] AS [Extent1]
			WHERE ([Extent1].[User_ID] = @p__linq__0) AND ([Extent1].[OrderDate] >= @p__linq__1) AND ([Extent1].[OrderDate] <= @p__linq__2) AND ([Extent1].[fulfillmentdetails] = @p__linq__3)
		',N'@p__linq__0 bigint,@p__linq__1 datetime2(7),@p__linq__2 datetime2(7),@p__linq__3 varchar(100)',@p__linq__0=@UserId,@p__linq__1=@FromDate,@p__linq__2=@ToDate,@p__linq__3=@FilterFlag
	End

	If(@Mode = 'CountByFulfillmentDateRange')
	Begin
		exec sp_executesql N'SELECT 
		[GroupBy1].[A1] AS [C1]
		FROM ( SELECT 
			COUNT(1) AS [A1]
			FROM [dbo].[Order] AS [Extent1]
			WHERE ([Extent1].[User_ID] = @p__linq__0) AND ([Extent1].[OrderDate] >= @p__linq__1) AND ([Extent1].[OrderDate] <= @p__linq__2) AND ([Extent1].[fulfillmentdetails] = @p__linq__3)
		)  AS [GroupBy1]',N'@p__linq__0 bigint,@p__linq__1 datetime2(7),@p__linq__2 datetime2(7),@p__linq__3 varchar(100)',@p__linq__0=@UserId,@p__linq__1=@FromDate,@p__linq__2=@ToDate,@p__linq__3=@FilterFlag
	End

	If(@Mode = 'GetOrdersByPaymentStatusDateRange')
	Begin
		exec sp_executesql N'SELECT *
			FROM [dbo].[Order] AS [Extent1]
			WHERE ([Extent1].[OrderDate] >= @p__linq__0) AND ([Extent1].[OrderDate] <= @p__linq__1) AND ([Extent1].[PaymentDetails] = @p__linq__3) AND ([Extent1].[User_ID] = @p__linq__2)
		 Order By [Extent1].[OrderID] Desc',N'@p__linq__0 datetime2(7),@p__linq__1 datetime2(7),@p__linq__2 bigint,@p__linq__3 varchar(100)',@p__linq__0=@FromDate,@p__linq__1=@ToDate,@p__linq__2=@UserId,@p__linq__3=@FilterFlag
	End

	If(@Mode = 'CountByPaymentStatusDateRange')
	Begin
		exec sp_executesql N'SELECT 
		[GroupBy1].[A1] AS [C1]
		FROM ( SELECT 
			COUNT(1) AS [A1]
			FROM [dbo].[Order] AS [Extent1]
			WHERE ([Extent1].[OrderDate] >= @p__linq__0) AND ([Extent1].[OrderDate] <= @p__linq__1) AND ([Extent1].[PaymentDetails] = @p__linq__3) AND ([Extent1].[User_ID] = @p__linq__2)
		)  AS [GroupBy1]',N'@p__linq__0 datetime2(7),@p__linq__1 datetime2(7),@p__linq__2 bigint,@p__linq__3 varchar(100)',@p__linq__0=@FromDate,@p__linq__1=@ToDate,@p__linq__2=@UserId,@p__linq__3=@FilterFlag
	End

	If(@Mode = 'GetTransitOrdersDateRange')
	Begin
		exec sp_executesql N'SELECT *
        FROM [dbo].[Order] AS [Extent1]
        WHERE (1 = [Extent1].[DIspatched]) AND (1 = [Extent1].[Shipped]) AND (0 = [Extent1].[Deliver]) AND ([Extent1].[OrderDate] >= @p__linq__0) AND ([Extent1].[OrderDate] <= @p__linq__1) AND ([Extent1].[User_ID] = @p__linq__2)
    ',N'@p__linq__0 datetime2(7),@p__linq__1 datetime2(7),@p__linq__2 bigint',@p__linq__0=@FromDate,@p__linq__1=@ToDate,@p__linq__2=@UserId
	End

	If(@Mode = 'CountTransitOrdersDateRange')
	Begin
		exec sp_executesql N'SELECT 
		[GroupBy1].[A1] AS [C1]
		FROM ( SELECT 
			COUNT(1) AS [A1]
			FROM [dbo].[Order] AS [Extent1]
			WHERE (1 = [Extent1].[DIspatched]) AND (1 = [Extent1].[Shipped]) AND (0 = [Extent1].[Deliver]) AND ([Extent1].[OrderDate] >= @p__linq__0) AND ([Extent1].[OrderDate] <= @p__linq__1) AND ([Extent1].[User_ID] = @p__linq__2)
		)  AS [GroupBy1]',N'@p__linq__0 datetime2(7),@p__linq__1 datetime2(7),@p__linq__2 bigint',@p__linq__0=@FromDate,@p__linq__1=@ToDate,@p__linq__2=@UserId
	End
	
	If(@Mode = 'GetSalesPerDayDateRange')
	Begin
		exec sp_executesql N'SELECT 
		1 AS [C1], 
		[GroupBy1].[K1] AS [C2], 
		[GroupBy1].[A1] AS [C3]
		FROM ( SELECT 
			[Project1].[C1] AS [K1], 
			SUM([Project1].[TotalAmount]) AS [A1]
			FROM ( SELECT 
				[Extent1].[TotalAmount] AS [TotalAmount], 
				convert (datetime2, convert(varchar(255), [Extent1].[OrderDate], 102) ,  102) AS [C1]
				FROM [dbo].[Order] AS [Extent1]
				WHERE ([Extent1].[User_ID] = @p__linq__0) AND ([Extent1].[OrderDate] >= @p__linq__1) AND ([Extent1].[OrderDate] <= @p__linq__2)
			)  AS [Project1]
			GROUP BY [Project1].[C1]
		)  AS [GroupBy1]',N'@p__linq__0 bigint,@p__linq__1 datetime2(7),@p__linq__2 datetime2(7)',@p__linq__0=@UserId,@p__linq__1=@FromDate,@p__linq__2=@ToDate	
	End

	If(@Mode = 'GetOrderPerDayDateRange')
	Begin
		exec sp_executesql N'SELECT 
		1 AS [C1], 
		[Project3].[C1] AS [C2], 
		[Project3].[C2] AS [C3]
		FROM ( SELECT 
			[Project2].[C1] AS [C1], 
			(SELECT 
				COUNT(1) AS [A1]
				FROM [dbo].[Order] AS [Extent2]
				WHERE ([Extent2].[User_ID] = @p__linq__0) AND ([Extent2].[OrderDate] >= @p__linq__1) AND ([Extent2].[OrderDate] <= @p__linq__2) AND (([Project2].[C1] = (convert (datetime2, convert(varchar(255), [Extent2].[OrderDate], 102) ,  102))) OR (([Project2].[C1] IS NULL) AND (convert (datetime2, convert(varchar(255), [Extent2].[OrderDate], 102) ,  102) IS NULL))) AND (0 <> [Extent2].[OrderID])) AS [C2]
			FROM ( SELECT 
				[Distinct1].[C1] AS [C1]
				FROM ( SELECT DISTINCT 
					convert (datetime2, convert(varchar(255), [Extent1].[OrderDate], 102) ,  102) AS [C1]
					FROM [dbo].[Order] AS [Extent1]
					WHERE ([Extent1].[User_ID] = @p__linq__0) AND ([Extent1].[OrderDate] >= @p__linq__1) AND ([Extent1].[OrderDate] <= @p__linq__2)
				)  AS [Distinct1]
			)  AS [Project2]
		)  AS [Project3]',N'@p__linq__0 bigint,@p__linq__1 datetime2(7),@p__linq__2 datetime2(7)',@p__linq__0=@UserId,@p__linq__1=@FromDate,@p__linq__2=@ToDate
	End

	If(@Mode = 'GetSalesPerCountryDateRange')
	Begin
		exec sp_executesql N'SELECT TOP (6) 
			[Project1].[C2] AS [C1], 
			[Project1].[Country_Name] AS [C2], 
			[Project1].[C1] AS [C3]
			FROM ( SELECT 
				[GroupBy1].[A1] AS [C1], 
				[GroupBy1].[K1] AS [Country_Name], 
				1 AS [C2]
				FROM ( SELECT 
					[Extent2].[Country_Name] AS [K1], 
					SUM([Extent1].[TotalAmount]) AS [A1]
					FROM  [dbo].[Order] AS [Extent1]
					INNER JOIN [dbo].[Customers] AS [Extent2] ON [Extent1].[CustomerID] = [Extent2].[CustomerID]
					WHERE ([Extent1].[User_ID] = @p__linq__0) AND ([Extent1].[OrderDate] >= @p__linq__1) AND ([Extent1].[OrderDate] <= @p__linq__2) AND ([Extent2].[User_ID] = @p__linq__0)
					GROUP BY [Extent2].[Country_Name]
				)  AS [GroupBy1]
			)  AS [Project1]
			ORDER BY [Project1].[C1] DESC',N'@p__linq__0 bigint,@p__linq__1 datetime2(7),@p__linq__2 datetime2(7)',@p__linq__0=@UserId,@p__linq__1=@FromDate,@p__linq__2=@ToDate
	End

	If(@Mode = 'GetOrderLikeOrderNo')
	Begin
		exec sp_executesql N'SELECT 
		[Extent1].[OrderID] AS [OrderID], 
		[Extent1].[CustomerID] AS [CustomerID], 
		[Extent1].[PaymentID] AS [PaymentID], 
		[Extent1].[ShippingID] AS [ShippingID], 
		[Extent1].[Discount] AS [Discount], 
		[Extent1].[Taxes] AS [Taxes], 
		[Extent1].[TotalAmount] AS [TotalAmount], 
		[Extent1].[isCompleted] AS [isCompleted], 
		[Extent1].[OrderDate] AS [OrderDate], 
		[Extent1].[DIspatched] AS [DIspatched], 
		[Extent1].[DispatchedDate] AS [DispatchedDate], 
		[Extent1].[Shipped] AS [Shipped], 
		[Extent1].[ShippingDate] AS [ShippingDate], 
		[Extent1].[Deliver] AS [Deliver], 
		[Extent1].[DeliveryDate] AS [DeliveryDate], 
		[Extent1].[Notes] AS [Notes], 
		[Extent1].[CancelOrder] AS [CancelOrder], 
		[Extent1].[User_ID] AS [User_ID], 
		[Extent1].[CustomerName] AS [CustomerName], 
		[Extent1].[PaymentDetails] AS [PaymentDetails], 
		[Extent1].[fulfillmentdetails] AS [fulfillmentdetails], 
		[Extent1].[OrderNo] AS [OrderNo]
		FROM [dbo].[Order] AS [Extent1]
		WHERE ([Extent1].[User_ID] = @p__linq__0) AND ([Extent1].[OrderNo] LIKE @p__linq__1 ESCAPE ''~'')',N'@p__linq__0 bigint,@p__linq__1 varchar(8000)',@p__linq__0=@UserId,@p__linq__1=@FilterFlag
	End

	If(@Mode = 'GetReturnableOrders')
	Begin
		exec sp_executesql N'SELECT 
		[Extent1].[OrderID] AS [OrderID], 
		[Extent1].[CustomerID] AS [CustomerID], 
		[Extent1].[PaymentID] AS [PaymentID], 
		[Extent1].[ShippingID] AS [ShippingID], 
		[Extent1].[Discount] AS [Discount], 
		[Extent1].[Taxes] AS [Taxes], 
		[Extent1].[TotalAmount] AS [TotalAmount], 
		[Extent1].[isCompleted] AS [isCompleted], 
		[Extent1].[OrderDate] AS [OrderDate], 
