/* ============================================================
   Procedure: [dbo].[usp_es_ProductSearchAutoComplete]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- exec usp_es_ProductSearchAutoComplete 'app', 'localhost'


CREATE   PROCEDURE usp_es_ProductSearchAutoComplete
	@FilterText NVARCHAR(100),
	@DomainName NVARCHAR(500)
AS
BEGIN
	DECLARE @UserId BIGINT = 0;
	SELECT @UserId = User_Id FROM eshop_client_domain WHERE Domain like @DomainName
	SELECT *
		FROM(
			SELECT Name, 'in products' as [IN], User_ID 
				   FROM Products(NOLOCK)
			UNION

			SELECT Name, 'in category' as [IN], User_ID
				FROM Categories(NOLOCK)
    
			UNION
			SELECT Meta_Tags, 'in tags' as [IN], User_ID
				FROM Products(NOLOCK)
    
			UNION
			SELECT name, 'in collection' as [IN], User_ID 
				FROM collection(NOLOCK)
		) tb
		WHERE tb.User_ID = @UserId and Name <> '' AND  NAME LIKE @FilterText+'%'
END


GO

/* ============================================================
   Procedure: [dbo].[usp_es_PunchFreshOrderOnExchangeOrReplaced]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_es_PunchFreshOrderOnExchangeOrReplaced
	@ReturnId bigint,
	@StateName nvarchar(255)
as
begin
	--declare @ReturnId bigint = 41;
	--declare @StateName nvarchar(255) = 'Product Exchanged';

	if(@StateName = 'Product Exchanged' or @StateName = 'Product Replaced' )
	begin
		declare @ProductName nvarchar(255), @Rep_Variant nvarchar(255),  @Quantity_Return int, @User_Id bigint, @OrderDetailId bigint, @OrderId bigint;

		select @ProductName = ProductName, @User_Id = User_ID, @Rep_Variant = Rep_Variant, @OrderDetailId = OrderDetailsID, @OrderId = OrderID, @Quantity_Return = Quantity_Return from eshop_Order_Return where ReturnID = @ReturnId

		declare @GeneratedOrderNo nvarchar(255) = ''

		select @GeneratedOrderNo = TRIM(Prefix) + '_'  + TRIM(str(LastUpdatedNumber)) + '_'+ TRIM(Suffix) from eshop_order_number_setting where User_Id = @User_Id
		
		print '@OrderDetailId =>' + str(@OrderDetailId)
		

		begin transaction
		begin try
			insert into [Order]	( CustomerID, PaymentID, ShippingID, Discount, Taxes, TotalAmount, OrderDate, User_ID, CustomerName, PaymentDetails, fulfillmentdetails, OrderNo
			) select 
				CustomerID, PaymentID, ShippingID, Discount, Taxes, 0, getdate(), User_ID, CustomerName, 'Paid', 'Unfulfilled', @GeneratedOrderNo
					from [Order] where OrderID = @OrderId
		
			declare @InsertedOrderId bigint = SCOPE_IDENTITY();
			print '@InsertedOrderId => '+str(@InsertedOrderId)
			print '@OrderDetailId => '+str(@OrderDetailId)
			print '@Quantity_Return => '+str(@Quantity_Return)
			print '@Rep_Variant => '+str(@Rep_Variant)

			insert into OrderDetails ( OrderID, ProductID, UnitPrice, Quantity, TaxAmt, Discount, TotalAmount, OrderDate, User_ID, ProductName, Variant, fulfillmentstatus, OrderNo ) select 
					@InsertedOrderId, ProductID, UnitPrice, @Quantity_Return, TaxAmt, Discount, UnitPrice * @Quantity_Return, getdate(), User_ID, ProductName, @Rep_Variant, 'Unfulfilled', @GeneratedOrderNo
						from OrderDetails  where OrderDetailsID = @OrderDetailId

			print '@@RowCount() => ' + str(@@RowCount)

			declare @InsertedOrderDetailId bigint = SCOPE_IDENTITY();
			print '@InsertedOrderDetailId => ' + str(@InsertedOrderDetailId)

			declare @UpdateTotalAmount numeric(18, 2) = (select TotalAmount from OrderDetails where OrderDetailsID =  @InsertedOrderDetailId)

			update [Order] set TotalAmount =  @UpdateTotalAmount where OrderID = @InsertedOrderId
			
			update eshop_order_number_setting
				set LastUpdatedNumber = LastUpdatedNumber + 1
			where User_ID = 33097

			commit transaction
		end try
		begin catch
			rollback transaction
		end catch
	end
end



GO

/* ============================================================
   Procedure: [dbo].[usp_es_RemoveEshop]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- Exec usp_es_RemoveEshop 32198
-- Exec usp_es_RemoveEshop 25254
CREATE   PROC [dbo].[usp_es_RemoveEshop]
(                                    
	@User_ID int
)
as
begin
	Declare @Msg varchar(200)='Eshop setup Removal UnSuccessfull'

	Delete From eshop_client_domain where User_Id=@User_ID

	Delete From eshop_store_address where User_Id=@User_ID
	
	Delete From eshop_store_details where User_Id=@User_ID

	Delete From eshop_store_standard where User_Id=@User_ID

	Delete From Eshop_client_About_Details where User_Id=@User_ID

	Delete from [tbl_es_PageTheme] where User_ID = @User_ID
			
	Delete from [tbl_es_PageSection] where User_ID = @User_ID

	Delete from [tbl_es_PageSectionDetail] Where User_Id=@User_ID

	Delete from default_setting where User_ID = @User_ID

	Delete from eshop_notification where User_ID = @User_ID

	Delete from Return_Stage where User_ID = @User_ID

	Delete from eshop_tax_master where User_ID = @User_ID

	Delete from eshop_loyality_event where User_ID = @User_ID

	Delete from eshop_loyalty_campaign where User_ID = @User_ID

	Delete from eshop_loyalty_global_setting where User_ID = @User_ID

	Delete from eshop_loyalty_redemption where User_ID = @User_ID

	Delete from eshop_loyalty_rule_OptIn where User_ID = @User_ID

	Delete from eshop_loyality_tbl where User_ID = @User_ID

	Delete from Eshop_Cust_Loyalty_Details where User_ID = @User_ID

	Delete from eshop_cust_loyalty_total where User_ID = @User_ID

	Delete from eshop_loyalty_rules where User_ID = @User_ID

	Delete from eshop_loyalty where User_ID = @User_ID

	Delete from Paymenttype where User_ID = @User_ID

	Delete from eshoppaymentgateway where User_ID = @User_ID

	Delete from eshop_product_Invenory Where User_ID = @User_ID

	Delete from Wishlist Where ProductID in (Select ProductId from Products where User_ID = @User_ID)

	Delete from variant_detail where User_ID = @User_ID
	
	Delete from variants where User_ID = @User_ID

	Delete from eshop_order_number_setting where User_ID = @User_ID

	Delete from collection_criteria where collectionid in (select id from collection(NOLOCK) where User_ID =@User_ID)

	Delete from [collection] where User_ID = @User_ID

	Delete from [OrderDetails] where User_ID = @User_ID

	Delete from [Order] where User_ID = @User_ID

	Delete from eshop_Order_Return_Stage where User_ID = @User_ID

	Delete from eshop_Order_Return where User_ID = @User_ID

	Delete from return_reason where User_ID = @User_ID

	Delete from Products where User_ID = @User_ID

	Delete from Suppliers where User_ID = @User_ID

	Delete from categories where User_ID = @User_ID

	Delete from eshop_Policy where User_ID = @User_ID

	Delete from GenLogo where User_ID = @User_ID

	Delete from eshop_customer_social_link where User_ID = @User_ID

	set @Msg='Eshop Setup Removal Successfull'

	Select @Msg as Msg
end 



