   Procedure: [dbo].[usp_es_SaveCoupon]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

--exec usp_es_SaveCoupon @CouponID=3,@IsDiscount=1,@IsFreebee=0,@IsOthers=0,@CouponName=N'Test Coupon2',@CouponCode=N'Test693056',@CouponDescription=N'Description of Coupon ',@SelectionCriteria=N'Product',@CriteriaApplyTo=N'All',@CriteriaDetail=N'1=1',@IncludedSegment=N'Everyone',@SelectedSegment=N'',@csvSegment=N'',@csvSegmentEmail=N'',@csvSegmentMobile=N'',@ApplyToBillAmtType=N'Any',@MinBillAmt=0.0,@MaxBillAmt=0.0,@DiscAmt=0.0,@DiscPerc=5.0,@DiscOther=N'',@StartDate='2021-03-01 00:00:00',@ExpiryDate='2021-03-31 12:00:00',@Status=1,@ParentID=37540,@ReuseCount=1,@UserId=37540
CREATE   PROC usp_es_SaveCoupon
(       
	@CouponID bigint = 0,
	@IsDiscount bit,
	@IsFreebee bit,
	@IsOthers bit,
	@CouponName varchar(50),
	@CouponCode varchar(50),
	@CouponDescription varchar(200),
	@SelectionCriteria varchar(50),
	@CriteriaApplyTo varchar(10),
	@CriteriaDetail varchar(max),
	@IncludedSegment varchar(10),
	@SelectedSegment varchar(10),
	@csvSegment nvarchar(max),
	@csvSegmentEmail nvarchar(max),
	@csvSegmentMobile nvarchar(max),
	@ApplyToBillAmtType varchar(10),
	@MinBillAmt numeric(18,2),
	@MaxBillAmt numeric(18,2),
	@DiscAmt numeric(18,2),
	@DiscPerc numeric(18,2),
	@DiscOther varchar(500),
	@StartDate datetime,
	@ExpiryDate datetime,
	@Status bit ,
	@ParentID bigint,
	@ReuseCount int,
	@UserId bigint
)        
as
begin

If(@CouponID = 0)
Begin
	if not exists(select '*' from tbl_es_Coupon(nolock) where CouponName = @CouponName and @ParentID = ParentID)
	Begin
		if not exists(select '*' from tbl_es_Coupon(nolock) where CouponCode = @CouponCode and @ParentID = ParentID)
		Begin
			INSERT INTO [dbo].[tbl_es_Coupon]
			([IsDiscount], [IsFreebee], [IsOthers], [CouponName], [CouponCode], [CouponDescription], [SelectionCriteria],
			[CriteriaApplyTo],[CriteriaDetail], [IncludedSegment], [SelectedSegment], [csvSegment], [csvSegmentEmail],
			[csvSegmentMobile],[ApplyToBillAmtType], [MinBillAmt], [MaxBillAmt], [DiscAmt], [DiscPerc], [DiscOther],
			[StartDate], [ExpiryDate],[Status], [ParentID], [ReuseCount], [CreatedBy], [CreatedDate])
			VALUES
			(@IsDiscount, @IsFreebee, @IsOthers, @CouponName, @CouponCode, @CouponDescription, @SelectionCriteria,
			@CriteriaApplyTo, @CriteriaDetail, @IncludedSegment, @SelectedSegment, @csvSegment, @csvSegmentEmail,
			@csvSegmentMobile, @ApplyToBillAmtType, @MinBillAmt, @MaxBillAmt, @DiscAmt, @DiscPerc, @DiscOther,
			@StartDate, @ExpiryDate, @Status, @ParentID, @ReuseCount, @UserId, GETDATE())

			Select SCOPE_IDENTITY() as MsgId, 'Coupon Added Successfully' as Msg
		End
		Else
		Begin
			Select -1 as MsgId, 'Coupon Code already exists' as Msg
		End
	End
	Else
	Begin
		Select -2 as MsgId, 'Coupon Name already exists' as Msg
	End
End
Else
Begin
	If not exists(select '*' from tbl_es_Coupon(nolock) where CouponName = @CouponName and @ParentID = ParentID and CouponID != @CouponID)
	Begin
		If not exists(select '*' from tbl_es_Coupon(nolock) where CouponCode = @CouponCode and @ParentID = ParentID and CouponID != @CouponID)
		Begin
			UPDATE [dbo].[tbl_es_Coupon]
			   SET [IsDiscount] = @IsDiscount ,[IsFreebee] = @IsFreebee ,[IsOthers] = @IsOthers , [CouponName] = @CouponName,
				   [CouponCode] = @CouponCode, [CouponDescription] = @CouponDescription, 
				   [SelectionCriteria] = @SelectionCriteria, [CriteriaApplyTo] = @CriteriaApplyTo, 
				   [CriteriaDetail] = @CriteriaDetail, [IncludedSegment] = @IncludedSegment, 
				   [SelectedSegment] = @SelectedSegment, [csvSegment] = @csvSegment, [csvSegmentEmail] = @csvSegmentEmail,
				   [csvSegmentMobile] = @csvSegmentMobile, [ApplyToBillAmtType] = @ApplyToBillAmtType, 
				   [MinBillAmt] = @MinBillAmt, [MaxBillAmt] = @MaxBillAmt, [DiscAmt] = @DiscAmt, [DiscPerc] = @DiscPerc,
				   [DiscOther] = @DiscOther, [StartDate] = @StartDate, [ExpiryDate] = @ExpiryDate, [Status] = @Status,
				   [ParentID] = @ParentID, [ReuseCount]=@ReuseCount, [ModifyBy] = @UserId,[ModifyDate] = GETDATE()
			 WHERE CouponID=@CouponID

			Select @CouponID as MsgId, 'Coupon Edited Successfully' as Msg
		End
		Else
		Begin
			Select -1 as MsgId, 'Coupon Code already exists' as Msg
		End
	End
	Else
	Begin
		Select -2 as MsgId, 'Coupon Name already exists' as Msg
	End
End

END



