/* ============================================================
   Procedure: [dbo].[usp_es_SaveLoyaltyTransaction]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- Exec usp_es_SaveLoyaltyTransaction 257108
CREATE   PROC usp_es_SaveLoyaltyTransaction
(  
	@ActivityId BIGINT
)  
As  
BEGIN  
	-- declare @ActivityId bigint=256830
	DECLARE @EventID BIGINT= 0, @LeadID bigint=0, @ParentID bigint=0, @CustomerID int=0, @ActivityType nvarchar(100)=''
	DECLARE @LoyaltyId BIGINT= 0, @Points bigint=0, @Percentage numeric(18,0)=0, @PointsBalance bigint=0, 
			@description nvarchar(500)='', @OrderId bigint=0, @GlobalOptIn bit=0, @CustOptIn bit=0, 
			@PointsExpiryDays int=0, @ExpiryDate datetime, @TxStatus varchar(50)='', @RewardMapId bigint

	Select @LeadID=LeadID, @ParentID=ParentID, @EventID=EventID From tbl_LeadEventHistory(nolock) Where HistoryID=@ActivityId
	-- Select * From tbl_LeadEventHistory(nolock) Where EventID in (16,20,21,25,34,60,63,64,66,67,69,70,71,72,73,74)  order by 1 desc

	select @CustomerID=CustomerID from customers(nolock) where LeadID=@LeadID

	Select @GlobalOptIn=isnull(OptInRequired,0), @PointsExpiryDays=PointsExpiryDays 
	From tbl_es_LoyaltyGlobalSetting(nolock) 
	Where User_ID=@ParentID

	If(@GlobalOptIn = 0)
	Begin
		Set @CustOptIn=1
	End
	Else
	Begin
		Select @CustOptIn=OptIn From tbl_es_CustomerLoginDetail(nolock) Where CustomerId=@CustomerID
	End

	If(@CustOptIn=1)
	Begin
		If exists (Select * from ActivityMaster(nolock) where Eventtype='eshop' and eventby='Lead' and ID=@EventID)
		Begin
			If exists(select * from eshop_rewardssettings(nolock) Where ParentID=@ParentID and IsActive=1 and EventID=@EventID)
			Begin
				If not exists(select * from eshop_rewardsmapping(nolock) Where ActivityId=@ActivityId and ActivityType='Rewards')
				Begin
					select top 1 @LoyaltyId=Id, @ActivityType ='Rewards', @description ='Cr. - ' + RuleName, 
								 @Percentage=Percentage, @Points=Points
					from eshop_rewardssettings(nolock) 
					Where ParentID=@ParentID and IsActive=1 and EventID=@EventID
					Order By RuleSequence

					SELECT top 1 @PointsBalance=[PointsBalance]
					FROM [dbo].[eshop_rewardsmapping](nolock)
					Where [CustomerId]=@CustomerID
					order by id desc

					If(@EventID=20)
					Begin
						Select @OrderId=Cast(isnull(refids,0) as bigint) From tbl_LeadEventHistory(nolock) Where HistoryID=@ActivityId

						If(@Percentage > 0 and @OrderId > 0)
						Begin
							Select @Points=cast(round(TotalAmount*@Percentage/100,0) as bigint) From [Order](nolock) Where OrderId=@OrderId
						End

						Set @TxStatus='Pending'
					End
					Else
					Begin
						Set @TxStatus='Active'
					End

					Select @ExpiryDate= case when @PointsExpiryDays=0 then null else DATEADD(DD, @PointsExpiryDays, GETDATE()) end

					INSERT INTO [dbo].[eshop_rewardsmapping]
					([ActivityId],[ActivityType],[LoyaltyId],[Points],[CustomerId],[leadid],[PointsBalance],[description],[CreatedOn],[IsExpired],[ExpiryDate],[TxStatus])
					 VALUES
					(@ActivityId,@ActivityType,@LoyaltyId, @Points, @CustomerId, @LeadID, (@PointsBalance + @Points), @description, getdate(), 0, @ExpiryDate, @TxStatus)

					set @RewardMapId=SCOPE_IDENTITY()

					If(@EventID=20)-- now saving Tx for processing by job
					Begin
						insert into tbl_es_ProcessLoyaltyTransaction(OrderID,EventID,RewardMapId,User_ID,IsProcessed,CreatedOn)
						values(@OrderId,@EventID,@RewardMapId,@ParentID,0,GETDATE())
					End

				End
			End
		End
	End

END  



GO

/* ============================================================
   Procedure: [dbo].[usp_es_SavePageTheme]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- Exec usp_es_SavePageTheme @UserId=33097,@JsonPageTheme='',@JsonPageSectionDetail='',@CsvFeaturedCollection=''  
CREATE   PROC usp_es_SavePageTheme  
(    
 @UserId bigint=0,  
 @JsonPageTheme varchar(max),  
 @JsonPageSectionDetail varchar(max),  
 @CsvFeaturedCollection varchar(1000) = ''  
)  
AS  
Begin  
 declare @RecordJson varchar(max), @Page_Id int, @PageName varchar(100), @Theme varchar(100), @Color varchar(20), @User_Id bigint,   
   @IsActive bit  
  
 SELECT @JsonPageTheme=REPLACE(REPLACE(@JsonPageTheme, CHAR(13), ''), CHAR(10), '')  
 SELECT @JsonPageSectionDetail=REPLACE(REPLACE(@JsonPageSectionDetail, CHAR(13), ''), CHAR(10), '')  
  
 If(isnull(@JsonPageTheme,'') != '')  
 Begin  
  select @Page_Id=Page_Id, @PageName=PageName, @Theme=Theme, @Color=Color, @User_Id=User_Id, @IsActive=IsActive  
  from openjson(@JsonPageTheme)      
  WITH   
  (     
   Page_Id     int    '$.Page_Id',  
   PageName    varchar(100) '$.PageName',  
   Theme     varchar(100) '$.Theme',  
   Color     varchar(20)  '$.Color',  
   User_Id     bigint   '$.User_Id',  
   IsActive    bit    '$.IsActive'  
  )  
     
  If(isnull(@PageName,'') != '' and isnull(@Theme,'') != '' and isnull(@Color,'') != '' and isnull(@User_Id,0) > 0)  
  Begin  
   If(@IsActive = 1)  
   Begin  
    Update [tbl_es_PageTheme] set IsActive=0 Where User_Id=@UserId and PageName=@PageName  
   End  
  
   If not exists(Select * From [tbl_es_PageTheme](nolock) Where User_Id=@UserId and PageName=@PageName and Theme=@Theme)  
   Begin --Insert  
    Insert into [tbl_es_PageTheme](PageName,Theme,Color,User_Id,IsActive)  
    values (@PageName, @Theme, @Color, @UserId, @IsActive)  
  
    Select @Page_Id=Scope_Identity()  
   End  
   Else --Update  
   Begin  
    Update [tbl_es_PageTheme]   
    Set  Color=@Color, IsActive=@IsActive, @Page_Id=Page_Id, ModifiedDate=getdate()  
    Where User_Id=@User_Id and PageName=@PageName and Theme=@Theme  
   End  
  
   If not exists(Select * From [tbl_es_PageSection](nolock) Where User_Id = @UserId)  
   Begin  
    Insert into [tbl_es_PageSection](SectionCode,SectionName,User_Id,IsActive)  
    Select SectionCode,SectionName,User_Id=@UserId,IsActive  
    From [tbl_es_PageSection]  
    Where User_Id=33097  
   End  
  
   If(isnull(@JsonPageSectionDetail,'') != '')  
   Begin  
    Update PSD  
    set  PSD.IsActive=0, PSD.ModifiedDate=getdate()  
    From [tbl_es_PageSectionDetail] PSD inner join [tbl_es_PageTheme] PT  
    On  PSD.Page_Id = PT.Page_Id  
    Where PSD.User_Id=@UserId and PT.PageName=@PageName and PT.Theme=@Theme  
    
    set @RecordJson=(SELECT (JSON_QUERY((select PSD.* from [tbl_es_PageSectionDetail](nolock) PSD inner join [tbl_es_PageTheme](nolock) PT  
    On  PSD.Page_Id = PT.Page_Id  
    Where PSD.User_Id=@UserId and PT.PageName=@PageName and PT.Theme=@Theme for json auto))) as col1)   
  
    If(isnull(@RecordJson,'') != '')  
    Begin  
     Insert into tbl_es_RecordHistory(Action,RecordJson,TableName,User_Id)  
     values('D',@RecordJson,'tbl_es_PageSectionDetail',@UserId)  
    End  
  
    Delete PSD   
    From [tbl_es_PageSectionDetail] PSD inner join [tbl_es_PageTheme] PT  
    On  PSD.Page_Id = PT.Page_Id  
    Where PSD.User_Id=@UserId and PT.PageName=@PageName and PT.Theme=@Theme  
  
    insert into [tbl_es_PageSectionDetail](Page_Id,SectionCode,SectionUrl,SectionContent,SectionTitle,User_Id,IsActive)  
    select Page_Id=@Page_Id,SectionCode,isnull(SectionUrl,''),SectionContent,isnull(SectionTitle,''),User_Id,IsActive  
    from openjson(@JsonPageSectionDetail)      
    WITH   
    (     
     PageSectionDetail_Id int    '$.PageSectionDetail_Id',  
     Page_Id     int    '$.Page_Id',  
     SectionCode    numeric(18,2) '$.SectionCode',  
     SectionUrl    varchar(1000) '$.SectionUrl',  
     SectionContent   nvarchar(max) '$.SectionContent',  
     SectionTitle   nvarchar(1000) '$.SectionTitle',  
     User_Id     bigint   '$.User_Id',  
     IsActive    bit    '$.IsActive'  
    )  
  
    set @RecordJson=''  
    set @RecordJson=(SELECT (JSON_QUERY((select * from [tbl_es_PageSectionDetail](nolock) where User_Id=@UserId and Page_Id=@Page_Id for json auto))) as col1)   
  
    If(isnull(@RecordJson,'') != '')  
    Begin  
     Insert into tbl_es_RecordHistory(Action,RecordJson,TableName,User_Id)  
     values('I',@RecordJson,'tbl_es_PageSectionDetail',@UserId)  
    End  
    
    If(isnull(@CsvFeaturedCollection,'')!='')  
    Begin  
     update [Collection]  
     set  isfeatured=0  
     Where USER_ID=@UserId and IsActive=1  
  
     update [Collection]  
     set  isfeatured=1  
     Where USER_ID=@UserId and IsActive=1 and Id in (select [value] from dbo.fn_Split(@CsvFeaturedCollection,','))  
    End  
     Select 1 as StatusCode, 'Page Theme saved Successfully' as Msg  
    End  
   Else  
   Begin  
    Select 0 as StatusCode, 'Failed to save Page Section Detail' as Msg  
   End  
  End  
  Else  
  Begin  
   Select 0 as StatusCode, 'Failed due to Invalid Page Data' as Msg  
  End  
 End  
 Else  
 Begin  
  Select 0 as StatusCode, 'Failed to save Page Theme' as Msg  
 End  
  
End  


GO

/* ============================================================
   Procedure: [dbo].[usp_es_SaveRedemptionAmt]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- Exec usp_es_SaveRedemptionAmt 
CREATE   PROCEDURE usp_es_SaveRedemptionAmt
(  
 @OrderId bigint,
 @UserId bigint,
 @RedemptionAmt numeric(18,2)
)  
as  
begin  
  
 if(not exists (select 1 from tbl_es_InvoiceDetail(nolock) where OrderID = @OrderId))
 begin          
  declare @InvoicePrefix nvarchar(100), @InvoiceSuffix nvarchar(100), @InvoiceStartNo bigint          
          
  select @InvoicePrefix  = ISNULL(InvoicePrefix, ''), @InvoiceSuffix   = ISNULL(InvoiceSuffix, ''), @InvoiceStartNo = ISNULL(InvoiceStartNo, 1) from eshop_order_number_setting --where User_ID =  @UserId          
  declare @InvoiceCount bigint = 0;          
  select @InvoiceCount = (Count(1) + @InvoiceStartNo) from tbl_es_InvoiceDetail where User_ID = @UserId          
          
          
  declare @GenInvioceNo nvarchar(250) = LTRIM(RTRIM(REPLACE(@InvoicePrefix, ' ', ''))) + '_'+LTRIM(RTRIM(REPLACE(str(@InvoiceCount), ' ', ''))) + '_' + LTRIM(RTRIM(REPLACE(@InvoiceSuffix, ' ', '')));          
          
  insert tbl_es_InvoiceDetail (User_ID, OrderID, InvoiceNo, CreatedOn, UpdatedOn, AppliedCouponCode, AppliedCouponJSON, RedemptionAmt)          
  values (@UserId, @OrderId, @GenInvioceNo, getdate(), getdate(), Null, Null, @RedemptionAmt)          

  Select SCOPE_IDENTITY()
 end
 else
 begin
	update tbl_es_InvoiceDetail set RedemptionAmt=@RedemptionAmt Where OrderID=@OrderId

	Select @@ROWCOUNT
 end
  
end  



GO

/* ============================================================
   Procedure: [dbo].[usp_es_SaveRedemptionSetting]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC usp_es_SaveRedemptionSetting
(  
    @Id	int=0,
	@RuleName	nvarchar(200),
	@RuleDescription	nvarchar(1000),
	@ParentId	bigint,
	@Condition	nvarchar(max),
	@Points	int,
	@Percentage	numeric(18,2),
	@FreebeeProducts nvarchar(max),
	@IsUserSelected	bit,
	@IsActive	bit,
	@RuleSequence	int,
	@SavedBy	bigint
)  
As  
BEGIN  

	If(@Id = 0) -- Insert
	Begin
		If not exists(Select * From eshop_redemptionsettings(nolock) Where RuleName=@RuleName and ParentId=@ParentId)
		Begin
			INSERT INTO [dbo].[eshop_redemptionsettings]
					   ([RuleName],[RuleDescription],[ParentId],[Condition],[Points],[Percentage],[FreebeeProducts]
					   ,[IsUserSelected],[IsActive],[RuleSequence],[CreatedOn],[CreatedBy])
				 VALUES
					   (@RuleName, @RuleDescription, @ParentId, @Condition, abs(@Points), abs(@Percentage), @FreebeeProducts,
					    @IsUserSelected, @IsActive, @RuleSequence, GETDATE(), @SavedBy)


			Select SCOPE_IDENTITY() as MsgId, 'Redemption Rule Added Successfully' as Msg
		End
		Else
		Begin
			Select -1 as MsgId, 'RuleName already exists' as Msg
		End
	End
	Else
	Begin -- Update
		If not exists(Select * From eshop_redemptionsettings(nolock) Where RuleName=@RuleName and ParentId=@ParentId and Id!=@Id)
		Begin
			UPDATE [dbo].[eshop_redemptionsettings]
			   SET [RuleName] = @RuleName, [RuleDescription] = @RuleDescription, [ParentId] = @ParentId
				  ,[Condition] = @Condition, [Points] = abs(@Points), [Percentage] = abs(@Percentage)
				  ,[FreebeeProducts] = @FreebeeProducts, [IsUserSelected] = @IsUserSelected, [IsActive] = @IsActive
				  ,[RuleSequence] = @RuleSequence, [LastModifiedOn] = GETDATE(), [LastModifiedBy] = @SavedBy
			WHERE Id=@Id

			Select @Id as MsgId, 'Redemption Rule Updated Successfully' as Msg
		End
		Else
		Begin
			Select -1 as MsgId, 'RuleName already exists' as Msg
		End
	End
 
END  



GO

