CREATE   PROCEDURE usp_es_SetMiscellaneousDetail 
	@UserId bigint, 
	@GSTNo nvarchar(15),
	@PANNo nvarchar(10),
	@FullAddress nvarchar(1000)
as
begin
	IF(EXISTS(SELECT 1 FROM tbl_es_MiscellaneousDetail where User_ID = @UserId))
		BEGIN
			UPDATE tbl_es_MiscellaneousDetail set
				GSTNo = IIF(ISNULL(@GSTNo, '') = '', GSTNo, @GSTNo),
				PANNo = IIF(ISNULL(@PANNo, '') = '', PANNo, @PANNo),
				FullAddress = IIF(ISNULL(@FullAddress, '') = FullAddress, GSTNo, @FullAddress),
				UpdatedOn = GETDATE()
					where  User_ID = @UserId
		END
	ELSE
		BEGIN
			INSERT tbl_es_MiscellaneousDetail (GSTNo, PANNo, FullAddress, User_ID, CreatedOn, UpdatedOn)
				VALUES (@GSTNo, @PANNo, @FullAddress, @UserId, GETDATE(), GETDATE())
		END
end



