)
As
Begin

	UPDATE [dbo].[collection]
	   SET [name] = case when @name='' then [name] else @name end
		  ,[description] = case when @description is null then description else @description end
		  ,[ProductID] = case when @ProductID is null then [ProductID] else @ProductID end
		  ,[isfeatured] = @isfeatured
		  ,[isactive] = @isactive
		  ,[User_ID] = @User_ID
		  ,[Collection_Image] = case when @Collection_Image is null then Collection_Image else @Collection_Image end
		  ,[Thumbnail_Image] = case when @Thumbnail_Image is null then Thumbnail_Image else @Thumbnail_Image end
		  ,[SortOrder] = case when @SortOrder=0 then SortOrder else @SortOrder end
		  ,[Datecreated] = case when @Datecreated is null then Datecreated else @Datecreated end
		  ,[CollectionTags] = case when @CollectionTags is null then CollectionTags else @CollectionTags end
		  ,[FeaturedName] = case when @FeaturedName is null then FeaturedName else @FeaturedName end
		  ,[criteriatype] = case when @criteriatype is null then criteriatype else @criteriatype end
		  ,[Title] = case when @Title='' then [Title] else @Title end
		  ,[Meta_description] = case when @Meta_description='' then [Meta_description] else @Meta_description end
		  ,[Meta_Tags] = case when @Meta_Tags='' then [Meta_Tags] else @Meta_Tags end
		  ,[PageName] = case when @PageName='' then [PageName] else @PageName end
	 WHERE id=@id

	 
End



