/* ============================================================
   Procedure: [dbo].[usp_es_UpdateCouponDetail]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_es_UpdateCouponDetail
(
	@OrderId bigint,
	@UserId bigint,
	@AppliedCouponCode nvarchar(500),
	@AppliedCouponJSON nvarchar(max)
)
as
begin

	if( not exists (select 1 from tbl_es_InvoiceDetail where OrderID = @OrderId))        
	begin        
		declare @InvoicePrefix nvarchar(100), @InvoiceSuffix nvarchar(100), @InvoiceStartNo bigint        
        
		select @InvoicePrefix  = ISNULL(InvoicePrefix, ''), @InvoiceSuffix   = ISNULL(InvoiceSuffix, ''), @InvoiceStartNo = ISNULL(InvoiceStartNo, 1) from eshop_order_number_setting --where User_ID =  @UserId        
		declare @InvoiceCount bigint = 0;        
		select @InvoiceCount = (Count(1) + @InvoiceStartNo) from tbl_es_InvoiceDetail where User_ID = @UserId        
        
        
		declare @GenInvioceNo nvarchar(250) = LTRIM(RTRIM(REPLACE(@InvoicePrefix, ' ', ''))) + '_'+LTRIM(RTRIM(REPLACE(str(@InvoiceCount), ' ', ''))) + '_' + LTRIM(RTRIM(REPLACE(@InvoiceSuffix, ' ', '')));        
        
		insert tbl_es_InvoiceDetail (User_ID, OrderID, InvoiceNo, CreatedOn, UpdatedOn, AppliedCouponCode, AppliedCouponJSON)        
		values (@UserId, @OrderId, @GenInvioceNo, getdate(), getdate(), @AppliedCouponCode, @AppliedCouponJSON)        
	end        

end



