/* ============================================================
   Procedure: [dbo].[usp_es_UpdateProductDetailForFreebee]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_es_UpdateProductDetailForFreebee(
	@dtProductFreeBee dtProductFreeBee readonly
)
as
begin
	insert into OrderDetails (
		OrderID,
		OrderDate,
		User_ID,
		fulfillmentstatus,
		ProductID,
		ProductName,
		Quantity,
		Discount,
		UnitPrice,
		Variant,
		CancelOrder,
		TotalAmount
	)
	select
		fb.OrderId,
		getdate(),
		fb.ParentId,
		'UnFulfilled',
		p.ProductID,
		p.Name,
		fb.MinQty,
		0,
		p.UnitPrice,
		'',
		0,
		0
	from Products(nolock) p 
		inner join @dtProductFreeBee fb on p.User_ID = fb.ParentId and p.Name = fb.ProductName
end




