/* ============================================================
   Procedure: [dbo].[usp_es_UpdateResetPassword]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_es_UpdateResetPassword
	@ResetGuid nvarchar(255),
	@Password nvarchar(255)
as
begin
	
	declare @CustomerId bigint  = ( select CustomerId from tbl_es_CustomerLoginDetail where ResetGuid = @ResetGuid )

	update Customers set Password = @Password where CustomerID = @CustomerId

	update tbl_es_CustomerLoginDetail 
		set ResetGuid = '',
			ResetExpired = 1,
			ResetRequestedOn = null
				where CustomerId = @CustomerId

end


