/* ============================================================
   Procedure: [dbo].[usp_es_ValidateResetGuid]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_es_ValidateResetGuid
	@resetGuid nvarchar(255)
as
begin	
	-- declare @resetGuid nvarchar(255) = '4E37BBAB-6190-4F09-9BB4-6E6AEBF14E49'

	declare @CustomerId bigint = 0 ;

	if(exists(select 'x' from tbl_es_CustomerLoginDetail(nolock) where ResetGuid = @resetGuid))
    Begin  
	 select @CustomerId = CustomerId from tbl_es_CustomerLoginDetail(nolock) where ResetGuid = @resetGuid    

     if(exists(select 'x' from tbl_es_CustomerLoginDetail(nolock) where CustomerId = @CustomerId and ResetExpired = 1 ))      
        begin      
            select 'Expired'      
        End      
     else      
        Begin      
            select 'Valid'      
        End         
     End      
     else      
     Begin      
            select 'NotExists'      
     End       

end


