/* ============================================================
   Procedure: [dbo].[USP_Escortskubota_DealerDailyUpdaterEnquiryDetails]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[USP_Escortskubota_DealerDailyUpdaterEnquiryDetails]  
as
BEGIN  
begin try
    DECLARE @custom CUSTOMENQUIRY;   
    DECLARE @DealerId BIGINT ;   
    DECLARE @jsondetails NVARCHAR(MAX);  
    DECLARE @ParentId BIGINT = 46169;  
      
  
    SELECT top 1 @DealerId=DealerUpdateID, @jsondetails = JsonDetails   
    FROM TBL_Escortskubota_DealerDailyUpdate (NOLOCK)   
    WHERE cast(CreatedDate as date)=cast(getdate() as date) and IsProcessed=0 order by DealerUpdateID desc--DealerUpdateID = @DealerId;  
    

	update TBL_Escortskubota_DealerDailyUpdate set ProcessStartDate=getdate() where DealerUpdateID = @DealerId;  
    DROP TABLE IF EXISTS #tempdealerdata;  
  
 CREATE TABLE #tempdealerdata (
    tid INT IDENTITY(1,1) PRIMARY KEY,
    userCode      VARCHAR(50),
    userName      VARCHAR(500),
    mobileNumber  VARCHAR(20),
    sourceName    NVARCHAR(MAX),
    source1       VARCHAR(4000),
    source2       VARCHAR(4000),
    source3       VARCHAR(4000),
    source4       VARCHAR(4000),
    source5       VARCHAR(4000),
	enquiryid bigint
);

INSERT INTO #tempdealerdata (userCode, userName, mobileNumber, sourceName, source1, source2, source3, source4, source5)
SELECT userCode, userName, mobileNumber, sourceName, source1, source2, source3, source4, source5
FROM OPENJSON(@jsondetails)   
WITH (  
    userCode      VARCHAR(50),  
    userName      VARCHAR(500),  
    mobileNumber  VARCHAR(20),  
    sourceName    NVARCHAR(MAX),  
    source1       VARCHAR(4000),  
    source2       VARCHAR(4000),  
    source3       VARCHAR(4000),  
    source4       VARCHAR(4000),  
    source5       VARCHAR(4000)
);
  
  
    UPDATE TDD   
    SET TDD.EnquiryId = CFE.EnquiryId  
    FROM customfieldEnquiryvalue CFE  
    INNER JOIN customfields CF (NOLOCK) ON CFE.fieldID = CF.field_ID  
    INNER JOIN #tempdealerdata TDD ON CF.fieldname = 'User_Code' AND CAST(CFE.fieldvalue AS NVARCHAR(MAX)) = TDD.userCode  
    WHERE CF.ParentID = @ParentId;  
  
  declare @p_count int,@p_id int=0,@p_c nvarchar(1)
select @p_count=count(1) from prohibitedcharacters

while @p_count>0
begin
select @p_id=min(id) from prohibitedcharacters where id>@p_id
select @p_c=charactersymbol from prohibitedcharacters where id=@p_id
if @p_c in ('/','\')
begin
update t set sourcename=replace(replace(sourcename,@p_c,'_'),'  ',' ')
,source1=replace(replace(source1,@p_c,'_'),'  ',' ')
,source2=replace(replace(source2,@p_c,'_'),'  ',' ')
,source3=replace(replace(source3,@p_c,'_'),'  ',' ')
,source4=replace(replace(source4,@p_c,'_'),'  ',' ')
,source5=replace(replace(source5,@p_c,'_'),'  ',' ')
from #tempdealerdata t
end
else
begin
update t set sourcename=replace(replace(sourcename,@p_c,''),'  ',' ')
,source3=replace(replace(source3,@p_c,''),'  ',' ')
,source1=replace(replace(source1,@p_c,''),'  ',' ')
,source2=replace(replace(source2,@p_c,''),'  ',' ')
,source4=replace(replace(source4,@p_c,''),'  ',' ')
,source5=replace(replace(source5,@p_c,''),'  ',' ')
from #tempdealerdata t
end


set @p_count=@p_count-1
end



  --for debugging
--    SELECT * FROM #tempdealerdata;  
  
    DECLARE @userCode NVARCHAR(MAX);  
    DECLARE @enquiryId BIGINT;  
    DECLARE @rowCount INT;  
    DECLARE @currentRow INT = 1,@id int=0;  
	declare @cf1 bigint,@cf2 bigint,@cf3 bigint,@cf4 bigint,@cf5 bigint,@sourceid bigint,@sourcename nvarchar(200),@usercodefeldid bigint

	select top 1 @sourcename=sourcename FROM #tempdealerdata
	select @cf1=field_id from customfields(nolock) where parentid=@parentid and fieldname='Source_1'
  	select @cf2=field_id from customfields(nolock) where parentid=@parentid and fieldname='Source_2'
	select @cf3=field_id from customfields(nolock) where parentid=@parentid and fieldname='Source_3'
	select @cf4=field_id from customfields(nolock) where parentid=@parentid and fieldname='Source_4'
	select @cf5=field_id from customfields(nolock) where parentid=@parentid and fieldname='Source_5'
	select @usercodefeldid=field_id from customfields(nolock) where parentid=@parentid and fieldname='User_Code'
	
	
	if exists(select 1 from usersourcesettings(nolock) where dbo.ufn_getuserparentid(UserID)=@parentid and name=@sourcename )
	begin
	select top 1 @sourceid=sourceid from usersourcesettings(nolock) where dbo.ufn_getuserparentid(UserID)=@parentid and name=@sourcename
	end
	else
	begin
	insert into usersourcesettings(name,UserID,CreatedDate,IsActive,IsEditable)
	select @sourcename,@parentid,getdate(),1,1
	select @sourceid=scope_identity()

	end


  
    SELECT @rowCount = max(tid) FROM #tempdealerdata;  
  
  
    WHILE @rowCount>0
    BEGIN  
  
  
  --for debugging
  select 'before update', cfe.* from customfieldEnquiryvalue CFE (nolock) 
        INNER JOIN 
		(select top 100 * from #tempdealerdata where tid between @id and @id +100 and enquiryid is not null) TDD ON TDD.enquiryid = cfe.EnquiryID 
		
where cfe.fieldID in (@cf1,@cf2,@cf3,@cf4,@cf5)

	    UPDATE CFE   
        SET CFE.fieldvalue = 
		case 
		when @cf1 = cfe.fieldID and TDD.source1<>'' then cast(TDD.source1  as sql_variant)
		when @cf2 = cfe.fieldID and TDD.source2<>'' then cast(TDD.source2   as sql_variant) 
		when @cf3 = cfe.fieldID and TDD.source3<>'' then cast(TDD.source3   as sql_variant) 
		when @cf4 = cfe.fieldID and TDD.source4<>'' then cast(TDD.source4   as sql_variant) 
		when @cf5 = cfe.fieldID and TDD.source5<>'' then cast(TDD.source5   as sql_variant) end
        FROM customfieldEnquiryvalue CFE  
        INNER JOIN 
		(select top 100 * from #tempdealerdata where tid between @id and @id +100  and enquiryid is not null) TDD ON TDD.enquiryid = cfe.EnquiryID  
  where cfe.fieldID in (@cf1,@cf2,@cf3,@cf4,@cf5)


  --for debugging
  select 'after update, before delete', cfe.* from customfieldEnquiryvalue CFE (nolock) 
        INNER JOIN 
		(select top 100 * from #tempdealerdata where tid between @id and @id +100  and enquiryid is not null) TDD ON TDD.enquiryid = cfe.EnquiryID  
		where cfe.fieldID in (@cf1,@cf2,@cf3,@cf4,@cf5)


	 delete c from
	 (select cfe.* from customfieldEnquiryvalue CFE where enquiryid in
		(select top 100 enquiryid from #tempdealerdata where tid between @id and @id +100) and
		cfe.fieldid in (@cf1,@cf2,@cf3,@cf4,@cf5) and cfe.fieldvalue=''
		) c

--for debugging
  select 'after delete, before insert', cfe.* from customfieldEnquiryvalue CFE (nolock) 
        INNER JOIN 
		(select top 100 * from #tempdealerdata where tid between @id and @id +100  and enquiryid is not null) TDD ON TDD.enquiryid = cfe.EnquiryID  


	 insert into customfieldEnquiryvalue(fieldid,fieldvalue,enquiryid)
	 select field_id,case 
		when cfe.field_ID= @cf1 and isnull(TDD.source1,'') <>'' then TDD.source1  
		when cfe.field_ID= @cf2 and isnull(TDD.source2,'') <>''  then TDD.source2  
		when cfe.field_ID= @cf3 and isnull(TDD.source3,'') <>''  then TDD.source3  
		when cfe.field_ID= @cf4 and isnull(TDD.source4,'') <>''  then TDD.source4  
		when cfe.field_ID= @cf5 and isnull(TDD.source5,'') <>''  then TDD.source5  end,enquiryid
	 from customfields cfe join 
	 (select top 100 * from #tempdealerdata where tid between @id and @id +100 and enquiryid is not null) TDD on 1=1
	 where cfe.field_ID in (@cf1,@cf2,@cf3,@cf4,@cf5)
	 	 AND (
    (cfe.field_ID = @usercodefeldid AND ISNULL(tdd.userCode, '') <> '') OR
    (cfe.field_ID = @cf1 AND ISNULL(TDD.source1, '') <> '') OR
    (cfe.field_ID = @cf2 AND ISNULL(TDD.source2, '') <> '') OR
    (cfe.field_ID = @cf3 AND ISNULL(TDD.source3, '') <> '') OR
    (cfe.field_ID = @cf4 AND ISNULL(TDD.source4, '') <> '') OR
    (cfe.field_ID = @cf5 AND ISNULL(TDD.source5, '') <> '')
)
	 and not exists(select 1 from customfieldEnquiryvalue(nolock) as CF where CF.fieldID=cfe.field_ID AND cf.EnquiryID=TDD.enquiryid)

--for debugging
  select 'after insert, final for existing enquiries', cfe.* from customfieldEnquiryvalue CFE (nolock) 
        INNER JOIN 
		(select top 100 * from #tempdealerdata where tid between @id and @id +100) TDD ON TDD.enquiryid = cfe.EnquiryID  

	 set @id=@id+100
	 	 set @rowCount=@rowCount-100

	 end

	 SELECT @rowCount = count(1),@id=0 FROM #tempdealerdata-- where enquiryid is null;
	 print concat('Rowcount: ',@rowcount)

	 drop table if exists #enquiryids
	 create table #enquiryids(enquiryid bigint,mobileno nvarchar(20))
	 declare  @CsvEnquiryID  nvarchar(max)    


	 while @rowcount>0
	 begin
	 print concat('enquiries to be inserted: ',@rowcount)
	 --for debugging
	 	 select t.userName,@sourceid,t.mobileNumber,'+91',@parentid,0,0  from #tempdealerdata t where enquiryid is null and tid between @id and @id+100


SET Context_Info 0x77777
	 insert into userenquiry(personname,sourcename,mobileno,countrycode,parentid,mediumname,campaignname,createdby,CreatedDate) 
	 output inserted.enquiryid,inserted.MobileNo into #enquiryids
	 select t.userName,@sourceid,t.mobileNumber,'+91',@parentid,0,0,@parentid,getdate()  from #tempdealerdata t where enquiryid is null and tid between @id and @id+100
SET Context_Info 0x
	 --for debugging
   --select 'null enquiry ids',t.*  from #tempdealerdata t where enquiryid is null and tid between @id and @id+100
   --select 'enquiries inserted',e.* from userenquiry E (nolock) 
   --     INNER JOIN #enquiryids d on e.EnquiryID=d.enquiryid 


	 update t set enquiryid=e.enquiryid from #tempdealerdata t join #enquiryids e on e.mobileno=t.mobileNumber
	 where t.enquiryid is null and tid between @id and @id+100

	  --for debugging
	 --select 'enquiries updated in #temp',t.* from #tempdealerdata t (nolock) join #enquiryids e on e.mobileno=t.mobileNumber where  tid between @id and @id+100


	 insert into customfieldEnquiryvalue(fieldid,fieldvalue,enquiryid)
	 select field_id,case 
	    when cfe.field_ID=@usercodefeldid then tdd.userCode
		when cfe.field_ID= @cf1 and isnull(TDD.source1,'') <>''  then TDD.source1  
		when cfe.field_ID= @cf2 and isnull(TDD.source2,'') <>''   then TDD.source2  
		when cfe.field_ID= @cf3 and isnull(TDD.source3,'') <>''   then TDD.source3  
		when cfe.field_ID= @cf4 and isnull(TDD.source4,'') <>''   then TDD.source4  
		when cfe.field_ID= @cf5 and isnull(TDD.source5,'') <>''   then TDD.source5  
		end,
		enquiryid
	 from customfields cfe join 
	 (select t.* from #tempdealerdata t join #enquiryids e on t.enquiryid=e.enquiryid  where tid between @id and @id +100 and t.enquiryid is not null) TDD on 1=1
	 where cfe.field_ID in (@cf1,@cf2,@cf3,@cf4,@cf5,@usercodefeldid)
	 AND (
    (cfe.field_ID = @usercodefeldid AND ISNULL(tdd.userCode, '') <> '') OR
    (cfe.field_ID = @cf1 AND ISNULL(TDD.source1, '') <> '') OR
    (cfe.field_ID = @cf2 AND ISNULL(TDD.source2, '') <> '') OR
    (cfe.field_ID = @cf3 AND ISNULL(TDD.source3, '') <> '') OR
    (cfe.field_ID = @cf4 AND ISNULL(TDD.source4, '') <> '') OR
    (cfe.field_ID = @cf5 AND ISNULL(TDD.source5, '') <> '')
)
	 and not exists(select 1 from customfieldEnquiryvalue(nolock) as CF where CF.fieldID=cfe.field_ID AND cf.EnquiryID=TDD.enquiryid)

	 select @CsvEnquiryID=coalesce(@CsvEnquiryID+',',cast(enquiryid as nvarchar))+ cast(enquiryid as nvarchar) from #enquiryids
     exec [dbo].[usp_ExecEnquiryTriggerTasks_multi] @CsvEnquiryID


	 --for debugging
	 --select cfe.* from customfieldEnquiryvalue(nolock) as cfe join #enquiryids e on cfe.EnquiryID=e.enquiryid
	 --select * from  #tempdealerdata t join #enquiryids e on t.enquiryid=e.enquiryid  where tid between @id and @id +100

	 truncate table #enquiryids

	 set @rowCount=@rowcount-100
	 set @id=@id+100


	 end
	 	update TBL_Escortskubota_DealerDailyUpdate set IsProcessed=1, ProcessEndDate=getdate() where DealerUpdateID = @DealerId;  
end try
begin catch
update TBL_Escortskubota_DealerDailyUpdate set ProcessEndDate=getdate(),ErrorDescription=ERROR_MESSAGE() where DealerUpdateID = @DealerId;  

exec usp_inserterrorinfo
end catch

	 end



	


