/* ============================================================
   Procedure: [dbo].[usp_eshop_GetVariantOrderListWithTax]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

    
-- Exec usp_eshop_GetVariantOrderListWithTax @PRODUCTNAME='', @User_ID=33097 
CREATE   PROC usp_eshop_GetVariantOrderListWithTax
(                              
	@PRODUCTNAME varchar(150) = '' ,
	@User_ID BIGINT
)                              
as                              
begin       

-- declare @PRODUCTNAME varchar(150) = '' ,@User_ID BIGINT=33097
DECLARE @V_COUNT INT, @COUNT INT, @V_VALUE VARCHAR(500)='', @NAME VARCHAR(500), @ID INT, @PNAME VARCHAR(150), @PRICE DECIMAL(18, 0), 
		@StockKeepingUnit VARCHAR(100), @INVENTORY INT, @Barcode VARCHAR(100), @Date DATETIME, @P_Count INT, @P1_Count INT= 0;                             

SELECT @id AS ID, PRODUCTNAME, NAME, V_VALUE, PRICE, StockKeepingUnit, INVENTORY, Barcode, [User_ID], Date_Modified, @COUNT AS RNO
INTO #TEMP
FROM VARIANTS
WHERE 1 = 2;       

SELECT Name
INTO #temp2
FROM Products(NOLOCK)
WHERE 1 = 2;       

IF(@PRODUCTNAME <> '')
BEGIN
	INSERT INTO #temp2
    SELECT DISTINCT Name
    FROM Products
    WHERE [User_ID] = @User_ID and Name LIKE '%' + @PRODUCTNAME + '%';
END;
ELSE
BEGIN
    INSERT INTO #temp2
    SELECT DISTINCT Name
    FROM Products
    WHERE [User_ID] = @User_ID;
END;

SET @P_Count =(SELECT COUNT(*) FROM #temp2);

WHILE(@P1_Count < @P_Count)
BEGIN
    SET @V_COUNT = 0;
     
	SELECT @V_COUNT = COUNT(*)
	FROM
	(
		SELECT ROW_NUMBER() OVER(ORDER BY ID ASC) AS rownumber
		FROM VARIANTS
		WHERE PRODUCTNAME = (
								SELECT Name 
								FROM (SELECT Name, ROW_NUMBER() OVER(ORDER BY Name ASC) AS rownumber FROM #temp2) AS t1 
								WHERE rownumber = @P1_Count + 1
							) AND [User_ID] = @User_ID
	) AS VARIANTS

    SET @COUNT = 0;                
    --select @V_COUNT return                          
    WHILE(@COUNT < @V_COUNT)
    BEGIN
        SELECT @ID = ID
        FROM
        (
            SELECT ID, ROW_NUMBER() OVER(ORDER BY ID ASC) AS rownumber
            FROM VARIANTS
            WHERE PRODUCTNAME = ISNULL(@PRODUCTNAME, PRODUCTNAME) AND [User_ID] = @User_ID
        ) AS VARIANTS
        WHERE rownumber = @COUNT + 1

        SELECT @PNAME = PRODUCTNAME
        FROM
        (
            SELECT PRODUCTNAME, ROW_NUMBER() OVER(ORDER BY ID ASC) AS rownumber
            FROM VARIANTS
            WHERE PRODUCTNAME = ISNULL(@PRODUCTNAME, PRODUCTNAME) AND [User_ID] = @User_ID
        ) AS VARIANTS
        WHERE rownumber = @COUNT + 1

        SELECT @V_VALUE = isnull(V_VALUE,'')
        FROM
        (
            SELECT V_VALUE, ROW_NUMBER() OVER(ORDER BY ID ASC) AS rownumber
            FROM VARIANTS
            WHERE PRODUCTNAME = ISNULL(''/*@PRODUCTNAME*/, PRODUCTNAME) AND [User_ID] = 33097--@User_ID
        ) AS VARIANTS
        WHERE rownumber = @COUNT + 1

        SELECT @NAME = NAME
        FROM
        (
            SELECT NAME, ROW_NUMBER() OVER(ORDER BY ID ASC) AS rownumber
            FROM VARIANTS
            WHERE PRODUCTNAME = ISNULL(@PRODUCTNAME, PRODUCTNAME) AND [User_ID] = @User_ID
        ) AS VARIANTS
        WHERE rownumber = @COUNT + 1

        SELECT @PRICE = PRICE
        FROM
        (
            SELECT PRICE, ROW_NUMBER() OVER(ORDER BY ID ASC) AS rownumber
            FROM VARIANTS
            WHERE PRODUCTNAME = ISNULL(@PRODUCTNAME, PRODUCTNAME) AND [User_ID] = @User_ID
        ) AS VARIANTS
        WHERE rownumber = @COUNT + 1

        SELECT @StockKeepingUnit = StockKeepingUnit
        FROM
        (
            SELECT StockKeepingUnit, ROW_NUMBER() OVER(ORDER BY ID ASC) AS rownumber
            FROM VARIANTS
            WHERE PRODUCTNAME = ISNULL(@PRODUCTNAME, PRODUCTNAME) AND [User_ID] = @User_ID
        ) AS VARIANTS
        WHERE rownumber = @COUNT + 1

        SELECT @INVENTORY = INVENTORY
        FROM
        (
            SELECT INVENTORY, ROW_NUMBER() OVER(ORDER BY ID ASC) AS rownumber
            FROM VARIANTS
            WHERE PRODUCTNAME = ISNULL(@PRODUCTNAME, PRODUCTNAME) AND [User_ID] = @User_ID
        ) AS VARIANTS
        WHERE rownumber = @COUNT + 1

        SELECT @Barcode = Barcode
        FROM
        (
            SELECT Barcode, ROW_NUMBER() OVER(ORDER BY ID ASC) AS rownumber
            FROM VARIANTS
            WHERE PRODUCTNAME = @PRODUCTNAME AND [User_ID] = @User_ID
        ) AS VARIANTS
        WHERE rownumber = @COUNT + 1

        SELECT @Date = Date_Modified
        FROM
        (
            SELECT Date_Modified, ROW_NUMBER() OVER(ORDER BY ID ASC) AS rownumber
            FROM VARIANTS
            WHERE PRODUCTNAME = ISNULL(@PRODUCTNAME, PRODUCTNAME) AND [User_ID] = @User_ID
        ) AS VARIANTS
        WHERE rownumber = @COUNT + 1

        INSERT INTO #TEMP
        (V_VALUE, RNO, NAME, PRICE, StockKeepingUnit, INVENTORY, Barcode, ID, PRODUCTNAME, User_ID)
        SELECT *, @COUNT + 1, @NAME, @PRICE, @StockKeepingUnit, @INVENTORY, @Barcode, @ID, @PNAME, @User_ID
        FROM dbo.SplitString(LTRIM(RTRIM(@V_VALUE)), '#') 
		Where len(@V_VALUE) > 0

        SET @NAME = '';
        SET @V_VALUE = '';
        SET @COUNT = @COUNT + 1;
    END;

    IF @V_COUNT = 1
    BEGIN
        IF NOT EXISTS(SELECT * FROM Variant_detail v, #TEMP t WHERE v.PRODUCTNAME = t.PRODUCTNAME AND v.Variant_Name = T.NAME AND v.User_ID = t.User_ID)
        BEGIN
            INSERT INTO Variant_detail
            SELECT T.PRODUCTNAME, LTRIM(RTRIM(t.V_VALUE)) AS Variant, t.PRICE, t.StockKeepingUnit, t.INVENTORY, t.Barcode, T.User_ID, t.NAME, T.Date_Modified
            FROM #TEMP t;
        END;
        ELSE
        BEGIN
            DELETE v FROM Variant_detail v, #TEMP t WHERE v.PRODUCTNAME = t.PRODUCTNAME AND v.Variant_Name = T.NAME AND v.User_ID = t.User_ID;
            
			INSERT INTO Variant_detail
            SELECT T.PRODUCTNAME, LTRIM(RTRIM(t.V_VALUE)) AS Variant, t.PRICE, t.StockKeepingUnit, t.INVENTORY, t.Barcode, T.User_ID, t.NAME, T.Date_Modified
            FROM #TEMP t;
        END;
	END;
    ELSE
		IF @V_COUNT = 2
		BEGIN
			IF NOT EXISTS(SELECT * FROM Variant_detail v, #TEMP t WHERE v.PRODUCTNAME = t.PRODUCTNAME AND v.Variant_Name = T.NAME AND v.User_ID = t.User_ID)
			BEGIN
				INSERT INTO Variant_detail
				SELECT T1.PRODUCTNAME, LTRIM(RTRIM(T1.V_VALUE + '#' + T2.V_VALUE)) AS Variant, T1.PRICE, T1.StockKeepingUnit, T1.INVENTORY, T1.Barcode, 
						T1.User_ID, t1.NAME, T1.Date_Modified
				FROM #TEMP T1 CROSS JOIN #TEMP T2
				WHERE T1.NAME <> T2.NAME AND T1.RNO = 1 AND T2.RNO = 2;
			END;
			ELSE
			BEGIN
				DELETE v FROM Variant_detail v, #TEMP t WHERE v.PRODUCTNAME = t.PRODUCTNAME AND v.Variant_Name = T.NAME AND v.User_ID = t.User_ID;
	
				INSERT INTO Variant_detail
				SELECT T1.PRODUCTNAME, LTRIM(RTRIM(T1.V_VALUE + '#' + T2.V_VALUE)) AS Variant, T1.PRICE, T1.StockKeepingUnit, T1.INVENTORY, T1.Barcode, 
						T1.User_ID, t1.NAME, T1.Date_Modified
				FROM #TEMP T1 CROSS JOIN #TEMP T2
				WHERE T1.NAME <> T2.NAME AND T1.RNO = 1 AND T2.RNO = 2;
			END;
		END;
		ELSE
			IF @V_COUNT = 3
			BEGIN
				IF NOT EXISTS(SELECT * FROM Variant_detail v, #TEMP t WHERE v.PRODUCTNAME = t.PRODUCTNAME AND v.Variant_Name = T.NAME AND v.User_ID = t.User_ID)
				BEGIN
					INSERT INTO Variant_detail
					SELECT	T1.PRODUCTNAME, LTRIM(RTRIM(T1.V_VALUE + '#' + T2.V_VALUE + '#' + T3.V_VALUE)) AS Variant, T1.PRICE, T1.StockKeepingUnit, 
							T1.INVENTORY, T1.Barcode, T1.User_ID, t1.NAME, T1.Date_Modified
					FROM #TEMP T1 CROSS JOIN #TEMP T2 CROSS JOIN #TEMP T3
					WHERE T1.NAME <> T2.NAME AND T1.NAME <> T3.NAME AND T1.NAME <> T3.NAME AND T1.RNO = 1 AND T2.RNO = 2 AND T3.RNO = 3;
				END;
				ELSE
				BEGIN
					DELETE v FROM Variant_detail v, #TEMP t WHERE v.PRODUCTNAME = t.PRODUCTNAME AND v.Variant_Name = T.NAME AND v.User_ID = t.User_ID;

					INSERT INTO Variant_detail
					SELECT	T1.PRODUCTNAME, LTRIM(RTRIM(T1.V_VALUE + '#' + T2.V_VALUE + '#' + T3.V_VALUE)) AS Variant, T1.PRICE, T1.StockKeepingUnit, 
							T1.INVENTORY, T1.Barcode, T1.User_ID, t1.NAME, T1.Date_Modified
					FROM	#TEMP T1 CROSS JOIN #TEMP T2 CROSS JOIN #TEMP T3
					WHERE	T1.NAME <> T2.NAME AND T1.NAME <> T3.NAME AND T1.NAME <> T3.NAME AND T1.RNO = 1 AND T2.RNO = 2 AND T3.RNO = 3;
				END;
			END;

			SET @P1_Count = @P1_Count + 1;
		END;        

	IF(@PRODUCTNAME <> '')
    BEGIN
        SELECT DISTINCT p.ProductID ID, v.PRODUCTNAME PRODUCTNAME, v.Variant Variant, v.PRICE PRICE, v.StockKeepingUnit StockKeepingUnit, 
						v.INVENTORY INVENTORY, v.Barcode Barcode, v.User_ID User_ID, v.Variant_Name NAME, v.Date_Modified Date_Modified,
						Tax1=cast(round(isnull(p.Tax1,0)/100.0,2) as numeric(18,2)), TaxName1=isnull(p.TaxName1,'')
        FROM Variant_detail v(NOLOCK) LEFT OUTER JOIN Products p(NOLOCK) 
		ON	 v.PRODUCTNAME = p.Name AND v.User_ID = p.User_ID
        WHERE	v.User_ID = @User_ID AND (v.PRODUCTNAME IN ( SELECT Name FROM Products WHERE User_ID = @User_ID AND ProductAvailable = 1)
				OR v.PRODUCTNAME IN (SELECT Name FROM Products WHERE User_ID = @User_ID AND UnitInStock > 0))
				AND v.PRODUCTNAME LIKE '%' + @PRODUCTNAME + '%'
        UNION
        SELECT ProductID ID, Name PRODUCTNAME, '' Variant, UnitPrice PRICE, StockKeepingUnit StockKeepingUnit, UnitInStock INVENTORY, Barcode Barcode, 
               User_ID User_ID, '' NAME, CreatedDate Date_Modified, Tax1=cast(round(isnull(Tax1,0)/100.0,2) as numeric(18,2)), TaxName1=isnull(TaxName1,'')
        FROM	Products(NOLOCK)
        WHERE	User_ID = @User_ID AND (UnitInStock > 0 OR ProductAvailable = 1) AND Name LIKE '%' + @PRODUCTNAME + '%' 
				AND Name NOT IN (SELECT PRODUCTNAME FROM Variant_detail(NOLOCK) WHERE User_ID = @User_ID);
	END;
    ELSE
    BEGIN
        SELECT DISTINCT p.ProductID ID, v.PRODUCTNAME PRODUCTNAME, v.Variant Variant, v.PRICE PRICE, v.StockKeepingUnit StockKeepingUnit, 
               v.INVENTORY INVENTORY, v.Barcode Barcode, v.User_ID User_ID, v.Variant_Name NAME, v.Date_Modified Date_Modified,
			   Tax1=cast(round(isnull(p.Tax1,0)/100.0,2) as numeric(18,2)), TaxName1=isnull(p.TaxName1,'')
        FROM Variant_detail v(NOLOCK) LEFT OUTER JOIN Products p(NOLOCK) 
		ON	 v.PRODUCTNAME = p.Name AND v.User_ID = p.User_ID
        WHERE	v.User_ID = @User_ID AND (v.PRODUCTNAME IN (SELECT Name FROM Products WHERE User_ID = @User_ID AND ProductAvailable = 1)
                OR v.PRODUCTNAME IN (SELECT Name FROM Products WHERE User_ID = @User_ID AND UnitInStock > 0))
        UNION
        SELECT ProductID ID, Name PRODUCTNAME, '' Variant, UnitPrice PRICE, StockKeepingUnit StockKeepingUnit, UnitInStock INVENTORY, Barcode Barcode, 
               User_ID User_ID, '' NAME, CreatedDate Date_Modified, Tax1=cast(round(isnull(Tax1,0)/100.0,2) as numeric(18,2)), TaxName1=isnull(TaxName1,'')
        FROM Products(NOLOCK)
        WHERE User_ID = @User_ID AND (UnitInStock > 0 OR ProductAvailable = 1)
              AND Name NOT IN (SELECT PRODUCTNAME FROM Variant_detail(NOLOCK) WHERE User_ID = @User_ID);
	END;

	DROP TABLE #TEMP;
	DROP TABLE #temp2;

end 



