/* ============================================================
   Procedure: [dbo].[usp_et_ClientVisitReportList]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_et_ClientVisitReportList](
	@SearchText varchar(200) = '',
	@Contain varchar(200) = '',
	@FromDate nvarchar(100),
	@ToDate nvarchar(100),
	@UserId bigint,
	@UserIds nvarchar(max) = '',
	@Offset int = 0,
	@PageSize int = 10 
)
as
begin	
	--declare
	--	@SearchText varchar(200) = '',
	--	@Contain varchar(200) = '',
	--	@FromDate nvarchar(100) = N'01-Aug-2024',
	--	@ToDate nvarchar(100) = N'01-Aug-2024',
	--	@UserId bigint = 45900, --42812,
	--	@UserIds nvarchar(max) = '46000',
	--	@Offset int = 0,
	--	@PageSize int = 10 
	

	declare @ParentId bigint, @isAdmin bit = 0
	
	select @ParentId = ParentId, @isAdmin = IsAdmin from User_Detail(nolock) where User_Id = @UserId

	drop table if exists #tempUsers  
	create table #tempUsers(User_ID bigint, Name nvarchar(255), Image nvarchar(255))  
	insert into #tempUsers(User_ID, Name, Image)  
	exec Use_GetUserDetails @UserID = @UserId  

	if(ISNULL(@UserIds, '') =  '') begin set @UserIds = '' end

	drop table if exists #tempSelectedUser
	create table #tempSelectedUser ( UserId bigint )
	insert into #tempSelectedUser(UserId) select [value] from string_split(@UserIds, ',')
	
	declare @StartPoint int  = (@Offset + 1), @EndPoint int  = (@Offset + @PageSize)


	declare @SqlQuery nvarchar(max) = concat(N'select * from ( select ',
		N'count(t.User_Id) over() as TotalRecords, ',
		N'ROW_NUMBER() over (partition by (select null) order by (select null) asc  ) as SNo, ',
		N'AssignedToName, User_Id, ',
		N'count(t.PhysicalAppointmentId) TotalAssigned, ',
		N'count(isnull(t.GeoEntityCheckId, 0)) TotalVisit, ',
		N'dbo.fn_TBL_ET_PhysicalAppointmentTypeCount(User_Id, ', 
			N'''', @FromDate, ''', ''', @ToDate, ''', ''Missed'') TotalMissed, ',
		N'dbo.fn_TBL_ET_PhysicalAppointmentTypeCount(User_Id, ', 
			N'''', @FromDate, ''', ''', @ToDate, ''', ''Pending'')  TotalPending, ',
		N'max(t.User_Login) as [User_Login], ',
		N'max(t.UserFullName) as [UserFullName] ',
	N'from ( ',
		N'select distinct tepa.PhysicalAppointmentId, ', 
		N' concat( ud.FName, '' '', ud.LName, '' ('', ud.User_Login, '')'' )  AssignedToName, ',
		 N'ud.User_Login,  isnull(ud.FName,'''') + '' '' + isnull(ud.LName,'''')  as [UserFullName] ,',
		N'ud.User_Id, tepa.Title, tepa.Description, tepa.Address, ',
		N'tepa.CompleteAddress, ',
		N'isnull(geci.GeoEntityCheckId, 0) GeoEntityCheckId ',
		N'from TBL_ET_PhysicalAppointment(nolock) tepa ',
			N'inner join #tempUsers tu on tepa.AssignedTo = tu.User_ID ',
			(case when exists(select 1 from #tempSelectedUser) 
				then N'inner join #tempSelectedUser su on tepa.AssignedTo = su.UserId '
			else '' end ),
			N'left join User_Detail(nolock) ud on tepa.AssignedTo = ud.User_ID ',
			N'left join FollowUp_Status(nolock) fuss on tepa.OutcomesId = fuss.ID ',
			N'left join TBL_ET_GeoEntityCheckInOut(nolock) geci on tepa.PhysicalAppointmentId = geci.PhysicalAppointmentId ',
			N'inner join TBL_ET_PhyAppointUserMapping(nolock) trpu on tepa.PhysicalAppointmentId = geci.PhysicalAppointmentId ',
		N'where ((cast(geci.CheckIn as date) between cast(''', @FromDate, ''' as date) and cast(''', @ToDate, ''' as date)) ',
		N'or (cast(geci.CheckOut as date) between cast(''', @FromDate, ''' as date) and cast(''', @ToDate, ''' as date))) ',
		N'and ( concat(ud.FName, '' '', ud.LName, '' ('', ud.User_Login, '')'') like ''%', @SearchText, '%'')  ',
		N' or Title like ''%', @SearchText, '%'' ) ', 
	N' t group by AssignedToName, User_Id ) t where t.SNo between ', @StartPoint, ' and ', @EndPoint )

	print @SqlQuery


	execute sp_executesql @SqlQuery

end




GO

/* ============================================================
   Procedure: [dbo].[usp_et_ClientVisitReportList_Cache]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE [dbo].[usp_et_ClientVisitReportList_Cache](
	@SearchText varchar(200) = '',
	@Contain varchar(200) = '',
	@FromDate nvarchar(100),
	@ToDate nvarchar(100),
	@UserId bigint,
	@UserIds nvarchar(max) = '',
	@Offset int = 0,
	@PageSize int = 10 
)
as
begin	
				DECLARE @MonthStart DATETIME;
				DECLARE @MonthEnd DATETIME;
				declare @ParentID bigint = 0;	

			select @ParentID = ParentID from Mysms.[dbo].User_Detail(nolock) where User_ID = @UserId;

				-- Get the first and last date of the current month
				--SET @MonthStart = FORMAT(DATEADD(DAY, 1 - DAY(GETDATE()), CAST(GETDATE() AS DATE)), 'dd-MMM-yyyy'); -- First day of current month
				--SET @MonthEnd = FORMAT(EOMONTH(GETDATE()), 'dd-MMM-yyyy'); -- Last day of current month

				Declare @Currentdate  DATE  = GETDATE();  -- Today's date
				SET @MonthStart      = FORMAT(DATEADD(DAY, -30, @Currentdate), 'dd-MMM-yyyy'); -- 30 days before today
				SET @MonthEnd  =  FORMAT(DATEADD(DAY, -1, @Currentdate), 'dd-MMM-yyyy');

				--if(ISNULL(@UserIds, '') =  '') begin set @UserIds = '' end

				-- Check conditions and select data
			IF (@FromDate Between @MonthStart AND @MonthEnd AND @ToDate Between @MonthStart AND @MonthEnd)  
				BEGIN
					 SELECT [ClientVisitReportId]
					  ,[TotalRecords]
					  ,[SNo]
					  ,[AssignedToName]
					  ,[User_Id]
					  ,[TotalAssigned]
					  ,[TotalVisit]
					  ,[TotalMissed]
					  ,[TotalPending]
					  ,[User_Login]
					  ,[UserFullName]
					  ,[UserId]
					  ,[ParentId]
					 FROM [dbo].[tbl_ClientVisitReport_Cache](nolock)
						WHERE [UserId]= @UserId  and [ParentId] = @ParentId
				END
			ELSE IF (@FromDate < @MonthStart OR @ToDate < @MonthStart)
				BEGIN
					SELECT [ClientVisitReportId]
					  ,[TotalRecords]
					  ,[SNo]
					  ,[AssignedToName]
					  ,[User_Id]
					  ,[TotalAssigned]
					  ,[TotalVisit]
					  ,[TotalMissed]
					  ,[TotalPending]
					  ,[User_Login]
					  ,[UserFullName]
					  ,[UserId]
					  ,[ParentId]
					 FROM [dbo].[tbl_ClientVisitReport_Archive](nolock)
						WHERE [UserId]= @UserId  and [ParentId] = @ParentId
				END
			ELSE
				BEGIN
					EXEC [Mysms].[dbo].usp_et_ClientVisitReportList @SearchText, @Contain, @FromDate, @ToDate, @UserId, @UserIds, @Offset, @PageSize;
				END

end



