/* ============================================================
   Procedure: [dbo].[usp_et_ExpenseClaimAttachmentHandler]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_et_ExpenseClaimAttachmentHandler(
	@Mode nvarchar(5) = '',
	@ExpenseClaimId bigint,
	@FileName nvarchar(max) = null,
	@FileType nvarchar(max) = null,
	@FileUrl nvarchar(max) = null,
	@EcaId bigint = 0,
	@CreatedBy  bigint = 0
)
as
begin
	if(@Mode = 'LS')
	begin
		select id as Id, file_name as FileName, file_type as FileType, file_url as FileUrl
			from TBL_ET_ExpenseClaimAttachments(nolock) 
			where expense_claim_id = @ExpenseClaimId and is_deleted = 0
	end
	else 
	begin
		select id as Id, file_name as FileName, file_type as FileType, file_url as FileUrl
			from TBL_ET_ExpenseClaimAttachments(nolock) 
			where expense_claim_id = 0
	end

	if(@Mode = 'IN')
	begin
		insert into TBL_ET_ExpenseClaimAttachments ( file_name, file_type, file_url, created_by, expense_claim_id )
			values ( @FileName, @FileType, @FileUrl, @CreatedBy, @ExpenseClaimId )

		select 'inserted'
	end

	if(@Mode = 'DE')
	begin
		update TBL_ET_ExpenseClaimAttachments set is_deleted = 1 where id = @EcaId
		select 'deleted'
	end


end



GO

/* ============================================================
   Procedure: [dbo].[usp_et_ExpenseRequestApprovalList]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_et_ExpenseRequestApprovalList(
	@Mode nvarchar(max) = 'all',
	@SearchText nvarchar(max) = '',
	@Condition varchar(20) = '',
	@FromDate date,
	@ToDate date,
	@UserId bigint,
	@UserIds nvarchar(max) = '',
	@OffsetValue int = 0,
	@PagingSize int = 100
)
as
begin
	
	--declare
	--	@Mode nvarchar(max) = 'all',
	--	@SearchText nvarchar(max) = '',
	--	@Condition varchar(20) = 'StartWith',
	--	@FromDate date = '01-Jan-2023',
	--	@ToDate date = '02-Feb-2024',
	--	@UserId bigint = 34594,
	--	@UserIds nvarchar(max) = '',
	--	@OffsetValue int = 0,
	--	@PagingSize int = 100
		
	declare @ParentId bigint = 0
	select @ParentId = ParentID from User_Detail(nolock) where User_Id = @UserId

	drop table if exists #tempUsers  
	create table #tempUsers(User_ID bigint, Name nvarchar(255), Image nvarchar(255))  
	insert into #tempUsers(User_ID, Name, Image)  
	exec Use_GetUserDetails @UserID = @UserId  

	if(ISNULL(@UserIds, '') =  '') begin set @UserIds = '' end

	drop table if exists #tempSelectedUser
	create table #tempSelectedUser ( UserId bigint )
	insert into #tempSelectedUser(UserId) select [value] from string_split(@UserIds, ',')
	
	declare @StartPoint int  = (@OffsetValue + 1), @EndPoint int = ( @OffsetValue + @PagingSize )

	declare @sqlQuery nvarchar(max),  @sqlQuery1 nvarchar(max), @sqlFinalQuery nvarchar(max)

	set @sqlQuery = concat( N'select SNo, TotalRecords, ApproverDate, Cast(RequestDate as varchar(20)) RequestDate, ',
		N'IconClass, ExpenseApprovalId, ExpenseClaimId, ExpenseHeadId, ExpenseHeadName, ',
		N'UserId, UserFullName, CreatedFullName, Cast(FromDate as varchar(11)) FromDate, Cast(ToDate as varchar(11)) ToDate, ',
		N'NoOfVisits, TotalKMs, ClaimAmount, SuccessfullVisit, FailedVisit, Reimbursement, TotalAmount, AttachDocuments, ',
		N'AttachDocuments AttachDocumentsUrl, Remarks, ApproverStatus, ApproverRemarks, ApproverFullName, ApprovedAmount, ',
		N'ApproverDate, Cast(RequestDate as varchar(20)) RequestDate, t.ParentId, t.CreatedDate, t.CreatedBy, t.UpdatedDate, ', 
		N't.UpdatedBy, t.IsActive, SiteName1, SiteName2, BranchAddress, LastLoginAttendanceIn ',
		N'from ( select ',
			N'ROW_NUMBER() over(partition by (select null) order by bm.ExpenseClaimId desc) SNo, ',
			N'count(bm.ParentId) over() as TotalRecords, ',
			N'ea.ExpenseApprovalId, eh.IconClass, bm.ExpenseClaimId, bm.ExpenseHeadId, eh.ExpenseHeadName, ',
			N'bm.UserId, concat(ud.FName, '' '', isnull(ud.LName, '''')) UserFullName, ',
			N'concat(ud2.FName, '' '', isnull(ud2.LName, '''')) CreatedFullName, FromDate, ToDate, NoOfVisits, TotalKMs, ClaimAmount, ',
			N'SuccessfullVisit, FailedVisit, Reimbursement, TotalAmount, AttachDocuments, Remarks, ',
			N'(case  when isnull(ea.ApproverStatus, '''') = '''' then ''Pending'' ',
				N'when isnull(ea.ApproverStatus, '''') <> '''' and ea.ApproverStatus = ''Rejected'' then ''Rejected'' ',
				N'when isnull(ea.ApproverStatus, '''') <> '''' and ea.ApproverStatus = ''Approved''  ',
					N'and isnull(bm.ClaimAmount, 0) - ISNULL(ea.ApprovedAmount, 0) > 0 then ''Partial''  ',
				N'when isnull(ea.ApproverStatus, '''') <> ''''  ',
					N'and ea.ApproverStatus = ''Approved'' then ''Approved'' else ''Pending'' end ) ApproverStatus, ',
			N'isnull(ea.ApproverRemarks, '''') ApproverRemarks, ApprovedAmount, ',
			N'concat(isnull(uda.FName, ''''), '' '', isnull(uda.LName, '''')) ApproverFullName, ',
			N'(case when ea.UpdatedDate is null then ea.CreatedDate else ea.UpdatedDate end) ApproverDate, ',
			N'(case when bm.UpdatedDate is null then bm.CreatedDate else bm.UpdatedDate end) RequestDate, ',
			N'bm.ParentId, bm.CreatedDate, bm.CreatedBy, bm.UpdatedDate, bm.UpdatedBy, bm.IsActive, ',
			N'isnull(bm.SiteId1, 0) SiteId1, isnull(bm.SiteId2, 0) SiteId2, isnull(esm2.GeoEntitySiteName, '''') SiteName1, ',
			N'isnull(esm2.GeoEntitySiteName, '''') SiteName2, ',
			N'concat(isnull(iutn.Address, ''''), '', '', isnull(ct.City_Name, ''''), '', '', isnull(st.State_Name, ''''), '', '',  ',
				N'isnull(co.Country_Name, '''')) BranchAddress, ',
			N'(select top 1 isnull(CONVERT(VARCHAR, AttendanceIn, 100), '''') from TBL_ET_Attendance(nolock) ia ',
				N'where ia.UserId = bm.UserId order by 1 desc) LastLoginAttendanceIn  ' )
	set @sqlQuery1 = concat( N'from TBL_ET_ExpenseClaim (nolock) bm  ',
			N'inner join #tempUsers tu on bm.UserId = tu.User_ID ',
			iif(LEN(@UserIds) > 0, 'inner join #tempSelectedUser  su on bm.UserId = su.UserId ', ''),
			N'inner join User_detail(nolock) ud on bm.UserId = ud.User_Id ',
			N'inner join User_detail(nolock) ud2 on bm.CreatedBy = ud2.User_Id ',
			N'left join TBL_ET_ExpenseApproval(nolock) ea on bm.ExpenseClaimId = ea.ExpenseClaimId ',
			N'left join User_detail(nolock) uda on ea.ApproverUserId = uda.User_Id ',
			N'inner join TBL_ET_ExpenseHead(nolock) eh on bm.ExpenseHeadId = eh.ExpenseHeadId ',
			N'left join TBL_ET_GeoEntitySiteMaster(nolock) esm1 on bm.SiteId1 = esm1.GeoEntitySiteId ',
			N'left join TBL_ET_GeoEntitySiteMaster(nolock) esm2 on bm.SiteId2 = esm2.GeoEntitySiteId ',
			N'left join TBL_ET_AttendanceGroupUserMapping(nolock) agum on bm.UserId = agum.UserId ',
			N'left join tbl_inv_UserTaxNumber(nolock) iutn on agum.UserBranchId = iutn.Id ',
			N'left join M_City(nolock) ct on iutn.City_Id = ct.City_Id ',
			N'left join M_State(nolock) st on iutn.State_Id = st.State_Id ', 
			N'left join M_Country(nolock) co on iutn.Country_Id = co.Country_Id ',
		N'where  bm.ParentId = ', @ParentId, 
			N' and ( cast(FromDate as date) between cast(''', @FromDate, ''' as date) and cast(''',
				@ToDate, ''' as date) ',
			N'or cast(ToDate as date) between cast(''', @FromDate, ''' as date) and cast(''',
				@ToDate, ''' as date)  ) ',
			N' and 1 = ( case ',
				N'when ''', @Mode, ''' = ''all'' then 1 ',
				N'when ''', @Mode, ''' = ''pending'' and ISNULL(ea.ApproverStatus, '''')  = '''' then 1 ',
				N'when ''', @Mode, ''' = ''approved'' and ISNULL(ea.ApproverStatus, '''')  <> '''' ',
					N'and ea.ApproverStatus = ''Approved'' then 1 ',
				N'when ''', @Mode, ''' = ''rejected'' and ISNULL(ea.ApproverStatus, '''')  <> '''' ',
					N'and ea.ApproverStatus = ''Rejected'' then 1 ',
				N'when ''', @Mode, ''' = ''partial'' and ISNULL(ea.ApproverStatus, '''')  <> '''' ',
					N'and ea.ApproverStatus = ''Approved'' ',
					N'and isnull(bm.ClaimAmount, 0) - ISNULL(ea.ApprovedAmount, 0) > 0 then 1 ',
			N'else 0 end ) ',
		N') t where t.SNo between ', @StartPoint, ' and ', @EndPoint )

	print @sqlQuery 
	print @sqlQuery1

	set @sqlFinalQuery = @sqlQuery + @sqlQuery1

	execute sp_executesql @sqlFinalQuery

end



GO

/* ============================================================
   Procedure: [dbo].[usp_et_ExportVisitReports]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE [dbo].[usp_et_ExportVisitReports](  
 @FromDate date,      
 @ToDate date,      
 @SearchText nvarchar(255) = '',    
 @SortType nvarchar(255) = null,  
 @UserId bigint,  
 @UserIds nvarchar(max) = ''  
)  
as  begin  
  
 --declare       
 -- @FromDate date = N'01-Apr-2024',      
 -- @ToDate date = '30-Apr-2024',      
 -- @SearchText nvarchar(255),      
 -- @SortType nvarchar(255) = 'asc',  
 -- @UserId bigint = 43966,  
 -- @UserIds nvarchar(max) = N''
  
  
 declare @ParentId bigint  
 select @ParentId = ParentID from User_Detail(nolock) u where u.User_ID = @UserId  
 if(isnull(@SortType, '') = '')  
 begin  
  set @SortType = 'asc'  
 end  
  
  
  
 drop table if exists #tempUsers  
 create table #tempUsers(User_ID bigint, Name nvarchar(255), Image nvarchar(255))    
 insert into #tempUsers(User_ID, Name, Image)    
 exec Use_GetUserDetails @UserID = @UserId    
  
 if(ISNULL(@UserIds, '') =  '') begin set @UserIds = '' end  
  
 drop table if exists #tempSelectedUser  
 create table #tempSelectedUser (UserId bigint )  
 insert into #tempSelectedUser(UserId) select [value] from string_split(@UserIds, ',')  
  
 declare @sqlQuery nvarchar(max) = concat(N'select ',  
  N'row_number() over ( partition by (select null) ',   
  N'order by lc.UserId, lc.LocationDateTime ', @SortType, N' ) as [SNo], ',  
  N'format(lc.LocationDateTime, ''dd-MMM-yyyy'') as [VisitDate], ',  
  N'format(lc.LocationDateTime, ''HH:mm:ss'') as [VisitTime], ',  
  N'concat(u.User_Login, '' ('', u.FName, '' '', u.LName, '')'') as [AgentName], ',  
  N'u.User_Login,  isnull(u.FName,'''') + '' '' + isnull(u.LName,'''')  as [User FullName] ,',
  N't.TerritoryName, t.TerritoryManager, ',  
  N'lc.MovementCode as [EventName], lc.Address, TRY_CONVERT(decimal(18, 3), ',  
  N'TRY_CONVERT(decimal(18, 3),lc.Distance) /1000) as [Distance], ',  
  N'lc.BatteryPerc, lc.NetworkPerc, ',  
  N'format(TRY_CONVERT(datetime, ( lc.LocationDateTime - (lag(lc.LocationDateTime, 1, lc.LocationDateTime) ',  
   N'over (partition by lc.UserId, cast(LocationDateTime as date) order by lc.UserId, lc.LocationDateTime) ',  
  N'))), ''HH:mm:ss'') as [Hours] ',  
  N'from ( ',  
  --N'select s.UserId, s.MovementCode, s.LocationDateTime, s.Latitude, s.Longitude, s.Address, s.Distance, ',  
  -- N's.BatteryPerc, s.NetworkPerc from ( select  u.UserId, u.MovementCode, u.LocationDateTime, u.Latitude, u.Longitude, ',  
  -- N'u.Address, u.Distance, u.BatteryPerc, u.NetworkPerc, row_number() over(partition by u.UserId, ',  
  -- N'cast(u.LocationDateTime as date) order by u.LocationDateTime asc ) as [rno] ',  
  -- N'from TBL_ET_UserLocationTracking(nolock) u ',  
  -- N'inner join #tempUsers tu on u.UserId = tu.User_Id ',
  -- iif(LEN(@UserIds) > 0, 'inner join #tempSelectedUser su on u.UserId = su.UserId ', ''),  
  --  N'where cast(LocationDateTime as date) between ''', @FromDate,''' and ''', @ToDate, ''' ',  
  -- N'and trim(lower(MovementCode))  = ''sign_in'' ) s  where s.rno = 1 ',  
  --N'union ',  
  N'select s.UserId, s.MovementCode, s.LocationDateTime, s.Latitude, s.Longitude, s.Address, s.Distance,  ',  
   N's.BatteryPerc, s.NetworkPerc from ( select  u.UserId, u.MovementCode, u.LocationDateTime, u.Latitude, u.Longitude, ',  
   N'u.Address, u.Distance, u.BatteryPerc, u.NetworkPerc, row_number() over(partition by u.UserId, ',  
   N'cast(u.LocationDateTime as date) order by u.LocationDateTime desc ) as [rno] ',  
   N'from ( ',
			N'select l.UserId, l.MovementCode, l.LocationDateTime, l.Latitude, l.Longitude, ',  
				N'l.Address, l.Distance, l.BatteryPerc, l.NetworkPerc ',
			N' from TBL_ET_UserLocationTracking(nolock) l inner join #tempUsers tu on l.UserId = tu.User_ID ',
			N' where cast(l.LocationDateTime as date) between ''', @FromDate, ''' and ''', @ToDate , '''',
			N' union ',
			N'select l.UserId, l.MovementCode, l.LocationDateTime, l.Latitude, l.Longitude, ',  
				N'l.Address, l.Distance, l.BatteryPerc, l.NetworkPerc ',
			N' from TBL_ET_UserLocationTracking_Archived(nolock) l inner join #tempUsers tu on l.UserId = tu.User_ID ',
			N' where cast(l.LocationDateTime as date) between ''', @FromDate, ''' and ''', @ToDate , '''',
		N') u ',  
   N'inner join #tempUsers tu on u.UserId = tu.User_Id ',
   iif(LEN(@UserIds) > 0, 'inner join #tempSelectedUser su on u.UserId = su.UserId ', ''),  
    N'where cast(LocationDateTime as date) between ''', @FromDate,''' and ''', @ToDate, ''' ',  
   N'and trim(lower(MovementCode)) in (''sign_in'', ''break_in'', ''check_in'',  ''check_out'', ''break_out'', ''sign_out'' )) s ',  
   /*
	Showing all movement code as per requiredment
   */

  --N'union ',  
  --N'select s.UserId, s.MovementCode, s.LocationDateTime, s.Latitude, s.Longitude, s.Address, s.Distance, ',   
  -- N's.BatteryPerc, s.NetworkPerc from ( select  u.UserId, u.MovementCode, u.LocationDateTime, u.Latitude, u.Longitude, ',  
  -- N'u.Address, u.Distance, u.BatteryPerc, u.NetworkPerc, row_number() over(partition by u.UserId, ',  
  -- N'cast(u.LocationDateTime as date) order by u.LocationDateTime desc ) as [rno] ',  
  -- N'from TBL_ET_UserLocationTracking(nolock)  u ',  
  -- N'inner join #tempUsers tu on u.UserId = tu.User_Id ',
  -- iif(LEN(@UserIds) > 0, 'inner join #tempSelectedUser su on u.UserId = su.UserId ', ''),  
  --  N'where cast(LocationDateTime as date) between ''', @FromDate,''' and ''', @ToDate, '''  ',  
  -- N'and trim(lower(MovementCode))  = ''sign_out'' ) s  where s.rno = 1 ',  
 N') lc  ',  
 N'inner join User_Detail(nolock) u on lc.UserId = u.User_ID ',  
 N'left join TBL_UA_UserRoleMappingMaster(nolock) rm on u.User_ID = rm.UserId and rm.Active = 1 ',  
 N'left join TBL_UA_RoleMaster(nolock) r on rm.RoleCode = r.RoleCode and rm.ParentID = r.ParentId and rm.Active = 1 ',  
 N'left join ( ',  
  N'select um.UserId, ',  
  N'STRING_AGG(concat( ut.User_Login, ''('', ut.FName, '' '', ut.LName, '')''), '', '') as [TerritoryManager], ',  
  N'STRING_AGG( m.TerritoryName, '', '') as [TerritoryName] ',  
   N'from TBL_ET_TerritoryUserMapping(nolock) um ',  
   N'inner join TBL_ET_TerritoryMaster(nolock) m on um.TerritoryId = m.TerritoryId ',  
   N'inner join User_Detail(nolock) ut on um.UserId = ut.User_ID ',  
    N'where um.IsActive = 1 and um.IsManager = 1 ',  
  N'group by um.UserId ) t on t.UserId = lc.UserId ',  
 N'where u.ParentId = ', @ParentId, N' order by lc.LocationDateTime ', @SortType )  
  
 print @sqlQuery  
  
 execute sp_executesql @sqlQuery  
  
end 




