/* ============================================================
   Procedure: [dbo].[usp_et_GenerateGpsOnOffActivity]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE  PROCEDURE [dbo].[usp_et_GenerateGpsOnOffActivity](
	@dtInsertedRecord tblScheduleIds readonly
)
as
begin
	
	begin try
		--declare 
		--	@dtInsertedRecord as  tblScheduleIds
		--insert into @dtInsertedRecord (ScheduledId)
		--	values (23907788),(23907789),(23907818),(23907843),(23907866),(23907912)

		begin transaction

		drop table if exists #tempInsertedRec

		select l.UserLocationTrackingId, l.MovementCode, l.LocationDateTime, l.UserId, 
			ROW_NUMBER() over(partition by UserId, MovementCode order by LocationDateTime asc) as rowNo
			into #tempInsertedRec 
				from @dtInsertedRecord i 
			inner join TBL_ET_UserLocationTracking(nolock) l on i.ScheduledId = l.UserLocationTrackingId
				where l.MovementCode in ( 'GPS_OFF', 'GPS_ON') order by LocationDateTime asc

		delete from #tempInsertedRec where rowNo  > 1

		delete r from #tempInsertedRec r 
			inner join V_TBL_ET_UserLocationGpsHistory t 
				on t.UserId = r.UserId and cast(r.LocationDateTime as date) =  cast(t.CreatedOn as date)

		if(exists(select top 1 * from #tempInsertedRec))
		begin
	
			drop table if exists #iGPS
			create table #iGPS (
				refId bigint,
				MovementCode nvarchar(25),
				LocationDateTime datetime,
				UserId bigint,
				ParentId bigint
			)
		
			insert into TBL_ET_UserLocationGpsHistory( UserLocationTrackingId, MovementCode, UserId, ParentId, CreatedOn )
				output inserted.id as [refId], inserted.MovementCode, inserted.CreatedOn, inserted.UserId	, inserted.ParentId into #iGPS
			select r.UserLocationTrackingId, r.MovementCode, r.UserId, u.ParentID, r.LocationDateTime
				from #tempInsertedRec r inner join User_Detail(nolock)  u on r.UserId = u.User_ID where rowNo = 1

			declare @tblActivity as LeadActivitywithid_Tbltype

			insert into @tblActivity(LeadID, UserID	, ParentID, EventDescription, EventName, RefTable, refid)
			select 0, d.UserId, d.ParentId, 
				concat(u.User_Login, ' - GPS is turned ', (case when d.MovementCode = 'GPS_OFF' then 'off' else 'on' end), ' at ', format(d.LocationDateTime, 'dd-MMM-yyyy HH:mm:ss' )),
				d.MovementCode, 'TBL_ET_UserLocationGpsHistory', d.refId
			from #iGPS d inner join User_Detail(nolock) u on d.UserId = u.User_ID


			--select * from @tblActivity
	
			exec UspSaveentityActivity_withMultipleValue_withid_bulk @tblActivity

			commit transaction
		end
	end try
	begin catch
		rollback transaction
		exec usp_InsertErrorInfo
	end catch

end



GO

/* ============================================================
   Procedure: [dbo].[usp_et_GetDashboardVisitReport]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_et_GetDashboardVisitReport](
	@FromDate date,      
	@ToDate date,      
	@SearchText nvarchar(max) = null,      
	@UserId bigint,      
	@Contain nvarchar(max) = null, 
	@SortType nvarchar(max) = null,
	@UserIds nvarchar(max) = null,
	@Offset int  = 0,      
	@PageSize int = 100      
)      
as      
begin      
      
	--declare       
	--	@FromDate date = N'2023-12-21',
	--	@ToDate date = N'2023-12-27',
	--	@SearchText nvarchar(255) = N'',
	--	@SortType nvarchar(max) = 'asc',
	--	@UserId bigint = 34594, 
	--	@UserIds nvarchar(max) = '34594',
	--	@Offset int  = 0,      
	--	@PageSize int = 10      
      
	 declare @ParentId bigint  
	 select @ParentId = ParentID from User_Detail(nolock) u where u.User_ID = @UserId  
	 print concat('@ParentId => ', @ParentId) 
 
	 if(isnull(@SortType, '') = '')
	 begin
		set @SortType = 'asc'
	 end

	 drop table if exists #tempUsers   
	 create table #tempUsers(User_ID bigint, Name nvarchar(255), Image nvarchar(255))  
	 insert into #tempUsers(User_ID, Name, Image)  
	 exec Use_GetUserDetails @UserID = @UserId  

	 if(ISNULL(@UserIds, '') =  '') begin set @UserIds = '' end

	 drop table if exists #tempSelectedUser
	 create table #tempSelectedUser ( UserId bigint )
	 insert into #tempSelectedUser(UserId) select [value] from string_split(@UserIds, ',')
    
	 declare @sqlQuery nvarchar(max) = concat(N'select distinct TOP 10 ',
		N'format(a.AttandanceDate, ''dd-MMM-yyyy'') as [AttandanceDate], ',
		N'a.UserId, ',
		N'format(a.SignIn, ''hh:mm tt'') as [SignIn], ',
		N'format(a.SignOut, ''hh:mm tt'') as [SignOut], ',
		N'(dbo.udf_GetTerritoryDefination(a.UserId)) AS [TerritoryDefination], ',
		N'u.User_ID as [AgentId], ',
		N'concat(u.User_Login, ''('', u.FName, '' '', u.LName, '')'') as [AgentName], ',
		N'c.CheckInCount, ',
		N'c.CheckOutCount, ',
		N'r.RoleName, ',
		N'ROUND(TRY_CONVERT(decimal(18, 3), isnull((select Max(cast(isnull(Distance, 0) as float)) from TBL_ET_UserLocationTracking(nolock) t ',
		N'where cast(t.LocationDateTime as date) = cast(a.AttandanceDate as date) and t.UserId = a.UserId ), 0)) /1000, 3) as [Distance], ',
		N'format(TRY_CONVERT(DATETIME, a.SignOut - a.SignIn), ''HH:mm:ss'') as [Hours] ',
		N'from v_VRAttendance a ',
		N'inner join User_Detail(nolock) u on a.UserId = u.User_ID ',
		iif(LEN(@UserIds) > 0, 'inner join #tempSelectedUser su on u.User_Id = su.UserId ', ''),
		N'left join TBL_UA_UserRoleMappingMaster(nolock) rm on u.User_ID = rm.UserId and rm.Active = 1 ',
		N'left join TBL_UA_RoleMaster(nolock) r on rm.RoleCode = r.RoleCode ',
		N'and rm.ParentID = r.ParentId and rm.Active = 1 ',
		N'left join v_VRACheckInOutCount(nolock) c on a.UserId = c.UserId and a.AttandanceDate = c.CheckInOutDate ',
		N'where a.ParentId = ', @ParentId, 
		N'and 1 = (case ',
		N'when u.User_Login like ''%', @SearchText, '%'' then 1 ',
		N'when u.FName like ''%', @SearchText, '%'' then 1 ',
		N'when u.LName like ''%', @SearchText, '%'' then 1 ',
		N'when u.Mobile like ''%', @SearchText, '%'' then 1 ',
		N'when u.EMail like ''%', @SearchText, '%'' then 1 ',
		N'else 0 end ) ',
		N' and cast(a.AttandanceDate as date) between ''', @FromDate, N''' and ''',  @ToDate,
		N'''' )

	  print @sqlQuery
  
	  execute sp_executesql @sqlQuery

end


GO

/* ============================================================
   Procedure: [dbo].[usp_et_GetDayScheduleActivities]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_et_GetDayScheduleActivities
(
	@PunchedDate date,
	@UserId bigint
)
as
begin
	--declare 
	--		@PunchedDate date = N'28-Apr-2024 20:37',
	--		@UserId bigint = 43973


	declare @tempActivity as table(
		Id bigint identity (1,1),
		RecordId bigint,
		RecordType nvarchar(50),
		Title nvarchar(255),
		StartTime datetime,
		EndTime datetime,
		ActivityTime datetime,
		MovementCode nvarchar(max),
		ScheduledAddress nvarchar(255),	
		ActualStartTime datetime,
		ActualEndTime datetime,
		ActualAddress nvarchar(255),
		GeoEntitySiteName nvarchar(255),
		FieldExecutiveImage nvarchar(255),
		FieldExecutiveName nvarchar(255),
		OutcomeName nvarchar(255),
		OutcomeIntent nvarchar(255),
		ActualStatus nvarchar(255),
		Remarks nvarchar(max),
		UserId bigint
	)

	insert into @tempActivity (RecordId, RecordType, Title, StartTime, EndTime, ActivityTime,
		OutcomeName, OutcomeIntent, MovementCode, UserId, ScheduledAddress, GeoEntitySiteName)
	select 
		pa.PhysicalAppointmentId as [RecordId], 'PhysicalAppointment' as [RecordType], pa.Title, pa.StartDate, pa.EndDate, 
			pa.StartDate as [ActivityTime], o.OutcomeName, o.Indent, 'APPOINTMENT', um.UserId, pa.Address, s.GeoEntitySiteName
		from TBL_ET_PhysicalAppointment(nolock) pa 
			inner join TBL_ET_PhyAppointUserMapping(nolock) um on pa.PhysicalAppointmentId = um.PhysicalAppointmentId
			left join tbl_tsk_UserOutcomeMaster(nolock) o on pa.OutcomesId = o.Id
			left join TBL_ET_GeoEntitySiteMaster(nolock) s on pa.GeoEntitySiteId = s.GeoEntitySiteId
		where cast(pa.StartDate as date) = cast(@PunchedDate as date) and um.UserId = @UserId

	update a set a.ActivityTime = c.LocationDateTime, ActualStartTime = c.CheckIn, ActualEndTime = c.CheckOut, ActualAddress  = c.Address,
		ActualStatus  = (case when isnull(c.CheckOut, '') = '' then 'pending' else 'completed' end)
	from @tempActivity a inner join 
		( SELECT  PhysicalAppointmentId,
			MAX(CASE WHEN MovementCode = 'CHECK_IN' THEN LocationDateTime END) AS CheckIn,
			MAX(CASE WHEN MovementCode = 'CHECK_OUT' THEN LocationDateTime END) AS CheckOut,
			MAX(CASE WHEN MovementCode = 'CHECK_IN' THEN LocationDateTime END) AS LocationDateTime,
			MAX(Latitude) AS Latitude,
			MAX(Longitude) AS Longitude,
			MAX(Address) as [Address]
		FROM (
			select MovementCode, UserId, LocationDateTime, Latitude, Longitude, Address, 
			JSON_VALUE(ut.LocationMetaData, '$.PhysicalAppointmentId') PhysicalAppointmentId
			from TBL_ET_UserLocationTracking(nolock) ut 
			where ut.UserId = @UserId and CAST(ut.LocationDateTime as date) = cast(@PunchedDate as date)
					and ut.MovementCode in ('CHECK_IN', 'CHECK_OUT')
		) t
	GROUP BY  PhysicalAppointmentId ) c on a.RecordType = 'PhysicalAppointment' and a.RecordId = c.PhysicalAppointmentId

	insert into @tempActivity( RecordId, RecordType, Title, StartTime, EndTime, ActivityTime, ActualStartTime, ActualEndTime, 
		ActualAddress, MovementCode, UserId)
	select UserLocationTrackingId, 'LocationTracking', ( case MovementCode  when 'GPS_OFF' then 'GPS Off' when 'BREAK_IN' then 'Break In' when 'SIGN_OUT' then 'Sign Out' when 'SIGN_IN' then 'Sign in' when 'BREAK_OUT' then 'Break Out' else MovementCode end), LocationDateTime, LocationDateTime, LocationDateTime, LocationDateTime, LocationDateTime, 
			Address, MovementCode, UserId
		from TBL_ET_UserLocationTracking(nolock)
			where UserId = @UserId and cast(LocationDateTime as date) = @PunchedDate
				and MovementCode in( 'GPS_OFF', 'SIGN_OUT', 'SIGN_IN') 

	insert into @tempActivity( RecordId, RecordType, Title, StartTime, EndTime, ActivityTime, ActualStartTime, ActualEndTime, 
		ActualAddress, MovementCode, UserId)
	select b.BreakTransactionId, 'BreakTransaction', 'Break',
		LocationDateTime, LocationDateTime, LocationDateTime, LocationDateTime, LocationDateTime, 
			Address, 'BREAK', @UserId from ( SELECT  BreakTransactionId,
				MAX(CASE WHEN MovementCode = 'BREAK_IN' THEN LocationDateTime END) AS BreakIn,
				MAX(CASE WHEN MovementCode = 'BREAK_OUT' THEN LocationDateTime END) AS BreakOut,
				MAX(CASE WHEN MovementCode = 'BREAK_IN' THEN LocationDateTime END) AS LocationDateTime,
				MAX(Latitude) AS Latitude, MAX(Longitude) AS Longitude, MAX(Address) as [Address]
			FROM ( select MovementCode, UserId, LocationDateTime, Latitude, Longitude, Address, 
				JSON_VALUE(ut.LocationMetaData, '$."BreakTransactionId"') BreakTransactionId
				from TBL_ET_UserLocationTracking(nolock) ut 
				where ut.UserId = @UserId and CAST(ut.LocationDateTime as date) = cast(@PunchedDate as date)
						and ut.MovementCode in ('BREAK_IN', 'BREAK_OUT')
			) t GROUP BY  BreakTransactionId
	) b 

	update a set a.FieldExecutiveImage = u.Image, a.FieldExecutiveName = CONCAT(u.User_Login, '(', u.FName, ' ', u.LName, ')')
		from @tempActivity a inner join User_Detail(nolock) u on a.UserId = u.User_ID

	select Id, RecordId, RecordType, Title, StartTime, EndTime, ActivityTime, MovementCode, ScheduledAddress, 
		FORMAT(ActualStartTime, 'hh:mm tt') as [ActualStartTime], isnull(FORMAT(ActualEndTime, 'hh:mm tt'), '') as [ActualEndTime], ActualAddress, GeoEntitySiteName, FieldExecutiveImage, FieldExecutiveName, OutcomeName, OutcomeIntent, ActualStatus, Remarks,
		UserId from @tempActivity order by ActivityTime

end



GO

/* ============================================================
   Procedure: [dbo].[usp_et_GetExpenseReportList]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_et_GetExpenseReportList](
	@UserId bigint,
	@FromDate date,
	@ToDate date,
	@FilterText nvarchar(255) = '',
	@UserIds nvarchar(max) = '',
	@Offset int = 0,
	@PagingSize int = 100
)
as
begin
	
	--declare 
	--	@UserId bigint = 42812,
	--	@FromDate date = N'01-Jan-2024',
	--	@ToDate date = N'31-Jan-2024',
	--	@FilterText nvarchar(255) = '',
	--	@UserIds nvarchar(max) = '',
	--	@Offset int = 0,
	--	@PagingSize int = 100


	drop table if exists #headWiseTotal

	declare @columns NVARCHAR(MAX) = '', @ParentId bigint = 0, @pvtColumns nvarchar(max) = '', @sqlExpQuery nvarchar(max);
	select @ParentId = ParentID from User_Detail(nolock) where User_ID = @UserId

	declare @Start int = (@Offset  + 1), @End int =  (@Offset  + @PagingSize)


	drop table if exists #tempUsers   
	create table #tempUsers(User_ID bigint, Name nvarchar(255), Image nvarchar(255))  
	insert into #tempUsers(User_ID, Name, Image)  
	exec Use_GetUserDetails @UserID = @UserId  

	if(ISNULL(@UserIds, '') =  '') begin set @UserIds = '' end

	drop table if exists #tempSelectedUser
	create table #tempSelectedUser ( UserId bigint )
	insert into #tempSelectedUser(UserId) select [value] from string_split(@UserIds, ',')

	select 
		@columns =  STRING_AGG( QUOTENAME(ExpenseHeadName), ','),
		@pvtColumns =  STRING_AGG( concat('[pvt].', QUOTENAME(ExpenseHeadName)), ',')
	from TBL_ET_ExpenseHead(nolock) teeh where teeh.ParentId = @ParentId -- order by ExpenseHeadName Asc

	print concat('@columns => ', @columns)
	print concat('@pvtColumns => ', @pvtColumns)

	set  @sqlExpQuery = CONCAT( N'select * from ( select ',
				N'row_number() over (partition by ud.ParentId order by ud.ParentId asc) as [SNo], ',
				N'count(1) over (order by ud.ParentId asc) as [TotalRow], ',
				N'concat(ud.User_Login, ''('', ud.FName, '' '', ud.LName, '')'' ) as ''DisplayName'', ',
				 N'ud.User_Login,  isnull(ud.FName,'''') + '' '' + isnull(ud.LName,'''')  as [UserFullName] ,',
				N'ud.User_ID as [UserId], ',
				N'd.TotalAmount, ',
				N'd.ApprovedAmount, ',
				N'd.RejectedAmount, ',
				N'd.PendingAmount, ',
				N'd.ClaimAmount ',
				case when ISNULL(@pvtColumns, '') <> '' then concat(', ', REPLACE(@pvtColumns, '[pvt].', '[d].')) else '' end ,
				N'from User_Detail(nolock) ud ',
				N'inner join #tempUsers tu on ud.User_Id = tu.User_Id ',
				iif(LEN(@UserIds) > 0, 'inner join #tempSelectedUser  su on ud.User_Id = su.UserId ', ''),
				N'left join ( select ext.UserId, ext.TotalAmount, ext.ApprovedAmount, ext.RejectedAmount, ext.PendingAmount, ext.ClaimAmount,',
					 @pvtColumns, N' from ( select ec.UserId, ',
					N'SUM(isnull(ec.TotalAmount, 0)) as [TotalAmount], ',
					N'SUM(case when ea.ApproverStatus = ''Approved'' then ea.ApprovedAmount else 0 end) as [ApprovedAmount], ',
					N'SUM(case when ea.ApproverStatus = ''Rejected'' then ec.TotalAmount else 0 end) as [RejectedAmount], ',
					N'SUM(case when ea.ApproverStatus is null then ec.TotalAmount else 0 end) as [PendingAmount], ',
					N'SUM(isnull(ec.ClaimAmount, 0)) as [ClaimAmount] ',
				N'from TBL_ET_ExpenseClaim(nolock) ec ',
					N'left join TBL_ET_ExpenseApproval(nolock) ea on ec.ExpenseClaimId = ea.ExpenseClaimId ',
				N'where ec.ParentId = ', @ParentId,
					N' and ( cast( ec.FromDate as date) between cast(''', @FromDate, ''' as date) and cast(''', @ToDate, ''' as date) ',
					N'or cast(ec.ToDate as date) between cast(''', @FromDate, ''' as date) and cast(''', @ToDate, ''' as date)) ',
				N'group by ec.UserId ) ext ',
				N'inner join ( select UserId, ', @columns, ' from ( ',
					N'select teec.UserId, isnull(teeh.ExpenseHeadName, '''') ExpenseHeadName, sum(isnull(teec.TotalAmount,0)) TotalAmounts ',
						N'from TBL_ET_ExpenseClaim(nolock) teec ',
							N'inner join TBL_ET_ExpenseHead(nolock) teeh on teec.ExpenseHeadId = teeh.ExpenseHeadId ',
						N'where teec.ParentId = ', @ParentId, ' and ',
						N'( cast( teec.FromDate as date) between cast(''', @FromDate, ''' as date) and cast(''', @ToDate, ''' as date) ',
							N'or cast(teec.ToDate as date) between cast(''', @FromDate, ''' as date) and cast(''', @ToDate, ''' as date)) ',
						N' group by teeh.ExpenseHeadName, teec.ExpenseHeadId, teec.UserId ',
					N') t  PIVOT( max(t.TotalAmounts) FOR t.ExpenseHeadName IN ( ', @columns, '  )) AS pivot_table ',
				N')  pvt on ext.UserId = pvt.UserId ) d on ud.User_ID = d.UserId ',
				N'where ud.ParentID = ', @ParentId,'  and 1  = (case  ',
				N' when ''', isnull(@FilterText, ''), N''' = '''' then 1 ',
				N' when ud.User_Login like ''%', @FilterText, '%'' then 1 ',
				N'else 0 end )) ot where ot.SNo between ', @Start, ' and ', @End)

	print concat('@sqlExpQuery => ', @sqlExpQuery)
	if(ISNULL(@sqlExpQuery,  '') <> '')
	begin
		execute sp_executesql @sqlExpQuery
	end


end




GO

/* ============================================================
   Procedure: [dbo].[usp_et_GetExpenseReportList_Cache]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE [dbo].[usp_et_GetExpenseReportList_Cache](
	@UserId bigint,
	@FromDate date,
	@ToDate date,
	@FilterText nvarchar(255) = '',
	@UserIds nvarchar(max) = '',
	@Offset int = 0,
	@PagingSize int = 100
)
as
begin

				DECLARE @MonthStart DATETIME;
				DECLARE @MonthEnd DATETIME;
				declare @ParentID bigint = 0;	

			select @ParentID = ParentID from Mysms.[dbo].User_Detail(nolock) where User_ID = @UserId;

				-- Get the first and last date of the current month
				--SET @MonthStart = FORMAT(DATEADD(DAY, 1 - DAY(GETDATE()), CAST(GETDATE() AS DATE)), 'dd-MMM-yyyy'); -- First day of current month
				--SET @MonthEnd = FORMAT(EOMONTH(GETDATE()), 'dd-MMM-yyyy'); -- Last day of current month

				Declare @Currentdate  DATE  = GETDATE();  -- Today's date
				SET @MonthStart      = FORMAT(DATEADD(DAY, -30, @Currentdate), 'dd-MMM-yyyy'); -- 30 days before today
				SET @MonthEnd  =  FORMAT(DATEADD(DAY, -1, @Currentdate), 'dd-MMM-yyyy');


				if(ISNULL(@UserIds, '') =  '') begin set @UserIds = '' end

				drop table if exists #tempSelectedUser
				create table #tempSelectedUser ( UserId bigint )
				insert into #tempSelectedUser(UserId) select [value] from string_split(@UserIds, ',')

				-- Check conditions and select data
			IF (@FromDate Between @MonthStart AND @MonthEnd AND @ToDate Between @MonthStart AND @MonthEnd)   
			BEGIN
				  SELECT --[ExpenseReportId]
				  [SNo]
				  ,[TotalRow]
				  ,[DisplayName]
				  ,[UserFullName]
				  ,[User_Login]
				  ,ex.[UserId]
				  ,[TotalAmount]
				  ,[ApprovedAmount]
				  ,[RejectedAmount]
				  ,[ClaimAmount]
				  --,[ParentId]
				  --,[User_Id]
				 FROM [dbo].[tbl_ExpenseReport_Cache](nolock) ex 
				 inner JOIN #tempSelectedUser su 
					ON (LEN(@UserIds) > 0 AND ex.UserId = su.UserId)
					WHERE ex.UserId = @UserId AND ex.ParentId = @ParentId and FromDate between @FromDate and @ToDate
			END
			ELSE IF (@FromDate < @MonthStart OR @ToDate < @MonthStart)
				BEGIN
					SELECT --[ExpenseReportId]
						  [SNo]
						  ,[TotalRow]
						  ,[DisplayName]
						  ,[UserFullName]
						  ,[User_Login]
						  ,ex.[UserId]
						  ,[TotalAmount]
						  ,[ApprovedAmount]
						  ,[RejectedAmount]
						  ,[ClaimAmount]
						  --,[ParentId]
						  --,[User_Id]
						 FROM [dbo].[tbl_ExpenseReport_Archive](nolock) ex
						 inner JOIN #tempSelectedUser su 
							ON (LEN(@UserIds) > 0 AND ex.UserId = su.UserId)
							WHERE ex.UserId = @UserId AND ex.ParentId = @ParentId and FromDate between @FromDate and @ToDate
				END
			ELSE
				BEGIN
					EXEC [Mysms].[dbo].usp_et_GetExpenseReportList @UserId, @FromDate, @ToDate, @FilterText, @UserIds, @Offset, @PagingSize;
				END
end



GO

/* ============================================================
   Procedure: [dbo].[usp_et_GetHolidayMasterCalendar]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_et_GetHolidayMasterCalendar]( 
	@UserId bigint,
	@start date,
	@end date,
	@branches nvarchar(max) = ''
)
as
begin
	--declare 
	--	@UserId bigint = 27215,
	--	@start date = '20230101',
	--	@end date = '20231231',
	--	@branches nvarchar(max) = ''

	declare 
		@ParentId bigint

	select @ParentId = ParentID from User_Detail(nolock) where User_Id = @UserId

	select 
		count(agas.HolidayId) over() as TotalRecords, 
		agas.HolidayId, 
		agas.HolidayName, 
		agas.HolidayDate,
		bh.BranchId, 
		agas.ParentId, 
		isnull(agas.Color, '#FFA07A') Color

		from TBL_ET_HolidayMaster(nolock) agas 
			inner join User_Detail (nolock) Ud on agas.CreatedBy = Ud.User_ID 
			inner join TBL_ET_HolidayBranch (nolock) bh on agas.HolidayId = bh.HolidayId
		where  Ud.ParentId = @ParentId 
		and cast(agas.HolidayDate as date) between cast(@start as date) and cast(@end as date)
		and 1 = ( case
			when isnull(@branches, '') = '' then 1
			when isnull(@branches, '') <> '' and bh.BranchId in 
				( select cast([value] as bigint) from string_split(@branches, ','))
					then 1
			else 0 end )
end



GO

/* ============================================================
   Procedure: [dbo].[usp_ET_GetLocationAddressStatus]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_ET_GetLocationAddressStatus](
	@UserId bigint,
	@Latitude float,
	@Longitude float
)
as
begin
	--declare 
	--	@UserId bigint = 32222,
	--	@Latitude float  = 28.6599898,
	--	@Longitude float  = 77.1461877

	declare 
		@Status int = -1,
		@Address nvarchar(max) = ''

	if(exists( select 1 from TBL_ET_UserLocationTracking(nolock)
		where UserId = @UserId and   ROUND(Latitude, 4) = ROUND(@Latitude, 4) 
		and ROUND(Longitude, 4) = ROUND(@Longitude, 4) ))
	begin
		select top 1 @Address = Address  from TBL_ET_UserLocationTracking(nolock) 
			where UserId = @UserId and ROUND(Latitude, 4) = ROUND(@Latitude, 4) 
		and ROUND(Longitude, 4) = ROUND(@Longitude, 4) 
		set @Status = 0
	end


	if(@Status = -1)
	begin
		if(exists( select 1 from TBL_ET_UserLocationTracking_Archived(nolock)
			where UserId = @UserId and   ROUND(Latitude, 4) = ROUND(@Latitude, 4) 
			and ROUND(Longitude, 4) = ROUND(@Longitude, 4) ))
		begin
			select top 1 @Address = Address  from TBL_ET_UserLocationTracking_Archived(nolock) 
				where UserId = @UserId and ROUND(Latitude, 4) = ROUND(@Latitude, 4) 
			and ROUND(Longitude, 4) = ROUND(@Longitude, 4) 
			set @Status = 0
		end
	end
	

	if(exists( select * from TBL_ET_UserLocationTracking(nolock)
		where UserId = @UserId and DATEDIFF(MINUTE, CreatedDate, getdate()) <= 20))
	begin
		set @Status = 1
	end

	select @Status as [Status], @Address as [Address]
end



GO

/* ============================================================
   Procedure: [dbo].[usp_et_GetPhysicalAppointment]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

--usp_et_GetPhysicalAppointment 0,200,'',34594,null,null,null,null
CREATE   PROCEDURE [dbo].[usp_et_GetPhysicalAppointment](
	@OffsetValue int =0,
	@PagingSize int =200,
	@FilterText nvarchar(max) = '',
	@UserId BIGINT,
	@AType nvarchar(25) = null,
	@uiId bigint = null,
	@FromDate date = null,
	@EndDate date = null
 )
 as
 begin
 
	 --declare 
		--@OffsetValue int =0,
		--@PagingSize int =200,
		--@FilterText nvarchar(max) = N' AND (  Status = ''open'' OR TaskStatus = ''Over Due''  OR Status = ''completed''  ) And ( ( 1 = 1 ) ) And  ( 1 = 1 ) ',
		--@UserId BIGINT = 46138, --47104,

		--@AType nvarchar(25) = '',
		--@uiId bigint = 46138, --34594,
		--@FromDate date = N'',
		--@EndDate date = N''

	if(isnull(@AType, '') <> '' and isnull(@AType, '') <> ''  and isnull(@AType, '') <> '' and isnull(@AType, '') <> '' )
	begin
		set @FilterText = concat(N' and 1 = ( case ',
		N' when ''', @AType, ''' = ''Visit'' and isnull(geci.GeoEntityCheckId, '''') <> '''' and A.AssignedTo = ', @uiId, '  THEN 1 ',
		N' when ''', @AType, ''' = ''Assigned'' and A.AssignedTo = ', @uiId, ' THEN 1 ',
		N' when ''', @AType, ''' = ''Missed'' and A.StartDate < GETDATE() and isnull(geci.GeoEntityCheckId, '''') = '''' and A.AssignedTo = ', @uiId, ' THEN 1 ',
		N' when ''', @AType, ''' = ''Pending'' and A.StartDate > GETDATE() and isnull(geci.GeoEntityCheckId, '''') = '''' and A.AssignedTo = ', @uiId, ' THEN 1',
		N' else 0 end ) and StartDate >= cast(''', @FromDate, ''' as date) and EndDate <= cast(''', @EndDate, ''' as date) ')
	end


	 DECLARE @ParentId BIGINT = 0, @iUserId bigint = @UserId
	 SELECT @ParentId = ParentID FROM User_Detail(nolock) WHERE User_ID = @UserId;                    
	 DECLARE @RoleType varchar(10);    


	 Declare @TeamCode varchar(10) = ''  
	 Declare @ScopeCode varchar(10) = ''   
	 Declare @UserIdTeamLst varchar(Max) = ''   
	 Declare @UserLoginTeamLst varchar(Max) = ''   

	  drop table if exists #tbluser
	 create table #tbluser (User_ID bigint,Name varchar(100), Image varchar(100),ParentID bigint)  
	 declare @IsAdmin bit = 0  
	 select @IsAdmin = IsAdmin from User_Detail(nolock) where User_ID = @UserId  
	 if(@IsAdmin = 1)  
	 begin  
	  set @UserId = 0;  
	  --insert into @tbluser  
	  insert into #tbluser  
	  exec usp_GetUserDetailWithParent @ParentId  
	 end  
	 else  
	 Begin  
	  --insert into @tbluser  
	  insert into #tbluser  
	  exec usp_GetUserDetailWithParent @UserId  
	 End  
  
	select @UserIdTeamLst = isnull(STRING_AGG(User_ID,','),'') From #tbluser  

	declare @FinalSql nvarchar(max), @ScriptPrefix nvarchar(max), @FirstSql nvarchar(max), @SecondSql nvarchar(max),
		@ThirdSql nvarchar(max), @FouthSql nvarchar(max), @ScriptSufix nvarchar(max), @StartPoint int, @Endpoint int

	set @StartPoint = @OffsetValue + 1;
	set @Endpoint = (@StartPoint + @PagingSize) - 1


	set @ScriptPrefix = concat( N'SELECT Sno, TotalRow, PhysicalAppointmentId, Title, Description, Address, StartDate, EndDate, STATUS, TaskStatus, ',
		N'ParentID, AssignedTo, CreatedBy, UserId, OutcomesId, IsActive, CompletedOn, TaskTypeId, Remarks, CreatedDate, UpdatedDate, ',
		N'GeoEntitySiteId, OutcomeName, GeoEntitySiteName, TasKName, GeoEntityName, GeoEntityType, EntityId, Mobile, EmailId, IconClass, isnull(TmhHasView, 0) as [TmhHasView],isnull(TmhHasEdit, 0) as [TmhHasEdit], isnull(TmhHasRemove, 0) as [TmhHasRemove], isnull(TmhHasCompletion, 0) as [TmhHasCompletion], isnull(TmhHasComment, 0) as [TmhHasComment], isnull(FepHasView, 0) as [FepHasView], isnull(FepHasEdit, 0) as [FepHasEdit], isnull(FephHasRemove, 0) as [FephHasRemove],
       isnull(FepHasCompletion, 0) as [FepHasCompletion], isnull(FepHasComment, 0) as [FepHasComment], ISNULL(Has_viewLead,0) Has_viewLead, ISNULL(Has_editLead,0) Has_editLead,ISNULL(Has_fieldviewLead,0) Has_fieldviewLead, ISNULL(Has_fieldeditLead,0) Has_fieldeditLead , UserType FROM (SELECT ',
			N'ROW_NUMBER() OVER(partition by (select null) order by A.PhysicalAppointmentId desc) AS Sno, ',
			N'COUNT(A.PhysicalAppointmentId) OVER() AS TotalRow, ',
			N'A.PhysicalAppointmentId, A.Title, A.Description, A.Address, A.StartDate, A.EndDate, ',
			N'A.STATUS, A.TaskStatus, A.ParentID, A.AssignedTo, A.CreatedBy, A.UserId, A.OutcomesId, A.IsActive, ',
			N'A.CompletedOn, A.TaskTypeId, A.Remarks, A.CreatedDate, A.UpdatedDate, A.GeoEntitySiteId, ',
			N'UOM.OutcomeName, SM.GeoEntitySiteName, GE.GeoEntityName, ISNULL(GE.GeoEntityType, ''location'') as [GeoEntityType], GE.EntityId, GE.Mobile, GE.EmailId, TM.TasKName, TM.IconClass, TM.has_view as [TmhHasView], TM.has_edit as [TmhHasEdit],  ',
			N'TM.has_remove as [TmhHasRemove], TM.has_completion as [TmhHasCompletion], TM.has_comment as [TmhHasComment], ',
			N'EP.has_view as [FepHasView], EP.has_edit as [FepHasEdit], EP.has_remove as [FephHasRemove], ',
			N'EP.has_completion as [FepHasCompletion], EP.has_comment as [FepHasComment], colb.Has_viewLead, colb.Has_editLead,colb.Has_fieldviewLead, colb.Has_fieldeditLead,  ',
			N'CASE WHEN A.Assignedto=',@iuserid,' THEN ''Owner''
				When 1= (Select distinct 1 from TBL_ET_PhyAppointCollaboratorUserMapping col where Userid=',@iUserId,' and col.PhysicalAppointmentId=A.PhysicalAppointmentId) THEN ''Collab''
				When 1= (Select distinct 1 from TBL_ET_PhyAppointUserMapping upm where Userid=',@iUserId,' and upm.PhysicalAppointmentId=A.PhysicalAppointmentId) THEN ''Field''
			END UserType ',
		 N'FROM ( ' )


	set @FirstSql  = concat( N'	SELECT TH.PhysicalAppointmentId, TH.Title, TH.Description, TH.Address, TH.StartDate, TH.EndDate, ',
				N'(CASE  WHEN LOWER(TH.STATUS) = ''completed'' THEN ''completed'' ',
					N'ELSE (CASE WHEN CAST(TH.EndDate AS DATE) > CAST(GETDATE() AS DATE) THEN ''scheduled'' ', 
					N'WHEN CAST(TH.EndDate AS DATE) < CAST(GETDATE() AS DATE) THEN ''over due'' ',
                N'ELSE ''open'' END) END) as [STATUS], (CASE  WHEN LOWER(TH.STATUS) = ''completed'' THEN ''Completed''
					ELSE (CASE WHEN CAST(TH.EndDate AS DATE) > CAST(GETDATE() AS DATE) THEN ''Scheduled''
                    WHEN CAST(TH.EndDate AS DATE) < CAST(GETDATE() AS DATE) THEN ''Over Due''
                    ELSE ''Due Today'' END) END) AS [TaskStatus],  UD.ParentID, ',
		 N'TH.AssignedTo,TH.CreatedBy, UD.User_ID AS [UserId], TH.OutcomesId, TH.IsActive, TH.CompletedOn, TH.TaskTypeId, TH.Remarks, ',
		 N'TH.CreatedDate, TH.UpdatedDate, TH.GeoEntitySiteId FROM TBL_ET_PhysicalAppointment(NOLOCK) TH  ',
					N'LEFT JOIN User_Detail(NOLOCK) UD ON TH.CreatedBy = case when '+cast(@isadmin as nvarchar)+' =1 then TH.CreatedBy else UD.User_ID end ',
			N'WHERE TH.CreatedBy IN( ', @UserIdTeamLst, ' ) AND TH.IsActive = 1  ' )

	set @SecondSql  = concat( N' UNION SELECT TH.PhysicalAppointmentId, TH.Title, TH.Description, TH.Address, TH.StartDate, TH.EndDate,  ',
				N'(CASE  WHEN LOWER(TH.STATUS) = ''completed'' THEN ''completed'' ',
					N'ELSE (CASE WHEN CAST(TH.EndDate AS DATE) > CAST(GETDATE() AS DATE) THEN ''scheduled'' ', 
					N'WHEN CAST(TH.EndDate AS DATE) < CAST(GETDATE() AS DATE) THEN ''over due'' ',
                N'ELSE ''open'' END) END) as [STATUS],  (CASE  WHEN LOWER(TH.STATUS) = ''completed'' THEN ''Completed''
					ELSE (CASE WHEN CAST(TH.EndDate AS DATE) > CAST(GETDATE() AS DATE) THEN ''Scheduled''
                    WHEN CAST(TH.EndDate AS DATE) < CAST(GETDATE() AS DATE) THEN ''Over Due''
                    ELSE ''Due Today'' END) END) AS [TaskStatus], ',
			N'UD.ParentID, TH.AssignedTo, TH.CreatedBy, UD.User_ID AS [UserId], TH.OutcomesId, TH.IsActive, TH.CompletedOn, TH.TaskTypeId, ',
			N'TH.Remarks, TH.CreatedDate, TH.UpdatedDate, TH.GeoEntitySiteId FROM TBL_ET_PhysicalAppointment(NOLOCK) TH ',
			N'LEFT JOIN User_Detail(NOLOCK) UD ON TH.AssignedTo = case when '+cast(@isadmin as nvarchar)+' =1 then TH.AssignedTo else UD.User_ID end ',
			N'WHERE TH.AssignedTo IN( ', @UserIdTeamLst, ' ) AND TH.IsActive = 1  ' )
	
	set @ThirdSql  = concat( N' UNION SELECT TH.PhysicalAppointmentId, TH.Title, TH.Description, TH.Address, TH.StartDate, TH.EndDate, ',
				N'(CASE  WHEN LOWER(TH.STATUS) = ''completed'' THEN ''completed'' ',
					N'ELSE (CASE WHEN CAST(TH.EndDate AS DATE) > CAST(GETDATE() AS DATE) THEN ''scheduled'' ', 
					N'WHEN CAST(TH.EndDate AS DATE) < CAST(GETDATE() AS DATE) THEN ''over due'' ',
                N'ELSE ''open'' END) END) as [STATUS], (CASE  WHEN LOWER(TH.STATUS) = ''completed'' THEN ''Completed''
					ELSE (CASE WHEN CAST(TH.EndDate AS DATE) > CAST(GETDATE() AS DATE) THEN ''Scheduled''
                    WHEN CAST(TH.EndDate AS DATE) < CAST(GETDATE() AS DATE) THEN ''Over Due''
                    ELSE ''Due Today'' END) END) AS [TaskStatus], ',
			N'TH.ParentID, TH.AssignedTo, TH.CreatedBy, TCM.UserId AS [UserId], TH.OutcomesId, TH.IsActive, TH.CompletedOn, TH.TaskTypeId, ',
			N'TH.Remarks, TH.CreatedDate, TH.UpdatedDate, TH.GeoEntitySiteId FROM TBL_ET_PhysicalAppointment(NOLOCK) TH ',
			N'LEFT JOIN TBL_ET_PhyAppointCollaboratorUserMapping(NOLOCK) TCM ON TH.PhysicalAppointmentId = TCM.PhysicalAppointmentId ',
			N'WHERE TCM.UserId IN( ', @UserIdTeamLst, ' ) AND TH.IsActive = 1  ' )

	set @FouthSql  = concat( N' UNION SELECT TH.PhysicalAppointmentId, TH.Title, TH.Description, TH.Address, TH.StartDate, TH.EndDate, ',
				N'(CASE  WHEN LOWER(TH.STATUS) = ''completed'' THEN ''completed'' ',
					N'ELSE (CASE WHEN CAST(TH.EndDate AS DATE) > CAST(GETDATE() AS DATE) THEN ''scheduled'' ', 
					N'WHEN CAST(TH.EndDate AS DATE) < CAST(GETDATE() AS DATE) THEN ''over due'' ',
                N'ELSE ''open'' END) END) as [STATUS], (CASE  WHEN LOWER(TH.STATUS) = ''completed'' THEN ''Completed''
					ELSE (CASE WHEN CAST(TH.EndDate AS DATE) > CAST(GETDATE() AS DATE) THEN ''Scheduled''
                    WHEN CAST(TH.EndDate AS DATE) < CAST(GETDATE() AS DATE) THEN ''Over Due''
                    ELSE ''Due Today'' END) END) AS [TaskStatus], ',
			N'Th.ParentID, TH.AssignedTo, TH.CreatedBy, TCM.UserId AS [UserId], TH.OutcomesId, TH.IsActive, TH.CompletedOn, TH.TaskTypeId, ',
			N'TH.Remarks, TH.CreatedDate, TH.UpdatedDate, TH.GeoEntitySiteId FROM TBL_ET_PhysicalAppointment(NOLOCK) TH ',
			N'LEFT JOIN TBL_ET_PhyAppointUserMapping(NOLOCK) TCM ON TH.PhysicalAppointmentId = TCM.PhysicalAppointmentId ',
			N'WHERE TCM.UserId IN( ', @UserIdTeamLst, ' ) AND TH.IsActive = 1  ' )

	set @ScriptSufix = concat( N' ) A ',
		N' LEFT JOIN TBL_ET_GeoEntitySiteMaster(NOLOCK) SM ON A.GeoEntitySiteId = SM.GeoEntitySiteId ',
		N' LEFT JOIN tbl_tsk_UserOutcomeMaster(NOLOCK) UOM ON UOM.Id = A.OutcomesId ',
		N' LEFT JOIN tbl_tsk_UserTaskMaster(NOLOCK) TM ON A.TaskTypeId = TM.Id ',
		N' LEFT JOIN TBL_ET_PhyApptTypeFieldExecutivePermission(NOLOCK) EP  ON A.TaskTypeId = EP.task_type_id ',
		N' LEFT JOIN TBL_ET_GeoEntityMaster(NOLOCK) GE ON SM.GeoEntityId = GE.GeoEntityId ',
		N' LEFT JOIN TBL_ET_GeoEntityCheckInOut(nolock) geci on A.PhysicalAppointmentId = geci.PhysicalAppointmentId ',
		N' Outer APPLY dbo.udf_tsk_GetCollaboratersLeadEditView1(A.PhysicalAppointmentId,',@iUserId,',' ,@ParentId,') colb',
		N' WHERE A.UserId = ', @iUserId, ' ', iif(isnull(@FilterText, '') <> '', @FilterText,  ''), ' ) T  WHERE T.Sno between ', @StartPoint, ' and ', @Endpoint )


	print @ScriptPrefix
	print @FirstSql
	print @SecondSql
	print @ThirdSql
	print @FouthSql
	print @ScriptSufix

	set @FinalSql = concat( @ScriptPrefix, @FirstSql, @SecondSql, @ThirdSql, @FouthSql, @ScriptSufix )

	execute sp_executesql @FinalSql

end




GO

/* ============================================================
   Procedure: [dbo].[usp_et_GetPhysicalAppointmentById]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_et_GetPhysicalAppointmentById] (
	@PhysicalAppointmentId bigint,
	@UserId bigint
)as
begin

	--declare 
	--	@PhysicalAppointmentId bigint = 111, 
	--	@UserId bigint = 34594



	SELECT 
		PA.PhysicalAppointmentId,
		PA.Title,
		PA.Description,
		PA.StartDate,
		PA.EndDate,
		PA.Address,
		PA.CompleteAddress,
		PA.CompletedOn,
		PA.CreatedDate,
		PA.UpdatedDate,
		OT.Id as [otId],
		OT.OutcomeName as [otOutcomeName],
		OT.Indent as [otIntent],
		TM.Id as [tmId],
		TM.TasKName as [tmTaskName],
		tm.IconClass as [tmIconClass],
		GE.GeoEntityId as [geGeoEntityId],
		GE.GeoEntityType as [geGeoEntityType],
		GE.GeoEntityName as [geGeoEntityName],
		GE.EntityId as [geEntityId],
		GE.Mobile as [geMobile],
		GE.EmailId as [geEmailId],
		SM.GeoEntitySiteId as [smGeoEntitySiteId],
		SM.GeoEntitySiteName as [smGeoEntitySiteName],
		SM.Latitude as [smLatitude],
		SM.Longitude  as [smLongitude],
		SM.MapAddress  as [smMapAddress],
		SM.Address as [smAddress],
		SM.City as [smCity],
		SM.State as [smState],
		SM.Country as [smCountry],
		SM.PinCode as [smPinCode],
		CU.User_ID as [cuUserId],
		CONCAT(CU.User_Login, '(',trim(CU.Fname), ' ', trim(CU.LName),  ')'  ) as [cuDisplayName],
		AU.User_ID as [auUserId],
		CONCAT(AU.User_Login, '(',trim(AU.Fname), ' ', trim(AU.LName),  ')'  ) as [auDisplayName],
		UU.User_ID as [uuUserId],
		CONCAT(CU.User_Login, '(',trim(UU.Fname), ' ', trim(UU.LName),  ')'  ) as [uuDisplayName],
		( select  fu.User_ID as [fuUserId],
			CONCAT(fu.User_Login, '(',trim(fu.Fname), ' ', trim(fu.LName),  ')'  ) as [fuDisplayName]
			from User_Detail(nolock) fu where fu.User_ID in (
			select UserId from TBL_ET_PhyAppointUserMapping(nolock) um 
			where um.PhysicalAppointmentId = @PhysicalAppointmentId
		) for json path ) as [FieldExecutives],
		( select  fu.User_ID as [fuUserId],
			CONCAT(fu.User_Login, '(',trim(fu.Fname), ' ', trim(fu.LName),  ')'  ) as [fuDisplayName]
			from User_Detail(nolock) fu where fu.User_ID in (
			select UserId from TBL_ET_PhyAppointCollaboratorUserMapping(nolock) um 
			where um.PhysicalAppointmentId = @PhysicalAppointmentId
		) for json path ) as [Collaborators]
	FROM TBL_ET_PhysicalAppointment(nolock) PA	
		LEFT JOIN TBL_ET_GeoEntityMaster(nolock) GE ON PA.GeoEntityId = GE.GeoEntityId
		LEFT JOIN User_Detail(nolock) CU ON PA.CreatedBy = CU.User_ID
		LEFT JOIN User_Detail(nolock) AU ON PA.AssignedTo = AU.User_ID
		LEFT JOIN User_Detail(nolock) UU ON PA.AssignedTo = UU.User_ID
		LEFT JOIN TBL_ET_GeoEntitySiteMaster(NOLOCK) SM ON PA.GeoEntitySiteId = SM.GeoEntitySiteId
		LEFT JOIN tbl_tsk_UserOutcomeMaster(NOLOCK) OT ON OT.Id = PA.OutcomesId
		LEFT JOIN tbl_tsk_UserTaskMaster(NOLOCK) TM ON PA.TaskTypeId = TM.Id
		LEFT JOIN TBL_ET_PhyApptTypeFieldExecutivePermission(NOLOCK) EP  ON PA.TaskTypeId = EP.task_type_id 
	where PA.PhysicalAppointmentId = @PhysicalAppointmentId

end 



