/* ============================================================
   Procedure: [dbo].[usp_et_GetUserLocationTracking]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

 
CREATE   PROCEDURE [dbo].[usp_et_GetUserLocationTracking](
	@UserId bigint,
	@UserIds nvarchar(max) =  '',
	@FromDate date,
	@ToDate date,
	@SearchText nvarchar(255) = null,
	@SortType nvarchar(255) = null,
	@Offset int = 0,
	@PageSize int = 10
)
as
begin

	--declare 
	--	@UserId bigint = 43966,
	--	@UserIds nvarchar(max) =  '',
	--	@FromDate date = N'21-Apr-2024',
	--	@ToDate date = N'27-Apr-2024',
	--	@SearchText nvarchar(255) = N'',
	--	@Offset int = 0,
	--	@PageSize int = 100

	declare @ParentId bigint

	select @ParentId = ParentID from User_Detail(nolock) where User_Id = @UserId
	declare @StartPoint int  = (@Offset + 1), @Endpoint int = (@Offset + @PageSize)

	drop table if exists #tempUsers  
	create table #tempUsers(User_ID bigint, Name nvarchar(255), Image nvarchar(255))  
	insert into #tempUsers(User_ID, Name, Image)  
	exec Use_GetUserDetails @UserID = @UserId  

	if(ISNULL(@UserIds, '') =  '') begin set @UserIds = '' end

	drop table if exists #tempSelectedUser
	create table #tempSelectedUser ( UserId bigint )
	insert into #tempSelectedUser(UserId) select [value] from string_split(@UserIds, ',') where [value] > 0
	
	declare @sqlQuery nvarchar(max) = concat(N'select ',
		N't.[SNo], ',
		N't.[Total], ',
		N't.[Date], ',
		N't.[Name], ',
		N't.[Time], ',
		N't.[Event], ',
		N't.[Address], ',
		N't.[Distance] ,',
		N't.UserFullName,',
		N't.User_Login ',
	N'from ( select  ',
		N'ROW_NUMBER() over(partition by (select null) order by t.LocationDateTime desc) [SNo], ',
		N'count(1) over( order by (select null) desc) [Total], ',
		N'format(t.LocationDateTime, ''dd-MMM-yyy'') as [Date], ',
		N'concat(u.User_Login, '' ('', u.FName, '' '', u.LName, '')'') as [Name], ',
		N' u.User_Login, isnull(u.FName,'''') + '' '' + isnull(u.LName,'''')  as [UserFullName] ,',
		N'format(t.LocationDateTime, ''HH:mm:ss'') as ''Time'', ',
		N't.MovementCode as [Event], ',
		N't.Address, ',
		N'(TRY_CONVERT(decimal(18, 3), t.Distance) /1000) as [Distance] ',
		N'from  ( ',
			N'select LocationDateTime, MovementCode, Address, Distance, UserId  ',
			N' from TBL_ET_UserLocationTracking(nolock) l inner join #tempUsers tu on l.UserId = tu.User_ID ',
			N' where cast(l.LocationDateTime as date) between ''', @FromDate, ''' and ''', @ToDate , '''',
			N' union ',
			N'select LocationDateTime, MovementCode, Address, Distance, UserId  ',
			N' from TBL_ET_UserLocationTracking_Archived(nolock) l inner join #tempUsers tu on l.UserId = tu.User_ID ',
			N' where cast(l.LocationDateTime as date) between ''', @FromDate, ''' and ''', @ToDate , '''',
		N') t ',
		N'inner join #tempUsers tu on t.UserId = tu.User_ID ',
		iif(LEN(@UserIds) > 0, 'inner join #tempSelectedUser su on t.UserId = su.UserId ', ''),
		N'inner join User_Detail(nolock) u on t.UserId = u.User_ID ',
	N'where  ',
		--t.UserId in (
		--	select User_ID from User_Detail(nolock) where ParentID = @ParentId
		--) and
	N'cast(t.LocationDateTime as date) between ''', @FromDate, ''' and ''', @ToDate , '''',
	N' and 1 = ( case  ',
		N'when isnull(''', @SearchText, ''', '''') = '''' then 1 ',
		N'when u.User_Login like ''%', @SearchText, '%'' then 1 ',
		N'when u.FName like ''%', @SearchText, '%''  then 1 ',
		N'when u.LName like ''%', @SearchText, '%''  then 1 ',
		N'when t.Address like ''%', @SearchText, '%''  then 1 ',
		N'else 0 end )  ',
	N') t where t.SNo between ', @StartPoint, ' and ', @Endpoint )

	print @sqlQuery

	exec sp_executesql @sqlQuery

end




GO

/* ============================================================
   Procedure: [dbo].[usp_et_GetUserLocationTracking_Cache]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_et_GetUserLocationTracking_Cache](
	@UserId bigint,
	@UserIds nvarchar(max) =  '',
	@FromDate date,
	@ToDate date,
	@SearchText nvarchar(255) = null,
	@SortType nvarchar(255) = null,
	@Offset int = 0,
	@PageSize int = 10
)
as
begin

	--DECLARE
	--	@UserId bigint = 0, 
	--	@UserIds nvarchar(max) =  '',
	--	@FromDate date,
	--	@ToDate date,
	--	@SearchText nvarchar(255) = null,
	--	@SortType nvarchar(255) = null,
	--	@Offset int = 0,
	--	@PageSize int = 10

	--SELECT @FromDate = N'11-Feb-2025',@ToDate = N'11-Feb-2025',@SearchText = null, @UserId = 42980, 
	--	@UserIds = null, @SortType = N'asc',@Offset = 0, @PageSize = 10

	DECLARE @MonthStart DATETIME;
	DECLARE @MonthEnd DATETIME;
	declare @ParentID bigint = 0;		

	declare @StartPoint int  = (@Offset + 1), @Endpoint int = (@Offset + @PageSize)
	select @ParentID = ParentID from Mysms.[dbo].User_Detail(nolock) where User_ID = @UserId;

	-- Get the first and last date of the current month
	--SET @MonthStart = FORMAT(DATEADD(DAY, 1 - DAY(GETDATE()), CAST(GETDATE() AS DATE)), 'dd-MMM-yyyy'); -- First day of current month
	--SET @MonthEnd = FORMAT(EOMONTH(GETDATE()), 'dd-MMM-yyyy'); -- Last day of current month

	Declare @Currentdate  DATE  = GETDATE();  -- Today's date
	SET @MonthStart      = FORMAT(DATEADD(DAY, -30, @Currentdate), 'dd-MMM-yyyy'); -- 30 days before today
	SET @MonthEnd  =  FORMAT(DATEADD(DAY, -1, @Currentdate), 'dd-MMM-yyyy');

	if(ISNULL(@UserIds, '') =  '') begin set @UserIds = '' end

	drop table if exists #tempUsers  
	create table #tempUsers(User_ID bigint, Name nvarchar(255), Image nvarchar(255))  
	insert into #tempUsers(User_ID, Name, Image)  
	exec Use_GetUserDetails @UserID = @UserId  

	drop table if exists #tempSelectedUser
	create table #tempSelectedUser ( UserId bigint )
	insert into #tempSelectedUser(UserId) select [value] from string_split(@UserIds, ',') where [value] > 0

	declare @selectUserCount int = 0
	select @selectUserCount = count(1) from #tempSelectedUser

	-- Check conditions and select data
	IF (@FromDate Between @MonthStart AND @MonthEnd AND @ToDate Between @MonthStart AND @MonthEnd)  
	BEGIN
		PRINT 'tbl_UserTrackingReport_Cache'

		PRINT CONCAT('@UserIds => ', @UserIds)

		;WITH cacheData as ( SELECT 
			ROW_NUMBER() over(partition by (select null) order by a.UserTrackingReportId desc) [SNo], 
			[Date], [a].[Name], [Time], [Event], [Address], [Distance], [User_Login], [UserFullName]
			FROM [MySMSReportCache].[dbo].[tbl_UserTrackingReport_Cache](nolock) a
			inner join #tempUsers hu on a.UserId = hu.User_ID
			where ParentId = @ParentID and cast([Date] as date) between @FromDate and @ToDate
				and 1 = ( case  when @selectUserCount = 0 then 1  
					when @selectUserCount > 0 and a.UserId in (select UserId from #tempSelectedUser) then 1 
				else 0 end )
		) SELECT SNo,  (SELECT COUNT(1) from cacheData) as [Total],
			[Date], [Name], [Time], [Event], [Address], [Distance], [User_Login], [UserFullName]
		FROM cacheData WHERE SNo between @StartPoint and @Endpoint
		
	END
	ELSE IF (@FromDate < @MonthStart OR @ToDate < @MonthStart)
	BEGIN
		;WITH archiveData as ( SELECT ROW_NUMBER() over(partition by (select null) order by a.UserTrackingReportId desc) [SNo], 
			[Date], [a].[Name], [Time], [Event], [Address], [Distance], [User_Login], [UserFullName]
		FROM [MySMSReportCache].[dbo].[tbl_UserTrackingReport_Archive](nolock) a
			inner join #tempUsers hu on a.UserId = hu.User_ID
		Where ParentId = @ParentID and cast([Date] as date) between @FromDate and @ToDate
			and 1 = ( case 
				when @selectUserCount = 0 then 1  
				when @selectUserCount > 0 and a.UserId in (select UserId from #tempSelectedUser) then 1 
				else 0 end
			)
		) SELECT SNo,  (SELECT COUNT(1) from archiveData) as [Total],
			[Date], [Name], [Time], [Event], [Address], [Distance], [User_Login], [UserFullName]
		FROM archiveData WHERE SNo between @StartPoint and @Endpoint
			
	END
	ELSE
	BEGIN
		PRINT 'CURRENT DATE'
		EXEC [Mysms].[dbo].usp_et_GetUserLocationTracking @UserId, @UserIds, @FromDate, @ToDate, @SearchText, @SortType,@Offset,@PageSize;
	END
END



GO

/* ============================================================
   Procedure: [dbo].[usp_et_GetUserLocationTrackingActivities]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_et_GetUserLocationTrackingActivities](
	@PunchedDate date,
	@UserId bigint
)
as
begin
	
	--declare 
	--	@PunchedDate date = '02-Apr-2024 14:17',
	--	@UserId bigint = 44010

	if(cast(@PunchedDate as date) <= DATEADD(day, -30, getdate()))
	begin
		select 
			UserLocationTrackingId,
			MovementCode,
			LocationDateTime,
			Latitude,
			Longitude,
			[Address], 
			BatteryPerc,
			NetworkPerc,
			Speed,
			Distance,
			LocationMetaData,
			isnull(m.Title, 'Appointment') as [Title],
			format(m.StartDate, 'dd-MMM-yyyy HH:mm:ss') as [StartDate],
			format(m.EndDate, 'dd-MMM-yyyy HH:mm:ss') as [EndDate],
			format(LocationDateTime, 'hh:mm tt') as [strOutTime],
			format(InTime, 'hh:mm tt') as [strInTime],
			GeoEntitySiteName,
			SiteAddress
		from ( select UserLocationTrackingId, MovementCode, LocationDateTime, lt.Latitude, lt.Longitude, [lt].[Address], 
			BatteryPerc, NetworkPerc, Speed, Distance, LocationMetaData, pa.Title, pa.StartDate, pa.EndDate,
				Lag(lt.LocationDateTime, 1, 0) over (partition by lt.UserId order by lt.UserLocationTrackingId) as InTime,
				isnull(sm.GeoEntitySiteName, '') as  [GeoEntitySiteName], isnull([sm].[Address], '') as [SiteAddress]
		from (select *, 
			ROW_NUMBER() over (partition by MovementCode, UserId, Latitude, Longitude
				order by UserLocationTrackingId asc) as [SNo]
		from TBL_ET_UserLocationTracking_Archived(nolock)
	
			where UserId = @UserId and cast(LocationDateTime as date) = @PunchedDate
				and MovementCode in( 'GPS_OFF', 'BREAK_IN', 'CHECK_IN', 'SIGN_OUT', 'SIGN_IN', 'CHECK_OUT', 'BREAK_OUT' ) 
		) lt
		left join TBL_ET_PhysicalAppointment(nolock) pa on 
			1 = ( case when lt.MovementCode in ('CHECK_IN', 'CHECK_OUT') and isnull(lt.LocationMetaData, '') <> '' and 
					JSON_VALUE(LocationMetaData, '$.EntityName') = 'PhysicalAppointment' and JSON_VALUE(LocationMetaData, '$.EntityId') = pa.PhysicalAppointmentId
					then 1 else 0 end ) 
		left join TBL_ET_GeoEntitySiteMaster(nolock) sm on pa.GeoEntitySiteId = sm.GeoEntitySiteId
		where lt.SNo = 1 ) m where m.MovementCode in ( 'GPS_OFF', 'SIGN_OUT', 'SIGN_IN', 'CHECK_OUT', 'BREAK_OUT' )
			order by LocationDateTime, ( case MovementCode 
				when 'SIGN_IN' then 1
				when 'GPS_OFF' then 2
				when 'BREAK_OUT' then 2
				when 'CHECK_OUT' then 2
				when 'SIGN_OUT' then 3
			end)  asc
	end
	else
	begin
		select 
			UserLocationTrackingId,
			MovementCode,
			LocationDateTime,
			Latitude,
			Longitude,
			[Address], 
			BatteryPerc,
			NetworkPerc,
			Speed,
			Distance,
			LocationMetaData,
			isnull(m.Title, 'Appointment') as [Title],
			format(m.StartDate, 'dd-MMM-yyyy HH:mm:ss') as [StartDate],
			format(m.EndDate, 'dd-MMM-yyyy HH:mm:ss') as [EndDate],
			format(LocationDateTime, 'hh:mm tt') as [strOutTime],
			format(InTime, 'hh:mm tt') as [strInTime],
			GeoEntitySiteName,
			SiteAddress
		from ( select UserLocationTrackingId, MovementCode, LocationDateTime, lt.Latitude, lt.Longitude, [lt].[Address], 
			BatteryPerc, NetworkPerc, Speed, Distance, LocationMetaData, pa.Title, pa.StartDate, pa.EndDate,
				Lag(lt.LocationDateTime, 1, 0) over (partition by lt.UserId order by lt.UserLocationTrackingId) as InTime,
				isnull(sm.GeoEntitySiteName, '') as  [GeoEntitySiteName], isnull([sm].[Address], '') as [SiteAddress]
		from (select *, 
			ROW_NUMBER() over (partition by MovementCode, UserId, Latitude, Longitude
				order by UserLocationTrackingId asc) as [SNo]
		from TBL_ET_UserLocationTracking(nolock)
	
			where UserId = @UserId and cast(LocationDateTime as date) = @PunchedDate
				and MovementCode in( 'GPS_OFF', 'BREAK_IN', 'CHECK_IN', 'SIGN_OUT', 'SIGN_IN', 'CHECK_OUT', 'BREAK_OUT' ) 
		) lt
		left join TBL_ET_PhysicalAppointment(nolock) pa on 
			1 = ( case when lt.MovementCode in ('CHECK_IN', 'CHECK_OUT') and isnull(lt.LocationMetaData, '') <> '' and 
					JSON_VALUE(LocationMetaData, '$.EntityName') = 'PhysicalAppointment' and JSON_VALUE(LocationMetaData, '$.EntityId') = pa.PhysicalAppointmentId
					then 1 else 0 end ) 
		left join TBL_ET_GeoEntitySiteMaster(nolock) sm on pa.GeoEntitySiteId = sm.GeoEntitySiteId
		where lt.SNo = 1 ) m where m.MovementCode in ( 'GPS_OFF', 'SIGN_OUT', 'SIGN_IN', 'CHECK_OUT', 'BREAK_OUT' )
			order by LocationDateTime, ( case MovementCode 
				when 'SIGN_IN' then 1
				when 'GPS_OFF' then 2
				when 'BREAK_OUT' then 2
				when 'CHECK_OUT' then 2
				when 'SIGN_OUT' then 3
			end)  asc
	end
end



GO

