/* ============================================================
   Procedure: [dbo].[usp_et_InsertSingleMovementCodeInternal]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_et_InsertSingleMovementCodeInternal(
	@MovementCode nvarchar(25) = null,
	@Latitude float = 0,
	@Longitude float =  0,
	@Address nvarchar(255) =  null,
	@LocationDateTime datetime,
	@AttendanceId nvarchar(255) = null,
	@PhysicalAppointmentId nvarchar(255) = null,
	@BreakTransactionId nvarchar(255) = null,
	@DeviceId nvarchar(1000) = null,
	@UserId bigint
)
as
begin

	--declare 
	--	@MovementCode nvarchar(25) = null,
	--	@Latitude float = 0,
	--	@Longitude float =  0,
	--	@Address nvarchar(255) =  null,
	--	@LocationDateTime datetime,
	--	@AttendanceId nvarchar(255) = null,
	--	@PhysicalAppointmentId nvarchar(255) = null,
	--	@BreakTransactionId nvarchar(255) = null,
	--	@DeviceId nvarchar(1000) = null,
	--	@UserId bigint = 43390

	if(ISNULL(@MovementCode, '') <> '')
	begin
		begin try

			declare 
				@jsonData nvarchar(max) = N'{"Timestamp":"","EntityName":"Dynamic","EntityId":"0","DeviceId":"","AttendanceId":"20974","PhysicalAppointmentId":"","BreakTransactionId":""}',
				@UserLogin nvarchar(255) = '', @Remarks nvarchar(255) = ''
	
			select @UserLogin = User_Login from User_Detail(nolock) where User_ID = @UserId

			set @jsonData = JSON_MODIFY(@jsonData, '$.Timestamp', isnull(format(GETDATE(), 'yyyyMMddHHmmssfff'), ''))
			if(isnull(@DeviceId, '') <> '')
			begin
				set @jsonData = JSON_MODIFY(@jsonData, '$.DeviceId', isnull(@DeviceId, ''))
			end

			if(isnull(@AttendanceId, '') <> '')
			begin
				set @jsonData = JSON_MODIFY(@jsonData, '$.AttendanceId', isnull(@AttendanceId, ''))
				set @Remarks = concat(@UserLogin, case when @MovementCode = 'SIGN_IN' then ' is SignIn.' else ' is SignOut.' end)
			end

			if(isnull(@PhysicalAppointmentId, '') <> '')
			begin
				set @jsonData = JSON_MODIFY(@jsonData, '$.PhysicalAppointmentId', isnull(@PhysicalAppointmentId, ''))
				set @jsonData = JSON_MODIFY(@jsonData, '$.EntityName', 'PhysicalAppointment')
				set @jsonData = JSON_MODIFY(@jsonData, '$.EntityId', isnull(@PhysicalAppointmentId, ''))
				set @Remarks = concat(@UserLogin, case when @MovementCode = 'CHECK_IN' then ' is check-in.' else ' is check-out.' end)
			end

			if(isnull(@BreakTransactionId, '') <> '')
			begin
				set @jsonData = JSON_MODIFY(@jsonData, '$.BreakTransactionId', isnull(@BreakTransactionId, ''))
				set @Remarks = concat(@UserLogin, case when @MovementCode = 'BREAK_IN' then ' is on break(BREAK_IN).' else ' is resume on work(BREAK_OUT).' end)
			end

			print @jsonData
			print concat('@Remarks => ', @Remarks )


			if(@Latitude > 0 and @Longitude > 0 and ISNULL(@Address, '') = '')
			begin
				select top 1 @Address = [Address] from TBL_ET_UserLocationTracking(nolock) 
					where UserId = @UserId and ROUND(Latitude, 4) = ROUND(@Longitude, 4) and ROUND(Longitude, 4) = ROUND(@Longitude, 4)
			end


			insert into TBL_ET_UserLocationTrackingBulkRequest(MovementCode, Remarks, UserId, LocationDateTime, Latitude, Longitude, [Address], 
				BatteryPerc, NetworkPerc, CreatedDate, CreatedBy, IsActive, IsMock, IsBulk, Speed, Distance, LocationMetaData, IsDistanceCalc)
			select @MovementCode, @Remarks, @UserId, isnull(@LocationDateTime, getdate()), @Latitude, @Longitude, @Address, 
				0, 0, GETDATE(), @UserId, 1, 1, 1, 0, 0, @jsonData, 1

		end try
		begin catch
			exec usp_InsertErrorInfo
		end catch
	end
end



GO

/* ============================================================
   Procedure: [dbo].[usp_et_LeaveRequestApprovalListByMode]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_et_LeaveRequestApprovalListByMode
(
	@Mode nvarchar(max),
	@SearchText nvarchar(max) = '',
	@Condition varchar(20) = '',
	@FromDate date,
	@ToDate date,
	@UserId bigint,
	@UserIds nvarchar(max) = '',
	@ParentId bigint = 0,
	@OffsetValue int = 0,
	@PagingSize int = 10
)
as
begin
	begin try
		--declare
		--	@Mode nvarchar(max) = 'all',
		--	@SearchText nvarchar(max) = '',
		--	@Condition varchar(20) = 'StartWith',
		--	@FromDate date = '01-Jan-2023',
		--	@ToDate date = '02-Feb-2024',
		--	@UserId bigint = 34594,
		--	@UserIds nvarchar(max) = '34594',
		--	@ParentId bigint = 34594,
		--	@OffsetValue int = 0,
		--	@PagingSize int = 10
		
		select @ParentId = ParentID from User_Detail(nolock) where User_Id = @UserId

		drop table if exists #tempUsers  
		create table #tempUsers(User_ID bigint, Name nvarchar(255), Image nvarchar(255))  
		insert into #tempUsers(User_ID, Name, Image)  
		exec Use_GetUserDetails @UserID = @UserId  

		if(ISNULL(@UserIds, '') =  '') begin set @UserIds = '' end

		drop table if exists #tempSelectedUser
		create table #tempSelectedUser ( UserId bigint )
		insert into #tempSelectedUser(UserId) select [value] from string_split(@UserIds, ',')
	
		declare @StartPoint int  = (@OffsetValue + 1), @EndPoint int = ( @OffsetValue + @PagingSize )
		declare @sqlQuery nvarchar(max),  @sqlQuery1 nvarchar(max), @sqlFinalQuery nvarchar(max)

		set @sqlQuery  = CONCAT(N'select SNo, TotalRecords, LeaveRequestId, LeaveId, FromDate, ToDate, ',
			N'StartQuarterDate, EndQuarterDate, TypeOfLeave, RequestDate, FromTime, ',
			N'ToTime, EmployeeName, Image, ProfilePictureName, UserId, CreatedDate, ',
			N'CreatedBy, UpdatedDate, UpdatedBy, Status, ApproverUserId, ApprovedName, ',
			N'RemarksApprover, ApproverStatus, ApprovedDate, LeaveApprovalId, Remarks, ',
			N'BranchAddress, LastLoginAttendanceIn  from ( select ',
			N'row_number() over (partition by (select null) order by lere.CreatedDate desc ) as SNo, ',
			N'count(1) over() as TotalRecords, ',
			N'lere.LeaveRequestId, lere.LeaveId, Cast(lere.FromDate as varchar(100)) FromDate, ',
			N'cast(lere.ToDate as varchar(100)) ToDate, lere.StartQuarterDate, lere.EndQuarterDate, ',
			N'isnull(TypeOfLeave, ''fullDay'') TypeOfLeave, ',
			N'cast(lere.CreatedDate as varchar(100)) RequestDate, ',
			N'isnull(FromTime , '''') FromTime, isnull(ToTime, '''') ToTime, ',
			N'concat(ud.FName,'' '', ud.LName, '' ('', ud.User_Login, '')'' ) EmployeeName, ',
			N'ud.Image, ud.ProfilePictureName, lere.UserId, lere.CreatedDate, lere.CreatedBy, lere.UpdatedDate, ',
			N'lere.UpdatedBy, (case when lere.IsActive = 1 then ''Active'' ',
				N'else ''InActive'' End) Status, isnull(atra.ApproverUserId, 0) ApproverUserId, ',
			N'concat(ud2.FName, '' '', ud2.LName, ''('', ud2.User_Login, '')'') ApprovedName, ',
			N'isnull(atra.RemarksApprover, '''') RemarksApprover, ',
			N'isnull(atra.ApproverStatus, ''Pending'') ApproverStatus, ',
			N'isnull(atra.ApprovedDate , '''') ApprovedDate, isnull(atra.LeaveApprovalId, 0) LeaveApprovalId, lere.Remarks,  ',
			N'concat( isnull(iutn.Address, '''') , '', '', isnull(ct.City_Name, '''') , '', '' , ',
				N'isnull(st.State_Name, '''') , '', '' , isnull(co.Country_Name, '''') ) BranchAddress, ',
			N'(select top 1 isnull(CONVERT(VARCHAR, AttendanceIn, 100), '''') LastLoginAttendanceIn ',
					N'from TBL_ET_Attendance(nolock) Where UserId = lere.UserId order by 1 desc) LastLoginAttendanceIn ',
		N'from TBL_ET_LeaveRequest(nolock) lere ',
			N'inner join #tempUsers tu on lere.UserId = tu.User_ID ',
			iif(LEN(@UserIds) > 0, 'inner join #tempSelectedUser  su on lere.UserId = su.UserId ', ''), 
			N'inner join User_Detail(nolock) ud on lere.UserId = ud.User_ID ',
			N'left join TBL_ET_LeaveApproval(nolock) atra on lere.LeaveRequestId = atra.LeaveRequestId ',
			N'left join User_Detail(nolock) ud2 on atra.ApproverUserId = ud2.User_ID ',
			N'left join TBL_ET_AttendanceGroupUserMapping (nolock) agum on lere.UserId = agum.UserId ',
			N'left join tbl_inv_UserTaxNumber (nolock) iutn on agum.UserBranchId = iutn.Id ',
			N'left join M_City (nolock) ct on iutn.City_Id = ct.City_Id ',
			N'left join M_State (nolock) st on iutn.State_Id = st.State_Id ',
			N'left join M_Country (nolock) co on iutn.Country_Id = co.Country_Id ',
			N'where ( cast(FromDate as date) between cast(''', @FromDate, ''' as date) and cast(''', @ToDate, ''' as date) ',
				N'or cast(ToDate as date) between cast(''', @FromDate, ''' as date) and cast(''', @ToDate, ''' as date)  ) ',
			N' and 1 = ( case 
				when ''', @Mode, ''' = ''all'' then 1
				when ''', @Mode, ''' = ''pending'' and isnull(atra.ApproverStatus, '''') = '''' then 1
				when ''', @Mode, ''' = ''approved'' and isnull(atra.ApproverStatus, '''') = ''Approved'' then 1
				when ''', @Mode, ''' = ''rejected'' and isnull(atra.ApproverStatus, '''') = ''Rejected'' then 1
			else 0 end ) ',
		N') t  where t.SNo between ', @StartPoint, ' and ', @EndPoint )
	 
		print @sqlQuery
		execute sp_executesql @sqlQuery
	end try
	begin catch
		execute usp_InsertErrorInfo
	end catch
end



GO

