	@StartDate datetime = null,
	@EndDate datetime = null,
	@Remarks varchar(200) = null,     
	@RemarksIn VARCHAR(500) = NULL,
	@RemarksOut VARCHAR(500) = NULL,
	@AttendanceGroupId BIGINT = 0,
	@ShiftId BIGINT = 0,
	@CreatedBy BIGINT = 0,
	@IsActive bit = 1,
	@ParentId bigint = 0
)
as
begin

	--declare
	--	@Mode VARCHAR(2) = N'CI',
	--	@AttendanceId BIGINT = 0,
	--	@PhysicalAppointmentId BIGINT = 0,
	--	@BreakTransactionId bigint = 0,
	--	@BreakTypeId int = 0,
	--	@UserLocationTrackingId bigint = 0,
	--	@LocationList nvarchar(max) = null,
	--	@UserId BIGINT = 34594,
	--	@AttendanceIn DateTime = N'06-Jan-2024 17:26:49',
	--	@AttendanceOut DateTime = NULL,
	--	@CheckIn DateTime = NULL,
	--	@CheckOut DateTime = NULL,
	--	@LatitudeIn float = 21.2128557,
	--	@LongitudeIn float = 72.8234616,
	--	@LatitudeOut float = NULL,
	--	@LongitudeOut float = NULL,
	--	@DeviceId VARCHAR(500) = N'ffTMgWdoQyWrERtBRdQimm:APA91bEVs27OKNIf-9W13e0xr6M6ReinKrz22qQRyJRhaGJRyrVHNtmD3EunvejhA_kCEdbHQLfmWDLxmPB5lJBIwf_BPxhz8j5xBZCwtAKakNTCHssk38kycxizi7pD_ttMZ2LExwiw',
	--	@StartDate datetime = null,
	--	@EndDate datetime = null,
	--	@Remarks varchar(200) = null,     
	--	@RemarksIn VARCHAR(500) = N'',
	--	@RemarksOut VARCHAR(500) = NULL,
	--	@AttendanceGroupId BIGINT = 0,
	--	@ShiftId BIGINT = 0,
	--	@CreatedBy BIGINT = 0,
	--	@IsActive bit = 1,
	--	@ParentId bigint = 0

	select @ParentId = ParentId from User_Detail(nolock) where User_ID = @UserId
	
	insert into tbl_wt_TrackingMetaData( Mode, AttendanceId, PhysicalAppointmentId, BreakTransactionId, BreakTypeId, 
		UserLocationTrackingId, LocationList, UserId, AttendanceIn, AttendanceOut, CheckIn, CheckOut, LatitudeIn, LongitudeIn, 
		LatitudeOut, LongitudeOut, DeviceId, StartDate, EndDate, Remarks, RemarksIn, RemarksOut, AttendanceGroupId, 
		ShiftId, CreatedBy, IsActive, ParentId ) 
	select 
		@Mode, @AttendanceId, @PhysicalAppointmentId, @BreakTransactionId, @BreakTypeId, 
		@UserLocationTrackingId, @LocationList, @UserId, @AttendanceIn, @AttendanceOut, @CheckIn, @CheckOut, @LatitudeIn, @LongitudeIn, 
		@LatitudeOut, @LongitudeOut, @DeviceId, @StartDate, @EndDate, @Remarks, @RemarksIn, @RemarksOut, @AttendanceGroupId,
		@ShiftId, @CreatedBy, @IsActive, @ParentId

	

	declare @tyLocationData tyLocationData


	if(@Mode = 'SI')
	begin
		--select @Mode, @UserId, @AttendanceIn, @LatitudeIn, @LongitudeIn, @DeviceId, @RemarksIn 
		--if(not exists(select 1 from TBL_ET_Attendance(nolock) 
		--	where UserId = @UserId and cast(@AttendanceIn as date) = cast(AttendanceIn as date) 
		--		and AttendanceOut  is null ))
		--begin
			exec usp_tbl_ET_Attendance @Mode = @Mode, @UserId = @UserId, @AttendanceIn = @AttendanceIn, 
				@LatitudeIn = @LatitudeIn, @LongitudeIn = @LongitudeIn, @DeviceId = @DeviceId, @RemarksIn = @RemarksIn

			--insert into @tyLocationData( MovementCode, Remarks, UserId, LocationDateTime, Latitude, Longitude, 
			--	CreatedBy, IsActive, IsMock, IsBulk, Speed, Distance, LocationMetaData, IsDistanceCalc)
			--values( 'SIGN_IN', @RemarksIn, @UserId, @AttendanceIn, @LatitudeIn, @LongitudeIn, @UserId,  1, 0, 0, 0, 0, '{}', 0)
		--end
	end

	if(@Mode = 'CI')
	begin
		--select @Mode, @PhysicalAppointmentId, @UserId, @CheckIn, @LatitudeIn, @LongitudeIn, @DeviceId, @RemarksIn
		exec usp_tbl_ET_GeoEntityCheckInOut @Mode = @Mode, @PhysicalAppointmentId = @PhysicalAppointmentId, @UserId = @UserId,
			@CheckIn = @CheckIn, @LatitudeIn = @LatitudeIn, @LongitudeIn = @LongitudeIn, @DeviceId = @DeviceId, @RemarksIn = @RemarksIn

		--insert into @tyLocationData( MovementCode, Remarks, UserId, LocationDateTime, Latitude, Longitude, 
		--	CreatedBy, IsActive, IsMock, IsBulk, Speed, Distance, LocationMetaData, IsDistanceCalc)
		--values( 'CHECK_IN', @RemarksIn, @UserId, @CheckIn, @LatitudeIn, @LongitudeIn, @UserId,  1, 0, 0, 0, 0, '{}', 0)
	end

	if(@Mode = 'CO')
	begin
		--select @Mode, @PhysicalAppointmentId, @UserId, @CheckOut, @LatitudeOut, @LongitudeOut, @DeviceId, @RemarksOut
		exec usp_tbl_ET_GeoEntityCheckInOut @Mode = @Mode, @PhysicalAppointmentId = @PhysicalAppointmentId, @UserId = @UserId, 
			@CheckOut = @CheckOut, @LatitudeOut = @LatitudeOut, @LongitudeOut = @LongitudeOut, @DeviceId = @DeviceId, @RemarksOut = @RemarksOut
	end

	if(@Mode = 'TI')
	begin
		--select  @Mode, @BreakTransactionId, @BreakTypeId, @UserId, @StartDate, @EndDate, @Remarks, @CreatedBy, @IsActive, @ParentId 
		exec usp_TBL_ET_BreakTransaction @Mode = @Mode, @BreakTransactionId = @BreakTransactionId, @BreakTypeId = @BreakTypeId, 
			@UserId = @UserId, @StartDate = @StartDate, @EndDate = @EndDate, @Remarks = @Remarks, @CreatedBy = @CreatedBy, 
				@IsActive = @IsActive, @ParentId = @ParentId 
	end

	if(@Mode = 'TO')
	begin
		--select  @Mode, @BreakTransactionId, @BreakTypeId, @UserId, @StartDate, @EndDate, @Remarks, @CreatedBy, @IsActive, @ParentId 
		exec usp_TBL_ET_BreakTransaction @Mode = @Mode, @BreakTransactionId = @BreakTransactionId, @BreakTypeId = @BreakTypeId, 
			@UserId = @UserId, @StartDate = @StartDate, @EndDate = @EndDate, @Remarks = @Remarks, @CreatedBy = @CreatedBy,
				@IsActive = @IsActive, @ParentId = @ParentId
	end

	if(@Mode  = 'BT')
	begin
		--select @Mode, @LocationList, @UserId, @CreatedBy, @IsActive
		exec usp_TBL_ET_UserLocationTrackingBulk @Mode = @Mode, @LocationList = @LocationList, @UserId = @UserId, 
			@CreatedBy = @CreatedBy, @IsActive = @IsActive
	end
	
end



