/* ============================================================
   Procedure: [dbo].[usp_et_PhysicalAppointmentSuggestion]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_et_PhysicalAppointmentSuggestion](
	@UserId bigint,
	@FilterText nvarchar(255) = ''
)
as
begin
	--declare 
	--	@UserId bigint = 34594,
	--	@FilterText nvarchar(255) = ''

	select top 10 
		th.PhysicalAppointmentId, 
		concat(th.Title, ' ( ', th.StartDate, '-', th.EndDate, ' )') as [DisplayName] 
		from TBL_ET_PhysicalAppointment(nolock) th 
		inner join TBL_ET_PhyAppointUserMapping(nolock) um on th.PhysicalAppointmentId = um.PhysicalAppointmentId
	where um.UserId = @UserId and th.Title like '%'+@FilterText+'%'
	
end



