	--	@PageSize int = 10 
	
	
	declare @json NVARCHAR(MAX)
	declare @ParentId bigint, @IsAdmin bit
	Select @IsAdmin = IsAdmin, @ParentId = ParentId from User_Detail(NOLOCK) where User_ID = @UserId

	declare @UserIdTeamLst nvarchar(max) = '', @MonthYearName varchar(20) = ''

	drop table if exists #tempUsers  
	create table #tempUsers(User_ID bigint, Name nvarchar(255), Image nvarchar(255))  
	insert into #tempUsers(User_ID, Name, Image)  
	exec Use_GetUserDetails @UserID = @UserId  

	if(ISNULL(@UserIds, '') =  '') begin set @UserIds = '' end

	drop table if exists #tempSelectedUser
	create table #tempSelectedUser ( UserId bigint )
	insert into #tempSelectedUser(UserId) select [value] from string_split(@UserIds, ',')


	set @MonthYearName = CONCAT(MONTH(@FromDate), ' ', YEAR(@FromDate))

	if(@Contain != '') begin set @Contain = ' and ' + @Contain end
	else begin set @Contain = '' end

	declare @StartPoint int  = (@Offset + 1), @EndPoint int = ( @Offset + @PageSize )

	declare @querySql nvarchar(max)
	set @querySql = concat(N'select * from (select ',
		N'count(t.ParentID) over() as TotalRecords, ',
		N'ROW_NUMBER() over(partition by (select null) order by t.UserName) SNo, ',
		N't.* from ( ',
		N'select teum.AttendanceGroupId, teag.AttendanceGroupName, ',
		N'concat(ud.FName, '' '', ud.LName)  UserName, ud.Mobile, ',
		N'ud.User_ID, ud.ParentID, ud.User_Login, ',
		N'isnull(ud.FName,'''') + '' '' + isnull(ud.LName,'''')  as   UserFullName, ',
		N'concat(ud.FName, '' '', ud.LName, '' ('', ud.User_Login, '')'') EmployeeName, ',
		N'concat(udpa.FName, '' '', udpa.LName, '' ('', udpa.User_Login, '')'') ManagerParent, '''' Designetion, ',
		N'ud.Image, ud.ProfilePictureName, ',
		N'''' + @MonthYearName + ''' MonthYearName, ',
		N'dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''TotalWorkingDay'') PresentDays, ',
		N'isnull(dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''FullDays''),0) FullDays, ',
		N'dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''HalfDays'') HalfDays, ',
		N'isnull(dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''ShortDays''),0) ShortDays, ',
		N'dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''WeekOff'') WeeklyOffDays, ',
		N'dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''TotalLeave'') OnLeaveDays, ',
		N'dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''TotalDays'') TotalDays, ',
		N'dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''LateSignin'') InLateDays, ',
		N'dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''OutEarlyDays'') OutEarlyDays, ',
		N'dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''Totalminutes'') TotalAttendanceTime, ',
		N'dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''NumberOfBreaks'') NumberOfBreaks, ',
		N'dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''TimeInBreaks'') TimeInBreaks, ',
		N'dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''MaxBreakTimes'') MaxBreakTimes, ',
		N'dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''TotalTask'') TotalTask, ',
		N'dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''TimeSpentInTasks'') TimeSpentInTasks, ',
		N'isnull(dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''HolidayDays''),0) HolidayDays, ',
		N'dbo.fn_TBL_ET_GeoEntityCheckInOutCount(ud.User_ID, cast(''', @FromDate, ''' as varchar(20)), ''CheckInCount'') CheckInCount, ',
		N'dbo.fn_TBL_ET_GeoEntityCheckInOutCount(ud.User_ID, cast(''', @FromDate, ''' as varchar(20)), ''CheckInRequest'') CheckInRequestCount, ',
		N'dbo.fn_TBL_ET_GeoEntityCheckInOutCount(ud.User_ID, cast(''', @FromDate, ''' as varchar(20)), ''CheckOutCount'') CheckOutCount, ',
		N'dbo.fn_TBL_ET_GeoEntityCheckInOutCount(ud.User_ID, cast(''', @FromDate, ''' as varchar(20)), ''CheckOutRequest'') CheckOutRequestCount, ',
		N'isnull(dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''SignIn''),0) SignInCount, ',
		N'isnull(dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''SignInRequest''),0) SignInRequestCount, ',
		N'isnull(dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''SignOut''),0) SignOutCount, ',
		N'isnull(dbo.fn_TBL_ET_AttendanceTotalSummary(ud.User_ID, ''', @FromDate, ''', ''SignOutRequest''),0) SignOutRequestCount, ',
		N'dbo.fn_TBL_ET_ExpenseTotalSummary(ud.User_ID, ''', @FromDate, ''', ''TotalTimeSpentTravelled'') TotalTimeSpentTravelled, ',
		N'dbo.fn_TBL_ET_ExpenseTotalSummary(ud.User_ID, ''', @FromDate, ''', ''TotalClaim'') TotalClaim, ',
		N'dbo.fn_TBL_ET_ExpenseTotalSummary(ud.User_ID, ''', @FromDate, ''', ''TotalApproved'') TotalApproved, ',
		N'dbo.fn_TBL_ET_ExpenseTotalSummary(ud.User_ID, ''', @FromDate, ''', ''TotalDistance'') TotalDistance, ',
		N'isnull(dbo.fn_TBL_ET_ExpenseTotalSummary(ud.User_ID, ''', @FromDate, ''', ''TotalTravelTime''), 0) TotalTravelTime, ',
		N''''' TeamName,  0 HirarchyParentid ',
		N'from User_Detail(nolock) ud ',
		N'inner join #tempUsers tu on ud.User_ID = tu.User_ID ',
		iif(LEN(@UserIds) > 0, 'inner join #tempSelectedUser  su on ud.User_Id = su.UserId ', ''),
		N'inner join TBL_ET_AttendanceGroupUserMapping(nolock) teum on ud.User_Id = teum.UserId ',
		N'inner join TBL_ET_AttendanceGroup(nolock) teag on teum.AttendanceGroupId = teag.AttendanceGroupId ',
		N'inner join User_Detail(nolock) udpa on ud.ParentId = udpa.User_Id where ',
		--N'inner join #TblHirarchy thia on ud.User_Id = thia.User_Id   ',
		--N'(ud.User_ID in (select [value] from dbo.fn_Split(''' + @UserIdTeamLst + ''', '','')) and  ',
		N'teag.AttendanceGroupId = (case when '''+ cast(@AttendanceGroupId as varchar(10)) +''' > 0 then ', 
		N'''' + cast(@AttendanceGroupId as varchar(10)) + ''' else teag.AttendanceGroupId end)) ', 
		N' t where ( 1 = 1 ) ', @Contain, N' ) tt where tt.SNo between ', @StartPoint, ' and ', @EndPoint	
	)
	
	print @querySql

	execute sp_executesql @querySql

end




GO

/* ============================================================
   Procedure: [dbo].[usp_et_Rtp_GetAttendanceList_Cache]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE [dbo].[usp_et_Rtp_GetAttendanceList_Cache](
	@Mode nvarchar(2),
	@SearchText nvarchar(255) = '',
	@FromDate date,
	@ToDate date,
	@AttendanceGroupId bigint = 0,
	@Contain nvarchar(max) = '',
	@Condition nvarchar(max) = '',
	@UserId bigint,
	@UserIds nvarchar(max) = '',
	@Offset int = 0,
	@PageSize int = 10 
)
as
begin

	
	
	DECLARE @MonthStart DATETIME;
	DECLARE @MonthEnd DATETIME;
	declare @ParentID bigint = 0;		

			select @ParentID = ParentID from Mysms.[dbo].User_Detail(nolock) where User_ID = @UserId;

				-- Get the first and last date of the current month
				--SET @MonthStart = FORMAT(DATEADD(DAY, 1 - DAY(GETDATE()), CAST(GETDATE() AS DATE)), 'dd-MMM-yyyy'); -- First day of current month
				--SET @MonthEnd = FORMAT(EOMONTH(GETDATE()), 'dd-MMM-yyyy'); -- Last day of current month

				Declare @Currentdate  DATE  = GETDATE();  -- Today's date
				SET @MonthStart      = FORMAT(DATEADD(DAY, -30, @Currentdate), 'dd-MMM-yyyy'); -- 30 days before today
				SET @MonthEnd  =  FORMAT(DATEADD(DAY, -1, @Currentdate), 'dd-MMM-yyyy');

				if(ISNULL(@UserIds, '') =  '') begin set @UserIds = '' end

				declare @MonthYearFromDate varchar(20) = '', @MonthYearToDate varchar(20) = ''
				set @MonthYearFromDate = CONCAT(MONTH(@FromDate), ' ', YEAR(@FromDate))

				set @MonthYearToDate = CONCAT(MONTH(@ToDate), ' ', YEAR(@ToDate))

				-- Check conditions and select data
				IF (@FromDate Between @MonthStart AND @MonthEnd AND @ToDate Between @MonthStart AND @MonthEnd)    
					BEGIN
						 SELECT [AttendanceMasterId]
								  ,[TotalRecords]
								  ,[SNo]
								  ,[User_Id]
								  ,[AttendanceGroupId]
								  ,[AttendanceGroupName]
								  ,[UserName]
								  ,[Mobile]
								  ,[ManagerParent]
								  ,[Designetion]
								  ,[TeamName]
								  ,[HirarchyParentid]
								  ,[MonthYearName]
								  ,[PresentDays]
								  ,[HalfDays]
								  ,[WeeklyOffDays]
								  ,[OnLeaveDays]
								  ,[TotalDays]
								  ,[InLateDays]
								  ,[OutEarlyDays]
								  ,[TotalAttendanceTime]
								  ,[NumberOfBreaks]
								  ,[TimeInBreaks]
								  ,[MaxBreakTimes]
								  ,[TotalTask]
								  ,[TimeSpentInTasks]
								  ,[User_Login]
								  ,[UserFullName]
								  ,[TotalTimeSpentTravelled]
								  ,[TotalClaim]
								  ,[TotalApproved]
								  ,[TotalDistance]
								  ,[TotalTravelTime]
								  ,[ProfilePictureName]
								  ,[FullDays]
								  ,[ShortDays]
								  ,[HolidayDays]
								  ,[CheckInCount]
								  ,[CheckInRequestCount]
								  ,[CheckOutCount]
								  ,[CheckOutRequestCount]
								  ,[SignInCount]
								  ,[SignInRequestCount]
								  ,[SignOutCount]
								  ,[SignOutRequestCount]
								  ,[ParentId]
								  ,[UserId]
								  ,[EmployeeName]
								  ,[Image]
							      FROM [dbo].[tbl_AttendanceMaster_Cache](nolock)
								  WHERE [UserId]= @UserId  and [ParentId] = @ParentId and [MonthYearName] between @MonthYearFromDate and @MonthYearToDate and (@UserIds = '' OR UserId = @UserIds)
					END
					ELSE IF (@FromDate < @MonthStart OR @ToDate < @MonthStart)
						BEGIN
							SELECT [AttendanceMasterId]
								  ,[TotalRecords]
								  ,[SNo]
								  ,[User_Id]
								  ,[AttendanceGroupId]
								  ,[AttendanceGroupName]
								  ,[UserName]
								  ,[Mobile]
								  ,[ManagerParent]
								  ,[Designetion]
								  ,[TeamName]
								  ,[HirarchyParentid]
								  ,[MonthYearName]
								  ,[PresentDays]
								  ,[HalfDays]
								  ,[WeeklyOffDays]
								  ,[OnLeaveDays]
								  ,[TotalDays]
								  ,[InLateDays]
								  ,[OutEarlyDays]
								  ,[TotalAttendanceTime]
								  ,[NumberOfBreaks]
								  ,[TimeInBreaks]
								  ,[MaxBreakTimes]
								  ,[TotalTask]
								  ,[TimeSpentInTasks]
								  ,[User_Login]
								  ,[UserFullName]
								  ,[TotalTimeSpentTravelled]
								  ,[TotalClaim]
								  ,[TotalApproved]
								  ,[TotalDistance]
								  ,[TotalTravelTime]
								  ,[ProfilePictureName]
								  ,[FullDays]
								  ,[ShortDays]
								  ,[HolidayDays]
								  ,[CheckInCount]
								  ,[CheckInRequestCount]
								  ,[CheckOutCount]
								  ,[CheckOutRequestCount]
								  ,[SignInCount]
								  ,[SignInRequestCount]
								  ,[SignOutCount]
								  ,[SignOutRequestCount]
								  ,[ParentId]
								  ,[UserId]
								  ,[EmployeeName]
								  ,[Image]
							      FROM [dbo].[tbl_AttendanceMaster_Archive](nolock)
								  WHERE [UserId]= @UserId  and [ParentId] = @ParentId and [MonthYearName] between @MonthYearFromDate and @MonthYearToDate and (@UserIds = '' OR UserId = @UserIds)
						END
					ELSE
					BEGIN
						EXEC [Mysms].[dbo].usp_et_Rtp_GetAttendanceList @Mode, @SearchText, @FromDate, @ToDate, @AttendanceGroupId, @Contain, @Condition, @UserId, @UserIds, @Offset, @PageSize;
					END

end



GO

/* ============================================================
   Procedure: [dbo].[usp_et_UpdateDistanceCalculationsMannullyUpdate]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_et_UpdateDistanceCalculationsMannullyUpdate(
	@UserId bigint,
	@prevDate datetime
)
as
begin

	--declare 
	--	@UserId bigint = 43772,
	--	@prevDate datetime = '20240116'

	begin try
		declare @LastDistance decimal(18, 4)  = 0,
			@prevLatitude float = null,
			@prevLongitude float = null,				
			@UserLocationTrackingId bigint = 0


		select top 1 @UserLocationTrackingId = UserLocationTrackingId, 
			@prevLatitude = Latitude, @prevLongitude = Longitude, @LastDistance = TRY_CONVERT(decimal(18, 4), Distance), @prevDate = LocationDateTime
		from TBL_ET_UserLocationTracking(nolock) where UserId = @UserId and cast(LocationDateTime as date) = cast(@prevDate as date)  order by UserLocationTrackingId asc

		--if(cast(@prevDate as date) > cast(@prevDate as date))
		--begin
		--	set @LastDistance = 0
		--end

		if(exists(select 1 from TBL_ET_UserLocationTracking(nolock) where UserId = @UserId and 
			 cast(LocationDateTime as date) = cast(@prevDate as date) and @UserLocationTrackingId > 0))
		begin
		
			select @LastDistance, @prevLatitude, @prevLongitude, @prevDate, @UserLocationTrackingId

			update t set t.Distance = b.lagSum from TBL_ET_UserLocationTracking(nolock) t
				inner join (
				select 
					c.UserLocationTrackingId,
					@LastDistance + sum(round((case 
						when @LastDistance = 0 and c.MovementCode = 'SIGN_IN' and c.SNO = 1  then 0 
					else geography::Point(c.prevLatitude, c.prevLongitude, 4326)
						.STDistance(geography::Point(c.Latitude, c.Longitude, 4326)) end), 3)) over (partition by c.UserId
						order by UserLocationTrackingId	
					) [lagSum] from ( 
				select UserLocationTrackingId, MovementCode, UserId, LocationDateTime, Latitude, Longitude, Distance, 
					lag(Latitude, 1, @prevLatitude) over (partition by UserId, cast(LocationDateTime as date) 
						order by UserLocationTrackingId asc) as [prevLatitude],
					lag(Longitude, 1, @prevLongitude) over (partition by UserId, cast(LocationDateTime as date) 
						order by UserLocationTrackingId asc) as [prevLongitude],
					row_number() over (partition by UserId, MovementCode order by UserLocationTrackingId asc) as SNO
				from TBL_ET_UserLocationTracking(nolock) where UserId = @UserId and UserLocationTrackingId >= @UserLocationTrackingId 
					and cast(LocationDateTime as date) = cast(@prevDate as date) )
			 c) b on t.UserLocationTrackingId = b.UserLocationTrackingId


			--select t.*, b.lagSum, b.UserLocationTrackingId from TBL_ET_UserLocationTracking(nolock) t
			--	inner join (
			--	select 
			--		c.UserLocationTrackingId,
			--		@LastDistance + sum(round((case 
			--			when @LastDistance = 0 and c.MovementCode = 'SIGN_IN' and c.SNO = 1  then 0 
			--		else geography::Point(c.prevLatitude, c.prevLongitude, 4326)
			--			.STDistance(geography::Point(c.Latitude, c.Longitude, 4326)) end), 3)) over (partition by c.UserId
			--			order by UserLocationTrackingId	
			--		) [lagSum] from ( 
			--	select UserLocationTrackingId, MovementCode, UserId, LocationDateTime, Latitude, Longitude, Distance, 
			--		lag(Latitude, 1, @prevLatitude) over (partition by UserId, cast(LocationDateTime as date) 
			--			order by UserLocationTrackingId asc) as [prevLatitude],
			--		lag(Longitude, 1, @prevLongitude) over (partition by UserId, cast(LocationDateTime as date) 
			--			order by UserLocationTrackingId asc) as [prevLongitude],
			--		row_number() over (partition by UserId, MovementCode order by UserLocationTrackingId asc) as SNO
			--	from TBL_ET_UserLocationTracking(nolock) where UserId = @UserId and UserLocationTrackingId >= @UserLocationTrackingId 
			--		and cast(LocationDateTime as date) = cast(@prevDate as date) )
			-- c) b on t.UserLocationTrackingId = b.UserLocationTrackingId
			
		end
	end try
	begin catch
		 DECLARE @ErrorMessage NVARCHAR(4000);  
		 SELECT @ErrorMessage = ERROR_MESSAGE();  
		 RAISERROR ( @ErrorMessage, 16, 1);  
	end catch
end



GO

/* ============================================================
   Procedure: [dbo].[usp_et_UpdateUserLocationTrackingBlankAddress]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_et_UpdateUserLocationTrackingBlankAddress(
	@UserLocationTrackingId bigint,
	@fetchedAddress nvarchar(255)
)
as
begin
	update TBL_ET_UserLocationTrackingBlankAddress set 
		isFatched = 2,
		updatedAddress = @fetchedAddress,
		updatedOn = getdate()
			where UserLocationTrackingId = @UserLocationTrackingId
end



