/* ============================================================
   Procedure: [dbo].[usp_et_UserLocationTrackingArchiving]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_et_UserLocationTrackingArchiving  
AS  
BEGIN  
 DROP TABLE IF EXISTS #ids;      
 CREATE TABLE #ids(id BIGINT)  
 declare @c int   
 SELECT @c = COUNT(1) FROM tbl_et_UserLocationTracking(NOLOCK)   
  WHERE CAST(CreatedDate AS DATE) < DATEADD(d, -30, CAST(GETDATE() AS DATE));      
  
  
 WHILE @c > 0      
 BEGIN      
  INSERT INTO tbl_et_UserLocationTracking_Archived(UserLocationTrackingId, MovementCode, Remarks, UserId, LocationDateTime, Latitude, Longitude, Address, BatteryPerc, NetworkPerc, CreatedDate, CreatedBy, IsActive, IsMock, IsBulk, Speed, Distance, LocationMetaData, IsDistanceCalc)      
   OUTPUT inserted.UserLocationTrackingId AS id INTO #ids      
  SELECT TOP 1000 UserLocationTrackingId, MovementCode, Remarks, UserId, LocationDateTime, Latitude, Longitude, Address, BatteryPerc, NetworkPerc, CreatedDate, CreatedBy, IsActive, IsMock, IsBulk, Speed, Distance, LocationMetaData, IsDistanceCalc  
  FROM tbl_et_UserLocationTracking(NOLOCK) WHERE CAST(CreatedDate AS DATE) < DATEADD(d, -30, CAST(GETDATE() AS DATE));      
          
  DELETE s FROM tbl_et_UserLocationTracking s JOIN #ids i ON i.id = s.UserLocationTrackingId;      
  TRUNCATE TABLE #ids;      
  SET @c = @c - 1000;      
 END;  
   
 TRUNCATE TABLE #ids;      
 SET @c = 0  
 SELECT @c = COUNT(1) FROM tbl_et_UserLocationTrackingBulkRequest(NOLOCK)   
  WHERE CAST(CreatedDate AS DATE) < DATEADD(d, -2, CAST(GETDATE() AS DATE));      
  
 WHILE @c > 0      
 BEGIN      
  INSERT INTO tbl_et_UserLocationTrackingBulkRequest_Archived(UserLocationTrackingId, MovementCode, Remarks, UserId, LocationDateTime, Latitude, Longitude, Address, BatteryPerc, NetworkPerc, CreatedDate, CreatedBy, IsActive, IsMock, IsBulk, Speed, Distance, LocationMetaData, IsDistanceCalc, IsProcess, ProcessAt, ErrorDescription)      
   OUTPUT inserted.UserLocationTrackingId AS id INTO #ids      
  SELECT TOP 1000 UserLocationTrackingId, MovementCode, Remarks, UserId, LocationDateTime, Latitude, Longitude, Address, BatteryPerc, NetworkPerc, CreatedDate, CreatedBy, IsActive, IsMock, IsBulk, Speed, Distance, LocationMetaData, IsDistanceCalc, IsProcess, ProcessAt, ErrorDescription   
  FROM tbl_et_UserLocationTrackingBulkRequest(NOLOCK) WHERE CAST(CreatedDate AS DATE) < DATEADD(d, -2, CAST(GETDATE() AS DATE));      
          
  DELETE s FROM tbl_et_UserLocationTrackingBulkRequest s JOIN #ids i ON i.id = s.UserLocationTrackingId;      
  TRUNCATE TABLE #ids;      
  SET @c = @c - 1000;      
 END;  
  
 DROP TABLE IF EXISTS #ids;  
END  



GO

