CREATE   PROCEDURE dbo.Usp_EventTemplate_DynamicVarReplacement --'SMS sent to lead',335,'This is testing123','7266895785'          
(          
   @EventName nvarchar(500) = null          
  ,@UserID  bigint  = null --#username#          
  ,@Message nvarchar(max) = null  --"#Messagecontent#"          
  ,@Mobile nvarchar(50)  = null  -- #mobileno#          
  ,@LeadID bigint  = null    -- #leadname#            
  ,@linklongurl nvarchar(500)  = null -- #linklongurl#          
  ,@MessageSentDate nvarchar(50) = null  -- #messagesentdate#           
  ,@SMSTemplateID bigint = null --  ##mailtemplate#          
  ,@MailTemplateID bigint  = null  -- #mailtemplate#               
  ,@Subject nvarchar(500) = null  -- "#MailSubject#"           
  ,@EmailID nvarchar(500) = null  -- #emailid#          
  ,@AppID bigint  = null -- #ivrname#           
  ,@DID_No nvarchar(50) = null -- #didno#           
  ,@Callduration int = null  -- #callduration#          
  ,@RecordURL  nvarchar(500) = null -- #recordurl#          
  ,@LeadColumnName nvarchar(500) = null -- #leadcolumname#           
  ,@OldValue nvarchar(500)  = null --  #oldvalue#          
  ,@NewValue nvarchar(500) = null  -- #newvalue#          
  ,@FollowupStatusID nvarchar(50) = null --  #followupstatus#          
  ,@AssignedTo bigint = null -- #assignedTo#          
  ,@TicketType nvarchar(500) = null -- #tickettype#           
  ,@TicketTitle nvarchar(500) = null  -- #tickettitle#          
  ,@Priority nvarchar(200) = null --  #priority#          
  ,@TicketCreationDate nvarchar(50 ) = null --  #ticketcreationdate#          
  ,@LatencyHours nvarchar(50) = null  --  #latencyinhours#          
  ,@TimeTakenResolvingHours  nvarchar(50) = null  -- #timetakentoresolvein hours#              
  ,@UserOrGroup nvarchar(500) = null -- #user/group#           
  ,@EshopDomain nvarchar(500) = null -- #eshopdomain#          
  ,@UserNameOrLeadName nvarchar(500) = null -- #username/leadname#          
  ,@EnquiryNoOrLeadNo nvarchar(50) = null  -- #enquiryno/leadno#          
  ,@ModeOfPayment nvarchar(200) = null  --  #modeofpayment#          
  ,@OrderNo nvarchar(50) = null --  #orderno#           
  ,@NoOfItems nvarchar(50) = null -- #no.ofitems#          
  ,@TotalAmount nvarchar(50) = null -- #totalamount#          
  ,@OrderDate nvarchar(50) = null  -- #orderdate#          
  ,@ReturnRequestNo nvarchar(40) = null -- #returnrequestno#          
  ,@ProductName nvarchar(500) = null -- #productname#          
  ,@NoOfStars nvarchar(50) = null  --  #no. of stars#          
  ,@ReviewComment nvarchar(500) = null -- #reviewcomment#          
  ,@LandingPageName nvarchar(500) = null --  #landingpagename#          
  ,@WebFormName nvarchar(500) = null    -- #webform#           
  ,@EnquiryNo nvarchar(50) = null  -- #enquiryno#          
  ,@DocName nvarchar(500) = null  -- #docname#          
  ,@NoteAddedDate nvarchar(50) = null -- #NoteAddedDate#              
  --,@chkMobile1 bit        
  --,@chkMobile2 bit        
  --,@chkMobile3 bit        
             
)          
as          
Begin          
          
  Declare @UserName nvarchar(200) = ''          
  Declare @LeadName nvarchar(200) = ''          
  Declare @EventDescription nvarchar(max) = ''          
  Declare @EventTemplate nvarchar(max)= ''          
  Declare @EventID bigint = 0          
  Declare @IVRName nvarchar(500) = ''           
  Declare @AssignToName nvarchar(500) = ''         
  Declare @FollowupStatusName nvarchar(500) = ''      
         
          
  select @UserName = isnull(User_Login,'') from User_Detail(nolock) where User_ID = isnull(@UserID,0)          
  select @LeadName = isnull(personName,'') from UserLeads(nolock) where id = isnull(@LeadID,0)            
  select @IVRName = isnull(APPNAME,'') from Cloud_app_master(nolock) where AppId = isnull(@AppID,0)          
  Select @AssignToName = isnull(user_login,'') from User_Detail(nolock) where User_ID = isnull( @AssignedTo,0)          
  Select @FollowupStatusName = ISNULL(FollowupStatus,'') from  FollowUp_Status(nolock) where ID =isnull(nullif(@FollowupStatusID,''),0)      
        
   --if(rtrim(ltrim(@Mobile)) = '')        
   --   Begin        
            
   --   if(@chkMobile1 = 1)        
   --   Begin     
   --         select @Mobile = isnull(MobileNo,'') from UserLeads where id = isnull(@LeadID,0)            
   --      End        
           
   --   if(@chkMobile2 = 1)        
   --   Begin        
   --         select @Mobile = isnull(MobileNo1,'') from UserLeads where id = isnull(@LeadID,0)            
   --      End        
           
   --   if(@chkMobile3 = 1)        
   --   Begin        
   --         select @Mobile = isnull(MobileNo2,'') from UserLeads where id = isnull(@LeadID,0)            
   --      End        
           
        
        
   --End        
        
        
         
          
          
  if(rtrim(ltrim(@Message)) = '')          
     Begin          
   if(@SMSTemplateID > 0)          
     Begin          
       select @Subject = ISNULL(MailSubject,''), @Message = ISNULL(MailContent,'')  from usermailTemplate(nolock) where ID = @SMSTemplateID           
        End          
         else if(@MailTemplateID > 0)          
     Begin          
       select  @Message = ISNULL(MailContent,'')  from usermailTemplate(nolock) where ID = @MailTemplateID           
        End          
  End                 
                          
   select @EventID = isnull(ID,0) ,@EventTemplate = ISNULL(EventTemplate,'') from ActivityMaster(nolock) where EventName = @EventName           
          
   if(@EventID > 0)          
     Begin          
            
  Select @EventDescription =          
   Replace(Replace(Replace(Replace(Replace(Replace(Replace(Replace(Replace(Replace(Replace( Replace(REplace(Replace(Replace(Replace(Replace(Replace(Replace(Replace(Replace(Replace(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REplace(Replace(REPLACE(Replace    
 
     
   (REPLACE(Replace(Replace(Replace(Replace(Replace( Replace(Replace(Replace(Replace(REPLACE (isnull(@EventTemplate,''),'#username#', isnull  (@UserName,'')),'#Messagecontent#',isnull(@Message,'')),'#mobileno#',isnull(@Mobile,'')),'#leadname#'
   ,isnull(@LeadName,'')),'#linklongurl#',isnull(@linklongurl,'')),'#messagesentdate#',isnull(@MessageSentDate,'')),'#mailtemplate#',isnull(@Message,'')),'#MailSubject#',isnull(@Subject,'')),'#emailid#'
   ,isnull(@EmailID,'')),'#ivrname#',isnull (@IVRName,'')),'#didno#',isnull(@DID_No,'')),'#callduration#',isnull(@Callduration,'0')),'#recordurl#',isnull(@RecordURL,'')),'#leadcolumname#',isnull(@LeadColumnName,''))          
    ,'#oldvalue#',isnull(@OldValue,'')),'#newvalue#',isnull(@NewValue,'')),'#followupstatus#',isnull(@FollowupStatusName,'')),'#assignedTo#',isnull(@AssignToName,'')),'#tickettype#'          
    ,isnull (@TicketType,'')),'#tickettitle#',isnull(@TicketTitle,'')),'#priority#',isnull(@Priority,'')),'#ticketcreationdate#',isnull(@TicketCreationDate,'')),'#latencyinhours#'          
     ,isnull(@LatencyHours,'0')),'#timetakentoresolvein hours#',isnull(@TimeTakenResolvingHours,'0')),'#user/group#',isnull(@UserOrGroup,'')),'#eshopdomain#',isnull(@EshopDomain,''))          
  ,'#username/leadname#',isnull(@UserNameOrLeadName,'')),'#enquiryno/leadno#',isnull(@EnquiryNoOrLeadNo,'')),'#modeofpayment#',isnull(@ModeOfPayment,''))          
 ,'#orderno#',isnull(@OrderNo,'0')),'#no.ofitems#',isnull(@NoOfItems,'0')),'#totalamount#',isnull(@TotalAMount,'0')),'#orderdate#',isnull(@OrderDate,'')),'#returnrequestno#'          
  ,isnull(@ReturnRequestNo,'0')),'#productname#',isnull(@ProductName,'')),'#no. of stars#',isnull(@NoOfStars,'0')),'#reviewcomment#',isnull(@ReviewComment,''))          
  ,'#landingpagename#',isnull(@LandingPageName,'')),'#webform#',isnull(@WebFormName,'')),'#enquiryno#',isnull(@EnquiryNo,'0')),'#docname#',isnull(@DocName,'')),'#NoteAddedDate#'          
  ,isnull(@NoteAddedDate,''))          
            
   End          
          
     select isnull(@EventDescription,'') as EventDescription          
              
End


