/* ============================================================
   Procedure: [dbo].[usp_ExecEnquiryTriggerTasks]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_ExecEnquiryTriggerTasks] (        
 @CsvEnquiryID  nvarchar(max)        
)        
AS            
BEGIN
     if(@CsvEnquiryID is null or @CsvEnquiryID = '' )
	   begin
	       insert into idnullinproc
		    (IdName,ProcName,Metadata)
			select '@CsvEnquiryID','usp_ExecEnquiryTriggerTasks', @CsvEnquiryID
	   end
	   else
	 begin
		
 print 'starting procedure usp_ExecEnquiryTriggerTasks'        
   
   DECLARE @RecCnt bigint  =0            
   ,@enquiryid BIGINT            
   ,@mobile NVARCHAR(max)            
   ,@email NVARCHAR(max)            
   ,@mobile1 NVARCHAR(max)            
   ,@email1 NVARCHAR(max)            
   ,@mobile2 NVARCHAR(max)            
   ,@email2 NVARCHAR(max)            
   ,@minrow BIGINT            
   ,@maxrow BIGINT            
   ,@parentid bigint            
  
 -- SET NOCOUNT ON added to prevent extra result sets from            
 -- interfering with SELECT statements.           
        
 SET NOCOUNT ON;        
         
 if(ISNULL(@CsvEnquiryID, '') = '')        
 begin        
  return;        
 end        
        
 drop table if exists #csvEnquriyId        
 create table #csvEnquriyId(        
  EnquiryId bigint        
 )        
 insert into #csvEnquriyId (EnquiryId)        
  select [value] from string_split(@CsvEnquiryID, ',')        
   
   
select top 1 @enquiryid=enquiryid from #csvEnquriyId  
select top 1 @parentid=parentid from userenquiry(nolock) where enquiryid=@enquiryid  
  --alter table #csvenquiryid add isdup_m int default 0,isdup_e int default 0      
 if(exists(select 1 from #csvEnquriyId))        
 begin        
  DROP TABLE IF EXISTS #temp;        
  DECLARE @tbl AS LeadActivitywithid_Tbltype            
            
  INSERT INTO @tbl ( LeadID, UserID, ParentID, EventDescription, EventName, reftable, Refid )            
   SELECT i.enquiryID, i.CreatedBy, i.ParentID,         
   'Enquiry with ' + isnull('name ' + isnull(nullif(i.personname, ''),''), 'no name') + ' is added to Enquiry by ' + u.user_login, 'Enquiry added', 'Userenquiry', i.EnquiryID            
   FROM UserEnquiry i (nolock)           
   inner join #csvEnquriyId t(nolock) on i.EnquiryID =  t.EnquiryId        
   JOIN user_detail(NOLOCK) u ON u.user_id = i.CreatedBy            
   WHERE NOT EXISTS ( SELECT 1 FROM tbl_EnquiryEventHistory(NOLOCK)            
     WHERE enquiryid = i.EnquiryID AND eventid = 119 )            
            
  EXEC UspSaveentityActivity_withMultipleValue_withid @tbl     
    
    
delete from @tbl    
  INSERT INTO @tbl ( LeadID, UserID, ParentID, EventDescription, EventName, reftable, Refid )            
  SELECT distinct ulme_id        
  ,CreatedBy        
  ,i.ParentID        
  ,'Lead with ' + isnull('name ' + isnull(nullif(personname, ''),''), 'no name') + ' expressed a new interest through enquiryno ' + cast(i.enquiryid as    
  nvarchar)    
  ,'Lead generated new enquiry'        
  ,'Userenquiry'        
  ,i.EnquiryID        
 --FROM inserted i        
 from userenquiry i with (nolock) join #csvEnquriyId c on c.EnquiryId=i.EnquiryID  
 JOIN userleads_mobile_email(NOLOCK) u ON i.parentid=u.parentid and    
 ((u.mobile <>'0' and u.mobile in (isnull(i.MobileNo,'1'),isnull(i.MobileNo2,'1'),isnull(i.MobileNo1,'1')))        
 or     
 (u.email<>'0' and u.email in (isnull(i.emailid,'2'),isnull(i.emailid1,'2'),isnull(emailid2,'2')) ))    
 and datediff(mi,u.leadcreateddate ,i.CreatedDate)>5--u.leadcreateddate<dateadd(mi,-5,getdate())  
 and  
 not exists    
 (select 1 from tbl_leadeventhistory(nolock) where eventid=28 and refids=i.enquiryid and leadid=ulme_id)    
    
      
    EXEC UspSaveentityActivity_withMultipleValue_withid @tbl     
    
       
            
  --SELECT row_number() OVER (            
  --   ORDER BY EnquiryID            
  --   ) AS ROWNO, * into #temp FROM inserted            
  -- SELECT *            
  --INTO #temp FROM (SELECT row_number() OVER (            
  --   ORDER BY EnquiryID            
  --   ) AS ROWNO, * FROM inserted) temp            
            
  -- select * from #temp             
            
  SELECT @minrow = MIN(EnquiryID)            
   ,@maxrow = max(EnquiryID)            
   ,@RecCnt = count(*)            
  FROM #csvEnquriyId;            
            
  print cast (@minrow as varchar)             
  BEGIN TRY            
             
    WHILE @minrow <= @maxrow and @RecCnt >0            
    BEGIN            
     SELECT @enquiryid = EnquiryID, @mobile = mobileno, @email = emailid, @mobile1 = MobileNo1, @email1 = emailid1,         
   @mobile2 = MobileNo2, @email2 = EmailID2, @parentid=parentid            
     FROM UserEnquiry(nolock)  WHERE EnquiryID = @minrow            
            
     IF EXISTS (SELECT * FROM ( SELECT * FROM userenquiry_mobile_email WITH(NOLOCK)            
     WHERE userenquiry_mobile_email.Parentid = @parentid AND userenquiry_mobile_email.mobile <> '0' AND enquiryid <> @enquiryid            
     ) Mobile WHERE -- Mobile.row > 1 AND             
      Mobile.mobile IN ( @mobile ,@mobile1,@mobile2 ))            
     BEGIN            
    UPDATE UserEnquiry SET IsduplicateMobile = 1 WHERE EnquiryID = @enquiryid            
   --SELECT 'Isdublicate mobile = 1'            
     END            
            
     IF EXISTS ( SELECT * FROM ( SELECT * FROM userenquiry_mobile_email (nolock)       
     WHERE userenquiry_mobile_email.Parentid = @parentid        
      AND userenquiry_mobile_email.email <> '1' AND enquiryid <> @enquiryid        
     ) email            
    WHERE -- email.row > 1 AND             
      Email.email IN ( @email, @email1, @email2 ))            
     BEGIN            
   UPDATE UserEnquiry SET IsduplicateEmail = 1 WHERE EnquiryID = @enquiryid        
     END            
            
     SELECT @minrow = MIN(EnquiryId) FROM #csvEnquriyId  where EnquiryId > @minrow            
               
        
     --SET @minrow = @minrow + 1            
  END            
  END TRY            
            
  BEGIN CATCH            
   --print '---- Procedure Error: usp_ExecLeadTriggerTasks on ' + Convert(Varchar,GetDate(),13) + ' ----'            
   insert into tmp_error_report(ErrorNumber,ErrorSeverity,ErrorState,ErrorProcedure,ErrorLine,ErrorMessage,Date)                    
   SELECT ERROR_NUMBER(),ERROR_SEVERITY(),ERROR_STATE(),ERROR_PROCEDURE()+'# usp_ExecEnquiryTriggerTasks',ERROR_LINE(),ERROR_MESSAGE(),GETDATE()              
  END CATCH            
            
 DROP TABLE IF EXISTS #temp;        
 end
 End
END 


GO

/* ============================================================
   Procedure: [dbo].[usp_ExecEnquiryTriggerTasks_multi]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

      
        
CREATE   PROCEDURE [dbo].[usp_ExecEnquiryTriggerTasks_multi]        
(          
 @CsvEnquiryID  nvarchar(max)          
)          
AS              
BEGIN              
 print 'starting procedure usp_ExecEnquiryTriggerTasks_multi'          
 SET NOCOUNT ON;          
           
 if(ISNULL(@CsvEnquiryID, '') = '')          
 begin          
  return;          
 end          
         
 drop table if exists #csvEnquiryId          
 create table #csvEnquiryId(          
  EnquiryId bigint,isdup_m bit,isdup_e bit,m1 nvarchar(50),m2 nvarchar(50),m3 nvarchar(50),e1 nvarchar(200),e2 nvarchar(200),e3 nvarchar(200)          
 )          
 insert into #csvEnquiryId (EnquiryId,isdup_m,isdup_e)          
  select [value],0,0 from dbo.fn_split(@CsvEnquiryID, ',')          
         
 begin try        
 if(exists(select 1 from #csvEnquiryId))          
 begin          
  DECLARE @tbl AS LeadActivitywithid_Tbltype              
              
  INSERT INTO @tbl ( LeadID, UserID, ParentID, EventDescription, EventName, reftable, Refid )              
   SELECT i.enquiryID, i.CreatedBy, i.ParentID,           
   'Enquiry with ' + isnull('name ' + isnull(nullif(i.personname, ''),''), 'no name') + ' is added to Enquiry by ' + u.user_login, 'Enquiry added', 'Userenquiry', i.EnquiryID              
   FROM UserEnquiry i (nolock)             
   inner join #csvEnquiryId t(nolock) on i.EnquiryID =  t.EnquiryId          
   JOIN user_detail(NOLOCK) u ON u.user_id = i.CreatedBy              
   WHERE NOT EXISTS ( SELECT 1 FROM tbl_EnquiryEventHistory(NOLOCK)              
     WHERE enquiryid = i.EnquiryID AND eventid = 119 )        
        
  DECLARE @parentid bigint              
              
  select top 1 @parentid=parentid from @tbl        
              
          
  EXEC UspSaveentityActivity_withMultipleValue_withid_bulk @tbl         
        
      
  delete from @tbl      
      
INSERT INTO @tbl ( LeadID, UserID, ParentID, EventDescription, EventName, reftable, Refid )              
SELECT distinct ulme_id          
  ,CreatedBy          
  ,i.ParentID          
  ,'Lead with ' + isnull('name ' + isnull(nullif(personname, ''),''), 'no name') + ' expressed a new interest through enquiryno ' + cast(i.enquiryid as      
  nvarchar)      
  ,'Lead generated new enquiry'          
  ,'Userenquiry'          
  ,t.EnquiryID          
 FROM UserEnquiry i (nolock)             
   inner join #csvEnquiryId t(nolock) on i.EnquiryID =  t.EnquiryId          
   JOIN user_detail(NOLOCK) d ON d.user_id = i.CreatedBy          
 JOIN userleads_mobile_email(NOLOCK) u ON i.parentid=u.parentid and      
 ((u.mobile <>'0' and u.mobile in (isnull(i.MobileNo,'1'),isnull(i.MobileNo2,'1'),isnull(i.MobileNo1,'1')))        
 or     
 (u.email<>'0' and u.email in (isnull(i.emailid,'2'),isnull(i.emailid1,'2'),isnull(emailid2,'2')) ))      
  and datediff(mi,u.leadcreateddate ,i.CreatedDate)>5--u.leadcreateddate<dateadd(mi,-5,getdate())  
 and    
  not exists    
  (select 1 from tbl_leadeventhistory(nolock) where eventid=28 and refids=t.enquiryid and leadid=ulme_id)    
     
 EXEC UspSaveentityActivity_withMultipleValue_withid_bulk @tbl         
      
      
              
  update c set m1=mobileno,m2=mobileno2,m3=mobileno1 ,e1=emailid,e2=emailid1,e3=emailid2        
  from #csvEnquiryId c join userenquiry u on c.enquiryid=u.EnquiryID        
         
        
  update c set isdup_m=1 from #csvEnquiryId c join         
  (select mobile,enquiryid from Userenquiry_Mobile_Email(nolock) where parentid=@parentid and isnull(mobile,'0')<>'0' ) u        
 on mobile in (m1,m2,m3) and c.EnquiryId>u.enquiryid        
        
 update c set isdup_e=1 from #csvEnquiryId c join         
  (select email,enquiryid from Userenquiry_Mobile_Email(nolock) where parentid=@parentid and isnull(email,'0')<>'0' ) u        
 on email in (e1,e2,e3) and c.EnquiryId>u.enquiryid        
        
 declare @minid bigint,@maxid bigint,@u_cnt bigint,@rowupdated int        
 select @minid=min(enquiryid),@maxid=max(enquiryid) from #csvEnquiryId        
 select @u_cnt=count(1) from #csvenquiryid        
         
 while @minid<@maxid and @u_cnt>0        
 begin        
 update u set u.IsduplicateMobile=c.isdup_m,u.IsduplicateEmail=c.isdup_e from userenquiry u join         
 (select top 500 * from #csvEnquiryId where enquiryid >@minid order by enquiryid) c on u.enquiryid=c.enquiryid        
select @rowupdated=@@Rowcount        
set @minid=@minid+@rowupdated        
set @u_cnt=@u_cnt-500        
 end         
        
 end          
 END TRY              
              
  BEGIN CATCH              
   exec usp_InsertErrorInfo        
  END CATCH              
        
END 


GO

