CREATE   PROCEDURE [dbo].[usp_ExecEnquiryTriggerTasks_multi_bulk]        
(          
 @CsvEnquiryID  nvarchar(max)          
)          
AS              
BEGIN              
 print 'starting procedure usp_ExecEnquiryTriggerTasks_multi_bulk'          
 SET NOCOUNT ON;          
           
 if(ISNULL(@CsvEnquiryID, '') = '')          
 begin          
  return;          
 end          
         
 drop table if exists #csvEnquiryId          
 create table #csvEnquiryId(          
 csv_eid bigint identity(1,1), EnquiryId bigint,isdup_m bit,isdup_e bit,m1 nvarchar(50),m2 nvarchar(50),m3 nvarchar(50),e1 nvarchar(200),e2 nvarchar(200),e3 nvarchar(200)          
 )          
 insert into #csvEnquiryId (EnquiryId,isdup_m,isdup_e)          
  select [value],0,0 from dbo.fn_split(@CsvEnquiryID, ',')          
  declare @csv_count int,@e_id bigint=0, @parentid bigint  ,@csv_eid bigint            
              
  select top 1 @csv_eid =enquiryid from #csvEnquiryId
  select top 1 @parentid=parentid from userenquiry(nolock) where enquiryid=@csv_eid          
  
  begin try        
 if(exists(select 1 from #csvEnquiryId))          
 begin 
 select @csv_count=count(1) from #csvEnquiryId

  DECLARE @tbl AS LeadActivitywithid_Tbltype              
  
  while @csv_count>0
  begin
  begin try
  print concat('Enquiry activity pending: ',@csv_count)
  INSERT INTO @tbl ( LeadID, UserID, ParentID, EventDescription, EventName, reftable, Refid )              
   SELECT top 500 i.enquiryID, i.CreatedBy, i.ParentID,           
   'Enquiry with ' + isnull('name ' + isnull(nullif(i.personname, ''),''), 'no name') + ' is added to Enquiry by ' + u.user_login, 'Enquiry added', 'Userenquiry', i.EnquiryID              
   FROM UserEnquiry i (nolock)             
   inner join #csvEnquiryId t(nolock) on i.EnquiryID =  t.EnquiryId          
   JOIN user_detail(NOLOCK) u ON u.user_id = i.CreatedBy              
   WHERE NOT EXISTS ( SELECT 1 FROM tbl_EnquiryEventHistory(NOLOCK)              
     WHERE enquiryid = i.EnquiryID AND eventid = 119 )  
	 and t.enquiryid>@e_id order by t.EnquiryId

	 
        

              
          
  EXEC UspSaveentityActivity_withMultipleValue_withid_bulk @tbl         
  END TRY              
              
  BEGIN CATCH              
   exec usp_InsertErrorInfo        
  END CATCH              
    
	 select @e_id=max(leadid) from @tbl
	 select @csv_count=@csv_count-500
	 delete from @tbl
end

delete from @tbl    

declare @efl Enquiryforla 

insert into @efl(EnquiryID,parentID)
select enquiryid,@parentid from #csvEnquiryId

exec usp_insertintoenquiryleadactivity_bulk @efl

