select @csv_count=(select count(distinct i.enquiryid) from UserEnquiry i (nolock) inner join #csvEnquiryId t(nolock) on i.EnquiryID =  t.EnquiryId 
JOIN #userleads_mobile_email(NOLOCK) u ON i.parentid=u.parentid and      
