/* ============================================================
   Procedure: [dbo].[usp_ExecEnquiryTriggerTasks_multi_bulk_dba]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

    
CREATE  PROCEDURE [dbo].[usp_ExecEnquiryTriggerTasks_multi_bulk_dba]  
(  
 @CsvEnquiryID NVARCHAR(MAX)  
)  
AS  
BEGIN  
    PRINT 'Starting procedure usp_ExecEnquiryTriggerTasks_multi_bulk';  
    SET NOCOUNT ON;  
  
    -- Return early if @CsvEnquiryID is empty              
    IF(ISNULL(@CsvEnquiryID, '') = '')  
    BEGIN  
        RETURN;  
    END;  
  
    -- Drop the temp table if it exists    
    DROP TABLE IF EXISTS #csvEnquiryId;  
    DROP TABLE IF EXISTS #TempMobile;  
    DROP TABLE IF EXISTS #TempEmail;  
    DROP TABLE IF EXISTS #TempBatch;  
  
    -- Create temp table for storing Enquiry IDs    
    CREATE TABLE #csvEnquiryId  
    (csv_eid   BIGINT IDENTITY(1, 1),   
        EnquiryId BIGINT,   
        isdup_m   BIT,   
        isdup_e   BIT,   
        m1        NVARCHAR(50),   
        m2        NVARCHAR(50),   
        m3        NVARCHAR(50),   
        e1        NVARCHAR(200),   
        e2        NVARCHAR(200),   
        e3        NVARCHAR(200)  
    );  
  
    -- Insert values from the function fn_split into the temp table    
    INSERT INTO #csvEnquiryId  
    (EnquiryId,   
        isdup_m,   
        isdup_e  
    )  
            SELECT [value],   
                    0,   
                    0  
            FROM dbo.fn_split(@CsvEnquiryID, ',');  
  
    -- Declare necessary variables    
    DECLARE @csv_count INT, @e_id BIGINT= 0, @parentid BIGINT, @csv_eid BIGINT;  
  
    -- Initialize @csv_eid and @parentid    
    SELECT TOP 1 @csv_eid = enquiryid  
    FROM #csvEnquiryId;  
    SELECT TOP 1 @parentid = parentid  
    FROM userenquiry(NOLOCK)  
    WHERE enquiryid = @csv_eid;  
    BEGIN TRY            
        -- Check if there are rows in #csvEnquiryId    
        IF(EXISTS  
        (  
            SELECT 1  
            FROM #csvEnquiryId  
        ))  
            BEGIN    
                -- Get the count of rows    
                SELECT @csv_count = COUNT(1)  
                FROM #csvEnquiryId;  
  
                -- Declare table type variable    
                DECLARE @tbl AS LEADACTIVITYWITHID_TBLTYPE;  
  
                -- Loop through batches of 500 rows    
                WHILE @csv_count > 0  
                BEGIN  
     BEGIN TRY    
      -- Print activity log    
      PRINT CONCAT('Enquiry activity pending: ', @csv_count);  
  
      -- Insert into @tbl for bulk processing    
      INSERT INTO @tbl  
      (LeadID,   
       UserID,   
       ParentID,   
       EventDescription,   
       EventName,   
       reftable,   
       Refid  
      )  
        SELECT TOP 500 i.EnquiryID,   
            i.CreatedBy,   
            i.ParentID,   
            'Enquiry with ' + ISNULL('name ' + ISNULL(NULLIF(i.personname, ''), ''), 'no name') + ' is added to Enquiry by ' + u.user_login,   
            'Enquiry added',   
            'Userenquiry',   
            i.EnquiryID  
        FROM UserEnquiry i(NOLOCK)  
         INNER JOIN #csvEnquiryId t(NOLOCK) ON i.EnquiryID = t.EnquiryId  
         JOIN user_detail(NOLOCK) u ON u.user_id = i.CreatedBy  
        WHERE NOT EXISTS  
        (  
         SELECT 1  
         FROM tbl_EnquiryEventHistory(NOLOCK)  
         WHERE enquiryid = i.EnquiryID  
           AND eventid = 119  
        )  
          AND t.enquiryid > @e_id  
        ORDER BY t.EnquiryId;  
  
      -- Execute the procedure to save activity    
      EXEC UspSaveentityActivity_withMultipleValue_withid_bulk   
        @tbl;  
     END TRY  
     BEGIN CATCH                  
      -- Insert error info if an exception occurs    
      EXEC usp_InsertErrorInfo;  
     END CATCH;  
  
                        -- Update counters    
                        SELECT @e_id = MAX(LeadID)  
                        FROM @tbl;  
                        SELECT @csv_count = @csv_count - 500;  
                        DELETE FROM @tbl;  
    END;  
  
                -- Reset @e_id and recalculate @csv_count    
delete from @tbl    

declare @efl Enquiryforla 

insert into @efl(EnquiryID,parentID)
select enquiryid,@parentid from #csvEnquiryId

exec usp_insertintoenquiryleadactivity_bulk @efl				



                SELECT @csv_count = COUNT(1)  
                FROM #csvEnquiryId;  
                select @e_id=(select min(enquiryid) from #csvEnquiryId)-1  
  
                -- Create temp tables for batch processing    
                CREATE TABLE #TempBatch  
                (csv_eid   BIGINT,   
                    EnquiryId BIGINT,   
                    isdup_m   BIT,   
                    isdup_e   BIT,   
                    m1        NVARCHAR(50),   
                    m2        NVARCHAR(50),   
                    m3        NVARCHAR(50),   
                    e1        NVARCHAR(200),   
                    e2        NVARCHAR(200),   
                    e3        NVARCHAR(200)  
                );  
                CREATE TABLE #TempMobile  
                (mobile    NVARCHAR(50),   
                    enquiryid BIGINT  
                );  
                CREATE TABLE #TempEmail  
                (email     NVARCHAR(200),   
                    enquiryid BIGINT  
                );  
  
    -- Create indexes for #TempBatch     CREATE INDEX IX_TempBatch_EnquiryId ON #TempBatch (EnquiryId);     CREATE INDEX IX_TempBatch_Mobiles ON #TempBatch (m1, m2, m3);      -- Create indexes for #TempMobile     CREATE INDEX IX_TempMobile_Mobile ON #TempMobile (mobile);     CREATE INDEX IX_TempMobile_EnquiryId ON #TempMobile (enquiryid);      -- Create indexes for #TempEmail     CREATE INDEX IX_TempEmail_Email ON #TempEmail (email);     CREATE INDEX IX_TempEmail_EnquiryId ON #TempEmail (enquiryid);   
                    -- Insert relevant mobile numbers into #TempMobile    
                    INSERT INTO #TempMobile  
                            SELECT mobile, enquiryid  
                            FROM Userenquiry_Mobile_Email(NOLOCK)  
                            WHERE parentid = @parentid AND ISNULL(mobile, '0') <> '0';  
  
                    -- Insert relevant emails into #TempEmail    
                    INSERT INTO #TempEmail  
                            SELECT email, enquiryid  
                            FROM Userenquiry_Mobile_Email(NOLOCK)  
                            WHERE parentid = @parentid AND ISNULL(email, '0') <> '0';  
  
  
                -- Batch update mobile and email fields    
                WHILE @csv_count > 0  
                BEGIN    
                    -- Insert batch of data into #TempBatch    
                    INSERT INTO #TempBatch  
                            SELECT TOP 500 *  
                            FROM #csvEnquiryId  
                            WHERE enquiryid > @e_id  
                            ORDER BY enquiryid;  
  
                    -- Update mobiles and emails in #TempBatch    
                    UPDATE c  
                        SET   
                            c.m1 = u.mobileno,   
                            c.m2 = u.mobileno2,   
                            c.m3 = u.mobileno1,   
                            c.e1 = u.emailid,   
                            c.e2 = u.emailid1,   
                            c.e3 = u.emailid2  
                    FROM #TempBatch c  
                            JOIN userenquiry u ON c.enquiryid = u.EnquiryID;  
  
                    -- Update isdup_m for duplicate mobiles in #TempBatch    
                    UPDATE c  
                        SET   
                            isdup_m = 1  
                    FROM #TempBatch c  
                            JOIN #TempMobile u ON u.mobile IN(c.m1, c.m2, c.m3)  
                    AND c.EnquiryId > u.enquiryid;  
  
                    -- Update isdup_e for duplicate emails in #TempBatch    
                    UPDATE c  
                        SET   
                            isdup_e = 1  
                    FROM #TempBatch c  
                            JOIN #TempEmail u ON u.email IN(c.e1, c.e2, c.e3)  
                    AND c.EnquiryId > u.enquiryid;  
  
                    -- Update batch counters    
                    SET @e_id = @e_id + 500;  
                    SET @csv_count = @csv_count - 500;  
  
                    -- Truncate temp tables for the next batch    
                    TRUNCATE TABLE #TempBatch;  
    END;  
  
                -- Declare variables for final update    
                DECLARE @minid BIGINT, @maxid BIGINT, @u_cnt BIGINT, @rowupdated INT;  
  
                -- Initialize min and max enquiry ids    
                SELECT @minid = MIN(enquiryid),   
                        @maxid = MAX(enquiryid)  
                FROM #csvEnquiryId;  
                SELECT @u_cnt = COUNT(1)  
                FROM #csvEnquiryId;  
  
                -- Final update to UserEnquiry table in batches    
                WHILE @minid < @maxid AND @u_cnt > 0  
                    BEGIN            
                        -- Insert batch of data into #TempBatch    
                        INSERT INTO #TempBatch  
                                SELECT TOP 500 *  
                                FROM #csvEnquiryId  
                                WHERE enquiryid > @minid  
                                ORDER BY enquiryid;  
  
                        -- Update UserEnquiry table    
                        UPDATE u  
                            SET   
                                u.IsduplicateMobile = c.isdup_m,   
                                u.IsduplicateEmail = c.isdup_e  
                        FROM userenquiry u  
                                JOIN #TempBatch c ON u.enquiryid = c.enquiryid;  
  
                        -- Update row count and minid    
                        SELECT @rowupdated = @@ROWCOUNT;  
                        SET @minid = @minid + @rowupdated;  
                        SET @u_cnt = @u_cnt - 500;  
  
                        -- Truncate temp table for the next batch    
                        TRUNCATE TABLE #TempBatch;  
        END;  
  
                -- Clean up temp tables    
                DROP TABLE IF EXISTS #TempBatch, #TempMobile, #TempEmail;  
        END;  
    END TRY  
    BEGIN CATCH                  
        -- Insert error info if an exception occurs    
        EXEC usp_InsertErrorInfo;  
    END CATCH;  
END;  


GO

/* ============================================================
   Procedure: [dbo].[Usp_execleadinteractiontriggertasks]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


CREATE   PROC [dbo].[Usp_execleadinteractiontriggertasks] (@CsvLeadInteractionId
NVARCHAR(max))
AS
  BEGIN
      IF Object_id('tempdb..#tbl_lstLeadInteractionID') IS NOT NULL
        BEGIN
            DROP TABLE #tbl_lstleadinteractionid
        END

      SELECT position AS RowId, value    AS Id
      INTO   #tbl_lstleadinteractionid
      FROM   dbo.Fn_split(@CsvLeadInteractionId, ',')

      IF (SELECT Count(DISTINCT parentid) FROM   leadinteractionhistory(nolock) l JOIN #tbl_lstleadinteractionid t ON t.id = l.id) = 1
         AND (SELECT Count(1) FROM   #tbl_lstleadinteractionid) > 1
      BEGIN
            BEGIN try
                DECLARE @multilih AS MULTI_LIHID

                INSERT INTO @multilih(lihid)
                SELECT id
                FROM   #tbl_lstleadinteractionid

                EXEC Usp_execleadinteractiontriggertasks_multi_lihid @multilih
            END try
            BEGIN catch
                EXEC Usp_inserterrorinfo
            END catch
        END
      ELSE
      BEGIN
            DECLARE @c INT=(SELECT Count(1) FROM   #tbl_lstleadinteractionid)

            DECLARE @parentid              BIGINT,
                    @userid                BIGINT,
                    @leadid                BIGINT,
                    @lehid                 BIGINT=0,
                    @leadno                BIGINT,
                    @eventdesc             NVARCHAR(1000),
                    @assignedto            BIGINT,
                    @userlogin             NVARCHAR(100),
                    @assignedlogin         NVARCHAR(100),
                    @enquirysource         INT,
                    @leadname              NVARCHAR(100),
                    @LastFollowupCreatedOn DATETIME,
                    @LastRemarks           NVARCHAR(max) = '',
                    @f_status              NVARCHAR(50),
                    @status_id             BIGINT

            WHILE @c > 0
            BEGIN
                  PRINT Concat('Leads interaction for trigger: ', @c)

                  SELECT @lehid = Min(id)
                  FROM   #tbl_lstleadinteractionid
                  WHERE  id > @lehid

                  SELECT @parentid = parentid,
                         @userid = createdby,
                         @leadno = leadno,
                         @assignedto = assignedto,
                         @LastFollowupCreatedOn = createdon,
                         @LastRemarks = remarks,
                         @status_id = followupstatus
                  FROM   leadinteractionhistory(nolock)
                  WHERE  id = @lehid

                  SELECT @f_status = followupstatus
                  FROM   followup_status(nolock)
                  WHERE  id = @status_id

                  SELECT TOP 1 @leadid = id,@leadname = personname,@enquirysource = enquirysource
                  FROM   userleads(nolock)
                  WHERE  leadno = @leadno AND parentid = @parentid
                  ORDER  BY id DESC

                  --if      
                  --exists(select 1 from LeadInteractionHistory(nolock) where leadno=@leadno and parentid=@parentid and abs(datediff(mi,createdon,getdate()))>2          
                  --and @enquirysource not in (12,13,14,15,22,23,24)) or @enquirysource in (12,13,14,15,22,23,24)          
                  --begin          
                  UPDATE userleads
                  SET    lastfollowupcreatedby = @userid,lastfollowupcreatedon = @LastFollowupCreatedOn,remarks = @LastRemarks
                  WHERE  id = @leadid AND followupstatus <> 6

                  --end          
                  IF NOT EXISTS (SELECT 1 FROM   tbl_leadeventhistory(nolock) WHERE  eventid = 37 AND refids = @lehid)
                     /*Added below condition so there is no notification for default follow up*/
                     AND 1 = CASE
                               --when exists       
                               --(select 1 from tbl_lam_UserAssignmentHistory(nolock) where leadid=@leadid and assignedUserId>0) then 1       
                               WHEN EXISTS (SELECT 1 FROM   tbl_leadassignmentmaster(nolock) WHERE  parentid = @parentid AND is_active = 1)
                                    AND NOT EXISTS (SELECT 1 FROM tbl_lam_userassignmenthistory(nolock) WHERE  leadid = @leadid AND assigneduserid > 0)
                                    AND (SELECT Count(1) FROM   leadinteractionhistory(nolock) WHERE  parentid = @parentid AND leadno = @leadno) = 1 THEN 0
                               ELSE 1
                             END
                    BEGIN
                        IF( Isnull(@assignedto, 0) > 0 )
                          BEGIN
                              SELECT @userlogin = user_login
                              FROM   user_detail(nolock)
                              WHERE  user_id = @userid

                              SELECT @assignedlogin = user_login
                              FROM   user_detail(nolock)
                              WHERE  user_id = @assignedto

                              SELECT @eventdesc = 'Lead with ' + CASE WHEN
                                                  Isnull(
                                                  NULLIF
                                                  (
                                                  @leadname
                                                  ,
                                                  ''),
                                                  '')<>'' THEN
                                                         'name '+
                                                         @leadname ELSE
                                                  'leadno '+
                                                  Cast
                                                  (
                                                  @leadno
                                                  AS
                                                  NVARCHAR
                                                  )
                                                  END +
                                                         ' is assigned to '
                                                  + @Assignedlogin + ' by ' +
                                                  @userlogin

                              EXEC Uspsaveleadactivity_withid
                                @leadid,
                                @userid,
                                @parentid,
                                @eventdesc,
                                'Lead Assigned to',
                                'Leadinteractionhistory',
                                @lehid

                                SELECT @eventdesc = @userlogin +
                                                  ' added a followup to leadno '
                                                  ++
                                     Cast(@leadno AS NVARCHAR)
                                     +
                                     ' with status ' +
                                     @f_status
                                     +
                                     '. Lead was assigned to ' + @Assignedlogin

                              EXEC Uspsaveleadactivity_withid
                                @leadid,
                                @userid,
                                @parentid,
                                @eventdesc,
                                'New Interaction added',
                                'Leadinteractionhistory',
                                @lehid

                          END
                        ELSE
                          BEGIN
                              SELECT @userlogin = user_login
                              FROM   user_detail(nolock)
                              WHERE  user_id = @userid

                              SELECT @eventdesc = @userlogin +
                                                  ' added a followup to leadno '
                                                  ++
                                     Cast(@leadno AS NVARCHAR)
                                     +
                                     ' with status ' +
                                     @f_status
                                     +
                                     '. Lead was assigned to no one'

                              EXEC Uspsaveleadactivity_withid
                                @leadid,
                                @userid,
                                @parentid,
                                @eventdesc,
                                'New Interaction added',
                                'Leadinteractionhistory',
                                @lehid
                          END
                    END

                  SET @c=@c - 1
              END
        END

      IF Object_id('tempdb..#tbl_lstLeadInteractionID') IS NOT NULL
        BEGIN
            DROP TABLE #tbl_lstleadinteractionid
        END
  END 



GO

/* ============================================================
   Procedure: [dbo].[usp_ExecLeadInteractionTriggerTasks_multi]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE  PROC [dbo].[usp_ExecLeadInteractionTriggerTasks_multi]  
(  
 @multi_lih as multiactivity_lih readonly  
)  
AS  
Begin  

insert into leadinteractiontriggers(lih_id,parentid)  
select l.id,m.parentid
from @multi_lih m join Leadinteractionhistory_latest(nolock) l  
on l.leadno=m.leadno and l.parentid=m.parentid  
return;  

 if object_id('tempdb..#tbl_lstLeadInteractionID') is not null begin drop table #tbl_lstLeadInteractionID end  
  
   
 create table #tbl_lstLeadInteractionID(lih_id bigint, lih_assignedto bigint, lih_leadno bigint,lih_parentid bigint,m_id int,lih_createdon datetime,  
 lih_LastRemarks nvarchar(2000),lih_createdby bigint)  
 insert into #tbl_lstLeadInteractionID(lih_id,lih_assignedto,lih_leadno,lih_parentid,m_id,lih_createdon,lih_createdby,lih_LastRemarks)  
 select l.id,assignedto,m.leadno,m.parentid,m.id,l.createdon,l.createdby,l.Remarks from @multi_lih m join Leadinteractionhistory_latest(nolock) l  
 on l.leadno=m.leadno and l.parentid=m.parentid  
 declare @c int=(select count(1) from #tbl_lstLeadInteractionID)   
 declare @parentid bigint,@lehid bigint=0  
 declare @lat as LeadActivitywithid_Tbltype   
 select top 1 @parentid=lih_parentid from #tbl_lstLeadInteractionID      
   
 while @c>0      
 begin      
 insert into @lat(leadid,UserID,parentid,EventName,EventDescription,RefTable,refid)  
 select u.id,lih_createdby,u.parentid,'Lead Assigned to','Lead with '+ case when isnull(nullif(personname,''),'')<>'' then 'name '  
 +personname else 'leadno '+cast(u.leadno as nvarchar) end +' is assigned to '+a.user_login+ ' by '+ c.user_login,'Leadnteractionhistory',lih_id    
 from #tbl_lstLeadInteractionID t   
 join   
 (select * from userleads(nolock) where parentid=@parentid) u on t.lih_parentid=u.parentid and t.lih_leadno=u.leadno  
 join  
 (select * from user_detail(nolock) where parentid=@parentid) c on c.user_id=t.lih_createdby  
 join  
 (select * from user_detail(nolock) where parentid=@parentid) a on a.user_id=t.lih_AssignedTo  
 where t.m_id between @lehid and @lehid+500 and   
 not exists (select 1 from tbl_LeadEventHistory(nolock) where eventid=37 and refids=lih_id)   
 and  
 1= case when exists (select 1 from tbl_LeadAssignmentMaster(nolock) where parentid=@parentid and is_active=1)  
 and not exists (select 1 from tbl_lam_UserAssignmentHistory(nolock) where leadid=u.id and assignedUserId>0)  
 and  (select count(1) from Leadinteractionhistory(nolock) where parentid=@parentid and leadno=u.leadno)=1 then 0   
 else 1 end  
  
 update u set LastFollowupCreatedBy=lih_createdby , LastFollowupCreatedOn = lih_CreatedOn,Remarks = lih_LastRemarks  
 from userleads(nolock) u join  
 (select top 500 * from #tbl_lstLeadInteractionID (nolock) where m_id between @lehid and @lehid+500) t  
 on u.leadno=t.lih_leadno and u.parentid=t.lih_parentid  
   
 exec UspSaveentityActivity_withMultipleValue_withid_bulk @lat  
  
 set @c=@c-500  
 set @lehid=@lehid+500  
    print concat('Leads interaction for trigger: ',@c)         
   delete from @lat  
   
  end      
      
 if object_id('tempdb..#tbl_lstLeadInteractionID') is not null begin drop table #tbl_lstLeadInteractionID end  
  
End  



GO

/* ============================================================
   Procedure: [dbo].[usp_ExecLeadInteractionTriggerTasks_multi_lihid]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC [dbo].[usp_ExecLeadInteractionTriggerTasks_multi_lihid]    
(    
 @multi_lih as [Multi_lihid] readonly    
)    
AS    
Begin    
begin try    
declare @parentid bigint,@lehid bigint=0 

select top 1 @lehid=lihid from @multi_lih  
select @parentid=parentid from LeadInteractionHistory(nolock) where id=@lehid  

insert into leadinteractiontriggers(lih_id,parentid)
select lihid,@parentid from @multi_lih
return;

select @lehid =0  
  
 if object_id('tempdb..#tbl_lstLeadInteractionID_multi') is not null     
 begin drop table #tbl_lstLeadInteractionID_multi end    
    
  drop table if exists #leadinteractionhistory  
  drop table if exists #userleads   
    
  select ID,ParentID,Id_Lead,leadno,createdon,createdby,Remarks,assignedto,FollowUpStatus into #leadinteractionhistory from LeadInteractionHistory(nolock) where parentid=@parentid   
  delete d from #leadinteractionhistory d left join  @multi_lih m on d.id=m.lihid where m.lihid is null  
  select u.* into #userleads from userleads u(nolock) join #leadinteractionhistory d on u.id=d.Id_Lead-- where parentid=@parentid   
  
 create table #tbl_lstLeadInteractionID_multi(lih_id bigint, lih_assignedto bigint, lih_leadno bigint,lih_parentid bigint,m_id int,lih_createdon datetime,    
 lih_LastRemarks nvarchar(2000),lih_createdby bigint,lih_fstatus nvarchar(100))    
 insert into #tbl_lstLeadInteractionID_multi(lih_id,lih_assignedto,lih_leadno,lih_parentid,m_id,lih_createdon,lih_createdby,lih_LastRemarks,lih_fstatus)    
 select l.id,assignedto,l.leadno,l.parentid,m.id,l.createdon,l.createdby,l.Remarks,f.FollowupStatus from @multi_lih m     
 join #leadinteractionhistory(nolock) l    
 on l.id=m.lihid    
 left join FollowUp_Status (nolock) f on f.id=l.FollowUpStatus    
    
 declare @c int=(select count(1) from #tbl_lstLeadInteractionID_multi)     
   
 declare @lat as LeadActivitywithid_Tbltype     
     
 while @c>0        
 begin        
 insert into @lat(leadid,UserID,parentid,EventName,EventDescription,RefTable,refid)    
 select u.id,lih_createdby,u.parentid,'Lead Assigned to','Lead with '+ case when isnull(nullif(personname,''),'')<>'' then 'name '    
 +personname else 'leadno '+cast(u.leadno as nvarchar) end +' is assigned to '+a.user_login+ ' by '+ c.user_login,'Leadinteractionhistory',lih_id      
 from #tbl_lstLeadInteractionID_multi t     
 join     
 (select * from #userleads(nolock) where parentid=@parentid) u on t.lih_parentid=u.parentid and t.lih_leadno=u.leadno    
 join    
 (select * from user_detail(nolock) where parentid=@parentid) c on c.user_id=t.lih_createdby    
 join    
 (select * from user_detail(nolock) where parentid=@parentid) a on a.user_id=t.lih_AssignedTo    
 where t.m_id between @lehid and @lehid+500 and     
 not exists (select 1 from tbl_LeadEventHistory(nolock) where eventid=37 and refids=lih_id)     
 and    
 1= case when exists (select 1 from tbl_LeadAssignmentMaster(nolock) where parentid=@parentid and is_active=1)    
 and not exists (select 1 from tbl_lam_UserAssignmentHistory(nolock) where leadid=u.id and assignedUserId>0)    
 and  (select count(1) from #Leadinteractionhistory(nolock) where parentid=@parentid and leadno=u.leadno)=1 then 0     
 else 1 end    
 union    
 select u.id,lih_createdby,u.parentid,'New Interaction added',c.user_login+ ' added a followup to leadno '+cast(u.leadno as nvarchar)+' with status '+lih_fstatus+    
 '. Lead was assigned to ' +isnull(a.user_login,'no one'),'Leadinteractionhistory',lih_id      
 from #tbl_lstLeadInteractionID_multi t     
 join     
 (select * from #userleads(nolock) where parentid=@parentid) u on t.lih_parentid=u.parentid and t.lih_leadno=u.leadno    
 join    
 (select * from user_detail(nolock) where parentid=@parentid) c on c.user_id=t.lih_createdby    
 join    
 (select * from user_detail(nolock) where parentid=@parentid) a on a.user_id=t.lih_AssignedTo    
  where t.m_id between @lehid and @lehid+500 and     
 not exists (select 1 from tbl_LeadEventHistory(nolock) where eventid=37 and refids=lih_id)     
 and    
 1= case when exists (select 1 from tbl_LeadAssignmentMaster(nolock) where parentid=@parentid and is_active=1)    
 and not exists (select 1 from tbl_lam_UserAssignmentHistory(nolock) where leadid=u.id and assignedUserId>0)    
 and  (select count(1) from #Leadinteractionhistory(nolock) where parentid=@parentid and leadno=u.leadno)=1 then 0     
 else 1 end    
    
    
    
    
 update u set LastFollowupCreatedBy=lih_createdby , LastFollowupCreatedOn = lih_CreatedOn,Remarks = lih_LastRemarks    
 from userleads(nolock) u join    
 (select top 500 * from #tbl_lstLeadInteractionID_multi (nolock) where m_id between @lehid and @lehid+500) t    
 on u.leadno=t.lih_leadno and u.parentid=t.lih_parentid    
     
 exec UspSaveentityActivity_withMultipleValue_withid_bulk @lat    
    
 set @c=@c-500    
 set @lehid=@lehid+500    
    print concat('Leads interaction for trigger: ',@c)           
   delete from @lat    
     
  end        
        
 if object_id('tempdb..#tbl_lstLeadInteractionID_multi') is not null begin drop table #tbl_lstLeadInteractionID_multi end    
end try    
begin catch    
exec usp_inserterrorinfo    
end catch    
End 



GO

/* ============================================================
   Procedure: [dbo].[usp_ExecLeadInteractionTriggerTasks_multi_lihid_async]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC [dbo].[usp_ExecLeadInteractionTriggerTasks_multi_lihid_async]    
AS    
Begin    
declare @parentid bigint=0,@lehid bigint=0 ,@countp int ,@countr int
drop table if exists #lit
select lih_id,parentid into #lit from leadinteractiontriggers(nolock) where isprocessed=0 and createdon>DATEADD(mi,-120,getdate())
select @countp=COUNT(distinct parentid) from #lit
print concat('Total parentids to be processed: ',@countp)
while @countp>0
begin
begin try    
select @parentid=min(parentid) from #lit where parentid>@parentid
select @countr=COUNT(1) from #lit where parentid=@parentid
print concat('Total records to be processed for parentid ',@parentid,' : ',@countr)

declare @multi_lih as [Multi_lihid]
select @lehid =0  
  
  insert into @multi_lih(lihid)
  select lih_id from #lit where parentid=@parentid

drop table if exists #tbl_lstLeadInteractionID_multi
drop table if exists #leadinteractionhistory  
drop table if exists #userleads   
    
  select l.ID,ParentID,Id_Lead,leadno,createdon,createdby,Remarks,assignedto,FollowUpStatus into #leadinteractionhistory from LeadInteractionHistory(nolock) l join @multi_lih m on l.id=m.lihid
  --delete d from #leadinteractionhistory d left join  @multi_lih m on d.id=m.lihid where m.lihid is null  
  select u.* into #userleads from userleads u(nolock) join #leadinteractionhistory d on u.id=d.Id_Lead-- where parentid=@parentid   
  
 create table #tbl_lstLeadInteractionID_multi(lih_id bigint, lih_assignedto bigint, lih_leadno bigint,lih_parentid bigint,m_id int,lih_createdon datetime,    
 lih_LastRemarks nvarchar(2000),lih_createdby bigint,lih_fstatus nvarchar(100))    
 insert into #tbl_lstLeadInteractionID_multi(lih_id,lih_assignedto,lih_leadno,lih_parentid,m_id,lih_createdon,lih_createdby,lih_LastRemarks,lih_fstatus)    
 select l.id,assignedto,l.leadno,l.parentid,m.id,l.createdon,l.createdby,l.Remarks,f.FollowupStatus 
 from 
 @multi_lih m join 
 #leadinteractionhistory(nolock) l    
 on l.id=m.lihid    
 left join FollowUp_Status (nolock) f on f.id=l.FollowUpStatus    
    
 declare @c int=(select count(1) from #tbl_lstLeadInteractionID_multi)     
   
 declare @lat as LeadActivitywithid_Tbltype     
     
 while @c>0        
 begin  
 begin try
 print concat('Records to be processed for parentid ',@parentid,' : ',@c)

 insert into @lat(leadid,UserID,parentid,EventName,EventDescription,RefTable,refid)    
select 
    u.id,
    t.lih_createdby,
    u.parentid,
    v.EventName,
    v.EventDescription,
    'Leadinteractionhistory',
    t.lih_id
from #tbl_lstLeadInteractionID_multi t
inner join #userleads u
    on t.lih_parentid = u.parentid
    and t.lih_leadno = u.leadno
inner join dbo.user_detail c
    on c.user_id = t.lih_createdby
    and c.parentid = @parentid
left join dbo.user_detail a
    on a.user_id = t.lih_assignedto
    and a.parentid = @parentid
cross apply (
    values
      (
        'Lead Assigned to',
        'Lead with ' + 
          case when isnull(nullif(u.personname,''),'') <> '' 
               then 'name ' + u.personname 
               else 'leadno ' + cast(u.leadno as nvarchar(50)) 
          end
        + ' is assigned to ' + isnull(a.user_login,'no one') + ' by ' + c.user_login
      ),
      (
        'New Interaction added',
        c.user_login + ' added a followup to leadno ' + cast(u.leadno as nvarchar(50)) 
          + ' with status ' + isnull(t.lih_fstatus,'') 
          + '. Lead was assigned to ' + isnull(a.user_login,'no one')
      )
) v(EventName, EventDescription)
where t.m_id between @lehid and @lehid+500
  --and not exists (
  --    select 1 
  --    from dbo.tbl_LeadEventHistory (nolock) 
  --    where eventid = 37 
  --      and refids = t.lih_id
  --)
  and 1 = case 
        when exists (select 1 from dbo.tbl_LeadAssignmentMaster (nolock) where parentid = @parentid and is_active = 1)
         and not exists (select 1 from dbo.tbl_lam_UserAssignmentHistory (nolock) where leadid = u.id and assignedUserId > 0)
         and (select count(1) from #leadinteractionhistory (nolock) where id_lead = u.id) = 1
        then 0 
        else 1 
      end;    
     
 update u set LastFollowupCreatedBy=lih_createdby , LastFollowupCreatedOn = lih_CreatedOn,Remarks = lih_LastRemarks    
 from userleads(nolock) u join    
 (select top 500 * from #tbl_lstLeadInteractionID_multi (nolock) where m_id between @lehid and @lehid+500) t    
 on u.leadno=t.lih_leadno and u.parentid=t.lih_parentid    
     
 exec UspSaveentityActivity_withMultipleValue_withid_bulk @lat    

update l set isprocessed=1,processedon=GETDATE()  from leadinteractiontriggers l join #tbl_lstLeadInteractionID_multi t on l.lih_id=t.lih_id where m_id between @lehid and @lehid+500
    delete from @lat    
 end try    
begin catch
update l set isprocessed=1,processedon=GETDATE(),last_error=ERROR_MESSAGE()  from leadinteractiontriggers l join #tbl_lstLeadInteractionID_multi t on l.lih_id=t.lih_id where m_id between @lehid and @lehid+500
 exec usp_inserterrorinfo    
end catch    
set @c=@c-500    
 set @lehid=@lehid+500    
    print concat('Leads interaction for trigger: ',@c)           
  end        
        
 drop table if exists #tbl_lstLeadInteractionID_multi 
 delete From @multi_lih
 delete From #leadinteractionhistory
 delete From #lit
 delete from #userleads
end try    
begin catch    
exec usp_inserterrorinfo    
end catch
select @countp=@countp-1
end


End 


--create table leadinteractiontriggers(id bigint identity(1,1) primary key,lih_id bigint,createdon datetime default getdate(),isprocessed int default 0,processedon datetime,last_error nvarchar(max))

