/* ============================================================
   Procedure: [dbo].[usp_ExecLeadTriggerTasks]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC [dbo].[usp_ExecLeadTriggerTasks]      
(      
 @CsvLeadId nvarchar(max)      
)      
AS      
BEGIN        
    
	 if(@CsvLeadId is null or @CsvLeadId = '' )
	   begin
	       insert into idnullinproc
		    (IdName,ProcName,Metadata)
			select '@CsvLeadId','usp_ExecLeadTriggerTasks', @CsvLeadId
	   end
	

--declare @CsvLeadId nvarchar(max)      
if @CsvLeadId is not null
begin
declare @MobileNo varchar(100), @MobileNo1 varchar(100), @MobileNo2 varchar(100), @EmailID varchar(100), @EmailID1 varchar(100), @EmailID2 varchar(100), @ParentID bigint, @UserID bigint, @LeadId bigint, @RowJson varchar(max)='', @Row_Id bigint, 
@RecCnt bigint=0, @xml NVARCHAR(MAX), @body NVARCHAR(MAX), @leadno bigint, @enquirysource int;                  
 declare @username nvarchar(100),@eventde nvarchar(200),@defaultagent bigint, @AutoLeadFollowup bit = 0, @FollowupStatus int = 0, @NextStatusDateAddUnit nvarchar(100) = '', @FollowupRemarks nvarchar(max) = '', @AddDayUnit nvarchar(10) = '00', @AddHrsUnit 
  
nvarchar(10) = '00', @AddMinutesUnit nvarchar(10) = '00', @DtFLP datetime = null, @leadname nvarchar(200)        
        
 drop table if exists #tbl_lstLeadID      
  print '@CsvLeadId: ' + isnull(@CsvLeadId,'')      
 SELECT Position as RowId, value as LeadId into #tbl_lstLeadID from dbo.fn_split(@CsvLeadId,',')        
        
 ------------------              
              
 Select @LeadId=min(LeadId) from #tbl_lstLeadID;     
 declare @tli int=(select count(1) from #tbl_lstLeadID)    
 print concat('Leads for trigger: ',@tli)           
 While exists(Select * from #tbl_lstLeadID where LeadId=@LeadId)      
 Begin    
  print concat('Leads left for trigger: ',@tli)           
    
 If exists(Select * from userleads(nolock) i inner join tbl_MergeLeadsEnquiry(nolock) t on t.leadno=i.leadno inner join userenquiry(nolock) e on e.parentid=i.parentid and e.enquiryid=t.enquiryno inner join #tbl_lstLeadID d on d.LeadId=i.id where isnull(i.
  
enquirysource,0)=0 and d.LeadId=@LeadId)      
 Begin      
   update i set enquirysource=e.enquirysource               
   from userleads i inner join tbl_MergeLeadsEnquiry t         
   on t.leadno=i.leadno inner join userenquiry e         
   on e.parentid=i.parentid and e.enquiryid=t.enquiryno inner join #tbl_lstLeadID d         
   on d.LeadId=i.id              
   where isnull(i.enquirysource,0)=0 and d.LeadId=@LeadId      
 End      
        
  select @MobileNo=IIf(isnull(UL.MobileNo,'')='','m',MobileNo),                   
  @MobileNo1=iif(isnull(UL.MobileNo1,'')='','m1',MobileNo1),                   
  @MobileNo2=iif(isnull(UL.MobileNo2,'')='','m2',MobileNo2),                   
  @EmailID=iif(isnull(UL.EmailID,'')='','e',EmailID),                   
  @EmailID1=iif(isnull(UL.EmailID1,'')='','e1',EmailID1),                   
  @EmailID2=iif(isnull(UL.EmailID2,'')='','e2',EmailID2),                   
  @ParentID=UL.ParentID, @UserID=UL.CreatedBy, @LeadId=UL.ID, @enquirysource=UL.enquirysource, @leadname=UL.personname, @leadno=UL.leadno        
  from #tbl_lstLeadID L inner join UserLeads(nolock) UL        
  on L.LeadId = UL.ID        
  where L.LeadId=@LeadId        
              
  if @enquirysource in (12,13,14,15,23,24)              
  begin              
   update UserLeads set LastFollowupCreatedBy=CreatedBy,LastFollowupCreatedOn = CreatedOn where id=@LeadId       
  end              
               
  if not exists(select 1 from tbl_leadeventhistory(nolock) where leadid=@LeadId and eventid=17)        
  begin        
   select @username =user_login from user_detail(nolock) where user_id=@userid        
   select @eventde= 'Lead with ' + case when nullif(@leadname,'') is not null then 'name ' + @leadname        
   else 'leadno ' + cast(@leadno as nvarchar) end + ' was added by ' + cast(@username as nvarchar(100))        
        
   begin try        
    exec UspSaveLeadActivity_withid @LeadId,@UserID,@ParentID,@eventde,'Lead added','Userleads',@LeadId        
   end try        
   begin catch        
    exec usp_inserterrorinfo        
   end catch        
  end                  
         /*         
  If exists (Select * from UserLeads(nolock) Where ParentID=@ParentID and ID!=@LeadId and ( isnull(MobileNo,'*') in (@MobileNo,@MobileNo1,@MobileNo2)         
  or isnull(MobileNo1,'*') in (@MobileNo,@MobileNo1,@MobileNo2) or isnull(MobileNo2,'*') in (@MobileNo,@MobileNo1,@MobileNo2)        
  or isnull(EmailID,'*') in (@EmailID,@EmailID1,@EmailID2) or isnull(EmailID1,'*') in (@EmailID,@EmailID1,@EmailID2)         
  or isnull(EmailID2,'*') in (@EmailID,@EmailID1,@EmailID2) )        
  ) or (@MobileNo = 'm' and @MobileNo1 = 'm1' and @MobileNo2 = 'm2' and @EmailID = 'e' and @EmailID1 = 'e1' and @EmailID2 = 'e2')        
  Begin        
   set @RowJson=(SELECT (JSON_QUERY((select * from UserLeads(nolock) where Id=@LeadId for json path))) as col1)        
        
   insert into tbl_UserLeadDMLReject(Lead_Id, RowJson, ActionFlag) values(@LeadId, @RowJson,'I')        
        
   set @Row_Id = SCOPE_IDENTITY()        
        
   SET @xml =CAST(( SELECT @Row_Id AS 'td','',[User_Login] AS 'td','',[FName] + [LName] AS 'td','',[User_ID] AS 'td','',@RowJson AS 'td',''        
   from User_Detail(nolock) where User_id=@UserID FOR XML PATH('tr'), ELEMENTS ) AS NVARCHAR(MAX))        
   SET @body ='<html><H1>Lead Insertion Resulted in Duplication on '+cast (getdate() as nvarchar)+',Log table(tbl_UserLeadDMLReject)</H1><body><table border = 2><tr><th>Row_ID</th><th>User Login</th><th>Name</th><th>User_Id</th><th>RowJson</th></tr>'    
   
   
   SET @body = @body + @xml +'</table></body></html>'        
        
   EXEC msdb.dbo.sp_send_dbmail        
   @profile_name='Alerts',        
   @recipients='mayank.nigam@pelsoftlabs.in;animesh.shukla@pelsoftlabs.in',        
   @blind_copy_recipients='karuna@pelsoftlabs.in',        
   @subject='Lead Insertion Resulted in Duplication',        
   @body = @body,        
   @body_format ='HTML'        
  End        
         */         
                  
  --Start add followup settiing                  
                  
 IF(EXISTS(SELECT 1 FROM UserLeads(NOLOCK) WHERE [ID] = @LeadId AND NULLIF(isnull([FollowUpStatus],0), 0) IS NULL))    
 BEGIN    
  IF(EXISTS(SELECT 1 FROM crmCampaignSettings(NOLOCK) WHERE [UserID] = @ParentID))    
  BEGIN    
   SELECT TOP 1 @AutoLeadFollowup=ISNULL([AutoLeadFollowup], 0),     
    @FollowupStatus=CASE WHEN ISNULL([FollowupStatus], 0)=0 THEN 1 ELSE [FollowupStatus] END,    
    @NextStatusDateAddUnit=CASE WHEN ISNULL([NextStatusDateAddUnit],'')='' THEN '00:00:00'     
           ELSE [NextStatusDateAddUnit] END,     
    @FollowupRemarks=ISNULL([FollowupRemarks],'')    
   FROM crmCampaignSettings(NOLOCK)    
   WHERE [UserID] = @ParentID;    
    
   --if(@AutoLeadFollowup = 1)        
   --Begin        
   IF( @NextStatusDateAddUnit <> '' )    
   BEGIN    
    SELECT @AddDayUnit=value FROM dbo.fn_split(@NextStatusDateAddUnit, ':') WHERE [position] = 1;-- SUBSTRING(@NextStatusDateAddUnit,1,2)        
    SELECT @AddHrsUnit=value FROM dbo.fn_split(@NextStatusDateAddUnit, ':') WHERE [position] = 2;-- SUBSTRING(@NextStatusDateAddUnit,4,2)        
    SELECT @AddMinutesUnit=value FROM dbo.fn_split(@NextStatusDateAddUnit, ':') WHERE [position] = 3;-- SUBSTRING(@NextStatusDateAddUnit,7,2)        
    
    IF ISNUMERIC(@adddayunit) = 1 AND ISNUMERIC(@addhrsunit) = 1 AND ISNUMERIC(@addminutesunit) = 1    
    BEGIN    
     SET @DtFLP=DATEADD(MINUTE, CAST(@AddMinutesUnit AS INT), DATEADD(HOUR, CAST(@AddHrsUnit AS    
     INT), DATEADD(DAY, CAST(@AddDayUnit AS INT), GETDATE())));    
    END;    
    ELSE    
    BEGIN    
     SET @DtFLP=GETDATE();    
    END;    
   END;    
   --End        
  END;    
  ELSE    
  BEGIN    
   SELECT TOP 1 @AutoLeadFollowup=1, @followupstatus=[id], @FollowupRemarks='',     
     @NextStatusDateAddUnit=CASE WHEN [iscallback]=1 THEN 0 ELSE NULL END, @DtFLP=NULL    
   FROM Followup_Status(NOLOCK)    
   WHERE ([parentid] = @parentid OR [parentid] IS NULL) AND [isactive] = 1 AND [isdisabled] = 0    
     AND [IsCallback] = 1    
   ORDER BY [parentid] DESC,CASE WHEN [followupstatus] = 'Call-Back' THEN 0 ELSE 1 END;    
    
   --SELECT @AutoLeadFollowup = 1, @FollowupStatus = 1, @NextStatusDateAddUnit = 0, @FollowupRemarks = '';      
  END;    
    
  SELECT @defaultagent=[createdby] FROM UserLeads(NOLOCK) WHERE [id] = @LeadId;    
    
  UPDATE Userleads SET [FollowUpStatus]=isnull(@FollowupStatus,1), [FollowupDate]=isnull(@DtFLP,getdate()),[NextStatusDate]=isnull(@DtFLP,getdate()),     
    [remarks]=CASE WHEN @FollowupRemarks <> '' THEN @FollowupRemarks ELSE [remarks] END,    
    [AssignedTo]= COALESCE([Assignedto], @defaultagent, ((SELECT TOP 1 value FROM [fn_Split]((SELECT [agents] FROM [CRMCampaignSettings](NOLOCK) WHERE [userid]=@ParentID),'#') ORDER BY NEWID())), @parentid)    
  WHERE [id] = @Leadid;    
    
 END;                      
   --End add lead followup setting        
        
        
   -- Executing Procedure for expression field        
   --exec usp_ManageExpressionField @LeadId, @ParentID, 'lead'        
        
 insert into tbl_las_LeadRequest(leadid, parentid, is_processed)     
 select ID, ParentID, 0--( case when enquirysource in (20, 21) then 10 else 0 end)     
   from UserLeads(nolock) where ID = @LeadId and ParentID = @ParentID    
   --exec ups_las_UpdateLeadAssignmentUser @LeadId        
        
   set @LeadId += 1        
   set @tli=@tli-1    
       
 End--End While        
end        
END 


GO

/* ============================================================
   Procedure: [dbo].[usp_ExecMergeLeadEnquiryTriggerTasks]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC usp_ExecMergeLeadEnquiryTriggerTasks  
(  
 @CsvMergeLeadEnquiryId nvarchar(max)  
)  
AS  
Begin  
  
 if object_id('tempdb..#tbl_lstMergeLeadEnquiryID') is not null begin drop table #tbl_lstMergeLeadEnquiryID end  
  
 SELECT Position as RowId, value as Id into #tbl_lstMergeLeadEnquiryID from dbo.fn_split(@CsvMergeLeadEnquiryId,',')  
  
  
 declare @count int,@id bigint=0      
 select @count=count(1) from #tbl_lstMergeLeadEnquiryID      
 declare @parentid bigint,@enquiryid bigint,@rawenquiryid bigint,@source nvarchar(50),@leadno bigint      
  
 while @count>0      
 begin      
  select @id=min(id) from #tbl_lstMergeLeadEnquiryID where id>@id      
  select @enquiryid=EnquiryNo,@leadno=LeadNo from tbl_MergeLeadsEnquiry(nolock) where id=@id      
  select @parentid=parentid from UserEnquiry(nolock) where enquiryid=@enquiryid      
  
  if not exists(select 1 from LeadInteractionHistory(nolock) where leadno=@LeadNo and parentid=@parentid)    
  begin      
   insert into LeadInteractionHistory(LeadNo,FollowUpStatus,NextStatusDate,Remarks,AssignedTo,ParentID,CreatedOn,CreatedBy,FollowupDate,Products,
   AmountPaid,IsAutoEntry,id_lead)      
   select leadno, isnull(FollowupStatus,1), isnull(Followupdate,createdon), Remarks, isnull(assignedto,parentid), parentid, CreatedOn, CreatedBy, FollowupDate, Products, AmountPaid, case when isnull(enquirysource,0) not in 
    (12,13,14,15,22,23,24) then 1 
   else 0 end as IsAutoEntry,id   
   from userleads(nolock)  
   where  leadno=@LeadNo and parentid=@parentid      
  end      
  
  set @count=@count-1      
 end      
  
 if object_id('tempdb..#tbl_lstMergeLeadEnquiryID') is not null begin drop table #tbl_lstMergeLeadEnquiryID end  
  
End  


GO

/* ============================================================
   Procedure: [dbo].[usp_execute_massmktgsequence_id]
