CREATE   PROCEDURE [dbo].[usp_execute_massmktgsequence_id] --3119,12560--2503,12352--2466,12350
 --2062,12139--750938--576912--31962967--33723--33539 --1325
	@batchid bigint,@actionid bigint  
as  
--declare @batchid bigint=3119,@actionid bigint=12560
begin  
begin try
DECLARE @sqlquery NVARCHAR(MAX),@sql NVARCHAR(MAX);
update tbl_mass_mktgsequence set isprocessed=2 where batchid=@batchid and sequenceactionid=@actionid
declare @actiontype nvarchar(50),@actiondetails nvarchar(max),@parentid bigint,@sequencename nvarchar(200),@sequenceid bigint,@a_count int,@entity nvarchar(20),@entityplaceholders nvarchar(1000),@sms_insertsql nvarchar(max),@sms_table varchar(100),@createdby bigint,@ispersonalizedmail int=0, @LeadIds Varchar(max)
select top 1 @entityplaceholders=dbo.ExtractPlaceholders(@entity,actiondetails)
,@sequenceid=sequenceid,@actiontype=actiontype,@actiondetails=
actiondetails,@parentid=parentid,@entity=entity,@createdby=createdby from tbl_mass_mktgsequence (nolock) where batchid=@batchid and @actionid= sequenceactionid

select @actiontype=case when @actiontype in ('addtag','add tag','addcommontag','addenquirytag','addleadtag') then 'addtag'
when @actiontype in ('removetag','remove tag','removecommontag','removeenquirytag','removeleadtag') then 'removetag'
else @actiontype end

select @a_count= count(1) from tbl_mass_mktgsequence (nolock) where batchid=@batchid and @actionid= sequenceactionid
and scheduledfor<=getdate()

print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'), ': Records to be processed: ',@a_count)

/*if [dbo].[fn_parent_hasactivesubscription](@parentid)=1 and exists
(select 1 from mysmsconversations.dbo.tbl_WA_SequenceMaster(nolock) where SequenceId=@sequenceid and IsActive=1 and IsDeleted=0)*/
DECLARE @exists bigint;

-- Build the dynamic SQL query to check both conditions
SET @sqlquery = '
    
            SELECT cast(1 as bigint)
           FROM tbl_WA_SequenceMaster (NOLOCK) 
WHERE SequenceId = ' + CAST(@sequenceid AS NVARCHAR) + ' AND IsActive = 1 AND IsDeleted = 0';

-- Execute the dynamic query using the CLR procedure to capture the result
EXEC usp_clr_GetRemoteLongValue  @sqlquery, @retval = @exists OUT;

-- Check if the conditions were met and execute the desired action
if [dbo].[fn_parent_hasactivesubscription](@parentid)=1 and @exists > 0
begin
print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'), ': Active subscription and sequence')

select @sequencename=[name] from [10.0.0.135].mysmsconversations.dbo.tbl_WA_SequenceMaster with (nolock) where SequenceId=@sequenceid 
--select @sqlquery = '
--    SELECT [name]
--    FROM tbl_WA_SequenceMaster WITH (NOLOCK)
--    WHERE SequenceId = @sequenceid
--';

---- Execute the dynamic query using the CLR procedure to capture the result
--EXEC usp_clr_GetRemoteStringValue @sqlquery, @retval = @sequencename OUT;

drop table if exists #entity_action_replaced
drop table if exists #sequenceaction
create table #entity_action_replaced(entityid bigint,actiondetails nvarchar(max))
create table #sequenceaction(entityid bigint,actiondetails nvarchar(max))

declare @entities as entities 

insert into @entities(entity,entityid)
select @entity,entityid from tbl_mass_mktgsequence(nolock) t where batchid=@batchid and @actionid=sequenceactionid

--Replace entityplaceholder with the real values  
declare @isprocessed bit, @processedat datetime,@taskstatus bit,@statusreason nvarchar(100),@internalerror nvarchar(500),
@eligible int=0,@creditsrequired numeric(18,4)

print concat('Processing for action: ',@actiontype)
if @actiontype in ('sendsms','sendmail','sendvoice')  
begin
select @creditsrequired=case when @actiontype='sendsms' then mobilecount when  @actiontype='sendmail' then emailcount
when @actiontype='sendvoice' then (select price from dbo.fn_GetVoiceCreditCalculation('Trans',@parentid,60,mobilecount) )end
from
(select sum(emailcount) emailcount,sum(mobilecount) mobilecount from
(select sum(case when mobile<>'0' then 1 else 0 end) mobilecount, sum(case when email<>'1' then 1 else 0 end) emailcount 
from userleads_mobile_email u join @entities e on u.ulme_id=e.entityid where @entity='lead'
union all
select sum(case when mobile<>'0' then 1 else 0 end) mobilecount, sum(case when email<>'1' then 1 else 0 end) emailcount 
from userenquiry_mobile_email u join @entities e on u.enquiryid=e.entityid where @entity='enquiry'
) a
) b

print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'), ': Credits required: ',@creditsrequired, ', sms bal: ',dbo.fn_getsmsbalance(@parentid),', mail bal: ',dbo.fn_getmailbalance(@parentid),', wallet bal: ',
dbo.fn_getmoneybalance(@parentid))

select @eligible=
case 
when dbo.fn_getsmsbalance(@parentid)>=@creditsrequired  and @actiontype='sendsms' then 1
when dbo.fn_getmailbalance(@parentid)>=@creditsrequired  and @actiontype='sendmail' then 1
when dbo.fn_getmoneybalance(@parentid)>=@creditsrequired  and @actiontype='sendvoice' then 1 
when @creditsrequired>0 then 1
else 0 end
if @eligible =0
begin
select @isprocessed=1,@taskstatus=0,@processedat=getdate(),@statusreason='Insufficient balance for activity type: '+@actiontype

end
end
else
begin
set @eligible=1
end
print concat('iseligible: ',@eligible)
if @eligible=1
begin  
insert into #sequenceaction(entityid,actiondetails)
exec [usp_replaceentityplaceholders_bulk_singlecontent] @entities,@actiondetails,@entityplaceholders

select @a_count=count(1) from #sequenceaction
  
if @actiontype in ('sendsms','sendmail','sendvoice','updaterecord','updaterecordlead','updaterecordenquiry','Addscore', 'addfollowup', 'createTicket', 'addtag','removetag', 'add task','add appointment','reassignlead','createTask','adddeal')  
