begin try

declare @PipelineID BIGINT        
 ,@PipelineStage BIGINT        
 ,@dealAmount nvarchar(200)        
 ,@EstimatedClosureDate int        
 ,@DealOwner BIGINT        
 ,@Probability NUMERIC(18, 2)
 

 
 SELECT @PipelineID=Dealpipeline, @PipelineStage=DealStage,   
      @dealAmount=Dealvalue,@EstimatedClosureDate=Estimatedclosuredate,@DealOwner=DealOwner,@Probability=Probability
      from OPENJSON(@actiondetails) WITH(   
Dealpipeline BIGINT, DealStage bigint,Dealvalue VARCHAR(200) ,Estimatedclosuredate int, DealOwner bigint,
Probability NUMERIC(18, 2)
      ) 

declare @amountplaceholders nvarchar(1000)=dbo.ExtractPlaceholders(@entity,@dealAmount)

drop table if exists #deal_data
create table #deal_data(entity nvarchar(20),entityid bigint,amount nvarchar(200))
declare @deal_part_entities as entities
select @a_count= count(1) from @entities
declare @dd bigint=0
while @a_count>0
begin
insert into @deal_part_entities(entity,entityid)
select top 500 entity,entityid from @entities where entityid>@dd order by entityid

insert into #deal_data(entity,entityid,amount)
select entity,entityid,@dealAmount from @deal_part_entities

if isnull(@amountplaceholders,'')<>''
begin
exec [usp_replaceentityplaceholders_bulk_singlecontent_tableinsert]
@deal_part_entities,@dealAmount,@amountplaceholders,@batchid,'dealamount',@actionid

if exists(select 1 from mass_replaced_content(nolock) m where batchid=@batchid and sequenceactionid=@actionid
and m.isprocessed=0 and m.type='dealamount'
)
begin

update c set c.amount =m.replacedcontent from #deal_data c join mass_replaced_content m on m.entityid=c.entityid
where m.batchid=@batchid and m.sequenceactionid=@actionid and m.isprocessed=0 and m.type='dealamount' and m.entity=@entity 
update m set isprocessed=1 from mass_replaced_content m 
(nolock) where m.batchid=@batchid and m.sequenceactionid=@actionid and m.isprocessed=0 and m.type='dealamount' and m.entity=@entity
end
end
select @PipelineID,@PipelineStage,@EstimatedClosureDate,@DealOwner,@CreatedBy,@Probability,@batchid,
@actionid,'dealamount',@dealAmount,* from @deal_part_entities

exec Usp_AddDeal_New_bulk 
@deal_part_entities,@PipelineID,@PipelineStage,@EstimatedClosureDate,@DealOwner,@CreatedBy,@Probability,@batchid,
@actionid,'dealamount',@dealAmount

delete from @deal_part_entities
select @dd=max(entityid) from #deal_data
truncate table #deal_data
select @a_count=@a_count-500

end


select @isprocessed=1,@taskstatus=1,@processedat=getdate()  
end try
begin catch
exec usp_inserterrorinfo
select @internalerror=ERROR_MESSAGE()  
select @isprocessed=1,@taskstatus=0,@statusreason=@internalerror  
end catch
end 

