print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'), ': Entered lead add followup/reAssignLead section')

	begin try
	if @entity='enquiry' and exists(select 1 from @newleadentities)
	begin
	delete from @entities
	insert into @entities(entity,entityid)
	select entity,entityid from @newleadentities
	end
	else
	begin
    select @isprocessed=1,@taskstatus=0,@processedat=getdate(),@internalerror='Enquiry already has a lead with matching email/mobile'
	end
	if @entity='lead'  or exists(select 1 from @newleadentities)
	begin
		declare @isOwner bit = 0, @OwnerId bigint = 0, @Amount decimal(18, 4) = 0, @nextStatusHH int = 0, @flRemarks nvarchar(max), @reAssign int = case when @actiontype='addfollowup' then 2 else 1 end, @product nvarchar(555), @isReAssign bit = 0, @followUpDetail nvarchar(max), 
@productDetails nvarchar(max), @productIds nvarchar(500),@followuptype nvarchar(20),
		@nextStatusDate datetime = getdate(), @followUpId bigint = 0, @productType nvarchar(25) ,
		@productsjson nvarchar(2000),@p_c int

		if @actiontype='addfollowup'
		begin
		print 'entered addfollowup'
		select @isOwner = isOwner,  @Amount = amount, @nextStatusHH = nextStatusDate, @OwnerId = OwnerId, @flRemarks = 
remarks, @isReAssign = reAssign, @productDetails = products, @followUpDetail = followUpDetail, @productType = productType,

		@followuptype = followuptype
		from openjson(@actiondetails) with ( 
			isOwner bit '$.owner.isExisting', 
			OwnerId bigint '$.owner.id',
			followuptype nvarchar(20) '$.owner.type',
			amount decimal(18,4) '$.amount', 
			nextStatusDate int '$.nextStatusDate', 
			remarks nvarchar(max) '$.remarks', 
			reAssign bit '$.reAssign',  
			products nvarchar(max) '$.products' as json, 
			followUpDetail nvarchar(max) '$.followUpDetail.id',
			productType nvarchar(max) '$.productType' 
		)


		declare @existingProduct nvarchar(1000) = ''
		if(isnull(@followUpDetail, '') <> '')
		begin
			select @followUpId = [value] from 
			( select *, ROW_NUMBER() over (partition by (select null) order by (select null)) as [sno]
				from String_split(@followUpDetail, ',')) fl where fl.sno = 1
		end

		

		declare @i int=0
		if(isnull(@productType, '') = 'predefined')
		begin
			set @productIds  = ( select STRING_AGG(productId, '#') from openjson(@productDetails) with (
				productId bigint '$.productId' ))
			set @productIds = ISNULL(@productIds, '')
			select @productsjson=@productDetails
			while @productsjson like '%productId%' and isjson(@productdetails)=1
			begin
			begin try
			select @productsjson=(select JSON_MODIFY(@productDetails,concat('$[',@i,']].productId'),Null))
			end try
			begin catch
			exec usp_InsertErrorInfo
			select @productsjson=''
			end catch
			set @i=@i+1
			end
			
		end

		end
		
		
		
	drop table if exists #foll
	create table #foll(entityid bigint,isOwner bit default 0, OwnerId bigint default 0, Amount decimal(18, 4) default 0, 
	nextStatusHH int default 0, flRemarks nvarchar(max), reAssign int default 0, product nvarchar(555), isReAssign bit 
	default 0, followUpDetail nvarchar(max), productDetails nvarchar(max), productIds nvarchar(500),followuptype 
	nvarchar(20),nextStatusDate datetime default getdate(), followUpId bigint default 0, productType nvarchar(25), 
	productsjson nvarchar(max) )

	insert into #foll(entityid,isOwner, OwnerId, Amount, nextStatusHH, flRemarks, isreAssign, product 
		, followUpDetail , productDetails, productIds ,followuptype,nextStatusDate, followUpId, productType,
		productsjson,reassign)
		select entityid,@isOwner,case when @actiontype<>'addfollowup' or @followuptype = 'existing' then u.AssignedTo
		when @followuptype = 'asperrule' then 0 else @OwnerId end, isnull(@amount,0),@nextStatusHH, case when @actiontype='addfollowup' then @flRemarks else u.Remarks end, case when @actiontype='addfollowup'then @reAssign
		else 1 end, 
		case when @actiontype<>'addfollowup' or isnull(@productType, '') = 'existing' then u.products when 
		isnull(@productType, '') = 'predefined' then 
		@productIds else '' end, 
		@followUpDetail,@productDetails,
		case when @actiontype<>'addfollowup' or isnull(@productType, '') = 'existing' then u.products when isnull(@productType, '') = 'predefined' then 
		@productIds else '' end,@followuptype,
		case when isnull(@nextStatusHH,'')<>'' then 
		DATEADD(HOUR, try_convert( int, @nextStatusHH), getdate()) else getdate() end ,case when @actiontype<>'addfollowup' then u.FollowUpStatus else @followUpId end,@productType,
		case when @actiontype<>'addfollowup' or isnull(@productType, '') = 'existing' then u.productsjson when 
		isnull(@productType, '') = 'predefined' then @productsjson else '' end,@reassign
		from @entities e join UserLeads(nolock) u on u.id=e.entityid


		if(@actiontype<>'addfollowup' or @followuptype = 'asperrule')
		begin
		drop table if exists #assigned
		create table #assigned(entityid bigint,assignedto bigint)

		select @a_count=count(1) from @entities
		while @a_count>0
		begin
		declare @ef_part as entities

		insert into @ef_part(entity,entityid)
		select top 1000 entity,entityid from @entities e where not exists (select 1 from #assigned where entityid=e.entityid)

		--insert into #assigned(entityid,assignedto)
		begin try
		execute MySMS.dbo.ups_las_ReplicaLeadAssignmentUser_bulk	@ef_part,@batchid,@actionid,@actiontype
		end try
		begin catch
		exec usp_inserterrorinfo
		end catch
		insert into #assigned(entityid,assignedto)
		select entityid,replacedcontent from mass_replaced_content(nolock) m where batchid=@batchid and sequenceactionid=@actionid and type=@actiontype and isprocessed=0 and entityid in
		(select entityid from @ef_part)

		delete from @ef_part
		set @a_count=@a_count-1000
		end

		select @a_count=count(1) from #foll
		update f set f.OwnerId=coalesce(nullif(a.assignedto,0),isnull(nullif(dbo.fn_getleadowner(f.entityid
		),0),@parentid)) from #foll f join #assigned a on f.entityid=a.entityid
		select * from #foll
		select coalesce(nullif(OwnerId,0),isnull(nullif(dbo.fn_getleadowner(f.entityid
		),0),@parentid)),* from #foll f
		end
		--print concat('@followUpId: ',@followUpId,', @nextStatusDate: ',@nextStatusDate,', @productIds: ',@productIds,', @Amount: ',@Amount,', @flRemarks: ',@flRemarks,'@OwnerId: ',@OwnerId)
		
		declare @massfollowup as massfollowup
		select '@massfollowup',* from @massfollowup
		while @a_count>0
		begin
		print concat('Mass followup starting for records: ',@a_count)
		insert into @massfollowup 
		(entityid,FollowUpStatus,assignedto,products,productsjson,modifiedby,modifiedon,followupdate,
		nextstatusdate,remarks,AmountPaid,IsReAssign,actiontype)
		select top 1000 entityid,followUpId,coalesce(nullif(ownerid,0),isnull(nullif(dbo.fn_getleadowner(f.entityid
		),0),@parentid)),productIds,productsjson,@parentid,getdate(),nextStatusDate,
		nextstatusdate,flRemarks,amount,isReAssign,@actiontype from #foll f

		select * from @massfollowup
		exec [Usp_AddMassFollowup_bulk] @massfollowup

		delete f from #foll f join @massfollowup m on f.entityid=m.entityid
		set @a_count=@a_count-1000
		end
		end
		select @isprocessed=1,@taskstatus=1,@processedat=getdate()  
	end try  
		begin catch  
		exec mysms.dbo.usp_InsertErrorInfo  
		select @isprocessed=1,@taskstatus=0,@processedat=getdate(),@internalerror=error_message()  
	end catch  
end
