        @LeadIds= ',isnull(@LeadIds,''),', @AssignedTo= ',isnull(@AssignedTo,0),', @IsActive= ',isnull(@IsActive,0),', @TaskId= ',isnull(@TaskId,''), ', @Status= ',isnull(@Status,''),', @UserID= ',isnull(@UserID,0),', @OutcomesId= ',isnull(@OutcomesId,0),', @CollabratoerUserIds= ',isnull(@CollabratoerUserIds,''),  
        ', @IsSMS= ',isnull(@IsSMS,0),', @IsEmail= ',isnull(@IsEmail,0),', @IsTask= ',isnull(@IsTask,''),', @IsAppointment= ',isnull(@IsAppointment,0), ', @TaskType= ',isnull(@TaskType,''),', @CompleteAddress= ',isnull(@CompleteAddress,''),', @Latitude= ',isnull(@Latitude,''),   
        ', @Longitude= ',isnull(@Longitude,''))

		select @LeadIds=string_agg(cast(entityid as nvarchar(max)),',') from @entities

		declare @t_startdate datetime,@t_enddate datetime
select @t_startdate=case when @istask=1 then null else dateadd(hh,@startdate,getdate()) end,
@t_enddate=dateadd(hh,@enddate,getdate()) 
EXEC [Usp_Mass_TaskAppointment_CrtUpdt_mktg_schedule] @Title=@Title, @Description=@Description, @Remarks=@Remarks, @Address=@Address, @StartDate=@StartDate, @EndDate=@EndDate,  
        @LeadIds=@LeadIds,@AssignedTo=@AssignedTo, @IsActive=@IsActive, @TaskId=@TaskId, @Status=@Status,@UserID=@createdby,@OutcomesId=@OutcomesId,@CollabratoerUserIds=@CollabratoerUserIds,  
        @IsSMS=@IsSMS,@IsEmail=@IsEmail,@IsTask=@IsTask, @IsAppointment=@IsAppointment, @TaskType=@TaskType, @CompleteAddress=@CompleteAddress, @Latitude=@Latitude,   
        @Longitude=@Longitude, @SmsSchedule=null,@EmailSchedule=null, @NotifyMe=null, @outcomeid=0,@massbatchid=@BatchID,@mode='Insert',@error=@error output  

		select @isprocessed=1,@taskstatus=1,@processedat=getdate()
