', processedat: ',isnull(@processedat,getdate()), ',taskstatus: ',@taskstatus,', internal_error: ',@internalerror)

update tbl_mass_mktgsequence set isprocessed=@isprocessed,processedat=case when @isprocessed=1 then getdate() else @processedat end,taskstatus=@taskstatus,  
statusreason=@statusreason,internal_error=@internalerror where batchid=@batchid and sequenceactionid  =@actionid
  
end


