--Replace entityplaceholder with the real values  
declare @isprocessed bit, @processedat datetime,@taskstatus bit,@statusreason nvarchar(100),@internalerror nvarchar(500),
@eligible int=0,@creditsrequired numeric(18,4)

print concat('Processing for action: ',@actiontype)
if @actiontype in ('sendsms','sendmail','sendvoice')  
begin
select @creditsrequired=case when @actiontype='sendsms' then mobilecount when  @actiontype='sendmail' then emailcount
when @actiontype='sendvoice' then (select price from dbo.fn_GetVoiceCreditCalculation('Trans',@parentid,60,mobilecount) )end
from
(select sum(emailcount) emailcount,sum(mobilecount) mobilecount from
(select sum(case when mobile<>'0' then 1 else 0 end) mobilecount, sum(case when email<>'1' then 1 else 0 end) emailcount 
from userleads_mobile_email u join @entities e on u.ulme_id=e.entityid where @entity='lead'
union all
select sum(case when mobile<>'0' then 1 else 0 end) mobilecount, sum(case when email<>'1' then 1 else 0 end) emailcount 
from userenquiry_mobile_email u join @entities e on u.enquiryid=e.entityid where @entity='enquiry'
) a
) b

print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'), ': Credits required: ',@creditsrequired, ', sms bal: ',dbo.fn_getsmsbalance(@parentid),', mail bal: ',dbo.fn_getmailbalance(@parentid),', wallet bal: ',
dbo.fn_getmoneybalance(@parentid))

select @eligible=
case 
when dbo.fn_getsmsbalance(@parentid)>=@creditsrequired  and @actiontype='sendsms' then 1
when dbo.fn_getmailbalance(@parentid)>=@creditsrequired  and @actiontype='sendmail' then 1
when dbo.fn_getmoneybalance(@parentid)>=@creditsrequired  and @actiontype='sendvoice' then 1 
when @creditsrequired>0 then 1
else 0 end
if @eligible =0
begin
select @isprocessed=1,@taskstatus=0,@processedat=getdate(),@statusreason='Insufficient balance for activity type: '+@actiontype

end
end
else
begin
set @eligible=1
end
print concat('iseligible: ',@eligible)
if @eligible=1
