begin
print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'), ': Entered add score')


if 1=1-- mysms.dbo.Func_IsScoreEligible(@entityid)=1
begin
begin try
drop table if exists #lsh_inserted
create table #lsh_inserted(id bigint,entityid bigint)
insert into mysms.dbo.lead_score_history(lsh_eventid,parentid,leadid,ScoreAdded,CurrentScore,createdon,lead_activity_id,
batchid ,sequenceid
) 
output inserted.id,inserted.leadid into #lsh_inserted
select 0,@parentid,entityid,@actiondetails,isnull(l.currentscore,0)+(@actiondetails),getdate(),0,@batchid,@actionid from @entities e
left join (select leadid,currentscore from  lead_score_history_latest(nolock)) l  on l.leadid=e.entityid
where dbo.Func_IsScoreEligible(e.entityid)=1


declare @as_tbl as LeadActivitywithid_Tbltype

insert into @as_tbl(LeadID,ParentID,EventName,EventDescription,UserID,RefTable,refid)
select entityid,@parentid,'Lead score affected','Lead score of lead was affected as '+@actiondetails+' points were added to the current score. The action was triggered  through automated rule/sequence named "'
+coalesce(@sequencename,'Unknown')+'"',@createdby,'lead_score_history',id
from #lsh_inserted 


exec UspSaveentityActivity_withMultipleValue_withid_bulk @as_tbl

select @isprocessed=1,@taskstatus=1,@processedat=getdate()  
end try
begin catch
exec usp_inserterrorinfo
select @isprocessed=1,@taskstatus=0,@processedat=getdate(),@internalerror=error_message()  

