			@AssignedUser = @tkAssignedUser,
			@AssignedSource = 20,
			@CustomFieldValueJson = null,
			@CreateEntityLogin = @tkCreateEntityLogin,
			@ResultOut = @tkTicketId

		print concat('@tkTicketId => ', @tkTicketId)
		select @isprocessed=1,@taskstatus=1,@processedat=getdate()  
	end try  
		begin catch  
		exec mysms.dbo.usp_InsertErrorInfo  
		select @isprocessed=1,@taskstatus=0,@processedat=getdate(),@internalerror=error_message()  
	end catch
end
*/
else if(@actiontype in( 'addtolist', 'removefromlist'))
begin
print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'), ': add/remove from list')
	declare @unsubscribe bit=case when @actiontype='addToList' then 1 else 0 end 
	begin try
	exec [10.0.0.135].mysmsconversations.dbo.usp_userchannelsubscription_bulk @entities,2,@parentid,@unsubscribe,null 
	/*SET @sqlquery = '
    EXEC usp_userchannelsubscription_bulk 
        ''' + @entities + ''', 
        2, 
        ' + CAST(@parentid AS NVARCHAR) + ', 
        ' + CAST(@unsubscribe AS NVARCHAR) + ', 
        NULL
    ';
	EXEC usp_clr_ExecuteRemoteQuery @sqlquery;*/
	select @isprocessed=1,@taskstatus=1,@processedat=getdate()
	end try
	begin catch
		exec mysms.dbo.usp_InsertErrorInfo  
		select @isprocessed=1,@taskstatus=0,@processedat=getdate(),@internalerror=error_message()  
	end catch
end
else if (@actiontype in ('addtag','removetag'))
begin
print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'), ': add/remove tag')
begin try
declare @tagid bigint
select top 1 @tagid=id from tagmaster(nolock) where parentid=@parentid and tag=@actiondetails
if isnull(@tagid,0)=0 and @actiontype='addtag'
begin
insert into tagmaster(tag,ParentID,CreatedDate,CreatedBy,IsActive)
select @actiondetails,@parentid,getdate(),@createdby,1
select @tagid=SCOPE_IDENTITY()
end
drop table if exists #entity_tags
create table #entity_tags(mappedid bigint,entity nvarchar(20) ,entityid bigint,tagid bigint)

if @actiontype='addtag'
begin
insert into EntityTagMapping(entity,entityid,TagID,ParentId,CreatedDate) output
inserted.id,inserted.entity,inserted.EntityID,@tagid into #entity_tags
select entity,entityid,@tagid,@parentid,getdate() from @entities e where not exists
(select 1 from EntityTagMapping(nolock) where entity=e.entity and entityid=e.entityid and tagid=@tagid)
end
else
begin
delete d output deleted.id,deleted.entity,deleted.entityid,@tagid into #entity_tags
from EntityTagMapping d join @entities e on d.Entity=e.entity and d.entityid=e.entityid and d.tagid=@tagid
end

declare @creator_username nvarchar(100)=(select user_login from User_Detail(nolock) where user_id=@createdby)
DECLARE @tbl1 AS LeadActivitywithid_Tbltype  
 
 INSERT INTO @tbl1 ( leadid,userid,parentid,eventdescription,eventname,reftable,refid)  
 SELECT entityid,@createdby,@ParentID  
	,case when @actiontype='addtag' then
	'A new tag "'+@actiondetails+'" was added to lead no '+cast(leadno as nvarchar)+' , lead name '+personname+' by '+@creator_username
	else 'Tag "'+@actiondetails+'" was removed from lead no '+cast(leadno as nvarchar)+' , lead name '+personname+' by '+@creator_username end
    ,case when @actiontype='addtag' then 'Tag added to lead'  else 'Tag removed from lead' end
    ,'EntityTagMapping'  
    ,mappedid  
   FROM #entity_tags l  
   JOIN userleads f(nolock) ON f.ID = l.entityid
   where l.entity='lead'
   union
	SELECT entityid,@createdby,@ParentID  
	,case when @actiontype='addtag' then
	'A new tag "'+@actiondetails+'" was added to enquiry no '+cast(enquiryid as nvarchar)+' , enquiry name '+personname+
	' by '+@creator_username
	else 'Tag "'+@actiondetails+'" was removed from enquiry no '+cast(enquiryid as nvarchar)+' , enquiry name '+personname
	+' by '+@creator_username end
    ,case when @actiontype='addtag' then 'Tag added to enquiry'  else 'Tag removed from enquiry' end
    ,'EntityTagMapping'  
    ,mappedid  
   FROM #entity_tags l  
   JOIN userenquiry f(nolock) ON f.enquiryID = l.entityid
   where l.entity='enquiry'



   		select @isprocessed=1,@taskstatus=1,@processedat=getdate()

	 EXEC UspSaveentityActivity_withMultipleValue_withid_bulk @tbl1  
	 end try
	begin catch
		exec mysms.dbo.usp_InsertErrorInfo  
		select @isprocessed=1,@taskstatus=0,@processedat=getdate(),@internalerror=error_message()  
	end catch



end
else if (@actiontype in ('add task','add appointment','createTask'))
begin
begin try
print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'), ': add task/appointment section')
declare @Title VARCHAR(255) ,@Description VARCHAR(1000), @Address VARCHAR(500), @StartDate int, @EndDate int, @LeadIds Varchar(max),                       
     @IsActive BIT, @TaskId BIGINT, @Status VARCHAR(255), @OutcomesId BIGINT, @CollabratoerUserIds VARCHAR(1000), @IsSMS 
BIT, @IsEmail BIT, @IsTask BIT, @IsAppointment BIT,@TaskType VARCHAR(100),  
     @CompleteAddress VARCHAR(500) ,@Latitude VARCHAR(50), @Longitude VARCHAR(50),@error nvarchar(max),@assignedto bigint,
	 @remarks nvarchar(max),@userid bigint
 
 
 SELECT @AssignedTo=AssignTo, @Remarks=Remarks,   
      @Title=Title,@Description=Description,@Address=Address,@StartDate=StartDate, @EndDate=EndDate,@LeadIds=LeadIds,  
      @IsActive =IsActive, @TaskId=TaskId,@Status=Status, @OutcomesId=OutcomesId, 
@CollabratoerUserIds=CollabratoerUserIds, @IsSMS=IsSMS,@IsEmail=IsEmail, @IsTask=IsTask,  
      
@IsAppointment=IsAppointment,@TaskType=TaskType,@CompleteAddress=CompleteAddress,@Latitude=Latitude,@Longitude=Longitude  
      from OPENJSON(@actiondetails) WITH(   
AssignTo BIGINT, Remarks VARCHAR(1000),Title VARCHAR(255) ,Description VARCHAR(1000), Address VARCHAR(500), StartDate int, 
EndDate int, LeadIds Varchar(max),                         
       IsActive BIT, TaskId BIGINT, Status VARCHAR(255), OutcomesId BIGINT, CollabratoerUserIds VARCHAR(1000), IsSMS BIT, 
IsEmail BIT, IsTask BIT, IsAppointment BIT,TaskType VARCHAR(100),  
       CompleteAddress VARCHAR(500) ,Latitude VARCHAR(50), Longitude VARCHAR(50)
      ) 

	  	--select @LeadIds=string_agg(cast(entityid as nvarchar(max)),',') from @entities
	  
	  print concat('@Title= ',isnull(@Title,''), ', @Description= ',isnull(@Description,''), ', @Remarks= ',
	  isnull(@Remarks,''),', @Address= ',isnull(@Address,''), ', @StartDate= ',isnull(@StartDate,''),', @EndDate= ',
	  isnull(@EndDate,''),',   
        @LeadIds= ',isnull(@LeadIds,''),', @AssignedTo= ',isnull(@AssignedTo,0),', @IsActive= ',isnull(@IsActive,0),', @TaskId= ',isnull(@TaskId,''), ', @Status= ',isnull(@Status,''),', @UserID= ',isnull(@UserID,0),', @OutcomesId= ',isnull(@OutcomesId,0),', @CollabratoerUserIds= ',isnull(@CollabratoerUserIds,''),  
        ', @IsSMS= ',isnull(@IsSMS,0),', @IsEmail= ',isnull(@IsEmail,0),', @IsTask= ',isnull(@IsTask,''),', @IsAppointment= ',isnull(@IsAppointment,0), ', @TaskType= ',isnull(@TaskType,''),', @CompleteAddress= ',isnull(@CompleteAddress,''),', @Latitude= ',isnull(@Latitude,''),   
        ', @Longitude= ',isnull(@Longitude,''))

		select @LeadIds=string_agg(cast(entityid as nvarchar(max)),',') from @entities

		declare @t_startdate datetime,@t_enddate datetime
select @t_startdate=case when @istask=1 then null else dateadd(hh,@startdate,getdate()) end,
@t_enddate=dateadd(hh,@enddate,getdate()) 
EXEC [Usp_Mass_TaskAppointment_CrtUpdt_mktg_schedule] @Title=@Title, @Description=@Description, @Remarks=@Remarks, @Address=@Address, @StartDate=@StartDate, @EndDate=@EndDate,  
        @LeadIds=@LeadIds,@AssignedTo=@AssignedTo, @IsActive=@IsActive, @TaskId=@TaskId, @Status=@Status,@UserID=@createdby,@OutcomesId=@OutcomesId,@CollabratoerUserIds=@CollabratoerUserIds,  
        @IsSMS=@IsSMS,@IsEmail=@IsEmail,@IsTask=@IsTask, @IsAppointment=@IsAppointment, @TaskType=@TaskType, @CompleteAddress=@CompleteAddress, @Latitude=@Latitude,   
        @Longitude=@Longitude, @SmsSchedule=null,@EmailSchedule=null, @NotifyMe=null, @outcomeid=0,@massbatchid=@BatchID,@mode='Insert',@error=@error output  

		select @isprocessed=1,@taskstatus=1,@processedat=getdate()
		select @error=@error
end try
	begin catch
		exec mysms.dbo.usp_InsertErrorInfo  
		select @isprocessed=1,@taskstatus=0,@processedat=getdate(),@internalerror=@error  
	end catch


end
end
end  
end  
else  
begin  
select @isprocessed=1,@processedat=getdate(),@taskstatus=0,@statusreason='No active subscription for user or sequence is inactive'  
end  
  
end try  
begin catch  
exec mysms.dbo.usp_inserterrorinfo  
select @internalerror=ERROR_MESSAGE(),@taskstatus=0,@isprocessed=1,@processedat=getdate()  
end catch  

print concat(format(getdate(),'dd-MM-yyyy H:mm:sss'), ': update table with results. Isprocessed: ',@isprocessed,
', processedat: ',isnull(@processedat,getdate()), ',taskstatus: ',@taskstatus,', internal_error: ',@internalerror)

update tbl_mass_mktgsequence set isprocessed=@isprocessed,processedat=case when @isprocessed=1 then getdate() else @processedat end,taskstatus=@taskstatus,  
statusreason=@statusreason,internal_error=@internalerror where batchid=@batchid and sequenceactionid  =@actionid
  
end


GO

/* ============================================================
   Procedure: [dbo].[usp_executeautomationactions]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_executeautomationactions] --5496132--4190166 --2856468--1011277--980598 --979487--750938--576912--31962967--33723--33539 --1325
@taskid bigint	--@activityid bigint  ,@entity nvarchar(20),@entityid bigint,@parentid bigint,@actiondetails nvarchar(max),@actiontype nvarchar(200),@taskid bigint,@message nvarchar(max)
as  
begin  
begin try


--declare @taskid bigint	=5427528

declare @actiontype nvarchar(50),@actiondetails nvarchar(max),@message nvarchar(max),@wa_id nvarchar(100),@entity nvarchar(200),@entityid bigint,@parentid bigint
declare @eventrefid nvarchar(20), @convuserid nvarchar(255), @leadno bigint,@leadid bigint,@action_creator bigint

,@ruleid bigint,@convparentid bigint,@convuser bigint,@activityid bigint,@eventid int,@sequencename nvarchar(200),@sequenceid bigint,@error nvarchar(max)

declare @eventname nvarchar(200),@eventdescription nvarchar(2000),@isprocessed bit=0, @processedat datetime,@taskstatus bit,@statusreason nvarchar(100),  
@internalerror nvarchar(500),@rulename nvarchar(100),@refid bigint  


select @sequenceid=sequenceid, @convuserid = convuserid,
@actiontype=actiontype,@actiondetails=actiondetails,@parentid=parentid,@ruleid=ruleid,@convparentid=convparentid,@message=messagetext,@activityid=
isnull(activityid,0)  ,@entity=twa_entity,@entityid=twa_entityid
from [10.0.0.135].MySMSConversations.dbo.tbl_wa_automationtasks with (nolock) where id=@taskid 
select @rulename=rulename from [10.0.0.135].MySMSConversations.dbo.tbl_WA_RuleMaster with (nolock) where ruleid=@ruleid  
select @sequencename=[name] from [10.0.0.135].MySMSConversations.dbo.tbl_WA_SequenceMaster with (nolock) where SequenceId=@sequenceid


print concat( 'entity: ', @entity, ', entityid: ', cast(@entityid as nvarchar),  ', actiontype:', @actiontype, ', parentid: ', @parentid)

if exists (select 1 from mysms.dbo.Price_UserSubscriptionDetails(nolock) where IsNewPlan=1 and cast(PlanEndDate as date)>=cast(getdate() as date) and UserID=@parentid )  
begin  
  
if @actiontype in ('sendsms','sendmail','sendvoice','updaterecord','Addscore', 'addfollowup', 'addtolead', 
'createTicket','reAssignLead', 'addcommontag','removecommontag', 'add task','add appointment','addAppointment','createTask','removeSegment','addSegment','adddeal','addnotes')  
begin  
print 'Entered execautomationtasks'  
--Replace message placeholder with real message  
if @actiondetails like '%#message#%' and @message is not null 
begin  
select @actiondetails=replace(@actiondetails,'#message#',@message)  
end
if @activityid>0
begin
declare @str1 nvarchar(max)
if @entity='lead'
begin
select @eventid=eventid,@eventrefid=refids,@action_creator=userid from mysms.dbo.tbl_leadeventhistory with (nolock) where historyid=@activityid
end
if @entity='enquiry'
begin
select @eventid=eventid,@eventrefid=refids,@action_creator=userid from mysms.dbo.tbl_enquiryeventhistory with (nolock) where historyid=@activityid
end
exec mysms.dbo.[usp_replaceplaceholders] @activityid ,@entity ,@actiondetails ,@eventid ,@str1 OUTPUT
select @actiondetails=@str1
Print 'Actiondetails after event placeholders replace: '+@actiondetails
end

--Replace entityplaceholder with the real values  
if @actiondetails like '%#%#%'  
begin  
if @entity='enquiry'  
begin  
select @actiondetails =replace(@actiondetails,'#lead.','#enquiry.')  
end  


print concat('Entityid: ',@entityid,', Actiondetails',@actiondetails)
declare @str nvarchar(max) 
if @eventid<>28 and @actiondetails not like '%#enquiry.'
begin
exec mysms.dbo.[usp_replaceentityplaceholders] @entityid,@entity,@actiondetails,@str output 

end
else if @eventid=28
begin
declare @enqentityid bigint=(select try_cast(refids as bigint) from mysms.dbo.tbl_leadeventhistory (nolock) where historyid=@activityid )
exec mysms.dbo.[usp_replaceentityplaceholders] @enqentityid,'Enquiry',@actiondetails,@str output  
end

select @actiondetails=@str
Print 'Actiondetails after entity placeholders replace: '+@actiondetails

end  
  
print @actiondetails  
if @actiontype='sendsms'  
begin  
declare @smsmessage nvarchar(2500),@mobile nvarchar(50),@sender varchar(10),@isunicode bit,@priority int=2,@DLTTemplateID nvarchar(50),@smsbatchid bigint=0  
select @sender=JSON_VALUE(replace(replace(replace(@actiondetails,char(39),char(146)),char(13),''),char(10),''),'$.SenderId'),  
@DLTTemplateID=JSON_VALUE(replace(replace(replace(@actiondetails,char(39),char(146)),char(13),''),char(10),''),'$.TemplateNo'),  
@isunicode=JSON_VALUE(replace(replace(replace(@actiondetails,char(39),char(146)),char(13),''),char(10),''),'$.IsUnicode'),  
@smsmessage=JSON_VALUE(replace(replace(replace(@actiondetails,char(39),char(146)),char(13),''),char(10),''),'$.Message')  
if isnull(@activityid,0)=0
begin
select @mobile =mobile from mysms.dbo.fn_separatecountrycodeandmobile(@wa_id)  
end
else
begin
if @entity='enquiry'  
begin  
print 'enquiry'
select @mobile=coalesce(@mobile+', ','')+mobile from mysms.dbo.Userenquiry_Mobile_Email with (nolock) where enquiryid=@entityid and mobile<>'0'  
end  
else if @entity='lead'  
begin  
print 'lead'
select @mobile=coalesce(@mobile+', ','')+mobile from mysms.dbo.Userleads_Mobile_Email with (nolock) where ulme_id=@entityid and mobile<>'0'  
end  


end
print 'send sms: parentid: ' +cast(@parentid as nvarchar)+', smsmessage: '+@smsmessage+ ', mobile: '+@mobile+ ', senderid: '+@sender+' isunicode: '+  
cast(@isunicode as nvarchar)+', priority: '+cast(@priority as nvarchar)+ ', dlt: '+cast(@DLTTemplateID as nvarchar)  
begin try
exec mysms.dbo.usp_sendmessage_WithDLTTemplateID_withoutput @parentid,@smsmessage,@mobile,@sender,@isunicode,@priority,@DLTTemplateID,'Automation',@smsbatchid out  
select @isprocessed=1,@taskstatus=1,@processedat=getdate()  
select @eventname='SMS sent to '+@entity,  
@eventdescription =user_login+' sent a SMS with senderid '+@sender+' and message text like "'+left(@smsmessage,30)+'" to mobile '+@mobile+' through automated rule/sequence named "'
+coalesce(@rulename,@sequencename,'Unknown')+'"'  
from mysms.dbo.user_detail (nolock) where user_id=@parentid  
exec mysms.dbo.UspSaveEntityActivity_withid @entity,@Entityid,@parentid,@parentid,@eventdescription,@eventname,'batchinfo',@smsbatchid    
  
end try  
begin catch  
exec mysms.dbo.usp_InsertErrorInfo  
select @isprocessed=1,@taskstatus=0,@processedat=getdate(),@internalerror=ERROR_MESSAGE()  
  
end catch  
  
end  
--Execute send mail action  
else if @actiontype='sendmail'  
begin  
print 'sendmail'
declare @frommail nvarchar(100),@replyto nvarchar(100),@emailtype varchar(20),@subject nvarchar(200),@templateid bigint,@mailmessage nvarchar(max)  
,@emails nvarchar(1000),@batchid bigint=0  
select @frommail=JSON_VALUE(replace(replace(replace(@actiondetails,char(39),char(146)),char(13),''),char(10),''),'$.FromEmailId'),  
@replyto=JSON_VALUE(replace(replace(replace(@actiondetails,char(39),char(146)),char(13),''),char(10),''),'$.ReplyTo'),  
@emailtype=JSON_VALUE(replace(replace(replace(@actiondetails,char(39),char(146)),char(13),''),char(10),''),'$.EmailType'),  
@subject=JSON_VALUE(replace(replace(replace(@actiondetails,char(39),char(146)),char(13),''),char(10),''),'$.Subject'),  
@templateid=JSON_VALUE(replace(replace(replace(@actiondetails,char(39),char(146)),char(13),''),char(10),''),'$.TemplateId'),  
@mailmessage=JSON_VALUE(@actiondetails,'$.MessageBody')  
print 1
if isnull(@mailmessage,'')='' and isnull(@templateid,0) >0
begin
set @str=null
select @mailmessage=MailContent from mysms.dbo.UserMailTemplate(nolock) where id=@templateid
exec mysms.dbo.[usp_replaceentityplaceholders] @entityid,@entity,@mailmessage,@str output  
select @mailmessage=@str

if isnull(@subject,'')=''
begin
set @str=null
select @subject=u.MailSubject from mysms.dbo.UserMailTemplate(nolock) u where id=@templateid
exec mysms.dbo.[usp_replaceentityplaceholders] @entityid,@entity,@subject,@str output  
select @subject=@str
end
end

print 'send mail: parentid: ' +cast(@parentid as nvarchar)+  ', Frommail: '+@frommail+' ReplyTo: '+  
cast(@replyto as nvarchar)+', Templateid: '+cast(@TemplateID as nvarchar)+ ', Subject: '+cast(@Subject as nvarchar)
print 'mailmessage: '+@mailmessage  

if @entity='enquiry'  
begin  
print 'enquiry'
select @emails=coalesce(@emails+', ','')+email from mysms.dbo.Userenquiry_Mobile_Email with (nolock) where enquiryid=@entityid and email<>'1'  
end  
else if @entity='lead'  
begin  
print 'lead'
select @emails=coalesce(@emails+', ','')+email from mysms.dbo.Userleads_Mobile_Email with (nolock) where ulme_id=@entityid and email<>'1'  
end  

print 'send mail: parentid: ' +cast(@parentid as nvarchar)+ ', emails: '+@emails+ ', Frommail: '+@frommail+' ReplyTo: '+  
cast(@replyto as nvarchar)+', Templateid: '+cast(@TemplateID as nvarchar)+ ', Subject: '+cast(@Subject as nvarchar)+', mailmessage: '+@mailmessage  
  
if @emails<>'' and @emails like '%@%'  
begin  
exec mysms.dbo.[usp_SendMails]  @emails,@parentid,@Subject,@TemplateID,@mailmessage,@frommail,@ReplyTo,'T',2,'AutomationRules',@batchid out  
select @isprocessed=1,@taskstatus=1,@processedat=getdate()  
select @eventname='Mail sent to '+@entity,  
@eventdescription =user_login+' sent a Mail with subject '+@subject+' to email(s) '+@emails+' through automated rule/sequence named "'+coalesce(@rulename,@sequencename,'Unknown')+'"'  
from mysms.dbo.user_detail (nolock) where user_id=@parentid  
exec mysms.dbo.UspSaveEntityActivity_withid @entity,@Entityid,@parentid,@parentid,@eventdescription,@eventname,'batchemail_infos',@batchid    
end  
else  
begin  
select @isprocessed=1,@taskstatus=0,@processedat=getdate(),@internalerror='No valid email id'  ,@statusreason='No valid email id'  
end  
end  
--Execute send voice action  
else if @actiontype='sendvoice'  
begin  
declare @vmobile nvarchar(20),@appid bigint,@dnid nvarchar(20),@duration int,@scheduledfor datetime=getdate(),@vroute nvarchar(20),@vbatchid bigint  
select @vroute=JSON_VALUE(replace(replace(replace(@actiondetails,char(39),char(146)),char(13),''),char(10),''),'$.VoiceType'),  
@dnid=JSON_VALUE(replace(replace(replace(@actiondetails,char(39),char(146)),char(13),''),char(10),''),'$.DNINumber'),  
@AppId=JSON_VALUE(replace(replace(replace(@actiondetails,char(39),char(146)),char(13),''),char(10),''),'$.AppId'),  
@Duration=JSON_VALUE(replace(replace(replace(@actiondetails,char(39),char(146)),char(13),''),char(10),''),'$.VoiceDuration')  
if isnull(@activityid,0)=0
begin
select @vmobile =mobile from mysms.dbo.fn_separatecountrycodeandmobile(@wa_id)  
end
else
begin
if @entity='enquiry'  
begin  
print 'enquiry'
select @vmobile=coalesce(@vmobile+', ','')+mobile from mysms.dbo.Userenquiry_Mobile_Email with (nolock) where enquiryid=@entityid and mobile<>'0'  
end  
else if @entity='lead'  
begin  
print 'lead'
select @vmobile=coalesce(@vmobile+', ','')+mobile from mysms.dbo.Userleads_Mobile_Email with (nolock) where ulme_id=@entityid and mobile<>'0'  
end  
end

select @vroute=case when @vroute='Promotional' then 'Promo' else 'Trans' end  
print 'send voice: parentid: ' +cast(@parentid as nvarchar)+', appid: '+cast(@appid as nvarchar)+ ', mobile: '+@vmobile+ ', dnid: '+@dnid+' duration: '+  
cast(@duration as nvarchar)+', vroute: '+cast(@vroute as nvarchar)+ ', scheduledfor: '+cast(@scheduledfor as nvarchar)  
  
begin try  
exec mysms.dbo.[usp_insertnewcallForBroadcast_withoutid_outputbatchid] @parentid,@vroute,@vmobile,@appid,@dnid,@duration,@scheduledfor,@vbatchid out  
select @eventname='Voice sent to '+@entity,  
@eventdescription =user_login+' sent an automated voice call using ivr flow '+c.AppName+' to mobile '+@vmobile+' from didno '+
@dnid+' through automated rule/sequence named "'+coalesce(@rulename,@sequencename,'Unknown')+'"'  
from mysms.dbo.user_detail (nolock) u join mysms.dbo.Cloud_app_master c (nolock) on u.parentid=c.User_id  
where u.user_id=@parentid  
exec mysms.dbo.UspSaveEntityActivity_withid @entity,@Entityid,@parentid,@parentid,@eventdescription,@eventname,'batchvoiceinfo',@vbatchid    
select @isprocessed=1,@taskstatus=1,@processedat=getdate()  
end try  
begin catch  
exec mysms.dbo.usp_InsertErrorInfo  
select @isprocessed=1,@taskstatus=0,@processedat=getdate(),@internalerror=error_message()  
end catch  
end  
--Execute updaterecord action  
else if @actiontype='updaterecord'  
begin  
select @actiondetails=replace(replace(@actiondetails,char(10),' '),char(13),' ')

drop table if exists #update  
select [Key].[key] AS [Sno], [Value].*,0 isprocessed,0 tstatus,cast(null as nvarchar(max)) error into #update from openjson(replace(replace(@actiondetails,'[',''),']',''),'$')  
AS [Key]  
CROSS APPLY OPENJSON([Key].value)  
    WITH (  
        field VARCHAR(100) '$.field',  
        Value NVARCHAR(max) '$.Value',  
        datatype VARCHAR(100) '$.datatype'  
    ) AS [Value]  
 --select * from #update  
declare @fieldid bigint,@fieldvalue nvarchar(max),@fieldname nvarchar(100),@sno int=0,@tbp int,@isvalid int=0,@datatype nvarchar(20)  
, @fieldtype nvarchar(20),@datatypeoriginal nvarchar(50),@fieldnameoriginal nvarchar(100),@sql nvarchar(max),@oldvalue nvarchar(max)  
,@sqloldvalue nvarchar(max),@fuid bigint  
select @tbp=count(1) from #update  
drop table if exists #entityplaceholders  
create table #entityplaceholders(displayfield nvarchar(100),originalfield nvarchar(100),fieldtype nvarchar(20))  
insert into #entityplaceholders  
exec mysms.dbo.usp_getentityplaceholders @parentid,@entity  
  
while @tbp>0  
begin  
select @sno=min(sno),@isvalid=0,@fuid=null from #update where sno>@sno  
select @fieldname=field,@fieldvalue=value,@datatype=datatype from #update where sno=@sno  
select @fieldtype=fieldtype,@fieldnameoriginal=replace(displayfield,@entity+'.','') from #entityplaceholders where replace(displayfield,@entity+'.','')=@fieldname  
print 'sno: '+cast(@sno as nvarchar)+', fieldname: '+@fieldname+', datatype: '+@datatype+', fieldvalue: '+@fieldvalue+', fieldtype: '+@fieldtype  
  
if @fieldtype is not null  
begin  
print '0'  
if @fieldtype='predefined'  
begin  
print '1'  
if @fieldname in ('Sourcename','Mediumname','Sourcename')  
begin  
if @fieldnameoriginal ='Sourcename' and exists (select 1 from mysms.dbo.usersourcesettings(nolock) where name=@fieldvalue and IsActive=1 and UserId = @Parentid )  
select top 1 @fieldvalue=sourceid from mysms.dbo.usersourcesettings(nolock) where name=@fieldvalue and IsActive=1 and UserId = @Parentid   
else if @fieldnameoriginal ='Mediumname' and exists (select 1 from mysms.dbo.usermediumsettings(nolock) where name=@fieldvalue and IsActive=1  and UserId = @Parentid)  
select top 1 @fieldvalue=mediumid from mysms.dbo.usermediumsettings(nolock) where name=@fieldvalue and IsActive=1 and UserId = @Parentid
else if @fieldnameoriginal ='Sourcename' and exists (select 1 from mysms.dbo.usercampaignsettings(nolock) where name=@fieldvalue and IsActive=1  and UserId = @Parentid )  
select top 1 @fieldvalue=campaignid from mysms.dbo.usercampaignsettings(nolock) where name=@fieldvalue and IsActive=1 and UserId = @Parentid
else  
begin  
select @isvalid=0  
GOTO NEXT  
end  
end  
Select @datatypeoriginal=DATA_TYPE  
  from INFORMATION_SCHEMA.COLUMNS    
  Where TABLE_NAME=case lower(@Entity) when 'lead' then 'UserLeads' when 'enquiry' then 'UserEnquiry' else @Entity end    
    and COLUMN_NAME=@FieldNameoriginal    
select @sql='select @isvalid=case when try_cast('+@fieldvalue+' as '+@datatypeoriginal+') is not null then 1 else 0 end'  
print 'SQL: '+@sql  
declare @xx int=0,@yy nvarchar(max)  
exec sp_executesql @Sql, N'@isvalid int out', @xx out  
select @isvalid=@xx  
print 'sno: '+cast(@sno as nvarchar)+', fieldname: '+@fieldname+', datatypeoriginal: '+@datatypeoriginal +', isvalid: '+cast(@isvalid as nvarchar)  
if @isvalid=0  
GOTO NEXT  
else  
begin  
if @entity='lead'  
begin  
select @sqloldvalue='select @oldvalue='+QUOTENAME(@fieldnameoriginal)+' from mysms.dbo.userleads (nolock) where id= '+cast(@entityid as nvarchar)  
exec sp_executesql @sqloldvalue,N'@oldvalue nvarchar(max) out',@yy out  
select @oldvalue=@yy  
print '@oldvalue: '+@oldvalue+', oldvaluesql: '+@sqloldvalue  
select @sql='update '+QUOTENAME('mysms')+'.dbo.'+QUOTENAME('userleads')+' set '+QUOTENAME(@fieldnameoriginal)+' = '+@fieldvalue +' where id= '+cast(@entityid as nvarchar)  
print '@sql: '+@sql  
  
end  
else if @entity='enquiry'  
begin  
select @sqloldvalue='select @oldvalue='+QUOTENAME(@fieldnameoriginal)+' from mysms.dbo.userenquiry (nolock) where enquiryid= '+cast(@entityid as nvarchar)  
exec sp_executesql @sqloldvalue,N'@oldvalue nvarchar(max) out',@yy out  
select @oldvalue=@yy  
print '@oldvalue: '+@oldvalue+', oldvaluesql: '+@sqloldvalue  
select @sql='update '+QUOTENAME('mysms')+'.dbo.'+QUOTENAME('userenquiry')+' set '+QUOTENAME(@fieldnameoriginal)+' = '+@fieldvalue +' where enquiryid= '+cast(@entityid as nvarchar)  
print '@sql: '+@sql  
  
end  
begin try  
exec sp_executesql @sql  
select @fuid=@entityid  
end try  
begin catch  
exec mysms.dbo.usp_inserterrorinfo  
select @internalerror=ERROR_MESSAGE()  
set @isvalid=0  
GOTO NEXT  
end catch  
end  
end  
else  
begin  
print '2'  
select @fieldid=field_ID from mysms.dbo.customfields with (nolock) where ParentID=@parentid and fieldname=@fieldname and isactive=1  
print 'customfieldid: '+cast(@fieldid as nvarchar)  
if @fieldid is not null  
begin  
select @isvalid=case when @datatype='Numeric' and ISNUMERIC(@fieldvalue)=1 then 1  
when @datatype='DATETIME' and ISdate(@fieldvalue)=1 then 1  
when @datatype='BIGINT' and Try_Cast(@fieldvalue as bigint) is not null then 1  
when @datatype='VARCHAR' and cast(@fieldvalue as varchar)=@fieldvalue then 1  
when @datatype='BIT' and Try_Cast(@fieldvalue as bit) is not null  then 1  
when @datatype='FLOAT' and Try_Cast(@fieldvalue as float) is not null  then 1  
when @datatype='INT' and Try_Cast(@fieldvalue as int) is not null  then 1  
when @datatype='NVARCHAR' and Try_Cast(@fieldvalue as NVARCHAR) is not null  then 1  
else 0 end  
--select @isvalid=dbo.fn_isfieldvaluevalid()  
print 'isvalid: '+cast(@isvalid as nvarchar(10))
if @isvalid=1  
begin  
if @entity='lead'  
begin  
print 'lead custom value update begin' 
if exists (select 1 from mysms.dbo.customfieldLeadvalue with (nolock) where fieldID=@fieldid and LeadID=@entityid)  
begin  

select @oldvalue=cast(Fieldvalue as nvarchar(4000)) from mysms.dbo.customfieldLeadvalue with (nolock) where fieldID=@fieldid and LeadID=@entityid  
print 'Old value exists, oldvalue: '+@oldvalue--+', oldvaluesql: '+@sqloldvalue  
update mysms.dbo.customfieldLeadvalue  set fieldvalue=try_cast(cast(@fieldvalue as nvarchar(4000)) as sql_variant) ,@fuid=recordid where fieldID=@fieldid and LeadID=@entityid  
end  
else  
begin  
--select @entityid,@fieldid,cast(cast(@fieldvalue as nvarchar(4000)) as sql_variant),getdate()  
begin try
print 'lead custom value insert begin'
insert into mysms.dbo.customfieldLeadvalue(LeadID,fieldID,fieldvalue,CreatedDate)  
select @entityid,@fieldid,cast(cast(@fieldvalue as nvarchar(4000)) as sql_variant),getdate() 
select @fuid=SCOPE_IDENTITY()  
select @oldvalue='' from mysms.dbo.customfieldLeadvalue with (nolock) where fieldID=@fieldid and LeadID=@entityid  
print '@oldvalue: '+@oldvalue--+', oldvaluesql: '+@sqloldvalue  
end try
begin catch
exec mysms.dbo.usp_inserterrorinfo
select ERROR_MESSAGE()

end catch
  
end  
  
end  
if @entity='enquiry'  
begin  
print 'Enquiry custom value update begin'
if exists (select 1 from mysms.dbo.customfieldenquiryvalue with (nolock) where fieldID=@fieldid and EnquiryID=@entityid)  
begin  
select @oldvalue=cast(Fieldvalue as nvarchar(4000)) from mysms.dbo.customfieldEnquiryvalue with (nolock) where fieldID=@fieldid and EnquiryID=@entityid  
print 'enquiry custom value update begin, oldvalue: '+@oldvalue+', newvalue: '+cast(@fieldvalue as nvarchar(max))  
 
update mysms.dbo.customfieldenquiryvalue set fieldvalue=try_cast(cast(@fieldvalue as nvarchar(4000)) as sql_variant) ,@fuid=recordid where fieldID=@fieldid and EnquiryID=@entityid  
end  
else  
begin
begin try
print 'enquiry custom value insert begin'
insert into mysms.dbo.customfieldenquiryvalue(EnquiryID,fieldID,fieldvalue)  
select @entityid,@fieldid,cast(cast(@fieldvalue as nvarchar(4000)) as sql_variant)  
select @fuid=SCOPE_IDENTITY()  
select @oldvalue=''--cast(Fieldvalue as nvarchar(4000)) from mysms.dbo.customfieldLeadvalue with (nolock) where fieldID=@fieldid and LeadID=@entityid  
print '@oldvalue: '+@oldvalue--+', oldvaluesql: '+@sqloldvalue  
end try
begin catch
exec mysms.dbo.usp_inserterrorinfo
select ERROR_MESSAGE()
end catch
end  
end  
end  
end  
else  
begin  
--select @isprocessed=1,@processedat=getdate(),@taskstatus=0,@internalerror='Field named '+@fieldnameoriginal+' does not exist'  
update #update set isprocessed=1,tstatus=0,error='Field named '+@fieldnameoriginal+' does not exist' where sno=@sno  
GOTO NEXT  
end  
--end  
end  
insert into mysms.dbo.fieldupdated(FieldName,Oldvalue,NewValue,Tablename,createdon,CreatedBy,fieldid)    
select @fieldnameoriginal,isnull(@oldvalue,'0'),@fieldvalue,    
case when @entity='Enquiry' and @fieldtype<>'predefined' then 'customfieldEnquiryvalue'   
when @entity='Enquiry' and @fieldtype='predefined' then 'Userenquiry'   
when @entity='Lead' and @fieldtype<>'predefined' then 'customfieldleadvalue'   
else 'userleads' end,    
getdate(),@parentid,@fieldid    
select @refid=scope_identity()   
  
end  
NEXT:  
update #update set isprocessed=1,tstatus=case when @isvalid=1 then 1 else 0 end,  
error=case when @fieldtype is null then 'No such field exists' when @isvalid=0 then 'Value supplied is invalid' else null end  
where sno=@sno and error is null  
      
if @fuid is not null    
begin    
select @eventdescription=user_login + ' edited '+mysms.dbo.fn_getentityfullname(@entity,@entityid) +' attribute '+@fieldnameoriginal+' from "'    
+isnull(left(@oldvalue,30),'')+'" to "'+isnull(left(cast(@fieldvalue as nvarchar),30),'')+'"'
from mysms.dbo.user_detail (nolock) where user_id=@parentid 
print @eventdescription
select @eventname=@entity +' details edited'    
exec mysms.dbo.UspSaveEntityActivity_withid @entity,@Entityid,@parentid,@parentid,@eventdescription,@eventname,'fieldupdated',@refid    
end      
  
select @tbp=@tbp-1  
end  
select @isprocessed=1,@taskstatus=case when not exists(select 1 from #update where tstatus=0) then 1 else 0 end,@internalerror=  
case when not exists(select 1 from #update where tstatus=0) then '' else (select * from #update for json AUTO, INCLUDE_NULL_VALUES) end  
select @statusreason=@internalerror
end 
