else if @actiontype in ('removeSegment','addSegment')
begin
declare @segmentid bigint=try_cast(@actiondetails as bigint)
if exists (select 1 from mysms.dbo.tbl_searchcriteria(nolock) where id=@segmentid and criteriatype=@entity)
begin

if @actiontype='addsegment'
begin
if not exists (select 1 from mysms.dbo.tbl_searchcriteria_explicitids(nolock) where criteriaid=@segmentid and Operator='in [A]')
begin
insert into mysms.dbo.tbl_searchcriteria_explicitids(criteriaid,fieldname,fieldtype,Operator,Value)
select @segmentid,case when @entity='lead' then 'id' else 'enquiryid' end,'entity','in [A]','( '+cast(@entityid as nvarchar)+' )'
end
else
begin
update mysms.dbo.tbl_searchcriteria_explicitids set value= replace(value,' )',', '+cast(@entityid as nvarchar)+' )') where criteriaid=@segmentid and  Operator='in [A]'
and value not like '%'+cast(@entityid as nvarchar)+' '+'%'
end
if exists (select 1 from mysms.dbo.tbl_searchcriteria_explicitids(nolock) where criteriaid=@segmentid and Operator='not in [A]' and 
value like '%'+cast(@entityid as nvarchar)+' '+'%')
begin
update mysms.dbo.tbl_searchcriteria_explicitids set value= replace(value,case when charindex(value,', '+cast(@entityid as nvarchar))>0 then ', '+cast(@entityid as nvarchar) when charindex(value,cast(@entityid as nvarchar)+' ,')>0 then cast(@entityid as nvarchar)+' ,' end,'') 
where criteriaid=@segmentid and Operator='not in [A]' and value like '%'+cast(@entityid as nvarchar)+' '+'%'
end

end

if @actiontype='removesegment'
begin
if not exists (select 1 from mysms.dbo.tbl_searchcriteria_explicitids(nolock) where criteriaid=@segmentid and Operator='not in [A]')
begin
insert into mysms.dbo.tbl_searchcriteria_explicitids(criteriaid,fieldname,fieldtype,Operator,Value)
select @segmentid,case when @entity='lead' then 'id' else 'enquiryid' end,'entity','not in [A]','( '+cast(@entityid as nvarchar)+' )'
end
else
begin
update mysms.dbo.tbl_searchcriteria_explicitids set value= replace(value,' )',', '+cast(@entityid as nvarchar)+' )') where criteriaid=@segmentid and Operator='not in [A]' and value not like '%'+cast(@entityid as nvarchar)+' '+'%'
end
if exists (select 1 from mysms.dbo.tbl_searchcriteria_explicitids(nolock) where criteriaid=@segmentid and Operator='in [A]' and value like '%'+cast(@entityid as nvarchar)+' '+'%'
)
begin
update mysms.dbo.tbl_searchcriteria_explicitids set value= replace(value,case when charindex(value,', '+cast(@entityid as nvarchar))>0 then ', '+cast(@entityid as nvarchar) when charindex(value,cast(@entityid as nvarchar)+' ,')>0 then cast(@entityid as nvarchar)+' ,' end,'') 
where criteriaid=@segmentid and Operator='in [A]' and value like '%'+cast(@entityid as nvarchar)+' '+'%'
end

end



select @isprocessed=1,@taskstatus=1,@processedat=getdate()  
end
else
begin
select @error='Segment does not match the entity type'
select @isprocessed=1,@taskstatus=0,@processedat=getdate() ,@internalerror=@error

end
end
else if @actiontype in ('addtolead','addfollowup' )--and @entity='lead'
begin
if @entity='enquiry'
begin
print 'entered add to lead for enquiry'
if not exists
(select 1 from mysms.dbo.userleads_mobile_email with (nolock) where parentid=@parentID AND mobile<>'0' and mobile in (select mobile from mysms.dbo.userenquiry_mobile_email with (nolock) where enquiryid=@entityid)
and 
not exists (select 1 from mysms.dbo.userleads_mobile_email with (nolock) where parentid=@parentID AND email<>'1' and email in (select email from mysms.dbo.userenquiry_mobile_email with (nolock) where enquiryid=@entityid)
)
)
begin
print 'Lead with same mobile/email does not exist, adding lead now'
begin try
begin tran
SET Context_Info 0x55555  
select @leadno=isnull((select max(leadno) from mysms.dbo.userleads with (nolock) where parentid=@parentid),0)+1
Insert into mysms.dbo.userleads (LeadNo, PersonName, MobileNo, EmailID,MobileNo1,MobileNo2,EmailID1,EmailId2, City, State, Country, PinCode, CountryCode, AssignedTo, SourceName, ParentID, mediumname, CampaignName,  InitialRemarks, CreatedOn, CreatedBy, OfficeAddress, ResidentialAddress, enquirysource, LastFollowupCreatedBy, LastFollowupCreatedOn)                                      
select @leadno, Personname, MobileNo, EmailID,MobileNo1,MobileNo2,EmailID1,EmailId2, City, State, Country, PinCode, CountryCode, @parentid, SourceName, ParentID, mediumname, CampaignName,  
       InitialRemarks, getdate(), @parentid, OfficeAddress, ResidentialAddress, 15, @parentid, getdate()                            
     from mysms.dbo.userenquiry with (nolock) where enquiryid=@entityid                
select @leadid=scope_identity()
SET Context_Info 0x  
print concat('New lead added with id: ',@leadid)
commit
     end try  
  begin catch  
      IF @@TRANCOUNT>0                                                                  
             ROLLBACK                                                             
            EXECUTE mysms.dbo.USP_INSERTERRORINFO;
			select @error=error_message()
print concat('Error while adding lead: ',@error)

   end catch      
if isnull(@leadid,0)<>0
begin
begin try
INSERT INTO mysms.dbo.customfieldLeadvalue (leadid,  fieldID, fieldvalue )    
Select  @leadid, fieldid, fieldvalue  from mysms.dbo.customfieldenquiryvalue (NOLOCK) where enquiryid=@entityid  
if not exists(select 1 from mysms.dbo.tbl_MergeLeadsEnquiry(nolock) where EnquiryNo=@entityid and leadno=@leadno)                
 begin                
  insert into  mysms.dbo.tbl_MergeLeadsEnquiry(EnquiryNo ,LeadNo,IsOpen)               
   values (@entityid,@Leadno,0)           
  exec mysms.dbo.usp_ims_UpgradeEnquiryToLead @entityid 
  update mysms.dbo.userenquiry set leadno=@leadno where enquiryid=@entityid
 end      
    
  Exec mysms.dbo.usp_ExecLeadTriggerTasks @leadid  

  select @entityid=@leadid,@entity='lead'
  end try
  begin catch
  exec mysms.dbo.usp_inserterrorinfo
  select @error=error_message()
  end catch
end
end
else
begin
select @error= 'A lead with same mobile/email already exists'
print @error
select @isprocessed=1,@taskstatus=0,@processedat=getdate(),@internalerror=@error
end

end

if (@entity='lead' )
begin
begin try
		print 'lead add followup section'


		declare @isOwner bit = 0, @OwnerId bigint = 0, @Amount decimal(18, 4) = 0, @nextStatusHH int = 0, @flRemarks nvarchar(max), @reAssign bit = 0, @product nvarchar(555), @isReAssign bit = 0, @followUpDetail nvarchar(max), @productDetails nvarchar(max), @productIds nvarchar(500),@followuptype nvarchar(20),@followupname nvarchar(100),
		@nextStatusDate datetime = getdate(), @followUpId bigint = 0, @productType nvarchar(25) = 'existing',@last_ownerid bigint

		select @isOwner = isOwner,  @Amount = amount, @nextStatusHH = nextStatusDate, @OwnerId = OwnerId, @flRemarks = remarks, @isReAssign = reAssign, @productDetails = products, @followUpDetail = followUpDetail, @productType = productType,
		@followuptype = followuptype,@followupname=followupname
		from openjson(@actiondetails) with ( 
			isOwner bit '$.owner.isExisting', 
			OwnerId bigint '$.owner.id',
			followupname nvarchar(100) '$.owner.name',
			followuptype nvarchar(20) '$.owner.type',
			amount decimal(18,4) '$.amount', 
			nextStatusDate int '$.nextStatusDate', 
			remarks nvarchar(max) '$.remarks', 
			reAssign bit '$.reAssign',  
			products nvarchar(max) '$.products' as json, 
			followUpDetail nvarchar(max) '$.followUpDetail.id',
			productType nvarchar(max) '$.productType' 
		)

		declare @existingProduct nvarchar(1000) = ''

		if(@followuptype = 'asperrule')
		begin
			--execute MySMS.dbo.ups_las_ReplicaLeadAssignmentUser	@EntityId, @AsigneeId = @OwnerId output
			--execute MySMS.dbo.ups_las_ReplicaLeadAssignmentUser	@EntityId, @AsigneeId = @OwnerId output
			select @last_ownerid=assignedto from userleads(nolock) where id=@entityid
			execute MySMS.dbo.ups_las_Replica_UpdateLeadAssignmentUser @EntityId, @assignee = @OwnerId output
			
			if @parentid>0 and isnull(@OwnerId,0)=0-- in (50344,26168,30108)
			begin
			if not exists (select 1 from temp_followupfailure_track where taskid=@taskid)
			begin
			insert into temp_followupfailure_track(leadid,last_ownerid,taskid,new_ownerid,parentid)
			select @entityid,@last_ownerid,@taskid,@ownerid,@parentid 
			end
			else
			begin
			update temp_followupfailure_track set force_run_at=getdate() , ownerid_force_run=@ownerid where taskid=@taskid
			end
			if isnull(@OwnerId,0)=0 
			begin
			exec usp_replaceentityplaceholders_allfields_insert @EntityId,@entity
			end
			end
		end
		
		if(@followuptype = 'existing')
		begin
			select @OwnerId = AssignedTo from MySMS.dbo.UserLeads(nolock) where ID = @EntityId
		end

		if(@followuptype = 'custom')
		begin
			select @OwnerId = case when @ownerid =-1 then isnull((select top 1 user_id from user_detail(nolock) where parentid=@parentid 
			and 
			user_login = left(@followupname,len(user_login)) order by len(user_login) desc ),@parentid)
			else @ownerid end

		end

			
		
		select 
			@existingProduct = Products
		from mysms.dbo.UserLeads(nolock) where ID = @entityid
		
		print concat('FU_type:',@followuptype,', ownerid: ',@ownerid)

		if(isnull(@nextStatusHH, '') <> '')
		begin
			select @nextStatusDate = DATEADD(HOUR, try_convert( int, @nextStatusHH), @nextStatusDate)
		end

		if(isnull(@followUpDetail, '') <> '')
		begin
			select @followUpId = [value] from ( select *, ROW_NUMBER() over (partition by (select null) order by (select null)) as [sno]
				from string_split(@followUpDetail, ',')) fl where fl.sno = 1
		end

		if(isnull(@productType, '') = 'existing')
		begin
			select @productIds = @existingProduct
		end

		if(isnull(@productType, '') = 'predefined')
		begin
			set @productIds  = ( select STRING_AGG(productId, '#') from openjson(@productDetails) with (
				productId bigint '$.productId' ))
		end

		if(isnull(@productType, '') = 'custom')
		begin
			declare @eRefId bigint = 0, @eRefTable nvarchar(50) = '', @webHookJson nvarchar(max) = '{}'
			select @eRefId = refids, @eRefTable = reftables
				from mysms.dbo.tbl_LeadEventHistory(nolock) where HistoryId = @activityid

			select @webHookJson = ( case 
				when @eRefTable = 'tbl_ce_EventWebhook'
					then ( select RequestJson from mysms.dbo.tbl_ce_EventWebhook(nolock) where id = @eRefId )
				else  '{}' end )

			declare @productArrayJSON nvarchar(max) = '[]';

			select @productArrayJSON =  productArray from openjson(@webHookJson) 
				with ( productArray nvarchar(max) '$.products' as json )

			declare  @productTable nvarchar(255) = concat('tbl_productmaster_', @ParentID)

			if(exists(select 1 from  mysms.sys.tables where name = @productTable ))
			begin
				
				declare @paramDefination nvarchar(255)  = '@retProductIdsInner nvarchar(500) OUTPUT'  
				declare @getProductSql nvarchar(max) = concat('select @retProductIdsInner = STRING_AGG(p.ProductID, ''#'') from  openjson(N''', replace(@productArrayJSON, '''', ''''''),
					''') a inner join mysms.dbo.', @productTable, '(nolock) p on trim(a.[value]) = trim(p.[Name])')  
				execute sp_executesql @getProductSql, @paramDefination, @retProductIdsInner = @productIds output
			end
			--select @eRefId as [@eRefId], @eRefTable as [@eRefTable], @webHookJson as [@webHookJson], @productArrayJSON as [@productArrayJSON], @productTable as [@productTable]
		end

		set @productIds = ISNULL(@productIds, '')
		set @flRemarks=@flRemarks--+'###'+coalesce(@rulename,@sequencename,'Unknown')
