 @recipients = 'karuna@pelsoftlabs.in', 
 @copy_recipients = 'csshukla@pelsoftlabs.in', 
 @subject = 'Our SMS Campaigns Execution Status', 
 @body = @body, 
 @body_format = 'HTML' 
 
 SELECT 'Success' 
 END TRY 
 
 BEGIN CATCH 
 update CampaignMaster set isrunning=0 where ID=@CampaignID 
 SET @body = 'Error in Executing Campaign : ' + @CampaignName + 
 '<br/>Error message : ' + CAST(ERROR_LINE() AS VARCHAR(50)) + 
 '/' + ERROR_MESSAGE() + 
 '... <br/> It will be retried in 15 mins... Unless Deleted..<br /> Thanks' 
 
 EXEC usp_enqueueemail 
 @profile_name = 'Alerts', 
 @recipients = 'karuna@pelsoftlabs.in', 
 @copy_recipients = 'csshukla@pelsoftlabs.in', 
 @subject = 'Our SMS Campaigns Execution Status', 
 @body = @body, 
 @body_format = 'HTML' 
 END CATCH 
 END 
 ELSE 
 BEGIN 
 update CampaignMaster set isrunning=0 where ID=@CampaignID 
 SET @body = 'Server Offline while executing Campaign Name :' + @CampaignName 
 + 
 '<br/>Time:' + CAST(GETDATE() AS VARCHAR(50)) 
 
 EXEC usp_enqueueemail 
 @profile_name = 'Alerts', 
 @recipients = 'abhishek.makkar@pelsoftlabs.in', 
 @copy_recipients = 'csshukla@pelsoftlabs.in', 
 @blind_copy_recipients = 'karuna@pelsoftlabs.in', 
 @subject = 'Our SMS Campaigns Execution Status', 
 @body = @body, 
 @body_format = 'HTML' 
 
 SELECT 'Success' 
 END 
 
 
 DROP TABLE #TempLinked 
END 





GO

/* ============================================================
   Procedure: [dbo].[usp_ExecuteCampaignMail]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_ExecuteCampaignMail]    
 @CampaignID BIGINT    
AS    
BEGIN    
 DECLARE @CampaignName VARCHAR(50) = (    
             SELECT cm.CampaignName    
             FROM   CampaignMaster AS cm    
             WHERE  cm.ID = @CampaignID    
         )                        
     
 DECLARE @body VARCHAR(150) = ' Executing Campaign Name :' + @CampaignName +    
         '<br/>Time:' + CAST(GETDATE() AS VARCHAR(50))          
     
 DECLARE @IsCRM INT = 0                  
 DECLARE @Iskitever INT = 0                  
     
 CREATE TABLE #TempLinked    
 (    
  Result VARCHAR(50)    
 )                        
     
 IF EXISTS(    
        SELECT 'x'    
        FROM   SearchDetails AS sd    
        WHERE  sd.IsCRMDB = 1    
               AND sd.ID IN (SELECT fs.[value]    
                             FROM   CampaignMaster AS cm    
                                    OUTER APPLY dbo.fn_Split(cm.Applicabilty, '#') AS     
                             fs    
                             WHERE  cm.ID = @CampaignID)    
    )    
 BEGIN    
     SET @IsCRM = 1                  
     INSERT INTO #TempLinked    
     EXEC GetStatusofLinkedServer '172.16.4.30\R2'--'CRM'    
 END                  
     
     
 IF EXISTS(    
        SELECT 'x'    
        FROM   SearchDetails AS sd    
        WHERE  sd.IsKitever = 1    
               AND sd.ID IN (SELECT fs.[value]    
                             FROM   CampaignMaster AS cm    
                                    OUTER APPLY dbo.fn_Split(cm.Applicabilty, '#') AS     
                             fs    
                             WHERE  cm.ID = @CampaignID)    
    )    
 BEGIN    
     SET @ISkitever = 1                  
     INSERT INTO #TempLinked    
     EXEC GetStatusofLinkedServer     
          '103.25.130.241,2499'    
 END                     
     
 IF EXISTS(    
        SELECT 'x'    
        FROM   SearchDetails AS sd    
        WHERE  sd.IsCRMDB = 1    
               AND sd.ID IN (SELECT fs.[value]    
                             FROM   CampaignMaster AS cm    
                                    OUTER APPLY dbo.fn_Split(cm.Exclusions, '#') AS     
                             fs    
                             WHERE  cm.ID = @CampaignID)    
    )    
 BEGIN    
     SET @IsCRM = 1                  
     INSERT INTO #TempLinked    
     EXEC GetStatusofLinkedServer '172.16.4.30\R2'--'CRM'    
 END                  
     
     
 IF EXISTS(    
        SELECT 'x'    
        FROM   SearchDetails AS sd    
        WHERE  sd.IsKitever = 1    
               AND sd.ID IN (SELECT fs.[value]    
                             FROM   CampaignMaster AS cm    
                                    OUTER APPLY dbo.fn_Split(cm.Exclusions, '#') AS     
                             fs    
                             WHERE  cm.ID = @CampaignID)    
    )    
 BEGIN    
     SET @ISkitever = 1                  
     INSERT INTO #TempLinked    
     EXEC GetStatusofLinkedServer     
          '103.25.130.241,2499'    
 END                       
     
 IF NOT EXISTS(    
        SELECT 'x'    
        FROM   #TempLinked    
    )    
 BEGIN    
     DECLARE @Error VARCHAR(500)         
         
     BEGIN TRY    
      --EXEC msdb.dbo.sp_send_dbmail    
      --     @profile_name = 'Alerts',    
      --     @recipients = 'animesh.shukla@pelsoftlabs.in',    
      --     @copy_recipients = 'csshukla@pelsoftlabs.in',    
      --     @blind_copy_recipients = 'karuna@pelsoftlabs.in',    
      --     @subject = 'Campaign Execution Status',    
      --     @body = @body,    
      --     @body_format = 'HTML'                  
          
          
      DECLARE @Applicability      VARCHAR(1050),    
              @Excluded           VARCHAR(1050),    
              @ExcludedNumber     VARCHAR(1050),    
              @IncludedMobile     VARCHAR(1050),    
              @Subject            VARCHAR(200),    
              @ReplyTo            VARCHAR(200),    
              @MailContent        VARCHAR(MAX),    
              @User_Filter        VARCHAR(50),    
        @UserID             BIGINT,    
              @SmppID             INT,    
              @ISTrack            BIT,    
              @ISUnsubscribe      BIT,    
              @balanceMails       BIGINT                  
          
      SELECT @Applicability = cm.Applicabilty,    
             @includedMobile     = cm.InclusionsNumber,    
             @Excluded           = cm.Exclusions,    
             @ExcludedNumber     = cm.ExclusionsNumber,    
             @Subject            = cm.MailSubject,    
             @MailContent        = cm.MailContent,    
             @ReplyTo            = cm.MailReplyTo,    
             @UserID             = cm.Accounts,    
             @ISTrack            = CASE     
                             WHEN cm.TrackResponse     
                                  <> '' THEN 1    
                             ELSE 0    
                        END,    
             @ISUnsubscribe      = CASE     
                                   WHEN cm.UnsubscribePage     
                                        <> '' THEN 1    
                                   ELSE 0    
                              END    
      FROM   CampaignMaster AS cm    
      WHERE  cm.ID = @CampaignID                        
          
      SET @balanceMails = (    
              SELECT TOP 1 mcd.Mail_Balance    
              FROM   PelConnectDB.dbo.Mail_CreditDetails AS mcd    
              WHERE  mcd.Mail_UserID = @UserID    
              ORDER BY    
                     mcd.Mail_Date DESC    
          )    
          
          
      SELECT @User_Filter = ud.userfilter,    
             @SmppID = ud.SmppID    
      FROM   User_Detail AS ud    
      WHERE  ud.[User_ID] = @UserID                        
          
      CREATE TABLE #TempMobileNo    
      (    
       Emails VARCHAR(100)    
      )                       
      CREATE TABLE #TempMobileNoExclude    
      (    
       Emails VARCHAR(100)    
      )                            
      CREATE TABLE #TempSearchIDApplicability    
      (    
       SearchID INT    
      )                            
      CREATE TABLE #TempSearchIDExcluded    
      (    
       SearchID INT    
      )                            
      DECLARE @CountApplicability     INT = (    
                  SELECT COUNT(*)    
                  FROM   dbo.fn_Split(@Applicability, '#') AS fs    
              )                            
          
      DECLARE @CountExcluded          INT = (    
                  SELECT COUNT(*)    
                  FROM   dbo.fn_Split(@Excluded, '#') AS fs    
              )                            
          
      DECLARE @Count INT = 0                            
      IF (@CountExcluded > @CountApplicability)    
      BEGIN    
          SET @Count = @CountExcluded    
      END    
      ELSE    
      BEGIN    
          SET @Count = @CountApplicability    
      END                            
      INSERT #TempSearchIDApplicability    
      SELECT fs.[value]    
      FROM   dbo.fn_Split(@Applicability, '#') AS fs                        
          
      INSERT #TempSearchIDExcluded    
      SELECT fs.[value]    
      FROM   dbo.fn_Split(@Excluded, '#') AS fs                            
          
          
      WHILE (@Count > 0)    
      BEGIN    
          DECLARE @Applicability1     BIGINT = (    
                      SELECT TOP 1 *    
                      FROM   #TempSearchIDApplicability    
                  )                        
              
          DECLARE @Excluded1          BIGINT = (    
                      SELECT TOP 1 *    
                      FROM   #TempSearchIDExcluded    
                  )                            
              
          DELETE     
          FROM   #TempSearchIDApplicability    
          WHERE  SearchID = @Applicability1                        
              
          DELETE     
          FROM   #TempSearchIDExcluded    
          WHERE  SearchID = @Excluded1     
              
          ----------------CRM PreEnquiry                             
          CREATE TABLE #TempCRMPreenquiry    
          (    
           EnqNo             VARCHAR(150) NULL,    
           EnqDate           VARCHAR(150) NULL,    
           NAME              VARCHAR(150) NULL,    
           Mobileno          FLOAT NULL,    
           R_Address         VARCHAR(150) NULL,    
           O_Address         VARCHAR(150) NULL,    
           Executive         VARCHAR(150) NULL,    
           ServiceName       VARCHAR(150) NULL,    
           STATUS            VARCHAR(150) NULL,    
           VisitStatus       VARCHAR(150) NULL,    
           MeetingStatus     VARCHAR(150) NULL,    
           Mobileno2         FLOAT NULL,    
           Mobileno3         FLOAT NULL,    
           EMail             VARCHAR(150) NULL,    
           Email2            VARCHAR(150) NULL,    
           Email3            VARCHAR(150) NULL,    
           company_name      VARCHAR(150) NULL    
          )     
              
          --IF @IsCRM = 1    
          --BEGIN    
          --    IF ISNULL(@Applicability1, 0) <> 0    
          --    BEGIN    
          --        INSERT INTO #TempCRMPreenquiry    
          --        EXEC usp_GetPreEnquiryExecute    
          -- @Applicability1,    
          --             '',    
          --             0    
          --    END    
          --END                   
              
              
          CREATE TABLE #TempCRMPreenquiryExc    
          (    
           EnqNo             VARCHAR(150) NULL,    
           EnqDate           VARCHAR(150) NULL,    
           NAME              VARCHAR(150) NULL,    
           Mobileno          FLOAT NULL,    
           R_Address         VARCHAR(150) NULL,    
           O_Address         VARCHAR(150) NULL,    
           Executive         VARCHAR(150) NULL,    
           ServiceName       VARCHAR(150) NULL,    
           STATUS            VARCHAR(150) NULL,    
           VisitStatus       VARCHAR(150) NULL,    
           MeetingStatus     VARCHAR(150) NULL,    
           Mobileno2         FLOAT NULL,    
           Mobileno3         FLOAT NULL,    
           EMail             VARCHAR(150) NULL,    
           Email2            VARCHAR(150) NULL,    
           Email3            VARCHAR(150) NULL,    
           company_name      VARCHAR(150) NULL    
          )                              
              
              
              
          IF @IsCRM = 1    
          BEGIN    
              EXEC usp_GetPreEnquiryExecuteExecuteCampaign @Applicability1                  
              EXEC usp_GetPreEnquiryExecuteExecuteCampaign @Excluded1                 
                  
              INSERT INTO #TempMobileNo    
              SELECT DISTINCT A.Emails    
              FROM   (    
                         SELECT Emails    
                         FROM   dbo.funcGetCampaignSearchCRMUsersMails(@Applicability1)     
                         --UNION ALL    
                         --SELECT mobileno    
                         --FROM   dbo.funcGetCampaignSearchCRMUnsubscribe(@Applicability1)       
                         UNION ALL                             
                             
                         SELECT ISNULL(NULLIF(msd.EMail, ''), 0)    
                         FROM   CRMDB.dbo.MYSMSSearchDetails     
                                msd    
                         WHERE  msd.SearchID = @Applicability1     
                             
                         UNION ALL                 
                         SELECT ISNULL(NULLIF(msd.Email2, ''), 0)    
                         FROM   CRMDB.dbo.MYSMSSearchDetails     
                                msd    
                         WHERE  msd.SearchID = @Applicability1     
                             
                         UNION ALL                 
                         SELECT ISNULL(NULLIF(msd.Email3, ''), 0)    
                         FROM   CRMDB.dbo.MYSMSSearchDetails     
                                msd    
                         WHERE  msd.SearchID = @Applicability1    
                     ) A        
                  
              INSERT INTO #TempMobileNoExclude    
              SELECT DISTINCT A.Emails    
              FROM   (    
                         SELECT Emails    
                         FROM   dbo.funcGetCampaignSearchCRMUsersMails(@Excluded1)     
                         --UNION ALL    
                         --SELECT mobileno    
                         --FROM   dbo.funcGetCampaignSearchCRMUnsubscribe(@Applicability1)       
                         UNION ALL                             
                             
                         SELECT ISNULL(NULLIF(msd.EMail, ''), 0)    
                         FROM   CRMDB.dbo.MYSMSSearchDetails     
                                msd    
                         WHERE  msd.SearchID = @Excluded1     
                             
                         UNION ALL                 
                         SELECT ISNULL(NULLIF(msd.Email2, ''), 0)    
                         FROM   CRMDB.dbo.MYSMSSearchDetails     
                                msd    
                         WHERE  msd.SearchID = @Excluded1     
                             
                         UNION ALL                 
                         SELECT ISNULL(NULLIF(msd.Email3, ''), 0)    
                         FROM   CRMDB.dbo.MYSMSSearchDetails     
                                msd    
                         WHERE  msd.SearchID = @Excluded1    
                     ) A    
