          Mail_Priority,    
          Mail_ScheduleDate,    
          Mail_TempleteBody    
        )    
      SELECT NEWID(),    
             'contactus@mail22.in',    
             tt.Emails,    
             @Subject,    
             @@identity,    
             GETDATE(),    
             @UserID,    
             @replyTo,    
             @batcHID,    
           1,    
             GETDATE(),    
             @mailContent    
      FROM   #TempMobileNoFinal tt    
          
      DECLARE @Mail_Debit BIGINT = (    
                  SELECT COUNT(*)    
                  FROM   #TempMobileNoFinal    
              )    
          
      INSERT INTO PelConnectDB.dbo.Mail_CreditDetails    
        (    
          -- Mail_CreditSrID -- this column value is auto-generated    
          Mail_UserID,    
          Mail_FromID,    
          Mail_Debit,    
          Mail_Balance,    
          Mail_Date    
        )    
      VALUES    
        (    
          29,    
          @UserID,    
          @Mail_Debit,    
          @balanceMails -@Mail_Debit,    
          GETDATE()    
        )    
          
          
          
          
      UPDATE CampaignMaster    
      SET    IsExecuted = 1,    
             ExecuteTime = GETDATE(),    
             NoOfRecipients = (    
                 SELECT COUNT(A.mobileno)    
                 FROM   (    
                            SELECT DISTINCT tt.mobileno    
                            FROM   #TempMobileNoFinal tt    
                            WHERE  tt.mobileno NOT IN (SELECT td.mobileno    
                                                       FROM       
                                                              #TempMobileNoFinalExc     
                                                              td)    
                        ) A    
             )    
      WHERE  ID = @CampaignID                   
          
      IF @ISTrack = 1    
      BEGIN    
          INSERT INTO SearchDetails    
            (    
              SearchName,    
              IsList,    
              CampaignID,    
              IsTrackUnsubscribe,    
              CreatedDate    
            )    
          VALUES    
            (    
              'Result -' + @CampaignName,    
              1,    
              @CampaignID,    
              1,    
              GETDATE()    
            )    
      END                    
          
      IF @ISUnsubscribe = 1    
      BEGIN    
          INSERT INTO SearchDetails    
            (    
              SearchName,    
              IsList,    
              CampaignID,    
              IsTrackUnsubscribe,    
              CreatedDate    
            )    
          VALUES    
            (    
              'Unsubscribe -' + @CampaignName,    
              1,    
              @CampaignID,    
              0,    
              GETDATE()    
            )    
      END     
          
      DROP TABLE #TempSearchIDApplicability     
      DROP TABLE #TempSearchIDExcluded     
      DROP TABLE #TempMobileNo     
          
          
      DROP TABLE #TempMobileNoExclude     
      DROP TABLE #TempMobileNoFinal     
      DROP TABLE #TempMobileNoFinalExc                         
          
          
          
      SET @body = (    
              'Campaign Name :' + @CampaignName +    
              ' Executed Successfully' +    
              '<br/>Time:' + CAST(GETDATE() AS VARCHAR(50))    
          )     
          
      --EXEC msdb.dbo.sp_send_dbmail    
      --     @profile_name = 'Alerts',    
      --     @recipients = 'animesh.shukla@pelsoftlabs.in',    
      --     @copy_recipients = 'csshukla@pelsoftlabs.in',    
      --     @blind_copy_recipients = 'karuna@pelsoftlabs.in',    
      --     @subject = 'Campaign Execution Status',    
      --     @body = @body,    
      --     @body_format = 'HTML'                        
          
      SELECT 'Success'    
     END TRY          
         
     BEGIN CATCH    
      SET @Error = 'Error in Executing Campaign :  ' + @CampaignName +    
          '<br/>Error message :  ' + CAST(ERROR_LINE() AS VARCHAR(50)) +    
          '/' + ERROR_MESSAGE() +    
          '... <br/> It will be retried in 15 mins... Unless Deleted..<br /> Thanks'                
          
      SELECT @Error     
             --EXEC msdb.dbo.sp_send_dbmail    
             --     @profile_name = 'Credit',    
             --     @recipients = 'animesh.shukla@pelsoftlabs.in',    
             --     @copy_recipients = 'csshukla@pelsoftlabs.in',    
             --     @blind_copy_recipients = 'karuna@pelsoftlabs.in',    
             --     @subject = 'Campaign Execution Status',    
             --     @body = @body,    
             --     @body_format = 'HTML'    
     END CATCH    
 END    
 ELSE    
 BEGIN    
     SET @body = 'Server Offline while executing Campaign Name :' + @CampaignName     
         +    
         '<br/>Time:' + CAST(GETDATE() AS VARCHAR(50))     
             
         --EXEC msdb.dbo.sp_send_dbmail    
         --     @profile_name = 'Alerts',    
         --     @recipients = 'animesh.shukla@pelsoftlabs.in',    
         --     @copy_recipients = 'csshukla@pelsoftlabs.in',    
         --     @blind_copy_recipients = 'karuna@pelsoftlabs.in',    
         --     @subject = 'Campaign Execution Status',    
         --     @body = @body,    
         --     @body_format = 'HTML'    
 END     
     
     
 DROP TABLE #TempLinked    
END   


GO

/* ============================================================
   Procedure: [dbo].[usp_ExecuteCampaignMailCorrected]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_ExecuteCampaignMailCorrected] --615--612 --366         
 @CampaignID BIGINT          
AS          
BEGIN          
 DECLARE @CampaignName VARCHAR(50) = (          
             SELECT cm.CampaignName          
             FROM   CampaignMaster AS cm          
             WHERE  cm.ID = @CampaignID          
         )                              
 update CampaignMaster set isrunning=1 where ID=@CampaignID            
 DECLARE @body VARCHAR(150) = ' Executing Campaign Name :' + @CampaignName +          
         '<br/>Time:' + CAST(GETDATE() AS VARCHAR(50))                
           
 DECLARE @IsCRM INT = 0                        
 DECLARE @Iskitever INT = 0                        
           
 CREATE TABLE #TempLinked          
 (          
  Result VARCHAR(50)          
 )                              
           
 IF EXISTS(          
        SELECT 'x'          
        FROM   SearchDetails AS sd          
        WHERE  sd.IsCRMDB = 1          
               AND sd.ID IN (SELECT fs.[value]          
                             FROM   CampaignMaster AS cm          
                                    OUTER APPLY dbo.fn_Split(cm.Applicabilty, '#') AS           
                             fs          
                             WHERE  cm.ID = @CampaignID)          
    )          
 BEGIN          
     SET @IsCRM = 1                        
     INSERT INTO #TempLinked          
     EXEC GetStatusofLinkedServer 'CRM'          
 END                        
           
           
 IF EXISTS(          
        SELECT 'x'          
        FROM   SearchDetails AS sd          
        WHERE  sd.IsKitever = 1          
               AND sd.ID IN (SELECT fs.[value]          
                             FROM   CampaignMaster AS cm          
                                    OUTER APPLY dbo.fn_Split(cm.Applicabilty, '#') AS           
                             fs          
                             WHERE  cm.ID = @CampaignID)          
    )          
 BEGIN          
     SET @ISkitever = 1                        
     INSERT INTO #TempLinked          
     EXEC GetStatusofLinkedServer           
          '103.25.130.241,2499'          
 END                           
           
 IF EXISTS(          
        SELECT 'x'          
        FROM   SearchDetails AS sd          
        WHERE  sd.IsCRMDB = 1          
               AND sd.ID IN (SELECT fs.[value]          
                             FROM   CampaignMaster AS cm          
                                    OUTER APPLY dbo.fn_Split(cm.Exclusions, '#') AS           
                             fs          
                             WHERE  cm.ID = @CampaignID)          
    )          
 BEGIN          
     SET @IsCRM = 1                        
     INSERT INTO #TempLinked          
     EXEC GetStatusofLinkedServer 'CRM'          
 END                        
           
           
 IF EXISTS(          
        SELECT 'x'          
        FROM   SearchDetails AS sd          
        WHERE  sd.IsKitever = 1          
               AND sd.ID IN (SELECT fs.[value]          
                             FROM   CampaignMaster AS cm          
                                    OUTER APPLY dbo.fn_Split(cm.Exclusions, '#') AS           
                             fs          
                             WHERE  cm.ID = @CampaignID)          
    )          
 BEGIN          
     SET @ISkitever = 1                        
     INSERT INTO #TempLinked          
     EXEC GetStatusofLinkedServer           
          '103.25.130.241,2499'          
 END                             
           
 IF NOT EXISTS(          
        SELECT 'x'          
        FROM   #TempLinked          
    )          
 BEGIN   
              
     DECLARE @Error VARCHAR(500)               
               
     BEGIN TRY          
      EXEC usp_enqueueemail          
           @profile_name = 'Alerts',          
           @recipients = 'animesh.shukla@pelsoftlabs.in',          
           @copy_recipients = 'csshukla@pelsoftlabs.in',          
           @blind_copy_recipients = 'karuna@pelsoftlabs.in',          
           @subject = 'Our Mail Campaign Execution Status',          
           @body = @body,          
           @body_format = 'HTML'                        
                
                
      DECLARE @Applicability      VARCHAR(1050),          
              @Excluded           VARCHAR(1050),          
              @ExcludedNumber     VARCHAR(1050),          
              @IncludedMobile     VARCHAR(1050),          
              @Subject            VARCHAR(200),          
              @ReplyTo            VARCHAR(200),          
              @MailContent        VARCHAR(MAX),          
              @User_Filter        VARCHAR(50),          
              @UserID       BIGINT,          
              @SmppID             INT,          
              @ISTrack            BIT,          
              @ISUnsubscribe      BIT,          
              @balanceMails       BIGINT                        
                
      SELECT @Applicability = cm.Applicabilty,          
             @includedMobile     = cm.InclusionsNumber,          
             @Excluded           = cm.Exclusions,          
             @ExcludedNumber     = cm.ExclusionsNumber,          
             @Subject            = cm.MailSubject,          
             @MailContent        = cm.MailContent,          
             @ReplyTo            = cm.MailReplyTo,          
             @UserID             = cm.Accounts,          
             @ISTrack            = CASE           
                             WHEN cm.TrackResponse           
                                  <> '' THEN 1          
                             ELSE 0          
                        END,          
             @ISUnsubscribe      = CASE           
                                   WHEN cm.UnsubscribePage           
                                        <> '' THEN 1          
                                   ELSE 0          
                              END          
      FROM   CampaignMaster AS cm          
      WHERE  cm.ID = @CampaignID                              
                
                
                
                
      SELECT @User_Filter = ud.userfilter,          
             @SmppID = ud.SmppID          
      FROM   User_Detail AS ud          
      WHERE  ud.[User_ID] = @UserID                              
                
      CREATE TABLE #TempMobileNo          
      (          
       Emails VARCHAR(100) collate SQL_Latin1_General_CP1_CI_AS         
      )                             
      CREATE TABLE #TempMobileNoExclude          
      (          
       Emails VARCHAR(100)  collate SQL_Latin1_General_CP1_CI_AS           
      )                                  
      CREATE TABLE #TempSearchIDApplicability          
      (          
       SearchID INT          
      )                                  
      CREATE TABLE #TempSearchIDExcluded          
      (          
       SearchID INT          
      )                                  
      DECLARE @CountApplicability     INT = (          
                  SELECT COUNT(*)          
                  FROM   dbo.fn_Split(@Applicability, '#') AS fs          
              )                                  
                
      DECLARE @CountExcluded          INT = (          
                  SELECT COUNT(*)          
                  FROM   dbo.fn_Split(@Excluded, '#') AS fs          
              )                                  
                
      DECLARE @Count INT = 0                                  
      IF (@CountExcluded > @CountApplicability)          
      BEGIN          
          SET @Count = @CountExcluded          
      END          
      ELSE          
      BEGIN          
          SET @Count = @CountApplicability          
      END                                  
      INSERT #TempSearchIDApplicability          
      SELECT fs.[value]          
      FROM   dbo.fn_Split(@Applicability, '#') AS fs                              
            
      INSERT #TempSearchIDExcluded          
      SELECT fs.[value]          
      FROM   dbo.fn_Split(@Excluded, '#') AS fs                                  
                
                
      WHILE (@Count > 0)          
      BEGIN          
          DECLARE @Applicability1     BIGINT = (          
                      SELECT TOP 1 *          
                      FROM   #TempSearchIDApplicability          
                  )      
                    
          DECLARE @Excluded1          BIGINT = (          
                      SELECT TOP 1 *          
                      FROM   #TempSearchIDExcluded          
                  )                                  
                    
          DELETE           
          FROM   #TempSearchIDApplicability          
          WHERE  SearchID = @Applicability1                              
                    
          DELETE           
          FROM   #TempSearchIDExcluded          
          WHERE  SearchID = @Excluded1           
                    
          ----------------CRM PreEnquiry                                   
          CREATE TABLE #TempCRMPreenquiry          
          (          
           EnqNo             VARCHAR(150) NULL,          
           EnqDate           VARCHAR(150) NULL,          
           NAME              VARCHAR(150) NULL,          
           Mobileno          FLOAT NULL,          
           R_Address         VARCHAR(150) NULL,          
           O_Address         VARCHAR(150) NULL,          
           Executive         VARCHAR(150) NULL,          
           ServiceName       VARCHAR(150) NULL,          
           STATUS            VARCHAR(150) NULL,          
           VisitStatus       VARCHAR(150) NULL,          
           MeetingStatus     VARCHAR(150) NULL,          
           Mobileno2         FLOAT NULL,          
           Mobileno3         FLOAT NULL,          
           EMail             VARCHAR(150) NULL,          
           Email2            VARCHAR(150) NULL,          
           Email3            VARCHAR(150) NULL,          
           company_name      VARCHAR(150) NULL          
          )           
                    
          --IF @IsCRM = 1          
          --BEGIN          
          --    IF ISNULL(@Applicability1, 0) <> 0          
          --    BEGIN          
          --        INSERT INTO #TempCRMPreenquiry          
          --        EXEC usp_GetPreEnquiryExecute          
          -- @Applicability1,          
          --             '',          
          --             0          
          --    END          
          --END                         
                    
                    
          CREATE TABLE #TempCRMPreenquiryExc          
          (          
           EnqNo             VARCHAR(150) NULL,          
           EnqDate           VARCHAR(150) NULL,          
           NAME              VARCHAR(150) NULL,          
           Mobileno          FLOAT NULL,          
           R_Address         VARCHAR(150) NULL,          
           O_Address         VARCHAR(150) NULL,          
           Executive         VARCHAR(150) NULL,          
           ServiceName       VARCHAR(150) NULL,          
           STATUS            VARCHAR(150) NULL,          
           VisitStatus       VARCHAR(150) NULL,          
           MeetingStatus     VARCHAR(150) NULL,          
           Mobileno2         FLOAT NULL,          
           Mobileno3         FLOAT NULL,          
           EMail             VARCHAR(150) NULL,          
           Email2            VARCHAR(150) NULL,          
           Email3            VARCHAR(150) NULL,          
           company_name      VARCHAR(150) NULL          
          )                                    
                    
                    
                    
          IF @IsCRM = 1          
          BEGIN          
              EXEC usp_GetPreEnquiryExecuteExecuteCampaign @Applicability1                        
              EXEC usp_GetPreEnquiryExecuteExecuteCampaign @Excluded1                       
                        
              INSERT INTO #TempMobileNo          
              SELECT DISTINCT A.Emails          
              FROM   (          
                         SELECT Emails          
                         FROM   dbo.funcGetCampaignSearchCRMUsersMails(@Applicability1)           
                         --UNION ALL          
                         --SELECT mobileno          
                         --FROM   dbo.funcGetCampaignSearchCRMUnsubscribe(@Applicability1)             
                         UNION ALL                                   
                
                         SELECT ISNULL(NULLIF(msd.EMail, ''), 0)          
                         FROM   CRM.CRMDB.dbo.MYSMSSearchDetails           
                                msd          
                         WHERE  msd.SearchID = @Applicability1           
                                   
                         UNION ALL                       
                         SELECT ISNULL(NULLIF(msd.Email2, ''), 0)          
                         FROM   CRM.CRMDB.dbo.MYSMSSearchDetails           
                                msd          
                         WHERE  msd.SearchID = @Applicability1           
                                   
                         UNION ALL                       
                         SELECT ISNULL(NULLIF(msd.Email3, ''), 0)          
                         FROM   CRM.CRMDB.dbo.MYSMSSearchDetails           
                                msd          
                         WHERE  msd.SearchID = @Applicability1          
                     ) A                      
                        
              INSERT INTO #TempMobileNoExclude          
              SELECT DISTINCT A.Emails          
              FROM   (          
                         SELECT Emails          
      FROM   dbo.funcGetCampaignSearchCRMUsersMails(@Excluded1)           
                         --UNION ALL          
                         --SELECT mobileno          
                         --FROM   dbo.funcGetCampaignSearchCRMUnsubscribe(@Applicability1)             
                         UNION ALL                                   
                                
                                  
                         SELECT ISNULL(NULLIF(msd.EMail, ''), 0)          
                         FROM   CRM.CRMDB.dbo.MYSMSSearchDetails           
                                msd          
                         WHERE  msd.SearchID = @Excluded1           
                                   
                         UNION ALL                       
                         SELECT ISNULL(NULLIF(msd.Email2, ''), 0)          
                         FROM   CRM.CRMDB.dbo.MYSMSSearchDetails           
                                msd          
                         WHERE  msd.SearchID = @Excluded1           
                                   
                         UNION ALL                       
                         SELECT ISNULL(NULLIF(msd.Email3, ''), 0)          
                         FROM   CRM.CRMDB.dbo.MYSMSSearchDetails           
                                msd          
                         WHERE  msd.SearchID = @Excluded1          
                     ) A          
          END           
          ----------------CRM PreEnquiry END                                     
                    
          ----------------Kitever Users                                    
          CREATE TABLE #TempKiteverUsers          
          (          
           fname                VARCHAR(200) NULL,          
           Mobileno             VARCHAR(200) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,          
           CompnayName          VARCHAR(200) NULL,          
           EMail                VARCHAR(200) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,          
           state_name           VARCHAR(200) NULL,          
           city_name            VARCHAR(200) NULL,          
           DateCreated          VARCHAR(200) NULL,          
           LoginType            VARCHAR(200) NULL,          
           Merchant_Code        VARCHAR(200) NULL,          
           lastLoginDate        VARCHAR(200) NULL,          
           Balance              VARCHAR(200) NULL,          
           Consumption          VARCHAR(200) NULL,          
           SMSConsumption       VARCHAR(200) NULL,          
           MailConsumption      VARCHAR(200) NULL,          
           TimeonAppInMin       VARCHAR(200) NULL,          
           mCRMConfigured       VARCHAR(200) NULL,          
           OrdersCount          VARCHAR(200) NULL,          
           OrdersAmount         VARCHAR(200) NULL,          
           Micrositecreated     VARCHAR(200) NULL,          
           MicrositeEdited      VARCHAR(200) NULL,          
           VisitsCount          VARCHAR(200) NULL,          
           Leadscount           VARCHAR(200) NULL,          
           TopupAmount          VARCHAR(200) NULL,          
           Ismerchant           VARCHAR(200) NULL,          
           Usercategory         VARCHAR(200) NULL,          
           UserType             VARCHAR(200) NULL          
          )                                    
                    
          IF @iskitever = 1          
          BEGIN          
              IF ISNULL(@Applicability1, 0) <> 0          
              BEGIN          
                  INSERT INTO #TempKiteverUsers          
                  EXEC Usp_KiteverUserSearh           
                       @Applicability1          
              END          
          END                         
                    
          CREATE TABLE #TempKiteverUsersExc          
          (          
           fname                VARCHAR(200) NULL,          
           Mobileno             VARCHAR(200) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,          
           CompnayName          VARCHAR(200) NULL,          
           EMail                VARCHAR(200) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,          
           state_name           VARCHAR(200) NULL,          
           city_name            VARCHAR(200) NULL,          
           DateCreated          VARCHAR(200) NULL,          
           LoginType            VARCHAR(200) NULL,          
           Merchant_Code        VARCHAR(200) NULL,          
           lastLoginDate        VARCHAR(200) NULL,          
           Balance              VARCHAR(200) NULL,          
           Consumption          VARCHAR(200) NULL,          
           SMSConsumption       VARCHAR(200) NULL,          
           MailConsumption      VARCHAR(200) NULL,          
           TimeonAppInMin       VARCHAR(200) NULL,          
           mCRMConfigured       VARCHAR(200) NULL,          
           OrdersCount          VARCHAR(200) NULL,          
           OrdersAmount         VARCHAR(200) NULL,          
           Micrositecreated     VARCHAR(200) NULL,          
           MicrositeEdited      VARCHAR(200) NULL,          
           VisitsCount          VARCHAR(200) NULL,          
           Leadscount           VARCHAR(200) NULL,          
           TopupAmount          VARCHAR(200) NULL,          
           Ismerchant           VARCHAR(200) NULL,          
           Usercategory         VARCHAR(200) NULL,          
           UserType             VARCHAR(200) NULL          
          )                                    
                    
          IF @iskitever = 1          
          BEGIN          
              IF ISNULL(@Excluded1, 0) <> 0          
              BEGIN          
                  INSERT INTO #TempKiteverUsersExc          
                  EXEC Usp_KiteverUserSearh           
                       @Excluded1          
              END                         
                        
              INSERT INTO #TempMobileNo          
              SELECT DISTINCT     Email          
              FROM   (          
                         SELECT Email          
                         FROM   dbo.funcGetCampaignSearchKiteverLeadsMails(@Applicability1)           
                                   
                         UNION                                   
                         SELECT EMail          
                         FROM   #TempKiteverUsers          
                     )            A                      
                        
              INSERT INTO #TempMobileNoExclude          
              SELECT DISTINCT     Email          
              FROM   (          
                         SELECT Email          
                         FROM   dbo.funcGetCampaignSearchKiteverLeadsMails(@Excluded1)           
                                   
                         UNION                                   
                         SELECT EMail          
                         FROM   #TempKiteverUsersExc          
                     )            A          
          END           
       ----------------Kitever Users END          
          ----------------Kit19 Users END                             
          CREATE TABLE #TempKit19UsersExc          
          (          
           [User_ID]      VARCHAR(200) NULL,          
           User_Login     VARCHAR(200) NULL,          
           FName          VARCHAR(200) NULL,          
           LName          VARCHAR(200) NULL,          
           EMail          VARCHAR(200) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,          
           Mobile         VARCHAR(200) COLLATE SQL_Latin1_General_CP1_CI_AS           
           NULL,          
           Country        VARCHAR(200) NULL,          
           [State]        VARCHAR(200) NULL,          
           City           VARCHAR(200) NULL,          
           userfilter     VARCHAR(200) NULL          
          )                             
          CREATE TABLE #TempKit19UsersApp          
          (          
           [User_ID]      VARCHAR(200) NULL,          
           User_Login     VARCHAR(200) NULL,          
           FName          VARCHAR(200) NULL,          
           LName          VARCHAR(200) NULL,          
           EMail          VARCHAR(200) collate SQL_Latin1_General_CP1_CI_AS Null,          
           Mobile         VARCHAR(200) COLLATE SQL_Latin1_General_CP1_CI_AS           
           NULL,          
           Country        VARCHAR(200) NULL,          
           [State]        VARCHAR(200) NULL,          
           City           VARCHAR(200) NULL,          
           userfilter     VARCHAR(200) NULL          
          )                            
          IF ISNULL(@Excluded1, 0) <> 0          
          BEGIN          
              INSERT INTO #TempKit19UsersExc          
              EXEC usp_GetExecutedKit19Users           
                   @Excluded1          
          END                        
                    
                    
          IF ISNULL(@Applicability1, '') <> ''          
          BEGIN          
              INSERT INTO #TempKit19UsersApp          
              EXEC usp_GetExecutedKit19Users           
                   @Applicability1          
          END           
          ----------------Kit19 Users END                                     
                    
                    
          INSERT INTO #TempMobileNo          
          SELECT DISTINCT     Email          
          FROM   (          
                     --SELECT DISTINCT fs.[value] AS mobileno          
                     --FROM   dbo.fn_Split(@IncludedMobile, ',') AS fs          
                     --UNION                      
                     SELECT Email          
                     FROM   dbo.funcGetCampaignSearchKit19LeadsMails(@Applicability1)           
                     UNION ALL                               
                     SELECT EMail          
                     FROM   #TempKit19UsersApp          
                 )            A                      
                 
          INSERT INTO #TempMobileNoExclude          
          SELECT DISTINCT     Email          
          FROM   (                               --SELECT DISTINCT fs.[value] AS mobileno          
                     --FROM   dbo.fn_Split(@ExcludedNumber, ',') AS fs          
                     --UNION                       
                     SELECT Email          
                     FROM   dbo.funcGetCampaignSearchKit19LeadsMails(@Applicability1)           
                     UNION ALL                               
                     SELECT EMail          
                     FROM   #TempKit19UsersExc          
                 )            A           
                    
          DROP TABLE #TempKiteverUsers           
          DROP TABLE #TempCRMPreenquiry           
          DROP TABLE #TempKiteverUsersExc           
          DROP TABLE #TempCRMPreenquiryExc           
          DROP TABLE #TempKit19UsersExc           
          DROP TABLE #TempKit19UsersApp                           
                    
                    
                    
          SET @Count = @Count -1          
      END                                  
                
                
      CREATE TABLE #TempMobileNoFinal          
      (          
       id int identity(1,1),Emails VARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS         
      )                              
      CREATE TABLE #TempMobileNoFinalExc          
      (          
       Emails VARCHAR(100)  COLLATE SQL_Latin1_General_CP1_CI_AS        
      )                         
                     
                
      INSERT INTO #TempMobileNoFinalExc          
      SELECT DISTINCT Emails          
      FROM   #TempMobileNoExclude          
              
                
      INSERT INTO #TempMobileNoFinal          
      SELECT DISTINCT Emails          
      FROM   #TempMobileNo tm where not exists (select 1 from #TempMobileNoExclude te where te.Emails=tm.Emails)        
    
declare @countemails bigint = (select COUNT(1) from #TempMobileNoFinal)    
--select * from #TempMobileNoFinal    
      
if @countemails>0      
begin      
INSERT INTO Getbatchrecord                                            
                  (                                            
      -- BatchID -- this column value is auto-generated                                            
       [User_id],                                            
     RandNum)                                            
      SELECT  @UserID,@CampaignID          
        
declare @batchid bigint= (select top 1 batchid from Getbatchrecord where USER_ID=@UserID and RandNum=@CampaignID order by BatchID desc)       
                                       
--select @batchid    
               
INSERT INTO Batchemail_infos(BatchID,UserID,SenderName,[Message],TotalRecords,TotalProcessed,ProcessTable,IsProcess,Priority_Level,BatchInsertTime,BatchProcessTime,ScheduledDate,ScheduledTime,TemplateID,[Route],PageName,IsScheduled,Email_Subject,ReplyTo)
  
     
        
SELECT @BatchID,@UserID,U.Email as SenderName,c.mailcontent,@countemails,0,0,0,0,Getdate(),NULL,Getdate(),Getdate(),0,0,0,0,c.MailSubject,c.MailReplyTo             
      FROM CampaignMaster C (nolock)             
      Inner join user_detail u on c.accounts = u.user_ID  where c.ID=@CampaignID      
      
DECLARE @output TABLE (GUID nvarchar(100) collate SQL_Latin1_General_CP1_CI_AS ,Email nvarchar(200) collate SQL_Latin1_General_CP1_CI_AS)          
     
declare @RecordCnt int=(select COUNT(1) FROM #TempMobileNoFinal)   
declare @orecordcnt int=@recordcnt           
while(@RecordCnt > 0)          
BEGIN          
SET NOCOUNT ON;    
INSERT INTO Clientemails                                            
                  (GUID,                                            
                   Email_Id,                                            
