          @balanceMails -@Mail_Debit,          
          GETDATE()          
        )  */        
     end           
                
                
                
      UPDATE CampaignMaster          
      SET    IsExecuted = 1,isrunning=0,          
             ExecuteTime = GETDATE(),          
             NoOfRecipients = @countemails        
      WHERE  ID = @CampaignID                         
                
      IF @ISTrack = 1          
      BEGIN          
          INSERT INTO SearchDetails          
            (          
              SearchName,          
              IsList,          
              CampaignID,          
              IsTrackUnsubscribe,          
              CreatedDate          
            )          
          VALUES          
            (          
              'Result -' + @CampaignName,          
