     SET @body = 'Server Offline while executing Campaign Name :' + @CampaignName           
         +          
         '<br/>Time:' + CAST(GETDATE() AS VARCHAR(50))           
                   
         EXEC usp_enqueueemail          
              @profile_name = 'Alerts',          
              @recipients = 'animesh.shukla@pelsoftlabs.in',          
              @copy_recipients = 'csshukla@pelsoftlabs.in',          
              @blind_copy_recipients = 'karuna@pelsoftlabs.in',          
              @subject = 'Our Mail Campaign Execution Status',          
              @body = @body,          
              @body_format = 'HTML'   
 END           
      
           
