CREATE   PROCEDURE dbo.usp_ExecuteCampaignMails
AS
BEGIN
	
	EXEC usp_ExecuteRecipientsUserCampaignMails 
	EXEC usp_GetRecipientsEventBasedMails
	EXEC usp_UserExecuteCampaignMessagesMailsNew 
	EXEC usp_InsertClonedeliveryCampaignMails
END


