      INSERT INTO Emailsfilter                                       
                  (Mail_GUID,                                        
                   Mail_FromEmail,                                        
                   Mail_ToEmail,                                        
                   Mail_Subject,                                        
                   Mail_TempleteName,                                        
                   Messages,                                        
                   Mail_InsertedDate,       
