                   ReplyTo,                                        
                   Mail_BatchID,                                        
                   Mail_Priority,                                        
                   Mail_ScheduleDate,                                        
                   Mail_Attechement,                                        
                   Mail_TempleteBody,                                        
                   IsMonitor)                                        
      SELECT O.Guid,                                        
             Efce.Mail_FromEmail,                                        
             Efce.Mail_ToEmail,            
             Efce.Mail_Subject,                                     
             Efce.Mail_TempleteName,                                        
             cast(Efce.Messages as nvarchar(max)),                                      
             isnull(Efce.Mail_InsertedDate,getdate()),                                        
             Efce.Mail_UserID,                                        
             Efce.ReplyTo,                                        
             TT.BatchID,                                        
             Efce.Mail_Priority,                                        
             isnull(Efce.Mail_ScheduleDate,getdate()),                                        
             Efce.Mail_Attechement,                                        
             cast(Efce.Mail_TempleteBody as nvarchar(max)),                                        
             1 AS Limit                                        
      FROM   EmailsfiltercampaignexecutionTEST2 AS Efce                                        
             INNER JOIN #tempMobile1 Tm                                        
        ON Tm.userID = Efce.Mail_UserID  and Tm.CampaignID = Efce.CampaignID                            
                        AND ValidEntries = 1       
                        inner join #tempTable1 TT on TT.campaignid=efce.campaignid      
                        inner join #output1 o on o.email=Efce.mail_toemail                                     
      WHERE  Efce.IsCompleted = 1 and o.batchid=tt.batchid     
      and not exists    
      (SELECT O.Guid--,                                        
             --Efce.Mail_FromEmail,                                        
             --Efce.Mail_ToEmail,            
             --Efce.Mail_Subject,                                     
             --Efce.Mail_TempleteName,                                        
             --cast(Efce.Messages as nvarchar(max)),                                      
             --isnull(Efce.Mail_InsertedDate,getdate()),                                        
             --Efce.Mail_UserID,                          
             --Efce.ReplyTo,                                        
             --TT.BatchID,                                        
             --Efce.Mail_Priority,                                        
             --isnull(Efce.Mail_ScheduleDate,getdate()),                                        
             --Efce.Mail_Attechement,                                        
             --cast(Efce.Mail_TempleteBody as nvarchar(max)),                                        
             --1 AS Limit                                        
      FROM   EmailsfiltercampaignexecutionTEST2 AS Efce                                        
             INNER JOIN #tempmobilevirtual Tm                                        
        ON Tm.userID = Efce.Mail_UserID  and Tm.CampaignID = Efce.CampaignID                            
                        AND ValidEntries = 0       
                        inner join #tempTable1 TT on TT.campaignid=efce.campaignid      
                        inner join #output1 o on o.email=Efce.mail_toemail                                     
      WHERE  Efce.IsCompleted = 1 and o.batchid=tt.batchid)    
          
          
      INSERT INTO EmailsfilterVirtual                                       
                (Mail_GUID,                                        
                   Mail_FromEmail,                                        
                   Mail_ToEmail,                                        
                   Mail_Subject,                                        
