      CREATE TABLE #TempMobileNoFinal  
      (  
       mobileno VARCHAR(20)  
      )                          
      CREATE TABLE #TempMobileNoFinalExc  
      (  
       mobileno VARCHAR(20)  
      )                     
      DECLARE @BATCHID NVARCHAR(500)                                      
      SELECT @BATCHID = ABS(CAST(CAST(NEWID() AS VARBINARY) AS INT))                   
        
      DELETE   
      FROM   #TempMobileNo  
      WHERE  ISNUMERIC(mobileno + '.0e0') = 0                  
        
      DELETE   
      FROM   #TempMobileNoExclude  
      WHERE  ISNUMERIC(mobileno + '.0e0') = 0          
        
      DELETE   
      FROM   #TempMobileNo  
      WHERE  ISNUMERIC(mobileno) = 0                  
        
      DELETE   
      FROM   #TempMobileNoExclude  
      WHERE  ISNUMERIC(mobileno) = 0                  
        
      INSERT INTO #TempMobileNoFinalExc  
      SELECT DISTINCT mobileno  
      FROM   #TempMobileNoExclude  
      WHERE  CAST(mobileno AS BIGINT) BETWEEN 7000000000 AND   
             9999999999  
      ORDER BY  
             mobileno           
        
      INSERT INTO #TempMobileNoFinal  
      SELECT DISTINCT mobileno  
      FROM   #TempMobileNo  
      WHERE  CAST(ISNULL(mobileno, 0) AS BIGINT) BETWEEN 7000000000   
             AND   
             9999999999  
      ORDER BY  
             mobileno   
        
      --INSERT INTO MESSAGEDELIVERYSTATUS  
      --  (  
      --    [MOBILE],  
      --    [MESSAGE],  
      --    [SENDERID],  
      --    [SMPPID],  
      --    [MESSAGEINSERTDATE],  
      --    [PRIORITY],  
      --    [U_ID],  
      --    [ISUNICODE],  
      --    [ISDND],  
      --    [OPERATOR],  
      --    [BATCHID],  
      --    [ISALLOWDND]  
      --  )  
      SELECT DISTINCT STR(tt.mobileno, 10, 0),  
             @Message,  
             @SenderID,  
             @SmppID,  
             GETDATE(),  
             2,  
             @UserID,  
             @IsUnicode,  
             0,  
             'UI',  
             @BATCHID,  
             0  
      FROM   #TempMobileNoFinal tt  
      WHERE  tt.mobileno NOT IN (SELECT td.mobileno 
                                 FROM   #TempMobileNoFinalExc   
                                        td)                  
        
        
        
      IF (@User_Filter = 'MTIX_TRC')  
      BEGIN  
          --INSERT INTO MessageDeliverystatustemp  
          --  (  
          --    MESSAGEID,  
          --    MOBILE,  
          --    [MESSAGE],  
          --    SENDERID,  
          --    MessageStatus,  
          --    SMPPID,  
          --    PRIORITY,  
          --    U_ID,  
          --    ISUNICODE,  
          --    OPERATOR,  
          --    BATCHID  
          --  )  
          SELECT DISTINCT '',  
                 STR(tt.mobileno, 10, 0),  
                 @Message,  
                 @SenderID,  
                 'Sent',  
                 @SmppID,  
                 2,  
                 @UserID,  
                 @IsUnicode,  
                 'UI',  
                 @BATCHID  
          FROM   #TempMobileNoFinal tt  
          WHERE  tt.mobileno NOT IN (SELECT td.mobileno  
                                     FROM   #TempMobileNoFinalExc   
                                            td)  
                 AND ISNULL(dbo.fn_finddnd(STR(tt.mobileno, 10, 0)), 0) = 1   
            
            
          --INSERT INTO MessageQueuePelsoft  
          --  (  
          --    -- MessageID -- this column value is auto-generated  
          --    Mobile,  
          --    [Message],  
          --    SenderID,  
          --    SmppID,  
          --    MessageInsertDate,  
          --    Priority,  
          --    U_ID,  
          --    IsUniCode,  
          --    IsDND,  
          --    Operator,  
          --    BatchID,  
          --    Isallowdnd  
          --  )  
          SELECT DISTINCT   
                 STR(tt.mobileno, 10, 0),  
                 @Message,  
                 @SenderID,  
                 @SmppID,  
                 GETDATE(),  
                 2,  
                 @UserID,  
                 @IsUnicode,  
                 0,  
                 'UI',  
                 @BATCHID,  
                 0  
          FROM   #TempMobileNoFinal tt  
          WHERE  tt.mobileno NOT IN (SELECT td.mobileno  
                                     FROM   #TempMobileNoFinalExc   
                                            td)  
                 AND ISNULL(dbo.fn_finddnd(STR(tt.mobileno, 10, 0)), 0) = 0  
      END  
      ELSE  
      BEGIN  
          --INSERT INTO MessageQueuePelsoft  
          --  (  
          --    -- MessageID -- this column value is auto-generated  
          --    Mobile,  
          --    [Message],  
          --    SenderID,  
          --    SmppID,  
          --    MessageInsertDate,  
          --    Priority,  
          --    U_ID,  
          --    IsUniCode,  
          --    IsDND,  
          --    Operator,  
          --    BatchID,  
          --    Isallowdnd  
          --  )  
          SELECT DISTINCT   
                 STR(tt.mobileno, 10, 0),  
                 @Message,  
                 @SenderID,  
                 @SmppID,  
                 GETDATE(),  
                 2,  
                 @UserID,  
                 @IsUnicode,  
                 0,  
                 'UI',  
                 @BATCHID,  
                 0  
          FROM   #TempMobileNoFinal tt  
          WHERE  tt.mobileno NOT IN (SELECT td.mobileno  
                                     FROM   #TempMobileNoFinalExc   
                                            td)  
      END                  
        
        
      UPDATE CampaignMaster  
      SET    IsExecuted = 1,  
             ExecuteTime = GETDATE(),  
             NoOfRecipients = (  
                 SELECT COUNT(A.mobileno)  
                 FROM   (  
                            SELECT DISTINCT tt.mobileno  
                            FROM   #TempMobileNoFinal tt  
                            WHERE  tt.mobileno NOT IN (SELECT td.mobileno  
                                                       FROM   #TempMobileNoFinalExc   
                                                              td)  
                        ) A  
             )  
      WHERE  ID = @CampaignID   
        
      --IF @ISTrack = 1  
      --BEGIN  
      --    INSERT INTO SearchDetails  
      --      (  
      --        SearchName,  
      --        IsList,  
      --        CampaignID,  
      --        IsTrackUnsubscribe,  
      --        CreatedDate  
      --      )  
      --    VALUES  
      --      (  
      --        'Result -' + @CampaignName,  
      --        1,  
      --        @CampaignID,  
      --        1,  
      --        GETDATE()  
      --      )  
      --END                      
        
      --IF @ISUnsubscribe = 1  
      --BEGIN  
      --    INSERT INTO SearchDetails  
      --      (  
      --        SearchName,  
      --        IsList,  
      --        CampaignID,  
      --        IsTrackUnsubscribe,  
      --        CreatedDate  
      --      )  
      --    VALUES  
      --      (  
      --        'Unsubscribe -' + @CampaignName,  
      --        1,  
      --        @CampaignID,  
      --        0,  
      --        GETDATE()  
      --      )  
      --END   
        
      DROP TABLE #TempSearchIDApplicability   
      DROP TABLE #TempSearchIDExcluded   
      DROP TABLE #TempMobileNo   
        
        
      DROP TABLE #TempMobileNoExclude   
      DROP TABLE #TempMobileNoFinal   
      DROP TABLE #TempMobileNoFinalExc                           
        
        
        
      SET @body = (  
              'Campaign Name :' + @CampaignName +  
              ' Executed Successfully' +  
          '<br/>Time:' + CAST(GETDATE() AS VARCHAR(50))  
          )     
        
      exec usp_enqueueemail   
           @profile_name = 'Alerts',  
           @recipients = 'abhishek.makkar@pelsoftlabs.in',  
           @copy_recipients = 'csshukla@pelsoftlabs.in',  
           @blind_copy_recipients = 'karuna@pelsoftlabs.in',  
           @subject = 'Campaign Execution Status',  
           @body = @body,  
           @body_format = 'HTML'                          
        
      SELECT 'Success'  
             --END TRY            
               
             --BEGIN CATCH  
             -- SET @Error = 'Error in Executing Campaign :  ' + @CampaignName +  
             --     '<br/>Error message :  ' + CAST(ERROR_LINE() AS VARCHAR(50)) +  
             --     '/' + ERROR_MESSAGE() +  
             --     '... <br/> It will be retried in 15 mins... Unless Deleted..<br /> Thanks'                  
               
             -- exec usp_enqueueemail  
             --      @profile_name = 'Alerts',  
             --      @recipients = 'abhishek.makkar@pelsoftlabs.in',  
             --      @copy_recipients = 'csshukla@pelsoftlabs.in',  
             --      @blind_copy_recipients = 'karuna@pelsoftlabs.in',  
             --      @subject = 'Campaign Execution Status',  
             --      @body = @body,  
             --      @body_format = 'HTML'  
             --END CATCH  
     END   
 ELSE  
 BEGIN  
     SET @body = 'Server Offline while executing Campaign Name :' + @CampaignName   
         +  
         '<br/>Time:' + CAST(GETDATE() AS VARCHAR(50))     
       
     exec usp_enqueueemail   
          @profile_name = 'Alerts',  
          @recipients = 'abhishek.makkar@pelsoftlabs.in',  
          @copy_recipients = 'csshukla@pelsoftlabs.in',  
          @blind_copy_recipients = 'karuna@pelsoftlabs.in',  
          @subject = 'Campaign Execution Status',  
          @body = @body,  
          @body_format = 'HTML'  
 END   
   
   
 DROP TABLE #TempLinked  
END   
  


