    CREATE TABLE #tempGroups                                      
    (                                      
     CampaignID         BIGINT,                                      
     ParentID           BIGINT,                                      
     messageContent     VARCHAR(MAX),                                      
     Mail_ToEmail       VARCHAR(500),                                      
     MailReplyTo        VARCHAR(500),                                      
     AccountUsed        VARCHAR(500),                             
     MailSubject        VARCHAR(500),    
     templateid bigint,  
     frommailid varchar(250)                                                    
    )                                      
                                           
    INSERT INTO #tempGroups              
      (                                      
     CampaignID,                                      
     ParentID,                                      
     messageContent,                                      
     Mail_ToEmail,                                      
     MailReplyTo,                                      
     AccountUsed,                                      
     MailSubject,    
     templateid,  
     frommailid                                                    
      )                                      
    EXEC Fn_getgroupmessagemailsnew2                                      
                                       
     insert into #TempTable                                    
     (CampaignID,ParentID,MailContent,Mail_ToEmail,MailReplyTo,AccountUsed,MailSubject,templateid,frommailid )                                    
   SELECT CampaignID,                                      
         ParentID,                                      
         CAST(                                      
          messageContent COLLATE Latin1_General_CI_AI AS VARCHAR(MAX)),                                      
         CAST(Mail_ToEmail COLLATE Latin1_General_CI_AI AS VARCHAR(MAX)),                
         CAST(MailReplyTo COLLATE Latin1_General_CI_AI AS VARCHAR(MAX)),                                      
         AccountUsed,                                      
         CAST(MailSubject COLLATE Latin1_General_CI_AI AS VARCHAR(MAX)),    
         templateid,isnull(cast(frommailid  COLLATE Latin1_General_CI_AI AS VARCHAR(250)),'contactus@email19.in')  
     FROM   #tempGroups                                      
     END      
                                         
   UPDATE Kd                                      
   SET    Kd.Mail_FromEmail = cast(isnull(A.frommailid COLLATE Latin1_General_CI_AI,'contactus@email19.in') as varchar(250))  
,    
    Kd.Mail_Subject = CAST(A.MailSubject COLLATE Latin1_General_CI_AI AS VARCHAR(MAX)),                                      
    Kd.Messages = (select CAST(dbo.build_mailContent(A.templateid,A.campaignid,A.parentid,A.MailContent COLLATE Latin1_General_CI_AI,A.Mail_ToEmail) AS VARCHAR(MAX))), --CAST(A.MailContent COLLATE Latin1_General_CI_AI AS VARCHAR(MAX)),           
    Kd.Mail_UserID = A.AccountUsed,                                      
    Kd.ReplyTo = CAST(A.MailReplyTo COLLATE Latin1_General_CI_AI AS VARCHAR(MAX)),                                      
    Kd.Mail_Priority = 0,                                      
    Kd.Mail_ScheduleDate = GETDATE(),                                      
    Kd.Mail_Attechement = NULL,                                      
    Kd.Mail_TempleteBody = (select CAST(dbo.build_mailContent(A.templateid,A.campaignid,A.parentid,A.MailContent COLLATE Latin1_General_CI_AI,A.Mail_ToEmail) AS VARCHAR(MAX))), --CAST(A.MailContent COLLATE Latin1_General_CI_AI AS VARCHAR(MAX)),          
  
                            
    Kd.Mail_InsertedDate = GETDATE(),                                      
    Kd.Mail_GUID = NEWID(),                                      
    Kd.IsCompleted = 1                             
   FROM   EmailsfiltercampaignexecutionTEST2 Kd    (nolock)                                  
    INNER JOIN #TempTable A                                     
      ON kd.Mail_ID = A.Mail_Id              
                                          
           
   UPDATE Kd                                          
      SET    Ismessages = 1                                          
      FROM   Usercampaignexecutionhistory Kd        
      inner join #temptable A                 
    ON  Kd.CampaignID = A.CampaignID AND A.ParentID = Kd.ParentID AND Kd.JobId = @Jobid                                      
                            
   UPDATE Kd                                    
   SET    Kd.Step2 = 1  ,Step2DateTime=GETDATE(), Step2Recipients=isnull(A.Step2Recipients,0)                                 
   FROM   Usercampaignhistory Kd  (nolock)            
    Inner JOIN                                 
    (select campaignid,count(campaignid) as Step2Recipients,parentid                 
    from #temptable group by Parentid,campaignid) A                                    
    ON  Kd.CampaignID = A.CampaignID AND A.ParentID = Kd.ParentID AND Kd.JobId = @Jobid                           
                     
   UPDATE Kd                                    
   SET    Kd.Step2 = 1  ,Step2DateTime=GETDATE() FROM   Usercampaignhistory Kd where JobId=@jobid    
                         
 DROP TABLE #TempTable             
  INSERT INTO Getbatchrecord                                        
                  (                                        
      -- BatchID -- this column value is auto-generated                                        
       [User_id],                                        
                   RandNum)                                        
      SELECT DISTINCT Ucerm.ParentID,                                        
                      Ucerm.CampaignID                                        
      FROM   EmailsfiltercampaignexecutionTEST2 AS Ucerm With(nolock)        
                                        
     SELECT         
     ROW_NUMBER() Over(order by Ucerm.CampaignId,Ucerm.ParentId) Id,        
     Ucerm.CampaignID,           
     Ucerm.ParentID                               ,        
                     -- Cast(Ucerm.Messages AS VARCHAR(MAX))  AS  Messages,                                        
                      dbo.Fn_createbatchid(Ucerm.CampaignID, Ucerm.ParentID) AS BatchID,                                      
                     Ucerm.Mail_FromEmail,                                        
                      Ucerm.Mail_UserID AS UserID,        
                      Ucerm.Mail_Subject,        
                      Ucerm.ReplyTo,        
                      Count(*) cnt        
                     -- Ucerm.Mail_ToEmail,                                        
   INTO   #tempTable1                                        
      FROM   EmailsfiltercampaignexecutionTEST2 Ucerm -- join user_detail u on ucerm.Mail_UserID=u.user_id                                      
      WHERE  Ucerm.IsCompleted = 1  --and u.HasVirtualCredits=0           
      Group by  Ucerm.CampaignID,           
     Ucerm.ParentID , Ucerm.Mail_FromEmail,                                        
                      Ucerm.Mail_UserID,        
                      Ucerm.Mail_Subject,        
                      Ucerm.ReplyTo       
                          
SELECT         
     ROW_NUMBER() Over(order by Ucerm.CampaignId,Ucerm.ParentId) Id,        
     Ucerm.CampaignID,           
     Ucerm.ParentID                               ,        
                     -- Cast(Ucerm.Messages AS VARCHAR(MAX))  AS  Messages,                                        
                      dbo.Fn_createbatchid(Ucerm.CampaignID, Ucerm.ParentID) AS BatchID,                                      
                     Ucerm.Mail_FromEmail,                                        
                      Ucerm.Mail_UserID AS UserID,        
                      Ucerm.Mail_Subject,        
                      Ucerm.ReplyTo,        
                      Count(*) cnt,    
                      ParentSuperResellerId        
                     -- Ucerm.Mail_ToEmail,                                        
   INTO   #tempTableVirtual                                        
      FROM   EmailsfiltercampaignexecutionTEST2 Ucerm  join user_detail u on ucerm.Mail_UserID=u.user_id                                      
      WHERE  Ucerm.IsCompleted = 1  and u.HasVirtualCredits=1           
      Group by  Ucerm.CampaignID,ParentSuperResellerId,           
     Ucerm.ParentID , Ucerm.Mail_FromEmail,                                        
                      Ucerm.Mail_UserID,        
                      Ucerm.Mail_Subject,        
                      Ucerm.ReplyTo     
                          
                            
              
   SELECT A.UserID,a.CampaignID, a.cnt,A.BatchID, SUM(b.cnt) RunningTotal into #tempTableRunningTotal1        
   FROM   #tempTable1 a join        
       #tempTable1 b on a.userid=b.userid       
   WHERE b.CampaignID <= a.CampaignID        
   GROUP BY A.UserID, a.CampaignID, a.cnt,A.BatchID        
   ORDER BY a.CampaignID;      
       
    SELECT A.UserID,a.CampaignID, a.cnt,A.BatchID, SUM(b.cnt) RunningTotal,a.ParentSuperResellerId into #tempTableRunningTotalVirtual         FROM   
    #tempTableVirtual a join        
       #tempTableVirtual b on a.userid=b.userid      
   WHERE b.CampaignID <= a.CampaignID        
   GROUP BY A.ParentSuperResellerId, a.CampaignID, a.cnt,A.BatchID,A.UserID        
   ORDER BY a.CampaignID;      
              
              
      DELETE Kd                                        
      FROM   Getbatchrecord Kd                                        
             INNER JOIN #tempTable1 Tt                                        
                     ON Tt.BatchID = Kd.BatchID       
                         
     DELETE Kd                                        
      FROM   Getbatchrecord Kd                                        
             INNER JOIN #tempTableVirtual Tt                                        
                     ON Tt.BatchID = Kd.BatchID                                     
                                      
                                        
      --- Calculate credits                                        
      SELECT B.UserID,         
    B.CampaignID,                                       
             CASE                                        
               WHEN B.Balance > B.Credits THEN 1                                        
               ELSE 0 --test, otherwise 0                                        
             END AS ValidEntries                                        
      INTO   #tempMobile1                                        
      FROM   (SELECT A.UserID,          
      A.CampaignID,                                      
                       (A.Credits)   AS Credits,  --Runningtotal                                      
                     A.Balance                                        
              FROM   (SELECT Tt.UserID,                                        
                             TT.RunningTotal AS Credits,        
                             TT.CampaignID,                                        
                            -- Tt.Mail_ToEmail,                                  
                             Tt.BatchID,                                        
                             (SELECT TOP 1 Balance                                        
                              FROM   Mailcreditdetails AS Mcd                                        
                              WHERE  Mcd.[User_ID] = Tt.UserID                 
                              ORDER  BY Credit_ID DESC)     AS Balance                                        
                      FROM   #tempTableRunningTotal1 Tt) A                                        
              GROUP  BY A.UserID,                                        
                        A.Balance,A.CampaignID,A.credits) B        
     --select * from #tempMobile1      
         
     SELECT B.UserID,         
            B.CampaignID,                                       
            CASE                                        
               WHEN B.Balance > B.Credits THEN 1                                        
               ELSE 0 --test, otherwise 0                                        
             END AS ValidEntries,    
             B.ParentSuperResellerId                                        
      INTO   #tempmobilevirtual                                        
      FROM   (SELECT A.UserID,          
      A.CampaignID,                                      
      (A.Credits)   AS Credits,  --Runningtotal                                      
      A.Balance,    
      A.ParentSuperResellerId                  
      FROM   (SELECT Tt.UserID,                                        
                     TT.RunningTotal AS Credits,        
                     TT.CampaignID,                                        
                     -- Tt.Mail_ToEmail,                                  
                     Tt.BatchID,                                        
                     (SELECT TOP 1 Balance                                        
                      FROM   SuperResellerMailCreditDetails AS Mcd                                        
                      WHERE  Mcd.[User_ID] = Tt.ParentSuperResellerId                
                      ORDER  BY Credit_ID DESC)     AS Balance,    
                      tt.ParentSuperResellerId                                        
               FROM   #tempTableRunningTotalVirtual Tt) A                                        
              GROUP  BY A.ParentSuperResellerId,A.UserID,                                       
                        A.Balance,A.CampaignID,A.credits) B     
         
select t.*,u.email into #Insufficientresellerbalance from #tempmobilevirtual t join #tempMobile1 tt on t.CampaignID=tt.CampaignID join user_detail u on u.user_id=t.ParentSuperResellerId where tt.ValidEntries=0    
    
