CREATE   PROCEDURE [dbo].[Usp_executeEventBasedSMScampaignCorrected_Combined]                                  
AS                                  
BEGIN    
declare @maxjobid bigint = (select top 1 JobId from UserCampaignHistory UCH order by ID desc)  
declare @maxid bigint = (select top 1 Id from UserCampaignHistory UCH order by ID desc)  
if ((select Step3DateTime from UserCampaignHistory UCH where ID=@maxid) is not null)  
begin                                
 DECLARE @Body VARCHAR(500)    
   
 DEclare @JobId Bigint = (Select ISNULL(MAX(JobId),0)+1 from UserCampaignHistory UCH )  
   
 DECLARE @LastExecutedTime datetime = isnull((select Top 1 CampaignExecutedDatetime from UserCampaignExecution where issms=1 and isevent=1 order by id desc),getdate())   
   
 Declare @CampaignStarttime datetime = Getdate()  
                                 
 if OBJECT_ID('tempdb..#temptemplate') is not null                
 Begin   
 Drop table #temptemplate   
 end        
   
 SELECT      ROW_NUMBER()Over(Order by Ucm.ID,Ucm.ParentID) AS Id,  
       ucm.ID      AS CampaignID,                  
                   ucm.ParentID,                  
                   A.[value]  AS Applicabilty,                  
                   AGL.[value] AS ApplicabiltyGroupList,                  
                   EGL.[Value] AS ExclusionsGroupList,                  
                   ucm.NotificationMail,                  
                   ucm.ExclusionsNumber,                  
                   E.[Value] AS Exclusions,                  
                   ucm.InclusionsNumber,                  
                   ucm.AccountUsed,                  
                   ucm.SenderID,                  
                   ucm.[Message],                  
                   ucm.TemplateID,                  
                   ucm.TemplateGroupID,                  
                   ucm.IsUnicode,                  
                   ucm.EventsName      INTO #TempTemplate                                       
 FROM   Usercampaignmaster ucm   (nolock)  
   Inner join  User_detail AS Ud  on Ud.[User_ID]  = AccountUsed and Ud.[Status] <> 0                                            OUTER APPLY Dbo.Fn_split(Ucm.Applicabilty, '#') AS A   
   OUTER APPLY Dbo.Fn_split(Ucm.ApplicabiltyGroupList, '#') AS AGL  
   OUTER APPLY Dbo.Fn_split(Ucm.ExclusionsGroupList, '#') AS  EGL   
   OUTER APPLY Dbo.Fn_split(Ucm.Exclusions, '#') AS E                                        
            WHERE Ucm.MailReplyTo = ''  and IsEventBased=1                                      
                   AND DATEDIFF(                                        
                           Minute,                                        
                           getdate(),                                        
                           CASE                                         
                                WHEN Ucm.IsNeverExpire = 1 THEN DATEADD(DAY, 1,getdate())                                        
                                ELSE ISNULL(Ucm.ExpiryDate, getdate())                                        
                       END                                        
                       ) > 0                                        
                   AND DATEDIFF(Minute, getdate(), ISNULL(Ucm.StartDate, getdate()))  < 0                                                                             
                   AND Ucm.IsActive = 1                                        
  
 /*(                                  
            SELECT Ucm.id      AS CampaignID,                                  
                   Ucm.parentid,                                  
                   Fs.[value]  AS Applicabilty,                                  
                   0           AS ApplicabiltyGroupList,                                  
                   0           AS ExclusionsGroupList,                                  
                   Ucm.notificationmail,                                  
                   Ucm.exclusionsnumber,                                  
                   0           AS Exclusions,                                  
                   Ucm.inclusionsnumber,                                  
                   Ucm.accountused,                                  
                   Ucm.senderid,                                  
                   Ucm.[message],                                  
                   Ucm.templateid,                                  
                   Ucm.templategroupid,                                  
                   Ucm.isunicode                                  
            FROM   usercampaignmaster Ucm  (nolock)                                
                   OUTER APPLY dbo.Fn_split(Ucm.applicabilty, '#') AS Fs                                  
            WHERE  Ucm.isscheduled = 1                                  
                   AND Ucm.mailreplyto = ''                                  
                   AND   Ucm.nextexecutedatetime between @LastExecutedTime and getdate()                                
                   AND DATEDIFF(                                  
                           minute,                                  
                           GETDATE(),                                  
                           CASE                                   
                                WHEN Ucm.isneverexpire = 1 THEN DATEADD(DAY, 1, GETDATE())                                  
                                ELSE ISNULL(Ucm.expirydate, GETDATE())                                  
                           END                                  
                       ) > 0                                  
AND DATEDIFF(minute, GETDATE(), ISNULL(Ucm.startdate, GETDATE()))                                  
                    
                                                         
                                                         
             <= 0                                  
                   AND Ucm.isactive = 1                                  
                                  
                                              
                                              
            UNION ALL                                  
                                              
                                              
                                              
            SELECT Ucm.id      AS CampaignID,                                  
                   Ucm.parentid,                                  
                   0           AS Applicabilty,                                  
                   Fs.[value]  AS ApplicabiltyGroupList,                                  
                   0           AS ExclusionsGroupList,                                 
                   Ucm.notificationmail,                                  
                   Ucm.exclusionsnumber,                                  
                   0        AS Exclusions,                                  
                   Ucm.inclusionsnumber,                                  
                   Ucm.accountused,                                  
 Ucm.senderid,                                  
                   Ucm.[message],                                  
                   Ucm.templateid,                                  
                   Ucm.templategroupid,                             
                   Ucm.isunicode                                  
            FROM   usercampaignmaster Ucm (nolock)                                 
                   OUTER APPLY dbo.Fn_split(Ucm.applicabiltygrouplist, '#') AS                                   
            Fs                                  
            WHERE  Ucm.isscheduled = 1                                  
                   AND Ucm.mailreplyto = ''                                  
                   AND   Ucm.nextexecutedatetime between @LastExecutedTime and getdate()                                
                   AND DATEDIFF(                              
                           minute,                                  
                           GETDATE(),                                  
                       CASE                                   
                                WHEN Ucm.isneverexpire = 1 THEN DATEADD(DAY, 1, GETDATE())                                  
                                ELSE ISNULL(Ucm.expirydate, GETDATE())                                  
                           END                                  
                       ) > 0                                  
                   AND DATEDIFF(minute, GETDATE(), ISNULL(Ucm.startdate, GETDATE()))                                  
                                                         
                                              
                                                         
                       < 0                                  
                   AND Ucm.isactive = 1                                  
                                              
                                              
                                              
            UNION ALL                                  
                                              
                                              
                                              
            SELECT Ucm.id      AS CampaignID,                                  
                   Ucm.parentid,                                  
                   0      AS Applicabilty,                                  
                   0           AS ApplicabiltyGroupList,                                  
                   Fs.[value]  AS ExclusionsGroupList,                                  
                   Ucm.notificationmail,                                  
         Ucm.exclusionsnumber,                                  
                   0           AS Exclusions,                                  
                   Ucm.inclusionsnumber,                                  
                   Ucm.accountused,                                  
                   Ucm.senderid,                                  
                   Ucm.[message],                                  
                   Ucm.templateid,                                  
   Ucm.templategroupid,                                  
                   Ucm.isunicode                                  
            FROM   usercampaignmaster Ucm  (nolock)                                
                   OUTER APPLY dbo.Fn_split(Ucm.exclusionsgrouplist, '#') AS                                   
            Fs                                  
            WHERE  Ucm.isscheduled = 1                                  
                   AND Ucm.isactive = 1                                  
                   AND Ucm.mailreplyto = ''                                  
                   AND   Ucm.nextexecutedatetime between @LastExecutedTime and getdate()                                
AND DATEDIFF(                                  
                           minute,                                  
                           GETDATE(),                                  
                           CASE                                   
                                WHEN Ucm.isneverexpire = 1 THEN DATEADD(DAY, 1, GETDATE())                                  
                                ELSE ISNULL(Ucm.expirydate, GETDATE())                                  
                           END                                  
                       ) > 0                                  
                   AND DATEDIFF(minute, GETDATE(), ISNULL(Ucm.startdate, GETDATE()))                                  
                                                         
                                                         
                                                         
                       < 0                                  
                                              
                                        
                            
            UNION ALL                                  
                                              
                                              
                                              
            SELECT Ucm.id      AS CampaignID,                                  
                   Ucm.parentid,                                  
                   0           AS Applicabilty,                                  
                   0           AS ApplicabiltyGroupList,                                  
                   0           AS ExclusionsGroupList,                                  
                   Ucm.notificationmail,                                  
                   Ucm.exclusionsnumber,                                  
                   Fs.[value]  AS Exclusions,                        
                   Ucm.inclusionsnumber,                                  
                   Ucm.accountused,                                  
                   Ucm.senderid,                                  
                   Ucm.[message],                                  
                   Ucm.templateid,                                  
                   Ucm.templategroupid,                                  
                   Ucm.isunicode                                  
            FROM   usercampaignmaster Ucm   (nolock)                               
                   OUTER APPLY dbo.Fn_split(Ucm.exclusions, '#') AS Fs                                  
            WHERE  Ucm.isscheduled = 1                                  
                   AND Ucm.isactive = 1                                  
                   AND Ucm.mailreplyto = ''                                  
                   AND   Ucm.nextexecutedatetime between @LastExecutedTime and getdate()                                 
 AND DATEDIFF(                                  
                           minute,                                  
                           GETDATE(),                                  
                           CASE                                   
                                WHEN Ucm.isneverexpire = 1 THEN DATEADD(DAY, 1, GETDATE())       
                                ELSE ISNULL(Ucm.expirydate, GETDATE())                                  
                           END                                  
                       ) > 0                                  
                   AND DATEDIFF(minute, GETDATE(), ISNULL(Ucm.startdate, GETDATE()))                                  
                                       
                                                         
                                                         
                       < 0                                  
        ) A    */                              
   
  SELECT ud.EMail,ucm.AccountUsed,ucm.Id As CampaignId,ucm.ParentID into #UserAccountDetails  
 FROM   UserCampaignMaster AS ucm  
 Inner join User_Detail AS ud on ud.[User_ID] = ucm.AccountUsed  
 Inner join #TempTemplate tt on tt.CampaignId = ucm.ID  
    WHERE  ucm.ID = tt.CampaignID AND ucm.IsActive = 1  
                                   
 INSERT INTO usercampaignhistory                                  
   (                                  
     -- ID -- this column value is auto-generated                                  
     campaignid,                                  
     parentid,                                  
     step1,                                  
     step2,                                  
     step3,                                 
     issms,                                  
     ismail,                                  
     isscheduled,                                  
     iseventbased,                                  
     createdon,  
     JobId                                  
       
   )                          
                 
 SELECT DISTINCT campaignid,                                  
        parentid,                                  
        0,                                  
        0,                                  
        0,                                  
        1,                                  
        0,                                  
        0,                                  
        1,                                  
        GETDATE(),  
        @JobId                               
 FROM   #temptemplate                                  
                                  
  IF NOT EXISTS (                                  
        SELECT 'x'                                  
        FROM   #temptemplate                                  
    )                                  
 BEGIN                                  
     SET @Body = 'No Campaign Found'                                  
      SELECT @Body                                  
 END                                  
 ELSE                                  
 BEGIN                                  
     CREATE TABLE #temptablesearchapp                        
     (                                  
      campaignid             BIGINT,                                  
      searchid               BIGINT,                                  
      parentid         BIGINT,   
      userid           bigint,                                 
      personname             NVARCHAR(200),                                  
      companyname            NVARCHAR(200),                                  
      mobileno               NVARCHAR(200),                                  
      mobileno1              NVARCHAR(200),                                  
      mobileno2              NVARCHAR(200),                                  
      emailid                NVARCHAR(200),                                  
      emailid1               NVARCHAR(200),                                  
      emailid2               NVARCHAR(200),                                  
      city                   NVARCHAR(200),                                  
      STATE                  NVARCHAR(200),                                  
      country                NVARCHAR(200),                                  
      countrycode            NVARCHAR(200),                                  
      pincode                NVARCHAR(200),                                  
      residentialaddress     NVARCHAR(200),                                  
      officeaddress          NVARCHAR(200),                                  
      sourcename       NVARCHAR(200),                                  
      mediumname             NVARCHAR(200),                                  
      campaignname           NVARCHAR(200),                                  
      initialremarks         NVARCHAR(1000)                                  
     )                                  
                                
     CREATE TABLE #temptablesearchexc                                  
     (                                  
      campaignid             BIGINT,                                  
      searchid               BIGINT,                                  
      parentid               BIGINT,  
      userid     bigint,                   
      personname             NVARCHAR(200),                                  
      companyname            NVARCHAR(200),                
      mobileno               NVARCHAR(200),                                  
      mobileno1              NVARCHAR(200),                                  
      mobileno2              NVARCHAR(200),                                  
      emailid                NVARCHAR(200),                                  
      emailid1               NVARCHAR(200),                                  
      emailid2               NVARCHAR(200),                                  
      city                   NVARCHAR(200),                                  
      STATE                  NVARCHAR(200),                                  
      country                NVARCHAR(200),           
      countrycode            NVARCHAR(200),                                  
      pincode                NVARCHAR(200),                                  
      residentialaddress     NVARCHAR(200),                                  
      officeaddress          NVARCHAR(200),                                  
      sourcename             NVARCHAR(200),                                  
      mediumname             NVARCHAR(200),                                
      campaignname           NVARCHAR(200),                                  
      initialremarks         NVARCHAR(1000)                   
     )                                  
   INSERT INTO #temptablesearchapp(mobileno,CampaignID,ParentID,userid  )                                        
         Select ISNULL(Usd.MobileNumber, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed    
   FROM  #temptemplate TT  
   Inner join  Usersearchdata AS Usd  (nolock)  on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ApplicabiltyGroupList and Tt.ApplicabiltyGroupList is not null       
         union     
      select distinct A.mobileno,A.CampaignID,A.ParentID,A.userid  
        from (select f.value as mobileno,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.InclusionsNumber,',') f where isnumeric(f.value)=1 group by CampaignID,ParentID,AccountUsed,f.value ) A        
                              
   
 INSERT INTO #temptablesearchexc (mobileno,CampaignID,ParentID,userid  )            
SELECT ISNULL(Usd.Mobilenumber, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed FROM #temptemplate TT   Inner join   Usersearchdata AS Usd  (nolock) on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ExclusionsGroupList and Tt.ExclusionsGroupList is not null    
      union     
select distinct A.mobileno,A.CampaignID,A.ParentID,A.userid  
from (select f.value as mobileno,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.ExclusionsNumber,',') f where isnumeric(f.value)=1 group by CampaignID,ParentID,AccountUsed,f.value ) A   
  
  
create table #EligibleCampaigns(Id int identity(1,1),Campaignid bigint,parentid bigint,accountused bigint,applicabilty bigint,exclusions bigint)  
 insert into #EligibleCampaigns(Campaignid ,parentid ,accountused ,applicabilty ,exclusions)  
 select t.Campaignid ,t.parentid ,t.accountused ,t.applicabilty ,t.exclusions from #TempTemplate t join userenquiry u on t.ParentID=u.ParentID and t.EventsName='enqadd' where u.CreatedDate>@LastExecutedTime  
 union  
 select t.Campaignid ,t.parentid ,t.accountused ,t.applicabilty ,t.exclusions from #TempTemplate t join userleads u on t.ParentID=u.ParentID and t.EventsName='LEDADD' where u.Createdon>@LastExecutedTime   
 union  
 select t.Campaignid ,t.parentid ,t.accountused ,t.applicabilty ,t.exclusions from #TempTemplate t join userleads u on t.ParentID=u.ParentID and t.EventsName='FOLADD' join LeadInteractionHistory l on u.LeadNo=l.LeadNo and u.ParentID=l.ParentID where l.Createdon>@LastExecutedTime  
  
                        
 DECLARE @CountCampaign     INT = (Select MAX(Id) from #EligibleCampaigns    )                                        
                                                                                 
     DECLARE @Count INT = 1                                                                                                  WHILE (@Count <= @CountCampaign)                                  
     BEGIN                                  
           DECLARE @Applicability BIGINT,                                     
     @Exclusions BIGINT,  
                 @Parentid BIGINT,                                        
                 @Campaignid BIGINT,  
                 @userid bigint  
                     
                   
          Select @Campaignid =Campaignid, @Parentid = Parentid ,@userid=AccountUsed  
          ,@Applicability = tt.Applicabilty,@Exclusions = tt.Exclusions  
           from #EligibleCampaigns tt Where Id = @Count                    If(@Applicability is not null)  
          Begin                                 
            INSERT INTO #temptablesearchapp                                        
       (                                       
      PersonName,                                        
      CompanyName,                                        
      MobileNo,                                        
      MobileNo1,                                        
      MobileNo2,                                        
      EmailID,                                        
      EmailID1,                                        
      EmailID2,                                        
      Country,                                        
      [STATE],                           
      City,                                  
      PinCode,                                        
      ResidentialAddress,                                        
      OfficeAddress,                                        
      SourceName,                                        
      MediumName,                                        
      CampaignName,                                        
      InitialRemarks,                                        
      SearchID,                                        
      ParentID,                                        
      CampaignID                                        
       )                                        
     EXEC Usp_executeusersearch                                        
       @ParentId,                                        
       @Applicability,                                        
       @Campaignid  
         
           End                                   
         if(@Exclusions is not null)  
          Begin                                   
         INSERT INTO #temptablesearchexc                                        
           (                                        
             PersonName,                                        
             CompanyName,                                        
             MobileNo,                                        
             MobileNo1,                                        
  MobileNo2,                                        
             EmailID,                                        
             EmailID1,                                        
             EmailID2,                                        
             Country,                                        
             [STATE],                                        
             City,                                        
             PinCode,                                        
             ResidentialAddress,                                        
            OfficeAddress,                                        
             SourceName,                                        
             MediumName,                                        
             CampaignName,                                        
             InitialRemarks,                                        
             SearchID,                                        
             ParentID,                                        
             CampaignID                                        
    )                                        
         EXEC Usp_executeusersearch                                        
              @Parentid,                                        
              @Exclusions,                                        
              @Campaignid  
      
    END  
     SET @Count = @Count+1  
       
     END                                        
    
  drop table #EligibleCampaigns                            
                                      
     SELECT distinct A.mobileno,                                  
            A.parentid,                                  
            A.campaignid,  
            A.userid                        
            INTO     #tmpemailid   
     FROM   (                                  
                SELECT Tt2.mobileno,                                  
                       Tt2.parentid,                                  
                       Tt2.campaignid,  
                       tt.Accountused as userid                                  
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                   
          WHERE NOT EXISTS (SELECT 1 FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.mobileno = Tt.mobileno OR Tt2.mobileno = Tt.mobileno1 OR Tt2.mobileno = Tt.mobileno2 ) )                          
          UNION                                        
        SELECT Tt2.mobileno1,                                        
                       Tt2.ParentID,                                        
           Tt2.CampaignID,tt.Accountused  as userid                                       
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                  
                 WHERE  NOT EXISTS (SELECT 1                                        
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.mobileno1 = Tt.mobileno OR Tt2.mobileno1 = Tt.mobileno1 OR  Tt2.mobileno1 = Tt.mobileno2)  )     
                UNION                                        
                SELECT Tt2.mobileno2,                                        
                       Tt2.ParentID,                                        
                       Tt2.CampaignID,tt.Accountused as userid                                        
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                                        
                 WHERE  NOT EXISTS (SELECT 1                                        
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND (Tt2.mobileno2 = Tt.mobileno OR Tt2.mobileno2 = Tt.mobileno1 OR  Tt2.mobileno2= Tt.mobileno2 ) )     
           
       )        A                                        
                       
    
   IF EXISTS( SELECT * FROM   #TempTemplate WHERE  EventsName = 'ENQADD')                  
 BEGIN                  
   
 select * into #UserEnquiry from UserEnquiry ue  (nolock) WHERE  ue.CreatedDate Between @LastExecutedTime and @CampaignStarttime                
     SELECT tt.Mobileno,                  
            tt.ParentID,                  
            tid.campaignid                
           INTO #TempEnq                  
   FROM   (   
      SELECT  ue.MobileNo,                  
        ue.ParentID,                  
        ue.CreatedDate                  
                FROM   #UserEnquiry AS ue                
    Inner  join (Select Distinct CampaignID,ParentID from #TempTemplate T WHERE  EventsName = 'ENQADD') ucs on ucs.ParentID = ue.ParentID     
                WHERE  ue.CreatedDate Between @LastExecutedTime and @CampaignStarttime  
          
    UNION                  
                SELECT ue.MobileNo1,                  
        ue.ParentID,                  
        ue.CreatedDate                  
                FROM   #UserEnquiry AS ue     
    Inner  join (Select Distinct CampaignID,ParentID from #TempTemplate T WHERE  EventsName = 'ENQADD') ucs on ucs.ParentID = ue.ParentID                  
                WHERE  ue.CreatedDate Between @LastExecutedTime and @CampaignStarttime                
    UNION                  
                SELECT ue.MobileNo2,                  
                       ue.ParentID,                  
                       ue.CreatedDate                  
                FROM   #UserEnquiry AS ue                  
                Inner  join (Select Distinct CampaignID,ParentID from #TempTemplate T  WHERE  EventsName = 'ENQADD') ucs on ucs.ParentID = ue.ParentID     
    WHERE  ue.CreatedDate Between @LastExecutedTime and @CampaignStarttime                
       ) tt          
    Inner join #tmpemailid tid on tid.mobileno = (CAST(tt.MobileNo COLLATE Latin1_General_CI_AI AS VARCHAR(50)))  
 WHERE tt.MobileNo <> ''    
                 
    drop table #UserEnquiry                 
                       
      INSERT INTO UserCampaignExecutionHistory                  
     (                  
      -- ID -- this column value is auto-generated                  
