             ON Tm.userID = Tt.userID   and Tm.CampaignID = Tt.CampaignID                                                  --AND Validentries = 1                                        
      WHERE  Jobid=@jobId                      
                      
if exists(select 1 from UserCampaignExecutionHistory where Jobid=@jobid and TemplateSequence<>0)    
begin    
update ucm set TemplateGroupSequence= case when isending=0 then isnull((select ugtm.orderno where OrderNo=TemplateSequence+1 and GroupID=ucm.TemplateGroupID),1) else isnull((select ugtm.orderno where OrderNo=TemplateSequence+1 and GroupID=ucm.TemplateGroupID),templategroupsequence) end from UserCampaignmaster ucm join usercampaignexecutionhistory uceh on uceh.CampaignID=ucm.ID join UserGroupTemplateMix ugtm on ugtm.GroupID=ucm.TemplateGroupID where Jobid=@jobid and TemplateSequence<>0 and IsExecuted=1    
end                
    
