Select BatchID,[User_id] ParentID,RandNum CampaignID into #Batch2 from Getbatchrecord Gbr                             Order by gbr.BatchID                           
                                        
      DELETE Kd                                        
      FROM   Getbatchrecord Kd                                        
     Inner join    #Batch2 B on B.BatchId = Kd.BatchID     
    
