    declare @ErrorMsg nvarchar (max)='Last campaign not executed yet, pl update step3datetime of job id ' + cast(@maxjobid as nvarchar)+ ' before running this campaign'   
     exec usp_InsertCampaignError @Service='SMS', @isevent=1, @ErrorMessage= @ErrorMsg  
    end  
