/* ============================================================
   Procedure: [dbo].[usp_executeeventcampaign]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_executeeventcampaign]  --'enquiry',59658401,11385--'enquiry',42230305,7449-- 'lead',1002391      --10657
@context nvarchar(20),@activityid bigint,@cmpid bigint=null,@tcmpid bigint=null,@errormessage nvarchar(2000)=null output                      
as                                                                        
begin                                        
set ansi_warnings on;                                                                  
drop table if exists #campaignstobeexecuted                                                                        
drop table if exists #applicablegroups                                                                        
drop table if exists #Exclusions                                                                        
   DECLARE @exists bigint,@sqlquery nvarchar(max);                                                                     
declare @parentid bigint,@eventid int,@entityid bigint, @mobile1 nvarchar(20),@mobile2 nvarchar(20),@mobile3 nvarchar(20),                                                                        
@email1 nvarchar(100),@email2 nvarchar(100),@email3 nvarchar(100),@isscheduledevent int=0,@duedate datetime,@tgcampid bigint,        
@st_rules int,@str_rules nvarchar(max),@tgname nvarchar(500)        
if @context='lead'                                                                        
begin                                                                        
select @parentid=parentid,@eventid=EventID,@entityid=leadid,@errormessage='' from                                                                         
tbl_LeadEventHistory(nolock) where historyid=@activityid                                                                        
select @mobile1=mobileno,@mobile2=mobileno1,@mobile3=mobileno2 ,@email1=emailid,@email2=emailid1,@email3=emailid2 from                                                                        
userleads(nolock) where id=@entityid                                                                        
end                                                                        
if @context='enquiry'                                                                        
begin                                                                        
select @parentid=parentid,@eventid=EventID,@entityid=enquiryid,@errormessage='' from                                                                         
tbl_EnquiryEventHistory(nolock) where historyid=@activityid                                                                        
select @mobile1=mobileno,@mobile2=mobileno1,@mobile3=mobileno2 ,@email1=emailid,@email2=emailid1,@email3=emailid2 from                                                                        
userenquiry(nolock) where EnquiryID=@entityid                                                                        
end                                                                        
if @context='conversationcontact'                                                                        
begin                                                                        
select @parentid=parentid,@eventid=EventID,@entityid=ConversationContactID,@errormessage='' from                                                                         
tbl_ContactEventHistory(nolock) where historyid=@activityid                                                                        
select @mobile1=mobile,@email1=emailid from                                                                        
conversationcontacts(nolock) where ID=@entityid                                                                        
end                                                                        
                  
if @cmpid is not null and @cmpid<>1                  
begin                  
select @isscheduledevent=1,@eventid=eventid from usercampaignmaster(nolock) where id=@cmpid --and eventid between 151 and 154                  
end                  
  
if @errormessage is null
begin
set @errormessage='Lead/Enquiry does not exist for this activity'
GOTO FINALEND
end


print concat('Eventid: ',@eventid,', Parentid: ',@parentid,', tcmpid: ',@tcmpid,', cmpid: ',@cmpid)
select 
ucm.ID,ucm.ParentID,ucm.CampaignName,ucm.IsEventBased,ucm.IsScheduled,ucm.Applicabilty,ucm.ExclusionsNumber,ucm.Exclusions,ucm.InclusionsNumber,ucm.AccountUsed,ucm.SenderID,                      
cast(ucm.Message as nvarchar(max)) 
Message,ucm.TemplateID,ucm.TemplateGroupID,ucm.IsUnicode,ucm.Medium,ucm.MailReplyTo,ucm.MailSubject,ucm.MailContent,ucm.TrackResponse,ucm.TrackShortURL,ucm.UnsubscribePage,                      
ucm.UnsubscribeShortURL,ucm.Tags,ucm.IsRunAfter,ucm.IsSchedule,ucm.ScheduleID,ucm.ExecutedDateTime,ucm.NextExecuteDateTime,ucm.IsActive,ucm.CreatedOn,ucm.Createdby,ucm.ModifiedOn,ucm.ModifiedBy,ucm.StartDate,ucm.ExpiryDate,ucm.EventsName,                 
     
ucm.ApplicabiltyGroupList,ucm.ExclusionsGroupList,ucm.NotificationMail,ucm.SuccessNotificationEmail,ucm.FailureNotificationEmail,ucm.IsRecurring,ucm.IsEnding,ucm.TemplateGroupSequence,ucm.IsNeverExpire,ucm.RunAtHours,ucm.RunAtMin,                      
ucm.IsSurplusExclusions,ucm.FromMailId,ucm.route,ucm.didno,ucm.appid,ucm.duration,ucm.credits,ucm.DLTTemplateID,ucm.mailroute,ucm.eventid,ucm.ContactType,t.id as triggeredcampaignid,
t.cname as triggeredcampaignname
 into #campaignstobeexecuted                                                                         
from usercampaignmaster(nolock) ucm                                                                         
Inner join  User_detail AS Ud  on Ud.[User_ID]= ucm.parentid and Ud.[Status] <> 0                                                                  
join triggeredcampaigns t on ucm.id in (t.smscampaignid,t.mailcampaignid,t.voicecampaignid,t.whatsappcampaignid)                                                                   
and t.isactive=1                                                                                                                    
join Price_UserSubscriptionDetails (nolock) p on p.UserID=ud.User_ID and user_id=ud.parentid and isnewplan=1 and PlanEndDate>=cast(getdate() as date)                                                       
where ucm.eventid=@eventid and ucm.IsEventBased=1                                                                        
and ucm.parentid=@parentid and ucm.IsActive=1 and isnull(ucm.StartDate,getdate())<=getdate()                    
and 
1=case when @tcmpid is not null and @tcmpid>0 and t.id=@tcmpid then 1
when @cmpid is null or @cmpid=1 then 1
when ucm.id=@cmpid then 1 
else 0 end                  
--and 1=case when @isscheduledevent=0 then 1                   
--else 0 end                  
 
 if not exists (select 1 from #campaignstobeexecuted)
 begin
set @errormessage='No active SMS/Mal/Voice/Whatsapp Campaign found for this activity'
GOTO FINALEND
 end

if exists(select 1 from #campaignstobeexecuted)                                                                
begin                                 
declare @c int=(select count(distinct id) from #campaignstobeexecuted),@id bigint=0,@medium nvarchar(20),@templategroupid int=0,                                           
@templateid int=0,@accountused bigint,@rowsaffected int=0,@creditsrequired numeric(18,4),@balance numeric(18,4),@contacttype nvarchar(10)                                        
,@wa_templatename nvarchar(100)                                                                  
declare @accountusedparentid bigint,@messagestring nvarchar(max)                                                             

while @c>0                                                                        
begin                                   
select top 1 @id=min(id) from #campaignstobeexecuted where id>@id                                                            
select @medium=medium,@templategroupid=templategroupid,@templateid=templateid,@accountused=accountused,@messagestring =case when medium='sms' then Message          
else mailcontent end,@tgcampid=triggeredcampaignid,@tgname=triggeredcampaignname          
,@rowsaffected=0,@creditsrequired=0,@balance=0 ,@contacttype=ContactType,@st_rules=0,@str_rules=''                                                                    
 from #campaignstobeexecuted where id=@id               
 select @accountusedparentid=parentid from user_detail (nolock) where user_id=@accountused                                                                        
 drop table if exists #applicablegroups                                                       
 drop table if exists #Exclusions                                                                     
 --drop table if exists #applicablegroups                    
                  
  declare @Status int = 0;                  
 -- Start applicability status                  
                   
   drop table if exists #temp1                   
   declare @Count1 int = 0, @RowIndex1 int = 0                     
   declare @temp1 table (rno int,value nvarchar(50))                   
   declare @applicabilty nvarchar(max) = ''                  
   select @applicabilty = Applicabilty from #campaignstobeexecuted where ID =  @id                  
   insert into @temp1(rno,value)                  
   select row_number() over( order by value asc) as rno, value  from fn_split(@applicabilty,'#')                   
   select @Count1 = COUNT(1) from @temp1                   
   drop table if exists #ApplicabilityStatus                  
   create table #ApplicabilityStatus(value nvarchar(50),Status int)                   
while(@Count1 > 0)                  
     Begin                  
    set @RowIndex1 = @RowIndex1 + 1                   
                      
     declare @value nvarchar(50) = '0'                   
     select @value = value from @temp1 where rno = @RowIndex1                     
                   
   exec Usp_ContactExistsInSearch @context,@entityid,@value,@Status output                   
   insert into #ApplicabilityStatus(Status,value)                    
   select @Status,@Value                     
                      
    set @Count1 = @Count1 -1                    
  End                   
delete from @temp1                                                                 

 select value as applicablegroups,0 as includedstatus into #applicablegroups from #campaignstobeexecuted                                                                          
cross apply dbo.fn_split(applicabilty,'#') where id=@id                  
update t1 set t1.includedstatus = t2.Status  from  #applicablegroups  as t1 join #ApplicabilityStatus as t2 on t1.applicablegroups = t2.value                   
                  
   -- end applicability status                   
                         
   -- Start exclusion status                  
                   
   drop table if exists #temp2                   
   declare @Count2 int = 0, @RowIndex2 int = 0                     
   declare @temp2 table (rno int,value nvarchar(50))                   
   declare @Exclusions nvarchar(max) = ''                  
   select @Exclusions = Exclusions from #campaignstobeexecuted where ID =  @id                  
   insert into @temp2(rno,value)                  
   select row_number() over( order by value asc) as rno, value  from fn_split(@Exclusions,'#')                   
   select @Count2 = COUNT(1) from @temp2                   
   drop table if exists #ExclusionStatus                  
   create table #ExclusionStatus(value nvarchar(50),Status int)                   
   while(@Count2 > 0)                  
    Begin                  
   set @RowIndex2 = @RowIndex2 + 1                   
                      
     declare @value_ex nvarchar(50) = '0'                   
     select @value_ex = value from @temp2 where rno = @RowIndex2                     
                   
   exec Usp_ContactExistsInSearch @context,@entityid,@value_ex,@Status output                   
   insert into #ExclusionStatus(Status,value)                    
   select @Status,@value_ex                     
                      
    set @Count2 = @Count2 -1                    
    End                       
 delete from @temp2              
                  
                                                                 
--select value as Exclusions,dbo.fn_contactexistsingroup(@context,@entityid,value) as includedstatus into #Exclusions from #campaignstobeexecuted                                                           
--cross apply dbo.fn_split(Exclusions,'#')  where id=@id                                                                        
                  
  select value as Exclusions,0 as includedstatus into #Exclusions from #campaignstobeexecuted                                                           
cross apply dbo.fn_split(Exclusions,'#')  where id=@id                                                                        
                  
    update t1 set t1.includedstatus = t2.Status  from  #Exclusions  as t1                  
                                       join #ExclusionStatus as t2                    
            on t1.Exclusions = t2.value                   
                  
                  
  -- end of exclusion status                  
        
--Added below code for triggered campaign rule matching        
exec usp_replaceplaceholders_withrules @tgcampid,null,@activityid,@context,@str_rules,@eventid,@str_rules output,        
@st_rules output         
print '@st:'+ cast (@st_rules as nvarchar)
if @st_rules<>1
 begin
set @errormessage=isnull(@errormessage+' ','')+'Triggered Campaign '+@tgname+' does not pass the rules. '
--GOTO FINALEND
end
if (exists (select 1 from #applicablegroups where includedstatus=1))  
begin  
print 'Campaign eligibility Applicability: pass'  
end  
if (not exists (select 1 from #exclusions where includedstatus=1))   
begin  
print 'Campaign eligibility Not Excluded: pass'  
end  
if @st_rules=1  
begin  
print 'Campaign eligibility Rules: pass'  
end  

if (exists (select 1 from #applicablegroups where includedstatus=1))                                                                        
and (not exists (select 1 from #exclusions where includedstatus=1)) and @st_rules=1             
begin       
print 'Campaigns are Eligible'      
declare @jobid bigint=isnull((select max(jobid) from usercampaignhistory(nolock)),0)+1                                                                        
declare @uchid bigint,@ucehid bigint                                                                        
INSERT INTO usercampaignhistory                                                                 
   ( campaignid,parentid, step1, step2,step3,issms,ismail,isvoice,iswhatsapp,isscheduled,iseventbased,createdon,JobId,activityid )                                                                                                         
SELECT id,parentid,0 as step1,0 as step2,0 as step3,case when medium='sms' then 1 when medium='voice' then 2 else 0 end,                                                                        
case when medium='mail' then 1 else 0 end,case when medium='voice' then 1 else 0 end,case when medium='whatsapp' then 1 else 0 end,isscheduled,iseventbased,getdate(),@jobid as JobId,@activityid                                                             
from #campaignstobeexecuted where id=@id                               
select @uchid=scope_identity()                                                                        
                                                                        
insert into Usercampaignexecutionhistory(CampaignID,ParentID,Jobid)                                                                        
select @id,@parentid,@jobid                                                        
select @ucehid=scope_identity()                                                                        
                                                                      
if isnull(@templategroupid,0)<>0                                                                        
begin                                       
select @templateid=dbo.fn_getnexttemplateidingroup(@id)                          
end                                                                      
          
declare @eventdescription nvarchar(2000),@eventname nvarchar(100),@s_bid bigint,@m_bid bigint,@v_bid bigint,@w_bid bigint--UspSaveEntityActivity_withid @entity,@Entityid,@parentid,@parentid,          
          
if @medium in ('sms','mail')           
and ((isnull(@templateid,0)=0  or not exists(select 1 from usermailtemplate(nolock) where id=@templateid) )                      
and isnull(@messagestring,'')=''          
)                    
begin 
print 'Entered execution'
update u set step1=0,Step1DateTime=GETDATE(), Step1Recipients=0,                                                                        
u.ReasonIfNotRun=case when isnull(@templateid,0)=0 then 'No templateid eligible' else 'Template does not exist' end                          
from UserCampaignHistory u where u.id=@uchid                                 
UPDATE Kd SET isrecipients=1,executiontime=getdate(),isexecuted=0,NoOfRecipients=@rowsaffected,                                                                        
response=case when isnull(@templateid,0)=0 then 'No templateid eligible' else 'Template does not exist' end                         
FROM Usercampaignexecutionhistory Kd  where kd.id=@ucehid                                                                        
set @errormessage=isnull(@errormessage+' ','')+'Triggered Campaign '+@tgname+' failed as it does not contain an eligible template for '+
case when @medium='sms' then 'SMS. ' when @medium='mail' then 'mail. ' end
print @errormessage
GOTO ENDPROC                                                                        
end                                                                 
                        
if @medium='sms'                                       
begin                                                          
if 1=1--@parentid=  34594                                                   
begin                         
select @messagestring=cast(case when isnull(c.message,'')<>'' then cast(c.message as nvarchar(max))                                                      
when @templateid<>0 then cast((select MailContent from UserMailTemplate(nolock) where id=@templateid)                                                                          
AS NVARCHAR(MAX)) end COLLATE Latin1_general_ci_ai AS NVARCHAR(MAX)) from #campaignstobeexecuted c where id=@id         
        
exec usp_replaceplaceholders @activityid,@context,@messagestring,@eventid,@messagestring output                                                     
exec usp_replaceentityplaceholders @entityid,@context,@messagestring, @messagestring   output                           
update #campaignstobeexecuted set message=@messagestring where id=@id                                                      
end                                  
                                                  
