when isnull(c.message,'')<>'' and @context ='lead' then (select dbo.[fn_getLeadsMailMessage_withid](@accountusedparentid,c.message,@entityid))                                                                         
when @templateid<>0 and @context ='enquiry' then (select dbo.[fn_getEnquiryMessageMail_withid](@accountusedparentid,MailContent,@entityid)                                                                        
from UserMailTemplate(nolock) where id=@templateid)                                                                        
when @templateid<>0 and @context ='lead' then (select dbo.[fn_getLeadsMailMessage_withid](@accountusedparentid,MailContent,@entityid)                                              
from UserMailTemplate(nolock) where id=@templateid) end                                                                  
AS NVARCHAR(MAX)) COLLATE Latin1_general_ci_ai AS NVARCHAR(MAX)),c.senderid COLLATE Latin1_general_ci_ai,                                                                        
case when @templateid=0 then c.isunicode else (select isunicode from usermailtemplate (nolock) where id=@templateid) end                                      
from #campaignstobeexecuted c                                                                         
cross apply dbo.fn_split(cast(coalesce(@mobile1,'') as nvarchar(20))+','+                                                                        
cast(coalesce(@mobile2,'') as nvarchar(20))+','+cast(coalesce(@mobile3,'') as nvarchar(20)),',')                                                                        
--left join usermailtemplate umt (nolock) on umt.id=c.TemplateID                                 
where value<>'' and isnumeric(value)=1 and id=@id                                                                       
set @rowsaffected=@@ROWCOUNT                                                                        
print 'Entered usercampaignexecutionrecipientsmessageTest2 with rows: '+cast(@rowsaffected as nvarchar)
                                                                        
if @rowsaffected>0                                                                        
begin
update kd set kd.len=len(message),kd.credits=case when isunicode=0 and len(message)<=160  then 1 when isunicode=0 and LEN(message)>160  
then ceiling(LEN(message)/cast(153 as float)) when IsUniCode=1 and len(message)<=70                                                                         
then 1 else ceiling(LEN(message)/cast(67 as float))                                                                          
end                                                                                      
FROM usercampaignexecutionrecipientsmessageTest2 Kd where jobid=@jobid                                                                        
                                             
--select @creditsrequired=sum(credits) from usercampaignexecutionrecipientsmessageTest2(nolock) where jobid=@jobid                     
--select top 1 @balance=balance from credit_details(nolock) where user_id=@accountused order by credit_id desc              
select @creditsrequired=sum(credits)*(select top 1 PTrns from Price_Base_SMS_RateDeduction(nolock) where DestinationCountryCode='+91'  ) from usercampaignexecutionrecipientsmessageTest2(nolock) where jobid=@jobid                     
select @balance=dbo.GetAvailableBalanceForService(@parentid,21)


if @balance<@creditsrequired                                                                 
begin                                                                        
set @errormessage=isnull(@errormessage+' ','')+'Triggered Campaign '+@tgname+' for SMS failed due to insufficient balance. '
print concat('Error message: insufficient bal',isnull(@errormessage,'') )                                                                          
end

                                                                        
if @balance>=@creditsrequired                                                                 
begin                                                                        
 begin tran                                                      
 declare @smsbatchid bigint                                                                        
