join user_detail u(nolock) on u.User_ID=Ucerm.u_id                               
WHERE  Ucerm.mobile <> '' AND ucerm.jobid=@jobid                                                                                          
print 'Entered #clonemessagedeliverystatus'

if not exists(select 1 from #clonemessagedeliverystatus)
begin
set @errormessage=isnull(@errormessage+' ','')+'Triggered Campaign '+@tgname+' for SMS failed due to no valid mobile no. '
print concat('Error message: no valid mobile ',isnull(@errormessage,'') )                                                                          
end
                                                       
 /*Creating indexes for temp table to improve the performance*/                                              
                                   
