INSERT INTO clonemessagedeliverystatus                                              
(batchid,mobile,[message],messagestatus,senderid,messageinsertdate,scheduleddate,scheduledtime,smppid,u_id,isunicode,isdnd,isairtel,mobilesubset,validno,isprority,    
isallowdnd,dbtype,campaignid,sms_source)                                                                   
SELECT batchid,mobile,[message],messagestatus,senderid,GETDATE(),ScheduledDate,ScheduledTime,smppid,u_id,isnull(isunicode,0),isdnd,isairtel,mobilesubset,validno,    
isprority,isallowdnd,dbtype,CampaignID,'Campaign :'+isnull(cast(campaignid as nvarchar),'')                                                           
 FROM   #clonemessagedeliverystatus Ucerm                                          
set @errormessage=isnull(@errormessage+' ','')+'Triggered Campaign '+@tgname+' for sending SMS is executed. '
print concat('Error message: ',isnull(@errormessage,'') )                                                                          
 delete FROM #clonemessagedeliverystatus                                                                         
                                                                                           
COMMIT                                                                                                                   
END TRY                                                                                                       
BEGIN CATCH                                                                                                          
IF @@TRANCOUNT>0                                                                               
ROLLBACK                                                                                                         
EXECUTE USP_INSERTERRORINFO;                                                                                
IF ERROR_NUMBER() = 1205 -- Deadlock Error Number                                                                                            
BEGIN                                                                                            
WAITFOR DELAY '00:00:00.05' -- Wait for 5 ms                                                                                            
GOTO RETRY -- Go to Label RETRY                                                                                            
END                                                                    
END CATCH                                                                                             
end                                                           
else                                                                         
begin                                                                        
update u set step1=1,Step2 = 1,Step2DateTime=GETDATE(), Step2Recipients=@rowsaffected,                                                                        
Step1DateTime=GETDATE(), Step1Recipients=@rowsaffected,                                 
u.ReasonIfNotRun='Insufficient Balance' from UserCampaignHistory u where                                                                         
u.id=@uchid                                                                        
UPDATE Kd SET isrecipients=1,executiontime=getdate(),Ismessages = 1,isexecuted=0,NoOfRecipients=@rowsaffected,                                                                        
batchid=@smsbatchid,response='Insufficient Balance' FROM  Usercampaignexecutionhistory Kd  where kd.id=@ucehid                                                  
GOTO ENDPROC                                              
end                                                                        
end                                                                        
