select top 1 @balance=dbo.GetAvailableBalanceForService(@parentid,11)


if @balance>=@creditsrequired
begin
declare @wabatchid bigint                               
begin tran                                                                        
INSERT INTO Getbatchrecord                                                                                                                                      
([User_id],RandNum)                                                                                           
SELECT @id,@parentid                                                                        
select @wabatchid=scope_identity()                                                                        
                                            
delete From GetBatchRecord where batchid=@wabatchid                                                                                        
commit                                                                                     
insert into WBatchInfo(ParentID,BatchID,TotalRecords,IsProcess,BatchInsertTime,BatchProcessTime,ScheduledDate,templateid,campaignid                                                                  
,CreatedBy,uchid,trigerringactivityid)                        
select @parentid,@wabatchid,1,0,getdate(),getdate(),null,@templateid,@id,@parentid,@uchid,@activityid                
set @rowsaffected=@@ROWCOUNT             
set @errormessage=isnull(@errormessage+' ','')+'Triggered Campaign '+@tgname+' for sending Whatsapp is executed. '
print @errormessage                                                                           

          
/*Added new code below to generate lead activity with other actions*/          
 select top 1 @eventdescription=cast(u.user_login as nvarchar) +' sent whatsapp template named '          
 +@wa_templatename+'.The template was sent automatically through triggered campaign named '+ c.CampaignName,          
 @eventname= 'Whatsapp template sent to '+@context,@w_bid=@wabatchid          
 from user_detail u(nolock) join UserCampaignMaster c(nolock) on c.ID=@id and c.ParentID=u.User_ID          
 --where m.entityname=@context and isnull(m.entityid,0)<>0          
          
exec UspSaveEntityActivity_withid @context,@entityid,@parentid,@PARENTID,@eventdescription,@eventname,'WBatchinfo',@w_bid          
          
                                                              
--if @context='lead'                                                              
-- begin                                                              
-- insert into tbl_leadeventhistory(LeadID,UserID,ParentID,EventDescription,EventID,reftables,refids)                                                              
-- select @entityid,c.parentid,c.ParentID,                                                    
--cast(u.user_login as nvarchar(max)) +' sent whatsapp template named '+@wa_templatename+'.The template was sent automatically through triggered campaign named '+ c.CampaignName,                                         
--dbo.fn_geteventid('Whatsapp template sent to enquiry'),'WBatchinfo',@wabatchid                                                                                
--from user_detail u join UserCampaignMaster c on c.ID=@id and c.ParentID=u.User_ID                                                                                           
-- end                                                              
-- if @context='enquiry'                                                              
-- begin                                           
--insert into tbl_enquiryeventhistory(enquiryID,UserID,ParentID,EventDescription,EventID,reftables,refids)                                                   
-- select @entityid,c.parentid,c.ParentID,                                                               
--cast(u.user_login as nvarchar(max)) +' sent whatsapp template named '+@wa_templatename+'.The template was sent automatically through triggered campaign named '+ c.CampaignName,                                                                  
--dbo.fn_geteventid('Whatsapp template sent to enquiry'),'WBatchinfo',@wabatchid                                                                                
--from user_detail u join UserCampaignMaster c on c.ID=@id and c.ParentID=u.User_ID                                        
-- end                                                         
                  
end
else
begin
set @errormessage=isnull(@errormessage+' ','')+'Triggered Campaign '+@tgname+' for whatsapp failed due to Insufficient Balance.'
GOTO ENDPROC                                                                        
end
end
else                                                                         
begin                                                                        
update u set step1=1,Step2 = 1,Step2DateTime=GETDATE(), Step2Recipients=@rowsaffected,                                                                        
Step1DateTime=GETDATE(), Step1Recipients=@rowsaffected,                                                               
u.ReasonIfNotRun='No active whatsapp business api ' from UserCampaignHistory u where                                                                         
u.id=@uchid                                                          
UPDATE Kd SET isrecipients=1,executiontime=getdate(),Ismessages = 1,isexecuted=0,NoOfRecipients=@rowsaffected,                                                                        
batchid=@smsbatchid,response='No active whatsapp business api ' FROM  Usercampaignexecutionhistory Kd  where kd.id=@ucehid 
set @errormessage=isnull(@errormessage+' ','')+'Triggered Campaign '+@tgname+' for Whatsapp failed since no active whatsapp business api was found. '
print @errormessage                                                                           

GOTO ENDPROC                                                                        
end

end
                        
declare @orderno int=(select orderno from usergrouptemplatemix(nolock) where groupid=@templategroupid and templateid=@templateid)                                                                        
UPDATE Kd SET isrecipients=1,Ismessages = 1,templatesequence=case when isnull(@templategroupid,0)<>0 then @orderno end,                                                                        
templateid =@templateid,ExecutionTime=getdate(),                                                                                                                         
isexecuted=1,NoOfRecipients=@rowsaffected,batchid=case when @medium='sms' then @smsbatchid                                                                
when @medium='mail' then @mailbatchid when @medium='voice' then @voicebatchid when @medium='Whatsapp' then @wabatchid                                                                  
end FROM Usercampaignexecutionhistory Kd                                                                                  
where Kd.ID = @ucehid                                                                                        
update u set step1=1,Step2 = 1,step3=1,Step2DateTime=GETDATE(),Step3DateTime=GETDATE(),Step2Recipients=@rowsaffected,                                                                        
Step1DateTime=GETDATE(), Step1Recipients=@rowsaffected,Step3Recipients=@rowsaffected,activityid=@activityid from UserCampaignHistory u where                                                                         
u.id=@uchid                                                                        
update ucm set executeddatetime=getdate(),                                                                        
TemplateGroupSequence= case when @templategroupid<>0 and isending=0 then @orderno                                      
else templategroupsequence end                                                                         
from UserCampaignmaster ucm where ucm.id=@id                                                                        
end                            
else
begin
print 'Campaign is not eligible'  
set @errormessage=isnull(@errormessage+' ','')+'Triggered Campaign '+@tgname+' audience does not include the Lead/Enquiry. '
print @errormessage                                                                           

end

ENDPROC:    
set @c = @c-1   
end                                                                  
end 
FINALEND:
print 'Errormessage: '+@errormessage
end



GO

/* ============================================================
   Procedure: [dbo].[usp_executeeventcampaign_1]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_executeeventcampaign_1]  --'lead',445403        
@context nvarchar(20),@activityid bigint          
as          
begin    
drop table if exists #campaignstobeexecuted          
drop table if exists #applicablegroups          
drop table if exists #Exclusions    
DECLARE @sqlquery NVARCHAR(MAX);
DECLARE @hasActiveToken bigint;
          
declare @parentid bigint,@eventid int,@entityid bigint, @mobile1 nvarchar(20),@mobile2 nvarchar(20),@mobile3 nvarchar(20),          
@email1 nvarchar(100),@email2 nvarchar(100),@email3 nvarchar(100)          
if @context='lead'          
begin          
select @parentid=parentid,@eventid=EventID,@entityid=leadid from           
tbl_LeadEventHistory(nolock) where historyid=@activityid          
select @mobile1=mobileno,@mobile2=mobileno1,@mobile3=mobileno2 ,@email1=emailid,@email2=emailid1,@email3=emailid2 from          
userleads(nolock) where id=@entityid          
end          
if @context='enquiry'          
begin          
select @parentid=parentid,@eventid=EventID,@entityid=enquiryid from           
tbl_EnquiryEventHistory(nolock) where historyid=@activityid          
select @mobile1=mobileno,@mobile2=mobileno1,@mobile3=mobileno2 ,@email1=emailid,@email2=emailid1,@email3=emailid2 from          
userenquiry(nolock) where EnquiryID=@entityid          
end          
if @context='conversationcontact'          
begin          
select @parentid=parentid,@eventid=EventID,@entityid=ConversationContactID from           
tbl_ContactEventHistory(nolock) where historyid=@activityid          
select @mobile1=mobile,@email1=emailid from          
conversationcontacts(nolock) where ID=@entityid          
end          
          
select ucm.* into #campaignstobeexecuted           
from usercampaignmaster(nolock) ucm           
Inner join  User_detail AS Ud  on Ud.[User_ID]= AccountUsed and Ud.[Status] <> 0    
join triggeredcampaigns t on ucm.id in (t.smscampaignid,t.mailcampaignid,t.voicecampaignid,t.whatsappcampaignid)     
and t.isactive=1                                                      
where ucm.eventid=@eventid and ucm.IsEventBased=1          
and ucm.parentid=@parentid and ucm.IsActive=1 and ucm.StartDate<=getdate()          
          
if exists(select 1 from #campaignstobeexecuted)          
begin          
declare @c int=(select count(distinct id) from #campaignstobeexecuted),@id bigint=0,@medium nvarchar(20),@templategroupid int=0,          
@templateid int=0,@accountused bigint,@rowsaffected int=0,@creditsrequired numeric(18,2),@balance numeric(18,2),@contacttype nvarchar(10)          
,@wa_templatename nvarchar(100)    
declare @accountusedparentid bigint          
          
while @c>0          
begin          
select top 1 @id=min(id) from #campaignstobeexecuted where id>@id          
select @medium=medium,@templategroupid=templategroupid,@templateid=templateid,@accountused=accountused          
,@rowsaffected=0,@creditsrequired=0,@balance=0 ,@contacttype=ContactType         
 from #campaignstobeexecuted where id=@id          
 select @accountusedparentid=parentid from user_detail (nolock) where user_id=@accountused          
 drop table if exists #applicablegroups       
 drop table if exists #Exclusions       
 --drop table if exists #applicablegroups       

  declare @Status int = 0;
 -- Start applicability status
 
   drop table if exists #temp1 
   declare @Count1 int = 0, @RowIndex1 int = 0   
   declare @temp1 table (rno int,value nvarchar(50)) 
   declare @applicabilty nvarchar(max) = ''
   select @applicabilty = Applicabilty from #campaignstobeexecuted where ID =  @id
   insert into @temp1(rno,value)
   select row_number() over( order by value asc) as rno, value  from fn_split(@applicabilty,'#') 
   select @Count1 = COUNT(1) from @temp1 
   drop table if exists #ApplicabilityStatus
   create table #ApplicabilityStatus(value nvarchar(50),Status int) 
   while(@Count1 > 0)
     Begin
	   set @RowIndex1 = @RowIndex1 + 1 
	   
	    declare @value nvarchar(50) = '0' 
	    select @value = value from @temp1 where rno = @RowIndex1   
	
		 exec Usp_ContactExistsInSearch @context,@entityid,@value,@Status output 
		 insert into #ApplicabilityStatus(Status,value)  
		 select @Status,@Value   
	   
	   set @Count1 = @Count1 -1  
  End 

--select value as applicablegroups,dbo.fn_contactexistsingroup(@context,@entityid,value) as includedstatus into #applicablegroups from #campaignstobeexecuted           
--cross apply dbo.fn_split(applicabilty,'#') where id=@id  

 select value as applicablegroups,0 as includedstatus into #applicablegroups from #campaignstobeexecuted                                                        
cross apply dbo.fn_split(applicabilty,'#') where id=@id

    update t1 set t1.includedstatus = t2.Status  from  #applicablegroups  as t1
	                                      join #ApplicabilityStatus as t2  
										  on t1.applicablegroups = t2.value 

   -- end applicability status 

   -- Start exclusion status

   drop table if exists #temp2 
   declare @Count2 int = 0, @RowIndex2 int = 0   
   declare @temp2 table (rno int,value nvarchar(50)) 
   declare @Exclusions nvarchar(max) = ''
   select @Exclusions = Exclusions from #campaignstobeexecuted where ID =  @id
   insert into @temp2(rno,value)
   select row_number() over( order by value asc) as rno, value  from fn_split(@Exclusions,'#') 
   select @Count2 = COUNT(1) from @temp2 
   drop table if exists #ExclusionStatus
   create table #ExclusionStatus(value nvarchar(50),Status int) 
   while(@Count2 > 0)
    Begin
	  set @RowIndex2 = @RowIndex2 + 1 
	   
	    declare @value_ex nvarchar(50) = '0' 
	    select @value_ex = value from @temp2 where rno = @RowIndex2   
	
		 exec Usp_ContactExistsInSearch @context,@entityid,@value_ex,@Status output 
		 insert into #ExclusionStatus(Status,value)  
		 select @Status,@value_ex   
	   
	   set @Count2 = @Count2 -1  
    End 

--	select value as Exclusions,dbo.fn_contactexistsingroup(@context,@entityid,value) as includedstatus into #Exclusions from #campaignstobeexecuted           
--cross apply dbo.fn_split(Exclusions,'#')  where id=@id 

	  select value as Exclusions,0 as includedstatus into #Exclusions from #campaignstobeexecuted                                         
cross apply dbo.fn_split(Exclusions,'#')  where id=@id                                                      

    update t1 set t1.includedstatus = t2.Status  from  #Exclusions  as t1
	                                      join #ExclusionStatus as t2  
										  on t1.Exclusions = t2.value 
  -- end of exclusion status
        


         
if (exists (select 1 from #applicablegroups where includedstatus=1))          
and (not exists (select 1 from #exclusions where includedstatus=1))          
begin          
declare @jobid bigint=isnull((select max(jobid) from usercampaignhistory(nolock)),0)+1          
declare @uchid bigint,@ucehid bigint          
INSERT INTO usercampaignhistory   
   ( campaignid,parentid, step1, step2,step3,issms,ismail,isvoice,iswhatsapp,isscheduled,iseventbased,createdon,JobId,activityid )                                           
SELECT id,parentid,0 as step1,0 as step2,0 as step3,case when medium='sms' then 1 when medium='voice' then 2 else 0 end,          
case when medium='mail' then 1 else 0 end,case when medium='voice' then 1 else 0 end,case when medium='whatsapp' then 1 else 0 end,isscheduled,iseventbased,getdate(),@jobid as JobId,@activityid          
from #campaignstobeexecuted where id=@id          
select @uchid=scope_identity()          
          
insert into Usercampaignexecutionhistory(CampaignID,ParentID,Jobid)          
select @id,@parentid,@jobid          
select @ucehid=scope_identity()          
        
if isnull(@templategroupid,0)<>0          
begin          
select @templateid=dbo.fn_getnexttemplateidingroup(@id)          
if @templateid=0          
begin          
update u set step1=0,Step1DateTime=GETDATE(), Step1Recipients=0,          
u.ReasonIfNotRun='No templateid eligible' from UserCampaignHistory u where           
u.id=@uchid          
UPDATE Kd SET isrecipients=1,executiontime=getdate(),isexecuted=0,NoOfRecipients=@rowsaffected,          
response='No templateid eligible' FROM             
Usercampaignexecutionhistory Kd  where kd.id=@ucehid          
GOTO ENDPROC          
end          
end          
          
if @medium='sms'          
begin          
INSERT INTO usercampaignexecutionrecipientsmessageTest2(Entityname,Entityid,mobile,parentid,campaignid,u_id,JobId,message          
,senderid,isunicode)                                                    
SELECT @context,@entityid,value as mobile,c.parentid,c.id,AccountUsed,@jobid,          
cast(cast(case when @templateid=0 then c.message           
when @templateid<>0 and @context ='enquiry' then (select dbo.[fn_getEnquiryMessageMail_withid](@accountusedparentid,MailContent,@entityid)          
from UserMailTemplate(nolock) where id=@templateid)          
when @templateid<>0 and @context ='lead' then (select dbo.[fn_getLeadsMailMessage_withid](@accountusedparentid,MailContent,@entityid)          
from UserMailTemplate(nolock) where id=@templateid) end           
AS NVARCHAR(MAX)) COLLATE Latin1_general_ci_ai AS NVARCHAR(MAX)),c.senderid COLLATE Latin1_general_ci_ai,          
case when @templateid=0 then c.isunicode else (select isunicode from usermailtemplate (nolock) where id=@templateid) end          
from #campaignstobeexecuted c           
cross apply dbo.fn_split(cast(coalesce(@mobile1,'') as nvarchar(20))+','+          
cast(coalesce(@mobile2,'') as nvarchar(20))+','+cast(coalesce(@mobile3,'') as nvarchar(20)),',')          
--left join usermailtemplate umt (nolock) on umt.id=c.TemplateID          
where value<>'' and isnumeric(value)=1 and id=@id         
set @rowsaffected=@@ROWCOUNT          
          
if @rowsaffected>0          
begin          
update kd set kd.len=len(message),kd.credits=case when isunicode=0 and len(message)<=160  then 1 when isunicode=0 and LEN(message)>160           
then ceiling(LEN(message)/cast(153 as float)) when IsUniCode=1 and len(message)<=70           
then 1 else ceiling(LEN(message)/cast(67 as float))            
end                         
FROM usercampaignexecutionrecipientsmessageTest2 Kd where jobid=@jobid          
          
select @creditsrequired=sum(credits) from usercampaignexecutionrecipientsmessageTest2(nolock) where jobid=@jobid          
select top 1 @balance=balance from credit_details(nolock) where user_id=@accountused order by credit_id desc          
          
if @balance>=@creditsrequired          
begin          
 begin tran                            
 declare @smsbatchid bigint          
INSERT INTO Getbatchrecord                                                                        
([User_id],RandNum)                             
SELECT @id,@parentid          
select @smsbatchid=scope_identity()          
                                 
delete From GetBatchRecord where batchid=@smsbatchid                          
commit                                                
          
update b set batchid=@smsbatchid from Link_smsUrl_dtl b (nolock) where b.ccid = @id           
  
drop table if exists  #clonemessagedeliverystatus        
SELECT DISTINCT entityname,entityid, @smsbatchid as batchid,Ucerm.mobile,Ucerm.[message],Ucerm.messagestatus,Ucerm.senderid,          
Ucerm.messageinsertdate,'' as scheduleddate,'' as scheduledtime,U.smppid,Ucerm.u_id,Ucerm.isunicode,Ucerm.isdnd,Ucerm.isairtel,          
Ucerm.mobilesubset,Ucerm.validno,Ucerm.isprority,Ucerm.isallowdnd,Ucerm.dbtype,@ID as campaignid,@rowsaffected as RCount           
into #clonemessagedeliverystatus                              
FROM   usercampaignexecutionrecipientsmessageTest2 Ucerm (nolock)                               
join user_detail u(nolock) on u.User_ID=Ucerm.u_id                                  
WHERE  Ucerm.mobile <> '' AND ucerm.jobid=@jobid                            
                             
 /*Creating indexes for temp table to improve the performance*/                            
                             
 CREATE NONCLUSTERED INDEX IX_#clonemessagedeliverystatus1 ON #clonemessagedeliverystatus(                            
 batchid,mobile,messagestatus,senderid,messageinsertdate)                            
                             
 CREATE NONCLUSTERED INDEX IX_#clonemessagedeliverystatus2 ON #clonemessagedeliverystatus(                            
 smppid,u_id,isunicode,isdnd,isairtel,mobilesubset)                                   
                             
 CREATE NONCLUSTERED INDEX IX_#clonemessagedeliverystatus3 ON #clonemessagedeliverystatus(                            
 validno,isprority,isallowdnd,dbtype,CampaignID,RCount)                            
                             
                             
 /*End index creation*/                          
 if @context='lead'
 begin
 insert into tbl_leadeventhistory(LeadID,UserID,ParentID,EventDescription,EventID,reftables,refids)
 select distinct entityid,m.u_id,u.ParentID, cast(u.user_login as nvarchar(max)) +' sent a SMS with senderid '+cast(ltrim(rtrim(m.SenderID)) as nvarchar(max))+ ' and message text '+cast(m.message as nvarchar(max))+' to mobile '+cast            
(m.mobile as nvarchar(max)) +' through automated campaign named ' + c.CampaignName,dbo.fn_geteventid('SMS sent to lead'),'Batchinfo',m.BatchID                  
from user_detail u join #clonemessagedeliverystatus m on m.u_id=u.User_ID                  
join UserCampaignMaster c on c.ID=m.CampaignID                  
where entityname=@context and isnull(entityid,0)<>0
 end
 if @context='enquiry'
 begin
insert into tbl_enquiryeventhistory(enquiryID,UserID,ParentID,EventDescription,EventID,reftables,refids)
 select distinct entityid,m.u_id,u.ParentID, cast(u.user_login as nvarchar(max)) +' sent a SMS with senderid '+cast(ltrim(rtrim(m.SenderID)) as nvarchar(max))+ ' and message text '+cast(m.message as nvarchar(max))+' to mobile '+cast            
(m.mobile as nvarchar(max)) +' through automated campaign named ' + c.CampaignName,dbo.fn_geteventid('SMS sent to enquiry'),'Batchinfo',m.BatchID                  
from user_detail u join #clonemessagedeliverystatus m on m.u_id=u.User_ID                  
join UserCampaignMaster c on c.ID=m.CampaignID                  
where entityname=@context and isnull(entityid,0)<>0
 end

--declare @tbl_activity as dbo.LeadActivitywithid_Tbltype              
--insert into @tbl_activity( LeadID , UserID, ParentID , EventDescription , EventName,reftable,refid)                             
--select distinct entityid,m.u_id,u.ParentID, cast(u.user_login as nvarchar(max)) +' sent a SMS with senderid '+cast(ltrim(rtrim(m.SenderID)) as nvarchar(max))+ ' and message text '+cast(m.message as nvarchar(max))+' to mobile '+cast            
--(m.mobile as nvarchar(max)) +' through automated campaign named ' + c.CampaignName,'SMS sent to '+@context,'Batchinfo',m.BatchID                  
--from user_detail u join #clonemessagedeliverystatus m on m.u_id=u.User_ID                  
--join UserCampaignMaster c on c.ID=m.CampaignID                  
--where entityname=@context and isnull(entityid,0)<>0                           
--exec UspSaveEntityActivity_withMultipleValue_withid @tbl_activity   
           
RETRY:                                                                       
BEGIN TRY                                                                    
BEGIN TRAN                               
declare @DLT_TemplateID nvarchar(50)=case when isnull(@templateid,0) =0 then (select DLTTemplateID from #campaignstobeexecuted where id=@id)            
else (select DLT_Templateid from UserMailTemplate(nolock) where id=@templateid) end          
           
insert into DLT_Template_MSG(batchid,DLT_TemplateID)            
select @smsbatchid,@DLT_TemplateID            
            
INSERT INTO clonemessagedeliverystatus                                                
(batchid,mobile,[message],messagestatus,senderid,messageinsertdate,scheduleddate,scheduledtime,smppid,u_id,isunicode,isdnd,isairtel,mobilesubset,validno,isprority,isallowdnd,dbtype,campaignid)                                            
SELECT batchid,mobile,[message],messagestatus,senderid,GETDATE(),ScheduledDate,ScheduledTime,smppid,u_id,isunicode,isdnd,isairtel,mobilesubset,validno,isprority,isallowdnd,dbtype,CampaignID          
 FROM   #clonemessagedeliverystatus Ucerm           
             
 delete FROM #clonemessagedeliverystatus           
                             
-- select @@TRANCOUNT                              
--IF @@TRANCOUNT>0                                                                    
COMMIT                                                                    
END TRY                                                                    
BEGIN CATCH                                            
IF @@TRANCOUNT>0                                                                    
ROLLBACK                                               
EXECUTE USP_INSERTERRORINFO;                               
IF ERROR_NUMBER() = 1205 -- Deadlock Error Number                              
BEGIN                              
WAITFOR DELAY '00:00:00.05' -- Wait for 5 ms                              
GOTO RETRY -- Go to Label RETRY                              
END                                                                         
END CATCH                               
end          
else           
begin          
update u set step1=1,Step2 = 1,Step2DateTime=GETDATE(), Step2Recipients=@rowsaffected,          
Step1DateTime=GETDATE(), Step1Recipients=@rowsaffected,          
u.ReasonIfNotRun='Insufficient Balance' from UserCampaignHistory u where           
u.id=@uchid          
UPDATE Kd SET isrecipients=1,executiontime=getdate(),Ismessages = 1,isexecuted=0,NoOfRecipients=@rowsaffected,          
batchid=@smsbatchid,response='Insufficient Balance' FROM  Usercampaignexecutionhistory Kd  where kd.id=@ucehid          
GOTO ENDPROC          
end          
end          
DELETE FROM usercampaignexecutionrecipientsmessageTest2 WHERE jobid=@jobid                              
drop table if exists #clonemessagedeliverystatus          
end          
if @medium='mail'          
begin          
          
INSERT INTO EmailsfiltercampaignexecutionTEST2(Entityname,Entityid,Mail_GUID,Mail_FromEmail,Mail_ToEmail,Mail_UserID,          
Mail_InsertedDate,ParentID,CampaignID,JobId,Messages,Mail_Subject,Mail_Priority,mailroute)                
SELECT @context,@Entityid,NEWID(),isnull(c.FromMailId,'contactus@email19.in'),value as EmailID,@AccountUsed,GETDATE(),@ParentID,c.ID,@JobId,          
cast(cast(case when @templateid=0 then c.message           
when @templateid<>0 and @context ='enquiry' then (select dbo.[fn_getEnquiryMessageMail_withid]( c.ParentID,MailContent,@entityid)          
from UserMailTemplate(nolock) where id=@templateid)          
when @templateid<>0 and @context ='lead' then (select dbo.[fn_getLeadsMailMessage_withid]( c.ParentID,MailContent,@entityid)          
from UserMailTemplate(nolock) where id=@templateid) end           
AS NVARCHAR(MAX)) COLLATE Latin1_general_ci_ai AS NVARCHAR(MAX)),          
cast(cast(case when @templateid=0 then c.MailSubject           
when @templateid<>0 and @context ='enquiry' then (select dbo.[fn_getEnquiryMessageMail_withid]( c.ParentID,MailSubject,@entityid)          
from UserMailTemplate(nolock) where id=@templateid)          
when @templateid<>0 and @context ='lead' then (select dbo.[fn_getLeadsMailMessage_withid]( c.ParentID,MailSubject,@entityid)          
from UserMailTemplate(nolock) where id=@templateid) end           
AS NVARCHAR(MAX)) COLLATE Latin1_general_ci_ai AS NVARCHAR(MAX)),2 as mail_priority,'T'          
from #campaignstobeexecuted c           
cross apply dbo.fn_split(cast(coalesce(@email1,'') as nvarchar(200))+','+          
cast(coalesce(@email2,'') as nvarchar(200))+','+cast(coalesce(@email3,'') as nvarchar(200)),',')          
where value<>''   and id=@id         
set @rowsaffected=@@ROWCOUNT          
          
if @rowsaffected>0          
begin          
select @creditsrequired=sum(case when datalength(messages)<=100 then 1 else 1+cast(ceiling(datalength(messages)/cast(200 as float)) as int) end)              
from EmailsfiltercampaignexecutionTEST2(nolock) where jobid=@jobid          
select top 1 @balance= balance from  mailcreditdetails (nolock) where user_id=@parentid order by credit_id desc          
          
if @balance>=@creditsrequired          
begin          
 begin tran                            
 declare @mailbatchid bigint          
INSERT INTO Getbatchrecord                                                                        
([User_id],RandNum)                             
SELECT @id,@parentid          
select @mailbatchid=scope_identity()          
                                 
delete From GetBatchRecord where batchid=@mailbatchid                          
commit                  
   
 drop table if exists  #cloneemail         
select mail_guid,entityname,entityid,Mail_FromEmail,Mail_ToEmail,Mail_Subject,Mail_TempleteName,Messages,Mail_InsertedDate,Mail_UserID,@parentid as Mail_ParentID          
