when m.Mail_Subject is not null then m.Mail_Subject            
else isnull(replace(m.[mail_subject],'''','"'),'') end+ '" to emailid '                
+cast(m.Mail_ToEmail as nvarchar) +' through automated campaign named ' +           
c.CampaignName,dbo.fn_geteventid('Mail sent to enquiry'),'Batchemail_infos',m.Mail_BatchID                  
 from user_detail u(nolock)               
 join #cloneemail m on m.Mail_UserID=u.User_ID                 
 join UserCampaignMaster c(nolock) on c.ID=m.CampaignID                  
  left join usermailtemplate umt(nolock) on umt.id=@templateid              
 where m.entityname=@context and isnull(m.entityid,0)<>0                           
 end

