--exec UspSaveEntityActivity_withMultipleValue_withid @tbl_activity_wa              
end          
else           
begin          
update u set step1=1,Step2 = 1,Step2DateTime=GETDATE(), Step2Recipients=@rowsaffected,          
Step1DateTime=GETDATE(), Step1Recipients=@rowsaffected,          
u.ReasonIfNotRun='No active whatsapp business api ' from UserCampaignHistory u where           
u.id=@uchid          
UPDATE Kd SET isrecipients=1,executiontime=getdate(),Ismessages = 1,isexecuted=0,NoOfRecipients=@rowsaffected,          
batchid=@smsbatchid,response='No active whatsapp business api ' FROM  Usercampaignexecutionhistory Kd  where kd.id=@ucehid          
GOTO ENDPROC          
end          
