declare @orderno int=(select orderno from usergrouptemplatemix(nolock) where groupid=@templategroupid and templateid=@templateid)          
UPDATE Kd SET isrecipients=1,Ismessages = 1,templatesequence=case when isnull(@templategroupid,0)<>0 then @orderno end,          
templateid =@templateid,ExecutionTime=getdate(),                                                           
isexecuted=1,NoOfRecipients=@rowsaffected,batchid=case when @medium='sms' then @smsbatchid           
when @medium='mail' then @mailbatchid when @medium='voice' then @voicebatchid when @medium='Whatsapp' then @wabatchid    
end FROM Usercampaignexecutionhistory Kd                    
where Kd.ID = @ucehid                          
update u set step1=1,Step2 = 1,step3=1,Step2DateTime=GETDATE(),Step3DateTime=GETDATE(),Step2Recipients=@rowsaffected,          
Step1DateTime=GETDATE(), Step1Recipients=@rowsaffected,Step3Recipients=@rowsaffected,activityid=@activityid from UserCampaignHistory u where           
u.id=@uchid          
update ucm set executeddatetime=getdate(),          
TemplateGroupSequence= case when @templategroupid<>0 and isending=0 then @orderno           
else templategroupsequence end           
from UserCampaignmaster ucm where ucm.id=@id          
end          
