/* ============================================================
   Procedure: [dbo].[usp_executeeventcampaign_mailbot]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_executeeventcampaign_mailbot]
    @context NVARCHAR(20),
    @activityid BIGINT,
    @cmpid BIGINT = NULL,
    @tcmpid BIGINT = NULL,
    @errormessage NVARCHAR(2000) = NULL OUTPUT
as
begin

    --declare
    --    @context NVARCHAR(20),
    --    @activityid BIGINT,
    --    @cmpid BIGINT = NULL,
    --    @tcmpid BIGINT = NULL,
    --    @errormessage NVARCHAR(2000) = NULL

    begin try

        DROP TABLE IF EXISTS #campaignstobeexecuted

        --SELECT @context = 'enquiry',
        --       @activityid = 63471750,
        --       @cmpid = 12201,
        --       @tcmpid = 12201,
        --       @errormessage = 'Init'


        declare @parentid bigint,@eventid int,@entityid bigint, @mobile1 nvarchar(20),@mobile2 nvarchar(20),
            @mobile3 nvarchar(20), @email1 nvarchar(100), @email2 nvarchar(100), @email3 nvarchar(100), @isscheduledevent int=0,@duedate datetime,@tgcampid bigint, @st_rules int, @str_rules nvarchar(max), @tgname nvarchar(500), @mailBotId bigint = 0, @AdditionalInstruction nvarchar(max) = null , @rowsaffected int = 0    
        if @context='lead'                                                                        
        begin                                                                        
        select @parentid=parentid,@eventid=EventID,@entityid=leadid,@errormessage='' from                                                                         
        tbl_LeadEventHistory(nolock) where historyid=@activityid                                                                        
        select @mobile1=mobileno,@mobile2=mobileno1,@mobile3=mobileno2 ,@email1=emailid,@email2=emailid1,@email3=emailid2 from                                                                        
        userleads(nolock) where id=@entityid                                                                        
        end                                                                        
        if @context='enquiry'                                                                        
        begin
            select @parentid = parentid, @eventid = EventID, @entityid = enquiryid, 
            @errormessage = '' from tbl_EnquiryEventHistory(nolock) 
                where historyid = @activityid                                                                        
        select @mobile1 = mobileno, @mobile2 = mobileno1, @mobile3 = mobileno2 ,@email1 = emailid, @email2 = emailid1,@email3=emailid2 from                                                                        
        userenquiry(nolock) where EnquiryID=@entityid                                                                        
        end                                                                        
        if @context='conversationcontact'                                                                        
        begin                                                                        
        select @parentid=parentid,@eventid=EventID,@entityid=ConversationContactID,@errormessage='' from                                                                         
        tbl_ContactEventHistory(nolock) where historyid=@activityid                                                                        
        select @mobile1=mobile,@email1=emailid from                                                                        
        conversationcontacts(nolock) where ID=@entityid                                                                        
        end                                                                        
                  
        if @cmpid is not null and @cmpid<>1                  
        begin                  
        select @isscheduledevent=1,@eventid=eventid, @mailBotId = MailBotId, @AdditionalInstruction = AdditionalInstruction from usercampaignmaster(nolock) where id=@cmpid --and eventid between 151 and 154                  
        end                  


        SELECT ucm.id, ucm.parentid, ucm.campaignname, ucm.iseventbased, ucm.isscheduled, ucm.applicabilty, ucm.exclusionsnumber, ucm.exclusions, ucm.inclusionsnumber, ucm.accountused, ucm.senderid, Cast(ucm.message AS NVARCHAR(max)) Message, ucm.templateid, ucm.templategroupid, ucm.isunicode, ucm.medium, ucm.mailreplyto, ucm.mailsubject, ucm.mailcontent, ucm.trackresponse, ucm.trackshorturl, ucm.unsubscribepage, ucm.unsubscribeshorturl, ucm.tags, ucm.isrunafter, ucm.isschedule, ucm.scheduleid, ucm.executeddatetime, ucm.nextexecutedatetime, ucm.isactive, ucm.createdon, ucm.createdby, ucm.modifiedon, ucm.modifiedby, ucm.startdate, ucm.expirydate, ucm.eventsname, ucm.applicabiltygrouplist, ucm.exclusionsgrouplist, ucm.notificationmail, ucm.successnotificationemail, ucm.failurenotificationemail, ucm.isrecurring, ucm.isending, ucm.templategroupsequence, ucm.isneverexpire, ucm.runathours, ucm.runatmin, ucm.issurplusexclusions, ucm.frommailid, ucm.route, ucm.didno, ucm.appid, ucm.duration, ucm.credits, ucm.dlttemplateid, ucm.mailroute, ucm.eventid, ucm.contacttype, t.id AS triggeredcampaignid, t.cname AS triggeredcampaignname, ucm.mailbotid, ucm.additionalinstruction
        INTO   #campaignstobeexecuted
        FROM usercampaignmaster(nolock) ucm
               INNER JOIN user_detail AS Ud ON Ud.[user_id] = ucm.parentid AND Ud.[status] <> 0
               JOIN triggeredcampaigns t 
                ON ucm.id IN ( t.smscampaignid, t.mailcampaignid, t.voicecampaignid, t.whatsappcampaignid )
                AND t.isactive = 1
        JOIN price_usersubscriptiondetails (nolock) p
          ON p.userid = ud.user_id
             AND user_id = ud.parentid
             AND isnewplan = 1
             AND planenddate >= Cast(Getdate() AS DATE)
        WHERE -- ucm.eventid = @eventid AND 
               ucm.iseventbased = 1 AND 
               ucm.parentid = @parentid AND 
               ucm.isactive = 1 AND 
               Isnull(ucm.startdate, Getdate()) <= Getdate() AND 
               --ucm.id = @cmpid
               1 = CASE
                         WHEN @tcmpid IS NOT NULL
                              AND @tcmpid > 0
                              AND t.id = @tcmpid THEN 1
                         WHEN @cmpid IS NULL
                               OR @cmpid = 1 THEN 1
                         WHEN ucm.id = @cmpid THEN 1
                         ELSE 0
                       END

                --and 1= case when @isscheduledevent = 0 then 1 else 0 end 

         if not exists (select 1 from #campaignstobeexecuted)
         begin
        set @errormessage='No active SMS/Mal/Voice/Whatsapp Campaign found for this activity'
        GOTO FINALEND
         end
        PRINT 'MAILBOT SECTION'

        INSERT INTO tbl_mailbot_campaigns (parentid, mailbotid, eventid, activityid, additionalinstruction, entityname, entityid, from_email, replay_email, to_emails)
        SELECT c.parentid, c.mailbotid, @eventid, @activityid, c.additionalinstruction, @context, @entityid, c.frommailid, c.mailreplyto, value
        FROM   #campaignstobeexecuted c
               CROSS apply dbo.Fn_split(concat(
                        cast(COALESCE(@email1, '') AS NVARCHAR(200)), ',',
                        cast(COALESCE(@email2, '') AS NVARCHAR(200)), ',',
                        cast(COALESCE(@email3, '') AS NVARCHAR(200))), ',')
            

        SET @rowsaffected = @@ROWCOUNT;

        IF @rowsaffected = 0
          BEGIN
              SET @errormessage = Isnull(@errormessage + ' ', '')
                                  + 'Triggered Campaign ' + @tgname
                                  + ' for Mail failed due to no valid emailid ';
              PRINT Concat('Error message: no valid email ', Isnull(@errormessage, ''));
          END  
    end try
    begin catch
        exec usp_InsertErrorInfo
        set @errormessage=Isnull(@errormessage+' ','')+ 'Error in execution of Mail Bot Campaign for this activity'
        PRINT 'Error in execution of Mail Bot Campaign for this activity'
    end catch

    FINALEND:
    IF @errormessage IS NULL OR @errormessage = ''
        SET @errormessage = 'Successfully Mail Bot Executed';

    PRINT 'Errormessage: ' + @errormessage;

end



GO

/* ============================================================
   Procedure: [dbo].[usp_executeeventcampaign_tcid]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_executeeventcampaign_tcid]-- 'enquiry',2659286,1-- 'lead',1002391
@context nvarchar(20),@activityid bigint,@tcmpid bigint                                                                  
as                                                                  
begin                                  
set ansi_warnings on;                                                            
drop table if exists #campaignstobeexecuted                                                                  
drop table if exists #applicablegroups                                                                  
drop table if exists #Exclusions  
DECLARE @sqlquery NVARCHAR(MAX);
DECLARE @exists bigint;

                                                                  
declare @parentid bigint,@eventid int,@entityid bigint, @mobile1 nvarchar(20),@mobile2 nvarchar(20),@mobile3 nvarchar(20),                                                                  
@email1 nvarchar(100),@email2 nvarchar(100),@email3 nvarchar(100),@isscheduledevent int=0,@duedate datetime,@tgcampid bigint,  
@st_rules int,@str_rules nvarchar(max)  
if @context='lead'                                                                  
begin                                                                  
select @parentid=parentid,@eventid=EventID,@entityid=leadid from                                                                   
tbl_LeadEventHistory(nolock) where historyid=@activityid                                                                  
select @mobile1=mobileno,@mobile2=mobileno1,@mobile3=mobileno2 ,@email1=emailid,@email2=emailid1,@email3=emailid2 from                                                                  
userleads(nolock) where id=@entityid                                                                  
end                                                                  
if @context='enquiry'                                                                  
begin                                                                  
select @parentid=parentid,@eventid=EventID,@entityid=enquiryid from                                                                   
tbl_EnquiryEventHistory(nolock) where historyid=@activityid                                                                  
select @mobile1=mobileno,@mobile2=mobileno1,@mobile3=mobileno2 ,@email1=emailid,@email2=emailid1,@email3=emailid2 from                                                                  
userenquiry(nolock) where EnquiryID=@entityid                                                                  
end                                                                  
if @context='conversationcontact'                                                                  
begin                                                                  
select @parentid=parentid,@eventid=EventID,@entityid=ConversationContactID from                                                                   
tbl_ContactEventHistory(nolock) where historyid=@activityid                                                                  
select @mobile1=mobile,@email1=emailid from                                                                  
conversationcontacts(nolock) where ID=@entityid                                                                  
end                                                                  
            
--if @cmpid is not null and @cmpid<>1            
--begin            
--select @isscheduledevent=1,@eventid=eventid from usercampaignmaster(nolock) where id=@cmpid --and eventid between 151 and 154            
--end            
                                                                  
select ucm.ID,ucm.ParentID,ucm.CampaignName,ucm.IsEventBased,ucm.IsScheduled,ucm.Applicabilty,ucm.ExclusionsNumber,ucm.Exclusions,ucm.InclusionsNumber,ucm.AccountUsed,ucm.SenderID,                
cast(ucm.Message as nvarchar(max)) Message,ucm.TemplateID,ucm.TemplateGroupID,ucm.IsUnicode,ucm.Medium,ucm.MailReplyTo,ucm.MailSubject,ucm.MailContent,ucm.TrackResponse,ucm.TrackShortURL,ucm.UnsubscribePage,                
ucm.UnsubscribeShortURL,ucm.Tags,ucm.IsRunAfter,ucm.IsSchedule,ucm.ScheduleID,ucm.ExecutedDateTime,ucm.NextExecuteDateTime,ucm.IsActive,ucm.CreatedOn,ucm.Createdby,ucm.ModifiedOn,ucm.ModifiedBy,ucm.StartDate,ucm.ExpiryDate,ucm.EventsName,                
ucm.ApplicabiltyGroupList,ucm.ExclusionsGroupList,ucm.NotificationMail,ucm.SuccessNotificationEmail,ucm.FailureNotificationEmail,ucm.IsRecurring,ucm.IsEnding,ucm.TemplateGroupSequence,ucm.IsNeverExpire,ucm.RunAtHours,ucm.RunAtMin,                
ucm.IsSurplusExclusions,ucm.FromMailId,ucm.route,ucm.didno,ucm.appid,ucm.duration,ucm.credits,ucm.DLTTemplateID,ucm.mailroute,ucm.eventid,ucm.ContactType,t.id as triggeredcampaignid                
 into #campaignstobeexecuted                                                                   
from usercampaignmaster(nolock) ucm                                                                   
Inner join  User_detail AS Ud  on Ud.[User_ID]= isnull(AccountUsed,Ud.[User_ID]) and Ud.[Status] <> 0                                                            
join triggeredcampaigns t on ucm.id in (t.smscampaignid,t.mailcampaignid,t.voicecampaignid,t.whatsappcampaignid)                                                             
and t.isactive=1                                                                                                              
join Price_UserSubscriptionDetails (nolock) p on p.UserID=ud.User_ID and user_id=ud.parentid and isnewplan=1 and PlanEndDate>getdate()                                                  
where t.id=@tcmpid  and ucm.eventid=@eventid and ucm.IsEventBased=1                                                                  
and ucm.parentid=@parentid and ucm.IsActive=1 
--and 1=case when @isscheduledevent=0 then 1             
--else 0 end            
                                                                
                                                                  
if exists(select 1 from #campaignstobeexecuted)                                                          
begin                           
declare @c int=(select count(distinct id) from #campaignstobeexecuted),@id bigint=0,@medium nvarchar(20),@templategroupid int=0,                                     
@templateid int=0,@accountused bigint,@rowsaffected int=0,@creditsrequired numeric(18,2),@balance numeric(18,2),@contacttype nvarchar(10)                                  
,@wa_templatename nvarchar(100)                                                            
declare @accountusedparentid bigint,@messagestring nvarchar(max)                                                       
                                                
--drop table if exists #replaceplaceholders                                                
--create table #replaceplaceholders(strvalue nvarchar(max), cnt int)                                                           
                                                                  
while @c>0                                                                  
begin                             
if OBJECT_ID('tempdb..#campaignstobeexecuted') is null                          
begin                          
insert into debugexecuteeventcampaign(entity,jsontext,activityid,created)                          
select '#campaign',@id,@activityid,getdate()                          
