begin                                                                        
set @errormessage=isnull(@errormessage+' ','')+'Triggered Campaign '+@tgname+' for Voice failed due to insufficient balance. '
print @errormessage                                                                           

end


                                                                        
if @balance>=@creditsrequired                                                                        
begin                                                                        
 begin tran                                                                                          
 declare @voicebatchid bigint                                              
INSERT INTO Getbatchrecord                                                                                                                                      
([User_id],RandNum)               
SELECT @id,@parentid                                                                        
select @voicebatchid=scope_identity()                                                                        
                                                                                               
delete From GetBatchRecord where batchid=@voicebatchid                                                                                        
commit                                                                                                              
                                         
drop table if exists  [#clonevoicemessagedeliverystatus]                                                                        
SELECT DISTINCT entityname,entityid,@voicebatchid batchid, [Ucerm].[mobile], [Ucerm].[message], [Ucerm].[messagestatus],                              
[Ucerm].[senderid], [Ucerm].[messageinsertdate], '' AS [scheduleddate], '' AS [scheduledtime],[Ucerm].[u_id],                                                                        
[Ucerm].[isunicode], [Ucerm].[isdnd],[Ucerm].[validno],case when @rowsaffected between 1 and 10 then 1 else 0 end as [isprority],                                                                         
[Ucerm].[isallowdnd], [Ucerm].[dbtype],[CampaignID], @rowsaffected Rcount, ISNULL([Credits], 0) [Credits],                                                                        
[appid], [duration], [didno], [route], [jobid]                                                                                    
INTO [#clonevoicemessagedeliverystatus]                                            
FROM usercampaignexecutionrecipientVoice2 Ucerm(NOLOCK)                                                                         
WHERE [Ucerm].[mobile] <> ''                                                                                    
  AND [ucerm].[jobid] = @jobid                                                                                    
          
 /*Added new code below to generate lead activity with other actions*/          
 select top 1 @eventdescription=cast(u.user_login as nvarchar) +' sent an automated call with ivr '+i.appname+ ' and did no. '          
 +cast(m.didno as nvarchar(20))+' to mobile '+cast(m.mobile as nvarchar) +' through automated campaign named '                 
 + c.CampaignName,@eventname= 'Voice sent to '+@context,@v_bid=m.batchid          
 from user_detail u(nolock) join #clonevoicemessagedeliverystatus m(nolock) on m.u_id=u.User_ID                                                                              
  join UserCampaignMaster c(nolock) on c.ID=m.CampaignID                                                                              
  join cloud_app_master i(nolock) on i.appid=m.appid                                                                                        
 where m.entityname=@context and isnull(m.entityid,0)<>0          
          
exec UspSaveEntityActivity_withid @context,@entityid,@parentid,@PARENTID,@eventdescription,@eventname,'BatchVoiceInfo',@v_bid          
/*Commented code below to stop just inserting activity without other actions          
                                                              
if @context='lead'                                                              
 begin                                                              
 insert into tbl_leadeventhistory(LeadID,UserID,ParentID,EventDescription,EventID,reftables,refids)                                                              
select distinct entityid,m.u_id,u.ParentID, cast(u.user_login as nvarchar) +' sent an automated call with ivr '+i.appname+ ' and did no. '+cast(m.didno as nvarchar(20))+' to mobile '+cast(m.mobile as nvarchar) +' through automated campaign named '       
  
    
      
        
          
 + c.CampaignName,dbo.fn_geteventid('Voice sent to lead'),'BatchVoiceInfo',m.BatchID     
 from user_detail u join #clonevoicemessagedeliverystatus m on m.u_id=u.User_ID                                                                              
  join UserCampaignMaster c on c.ID=m.CampaignID                                                                              
  join cloud_app_master i on i.appid=m.appid                                                                                        
 end                                                              
 if @context='enquiry'                                                              
 begin                                                              
insert into tbl_enquiryeventhistory(enquiryID,UserID,ParentID,EventDescription,EventID,reftables,refids)                                                              
 select distinct entityid,m.u_id,u.ParentID, cast(u.user_login as nvarchar) +' sent an automated call with ivr '+i.appname+ ' and did no. '+cast(m.didno as nvarchar(20))+' to mobile '+cast(m.mobile as nvarchar) +' through automated campaign named '      
   
    
      
        
          
 + c.CampaignName,dbo.fn_geteventid('Voice sent to enquiry'),'BatchVoiceInfo',m.BatchID                                                                              
 from user_detail u join #clonevoicemessagedeliverystatus m on m.u_id=u.User_ID                                       
  join UserCampaignMaster c on c.ID=m.CampaignID                                                                              
  join cloud_app_master i on i.appid=m.appid                                                                                         
 end                                                              
*/                                                                        
begin try                                                                        
INSERT INTO Clone_VoiceDeliveryStatus ([BatchID], [didno], [Mobile], [voiceDuration], [AppId], [IsDnd], [IsPrority], [IsAllowDND],               
[price], user_id, [VoiceInsertDate], [voice_type], [route], [campaignid], [jobid],v_activityid,v_entity,voice_source)                                                                                    
SELECT distinct [batchid], [didno], [Ucerm].[mobile], [duration], [appid], [Ucerm].[isdnd], [IsPrority], [Ucerm].[isallowdnd],                                                                         
[Credits], [Ucerm].[u_id], GETDATE(), [Ucerm].[dbtype], [route], [campaignid], [jobid],@activityid,@context,'Campaign :'+    
isnull(cast(campaignid as nvarchar),'')                                                       
FROM #clonevoicemessagedeliverystatus Ucerm                                                                     
WHERE [BatchID] = @voicebatchid;                                                     
set @errormessage=isnull(@errormessage+' ','')+'Triggered Campaign '+@tgname+' for sending Voice is executed. '
print @errormessage                                                                           

end try                                                                        
begin catch                                                                        
exec usp_InsertErrorInfo                     
set @errormessage=isnull(@errormessage+' ','')+'Triggered Campaign '+@tgname+' for Voice failed while sending. '
print @errormessage                                                                           


end catch                                                                        
end                                   
else                                                                         
begin                                                                        
update u set step1=1,Step2 = 1,Step2DateTime=GETDATE(), Step2Recipients=@rowsaffected,                                                                        
Step1DateTime=GETDATE(), Step1Recipients=@rowsaffected,                                                                        
u.ReasonIfNotRun='Insufficient Balance' from UserCampaignHistory u where                                                                         
u.id=@uchid                                                                        
UPDATE Kd SET isrecipients=1,executiontime=getdate(),Ismessages = 1,isexecuted=0,NoOfRecipients=@rowsaffected,batchid=@smsbatchid,response='Insufficient Balance' FROM                                                                           
Usercampaignexecutionhistory Kd  where kd.id=@ucehid                                                                        
GOTO ENDPROC                                                         
end                                                           
end                                                                        
DELETE FROM usercampaignexecutionrecipientVoice2 WHERE jobid=@jobid                                  
drop table if exists #clonevoicemessagedeliverystatus                                                     
end                                                                        
if @medium='whatsapp'                                                                        
begin       
print concat('Eligible campaign:',@id)      
--if exists(select 1 from MySMSConversations.dbo.channeltokens(nolock) where channelid=2                                                                 
--and parentid=@parentid and isactive=1)       
SET @sqlquery = '
        SELECT cast(1 as bigint)
       FROM channeltokens (NOLOCK) 
WHERE channelid = 2 
  AND parentid = ' + CAST(@parentid AS NVARCHAR) + ' 
  AND isactive = 1';

EXEC usp_clr_GetRemoteLongValue @sqlquery, @retval = @exists OUT;

IF @exists > 0
begin                                                                  
--select @wa_templatename= templatename from MySMSConversations.dbo.convtemplates (nolock) where id=@templateid                                                                  
SET @sqlquery = '
    SELECT templatename 
    FROM convtemplates WITH (NOLOCK)
    WHERE id = ' + CAST(@templateid AS NVARCHAR);

EXEC usp_clr_GetRemoteStringValue @sqlquery, @retval = @wa_templatename OUT;
declare @wabatchid bigint                               
begin tran                                                                        
INSERT INTO Getbatchrecord                                                                                                                                      
([User_id],RandNum)                                                                                           
SELECT @id,@parentid                                                                        
select @wabatchid=scope_identity()                                                                        
                                            
delete From GetBatchRecord where batchid=@wabatchid                                                                                        
commit                                                                                     
insert into WBatchInfo(ParentID,BatchID,TotalRecords,IsProcess,BatchInsertTime,BatchProcessTime,ScheduledDate,templateid,campaignid                                                                  
,CreatedBy,uchid,trigerringactivityid)                        
select @parentid,@wabatchid,1,0,getdate(),getdate(),null,@templateid,@id,@parentid,@uchid,@activityid                
set @rowsaffected=@@ROWCOUNT             
set @errormessage=isnull(@errormessage+' ','')+'Triggered Campaign '+@tgname+' for sending Whatsapp is executed. '
print @errormessage                                                                           

          
/*Added new code below to generate lead activity with other actions*/          
 select top 1 @eventdescription=cast(u.user_login as nvarchar) +' sent whatsapp template named '          
 +@wa_templatename+'.The template was sent automatically through triggered campaign named '+ c.CampaignName,          
 @eventname= 'Whatsapp template sent to '+@context,@w_bid=@wabatchid          
 from user_detail u(nolock) join UserCampaignMaster c(nolock) on c.ID=@id and c.ParentID=u.User_ID          
 --where m.entityname=@context and isnull(m.entityid,0)<>0          
          
exec UspSaveEntityActivity_withid @context,@entityid,@parentid,@PARENTID,@eventdescription,@eventname,'WBatchinfo',@w_bid          
          
                                                              
--if @context='lead'                                                              
-- begin                                                              
-- insert into tbl_leadeventhistory(LeadID,UserID,ParentID,EventDescription,EventID,reftables,refids)                                                              
-- select @entityid,c.parentid,c.ParentID,                                                    
--cast(u.user_login as nvarchar(max)) +' sent whatsapp template named '+@wa_templatename+'.The template was sent automatically through triggered campaign named '+ c.CampaignName,                                         
--dbo.fn_geteventid('Whatsapp template sent to enquiry'),'WBatchinfo',@wabatchid                                                                                
--from user_detail u join UserCampaignMaster c on c.ID=@id and c.ParentID=u.User_ID                                                                                           
-- end                                                              
-- if @context='enquiry'                                                              
-- begin                                           
--insert into tbl_enquiryeventhistory(enquiryID,UserID,ParentID,EventDescription,EventID,reftables,refids)                                                   
-- select @entityid,c.parentid,c.ParentID,                                                               
--cast(u.user_login as nvarchar(max)) +' sent whatsapp template named '+@wa_templatename+'.The template was sent automatically through triggered campaign named '+ c.CampaignName,                                                                  
--dbo.fn_geteventid('Whatsapp template sent to enquiry'),'WBatchinfo',@wabatchid                                                                                
--from user_detail u join UserCampaignMaster c on c.ID=@id and c.ParentID=u.User_ID                                        
-- end                                                         
                  
end                                                                        
else                                                                         
begin                                                                        
update u set step1=1,Step2 = 1,Step2DateTime=GETDATE(), Step2Recipients=@rowsaffected,                                                                        
Step1DateTime=GETDATE(), Step1Recipients=@rowsaffected,                                                               
u.ReasonIfNotRun='No active whatsapp business api ' from UserCampaignHistory u where                                                                         
u.id=@uchid                                                          
UPDATE Kd SET isrecipients=1,executiontime=getdate(),Ismessages = 1,isexecuted=0,NoOfRecipients=@rowsaffected,                                                                        
batchid=@smsbatchid,response='No active whatsapp business api ' FROM  Usercampaignexecutionhistory Kd  where kd.id=@ucehid 
set @errormessage=isnull(@errormessage+' ','')+'Triggered Campaign '+@tgname+' for Whatsapp failed since no active whatsapp business api was found. '
print @errormessage                                                                           

GOTO ENDPROC                                                                        
end

end
                        
declare @orderno int=(select orderno from usergrouptemplatemix(nolock) where groupid=@templategroupid and templateid=@templateid)                                                                        
UPDATE Kd SET isrecipients=1,Ismessages = 1,templatesequence=case when isnull(@templategroupid,0)<>0 then @orderno end,                                                                        
templateid =@templateid,ExecutionTime=getdate(),                                                                                                                         
isexecuted=1,NoOfRecipients=@rowsaffected,batchid=case when @medium='sms' then @smsbatchid                                                                
when @medium='mail' then @mailbatchid when @medium='voice' then @voicebatchid when @medium='Whatsapp' then @wabatchid                                                                  
end FROM Usercampaignexecutionhistory Kd                                                                                  
where Kd.ID = @ucehid                                                                                        
update u set step1=1,Step2 = 1,step3=1,Step2DateTime=GETDATE(),Step3DateTime=GETDATE(),Step2Recipients=@rowsaffected,                                                                        
Step1DateTime=GETDATE(), Step1Recipients=@rowsaffected,Step3Recipients=@rowsaffected,activityid=@activityid from UserCampaignHistory u where                                                                         
u.id=@uchid                                                                        
update ucm set executeddatetime=getdate(),                                                                        
TemplateGroupSequence= case when @templategroupid<>0 and isending=0 then @orderno                                      
else templategroupsequence end                                                                         
from UserCampaignmaster ucm where ucm.id=@id                                                                        
end                            
else
begin
print 'Campaign is not eligible'  
set @errormessage=isnull(@errormessage+' ','')+'Triggered Campaign '+@tgname+' audience does not include the Lead/Enquiry. '
print @errormessage                                                                           

end

ENDPROC:    
set @c = @c-1   
end                                                                  
end 
FINALEND:
print 'Errormessage: '+@errormessage
end


GO

/* ============================================================
   Procedure: [dbo].[usp_executeeventcampaign1]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_executeeventcampaign1] -- 'lead',1002391                                                        
@context nvarchar(20),@activityid bigint                                                          
as 
begin                          
set ansi_warnings on;              
drop table if exists #scamps  
drop table if exists #campaignschedule              
drop table if exists #vcampaignschedule              

--declare @context nvarchar(20),@activityid bigint                                                          
--select @context='lead',@activityid=108312013

begin try              
declare @eventid int,@refid bigint,@reftables nvarchar(100),@leadid bigint,@ParentID bigint,@enquirysource int,@leadno bigint,@enquiryid bigint      
create table #scamps(parentid bigint,eventid int,activityid bigint,createdon datetime,reftable nvarchar(200),              
refid bigint,isnotified int,refcolumn nvarchar(50),scheduledfor datetime,isvalid int,scheduledaction nvarchar(20),tcampaignid bigint,std_entity_name nvarchar(50),std_entity_id bigint,bot_type varchar(20) null,bot_campaignid bigint null)             
create table #campaignschedule(cid bigint,scheduledfor datetime,eventid int)  
create table #vcampaignschedule(cid bigint,scheduledfor datetime,eventid int,bot_type varchar(20))  

if @context='lead'              
begin          
select @leadid=leadid,@eventid=eventid,@ParentID=parentid,@refid=refids,@reftables=reftables from  tbl_leadeventhistory(nolock) l where historyid=@activityid     
 and eventdate>dateadd(d,-1,getdate())
select @enquirysource=enquirysource,@leadno=leadno from userleads(nolock) where id=@leadid      
      
insert into #campaignschedule(cid,scheduledfor,eventid)          
select id as campaignid,          
--case when isnull(nullif(timeunit,''),'')='' then getdate()           
--when timeunit='second' then dateadd(ss,0-isnull(timebeforeevent,0),getdate())          
--when timeunit='minute' then dateadd(mi,0-isnull(timebeforeevent,0),getdate())           
--when timeunit='hour' then dateadd(HH,0-isnull(timebeforeevent,0),getdate())          
--when timeunit='day' then dateadd(dd,0-isnull(timebeforeevent,0),getdate())          
--end           
getdate()          
as scheduledfor,eventid           
from usercampaignmaster(nolock) where id in           
(select smscampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid          
union          
select mailcampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid          
union          
select voicecampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid          
union          
select whatsappcampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid          
)      
and 1=case when @enquirysource in (10,20,21) and @eventid =17 then 0      
when @enquirysource in (10,20,21) and @eventid  in (10,37) and @refid =      
(select min(id) from LeadInteractionHistory(nolock) where leadno=@leadno and parentid=@parentid)      
then 0 else 1 end      

insert into #vcampaignschedule(cid,scheduledfor,eventid,bot_type)          
select id as campaignid,getdate() as scheduledfor,  eventid,'voice'         
from voice_bot_campaigns(nolock) where id in           
(select bot_campaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid)  
and 1=case when @enquirysource in (10,20,21) and @eventid =17 then 0      
when @enquirysource in (10,20,21) and @eventid  in (10,37) and @refid =      
(select min(id) from LeadInteractionHistory(nolock) where leadno=@leadno and parentid=@parentid)      
then 0 else 1 end

insert into #scamps(parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,scheduledaction,tcampaignid,std_entity_name,std_entity_id,bot_type,bot_campaignid)              
select l.parentid,l.eventid,historyid,getdate() as createdon,reftables,refids,0 as isnotified,'' refcolumn,scheduledfor,1 as isvalid,              
'Campaign' scheduledaction,cid as tcampaignid,'lead',l.leadid ,null,null             
from tbl_leadeventhistory(nolock) l           
join #campaignschedule c on c.eventid=l.EventID          
where exists               
(select 1 from triggeredcampaigns (nolock) t where t.eventid=l.eventid and t.parentid=l.parentid and t.isactive=1)              
 and historyid=@activityid     and eventdate>dateadd(d,-1,getdate())         
union
select l.parentid,l.eventid,historyid,getdate() as createdon,reftables,refids,0 as isnotified,'' refcolumn,scheduledfor,
1 as isvalid,              
'BotCampaign' scheduledaction,null as tcampaignid,'lead',l.leadid ,bot_type ,cid            
from tbl_leadeventhistory(nolock) l           
join #vcampaignschedule c on c.eventid=l.EventID          
where exists               
(select 1 from triggeredcampaigns (nolock) t where t.eventid=l.eventid and t.parentid=l.parentid and t.isactive=1)              
 and historyid=@activityid     and eventdate>dateadd(d,-1,getdate())         

end              
else if @context='enquiry'              
begin          
select @eventid=eventid,@ParentID=parentid,@refid=refids,@reftables=reftables,@enquiryid=EnquiryID from  tbl_enquiryeventhistory(nolock) l where historyid=@activityid 
 and eventdate>dateadd(d,-1,getdate())
select @enquirysource=enquirysource from userenquiry(nolock) where enquiryid=@enquiryid      
insert into #campaignschedule(cid,scheduledfor,eventid)          
select id as campaignid,        
--case when isnull(nullif(timeunit,''),'')='' then getdate()         
--when timeunit='second' then dateadd(ss,0-isnull(timebeforeevent,0),getdate())          
--when timeunit='minute' then dateadd(mi,0-isnull(timebeforeevent,0),getdate())         
--when timeunit='hour' then dateadd(HH,0-isnull(timebeforeevent,0),getdate())          
--when timeunit='day' then dateadd(dd,0-isnull(timebeforeevent,0),getdate())          
--end         
getdate() as scheduledfor,eventid           
from usercampaignmaster(nolock) where id in           
(select smscampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid          
union          
select mailcampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid          
union          
select voicecampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid          
union          
select whatsappcampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid          
)     
--and 1=case when @enquirysource =20 and @eventid =119 then 0      
-- else 1 end      
 insert into #vcampaignschedule(cid,scheduledfor,eventid,bot_type)          
select id as campaignid,getdate() as scheduledfor,  eventid,'voice'         
from voice_bot_campaigns(nolock) where id in           
(select bot_campaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid )  
         
          
insert into #scamps(parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,scheduledaction,tcampaignid,std_entity_name,std_entity_id,bot_type,bot_campaignid)              
select l.parentid,l.eventid,historyid,getdate() as createdon,reftables,refids,0 as isnotified,'' refcolumn,scheduledfor,1 as isvalid,              
'Campaign' scheduledaction,cid as tcampaignid,'enquiry',l.enquiryid,null,null              
from tbl_enquiryeventhistory(nolock) l           
join #campaignschedule c on c.eventid=l.EventID          
where exists               
(select 1 from triggeredcampaigns (nolock) t where t.eventid=l.eventid and t.parentid=l.parentid and t.isactive=1)              
 and historyid=@activityid and eventdate>dateadd(d,-1,getdate())  
 union
 select l.parentid,l.eventid,historyid,getdate() as createdon,reftables,refids,0 as isnotified,'' refcolumn,scheduledfor,1 as isvalid,              
'BotCampaign' scheduledaction,null as tcampaignid,'enquiry',l.enquiryid ,bot_type,cid             
from tbl_enquiryeventhistory(nolock) l           
join #vcampaignschedule c on c.eventid=l.EventID          
where exists               
(select 1 from triggeredcampaigns (nolock) t where t.eventid=l.eventid and t.parentid=l.parentid and t.isactive=1)              
 and historyid=@activityid and eventdate>dateadd(d,-1,getdate()) 



end   

--select top 1 @eventid=eventid,@ParentID=parentid from #scamps            
            
if @eventid in (41,43,54,50,51,55,10,37,42,44,45,46,56)            
begin            
declare @typeofevent nvarchar(100),@scheduledaction nvarchar(50)='' ,@campaignid bigint,@seventid int               
select @typeofevent=EventType FROM   ActivityMaster(nolock) WHERE @eventid=id                
select @seventid=case when @typeofevent='task' then 151 when @typeofevent                
='Appointment' then 152 when @typeofevent='Deal' then 154 when @eventid in (10,37) then 153 end            
--select @reftables=reftable,@refid=refid from #scamps(nolock)             
            
if exists(select 1 from triggeredcampaigns(nolock) where isactive=1 and eventid=@seventid and parentid=@ParentID)                
begin            
declare @duedate datetime,@refcolumn nvarchar(100)='',@duetype nvarchar(20)=case when @eventid  in (10,37) then 'FollowUp' else @typeofevent end                
select @duedate=case when IsAppointment=1 then startdate else enddate end,@refcolumn=case when IsAppointment=1 then 'startdate' else 'enddate' end                 
from tbl_tsk_TaskHistory(nolock) where id=@refid and @typeofevent in ('task','appointment')                
select @duedate=followupdate,@refcolumn='followupdate'                
from leadinteractionhistory(nolock) where id=@refid and @eventid in (10,37)               
select @duedate=dbo.fn_getleadpipelineexpirydate(leadid,pipelineid)                 
from leadpipelinemapping(nolock) l where l.id=@refid            
  and @typeofevent ='Deal'              
            
            
if @eventid  in (41,43,54,50,51,55,10,37)             
begin            
if exists (select 1 from scheduledtodos (nolock) s where s.isnotified=0 and s.eventid=@seventid            
and activityid in (select historyid from tbl_LeadEventHistory(nolock) where eventid in (10,37) and leadid=@leadid)            
) and @eventid in (10,37)                
 begin                
update s set isvalid=0 from scheduledtodos s             
where s.isnotified=0 and s.eventid=@seventid and activityid in (select historyid from tbl_LeadEventHistory(nolock) where       
eventid in (10,37) and leadid=@leadid)                 
end             

insert into scheduledtodos(parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,      
          
scheduledaction,tcampaignid,std_entity_name,std_entity_id,bot_type,bot_campaignid)             
select @ParentID as parentid,@seventid as eventid,@activityid as activityid,            
getdate() as createdon,@reftables as reftable,@refid refid,0 isnotified,@refcolumn refcolumn,@duedate scheduledfor,1 as       
isvalid,'Campaign' as scheduledaction,u.id as Tcampaignid,@context,case when @context='lead' then @leadid else @enquiryid end            ,null,null
from triggeredcampaigns(nolock) t join             
usercampaignmaster(nolock) u on u.id in (t.smscampaignid,t.whatsappcampaignid,t.mailcampaignid,t.voicecampaignid)            
where t.isactive=1 and u.IsActive=1 and t.eventid=@seventid and t.parentid=@parentid            
and not exists            
(select 1 from scheduledtodos(nolock) where eventid=@seventid and reftable=@reftables and refid=@refid and parentid=@ParentID and             
scheduledaction='Campaign' and tcampaignid=u.id)            
union
select @ParentID as parentid,@seventid as eventid,@activityid as activityid,            
getdate() as createdon,@reftables as reftable,@refid refid,0 isnotified,@refcolumn refcolumn,@duedate scheduledfor,1 as       
isvalid,'BotCampaign' as scheduledaction,null as Tcampaignid,@context,case when @context='lead' then @leadid else @enquiryid end,'voice',u.id            
from triggeredcampaigns(nolock) t join             
voice_bot_campaigns(nolock) u on u.id = t.bot_campaignid            
where t.isactive=1 and u.IsActive=1 and t.eventid=@seventid and t.parentid=@parentid            
and not exists            
(select 1 from scheduledtodos(nolock) where eventid=@seventid and reftable=@reftables and refid=@refid and parentid=@ParentID and             
scheduledaction='BotCampaign' and bot_campaignid=u.id)            





            
if @eventid not in (10,37)            
begin            
update s set scheduledfor=@duedate,isnotified=0,isvalid=1,activityid=@activityid from scheduledtodos s            
where reftable=@reftables and refid=@refid and parentid=@parentid and eventid=@seventid  --and @duedate>getdate()               
end            
end            
else if @eventid in (42,44,45,46,56)  --completed or deleted              
begin                
update scheduledtodos set isvalid=0 where reftable=@reftables and refid=@refid and parentid=@parentid and eventid=@seventid               
end            
               
end            
end            
insert into scheduledtodos(parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,scheduledaction,tcampaignid,std_entity_name,std_entity_id,bot_type,bot_campaignid)           
select parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,scheduledaction,tcampaignid,std_entity_name,std_entity_id,bot_type,bot_campaignid from #scamps              
drop table if exists #scamps              
drop table if exists #campaignschedule
drop table if exists #vcampaignschedule          

end try              
begin catch              
exec usp_InsertErrorInfo              
end catch              
end


GO

/* ============================================================
   Procedure: [dbo].[usp_executeeventcampaign1_multi]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_executeeventcampaign1_multi] -- 'lead',1002391                                                          
@multiactivity as multiactivity readonly      
as                                                            
begin                            
set ansi_warnings on;                
drop table if exists #scamps                
begin try        
declare @context nvarchar(20)=(select top 1 context from @multiactivity)      
declare @eventid int,@typeofevent nvarchar(50),@refid bigint,@reftables nvarchar(100),@leadid bigint,@ParentID bigint,@enquirysource int,@leadno bigint,@enquiryid bigint        
create table #scamps(parentid bigint,eventid int,activityid bigint,createdon datetime,reftable nvarchar(200),                
refid bigint,isnotified int,refcolumn nvarchar(50),scheduledfor datetime,isvalid int,scheduledaction nvarchar(20),tcampaignid bigint      
,duedate datetime,typeofevent nvarchar(50),s_eventid int,entityid bigint      
)               
create table #campaignschedule(cid bigint,scheduledfor datetime,eventid int)            
      
if @context='lead'                
begin            
select top 1 @eventid=eventid,@ParentID=parentid,@leadid=leadid from  tbl_leadeventhistory(nolock) l where historyid=(select top 1 activityid from @multiactivity)         
select top 1 @enquirysource=enquirysource from userleads(nolock) where id=@leadid      
select @typeofevent=eventtype from activitymaster(nolock) where id=@eventid      
      
insert into #scamps(parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,scheduledaction,      
tcampaignid,typeofevent,entityid)                
select l.parentid,l.eventid,historyid,getdate() as createdon,reftables,refids,0 as isnotified,'' refcolumn,getdate(),1 as isvalid,                
'Campaign' scheduledaction,u.id as tcampaignid,@typeofevent,leadid               
from tbl_leadeventhistory(nolock) l join @multiactivity m on m.activityid=l.historyid      
join       
(select id,eventid from usercampaignmaster(nolock) u where u.id in             
(select smscampaignid from triggeredcampaigns(nolock) t       
where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid            
union            
select mailcampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid            
union            
select voicecampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid            
union            
select whatsappcampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid            
)        
) u on u.eventid=l.eventid      
where       
 1=case when @enquirysource in (10,20,21) and @eventid =17 then 0        
when @enquirysource in (10,20,21) and @eventid  in (10,37) and not exists        
(select 1 from tbl_leadeventhistory(nolock) where leadid=l.leadid and eventid=l.eventid and historyid<l.historyid)        
then 0       
else 1 end        
             
end                
else if @context='enquiry'                
begin      
select top 1 @eventid=eventid,@ParentID=parentid,@enquiryid=EnquiryID from  tbl_enquiryeventhistory(nolock) l       
where historyid=(select top 1 activityid from @multiactivity)         
select top 1 @enquirysource=enquirysource from userenquiry(nolock) where enquiryid=@enquiryid      
select @typeofevent=eventtype from activitymaster(nolock) where id=@eventid      
      
insert into #campaignschedule(cid,scheduledfor,eventid)            
select id as campaignid,          
getdate() as scheduledfor,eventid             
from usercampaignmaster(nolock) where id in             
(select smscampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid            
union            
select mailcampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid            
union            
select voicecampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid            
union            
select whatsappcampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid            
) 
--and 1=case when @enquirysource =20 and @eventid =119 then 0        
-- else 1 end        
            
insert into #scamps(parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,scheduledaction,      
tcampaignid,typeofevent,entityid)                
select l.parentid,l.eventid,historyid,getdate() as createdon,reftables,refids,0 as isnotified,'' refcolumn,scheduledfor,1 as isvalid,                
'Campaign' scheduledaction,cid as tcampaignid,@typeofevent,enquiryid                
from tbl_enquiryeventhistory(nolock) l             
join #campaignschedule c on c.eventid=l.EventID        
join @multiactivity m on m.ActivityID=l.HistoryID      
where exists                 
(select 1 from triggeredcampaigns (nolock) t where t.eventid=l.eventid and t.parentid=l.parentid and t.isactive=1)                
end                
--select top 1 @eventid=eventid,@ParentID=parentid from #scamps              
              
if @eventid in (41,43,54,50,51,55,10,42,44,45,46)              
begin              
update s set s_eventid=      
case when typeofevent='task' then 151 when typeofevent                  
='Appointment' then 152 when typeofevent='Deal' then 154 when eventid=10 then 153 end         
from #scamps s      
      
update s set duedate=case when IsAppointment=1 then startdate else enddate end      
from #scamps s (nolock) join  tbl_tsk_TaskHistory(nolock) t on s.refid=t.id      
where s_eventid in (151,152)        
      
update s set duedate=followupdate       
from #scamps s(nolock) join leadinteractionhistory(nolock) l on l.id=s.refid where s_eventid =153      
      
update s set duedate=dbo.fn_getleadpipelineexpirydate(leadid,pipelineid)       
from #scamps s (nolock) join leadpipelinemapping(nolock) l on l.id=s.refid              
where s_eventid=154      
      
update s set isvalid=0 from scheduledtodos s              
where s.isnotified=0 and s.eventid=153 and activityid in       
(select historyid from tbl_LeadEventHistory(nolock) t join #scamps m on t.LeadID=m.entityid     
where t.eventid=10 and historyid<m.activityid)                   
      
      
insert into scheduledtodos(parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,              
scheduledaction,tcampaignid)               
select distinct s.parentid,isnull(s_eventid,s.eventid) as eventid,activityid as activityid,              
getdate() as createdon,reftable as reftable,refid refid,0 isnotified,'' refcolumn,isnull(duedate,getdate()) scheduledfor,1 as isvalid,              
'Campaign' as scheduledaction,u.id as Tcampaignid              
from #scamps s join       
triggeredcampaigns(nolock) t on s.eventid=t.eventid and t.parentid=s.parentid join               
usercampaignmaster(nolock) u on u.id in (t.smscampaignid,t.whatsappcampaignid,t.mailcampaignid,t.voicecampaignid)              
where s_eventid is not null and t.isactive=1 and u.IsActive=1       
and not exists              
(select 1 from scheduledtodos(nolock) where eventid=s_eventid and reftable=reftable and refid=refid and parentid=s.ParentID and               
scheduledaction='Campaign' and tcampaignid=u.id)              
if @eventid<>10              
begin              
update s set scheduledfor=duedate,isnotified=0,isvalid=1,activityid=c.activityid from scheduledtodos s   join #scamps c      
on s.parentid=c.parentid and s.eventid=c.s_eventid and s.refid=c.refid  and s.reftable=c.reftable      
where c.s_eventid is not null  --and @duedate>getdate()                 
end              
end              
else if @eventid in (42,44,45,46,56)  --completed or deleted                
begin                  
update s set isvalid=0       
from scheduledtodos s join #scamps c on s.parentid=c.parentid and s.eventid=c.s_eventid and s.refid=c.refid  and s.reftable=c.reftable      
where c.s_eventid is not null                 
end       


insert into scheduledtodos(parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,scheduledaction,tcampaignid)         
select parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,scheduledaction,tcampaignid from #scamps            



      
drop table if exists #scamps                
drop table if exists #campaignschedule            
end try                
begin catch                
exec usp_InsertErrorInfo                
end catch                
          
end  
  
--select * from ActivityMaster  


GO

/* ============================================================
   Procedure: [dbo].[usp_executeeventcampaign1_withoutscheduling]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_executeeventcampaign1_withoutscheduling] -- 'lead',1002391                                              
@context nvarchar(20),@activityid bigint                                                
as                                                
begin                
set ansi_warnings on;    
drop table if exists #scamps    
begin try    
declare @eventid int,@refid bigint,@reftables nvarchar(100),@leadid bigint,@ParentID bigint  
create table #scamps(parentid bigint,eventid int,activityid bigint,createdon datetime,reftable nvarchar(200),    
refid bigint,isnotified int,refcolumn nvarchar(50),scheduledfor datetime,isvalid int,scheduledaction nvarchar(20),tcampaignid bigint)    
if @context='lead'    
begin    
insert into #scamps(parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,scheduledaction,tcampaignid)    
select l.parentid,l.eventid,historyid,getdate() as createdon,reftables,refids,0 as isnotified,'' refcolumn,getdate() scheduledfor,1 as isvalid,    
'Campaign' scheduledaction,1 as tcampaignid    
from tbl_leadeventhistory(nolock) l where exists     
(select 1 from triggeredcampaigns (nolock) t where t.eventid=l.eventid and t.parentid=l.parentid and t.isactive=1)    
 and historyid=@activityid   
 select @leadid=leadid,@eventid=eventid,@ParentID=parentid,@refid=refids,@reftables=reftables from  tbl_leadeventhistory(nolock) l where historyid=@activityid  
end    
else if @context='enquiry'    
begin    
insert into #scamps(parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,scheduledaction,tcampaignid)    
select l.parentid,l.eventid,historyid,getdate() as createdon,reftables,refids,0 as isnotified,'' refcolumn,getdate() scheduledfor,1 as isvalid,    
'Campaign' scheduledaction,1 as tcampaignid    
from tbl_enquiryeventhistory(nolock) l where exists     
(select 1 from triggeredcampaigns (nolock) t where t.eventid=l.eventid and t.parentid=l.parentid and t.isactive=1)    
 and historyid=@activityid    
end    
--select top 1 @eventid=eventid,@ParentID=parentid from #scamps  
  
if @eventid in (41,43,54,50,51,55,10,42,44,45,46,56)  
begin  
declare @typeofevent nvarchar(100),@scheduledaction nvarchar(50)='' ,@campaignid bigint,@seventid int     
select @typeofevent=EventType FROM   ActivityMaster(nolock) WHERE @eventid=id      
select @seventid=case when @typeofevent='task' then 151 when @typeofevent      
='Appointment' then 152 when @typeofevent='Deal' then 154 when @eventid=10 then 153 end  
--select @reftables=reftable,@refid=refid from #scamps(nolock)   
  
if exists(select 1 from triggeredcampaigns(nolock) where isactive=1 and eventid=@seventid and parentid=@ParentID)      
begin  
declare @duedate datetime,@refcolumn nvarchar(100)='',@duetype nvarchar(20)=case when @eventid=10 then 'FollowUp' else @typeofevent end      
select @duedate=case when IsAppointment=1 then startdate else enddate end,@refcolumn=case when IsAppointment=1 then 'startdate' else 'enddate' end       
from tbl_tsk_TaskHistory(nolock) where id=@refid and @typeofevent in ('task','appointment')      
select @duedate=followupdate,@refcolumn='followupdate'      
from leadinteractionhistory(nolock) where id=@refid and @eventid =10      
select @duedate=dbo.fn_getleadpipelineexpirydate(leadid,pipelineid)       
from leadpipelinemapping(nolock) l where l.id=@refid  
  and @typeofevent ='Deal'    
  
  
if @eventid  in (41,43,54,50,51,55,10)   
begin  
if exists (select 1 from scheduledtodos (nolock) s where s.isnotified=0 and s.eventid=@seventid  
and activityid in (select historyid from tbl_LeadEventHistory(nolock) where eventid=10 and leadid=@leadid)  
) and @eventid=10      
 begin      
update s set isvalid=0 from scheduledtodos s   
where s.isnotified=0 and s.eventid=@seventid and activityid in (select historyid from tbl_LeadEventHistory(nolock) where eventid=10 and leadid=@leadid)       
end   
insert into scheduledtodos(parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,  
scheduledaction,tcampaignid)   
select @ParentID as parentid,@seventid as eventid,@activityid as activityid,  
getdate() as createdon,@reftables as reftable,@refid refid,0 isnotified,@refcolumn refcolumn,@duedate scheduledfor,1 as isvalid,  
'Campaign' as scheduledaction,u.id as Tcampaignid  
from triggeredcampaigns(nolock) t join   
usercampaignmaster(nolock) u on u.id in (t.smscampaignid,t.whatsappcampaignid,t.mailcampaignid,t.voicecampaignid)  
where t.isactive=1 and u.IsActive=1 and t.eventid=@seventid and t.parentid=@parentid  
and not exists  
(select 1 from scheduledtodos(nolock) where eventid=@seventid and reftable=@reftables and refid=@refid and parentid=@ParentID and   
scheduledaction='Campaign' and tcampaignid=u.id)  
  
if @eventid<>10  
begin  
update s set scheduledfor=@duedate,isnotified=0,isvalid=1,activityid=@activityid from scheduledtodos s  
where reftable=@reftables and refid=@refid and parentid=@parentid and eventid=@seventid  --and @duedate>getdate()     
end  
end  
else if @eventid in (42,44,45,46,56)  --completed or deleted    
begin      
update scheduledtodos set isvalid=0 where reftable=@reftables and refid=@refid and parentid=@parentid and eventid=@seventid     
end  
     
end  
end  
insert into scheduledtodos(parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,scheduledaction,tcampaignid)    
select parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,scheduledaction,tcampaignid from #scamps    
drop table if exists #scamps    
end try    
begin catch    
exec usp_InsertErrorInfo    
end catch    
/*    
drop table if exists #campaignstobeexecuted                                                
drop table if exists #applicablegroups                                                
drop table if exists #Exclusions                                                
                                                
declare @parentid bigint,@eventid int,@entityid bigint, @mobile1 nvarchar(20),@mobile2 nvarchar(20),@mobile3 nvarchar(20),                                                
@email1 nvarchar(100),@email2 nvarchar(100),@email3 nvarchar(100)                                                
if @context='lead'                                                
begin                                                
select @parentid=parentid,@eventid=EventID,@entityid=leadid from                                                 
tbl_LeadEventHistory(nolock) where historyid=@activityid                                                
select @mobile1=mobileno,@mobile2=mobileno1,@mobile3=mobileno2 ,@email1=emailid,@email2=emailid1,@email3=emailid2 from                                                
userleads(nolock) where id=@entityid                                                
end                                                
if @context='enquiry'                                                
begin                                                
select @parentid=parentid,@eventid=EventID,@entityid=enquiryid from                                                 
tbl_EnquiryEventHistory(nolock) where historyid=@activityid                                                
select @mobile1=mobileno,@mobile2=mobileno1,@mobile3=mobileno2 ,@email1=emailid,@email2=emailid1,@email3=emailid2 from                                                
userenquiry(nolock) where EnquiryID=@entityid                                                
end                                                
if @context='conversationcontact'                     
begin                                                
select @parentid=parentid,@eventid=EventID,@entityid=ConversationContactID from                                                 
tbl_ContactEventHistory(nolock) where historyid=@activityid                                                
select @mobile1=mobile,@email1=emailid from                                                
conversationcontacts(nolock) where ID=@entityid                                
end                                                
                                                
select ucm.* into #campaignstobeexecuted                                                 
from usercampaignmaster(nolock) ucm                                                 
Inner join  User_detail AS Ud  on Ud.[User_ID]= AccountUsed and Ud.[Status] <> 0                                          
join triggeredcampaigns t on ucm.id in (t.smscampaignid,t.mailcampaignid,t.voicecampaignid,t.whatsappcampaignid)                                           
and t.isactive=1                                                                                            
join Price_UserSubscriptionDetails (nolock) p on p.UserID=ud.User_ID and user_id=ud.parentid and isnewplan=1 and PlanEndDate>getdate()                                
where ucm.eventid=@eventid and ucm.IsEventBased=1                                                
and ucm.parentid=@parentid and ucm.IsActive=1 and ucm.StartDate<=getdate()                                                
                                                
if exists(select 1 from #campaignstobeexecuted)                                                
begin                                                
declare @c int=(select count(distinct id) from #campaignstobeexecuted),@id bigint=0,@medium nvarchar(20),@templategroupid int=0,                   
@templateid int=0,@accountused bigint,@rowsaffected int=0,@creditsrequired numeric(18,2),@balance numeric(18,2),@contacttype nvarchar(10)                
,@wa_templatename nvarchar(100)                                          
declare @accountusedparentid bigint,@messagestring nvarchar(max)                                     
                              
--drop table if exists #replaceplaceholders                              
--create table #replaceplaceholders(strvalue nvarchar(max), cnt int)                                         
                                                
while @c>0                                                
begin           
if OBJECT_ID('tempdb..#campaignstobeexecuted') is null        
begin        
insert into debugexecuteeventcampaign(entity,jsontext,activityid,created)        
select '#campaign',@id,@activityid,getdate()        
--select '#clonemessagedeliverystatus',cast((select * from (select batchid,IsUniCode,campaignid from #clonemessagedeliverystatus) a for json auto,include_null_values) as nvarchar(max)),@activityid,getdate()        
end     
else    
begin                                       
select top 1 @id=min(id) from #campaignstobeexecuted where id>@id                                    
select @medium=medium,@templategroupid=templategroupid,@templateid=templateid,@accountused=accountused                                                
,@rowsaffected=0,@creditsrequired=0,@balance=0 ,@contacttype=ContactType                                             
 from #campaignstobeexecuted where id=@id                                                
 select @accountusedparentid=parentid from user_detail (nolock) where user_id=@accountused                                                
 drop table if exists #applicablegroups                                             
 drop table if exists #Exclusions                                             
 --drop table if exists #applicablegroups                                             
select value as applicablegroups,dbo.fn_contactexistsingroup(@context,@entityid,value) as includedstatus into #applicablegroups from #campaignstobeexecuted                                                 
cross apply dbo.fn_split(applicabilty,'#') where id=@id                                         
select value as Exclusions,dbo.fn_contactexistsingroup(@context,@entityid,value) as includedstatus into #Exclusions from #campaignstobeexecuted                                                 
cross apply dbo.fn_split(Exclusions,'#')  where id=@id                                                
if (exists (select 1 from #applicablegroups where includedstatus=1))                                                
and (not exists (select 1 from #exclusions where includedstatus=1))                                                
begin                                                
declare @jobid bigint=isnull((select max(jobid) from usercampaignhistory(nolock)),0)+1                                                
declare @uchid bigint,@ucehid bigint                                                
INSERT INTO usercampaignhistory                                         
   ( campaignid,parentid, step1, step2,step3,issms,ismail,isvoice,iswhatsapp,isscheduled,iseventbased,createdon,JobId,activityid )                                                                                 
SELECT id,parentid,0 as step1,0 as step2,0 as step3,case when medium='sms' then 1 when medium='voice' then 2 else 0 end,                                                
case when medium='mail' then 1 else 0 end,case when medium='voice' then 1 else 0 end,case when medium='whatsapp' then 1 else 0 end,isscheduled,iseventbased,getdate(),@jobid as JobId,@activityid                                                
from #campaignstobeexecuted where id=@id                                                
select @uchid=scope_identity()                                                
                                                
insert into Usercampaignexecutionhistory(CampaignID,ParentID,Jobid)                                                
select @id,@parentid,@jobid                                                
select @ucehid=scope_identity()                                                
                                              
if isnull(@templategroupid,0)<>0                                                
begin                                                
select @templateid=dbo.fn_getnexttemplateidingroup(@id)                                                
if @templateid=0           
begin                                                
update u set step1=0,Step1DateTime=GETDATE(), Step1Recipients=0,                                                
u.ReasonIfNotRun='No templateid eligible' from UserCampaignHistory u where                                                 
u.id=@uchid              
UPDATE Kd SET isrecipients=1,executiontime=getdate(),isexecuted=0,NoOfRecipients=@rowsaffected,                                                
response='No templateid eligible' FROM                                              
Usercampaignexecutionhistory Kd  where kd.id=@ucehid                                                
GOTO ENDPROC                                                
end                                         
end                                                
                                                
if @medium='sms'                                                
begin                                  
           
                         
if @parentid=  34594                           
begin                           
select @messagestring=cast(case when isnull(c.message,'')<>'' then cast(c.message as nvarchar(max))                              
when @templateid<>0 then cast((select MailContent from UserMailTemplate(nolock) where id=@templateid)                                                  
AS NVARCHAR(MAX)) end COLLATE Latin1_general_ci_ai AS NVARCHAR(MAX)) from #campaignstobeexecuted c where id=@id                             
exec usp_replaceplaceholders @activityid,@context,@messagestring,@eventid,@messagestring output                             
exec usp_replaceentityplaceholders @entityid,@context,@messagestring, @messagestring   output                        
update #campaignstobeexecuted set message=@messagestring where id=@id                              
end          
                          
INSERT INTO usercampaignexecutionrecipientsmessageTest2(Entityname,Entityid,mobile,parentid,campaignid,u_id,JobId,message            
,senderid,isunicode)                                                                                          
SELECT @context,@entityid,value as mobile,c.parentid,c.id,AccountUsed,@jobid,                                                
cast(cast(case when isnull(c.message,'')<>'' and @context ='enquiry' then (select dbo.[fn_getEnquiryMessageMail_withid](@accountusedparentid,c.message,@entityid))                                                 
when isnull(c.message,'')<>'' and @context ='lead' then (select dbo.[fn_getLeadsMailMessage_withid](@accountusedparentid,c.message,@entityid))                                                 
when @templateid<>0 and @context ='enquiry' then (select dbo.[fn_getEnquiryMessageMail_withid](@accountusedparentid,MailContent,@entityid)                                                
from UserMailTemplate(nolock) where id=@templateid)                                                
when @templateid<>0 and @context ='lead' then (select dbo.[fn_getLeadsMailMessage_withid](@accountusedparentid,MailContent,@entityid)                                                
from UserMailTemplate(nolock) where id=@templateid) end                                          
AS NVARCHAR(MAX)) COLLATE Latin1_general_ci_ai AS NVARCHAR(MAX)),c.senderid COLLATE Latin1_general_ci_ai,                                                
case when @templateid=0 then c.isunicode else (select isunicode from usermailtemplate (nolock) where id=@templateid) end                                                
from #campaignstobeexecuted c                                                 
cross apply dbo.fn_split(cast(coalesce(@mobile1,'') as nvarchar(20))+','+                                                
cast(coalesce(@mobile2,'') as nvarchar(20))+','+cast(coalesce(@mobile3,'') as nvarchar(20)),',')                                                
--left join usermailtemplate umt (nolock) on umt.id=c.TemplateID                                                
where value<>'' and isnumeric(value)=1 and id=@id                                               
set @rowsaffected=@@ROWCOUNT                                                
                                                
if @rowsaffected>0                                                
