CREATE   PROCEDURE [dbo].[usp_executeeventcampaign1_wo_max] -- 'lead',1002391                                                      
@context nvarchar(20),@activityid bigint                                                        
as                                                        
begin                        
set ansi_warnings on;            
drop table if exists #scamps            
begin try            
declare @eventid int,@refid bigint,@reftables nvarchar(100),@leadid bigint,@ParentID bigint,@enquirysource int,@leadno bigint,@enquiryid bigint    
create table #scamps(parentid bigint,eventid int,activityid bigint,createdon datetime,reftable nvarchar(200),            
refid bigint,isnotified int,refcolumn nvarchar(50),scheduledfor datetime,isvalid int,scheduledaction nvarchar(20),tcampaignid bigint)           
create table #campaignschedule(cid bigint,scheduledfor datetime,eventid int)        
if @context='lead'            
begin        
select @leadid=leadid,@eventid=eventid,@ParentID=parentid,@refid=refids,@reftables=reftables from  tbl_leadeventhistory(nolock) l where historyid=@activityid     
select @enquirysource=enquirysource,@leadno=leadno from userleads(nolock) where id=@leadid    
    
insert into #campaignschedule(cid,scheduledfor,eventid)        
select id as campaignid,        
--case when isnull(nullif(timeunit,''),'')='' then getdate()         
--when timeunit='second' then dateadd(ss,0-isnull(timebeforeevent,0),getdate())        
--when timeunit='minute' then dateadd(mi,0-isnull(timebeforeevent,0),getdate())         
--when timeunit='hour' then dateadd(HH,0-isnull(timebeforeevent,0),getdate())        
--when timeunit='day' then dateadd(dd,0-isnull(timebeforeevent,0),getdate())        
--end         
getdate()        
as scheduledfor,eventid         
from usercampaignmaster(nolock) where id in         
(select smscampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid        
union        
select mailcampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid        
union        
select voicecampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid        
union        
select whatsappcampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid        
)    
and 1=case when @enquirysource in (10,20,21) and @eventid =17 then 0    
when @enquirysource in (10,20,21) and @eventid  in (10,37) and @refid =    
(select min(id) from LeadInteractionHistory(nolock) where leadno=@leadno and parentid=@parentid)    
then 0 else 1 end    
        
insert into #scamps(parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,scheduledaction,tcampaignid)            
select l.parentid,l.eventid,historyid,getdate() as createdon,reftables,refids,0 as isnotified,'' refcolumn,scheduledfor,1 as isvalid,            
'Campaign' scheduledaction,cid as tcampaignid            
from tbl_leadeventhistory(nolock) l         
join #campaignschedule c on c.eventid=l.EventID        
where exists             
(select 1 from triggeredcampaigns (nolock) t where t.eventid=l.eventid and t.parentid=l.parentid and t.isactive=1)            
 and historyid=@activityid           
         
end            
else if @context='enquiry'            
begin        
select @eventid=eventid,@ParentID=parentid,@refid=refids,@reftables=reftables,@enquiryid=EnquiryID from  tbl_enquiryeventhistory(nolock) l where historyid=@activityid          
select @enquirysource=enquirysource from userenquiry(nolock) where enquiryid=@enquiryid    
insert into #campaignschedule(cid,scheduledfor,eventid)        
select id as campaignid,      
--case when isnull(nullif(timeunit,''),'')='' then getdate()       
--when timeunit='second' then dateadd(ss,0-isnull(timebeforeevent,0),getdate())        
--when timeunit='minute' then dateadd(mi,0-isnull(timebeforeevent,0),getdate())       
--when timeunit='hour' then dateadd(HH,0-isnull(timebeforeevent,0),getdate())        
--when timeunit='day' then dateadd(dd,0-isnull(timebeforeevent,0),getdate())        
--end       
getdate() as scheduledfor,eventid         
from usercampaignmaster(nolock) where id in         
(select smscampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid        
union        
select mailcampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid        
union        
select voicecampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid        
union        
select whatsappcampaignid from triggeredcampaigns(nolock) t  where t.parentid=@parentid and t.isactive=1 and t.eventid =@eventid        
)   
--and 1=case when @enquirysource =20 and @eventid =119 then 0    
-- else 1 end    
        
        
        
insert into #scamps(parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,scheduledaction,tcampaignid)            
select l.parentid,l.eventid,historyid,getdate() as createdon,reftables,refids,0 as isnotified,'' refcolumn,scheduledfor,1 as isvalid,            
'Campaign' scheduledaction,cid as tcampaignid            
from tbl_enquiryeventhistory(nolock) l         
join #campaignschedule c on c.eventid=l.EventID        
where exists             
(select 1 from triggeredcampaigns (nolock) t where t.eventid=l.eventid and t.parentid=l.parentid and t.isactive=1)            
 and historyid=@activityid            
end            
--select top 1 @eventid=eventid,@ParentID=parentid from #scamps          
          
if @eventid in (41,43,54,50,51,55,10,37,42,44,45,46,56)          
begin          
declare @typeofevent nvarchar(100),@scheduledaction nvarchar(50)='' ,@campaignid bigint,@seventid int             
select @typeofevent=EventType FROM   ActivityMaster(nolock) WHERE @eventid=id              
select @seventid=case when @typeofevent='task' then 151 when @typeofevent              
='Appointment' then 152 when @typeofevent='Deal' then 154 when @eventid in (10,37) then 153 end          
--select @reftables=reftable,@refid=refid from #scamps(nolock)           
          
if exists(select 1 from triggeredcampaigns(nolock) where isactive=1 and eventid=@seventid and parentid=@ParentID)              
begin          
declare @duedate datetime,@refcolumn nvarchar(100)='',@duetype nvarchar(20)=case when @eventid  in (10,37) then 'FollowUp' else @typeofevent end              
select @duedate=case when IsAppointment=1 then startdate else enddate end,@refcolumn=case when IsAppointment=1 then 'startdate' else 'enddate' end               
from tbl_tsk_TaskHistory(nolock) where id=@refid and @typeofevent in ('task','appointment')              
select @duedate=followupdate,@refcolumn='followupdate'              
from leadinteractionhistory(nolock) where id=@refid and @eventid in (10,37)             
select @duedate=dbo.fn_getleadpipelineexpirydate(leadid,pipelineid)               
from leadpipelinemapping(nolock) l where l.id=@refid          
  and @typeofevent ='Deal'            
          
          
if @eventid  in (41,43,54,50,51,55,10,37)           
begin          
if exists (select 1 from scheduledtodos (nolock) s where s.isnotified=0 and s.eventid=@seventid          
and activityid in (select historyid from tbl_LeadEventHistory(nolock) where eventid in (10,37) and leadid=@leadid)          
) and @eventid in (10,37)              
 begin              
update s set isvalid=0 from scheduledtodos s           
where s.isnotified=0 and s.eventid=@seventid and activityid in (select historyid from tbl_LeadEventHistory(nolock) where     
eventid in (10,37) and leadid=@leadid)               
end           
insert into scheduledtodos(parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,    
          
scheduledaction,tcampaignid)           
select @ParentID as parentid,@seventid as eventid,@activityid as activityid,          
getdate() as createdon,@reftables as reftable,@refid refid,0 isnotified,@refcolumn refcolumn,@duedate scheduledfor,1 as     
isvalid,'Campaign' as scheduledaction,u.id as Tcampaignid          
from triggeredcampaigns(nolock) t join           
usercampaignmaster(nolock) u on u.id in (t.smscampaignid,t.whatsappcampaignid,t.mailcampaignid,t.voicecampaignid)          
where t.isactive=1 and u.IsActive=1 and t.eventid=@seventid and t.parentid=@parentid          
and not exists          
(select 1 from scheduledtodos(nolock) where eventid=@seventid and reftable=@reftables and refid=@refid and parentid=@ParentID and           
scheduledaction='Campaign' and tcampaignid=u.id)          
          
if @eventid not in (10,37)          
begin          
update s set scheduledfor=@duedate,isnotified=0,isvalid=1,activityid=@activityid from scheduledtodos s          
where reftable=@reftables and refid=@refid and parentid=@parentid and eventid=@seventid  --and @duedate>getdate()             
end          
end          
else if @eventid in (42,44,45,46,56)  --completed or deleted            
begin              
update scheduledtodos set isvalid=0 where reftable=@reftables and refid=@refid and parentid=@parentid and eventid=@seventid             
end          
             
end          
end          
insert into scheduledtodos(parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,scheduledaction,tcampaignid)         
select parentid,eventid,activityid,createdon,reftable,refid,isnotified,refcolumn,scheduledfor,isvalid,scheduledaction,tcampaignid from #scamps            
drop table if exists #scamps            
drop table if exists #campaignschedule        
end try            
begin catch            
exec usp_InsertErrorInfo            
end catch            
end


GO

/* ============================================================
   Procedure: [dbo].[Usp_executerecipientsEventBasedcampaignVoice]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

      
--select top 10 * from UserCampaignHistory(nolock) where IsSMS=2 and IsEventBased=1 and Step1Recipients>0 order by id desc          
          
          
CREATE   PROCEDURE [dbo].[Usp_executerecipientsEventBasedcampaignVoice]                                                    
AS                                                    
BEGIN  
exec Usp_executerecipientsEventBasedcampaignVoice_withid21102020 @campid=null
                    
--declare @maxjobid bigint = (select top 1 JobId from UserCampaignHistory UCH order by ID desc)                    
--declare @maxid bigint = (select top 1 Id from UserCampaignHistory UCH order by ID desc)                    
--if ((select Step3DateTime from UserCampaignHistory UCH where ID=@maxid) is not null)                    
--begin                                                  
/*
 DECLARE @Body VARCHAR(500)                      
                    
 DEclare @JobId Bigint = (Select ISNULL(MAX(JobId),0)+1 from UserCampaignHistory UCH )                    
 declare @campaignstartdate datetime=getdate()                    
  INSERT INTO usercampaignhistory                                                    
   (                                                    
     -- ID -- this column value is auto-generated                                                    
     campaignid,                                                    
     parentid,                                                    
     step1,                                                    
     step2,                                                    
     step3,                                                   
     issms,                                                    
     ismail,                                                    
     isscheduled,                                                    
     iseventbased,                                                    
     createdon,                    
     JobId                                                    
                         
   )                                            
                                   
 SELECT 0,                                                    
        0,                                                    
        0,                                                    
        0,                                                    
        0,                                                    
        2,                                                    
        0,                                                    
        0,                                                    
        1,                                                    
        @campaignstartdate,                    
        @JobId                    
                      
 DECLARE @LastExecutedTime datetime = isnull((select Top 1 CampaignExecutedDatetime from UserCampaignExecution where issms=2 and isevent=1 order by id desc),getdate()) --isevent=0                    
                     
 --RETRY:                    
 if exists(select 1 from UserCampaignExecution where issms=2 and isnull(isevent,0)=1 and isrunning=0)                    
 begin                    
 update UserCampaignExecution set isrunning=1,cjobid=@jobid where issms=2 and isnull(isevent,0)=1                    
                     
 Declare @CampaignStarttime datetime = Getdate()                    
                                                   
 if OBJECT_ID('tempdb..#temptemplate') is not null                                  
 Begin                     
 Drop table #temptemplate                     
 end                          
                     
 SELECT      ROW_NUMBER()Over(Order by Ucm.ID,Ucm.ParentID) AS Id,                    
       ucm.ID      AS CampaignID,                                    
                   ucm.ParentID,                                    
                   A.[value]  AS Applicabilty,                                    
                   AGL.[value] AS ApplicabiltyGroupList,                                    
                   EGL.[Value] AS ExclusionsGroupList,                                  
                   ucm.NotificationMail,                                    
                   ucm.ExclusionsNumber,                                    
                   E.[Value] AS Exclusions,                                    
               ucm.InclusionsNumber,                                    
                   ucm.AccountUsed,                                    
                   ucm.SenderID,                                    
                   ucm.[Message],                                    
                   ucm.TemplateID,                                    
                   ucm.TemplateGroupID,                                    
                   ucm.IsUnicode,                                    
                   ucm.EventsName,                
                   didno,appid ,duration,isnull(credits,0) credits,route,1 priority                
                   INTO #TempTemplate                                                         
 FROM   Usercampaignmaster ucm   (nolock)                    
   Inner join  User_detail AS Ud  on Ud.[User_ID]  = AccountUsed and Ud.[Status] <> 0            
   OUTER APPLY Dbo.Fn_split(Ucm.Applicabilty, '#') AS A                     
   OUTER APPLY Dbo.Fn_split(Ucm.ApplicabiltyGroupList, '#') AS AGL                    
   OUTER APPLY Dbo.Fn_split(Ucm.ExclusionsGroupList, '#') AS  EGL                     
   OUTER APPLY Dbo.Fn_split(Ucm.Exclusions, '#') AS E                                                          
            WHERE lower(Ucm.Medium) = 'voice'  and IsEventBased=1           
                   AND DATEDIFF(                                                          
                           Minute,                                                          
                           getdate(),                                                          
                           CASE                                                           
                                WHEN Ucm.IsNeverExpire = 1 THEN DATEADD(DAY, 1,getdate())                                                          
                                ELSE ISNULL(Ucm.ExpiryDate, getdate())                                                          
                       END                                                          
                       ) > 0                                                          
                   AND DATEDIFF(Minute, getdate(),           
                   ISNULL(Ucm.StartDate, getdate()))  < 0  AND Ucm.IsActive = 1                                                          
                    
  SELECT ud.EMail,ucm.AccountUsed,ucm.Id As CampaignId,ucm.ParentID,                 
  tt.didno,tt.appid, tt.duration,tt.credits ,tt.route               
  into #UserAccountDetails                    
 FROM   UserCampaignMaster AS ucm                    
 Inner join User_Detail AS ud on ud.[User_ID] = ucm.AccountUsed                    
 Inner join #TempTemplate tt on tt.CampaignId = ucm.ID                    
    WHERE  ucm.ID = tt.CampaignID AND ucm.IsActive = 1                    
                                                     
 INSERT INTO usercampaignhistory                                                    
   (                                                    
     -- ID -- this column value is auto-generated                                                    
     campaignid,                                                    
     parentid,                                                    
     step1,                                                    
     step2,                                                    
     step3,                                                   
     issms,                                                    
     ismail,                                                    
     isscheduled,                                                    
     iseventbased,                                                    
     createdon,                    
     JobId , appid,duration, didno,route                                                     
   )                                            
                                   
 SELECT DISTINCT campaignid,                                           
        parentid,                                                    
        0,                                                    
        0,                                                    
        0,                                                
        2,                                                    
        0,                                                    
        0,                                                    
        1,                                                    
        @campaignstartdate,                    
        @JobId, appid,duration, didno,route                                 
 FROM   #temptemplate                                                    
                                                    
  IF NOT EXISTS (                                                    
        SELECT 'x'                                                    
        FROM  #temptemplate                                                    
    )                                                    
 BEGIN                                                    
     SET @Body = 'No Campaign Found'                                              
      SELECT @Body                     
      INSERT INTO usercampaignhistory                                                    
   (                                                    
     -- ID -- this column value is auto-generated                   
     campaignid,                                                    
     parentid,                                                    
     step1,                                                    
     step2,                                                    
     step3,                                                   
     issms,                                                    
     ismail,                                                    
     isscheduled,                                                    
     iseventbased,                                                    
     createdon,                    
     JobId                                                    
                         
   )                                            
                                   
 SELECT 0,                                                    
        0,                                                    
        0,                                                    
        0,                                                    
        0,                                                    
        2,                                                    
        0,                                            
        0,                                                    
        1,                                                    
        GETDATE(),                    
        @JobId                                                      
 END                                                    
 ELSE                                                    
 BEGIN                                                    
     CREATE TABLE #temptablesearchapp                                          
     (                                                    
      campaignid             BIGINT,                                                    
      searchid               BIGINT,                                                    
      parentid         BIGINT,                     
      userid           bigint,                                                   
      personname             NVARCHAR(200),                              
      companyname            NVARCHAR(200),                                                    
      mobileno               NVARCHAR(200),              
      mobileno1              NVARCHAR(200),                                                    
      mobileno2              NVARCHAR(200),                                                    
      emailid                NVARCHAR(200),                                                    
      emailid1               NVARCHAR(200),                                       
      emailid2               NVARCHAR(200),                                                    
      city                   NVARCHAR(200),                                                    
      STATE                  NVARCHAR(200),                                                    
      country                NVARCHAR(200),                                               
      countrycode            NVARCHAR(200),                                                    
      pincode                NVARCHAR(200),                                                    
      residentialaddress     NVARCHAR(500),                                                    
      officeaddress          NVARCHAR(500),                                                    
      sourcename       NVARCHAR(200),          
      mediumname             NVARCHAR(200),                                                    
      campaignname           NVARCHAR(200),                                                    
      initialremarks         NVARCHAR(1000)                                                    
     )                                                    
                                                  
     CREATE TABLE #temptablesearchexc                                                   
     (                                                    
      campaignid             BIGINT,                                                    
      searchid               BIGINT,                                                    
      parentid               BIGINT,                    
      userid     bigint,                                     
      personname             NVARCHAR(200),                                                    
      companyname            NVARCHAR(200),                                  
      mobileno               NVARCHAR(200),                                                    
      mobileno1              NVARCHAR(200),                                                    
      mobileno2        NVARCHAR(200),                                                    
      emailid                NVARCHAR(200),                                                    
      emailid1               NVARCHAR(200),                                                    
      emailid2               NVARCHAR(200),                                            city                   NVARCHAR(200),                                                    
      STATE                  NVARCHAR(200),                                                    
      country                NVARCHAR(200),                                                    
      countrycode            NVARCHAR(200),                                                    
      pincode                NVARCHAR(200),                                                    
      residentialaddress     NVARCHAR(500),                                                    
      officeaddress          NVARCHAR(500),                                                    
      sourcename             NVARCHAR(200),                                                    
      mediumname             NVARCHAR(200),                                                  
      campaignname           NVARCHAR(200),                                                    
      initialremarks         NVARCHAR(1000)                                     
     )                                                    
   INSERT INTO #temptablesearchapp(mobileno,CampaignID,ParentID,userid  )                                                          
         Select ISNULL(Usd.MobileNumber, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed                      
   FROM  #temptemplate TT                    
   Inner join  Usersearchdata AS Usd  (nolock)  on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ApplicabiltyGroupList and Tt.ApplicabiltyGroupList is not null                         
         union                       
      select distinct A.mobileno,A.CampaignID,A.ParentID,A.userid                    
        from (select f.value as mobileno,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.InclusionsNumber,',') f where isnumeric(f.value)=1 group by CampaignID,ParentID,AccountUsed,f.value ) A        
  
    
      
        
          
            
              
                
                  
                                                
                     
 INSERT INTO #temptablesearchexc (mobileno,CampaignID,ParentID,userid  )                    
SELECT ISNULL(Usd.Mobilenumber, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed FROM #temptemplate TT   Inner join   Usersearchdata AS Usd  (nolock) on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ExclusionsGroupList and                   
Tt.ExclusionsGroupList is not null                      
      union                       
select distinct A.mobileno,A.CampaignID,A.ParentID,A.userid                    
from (select f.value as mobileno,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.ExclusionsNumber,',') f where isnumeric(f.value)=1 group by CampaignID,ParentID,AccountUsed,f.value ) A                 
  
   
       
        
          
            
              
                
create table #EligibleCampaigns(Id int identity(1,1),Campaignid bigint,parentid bigint,accountused bigint,applicabilty bigint,exclusions bigint)                    
 insert into #EligibleCampaigns(Campaignid ,parentid ,accountused ,applicabilty ,exclusions)                    
 select t.Campaignid ,t.parentid ,t.accountused ,t.applicabilty ,t.exclusions from #TempTemplate t                   
 join userenquiry u on t.ParentID=u.ParentID and t.EventsName='enqadd' where u.CreatedDate>@LastExecutedTime                    
 union                    
 select t.Campaignid ,t.parentid ,t.accountused ,t.applicabilty ,t.exclusions from #TempTemplate t join userleads u on t.ParentID=u.ParentID and t.EventsName='LEDADD' where u.Createdon>@LastExecutedTime                     
 union                    
 select t.Campaignid ,t.parentid ,t.accountused ,t.applicabilty ,t.exclusions from #TempTemplate t join userleads u on t.ParentID=u.ParentID and t.EventsName='FOLDUE' where u.FollowupDate>@LastExecutedTime                     
 union                    
 select t.Campaignid ,t.parentid ,t.accountused ,t.applicabilty ,t.exclusions from #TempTemplate t join userleads u on t.ParentID=u.ParentID and t.EventsName='FOLADD'             
 join LeadInteractionHistory l on u.LeadNo=l.LeadNo and u.ParentID=l.ParentID where l.Createdon>@LastExecutedTime                    
                    
                    
                              
 DECLARE @CountCampaign     INT = (Select MAX(Id) from #EligibleCampaigns    )                                                          
                                                                   
     DECLARE @Count INT = 1                                                                                                  WHILE (@Count <= @CountCampaign)                                                    
     BEGIN                                                    
           DECLARE @Applicability BIGINT,                                                       
     @Exclusions BIGINT,                    
                 @Parentid BIGINT,                                                          
                 @Campaignid BIGINT,                    
                 @userid bigint                    
                                       
                                     
  Select @Campaignid =Campaignid, @Parentid = Parentid ,@userid=AccountUsed                    
          ,@Applicability = tt.Applicabilty,@Exclusions = tt.Exclusions                    
           from #EligibleCampaigns tt Where Id = @Count                    If(@Applicability is not null)                    
          Begin                                                   
            INSERT INTO #temptablesearchapp                                                          
       (                                                         
      PersonName,                                                          
      CompanyName,                                                          
      MobileNo,                                                          
      MobileNo1,                                            
      MobileNo2,                                                         
      EmailID,                                                          
      EmailID1,                                                          
      EmailID2,                                                          
      Country,                                                          
      [STATE],                                             
      City,                                                    
      PinCode,                            
      ResidentialAddress,                                                          
      OfficeAddress,                                                          
      SourceName,                                                          
      MediumName,                                                          
      CampaignName,                                                          
      InitialRemarks,                                                          
      SearchID,                                                          
      ParentID,                                                          
      CampaignID                                          
       )                                                          
     EXEC Usp_executeusersearch                                                          
       @ParentId,                                                          
       @Applicability,                                                          
       @Campaignid                    
                           
                      
           End                                                     
         if(@Exclusions is not null)                    
          Begin                                                     
         INSERT INTO #temptablesearchexc                                                          
       (                                                          
             PersonName,                                                          
             CompanyName,                                                          
             MobileNo,                                                          
             MobileNo1,                                                          
  MobileNo2,                                                          
             EmailID,                                                          
             EmailID1,                      
             EmailID2,                                                          
             Country,                                                          
             [STATE],                                                          
             City,                                                          
             PinCode,                                                          
             ResidentialAddress,                                                          
            OfficeAddress,                                                          
             SourceName,                                   
             MediumName,     
             CampaignName,                                                          
             InitialRemarks,                                                          
             SearchID,                                                          
             ParentID,                                                          
             CampaignID                                                          
    )                                                          
         EXEC Usp_executeusersearch                                                       
              @Parentid,                                                          
              @Exclusions,                                                          
              @Campaignid                    
                        
    END                    
     SET @Count = @Count+1                    
                         
  END                                                          
                         
     drop table #EligibleCampaigns                                           
                                                        
     SELECT distinct A.mobileno,                                                    
            A.parentid,                                                    
            A.campaignid,                    
            A.userid                                          
            INTO     #tmpemailid                                                    
     FROM   (                                                    
                SELECT Tt2.mobileno,                                                    
                       Tt2.parentid,                                                    
                       Tt2.campaignid,                    
                       tt.Accountused as userid                                                    
     FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                 
     WHERE NOT EXISTS (SELECT 1 FROM   #temptablesearchexc Tt                 
     Where (Tt2.CampaignID = Tt.CampaignID ) AND                 
     (Tt2.mobileno = Tt.mobileno OR Tt2.mobileno = Tt.mobileno1 OR Tt2.mobileno = Tt.mobileno2))             UNION                                    
        SELECT Tt2.mobileno1, Tt2.ParentID,                                                          
           Tt2.CampaignID,tt.Accountused  as userid                                                         
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                  WHERE  NOT EXISTS (SELECT 1                                                          
                 FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID )                 
                 AND ( Tt2.mobileno1 = Tt.mobileno OR Tt2.mobileno1 = Tt.mobileno1 OR                  
                 Tt2.mobileno1 = Tt.mobileno2)  )                       
                UNION                                                       
                SELECT Tt2.mobileno2,                                                          
                       Tt2.ParentID,                                                          
                       Tt2.CampaignID,tt.Accountused as userid                                                       FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                  WHERE  NOT EXISTS (SELECT 1        
  
    
       
        
         
            
              
                                                  
                 FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND                 
                 (Tt2.mobileno2 = Tt.mobileno OR Tt2.mobileno2 = Tt.mobileno1 OR                  
                 Tt2.mobileno2= Tt.mobileno2 ) )) A                                     
   IF EXISTS( SELECT * FROM   #TempTemplate WHERE  EventsName = 'ENQADD')                                    
