 FROM   #UserEnquiry AS ue Inner  join (Select Distinct CampaignID,ParentID                 
   from #TempTemplate T WHERE  EventsName = 'ENQADD') ucs on ucs.ParentID = ue.ParentID                 
  WHERE  ue.CreatedDate Between @LastExecutedTime and @CampaignStarttime                                  
    UNION                                   
    SELECT ue.MobileNo2,ue.ParentID,ue.CreatedDate ,ue.EnquiryID                                    
    FROM   #UserEnquiry AS ue Inner  join (Select Distinct CampaignID,ParentID                 
    from #TempTemplate T  WHERE  EventsName = 'ENQADD') ucs on ucs.ParentID = ue.ParentID                       
    WHERE  ue.CreatedDate Between @LastExecutedTime and @CampaignStarttime) tt                            
