     INSERT INTO UserCampaignExecutionHistory                                    
       (                                    
         -- ID -- this column value is auto-generated                                    
         CampaignID,                                    
         ExecutionTime,                                    
         NoOfRecipients,                                    
         Response,                                    
         BatchID,                                    
         IsRecipients,                                    
  IsMessages,                                    
         IsExecuted,                                    
         ParentID,                    
         Jobid                                    
       )                                    
     SELECT DISTINCT tt.CampaignID,                                    
            GETDATE(),                                    
            0,                                    
            NULL,                                    
            0,                                    
            1,                              
            1,                                    
            0,                                    
            tt.ParentID,                    
            @JobId                                    
     FROM   #TempFollowUp tt                                    
