 END                                    
                    
UPDATE A                                              
SET step1=1,step1datetime=getdate(),step1recipients = isnull(B.[RecipientsCount],0) ,          
step2=1,step2datetime=getdate(),step2recipients = isnull(B.[RecipientsCount],0)                                   
FROM [dbo].UserCampaignHistory A INNER JOIN                                               
(SELECT a.campaignid as campaignid, A.Jobid,isnull(count(e.CampaignID),0) AS [RecipientsCount]  FROM UserCampaignHistory A (nolock)                     
    left outer join [dbo].usercampaignexecutionrecipientVoice2 e (nolock)                 
    on e.CampaignID=a.CampaignID and e.jobid=@JobId                     
    Where A.Jobid = @jobId                    
    group by a.campaignid  , A.Jobid) B                                              
ON A.[campaignid] = B.[campaignid] and A.Jobid = B.JoBId                    
                                    
  IF OBJECT_ID(N'tempdb..#TempTableSearchApp', N'U') IS NOT NULL                                    
  BEGIN                                    
   DROP TABLE #TempTableSearchApp                                    
  END                                    
                
  IF OBJECT_ID(N'tempdb..#temptablesearchexc', N'U') IS NOT NULL                                    
  BEGIN                                    
                                    
   DROP TABLE #temptablesearchexc                                    
                                    
  END                                    
                                    
  IF OBJECT_ID(N'tempdb..#TempTemplate', N'U') IS NOT NULL                                    
  BEGIN                                    
     DROP TABLE #TempTemplate                                    
  END                                    
                     
                     
UPDATE A                                       
SET step1=1,step2=1,step1datetime=getdate(),step2datetime=getdate()                              
FROM [dbo].UserCampaignHistory A where A.Jobid = @JobId                     
                 
DROP TABLE #tmpemailid                                                          
                      
END                                                    
                    
 update UserCampaignExecution                                                        
 set CampaignExecutedDatetime=@CampaignStarttime,isevent=1                                                        
 where issms=2 and isnull(isevent,0)=1                          
 --select 11                                   
exec [Usp_insertclonedeliverycampaignVoice] @Jobid                    
end                    
  else                    
  begin                    
  if (select Lasterrorreported from UserCampaignExecution where issms=2                 
  and isnull(isevent,0)=1) is null or                 
  (DATEDIFF(mi,(select isnull(Lasterrorreported,dateadd(mi,-6,getdate()))                 
  from UserCampaignExecution where issms=2 and isnull(isevent,0)=1),getdate())>5 and                 
  DATEDIFF(mi,(select isnull(CampaignExecutedDatetime,dateadd(mi,-6,getdate()))                 
  from UserCampaignExecution where issms=2 and isnull(isevent,0)=1),getdate())>5)                    
  begin                    
  declare @campaignstart datetime =(select CampaignExecutedDatetime                 
  from UserCampaignExecution where issms=2 and isnull(isevent,0)=1),                 
  @lastjobid bigint =(select isnull(cjobid,        
  (select top 1 jobid from usercampaignhistory (nolock) where issms=2 and iseventbased=1 and campaignid<>0 and jobid<>@jobid order by id desc)) from usercampaignexecution        
  where issms=2 and isevent=1)        
  select top 1 @campaignstart = CreatedOn from usercampaignhistory(nolock) where jobid=@lastjobid        
        
  declare @step int = (select top 1 case when step2datetime is null then 2 else 3 end                 
  from usercampaignhistory (nolock) where jobid=@lastjobid)                    
  declare @mobile nvarchar(20),@message nvarchar(2000),@total int,@attime datetime,                
  @appid nvarchar(2000)                    
                     
  if exists(select mobile,COUNT(mobile)Count from                    
(select top 50 mobile,b.batchid from batchinfo b (nolock)                 
join dbo.Voice_DeliveryStatus m (nolock)on m.BatchID=b.batchid                 
where TotalRecords=1 order by BatchInfoID desc) A                    
group by Mobile having COUNT(mobile)>2)                    
  begin                    
   select top 1 @mobile=mobile,@total=COUNT(mobile),@attime=MAX(batchinserttime),                
  @appid = appid                 
  from                      
(select top 50 mobile,b.batchid,BatchInsertTime,b.appid from BatchVoiceInfo b (nolock)                 
 join Voice_DeliveryStatus m (nolock)on m.BatchID=b.batchid where TotalRecords=1                 
 order by BatchInfoID desc) A group by Mobile,appid having COUNT(mobile)>2                    
  end                    
                 
   declare @error nvarchar(200)='Last Voice Campaign with jobid ' +                 
   cast(@lastjobid as varchar(10)) + ' failed at step ' + cast(@step as varchar) +                 
   ' running since ' + cast(@campaignstart as nvarchar(20)) +                 
   case when @mobile is null then '.' else 'Effected mobile '+ @mobile + ' - Got SMS ' +                
   cast(@total as nvarchar) + ' times at ' +cast(@attime as nvarchar(20))+                
   ' with appid ' + @appid end                      
  exec usp_InsertCampaignError 'VOICE',1,@error                  
                          
--  declare @error nvarchar(200)=    
--'Last Campaign with jobid ' + cast(@lastjobid as varchar(10)) + ' failed at step ' + cast(@step as varchar) + ' running since ' + cast(@campaignstart as nvarchar(20)) + case when @mobile is null then '.' else 'Effected mobil                
                  
--e '+ @mobile + ' - Got SMS ' +  cast(@total as nvarchar) + ' times at ' +cast(@attime as nvarchar(20))+' with message as ' + @message end                      
  --exec usp_InsertCampaignError'SMS',1,@error                    
  --if @step=2           
  --begin                  
  -- exec Usp_insertclonedeliverycampaignVoice @lastjobid                      
  ----exec Usp_userexecutecampaignmessagesCorrected @lastjobid                    
  --end                    
  if @step=3                    
  begin                 
   exec Usp_insertclonedeliverycampaignVoice @lastjobid                       
 -- exec Usp_insertclonedeliverycampaignCorrected @lastjobid                    
  end                    
  update UserCampaignExecution set Lasterrorreported=GETDATE()                 
  where issms=2 and isnull(isevent,0)=1                    
  --GOTO RETRY                    
  end                    
  end                    
  */
END                 
                
    


