/* ============================================================
   Procedure: [dbo].[Usp_executerecipientsEventBasedcampaignVoice_withid21102020]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

    
--select top 10 * from UserCampaignHistory(nolock) where IsSMS=2 and IsEventBased=1 and Step1Recipients>0 order by id desc        
        
        
CREATE   PROCEDURE [dbo].[Usp_executerecipientsEventBasedcampaignVoice_withid21102020] @campid bigint=null                                                  
AS                                                  
BEGIN                    
--declare @maxjobid bigint = (select top 1 JobId from UserCampaignHistory UCH order by ID desc)                  
--declare @maxid bigint = (select top 1 Id from UserCampaignHistory UCH order by ID desc)                  
--if ((select Step3DateTime from UserCampaignHistory UCH where ID=@maxid) is not null)                  
--begin              
begin try               
--declare @campid bigint=null                                                  
 DECLARE @Body VARCHAR(500)                    
                  
 DEclare @JobId Bigint = (Select ISNULL(MAX(JobId),0)+1 from UserCampaignHistory UCH(nolock) )  
 print @jobid
 declare @campaignstartdate datetime=getdate()                  
  INSERT INTO usercampaignhistory                                                  
   (                                                  
     -- ID -- this column value is auto-generated                                                  
     campaignid,                                                  
     parentid,                                                  
     step1,                                                  
     step2,                                                  
     step3,                                                 
     issms,                                                  
     ismail,                                                  
     isscheduled,                                                  
     iseventbased,                                                  
     createdon,                  
     JobId                                                  
                       
   )                                          
                                 
 SELECT 0,                                                  
        0,                                                  
        0,                                                  
        0,                                                  
        0,                                                  
        2,                                                  
        0,                                                  
        0,                                                  
        1,                                                  
        @campaignstartdate,                  
        @JobId                  
                    
 DECLARE @LastExecutedTime datetime = isnull((select Top 1 CampaignExecutedDatetime from UserCampaignExecution where issms=2 and isevent=1 order by id desc),getdate()) --isevent=0                  
                   
 --RETRY:                  
 if @campid is not null or exists(select 1 from UserCampaignExecution where issms=2 and isnull(isevent,0)=1 and isrunning=0)                  
 begin                  
 if @campid is null
 update UserCampaignExecution set isrunning=1,cjobid=@jobid where issms=2 and isnull(isevent,0)=1                  
                   
 Declare @CampaignStarttime datetime = Getdate()                  
                                                 
 if OBJECT_ID('tempdb..#temptemplate') is not null                                
 Begin                   
 Drop table #temptemplate                   
 end                        
                   
 SELECT      ROW_NUMBER()Over(Order by Ucm.ID,Ucm.ParentID) AS Id,                  
       ucm.ID      AS CampaignID,                                  
                   ucm.ParentID,                                  
                   A.[value]  AS Applicabilty,                                  
                   AGL.[value] AS ApplicabiltyGroupList,                                  
                   EGL.[Value] AS ExclusionsGroupList,                                  
                   ucm.NotificationMail,                                  
                   ucm.ExclusionsNumber,                                  
                   E.[Value] AS Exclusions,                                  
               ucm.InclusionsNumber,                                  
                   ucm.AccountUsed,                                  
                   ucm.SenderID,                                  
                   ucm.[Message],                                  
                   ucm.TemplateID,                                  
                   ucm.TemplateGroupID,                                  
                   ucm.IsUnicode,                                  
                   ucm.EventsName,              
                   didno,appid ,duration,isnull(credits,0) credits,route,1 priority              
                   INTO #TempTemplate                                                       
 FROM   Usercampaignmaster ucm   (nolock)                  
   Inner join  User_detail AS Ud(nolock)  on Ud.[User_ID]  = AccountUsed and Ud.[Status] <> 0
   join (select distinct user_id as parentaccount from User_detail AS Ud(nolock)
   join Price_UserSubscriptionDetails(nolock) p on p.UserID=ud.parentid and IsNewPlan=1 and planenddate>getdate() and ud.status=1
   and ud.user_id=ud.ParentID
   )
   p on p.parentaccount=ucm.ParentID          
   OUTER APPLY Dbo.Fn_split(Ucm.Applicabilty, '#') AS A                   
   OUTER APPLY Dbo.Fn_split(Ucm.ApplicabiltyGroupList, '#') AS AGL                  
   OUTER APPLY Dbo.Fn_split(Ucm.ExclusionsGroupList, '#') AS  EGL                   
   OUTER APPLY Dbo.Fn_split(Ucm.Exclusions, '#') AS E                                                        
   WHERE lower(Ucm.Medium) = 'voice'  and IsEventBased=1         
                   AND DATEDIFF(                                                        
                           Minute,                                                        
                           getdate(),                                                        
                           CASE                                                         
                                WHEN Ucm.IsNeverExpire = 1 THEN DATEADD(DAY, 1,getdate())                                                        
                                ELSE ISNULL(Ucm.ExpiryDate, getdate())                                                        
                       END                                                        
                       ) > 0                                                        
                   AND DATEDIFF(Minute, getdate(),         
                   ISNULL(Ucm.StartDate, getdate()))  < 0  AND Ucm.IsActive = 1                                                        
				   and ucm.id=case when @campid is not null then @campid else ucm.id end
				   and nullif(ucm.eventid,0) is null                                                                                     
  
  print '#temptemplate compiled'
  SELECT ud.EMail,ucm.AccountUsed,ucm.Id As CampaignId,ucm.ParentID,               
  tt.didno,tt.appid, tt.duration,tt.credits ,tt.route             
  into #UserAccountDetails                  
 FROM   UserCampaignMaster AS ucm (nolock)                 
 Inner join User_Detail AS ud (nolock) on ud.[User_ID] = ucm.AccountUsed                  
 Inner join #TempTemplate tt on tt.CampaignId = ucm.ID                  
    WHERE  ucm.ID = tt.CampaignID AND ucm.IsActive = 1                  
                                                   
 INSERT INTO usercampaignhistory                                                  
   (                                                  
     -- ID -- this column value is auto-generated                                                  
     campaignid,                                                  
     parentid,                                                  
     step1,                                                  
     step2,                                                  
     step3,                                                 
     issms,                                                  
     ismail,                                                  
     isscheduled,                                                  
     iseventbased,                                                  
