/* ============================================================
   Procedure: [dbo].[Usp_executerecipientsEventBasedcampaignVoicewithFollowupdue]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

    
--select top 10 * from UserCampaignHistory(nolock) where IsSMS=2 and IsEventBased=1 and Step1Recipients>0 order by id desc        
        
        
CREATE   PROCEDURE [dbo].[Usp_executerecipientsEventBasedcampaignVoicewithFollowupdue]                                                  
AS                                                  
BEGIN                    
--declare @maxjobid bigint = (select top 1 JobId from UserCampaignHistory UCH order by ID desc)                  
--declare @maxid bigint = (select top 1 Id from UserCampaignHistory UCH order by ID desc)                  
--if ((select Step3DateTime from UserCampaignHistory UCH where ID=@maxid) is not null)                  
--begin                                                
 DECLARE @Body VARCHAR(500)                    
                  
 DEclare @JobId Bigint = (Select ISNULL(MAX(JobId),0)+1 from UserCampaignHistory UCH )                  
 declare @campaignstartdate datetime=getdate()                  
  INSERT INTO usercampaignhistory                                                  
   (                                                  
     -- ID -- this column value is auto-generated                                                  
     campaignid,                                                  
     parentid,                                                  
     step1,                                                  
     step2,                                                  
     step3,                                                 
     issms,                                                  
     ismail,                                                  
     isscheduled,                                                  
     iseventbased,                                                  
     createdon,                  
     JobId                                                  
                       
   )                                          
                                 
 SELECT 0,                                                  
        0,                                                  
        0,                                                  
        0,                                                  
        0,                                                  
        2,                                                  
        0,                                                  
        0,                                                  
        1,                                                  
        @campaignstartdate,                  
        @JobId                  
                    
 DECLARE @LastExecutedTime datetime = isnull((select Top 1 CampaignExecutedDatetime from UserCampaignExecution where issms=2 and isevent=1 order by id desc),getdate()) --isevent=0                  
                   
 --RETRY:                  
 if exists(select 1 from UserCampaignExecution where issms=2 and isnull(isevent,0)=1 and isrunning=0)                  
 begin                  
 update UserCampaignExecution set isrunning=1,cjobid=@jobid where issms=2 and isnull(isevent,0)=1                  
                   
 Declare @CampaignStarttime datetime = Getdate()                  
                                                 
 if OBJECT_ID('tempdb..#temptemplate') is not null                                
 Begin                   
 Drop table #temptemplate                   
 end                        
                   
 SELECT      ROW_NUMBER()Over(Order by Ucm.ID,Ucm.ParentID) AS Id,                  
       ucm.ID      AS CampaignID,                                  
                   ucm.ParentID,                                  
                   A.[value]  AS Applicabilty,                                  
                   AGL.[value] AS ApplicabiltyGroupList,                                  
                   EGL.[Value] AS ExclusionsGroupList,                                  
                   ucm.NotificationMail,                                  
                   ucm.ExclusionsNumber,                                  
                   E.[Value] AS Exclusions,                                  
               ucm.InclusionsNumber,                                  
                   ucm.AccountUsed,                                  
                   ucm.SenderID,                                  
                   ucm.[Message],                                  
                   ucm.TemplateID,                                  
                   ucm.TemplateGroupID,                                  
                   ucm.IsUnicode,                                  
                   ucm.EventsName,              
                   didno,appid ,duration,isnull(credits,0) credits,route,1 priority              
                   INTO #TempTemplate                                                       
 FROM   Usercampaignmaster ucm   (nolock)                  
   Inner join  User_detail AS Ud  on Ud.[User_ID]  = AccountUsed and Ud.[Status] <> 0          
   OUTER APPLY Dbo.Fn_split(Ucm.Applicabilty, '#') AS A                   
   OUTER APPLY Dbo.Fn_split(Ucm.ApplicabiltyGroupList, '#') AS AGL                  
   OUTER APPLY Dbo.Fn_split(Ucm.ExclusionsGroupList, '#') AS  EGL                   
   OUTER APPLY Dbo.Fn_split(Ucm.Exclusions, '#') AS E                                                        
            WHERE lower(Ucm.Medium) = 'voice'  and IsEventBased=1         
                   AND DATEDIFF(                                                        
                           Minute,                                                        
                           getdate(),                                                        
                           CASE                                                         
                                WHEN Ucm.IsNeverExpire = 1 THEN DATEADD(DAY, 1,getdate())                                                        
                                ELSE ISNULL(Ucm.ExpiryDate, getdate())                                                        
                       END                                                        
                       ) > 0                                                        
                   AND DATEDIFF(Minute, getdate(),         
                   ISNULL(Ucm.StartDate, getdate()))  < 0  AND Ucm.IsActive = 1                                                        
                  
  SELECT ud.EMail,ucm.AccountUsed,ucm.Id As CampaignId,ucm.ParentID,               
  tt.didno,tt.appid, tt.duration,tt.credits ,tt.route             
  into #UserAccountDetails                  
 FROM   UserCampaignMaster AS ucm                  
 Inner join User_Detail AS ud on ud.[User_ID] = ucm.AccountUsed                  
 Inner join #TempTemplate tt on tt.CampaignId = ucm.ID                  
    WHERE  ucm.ID = tt.CampaignID AND ucm.IsActive = 1                  
                                                   
 INSERT INTO usercampaignhistory                                                  
   (                                                  
     -- ID -- this column value is auto-generated                                                  
     campaignid,                                                  
     parentid,                                                  
     step1,                                                  
     step2,                                                  
     step3,                                                 
     issms,                                                  
     ismail,                                                  
     isscheduled,                                                  
     iseventbased,                                                  
     createdon,                  
     JobId , appid,duration, didno,route                                                   
   )                                          
                                 
 SELECT DISTINCT campaignid,                                         
        parentid,                                                  
        0,                                                  
        0,                                                  
        0,                                              
        2,                                                  
        0,                                                  
        0,                                                  
        1,                                                  
        @campaignstartdate,                  
        @JobId, appid,duration, didno,route                               
 FROM   #temptemplate                                                  
                                                  
  IF NOT EXISTS (                                                  
        SELECT 'x'                                                  
        FROM  #temptemplate                                                  
    )                                                  
 BEGIN                                                  
     SET @Body = 'No Campaign Found'                                            
      SELECT @Body                   
      INSERT INTO usercampaignhistory                                                  
   (                                                  
     -- ID -- this column value is auto-generated                 
     campaignid,                                                  
     parentid,                                                  
     step1,                                                  
     step2,                                                  
     step3,                                                 
     issms,                                                  
     ismail,                                                  
     isscheduled,                                                  
     iseventbased,                                                  
     createdon,                  
     JobId                                                  
                       
   )                                          
                                 
 SELECT 0,                                                  
        0,                                                  
        0,                                                  
        0,                                                  
        0,                                                  
        2,                                                  
        0,                                          
        0,                                                  
        1,                                                  
        GETDATE(),                  
        @JobId                                                    
 END                                                  
 ELSE                                                  
 BEGIN                                                  
     CREATE TABLE #temptablesearchapp                                        
     (                                                  
      campaignid             BIGINT,                                                  
      searchid               BIGINT,                                                  
      parentid         BIGINT,                   
      userid           bigint,                                                 
      personname             NVARCHAR(200),                            
      companyname            NVARCHAR(200),                                                  
      mobileno               NVARCHAR(200),                                                  
      mobileno1              NVARCHAR(200),                                                  
      mobileno2              NVARCHAR(200),                                                  
      emailid                NVARCHAR(200),                                                  
      emailid1               NVARCHAR(200),                                     
      emailid2               NVARCHAR(200),                                                  
      city                   NVARCHAR(200),                                                  
      STATE                  NVARCHAR(200),                                                  
      country                NVARCHAR(200),                                             
      countrycode            NVARCHAR(200),                                                  
      pincode                NVARCHAR(200),                                                  
      residentialaddress     NVARCHAR(500),                                                  
      officeaddress          NVARCHAR(500),                                                  
      sourcename       NVARCHAR(200),        
      mediumname             NVARCHAR(200),                                                  
      campaignname           NVARCHAR(200),                                                  
      initialremarks         NVARCHAR(1000)                                                  
     )                                                  
                                                
     CREATE TABLE #temptablesearchexc                                                 
     (                                                  
      campaignid             BIGINT,                                                  
      searchid               BIGINT,                                                  
      parentid               BIGINT,                  
      userid     bigint,                                   
      personname             NVARCHAR(200),                                                  
      companyname            NVARCHAR(200),                                
      mobileno               NVARCHAR(200),                                                  
      mobileno1              NVARCHAR(200),                                                  
      mobileno2        NVARCHAR(200),                                                  
      emailid                NVARCHAR(200),                                                  
      emailid1               NVARCHAR(200),                                                  
      emailid2               NVARCHAR(200),                                            city                   NVARCHAR(200),                                                  
      STATE                  NVARCHAR(200),                                                  
      country                NVARCHAR(200),                                                  
      countrycode            NVARCHAR(200),                                                  
      pincode                NVARCHAR(200),                                                  
      residentialaddress     NVARCHAR(500),                                                  
      officeaddress          NVARCHAR(500),                                                  
      sourcename             NVARCHAR(200),                                                  
      mediumname             NVARCHAR(200),                                                
      campaignname           NVARCHAR(200),                                                  
      initialremarks         NVARCHAR(1000)                                   
     )                                                  
   INSERT INTO #temptablesearchapp(mobileno,CampaignID,ParentID,userid  )                                                        
         Select ISNULL(Usd.MobileNumber, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed                    
   FROM  #temptemplate TT                  
   Inner join  Usersearchdata AS Usd  (nolock)  on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ApplicabiltyGroupList and Tt.ApplicabiltyGroupList is not null                       
         union                     
      select distinct A.mobileno,A.CampaignID,A.ParentID,A.userid                  
        from (select f.value as mobileno,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.InclusionsNumber,',') f where isnumeric(f.value)=1 group by CampaignID,ParentID,AccountUsed,f.value ) A        
  
    
      
        
          
            
              
                
                                              
                   
 INSERT INTO #temptablesearchexc (mobileno,CampaignID,ParentID,userid  )                  
SELECT ISNULL(Usd.Mobilenumber, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed FROM #temptemplate TT   Inner join   Usersearchdata AS Usd  (nolock) on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ExclusionsGroupList and                 
Tt.ExclusionsGroupList is not null                    
      union                     
select distinct A.mobileno,A.CampaignID,A.ParentID,A.userid                  
from (select f.value as mobileno,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.ExclusionsNumber,',') f where isnumeric(f.value)=1 group by CampaignID,ParentID,AccountUsed,f.value ) A                 
 
     
      
        
          
            
              
create table #EligibleCampaigns(Id int identity(1,1),Campaignid bigint,parentid bigint,accountused bigint,applicabilty bigint,exclusions bigint)                  
 insert into #EligibleCampaigns(Campaignid ,parentid ,accountused ,applicabilty ,exclusions)                  
 select t.Campaignid ,t.parentid ,t.accountused ,t.applicabilty ,t.exclusions from #TempTemplate t                 
 join userenquiry u on t.ParentID=u.ParentID and t.EventsName='enqadd' where u.CreatedDate>@LastExecutedTime                  
 union                  
 select t.Campaignid ,t.parentid ,t.accountused ,t.applicabilty ,t.exclusions from #TempTemplate t join userleads u on t.ParentID=u.ParentID and t.EventsName='LEDADD' where u.Createdon>@LastExecutedTime                   
 union                  
 select t.Campaignid ,t.parentid ,t.accountused ,t.applicabilty ,t.exclusions from #TempTemplate t join userleads u on t.ParentID=u.ParentID and t.EventsName='FOLDUE' where u.FollowupDate>@LastExecutedTime                   
 union                  
 select t.Campaignid ,t.parentid ,t.accountused ,t.applicabilty ,t.exclusions from #TempTemplate t join userleads u on t.ParentID=u.ParentID and t.EventsName='FOLADD'           
 join LeadInteractionHistory l on u.LeadNo=l.LeadNo and u.ParentID=l.ParentID where l.Createdon>@LastExecutedTime                  
                  
                  
                            
 DECLARE @CountCampaign     INT = (Select MAX(Id) from #EligibleCampaigns    )                                                        
                                                                 
     DECLARE @Count INT = 1                                                                                                  WHILE (@Count <= @CountCampaign)                                                  
     BEGIN                                                  
           DECLARE @Applicability BIGINT,                                                     
     @Exclusions BIGINT,                  
                 @Parentid BIGINT,                                                        
                 @Campaignid BIGINT,                  
                 @userid bigint                  
                                     
                                   
          Select @Campaignid =Campaignid, @Parentid = Parentid ,@userid=AccountUsed                  
          ,@Applicability = tt.Applicabilty,@Exclusions = tt.Exclusions                  
           from #EligibleCampaigns tt Where Id = @Count                    If(@Applicability is not null)                  
          Begin                                                 
            INSERT INTO #temptablesearchapp                                                        
       (                                                       
      PersonName,                                                        
      CompanyName,                                                        
      MobileNo,                                                        
      MobileNo1,                                          
      MobileNo2,                                                       
      EmailID,                                                        
      EmailID1,                                                        
      EmailID2,                                                        
      Country,                                                        
      [STATE],                                           
      City,                                                  
      PinCode,                          
      ResidentialAddress,                                                        
      OfficeAddress,                                                        
      SourceName,                                                        
      MediumName,                                                        
      CampaignName,                                                        
      InitialRemarks,                                                        
      SearchID,                                                        
      ParentID,                                                        
      CampaignID                                        
       )                                                        
     EXEC Usp_executeusersearch                                                        
       @ParentId,                                                        
       @Applicability,                                                        
       @Campaignid                  
                         
                    
           End                                                   
         if(@Exclusions is not null)                  
