       (                                                        
             PersonName,                                                        
             CompanyName,                                                        
             MobileNo,                                                        
             MobileNo1,                                                        
  MobileNo2,                                                        
             EmailID,                                                        
             EmailID1,                    
             EmailID2,                                                        
             Country,                                                        
             [STATE],                                                        
             City,                                                        
             PinCode,                                                        
             ResidentialAddress,                                                        
            OfficeAddress,                                                        
             SourceName,                                 
             MediumName,                                                        
             CampaignName,                                                        
             InitialRemarks,                                                        
             SearchID,                                                        
             ParentID,                                                        
             CampaignID                                                        
    )                                                        
         EXEC Usp_executeusersearch                                                     
              @Parentid,                                                        
              @Exclusions,                                                        
              @Campaignid                  
                      
