      campaignid     BIGINT                   
     )                              
                                   
                                   
                        
                                   
                                   
                                   
                                   
     CREATE TABLE #tempapplicabilitylists                              
     (                              
      listid         BIGINT,                              
      parentid       BIGINT,                              
      campaignid     BIGINT                              
     )                              
                                 
                                   
                                   
                                   
                                   
                                   
                                   
     INSERT INTO #tempapplicability                              
       (                              
         searchid,                              
