     DROP TABLE #tempapplicabilitylists                              
                                   
                                   
                                   
                                   
                                   
                                   
                                   
     SELECT A.mobileno,                              
            A.parentid,                              
            A.campaignid                              
                                          
                                          
                                          
            INTO     #tempmobileno                              
     FROM   (                              
                SELECT Tt2.mobileno,                              
                       Tt2.parentid,                              
                       Tt2.campaignid                              
                FROM   #temptablesearchapp Tt2               
          WHERE  Tt2.mobileno NOT IN (SELECT Tt.mobileno       
                                      FROM   #temptablesearchexc Tt)                            
                       OR  Tt2.mobileno NOT IN (SELECT Tt.mobileno1                              
                     FROM   #temptablesearchexc Tt)                              
                       OR  Tt2.mobileno NOT IN (SELECT Tt.mobileno2                              
                                                FROM   #temptablesearchexc Tt)                              
                       OR  Tt2.mobileno1 NOT IN (SELECT Tt.mobileno                              
                                                 FROM   #temptablesearchexc                               
                                                                                      
                                                                                      
                                                                                      
                                                        Tt)                              
                       OR  Tt2.mobileno1 NOT IN (SELECT Tt.mobileno1                              
                                                 FROM   #temptablesearchexc                               
                                                                                      
                                                                                      
                                                                                      
                                                        Tt)                              
                       OR  Tt2.mobileno1 NOT IN (SELECT Tt.mobileno2                              
                                                 FROM   #temptablesearchexc                               
                                                                                      
                                                                                      
                                                                                      
                                                        Tt)                              
    OR  Tt2.mobileno2 NOT IN (SELECT Tt.mobileno           
    FROM   #temptablesearchexc                               
                                                                 
                                                                                      
                                                                                      
                                                        Tt)                              
                       OR  Tt2.mobileno2 NOT IN (SELECT Tt.mobileno1                              
                                                 FROM   #temptablesearchexc                               
                                                                                      
                                                                                      
                                                                                      
                                                        Tt)                              
                       OR  Tt2.mobileno2 NOT IN (SELECT Tt.mobileno2                              
                                                 FROM   #temptablesearchexc                               
                                                                                      
                                                                                      
                                                                                      
                                                        Tt)                              
                                              
                                              
                                              
                UNION                              
                                              
                                              
                                              
                SELECT Tt2.mobileno1,                              
                       Tt2.parentid,                              
                       Tt2.campaignid          
                FROM   #temptablesearchapp Tt2                              
                WHERE  Tt2.mobileno NOT IN (SELECT Tt.mobileno                              
                              FROM   #temptablesearchexc Tt)                              
                       OR  Tt2.mobileno NOT IN (SELECT Tt.mobileno1                              
                                                FROM   #temptablesearchexc Tt)                              
                       OR  Tt2.mobileno NOT IN (SELECT Tt.mobileno2                              
                                                FROM   #temptablesearchexc Tt)                              
                       OR  Tt2.mobileno1 NOT IN (SELECT Tt.mobileno                              
                   FROM   #temptablesearchexc                               
                                                                                      
                                                                                      
                                                                                      
                                                        Tt)                              
                       OR  Tt2.mobileno1 NOT IN (SELECT Tt.mobileno1                              
                                                 FROM   #temptablesearchexc                               
                                                                                      
                                                                                      
                                                                                      
        Tt)                              
                       OR  Tt2.mobileno1 NOT IN (SELECT Tt.mobileno2                              
                                                 FROM   #temptablesearchexc                               
                                                                                      
                             
                                                                                      
                                                        Tt)                              
                       OR  Tt2.mobileno2 NOT IN (SELECT Tt.mobileno                              
                                                 FROM   #temptablesearchexc              
                                                                                      
                                                                                      
                                                                                      
                                                        Tt)                         
                       OR  Tt2.mobileno2 NOT IN (SELECT Tt.mobileno1                              
                                                 FROM   #temptablesearchexc                               
                                                                                      
                                                         
                                                                                      
                                                        Tt)                              
                       OR  Tt2.mobileno2 NOT IN (SELECT Tt.mobileno2                              
                                                 FROM   #temptablesearchexc                               
                                                                                      
                                                                                      
                                                                  
                                                        Tt)                              
                                              
                                              
                                              
                UNION                              
          
                                              
                                              
                SELECT Tt2.mobileno2,                              
                       Tt2.parentid,                              
 Tt2.campaignid                              
