update usercampaignhistory set step1=1,step1datetime=getdate() where ID in (select campaignrunid from ##campaignrun)     
end    
   else     
  begin    
  update u set step1=1,step1datetime=getdate() from usercampaignhistory u join #temptemplate t on u.CampaignID=t.CampaignID  where u.ID=(select MAX(id) from usercampaignhistory u1 where u1.CampaignID=u.CampaignID)  
  end    
DROP TABLE #temptemplate              
END 


