     createdon,      
     JobId                                      
           
   )                              
                     
 SELECT 0,                                      
        0,                                      
        0,                                      
        0,                                      
        0,                                      
        1,                                      
        0,                                      
        1,                                      
        0,                                      
        GETDATE(),      
        @JobId                                   
