    UNION                         
                       
        SELECT Tt2.mobileno1,                                            
                      Tt2.ParentID,                                            
           Tt2.CampaignID,tt.Accountused  as userid                                           
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                      
                 WHERE Tt2.mobileno1 is not null and NOT EXISTS (SELECT 1                                            
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.mobileno1 = Tt.mobileno OR Tt2.mobileno1 = Tt.mobileno1 OR  Tt2.mobileno1 = Tt.mobileno2)  )         
                UNION                                            
