        1,                                    
        0,                                    
        @campaignstartdate,    
        @JobId  
   
      
 if exists(select 1 from UserCampaignExecution where issms=1 and isnull(isevent,0)=0 and isrunning=0)    
 begin    
 --update UserCampaignExecution set isrunning=1 where issms=1 and isnull(isevent,0)=0    
     
 Declare @CampaignStarttime datetime = Getdate()      
    
 if OBJECT_ID('tempdb..#temptemplate') is not null                  
 Begin     
 Drop table #temptemplate     
 end          
                                
 SELECT ROW_NUMBER()Over(Order by Ucm.ID,Ucm.ParentID) AS Id,    
        ucm.id as campaignid,                                    
        ucm.parentid,                                    
        A.value as applicabilty,                                    
        Agl.value as applicabiltygrouplist,                                    
        egl.value as exclusionsgrouplist,                                    
        ucm.notificationmail,                                    
        ucm.exclusionsnumber,                                    
        e.value as exclusions,                                    
        ucm.inclusionsnumber,                                    
        ucm.accountused,                                    
        ucm.senderid,                                    
        ucm.[message],                                    
        ucm.templateid,                                    
        ucm.templategroupid,                                    
        ucm.isunicode                                    
        INTO #temptemplate                                    
 FROM   Usercampaignmaster ucm   (nolock)    
   Inner join  User_detail AS Ud  on Ud.[User_ID]  = AccountUsed and Ud.[Status] <> 0                                            OUTER APPLY Dbo.Fn_split(Ucm.Applicabilty, '#') AS A     
   OUTER APPLY Dbo.Fn_split(Ucm.ApplicabiltyGroupList, '#') AS AGL    
   OUTER APPLY Dbo.Fn_split(Ucm.ExclusionsGroupList, '#') AS  EGL     
   OUTER APPLY Dbo.Fn_split(Ucm.Exclusions, '#') AS E                                          
            WHERE Ucm.MailReplyTo = ''  and isscheduled=1  and ucm.id in (select value from dbo.fn_split(@campaignstorun,','))                                          
                   /*AND convert(varchar(20),Ucm.NextExecuteDateTime,100) between     
                   convert(varchar(20),@LastExecutedTime,100) and      
                   convert(varchar(20), GETDATE(), 100) */    
                  -- AND Ucm.NextExecuteDateTime between     
                  -- @LastExecutedTime and      
                  --GETDATE()                                
                  -- AND DATEDIFF(                                          
                  --         Minute,                                          
                  --         getdate(),                                          
                  --         CASE                                           
                  --              WHEN Ucm.IsNeverExpire = 1 THEN DATEADD(DAY, 1,getdate())                                          
                  --              ELSE ISNULL(Ucm.ExpiryDate, getdate())                                          
                  --     END                                          
                  --     ) > 0                                          
                  -- AND DATEDIFF(Minute, getdate(), ISNULL(Ucm.StartDate, getdate()))  <= 0         
                  -- AND Ucm.IsActive = 1                                          
                                     
 INSERT INTO usercampaignhistory                                    
   (                                    
     -- ID -- this column value is auto-generated                                    
     campaignid,                                    
     parentid,                                    
     step1,                                    
     step2,                                    
     step3,                                   
     issms,                                    
     ismail,                                    
     isscheduled,                                    
     iseventbased,                                    
     createdon,    
     JobId                                    
         
   )                            
                   
 SELECT DISTINCT campaignid,                                    
        parentid,                                    
        0,                                    
        0,                                    
        0,                                    
        1,                                    
        0,                                    
        1,                                    
        0,                                    
        @campaignstartdate,    
        @JobId                                 
 FROM   #temptemplate                                    
                                    
  IF NOT EXISTS (                                    
        SELECT 'x'                                    
        FROM   #temptemplate                                    
    )                                    
 BEGIN                                    
     SET @Body = 'No Campaign Found'                                    
      SELECT @Body     
      INSERT INTO usercampaignhistory                                    
   (                                    
     -- ID -- this column value is auto-generated                                    
     campaignid,                                    
     parentid,                                    
     step1,                                    
     step2,                                    
     step3,                                   
     issms,                                    
     ismail,                                    
     isscheduled,                                    
     iseventbased,                                    
     createdon,    
     JobId                                    
         
   )                            
                   
 SELECT 0,                              
        0,                                    
        0,                                    
        0,                                    
        0,                                    
        1,                                    
        0,                                    
        1,                                    
        0,                                    
        GETDATE(),    
        @JobId                                 
 END                                    
 ELSE                                    
 BEGIn                                   
     CREATE TABLE #temptablesearchapp                          
     (                                    
      campaignid             BIGINT,                                    
      searchid               BIGINT,                                    
      parentid         BIGINT,     
      userid           bigint,                                   
      personname             NVARCHAR(200),                                    
      companyname            NVARCHAR(200),                                    
      mobileno               NVARCHAR(200),                                    
      mobileno1              NVARCHAR(200),                                    
      mobileno2              NVARCHAR(200),                                    
      emailid                NVARCHAR(200),                                    
      emailid1               NVARCHAR(200),                                    
      emailid2               NVARCHAR(200),                        
      city                   NVARCHAR(200),                                    
      STATE                  NVARCHAR(200),                                    
      country                NVARCHAR(200),                                    
      countrycode            NVARCHAR(200),                                    
      pincode                NVARCHAR(200),                                    
      residentialaddress     NVARCHAR(200),                                    
      officeaddress          NVARCHAR(200),                                    
      sourcename       NVARCHAR(200),                                    
      mediumname             NVARCHAR(200),                                    
      campaignname           NVARCHAR(200),                                    
      initialremarks         NVARCHAR(1000)                                    
     )                                    
                                  
     CREATE TABLE #temptablesearchexc                                    
     (                                    
      campaignid             BIGINT,                                    
      searchid               BIGINT,                                    
      parentid               BIGINT,    
      userid     bigint,                     
      personname             NVARCHAR(200),                                    
      companyname            NVARCHAR(200),                  
      mobileno               NVARCHAR(200),                                    
      mobileno1              NVARCHAR(200),                                    
      mobileno2              NVARCHAR(200),                                    
      emailid                NVARCHAR(200),                                    
      emailid1               NVARCHAR(200),                                    
      emailid2               NVARCHAR(200),                                    
      city                   NVARCHAR(200),                                    
      STATE                  NVARCHAR(200),                                    
      country                NVARCHAR(200),                                    
      countrycode            NVARCHAR(200),                                    
      pincode                NVARCHAR(200),                                    
      residentialaddress     NVARCHAR(200),                                    
      officeaddress          NVARCHAR(200),        
      sourcename             NVARCHAR(200),                                    
      mediumname             NVARCHAR(200),                                  
      campaignname           NVARCHAR(200),                                    
      initialremarks         NVARCHAR(1000)                     
     )          
     --For searces from contacts,uncomment below code    
     Create table #temptablesearchContacts    
        (Contact_ID             BIGINT,          
         Contact_Name           VARCHAR(150),          
         Contact_Mobile         VARCHAR(50),          
         Contact_Email          VARCHAR(50),          
         Contact_DOB            VARCHAR(50),          
         Contact_Anniversary    VARCHAR(50),          
         CompanyName            VARCHAR(100),          
         City                   VARCHAR(100),          
         STATE                  VARCHAR(100),          
         Country                VARCHAR(100),          
         ADDRESS                VARCHAR(200),          
         DateCreated            VARCHAR(50),    
         CampaignID             BIGINT,                                          
      SearchID               BIGINT,                                          
      ParentID               BIGINT,    
      UserId                 bigint)     
          
     Create table #temptablesearchExcContacts    
        (Contact_ID             BIGINT,          
         Contact_Name           VARCHAR(150),          
         Contact_Mobile         VARCHAR(50),          
         Contact_Email          VARCHAR(50),          
         Contact_DOB            VARCHAR(50),          
         Contact_Anniversary  VARCHAR(50),          
         CompanyName            VARCHAR(100),          
         City                   VARCHAR(100),          
         STATE                  VARCHAR(100),          
         Country                VARCHAR(100),          
         ADDRESS                VARCHAR(200),          
         DateCreated            VARCHAR(50),    
         CampaignID             BIGINT,                                          
      SearchID               BIGINT,                                          
      ParentID               BIGINT,    
      UserId                 bigint)         
    
         
         
                                   
   INSERT INTO #temptablesearchapp(mobileno,CampaignID,ParentID,userid  )                                          
         Select ISNULL(Usd.MobileNumber, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed      
   FROM  #temptemplate TT    
   Inner join  Usersearchdata AS Usd  (nolock)  on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ApplicabiltyGroupList and Tt.ApplicabiltyGroupList is not null         
         union       
      select distinct A.mobileno,A.CampaignID,A.ParentID,A.userid    
        from (select f.value as mobileno,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.InclusionsNumber,',') f where isnumeric(f.value)=1 group by CampaignID,ParentID,AccountUsed,f.value ) A        
  
                                
     
 INSERT INTO #temptablesearchexc (mobileno,CampaignID,ParentID,userid  )              
SELECT ISNULL(Usd.Mobilenumber, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed FROM #temptemplate TT   Inner join   Usersearchdata AS Usd  (nolock) on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ExclusionsGroupList 
and Tt.ExclusionsGroupList is not null      
      union       
select distinct A.mobileno,A.CampaignID,A.ParentID,A.userid    
from (select f.value as mobileno,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.ExclusionsNumber,',') f where isnumeric(f.value)=1 group by CampaignID,ParentID,AccountUsed,f.value ) A                 
  
          
 DECLARE @CountCampaign     INT = (Select MAX(Id) from #temptemplate    )                                          
          
     DECLARE @Count INT = 1                                                                                                  WHILE (@Count <= @CountCampaign)                                    
     BEGIN                                    
           DECLARE @Applicability BIGINT,                                       
     @Exclusions BIGINT,    
                 @Parentid BIGINT,                                          
                 @Campaignid BIGINT,    
                 @userid bigint    
                       
                     
          Select @Campaignid =Campaignid, @Parentid = Parentid ,@userid=AccountUsed    
          ,@Applicability = tt.Applicabilty,@Exclusions = tt.Exclusions    
           from #temptemplate tt Where Id = @Count                       
           If(@Applicability is not null)    
          Begin                                   
          --For contact search, uncomment the below code & use usp_executeusersearch_New3 instead of usp_executeusersearch    
          if (isnull((select isgroup from usersearchlist where id=@applicability),0)=1)    
          begin    
            INSERT INTO #temptablesearchContacts                                          
  (Contact_ID ,          
         Contact_Name,          
         Contact_Mobile,          
         Contact_Email,          
         Contact_DOB,          
         Contact_Anniversary,          
         CompanyName ,          
         City ,          
         STATE ,          
         Country,          
         ADDRESS,          
         DateCreated,    
         Searchid,    
         Parentid,    
         Campaignid,    
         UserId  )    
         exec Usp_executeusersearch_New3 @parentid,@applicability,@campaignid,@userid                                   
              
end    
          else     
          begin    
            INSERT INTO #temptablesearchapp                                          
       (                                         
      PersonName,                                          
      CompanyName,                                          
      MobileNo,                                          
      MobileNo1,                                          
      MobileNo2,                                          
      EmailID,                                          
      EmailID1,                                          
      EmailID2,                                          
      Country,                                          
      [STATE],                             
      City,                                    
      PinCode,                                          
      ResidentialAddress,                                          
      OfficeAddress,                                          
      SourceName,                                          
      MediumName,                                          
      CampaignName,                                          
      InitialRemarks,                                          
      SearchID,                                          
      ParentID,                                          
      CampaignID                                          
       )                                          
     EXEC Usp_executeusersearch                                          
       @ParentId,                                          
       @Applicability,                                          
       @Campaignid    
   end    
           
           End                                     
         if(@Exclusions is not null)    
          Begin    
          --For search within contacts uncomment below code    
          if (isnull((select isgroup from usersearchlist where id=@Exclusions),0)=1)    
          begin    
            INSERT INTO #temptablesearchExcContacts                                          
  (Contact_ID ,          
         Contact_Name,          
         Contact_Mobile,          
         Contact_Email,          
         Contact_DOB,          
Contact_Anniversary,          
         CompanyName ,          
         City ,          
         STATE ,          
         Country,          
         ADDRESS,          
         DateCreated,    
         Searchid,    
         Parentid,    
         Campaignid,    
         UserId  )    
         exec Usp_executeusersearch_New3 @parentid,@applicability,@campaignid,@userid                                   
              
          end    
          else     
          begin       
                                              
         INSERT INTO #temptablesearchexc                                          
           (                                          
             PersonName,                                          
             CompanyName,                                          
             MobileNo,                                          
             MobileNo1,                                          
  MobileNo2,                                          
             EmailID,                                          
             EmailID1,                                          
             EmailID2,                                          
             Country,                                          
             [STATE],                                          
             City,                                          
             PinCode,                                          
             ResidentialAddress,                                          
            OfficeAddress,                                          
             SourceName,                                          
             MediumName,                                          
             CampaignName,                                          
             InitialRemarks,                                          
             SearchID,                                          
             ParentID,                                          
         CampaignID                                          
    )                                          
         EXEC Usp_executeusersearch                                          
              @Parentid,                                          
              @Exclusions,                                          
              @Campaignid    
    end    
    END    
     SET @Count = @Count+1    
         
     END                                          
                                
     INSERT INTO #temptablesearchapp(mobileno,CampaignID,ParentID,userid)      
          select Contact_Mobile,CampaignID,ParentID,userid from #temptablesearchContacts    
           INSERT INTO #temptablesearchexc(mobileno,CampaignID,ParentID,userid)      
          select Contact_Mobile,CampaignID,ParentID,userid from #temptablesearchExcContacts     
              
                                         
     SELECT A.mobileno,                                    
            A.parentid,                                    
            A.campaignid,    
            A.userid                                    
                                              
            INTO     #tempemailid                                    
     FROM   (                                    
                SELECT Tt2.mobileno,                                    
                       Tt2.parentid,                                    
                       Tt2.campaignid,    
                       tt.Accountused as userid                                    
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                     
          WHERE NOT EXISTS (SELECT 1 FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.mobileno = Tt.mobileno OR Tt2.mobileno = Tt.mobileno1 OR Tt2.mobileno = Tt.mobileno2 ) )                        UNION                     
  
                     
        SELECT Tt2.mobileno1,                                          
                       Tt2.ParentID,                                   
           Tt2.CampaignID,tt.Accountused  as userid                                         
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                    
                 WHERE  NOT EXISTS (SELECT 1                                          
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.mobileno1 = Tt.mobileno OR Tt2.mobileno1 = Tt.mobileno1 OR  Tt2.mobileno1 = Tt.mobileno2)  )       
                UNION                                          
                SELECT Tt2.mobileno2,                                          
                       Tt2.ParentID,                                          
                       Tt2.CampaignID,tt.Accountused as userid                                          
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                                          
                 WHERE  NOT EXISTS (SELECT 1                                          
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND (Tt2.mobileno2 = Tt.mobileno OR Tt2.mobileno2 = Tt.mobileno1 OR  Tt2.mobileno2= Tt.mobileno2 ) )       
             
       )        A                                          
                                      
     SELECT     
     ROW_NUMBER() Over(order by CampaignId,ParentId) Id,    
     Ucerm.CampaignID,       
     Ucerm.ParentID                               ,    
                     -- Cast(Ucerm.Messages AS VARCHAR(MAX))  AS  Messages,                                    
                     ucerm.userID,                                  
                     Count(*) cnt    
                     -- Ucerm.Mail_ToEmail,                                    
   INTO   #tempCount                                    
      FROM   #tempemailid Ucerm                                    
      Group by  Ucerm.CampaignID,       
     Ucerm.ParentID ,                                    
                      Ucerm.UserID    
                                                      
          
      SELECT A.UserID,a.CampaignID, a.cnt,SUM(b.cnt) RunningTotal into #TempTableRunningTotal    
   FROM   #tempCount a join    
       #tempCount b  on a.userid=b.userid  
   WHERE b.CampaignID <= a.CampaignID    
   GROUP BY A.UserID, a.CampaignID, a.cnt    
   ORDER BY a.CampaignID;    
          
   --- Calculate credits                                    
      SELECT B.UserID,     
    B.CampaignID,    
      CASE                                    
               WHEN B.Balance > B.Credits THEN 1                                    
               ELSE 0  -- Test                                    
             END AS ValidEntries                                    
      INTO   #tempMobile                                    
      FROM   (SELECT A.UserID,      
      A.CampaignID,                                  
                     (A.Credits)   AS Credits,  --Runningtotal                                  
                     A.Balance                                    
              FROM   (SELECT Tt.UserID,                                    
                             TT.RunningTotal AS Credits,    
                             TT.CampaignID,                                    
                            -- Tt.Mail_ToEmail,                                    
                             (SELECT TOP 1 Balance                                    
                              FROM   credit_details AS Mcd                                    
                              WHERE  Mcd.[User_ID] = Tt.UserID                                    
                              ORDER  BY Credit_ID DESC)     AS Balance                                    
                      FROM   #TempTableRunningTotal Tt) A                                    
              GROUP  BY A.UserID,                                    
                        A.Balance,A.CampaignID,A.credits) B    
                                     
                                         
     INSERT INTO usercampaignexecutionhistory                                    
       (                                    
         -- ID -- this column value is auto-generated                    
         campaignid,                                    
         Jobid,    
         executiontime,                                    
         isrecipients,                                    
         parentid                                    
       )                                    
     SELECT DISTINCT A.campaignid,    
            @JobId,                     
            GETDATE(),                                    
            1,                                    
            A.parentid                                    
     FROM   (                                    
               SELECT    
      TT.ParentID,    
      TT.CampaignID    
                from #tempcount TT join #tempMobile tm on tm.CampaignID=tt.CampaignID    
                where tm.ValidEntries=1       
            ) A                                    
                                                                                                     
     INSERT INTO usercampaignexecutionrecipientsmessagetest2                                    
       (                                    
         mobile,                                   
         parentid,                                    
         campaignid,    
         u_id,    
         jobid                                    
       )                                    
     SELECT A.mobileno,                                    
            A.parentid,                                    
            A.campaignid,    
            A.userid,    
            @JobId                           
     FROM   ( SELECT mobileno,parentid,                                            campaignid,userid, @JobId Jobid                                  FROM   #tempemailid                                         WHERE  MobileNo is not null and MobileNo<>''  
   
                                  
     /*UNION           
         SELECT CAST(Fs.[value] COLLATE Latin1_general_ci_ai AS VARCHAR(500)),                                          
                       tt.ParentID,                                          
                       tt.CampaignID ,    
                       tt.AccountUsed                                         
                FROM   #temptemplate AS tt  (nolock)                                        
                       OUTER APPLY Dbo.Fn_split(tt.InclusionsNumber, ',') AS Fs  where  fs.value is not null */                                        
     ) A    
     Inner join #tempMobile TM on TM.CampaignID = A.CampaignID                                          
     WHERE  TM.ValidEntries = 1 /*and    
      CAST(A.mobileno COLLATE Latin1_general_ci_ai AS VARCHAR(500))                                          
            NOT IN (SELECT CAST(                                          
                  ISNULL(Fs.[value], '0') COLLATE                                          
                               Latin1_general_ci_ai AS                                          
                               VARCHAR(500)                                 )                    
                    FROM   #temptemplate AS Ucm2  (nolock)                                        
                           OUTER APPLY Dbo.Fn_split(Ucm2.ExclusionsNumber, ',') AS Fs                                          
                    WHERE  Ucm2.ID = A.CampaignID                                                                            
                  AND A.ParentID = Ucm2.ParentID)*/                              
                                         
    
UPDATE A                              
SET step1=1,step1datetime=getdate(),step1recipients = B.cnt   
FROM [dbo].UserCampaignHistory A INNER JOIN  #tempcount B                             
/*(SELECT a.campaignid as campaignid, A.Jobid,isnull(count(e.CampaignID),0) AS [RecipientsCount]                              
         FROM UserCampaignHistory A (nolock)     
    left outer join [dbo].[EmailsfiltercampaignexecutionTest2] e (nolock) on e.CampaignID=a.CampaignID     
    Where A.Jobid = @jobId    
         group by a.campaignid  , A.Jobid                            
 ) B*/                              
ON A.[campaignid] = B.[campaignid] and A.Jobid = @JobId    
    
UPDATE A                                
SET step1=1,step1datetime=getdate()    
FROM [dbo].UserCampaignHistory A where A.Jobid = @JobId     
                                               
                                         
                                         
 /*                                        
     IF EXISTS (                                    
            SELECT 'x'                                    
            FROM   #tempemailid    
        )                                    
     BEGIN                                    
         INSERT INTO getbatchrecord                                    
           (                                    
             [user_id],                                    
             randnum                                    
           )                               
        SELECT  TC.ParentID,                           
            TC.CampaignID                                          
     FROM    #tempCount TC                              
                                             
    Select BatchID,[User_id] ParentID,RandNum CampaignID into #Batch from Getbatchrecord Gbr                                     
 Order by gbr.BatchID    
                                               
     DELETE Kd                                          
     FROM   Getbatchrecord Kd         
     Inner join    #Batch B on B.BatchId = Kd.BatchID                                                                       
  INSERT INTO Batchemail_infos                                          
       (                                          
         -- ID -- this column value is auto-generated                                          
         BatchID,                                          
         UserID,                          
         SenderName,                                          
         [Message],                                          
       TotalRecords,                                          
         TotalProcessed,                                          
         ProcessTable,                                          
         IsProcess,                                          
         Priority_Level,                                          
         BatchInsertTime,                                          
         BatchProcessTime,             
         ScheduledDate,                                          
         ScheduledTime,                                          
         TemplateID,                                          
         [Route],                                          
         PageName,                                          
         IsScheduled,                                          
         Email_Subject,                          
         ReplyTo,                                          
         Amount,                                          
         Currency                                          
       )                                          
     SELECT B.BatchId,                                          
            335,                                   
            Ucm.NotificationMail,                                          
            case when tm.validentries=1 then 'Hold tight ! Your SMS campaign "'                                          
