         Campaignid,          
         UserId  )          
         exec Usp_executeusersearch_New3 @parentid,@applicability,@campaignid,@userid                                         
                    
end          
          else           
          begin          
            INSERT INTO #temptablesearchapp                                                
       (                                               
      PersonName,                        
      CompanyName,                                                
      MobileNo,                                                
      MobileNo1,                                                
      MobileNo2,                                                
      EmailID,                                                
      EmailID1,                                                
      EmailID2,                                                
      Country,                                                
      [STATE],                                   
      City,                                          
      PinCode,                                     
      ResidentialAddress,                                                
      OfficeAddress,                                                
      SourceName,                                                
      MediumName,                                                
      CampaignName,                                                
      InitialRemarks,                                                
      SearchID,                                                
      ParentID,                                                
      CampaignID                                                
       )                                                
     EXEC Usp_executeusersearch                                                
       @ParentId,                                                
       @Applicability,                                                
       @Campaignid          
   end          
                 
           End                                           
         if(@Exclusions is not null)          
          Begin          
          --For search within contacts uncomment below code          
