   INSERT INTO #temptablesearchapp(mobileno,CampaignID,ParentID,userid  )                                                
         Select ISNULL(Usd.MobileNumber, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed            
   FROM  #temptemplate TT          
   Inner join  Usersearchdata AS Usd  (nolock)  on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ApplicabiltyGroupList and Tt.ApplicabiltyGroupList is not null               
         union             
      select distinct A.mobileno,A.CampaignID,A.ParentID,A.userid          
        from (select f.value as mobileno,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.InclusionsNumber,',') f where isnumeric(f.value)=1 group by CampaignID,ParentID,AccountUsed,f.value ) A        
  
    
      
        
                                      
           
 INSERT INTO #temptablesearchexc (mobileno,CampaignID,ParentID,userid  )                    
SELECT ISNULL(Usd.Mobilenumber, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed FROM #temptemplate TT   Inner join   Usersearchdata AS Usd  (nolock) on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ExclusionsGroupList 
and Tt.ExclusionsGroupList is not null            
      union             
select distinct A.mobileno,A.CampaignID,A.ParentID,A.userid          
from (select f.value as mobileno,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.ExclusionsNumber,',') f where isnumeric(f.value)=1 group by CampaignID,ParentID,AccountUsed,f.value ) A                 
  
    
      
        
                
 DECLARE @CountCampaign     INT = (Select MAX(Id) from #temptemplate    )                                         
                                                                                         
     DECLARE @Count INT = 1                                                                                                  WHILE (@Count <= @CountCampaign)                                          
     BEGIN                                          
           DECLARE @Applicability BIGINT,                                             
     @Exclusions BIGINT,          
                 @Parentid BIGINT,                                                
                 @Campaignid BIGINT,          
                 @userid bigint          
                             
                           
          Select @Campaignid =Campaignid, @Parentid = Parentid ,@userid=AccountUsed          
          ,@Applicability = tt.Applicabilty,@Exclusions = tt.Exclusions          
           from #temptemplate tt Where Id = @Count                             
           If(@Applicability is not null)          
          Begin                                         
          --For contact search, uncomment the below code & use usp_executeusersearch_New3 instead of usp_executeusersearch          
          if (isnull((select isgroup from usersearchlist where id=@applicability),0)=1)          
          begin          
            INSERT INTO #temptablesearchContacts                                                
  (Contact_ID ,                
         Contact_Name,                
         Contact_Mobile,                
         Contact_Email,                
         Contact_DOB,                
         Contact_Anniversary,                
         CompanyName ,                
         City ,                
         STATE ,                
         Country,                
         ADDRESS,                
         DateCreated,          
         Searchid,          
         Parentid,          
         Campaignid,          
         UserId  )          
         exec Usp_executeusersearch_New3 @parentid,@applicability,@campaignid,@userid                                         
                    
end          
          else           
          begin          
            INSERT INTO #temptablesearchapp                                                
       (
	   Entityname,Entityid,                                               
      PersonName,                        
      CompanyName,                                                
      MobileNo,                                                
      MobileNo1,                                                
      MobileNo2,                                                
      EmailID,                                                
      EmailID1,                                                
      EmailID2,                                                
      Country,                                                
      [STATE],                                   
      City,                                          
      PinCode,                                     
      ResidentialAddress,                                                
      OfficeAddress,                                                
      SourceName,                                                
      MediumName,                                                
      CampaignName,                                                
      InitialRemarks,                                                
      SearchID,                                                
      ParentID,                                                
      CampaignID                                                
       )                                                
     EXEC Usp_executeusersearchwithid                                                
       @ParentId,                                                
       @Applicability,                                                
       @Campaignid          
   end          
                 
           End                                           
         if(@Exclusions is not null)          
          Begin          
          --For search within contacts uncomment below code          
          if (isnull((select isgroup from usersearchlist where id=@Exclusions),0)=1)          
          begin          
            INSERT INTO #temptablesearchExcContacts                                                
  (Contact_ID ,                
         Contact_Name,                
      Contact_Mobile,                
         Contact_Email,                
         Contact_DOB,                
         Contact_Anniversary,                
         CompanyName ,                
         City ,                
         STATE ,                
         Country,                
         ADDRESS,                
         DateCreated,          
         Searchid,          
         Parentid,          
         Campaignid,          
         UserId  )          
         exec Usp_executeusersearch_New3 @parentid,@applicability,@campaignid,@userid                                         
                    
          end          
          else           
          begin             
                                                    
         INSERT INTO #temptablesearchexc                                                
           (                            
		   Entityname,Entityid,                    
             PersonName,                                                
             CompanyName,                                                
             MobileNo,                                                
             MobileNo1,                                                
  MobileNo2,                                                
             EmailID,                                                
             EmailID1,                                                
             EmailID2,                                                
             Country,                                                
             [STATE],                                                
             City,                                                
             PinCode,                                                
             ResidentialAddress,                                                
            OfficeAddress,                                                
             SourceName,                                          
             MediumName,                                                
             CampaignName,                                                
             InitialRemarks,                                                
             SearchID,                                                
             ParentID,                                                
         CampaignID                                                
    )                                                
         EXEC Usp_executeusersearchwithid                                                
              @Parentid,                                                
              @Exclusions,                                                
              @Campaignid          
    end          
    END          
     SET @Count = @Count+1          
               
     END                                                
                                      
     INSERT INTO #temptablesearchapp(mobileno,CampaignID,ParentID,userid)            
