 END                                          
 update UserCampaignExecution                                              
    set CampaignExecutedDatetime=@CampaignStarttime,isevent=0                                              
                where issms=2 and isnull(isevent,0)=0                
           
exec [Usp_insertclonedeliverycampaignVoice1]  @Jobid                         
end          
  else          
  begin          
  if (select Lasterrorreported from UserCampaignExecution where issms=2 and isnull(isevent,0)=0) is null or (DATEDIFF(mi,(select isnull(Lasterrorreported,dateadd(mi,-6,getdate())) from UserCampaignExecution where issms=2 and isnull(isevent,0)=0),getdate(
  
    
      
)        
)>5 and DATEDIFF(mi,(select isnull(CampaignExecutedDatetime,dateadd(mi,-6,getdate())) from UserCampaignExecution where issms=2 and isnull(isevent,0)=0),getdate()        
)>5)          
  begin          
  declare @campaignstart datetime =(select CampaignExecutedDatetime from UserCampaignExecution where issms=2 and isnull(isevent,0)=0),     
  @lastjobid bigint =(select isnull(cjobid,    
  (select top 1 jobid from usercampaignhistory (nolock) where issms=2 and iseventbased=0 and campaignid<>0 and jobid<>@jobid order by id desc)) from usercampaignexecution    
  where issms=2 and isevent=0)    
    
  select top 1 @campaignstart = CreatedOn from usercampaignhistory(nolock) where jobid=@lastjobid    
            
  declare @step int = (select top 1 case when step2datetime is null then 2 else 3 end from usercampaignhistory (nolock) where jobid=@lastjobid)          
            
  declare @mobile nvarchar(20),@message nvarchar(2000),@total int,@attime datetime          
            
  if exists(select mobile,COUNT(mobile)Count from          
(select top 50 mobile,b.batchid from batchinfo b (nolock) join Voice_DeliveryStatus m (nolock)on m.BatchID=b.batchid where TotalRecords=1 order by BatchInfoID desc) A          
group by Mobile having COUNT(mobile)>2)          
  begin          
  select top 1 @mobile=mobile,@total=COUNT(mobile), @attime=MAX(batchinserttime) from          
(select top 50 mobile,b.batchid,BatchInsertTime from batchinfo b (nolock) join Voice_DeliveryStatus m (nolock)on m.BatchID=b.batchid where TotalRecords=1 order by BatchInfoID desc) A          
group by Mobile having COUNT(mobile)>2          
  end          
            
            
  declare @error nvarchar(200)='Last Voice Campaign with jobid ' + cast(@lastjobid as varchar(10)) + ' failed at step ' + cast(@step as varchar) + ' running since ' + cast(@campaignstart as nvarchar(20)) + case when @mobile is null then '.' else 'Effecte 
  
   
d      
 mobile '+ @mobile +        
   ' - Got SMS ' +  cast(@total as nvarchar) + ' times at ' +cast(@attime as nvarchar(20))+        
   ' with message as ' + @message end          
            
exec usp_InsertCampaignError 'VOICE',0,@error          
  --if @step=2          
  --begin         
  --   exec Usp_insertclonedeliverycampaignVoice @lastjobid                    
  ----exec Usp_userexecutecampaignmessagesCorrected @lastjobid          
  --end          
  --else         
  if @step=3          
  begin        
     exec Usp_insertclonedeliverycampaignVoice_withid @lastjobid                    
          
  --exec Usp_insertclonedeliverycampaignCorrected @lastjobid          
  end          
          
 update UserCampaignExecution set Lasterrorreported=GETDATE() where issms=2 and isnull(isevent,0)=0          
 --GOTO RETRY          
  end          
  end          
END     


