     issms,                                          
     ismail,                                          
     isscheduled,                                          
     iseventbased,                                          
     createdon,          
     JobId                                    
               
   )                                  
                         
 SELECT 0,                                          
        0,                                          
        0,                                          
        0,                                          
        0,                                          
        2,                                          
        0,                                          
        1,                                          
        0,                                          
        GETDATE(),          
        @JobId                                       
 END                                          
 ELSE                                          
 BEGIn                                         
     CREATE TABLE #temptablesearchapp                                
