     SELECT A.Entityname,A.Entityid,A.mobileno,                                          
            A.parentid,                                          
            A.campaignid,          
            A.userid,                                          
   A.didno,A.appid, A.duration,A.credits ,route             
            INTO     #tempemailid                                          
     FROM   (                                          
                SELECT Entityname,Entityid,Tt2.mobileno,                                          
                       Tt2.parentid,                                          
                       Tt2.campaignid,          
                       tt.Accountused as userid,        
                       tt.didno,tt.appid, tt.duration,tt.credits,tt.route                                                
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                           
          WHERE nullif(Tt2.mobileno,'') is not null and NOT EXISTS (SELECT 1 FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.mobileno = Tt.mobileno OR Tt2.mobileno = Tt.mobileno1 OR Tt2.mobileno = Tt.mobileno2 ) )                    
  
     
     
    UNION                             
                           
        SELECT Entityname,Entityid,Tt2.mobileno1,                                                
                       Tt2.ParentID,                                                
           Tt2.CampaignID,tt.AccountUsed  as userid,        
           tt.didno,tt.appid, tt.duration,tt.credits,tt.route                                                
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                          
                 WHERE nullif(Tt2.mobileno1,'') is not null and NOT EXISTS (SELECT 1                                                
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.mobileno1 = Tt.mobileno OR Tt2.mobileno1 = Tt.mobileno1 OR  Tt2.mobileno1 = Tt.mobileno2)  )             
                UNION                                                
                SELECT Entityname,Entityid,Tt2.mobileno2,                                                
                       Tt2.ParentID,                                                
                       Tt2.CampaignID,tt.AccountUsed as userid,        
                       tt.didno,tt.appid, tt.duration,tt.credits,tt.route                                                 
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                                                
                 WHERE nullif(Tt2.mobileno2,'') is not null and NOT EXISTS (SELECT 1                                                
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND (Tt2.mobileno2 = Tt.mobileno OR Tt2.mobileno2 = Tt.mobileno1 OR  Tt2.mobileno2= Tt.mobileno2 ) )             
                   
