     SELECT           
     ROW_NUMBER() Over(order by CampaignId,ParentId) Id,          
     Ucerm.CampaignID,             
     Ucerm.ParentID ,          
                     -- Cast(Ucerm.Messages AS VARCHAR(MAX))  AS  Messages,                                          
                     ucerm.userID,    
                     dbo.fn_GetVoiceCreditCalculationScalar(ucerm.route,ucerm.UserID,ucerm.duration,count(ucerm.campaignid)) cnt  ,  
                     Count(*) RCCnt              
                     --Count(*) cnt          
                     -- Ucerm.Mail_ToEmail,                                          
   INTO   #tempCount                                          
      FROM   #tempemailid Ucerm  where ucerm.mobileno is not null                                        
      Group by  Ucerm.CampaignID,             
     Ucerm.ParentID , Ucerm.UserID,ucerm.route,ucerm.duration          
                                                            
                
      SELECT A.UserID,a.CampaignID, a.cnt,SUM(b.cnt) RunningTotal into #TempTableRunningTotal          
   FROM   #tempCount a join          
       #tempCount b  on a.userid=b.userid        
   WHERE b.CampaignID <= a.CampaignID          
   GROUP BY A.UserID, a.CampaignID, a.cnt          
   ORDER BY a.CampaignID;          
                
   --- Calculate credits                                          
      SELECT B.UserID,           
    B.CampaignID,          
      CASE                                          
               WHEN B.Balance >= B.Credits THEN 1                                          
               ELSE 0  -- Test                                          
             END AS ValidEntries                                          
      INTO   #tempMobile                                          
      FROM   (SELECT A.UserID,            
      A.CampaignID,                                        
                     (A.Credits)   AS Credits,  --Runningtotal                                        
                     A.Balance                                          
              FROM   (SELECT Tt.UserID,                                          
                             TT.RunningTotal AS Credits,          
                             TT.CampaignID,                                          
                            -- Tt.Mail_ToEmail,                                          
                             (SELECT TOP 1 Balance                                 
                              FROM   IntCredit_Details AS Mcd                                          
                              WHERE  Mcd.[User_ID] = Tt.UserID                                          
                              ORDER  BY Credit_ID DESC)     AS Balance                                          
                      FROM   #TempTableRunningTotal Tt) A                                          
              GROUP  BY A.UserID,                                          
                        A.Balance,A.CampaignID,A.credits) B     
                            
                            
