 select campaignid into #FindCampaignsNextExecution from #temptemplate t join UserCampaignMaster ucm on t.CampaignID=ucm.id          
    where ucm.IsActive=1 and ucm.IsSchedule=1 and ucm.IsScheduled=1          
              
 declare @count1 int =isnull((select COUNT(1) from #FindCampaignsNextExecution),0)          
 if @count1>0          
 begin          
    create table #nextexec1(campaignid bigint,nextexecution datetime)                      
    WHILE @Count1 > 0                          
  BEGIN                          
   DECLARE @Campaignid1 BIGINT = (                          
       SELECT TOP 1 campaignid         
    FROM   #FindCampaignsNextExecution                          
      )              
         
   INSERT INTO #nextexec1                          
       (                          
      campaignid,                          
      nextexecution                          
       )                          
    EXEC Usp_getnextscheduledate                      
       @Campaignid1                          
          
    DELETE                           
    FROM   #FindCampaignsNextExecution                          
    WHERE  campaignid = @Campaignid1                          
          
    SET @Count1 = @Count1 - 1            
  END          
   update u set NextExecuteDateTime= nextexecution from usercampaignmaster u join #nextexec1 n on n.campaignid=u.id          
   where u.ExpiryDate > nextexecution or u.ExpiryDate is null          
    drop table #nextexec1          
    drop table #FindCampaignsNextExecution         
          
 end       
 -----Next schedule time updated---                                          
      DROP TABLE #tempemailid                                            
                                              
     DROP TABLE #temptablesearchapp                                            
                                                 
  DROP TABLE #temptablesearchexc       
  drop table #tempCount      
  drop table #TempTableRunningTotal      
  drop table #tempMobile         
  DROP TABLE #temptemplate       
        
  drop table #temptablesearchContacts      
  drop table #temptablesearchExcContacts       
         
 END                                      
 update UserCampaignExecution                                          
    set CampaignExecutedDatetime=@CampaignStarttime,isevent=0                                          
                where issms=1 and isnull(isevent,0)=0            
       
  exec [Usp_userexecutecampaignmessagesCorrected]          
@Jobid                     
end      
  else      
  begin      
  if (select Lasterrorreported from UserCampaignExecution where issms=1 and isnull(isevent,0)=0) is null or (DATEDIFF(mi,(select isnull(Lasterrorreported,dateadd(mi,-6,getdate())) from UserCampaignExecution where issms=1 and isnull(isevent,0)=0),getdate(
  
)    
)>5 and DATEDIFF(mi,(select isnull(CampaignExecutedDatetime,dateadd(mi,-6,getdate())) from UserCampaignExecution where issms=1 and isnull(isevent,0)=0),getdate()    
)>5)      
  begin      
  declare @campaignstart datetime ,     
  @lastjobid bigint =(select isnull(cjobid,(select top 1 jobid from usercampaignhistory (nolock) where issms=1 and iseventbased=0 and campaignid<>0 and jobid<>@jobid order by id desc))     
  from usercampaignexecution where issms=1 and isevent=0)    
  select top 1 @campaignstart = CreatedOn from usercampaignhistory(nolock) where jobid=@lastjobid    
        
  declare @step int = (select top 1 case when step2datetime is null then 2 else 3 end from usercampaignhistory (nolock) where jobid=@lastjobid)      
        
  declare @mobile nvarchar(20),@message nvarchar(2000),@total int,@attime datetime      
        
  if exists(select mobile,COUNT(mobile)Count,message from      
(select top 50 mobile,message,b.batchid from batchinfo b (nolock) join MessageDeliveryStatus m (nolock)on m.BatchID=b.batchid where TotalRecords=1 order by BatchInfoID desc) A      
group by Mobile,message having COUNT(mobile)>2)      
  begin      
  select top 1 @mobile=mobile,@total=COUNT(mobile),@message=message,@attime=MAX(batchinserttime) from      
(select top 50 mobile,message,b.batchid,BatchInsertTime from batchinfo b (nolock) join MessageDeliveryStatus m (nolock)on m.BatchID=b.batchid where TotalRecords=1 order by BatchInfoID desc) A      
group by Mobile,message having COUNT(mobile)>2      
  end      
        
        
  declare @error nvarchar(200)='Last Campaign with jobid ' + cast(@lastjobid as varchar(10)) + ' failed at step ' + cast(@step as varchar) + ' running since ' + cast(@campaignstart as nvarchar(20)) + case when @mobile is null then '.' else 'Effected mobil
  
e '+ @mobile + ' - Got SMS ' +  cast(@total as nvarchar) + ' times at ' +cast(@attime as nvarchar(20))+' with message as ' + @message end      
        
exec usp_InsertCampaignError 'SMS',0,@error      
  if @step=2      
  begin      
  exec Usp_userexecutecampaignmessagesCorrected_withid @lastjobid      
  end      
  else if @step=3      
  begin      
  exec Usp_insertclonedeliverycampaignCorrected_withid @lastjobid      
  end      
      
 update UserCampaignExecution set Lasterrorreported=GETDATE() where issms=1 and isnull(isevent,0)=0      
 --GOTO RETRY      
  end      
  end      
END 


GO

