      personname             NVARCHAR(200),                                      
      companyname            NVARCHAR(200),                                      
      mobileno               NVARCHAR(200),                                      
      mobileno1              NVARCHAR(200),                                      
      mobileno2              NVARCHAR(200),                                      
      emailid                NVARCHAR(200),                                      
      emailid1               NVARCHAR(200),                                      
      emailid2               NVARCHAR(200),                          
      city                   NVARCHAR(200),                                      
      STATE                  NVARCHAR(200),                                      
      country                NVARCHAR(200),                                      
      countrycode            NVARCHAR(200),                                      
      pincode                NVARCHAR(200),                                      
      residentialaddress     NVARCHAR(500),                                      
      officeaddress          NVARCHAR(500),                                      
      sourcename       NVARCHAR(200),                                      
      mediumname             NVARCHAR(200),                                      
      campaignname           NVARCHAR(200),                                      
      initialremarks         NVARCHAR(1000)                                      
     )                                      
                                    
     CREATE TABLE #temptablesearchexc                                      
     (                                      
	 Entityname nvarchar(20),Entityid bigint,
      campaignid             BIGINT,                                      
      searchid               BIGINT,                                      
      parentid               BIGINT,      
      userid     bigint,                       
      personname             NVARCHAR(200),                                      
      companyname            NVARCHAR(200),                    
      mobileno               NVARCHAR(200),                                      
      mobileno1              NVARCHAR(200),                                      
      mobileno2              NVARCHAR(200),                                      
      emailid                NVARCHAR(200),                                      
      emailid1               NVARCHAR(200),                                      
      emailid2               NVARCHAR(200),                                      
      city                   NVARCHAR(200),        
      STATE                  NVARCHAR(200),                                      
      country                NVARCHAR(200),                                      
      countrycode            NVARCHAR(200),                                      
      pincode                NVARCHAR(200),                                      
      residentialaddress     NVARCHAR(500),                                      
      officeaddress          NVARCHAR(500),                        
      sourcename             NVARCHAR(200),                                      
      mediumname             NVARCHAR(200),                                    
      campaignname           NVARCHAR(200),                                      
      initialremarks         NVARCHAR(1000)                       
     )            
     --For searces from contacts,uncomment below code      
     Create table #temptablesearchContacts      
        (Entityname nvarchar(20),Contact_ID             BIGINT,            
         Contact_Name           VARCHAR(150),            
         Contact_Mobile         VARCHAR(50),            
         Contact_Email          VARCHAR(50),            
         Contact_DOB            VARCHAR(50),            
         Contact_Anniversary    VARCHAR(50),            
         CompanyName            VARCHAR(100),            
         City                   VARCHAR(100),            
         STATE                  VARCHAR(100),            
         Country                VARCHAR(100),            
         ADDRESS                VARCHAR(500),            
         DateCreated            VARCHAR(50),      
         CampaignID             BIGINT,                                            
      SearchID               BIGINT,                                            
      ParentID               BIGINT,      
      UserId                 bigint)       
            
     Create table #temptablesearchExcContacts      
        (Entityname nvarchar(20),Contact_ID             BIGINT,            
         Contact_Name           VARCHAR(150),            
         Contact_Mobile         VARCHAR(50),            
         Contact_Email          VARCHAR(50),            
         Contact_DOB            VARCHAR(50),            
         Contact_Anniversary  VARCHAR(50),            
         CompanyName            VARCHAR(100),            
         City                   VARCHAR(100),            
         STATE                  VARCHAR(100),            
         Country                VARCHAR(100),            
         ADDRESS                VARCHAR(500),            
         DateCreated            VARCHAR(50),      
         CampaignID             BIGINT,                                            
      SearchID               BIGINT,                                            
      ParentID               BIGINT,      
      UserId                 bigint)           
      
           
           
                                     
   INSERT INTO #temptablesearchapp(Entityname,Entityid,mobileno,CampaignID,ParentID,userid  )                                            
         Select 'ImportedList',usd.id, ISNULL(Usd.MobileNumber, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed        
   FROM  #temptemplate TT      
   Inner join  Usersearchdata AS Usd  (nolock)  on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ApplicabiltyGroupList and Tt.ApplicabiltyGroupList is not null           
         union         
      select 'Explicit',A.position, A.mobileno,A.CampaignID,A.ParentID,A.userid      
        from (select f.value as mobileno,f.position,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.InclusionsNumber,',') f where isnumeric(f.value)=1 group by CampaignID,ParentID,AccountUsed,f.value,f.position ) A        
  
    
                                  
       
 INSERT INTO #temptablesearchexc (Entityname,Entityid,mobileno,CampaignID,ParentID,userid  )                
SELECT 'ImportedList',usd.id,ISNULL(Usd.Mobilenumber, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed FROM #temptemplate TT   Inner join   Usersearchdata AS Usd  (nolock) on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ExclusionsGroupList and 
Tt.ExclusionsGroupList is not null        
      union         
select 'Explicit',A.position,A.mobileno,A.CampaignID,A.ParentID,A.userid      
from (select f.value as mobileno,f.position,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.ExclusionsNumber,',') f where isnumeric(f.value)=1 group by CampaignID,ParentID,AccountUsed,f.value,f.position ) A                 
  
    
            
 DECLARE @CountCampaign     INT = (Select MAX(Id) from #temptemplate    )                                            
                          
     DECLARE @Count INT = 1                                                                                                  WHILE (@Count <= @CountCampaign)                                      
     BEGIN                                      
           DECLARE @Applicability BIGINT,                                         
     @Exclusions BIGINT,      
                 @Parentid BIGINT,                                            
                 @Campaignid BIGINT,      
                 @userid bigint      
                         
                       
          Select @Campaignid =Campaignid, @Parentid = Parentid ,@userid=AccountUsed      
