     INSERT INTO #temptablesearchapp(Entityname,Entityid,mobileno,CampaignID,ParentID,userid)        
          select Entityname,Contact_ID,Contact_Mobile,CampaignID,ParentID,userid from #temptablesearchContacts      
           INSERT INTO #temptablesearchexc(Entityname,Entityid,mobileno,CampaignID,ParentID,userid)        
          select Entityname,Contact_ID,Contact_Mobile,CampaignID,ParentID,userid from #temptablesearchExcContacts       
                
                                           
     SELECT Entityname,Entityid,A.mobileno,                                      
            A.parentid,                                      
            A.campaignid,      
            A.userid                                      
                                                
            INTO     #tempemailid                                      
     FROM   (                                      
                SELECT Entityname,Entityid,
				Tt2.mobileno,                                      
                       Tt2.parentid,                                      
                       Tt2.campaignid,      
                       tt.Accountused as userid                                      
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                       
          WHERE nullif(Tt2.mobileno,'') is not null and NOT EXISTS (SELECT 1 FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.mobileno = Tt.mobileno OR Tt2.mobileno = Tt.mobileno1 OR Tt2.mobileno = Tt.mobileno2 ) )                    
  
    UNION                         
                       
        SELECT Entityname,Entityid,Tt2.mobileno1,                                            
                      Tt2.ParentID,                                            
           Tt2.CampaignID,tt.Accountused  as userid                                           
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                      
                 WHERE nullif(Tt2.mobileno1,'') is not null and NOT EXISTS (SELECT 1                                            
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.mobileno1 = Tt.mobileno OR Tt2.mobileno1 = Tt.mobileno1 OR  Tt2.mobileno1 = Tt.mobileno2)  )         
                UNION                                            
                SELECT Entityname,Entityid,Tt2.mobileno2,                                            
                       Tt2.ParentID,                                            
                       Tt2.CampaignID,tt.Accountused as userid                                            
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                                            
                 WHERE nullif(Tt2.mobileno2,'') is not null and NOT EXISTS (SELECT 1                                            
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND (Tt2.mobileno2 = Tt.mobileno OR Tt2.mobileno2 = Tt.mobileno1 OR  Tt2.mobileno2= Tt.mobileno2 ) )         
               
       )        A                                            
   
   declare @smscost numeric(18,4),@totalcost numeric(18,4)

   select top 1 @smscost=PTrns from Price_Base_SMS_RateDeduction(nolock) where DestinationCountryCode='+91'

     SELECT       
     ROW_NUMBER() Over(order by CampaignId,ParentId) Id,      
     Ucerm.CampaignID,         
     Ucerm.ParentID                               ,      
                     -- Cast(Ucerm.Messages AS VARCHAR(MAX))  AS  Messages,                                      
                     ucerm.userID,                                    
                     Count(*) cnt      
                     -- Ucerm.Mail_ToEmail,                                      
   INTO   #tempCount                                      
      FROM   #tempemailid Ucerm  where ucerm.mobileno is not null                                    
      Group by  Ucerm.CampaignID,         
     Ucerm.ParentID ,                                      
                      Ucerm.UserID      
                                                        
            
      SELECT A.UserID,a.CampaignID, a.cnt,SUM((b.cnt*@smscost)) RunningTotal into #TempTableRunningTotal      
   FROM   #tempCount a join      
       #tempCount b  on a.userid=b.userid    
   WHERE b.CampaignID <= a.CampaignID      
   GROUP BY A.UserID, a.CampaignID, a.cnt      
   ORDER BY a.CampaignID;      
            
   --- Calculate credits                                      
      SELECT B.UserID,       
    B.CampaignID,      
      CASE                                      
               WHEN B.Balance >= B.Credits THEN 1                                      
               ELSE 0  -- Test                                      
             END AS ValidEntries                                      
      INTO   #tempMobile                                      
 FROM   (SELECT A.UserID,        
      A.CampaignID,                                    
                     (A.Credits)   AS Credits,  --Runningtotal                                    
                     A.Balance                                      
              FROM   (SELECT Tt.UserID,                                      
                             TT.RunningTotal AS Credits,      
                             TT.CampaignID,                                      
                            -- Tt.Mail_ToEmail,                                      
                             dbo.GetAvailableBalanceForService(dbo.ufn_getuserparentid(tt.userid),21) AS Balance          
                      FROM   #TempTableRunningTotal Tt) A                                      
              GROUP  BY A.UserID,                                      
                        A.Balance,A.CampaignID,A.credits) B     
                            
update u set u.ReasonIfNotRun='Insuffcient Balance' from UserCampaignHistory u join #tempMobile t    
on u.campaignid=t.CampaignID and u.jobid=@jobid where t.validentries=0     
                                       
                                           
