/* ============================================================
   Procedure: [dbo].[Usp_executerecipientsusercampaignmails]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

                                     
CREATE   PROCEDURE [Dbo].[Usp_executerecipientsusercampaignmails]                                    
AS                                    
BEGIN                                    
 DECLARE @Body VARCHAR(500)                                    
                                     
 DECLARE @LastExecutedTime datetime =(select Top 1 CampaignExecutedDatetime from UserCampaignExecution where issms=0 order by id desc)        
 if OBJECT_ID('tempdb..##timediffmail') is null            
begin    
 create table ##timediffmail(id int identity(1,1),Campaigntime datetime,lastexecutiontime datetime,timediff bigint)    
end    
 declare @id bigint    
 insert into ##timediffmail(Campaigntime)    
 select GETDATE()      
 set @id=(select SCOPE_IDENTITY())     
     
                                     
 SELECT A.CampaignID,                                    
        A.ParentID,                                    
        A.Applicabilty,                                    
        A.ApplicabiltyGroupList,                                    
        A.ExclusionsGroupList,                                    
        A.NotificationMail,                                    
        A.ExclusionsNumber,                                    
        A.Exclusions,                                    
        A.InclusionsNumber,                                    
        A.AccountUsed,                                    
        A.SenderID,                                    
        A.[Message],                                    
        A.TemplateID,                                    
        A.TemplateGroupID,                                    
        A.IsUnicode                                    
        INTO #temptemplate                                    
 FROM   (                                    
            SELECT Ucm.ID      AS CampaignID,                                    
                   Ucm.ParentID,                                    
                   Fs.[value]  AS Applicabilty,                                    
                   0           AS ApplicabiltyGroupList,                                    
                   0           AS ExclusionsGroupList,                                    
                   Ucm.NotificationMail,                                    
                   Ucm.ExclusionsNumber,                                    
                   0           AS Exclusions,                                    
                   Ucm.InclusionsNumber,                                    
                   Ucm.AccountUsed,                                    
                   Ucm.SenderID,                                    
                   Ucm.[Message],                                    
                   Ucm.TemplateID,                                    
                   Ucm.TemplateGroupID,                                    
                   Ucm.IsUnicode                                    
            FROM   Usercampaignmaster Ucm   (nolock)                                 
                   OUTER APPLY Dbo.Fn_split(Ucm.Applicabilty, '#') AS Fs                                    
            WHERE  Ucm.MailReplyTo <> ''  and isscheduled=1                                  
                   AND Ucm.NextExecuteDateTime between @LastExecutedTime and  getdate()                           
                   AND DATEDIFF(                                    
                           Minute,                                    
                           getdate(),                                    
                           CASE                                     
                                WHEN Ucm.IsNeverExpire = 1 THEN DATEADD(DAY, 1,getdate())                                    
                                ELSE ISNULL(Ucm.ExpiryDate, getdate())                                    
                           END                                    
                       ) > 0                                    
                   AND DATEDIFF(Minute, getdate(), ISNULL(Ucm.StartDate, getdate()))                                    
       <= 0                                    
                   AND Ucm.IsActive = 1                                    
            UNION ALL                                    
            SELECT Ucm.ID      AS CampaignID,                                    
                   Ucm.ParentID,                                    
                   0           AS Applicabilty,             
                   Fs.[value]  AS ApplicabiltyGroupList,                                    
                   0       AS ExclusionsGroupList,                                    
                   Ucm.NotificationMail,              
                   Ucm.ExclusionsNumber,                                    
                   0           AS Exclusions,                             
                   Ucm.InclusionsNumber,                                    
                   Ucm.AccountUsed,                          
                   Ucm.SenderID,                                    
                   Ucm.[Message],                                    
         Ucm.TemplateID,                                    
                   Ucm.TemplateGroupID,                                    
                   Ucm.IsUnicode                                    
            FROM   Usercampaignmaster Ucm  (nolock)                                  
                   OUTER APPLY Dbo.Fn_split(Ucm.ApplicabiltyGroupList, '#') AS                                     
            Fs                                    
            WHERE  Ucm.MailReplyTo <> ''    and isscheduled=1                                 
          AND Ucm.NextExecuteDateTime between @LastExecutedTime and  getdate()                                   
                   AND DATEDIFF(                                    
             Minute,                                    
                           getdate(),                                    
                           CASE                                     
                                WHEN Ucm.IsNeverExpire = 1 THEN DATEADD(DAY, 1, getdate())                                    
                                ELSE ISNULL(Ucm.ExpiryDate, getdate())                                    
                           END                                    
  ) > 0                                    
                   AND DATEDIFF(Minute, getdate(), ISNULL(Ucm.StartDate, getdate()))                                    
                       <= 0                                    
                   AND Ucm.IsActive = 1                                    
            UNION ALL                                    
            SELECT Ucm.ID      AS CampaignID,                                    
                   Ucm.ParentID,                                    
                   0           AS Applicabilty,                                    
                   0           AS ApplicabiltyGroupList,                                    
                   Fs.[value]  AS ExclusionsGroupList,                                    
                   Ucm.NotificationMail,                                    
                   Ucm.ExclusionsNumber,                                    
                   0           AS Exclusions,                                    
               Ucm.InclusionsNumber,                                    
                   Ucm.AccountUsed,                                    
                   Ucm.SenderID,                                    
                   Ucm.[Message],                                    
                   Ucm.TemplateID,                                    
                   Ucm.TemplateGroupID,                                    
                   Ucm.IsUnicode                                    
            FROM   Usercampaignmaster Ucm (nolock)                                   
                   OUTER APPLY Dbo.Fn_split(Ucm.ExclusionsGroupList, '#') AS                                     
            Fs                                    
            WHERE  Ucm.MailReplyTo <> ''   and isscheduled=1                                  
  AND  Ucm.NextExecuteDateTime between @LastExecutedTime and  getdate()                                   
                   AND DATEDIFF(                                    
                           Minute,                                    
                           getdate(),                                    
                           CASE                                     
                                WHEN Ucm.IsNeverExpire = 1 THEN DATEADD(DAY, 1, getdate())                            
                                ELSE ISNULL(Ucm.ExpiryDate, getdate())                                    
                           END                                    
                       ) > 0                        
                   AND DATEDIFF(Minute, getdate(), ISNULL(Ucm.StartDate, getdate()))                                    
                       <= 0                                    
                   AND Ucm.IsActive = 1                                    
            UNION ALL                                    
            SELECT Ucm.ID      AS CampaignID,                                    
                   Ucm.ParentID,                                    
    0           AS Applicabilty,                                    
                   0           AS ApplicabiltyGroupList,                                    
                   0           AS ExclusionsGroupList,                                    
                   Ucm.NotificationMail,                                    
                   Ucm.ExclusionsNumber,                                    
                   Fs.[value]  AS Exclusions,                                    
                   Ucm.InclusionsNumber,                                    
            Ucm.AccountUsed,                                    
                   Ucm.SenderID,                                    
                   Ucm.[Message],                                    
                   Ucm.TemplateID,                                    
                   Ucm.TemplateGroupID,                         
                   Ucm.IsUnicode                                    
            FROM   Usercampaignmaster Ucm   (nolock)                                 
                   OUTER APPLY Dbo.Fn_split(Ucm.Exclusions, '#') AS Fs                                    
            WHERE  Ucm.MailReplyTo <> ''      and isscheduled=1                               
                   AND  Ucm.NextExecuteDateTime between @LastExecutedTime and  getdate()       AND DATEDIFF(                                    
                           Minute,                                    
                           getdate(),                                    
CASE                                     
                                WHEN Ucm.IsNeverExpire = 1 THEN DATEADD(DAY, 1, getdate())                                    
                                ELSE ISNULL(Ucm.ExpiryDate, getdate())                                    
                           END                                    
     ) > 0                                    
                   AND DATEDIFF(Minute, getdate(), ISNULL(Ucm.StartDate, getdate()))                                    
                       <= 0                                    
                   AND Ucm.IsActive = 1                                    
        ) A                  
                          
                          
if OBJECT_ID('tempdb..##campaignrunmail') is null            
begin            
create table ##campaignrunmail(Date datetime,CampaignrunID bigint,                          
                           Campaignid bigint);                                                
end                                   
                                     
 INSERT INTO Usercampaignhistory                                    
   (                                    
     -- ID -- this column value is auto-generated                                    
     CampaignID,                                    
     ParentID,                                    
     Step1,                                    
     Step2,                                
     Step3,                                    
     IsSMS,                                    
     IsMail,                                    
     IsScheduled,                                    
     IsEventBased,                                    
     CreatedOn                                
   )                      
    output getdate(),inserted.id,inserted.campaignid into ##campaignrunmail                                 
 SELECT DISTINCT CampaignID,                                    
    ParentID,                                    
        0,        
        0,                                    
        0,                                    
        0,                                    
        1,                                    
        1,                                    
        0,                                    
        GETDATE()                                    
 FROM   #temptemplate          
                   
                   
                                     
 DELETE                                     
 FROM   #temptemplate                                    
 WHERE  AccountUsed IN (SELECT Ud.[User_ID]                                    
                        FROM   User_detail AS Ud                                    
                        WHERE  Ud.[Status] = 0)                          
                                     
 IF NOT EXISTS (                                    
        SELECT 'x'                                    
        FROM   #temptemplate                                    
    )                                    
 BEGIN                                    
     SET @Body = 'No Campaign Found'                                    
                                         
     SELECT @Body                                    
END                                    
 ELSE                                    
 BEGIN                                    
     CREATE TABLE #tempapplicability                                    
     (                                    
      SearchID       BIGINT,                                    
      ParentID       BIGINT,                                    
      CampaignID  BIGINT                                    
     )                                    
                                         
     CREATE TABLE #tempapplicabilitygroups                                    
     (                                    
 GroupID        BIGINT,                                    
      ParentID       BIGINT,                                    
      CampaignID     BIGINT                                    
     )                                    
                                         
     CREATE TABLE #tempapplicabilitylists                                    
     (                                    
      ListID         BIGINT,                                    
      ParentID       BIGINT,                                    
      CampaignID     BIGINT                                    
     )                                    
                                         
     INSERT INTO #tempapplicability                                    
       (                                    
         SearchID,                                    
         ParentID,                                    
         CampaignID                                    
       )                                    
     SELECT Tt.Applicabilty,                                    
            Tt.ParentID,                                    
            Tt.CampaignID                                    
     FROM   #temptemplate Tt                         
                                         
     INSERT INTO #tempapplicabilitygroups                                    
       (                                    
         GroupID,                                    
         ParentID,                                    
         CampaignID                                    
       )                                    
     SELECT Tt.ApplicabiltyGroupList,                                    
            Tt.ParentID,                       
            Tt.CampaignID                                    
     FROM   #temptemplate Tt                                    
                                         
     INSERT INTO #tempapplicabilitylists                                    
       (                                    
         ListID,                                    
         ParentID,                                    
         CampaignID                                    
       )                                    
     SELECT Tt.ApplicabiltyGroupList,                                    
            Tt.ParentID,                                    
            Tt.CampaignID                                    
     FROM   #temptemplate Tt                      
                                         
     CREATE TABLE #tempexclusion                                    
     (                                    
      SearchID       BIGINT,                                    
      ParentID       BIGINT,                                   
      CampaignID     BIGINT                                    
     )                                    
                                         
     CREATE TABLE #tempexclusiongroups                                    
     (                              
      GroupID        BIGINT,                                    
      ParentID       BIGINT,                                    
      CampaignID     BIGINT                                    
     )                                    
                                         
     CREATE TABLE #tempexclusionlists                                    
     (                                    
      ListID         BIGINT,                                    
      ParentID       BIGINT,                                   
      CampaignID     BIGINT                               
     )                                    
                                         
     INSERT INTO #tempexclusion                                    
       (                                    
         SearchID,                                    
         ParentID,                                    
         CampaignID                                    
       )                                    
     SELECT Tt.Exclusions,                                    
            Tt.ParentID,                                    
            Tt.CampaignID                                    
     FROM   #temptemplate Tt                                    
                                      
     INSERT INTO #tempexclusiongroups                                    
       (                                    
         GroupID,                                    
         ParentID,                                    
         CampaignID                                    
       )                 SELECT Tt.ExclusionsGroupList,                                    
            Tt.ParentID,                                    
            Tt.CampaignID                                    
     FROM   #temptemplate Tt                                    
                                         
     INSERT INTO #tempexclusionlists                                    
       (                                    
         ListID,                                    
         ParentID,                              
         CampaignID                                    
       )                                    
     SELECT Tt.ExclusionsGroupList,                        
            Tt.ParentID,                                    
            Tt.CampaignID                                    
     FROM #temptemplate Tt                                    
                                         
     CREATE TABLE #temptablesearchapp                                    
     (                                    
      CampaignID             BIGINT,                                    
      SearchID               BIGINT,                                    
      ParentID               BIGINT,                                    
      PersonName             NVARCHAR(200),                      
      CompanyName            NVARCHAR(200),                                    
      MobileNo               NVARCHAR(200),                                    
      MobileNo1              NVARCHAR(200),                                    
      MobileNo2              NVARCHAR(200),                                    
      EmailID                NVARCHAR(200),                                    
      EmailID1               NVARCHAR(200),                                    
      EmailID2               NVARCHAR(200),                                    
      City        NVARCHAR(200),                                    
      STATE                  NVARCHAR(200),                                    
   Country                NVARCHAR(200),                                    
      CountryCode            NVARCHAR(200),                                    
    PinCode                NVARCHAR(200),                                    
      ResidentialAddress     NVARCHAR(200),                                    
      OfficeAddress          NVARCHAR(200),                                    
      SourceName             NVARCHAR(200),                                    
      MediumName             NVARCHAR(200),                                    
      CampaignName           NVARCHAR(200),                                    
      InitialRemarks         NVARCHAR(1000)                                    
     )                                    
                                         
     CREATE TABLE #temptablesearchexc                                    
     (                            
      CampaignID             BIGINT,                                    
      SearchID               BIGINT,                                    
      ParentID               BIGINT,                                    
      PersonName             NVARCHAR(200),                                    
      CompanyName            NVARCHAR(200),                                    
      MobileNo               NVARCHAR(200),                                    
      MobileNo1              NVARCHAR(200),                                    
      MobileNo2              NVARCHAR(200),                                    
      EmailID   NVARCHAR(200),                                    
      EmailID1               NVARCHAR(200),                                    
      EmailID2               NVARCHAR(200),                                    
      City                   NVARCHAR(200),                                    
      STATE                  NVARCHAR(200),                                    
      Country           NVARCHAR(200),                                    
      CountryCode            NVARCHAR(200),                                    
      PinCode                NVARCHAR(200),                                    
      ResidentialAddress     NVARCHAR(200),                                    
      OfficeAddress          NVARCHAR(200),                                    
      SourceName             NVARCHAR(200),                                    
      MediumName             NVARCHAR(200),                                    
      CampaignName           NVARCHAR(200),                                    
      InitialRemarks         NVARCHAR(1000)                                    
     )                                    
                     
     DECLARE @Countapp     INT = (                                    
                 (                                    
                     SELECT COUNT(*)                                  
   FROM   #tempapplicability                                    
                 )                                    
                 + (                                    
                     SELECT COUNT(*)                                    
                     FROM   #tempapplicabilitygroups                                    
                 )                                    
                 + (                                    
                     SELECT COUNT(*)                                    
              FROM   #tempapplicabilitylists                                    
                 )                                    
             )                                    
                                         
     DECLARE @Countexc     INT = (                                    
                 (                                    
                     SELECT COUNT(*)                                    
                     FROM   #tempexclusion                                    
                 )                                    
                 + (                                    
                     SELECT COUNT(*)                                    
                     FROM  #tempexclusiongroups                                    
                 )                   
                 + (                                    
                     SELECT COUNT(*)                                    
                     FROM   #tempexclusionlists         
                 )                                    
             )                                    
                                         
     DECLARE @Count INT = 0                                    
                                         
     IF (@Countexc > @Countapp)                                    
     BEGIN                                    
         SET @Count = @Countexc                                    
     END                                    
     ELSE                                    
     BEGIN                                    
         SET @Count = @Countapp                                    
     END                                    
                                         
     WHILE (@Count > 0)                                    
     BEGIN                                    
    SET @Count = @Count - 1                                    
                                          
         DECLARE @Applicability1 BIGINT,                                    
                 @Parentidapp BIGINT,                                    
                 @Campaignidapp BIGINT                                    
                                             
         DECLARE @Groupid BIGINT,                                    
                 @Parentidgroup BIGINT,                                    
                 @Campaignidgroup BIGINT,                                    
                 @Groupidexc BIGINT,                                    
                 @Parentidgroupexc BIGINT,                                    
                 @Campaignidgroupexc BIGINT                                    
            
         DECLARE @Listid                BIGINT,                                    
                 @Parentidlist          BIGINT,                                    
                 @Campaignidlist        BIGINT,                                    
                @Listidexc             BIGINT,                                    
                 @Parentidlistexc       BIGINT,                                    
                 @Campaignidlistexc     BIGINT                                    
                                             
         SELECT TOP 1 @Applicability1 = SearchID,                                    
              @Parentidapp       = ParentID,                                    
                @Campaignidapp     = CampaignID                                    
         FROM   #tempapplicability                                    
         ORDER BY                                    
            SearchID,                      
                ParentID                                    
                                             
         SELECT TOP 1 @Groupid = GroupID,                                    
                @Parentidgroup       = ParentID,                                    
                @Campaignidgroup     = CampaignID                                    
         FROM   #tempapplicabilitygroups                                    
         ORDER BY                                    
                GroupID,         
                ParentID                            
                                             
         DELETE                                     
         FROM   #tempapplicabilitygroups                                    
         WHERE  GroupID = @Groupid                                    
                AND ParentID = @Parentidgroup                                    
                AND CampaignID = @Campaignidgroup                                    
                                             
         SELECT TOP 1 @Listid = ListID,                                    
     @Parentidlist       = ParentID,                                    
                @Campaignidlist     = CampaignID                                    
         FROM   #tempapplicabilitylists                                    
         ORDER BY                                    
                ListID,                                    
                ParentID                                    
                                             
         DELETE                                     
         FROM   #tempapplicabilitylists                                    
         WHERE  ListID = @Listid                                    
                AND ParentID = @Parentidgroup                                    
                AND CampaignID = @Campaignidgroup                                    
                                             
         DECLARE @Excluded1         BIGINT,                                    
                 @Parentidexc       BIGINT,                                    
                 @Campaignidexc     BIGINT                         
                                             
         SELECT TOP 1 @Excluded1 = SearchID,                                    
                @Parentidexc       = ParentID,                                    
                @Campaignidexc     = CampaignID                                    
         FROM   #tempexclusion                                    
         ORDER BY                  
                SearchID,                                    
                ParentID                                    
                                             
         SELECT TOP 1 @Groupidexc = GroupID,                                    
                @Parentidgroupexc       = ParentID,                                    
                @Campaignidgroupexc     = CampaignID                                    
         FROM   #tempexclusiongroups                                    
         ORDER BY                                    
                GroupID,                                    
                ParentID                                    
                                  
         DELETE                                     
         FROM   #tempexclusiongroups                                    
         WHERE  GroupID = @Groupidexc                                    
                AND ParentID = @Parentidgroupexc                        
                AND CampaignID = @Campaignidgroupexc                                    
                                             
    SELECT TOP 1 @Listidexc = ListID,                                    
                @Parentidlistexc       = ParentID,                                    
                @Campaignidlistexc     = CampaignID                                    
         FROM   #tempexclusionlists                                    
         ORDER BY                                    
                ListID,                                    
                ParentID                                    
                                             
         DELETE                                     
         FROM   #tempexclusionlists                                    
         WHERE  ListID = @Listidexc                                    
                AND ParentID = @Parentidlistexc                                    
                AND CampaignID = @Campaignidlistexc                                    
                                             
         DELETE                         
         FROM   #tempapplicability                                    
         WHERE  SearchID = @Applicability1                                    
                AND ParentID = @Parentidapp                                    
                                             
         DELETE                                     
         FROM   #tempexclusion                                    
         WHERE  SearchID = @Excluded1                                    
                AND ParentID = @Parentidexc                                    
                                             
      INSERT INTO #temptablesearchapp                                    
           (                                    
             EmailID,                                    
             CampaignID,                                    
             ParentID                                    
           )                                    
         SELECT ISNULL(Usd.EmailID, ''),                                    
                @Campaignidlist,                                    
                @Parentidlist                                    
         FROM   Usersearchdata AS Usd  (nolock)                                  
         WHERE  Usd.ParentID = @Parentidlist                                    
             AND Usd.ImportedListID = @Listid                                    
                                             
         INSERT INTO #temptablesearchapp                                    
           (                                    
             EmailID,                                    
             CampaignID,                                    
             ParentID                                    
           )                                    
         SELECT ISNULL(Cd.Contact_Email, ''),                                    
                @Campaignidgroup,                                    
                @Parentidgroup                                    
         FROM   Contact_detail AS Cd  (nolock)                                  
                INNER JOIN Contact_group_detail AS Cgd  (nolock)                                  
                     ON  Cgd.Contact_ID = Cd.Contact_ID                                    
         WHERE  Cgd.Group_ID = @Groupid               
                                             
         INSERT INTO #temptablesearchapp                                    
           (                                   
             PersonName,                                    
             CompanyName,                                    
             MobileNo,                                    
             MobileNo1,                                    
             MobileNo2,                                    
             EmailID,                                    
             EmailID1,                                    
             EmailID2,                                    
             Country,                                    
             [STATE],                       
             City,                              
             PinCode,                                    
             ResidentialAddress,                                    
             OfficeAddress,                                    
             SourceName,                                    
             MediumName,                                    
             CampaignName,                                    
             InitialRemarks,                                    
             SearchID,                                    
             ParentID,                                    
             CampaignID                                    
           )                                    
         EXEC Usp_executeusersearch                                    
              @Parentidapp,                                    
              @Applicability1,                                    
              @Campaignidapp                                 
                                             
         INSERT INTO #temptablesearchexc                   
           (                                    
             EmailID,                                    
             CampaignID,                                    
             ParentID                                    
           )                                    
         SELECT ISNULL(Usd.EmailID, ''),                                    
                @Campaignidlistexc,                                    
                @Parentidlistexc                                    
         FROM   Usersearchdata AS Usd  (nolock)                                  
         WHERE  Usd.ParentID = @Parentidlistexc                                    
                AND Usd.ImportedListID = @Listidexc                                    
                                             
         INSERT INTO #temptablesearchexc                                    
           (                                    
             EmailID,                                    
             CampaignID,                                    
             ParentID                                    
           )                                    
         SELECT ISNULL(Cd.Contact_Email, ''),                                    
                @Campaignidgroupexc,                                    
                @Parentidgroupexc                                    
         FROM   Contact_detail AS Cd  (nolock)                                  
       INNER JOIN Contact_group_detail AS Cgd   (nolock)                                 
                     ON  Cgd.Contact_ID = Cd.Contact_ID                                    
         WHERE  Cgd.Group_ID = @Groupidexc                                    
                                             
         INSERT INTO #temptablesearchexc                                    
           (                                    
             PersonName,                                    
             CompanyName,                                    
             MobileNo,                                    
             MobileNo1,                                    
  MobileNo2,                                    
             EmailID,                                    
             EmailID1,                                    
             EmailID2,                                    
             Country,                                    
             [STATE],                                    
             City,                                    
             PinCode,                                    
             ResidentialAddress,                                    
            OfficeAddress,                                    
             SourceName,                                    
             MediumName,                                    
             CampaignName,                                    
             InitialRemarks,                                    
             SearchID,                                    
             ParentID,                                    
             CampaignID                                    
           )                                    
         EXEC Usp_executeusersearch                                    
              @Parentidexc,                                    
              @Excluded1,                                    
              @Campaignidexc                                    
     END                                    
                                         
     DROP TABLE #tempexclusion                                    
                                         
     DROP TABLE #tempapplicability                                    
                                         
     DROP TABLE #tempexclusiongroups                                    
                                         
     DROP TABLE #tempapplicabilitygroups                                    
            DROP TABLE #tempexclusionlists                                    
                                         
     DROP TABLE #tempapplicabilitylists                                    
                                         
     SELECT A.EmailID,                                    
            A.ParentID,                                    
            A.CampaignID                                    
            INTO     #tempemailid                                    
     FROM   (                                    
                SELECT Tt2.EmailID,                                    
                       Tt2.ParentID,                                    
                       Tt2.CampaignID                                    
                FROM   #temptablesearchapp Tt2                                    
                WHERE  Tt2.EmailID NOT IN (SELECT Tt.EmailID                                    
                                           FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID NOT IN (SELECT Tt.EmailID1                                    
     FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID NOT IN (SELECT Tt.EmailID2                                    
                                        FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID1 NOT IN (SELECT Tt.EmailID                                    
                                                FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID1 NOT IN (SELECT Tt.EmailID1                                    
       FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID1 NOT IN (SELECT Tt.EmailID2                                    
                                                FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID2 NOT IN (SELECT Tt.EmailID                                    
                                                FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID2 NOT IN (SELECT Tt.EmailID1                                    
                                                FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID2 NOT IN (SELECT Tt.EmailID2                                    
                                                FROM   #temptablesearchexc Tt)                                    
                UNION                                    
                SELECT Tt2.EmailID1,                                    
                       Tt2.ParentID,                                    
           Tt2.CampaignID                                    
                FROM   #temptablesearchapp Tt2               
                WHERE  Tt2.EmailID NOT IN (SELECT Tt.EmailID                   
                                           FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID NOT IN (SELECT Tt.EmailID1                                    
                                               FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID NOT IN (SELECT Tt.EmailID2                                    
                                               FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID1 NOT IN (SELECT Tt.EmailID                                    
                                                FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID1 NOT IN (SELECT Tt.EmailID1                                    
                                                FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID1 NOT IN (SELECT Tt.EmailID2                                    
                                                FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID2 NOT IN (SELECT Tt.EmailID             
        FROM   #temptablesearchexc Tt)                          
                       OR  Tt2.EmailID2 NOT IN (SELECT Tt.EmailID1                                    
                          FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID2 NOT IN (SELECT Tt.EmailID2                                    
                                                FROM   #temptablesearchexc Tt)                                    
                UNION                                    
                SELECT Tt2.EmailID2,                                    
                       Tt2.ParentID,                                    
                       Tt2.CampaignID                                    
                FROM   #temptablesearchapp Tt2                                    
                WHERE  Tt2.EmailID NOT IN (SELECT Tt.EmailID                                    
                                           FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID NOT IN (SELECT Tt.EmailID1                                    
                                               FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID NOT IN (SELECT Tt.EmailID2                                    
                                               FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID1 NOT IN (SELECT Tt.EmailID                                    
                       FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID1 NOT IN (SELECT Tt.EmailID1                                    
                        FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID1 NOT IN (SELECT Tt.EmailID2                                    
                                                FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID2 NOT IN (SELECT Tt.EmailID                                    
                                                FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID2 NOT IN (SELECT Tt.EmailID1                                    
                                                FROM   #temptablesearchexc Tt)                                    
                       OR  Tt2.EmailID2 NOT IN (SELECT Tt.EmailID2                                    
                                                FROM   #temptablesearchexc Tt)                                    
       )        A                                    
                                         
     INSERT INTO Usercampaignexecutionhistory                                    
       (                                    
         CampaignID,                                    
         ExecutionTime,                                    
         IsRecipients,                                    
         ParentID                               
       )                                    
     SELECT DISTINCT A.CampaignID,                                    
            GETDATE(),                                    
            1,                                    
            A.ParentID                                    
     FROM   (                                    
                SELECT A.EmailID,                                    
                       A.ParentID,                                    
                       A.CampaignID                                    
                FROM   #tempemailid A                                    
                UNION                                    
                SELECT CAST(Fs.[value] COLLATE Latin1_general_ci_ai AS VARCHAR(500)),                                    
                       Ucm.ParentID,                                    
                       Ucm.ID                                    
      FROM   Usercampaignmaster AS Ucm   (nolock)                                 
                       OUTER APPLY Dbo.Fn_split(Ucm.InclusionsNumber, ',') AS                                     
                Fs                                    
                WHERE  Ucm.MailReplyTo <> ''              
                      AND Ucm.NextExecuteDateTime between @LastExecutedTime and  getdate()  AND DATEDIFF(                                    
                               Minute,                                    
                               getdate(),                                    
                               CASE                                     
                                    WHEN Ucm.IsNeverExpire = 1 THEN DATEADD(DAY, 1, getdate())                                    
                                    ELSE ISNULL(Ucm.ExpiryDate, getdate())                                    
                               END                                    
                           ) > 0                                    
                       AND DATEDIFF(Minute, getdate(), ISNULL(Ucm.StartDate, getdate()))                                    
                           < 0                                    
                       AND Ucm.IsActive = 1                                    
            ) A                                    
                                         
     INSERT INTO Emailsfiltercampaignexecution                                    
       (                                    
         Mail_FromEmail,                                    
         Mail_GUID,                                    
         Mail_ToEmail,           
         Mail_InsertedDate,                                    
         ParentID,                                    
         CampaignID,                                    
   Mail_UserID                                    
       )                                    
     SELECT '',                                    
            NEWID(),                                    
            A.EmailID,                                    
            GETDATE(),                                    
            A.ParentID,                                    
            A.CampaignID,                                    
            0                                    
     FROM   (                                    
                SELECT CAST(Tt.EmailID COLLATE Latin1_general_ci_ai AS VARCHAR(500)) AS                                     
                       EmailID,                                    
   Tt.ParentID,                                    
                 Tt.CampaignID                                    
                FROM   #tempemailid Tt                                    
                WHERE  Tt.EmailID <> ''                                    
                UNION                                    
                SELECT CAST(Fs.[value] COLLATE Latin1_general_ci_ai AS VARCHAR(500)),                                    
                       Ucm.ParentID,                                    
                       Ucm.ID                                    
                FROM   Usercampaignmaster AS Ucm  (nolock)                                  
                       OUTER APPLY Dbo.Fn_split(Ucm.InclusionsNumber, ',') AS                                     
                Fs                                    
                WHERE  Ucm.MailReplyTo <> ''                                    
                        AND  Ucm.NextExecuteDateTime between @LastExecutedTime and  getdate()   AND DATEDIFF(                                    
                               Minute,                                    
                               getdate(),                                    
                              CASE                                     
                                    WHEN Ucm.IsNeverExpire = 1 THEN DATEADD(DAY, 1, getdate())                                    
                                    ELSE ISNULL(Ucm.ExpiryDate, getdate())                                    
                       END                                    
                           ) > 0                                    
                       AND DATEDIFF(Minute, getdate(), ISNULL(Ucm.StartDate, getdate()))                                    
                           < 0                                    
                       AND Ucm.IsActive = 1                               
            ) A                                    
     WHERE  CAST(A.EmailID COLLATE Latin1_general_ci_ai AS VARCHAR(500))                                    
            NOT IN (SELECT CAST(                                    
                  ISNULL(Fs.[value], 'test') COLLATE                                    
                               Latin1_general_ci_ai AS                                    
                               VARCHAR(500)                                 )                                    
                    FROM   Usercampaignmaster AS Ucm2  (nolock)                                  
                           OUTER APPLY Dbo.Fn_split(Ucm2.ExclusionsNumber, ',') AS                                     
                    Fs                                    
                    WHERE  Ucm2.ID = A.CampaignID                                    
                           AND Ucm2.IsActive = 1                                    
                  AND A.ParentID = Ucm2.ParentID)                    
                                    
UPDATE A                        
SET step1=1,step1datetime=getdate(),step1recipients = isnull(B.[RecipientsCount],0)              
FROM [dbo].UserCampaignHistory A INNER JOIN                         
(SELECT a.campaignid as campaignid,isnull(count(e.CampaignID),0) AS [RecipientsCount]                        
         FROM UserCampaignHistory A (nolock) left outer join [dbo].[EmailsFilterCampaignExecution] e (nolock) on e.CampaignID=a.ID group by a.campaignid                        
 ) B                        
ON A.[campaignid] = B.[campaignid] join ##campaignrunmail c on a.ID=c.CampaignrunID                                         
                                         
     ---------------------------------Send Notification mail --------------------                                    
     INSERT INTO Getbatchrecord                                    
       (                                    
         [User_id],                                    
         RandNum                                    
       )                                    
     SELECT TOP 1 ParentID,                     
            CampaignID                                    
     FROM   #tempemailid                                    
     WHERE  EmailID <> ''                                    
                                         
     DECLARE @Batchidmails BIGINT                                    
                                         
     SELECT @Batchidmails = MAX(BatchID)                                    
     FROM   Getbatchrecord Gbr                                    
                                         
     DELETE Kd                                    
     FROM   Getbatchrecord Kd                                    
     WHERE  Kd.BatchID = @Batchidmails                                    
                                         
     INSERT INTO Batchemail_infos                                    
       (                                    
         -- ID -- this column value is auto-generated                                    
         BatchID,                                    
         UserID,                                    
         SenderName,                                    
         [Message],                                    
       TotalRecords,                                    
         TotalProcessed,                                    
         ProcessTable,                                    
         IsProcess,                                    
         Priority_Level,                                    
         BatchInsertTime,                                    
         BatchProcessTime,       
         ScheduledDate,                                    
         ScheduledTime,                                    
         TemplateID,                                    
         [Route],                                    
         PageName,                                    
         IsScheduled,                                    
         Email_Subject,                    
         ReplyTo,                                    
         Amount,                                    
         Currency                                    
       )                                    
     SELECT @Batchidmails,                                    
            335,                                    
            Ucm.NotificationMail,                                    
            'Hold tight ! Your ' + CASE                                     
                                        WHEN Ucm.MailReplyTo <> '' THEN                                     
                                             'Mail'                                    
                            ELSE 'SMS'                                    
                                   END + ' campaign '                                    
            + Ucm.CampaignName + ' scheduled for '                                    
            + CAST(GETDATE() AS VARCHAR(50))                +                                    
            ' is executing. We shall further notify you when the execution completes',                                    
            1,                                    
            0,                                    
          0,                                    
            0,                                    
            1,                                    
            GETDATE(),                                    
            GETDATE(),                                    
            GETDATE(),                                    
          GETDATE(),                                    
            0,                                    
            0,                                    
            0,                                    
            0,                                    
            'Campaign execution alert',                                    
            '',                                    
            0,                                    
            0                             
     FROM   #tempemailid Tt                             
            INNER JOIN Usercampaignmaster AS Ucm   (nolock)                                 
                 ON  Ucm.ID = Tt.CampaignID                     
                 AND Ucm.ParentID = Tt.ParentID                                    
                 AND Ucm.IsActive = 1                                    
     WHERE  EmailID <> ''                                    
     GROUP BY                                    
            Ucm.NotificationMail,                                    
            Ucm.MailReplyTo,                                    
            Ucm.CampaignName                         
                                         
     INSERT INTO Clientemails                                    
       (                                    
         -- Id -- this column value is auto-generated                                    
         GUID,                                    
         Email_Id,                                    
         SentDateTime,                                    
         UserId,                                    
         ReplyTo,                                    
         [Status],                                    
         BatchID,                                    
         [Message]                                    
       )                   
     SELECT NEWID(),                                    
            Ucm.NotificationMail,                                    
            GETDATE(),                                    
            335,                                    
            '',                                    
            '',                                    
            @Batchidmails,                          
            'Hold tight ! Your ' + CASE                                     
                                        WHEN Ucm.MailReplyTo <> '' THEN                                     
                                        'Mail'                                    
                                        ELSE 'SMS'                                    
                                   END + ' campaign '                                    
            + Ucm.CampaignName + ' scheduled for '                                    
            + CAST(GETDATE() AS VARCHAR(50))                                    
            +                                    
            ' is executing. We shall further notify you when the execution completes'                                    
     FROM   #tempemailid Tt                                    
     INNER JOIN Usercampaignmaster AS Ucm   (nolock)                                 
                 ON  Ucm.ID = Tt.CampaignID                                    
                 AND Ucm.ParentID = Tt.ParentID                 
                 AND Ucm.IsActive = 1                                    
     WHERE  EmailID <> ''                                    
     GROUP BY                                    
            Ucm.NotificationMail,                                    
            Ucm.MailReplyTo,                                    
            Ucm.CampaignName                    
                                         
     INSERT INTO Emailsfilter                                    
       (                                    
         Mail_GUID,                                    
         -- Mail_ID -- this column value is auto-generated                                    
         Mail_FromEmail,                                    
         Mail_ToEmail,                                    
         Mail_Subject,                                    
         Mail_TempleteName,                                    
         Messages,                                    
         Mail_InsertedDate,                                    
         Mail_UserID,                                    
         ReplyTo,                                    
         Mail_BatchID,                                    
         Mail_Priority,                  
         Mail_ScheduleDate,                                    
         Mail_Attechement,                                    
         Mail_TempleteBody,                                    
         IsMonitor                                    
       )                                    
     SELECT NEWID(),                                    
            'contactus@email19.in',                                    
            A.NotificationMail,                                    
            'Campaign execution alert',                                    
            '',                                    
            'Hold tight ! Your ' + CASE                                     
                                        WHEN A.MailReplyTo <> '' THEN 'Mail'                                    
                                        ELSE 'SMS'                                    
                                   END                                    
            + ' campaign '                                    
            + A.CampaignName + ' scheduled for '                                    
            + CAST(GETDATE() AS VARCHAR(50))                       
            +                                    
            ' is executing. We shall further notify you when the execution completes',                          
            GETDATE(),                                    
            335,                                    
            '',                                    
            @Batchidmails,                                    
            1,                                    
            GETDATE(),                                    
            0,                               
            '',                                    
            1            
     FROM   (                                    
                SELECT DISTINCT Ucm.CampaignName,                                    
                       Ucm.MailReplyTo,                                    
                       Ucm.NotificationMail                                    
                FROM   #tempemailid Tt                                    
                       INNER JOIN Usercampaignmaster AS Ucm  (nolock)                                  
                            ON  Ucm.ID = Tt.CampaignID                                    
                            AND Ucm.ParentID = Tt.ParentID                                    
                            AND Ucm.IsActive = 1                                    
                WHERE  EmailID <> ''                                    
                GROUP BY                                    
                       Ucm.NotificationMail,                                    
                       Ucm.CampaignName,                                    
                       Ucm.MailReplyTo                                    
            ) A                                    
                                              
      --      update EmailsFilter set EmailsFilter.Mail_Priority=2                                  
      --from   EmailsFilter inner join CustomerEmail on  EmailsFilter.Mail_ToEmail=CustomerEmail.Email                                                  
                                         
     INSERT INTO Mailcreditdetails                                    
       (                                    
         ID,                                    
         -- Credit_ID -- this column value is auto-generated                                    
         M_ID,                                    
      FromUser_ID,                                    
      [User_ID],                                    
         Debits,                                    
         Credits,                                    
         Balance,                                    
         Validity,                                    
         Default_Credit,                                    
         FromDate,         
         ToDate,                                    
         DateCreated,                                    
         DateUpdated,                                    
         EmpUpdated,                                    
         MachineName,                                    
         LastModified,                                    
         typecredit                                    
       )                                    
     SELECT NEWID(),                                    
            10001,                                    
            335,                                    
            335,                                    
            COUNT(*),                                    
            0,                                    
            (                                    
                SELECT TOP 1 Mcd.Balance                                    
                FROM   Mailcreditdetails AS Mcd  (nolock)                                  
                WHERE  Mcd.[User_ID] = 335                                    
                ORDER BY                                    
                       Mcd.Credit_ID DESC                                    
            ) - COUNT(*),                                    
            99999,                                    
            0,                                    
            GETDATE(),                                    
            GETDATE(),                                    
            GETDATE(),                                    
            GETDATE(),                                    
            'Campaign Exec',                                    
            '',                                    
            GETDATE(),                                    
0                                    
     FROM   (                                    
                SELECT DISTINCT Ucm.CampaignName,              
                       Ucm.MailReplyTo,                                    
              Ucm.NotificationMail                                    
         FROM   #tempemailid Tt                                    
                       INNER JOIN Usercampaignmaster AS Ucm   (nolock)                                 
                      ON  Ucm.ID = Tt.CampaignID                                    
                            AND Ucm.ParentID = Tt.ParentID                                    
                            AND Ucm.IsActive = 1                                    
                WHERE  EmailID <> ''                                    
                GROUP BY                                    
                       Ucm.NotificationMail,                                    
                       Ucm.CampaignName,                                    
    Ucm.MailReplyTo                                    
            ) A                                    
                                         
     ---------------------------------Send Notification Mail End ----------------                                    
     DROP TABLE #tempemailid                                    
                                      
     DROP TABLE #temptablesearchapp                                    
                                         
     DROP TABLE #temptablesearchexc                                    
 END                                    
                                     
    update UserCampaignExecution                                  
    set CampaignExecutedDatetime=GETDATE()                                  
                where issms=0      
   if exists(select 1 from ##timediffmail where id=@id)  
   begin               
   update ##timediffmail set lastexecutiontime=GETDATE(),timediff=DATEDIFF(s,campaigntime,GETDATE()) where id=@id    
   end                            
   
 if exists(select 1 from ##campaignrunmail)  
   begin                       
  update usercampaignhistory set step1=1,step1datetime=getdate() where ID in (select campaignrunid from ##campaignrunmail)                                 
  end  
  else   
  begin  
  update u set step1=1,step1datetime=getdate() from usercampaignhistory u join #temptemplate t on u.CampaignID=t.CampaignID  
  end  
  DROP TABLE #temptemplate  
END     


