                                           FROM   #temptablesearchexc Tt Where Tt2.EmailID1 = Tt.EmailID OR Tt2.EmailID1 = Tt.EmailID1 OR  Tt2.EmailID1 = Tt.EmailID2  )   
                UNION                                      
