     DECLARE @CountCampaign     INT = (Select MAX(Id) from #temptemplate    )                                        
                                                                              
     DECLARE @Count INT = 1                                                                         
                                             
     WHILE (@Count <= @CountCampaign)                                        
     BEGIN                                                             
                                              
         DECLARE @Applicability BIGINT,                                     
     @Exclusions BIGINT,  
                 @Parentid BIGINT,                                        
                 @Campaignid BIGINT,  
                 @userid bigint  
                     
                   
          Select @Campaignid =Campaignid, @Parentid = Parentid ,@userid=AccountUsed  
          ,@Applicability = tt.Applicabilty,@Exclusions = tt.Exclusions  
           from #temptemplate tt Where Id = @Count                                                                                          
          If(@Applicability is not null)  
          Begin    
          --For contact search, uncomment the below code & use usp_executeusersearch_New3 instead of usp_executeusersearch  
          if (isnull((select isgroup from usersearchlist where id=@applicability),0)=1)  
          begin  
            INSERT INTO #temptablesearchContacts                                        
  (Contact_ID ,        
         Contact_Name,        
         Contact_Mobile,        
         Contact_Email,        
         Contact_DOB,        
         Contact_Anniversary,        
         CompanyName ,        
         City ,        
         STATE ,        
         Country,        
         ADDRESS,        
         DateCreated,  
         Searchid,  
         Parentid,  
         Campaignid,  
         UserId  )  
         exec Usp_executeusersearch_New3 @parentid,@applicability,@campaignid,@userid                                 
            
          end  
          else   
          begin  
            
            
            INSERT INTO #temptablesearchapp                                        
       (                                       
      PersonName,                                        
      CompanyName,                                        
      MobileNo,                                        
      MobileNo1,                                        
      MobileNo2,                                        
      EmailID,                                        
      EmailID1,                                        
      EmailID2,                                        
      Country,                                        
      [STATE],                           
      City,                                  
      PinCode,                                        
      ResidentialAddress,                                        
      OfficeAddress,                                        
      SourceName,                                        
      MediumName,                                        
      CampaignName,                                        
      InitialRemarks,                                        
      SearchID,                                        
      ParentID,                                        
      CampaignID                                        
       )                                        
     EXEC Usp_executeusersearch                                        
       @ParentId,                                        
       @Applicability,                                        
       @Campaignid  
         
           End  
          end  
          if(@Exclusions is not null)  
          Begin  
          --For search within contacts uncomment below code  
          if (isnull((select isgroup from usersearchlist where id=@Exclusions),0)=1)  
          begin  
            INSERT INTO #temptablesearchExcContacts                                        
  (Contact_ID ,        
         Contact_Name,        
         Contact_Mobile,        
         Contact_Email,        
         Contact_DOB,        
         Contact_Anniversary,        
         CompanyName ,        
         City ,        
         STATE ,        
         Country,        
         ADDRESS,        
         DateCreated,  
         Searchid,  
         Parentid,  
         Campaignid,  
         UserId  )  
         exec Usp_executeusersearch_New3 @parentid,@applicability,@campaignid,@userid                                 
            
          end  
          else   
          begin                                    
    INSERT INTO #temptablesearchexc                                        
           (                                        
             PersonName,                                        
             CompanyName,                                        
             MobileNo,                                        
             MobileNo1,                                        
  MobileNo2,                                        
             EmailID,                                        
             EmailID1,                                        
             EmailID2,                                        
             Country,                                        
             [STATE],                                        
             City,                                        
             PinCode,                                        
             ResidentialAddress,                                        
            OfficeAddress,                                        
             SourceName,                                        
             MediumName,                                        
             CampaignName,                                        
             InitialRemarks,                                        
             SearchID,                                        
             ParentID,                                        
             CampaignID                                        
    )                                        
         EXEC Usp_executeusersearch                                        
              @Parentid,                                        
              @Exclusions,                                        
              @Campaignid  
      
    ENd  
    end  
     SET @Count = @Count+1  
       
     END                                        
