         [Message]                                        
       )       
       output inserted.GUID,inserted.Email_Id,inserted.BatchID into #output                  
     SELECT NEWID(),                                        
            Ucm.NotificationMail,                                        
            GETDATE(),                                        
            335,                                        
            'contactus@kit19.com',                                        
            '',                                        
            B.BatchId,                              
            case when tm.validentries=1 then 'Hold tight ! Your campaign "'                                        
         + Ucm.CampaignName + '" scheduled for '                                        
            + CAST(GETDATE() AS VARCHAR(50))                +                                        
            ' is executing. We shall further notify you when the execution completes' else 'Oops, you don''t have sufficient mail credits to run your mail campaign "'  
             + Ucm.CampaignName + '" scheduled for '                                  
             + Cast(Getdate() AS VARCHAR(50))                                  
             + '. Pl refill your credit balance & rerun the campaign ' end                                        
     FROM   #tempcount Tt                                        
     INNER JOIN Usercampaignmaster AS Ucm   (nolock)                                     
                 ON  Ucm.ID = Tt.CampaignID                                        
                 AND Ucm.ParentID = Tt.ParentID                     
                 AND Ucm.IsActive = 1                                       
                 inner join #tempMobile tm on tm.CampaignID=tt.CampaignID    
                 Inner join #Batch B on B.CampaignID = Tt.CampaignID  
     /*WHERE  EmailID <> ''                                        
     GROUP BY                                        
            Ucm.NotificationMail,                                        
            Ucm.MailReplyTo,                                        
            Ucm.CampaignName*/                        
                                             
     INSERT INTO Emailsfilter                                        
       (                                        
         Mail_GUID,                                        
         -- Mail_ID -- this column value is auto-generated                                        
         Mail_FromEmail,                                        
         Mail_ToEmail,                                        
         Mail_Subject,                                        
         Mail_TempleteName,                                        
         Messages,                                        
         Mail_InsertedDate,                                        
         Mail_UserID,                                        
         ReplyTo,                                        
         Mail_BatchID,                                        
         Mail_Priority,                      
         Mail_ScheduleDate,                                        
         Mail_Attechement,                                        
         Mail_TempleteBody,                                        
         IsMonitor                                        
       )                                        
     SELECT o.guid,                                        
            'contactus@email19.in',                                        
            ucm.NotificationMail,                                        
            'Campaign execution alert',                                        
            '',                                        
            case when tm.validentries=1 then 'Hold tight ! Your campaign "'                                        
            + Ucm.CampaignName + '" scheduled for '                                        
            + CAST(GETDATE() AS VARCHAR(50))                +                                        
            ' is executing. We shall further notify you when the execution completes' else 'Oops, you don''t have sufficient mail credits to run your mail campaign "'  
             + Ucm.CampaignName + '" scheduled for '                                  
             + Cast(Getdate() AS VARCHAR(50))                                  
             + '. Pl refill your credit balance & rerun the campaign ' end,                              
            GETDATE(),                                        
            335,                                        
            'contactus@kit19.com',                                        
            B.BatchId,                                        
            1,                                        
            GETDATE(),                                        
            0,                                   
            '',                                        
            1                
     FROM   #tempcount Tt                                        
                       INNER JOIN Usercampaignmaster AS Ucm  (nolock)                                      
                            ON  Ucm.ID = Tt.CampaignID                                        
                            AND Ucm.ParentID = Tt.ParentID                                        
                            AND Ucm.IsActive = 1   
                            inner join #tempMobile tm on tm.CampaignID=tt.CampaignID                                       
                            Inner join #Batch B on B.CampaignID = Tt.CampaignID  
                            inner join #output o on o.Email=ucm.NotificationMail  
                            where o.Batchid=B.BatchID  
               /* WHERE  EmailID <> ''                                        
                GROUP BY                                        
                       Ucm.NotificationMail,                                        
                       Ucm.CampaignName,                                        
                       Ucm.MailReplyTo                                        
            ) A */                                       
                                                  
      --      update EmailsFilter set EmailsFilter.Mail_Priority=2                                      
      --from   EmailsFilter inner join CustomerEmail on  EmailsFilter.Mail_ToEmail=CustomerEmail.Email                                                      
                                             
     INSERT INTO Mailcreditdetails                                        
       (                                        
         ID,                                        
         -- Credit_ID -- this column value is auto-generated                                        
         M_ID,                                        
      FromUser_ID,                                        
      [User_ID],                                        
         Debits,                                        
         Credits,                                        
         Balance,                                        
         Validity,                                        
         Default_Credit,                                        
         FromDate,             
         ToDate,                                        
         DateCreated,                                        
         DateUpdated,                                        
         EmpUpdated,                                        
         MachineName,                                        
         LastModified,                                        
         typecredit                                        
       )                                        
     SELECT NEWID(),                                        
            10001,                                        
            335,                                        
            335,                                        
            COUNT(*),                                        
            0,                                        
            (                                        
                SELECT TOP 1 Mcd.Balance                                        
                FROM   Mailcreditdetails AS Mcd  (nolock)                                      
                WHERE  Mcd.[User_ID] = 335                                        
                ORDER BY                                        
                       Mcd.Credit_ID DESC                                        
            ) - COUNT(*),                                        
            99999,       
            0,                                        
            GETDATE(),                                        
            GETDATE(),                                        
            GETDATE(),                                        
            GETDATE(),                                        
            'Campaign Exec',                                        
            '',                                        
            GETDATE(),                                        
0                                        
     FROM   #tempcount Tt                                        
                       INNER JOIN Usercampaignmaster AS Ucm   (nolock)                                     
                      ON  Ucm.ID = Tt.CampaignID                                        
                            AND Ucm.ParentID = Tt.ParentID                                        
                            AND Ucm.IsActive = 1    
                            --inner join #tempMobile tm on tm.CampaignID=tt.CampaignID                                      
               /* WHERE  EmailID <> ''                                        
                GROUP BY                                        
                       Ucm.NotificationMail,                                        
                       Ucm.CampaignName,                                        
    Ucm.MailReplyTo                                        
            ) A  */                                      
                                             
     ---------------------------------Send Notification Mail End ----------------    
   
 ---Update the next schedule for campaign      
select campaignid into #FindCampaignsNextExecution from #temptemplate t join UserCampaignMaster ucm on t.CampaignID=ucm.id      
    where ucm.IsActive=1 and ucm.IsSchedule=1 and ucm.IsScheduled=1      
          
 declare @count1 int =isnull((select COUNT(1) from #FindCampaignsNextExecution),0)      
 if @count1>0      
 begin      
    create table #nextexec1(campaignid bigint,nextexecution datetime)                  
    WHILE @Count1 > 0                      
  BEGIN                      
   DECLARE @Campaignid1 BIGINT = (                      
       SELECT TOP 1 campaignid                      
    FROM   #FindCampaignsNextExecution                      
      )          
     
   INSERT INTO #nextexec1                      
       (                      
      campaignid,                      
      nextexecution                      
       )                      
    EXEC Usp_getnextscheduledate                  
       @Campaignid1                      
      
    DELETE                       
    FROM   #FindCampaignsNextExecution                      
    WHERE  campaignid = @Campaignid1                      
      
    SET @Count1 = @Count1 - 1        
  END      
   update u set NextExecuteDateTime= nextexecution from usercampaignmaster u join #nextexec1 n on n.campaignid=u.id      
   where u.ExpiryDate > nextexecution or u.ExpiryDate is null      
    drop table #nextexec1      
    drop table #FindCampaignsNextExecution     
      
 end   
 -----Next schedule time updated---  
       
     drop table #Batch  
     drop table #output  
                                           
     DROP TABLE #tempemailid                                        
                                          
     DROP TABLE #temptablesearchapp                                        
                                             
     DROP TABLE #temptablesearchexc   
  drop table #tempCount  
  drop table #TempTableRunningTotal  
  drop table #tempMobile     
  DROP TABLE #temptemplate                                          
  drop table #temptablesearchContacts  
  drop table #temptablesearchExcContacts   
 ENd                                       
                                         
  update UserCampaignExecution                                      
    set CampaignExecutedDatetime=@CampaignStarttime,isevent=0              
                where issms=0 and isnull(isevent,0)=0          
    
  UPDATE A                              
  SET step1=1,step1datetime=getdate()  
  FROM [dbo].UserCampaignHistory A where A.Jobid = @JobId   
    
  exec Usp_userexecutecampaignmessagesmailsnewCorrected @jobid  
end  
  else  
  begin  
  if (select Lasterrorreported from UserCampaignExecution where issms=0 and isnull(isevent,0)=0) is null or (DATEDIFF(mi,(select isnull(Lasterrorreported,dateadd(mi,-6,getdate())) from UserCampaignExecution where issms=0 and isnull(isevent,0)=0),getdate()
)>5  and DATEDIFF(mi,(select isnull(CampaignExecutedDatetime,dateadd(mi,-6,getdate())) from UserCampaignExecution where issms=0 and isnull(isevent,0)=0),getdate()
)>5) 
  begin  
  declare @campaignstart datetime =(select CampaignExecutedDatetime from UserCampaignExecution where issms=0 and isnull(isevent,0)=0), @lastjobid bigint =(select top 1 jobid from usercampaignhistory (nolock) where issms=0 and iseventbased=0 and campaignid<>0 and jobid<>@jobid order by ID desc)  
  declare @step int = (select top 1 case when step2datetime is null then 2 else 3 end from usercampaignhistory (nolock) where jobid=@lastjobid)  
  declare @error nvarchar(200)='Last Campaign with jobid ' + cast(@lastjobid as varchar(10)) + ' failed at step ' + cast(@step as varchar) + ' running since ' + cast(@campaignstart as nvarchar(20))  
  exec usp_InsertCampaignError'Mail',0,@error  
  update UserCampaignExecution set Lasterrorreported=GETDATE() where issms=0 and isnull(isevent,0)=0  
  end  
  end  
  
END   
  


GO

/* ============================================================
   Procedure: [dbo].[Usp_executerecipientsusercampaignmailsCorrected_segregatemail]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

                                         
CREATE   PROCEDURE [dbo].[Usp_executerecipientsusercampaignmailsCorrected_segregatemail]   
AS                                        
BEGIN   
 DECLARE @Body VARCHAR(500)                                        
                                      
 DECLARE @LastExecutedTime datetime =isnull((select Top 1 CampaignExecutedDatetime from UserCampaignExecution where issms=0 and isnull(isevent,0)=0 order by id desc),getdate())    
 DEclare @JobId Bigint = (Select ISNULL(MAX(JobId),0)+1 from UserCampaignHistory UCH )
 declare @campaignstartdate datetime=getdate()
    INSERT INTO Usercampaignhistory                                        
   (                                        
     -- ID -- this column value is auto-generated                                        
     CampaignID,                                        
     ParentID,                                        
     Step1,                                        
     Step2,                                    
     Step3,                                        
     IsSMS,                                        
     IsMail,                                        
     IsScheduled,                                        
     IsEventBased,                                        
     CreatedOn,  
     JobId                                    
   )                          
 SELECT 0,                                        
    0,                                        
        0,            
        0,                                        
        0,                                        
        0,                                        
        1,                                        
        1,                                        
        0,                                        
        @campaignstartdate,  
        @JobId
   
 --select @jobid  
 if exists(select 1 from UserCampaignExecution where issms=0 and isnull(isevent,0)=0 and isrunning=0)  
 begin  
 update UserCampaignExecution set isrunning=1 where issms=0 and isnull(isevent,0)=0
 Declare @CampaignStarttime datetime = Getdate()    
 if OBJECT_ID('tempdb..#temptemplate') is not null                
 Begin   
 Drop table #temptemplate   
 end        
       
 SELECT    ROW_NUMBER()Over(Order by Ucm.ID,Ucm.ParentID) AS Id,     
     Ucm.ID      AS CampaignID,                                        
                   Ucm.ParentID,                                        
                   A.[value]  AS Applicabilty,                                        
                   AGL.[value]         AS ApplicabiltyGroupList,                                        
                   EGL.[value]        AS ExclusionsGroupList,                                        
                   Ucm.NotificationMail,                                        
                   Ucm.ExclusionsNumber,                                        
                   E.[value]           AS Exclusions,                                        
                   Ucm.InclusionsNumber,                                        
                   Ucm.AccountUsed,                                        
                   Ucm.SenderID,                                        
                   Ucm.[Message],                                        
                   Ucm.TemplateID,                                        
                   Ucm.TemplateGroupID,                                        
                   Ucm.IsUnicode                    INTO #temptemplate                                                                   FROM   Usercampaignmaster Ucm   (nolock)  
   Inner join  User_detail AS Ud  on Ud.[User_ID]  = AccountUsed and Ud.[Status] <> 0                                            OUTER APPLY Dbo.Fn_split(Ucm.Applicabilty, '#') AS A   
   OUTER APPLY Dbo.Fn_split(Ucm.ApplicabiltyGroupList, '#') AS AGL  
   OUTER APPLY Dbo.Fn_split(Ucm.ExclusionsGroupList, '#') AS  EGL   
   OUTER APPLY Dbo.Fn_split(Ucm.Exclusions, '#') AS E                                        
            WHERE Ucm.MailReplyTo <> ''  and isscheduled=1                                      
                   /*AND convert(varchar(20),Ucm.NextExecuteDateTime,100) between   
                   convert(varchar(20),@LastExecutedTime,100) and    
                   convert(varchar(20), GETDATE(), 100) */  
                   AND Ucm.NextExecuteDateTime between   
                   @LastExecutedTime and    
                  GETDATE()                              
                   AND DATEDIFF(                                        
                           Minute,                                        
                           getdate(),                                        
                           CASE                                         
                                WHEN Ucm.IsNeverExpire = 1 THEN DATEADD(DAY, 1,getdate())                                        
                                ELSE ISNULL(Ucm.ExpiryDate, getdate())                                        
                       END                                        
                       ) > 0                                        
                   AND DATEDIFF(Minute, getdate(), ISNULL(Ucm.StartDate, getdate()))  <= 0                                        
                   AND Ucm.IsActive = 1                                        
     
   --select * from #temptemplate  
                                   
   INSERT INTO Usercampaignhistory                                        
   (                                        
     -- ID -- this column value is auto-generated                                        
     CampaignID,                                        
     ParentID,                                        
     Step1,                                        
     Step2,                                    
     Step3,                                        
     IsSMS,                                        
     IsMail,                                        
     IsScheduled,                                        
     IsEventBased,                                        
     CreatedOn,  
     JobId                                    
   )                          
 SELECT DISTINCT CampaignID,                                        
    ParentID,                                        
        0,            
        0,                                        
        0,                                        
        0,                                        
        1,                                        
        1,                                        
        0,                                        
        @campaignstartdate,  
        @JobId                                        
 FROM   #temptemplate     
                       
 IF NOT EXISTS (                                        
        SELECT 'x'                                        
        FROM   #temptemplate   
        )                                        
 BEGIN    
     SET @Body = 'No Campaign Found'                                        
     SELECT @Body                                        
     INSERT INTO Usercampaignhistory                                        
   (                                        
     -- ID -- this column value is auto-generated                                        
     CampaignID,                                        
     ParentID,                                        
     Step1,                                        
     Step2,                                    
     Step3,                                        
     IsSMS,                                        
     IsMail,                                        
     IsScheduled,                                        
     IsEventBased,                                        
     CreatedOn,  
     JobId                                    
   )                          
 SELECT 0,                                        
        0,                                        
        0,            
        0,                                        
        0,                                        
        0,                                        
        1,                                        
        1,                                        
        0,                                        
        GETDATE(),  
        @JobId  
--select 2  
END     
--select * from #temptemplate  
 ELSE                                        
 BEGIn                                                       
     CREATE TABLE #temptablesearchapp                                        
     (                                        
      CampaignID             BIGINT,                                        
      SearchID               BIGINT,                                        
      ParentID               BIGINT,  
      UserId                 bigint,                                       
      PersonName             NVARCHAR(200),                          
      CompanyName            NVARCHAR(200),                                        
      MobileNo               NVARCHAR(200),                                        
      MobileNo1              NVARCHAR(200),                                        
      MobileNo2              NVARCHAR(200),                 
      EmailID                NVARCHAR(200),                                        
      EmailID1               NVARCHAR(200),                                        
      EmailID2               NVARCHAR(200),                                        
      City        NVARCHAR(200),                                        
      STATE                  NVARCHAR(200),                                        
   Country                NVARCHAR(200),                                        
      CountryCode            NVARCHAR(200),                                        
    PinCode                NVARCHAR(200),                                        
      ResidentialAddress     NVARCHAR(200),                                        
      OfficeAddress          NVARCHAR(200),                                        
      SourceName             NVARCHAR(200),                                        
      MediumName             NVARCHAR(200),                                        
      CampaignName           NVARCHAR(200),                                        
      InitialRemarks         NVARCHAR(1000) )  
      --For searces from contacts,uncomment below code  
     Create table #temptablesearchContacts  
        (Contact_ID             BIGINT,        
         Contact_Name           VARCHAR(150),        
         Contact_Mobile         VARCHAR(50),        
         Contact_Email          VARCHAR(50),        
         Contact_DOB            VARCHAR(50),        
         Contact_Anniversary    VARCHAR(50),        
         CompanyName            VARCHAR(100),        
         City                   VARCHAR(100),        
         STATE                  VARCHAR(100),        
         Country                VARCHAR(100),        
         ADDRESS                VARCHAR(200),        
         DateCreated            VARCHAR(50),  
         CampaignID             BIGINT,                                        
      SearchID               BIGINT,                                        
      ParentID               BIGINT,  
      UserId                 bigint)                                           
                                             
                                             
     CREATE TABLE #temptablesearchexc                                        
     (                                
      CampaignID             BIGINT,                                        
      SearchID               BIGINT,                                        
      ParentID               BIGINT,                                        
      UserId                 bigint,  
      PersonName             NVARCHAR(200),                                        
      CompanyName            NVARCHAR(200),                                        
      MobileNo               NVARCHAR(200),                                        
      MobileNo1              NVARCHAR(200),                                        
      MobileNo2              NVARCHAR(200),                                        
      EmailID   NVARCHAR(200),                                        
      EmailID1               NVARCHAR(200),                                        
      EmailID2               NVARCHAR(200),                                        
      City                   NVARCHAR(200),                                        
      STATE                  NVARCHAR(200),                                        
      Country           NVARCHAR(200),                                        
      CountryCode            NVARCHAR(200),                                        
      PinCode                NVARCHAR(200),                                        
      ResidentialAddress     NVARCHAR(200),                                        
      OfficeAddress          NVARCHAR(200),                                        
      SourceName             NVARCHAR(200),                                        
      MediumName             NVARCHAR(200),                                        
      CampaignName           NVARCHAR(200),                                        
      InitialRemarks         NVARCHAR(1000)  )                                      
       --For searces from contacts,uncomment below code  
     Create table #temptablesearchExcContacts  
        (Contact_ID             BIGINT,        
         Contact_Name           VARCHAR(150),        
         Contact_Mobile         VARCHAR(50),        
         Contact_Email          VARCHAR(50),        
         Contact_DOB            VARCHAR(50),        
         Contact_Anniversary    VARCHAR(50),        
         CompanyName            VARCHAR(100),        
         City                   VARCHAR(100),        
         STATE                  VARCHAR(100),        
         Country                VARCHAR(100),        
         ADDRESS                VARCHAR(200),        
         DateCreated            VARCHAR(50),  
         CampaignID             BIGINT,                                        
      SearchID               BIGINT,                                        
      ParentID               BIGINT,  
      UserId                 bigint)       
  
 INSERT INTO #temptablesearchapp(  EmailID,CampaignID,ParentID,userid  )                                        
         Select ISNULL(Usd.EmailID, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed    
   FROM  #temptemplate TT  
   Inner join  Usersearchdata AS Usd  (nolock)  on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ApplicabiltyGroupList and Tt.ApplicabiltyGroupList is not null       
         union     
      select distinct A.emailid,A.CampaignID,A.ParentID,A.userid  
        from (select f.value as Emailid,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.InclusionsNumber,',') f where f.value is not null group by CampaignID,ParentID,AccountUsed,f.value ) A          
--For search in contacts, the below code should be reviewed,corrected & uncommented                               
  /*  INSERT INTO #temptablesearchapp(Contact_EmailID,CampaignID,ParentID,userid)                                        
         SELECT ISNULL(Cd.Contact_Email, ''),Tt.CampaignID, Tt.ParentID,tt.AccountUsed     
         FROM  #temptemplate TT                                     
   Inner join Contact_group_detail AS Cgd  (nolock) on Cgd.Group_ID = TT.ApplicabiltyGroupList and Tt.ApplicabiltyGroupList is not null               
         INNER JOIN Contact_detail  AS  Cd   (nolock) ON  Cgd.Contact_ID = Cd.Contact_ID   */  
     
    INSERT INTO #temptablesearchexc (  EmailID,CampaignID,ParentID,userid  )            
         SELECT ISNULL(Usd.EmailID, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed    
         FROM #temptemplate TT                 
    Inner join   Usersearchdata AS Usd  (nolock) on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ExclusionsGroupList and Tt.ExclusionsGroupList is not null    
      union     
      select distinct A.emailid,A.CampaignID,A.ParentID,A.userid  
        from (select f.value as Emailid,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.ExclusionsNumber,',') f where f.value is not null group by CampaignID,ParentID,AccountUsed,f.value ) A          
               
   
--For search in contacts, the below code should be reviewed,corrected & uncommented                                
    /*INSERT INTO #temptablesearchexc  (  EmailID,CampaignID,ParentID,userid  )                                                             SELECT ISNULL(Cd.Contact_Email, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed    
   FROM  #temptemplate TT                                     
   Inner join Contact_group_detail AS Cgd  (nolock) on Cgd.Group_ID = TT.ExclusionsGroupList and Tt.ExclusionsGroupList is not null               
         INNER JOIN Contact_detail  AS  Cd   (nolock) ON  Cgd.Contact_ID = Cd.Contact_ID   */  
  
     DECLARE @CountCampaign     INT = (Select MAX(Id) from #temptemplate    )                                        
                                                                              
     DECLARE @Count INT = 1                                                                         
                                             
     WHILE (@Count <= @CountCampaign)                                        
     BEGIN                                                             
                                              
         DECLARE @Applicability BIGINT,                                     
     @Exclusions BIGINT,  
                 @Parentid BIGINT,                                        
                 @Campaignid BIGINT,  
                 @userid bigint  
                     
                   
          Select @Campaignid =Campaignid, @Parentid = Parentid ,@userid=AccountUsed  
          ,@Applicability = tt.Applicabilty,@Exclusions = tt.Exclusions  
           from #temptemplate tt Where Id = @Count                                                                                          
          If(@Applicability is not null)  
          Begin    
          --For contact search, uncomment the below code & use usp_executeusersearch_New3 instead of usp_executeusersearch  
          if (isnull((select isgroup from usersearchlist where id=@applicability),0)=1)  
          begin  
            INSERT INTO #temptablesearchContacts                                        
  (Contact_ID ,        
         Contact_Name,        
         Contact_Mobile,        
         Contact_Email,        
         Contact_DOB,        
         Contact_Anniversary,        
         CompanyName ,        
         City ,        
         STATE ,        
         Country,        
         ADDRESS,        
         DateCreated,  
         Searchid,  
         Parentid,  
         Campaignid,  
         UserId  )  
         exec Usp_executeusersearch_New3 @parentid,@applicability,@campaignid,@userid                                 
            
          end  
          else   
          begin  
            
            
            INSERT INTO #temptablesearchapp                                        
       (                                       
      PersonName,                                        
      CompanyName,                                        
      MobileNo,                                        
      MobileNo1,                                        
      MobileNo2,                                        
      EmailID,                                        
      EmailID1,                                        
      EmailID2,                                        
      Country,                                        
      [STATE],                           
      City,                                  
      PinCode,                                        
      ResidentialAddress,                                        
      OfficeAddress,                                        
      SourceName,                                        
      MediumName,                                        
      CampaignName,                                        
      InitialRemarks,                                        
      SearchID,                                        
      ParentID,                                        
      CampaignID                                        
       )                                        
     EXEC Usp_executeusersearch                                        
       @ParentId,                                        
       @Applicability,                                        
       @Campaignid  
         
           End  
          end  
          if(@Exclusions is not null)  
          Begin  
          --For search within contacts uncomment below code  
          if (isnull((select isgroup from usersearchlist where id=@Exclusions),0)=1)  
          begin  
            INSERT INTO #temptablesearchExcContacts                                        
  (Contact_ID ,        
         Contact_Name,        
         Contact_Mobile,        
         Contact_Email,        
         Contact_DOB,        
         Contact_Anniversary,        
         CompanyName ,        
         City ,        
         STATE ,        
         Country,        
         ADDRESS,        
         DateCreated,  
         Searchid,  
         Parentid,  
         Campaignid,  
         UserId  )  
         exec Usp_executeusersearch_New3 @parentid,@applicability,@campaignid,@userid                                 
            
          end  
          else   
          begin                                    
    INSERT INTO #temptablesearchexc                                        
           (                                        
             PersonName,                                        
             CompanyName,                                        
             MobileNo,                                        
             MobileNo1,                                        
  MobileNo2,                                        
             EmailID,                                        
             EmailID1,                                        
             EmailID2,                                        
             Country,                                        
             [STATE],                                        
             City,                                        
             PinCode,                                        
             ResidentialAddress,                                        
            OfficeAddress,                                        
             SourceName,                                        
             MediumName,                                        
             CampaignName,                                        
             InitialRemarks,                                        
             SearchID,                                        
             ParentID,                                        
             CampaignID                                        
    )                                        
         EXEC Usp_executeusersearch                                        
              @Parentid,                                        
              @Exclusions,                                        
              @Campaignid  
      
    ENd  
    end  
     SET @Count = @Count+1  
       
     END                                        
     --For search within contacts uncomment below code  
            
          INSERT INTO #temptablesearchapp(EmailID,CampaignID,ParentID,userid)    
          select Contact_Email,CampaignID,ParentID,userid from #temptablesearchContacts  
           INSERT INTO #temptablesearchexc(EmailID,CampaignID,ParentID,userid)    
          select Contact_Email,CampaignID,ParentID,userid from #temptablesearchExcContacts  
                                                                                            
     SELECT A.EmailID,                                        
            A.ParentID,                                        
            A.CampaignID,  
            A.userid                                        
            INTO     #tempemailid                                        
     FROM   (                                        
                SELECT Tt2.EmailID,                                        
                       Tt2.ParentID,                                        
                       Tt2.CampaignID,  
                       tt.Accountused as userid    
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                                        
                WHERE  Tt2.EmailID is not null and NOT EXISTS (SELECT 1 FROM   #temptablesearchexc Tt   
       Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.EmailID = Tt.EmailID OR Tt2.EmailID = Tt.EmailID1 OR Tt2.EmailID = Tt.EmailID2 ) )                        UNION                                        
                SELECT Tt2.EmailID1,                                        
                       Tt2.ParentID,                    
           Tt2.CampaignID,tt.Accountused  as userid                                       
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                  
                 WHERE Tt2.EmailID1 is not null and  NOT EXISTS (SELECT 1                                        
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.EmailID1 = Tt.EmailID OR Tt2.EmailID1 = Tt.EmailID1 OR  Tt2.EmailID1 = Tt.EmailID2)  )     
                UNION                                        
                SELECT Tt2.EmailID2,                                        
                       Tt2.ParentID,                                        
                       Tt2.CampaignID,tt.Accountused as userid                                        
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                                        
                 WHERE  Tt2.EmailID2 is not null and  NOT EXISTS (SELECT 1                                        
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND (Tt2.EmailID2 = Tt.EmailID OR Tt2.EmailID2 = Tt.EmailID1 OR  Tt2.EmailID2= Tt.EmailID2 ) )     
           
       )        A                                        
                       
    SELECT   
     ROW_NUMBER() Over(order by CampaignId,ParentId) Id,  
     Ucerm.CampaignID,     
     Ucerm.ParentID                               ,  
                     -- Cast(Ucerm.Messages AS VARCHAR(MAX))  AS  Messages,                                  
                     ucerm.userID,                                
                     Count(*) cnt  
                     -- Ucerm.Mail_ToEmail,                                  
   INTO   #tempCount                                  
      FROM   #tempemailid Ucerm where ucerm.EmailID is not null                                 
      Group by  Ucerm.CampaignID,     
     Ucerm.ParentID ,                                  
                      Ucerm.UserID  
                                                    
        
      SELECT A.UserID,a.CampaignID, a.cnt,SUM(b.cnt) RunningTotal into #TempTableRunningTotal  
   FROM   #tempCount a join  
       #tempCount b  on a.userid=b.userid
   WHERE b.CampaignID <= a.CampaignID  
   GROUP BY A.UserID, a.CampaignID, a.cnt  
   ORDER BY a.CampaignID;  
        
   --- Calculate credits                                  
      SELECT B.UserID,   
    B.CampaignID,  
      CASE                                  
               WHEN B.Balance >= B.Credits THEN 1                                  
               ELSE 0  -- Test                                  
             END AS ValidEntries                                  
      INTO   #tempMobile                                  
      FROM   (SELECT A.UserID,    
      A.CampaignID,                                
                     (A.Credits)   AS Credits,  --Runningtotal                                
                     A.Balance                                  
              FROM   (SELECT Tt.UserID,                                  
                             TT.RunningTotal AS Credits,  
                             TT.CampaignID,                                  
                            -- Tt.Mail_ToEmail,                                  
                             (SELECT TOP 1 Balance                                  
                              FROM   Mailcreditdetails AS Mcd                                  
                              WHERE  Mcd.[User_ID] = Tt.UserID                                  
                              ORDER  BY Credit_ID DESC)     AS Balance                                  
                      FROM   #TempTableRunningTotal Tt) A                                  
              GROUP  BY A.UserID,                                  
                        A.Balance,A.CampaignID,A.credits) B  
                                             
     INSERT INTO Usercampaignexecutionhistory                                        
       (                                        
         CampaignID,                                        
         Jobid,  
         ExecutionTime,                                        
         IsRecipients,                                        
         ParentID  
           
       )                                        
     SELECT DISTINCT A.CampaignID,                                        
            @JobId,  
            GETDATE(),                                        
            1,                                        
            A.ParentID                                        
     FROM   (                                        
               SELECT  
      TT.ParentID,  
      TT.CampaignID  
                from #tempcount TT join #tempMobile tm on tm.CampaignID=tt.CampaignID  
                where tm.ValidEntries=1                                                 
            ) A     
                                     
       
     --delete te from #tempemailid te join #tempmobile tm on te.campaignid=tm.campaignid where tm.validentries=0                                       
     INSERT INTO EmailsfiltercampaignexecutionTEST2                                        
       (                                        
         Mail_FromEmail,                                        
         Mail_GUID,                                        
         Mail_ToEmail,               
         Mail_InsertedDate,                                        
         ParentID,                                        
         CampaignID,                                        
   Mail_UserID,  
            JobId                                          
       )                                        
     SELECT '',                                        
            NEWID(),                                        
            A.EmailID,                                        
            GETDATE(),                                        
            A.ParentID,                                        
            A.CampaignID,                                        
            0,  
            @JobId                                          
     FROM   (SELECT CAST(Tt.EmailID COLLATE Latin1_general_ci_ai AS VARCHAR(500)) AS EmailID,                                        
   Tt.ParentID,                                        
                 Tt.CampaignID ,  
            @JobId Jobid                                         
                FROM   #tempemailid Tt                                        
                WHERE  Tt.EmailID <> '' and tt.EmailID is not null                                       
                UNION                                        
                SELECT CAST(Fs.[value] COLLATE Latin1_general_ci_ai AS VARCHAR(500)),                                        
                       tt.ParentID,                                        
                       tt.CampaignID,  
            @JobId  Jobid                                        
                FROM   #temptemplate AS tt  (nolock)                                      
                       OUTER APPLY Dbo.Fn_split(tt.InclusionsNumber, ',') AS Fs  where  fs.value is not null  and fs.value<>''                                     
     ) A  
     Inner join #tempMobile TM on TM.CampaignID = A.CampaignID                                        
     WHERE  TM.ValidEntries = 1 and  
      CAST(A.EmailID COLLATE Latin1_general_ci_ai AS VARCHAR(500))                                        
            NOT IN (SELECT CAST(                                        
                  ISNULL(Fs.[value], 'test') COLLATE                                        
                               Latin1_general_ci_ai AS                                        
                               VARCHAR(500)                                 )                  
                    FROM   #temptemplate AS Ucm2  (nolock)                                      
                         OUTER APPLY Dbo.Fn_split(Ucm2.ExclusionsNumber, ',') AS Fs                                        
                    WHERE  Ucm2.ID = A.CampaignID                                                                          
                  AND A.ParentID = Ucm2.ParentID)                        
                                        
UPDATE A                            
SET step1=1,step1datetime=getdate(),step1recipients = B.cnt                  
FROM [dbo].UserCampaignHistory A INNER JOIN  #tempcount B                           
/*(SELECT a.campaignid as campaignid, A.Jobid,isnull(count(e.CampaignID),0) AS [RecipientsCount]                            
         FROM UserCampaignHistory A (nolock)   
    left outer join [dbo].[EmailsfiltercampaignexecutionTEST2] e (nolock) on e.CampaignID=a.CampaignID   
    Where A.Jobid = @jobId  
         group by a.campaignid  , A.Jobid                          
 ) B*/                            
ON A.[campaignid] = B.[campaignid] and A.Jobid = @JobId  
  
  
                                             
     ---------------------------------Send Notification mail --------------------                                        
     INSERT INTO Getbatchrecord                                        
       (                                        
         [User_id],                                        
         RandNum                                        
       )                                        
     SELECT  TC.ParentID,                         
            TC.CampaignID                                        
     FROM    #tempCount TC   
    -- WHERE  TM.ValidEntries = 1     
      
 Select BatchID,[User_id] ParentID,RandNum CampaignID into #Batch from Getbatchrecord Gbr                                   
 Order by gbr.BatchID  
                                             
     DELETE Kd                                        
     FROM   Getbatchrecord Kd       
     Inner join    #Batch B on B.BatchId = Kd.BatchID                                
                                                  
     INSERT INTO Batchemail_infos                                        
       (                                        
         -- ID -- this column value is auto-generated                                        
         BatchID,                                        
         UserID,                                        
         SenderName,                                        
         [Message],                                        
       TotalRecords,                                        
         TotalProcessed,                                        
         ProcessTable,                                        
         IsProcess,                                        
         Priority_Level,                                        
         BatchInsertTime,                                        
         BatchProcessTime,           
         ScheduledDate,                                        
         ScheduledTime,                                        
         TemplateID,                                        
         [Route],                                        
         PageName,                                        
         IsScheduled,                                        
         Email_Subject,                        
         ReplyTo,                                        
         Amount,                                        
         Currency                                        
       )                                        
     SELECT B.BatchId,                                        
            335,                                 
            Ucm.NotificationMail,                                        
            case when tm.validentries=1 then 'Hold tight ! Your campaign "'                                        
            + Ucm.CampaignName + '" scheduled for '                                        
            + CAST(GETDATE() AS VARCHAR(50))          +                                        
            ' is executing. We shall further notify you when the execution completes' else 'Oops, you don''t have sufficient mail credits to run your mail campaign "'  
             + Ucm.CampaignName + '" scheduled for '                                  
             + Cast(Getdate() AS VARCHAR(50))                                  
             + '. Pl refill your credit balance & rerun the campaign ' end,                                        
            1,                                        
            0,                                        
          0,                                        
            0,                                        
            1,                                        
            GETDATE(),                                        
            GETDATE(),                                        
            GETDATE(),                                        
          GETDATE(),                                        
            0,                                        
            0,                                        
            0,                                        
            0,                                        
            case when tm.ValidEntries=1 then 'Campaign execution alert' else 'Failure: Your campaign "' +ucm.CampaignName + '" failed due to insufficient credits' end,                                        
            'contactus@kit19.com',                                        
            0,                                        
            0                                 
            FROM   #tempcount Tt                                 
            INNER JOIN Usercampaignmaster AS Ucm   (nolock)                                     
                 ON  Ucm.ID = Tt.CampaignID                         
                 AND Ucm.ParentID = Tt.ParentID                                        
                 AND Ucm.IsActive = 1                                        
                 inner join #tempMobile tm on tm.CampaignID=tt.CampaignID   
                 Inner join #Batch B on B.CampaignId = Tt.CampaignId  
     /*WHERE  EmailID <> ''                                        
       GROUP BY                                        
            Ucm.NotificationMail,                                        
            Ucm.MailReplyTo,                                        
            Ucm.CampaignName*/                             
     create table #output (GUID nvarchar(100) collate SQL_Latin1_General_CP1_CI_AS ,Email nvarchar(200) collate SQL_Latin1_General_CP1_CI_AS,Batchid bigint)      
                                        
     INSERT INTO Clientemails                                        
       (                                        
         -- Id -- this column value is auto-generated                                        
         GUID,                                        
         Email_Id,                                        
         SentDateTime,                                        
         UserId,                                        
         ReplyTo,                                        
         [Status],                                        
         BatchID,                                        
         [Message]                                        
       )       
       output inserted.GUID,inserted.Email_Id,inserted.BatchID into #output                  
     SELECT NEWID(),                                        
            Ucm.NotificationMail,                                        
            GETDATE(),                                        
            335,                                        
            'contactus@kit19.com',                                        
            '',                                        
            B.BatchId,                              
            case when tm.validentries=1 then 'Hold tight ! Your campaign "'                                        
         + Ucm.CampaignName + '" scheduled for '                                        
            + CAST(GETDATE() AS VARCHAR(50))                +                                        
            ' is executing. We shall further notify you when the execution completes' else 'Oops, you don''t have sufficient mail credits to run your mail campaign "'  
             + Ucm.CampaignName + '" scheduled for '                                  
             + Cast(Getdate() AS VARCHAR(50))                                  
             + '. Pl refill your credit balance & rerun the campaign ' end                                        
     FROM   #tempcount Tt                                        
     INNER JOIN Usercampaignmaster AS Ucm   (nolock)                                     
                 ON  Ucm.ID = Tt.CampaignID                                        
                 AND Ucm.ParentID = Tt.ParentID                     
                 AND Ucm.IsActive = 1                                       
                 inner join #tempMobile tm on tm.CampaignID=tt.CampaignID    
                 Inner join #Batch B on B.CampaignID = Tt.CampaignID  
     /*WHERE  EmailID <> ''                                        
     GROUP BY                                        
            Ucm.NotificationMail,                                        
            Ucm.MailReplyTo,                                        
            Ucm.CampaignName*/                        
                                             
     INSERT INTO Emailsfilter                                        
       (                                        
         Mail_GUID,                                        
         -- Mail_ID -- this column value is auto-generated                                        
         Mail_FromEmail,                                        
         Mail_ToEmail,                                        
         Mail_Subject,                                        
         Mail_TempleteName,                                        
         Messages,                                        
         Mail_InsertedDate,                                        
         Mail_UserID,                                        
         ReplyTo,                                        
         Mail_BatchID,                                        
         Mail_Priority,                      
         Mail_ScheduleDate,                                        
         Mail_Attechement,                                        
         Mail_TempleteBody,                                        
         IsMonitor                                        
       )                                        
     SELECT o.guid,                                        
            'contactus@email19.in',                                        
            ucm.NotificationMail,                                        
            'Campaign execution alert',                                        
            '',                                        
            case when tm.validentries=1 then 'Hold tight ! Your campaign "'                                        
            + Ucm.CampaignName + '" scheduled for '                                        
            + CAST(GETDATE() AS VARCHAR(50))                +                                        
            ' is executing. We shall further notify you when the execution completes' else 'Oops, you don''t have sufficient mail credits to run your mail campaign "'  
             + Ucm.CampaignName + '" scheduled for '                                  
             + Cast(Getdate() AS VARCHAR(50))                                  
             + '. Pl refill your credit balance & rerun the campaign ' end,                              
            GETDATE(),                                        
            335,                                        
            'contactus@kit19.com',                                        
            B.BatchId,                                        
            1,                                        
            GETDATE(),                                        
            0,                                   
            '',                                        
            1                
     FROM   #tempcount Tt                                        
                       INNER JOIN Usercampaignmaster AS Ucm  (nolock)                                      
                            ON  Ucm.ID = Tt.CampaignID                                        
                            AND Ucm.ParentID = Tt.ParentID                                        
                            AND Ucm.IsActive = 1   
                            inner join #tempMobile tm on tm.CampaignID=tt.CampaignID                                       
                            Inner join #Batch B on B.CampaignID = Tt.CampaignID  
                            inner join #output o on o.Email=ucm.NotificationMail  
                            where o.Batchid=B.BatchID  
               /* WHERE  EmailID <> ''                                        
                GROUP BY                                        
                       Ucm.NotificationMail,                                        
                       Ucm.CampaignName,                                        
                       Ucm.MailReplyTo                                        
            ) A */                                       
                                                  
      --      update EmailsFilter set EmailsFilter.Mail_Priority=2                                      
      --from   EmailsFilter inner join CustomerEmail on  EmailsFilter.Mail_ToEmail=CustomerEmail.Email                                                      
                                             
     INSERT INTO Mailcreditdetails                                        
       (                                        
         ID,                                        
         -- Credit_ID -- this column value is auto-generated                                        
         M_ID,                                        
      FromUser_ID,                                        
      [User_ID],                                        
         Debits,                                        
         Credits,                                        
         Balance,                                        
         Validity,                                        
         Default_Credit,                                        
         FromDate,             
         ToDate,                                        
         DateCreated,                                        
         DateUpdated,                                        
         EmpUpdated,                                        
         MachineName,                                        
         LastModified,                                        
         typecredit                                        
       )                                        
     SELECT NEWID(),                                        
            10001,                                        
            335,                                        
            335,                                        
            COUNT(*),                                        
            0,                                        
            (                                        
                SELECT TOP 1 Mcd.Balance                                        
                FROM   Mailcreditdetails AS Mcd  (nolock)                                      
                WHERE  Mcd.[User_ID] = 335                                        
                ORDER BY                                        
                       Mcd.Credit_ID DESC                                        
            ) - COUNT(*),                                        
            99999,       
            0,                                        
            GETDATE(),                                        
            GETDATE(),                                        
            GETDATE(),                                        
            GETDATE(),                                        
            'Campaign Exec',                                        
            '',                                        
            GETDATE(),                                        
0                                        
     FROM   #tempcount Tt                                        
                       INNER JOIN Usercampaignmaster AS Ucm   (nolock)                                     
                      ON  Ucm.ID = Tt.CampaignID                                        
                            AND Ucm.ParentID = Tt.ParentID                                        
                            AND Ucm.IsActive = 1    
                            --inner join #tempMobile tm on tm.CampaignID=tt.CampaignID                                      
               /* WHERE  EmailID <> ''                                        
                GROUP BY                                        
                       Ucm.NotificationMail,                                        
                       Ucm.CampaignName,                                        
    Ucm.MailReplyTo                                        
            ) A  */                                      
                                             
     ---------------------------------Send Notification Mail End ----------------    
   
 ---Update the next schedule for campaign      
select campaignid into #FindCampaignsNextExecution from #temptemplate t join UserCampaignMaster ucm on t.CampaignID=ucm.id      
    where ucm.IsActive=1 and ucm.IsSchedule=1 and ucm.IsScheduled=1      
          
 declare @count1 int =isnull((select COUNT(1) from #FindCampaignsNextExecution),0)      
 if @count1>0      
 begin      
    create table #nextexec1(campaignid bigint,nextexecution datetime)                  
    WHILE @Count1 > 0                      
  BEGIN                      
   DECLARE @Campaignid1 BIGINT = (                      
       SELECT TOP 1 campaignid                      
    FROM   #FindCampaignsNextExecution                      
      )          
     
   INSERT INTO #nextexec1                      
       (                      
      campaignid,                      
      nextexecution                      
       )                      
    EXEC Usp_getnextscheduledate                  
       @Campaignid1                      
      
    DELETE                       
    FROM   #FindCampaignsNextExecution                      
    WHERE  campaignid = @Campaignid1                      
      
    SET @Count1 = @Count1 - 1        
  END      
   update u set NextExecuteDateTime= nextexecution from usercampaignmaster u join #nextexec1 n on n.campaignid=u.id      
   where u.ExpiryDate > nextexecution or u.ExpiryDate is null      
    drop table #nextexec1      
    drop table #FindCampaignsNextExecution     
      
 end   
 -----Next schedule time updated---  
       
     drop table #Batch  
     drop table #output  
                                           
     DROP TABLE #tempemailid                                        
                                          
     DROP TABLE #temptablesearchapp                                        
                                             
     DROP TABLE #temptablesearchexc   
  drop table #tempCount  
  drop table #TempTableRunningTotal  
  drop table #tempMobile     
  DROP TABLE #temptemplate                                          
  drop table #temptablesearchContacts  
  drop table #temptablesearchExcContacts   
 ENd                                       
                                         
  update UserCampaignExecution                                      
    set CampaignExecutedDatetime=@CampaignStarttime,isevent=0              
                where issms=0 and isnull(isevent,0)=0          
    
  UPDATE A                              
  SET step1=1,step1datetime=getdate()  
  FROM [dbo].UserCampaignHistory A where A.Jobid = @JobId   
    
  exec Usp_userexecutecampaignmessagesmailsnewCorrected_segregatemail @jobid  
end  
  else  
  begin  
  if (select Lasterrorreported from UserCampaignExecution where issms=0 and isnull(isevent,0)=0) is null or (DATEDIFF(mi,(select isnull(Lasterrorreported,dateadd(mi,-6,getdate())) from UserCampaignExecution where issms=0 and isnull(isevent,0)=0),getdate()
)>5  and DATEDIFF(mi,(select isnull(CampaignExecutedDatetime,dateadd(mi,-6,getdate())) from UserCampaignExecution where issms=0 and isnull(isevent,0)=0),getdate()
)>5) 
  begin  
  declare @campaignstart datetime =(select CampaignExecutedDatetime from UserCampaignExecution where issms=0 and isnull(isevent,0)=0), @lastjobid bigint =(select top 1 jobid from usercampaignhistory (nolock) where issms=0 and iseventbased=0 and campaignid<>0 and jobid<>@jobid order by ID desc)  
  declare @step int = (select top 1 case when step2datetime is null then 2 else 3 end from usercampaignhistory (nolock) where jobid=@lastjobid)  
  declare @error nvarchar(200)='Last Campaign with jobid ' + cast(@lastjobid as varchar(10)) + ' failed at step ' + cast(@step as varchar) + ' running since ' + cast(@campaignstart as nvarchar(20))  
  exec usp_InsertCampaignError'Mail',0,@error  
  update UserCampaignExecution set Lasterrorreported=GETDATE() where issms=0 and isnull(isevent,0)=0  
  end  
  end  
  
END   
  


GO

/* ============================================================
   Procedure: [dbo].[Usp_executerecipientsusercampaignmailsCorrected_withcampaignmessage]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

                                         
CREATE   PROCEDURE [dbo].[Usp_executerecipientsusercampaignmailsCorrected_withcampaignmessage]   
AS                                        
BEGIN   
 DECLARE @Body VARCHAR(500)                                        
                                      
 DECLARE @LastExecutedTime datetime =isnull((select Top 1 CampaignExecutedDatetime from UserCampaignExecution where issms=0 and isnull(isevent,0)=0 order by id desc),getdate())    
 DEclare @JobId Bigint = (Select ISNULL(MAX(JobId),0)+1 from UserCampaignHistory UCH )
 declare @campaignstartdate datetime=getdate()
    INSERT INTO Usercampaignhistory                                        
   (                                        
     -- ID -- this column value is auto-generated                                        
     CampaignID,                                        
     ParentID,                                        
     Step1,                                        
     Step2,                                    
     Step3,                                        
     IsSMS,                                        
     IsMail,                                        
     IsScheduled,                                        
     IsEventBased,                                        
     CreatedOn,  
     JobId                                    
   )                          
 SELECT 0,                                        
    0,                                        
        0,            
        0,                                        
        0,                                        
        0,                                        
        1,                                        
        1,                                        
        0,                                        
        @campaignstartdate,  
        @JobId
   
 --select @jobid  
 if exists(select 1 from UserCampaignExecution where issms=0 and isnull(isevent,0)=0 and isrunning=0)  
 begin  
 update UserCampaignExecution set isrunning=1 where issms=0 and isnull(isevent,0)=0
 Declare @CampaignStarttime datetime = Getdate()    
 if OBJECT_ID('tempdb..#temptemplate') is not null                
 Begin   
 Drop table #temptemplate   
 end        
       
 SELECT    ROW_NUMBER()Over(Order by Ucm.ID,Ucm.ParentID) AS Id,     
     Ucm.ID      AS CampaignID,                                        
                   Ucm.ParentID,                                        
                   A.[value]  AS Applicabilty,                                        
                   AGL.[value]         AS ApplicabiltyGroupList,                                        
                   EGL.[value]        AS ExclusionsGroupList,                                        
                   Ucm.NotificationMail,                                        
                   Ucm.ExclusionsNumber,                                        
                   E.[value]           AS Exclusions,                                        
                   Ucm.InclusionsNumber,                                        
                   Ucm.AccountUsed,                                        
                   Ucm.SenderID,                                        
                   Ucm.[Message],                                        
                   Ucm.TemplateID,                                        
                   Ucm.TemplateGroupID,                                        
                   Ucm.IsUnicode                    INTO #temptemplate                                                                   FROM   Usercampaignmaster Ucm   (nolock)  
   Inner join  User_detail AS Ud  on Ud.[User_ID]  = AccountUsed and Ud.[Status] <> 0                                            OUTER APPLY Dbo.Fn_split(Ucm.Applicabilty, '#') AS A   
   OUTER APPLY Dbo.Fn_split(Ucm.ApplicabiltyGroupList, '#') AS AGL  
   OUTER APPLY Dbo.Fn_split(Ucm.ExclusionsGroupList, '#') AS  EGL   
   OUTER APPLY Dbo.Fn_split(Ucm.Exclusions, '#') AS E                                        
            WHERE Ucm.MailReplyTo <> ''  and isscheduled=1                                      
                   /*AND convert(varchar(20),Ucm.NextExecuteDateTime,100) between   
                   convert(varchar(20),@LastExecutedTime,100) and    
                   convert(varchar(20), GETDATE(), 100) */  
                   AND Ucm.NextExecuteDateTime between   
                   @LastExecutedTime and    
                  GETDATE()                              
                   AND DATEDIFF(                                        
                           Minute,                                        
                           getdate(),                                        
                           CASE                                         
                                WHEN Ucm.IsNeverExpire = 1 THEN DATEADD(DAY, 1,getdate())                                        
                                ELSE ISNULL(Ucm.ExpiryDate, getdate())                                        
                       END                                        
                       ) > 0                                        
                   AND DATEDIFF(Minute, getdate(), ISNULL(Ucm.StartDate, getdate()))  <= 0                                        
                   AND Ucm.IsActive = 1                                        
     
   --select * from #temptemplate  
                                   
   INSERT INTO Usercampaignhistory                                        
   (                                        
     -- ID -- this column value is auto-generated                                        
     CampaignID,                                        
     ParentID,                                        
     Step1,                                        
     Step2,                                    
     Step3,                                        
     IsSMS,                                        
     IsMail,                                        
     IsScheduled,                                        
     IsEventBased,                                        
     CreatedOn,  
     JobId                                    
   )                          
 SELECT DISTINCT CampaignID,                                        
    ParentID,                                        
        0,            
        0,                                        
        0,                                        
        0,                                        
        1,                                        
        1,                                        
        0,                                        
        @campaignstartdate,  
        @JobId                                        
 FROM   #temptemplate     
                       
 IF NOT EXISTS (                                        
        SELECT 'x'                                        
        FROM   #temptemplate   
        )                                        
 BEGIN    
     SET @Body = 'No Campaign Found'                                        
     SELECT @Body                                        
     INSERT INTO Usercampaignhistory                                        
   (                                        
     -- ID -- this column value is auto-generated                                        
     CampaignID,                                        
     ParentID,                                        
     Step1,                                        
     Step2,                                    
     Step3,                                        
     IsSMS,                                        
     IsMail,                                        
     IsScheduled,                                        
     IsEventBased,                                        
     CreatedOn,  
     JobId                                    
   )                          
 SELECT 0,                                        
        0,                                        
        0,            
        0,                                        
        0,                                        
        0,                                        
        1,                                        
        1,                                        
        0,                                        
        GETDATE(),  
        @JobId  
--select 2  
END     
--select * from #temptemplate  
 ELSE                                        
 BEGIn                                                       
     CREATE TABLE #temptablesearchapp                                        
     (                                        
      CampaignID             BIGINT,                                        
      SearchID               BIGINT,                                        
      ParentID               BIGINT,  
      UserId                 bigint,                                       
      PersonName             NVARCHAR(200),                          
      CompanyName            NVARCHAR(200),                                        
      MobileNo               NVARCHAR(200),                                        
      MobileNo1              NVARCHAR(200),                                        
      MobileNo2              NVARCHAR(200),                 
      EmailID                NVARCHAR(200),                                        
      EmailID1               NVARCHAR(200),                                        
      EmailID2               NVARCHAR(200),                                        
      City        NVARCHAR(200),                                        
      STATE                  NVARCHAR(200),                                        
   Country                NVARCHAR(200),                                        
      CountryCode            NVARCHAR(200),                                        
    PinCode                NVARCHAR(200),                                        
      ResidentialAddress     NVARCHAR(200),                                        
      OfficeAddress          NVARCHAR(200),                                        
      SourceName             NVARCHAR(200),                                        
      MediumName             NVARCHAR(200),                                        
      CampaignName           NVARCHAR(200),                                        
      InitialRemarks         NVARCHAR(1000) )  
      --For searces from contacts,uncomment below code  
