          INSERT INTO #temptablesearchapp(EmailID,CampaignID,ParentID,userid)    
          select Contact_Email,CampaignID,ParentID,userid from #temptablesearchContacts  
           INSERT INTO #temptablesearchexc(EmailID,CampaignID,ParentID,userid)    
          select Contact_Email,CampaignID,ParentID,userid from #temptablesearchExcContacts  
                                                                                            
     SELECT A.EmailID,                                        
            A.ParentID,                                        
            A.CampaignID,  
            A.userid,A.templateid                                        
            INTO     #tempemailid                                        
     FROM   (                                        
                SELECT Tt2.EmailID,                                        
                       Tt2.ParentID,                                        
                       Tt2.CampaignID,  
                       tt.Accountused as userid,tt.templateid    
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                                        
                WHERE  Tt2.EmailID is not null and NOT EXISTS (SELECT 1 FROM   #temptablesearchexc Tt   
       Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.EmailID = Tt.EmailID OR Tt2.EmailID = Tt.EmailID1 OR Tt2.EmailID = Tt.EmailID2 ) )                        UNION                                        
                SELECT Tt2.EmailID1,                                        
                       Tt2.ParentID,                    
           Tt2.CampaignID,tt.Accountused  as userid,tt.templateid                                       
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                  
                 WHERE Tt2.EmailID1 is not null and  NOT EXISTS (SELECT 1                                        
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.EmailID1 = Tt.EmailID OR Tt2.EmailID1 = Tt.EmailID1 OR  Tt2.EmailID1 = Tt.EmailID2)  )     
                UNION                                        
                SELECT Tt2.EmailID2,                                        
                       Tt2.ParentID,                                        
                       Tt2.CampaignID,tt.Accountused as userid,tt.templateid                                        
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                                        
                 WHERE  Tt2.EmailID2 is not null and  NOT EXISTS (SELECT 1                                        
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND (Tt2.EmailID2 = Tt.EmailID OR Tt2.EmailID2 = Tt.EmailID1 OR  Tt2.EmailID2= Tt.EmailID2 ) )     
           
       )        A                                        
                       
    SELECT   
     ROW_NUMBER() Over(order by CampaignId,ParentId) Id,  
     Ucerm.CampaignID,     
     Ucerm.ParentID                               ,  
                     -- Cast(Ucerm.Messages AS VARCHAR(MAX))  AS  Messages,                                  
                     ucerm.userID,                                
                     Count(*) cnt  
                     -- Ucerm.Mail_ToEmail,                                  
   INTO   #tempCount                                  
      FROM   #tempemailid Ucerm where ucerm.EmailID is not null                                 
      Group by  Ucerm.CampaignID,     
     Ucerm.ParentID ,                                  
                      Ucerm.UserID  
                                                    
        
      SELECT A.UserID,a.CampaignID, a.cnt,SUM(b.cnt) RunningTotal into #TempTableRunningTotal  
   FROM   #tempCount a join  
       #tempCount b  on a.userid=b.userid
   WHERE b.CampaignID <= a.CampaignID  
   GROUP BY A.UserID, a.CampaignID, a.cnt  
   ORDER BY a.CampaignID;  
        
   --- Calculate credits                                  
      SELECT B.UserID,   
    B.CampaignID,  
      CASE                                  
               WHEN B.Balance >= B.Credits THEN 1                                  
               ELSE 0  -- Test                                  
             END AS ValidEntries                                  
      INTO   #tempMobile                                  
      FROM   (SELECT A.UserID,    
      A.CampaignID,                                
                     (A.Credits)   AS Credits,  --Runningtotal                                
                     A.Balance                                  
              FROM   (SELECT Tt.UserID,                                  
                             TT.RunningTotal AS Credits,  
                             TT.CampaignID,                                  
                            -- Tt.Mail_ToEmail,                                  
                             (SELECT TOP 1 Balance                                  
                              FROM   Mailcreditdetails AS Mcd                                  
                              WHERE  Mcd.[User_ID] = Tt.UserID                                  
                              ORDER  BY Credit_ID DESC)     AS Balance                                  
                      FROM   #TempTableRunningTotal Tt) A                                  
              GROUP  BY A.UserID,                                  
                        A.Balance,A.CampaignID,A.credits) B  
                                             
     INSERT INTO Usercampaignexecutionhistory                                        
       (                                        
         CampaignID,                                        
         Jobid,  
         ExecutionTime,                                        
         IsRecipients,                                        
         ParentID  
           
       )                                        
     SELECT DISTINCT A.CampaignID,                                        
            @JobId,  
            GETDATE(),                                        
            1,                                        
            A.ParentID                                        
     FROM   (                                        
               SELECT  
      TT.ParentID,  
      TT.CampaignID  
                from #tempcount TT join #tempMobile tm on tm.CampaignID=tt.CampaignID  
                where tm.ValidEntries=1                                                 
            ) A     
                                     
       
     --delete te from #tempemailid te join #tempmobile tm on te.campaignid=tm.campaignid where tm.validentries=0                                       
     INSERT INTO EmailsfiltercampaignexecutionTEST2                                        
       (                                        
         Mail_FromEmail,                                        
         Mail_GUID,                                        
         Mail_ToEmail,               
         Mail_InsertedDate,                                        
         ParentID,                                        
         CampaignID,                                        
   Mail_UserID,  
            JobId,templateid                                          
       )                                        
     SELECT '',                                        
            NEWID(),                                        
            A.EmailID,                                        
            GETDATE(),                                        
            A.ParentID,                                        
            A.CampaignID,                                        
            0,  
            @JobId,templateid                                          
     FROM   (SELECT CAST(Tt.EmailID COLLATE Latin1_general_ci_ai AS VARCHAR(500)) AS EmailID,                                        
   Tt.ParentID,                                        
                 Tt.CampaignID ,  
            @JobId Jobid ,templateid                                        
                FROM   #tempemailid Tt                                        
                WHERE  Tt.EmailID <> '' and tt.EmailID is not null                                       
                UNION                                        
                SELECT CAST(Fs.[value] COLLATE Latin1_general_ci_ai AS VARCHAR(500)),                                        
                       tt.ParentID,                                        
                       tt.CampaignID,  
            @JobId  Jobid ,templateid                                       
                FROM   #temptemplate AS tt  (nolock)                                      
                       OUTER APPLY Dbo.Fn_split(tt.InclusionsNumber, ',') AS Fs  where  fs.value is not null  and fs.value<>''                                     
     ) A  
     Inner join #tempMobile TM on TM.CampaignID = A.CampaignID                                        
     WHERE  TM.ValidEntries = 1 and  
      CAST(A.EmailID COLLATE Latin1_general_ci_ai AS VARCHAR(500))                                        
            NOT IN (SELECT CAST(                                        
                  ISNULL(Fs.[value], 'test') COLLATE                                        
                               Latin1_general_ci_ai AS                                        
                               VARCHAR(500)                                 )                  
                    FROM   #temptemplate AS Ucm2  (nolock)                                      
                         OUTER APPLY Dbo.Fn_split(Ucm2.ExclusionsNumber, ',') AS Fs                                        
                    WHERE  Ucm2.ID = A.CampaignID                                                                          
                  AND A.ParentID = Ucm2.ParentID)                        
                                        
UPDATE A                            
SET step1=1,step1datetime=getdate(),step1recipients = B.cnt                  
