     SELECT o.guid,                                          
            'contactus@email19.in',                                          
            ucm.NotificationMail,                                          
            case when tm.ValidEntries=1 then 'Campaign execution alert' else 'Failure: Your campaign "' +ucm.CampaignName + '" failed due to insufficient credits' end,                                          
            '',                                          
