     Step3,                                          
     IsSMS,                                          
     IsMail,                                          
     IsScheduled,                          
     IsEventBased,                                          
     CreatedOn,    
     JobId                                      
   )                            
 SELECT 0,                                          
        0,                                          
        0,              
        0,                                          
        0,                                          
        0,                                          
        1,                                          
        1,                                          
        0,                                          
        GETDATE(),    
        @JobId    
--select 2    
END       
--select * from #temptemplate    
 ELSE                                          
 BEGIn                                                         
