          INSERT INTO #temptablesearchapp(Entityname,Entityid,EmailID,CampaignID,ParentID,userid)      
          select Entityname,Contact_ID,Contact_Email,CampaignID,ParentID,userid from #temptablesearchContacts    
           INSERT INTO #temptablesearchexc(Entityname,Entityid,EmailID,CampaignID,ParentID,userid)      
          select Entityname,Contact_ID,Contact_Email,CampaignID,ParentID,userid from #temptablesearchExcContacts    
                                                                                              
     SELECT Entityname,Entityid,A.EmailID,                                          
            A.ParentID,                                          
            A.CampaignID,    
            A.userid,
			A.templateid                                          
            INTO     #tempemailid                                          
     FROM   (                                          
                SELECT Entityname,Entityid,Tt2.EmailID,                                          
                       Tt2.ParentID,                                          
                       Tt2.CampaignID,    
                       tt.Accountused as userid,tt.TemplateID      
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                                          
                WHERE  nullif(Tt2.EmailID,'') is not null and NOT EXISTS (SELECT 1 FROM   #temptablesearchexc Tt     
       Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.EmailID = Tt.EmailID OR Tt2.EmailID = Tt.EmailID1 OR Tt2.EmailID = Tt.EmailID2 )
	   )                        UNION                                          
                SELECT Entityname,Entityid,Tt2.EmailID1,                                          
                       Tt2.ParentID,                      
           Tt2.CampaignID,tt.Accountused  as userid,tt.TemplateID                                         
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                    
                 WHERE nullif(Tt2.EmailID1,'') is not null and  NOT EXISTS (SELECT 1                                          
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.EmailID1 = Tt.EmailID OR Tt2.EmailID1 = Tt.EmailID1 OR  Tt2.EmailID1 = Tt.EmailID2)  )       
                UNION                                          
                SELECT Entityname,Entityid,Tt2.EmailID2,                                          
                       Tt2.ParentID,                                          
                       Tt2.CampaignID,tt.Accountused as userid,tt.TemplateID                                          
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                                          
                 WHERE  nullif(Tt2.EmailID2,'') is not null and  NOT EXISTS (SELECT 1                                          
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND (Tt2.EmailID2 = Tt.EmailID OR Tt2.EmailID2 = Tt.EmailID1 OR  Tt2.EmailID2= Tt.EmailID2 ) )       
             
       )        A                                          
                         
    SELECT     
     ROW_NUMBER() Over(order by CampaignId,ParentId) Id,    
     Ucerm.CampaignID,       
     Ucerm.ParentID                               ,    
                     -- Cast(Ucerm.Messages AS VARCHAR(MAX))  AS  Messages,                                    
                     ucerm.userID,                                  
                     Count(*) cnt    
                     -- Ucerm.Mail_ToEmail,                                    
   INTO   #tempCount                                    
      FROM   #tempemailid Ucerm where ucerm.EmailID is not null                                   
      Group by  Ucerm.CampaignID,       
     Ucerm.ParentID ,                                    
                      Ucerm.UserID    
                                                      
          
      SELECT A.UserID,a.CampaignID, a.cnt,SUM(b.cnt) RunningTotal into #TempTableRunningTotal    
   FROM   #tempCount a join    
       #tempCount b  on a.userid=b.userid  
   WHERE b.CampaignID <= a.CampaignID    
   GROUP BY A.UserID, a.CampaignID, a.cnt    
   ORDER BY a.CampaignID;    
          
   --- Calculate credits                                    
      SELECT B.UserID,     
    B.CampaignID,    
      CASE                                    
               WHEN B.Balance >= B.Credits THEN 1                                    
               ELSE 0  -- Test                                    
             END AS ValidEntries                                    
      INTO   #tempMobile                                    
      FROM   (SELECT A.UserID,      
      A.CampaignID,                                  
                     (A.Credits)   AS Credits,  --Runningtotal                                  
                     A.Balance                                    
              FROM   (SELECT Tt.UserID,                                    
                             TT.RunningTotal AS Credits,    
                             TT.CampaignID,                                    
                            -- Tt.Mail_ToEmail,                                    
                             (SELECT TOP 1 Balance                                    
                              FROM   Mailcreditdetails AS Mcd                                    
                              WHERE  Mcd.[User_ID] = Tt.UserID                                    
                              ORDER  BY Credit_ID DESC)     AS Balance                                    
                      FROM   #TempTableRunningTotal Tt) A                                    
              GROUP  BY A.UserID,                                    
                        A.Balance,A.CampaignID,A.credits) B  
                          
update u set u.ReasonIfNotRun='Insuffcient Balance' from UserCampaignHistory u join #tempMobile t  
on u.campaignid=t.CampaignID and u.jobid=@jobid where t.validentries=0    
                                               
     INSERT INTO Usercampaignexecutionhistory                                          
       (                                          
         CampaignID,                                          
         Jobid,    
         ExecutionTime,                                          
         IsRecipients,                                          
         ParentID    
             
       )                                          
     SELECT DISTINCT A.CampaignID,                                          
            @JobId,    
            GETDATE(),                                          
            1,                                          
            A.ParentID                                          
     FROM   (                                          
               SELECT    
      TT.ParentID,    
      TT.CampaignID    
                from #tempcount TT join #tempMobile tm on tm.CampaignID=tt.CampaignID    
                where tm.ValidEntries=1                                                   
            ) A       
                                       
         
