       )    
	   
     select Entityname,Entityid,Mail_FromEmail,                                          
            NEWID() as MG,                                          
            A.EmailID,                                          
            MID,                                          
            A.ParentID,                                          
            A.CampaignID,                                          
            MUID,    
            Jobid,TemplateID                                            
     FROM 
	 (
     SELECT distinct Entityname,Entityid,'' Mail_FromEmail,                                          
            A.EmailID,                                          
            GETDATE() MID,                                          
            A.ParentID,                                          
            A.CampaignID,                                          
            0 MUID,    
            @JobId Jobid,TemplateID                                            
     FROM   
	 (SELECT Entityname,Entityid,CAST(Tt.EmailID COLLATE Latin1_general_ci_ai AS VARCHAR(500)) AS EmailID,                                          
   Tt.ParentID,                                          
                 Tt.CampaignID ,    
            @JobId Jobid,tt.TemplateID                                           
                FROM   #tempemailid Tt                                          
                WHERE  Tt.EmailID <> '' and tt.EmailID is not null                                         
                UNION                                          
                SELECT 'Explicit',fs.position,CAST(Fs.[value] COLLATE Latin1_general_ci_ai AS VARCHAR(500)),                                          
                       tt.ParentID,                                          
                       tt.CampaignID,    
            @JobId  Jobid,tt.TemplateID                                          
                FROM   #temptemplate AS tt  (nolock)                                        
                       OUTER APPLY Dbo.Fn_split(tt.InclusionsNumber, ',') AS Fs  where  fs.value is not null  and fs.value<>''                                       
     ) A    
     Inner join #tempMobile TM on TM.CampaignID = A.CampaignID                                          
     WHERE  TM.ValidEntries = 1 and    
      CAST(A.EmailID COLLATE Latin1_general_ci_ai AS VARCHAR(500))                                          
            NOT IN (SELECT CAST(                                          
                  ISNULL(Fs.[value], 'test') COLLATE                                          
                               Latin1_general_ci_ai AS                                          
                               VARCHAR(500)                                 )                    
                    FROM   #temptemplate AS Ucm2  (nolock)                                        
                         OUTER APPLY Dbo.Fn_split(Ucm2.ExclusionsNumber, ',') AS Fs                                          
                    WHERE  Ucm2.ID = A.CampaignID                                                                            
                  AND A.ParentID = Ucm2.ParentID)                          
           ) A                               
