            + '. Pl refill your credit balance & rerun the campaign ' end,                                          
            1                  
     FROM   #tempcount Tt                                          
                       INNER JOIN Usercampaignmaster AS Ucm  (nolock)                                        
                            ON  Ucm.ID = Tt.CampaignID                                          
                            AND Ucm.ParentID = Tt.ParentID                                          
                            AND Ucm.IsActive = 1     
                            inner join #tempMobile tm on tm.CampaignID=tt.CampaignID                                         
                            Inner join #Batch B on B.CampaignID = Tt.CampaignID    
                            inner join #output o on o.Email=ucm.NotificationMail    
                            where o.Batchid=B.BatchID    
               /* WHERE  EmailID <> ''                                          
                GROUP BY                                          
                       Ucm.NotificationMail,                                          
                       Ucm.CampaignName,                                          
                       Ucm.MailReplyTo                                          
            ) A */                                         
                                                    
      --      update EmailsFilter set EmailsFilter.Mail_Priority=2                                        
      --from   EmailsFilter inner join CustomerEmail on  EmailsFilter.Mail_ToEmail=CustomerEmail.Email                                                        
                                               
     INSERT INTO Mailcreditdetails                                          
       (                                          
         ID,                                          
         -- Credit_ID -- this column value is auto-generated                                          
         M_ID,                                          
      FromUser_ID,                                          
      [User_ID],                                          
         Debits,                                          
         Credits,                                          
         Balance,                                          
         Validity,                                          
         Default_Credit,                                          
         FromDate,               
         ToDate,                                          
         DateCreated,                                          
         DateUpdated,                                          
         EmpUpdated,                                          
         MachineName,                                          
         LastModified,                                          
         typecredit                                          
       )                                          
     SELECT NEWID(),                                          
            10001,                                          
            335,                                          
            335,                                          
            COUNT(*),                                          
            0,                                          
            (                                          
                SELECT TOP 1 Mcd.Balance                                          
                FROM   Mailcreditdetails AS Mcd  (nolock)                                        
                WHERE  Mcd.[User_ID] = 335                                          
                ORDER BY                                          
                       Mcd.Credit_ID DESC                                          
            ) - COUNT(*),                                          
            99999,         
          0,                                          
            GETDATE(),                                          
            GETDATE(),                                          
            GETDATE(),                                          
            GETDATE(),                                          
            'Campaign Exec',                                          
            '',                                          
            GETDATE(),                                          
0                                          
     FROM   #tempcount Tt                                          
                       INNER JOIN Usercampaignmaster AS Ucm   (nolock)                                       
                      ON  Ucm.ID = Tt.CampaignID                                          
                            AND Ucm.ParentID = Tt.ParentID                                          
                            AND Ucm.IsActive = 1      
                            --inner join #tempMobile tm on tm.CampaignID=tt.CampaignID                                        
               /* WHERE  EmailID <> ''                                          
                GROUP BY                                          
                       Ucm.NotificationMail,                                          
                       Ucm.CampaignName,                                          
    Ucm.MailReplyTo                                          
            ) A  */                                        
                                               
     ---------------------------------Send Notification Mail End ----------------      
     
 ---Update the next schedule for campaign        
select campaignid into #FindCampaignsNextExecution from #temptemplate t join UserCampaignMaster ucm on t.CampaignID=ucm.id        
    where ucm.IsActive=1 and ucm.IsSchedule=1 and ucm.IsScheduled=1        
            
 declare @count1 int =isnull((select COUNT(1) from #FindCampaignsNextExecution),0)        
 if @count1>0        
 begin        
    create table #nextexec1(campaignid bigint,nextexecution datetime)                    
    WHILE @Count1 > 0                        
  BEGIN                        
   DECLARE @Campaignid1 BIGINT = (                        
       SELECT TOP 1 campaignid                        
    FROM   #FindCampaignsNextExecution                        
      )            
       
   INSERT INTO #nextexec1                        
       (                        
      campaignid,                        
      nextexecution                        
       )                        
    EXEC Usp_getnextscheduledate                    
       @Campaignid1                        
        
    DELETE                         
    FROM   #FindCampaignsNextExecution                        
    WHERE  campaignid = @Campaignid1                        
        
    SET @Count1 = @Count1 - 1          
  END        
   update u set NextExecuteDateTime= nextexecution from usercampaignmaster u join #nextexec1 n on n.campaignid=u.id        
   where u.ExpiryDate > nextexecution or u.ExpiryDate is null        
    drop table #nextexec1        
    drop table #FindCampaignsNextExecution       
        
 end     
 -----Next schedule time updated---    
         
     drop table #Batch    
     drop table #output    
                                             
     DROP TABLE #tempemailid                                          
                                            
     DROP TABLE #temptablesearchapp                                          
                                               
     DROP TABLE #temptablesearchexc     
  drop table #tempCount    
  drop table #TempTableRunningTotal    
  drop table #tempMobile       
  DROP TABLE #temptemplate                                            
  drop table #temptablesearchContacts    
  drop table #temptablesearchExcContacts     
 ENd                                         
  
   if @campid is null                                         
  update UserCampaignExecution                                        
    set CampaignExecutedDatetime=@CampaignStarttime,isevent=0                
                where issms=0 and isnull(isevent,0)=0            
      
  UPDATE A                                
  SET step1=1,step1datetime=getdate()    
  FROM [dbo].UserCampaignHistory A where A.Jobid = @JobId     
      
  exec Usp_userexecutecampaignmessagesmailsnewCorrected_segregatemail_withid21102020 @jobid    
end    
  else  if @campid is null and not exists(select 1 from UserCampaignExecution where issms=0 and isnull(isevent,0)=0 and isrunning=0)    
  begin    
  if (select Lasterrorreported from UserCampaignExecution where issms=0 and isnull(isevent,0)=0) is null or (DATEDIFF(mi,(select isnull(Lasterrorreported,dateadd(mi,-6,getdate())) from UserCampaignExecution where issms=0 and isnull(isevent,0)=0),getdate(
)  
)>5  and DATEDIFF(mi,(select isnull(CampaignExecutedDatetime,dateadd(mi,-6,getdate())) from UserCampaignExecution where issms=0 and isnull(isevent,0)=0),getdate()  
)>5)   
  begin    
  declare @campaignstart datetime =(select CampaignExecutedDatetime from UserCampaignExecution where issms=0 and isnull(isevent,0)=0),  
     @lastjobid bigint =(select isnull(cjobid,(select top 1 jobid from usercampaignhistory (nolock) where issms=0 and iseventbased=0 and campaignid<>0 and jobid<>@jobid order by ID desc))   
  from usercampaignexecution where issms=0 and isevent=0)  
   select top 1 @campaignstart = CreatedOn from usercampaignhistory(nolock) where jobid=@lastjobid  
       
  declare @step int = (select top 1 case when step2datetime is null then 2 else 3 end from usercampaignhistory (nolock) where jobid=@lastjobid)    
  declare @error nvarchar(200)='Last Campaign with jobid ' + cast(@lastjobid as varchar(10)) + ' failed at step ' + cast(@step as varchar) + ' running since ' + cast(@campaignstart as nvarchar(20))    
  exec usp_InsertCampaignError'Mail',0,@error  
    
  if @step=2  
  begin  
  exec Usp_userexecutecampaignmessagesmailsnewCorrected_segregatemail_withid21102020 @lastjobid  
  end  
  else if @step=3  
  begin  
  exec Usp_insertclonedeliverycampaignmailsCorrected_segregatemail_withid21102020 @lastjobid  
  end  
    
   update UserCampaignExecution set Lasterrorreported=GETDATE() where issms=0 and isnull(isevent,0)=0    
  end    
  end    
*/    
END     


GO

/* ============================================================
   Procedure: [dbo].[Usp_executerecipientsusercampaignmailsSelected]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

                                           
CREATE   PROCEDURE [dbo].[Usp_executerecipientsusercampaignmailsSelected]     
@campaignsToRun  nvarchar(max),@notification bit = null,@send bit=null                                       
AS                                          
BEGIN     
 --declare @campaignsToRun  nvarchar(max) ='497'                                       
 DECLARE @Body VARCHAR(500)  
 set @notification =coalesce(@notification,1)    
 set @send =coalesce(@send,1)                                          
                                           
 DECLARE @LastExecutedTime datetime =isnull((select Top 1 CampaignExecutedDatetime from UserCampaignExecution where issms=0 and isnull(isevent,0)=0 order by id desc),getdate())      
 DEclare @JobId Bigint = (Select ISNULL(MAX(JobId),0)+1 from UserCampaignHistory UCH )    
     
 Declare @CampaignStarttime datetime = Getdate()      
    
 if OBJECT_ID('tempdb..#temptemplate') is not null                  
 Begin     
 Drop table #temptemplate     
end          
         
 SELECT ROW_NUMBER()Over(Order by Ucm.ID,Ucm.ParentID) AS Id,       
     Ucm.ID      AS CampaignID,                                          
                   Ucm.ParentID,                                          
                   A.[value]  AS Applicabilty,                                          
                   AGL.[value]         AS ApplicabiltyGroupList,                                          
                   EGL.[value]        AS ExclusionsGroupList,                                          
                   Ucm.NotificationMail,                                          
                   Ucm.ExclusionsNumber,                                          
                   E.[value]           AS Exclusions,                                          
                   Ucm.InclusionsNumber,                                          
                   Ucm.AccountUsed,                                          
                   Ucm.SenderID,                                          
                   Ucm.[Message],                                          
                   Ucm.TemplateID,                                          
                   Ucm.TemplateGroupID,                                          
                   Ucm.IsUnicode                    INTO #temptemplate                                                                   FROM   Usercampaignmaster Ucm   (nolock)    
   Inner join  User_detail AS Ud  on Ud.[User_ID]  = AccountUsed and Ud.[Status] <> 0                                            OUTER APPLY Dbo.Fn_split(Ucm.Applicabilty, '#') AS A     
   OUTER APPLY Dbo.Fn_split(Ucm.ApplicabiltyGroupList, '#') AS AGL    
   OUTER APPLY Dbo.Fn_split(Ucm.ExclusionsGroupList, '#') AS  EGL     
   OUTER APPLY Dbo.Fn_split(Ucm.Exclusions, '#') AS E                                          
            WHERE Ucm.ID in (select value from dbo.fn_split(@campaignsToRun,','))     
            /*Ucm.MailReplyTo <> ''  and isscheduled=1                                        
                   AND Ucm.NextExecuteDateTime between @LastExecutedTime and  getdate()                                 
                   AND DATEDIFF(                                          
                           Minute,                                          
                           getdate(),                                          
                           CASE                                           
                                WHEN Ucm.IsNeverExpire = 1 THEN DATEADD(DAY, 1,getdate())                                          
                                ELSE ISNULL(Ucm.ExpiryDate, getdate())                                          
                       END                                          
                       ) > 0                                          
                   AND DATEDIFF(Minute, getdate(), ISNULL(Ucm.StartDate, getdate()))  <= 0                                          
AND Ucm.IsActive = 1  */                                        
                                     
   INSERT INTO Usercampaignhistory                                          
   (          
     -- ID -- this column value is auto-generated                                          
     CampaignID,                                          
     ParentID,                                          
     Step1,                                          
     Step2,                                      
     Step3,                                          
     IsSMS,                                          
     IsMail,                                          
     IsScheduled,                                          
     IsEventBased,                                          
     CreatedOn,    
     JobId                                      
   )                            
 SELECT DISTINCT CampaignID,                                          
    ParentID,                                          
        0,              
        0,                                          
        0,                                          
        0,                                          
        1,                                          
        1,                                          
        0,                                          
        GETDATE(),    
        @JobId                                          
 FROM   #temptemplate       
                         
 IF NOT EXISTS (                                          
        SELECT 'x'                                          
        FROM   #temptemplate                                          
    )                                          
 BEGIN                                          
     SET @Body = 'No Campaign Found'                                          
                                               
     SELECT @Body                                          
END       
--select * from #temptemplate    
 ELSE                                          
 BEGIN                                                          
     CREATE TABLE #temptablesearchapp                                          
     (                                          
      CampaignID             BIGINT,                                          
      SearchID               BIGINT,                                          
      ParentID               BIGINT,    
      UserId                 bigint,                                         
      PersonName             NVARCHAR(200),                            
      CompanyName            NVARCHAR(200),                                          
      MobileNo               NVARCHAR(200),                                          
      MobileNo1              NVARCHAR(200),                                          
      MobileNo2              NVARCHAR(200),                                          
      EmailID                NVARCHAR(200),                                          
      EmailID1               NVARCHAR(200),                                          
      EmailID2               NVARCHAR(200),                                          
      City        NVARCHAR(200),                                          
      STATE                  NVARCHAR(200),                                          
   Country                NVARCHAR(200),                                          
      CountryCode            NVARCHAR(200),                                          
    PinCode                NVARCHAR(200),                                          
      ResidentialAddress     NVARCHAR(200),                                          
      OfficeAddress          NVARCHAR(200),                                          
      SourceName             NVARCHAR(200),                                          
      MediumName             NVARCHAR(200),                                          
      CampaignName           NVARCHAR(200),                                          
      InitialRemarks         NVARCHAR(1000)     
      --For searces from contacts,uncomment below code    
     /* Create table #temptablesearchContacts    
        (Contact_ID             BIGINT,          
         Contact_Name           VARCHAR(150),          
         Contact_Mobile         VARCHAR(50),          
         Contact_Email          VARCHAR(50),          
         Contact_DOB            VARCHAR(50),          
         Contact_Anniversary    VARCHAR(50),          
         CompanyName            VARCHAR(100),          
         City                   VARCHAR(100),          
         STATE                  VARCHAR(100),          
         Country                VARCHAR(100),          
         ADDRESS                VARCHAR(200),          
         DateCreated            VARCHAR(50),    
         CampaignID             BIGINT,                                          
      SearchID               BIGINT,                                          
      ParentID               BIGINT,    
      UserId                 bigint)      */                                         
     )                                          
                                               
     CREATE TABLE #temptablesearchexc                                          
     (                                  
      CampaignID             BIGINT,                                          
      SearchID               BIGINT,                                          
      ParentID               BIGINT,                                          
      UserId                 bigint,    
      PersonName             NVARCHAR(200),                                          
      CompanyName            NVARCHAR(200),                                          
      MobileNo               NVARCHAR(200),                                          
      MobileNo1              NVARCHAR(200),                                          
      MobileNo2              NVARCHAR(200),                                          
      EmailID   NVARCHAR(200),                                          
      EmailID1               NVARCHAR(200),                                          
      EmailID2               NVARCHAR(200),                                          
      City                   NVARCHAR(200),                                          
      STATE                  NVARCHAR(200),                                          
      Country           NVARCHAR(200),                                          
      CountryCode            NVARCHAR(200),                                          
      PinCode                NVARCHAR(200),                                          
      ResidentialAddress     NVARCHAR(200),                                          
      OfficeAddress          NVARCHAR(200),                                          
      SourceName             NVARCHAR(200),                                          
      MediumName             NVARCHAR(200),                                          
      CampaignName           NVARCHAR(200),                                          
      InitialRemarks         NVARCHAR(1000)                                          
       --For searces from contacts,uncomment below code    
     /* Create table ##temptablesearchExcContacts    
        (Contact_ID             BIGINT,          
         Contact_Name           VARCHAR(150),          
         Contact_Mobile         VARCHAR(50),          
         Contact_Email          VARCHAR(50),          
         Contact_DOB            VARCHAR(50),          
         Contact_Anniversary    VARCHAR(50),          
         CompanyName            VARCHAR(100),          
         City                   VARCHAR(100),          
         STATE                  VARCHAR(100),          
         Country                VARCHAR(100),          
         ADDRESS                VARCHAR(200),          
         DateCreated            VARCHAR(50),    
         CampaignID             BIGINT,                                          
      SearchID               BIGINT,                                          
      ParentID               BIGINT,    
      UserId                 bigint)        */                                         
     )                                          
    
 INSERT INTO #temptablesearchapp(  EmailID,CampaignID,ParentID,userid  )                                          
         Select ISNULL(Usd.EmailID, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed      
   FROM  #temptemplate TT    
   Inner join  Usersearchdata AS Usd  (nolock)  on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ApplicabiltyGroupList and Tt.ApplicabiltyGroupList is not null         
 union    
       select distinct A.emailid,A.CampaignID,A.ParentID,A.userid    
        from (select f.value as Emailid,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.InclusionsNumber,',') f where f.value is not null group by CampaignID,ParentID,AccountUsed,f.value ) A           
 
    
    
--For search in contacts, the below code should be reviewed,corrected & uncommented                                 
  /*  INSERT INTO #temptablesearchapp(Contact_EmailID,CampaignID,ParentID,userid)                                          
         SELECT ISNULL(Cd.Contact_Email, ''),Tt.CampaignID, Tt.ParentID,tt.AccountUsed       
         FROM  #temptemplate TT                                       
   Inner join Contact_group_detail AS Cgd  (nolock) on Cgd.Group_ID = TT.ApplicabiltyGroupList and Tt.ApplicabiltyGroupList is not null                 
         INNER JOIN Contact_detail  AS  Cd   (nolock) ON  Cgd.Contact_ID = Cd.Contact_ID   */    
       
    INSERT INTO #temptablesearchexc (  EmailID,CampaignID,ParentID,userid  )              
         SELECT ISNULL(Usd.EmailID, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed      
         FROM #temptemplate TT                   
    Inner join   Usersearchdata AS Usd  (nolock) on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ExclusionsGroupList and Tt.ExclusionsGroupList is not null                         
       union    
       select distinct A.emailid,A.CampaignID,A.ParentID,A.userid    
        from (select f.value as Emailid,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.ExclusionsNumber,',') f where f.value is not null group by CampaignID,ParentID,AccountUsed,f.value ) A           
 
--For search in contacts, the below code should be reviewed,corrected & uncommented                                  
    /*INSERT INTO #temptablesearchexc  (  EmailID,CampaignID,ParentID,userid  )                                                             SELECT ISNULL(Cd.Contact_Email, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed      
   FROM  #temptemplate TT                                       
   Inner join Contact_group_detail AS Cgd  (nolock) on Cgd.Group_ID = TT.ExclusionsGroupList and Tt.ExclusionsGroupList is not null                 
         INNER JOIN Contact_detail  AS  Cd   (nolock) ON  Cgd.Contact_ID = Cd.Contact_ID   */    
    
     DECLARE @CountCampaign     INT = (Select MAX(Id) from #temptemplate    )                                          
                                                                                   
     DECLARE @Count INT = 1                                                                           
                                               
     WHILE (@Count <= @CountCampaign)                                          
     BEGIN                                                               
                                                
         DECLARE @Applicability BIGINT,                                       
     @Exclusions BIGINT,    
                 @Parentid BIGINT,                                          
                 @Campaignid BIGINT,    
                 @userid bigint    
                       
                     
          Select @Campaignid =Campaignid, @Parentid = Parentid ,@userid=AccountUsed    
          ,@Applicability = tt.Applicabilty,@Exclusions = tt.Exclusions    
           from #temptemplate tt Where Id = @Count                                                                                            
          If(@Applicability is not null)    
          Begin      
          --For contact search, uncomment the below code & use usp_executeusersearch_New3 instead of usp_executeusersearch    
          /* if (isnull((select isgroup from usersearchlist where searchid=@applicability),0)=1)    
          begin    
        INSERT INTO #temptablesearchContacts                                          
  (Contact_ID ,          
         Contact_Name,          
         Contact_Mobile,          
         Contact_Email,          
         Contact_DOB,          
         Contact_Anniversary,          
         CompanyName ,          
         City ,          
         STATE ,          
         Country,          
         ADDRESS,          
         DateCreated,    
         Parentid,    
         Searchid,    
         Campaignid,    
         UserId  )    
         exec Usp_executeusersearch_New3 @parentid,@applicability,@campaignid,@userid                                   
              
          end    
          else     
          begin    
          */    
              
            INSERT INTO #temptablesearchapp                                          
       (                                         
      PersonName,                                          
      CompanyName,                                          
      MobileNo,                                          
      MobileNo1,                                          
      MobileNo2,                                          
      EmailID,                                          
      EmailID1,                                          
      EmailID2,                                          
      Country,                                          
      [STATE],                             
      City,                                    
      PinCode,                                          
      ResidentialAddress,                                          
      OfficeAddress,                                          
      SourceName,                                          
      MediumName,                                          
      CampaignName,                                          
      InitialRemarks,                                          
      SearchID,                                          
      ParentID,                                          
      CampaignID                                          
       )                                          
     EXEC Usp_executeusersearch                                          
       @ParentId,                                          
       @Applicability,                                          
       @Campaignid    
           
           End    
          --end    
          if(@Exclusions is not null)    
          Begin    
          --For search within contacts uncomment below code    
          /* if (isnull((select isgroup from usersearchlist where searchid=@Exclusions),0)=1)    
          begin    
            INSERT INTO #temptablesearchExcContacts                                          
  (Contact_ID ,          
         Contact_Name,          
         Contact_Mobile,          
         Contact_Email,          
         Contact_DOB,          
         Contact_Anniversary,          
         CompanyName ,          
         City ,          
         STATE ,          
         Country,          
         ADDRESS,          
         DateCreated,    
         Parentid,    
         Searchid,    
         Campaignid,    
         UserId  )    
         exec Usp_executeusersearch_New3 @parentid,@applicability,@campaignid,@userid                                   
              
          end*/                                      
    INSERT INTO #temptablesearchexc                                          
           (                                          
             PersonName,                                          
             CompanyName,                                          
             MobileNo,                                          
             MobileNo1,                                          
  MobileNo2,                                          
             EmailID,                                          
             EmailID1,                                          
             EmailID2,                                          
             Country,                                          
             [STATE],                                          
             City,              
             PinCode,                                          
             ResidentialAddress,                                          
            OfficeAddress,                                          
             SourceName,                                          
             MediumName,                                          
             CampaignName,                                          
             InitialRemarks,                                          
             SearchID,                                          
             ParentID,                                          
             CampaignID                                          
    )                                          
         EXEC Usp_executeusersearch                                          
              @Parentid,                                          
              @Exclusions,                                          
              @Campaignid    
        
    END    
     SET @Count = @Count+1    
         
     END                                          
     --For search within contacts uncomment below code    
          /*    
          INSERT INTO #temptablesearchapp(EmailID,CampaignID,ParentID,userid)      
          select Contact_Email,CampaignID,ParentID,userid from #temptablesearchContacts    
           INSERT INTO #temptablesearchexc(EmailID,CampaignID,ParentID,userid)      
          select Contact_Email,CampaignID,ParentID,userid from #temptablesearchExcContacts    
         */                                                                                     
     SELECT A.EmailID,                                          
            A.ParentID,                                          
            A.CampaignID,    
            A.userid                                          
            INTO     #tempemailid                                          
     FROM   (                                          
                SELECT Tt2.EmailID,                                          
                       Tt2.ParentID,                                          
                       Tt2.CampaignID,    
                       tt.Accountused as userid      
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                                          
                WHERE  NOT EXISTS (SELECT 1 FROM   #temptablesearchexc Tt     
       Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.EmailID = Tt.EmailID OR Tt2.EmailID = Tt.EmailID1 OR Tt2.EmailID = Tt.EmailID2 ) )                        UNION                                          
                SELECT Tt2.EmailID1,                                          
                       Tt2.ParentID,                                          
           Tt2.CampaignID,tt.Accountused  as userid                                         
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                    
                 WHERE  NOT EXISTS (SELECT 1                                          
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.EmailID1 = Tt.EmailID OR Tt2.EmailID1 = Tt.EmailID1 OR  Tt2.EmailID1 = Tt.EmailID2)  )       
        UNION                                          
                SELECT Tt2.EmailID2,                                          
                       Tt2.ParentID,                                          
                       Tt2.CampaignID,tt.Accountused as userid                                          
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                                          
                 WHERE  NOT EXISTS (SELECT 1                                          
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND (Tt2.EmailID2 = Tt.EmailID OR Tt2.EmailID2 = Tt.EmailID1 OR  Tt2.EmailID2= Tt.EmailID2 ) )       
             
       )        A                          
                         
    SELECT     
     ROW_NUMBER() Over(order by CampaignId,ParentId) Id,    
     Ucerm.CampaignID,       
     Ucerm.ParentID                               ,    
                     -- Cast(Ucerm.Messages AS VARCHAR(MAX))  AS  Messages,                                    
                     ucerm.userID,                                  
                     Count(*) cnt    
                     -- Ucerm.Mail_ToEmail,                                    
   INTO   #tempCount                                    
      FROM   #tempemailid Ucerm                                    
      Group by  Ucerm.CampaignID,       
     Ucerm.ParentID ,                                    
                      Ucerm.UserID    
                                                      
          
      SELECT A.UserID,a.CampaignID, a.cnt,SUM(b.cnt) RunningTotal into #TempTableRunningTotal    
   FROM   #tempCount a join    
       #tempCount b  on a.userid=b.userid  
   WHERE b.CampaignID <= a.CampaignID    
   GROUP BY A.UserID, a.CampaignID, a.cnt    
   ORDER BY a.CampaignID;    
          
   --- Calculate credits                                    
      SELECT B.UserID,     
    B.CampaignID,    
      CASE                                    
               WHEN B.Balance > B.Credits THEN 1                                    
               ELSE 0  -- Test                                    
             END AS ValidEntries                                    
      INTO   #tempMobile                                    
      FROM   (SELECT A.UserID,      
      A.CampaignID,                                  
                     (A.Credits)   AS Credits,  --Runningtotal                                  
                     A.Balance                                    
              FROM   (SELECT Tt.UserID,                                    
                             TT.RunningTotal AS Credits,    
                             TT.CampaignID,                                    
                            -- Tt.Mail_ToEmail,                                    
                             (SELECT TOP 1 Balance                                    
                              FROM   Mailcreditdetails AS Mcd                                    
                              WHERE  Mcd.[User_ID] = Tt.UserID                                    
                              ORDER  BY Credit_ID DESC)     AS Balance                                    
                      FROM   #TempTableRunningTotal Tt) A                                    
              GROUP  BY A.UserID,                                    
                        A.Balance,A.CampaignID,A.credits) B    
       
      if @notification=1  
     begin                                          
     INSERT INTO Usercampaignexecutionhistory                                          
       (                                          
         CampaignID,                                          
         Jobid,    
         ExecutionTime,                                          
         IsRecipients,                                          
         ParentID    
             
       )                                          
     SELECT DISTINCT A.CampaignID,                                          
            @JobId,    
            GETDATE(),                                          
