 ue.companyname  ,                
 ue.mobileno ,ue.mobileno1 ,ue.mobileno2 ,ue.emailid                
 ,ue.emailid1 ,                
 ue.emailid2 ,                
 ue.LeadNo ,                 
 ue.NextStatusDate ,                
 ud2.fName ,                
 ud2.LName ,                
 ue.Remarks ,                
 ue.CreatedOn,                
 ud.FName ,                
 ud.LName ,      
 uss.NAME,                
 ums.Name,                
 Ucs.Name                                      
                   ),                                      
                   Ucerm.Mail_ToEmail,                                      
