         CAST(                                      
          messageContent COLLATE Latin1_General_CI_AI AS VARCHAR(MAX)),                                      
         CAST(Mail_ToEmail COLLATE Latin1_General_CI_AI AS VARCHAR(MAX)),                
         CAST(MailReplyTo COLLATE Latin1_General_CI_AI AS VARCHAR(MAX)),                                      
         AccountUsed,                                      
         CAST(MailSubject COLLATE Latin1_General_CI_AI AS VARCHAR(MAX)),    
         templateid,ISNULL(CAST(FromMailId COLLATE Latin1_General_CI_AI AS VARCHAR(250)),'contactus@email19.in')                                      
     FROM   #tempGroups                                      
     END      
                                         
   UPDATE Kd                                      
   SET    Kd.Mail_FromEmail = ISNULL(CAST(A.FromMailId COLLATE Latin1_General_CI_AI AS VARCHAR(250)),'contactus@email19.in'),    
    Kd.Mail_Subject = CAST(A.MailSubject COLLATE Latin1_General_CI_AI AS VARCHAR(MAX)),                                      
    Kd.Messages = (select CAST(dbo.build_mailContent(A.templateid,A.campaignid,A.parentid,A.MailContent COLLATE Latin1_General_CI_AI,A.Mail_ToEmail) AS VARCHAR(MAX))), --CAST(A.MailContent COLLATE Latin1_General_CI_AI AS VARCHAR(MAX)),           
    Kd.Mail_UserID = A.AccountUsed,                                      
    Kd.ReplyTo = CAST(A.MailReplyTo COLLATE Latin1_General_CI_AI AS VARCHAR(MAX)),                   
    Kd.Mail_Priority = 0,                                      
    Kd.Mail_ScheduleDate = GETDATE(),                                      
    Kd.Mail_Attechement = NULL,                                      
    Kd.Mail_TempleteBody = (select CAST(dbo.build_mailContent(A.templateid,A.campaignid,A.parentid,A.MailContent COLLATE Latin1_General_CI_AI,A.Mail_ToEmail) AS VARCHAR(MAX))), --CAST(A.MailContent COLLATE Latin1_General_CI_AI AS VARCHAR(MAX)),          
  
                            
    Kd.Mail_InsertedDate = GETDATE(),                                      
    Kd.Mail_GUID = NEWID(),                                      
    Kd.IsCompleted = 1                             
   FROM   EmailsfiltercampaignexecutionTEST2 Kd    (nolock)                                  
    INNER JOIN #TempTable A                                     
      ON kd.Mail_ID = A.Mail_Id              
                                          
   if @notification=1  
   begin        
   UPDATE Kd                                          
      SET    Ismessages = 1                                          
      FROM   Usercampaignexecutionhistory Kd        
      inner join #temptable A                 
    ON  Kd.CampaignID = A.CampaignID AND A.ParentID = Kd.ParentID AND Kd.JobId = @Jobid                                      
   end   
                      
   UPDATE Kd                                    
   SET    Kd.Step2 = 1  ,Step2DateTime=GETDATE(), Step2Recipients=isnull(A.Step2Recipients,0)                                 
   FROM   Usercampaignhistory Kd  (nolock)                                  
    Inner JOIN                                 
    (select campaignid,count(campaignid) as Step2Recipients,parentid                 
    from #temptable group by Parentid,campaignid) A                                    
    ON  Kd.CampaignID = A.CampaignID AND A.ParentID = Kd.ParentID AND Kd.JobId = @Jobid                           
                     
   UPDATE Kd                                    
   SET    Kd.Step2 = 1  ,Step2DateTime=GETDATE() FROM   Usercampaignhistory Kd where JobId=@jobid    
                         
 DROP TABLE #TempTable  
   
 INSERT INTO Getbatchrecord                                        
                  (                                        
      -- BatchID -- this column value is auto-generated                                        
       [User_id],                                        
                   RandNum)                                        
      SELECT DISTINCT Ucerm.ParentID,                                        
                      Ucerm.CampaignID                                        
      FROM   EmailsfiltercampaignexecutionTEST2 AS Ucerm With(nolock)        
                                        
     SELECT         
     ROW_NUMBER() Over(order by Ucerm.CampaignId,Ucerm.ParentId) Id,        
     Ucerm.CampaignID,           
     Ucerm.ParentID                               ,        
                     -- Cast(Ucerm.Messages AS VARCHAR(MAX))  AS  Messages,                                        
                      dbo.Fn_createbatchid(Ucerm.CampaignID, Ucerm.ParentID) AS BatchID,                                      
                     Ucerm.Mail_FromEmail,                                        
                      Ucerm.Mail_UserID AS UserID,        
                      Ucerm.Mail_Subject,        
                      Ucerm.ReplyTo,        
                      Count(*) cnt        
                     -- Ucerm.Mail_ToEmail,                                        
   INTO   #tempTable1                                        
      FROM   EmailsfiltercampaignexecutionTEST2 Ucerm -- join user_detail u on ucerm.Mail_UserID=u.user_id                                      
      WHERE  Ucerm.IsCompleted = 1  --and u.HasVirtualCredits=0           
      Group by  Ucerm.CampaignID,           
     Ucerm.ParentID , Ucerm.Mail_FromEmail,                                        
                      Ucerm.Mail_UserID,        
                      Ucerm.Mail_Subject,        
                      Ucerm.ReplyTo       
                          
SELECT         
     ROW_NUMBER() Over(order by Ucerm.CampaignId,Ucerm.ParentId) Id,        
     Ucerm.CampaignID,           
     Ucerm.ParentID                               ,        
                     -- Cast(Ucerm.Messages AS VARCHAR(MAX))  AS  Messages,                                        
                      dbo.Fn_createbatchid(Ucerm.CampaignID, Ucerm.ParentID) AS BatchID,                                      
                     Ucerm.Mail_FromEmail,                                        
                      Ucerm.Mail_UserID AS UserID,        
                      Ucerm.Mail_Subject,        
                      Ucerm.ReplyTo,        
                      Count(*) cnt,    
                      ParentSuperResellerId        
                     -- Ucerm.Mail_ToEmail,                                        
   INTO   #tempTableVirtual                                        
      FROM   EmailsfiltercampaignexecutionTEST2 Ucerm  join user_detail u on ucerm.Mail_UserID=u.user_id                                      
      WHERE  Ucerm.IsCompleted = 1  and u.HasVirtualCredits=1           
      Group by  Ucerm.CampaignID,ParentSuperResellerId,           
     Ucerm.ParentID , Ucerm.Mail_FromEmail,                                        
                      Ucerm.Mail_UserID,        
                      Ucerm.Mail_Subject,        
                      Ucerm.ReplyTo     
                          
                                                       
              
   SELECT A.UserID,a.CampaignID, a.cnt,A.BatchID, SUM(b.cnt) RunningTotal into #tempTableRunningTotal1        
   FROM   #tempTable1 a join        
       #tempTable1 b on a.UserID=b.userid       
   WHERE b.CampaignID <= a.CampaignID        
   GROUP BY A.UserID, a.CampaignID, a.cnt,A.BatchID        
   ORDER BY a.CampaignID;      
       
    SELECT A.UserID,a.CampaignID, a.cnt,A.BatchID, SUM(b.cnt) RunningTotal,a.ParentSuperResellerId into #tempTableRunningTotalVirtual         FROM   #tempTableVirtual a,        
       #tempTableVirtual b        
   WHERE b.CampaignID <= a.CampaignID        
   GROUP BY A.ParentSuperResellerId, a.CampaignID, a.cnt,A.BatchID,A.UserID        
   ORDER BY a.CampaignID;      
              
              
      DELETE Kd                                        
      FROM   Getbatchrecord Kd                                        
             INNER JOIN #tempTable1 Tt                                        
                     ON Tt.BatchID = Kd.BatchID       
                         
     DELETE Kd                                        
      FROM   Getbatchrecord Kd                                        
             INNER JOIN #tempTableVirtual Tt                                        
                     ON Tt.BatchID = Kd.BatchID                                     
                                      
                                        
      --- Calculate credits                                        
      SELECT B.UserID,         
    B.CampaignID,                                       
             CASE                                        
               WHEN B.Balance > B.Credits THEN 1                                        
               ELSE 0 --test, otherwise 0                                        
             END AS ValidEntries                                        
      INTO   #tempMobile1                                        
      FROM   (SELECT A.UserID,          
      A.CampaignID,                                      
                       (A.Credits)   AS Credits,  --Runningtotal                                      
                     A.Balance                                        
              FROM   (SELECT Tt.UserID,                                        
                             TT.RunningTotal AS Credits,        
                             TT.CampaignID,       
                            -- Tt.Mail_ToEmail,                                  
                             Tt.BatchID,                                        
                             (SELECT TOP 1 Balance                                        
                              FROM   Mailcreditdetails AS Mcd                                        
                              WHERE  Mcd.[User_ID] = Tt.UserID                 
                              ORDER  BY Credit_ID DESC)     AS Balance                                        
                      FROM   #tempTableRunningTotal1 Tt) A                                        
              GROUP  BY A.UserID,                                        
                        A.Balance,A.CampaignID,A.credits) B        
     --select * from #tempMobile1      
         
     SELECT B.UserID,         
            B.CampaignID,                                       
            CASE                                        
               WHEN B.Balance > B.Credits THEN 1                                        
               ELSE 0 --test, otherwise 0                                        
             END AS ValidEntries,    
             B.ParentSuperResellerId                                        
      INTO   #tempmobilevirtual                                        
      FROM   (SELECT A.UserID,          
      A.CampaignID,                                      
      (A.Credits)   AS Credits,  --Runningtotal                                      
      A.Balance,    
      A.ParentSuperResellerId                                        
      FROM   (SELECT Tt.UserID,                                        
                     TT.RunningTotal AS Credits,        
                     TT.CampaignID,                                        
                     -- Tt.Mail_ToEmail,                                  
                     Tt.BatchID,                                        
                     (SELECT TOP 1 Balance                                        
                      FROM   SuperResellerMailCreditDetails AS Mcd                                        
                      WHERE  Mcd.[User_ID] = Tt.ParentSuperResellerId                
                      ORDER  BY Credit_ID DESC)     AS Balance,    
                      tt.ParentSuperResellerId                                        
               FROM   #tempTableRunningTotalVirtual Tt) A                                        
              GROUP  BY A.ParentSuperResellerId,A.UserID,                                       
                        A.Balance,A.CampaignID,A.credits) B     
         
select t.*,u.email into #Insufficientresellerbalance from #tempmobilevirtual t join #tempMobile1 tt on t.CampaignID=tt.CampaignID join user_detail u on u.user_id=t.ParentSuperResellerId where tt.ValidEntries=0    
  
if @send=1  
begin    
INSERT INTO Batchemail_infos(BatchID,UserID,SenderName,[Message],TotalRecords,TotalProcessed,ProcessTable,IsProcess,Priority_Level,BatchInsertTime,     BatchProcessTime,ScheduledDate,ScheduledTime,TemplateID,[Route],PageName,IsScheduled,Email_Subject,ReplyTo)    
                                 
      SELECT A.BatchID,A.UserID,U.Email as SenderName,(select top 1 Cast(e.Messages AS VARCHAR(MAX))         
      from EmailsfiltercampaignexecutionTEST2 e         
      where e.CampaignID=a.campaignid),A.cnt,0,0,0,0,Getdate(),NULL,NULL,NULL,0,0,0,0,A.Mail_Subject,A.ReplyTo         
      FROM #tempTable1 A (nolock)         
      Inner join #tempMobile1 TM on Tm.CampaignID = A.CampaignID and TM.UserID = A.UserID         
      join user_detail u (nolock) on u.user_id=a.UserID  and TM.ValidEntries = 1        
          
               
create table #output1 (GUID nvarchar(100) collate SQL_Latin1_General_CP1_CI_AS ,Email nvarchar(200) collate SQL_Latin1_General_CP1_CI_AS,Batchid bigint)        
    
             
      INSERT INTO Clientemails                                        
                  (       
      -- Id -- this column value is auto-generated                                        
      GUID,                                        
                   Email_Id,                                        
                   SentDateTime,                                        
                   UserId,                                        
                   ReplyTo,                            
                   [Status],                                        
                   BatchID,                                        
                   [Message],    
                   campaignid,    
                   parentid)     
      OUTPUT inserted.GUID  as GUId,inserted.email_id,inserted.batchid as Email INTO #output1                                           
      SELECT Newid(),                                        
             Efce.Mail_ToEmail,                                        
             Getdate(),                                        
             Efce.Mail_UserID,                                        
             Efce.ReplyTo,                                        
             '',                                        
             TT.BatchID,                                        
             Efce.Messages,    
             efce.CampaignID,    
             efce.ParentID                                        
      FROM   EmailsfiltercampaignexecutionTEST2 AS Efce                                        
             INNER JOIN #tempMobile1 Tm                                        
      ON Tm.CampaignID = Efce.CampaignID AND ValidEntries = 1       
   inner join #tempTable1 TT on TT.campaignid=efce.campaignid      
      WHERE  Efce.IsCompleted = 1     
                                        
                                        
      INSERT INTO Emailsfilter                                       
                  (Mail_GUID,                                        
                   Mail_FromEmail,                                        
                   Mail_ToEmail,                                        
                   Mail_Subject,                                        
                   Mail_TempleteName,                                        
                   Messages,                                        
                   Mail_InsertedDate,       
                   Mail_UserID,                                        
                   ReplyTo,                                        
                   Mail_BatchID,                                        
                   Mail_Priority,                                        
                   Mail_ScheduleDate,                                        
                   Mail_Attechement,                                        
                   Mail_TempleteBody,                                        
                   IsMonitor)                                        
      SELECT O.Guid,                                        
             Efce.Mail_FromEmail,                                        
             Efce.Mail_ToEmail,            
             Efce.Mail_Subject,                                     
             Efce.Mail_TempleteName,                                        
             cast(Efce.Messages as nvarchar(max)),                                      
             isnull(Efce.Mail_InsertedDate,getdate()),                                        
             Efce.Mail_UserID,                                        
             Efce.ReplyTo,                                        
             TT.BatchID,                                        
             Efce.Mail_Priority,                                        
             isnull(Efce.Mail_ScheduleDate,getdate()),                                        
             Efce.Mail_Attechement,                                        
             cast(Efce.Mail_TempleteBody as nvarchar(max)),                                        
             1 AS Limit                    
      FROM   EmailsfiltercampaignexecutionTEST2 AS Efce                                        
             INNER JOIN #tempMobile1 Tm                                        
        ON Tm.userID = Efce.Mail_UserID  and Tm.CampaignID = Efce.CampaignID                            
                        AND ValidEntries = 1       
                        inner join #tempTable1 TT on TT.campaignid=efce.campaignid      
                        inner join #output1 o on o.email=Efce.mail_toemail                                     
      WHERE  Efce.IsCompleted = 1 and o.batchid=tt.batchid     
      and not exists    
      (SELECT O.Guid--,                                        
             --Efce.Mail_FromEmail,                                        
             --Efce.Mail_ToEmail,            
             --Efce.Mail_Subject,                                     
             --Efce.Mail_TempleteName,                                        
             --cast(Efce.Messages as nvarchar(max)),                                      
             --isnull(Efce.Mail_InsertedDate,getdate()),                                        
             --Efce.Mail_UserID,                                        
             --Efce.ReplyTo,                                        
             --TT.BatchID,                                        
             --Efce.Mail_Priority,                                        
             --isnull(Efce.Mail_ScheduleDate,getdate()),                                        
             --Efce.Mail_Attechement,                                        
             --cast(Efce.Mail_TempleteBody as nvarchar(max)),                                        
             --1 AS Limit                                        
      FROM   EmailsfiltercampaignexecutionTEST2 AS Efce                                        
             INNER JOIN #tempmobilevirtual Tm                                        
        ON Tm.userID = Efce.Mail_UserID  and Tm.CampaignID = Efce.CampaignID                            
                        AND ValidEntries = 0       
                        inner join #tempTable1 TT on TT.campaignid=efce.campaignid      
                        inner join #output1 o on o.email=Efce.mail_toemail                                     
      WHERE  Efce.IsCompleted = 1 and o.batchid=tt.batchid)    
          
          
      INSERT INTO EmailsfilterVirtual                                       
                (Mail_GUID,                                        
                   Mail_FromEmail,                                        
                   Mail_ToEmail,                                        
                   Mail_Subject,                                        
                   Mail_TempleteName,                                        
                   Messages,                                        
                   Mail_InsertedDate,                                        
                   Mail_UserID,                                        
                   ReplyTo,                                        
                   Mail_BatchID,                                        
                   Mail_Priority,                                        
                   Mail_ScheduleDate,                                        
                   Mail_Attechement,                                        
                   Mail_TempleteBody,                                        
                   IsMonitor)                                        
      SELECT O.Guid,                                        
             Efce.Mail_FromEmail,                                        
             Efce.Mail_ToEmail,            
             Efce.Mail_Subject,                                     
             Efce.Mail_TempleteName,                                        
             Efce.Messages,                                      
             isnull(Efce.Mail_InsertedDate,getdate()),                                
             Efce.Mail_UserID,                                        
             Efce.ReplyTo,                                        
             TT.BatchID,                                        
             Efce.Mail_Priority,                                        
             isnull(Efce.Mail_ScheduleDate,getdate()),                                        
             Efce.Mail_Attechement,                                        
             Efce.Mail_TempleteBody,                                        
             1 AS Limit                                        
      FROM   EmailsfiltercampaignexecutionTEST2 AS Efce                                        
             INNER JOIN #tempmobilevirtual Tm                                        
        ON Tm.userID = Efce.Mail_UserID  and Tm.CampaignID = Efce.CampaignID                            
                        AND ValidEntries = 0       
                        inner join #tempTableVirtual TT on TT.campaignid=efce.campaignid      
                        inner join #output1 o on o.email=Efce.mail_toemail                                     
      WHERE  Efce.IsCompleted = 1 and o.batchid=tt.batchid       
          
      truncate table #output1                                     
                                        
      INSERT INTO Mailcreditdetails                                        
                  (ID,                                        
                   -- Credit_ID -- this column value is auto-generated                                        
                   M_ID,                                        
                   FromUser_ID,                                        
                   [User_ID],                                        
                   Debits,                                        
                 Credits,                                        
                 Balance,                                        
                   Validity,                                        
                   Default_Credit,                                        
                   FromDate,                                        
                   ToDate,                                        
                   DateCreated,                                        
                   DateUpdated,                                        
               EmpUpdated,                                        
                   MachineName,                                        
                   LastModified,                            
                   typecredit,      
                   campaignid)                                        
      SELECT Newid(),                                        
             (SELECT TOP 1 Ud.M_ID                                        
              FROM   User_detail AS Ud                                        
              WHERE  Ud.[User_ID] = A.UserID),                                        
             A.UserID,                                        
             A.UserID,                                        
             A.NoofRecipients,                                        
             0,                                        
             (SELECT TOP 1 Mcd.Balance                                        
              FROM   Mailcreditdetails AS Mcd                                        
              WHERE  Mcd.[User_ID] = A.UserID                                        
              ORDER  BY Mcd.Credit_ID DESC) - A.NoofRecipients,                                        
             99999,                                        
       '',                                        
             Getdate(),                                        
             Getdate(),                                        
             Getdate(),                                        
             Getdate(),                                        
             '',                 
             '',                                        
             Getdate(),                               
             '',      
             A.Campaignid                                        
      FROM   (SELECT DISTINCT Ed.UserID,Ed.CampaignID,Ed.ParentID,                                        
                              SUM(Ed.Cnt) AS NoofRecipients                                        
              FROM   #tempTable1 Ed                                        
                     INNER JOIN #tempMobile1 Tm                                        
                  ON Tm.userID = Ed.UserID   and Tm.CampaignID = Ed.CampaignID     
                  where Ed.Cnt>0 AND ValidEntries = 1                                        
               GROUP  BY Ed.UserID,Ed.CampaignID,Ed.ParentID,ED.UserID) A        
    
      INSERT INTO SuperresellerMailcreditdetails                                        
                  (ID,                                        
                   -- Credit_ID -- this column value is auto-generated                                        
                   M_ID,                                        
                   FromUser_ID,                                        
                   [User_ID],                                        
                   Debits,                                        
                 Credits,                                        
                 Balance,                                        
                   Validity,                                        
                   Default_Credit,                                        
                   FromDate,                                        
                   ToDate,                                        
                   DateCreated,                                        
                   DateUpdated,                                        
               EmpUpdated,                                        
                   MachineName,                                        
                   LastModified,                                        
                   typecredit,      
                   campaignid)                                        
      SELECT Newid(),                                        
             (SELECT TOP 1 Ud.M_ID                                        
              FROM   User_detail AS Ud                                        
              WHERE  Ud.[User_ID] = A.ParentSuperResellerId),                                        
             A.ParentSuperResellerId,                                        
             A.ParentSuperResellerId,                
             A.NoofRecipients,                                        
             0,                                        
             (SELECT TOP 1 Mcd.Balance                                        
              FROM   SuperResellerMailCreditDetails AS Mcd                                        
              WHERE  Mcd.[User_ID] = A.ParentSuperResellerId                                        
              ORDER  BY Mcd.Credit_ID DESC) - A.NoofRecipients,                                        
             99999,                                        
       '',                                        
             Getdate(),                                        
             Getdate(),                                        
             Getdate(),                                        
             Getdate(),                                        
             '',                                        
             '',                                        
             Getdate(),                               
             '',      
             A.Campaignid                                        
      FROM   (SELECT DISTINCT tm.ParentSuperResellerId,ed.userid,Ed.CampaignID,Ed.ParentID,                                                                  SUM(Ed.Cnt) AS NoofRecipients                       
              FROM   #tempTable1 Ed                                        
                     INNER JOIN #tempmobilevirtual Tm                                        
                  ON Tm.userID = Ed.UserID   and Tm.CampaignID = Ed.CampaignID     
                  where Ed.Cnt>0 AND ValidEntries = 1                                        
               GROUP  BY Ed.UserID,tm.ParentSuperResellerId,Ed.CampaignID,Ed.ParentID,ED.UserID) A                       
 end                 
                   
                       
if @notification=1  
begin                  
     UPDATE Kd                                        
      SET    Executiontime = Getdate(),                                        
             Noofrecipients = Tt.Cnt,                
             Batchid = Tt.BatchID,                                        
             --Ismessages = 1,                                        
             Isexecuted = case when tm.Validentries=1 then 1 else 0 end                                            
      FROM   Usercampaignexecutionhistory Kd                                        
             INNER JOIN #tempTable1 Tt                                        
          ON Tt.CampaignID = Kd.CampaignID                                        
             INNER JOIN #tempMobile1 Tm                                        
                     ON Tm.userID = Tt.userID   and Tm.CampaignID = Tt.CampaignID                                                  --AND Validentries = 1                                        
      WHERE  Jobid=@jobId--Kd.ID = (select MAX(id) from Usercampaignexecutionhistory Kd1 where kd1.CampaignID=kd.CampaignID)        
            
      --select * from UserCampaignExecutionHistory where CampaignID=497 order by id desc                                      
                                        
