                                               FROM   #temptablesearchexc Tt)                                          
                       OR  Tt2.EmailID NOT IN (SELECT Tt.EmailID2                                          
                                               FROM   #temptablesearchexc Tt)                                          
                       OR  Tt2.EmailID1 NOT IN (SELECT Tt.EmailID                                          
                                                FROM   #temptablesearchexc Tt)                                          
                       OR  Tt2.EmailID1 NOT IN (SELECT Tt.EmailID1                                          
                        FROM   #temptablesearchexc Tt)                                          
                       OR  Tt2.EmailID1 NOT IN (SELECT Tt.EmailID2                                          
