     INSERT INTO Usercampaignexecutionhistory                                          
       (                                          
         CampaignID,                                          
         ExecutionTime,                                          
         IsRecipients,                                          
         ParentID                                          
       )                                          
     SELECT DISTINCT A.CampaignID,                                          
            GETDATE(),                                          
            1,                                          
            A.ParentID                                          
     FROM   (                                          
                SELECT A.EmailID,                                          
                       A.ParentID,                                          
                       A.CampaignID                                          
                FROM   #tempemailid A                   
                UNION                                          
                SELECT CAST(Fs.[value] COLLATE Latin1_general_ci_ai AS VARCHAR(500)),                                          
      Ucm.ParentID,                                          
                       Ucm.ID                                          
                FROM   Usercampaignmaster AS Ucm                                          
                       OUTER APPLY Dbo.Fn_split(Ucm.InclusionsNumber, ',') AS                                           
  Fs                                          
                WHERE  Ucm.MailReplyTo <> ''                                          
                      AND Ucm.NextExecuteDateTime between @LastExecutedTime and  getdate()  AND DATEDIFF(                                          
                               Minute,                                          
                               getdate(),                                          
                               CASE                                           
                                    WHEN Ucm.IsNeverExpire = 1 THEN DATEADD(DAY, 1, getdate())                                          
                                    ELSE ISNULL(Ucm.ExpiryDate, getdate())                                          
                               END                                          
                           ) > 0                         
                       AND DATEDIFF(Minute, getdate(), ISNULL(Ucm.StartDate, getdate()))                                          
                           < 0                               
                       AND Ucm.IsActive = 1                                          
            ) A                                          
                                               
     INSERT INTO Emailsfiltercampaignexecution                            
       (                                          
         Mail_FromEmail,                                          
         Mail_GUID,                                          
         Mail_ToEmail,                                        
         Mail_InsertedDate,                                          
         ParentID,                                          
         CampaignID,                                          
   Mail_UserID                                          
       )                                          
     SELECT '',                                          
            NEWID(),                                          
            A.EmailID,                                          
            GETDATE(),                                          
            A.ParentID,                                       
            A.CampaignID,                                          
            0                                          
     FROM   (                                          
                SELECT CAST(Tt.EmailID COLLATE Latin1_general_ci_ai AS VARCHAR(500)) AS                                           
                       EmailID,                                          
                       Tt.ParentID,                                          
                       Tt.CampaignID                                          
                FROM   #tempemailid Tt                        
                WHERE  Tt.EmailID <> ''                                          
                UNION                                          
                SELECT CAST(Fs.[value] COLLATE Latin1_general_ci_ai AS VARCHAR(500)),                                          
                       Ucm.ParentID,                                          
                       Ucm.ID                                          
                FROM   Usercampaignmaster AS Ucm                                          
                       OUTER APPLY Dbo.Fn_split(Ucm.InclusionsNumber, ',') AS                                           
                Fs                                          
                WHERE  Ucm.MailReplyTo <> ''                         
                        AND  Ucm.NextExecuteDateTime between @LastExecutedTime and  getdate()   AND DATEDIFF(                                          
                               Minute,                                          
                               getdate(),                                          
                               CASE                                           
                                    WHEN Ucm.IsNeverExpire = 1 THEN DATEADD(DAY, 1, getdate())                                          
                                    ELSE ISNULL(Ucm.ExpiryDate, getdate())                                          
                               END                                          
                           ) > 0                                          
                       AND DATEDIFF(Minute, getdate(), ISNULL(Ucm.StartDate, getdate()))                                          
                           < 0                                          
                       AND Ucm.IsActive = 1                                     
            ) A                                          
     WHERE  CAST(A.EmailID COLLATE Latin1_general_ci_ai AS VARCHAR(500))                                          
            NOT IN (SELECT CAST(                                          
                               ISNULL(Fs.[value], 'test') COLLATE                                          
                               Latin1_general_ci_ai AS            
                               VARCHAR(500)                                 )                        
                    FROM   Usercampaignmaster AS Ucm2                                          
                           OUTER APPLY Dbo.Fn_split(Ucm2.ExclusionsNumber, ',') AS                                           
                    Fs                                          
                    WHERE  Ucm2.ID = A.CampaignID                                          
                           AND Ucm2.IsActive = 1                                   
                  AND A.ParentID = Ucm2.ParentID)                      
                                      
                  --update UserCampaignHistory set step1recipients=isnull(COUNT(e.campaignid),0) from EmailsFilterCampaignExecution e join UserCampaignHistory u on e.CampaignID=U.CampaignID  where u.ID=@campaignrun                    
                    
UPDATE A                    
SET step1=1,step1datetime=getdate(),step1recipients = isnull(B.[RecipientsCount],0)          
FROM [dbo].UserCampaignHistory A INNER JOIN                     
(SELECT a.campaignid as campaignid,isnull(count(e.CampaignID),0) AS [RecipientsCount]                    
         FROM UserCampaignHistory A left outer join [dbo].[EmailsFilterCampaignExecution] e on e.CampaignID=a.ID group by a.campaignid                    
 ) B                    
ON A.[campaignid] = B.[campaignid] join ##campaignrunmail c on a.ID=c.CampaignrunID                     
                                        
                                               
