CREATE   PROCEDURE [dbo].[Usp_executerecipientsusercampaignmailsSelectedCorrected]     
@campaignsToRun  nvarchar(max)                                       
AS                                          
BEGIN     
 --declare @campaignsToRun  nvarchar(max) ='497'                                       
 DECLARE @Body VARCHAR(500)                                          
                                           
 DECLARE @LastExecutedTime datetime =isnull((select Top 1 CampaignExecutedDatetime from UserCampaignExecution where issms=0 and isnull(isevent,0)=0 order by id desc),getdate())   
  
if exists(select 1 from UserCampaignExecution where issms=0 and isnull(isevent,0)=0 and isrunning=0)  
 begin  
 update UserCampaignExecution set isrunning=1 where issms=0 and isnull(isevent,0)=0  
   
 DEclare @JobId Bigint = (Select ISNULL(MAX(JobId),0)+1 from UserCampaignHistory UCH )    
     
 Declare @CampaignStarttime datetime = Getdate()      
    
 if OBJECT_ID('tempdb..#temptemplate') is not null                  
 Begin     
 Drop table #temptemplate     
end          
         
 SELECT    ROW_NUMBER()Over(Order by Ucm.ID,Ucm.ParentID) AS Id,       
     Ucm.ID      AS CampaignID,                                          
                   Ucm.ParentID,                                          
                   A.[value]  AS Applicabilty,                                          
                   AGL.[value]         AS ApplicabiltyGroupList,                                          
                   EGL.[value]        AS ExclusionsGroupList,                                          
                   Ucm.NotificationMail,                                          
                   Ucm.ExclusionsNumber,                                          
                   E.[value]           AS Exclusions,                                          
                   Ucm.InclusionsNumber,                                          
                   Ucm.AccountUsed,                                          
                   Ucm.SenderID,                                          
                   Ucm.[Message],                                          
                   Ucm.TemplateID,                                          
                   Ucm.TemplateGroupID,                                          
                   Ucm.IsUnicode                    INTO #temptemplate                                                                   FROM   Usercampaignmaster Ucm   (nolock)    
   Inner join  User_detail AS Ud  on Ud.[User_ID]  = AccountUsed and Ud.[Status] <> 0                                            OUTER APPLY Dbo.Fn_split(Ucm.Applicabilty, '#') AS A     
   OUTER APPLY Dbo.Fn_split(Ucm.ApplicabiltyGroupList, '#') AS AGL    
   OUTER APPLY Dbo.Fn_split(Ucm.ExclusionsGroupList, '#') AS  EGL     
   OUTER APPLY Dbo.Fn_split(Ucm.Exclusions, '#') AS E                                          
            WHERE Ucm.ID in (select value from dbo.fn_split(@campaignsToRun,','))     
            /*Ucm.MailReplyTo <> ''  and isscheduled=1                                        
                   AND Ucm.NextExecuteDateTime between @LastExecutedTime and  getdate()                                 
                   AND DATEDIFF(                                          
                           Minute,                                          
                           getdate(),                                          
                           CASE                                           
                                WHEN Ucm.IsNeverExpire = 1 THEN DATEADD(DAY, 1,getdate())                                          
                                ELSE ISNULL(Ucm.ExpiryDate, getdate())                                          
                       END                                          
                       ) > 0                                          
                   AND DATEDIFF(Minute, getdate(), ISNULL(Ucm.StartDate, getdate()))  <= 0                                          
                   AND Ucm.IsActive = 1  */                                        
                                     
   INSERT INTO Usercampaignhistory                                          
   (          
     -- ID -- this column value is auto-generated                                          
     CampaignID,                                          
     ParentID,                                          
     Step1,                                          
     Step2,                                      
     Step3,                                          
     IsSMS,                                          
     IsMail,                                          
     IsScheduled,                                          
     IsEventBased,                                          
     CreatedOn,    
     JobId                                      
   )                            
 SELECT DISTINCT CampaignID,                                          
    ParentID,                                          
        0,              
        0,                                          
        0,                                          
        0,                                          
        1,                                          
        1,                                          
        0,                                          
        GETDATE(),    
        @JobId                                          
 FROM   #temptemplate       
                         
 IF NOT EXISTS (                                          
        SELECT 'x'                                          
        FROM   #temptemplate                                          
    )                                          
 BEGIN                                          
     SET @Body = 'No Campaign Found'                                          
                                               
     SELECT @Body                                          
END       
--select * from #temptemplate    
 ELSE                                          
 BEGIN                                                          
     CREATE TABLE #temptablesearchapp                                          
     (                                          
      CampaignID             BIGINT,                                          
      SearchID               BIGINT,                                          
      ParentID               BIGINT,    
      UserId                 bigint,                                         
      PersonName             NVARCHAR(200),                            
      CompanyName            NVARCHAR(200),                                          
      MobileNo               NVARCHAR(200),                                          
      MobileNo1              NVARCHAR(200),                                          
      MobileNo2              NVARCHAR(200),                                          
      EmailID                NVARCHAR(200),                                          
      EmailID1               NVARCHAR(200),                                          
      EmailID2               NVARCHAR(200),                                          
      City        NVARCHAR(200),                                          
      STATE                  NVARCHAR(200),                                          
   Country                NVARCHAR(200),                                          
      CountryCode            NVARCHAR(200),                                          
    PinCode                NVARCHAR(200),                                          
      ResidentialAddress     NVARCHAR(200),                                          
      OfficeAddress          NVARCHAR(200),                                          
      SourceName             NVARCHAR(200),                                          
      MediumName             NVARCHAR(200),                                          
      CampaignName           NVARCHAR(200),                                          
      InitialRemarks         NVARCHAR(1000)     
      --For searces from contacts,uncomment below code    
     /* Create table #temptablesearchContacts    
        (Contact_ID             BIGINT,          
         Contact_Name           VARCHAR(150),          
