      ParentID               BIGINT,    
      UserId                 bigint)        */                                         
     )                                          
    
 INSERT INTO #temptablesearchapp(  EmailID,CampaignID,ParentID,userid  )                                          
         Select ISNULL(Usd.EmailID, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed      
   FROM  #temptemplate TT    
   Inner join  Usersearchdata AS Usd  (nolock)  on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ApplicabiltyGroupList and Tt.ApplicabiltyGroupList is not null         
 union    
       select distinct A.emailid,A.CampaignID,A.ParentID,A.userid    
        from (select f.value as Emailid,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.InclusionsNumber,',') f where f.value is not null group by CampaignID,ParentID,AccountUsed,f.value ) A           
 
    
    
--For search in contacts, the below code should be reviewed,corrected & uncommented                                 
  /*  INSERT INTO #temptablesearchapp(Contact_EmailID,CampaignID,ParentID,userid)                                          
         SELECT ISNULL(Cd.Contact_Email, ''),Tt.CampaignID, Tt.ParentID,tt.AccountUsed       
         FROM  #temptemplate TT                                       
   Inner join Contact_group_detail AS Cgd  (nolock) on Cgd.Group_ID = TT.ApplicabiltyGroupList and Tt.ApplicabiltyGroupList is not null                 
         INNER JOIN Contact_detail  AS  Cd   (nolock) ON  Cgd.Contact_ID = Cd.Contact_ID   */    
       
    INSERT INTO #temptablesearchexc (  EmailID,CampaignID,ParentID,userid  )              
         SELECT ISNULL(Usd.EmailID, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed      
         FROM #temptemplate TT                   
    Inner join   Usersearchdata AS Usd  (nolock) on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ExclusionsGroupList and Tt.ExclusionsGroupList is not null                         
       union    
       select distinct A.emailid,A.CampaignID,A.ParentID,A.userid    
        from (select f.value as Emailid,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.ExclusionsNumber,',') f where f.value is not null group by CampaignID,ParentID,AccountUsed,f.value ) A           
 
--For search in contacts, the below code should be reviewed,corrected & uncommented                                  
    /*INSERT INTO #temptablesearchexc  (  EmailID,CampaignID,ParentID,userid  )                                                             SELECT ISNULL(Cd.Contact_Email, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed      
   FROM  #temptemplate TT                                       
   Inner join Contact_group_detail AS Cgd  (nolock) on Cgd.Group_ID = TT.ExclusionsGroupList and Tt.ExclusionsGroupList is not null                 
         INNER JOIN Contact_detail  AS  Cd   (nolock) ON  Cgd.Contact_ID = Cd.Contact_ID   */    
    
     DECLARE @CountCampaign     INT = (Select MAX(Id) from #temptemplate    )                                          
                                                                                   
     DECLARE @Count INT = 1                                                                           
                                               
     WHILE (@Count <= @CountCampaign)                                          
     BEGIN                                                               
                                                
         DECLARE @Applicability BIGINT,                                       
     @Exclusions BIGINT,    
                 @Parentid BIGINT,                                          
                 @Campaignid BIGINT,    
                 @userid bigint    
                       
           
          Select @Campaignid =Campaignid, @Parentid = Parentid ,@userid=AccountUsed    
          ,@Applicability = tt.Applicabilty,@Exclusions = tt.Exclusions    
           from #temptemplate tt Where Id = @Count                                                                                            
          If(@Applicability is not null)    
          Begin      
          --For contact search, uncomment the below code & use usp_executeusersearch_New3 instead of usp_executeusersearch    
          /* if (isnull((select isgroup from usersearchlist where searchid=@applicability),0)=1)    
          begin    
        INSERT INTO #temptablesearchContacts                                          
  (Contact_ID ,          
         Contact_Name,          
         Contact_Mobile,          
         Contact_Email,          
         Contact_DOB,          
         Contact_Anniversary,          
         CompanyName ,          
         City ,          
         STATE ,          
         Country,          
         ADDRESS,          
         DateCreated,    
         Parentid,    
         Searchid,    
         Campaignid,    
         UserId  )    
         exec Usp_executeusersearch_New3 @parentid,@applicability,@campaignid,@userid                                   
              
          end    
          else     
          begin    
          */    
              
            INSERT INTO #temptablesearchapp                                          
       (                                         
      PersonName,                                          
      CompanyName,                                          
      MobileNo,                                          
      MobileNo1,                                          
      MobileNo2,                                          
      EmailID,                                          
      EmailID1,                                          
      EmailID2,                                          
      Country,                                          
      [STATE],                             
      City,                                    
      PinCode,                                          
      ResidentialAddress,                                          
      OfficeAddress,                                          
      SourceName,                                          
      MediumName,                                          
      CampaignName,                                          
      InitialRemarks,                                          
      SearchID,                                          
      ParentID,                                          
      CampaignID                                          
       )                                          
     EXEC Usp_executeusersearch                                          
       @ParentId,                                          
       @Applicability,                                          
       @Campaignid    
           
           End    
          --end    
          if(@Exclusions is not null)    
          Begin    
          --For search within contacts uncomment below code    
          /* if (isnull((select isgroup from usersearchlist where searchid=@Exclusions),0)=1)    
          begin    
            INSERT INTO #temptablesearchExcContacts                                          
  (Contact_ID ,          
         Contact_Name,          
         Contact_Mobile,          
         Contact_Email,          
         Contact_DOB,          
         Contact_Anniversary,          
         CompanyName ,          
         City ,          
         STATE ,          
         Country,          
         ADDRESS,          
         DateCreated,    
         Parentid,    
         Searchid,    
         Campaignid,    
         UserId  )    
         exec Usp_executeusersearch_New3 @parentid,@applicability,@campaignid,@userid                                   
              
          end*/                                      
  INSERT INTO #temptablesearchexc                                          
           (                                          
             PersonName,                                          
             CompanyName,                                          
             MobileNo,                                          
             MobileNo1,                                          
  MobileNo2,                                          
             EmailID,                                          
             EmailID1,                                          
             EmailID2,                                          
             Country,                                          
             [STATE],                                          
             City,              
             PinCode,                                          
             ResidentialAddress,                                          
            OfficeAddress,                                          
             SourceName,                                          
             MediumName,                                          
             CampaignName,                                          
             InitialRemarks,                                          
             SearchID,                                          
             ParentID,                                          
             CampaignID                                          
    )                                          
         EXEC Usp_executeusersearch                                          
              @Parentid,                                          
              @Exclusions,                                          
              @Campaignid    
        
    END    
     SET @Count = @Count+1    
         
     END                                          
     --For search within contacts uncomment below code    
          /*    
          INSERT INTO #temptablesearchapp(EmailID,CampaignID,ParentID,userid)      
          select Contact_Email,CampaignID,ParentID,userid from #temptablesearchContacts    
           INSERT INTO #temptablesearchexc(EmailID,CampaignID,ParentID,userid)      
          select Contact_Email,CampaignID,ParentID,userid from #temptablesearchExcContacts    
         */                                                                                     
     SELECT A.EmailID,                                          
            A.ParentID,                                          
            A.CampaignID,    
            A.userid                                          
            INTO     #tempemailid                                          
     FROM   (                                          
                SELECT Tt2.EmailID,                                          
                       Tt2.ParentID,                                          
                       Tt2.CampaignID,    
                       tt.Accountused as userid      
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                                          
                WHERE  NOT EXISTS (SELECT 1 FROM   #temptablesearchexc Tt     
       Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.EmailID = Tt.EmailID OR Tt2.EmailID = Tt.EmailID1 OR Tt2.EmailID = Tt.EmailID2 ) )                        UNION                                          
                SELECT Tt2.EmailID1,                                          
                       Tt2.ParentID,                                          
           Tt2.CampaignID,tt.Accountused  as userid                                         
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                    
                 WHERE  NOT EXISTS (SELECT 1                                          
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.EmailID1 = Tt.EmailID OR Tt2.EmailID1 = Tt.EmailID1 OR  Tt2.EmailID1 = Tt.EmailID2)  )       
                UNION                                          
                SELECT Tt2.EmailID2,                                          
                       Tt2.ParentID,                                          
                       Tt2.CampaignID,tt.Accountused as userid                                          
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                                          
                 WHERE  NOT EXISTS (SELECT 1                                          
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND (Tt2.EmailID2 = Tt.EmailID OR Tt2.EmailID2 = Tt.EmailID1 OR  Tt2.EmailID2= Tt.EmailID2 ) )       
             
       )        A                          
                         
    SELECT     
     ROW_NUMBER() Over(order by CampaignId,ParentId) Id,    
     Ucerm.CampaignID,       
     Ucerm.ParentID                               ,    
                     -- Cast(Ucerm.Messages AS VARCHAR(MAX))  AS  Messages,                                    
                     ucerm.userID,                                  
                     Count(*) cnt    
                     -- Ucerm.Mail_ToEmail,                                    
   INTO   #tempCount                                    
      FROM   #tempemailid Ucerm                                    
      Group by  Ucerm.CampaignID,       
     Ucerm.ParentID ,                                    
                      Ucerm.UserID    
                                                      
          
      SELECT A.UserID,a.CampaignID, a.cnt,SUM(b.cnt) RunningTotal into #TempTableRunningTotal    
   FROM   #tempCount a join    
       #tempCount b    on a.userid=b.userid
   WHERE b.CampaignID <= a.CampaignID    
   GROUP BY A.UserID, a.CampaignID, a.cnt    
   ORDER BY a.CampaignID;    
          
   --- Calculate credits                                    
      SELECT B.UserID,     
    B.CampaignID,    
      CASE                                    
               WHEN B.Balance > B.Credits THEN 1                                    
               ELSE 0  -- Test                                    
             END AS ValidEntries                                    
      INTO   #tempMobile                                    
      FROM   (SELECT A.UserID,      
      A.CampaignID,                                  
                     (A.Credits)   AS Credits,  --Runningtotal                                  
                     A.Balance                                    
              FROM   (SELECT Tt.UserID,                                    
                             TT.RunningTotal AS Credits,    
                             TT.CampaignID,                                    
                            -- Tt.Mail_ToEmail,                                    
                             (SELECT TOP 1 Balance                                    
                              FROM   Mailcreditdetails AS Mcd                                    
                              WHERE  Mcd.[User_ID] = Tt.UserID                                    
                              ORDER  BY Credit_ID DESC)     AS Balance                                    
                      FROM   #TempTableRunningTotal Tt) A                                    
              GROUP  BY A.UserID,                                    
                        A.Balance,A.CampaignID,A.credits) B    
                                               
     INSERT INTO Usercampaignexecutionhistory                                          
       (                                          
         CampaignID,                                          
         Jobid,    
         ExecutionTime,                                          
         IsRecipients,                                          
         ParentID    
             
)                                          
     SELECT DISTINCT A.CampaignID,                                          
            @JobId,    
            GETDATE(),                                          
            1,                                          
            A.ParentID                                          
     FROM   (                                          
               SELECT    
      TT.ParentID,    
      TT.CampaignID    
                from #tempcount TT join #tempMobile tm on tm.CampaignID=tt.CampaignID    
                where tm.ValidEntries=1                                                   
            ) A       
                                       
         
     --delete te from #tempemailid te join #tempmobile tm on te.campaignid=tm.campaignid where tm.validentries=0                                         
     INSERT INTO EmailsfiltercampaignexecutionTEST2                                          
       (                                          
         Mail_FromEmail,                                        
         Mail_GUID,                                          
         Mail_ToEmail,                 
         Mail_InsertedDate,                                          
         ParentID,                                          
         CampaignID,                                          
   Mail_UserID                                          
       )                                          
     SELECT '',                                          
            NEWID(),                                          
            A.EmailID,                                          
            GETDATE(),                                          
            A.ParentID,                                          
            A.CampaignID,                                          
            0                                          
     FROM   (                                          
                SELECT CAST(Tt.EmailID COLLATE Latin1_general_ci_ai AS VARCHAR(500)) AS                                           
                       EmailID,                                          
   Tt.ParentID,                                          
                 Tt.CampaignID                                          
                FROM   #tempemailid Tt                                          
                WHERE  Tt.EmailID <> ''  and tt.EmailID is not null                                        
                UNION                                          
                SELECT CAST(Fs.[value] COLLATE Latin1_general_ci_ai AS VARCHAR(500)),                                          
                       tt.ParentID,                                          
                       tt.CampaignID                                          
                FROM   #temptemplate AS tt  (nolock)                                        
                       OUTER APPLY Dbo.Fn_split(tt.InclusionsNumber, ',') AS Fs  where  fs.value is not null                                         
     ) A    
     Inner join #tempMobile TM on TM.CampaignID = A.CampaignID                                          
     WHERE  TM.ValidEntries = 1 and    
      CAST(A.EmailID COLLATE Latin1_general_ci_ai AS VARCHAR(500))                                          
            NOT IN (SELECT CAST(                                          
                  ISNULL(Fs.[value], 'test') COLLATE                                          
                               Latin1_general_ci_ai AS                                          
                               VARCHAR(500)                                 )                    
                    FROM   #temptemplate AS Ucm2  (nolock)                                        
                           OUTER APPLY Dbo.Fn_split(Ucm2.ExclusionsNumber, ',') AS Fs                                          
                    WHERE  Ucm2.ID = A.CampaignID                          
                  AND A.ParentID = Ucm2.ParentID)                          
                                          
UPDATE A                              
SET step1=1,step1datetime=getdate(),step1recipients = B.cnt                    
FROM [dbo].UserCampaignHistory A INNER JOIN  #tempcount B                             
/*(SELECT a.campaignid as campaignid, A.Jobid,isnull(count(e.CampaignID),0) AS [RecipientsCount]                              
         FROM UserCampaignHistory A (nolock)     
    left outer join [dbo].[EmailsfiltercampaignexecutionTest2] e (nolock) on e.CampaignID=a.CampaignID     
    Where A.Jobid = @jobId    
         group by a.campaignid  , A.Jobid                            
 ) B*/                              
ON A.[campaignid] = B.[campaignid] and A.Jobid = @JobId    
  
UPDATE A                              
SET step1=1,step1datetime=getdate()  
FROM [dbo].UserCampaignHistory A where A.Jobid = @JobId   
                                               
     ---------------------------------Send Notification mail --------------------                                          
     INSERT INTO Getbatchrecord                                          
       (                                          
         [User_id],                   
         RandNum                                          
       )                                          
     SELECT  TC.ParentID,                           
            TC.CampaignID                                          
     FROM    #tempCount TC     
    -- WHERE  TM.ValidEntries = 1       
        
 Select BatchID,[User_id] ParentID,RandNum CampaignID into #Batch from Getbatchrecord Gbr                                     
 Order by gbr.BatchID    
                                               
     DELETE Kd                                          
     FROM   Getbatchrecord Kd         
     Inner join    #Batch B on B.BatchId = Kd.BatchID                                  
                                                    
     INSERT INTO Batchemail_infos                                          
       (                                          
         -- ID -- this column value is auto-generated                                          
         BatchID,                                          
         UserID,                                          
         SenderName,                                          
         [Message],                                          
       TotalRecords,                                          
         TotalProcessed,                                          
         ProcessTable,                                          
         IsProcess,                                          
         Priority_Level,                                          
         BatchInsertTime,                                          
         BatchProcessTime,             
         ScheduledDate,                                          
         ScheduledTime,                                          
         TemplateID,                                          
         [Route],                                          
         PageName,                                          
         IsScheduled,                                          
         Email_Subject,                          
         ReplyTo,                                          
         Amount,                                          
         Currency                                          
       )                                          
     SELECT B.BatchId,                                          
            335,                                   
            Ucm.NotificationMail,                                          
            case when tm.validentries=1 then 'Hold tight ! Your campaign "'                                          
            + Ucm.CampaignName + '" scheduled for '                                          
            + CAST(GETDATE() AS VARCHAR(50))                +                                          
            ' is executing. We shall further notify you when the execution completes' else 'Oops, you don''t have sufficient mail credits to run your mail campaign "'    
             + Ucm.CampaignName + '" scheduled for '                                    
             + Cast(Getdate() AS VARCHAR(50))                                    
             + '. Pl refill your credit balance & rerun the campaign ' end,                                          
            1,                                          
            0,                                          
          0,                                          
            0,                                          
            1,                                          
            GETDATE(),                                          
            GETDATE(),                                          
            GETDATE(),                                          
          GETDATE(),                                          
            0,                                          
            0,                                          
            0,                                          
            0,                                          
            case when tm.ValidEntries=1 then 'Campaign execution alert' else 'Failure: Your campaign "' +ucm.CampaignName + '" failed due to insufficient credits' end,                                          
            'contactus@kit19.com',                                          
            0,                                          
            0                                   
            FROM   #tempcount Tt                                   
            INNER JOIN Usercampaignmaster AS Ucm   (nolock)                                       
                 ON  Ucm.ID = Tt.CampaignID                           
                 AND Ucm.ParentID = Tt.ParentID                                          
                 --AND Ucm.IsActive = 1                                          
                 inner join #tempMobile tm on tm.CampaignID=tt.CampaignID     
                 Inner join #Batch B on B.CampaignId = Tt.CampaignId    
     /*WHERE  EmailID <> ''                                          
       GROUP BY                                          
            Ucm.NotificationMail,                                          
            Ucm.MailReplyTo,                                          
            Ucm.CampaignName*/                               
                                               
     INSERT INTO Clientemails                                          
       (                                          
         -- Id -- this column value is auto-generated                                          
         GUID,                                          
         Email_Id,                                          
         SentDateTime,                                          
         UserId,                                          
         ReplyTo,                                          
         [Status],                                          
         BatchID,                                          
         [Message]                                          
       )                         
     SELECT NEWID(),                                          
            Ucm.NotificationMail,                                          
            GETDATE(),                                          
            335,                                          
            'contactus@kit19.com',                                          
            '',                                          
            B.BatchId,                                
            case when tm.validentries=1 then 'Hold tight ! Your campaign "'                                          
            + Ucm.CampaignName + '" scheduled for '                                          
            + CAST(GETDATE() AS VARCHAR(50))                +                                          
            ' is executing. We shall further notify you when the execution completes' else 'Oops, you don''t have sufficient mail credits to run your mail campaign "'    
             + Ucm.CampaignName + '" scheduled for '                                    
             + Cast(Getdate() AS VARCHAR(50))                                    
             + '. Pl refill your credit balance & rerun the campaign ' end                                          
     FROM   #tempcount Tt                                          
     INNER JOIN Usercampaignmaster AS Ucm   (nolock)                                       
                 ON  Ucm.ID = Tt.CampaignID                                          
                 AND Ucm.ParentID = Tt.ParentID                       
                 --AND Ucm.IsActive = 1                                         
                 inner join #tempMobile tm on tm.CampaignID=tt.CampaignID      
                 Inner join #Batch B on B.CampaignID = Tt.CampaignID    
     /*WHERE  EmailID <> ''                                          
     GROUP BY                                          
            Ucm.NotificationMail,                                          
            Ucm.MailReplyTo,                                          
            Ucm.CampaignName*/                          
                                               
     INSERT INTO Emailsfilter                
       (                                          
         Mail_GUID,                                          
         -- Mail_ID -- this column value is auto-generated                                          
         Mail_FromEmail,                                          
         Mail_ToEmail,                                          
         Mail_Subject,                                          
         Mail_TempleteName,                                          
         Messages,                                          
         Mail_InsertedDate,                                          
         Mail_UserID,                                          
         ReplyTo,                                          
         Mail_BatchID,                                          
         Mail_Priority,                        
         Mail_ScheduleDate,                                          
         Mail_Attechement,                                          
         Mail_TempleteBody,                                          
         IsMonitor                                          
       )                                          
     SELECT NEWID(),                                          
            'contactus@email19.in',                                          
            ucm.NotificationMail,                                          
            'Campaign execution alert',                                          
            '',                                          
            case when tm.validentries=1 then 'Hold tight ! Your campaign "'                                          
            + Ucm.CampaignName + '" scheduled for '                                          
            + CAST(GETDATE() AS VARCHAR(50))                +                                          
            ' is executing. We shall further notify you when the execution completes' else 'Oops, you don''t have sufficient mail credits to run your mail campaign "'    
             + Ucm.CampaignName + '" scheduled for '                                    
             + Cast(Getdate() AS VARCHAR(50))                                    
             + '. Pl refill your credit balance & rerun the campaign ' end,                                
            GETDATE(),                                          
            335,                                          
            'contactus@kit19.com',                                          
            B.BatchId,                      
            1,                                          
            GETDATE(),                                          
            0,                                     
            '',                                          
            1                  
     FROM   #tempcount Tt                                          
                       INNER JOIN Usercampaignmaster AS Ucm  (nolock)                                        
                            ON  Ucm.ID = Tt.CampaignID                                          
                            AND Ucm.ParentID = Tt.ParentID                                          
                            --AND Ucm.IsActive = 1     
                            inner join #tempMobile tm on tm.CampaignID=tt.CampaignID                                         
                            Inner join #Batch B on B.CampaignID = Tt.CampaignID    
               /* WHERE  EmailID <> ''                                          
                GROUP BY                                          
                       Ucm.NotificationMail,                                          
                       Ucm.CampaignName,                                          
                       Ucm.MailReplyTo                                          
            ) A */                                         
                                                    
      --      update EmailsFilter set EmailsFilter.Mail_Priority=2                                        
      --from   EmailsFilter inner join CustomerEmail on  EmailsFilter.Mail_ToEmail=CustomerEmail.Email                                                        
                                               
     INSERT INTO Mailcreditdetails                                          
       (                                          
         ID,                                          
         -- Credit_ID -- this column value is auto-generated                                          
         M_ID,                                          
      FromUser_ID,                                          
      [User_ID],                                          
         Debits,                                          
         Credits,                                          
         Balance,                                          
         Validity,                                          
         Default_Credit,                                          
         FromDate,               
         ToDate,                                          
         DateCreated,                                          
         DateUpdated,                                          
         EmpUpdated,                                          
         MachineName,                                          
         LastModified,                                          
         typecredit                                          
       )                                          
     SELECT NEWID(),                                          
            10001,                                          
            335,                                          
            335,                                          
            COUNT(*),                                          
            0,                                          
            (                                          
                SELECT TOP 1 Mcd.Balance                                          
                FROM   Mailcreditdetails AS Mcd  (nolock)                                        
                WHERE  Mcd.[User_ID] = 335                                          
                ORDER BY                                          
                       Mcd.Credit_ID DESC                                          
            ) - COUNT(*),                                          
            99999,                                          
            0,              
            GETDATE(),                                          
            GETDATE(),                                          
            GETDATE(),                                          
            GETDATE(),                                          
            'Campaign Exec',                                          
            '',                                          
            GETDATE(),                                          
0                                          
     FROM   #tempcount Tt                                          
                       INNER JOIN Usercampaignmaster AS Ucm   (nolock)                                       
                      ON  Ucm.ID = Tt.CampaignID                                          
                            AND Ucm.ParentID = Tt.ParentID                                          
                            --AND Ucm.IsActive = 1      
                            --inner join #tempMobile tm on tm.CampaignID=tt.CampaignID                                        
               /* WHERE  EmailID <> ''                                          
                GROUP BY                                          
                       Ucm.NotificationMail,                                          
                       Ucm.CampaignName,                                          
    Ucm.MailReplyTo                                          
            ) A  */                                        
                                               
     ---------------------------------Send Notification Mail End ----------------                                          
     DROP TABLE #tempemailid               
                                            
     DROP TABLE #temptablesearchapp                                          
                                               
     DROP TABLE #temptablesearchexc                                          
 END                                          
                                           
    --update UserCampaignExecution                                        
    --set CampaignExecutedDatetime=@CampaignStarttime,isevent=0                                        
    --            where issms=0 and isnull(isevent,0)=0            
  drop table #tempCount    
  drop table #TempTableRunningTotal    
  drop table #tempMobile       
  DROP TABLE #temptemplate       
      
  exec [Usp_userexecutecampaignmessagesmailsnewCorrected] @jobid    
  end  
  else  
  begin  
  if DATEDIFF(mi,(select Lasterrorreported from UserCampaignExecution where issms=0 and isnull(isevent,0)=0),getdate())>5  
  begin  
  declare @campaignstart datetime =(select CampaignExecutedDatetime from UserCampaignExecution where issms=0 and isnull(isevent,0)=0)  
  declare @error nvarchar(100)='Last Campaign running since ' + cast(@campaignstart as nvarchar(20))  
  exec usp_InsertCampaignError'Mail',0,@error  
  update UserCampaignExecution set Lasterrorreported=GETDATE() where issms=0 and isnull(isevent,0)=0  
  end  
  end  
  END     
    
