                  Inner join #tempMobile1 TM on TM.CampaignID = Tt.CampaignID       
                  Inner join #Batch2 B on B.CampaignId = Tt.CampaignId     
                  left join #tempmobilevirtual tmv on tt.CampaignID=tmv.CampaignID where tmv.ValidEntries is null or tmv.ValidEntries=1      
