     ParentID,                                          
     Step1,                                          
     Step2,                                      
     Step3,                                          
     IsSMS,                                          
     IsMail,                                          
     IsScheduled,                                          
     IsEventBased,                                          
     CreatedOn,    
     JobId                                      
   )                            
 SELECT DISTINCT CampaignID,                                          
    ParentID,                                          
        0,              
        0,                                          
        0,                                          
        0,                                          
        1,                                          
        1,                                          
        0,                                          
        GETDATE(),    
        @JobId                                          
 FROM   #temptemplate       
                         
 IF NOT EXISTS (                                          
        SELECT 'x'                                          
        FROM   #temptemplate                                          
    )                                          
 BEGIN                                          
     SET @Body = 'No Campaign Found'                                          
                                               
     SELECT @Body                                          
END       
