SELECT A.EmailID,                                          
            A.ParentID,                                          
            A.CampaignID,    
            A.userid                                          
            INTO     #tempIncemailid                                          
     FROM   (                                          
                SELECT Tt2.EmailID,                                          
                       Tt2.ParentID,                                          
                       Tt2.CampaignID,    
                       tt.Accountused as userid      
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid where tt2.EmailID is not null                                                            UNION                                          
                SELECT Tt2.EmailID1,                                          
                       Tt2.ParentID,                                          
           Tt2.CampaignID,tt.Accountused  as userid                                         
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid where tt2.EmailID1 is not null  
                UNION                                          
                SELECT Tt2.EmailID2,                                          
                       Tt2.ParentID,                                          
                       Tt2.CampaignID,tt.Accountused as userid                                          
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid where tt2.EmailID2 is not null       )        A      
                                                                                           
SELECT A.EmailID,                             
            A.ParentID,                                          
            A.CampaignID,    
            A.userid                                          
            INTO     #tempExcemailid                                          
     FROM   (                                          
                SELECT Tt2.EmailID,                                          
                       Tt2.ParentID,                                          
                       Tt2.CampaignID,    
                       tt.Accountused as userid      
                FROM   #temptablesearchexc Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid where tt2.EmailID is not null                                                               
                UNION                                          
                SELECT Tt2.EmailID1,                                          
                       Tt2.ParentID,                                          
           Tt2.CampaignID,tt.Accountused  as userid                                         
                FROM   #temptablesearchexc Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid where tt2.EmailID1 is not null  
                UNION                                          
                SELECT Tt2.EmailID2,                                          
                       Tt2.ParentID,                                          
                       Tt2.CampaignID,tt.Accountused as userid                                          
                FROM   #temptablesearchexc Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid where tt2.EmailID2 is not null                                )        A   
  
SELECT TI.EmailID,                                          
       TI.ParentID,                                          
