   Procedure: [dbo].[Usp_executerecipientsusercampaignSelected1]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[Usp_executerecipientsusercampaignSelected1]                        
@campaigns nvarchar(max)                      
AS                            
BEGIN                            
 DECLARE @Body VARCHAR(500)                            
 DECLARE @LastExecutedTime datetime =(select Top 1 CampaignExecutedDatetime from UserCampaignExecution where issms=1 order by id desc)                                  
 SELECT A.campaignid,                            
        A.parentid,                            
        A.applicabilty,                            
        A.applicabiltygrouplist,                            
        A.exclusionsgrouplist,                            
        A.notificationmail,                            
        A.exclusionsnumber,                            
        A.exclusions,                            
        A.inclusionsnumber,                            
        A.accountused,                            
        A.senderid,                            
        A.[message],                            
        A.templateid,                            
        A.templategroupid,                            
        A.isunicode                            
                                    
                                    
                                    
        INTO #temptemplate                            
 FROM   (                            
            SELECT Ucm.id      AS CampaignID,                            
                   Ucm.parentid,                            
                   Fs.[value]  AS Applicabilty,                            
                   0           AS ApplicabiltyGroupList,                            
                   0           AS ExclusionsGroupList,                            
                   Ucm.notificationmail,                            
                   Ucm.exclusionsnumber,                            
                   0           AS Exclusions,                            
                   Ucm.inclusionsnumber,                            
                   Ucm.accountused,                            
                   Ucm.senderid,                            
                   Ucm.[message],                            
                   Ucm.templateid,                            
                   Ucm.templategroupid,                            
                   Ucm.isunicode                            
            FROM   usercampaignmaster Ucm  (nolock)                          
                   OUTER APPLY dbo.Fn_split(Ucm.applicabilty, '#') AS Fs                            
            WHERE  ucm.ID in (select value from dbo.fn_Split(@campaigns,','))                    
            --Ucm.isscheduled = 1                            
            --       AND Ucm.mailreplyto = ''                            
            --       AND   Ucm.nextexecutedatetime between @LastExecutedTime and getdate()                          
            --       AND DATEDIFF(                            
            --               minute,                            
            --               GETDATE(),                            
            --               CASE                             
            --                    WHEN Ucm.isneverexpire = 1 THEN DATEADD(DAY, 1, GETDATE())                            
            --                    ELSE ISNULL(Ucm.expirydate, GETDATE())                            
            --               END                            
            --           ) > 0                            
            --       AND DATEDIFF(minute, GETDATE(), ISNULL(Ucm.startdate, GETDATE()))                            
                                                   
                                                   
                                                   
            --           < 0                            
                   AND Ucm.isactive = 1                            
                                        
                                        
                                       
            UNION ALL                            
                                        
                                    
                                        
            SELECT Ucm.id      AS CampaignID,          
                   Ucm.parentid,                            
                   0           AS Applicabilty,                            
         Fs.[value]  AS ApplicabiltyGroupList,                            
                   0           AS ExclusionsGroupList,                            
                 Ucm.notificationmail,                            
                   Ucm.exclusionsnumber,                            
                   0           AS Exclusions,                            
                   Ucm.inclusionsnumber,                            
                   Ucm.accountused,                            
     Ucm.senderid,                            
                   Ucm.[message],                            
                   Ucm.templateid,                            
                   Ucm.templategroupid,                            
                   Ucm.isunicode                            
            FROM   usercampaignmaster Ucm (nolock)                           
                   OUTER APPLY dbo.Fn_split(Ucm.applicabiltygrouplist, '#') AS                             
            Fs                            
            WHERE  ucm.ID in (select value from dbo.fn_Split(@campaigns,','))                    
            --Ucm.isscheduled = 1                            
            --       AND Ucm.mailreplyto = ''                            
            --       AND   Ucm.nextexecutedatetime between @LastExecutedTime and getdate()                          
            --       AND DATEDIFF(                            
            --               minute,                            
            --               GETDATE(),                            
            --           CASE                             
            --                    WHEN Ucm.isneverexpire = 1 THEN DATEADD(DAY, 1, GETDATE())                            
            --                    ELSE ISNULL(Ucm.expirydate, GETDATE())                            
            --               END                            
            --           ) > 0                            
            --       AND DATEDIFF(minute, GETDATE(), ISNULL(Ucm.startdate, GETDATE()))                            
                                                   
                                        
                                                   
            --           < 0                            
                   AND Ucm.isactive = 1                            
                                        
                                        
                                        
            UNION ALL                            
                                        
                                        
                                        
            SELECT Ucm.id      AS CampaignID,                            
                   Ucm.parentid,                            
                   0      AS Applicabilty,                            
                   0           AS ApplicabiltyGroupList,                            
                   Fs.[value]  AS ExclusionsGroupList,                            
                   Ucm.notificationmail,                            
                   Ucm.exclusionsnumber,                            
                   0           AS Exclusions,                            
                   Ucm.inclusionsnumber,                            
                   Ucm.accountused,                            
                   Ucm.senderid,                            
                   Ucm.[message],                            
                   Ucm.templateid,                            
                   Ucm.templategroupid,                            
                   Ucm.isunicode                          
            FROM   usercampaignmaster Ucm   (nolock)                         
                   OUTER APPLY dbo.Fn_split(Ucm.exclusionsgrouplist, '#') AS                             
            Fs                            
            WHERE  ucm.ID in (select value from dbo.fn_Split(@campaigns,','))                    
            --Ucm.isscheduled = 1                            
            --       AND Ucm.isactive = 1                            
            --       AND Ucm.mailreplyto = ''                            
            --       AND   Ucm.nextexecutedatetime between @LastExecutedTime and getdate()                          
            --       AND DATEDIFF(                            
            --               minute,                            
           --               GETDATE(),                            
            --               CASE                             
            --                    WHEN Ucm.isneverexpire = 1 THEN DATEADD(DAY, 1, GETDATE())                            
            --                    ELSE ISNULL(Ucm.expirydate, GETDATE())                            
            --               END                            
            --           ) > 0                            
            --       AND DATEDIFF(minute, GETDATE(), ISNULL(Ucm.startdate, GETDATE()))                            
                   
                                                   
                                                   
            --           < 0                            
                                        
                                        
                                        
            UNION ALL                            
                  
                                        
                                        
            SELECT Ucm.id      AS CampaignID,                            
                   Ucm.parentid,                            
                   0           AS Applicabilty,                            
                   0           AS ApplicabiltyGroupList,                            
         0           AS ExclusionsGroupList,                            
                   Ucm.notificationmail,                            
                   Ucm.exclusionsnumber,                            
                   Fs.[value]  AS Exclusions,                            
                   Ucm.inclusionsnumber,                            
                   Ucm.accountused,                            
                   Ucm.senderid,                            
                   Ucm.[message],                            
                   Ucm.templateid,                            
                   Ucm.templategroupid,                            
                   Ucm.isunicode                            
            FROM   usercampaignmaster Ucm  (nolock)                          
                   OUTER APPLY dbo.Fn_split(Ucm.exclusions, '#') AS Fs                            
            WHERE  ucm.ID in (select value from dbo.fn_Split(@campaigns,','))                    
            --Ucm.isscheduled = 1                            
            --       AND Ucm.isactive = 1                            
            --       AND Ucm.mailreplyto = ''                            
            --       AND   Ucm.nextexecutedatetime between @LastExecutedTime and getdate()                           
            --       AND DATEDIFF(                            
            --               minute,                            
            --               GETDATE(),                            
            --               CASE                             
            --                    WHEN Ucm.isneverexpire = 1 THEN DATEADD(DAY, 1, GETDATE())                            
            --                    ELSE ISNULL(Ucm.expirydate, GETDATE())                            
            --               END                            
            --           ) > 0                            
          --       AND DATEDIFF(minute, GETDATE(), ISNULL(Ucm.startdate, GETDATE()))                            
                                                   
                                                   
                                                   
            --           < 0                            
        ) A                            
             
                             
                             
if OBJECT_ID('tempdb..##campaignrun') is null        
begin        
create table ##campaignrun(date datetime,CampaignrunID bigint,                      
                           Campaignid bigint);                                            
end                             
                             
 INSERT INTO usercampaignhistory                            
   (                            
     -- ID -- this column value is auto-generated                            
                                 
                                 
                                 
     campaignid,                            
     parentid,                            
     step1,                            
     step2,                            
     step3,                           
     issms,                 
     ismail,                            
     isscheduled,                            
     iseventbased,                            
     createdon                            
   )                     
   output getdate(),inserted.id,inserted.campaignid into ##campaignrun                        
 SELECT DISTINCT campaignid,                            
        parentid,                            
        0,                            
        0,                            
   0,                            
        1,                            
        0,                            
        1,                         
        0,                            
        GETDATE()                            
 FROM   #temptemplate                            
                             
                             
                             
                             
                             
                             
                             
 DELETE                             
 FROM   #temptemplate                            
 WHERE  accountused IN (SELECT Ud.[user_id]                            
                        FROM   user_detail AS Ud                            
                        WHERE  Ud.[status] = 0)                            
                             
                             
                             
                             
                             
                             
                             
 IF NOT EXISTS (                            
        SELECT 'x'                            
