 ELSE                            
 BEGIN                            
     CREATE TABLE #tempapplicability                            
     (                            
      searchid       BIGINT,                            
      parentid       BIGINT,                            
      campaignid     BIGINT                            
     )                            
                                 
                                 
                                 
                                 
                             
                                 
                                 
     CREATE TABLE #tempapplicabilitygroups                            
     (                            
      groupid        BIGINT,                        
      parentid       BIGINT,                            
      campaignid     BIGINT                            
     )                            
                                 
                                 
                                 
                                 
                                 
                                 
                                 
     CREATE TABLE #tempapplicabilitylists                            
     (                            
      listid         BIGINT,                            
      parentid       BIGINT,                            
      campaignid     BIGINT                            
   )                            
                                 
                                 
                                 
                                 
                                 
                                 
                                 
     INSERT INTO #tempapplicability                            
       (                            
         searchid,                            
         parentid,                            
         campaignid                            
       )             
     SELECT Tt.applicabilty,                            
            Tt.parentid,                            
            Tt.campaignid                            
     FROM   #temptemplate Tt                            
                                 
                                 
                                 
                                 
                                 
                                 
                                 
     INSERT INTO #tempapplicabilitygroups                            
       (                            
         groupid,                            
         parentid,                            
         campaignid                            
       )                    
     SELECT Tt.applicabiltygrouplist,                            
            Tt.parentid,                            
            Tt.campaignid                            
     FROM   #temptemplate Tt                            
                                 
                                 
                                 
                                 
                           
                                 
                                 
     INSERT INTO #tempapplicabilitylists                            
       (                            
         listid,                            
         parentid,                            
         campaignid                            
       )                            
     SELECT Tt.applicabiltygrouplist,                            
            Tt.parentid,                            
   Tt.campaignid                            
     FROM   #temptemplate Tt                            
                                 
                                 
                                 
                                 
                                 
                                 
                                 
     CREATE TABLE #tempexclusion                            
     (                            
      searchid       BIGINT,                            
      parentid       BIGINT,                            
      campaignid     BIGINT                            
     )                            
                                 
                                 
                                 
                                 
                                 
                                 
                                 
     CREATE TABLE #tempexclusiongroups                            
     (                            
      groupid        BIGINT,                            
     parentid       BIGINT,                            
      campaignid     BIGINT                            
     )                            
                                 
                                 
           
                                 
                                 
                                 
                                 
     CREATE TABLE #tempexclusionlists                            
     (                            
      listid         BIGINT,                            
      parentid       BIGINT,                            
      campaignid     BIGINT                            
     )                            
                                 
                                 
                                 
                                 
                                 
                               
                                 
     INSERT INTO #tempexclusion                            
       (                            
      searchid,                            
         parentid,                            
