     DROP TABLE #tempapplicabilitylists                            
                                 
                                 
                                 
                                 
                                 
                                 
                                 
     SELECT A.mobileno,                            
            A.parentid,                            
            A.campaignid                            
                                        
                                        
                             
            INTO     #tempmobileno                            
     FROM   (                            
   SELECT Tt2.mobileno,                            
                       Tt2.parentid,                          
                       Tt2.campaignid         
                FROM   #temptablesearchapp Tt2                            
                WHERE  Tt2.mobileno NOT IN (SELECT Tt.mobileno                            
                                            FROM   #temptablesearchexc Tt)                          
                       OR  Tt2.mobileno NOT IN (SELECT Tt.mobileno1                            
                                      FROM   #temptablesearchexc Tt)                            
                       OR  Tt2.mobileno NOT IN (SELECT Tt.mobileno2                            
                                                FROM   #temptablesearchexc Tt)                            
                       OR  Tt2.mobileno1 NOT IN (SELECT Tt.mobileno                            
                                                 FROM   #temptablesearchexc                             
                                                                                    
                                                                                    
                                                                                    
                                                        Tt)                            
                       OR  Tt2.mobileno1 NOT IN (SELECT Tt.mobileno1                            
                                                 FROM   #temptablesearchexc                             
                                                                                    
                                                                                    
                                                                                    
                                                        Tt)                            
                       OR  Tt2.mobileno1 NOT IN (SELECT Tt.mobileno2                            
                                                 FROM   #temptablesearchexc                             
                                                                                    
                
                                           
                  Tt)                            
                       OR  Tt2.mobileno2 NOT IN (SELECT Tt.mobileno                            
                                                 FROM   #temptablesearchexc                             
                                                                                    
                                                                                    
                                                                                    
                                                        Tt)                            
                       OR  Tt2.mobileno2 NOT IN (SELECT Tt.mobileno1                            
                                                 FROM   #temptablesearchexc                             
                                                                                    
                                                                                    
                                                                                    
                                                        Tt)                            
                       OR  Tt2.mobileno2 NOT IN (SELECT Tt.mobileno2                            
                                                 FROM   #temptablesearchexc                             
                                                                                    
                                                                                    
                                                                                    
                                                        Tt)                            
                                            
                                            
                                            
                UNION                            
                                            
                                            
                                            
                SELECT Tt2.mobileno1,                            
                       Tt2.parentid,                            
                       Tt2.campaignid                            
                FROM   #temptablesearchapp Tt2                            
             WHERE  Tt2.mobileno NOT IN (SELECT Tt.mobileno                        
                                            FROM   #temptablesearchexc Tt)                            
                       OR  Tt2.mobileno NOT IN (SELECT Tt.mobileno1                            
                                                FROM   #temptablesearchexc Tt)                            
                       OR  Tt2.mobileno NOT IN (SELECT Tt.mobileno2                            
                                                FROM   #temptablesearchexc Tt)                            
                       OR  Tt2.mobileno1 NOT IN (SELECT Tt.mobileno                            
                   FROM   #temptablesearchexc                             
                                                                                    
                                                                                    
                                                                                    
                                                        Tt)                            
                       OR  Tt2.mobileno1 NOT IN (SELECT Tt.mobileno1                            
                                                 FROM   #temptablesearchexc                             
                                                                                    
                                                                                    
                                                                                    
        Tt)                            
                       OR  Tt2.mobileno1 NOT IN (SELECT Tt.mobileno2                            
                    FROM   #temptablesearchexc                             
                                                                                    
                                                                   
                                                                                    
                                                        Tt)                            
                       OR  Tt2.mobileno2 NOT IN (SELECT Tt.mobileno                            
                                                 FROM   #temptablesearchexc                                                                                                     
                                                                                    
                                                                                    
                          Tt)                            
                       OR  Tt2.mobileno2 NOT IN (SELECT Tt.mobileno1                            
                                                 FROM   #temptablesearchexc                             
                                                                                    
                                                                                    
                                                                                    
                                                        Tt)                            
                       OR  Tt2.mobileno2 NOT IN (SELECT Tt.mobileno2                            
                                                 FROM   #temptablesearchexc                             
                                                                                    
                                                                                    
                                                                
                                                        Tt)                            
                                            
                                            
                                            
                UNION                            
                                     
                                            
                                            
                SELECT Tt2.mobileno2,                            
                       Tt2.parentid,                            
 Tt2.campaignid                            
                FROM   #temptablesearchapp Tt2                            
                WHERE  Tt2.mobileno NOT IN (SELECT Tt.mobileno                            
                                            FROM   #temptablesearchexc Tt)                            
                       OR  Tt2.mobileno NOT IN (SELECT Tt.mobileno1                            
                       FROM   #temptablesearchexc Tt)                            
                       OR  Tt2.mobileno NOT IN (SELECT Tt.mobileno2                            
                                                FROM   #temptablesearchexc Tt)                            
                       OR  Tt2.mobileno1 NOT IN (SELECT Tt.mobileno                            
                                                 FROM   #temptablesearchexc                             
                                                                                    
                                                                                    
                                                                                    
                                                        Tt)                            
                       OR  Tt2.mobileno1 NOT IN (SELECT Tt.mobileno1                            
                                                 FROM   #temptablesearchexc                             
                                                                                    
                                                                                    
                                            
                                                        Tt)                            
                       OR  Tt2.mobileno1 NOT IN (SELECT Tt.mobileno2                            
                                                 FROM   #temptablesearchexc                             
                                                           
                                                                                    
                                                                                    
                                                        Tt)                            
                       OR  Tt2.mobileno2 NOT IN (SELECT Tt.mobileno                            
                                                 FROM   #temptablesearchexc                             
                                                                      
                                                                                    
                                                                                    
                                                        Tt)                            
                       OR Tt2.mobileno2 NOT IN (SELECT Tt.mobileno1                            
                                                 FROM   #temptablesearchexc                             
                                       
                                                                                    
                                                                                    
                                                        Tt)                            
                       OR  Tt2.mobileno2 NOT IN (SELECT Tt.mobileno2                            
                                                 FROM   #temptablesearchexc                             
                                                                                    
                                                                                    
                                                                                    
                                                        Tt)                            
            )        A                      
                                 
                                 
                                 
                                 
                                 
                                 
                                 
     --  WHERE  ISNULL(NULLIF(CAST(A.MobileNo AS BIGINT), ''), 0) <> 0                            
                                 
                                 
                                 
     INSERT INTO usercampaignexecutionhistory                            
       (          
         -- ID -- this column value is auto-generated                            
                                     
                                     
                                     
         campaignid,                            
         executiontime,                            
         isrecipients,                            
         parentid                            
       )                            
     SELECT DISTINCT A.campaignid,                            
            GETDATE(),                            
            1,                            
            A.parentid              
     FROM   (                            
                SELECT mobileno,                            
                       parentid,                            
                       campaignid                            
                FROM   #tempmobileno                            
                WHERE  mobileno <> ''                            
                                            
                                            
                                            
                UNION                            
                                            
                                            
                                        
                SELECT CAST(Fs.[value] COLLATE latin1_general_ci_ai AS VARCHAR(500)),                            
                       Ucm.parentid,                            
                       Ucm.id                            
                FROM   usercampaignmaster AS Ucm  (nolock)                          
                       OUTER APPLY dbo.Fn_split(Ucm.inclusionsnumber, ',') AS                             
                Fs                            
                WHERE  Ucm.mailreplyto = ''                            
                       AND Ucm.isactive = 1                            
                       AND  Ucm.nextexecutedatetime between @LastExecutedTime and getdate()                               
                       AND DATEDIFF(                            
                               minute,                            
                               GETDATE(),                            
                               CASE                             
                                    WHEN Ucm.isneverexpire = 1 THEN DATEADD(DAY, 1, GETDATE())                            
                                    ELSE ISNULL(Ucm.expirydate, GETDATE())                            
                               END                            
                           ) > 0                            
    AND DATEDIFF(minute, GETDATE(), ISNULL(Ucm.startdate, GETDATE()))                            
                                                       
                                                       
                                                       
                           < 0                            
            ) A                            
                                 
                                 
                                 
                                 
                                 
                                 
                                 
     INSERT INTO usercampaignexecutionrecipientsmessage                            
       (                            
         mobile,                            
         parentid,                            
         campaignid                            
       )                            
     SELECT mobileno,                            
            parentid,                            
            campaignid                            
     FROM   (                            
                SELECT mobileno,                            
                       parentid,                            
                       campaignid                            
                FROM   #tempmobileno                            
                WHERE  mobileno <> ''                            
                                            
                                            
                                            
                UNION                            
                                            
                                         
                                            
                SELECT CAST(Fs.[value] COLLATE latin1_general_ci_ai AS VARCHAR(500)),                            
                       Ucm.parentid,             
                       Ucm.id                   
                FROM   usercampaignmaster AS Ucm   (nolock)                         
                       OUTER APPLY dbo.Fn_split(Ucm.inclusionsnumber, ',') AS                             
                Fs                            
                WHERE  Ucm.mailreplyto = ''                            
                       AND Ucm.isactive = 1                            
                       AND  Ucm.nextexecutedatetime between @LastExecutedTime and getdate()                               
                       AND DATEDIFF(                            
                               minute,                            
                               GETDATE(),                            
  CASE                             
                                    WHEN Ucm.isneverexpire = 1 THEN DATEADD(DAY, 1, GETDATE())                    
                                    ELSE ISNULL(Ucm.expirydate, GETDATE())                            
                               END                            
                           ) > 0                            
                       AND DATEDIFF(minute, GETDATE(), ISNULL(Ucm.startdate, GETDATE()))                            
                                                       
                                                       
                                                       
                           < 0                            
            ) A                            
     WHERE  CAST(A.mobileno COLLATE latin1_general_ci_ai AS VARCHAR(500))                            
                   
                                        
                                        
            NOT                            
                                        
                                        
                                        
            IN (SELECT CAST(                            
                     ISNULL(Fs.[value], '0000000000') COLLATE                            
                                                       
                                                       
                                                       
                           latin1_general_ci_ai                            
                                                       
                                                       
                                                       
                           AS                            
                                                       
                                                       
                                                       
                           VARCHAR(500)                            
                       )                            
         FROM   usercampaignmaster AS Ucm2  (nolock)                          
                       OUTER APPLY dbo.Fn_split(Ucm2.exclusionsnumber, ',') AS                             
                Fs                            
                WHERE  Ucm2.id = A.campaignid                            
                       AND Ucm2.isactive = 1                            
                       AND A.parentid = Ucm2.parentid)                            
                
UPDATE A                
SET step1=1,step1datetime=getdate(),step1recipients = isnull(B.[RecipientsCount],0)            
FROM [dbo].UserCampaignHistory A INNER JOIN                 
(SELECT u.campaignid,isnull(count(ur.[campaignid]),0) AS [RecipientsCount]                
         FROM UserCampaignHistory u left outer join usercampaignexecutionrecipientsmessage ur on u.CampaignID=ur.CampaignID group by u.CampaignID                
 ) B                
ON A.[campaignid] = B.[campaignid] join ##campaignrun c on a.ID=c.CampaignrunID                 
                                
                                 
                                 
                                 
                       
                                 
                                 
     IF EXISTS (                            
            SELECT 'x'                            
            FROM   #tempmobileno                            
        )                            
     BEGIN                            
         INSERT INTO getbatchrecord                            
           (                            
             [user_id],                            
             randnum                            
           )                       
         SELECT TOP 1 parentid,                            
                mobileno                            
         FROM   #tempmobileno                            
         WHERE  mobileno <> ''                            
                                     
       
                                     
                                     
                                     
                                     
                                     
         DECLARE @Batchidmails BIGINT                            
                                     
                                     
                                     
                                     
                                     
                                     
                                     
         SELECT @Batchidmails = MAX(batchid)                            
         FROM   getbatchrecord Gbr                            
                                     
                                     
                                     
                                     
                                     
                                     
                                     
         DELETE Kd                            
         FROM   getbatchrecord Kd                            
         WHERE  Kd.batchid = @Batchidmails                            
                                     
         INSERT INTO batchemail_infos                            
           (                            
             -- ID -- this column value is auto-generated                            
                                         
                                         
                             
             batchid,                            
             userid,                            
             sendername,                            
             [message],                            
             totalrecords,                            
             totalprocessed,                            
             processtable,                            
             isprocess,                            
             priority_level,                            
             batchinserttime,                            
             batchprocesstime,                            
             scheduleddate,                            
       scheduledtime,                            
             templateid,                            
             [route],                            
             pagename,                            
             isscheduled,                            
             email_subject,                            
             replyto,                            
             amount,                            
             currency                            
           )                            
         SELECT @Batchidmails,                            
                335,                            
                Ucm.notificationmail,                            
                'Hold tight ! Your ' + CASE                             
                                            WHEN Ucm.mailreplyto <> '' THEN                             
                                                 'Mail'                            
                                            ELSE 'SMS'                            
                                       END + ' campaign '                            
                                            
                                            
                                            
                + Ucm.campaignname + ' scheduled for '                            
                                            
                                            
                                            
                + CAST(GETDATE() AS VARCHAR(50))                            
                                            
                                            
                                            
                +                            
                                            
                                            
                                            
                ' is executing. We shall further notify you when the execution completes',      
                1,                            
                0,                            
                0,                            
    0,                            
          1,                            
                GETDATE(),                            
                GETDATE(),                            
                GETDATE(),                            
                GETDATE(),                            
                0,                            
                0,                            
                0,                            
                0,                            
                'Campaign execution alert',                            
        '',                            
                0,                            
                0                            
         FROM   #tempmobileno Tt                            
                INNER JOIN usercampaignmaster AS Ucm  (nolock)                          
                     ON  Ucm.id = Tt.campaignid                            
                     AND Ucm.isactive = 1                            
                     AND Ucm.parentid = Tt.parentid                            
         WHERE  mobileno <> ''                            
         GROUP BY                            
                Ucm.notificationmail,                            
                Ucm.mailreplyto,                            
                Ucm.campaignname                            
                                     
                           
                                     
                                     
                                     
                                     
                                     
                                     
                                     
                                     
                                     
    INSERT INTO clientemails                            
           (                            
        -- Id -- this column value is auto-generated                            
                                         
                                         
                                         
             guid,                            
             email_id,                            
             sentdatetime,                            
             userid,                            
             replyto,                            
             [status],                            
             batchid,                            
             [message]                            
           )                            
         SELECT NEWID(),                            
                Ucm.notificationmail,                            
                GETDATE(),                            
                335,                            
                '',                        
                '',                            
                @Batchidmails,                            
   'Hold tight ! Your ' + CASE                             
                                            WHEN Ucm.mailreplyto <> '' THEN                             
                                                 'Mail'                            
                                            ELSE 'SMS'                            
                                       END + ' campaign '                            
                                            
                                
                                            
                + Ucm.campaignname + ' scheduled for '                            
                                            
                                            
                                            
                + CAST(GETDATE() AS VARCHAR(50))                            
                                            
                                            
                                            
                +                            
            
                                            
                                            
                ' is executing. We shall further notify you when the execution completes'                            
         FROM   #tempmobileno Tt                            
                INNER JOIN usercampaignmaster AS Ucm   (nolock)                         
                     ON  Ucm.id = Tt.campaignid                            
                     AND Ucm.isactive = 1                            
                     AND Ucm.parentid = Tt.parentid                            
         WHERE  mobileno <> ''                            
         GROUP BY                       
    Ucm.notificationmail,                            
                Ucm.mailreplyto,                            
                Ucm.campaignname                            
                                     
                                     
                                     
                                     
                                     
                                     
                                     
         INSERT INTO emailsfilter                            
           (                            
             mail_guid,                            
             -- Mail_ID -- this column value is auto-generated                            
                                         
                                         
                                         
             mail_fromemail,                            
             mail_toemail,                            
             mail_subject,                            
             mail_templetename,                            
             messages,                            
             mail_inserteddate,                            
             mail_userid,                           
             replyto,                            
             mail_batchid,                            
             mail_priority,                            
             mail_scheduledate,                            
             mail_attechement,                            
             mail_templetebody,                            
             ismonitor                            
           )                            
         SELECT NEWID(),                            
                'contactus@email19.in',                            
                A.notificationmail,                            
                'Campaign execution alert',                            
                '',                            
                'Hold tight ! Your ' + CASE                             
                                            WHEN A.mailreplyto <> '' THEN                             
                                                 'Mail'                            
                                            ELSE 'SMS'                            
                                       END         
                                            
                                            
                                            
                + ' campaign '                            
                                            
                                            
                                            
                + A.campaignname + ' scheduled for '                            
                                            
                                            
                                            
                + CAST(GETDATE() AS VARCHAR(50))                            
                                            
                                            
                                            
                +                            
                                        
                                            
                                            
                ' is executing. We shall further notify you when the execution completes',       
                GETDATE(),                            
                335,                            
                '',                            
                @Batchidmails,                            
                1,                            
           GETDATE(),                            
                0,                            
                '',                            
                1                            
         FROM   (                            
                    SELECT DISTINCT Ucm.campaignname,                            
                           Ucm.mailreplyto,                            
                           Ucm.notificationmail                            
                    FROM   #tempmobileno Tt                            
                           INNER JOIN usercampaignmaster AS Ucm  (nolock)                          
                                ON  Ucm.id = Tt.campaignid                            
                                AND Ucm.isactive = 1                            
                                AND Ucm.parentid = Tt.parentid                     
                    WHERE  mobileno <> ''                            
                    GROUP BY                            
                           Ucm.notificationmail,                            
                           Ucm.campaignname,                            
                           Ucm.mailreplyto                            
                ) A                            
                                     
                                     
                                     
                                     
                                     
                                     
                                     
         INSERT INTO mailcreditdetails                            
           (                            
             id,                            
             -- Credit_ID -- this column value is auto-generated                            
                                         
                                         
                         
             m_id,                            
             fromuser_id,                            
             [user_id],                            
             debits,                            
             credits,                            
             balance,                            
             validity,                            
             default_credit,                            
             fromdate,                            
             todate,                            
             datecreated,                            
             dateupdated,                            
             empupdated,                            
             machinename,                            
             lastmodified,                            
             typecredit                            
           )                            
         SELECT NEWID(),                            
                10001,                            
                335,             
                335,                            
                COUNT(*),                            
                0,                            
                (                            
                    SELECT TOP 1 Mcd.balance                            
                    FROM   mailcreditdetails AS Mcd  (nolock)                          
                    WHERE  Mcd.[user_id] = 335                            
                    ORDER BY                            
                           Mcd.credit_id DESC                      
                ) - COUNT(*),                            
                99999,                            
                0,                            
                GETDATE(),                            
                GETDATE(),                            
                GETDATE(),                            
                GETDATE(),                            
                'Campaign Exec',                            
                '',                            
                GETDATE(),                            
                0                            
         FROM   (                            
                    SELECT DISTINCT Ucm.campaignname,                            
                           Ucm.mailreplyto,                            
                           Ucm.notificationmail                            
                    FROM   #tempmobileno Tt                            
                           INNER JOIN usercampaignmaster AS Ucm  (nolock)                          
                                ON  Ucm.id = Tt.campaignid                            
                                AND Ucm.isactive = 1                            
                                AND Ucm.parentid = Tt.parentid                            
                    WHERE  mobileno <> ''                            
                    GROUP BY                            
                           Ucm.notificationmail,                            
                           Ucm.campaignname,                            
                           Ucm.mailreplyto                            
                ) A                            
     END                            
                                 
                                 
                                 
     DROP TABLE #tempmobileno                            
                                 
                                 
                            
                               
                                 
                                 
                                 
     DROP TABLE #temptablesearchapp                            
                                 
                                 
                                 
                                 
                                 
                                 
                                 
     DROP TABLE #temptablesearchexc                            
 END                            
                             
                             
                             
                             
    --update UserCampaignExecution                                    
    --set CampaignExecutedDatetime=GETDATE()                         
    --            where issms=1                                                 
 if exists(select 1 from ##campaignrun)  
   begin                
update usercampaignhistory set step1=1,step1datetime=getdate() where ID in (select campaignrunid from ##campaignrun)   
end  
   else   
  begin  
  update u set step1=1,step1datetime=getdate() from usercampaignhistory u join #temptemplate t on u.CampaignID=t.CampaignID  
  end  
                          
                             
 DROP TABLE #temptemplate                  
                           
END 


GO

/* ============================================================
   Procedure: [dbo].[Usp_executerecipientsusercampaignSelectedCorrected]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[Usp_executerecipientsusercampaignSelectedCorrected] --'650'  
@campaignstorun nvarchar(max)  
AS                                  
BEGIN                                  
 DECLARE @Body VARCHAR(500)                                  
                                
 --DECLARE @LastExecutedTime datetime =isnull((select Top 1 CampaignExecutedDatetime from UserCampaignExecution where issms=1 and isnull(isevent,0)=0 order by id desc),getdate())   
 DEclare @JobId Bigint = (Select ISNULL(MAX(JobId),0)+1 from UserCampaignHistory UCH )                           
   
 --Declare @CampaignStarttime datetime = Getdate()    
  
 if OBJECT_ID('tempdb..#temptemplate') is not null                
 Begin   
 Drop table #temptemplate   
 end        
                              
 SELECT ROW_NUMBER()Over(Order by Ucm.ID,Ucm.ParentID) AS Id,  
        ucm.id as campaignid,                                  
        ucm.parentid,                                  
        A.value as applicabilty,                                  
        Agl.value as applicabiltygrouplist,                                  
        egl.value as exclusionsgrouplist,                                  
        ucm.notificationmail,                                  
        ucm.exclusionsnumber,                                  
        e.value as exclusions,                                  
        ucm.inclusionsnumber,                                  
        ucm.accountused,                                  
        ucm.senderid,                                  
        ucm.[message],                                  
        ucm.templateid,                                  
        ucm.templategroupid,                                  
        ucm.isunicode                                  
        INTO #temptemplate                                  
 FROM   Usercampaignmaster ucm   (nolock)  
   Inner join  User_detail AS Ud  on Ud.[User_ID]  = AccountUsed and Ud.[Status] <> 0                                            OUTER APPLY Dbo.Fn_split(Ucm.Applicabilty, '#') AS A   
   OUTER APPLY Dbo.Fn_split(Ucm.ApplicabiltyGroupList, '#') AS AGL  
   OUTER APPLY Dbo.Fn_split(Ucm.ExclusionsGroupList, '#') AS  EGL   
   OUTER APPLY Dbo.Fn_split(Ucm.Exclusions, '#') AS E                                        
            WHERE Ucm.MailReplyTo = '' and ucm.ID in (select value from dbo.fn_Split(@campaignstorun,','))   
            /*and isscheduled=1                                      
                   AND Ucm.NextExecuteDateTime between @LastExecutedTime and  getdate()                               
                   AND DATEDIFF(                                        
                           Minute,                                        
                           getdate(),                                        
                           CASE                                         
                                WHEN Ucm.IsNeverExpire = 1 THEN DATEADD(DAY, 1,getdate())                                        
                                ELSE ISNULL(Ucm.ExpiryDate, getdate())                                        
                       END                                        
                       ) > 0                                        
                   AND DATEDIFF(Minute, getdate(), ISNULL(Ucm.StartDate, getdate()))  <= 0                                        
                   AND Ucm.IsActive = 1 */                                       
  
                            
                                   
 INSERT INTO usercampaignhistory                                  
   (                                  
     -- ID -- this column value is auto-generated                                  
     campaignid,                                  
     parentid,                                  
     step1,                                  
     step2,                                  
     step3,                                 
     issms,                                  
   ismail,                                  
     isscheduled,                                  
     iseventbased,                                  
     createdon,  
     JobId                                  
       
   )                          
                 
 SELECT DISTINCT campaignid,                                  
        parentid,                                  
        0,                                  
        0,                                  
        0,                                  
        1,                                  
        0,                                  
        1,                                  
        0,                                  
        GETDATE(),  
        @JobId                               
 FROM   #temptemplate                                  
                                  
  IF NOT EXISTS (                                  
        SELECT 'x'                                  
        FROM   #temptemplate                                  
    )                                  
 BEGIN                                  
     SET @Body = 'No Campaign Found'                                  
      SELECT @Body                                  
 END                                  
 ELSE                                  
 BEGIN                                  
     CREATE TABLE #temptablesearchapp                        
     (                                  
      campaignid             BIGINT,                                  
      searchid               BIGINT,                                  
      parentid         BIGINT,   
      userid           bigint,                                 
      personname             NVARCHAR(200),                                  
      companyname            NVARCHAR(200),                                  
      mobileno               NVARCHAR(200),                                  
      mobileno1              NVARCHAR(200),                                  
      mobileno2              NVARCHAR(200),                                  
      emailid                NVARCHAR(200),                                  
      emailid1               NVARCHAR(200),                                  
      emailid2               NVARCHAR(200),                                  
      city                   NVARCHAR(200),                                  
      STATE                  NVARCHAR(200),                                  
      country                NVARCHAR(200),                                  
      countrycode            NVARCHAR(200),                                  
      pincode                NVARCHAR(200),                                  
      residentialaddress     NVARCHAR(200),                                  
      officeaddress          NVARCHAR(200),                                  
      sourcename       NVARCHAR(200),                                  
      mediumname             NVARCHAR(200),                                  
      campaignname           NVARCHAR(200),                                  
      initialremarks         NVARCHAR(1000)                                  
     )                                  
                                
     CREATE TABLE #temptablesearchexc                                  
     (                                  
      campaignid             BIGINT,                                  
      searchid               BIGINT,                                  
      parentid               BIGINT,  
      userid     bigint,                   
      personname             NVARCHAR(200),                                  
      companyname            NVARCHAR(200),                
      mobileno               NVARCHAR(200),                                  
      mobileno1              NVARCHAR(200),                                  
      mobileno2              NVARCHAR(200),                                  
      emailid                NVARCHAR(200),                                  
      emailid1               NVARCHAR(200),                                  
      emailid2               NVARCHAR(200),                                  
      city                   NVARCHAR(200),                                  
      STATE                  NVARCHAR(200),                                  
      country                NVARCHAR(200),                                  
      countrycode            NVARCHAR(200),                                  
      pincode                NVARCHAR(200),                                  
      residentialaddress     NVARCHAR(200),                                  
      officeaddress          NVARCHAR(200),                                  
      sourcename             NVARCHAR(200),                                  
      mediumname             NVARCHAR(200),                                
      campaignname           NVARCHAR(200),                                  
      initialremarks         NVARCHAR(1000)                   
     )                                  
   INSERT INTO #temptablesearchapp(mobileno,CampaignID,ParentID,userid  )                                        
         Select ISNULL(Usd.MobileNumber, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed    
   FROM  #temptemplate TT  
   Inner join  Usersearchdata AS Usd  (nolock)  on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ApplicabiltyGroupList and Tt.ApplicabiltyGroupList is not null       
         union     
      select distinct A.mobileno,A.CampaignID,A.ParentID,A.userid  
        from (select f.value as mobileno,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.InclusionsNumber,',') f where isnumeric(f.value)=1 group by CampaignID,ParentID,AccountUsed,f.value ) A         
                             
   
 INSERT INTO #temptablesearchexc (mobileno,CampaignID,ParentID,userid  )            
SELECT ISNULL(Usd.Mobilenumber, ''),Tt.CampaignID, Tt.ParentID ,tt.AccountUsed FROM #temptemplate TT   Inner join   Usersearchdata AS Usd  (nolock) on Usd.ParentID =  Tt.ParentID AND Usd.ImportedListID = Tt.ExclusionsGroupList and Tt.ExclusionsGroupList is not null    
      union     
select distinct A.mobileno,A.CampaignID,A.ParentID,A.userid  
from (select f.value as mobileno,tt.campaignid,tt.parentid,tt.accountused as userid FROM  #temptemplate TT cross apply dbo.fn_Split(tt.ExclusionsNumber,',') f where isnumeric(f.value)=1 group by CampaignID,ParentID,AccountUsed,f.value ) A                 
        
 DECLARE @CountCampaign     INT = (Select MAX(Id) from #temptemplate    )                                        
                                                                                 
     DECLARE @Count INT = 1                                                                                                  WHILE (@Count <= @CountCampaign)                                  
     BEGIN                                  
           DECLARE @Applicability BIGINT,                                     
     @Exclusions BIGINT,  
                 @Parentid BIGINT,                                        
                 @Campaignid BIGINT,  
                 @userid bigint  
                     
                   
          Select @Campaignid =Campaignid, @Parentid = Parentid ,@userid=AccountUsed  
          ,@Applicability = tt.Applicabilty,@Exclusions = tt.Exclusions  
           from #temptemplate tt Where Id = @Count                    If(@Applicability is not null)  
          Begin                                 
            INSERT INTO #temptablesearchapp                                        
       (                                       
      PersonName,                                        
      CompanyName,                                        
      MobileNo,                                        
      MobileNo1,                                        
      MobileNo2,                                        
      EmailID,                                        
      EmailID1,       
      EmailID2,                                        
      Country,                                        
      [STATE],                           
      City,                                  
      PinCode,                                        
      ResidentialAddress,                                        
      OfficeAddress,                                        
      SourceName,                                        
      MediumName,                                        
      CampaignName,                                        
      InitialRemarks,                                        
      SearchID,                                        
      ParentID,                                        
      CampaignID                                        
       )                                        
     EXEC Usp_executeusersearch                                        
       @ParentId,                                        
       @Applicability,                                        
       @Campaignid  
         
           End                                   
         if(@Exclusions is not null)  
          Begin                                   
         INSERT INTO #temptablesearchexc                                        
           (                                        
             PersonName,                                        
             CompanyName,                                        
             MobileNo,                                        
             MobileNo1,                                        
  MobileNo2,                                        
             EmailID,                                        
             EmailID1,                                        
             EmailID2,                                        
             Country,                                        
             [STATE],                                        
             City,                                        
             PinCode,                                        
             ResidentialAddress,                                        
            OfficeAddress,                                        
             SourceName,                                        
             MediumName,                                        
             CampaignName,                                        
             InitialRemarks,                                        
             SearchID,                                        
             ParentID,                                        
             CampaignID                                        
    )                                        
         EXEC Usp_executeusersearch                                        
              @Parentid,                                        
              @Exclusions,                                        
              @Campaignid  
      
    END  
     SET @Count = @Count+1  
       
     END                                        
                              
                                       
                                       
                                       
     SELECT A.mobileno,                                  
            A.parentid,                                  
            A.campaignid,  
            A.userid                                  
                                            
            INTO     #tempemailid                                  
     FROM   (                                  
                SELECT Tt2.mobileno,                                  
                       Tt2.parentid,                                  
                       Tt2.campaignid,  
                       tt.Accountused as userid                                  
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                   
          WHERE NOT EXISTS (SELECT 1 FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.mobileno = Tt.mobileno OR Tt2.mobileno = Tt.mobileno1 OR Tt2.mobileno = Tt.mobileno2 ) )                        UNION                    
                    
        SELECT Tt2.mobileno1,                                        
                       Tt2.ParentID,                                        
           Tt2.CampaignID,tt.Accountused  as userid                                       
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                  
                 WHERE  NOT EXISTS (SELECT 1                                        
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.mobileno1 = Tt.mobileno OR Tt2.mobileno1 = Tt.mobileno1 OR  Tt2.mobileno1 = Tt.mobileno2)  )     
                UNION                                        
                SELECT Tt2.mobileno2,                                        
                       Tt2.ParentID,                                        
                       Tt2.CampaignID,tt.Accountused as userid                                        
                FROM   #temptablesearchapp Tt2 join #temptemplate tt on tt.CampaignID=tt2.campaignid                                        
                 WHERE  NOT EXISTS (SELECT 1                                        
                                           FROM   #temptablesearchexc Tt Where (Tt2.CampaignID = Tt.CampaignID ) AND (Tt2.mobileno2 = Tt.mobileno OR Tt2.mobileno2 = Tt.mobileno1 OR  Tt2.mobileno2= Tt.mobileno2 ) )     
           
       )        A                                        
                                    
     SELECT   
     ROW_NUMBER() Over(order by CampaignId,ParentId) Id,  
     Ucerm.CampaignID,     
     Ucerm.ParentID                               ,  
                     -- Cast(Ucerm.Messages AS VARCHAR(MAX))  AS  Messages,                                  
                     ucerm.userID,                                
                     Count(*) cnt  
                     -- Ucerm.Mail_ToEmail,                                  
   INTO   #tempCount                                  
      FROM   #tempemailid Ucerm                                  
      Group by  Ucerm.CampaignID,     
     Ucerm.ParentID ,                                  
                      Ucerm.UserID  
                                                    
        
      SELECT A.UserID,a.CampaignID, a.cnt,SUM(b.cnt) RunningTotal into #TempTableRunningTotal  
   FROM   #tempCount a join  
       #tempCount b  on a.userid=b.userid
   WHERE b.CampaignID <= a.CampaignID  
   GROUP BY A.UserID, a.CampaignID, a.cnt  
   ORDER BY a.CampaignID;  
        
   --- Calculate credits                                  
      SELECT B.UserID,   
    B.CampaignID,  
      CASE                                  
               WHEN B.Balance > B.Credits THEN 1                                  
               ELSE 0  -- Test                                  
             END AS ValidEntries                                  
      INTO   #tempMobile                                  
