                   WHERE  Ucerm.IsCompleted = 0 AND Ucm.MailReplyTo = '' and tg.TemplateID<>0                                                       and umt.IsEnquiry=0 and umt.IsLeads=0 and umt.IsList=0 and umt.IsConversion=0                             
                              
