 UPDATE Kd                    
 SET        
 Kd.[Message] = CAST(CAST(A.[Message] AS VARCHAR(MAX)) COLLATE Latin1_general_ci_ai AS VARCHAR(MAX)),  
 Kd.SenderID = CAST(CAST(A.SenderID AS VARCHAR(MAX))   
 COLLATE  Latin1_general_ci_ai AS VARCHAR(MAX)),  
 Kd.U_ID = A.AccountUsed,                    
 Kd.IsCompleted = 1,                    
 Kd.IsUniCode = A.IsUnicode,  
 kd.len=len(A.message),  
 kd.credits=case when A.isunicode=0 and len(A.message)<=160  then 1 when A.isunicode=0 and LEN(A.message)>160 then ceiling(LEN(A.message)/153) when A.IsUniCode=1 and len(A.message)<=70 then 1 else ceiling(LEN(A.message)/67) end   
 FROM   usercampaignexecutionrecipientsmessageTest2 Kd  (nolock)                   
        INNER JOIN #temptable A                    
             ON  Kd.CampaignID = A.CampaignID                    
             AND Kd.ParentID = A.ParentID                    
             AND Kd.Mobile = CAST(                    
                     CAST(A.Mobile AS VARCHAR(MAX))                    
                     COLLATE                    
                     Latin1_general_ci_ai AS                    
                     VARCHAR(MAX)                    
                 )                    
                     
