     SELECT distinct Entityname,Entityid,A.mobileno,                                              
            A.parentid,                                              
            A.campaignid,              
            A.userid                                    
            INTO     #tmpemailid                                              
     FROM   (                                              
                SELECT Entityname,Entityid,      
    Tt2.mobileno,                                              
                       Tt2.parentid,                                              
                       Tt2.campaignid,              
                      tt.Accountused as userid                                              
                FROM   #temptablesearchapp Tt2  (nolock) join #temptemplate tt  (nolock) on tt.CampaignID=tt2.campaignid                               
          WHERE NOT EXISTS (SELECT 1 FROM   #temptablesearchexc Tt  (nolock) Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.mobileno = Tt.mobileno OR Tt2.mobileno = Tt.mobileno1 OR Tt2.mobileno = Tt.mobileno2 ) )                              
    UNION                 
                             
        SELECT Entityname,Entityid,Tt2.mobileno1,                                                    
                       Tt2.ParentID,               
           Tt2.CampaignID,tt.Accountused  as userid                                                   
                FROM   #temptablesearchapp Tt2  (nolock) join #temptemplate tt  (nolock) on tt.CampaignID=tt2.campaignid                              
                 WHERE  NOT EXISTS (SELECT 1                                                    
                                           FROM   #temptablesearchexc Tt  (nolock) Where (Tt2.CampaignID = Tt.CampaignID ) AND ( Tt2.mobileno1 = Tt.mobileno OR Tt2.mobileno1 = Tt.mobileno1 OR  Tt2.mobileno1 = Tt.mobileno2)  )                 
                UNION                                                 
                SELECT Entityname,Entityid,Tt2.mobileno2,                                                    
                       Tt2.ParentID,                                                    
                       Tt2.CampaignID,tt.Accountused as userid                                                    
                FROM   #temptablesearchapp Tt2 (nolock) join #temptemplate tt  (nolock) on tt.CampaignID=tt2.campaignid                                                    
                 WHERE  NOT EXISTS (SELECT 1                                                    
                                           FROM   #temptablesearchexc Tt  (nolock) Where (Tt2.CampaignID = Tt.CampaignID ) AND (Tt2.mobileno2 = Tt.mobileno OR Tt2.mobileno2 = Tt.mobileno1 OR  Tt2.mobileno2= Tt.mobileno2 ) )                 
                       
       )        A     where nullif(A.mobileno,'') is not null                                               
                                   
                
