 BEGIN               
   Print 'Collecting enq added data'          
 select * into #UserEnquiry from UserEnquiry ue  (nolock) WHERE  ue.CreatedDate Between @LastExecutedTime and @CampaignStarttime              
                              
     SELECT 'Enquiry' as EntityName, tt.Mobileno,                              
            tt.ParentID,            
            tid.campaignid , tt.EnquiryID as EntityID                            
           INTO #TempEnq                              
   FROM   (               
      SELECT  ue.MobileNo,                              
        ue.ParentID,                              
        ue.CreatedDate , ue.EnquiryID                              
                FROM   #UserEnquiry AS ue                            
    Inner  join (Select Distinct CampaignID,ParentID from #TempTemplate T  (nolock) WHERE  EventsName = 'ENQADD') ucs on ucs.ParentID = ue.ParentID                 
                WHERE  ue.CreatedDate Between @LastExecutedTime and @CampaignStarttime              
                      
    UNION                              
                SELECT ue.MobileNo1,                              
        ue.ParentID,                      
        ue.CreatedDate, ue.EnquiryID                               
                FROM   #UserEnquiry AS ue                 
    Inner  join (Select Distinct CampaignID,ParentID from #TempTemplate T  (nolock) WHERE  EventsName = 'ENQADD') ucs on ucs.ParentID = ue.ParentID                              
                WHERE  ue.CreatedDate Between @LastExecutedTime and @CampaignStarttime                            
    UNION       
                SELECT ue.MobileNo2,                              
                       ue.ParentID,                              
                       ue.CreatedDate ,ue.EnquiryID                              
                FROM   #UserEnquiry AS ue                              
                Inner  join (Select Distinct CampaignID,ParentID from #TempTemplate T  (nolock) WHERE  EventsName = 'ENQADD') ucs on ucs.ParentID = ue.ParentID                 
    WHERE  ue.CreatedDate Between @LastExecutedTime and @CampaignStarttime                            
       ) tt                      
    Inner join #tmpemailid tid on tid.Entityid=tt.EnquiryID and tid.Entityname='Enquiry'      
 join #TempTemplate T  (nolock) on t.CampaignID=tid.campaignid and  EventsName = 'ENQADD'      
 --tid.mobileno = (CAST(tt.MobileNo COLLATE Latin1_General_CI_AI AS VARCHAR(50)))              
 WHERE tt.MobileNo <> ''                              
                                 
