     DROP TABLE #TempLeads                              
 END          
       
IF EXISTS( SELECT * FROM   #TempTemplate WHERE  EventsName = 'FOLDUE' )                                
 BEGIN                      
  
  Print 'Collecting followup due data'
  select * into #UserFolLeads from UserLeads ue (nolock) WHERE ue.FollowupDate Between @LastExecutedTime and @CampaignStarttime                    
                
                           
     SELECT 'Lead' as Entityname,tt.Mobileno,                                
            tt.ParentID,                                
            tid.CampaignID,tt.EntityID                                
            INTO #TempFolLeads                                
     FROM   (                                
    SELECT ue.MobileNo,                                
                       ue.ParentID,                                
                       ue.CreatedOn  AS CreatedDate,ue.ID as EntityID                                
                FROM   #UserFolLeads     AS ue                                
    Inner  join (Select Distinct CampaignID,ParentID from #TempTemplate T  (nolock) WHERE  EventsName = 'FOLDUE') ucs on ucs.ParentID = ue.ParentID                 
                WHERE ue.FollowupDate Between @LastExecutedTime and @CampaignStarttime                                
    UNION                                
                SELECT ue.MobileNo1,                                
                       ue.ParentID,                                
       ue.CreatedOn  AS CreatedDate,ue.ID as EntityID                                
                FROM   #UserFolLeads     AS ue                 
    Inner  join (Select Distinct CampaignID,ParentID from #TempTemplate T  (nolock) WHERE  EventsName = 'FOLDUE') ucs on ucs.ParentID = ue.ParentID                              
                WHERE   ue.FollowupDate Between @LastExecutedTime and @CampaignStarttime                                
                UNION                                
                SELECT ue.MobileNo2,                                
                       ue.ParentID,                                
                       ue.CreatedOn  AS CreatedDate,ue.ID as EntityID                                
                FROM   #UserFolLeads     AS ue                                
                Inner  join (Select Distinct CampaignID,ParentID from #TempTemplate T  (nolock)  WHERE  EventsName = 'FOLDUE') ucs on ucs.ParentID = ue.ParentID                 
    WHERE   ue.FollowupDate Between @LastExecutedTime and @CampaignStarttime                    
            ) tt                     
   Inner join #tmpemailid tid on tid.Entityid=tt.EntityID and tid.Entityname='Lead'      
   join #TempTemplate T  (nolock) on t.CampaignID=tid.campaignid and  EventsName = 'FOLDUE'      
   --tid.mobileno = (CAST(tt.MobileNo COLLATE Latin1_General_CI_AI AS VARCHAR(50)))                           
  WHERE  isnull(tt.MobileNo,'') <> ''                 
                  
  drop table #UserFolLeads                               
                                
     INSERT INTO UserCampaignExecutionHistory                                
     (                                
         -- ID -- this column value is auto-generated                                
         CampaignID,                                
         ExecutionTime,                                
         NoOfRecipients,                                
         Response,                                
         BatchID,                                
         IsRecipients,                                
         IsMessages,                                
         IsExecuted,                                
         ParentID,                
         Jobid                                
       )                                
     SELECT DISTINCT tt.CampaignID,                     
            GETDATE(),                                
            0,                                
            NULL,                
            0,                                
            1,                                
            0,                                
            0,                                
            tt.ParentID ,                
            @JobId                               
     FROM   #TempFolLeads tt                                
     WHERE  tt.MobileNo <> ''                  
                     
      INSERT INTO usercampaignexecutionrecipientsmessageTest2                                
     (                           
  entityname,entityid,           
         mobile,                                               
         parentid,                                                
         campaignid,                
         u_id,                
            JobId                            
       )                                                
     SELECT entityname,entityid,tt.MobileNo,                
            tt.ParentID,                                
            tt.CampaignID,                
   UAD.AccountUsed,                
            @JobId                  
     FROM   #TempFolLeads     tt                
  Inner join #UserAccountDetails UAD  (nolock) on UAD.CampaignID = tt.CampaignID and UAD.ParentID = tt.ParentID where tt.MobileNo is not null and tt.MobileNo<>''                
                       
                     
     DROP TABLE #TempFolLeads                                
 END                                
                           
              
IF EXISTS( SELECT * FROM   #TempTemplate WHERE  EventsName = 'FOLADD' )                              
BEGIN                  
Print 'Collecting followup added data'              
select ue.* into #userleadsupdated FROM   UserLeads AS ue (nolock)  INNER JOIN LeadInteractionHistory AS lih (nolock) ON  lih.LeadNo = ue.LeadNo AND lih.ParentID = ue.ParentID WHERE  lih.CreatedOn Between @LastExecutedTime and @CampaignStarttime         
  
    
      
       
              
                          
     SELECT 'Lead' as EntityName,tt.mobileno,                              
            tt.ParentID,                              
            tid.CampaignID AS CampaignID,tt.id as Entityid                              
 INTO #TempFollowUp                              
     FROM   (                              
                SELECT ue.MobileNo,                              
                       ue.ParentID,                              
                       lih.CreatedOn  AS CreatedDate,ue.ID                              
                FROM   #userleadsupdated      AS ue    (nolock)                           
                       INNER JOIN LeadInteractionHistory AS lih  (nolock) ON  lih.LeadNo = ue.LeadNo AND lih.ParentID = ue.ParentID              
        Inner  join (Select Distinct CampaignID,ParentID from #TempTemplate T  (nolock)  WHERE  EventsName = 'FOLADD') ucs on ucs.ParentID = lih.ParentID               
                WHERE  lih.CreatedOn Between @LastExecutedTime and @CampaignStarttime                                                    
                UNION                              
                SELECT ue.MobileNo1,                              
                       ue.ParentID,                              
                       lih.CreatedOn  AS CreatedDate,ue.ID                              
                FROM   #userleadsupdated      AS ue                              
                       INNER JOIN LeadInteractionHistory AS lih  (nolock) ON  lih.LeadNo = ue.LeadNo AND lih.ParentID = ue.ParentID                              
        Inner  join (Select Distinct CampaignID,ParentID from #TempTemplate T  (nolock)  WHERE  EventsName = 'FOLADD') ucs on ucs.ParentID = lih.ParentID               
                WHERE  lih.CreatedOn Between @LastExecutedTime and @CampaignStarttime                                        
                UNION                              
                SELECT ue.MobileNo2,                              
                       ue.ParentID,                              
                       lih.CreatedOn  AS CreatedDate,ue.ID                              
                FROM   #userleadsupdated      AS ue                              
                       INNER JOIN LeadInteractionHistory AS lih  (nolock) ON  lih.LeadNo = ue.LeadNo AND lih.ParentID = ue.ParentID                              
        Inner  join (Select Distinct CampaignID,ParentID from #TempTemplate T  (nolock)  WHERE  EventsName = 'FOLADD') ucs on ucs.ParentID = lih.ParentID               
                WHERE  lih.CreatedOn Between @LastExecutedTime and @CampaignStarttime                                                                
            )tt                              
   Inner join #tmpemailid tid on tid.Entityid=tt.ID and tid.Entityname='Lead'      
   join #TempTemplate T  (nolock) on t.CampaignID=tid.campaignid and  EventsName = 'FOLADD'      
   --tid.mobileno = (CAST(tt.MobileNo COLLATE Latin1_General_CI_AI AS VARCHAR(50)))              
        WHERE  tt.MobileNo <> ''              
                      
        drop table #userleadsupdated                                                         
                              
     INSERT INTO UserCampaignExecutionHistory                              
       (                              
         -- ID -- this column value is auto-generated                              
         CampaignID,                              
         ExecutionTime,                              
         NoOfRecipients,                              
         Response,                              
         BatchID,                              
         IsRecipients,                              
         IsMessages,                              
         IsExecuted,                              
         ParentID,              
         Jobid                              
       )                              
     SELECT DISTINCT tt.CampaignID,                              
            GETDATE(),                              
            0,                              
            NULL,                              
            0,                              
            1,        
            0,                              
            0,                              
            tt.ParentID,              
            @JobId                              
     FROM   #TempFollowUp tt     (nolock)                          
