create table #EligibleCampaigns(Id int identity(1,1),Campaignid bigint,parentid bigint,accountused bigint,applicabilty bigint,exclusions bigint)        
 insert into #EligibleCampaigns(Campaignid ,parentid ,accountused ,applicabilty ,exclusions)        
 select t.Campaignid ,t.parentid ,t.accountused ,t.applicabilty ,t.exclusions from #TempTemplate t  (nolock)     
 join userenquiry u  (nolock) on t.ParentID=u.ParentID and t.EventsName='enqadd' where u.CreatedDate>@LastExecutedTime        
 union        
 select t.Campaignid ,t.parentid ,t.accountused ,t.applicabilty ,t.exclusions from #TempTemplate t  (nolock) join userleads u  (nolock) on t.ParentID=u.ParentID and t.EventsName='LEDADD' where   
 u.Createdon>@LastExecutedTime          
union        
 select t.Campaignid ,t.parentid ,t.accountused ,t.applicabilty ,t.exclusions from #TempTemplate t  (nolock) join userleads u  (nolock) on t.ParentID=u.ParentID and t.EventsName='FOLDUE' where   
 u.FollowupDate>@LastExecutedTime          
 union        
 select t.Campaignid ,t.parentid ,t.accountused ,t.applicabilty ,t.exclusions from #TempTemplate t  (nolock) join userleads u  (nolock) on t.ParentID=u.ParentID and t.EventsName='FOLADD'   
 join LeadInteractionHistory l  (nolock) on u.LeadNo=l.LeadNo and u.ParentID=l.ParentID where l.Createdon>@LastExecutedTime        
        
        
                  
 DECLARE @CountCampaign     INT = (Select MAX(Id) from #EligibleCampaigns    )                                              
                                                                                       
     DECLARE @Count INT = 1                                                                                                  WHILE (@Count <= @CountCampaign)                                        
     BEGIN                                        
           DECLARE @Applicability BIGINT,                                           
     @Exclusions BIGINT,        
                 @Parentid BIGINT,                                              
                @Campaignid BIGINT,        
                 @userid bigint        
                           
                         
          Select @Campaignid =Campaignid, @Parentid = Parentid ,@userid=AccountUsed        
          ,@Applicability = tt.Applicabilty,@Exclusions = tt.Exclusions        
           from #EligibleCampaigns tt  (nolock) Where Id = @Count                    If(@Applicability is not null)        
          Begin                                       
            INSERT INTO #temptablesearchapp                                              
       (                                             
      PersonName,                                              
      CompanyName,                                              
      MobileNo,                                              
      MobileNo1,                                              
  MobileNo2,                                              
      EmailID,                                              
      EmailID1,                                              
      EmailID2,                                              
      Country,                                              
      [STATE],                                 
      City,                                        
      PinCode,                                              
      ResidentialAddress,                                              
      OfficeAddress,                                              
      SourceName,                                              
      MediumName,                                              
      CampaignName,                                              
      InitialRemarks,                                              
      SearchID,                                              
      ParentID,                                              
      CampaignID                              
       )                                              
     EXEC Usp_executeusersearch                                              
       @ParentId,                                              
       @Applicability,                                              
       @Campaignid        
               
          
           End                                         
         if(@Exclusions is not null)        
          Begin                                         
         INSERT INTO #temptablesearchexc                                              
           (                                              
             PersonName,                                              
             CompanyName,                                              
             MobileNo,                                              
             MobileNo1,                                              
  MobileNo2,                                              
             EmailID,                                              
      EmailID1,                                              
             EmailID2,                                              
             Country,                                              
             [STATE],                                              
             City,                                              
             PinCode,                                              
             ResidentialAddress,                                              
            OfficeAddress,                                              
             SourceName,                                              
             MediumName,                                              
             CampaignName,                                              
             InitialRemarks,                                              
             SearchID,                                              
             ParentID,                                              
             CampaignID                                              
    )                                              
         EXEC Usp_executeusersearch                                              
              @Parentid,            
              @Exclusions,                                              
              @Campaignid        
            
    END        
     SET @Count = @Count+1        
             
     END                                              
             
