/* ============================================================
   Procedure: [dbo].[USP_ExecuteSequential]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE [dbo].[USP_ExecuteSequential]
AS
BEGIN
	SELECT cm.CampaignName  AS SequentialCampaignName,
	       cm.SenderID,
	       cm.[Message],
	       cm.[Time],
	       cm.Accounts      AS Account,
	       cm.IsUnicode,
	       DATEDIFF(MINute, cm.SequentialJobTime, GETDATE()) AS JobTime,
	       fs.[value]       AS CampaignName INTO #temptable
	FROM   CampaignMaster   AS cm
	       OUTER APPLY dbo.fn_Split(cm.SequentialCampaign, '#') AS fs
	WHERE  cm.IsSequential = 1
	       AND CASE 
	                WHEN cm.SequentialJobTime IS NULL THEN 0
	                ELSE DATEDIFF(MINute, cm.SequentialJobTime, GETDATE())
	           END < 5  
	
	SELECT DISTINCT 
	       cld.Mobile,
	       tt.SenderID,
	       tt.[Message],
	       tt.Account,
	       tt.IsUnicode INTO     #Temp2
	FROM   ClientLeadDetails  AS cld
	       INNER JOIN #temptable tt
	            ON  tt.CampaignName = cld.CampaignName
	WHERE  DATEDIFF(minute, cld.DateCreated, GETDATE()) <= CASE 
	                                                            WHEN (ISNULL(tt.[Time], 0) + ISNULL(tt.JobTime, 0) - 5)
	                                                                 BETWEEN 
	                                                                 -
	                                                                 5
	       AND 0 THEN 0
	           ELSE (ISNULL(tt.[Time], 0) + ISNULL(tt.JobTime, 0) -5)
END 
AND 
DATEDIFF(minute, cld.DateCreated, GETDATE()) >=
CASE 
     WHEN (ISNULL(tt.[Time], 0) + ISNULL(tt.JobTime, 0))
          BETWEEN -
          5
          AND 0 THEN 0
     ELSE (ISNULL(tt.[Time], 0) + ISNULL(tt.JobTime, 0))
END  


DECLARE @BATCHID NVARCHAR(500)                
SELECT @BATCHID = ABS(CAST(CAST(NEWID() AS VARBINARY) AS INT))   


INSERT INTO MessageSource
  (
    -- MessageSourceID -- this column value is auto-generated    
    MessageID,
    MessageBatchID,
    Mobile,
    [Message],
    M_ID,
    U_ID,
    SenderID,
    SmppID,
    ScheduleDate,
    ScheduleTime,
    MessageInsertDate,
    ScheduleTag,
    IsUniCode,
    IsDnd,
    Operator,
    Priority,
    Isallowdnd,
    userFilter
  )
SELECT DISTINCT '',
       @BATCHID,
       CAST(CAST(tt.Mobile AS DECIMAL(20))AS VARCHAR(20)),
       tt.Message,
       '',
       tt.Account,
       tt.SenderID,
       7,
       GETDATE(),
       GETDATE(),
       GETDATE(),
       '',
       tt.IsUnicode,
       0,
       'UI',
       2,
       0,
       (
           SELECT ud.userfilter
           FROM   User_Detail AS ud
           WHERE  ud.[User_ID] = tt.Account
       )
FROM   #Temp2 tt
WHERE  LEN(tt.Mobile) > 10   


INSERT INTO MESSAGEDELIVERYSTATUS
  (
    [MOBILE],
    [MESSAGE],
    [SENDERID],
    [SMPPID],
    [MESSAGEINSERTDATE],
    [PRIORITY],
    [U_ID],
    [ISUNICODE],
    [ISDND],
    [OPERATOR],
    [BATCHID],
    [ISALLOWDND]
  )
SELECT DISTINCT CAST(CAST(tt.Mobile AS DECIMAL(20))AS VARCHAR(20)),
       tt.Message,
       tt.SenderID,
       7,
       GETDATE(),
       2,
       '',
       tt.IsUnicode,
       0,
       'UI',
       @BATCHID,
       0
FROM   #Temp2 tt
WHERE  LEN(tt.Mobile) > 10 


DROP TABLE #Temp2 
DROP TABLE #temptable 
END



GO

/* ============================================================
   Procedure: [dbo].[Usp_executesmscampaignCorrected_Combined]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[Usp_executesmscampaignCorrected_Combined]                                    
AS                                    
BEGIN      
declare @maxjobid bigint = (select top 1 JobId from UserCampaignHistory UCH order by ID desc)    
declare @maxid bigint = (select top 1 Id from UserCampaignHistory UCH order by ID desc)    
if ((select Step3DateTime from UserCampaignHistory UCH where ID=@maxid) is not null)    
begin                                  
 DECLARE @Body VARCHAR(500)                                    
                                  
 DECLARE @LastExecutedTime datetime =isnull((select Top 1 CampaignExecutedDatetime from UserCampaignExecution where issms=1 and isnull(isevent,0)=0 order by id desc),getdate())     
 DEclare @JobId Bigint = (Select ISNULL(MAX(JobId),0)+1 from UserCampaignHistory UCH )                             
     
 Declare @CampaignStarttime datetime = Getdate()      
    
 if OBJECT_ID('tempdb..#temptemplate') is not null                  
 Begin     
 Drop table #temptemplate     
 end          
                                
 SELECT ROW_NUMBER()Over(Order by Ucm.ID,Ucm.ParentID) AS Id,    
        ucm.id as campaignid,                                    
        ucm.parentid,                                    
        A.value as applicabilty,                                    
        Agl.value as applicabiltygrouplist,                                    
        egl.value as exclusionsgrouplist,                                    
        ucm.notificationmail,                                    
        ucm.exclusionsnumber,                                    
        e.value as exclusions,                                    
        ucm.inclusionsnumber,                                    
        ucm.accountused,                                    
        ucm.senderid,                                    
        ucm.[message],                                    
        ucm.templateid,                                    
        ucm.templategroupid,                                    
        ucm.isunicode                                    
        INTO #temptemplate                                    
 FROM   Usercampaignmaster ucm   (nolock)    
   Inner join  User_detail AS Ud  on Ud.[User_ID]  = AccountUsed and Ud.[Status] <> 0                                            OUTER APPLY Dbo.Fn_split(Ucm.Applicabilty, '#') AS A     
   OUTER APPLY Dbo.Fn_split(Ucm.ApplicabiltyGroupList, '#') AS AGL    
   OUTER APPLY Dbo.Fn_split(Ucm.ExclusionsGroupList, '#') AS  EGL     
   OUTER APPLY Dbo.Fn_split(Ucm.Exclusions, '#') AS E                                          
            WHERE Ucm.MailReplyTo = ''  and isscheduled=1                                        
                   AND Ucm.NextExecuteDateTime between @LastExecutedTime and  getdate()                                 
                   AND DATEDIFF(                                          
                           Minute,                                          
                           getdate(),                                          
                           CASE                                           
                                WHEN Ucm.IsNeverExpire = 1 THEN DATEADD(DAY, 1,getdate())                                          
                                ELSE ISNULL(Ucm.ExpiryDate, getdate())                                          
                       END                                          
                       ) > 0                                          
                   AND DATEDIFF(Minute, getdate(), ISNULL(Ucm.StartDate, getdate()))  <= 0                                          
                   AND Ucm.IsActive = 1                                          
    
 /*(                                    
            SELECT Ucm.id      AS CampaignID,                                    
                   Ucm.parentid,                                    
                   Fs.[value]  AS Applicabilty,                       
                   0           AS ApplicabiltyGroupList,                                    
               0           AS ExclusionsGroupList,                                    
                   Ucm.notificationmail,                                    
                   Ucm.exclusionsnumber,                                    
                   0           AS Exclusions,                                    
                   Ucm.inclusionsnumber,                                    
                   Ucm.accountused,                                    
                   Ucm.senderid,                                    
                   Ucm.[message],                                    
                   Ucm.templateid,                                    
                   Ucm.templategroupid,                                    
                   Ucm.isunicode                                    
            FROM   usercampaignmaster Ucm  (nolock)                                  
                   OUTER APPLY dbo.Fn_split(Ucm.applicabilty, '#') AS Fs                                    
            WHERE  Ucm.isscheduled = 1                                    
                   AND Ucm.mailreplyto = ''                                    
                   AND   Ucm.nextexecutedatetime between @LastExecutedTime and getdate()                                  
                   AND DATEDIFF(                                    
                           minute,                                    
                           GETDATE(),                                    
                           CASE                                     
                                WHEN Ucm.isneverexpire = 1 THEN DATEADD(DAY, 1, GETDATE())                                    
                                ELSE ISNULL(Ucm.expirydate, GETDATE())                                    
                           END                                    
                       ) > 0                                    
AND DATEDIFF(minute, GETDATE(), ISNULL(Ucm.startdate, GETDATE()))                                    
                      
                                                           
                                                           
             <= 0                                    
                   AND Ucm.isactive = 1                                    
                                    
                                                
                                                
            UNION ALL                                    
                                                
                                                
                                                
            SELECT Ucm.id      AS CampaignID,                                    
                   Ucm.parentid,                                    
                   0           AS Applicabilty,                                    
                   Fs.[value]  AS ApplicabiltyGroupList,                                    
                   0           AS ExclusionsGroupList,                                   
                   Ucm.notificationmail,                                    
                   Ucm.exclusionsnumber,                                    
                   0        AS Exclusions,                                    
                   Ucm.inclusionsnumber,                                    
                   Ucm.accountused,                                    
 Ucm.senderid,                                    
                   Ucm.[message],                                    
                   Ucm.templateid,                                    
                   Ucm.templategroupid,                               
                   Ucm.isunicode                                    
            FROM   usercampaignmaster Ucm (nolock)                                   
                   OUTER APPLY dbo.Fn_split(Ucm.applicabiltygrouplist, '#') AS                                     
            Fs                                    
            WHERE  Ucm.isscheduled = 1                                    
                   AND Ucm.mailreplyto = ''                                    
                   AND   Ucm.nextexecutedatetime between @LastExecutedTime and getdate()                                  
                   AND DATEDIFF(                                    
                           minute,                                    
                           GETDATE(),                                    
                       CASE                                     
                                WHEN Ucm.isneverexpire = 1 THEN DATEADD(DAY, 1, GETDATE())                                    
                                ELSE ISNULL(Ucm.expirydate, GETDATE())                                    
                           END                                    
                       ) > 0                                    
                   AND DATEDIFF(minute, GETDATE(), ISNULL(Ucm.startdate, GETDATE()))                                    
                                                           
                                                
                                                           
                       < 0                                    
                   AND Ucm.isactive = 1                                    
                                                
                                                
                                                
            UNION ALL                                    
                                                
                                                
                                                
            SELECT Ucm.id      AS CampaignID,                                    
                   Ucm.parentid,                                    
                   0      AS Applicabilty,                                    
                   0           AS ApplicabiltyGroupList,                                    
                   Fs.[value]  AS ExclusionsGroupList,                                    
                   Ucm.notificationmail,                                    
         Ucm.exclusionsnumber,                                    
                   0           AS Exclusions,                                    
                   Ucm.inclusionsnumber,                                    
                   Ucm.accountused,                                    
                   Ucm.senderid,                                    
                   Ucm.[message],                                    
                   Ucm.templateid,                                    
   Ucm.templategroupid,                                    
                   Ucm.isunicode                                    
            FROM   usercampaignmaster Ucm  (nolock)                                  
                   OUTER APPLY dbo.Fn_split(Ucm.exclusionsgrouplist, '#') AS                                     
            Fs                                    
            WHERE  Ucm.isscheduled = 1                                    
                   AND Ucm.isactive = 1                                    
                   AND Ucm.mailreplyto = ''                                    
                   AND   Ucm.nextexecutedatetime between @LastExecutedTime and getdate()                                  
AND DATEDIFF(                                    
                           minute,                                    
                           GETDATE(),                                    
                           CASE                                     
                                WHEN Ucm.isneverexpire = 1 THEN DATEADD(DAY, 1, GETDATE())                                    
                                ELSE ISNULL(Ucm.expirydate, GETDATE())                                    
                  END                                    
                       ) > 0                                    
                   AND DATEDIFF(minute, GETDATE(), ISNULL(Ucm.startdate, GETDATE()))                                    
                                                           
                       
                                                           
                       < 0                                    
                                                
                                                
                              
            UNION ALL                                    
                                                
                                                
                                                
            SELECT Ucm.id      AS CampaignID,                                    
                   Ucm.parentid,                                    
                   0           AS Applicabilty,                                    
                   0           AS ApplicabiltyGroupList,                                    
                   0           AS ExclusionsGroupList,                                    
                   Ucm.notificationmail,                                    
                   Ucm.exclusionsnumber,                                    
                   Fs.[value]  AS Exclusions,                          
                   Ucm.inclusionsnumber,                                    
                   Ucm.accountused,                                    
                   Ucm.senderid,                                    
                   Ucm.[message],                                    
                   Ucm.templateid,                                    
                   Ucm.templategroupid,                                    
                   Ucm.isunicode                                    
            FROM   usercampaignmaster Ucm   (nolock)                                 
                   OUTER APPLY dbo.Fn_split(Ucm.exclusions, '#') AS Fs                                    
            WHERE  Ucm.isscheduled = 1                                    
                   AND Ucm.isactive = 1                                    
                   AND Ucm.mailreplyto = ''                                    
                   AND   Ucm.nextexecutedatetime between @LastExecutedTime and getdate()                                   
 AND DATEDIFF(                                    
