 DECLARE @CountCampaign     INT = (Select MAX(Id) from #temptemplate    )                                          
                                                                                   
     DECLARE @Count INT = 1                                                                                                  WHILE (@Count <= @CountCampaign)                                    
     BEGIN                                    
           DECLARE @Applicability BIGINT,                                       
     @Exclusions BIGINT,    
                 @Parentid BIGINT,                                          
                 @Campaignid BIGINT,    
                 @userid bigint    
                       
                     
          Select @Campaignid =Campaignid, @Parentid = Parentid ,@userid=AccountUsed    
          ,@Applicability = tt.Applicabilty,@Exclusions = tt.Exclusions    
           from #temptemplate tt Where Id = @Count                    If(@Applicability is not null)    
          Begin                                   
            INSERT INTO #temptablesearchapp                                          
       (                                         
      PersonName,                                          
      CompanyName,                                          
      MobileNo,                                          
      MobileNo1,          
      MobileNo2,                                          
      EmailID,                                          
      EmailID1,                                          
      EmailID2,                                          
      Country,                                          
      [STATE],                             
      City,                                    
      PinCode,                                          
      ResidentialAddress,                                          
      OfficeAddress,                                          
      SourceName,                                          
      MediumName,                                         
      CampaignName,                                          
      InitialRemarks,                                          
      SearchID,                                          
      ParentID,                                          
      CampaignID                                          
       )                                          
     EXEC Usp_executeusersearch                                          
       @ParentId,                                          
       @Applicability,                                          
       @Campaignid    
           
           End                                     
         if(@Exclusions is not null)    
          Begin                                     
         INSERT INTO #temptablesearchexc                                          
           (                                          
             PersonName,                                          
             CompanyName,                                          
             MobileNo,                                          
             MobileNo1,                                          
  MobileNo2,                                          
             EmailID,                                          
             EmailID1,                                          
             EmailID2,                                          
             Country,                                          
             [STATE],                                          
             City,                                          
             PinCode,                                          
             ResidentialAddress,                                          
            OfficeAddress,                                          
             SourceName,                                          
             MediumName,                                          
             CampaignName,                                          
             InitialRemarks,                                          
             SearchID,                                          
             ParentID,                                          
             CampaignID                                          
    )                                          
         EXEC Usp_executeusersearch                                          
              @Parentid,                                          
              @Exclusions,                                          
              @Campaignid    
        
    END    
     SET @Count = @Count+1    
         
     END                                          
                                
                                         
                                         
                                         
