 UPDATE Kd                        
 SET            
 Kd.[Message] = CAST(CAST(A.[Message] AS VARCHAR(MAX)) COLLATE Latin1_general_ci_ai AS VARCHAR(MAX)),      
 Kd.SenderID = CAST(CAST(A.SenderID AS VARCHAR(MAX))       
 COLLATE  Latin1_general_ci_ai AS VARCHAR(MAX)),      
 Kd.U_ID = A.AccountUsed,                        
 Kd.IsCompleted = 1,                        
 Kd.IsUniCode = A.IsUnicode,      
 kd.len=len(A.message),      
 kd.credits=case when A.isunicode=0 and len(A.message)<=160  then 1 when A.isunicode=0 and LEN(A.message)>160 then ceiling(LEN(A.message)/153) when A.IsUniCode=1 and len(A.message)<=70 then 1 else ceiling(LEN(A.message)/67) end       
 FROM   usercampaignexecutionrecipientsmessageTest2 Kd  (nolock)                       
        INNER JOIN #temptable A                        
             ON  Kd.CampaignID = A.CampaignID                        
             AND Kd.ParentID = A.ParentID                        
             AND Kd.Mobile = CAST(                        
                     CAST(A.Mobile AS VARCHAR(MAX))                        
                     COLLATE                        
                     Latin1_general_ci_ai AS                        
                     VARCHAR(MAX)                        
                 )                        
                         
 --UPDATE Kd                        
 --SET    Kd.Step2 = 1  ,Step2DateTime=GETDATE()                      
 --FROM   Usercampaignhistory Kd                        
 --       INNER JOIN #temptable A                        
 --            ON  Kd.CampaignID = A.CampaignID                        
 --            AND Kd.ParentID = A.ParentID                      
  UPDATE Kd                                                
      SET    Ismessages = 1,                                                
             templatesequence=tg.orderno,      
             templateid =tg.templateid                                         
             FROM   Usercampaignexecutionhistory Kd              
             inner join #temptable A                  
             ON  Kd.CampaignID = A.CampaignID AND A.ParentID = Kd.ParentID AND Kd.JobId = @Jobid        
             left join #tempgroups tg      
             on tg.CampaignID=kd.CampaignID                        
                     
 UPDATE Kd                                          
   SET    Kd.Step2 = 1  ,Step2DateTime=GETDATE(), Step2Recipients=isnull(A.Step2Recipients,0)                                       
   FROM   Usercampaignhistory Kd  (nolock)                                        
    Inner JOIN                                       
    (select campaignid,count(campaignid) as Step2Recipients,parentid                       
    from #temptable group by Parentid,campaignid) A                                          
    ON  Kd.CampaignID = A.CampaignID AND A.ParentID = Kd.ParentID AND Kd.JobId = @Jobid          
                             
--UPDATE Kd  SET    Kd.Step2 = 1  ,Step2DateTime=GETDATE()     FROM   Usercampaignhistory Kd                    
--        INNER JOIN  ##campaignrun c on Kd.ID=c.campaignrunid                         
                                 
  UPDATE Kd                                          
   SET    Kd.Step2 = 1  ,Step2DateTime=GETDATE() FROM   Usercampaignhistory Kd where JobId=@jobid                                   
                         
 DROP TABLE #temptable      
  INSERT INTO getbatchrecord                        
   ( -- BatchID auto-generated                 
     [user_id],                        
     randnum                        
   )                        
 SELECT DISTINCT Ucerm.u_id,                        
        Ucerm.campaignid                        
 FROM   usercampaignexecutionrecipientsmessageTest2 Ucerm   (nolock)                     
 WHERE  Ucerm.iscompleted = 1                        
       
 SELECT ROW_NUMBER() Over(order by CampaignId,ParentId) Id,       Ucerm.CampaignID,             
     Ucerm.ParentID,        
     dbo.Fn_createbatchid(Ucerm.CampaignID, Ucerm.U_ID) AS        BatchID,                                        
     Ucerm.Senderid,                                              Ucerm.U_ID AS UserID,      
     ucerm.isunicode,          
     SUM(credits) cnt,      
     COUNT(*) RCount      
      INTO   #tempTable1                                          
      FROM   usercampaignexecutionrecipientsmessageTest2 Ucerm         WHERE  Ucerm.IsCompleted = 1               
     Group by  Ucerm.CampaignID,             
     Ucerm.ParentID , Ucerm.SenderID, Ucerm.U_ID,          
                      Ucerm.isunicode           
                            
SELECT ROW_NUMBER() Over(order by Ucerm.CampaignId,Ucerm.ParentId) Id,       Ucerm.CampaignID,             
     Ucerm.ParentID,        
     dbo.Fn_createbatchid(Ucerm.CampaignID, Ucerm.U_ID) AS        BatchID,                                        
     Ucerm.Senderid,                                              Ucerm.U_ID AS UserID,      
     ucerm.isunicode,          
     SUM(credits) cnt,      
     COUNT(*) RCount,      
     ParentSuperResellerId      
      INTO   #tempTableVirtual                                          
      FROM   usercampaignexecutionrecipientsmessageTest2 Ucerm  join user_detail u on u.User_ID=ucerm.U_ID             
      WHERE  Ucerm.IsCompleted = 1  and HasVirtualCredits=1             
     Group by  Ucerm.CampaignID, u.ParentSuperResellerId,            
     Ucerm.ParentID , Ucerm.SenderID, Ucerm.U_ID,          
                      Ucerm.isunicode      
                            
                                                     
SELECT A.UserID,a.CampaignID, a.cnt,A.BatchID, SUM(b.cnt) RunningTotal into #TempTableRunningTotal1          
FROM   #tempTable1 a join          
       #tempTable1 b on a.userid=b.userid         
WHERE b.CampaignID <= a.CampaignID          
GROUP BY A.UserID, a.CampaignID, a.cnt,A.BatchID          
ORDER BY a.CampaignID;          
      
SELECT A.UserID,a.CampaignID, a.cnt,A.BatchID, SUM(b.cnt) RunningTotal,a.ParentSuperResellerId into #TempTableRunningTotalVirtual          
FROM   #tempTableVirtual a,          
       #tempTableVirtual b          
WHERE b.CampaignID <= a.CampaignID          
GROUP BY A.UserID, a.CampaignID, a.cnt,A.BatchID,a.ParentSuperResellerId          
ORDER BY a.CampaignID;      
                
                
