 drop table #tempMobileVirtual      
 drop table #Insufficientresellerbalance      
 drop table #TempTableRunningTotal1      
 drop table #TempTableRunningTotalVirtual      
 drop table #clonemessagedeliverystatus      
 drop table #tempTableVirtual      
     
 update usercampaignexecution set CampaignEnddatetime=GETDATE() where isevent=0 and isSMS=1    
 end    
    else    
    begin    
    declare @ErrorMsg nvarchar (max)='Last campaign not executed yet, pl update step3datetime of job id ' + cast(@maxjobid as nvarchar)+ ' before running this campaign'     
     exec usp_InsertCampaignError @Service='SMS', @isevent=0, @ErrorMessage= @ErrorMsg    
    end     
 END 


