CREATE   PROCEDURE [dbo].[usp_ExecuteUserSearch] --33265,208472 --27757,197107--26150,133812                    
--27836,153622--335,152762,NULL                        
 @ParentID BIGINT,                        
 @SearchID BIGINT,                        
 @CampaignID BIGINT = NULL                        
AS                        
BEGIN                      
 declare @isevent int = isnull((select iseventbased from UserCampaignMaster(nolock) where ID=@campaignid),0)                  
 declare @cmedium nvarchar(20)= (select medium from UserCampaignMaster(nolock) where ID=@campaignid)                  
 declare @LastExecutedTime datetime                  
 if @isevent=1 and @cmedium is not  null                  
 begin                  
 select @LastExecutedTime = case when @cmedium='SMS'     
 then isnull((select CampaignExecutedDatetime from UserCampaignExecution where issms=1 and isevent=1),getdate())     
 else isnull((select CampaignExecutedDatetime from UserCampaignExecution where issms=0 and isevent=1),getdate()) end                  
 end                  
                    
 DECLARE @SearchType               VARCHAR(50),                        
         @Medium                   VARCHAR(50),                        
         @Source                   VARCHAR(50),                        
         @Campaign                 VARCHAR(50),                        
         @SpecificName             VARCHAR(50),                        
         @SpecificAddress          VARCHAR(50),                        
         @SpecificMobileNo         VARCHAR(50),                        
         @SpecificEmail            VARCHAR(50),                        
         @SpecificCity             VARCHAR(50),                        
         @SpecificState            VARCHAR(50),                        
         @SpecificCountry          VARCHAR(50),                        
         @CurrentlyAssignedTo      VARCHAR(50),                        
         @FollowUpStatus           VARCHAR(50),                        
         @CreatedBetweenFrom       VARCHAR(50),                        
         @CreatedBetweenTo         VARCHAR(50),                        
         @NextFollowUpDateFrom     VARCHAR(50),                        
         @NextFollowUpDateTo       VARCHAR(50),                        
         @ConvertedWithinFrom      VARCHAR(50),                        
         @ConvertedWithinTo        VARCHAR(50)                        
                         
                         
                         
                         
                         
                         
                         
 SELECT @SearchType = usl.searchtype,                        
        @Medium                   = usl.medium,                        
        @Source                   = usl.source,                        
        @Campaign                 = usl.campaign,                        
        @SpecificName             = usl.specificname,                        
        @SpecificAddress          = usl.specificaddress,                        
        @SpecificMobileNo         = usl.specificmobileno,                        
        @SpecificEmail            = usl.specificemail,                        
        @SpecificCity             = usl.specificcity,                        
        @SpecificState            = usl.specificstate,                        
        @SpecificCountry          = usl.specificcountry,                        
        @CurrentlyAssignedTo      = usl.currentlyassignedto,                        
        @FollowUpStatus           = usl.followupstatus,                        
        @CreatedBetweenFrom       = usl.createdbetweenfrom,                        
        @CreatedBetweenTo         = usl.createdbetweento,                        
        @NextFollowUpDateFrom     = usl.nextfollowupdatefrom,                        
        @NextFollowUpDateTo       = usl.nextfollowupdateto,                        
        @ConvertedWithinFrom      = usl.convertedwithinfrom,                        
        @ConvertedWithinTo        = usl.convertedwithinto                        
 FROM   usersearchlist AS usl                        
 WHERE  usl.id = @SearchID                        
                         
                        
                         
                         
                         
                         
                         
 ----------------------------------Enquiry -------------------------                        
                         
                         
                         
 IF (LOWER(@SearchType) = 'en' OR LOWER(@SearchType) = 'al')                        
 BEGIN                        
                   
 if @isevent=1                  
 begin                  
 set @LastExecutedTime=(select MIN(createddate) FROM   UserEnquiry (nolock))                  
 end                  
 IF OBJECT_ID (N'tempdb..#temptableenquiry', N'U') IS NOT NULL DROP TABLE #temptableenquiry;                    
                    
 CREATE TABLE #temptableenquiry                        
     (                        
      id                     BIGINT,                        
      personname             VARCHAR(200),                        
      companyname            VARCHAR(200),                        
      mobileno               VARCHAR(100),                        
      mobileno1              VARCHAR(100),                        
      mobileno2              VARCHAR(100),                        
      emailid                VARCHAR(100),                        
      emailid1               VARCHAR(100),                        
      emailid2               VARCHAR(100),                        
      city                   VARCHAR(100),                        
      STATE                  VARCHAR(100),                        
      country                VARCHAR(100),                        
      countrycode            VARCHAR(50),                        
      countrycode1           VARCHAR(50),                        
      countrycode2           VARCHAR(50),                        
      pincode                VARCHAR(50),                        
      residentialaddress     VARCHAR(500),                        
      officeaddress          VARCHAR(500),                        
      sourcename             VARCHAR(200)collate SQL_Latin1_General_CP1_CI_AS                    
,                        
      mediumname             VARCHAR(200)collate SQL_Latin1_General_CP1_CI_AS                    
,                        
      campaignname           VARCHAR(200) collate SQL_Latin1_General_CP1_CI_AS                    
,                        
      initialremarks         VARCHAR(1000) collate SQL_Latin1_General_CP1_CI_AS                    
,                        
      datecreated            VARCHAR(50) collate SQL_Latin1_General_CP1_CI_AS                    
                       
     )                        
                             
     CREATE NONCLUSTERED INDEX NX_temptableenquiry on #temptableenquiry (mediumname,sourcename,campaignname,personname);                  
                       
     CREATE NONCLUSTERED INDEX NX_temptableenquiry1 on #temptableenquiry (residentialaddress,officeaddress,emailid,emailid1,emailid2);                    
                                  
     CREATE NONCLUSTERED INDEX NX_temptableenquiry2 on #temptableenquiry (mobileno,mobileno1,mobileno2,city,country,state,id);                             
                             
     INSERT INTO #temptableenquiry                    
       (                        
         id,                        
         personname,                        
         companyname,                        
         mobileno,                        
         mobileno1,                        
         mobileno2,                        
         emailid,                        
         emailid1,                        
         emailid2,                        
         city,                        
         [state],                                 country,                        
         countrycode,                        
         countrycode1,                        
         countrycode2,                        
         pincode,                        
         residentialaddress,                        
         officeaddress,                        
         sourcename,                        
         mediumname,                        
         campaignname,                        
         initialremarks,                        
         datecreated                        
       )           
     SELECT ue.enquiryid,                        
            ue.personname,                        
            ue.companyname,                        
            ue.mobileno,                        
            ue.mobileno1,                        
            ue.mobileno2,                        
            ue.emailid,                        
            ue.emailid1,                        
            ue.emailid2,                        
            ue.city,                        
            ue.[state],                        
            ue.country,                        
            ue.countrycode,                        
            ue.countrycode1,                        
            ue.countrycode2,                        
       ue.pincode,                        
            ue.residentialaddress,                        
            ue.officeaddress,                        
            ue.sourcename,                        
            ue.mediumname,                        
            ue.campaignname,                        
       ue.initialremarks,                        
            ue.createddate                        
     FROM   UserEnquiry AS ue  with (nolock)                      
     WHERE  ue.parentid = @ParentID and ue.CreatedDate>isnull(@LastExecutedTime,dateadd(m,-5,ue.CreatedDate))                        
                             
                             
                             
     IF (ISNULL(@Medium, '') <> '' AND ISNULL(@Medium, '') <> '0')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableenquiry                        
         WHERE  mediumname NOT IN (SELECT fs.[value]                        
                                   FROM   dbo.Fn_split(@Medium, '#') AS fs)                        
     END                        
                             
                             
     IF (ISNULL(@Source, '') <> '' AND ISNULL(@Source, '') <> '0')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableenquiry                        
         WHERE  sourcename NOT IN (SELECT fs.[value]                        
                                   FROM   dbo.Fn_split(@Source, '#') AS fs)                        
     END                        
                                  
                             
     IF (                        
            ISNULL(@Campaign, '') <> ''                        
            AND ISNULL(@Campaign, '') <> '0'                        
        )                        
     BEGIN                        
         DELETE                         
         FROM   #temptableenquiry                        
         WHERE  campaignname NOT IN (SELECT fs.[value]                        
                                     FROM   dbo.Fn_split(@Campaign, '#') AS                         
                                            fs)                        
     END                        
                             
                            
                             
     IF (ISNULL(@SpecificName, '') <> '')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableenquiry                        
         WHERE  personname is null or personname not like  '%' +@SpecificName  + '%'                       
     END                        
                      
                            
                             
     IF (ISNULL(@SpecificAddress, '') <> '')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableenquiry                        
         WHERE  ((residentialaddress is not null and residentialaddress not LIKE '%' + @SpecificAddress + '%') and  officeaddress is null )        
   OR     (residentialaddress is null and (officeaddress not LIKE '%' + @SpecificAddress + '%' and officeaddress is not null))     
   OR     (officeaddress is null and residentialaddress is null)                     
     END                        
                            
                             
     IF (ISNULL(@SpecificMobileNo, '') <> '')                        
     BEGIN                
        DELETE                         
         FROM   #temptableenquiry   WHERE                
         CAST(isnull(mobileno,'') COLLATE Latin1_General_CI_AI AS VARCHAR(50)) ='' and        
         CAST(isnull(mobileno2,'') COLLATE Latin1_General_CI_AI AS VARCHAR(50)) ='' and               
         CAST(isnull(mobileno1,'') COLLATE Latin1_General_CI_AI AS VARCHAR(50)) =''                
                       
         DELETE                         
         FROM   #temptableenquiry                        
         WHERE  CAST(isnull(mobileno,'') COLLATE Latin1_General_CI_AI AS VARCHAR(50))                         
                                        
                NOT IN (SELECT fs.[value]                        
                        FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)                        
  and  CAST(isnull(mobileno1,'') COLLATE Latin1_General_CI_AI AS VARCHAR(50))                         
                                            
                    NOT IN (SELECT fs.[value]                        
                            FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)                        
                and  CAST(isnull(mobileno2,'') COLLATE Latin1_General_CI_AI AS VARCHAR(50))                         
                                            
                    NOT IN (SELECT fs.[value]                        
                            FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)                        
     END                        
                             
                                   
     IF (ISNULL(@SpecificEmail, '') <> '')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableenquiry                        
         WHERE  CAST(isnull(emailid,'') COLLATE Latin1_General_CI_AI AS VARCHAR(250))                         
                                        
                NOT IN (SELECT fs.[value]                        
                        FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)                        
                and  CAST(isnull(emailid1,'') COLLATE Latin1_General_CI_AI AS VARCHAR(250))                         
                                            
                    NOT IN (SELECT fs.[value]                        
                            FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)                        
                and  CAST(isnull(emailid2,'') COLLATE Latin1_General_CI_AI AS VARCHAR(250))                         
                                            
                    NOT IN (SELECT fs.[value]                        
                            FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)                        
     END                        
                             
                            
                             
     IF (ISNULL(@SpecificCity, '') <> '')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableenquiry                        
         WHERE  city  is null or city not like '%' + @SpecificCity  + '%'                       
     END                        
                           
                             
     IF (ISNULL(@SpecificCountry, '') <> '')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableenquiry                        
         WHERE  country  is null or country not like '%' + @SpecificCountry + '%'                       
     END                        
                                      
     IF (ISNULL(@SpecificState, '') <> '')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableenquiry                        
       WHERE  [state]  is null or  [state] not like '%' + @SpecificState + '%'                       
   END                        
                             
                             
     IF (                        
            ISNULL(@CreatedBetweenFrom, '') <> ''                        
            AND ISNULL(@CreatedBetweenTo, '') <> ''                        
        )                        
     BEGIN               
  DELETE t                        
         FROM   #temptableenquiry t where  DATEDIFF(d, datecreated, GETDATE())                      
                                  not BETWEEN @CreatedBetweenFrom and @CreatedBetweenTo                     
         /*DELETE                         
         FROM   #temptableenquiry                             WHERE  id NOT IN (SELECT ue.enquiryid                        
                           FROM   userenquiry AS ue                        
                           WHERE  DATEDIFF(d, ue.createddate, GETDATE())                      
                                  BETWEEN                      
                                  @CreatedBetweenFrom AND    @CreatedBetweenTo)*/                        
     END                        
 END                        
                              
 ---------------------------------- LEADS -------------------------                        
                         
                         
                         
 IF (LOWER(@SearchType) = 'le' OR LOWER(@SearchType) = 'al')                        
 BEGIN                        
                    
  if @isevent=1                  
 begin                  
 set @LastExecutedTime=(select MIN(CreatedOn) FROM   UserLeads (nolock))                  
 end                 
 IF OBJECT_ID (N'tempdb..#temptableleads', N'U') IS NOT NULL DROP TABLE #temptableleads;                    
                     
 CREATE TABLE #temptableleads                        
     (                        
      id                     BIGINT,             
   leadno                 bigint,                       
      personname             VARCHAR(200),                        
      companyname            VARCHAR(200),                        
      mobileno               VARCHAR(100),                        
      mobileno1              VARCHAR(100),                        
      mobileno2              VARCHAR(100),                        
      emailid                VARCHAR(100),                        
      emailid1          VARCHAR(100),                        
      emailid2               VARCHAR(100),                        
      city                   VARCHAR(100),                        
      STATE                  VARCHAR(100),                        
      country                VARCHAR(100),                        
      countrycode            VARCHAR(50),                        
      countrycode1           VARCHAR(50),                        
      countrycode2           VARCHAR(50),                        
      pincode                VARCHAR(50),                        
      residentialaddress     VARCHAR(500),                        
      officeaddress          VARCHAR(500),             
      sourcename             VARCHAR(200) COLLATE                     
      sql_latin1_general_cp1_ci_as,                        
      mediumname             VARCHAR(200) COLLATE                     
      sql_latin1_general_cp1_ci_as,                        
      campaignname           VARCHAR(200) COLLATE                     
      sql_latin1_general_cp1_ci_as,                        
      initialremarks         VARCHAR(1000) collate SQL_Latin1_General_CP1_CI_AS,                        
      datecreated            VARCHAR(50) collate SQL_Latin1_General_CP1_CI_AS                    
,                        
      assignedto             VARCHAR(200) collate SQL_Latin1_General_CP1_CI_AS                    
,                        
      followupstatus         VARCHAR(200) collate SQL_Latin1_General_CP1_CI_AS                    
,                        
      nextfollowupdate       VARCHAR(200) collate SQL_Latin1_General_CP1_CI_AS                    
                        
     )                     
                             
                       
     CREATE NONCLUSTERED INDEX NX_temptableleads on #temptableleads (mediumname,sourcename,campaignname,personname);                  
                       
     CREATE NONCLUSTERED INDEX NX_temptableleads1 on #temptableleads (residentialaddress,officeaddress,emailid,emailid1,emailid2);                    
                                  
     CREATE NONCLUSTERED INDEX NX_temptableleads2 on #temptableleads (mobileno,mobileno1,mobileno2,city,country,state,id);                             
                             
                             
     INSERT INTO #temptableleads                        
       (                        
         id,              
   leadno,                      
         personname,                        
         companyname,                        
         mobileno,                        
         mobileno1,                       
         mobileno2,                        
         emailid,                        
         emailid1,                        
         emailid2,                        
         city,                        
         [state],                        
         country,                        
         countrycode,                        
         countrycode1,                        
         countrycode2,                        
         pincode,                        
         residentialaddress,                        
         officeaddress,                        
         sourcename,                        
         mediumname,                        
         campaignname,                        
         initialremarks,                        
         datecreated,                        
         assignedto,                        
         followupstatus,                        
         nextfollowupdate                        
       )                        
     SELECT ue.id,              
         ue.leadno,                      
            ue.personname,                        
            ue.companyname,                
            ue.mobileno,                        
            ue.mobileno1,                        
            ue.mobileno2,                        
            ue.emailid,                        
            ue.emailid1,                        
            ue.emailid2,                        
            ue.city,                        
            ue.[state],                        
            ue.country,                        
            ue.countrycode,                        
            ue.countrycode1,                        
            ue.countrycode2,                        
            ue.pincode,                        
            ue.residentialaddress,                        
            ue.officeaddress,                        
            ue.sourcename,                        
            ue.mediumname,                        
            ue.campaignname,                        
            ue.initialremarks,                        
        ue.createdon,                        
            ue.assignedto,                        
            ue.followupstatus,                        
            ue.FollowupDate                        
     FROM   UserLeads AS ue   with (nolock)                      
     WHERE  ue.ParentID = @ParentID  and ue.Createdon>isnull(@LastExecutedTime,dateadd(m,-5,ue.Createdon))       
      
      
                          
     IF (ISNULL(@Medium, '') <> '' AND ISNULL(@Medium, '') <> '0')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableleads                        
         WHERE  mediumname NOT IN (SELECT fs.[value]                        
                                   FROM   dbo.Fn_split(@Medium, '#') AS fs)                        
     END                        
                             
                     
     IF (ISNULL(@Source, '') <> '' AND ISNULL(@Source, '') <> '0')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableleads                        
         WHERE  sourcename NOT IN (SELECT fs.[value]                        
                                   FROM   dbo.Fn_split(@Source, '#') AS fs)                        
     END                        
                             
                             
     IF (                        
            ISNULL(@Campaign, '') <> ''                        
            AND ISNULL(@Campaign, '') <> '0'                        
        )                        
     BEGIN                        
         DELETE                         
         FROM   #temptableleads                        
         WHERE  campaignname NOT IN (SELECT fs.[value]                        
                                     FROM   dbo.Fn_split(@Campaign, '#') AS                         
                                            fs)                        
     END                        
                             
                             
                             
     IF (ISNULL(@SpecificName, '') <> '')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableleads                        
         WHERE  personname is null or personname not like '%' + @SpecificName    +'%'                    
     END                        
                             
                
     IF (ISNULL(@SpecificAddress, '') <> '')           BEGIN                        
         DELETE                         
         FROM   #temptableleads                        
         WHERE   ((residentialaddress is not null and residentialaddress not LIKE '%' + @SpecificAddress + '%') and  officeaddress is null )                                  
   OR     (residentialaddress is null and (officeaddress not LIKE '%' + @SpecificAddress + '%' and officeaddress is not null))     
   OR     (officeaddress is null and residentialaddress is null)                     
     END                        
                             
                             
     IF (ISNULL(@SpecificMobileNo, '') <> '')                        
     BEGIN                 
     DELETE                         
         FROM   #temptableleads   WHERE                
         CAST(isnull(mobileno,'') COLLATE Latin1_General_CI_AI AS VARCHAR(50)) ='' and                
         CAST(isnull(mobileno2,'') COLLATE Latin1_General_CI_AI AS VARCHAR(50)) ='' and               
         CAST(isnull(mobileno1,'') COLLATE Latin1_General_CI_AI AS VARCHAR(50)) =''                       
         DELETE                         
         FROM   #temptableleads                        
         WHERE  CAST(isnull(mobileno,'') COLLATE Latin1_General_CI_AI AS VARCHAR(50))                         
                                     
                NOT IN (SELECT fs.[value]                        
                        FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)                        
                and  CAST(isnull(mobileno1,'') COLLATE Latin1_General_CI_AI AS VARCHAR(50))                         
                                            
                    NOT IN (SELECT fs.[value]                  
                            FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)                        
                and  CAST(isnull(mobileno2,'') COLLATE Latin1_General_CI_AI AS VARCHAR(50))                         
                                            
                    NOT IN (SELECT fs.[value]                        
                            FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)                        
     END                        
                             
                             
                             
     IF (ISNULL(@SpecificEmail, '') <> '')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableleads                        
         WHERE  CAST(isnull(emailid,'') COLLATE Latin1_General_CI_AI AS VARCHAR(250))                         
                                        
                NOT IN (SELECT fs.[value]                        
                        FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)                        
                and  CAST(isnull(emailid1,'') COLLATE Latin1_General_CI_AI AS VARCHAR(250))                         
                                            
                    NOT IN (SELECT fs.[value]                        
                            FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)                        
                and  CAST(isnull(emailid2,'') COLLATE Latin1_General_CI_AI AS VARCHAR(250))                         
                                            
                    NOT IN (SELECT fs.[value]                        
                            FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)                        
     END                        
                             
                             
                        IF (ISNULL(@SpecificCity, '') <> '')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableleads                        
         WHERE  city  is null or  city not like '%' + @SpecificCity +'%'                       
     END                        
                             
                             
                             
     IF (ISNULL(@SpecificCountry, '') <> '')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableleads                        
         WHERE  country  is null or  country not like '%' + @SpecificCountry +'%'                       
     END                        
                             
                             
                             
     IF (ISNULL(@SpecificState, '') <> '')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableleads                        
         WHERE  [state]  is null or  [STATE]  not like '%' + @SpecificState  +'%'                      
     END                        
                             
                             
     IF (                        
            ISNULL(@CurrentlyAssignedTo, '') <> ''                        
            AND ISNULL(@CurrentlyAssignedTo, '') <> '0'                        
        )                        
     BEGIN                        
         DELETE                         
         FROM   #temptableleads                        
         WHERE  assignedto NOT IN (SELECT fs.[value]                        
                                   FROM   dbo.Fn_split(@CurrentlyAssignedTo, ',') AS                         
                                          fs)                        
     END                        
                             
                       
                             
     IF (                        
            ISNULL(@CreatedBetweenFrom, '') <> ''                        
            AND ISNULL(@CreatedBetweenTo, '') <> ''                        
        )                        
     BEGIN           
  DELETE t                        
         FROM   #temptableleads t where  DATEDIFF(d, datecreated, GETDATE())                      
                                  not BETWEEN @CreatedBetweenFrom and @CreatedBetweenTo                    
       /*DELETE                         
         FROM   #temptableleads                        
         WHERE  id NOT IN (SELECT ue.id                        
                           FROM   userleads AS ue                        
                           WHERE  DATEDIFF(d, ue.createdon, GETDATE())                     
                                  BETWEEN @CreatedBetweenFrom AND @CreatedBetweenTo                     
                                  AND ue.parentid = @ParentID) */                       
     END                        
                             
                             
     IF (                        
            ISNULL(@NextFollowUpDateFrom, '') <> ''                        
            AND ISNULL(@NextFollowUpDateTo, '') <> ''                        
        )                        
     BEGIN                      
 DELETE t                        
         FROM   #temptableleads t join leadinteractionhistory lih                        
                                       ON  lih.leadno = t.leadno and lih.parentid=@ParentID where  DATEDIFF(d, GETDATE(), lih.FollowupDate)                     
                                  not BETWEEN                     
                                  @NextFollowUpDateFrom AND                     
                   @NextFollowUpDateTo            
         /*DELETE                         
         FROM   #temptableleads                        
         WHERE  id NOT IN (SELECT ue.id                        
                   FROM   userleads AS ue                        
                                  INNER JOIN leadinteractionhistory lih                        
                                       ON  lih.leadno = ue.leadno                        
                           WHERE  DATEDIFF(d, GETDATE(), lih.nextstatusdate)                     
                                  BETWEEN                     
                                  @NextFollowUpDateFrom AND                     
                                  @NextFollowUpDateTo                        
                                  AND ue.parentid = @ParentID)*/                        
     END                        
                             
                             
                             
     IF (                        
            ISNULL(@FollowUpStatus, '') <> ''                        
            AND ISNULL(@FollowUpStatus, '') <> '0'                        
    )                        
     BEGIN                        
         DELETE                         
         FROM   #temptableleads       
         WHERE  followupstatus NOT IN (SELECT fs.[value]                        
                                       FROM   dbo.Fn_split(@FollowUpStatus, '#') AS                         
                                              fs)                        
     END                        
 END                        
                         
 ---------------------------------- Conversions -------------------------                        
                         
                         
                         
 IF (LOWER(@SearchType) = 'co' OR LOWER(@SearchType) = 'al')                        
 BEGIN                        
                   
  if @isevent=1                  
 begin                  
 set @LastExecutedTime=(select MIN(CreatedOn) FROM   UserLeads (nolock))                  
 end                    
                    
                         
 IF OBJECT_ID (N'tempdb..#temptableconversion', N'U') IS NOT NULL DROP TABLE #temptableconversion;                    
                     
 CREATE TABLE #temptableconversion                        
     (                        
      id                     BIGINT,               
   leadno bigint,              
      personname             VARCHAR(200),                        
      companyname            VARCHAR(200),                        
      mobileno               VARCHAR(100),                        
      mobileno1              VARCHAR(100),                        
      mobileno2              VARCHAR(100),                        
      emailid     VARCHAR(100),                        
      emailid1               VARCHAR(100),                        
      emailid2               VARCHAR(100),                        
      city                   VARCHAR(100),                        
      STATE                  VARCHAR(100),                        
      country                VARCHAR(100),                      
      countrycode            VARCHAR(50),                        
      pincode                VARCHAR(50),                        
      residentialaddress     VARCHAR(500),                        
      officeaddress          VARCHAR(500),                        
      sourcename             VARCHAR(200) COLLATE sql_latin1_general_cp1_ci_as,                        
      mediumname             VARCHAR(200) COLLATE sql_latin1_general_cp1_ci_as,                        
      campaignname           VARCHAR(200) COLLATE sql_latin1_general_cp1_ci_as,                        
      initialremarks         VARCHAR(1000) collate SQL_Latin1_General_CP1_CI_AS,                        
      datecreated            VARCHAR(50) collate SQL_Latin1_General_CP1_CI_AS,                  
      assignedto             VARCHAR(200) collate SQL_Latin1_General_CP1_CI_AS,                        
      followupstatus         VARCHAR(200) collate SQL_Latin1_General_CP1_CI_AS,                        
      nextfollowupdate       VARCHAR(200) collate SQL_Latin1_General_CP1_CI_AS                  
     )                        
                         
 CREATE NONCLUSTERED INDEX NX_temptableconversion on #temptableconversion (  id,                        
                     personname,                        
                     companyname,                        
                     mobileno,                        
          mobileno1,                        
                     mobileno2                      
                     );                    
                    
  CREATE NONCLUSTERED INDEX NX_temptableconversion1 on #temptableconversion(                  
                     emailid,                        
                     emailid1,                        
                     emailid2,                        
                     city,                        
                     [state],                        
                     country,                        
                     countrycode,                        
                     pincode                  
                   );                  
                           
    CREATE NONCLUSTERED INDEX NX_temptableconversion2 on #temptableconversion (  residentialaddress,                        
                     officeaddress,                        
                     sourcename,                        
        mediumname                  
                     );                  
                      
    CREATE NONCLUSTERED INDEX NX_temptableconversion3 on #temptableconversion (                        
                     campaignname,                                             
                     datecreated                  
                     );                  
                      
    CREATE NONCLUSTERED INDEX NX_temptableconversion4 on #temptableconversion (  assignedto,               
                     followupstatus,                        
                     nextfollowupdate);                  
                         
     INSERT INTO #temptableconversion                        
       (                        
         id,             
   leadno,                       
         personname,                        
         companyname,                        
         mobileno,                        
         mobileno1,                        
         mobileno2,                        
         emailid,                        
         emailid1,                        
         emailid2,                        
   city,                        
         [state],                        
         country,                        
         countrycode,                        
         pincode,                        
         residentialaddress,                        
         officeaddress,                        
         sourcename,                        
         mediumname,                        
         campaignname,                        
         initialremarks,                        
         datecreated,                        
         assignedto,                        
         followupstatus,                        
         nextfollowupdate                        
       )                        
     SELECT ue.id,             
  ue.LeadNo,                       
            ue.personname,                        
            ue.companyname,                        
            ue.mobileno,                        
            ue.mobileno1,                   
            ue.mobileno2,                        
            ue.emailid,                        
            ue.emailid1,                        
            ue.emailid2,                        
            ue.city,                        
            ue.[state],                        
            ue.country,                        
            ue.countrycode,                        
            ue.pincode,                        
            ue.residentialaddress,                        
            ue.officeaddress,                        
            ue.sourcename,                        
            ue.mediumname,                        
            ue.campaignname,                        
            ue.initialremarks,                        
            ue.createdon,                        
            ue.assignedto,                        
            ue.followupstatus,                        
            ue.FollowupDate                        
     FROM   UserLeads AS ue   with (nolock)                      
           INNER JOIN LeadInteractionHistory AS lih   with (nolock)                      
                 ON  lih.LeadNo = ue.LeadNo                        
                 AND lih.ParentID = @ParentID                        
				 and lih.FollowUpStatus=5
                 --AND ISNULL(NULLIF(lih.amountpaid, 0), 0) <> 0                        
     WHERE  ue.ParentID = @ParentID  and lih.CreatedOn>isnull(@LastExecutedTime,dateadd(m,-5,lih.CreatedOn))               
                             
                            
                             
     IF (ISNULL(@Medium, '') <> '' AND ISNULL(@Medium, '') <> '0')                        
     BEGIN                        
     DELETE                         
         FROM   #temptableconversion                        
         WHERE  mediumname NOT IN (SELECT fs.[value]                        
                                   FROM   dbo.Fn_split(@Medium, '#') AS fs)                        
     END                        
                             
                             
                             
                             
                             
                             
                             
     IF (ISNULL(@Source, '') <> '' AND ISNULL(@Source, '') <> '0')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableconversion                        
         WHERE  sourcename NOT IN (SELECT fs.[value]                        
                                   FROM   dbo.Fn_split(@Source, '#') AS fs)                        
     END                        
                             
                             
                             
                             
                             
                             
                             
IF (                        
            ISNULL(@Campaign, '') <> ''                        
            AND ISNULL(@Campaign, '') <> '0'                        
        )                        
     BEGIN                        
         DELETE                         
         FROM   #temptableconversion                        
         WHERE  campaignname NOT IN (SELECT fs.[value]                        
                                     FROM   dbo.Fn_split(@Campaign, '#') AS                         
                                            fs)                        
     END                        
                             
                          
                             
                             
                             
                             
                             
     IF (ISNULL(@SpecificName, '') <> '')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableconversion                        
         WHERE  personname is null or personname not like '%' + @SpecificName   +'%'                     
     END                        
                             
                             
                             
                             
                             
                             
                             
     IF (ISNULL(@SpecificAddress, '') <> '')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableconversion                        
        WHERE   ((residentialaddress is not null and residentialaddress not LIKE '%' + @SpecificAddress + '%') and  officeaddress is null )                                  
   OR     (residentialaddress is null and (officeaddress not LIKE '%' + @SpecificAddress + '%' and officeaddress is not null))     
   OR     (officeaddress is null and residentialaddress is null)                                         
     END                        
                             
                          
                             
                             
                             
                             
                             
     IF (ISNULL(@SpecificMobileNo, '') <> '')                        
     BEGIN                  
     DELETE                         
         FROM   #temptableconversion                        
         WHERE  CAST(isnull(mobileno,'') COLLATE Latin1_General_CI_AI AS VARCHAR(50))='' and              
                CAST(isnull(mobileno1,'') COLLATE Latin1_General_CI_AI AS VARCHAR(50))='' and              
                CAST(isnull(mobileno2,'') COLLATE Latin1_General_CI_AI AS VARCHAR(50))=''               
         DELETE                         
         FROM   #temptableconversion                        
         WHERE  CAST(mobileno COLLATE Latin1_General_CI_AI AS VARCHAR(50))                         
                                        
                NOT IN (SELECT fs.[value]                        
                        FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)                        
                OR  CAST(mobileno1 COLLATE Latin1_General_CI_AI AS VARCHAR(50))                         
                                            
                    NOT IN (SELECT fs.[value]                        
                            FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)                        
                OR  CAST(mobileno2 COLLATE Latin1_General_CI_AI AS VARCHAR(50))                         
                                            
                    NOT IN (SELECT fs.[value]                        
                            FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)                        
     END                        
                             
                             
                             
                             
                             
          
                             
     IF (ISNULL(@SpecificEmail, '') <> '')                     
     BEGIN                        
         DELETE                         
         FROM   #temptableconversion                        
         WHERE  CAST(emailid COLLATE Latin1_General_CI_AI AS VARCHAR(250))                         
                                        
                NOT IN (SELECT fs.[value]                        
                        FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)                        
                OR  CAST(emailid1 COLLATE Latin1_General_CI_AI AS VARCHAR(250))                         
                                            
                    NOT IN (SELECT fs.[value]                        
  FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)                        
                OR  CAST(emailid2 COLLATE Latin1_General_CI_AI AS VARCHAR(250))                         
                                            
                    NOT IN (SELECT fs.[value]                        
                            FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)                        
     END                        
                             
                             
                             
                             
                             
                             
                             
     IF (ISNULL(@SpecificCity, '') <> '')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableconversion                        
         WHERE  city is null or city not like '%' + @SpecificCity   +'%'                     
     END                        
                             
                             
                             
                             
                             
                             
                             
     IF (ISNULL(@SpecificCountry, '') <> '')                        
     BEGIN     
         DELETE                         
       FROM   #temptableconversion                        
         WHERE  country  is null or country not like '%' + @SpecificCountry  +'%'                      
     END                        
                             
                             
                             
                             
                             
                             
                             
     IF (ISNULL(@SpecificState, '') <> '')                        
     BEGIN                        
         DELETE                         
         FROM   #temptableconversion                        
         WHERE [STATE]  is null or  [state]  not like '%' + @SpecificState   +'%'                     
     END                        
                  
                             
                             
                             
                             
                             
                             
     IF (                        
            ISNULL(@CurrentlyAssignedTo, '') <> ''                        
            AND ISNULL(@CurrentlyAssignedTo, '') <> '0'                        
        )                        
     BEGIN                        
         DELETE                         
         FROM   #temptableconversion                        
         WHERE  assignedto NOT IN (SELECT fs.[value]                        
                                   FROM   dbo.Fn_split(@CurrentlyAssignedTo, ',') AS                         
                                          fs)                        
     END                        
                             
                             
                             
                             
                             
                             
                             
     IF (                        
            ISNULL(@CreatedBetweenFrom, '') <> ''                        
            AND ISNULL(@CreatedBetweenTo, '') <> ''                        
        )                        
     BEGIN                    
  DELETE t                        
         FROM   #temptableconversion t  WHERE  DATEDIFF(d, datecreated, GETDATE())  not BETWEEN                        
                                  @CreatedBetweenFrom AND   @CreatedBetweenTo                
         /*DELETE t                        
         FROM   #temptableconversion t                        
     WHERE  id NOT IN (SELECT ue.id                    
                           FROM   userleads AS ue                        
                           WHERE  DATEDIFF(d, ue.createdon, GETDATE())                        
                                                          
                                                          
                                                          
                                  BETWEEN                        
                                 
                                                          
                                                          
                                  @CreatedBetweenFrom AND                        
                                                          
                                                          
                                                          
                                  @CreatedBetweenTo                        
                                  AND ue.parentid = @ParentID)*/                        
     END                        
                             
                             
                             
                             
                             
                             
                             
     IF (                        
            ISNULL(@NextFollowUpDateFrom, '') <> ''                        
     AND ISNULL(@NextFollowUpDateTo, '') <> ''                        
        )                        
     BEGIN                     
  DELETE t                        
         FROM   #temptableleads t join leadinteractionhistory lih                        
                                       ON  lih.leadno = t.leadno and lih.parentid=@ParentID where  DATEDIFF(d, GETDATE(), lih.FollowupDate)                     
                                  not BETWEEN                     
                                  @NextFollowUpDateFrom AND                     
                                  @NextFollowUpDateTo               
        /* DELETE                         
         FROM   #temptableconversion                        
         WHERE  id NOT IN (SELECT ue.id                        
                           FROM   userleads AS ue                        
                                  INNER JOIN leadinteractionhistory lih                        
                                       ON  lih.leadno = ue.leadno                        
                           WHERE  DATEDIFF(d, GETDATE(), lih.nextstatusdate)                        
                                                          
                          
                                                          
                                  BETWEEN                        
                                                          
                                                          
                                        
                                  @NextFollowUpDateFrom AND                        
                                                          
                             
                                                          
                                  @NextFollowUpDateTo                        
                                  AND ue.parentid = @ParentID)  */                      
     END                        
                             
                             
                             
                             
                             
                             
                             
     IF (                        
            ISNULL(@ConvertedWithinFrom, '') <> ''                        
            AND ISNULL(@ConvertedWithinTo, '') <> ''                                )                        
     BEGIN                      
  DELETE t                        
         FROM   #temptableleads t join leadinteractionhistory lih                        
                                       ON  lih.leadno = t.leadno and lih.parentid=@ParentID and ISNULL(NULLIF(lih.amountpaid, 0), 0)<>0            
            where  DATEDIFF(d, lih.createdon, GETDATE())                        
                                  NOT BETWEEN                        
                                  @ConvertedWithinFrom AND                        
                                  @ConvertedWithinTo             
 /* DELETE                         
         FROM   #temptableconversion                        
         WHERE  id NOT IN (SELECT ue.id                        
                           FROM   userleads AS ue   with (nolock)                      
                                  INNER JOIN leadinteractionhistory lih   with (nolock)                       
                                       ON  lih.leadno = ue.leadno                        
                                       AND ISNULL(NULLIF(lih.amountpaid, 0), 0)            
                                           <>                        
                                           0                        
                           WHERE  DATEDIFF(d, lih.createdon, GETDATE())                        
                                  BETWEEN                        
                                  @ConvertedWithinFrom AND                        
                                  @ConvertedWithinTo                        
                                  AND ue.parentid = @ParentID)    */                    
     END                        
                             
                             
                             
                             
                             
                             
                             
     IF (                        
            ISNULL(@FollowUpStatus, '') <> ''                        
            AND ISNULL(@FollowUpStatus, '') <> '0'                        
        )                        
     BEGIN                        
         DELETE                   
         FROM   #temptableconversion                        
         WHERE  followupstatus NOT IN (SELECT fs.[value]                        
                                       FROM   dbo.Fn_split(@FollowUpStatus, '#') AS                         
                                              fs)                        
     END                        
 END                        
                         
                            
                         
 IF (LOWER(@SearchType) = 'en')                        
 BEGIN                        
     SELECT tteq.personname,                        
            tteq.companyname,                        
            ISNULL(tteq.mobileno, '')  AS MobileNo,                        
            ISNULL(tteq.mobileno1, '') AS MobileNo1,                        
   ISNULL(tteq.mobileno2, '') AS MobileNo2,                        
            ISNULL(tteq.emailid, '')   AS EMAILID,                        
            ISNULL(tteq.emailid1, '')  AS EmailID1,                        
            ISNULL(tteq.emailid2, '')  AS EmailID2,                        
            tteq.country,                        
            tteq.[state],                        
            tteq.city,                        
            tteq.pincode,                        
            tteq.residentialaddress,                        
            tteq.officeaddress,           
            uss.NAME                   AS SourceName,                        
            ums.NAME                   AS MediumName,                        
            ucs.NAME                   AS CampaignName,                        
  tteq.initialremarks,                        
            @SearchID                  AS SearchID,                        
            @ParentID  AS ParentID,                        
            @CampaignID                AS CampaignID                        
     FROM   #temptableenquiry         AS tteq                        
            LEFT JOIN usermediumsettings ums   with (nolock)                      
                 ON  tteq.mediumname = ums.mediumid                        
            LEFT JOIN usercampaignsettings ucs   with (nolock)                      
                 ON  tteq.campaignname = ucs.campaignid                        
            LEFT JOIN usersourcesettings uss   with (nolock)                      
                 ON  tteq.sourcename = uss.sourceid                        
                             
                             
                             
                             
                             
                             
                             
     DROP TABLE #temptableenquiry                        
 END                      
 ELSE                         
                         
                         
                         
 IF (LOWER(@SearchType) = 'le')                        
 BEGIN                        
     SELECT tteq.personname,                        
            tteq.companyname,                        
            ISNULL(tteq.mobileno, '')  AS MobileNo,                        
            ISNULL(tteq.mobileno1, '') AS MobileNo1,                        
            ISNULL(tteq.mobileno2, '') AS MobileNo2,                        
            ISNULL(tteq.emailid, '')   AS EMAILID,                        
            ISNULL(tteq.emailid1, '')  AS EmailID1,                        
            ISNULL(tteq.emailid2, '')  AS EmailID2,                        
            tteq.country,                        
            tteq.[state],                        
            tteq.city,                        
            tteq.pincode,                        
            tteq.residentialaddress,                        
            tteq.officeaddress,                        
            uss.NAME         AS SourceName,                        
            ums.NAME                   AS MediumName,                        
            ucs.NAME                   AS CampaignName,                        
            tteq.initialremarks,                        
            @SearchID                  AS SearchID,                                  @ParentID                  AS ParentID,                        
            @CampaignID                AS CampaignID                        
            --tteq.countrycode                        
     FROM   #temptableleads            AS tteq                        
            LEFT JOIN usermediumsettings ums   with (nolock)                      
                 ON  tteq.mediumname = ums.mediumid                        
            LEFT JOIN usercampaignsettings ucs   with (nolock)                      
                 ON  tteq.campaignname = ucs.campaignid                        
            LEFT JOIN usersourcesettings uss   with (nolock)                      
                 ON  tteq.sourcename = uss.sourceid                        
            LEFT JOIN followup_status fus   with (nolock)                      
                 ON  fus.followupstatus = tteq.followupstatus                        
                             
                             
                             
                             
                             
                             
                             
     DROP TABLE #temptableleads                        
 END                        
 ELSE                         
                         
                         
                         
 IF (LOWER(@SearchType) = 'co')                        
 BEGIN                        
     SELECT tteq.personname,                        
            tteq.companyname,                        
            ISNULL(tteq.mobileno, '')  AS MobileNo,                        
            ISNULL(tteq.mobileno1, '') AS MobileNo1,                        
           ISNULL(tteq.mobileno2, '') AS MobileNo2,                        
       ISNULL(tteq.emailid, '')   AS EMAILID,                        
            ISNULL(tteq.emailid1, '')  AS EmailID1,                        
            ISNULL(tteq.emailid2, '')  AS EmailID2,                        
            tteq.country,                        
            tteq.[state],                        
            tteq.city,                        
            tteq.pincode,                        
            tteq.residentialaddress,                        
       tteq.officeaddress,                        
            uss.NAME                   AS SourceName,                        
            ums.NAME                   AS MediumName,                        
            ucs.NAME                   AS CampaignName,                        
            tteq.initialremarks,                        
            @SearchID                  AS SearchID,                        
            @ParentID                  AS ParentID,                        
            @CampaignID                AS CampaignID                        
     FROM   #temptableconversion       AS tteq                        
            LEFT JOIN usermediumsettings ums   with (nolock)                      
                 ON  CAST(                        
                         CAST(tteq.mediumname AS VARCHAR(50)) COLLATE                         
                                                 
                                                 
                                                 
                         Latin1_General_CI_AI AS VARCHAR(50)                       
                     ) = CAST(                        
                         CAST(ums.MediumID AS VARCHAR(50))                         
                                                 
                                                 
                                                 
                         COLLATE                         
                                                 
                                   
                                                 
                         Latin1_General_CI_AI AS VARCHAR(50)                        
                     )                        
            LEFT JOIN usercampaignsettings ucs   with (nolock)                      
                 ON  CAST(                        
                         CAST(tteq.campaignname AS VARCHAR(50)) COLLATE                         
                               
                                                 
                                                 
       Latin1_General_CI_AI AS VARCHAR(50)                        
                     ) = CAST(                        
                         CAST(ucs.CampaignID AS VARCHAR(50))                        
                                                 
                                                 
                                                 
                         COLLATE                         
                                                 
                                                 
                                                 
                         Latin1_General_CI_AI AS VARCHAR(50)                        
                     )                        
            LEFT JOIN usersourcesettings uss   with (nolock)                      
                 ON  CAST(                        
                         CAST(tteq.sourcename AS VARCHAR(50)) COLLATE                         
                                                 
                                                 
                                                 
                         Latin1_General_CI_AI AS VARCHAR(50)                        
                     ) = CAST(                        
                         CAST(uss.SourceID AS VARCHAR(50))                    
                         COLLATE                     
                         Latin1_General_CI_AI AS VARCHAR(50)             
                     )                        
                             
                             
     DROP TABLE #temptableconversion                        
 END                        
 ELSE                         
                         
                         
                         
 IF (LOWER(@SearchType) = 'al')                        
 BEGIN                        
     SELECT A.personname,                        
            A.companyname,                        
            A.MobileNo,                      
            A.MobileNo1,                        
            A.MobileNo2,                        
            A.EMAILID,                        
            A.EmailID1,                        
            A.EmailID2,                        
            A.country,                        
            A.[state],                        
            A.city,                        
            A.pincode,                        
            A.residentialaddress,                        
            A.officeaddress,                        
            A.SourceName,                   
            A.MediumName,                        
            A.CampaignName,                        
            A.initialremarks,                        
            A.SearchID,                        
            A.ParentID,                        
            A.CampaignID                        
     FROM   (                        
                SELECT tteq.personname,                        
                       tteq.companyname,                        
                       ISNULL(tteq.mobileno, '') AS MobileNo,                        
                       ISNULL(tteq.mobileno1, '') AS MobileNo1,                        
                       ISNULL(tteq.mobileno2, '') AS MobileNo2,                        
                       ISNULL(tteq.emailid, '') AS EMAILID,                        
                       ISNULL(tteq.emailid1, '') AS EmailID1,                        
                       ISNULL(tteq.emailid2, '') AS EmailID2,                        
                       tteq.country,                        
                       tteq.[state],                        
                       tteq.city,                        
                       tteq.pincode,                        
                       tteq.residentialaddress,                        
                       tteq.officeaddress,                        
                       uss.NAME     AS SourceName,                        
                       ums.NAME     AS MediumName,                        
  ucs.NAME     AS CampaignName,                        
                       tteq.initialremarks,                        
                       @SearchID    AS SearchID,                        
                       @ParentID    AS ParentID,                        
                       @CampaignID  AS CampaignID                        
                FROM   #temptableconversion AS tteq                        
                       LEFT JOIN usermediumsettings ums   with (nolock)                      
                            ON  CAST(                        
                                    CAST(tteq.mediumname AS VARCHAR(50))                         
                                    COLLATE                         
                                                        
                                    Latin1_General_CI_AI AS VARCHAR(50)                        
                                ) = CAST(                        
                                    CAST(ums.MediumID AS VARCHAR(50))                         
                                                            
                                    COLLATE                         
                                                            
                                    Latin1_General_CI_AI AS VARCHAR(50)                        
                                )                        
       LEFT JOIN usercampaignsettings ucs  with (nolock)                       
                            ON  CAST(                        
                                    CAST(tteq.campaignname AS VARCHAR(50))                         
                                    COLLATE                         
                                                            
                                    Latin1_General_CI_AI AS VARCHAR(50)                        
                                ) = CAST(                        
                                    CAST(ucs.CampaignID AS VARCHAR(50))                        
                                                            
             COLLATE                         
                                                            
                                    Latin1_General_CI_AI AS VARCHAR(50)                        
                )                        
                       LEFT JOIN usersourcesettings uss  with (nolock)                       
                            ON  CAST(                        
                                    CAST(tteq.sourcename AS VARCHAR(50))                         
                                    COLLATE                         
                                                           
                                    Latin1_General_CI_AI AS VARCHAR(50)                        
                                ) = CAST(                        
                                    CAST(uss.SourceID AS VARCHAR(50))                         
                                                            
                                    COLLATE                         
        
                                    Latin1_General_CI_AI AS VARCHAR(50)                        
 )                        
                                        
                                        
      UNION                        
                 
                                        
                                        
                SELECT tteq.personname,                        
                       tteq.companyname,                        
                       ISNULL(tteq.mobileno, '') AS MobileNo,                        
                       ISNULL(tteq.mobileno1, '') AS MobileNo1,                        
                       ISNULL(tteq.mobileno2, '') AS MobileNo2,                        
                       ISNULL(tteq.emailid, '') AS EMAILID,                        
                       ISNULL(tteq.emailid1, '') AS EmailID1,                        
                       ISNULL(tteq.emailid2, '') AS EmailID2,                        
                       tteq.country,     
                       tteq.[state],                        
                       tteq.city,                        
                       tteq.pincode,                        
                       tteq.residentialaddress,                        
                       tteq.officeaddress,                        
                       uss.NAME     AS SourceName,                        
                       ums.NAME     AS MediumName,                        
                       ucs.NAME     AS CampaignName,                        
                       tteq.initialremarks,                        
                       @SearchID    AS SearchID,                        
                       @ParentID    AS ParentID,                        
                       @CampaignID  AS CampaignID                        
                FROM   #temptableenquiry AS tteq                        
                       LEFT JOIN usermediumsettings ums   with (nolock)                      
                            ON  CAST(                        
                                    CAST(tteq.mediumname AS VARCHAR(50))                         
                                    COLLATE                         
                                                            
             Latin1_General_CI_AI AS VARCHAR(50)                        
                                ) = CAST(                        
                                    CAST(ums.MediumID AS VARCHAR(50))                         
                                                            
                                    COLLATE                         
                                                            
                                    Latin1_General_CI_AI AS VARCHAR(50)                        
    )                        
                       LEFT JOIN usercampaignsettings ucs  with (nolock)                       
                            ON  CAST(                        
                                    CAST(tteq.campaignname AS VARCHAR(50))                         
                                    COLLATE                         
                                                            
                                    Latin1_General_CI_AI AS VARCHAR(50)                        
                                ) = CAST(                        
                                    CAST(ucs.CampaignID AS VARCHAR(50))                        
                                                    
                                    COLLATE                         
                                                            
                                    Latin1_General_CI_AI AS VARCHAR(50)                        
                                )                        
                       LEFT JOIN usersourcesettings uss   with (nolock)                      
                            ON  CAST(                        
                                    CAST(tteq.sourcename AS VARCHAR(50))                         
                                    COLLATE                         
                                                            
                Latin1_General_CI_AI AS VARCHAR(50)                        
                                ) = CAST(                        
                                    CAST(uss.SourceID AS VARCHAR(50))                         
                                                            
                                    COLLATE                         
                                                        
                                    Latin1_General_CI_AI AS VARCHAR(50)                        
                                )                        
                                        
            
                          
                UNION                        
                                        
                                        
                                        
                SELECT tteq.personname,                        
                       tteq.companyname,           
                       ISNULL(tteq.mobileno, '') AS MobileNo,                        
                       ISNULL(tteq.mobileno1, '') AS MobileNo1,                        
                       ISNULL(tteq.mobileno2, '') AS MobileNo2,                        
                       ISNULL(tteq.emailid, '') AS EMAILID,                        
                       ISNULL(tteq.emailid1, '') AS EmailID1,                        
                       ISNULL(tteq.emailid2, '') AS EmailID2,                        
               tteq.country,                        
                       tteq.[state],                        
                       tteq.city,                        
                       tteq.pincode,                        
                       tteq.residentialaddress,                        
                       tteq.officeaddress,                        
                       uss.NAME     AS SourceName,                        
                       ums.NAME     AS MediumName,                        
                       ucs.NAME     AS CampaignName,                        
                       tteq.initialremarks,                        
           @SearchID    AS SearchID,                        
                       @ParentID    AS ParentID,                        
                 @CampaignID  AS CampaignID                        
                FROM   #temptableleads AS tteq                        
                       LEFT JOIN usermediumsettings ums   with (nolock)                      
                            ON  CAST(                        
                                    CAST(tteq.mediumname AS VARCHAR(50))                         
                                    COLLATE                         
                                                            
                                    Latin1_General_CI_AI AS VARCHAR(50)                        
                                ) = CAST(                        
                                    CAST(ums.MediumID AS VARCHAR(50))                         
                                                            
                                    COLLATE                         
                                                            
                                    Latin1_General_CI_AI AS VARCHAR(50)                        
                                )                        
                       LEFT JOIN usercampaignsettings ucs   with (nolock)                      
                            ON  CAST(                        
                                    CAST(tteq.campaignname AS VARCHAR(50))                         
       COLLATE                         
                                                    
                                    Latin1_General_CI_AI AS VARCHAR(50)                        
                                ) = CAST(                        
                            CAST(ucs.CampaignID AS VARCHAR(50))                        
                                                            
                                    COLLATE                         
                                                            
                                    Latin1_General_CI_AI AS VARCHAR(50)                        
                       )                        
                       LEFT JOIN usersourcesettings uss  with (nolock)                       
                            ON  CAST(                        
                                    CAST(tteq.sourcename AS VARCHAR(50))                         
                                    COLLATE                         
                                                            
                                    Latin1_General_CI_AI AS VARCHAR(50)                        
                                ) = CAST(                        
                                    CAST(uss.SourceID AS VARCHAR(50))                         
                                                            
                                    COLLATE       
                                    Latin1_General_CI_AI AS VARCHAR(50)                        
                                )                        
            ) A              
                             
                             
                             
     DROP TABLE #temptableenquiry                              
                                      
  DROP TABLE #temptableleads                        
                                      
     DROP TABLE #temptableconversion                        
 END                        
END 


GO

/* ============================================================
   Procedure: [dbo].[usp_ExecuteUserSearch_New1]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


 CREATE   PROCEDURE [dbo].[usp_ExecuteUserSearch_New1] --335,230192,NULL--335,152762,NULL  
  @ParentID BIGINT,  
  @SearchID BIGINT,  
  @CampaignID BIGINT = NULL  
 AS  
 BEGIN   
  
DECLARE @SearchType                VARCHAR(50),  
        @Medium                    VARCHAR(50),  
        @Source                    VARCHAR(50),  
        @Campaign                  VARCHAR(50),  
        @SpecificName              VARCHAR(50),  
        @SpecificAddress           VARCHAR(50),  
        @SpecificMobileNo          VARCHAR(50),  
        @SpecificEmail             VARCHAR(50),  
        @SpecificCity              VARCHAR(50),  
        @SpecificState             VARCHAR(50),  
        @SpecificCountry           VARCHAR(50),  
        @CurrentlyAssignedTo       VARCHAR(50),  
        @FollowUpStatus            VARCHAR(50),  
        @CreatedBetweenFrom        VARCHAR(50),  
        @CreatedBetweenTo          VARCHAR(50),  
        @NextFollowUpDateFrom      VARCHAR(50),  
        @NextFollowUpDateTo        VARCHAR(50),  
        @ConvertedWithinFrom       VARCHAR(50),  
        @ConvertedWithinTo         VARCHAR(50),  
        @NameGRP                   VARCHAR(5000),  
        @CompanyGRP                VARCHAR(500),  
        @MobileGRP                 VARCHAR(5000),  
        @EmailGRP                  VARCHAR(5000),  
        @CityGRP                   VARCHAR(5000),  
        @StateGRP                  VARCHAR(5000),  
        @CountryGRP                VARCHAR(5000),  
        @AddressGRP                VARCHAR(500),  
        @BirthBetweenFromGRP       VARCHAR(50),  
        @BirthBetweenToGRP         VARCHAR(50),  
        @ANVBetweenFromGRP         VARCHAR(50),  
        @ANVBetweenToGRP           VARCHAR(50),  
        @CreatedBetweenFromGRP     VARCHAR(50),  
        @CreatedBetweenToGRP       VARCHAR(50),  
        @IsENQLeadCNV              BIT,  
        @IsGroup                   BIT    
   
   
   
SELECT @SearchType = usl.searchtype,  
       @Medium                    = usl.medium,  
       @Source                    = usl.source,  
       @Campaign                  = usl.campaign,  
       @SpecificName              = usl.specificname,  
       @SpecificAddress           = usl.specificaddress,  
       @SpecificMobileNo          = usl.specificmobileno,  
       @SpecificEmail             = usl.specificemail,  
       @SpecificCity              = usl.specificcity,  
       @SpecificState             = usl.specificstate,  
       @SpecificCountry           = usl.specificcountry,  
       @CurrentlyAssignedTo       = usl.currentlyassignedto,  
       @FollowUpStatus            = usl.followupstatus,  
       @CreatedBetweenFrom        = usl.createdbetweenfrom,  
       @CreatedBetweenTo          = usl.createdbetweento,  
       @NextFollowUpDateFrom      = usl.nextfollowupdatefrom,  
       @NextFollowUpDateTo        = usl.nextfollowupdateto,  
       @ConvertedWithinFrom       = usl.convertedwithinfrom,  
       @ConvertedWithinTo         = usl.convertedwithinto,  
       @NameGRP                   = usl.NameGRP,  
       @CompanyGRP                = usl.CompanyGRP,  
       @MobileGRP                 = usl.MobileGRP,  
       @EmailGRP                  = usl.EmailGRP,  
       @CityGRP                   = usl.CityGRP,  
       @StateGRP                  = usl.StateGRP,  
       @CountryGRP                = usl.CountryGRP,  
       @AddressGRP                = usl.AddressGRP,  
       @BirthBetweenFromGRP       = usl.BirthBetweenFromGRP,  
       @BirthBetweenToGRP         = usl.BirthBetweenToGRP,  
       @ANVBetweenFromGRP         = usl.ANVBetweenFromGRP,  
       @ANVBetweenToGRP           = usl.ANVBetweenToGRP,  
       @CreatedBetweenFromGRP     = usl.CreatedBetweenFrom,  
       @CreatedBetweenToGRP       = usl.CreatedBetweenToGRP,  
       @IsENQLeadCNV              = usl.IsENQLeadCNV,  
       @IsGroup                   = usl.IsGroup  
FROM   usersearchlist AS usl  
WHERE  usl.id = @SearchID    
   
   
   
   
   
   
   
   
   
   
   
   
   
   
   
   
   
IF (@IsGroup = 0)  
BEGIN  
    ----------------------------------Enquiry -------------------------    
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
    IF (LOWER(@SearchType) = 'en' OR LOWER(@SearchType) = 'al')  
    BEGIN  
        CREATE TABLE #temptableenquiry  
        (  
         id                     BIGINT,  
         personname             VARCHAR(200),  
         companyname            VARCHAR(200),  
         mobileno               VARCHAR(200),  
         mobileno1              VARCHAR(200),  
         mobileno2              VARCHAR(200),  
         emailid                VARCHAR(200),  
         emailid1               VARCHAR(200),  
         emailid2               VARCHAR(200),  
         city                   VARCHAR(200),  
         STATE                  VARCHAR(200),  
         country                VARCHAR(200),  
         countrycode            VARCHAR(200),  
         countrycode1           VARCHAR(200),  
         countrycode2           VARCHAR(200),  
         pincode                VARCHAR(200),  
         residentialaddress     VARCHAR(200),  
         officeaddress          VARCHAR(200),  
         sourcename             VARCHAR(200),  
         mediumname             VARCHAR(200),  
         campaignname           VARCHAR(200),  
         initialremarks         VARCHAR(1000),  
         datecreated            VARCHAR(50)  
        )    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        INSERT INTO #temptableenquiry  
          (  
            id,  
            personname,  
            companyname,  
            mobileno,  
            mobileno1,  
            mobileno2,  
            emailid,  
            emailid1,  
            emailid2,  
            city,  
            [state],  
            country,  
            countrycode,  
            countrycode1,  
            countrycode2,  
            pincode,  
            residentialaddress,  
            officeaddress,  
            sourcename,  
            mediumname,  
            campaignname,  
            initialremarks,  
            datecreated  
          )  
        SELECT ue.enquiryid,  
               ue.personname,  
               ue.companyname,  
               ue.mobileno,  
               ue.mobileno1,  
               ue.mobileno2,  
               ue.emailid,  
               ue.emailid1,  
               ue.emailid2,  
               ue.city,  
               ue.[state],  
               ue.country,  
               ue.countrycode,  
               ue.countrycode1,  
               ue.countrycode2,  
               ue.pincode,  
               ue.residentialaddress,  
               ue.officeaddress,  
               ue.sourcename,  
               ue.mediumname,  
               ue.campaignname,  
               ue.initialremarks,  
               ue.createddate  
        FROM   UserEnquiry AS ue  
        WHERE  ue.parentid = @ParentID    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@Medium, '') <> '' AND ISNULL(@Medium, '') <> '0')  
        BEGIN  
            DELETE   
            FROM   #temptableenquiry  
            WHERE  mediumname NOT IN (SELECT fs.[value]  
                                      FROM   dbo.Fn_split(@Medium, '#') AS fs)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
    
        IF (ISNULL(@Source, '') <> '' AND ISNULL(@Source, '') <> '0')  
        BEGIN  
            DELETE   
            FROM   #temptableenquiry  
            WHERE  sourcename NOT IN (SELECT fs.[value]  
                                      FROM   dbo.Fn_split(@Source, '#') AS fs)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (  
               ISNULL(@Campaign, '') <> ''  
               AND ISNULL(@Campaign, '') <> '0'  
           )  
        BEGIN  
            DELETE   
            FROM   #temptableenquiry  
            WHERE  campaignname NOT IN (SELECT fs.[value]  
                                        FROM   dbo.Fn_split(@Campaign, '#') AS   
                                               fs)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@SpecificName, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableenquiry  
            WHERE  personname = @SpecificName  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@SpecificAddress, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableenquiry  
            WHERE  residentialaddress LIKE '%' + @SpecificAddress + '%'  
                   OR  officeaddress LIKE '%' + @SpecificAddress + '%'  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@SpecificMobileNo, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableenquiry  
            WHERE  CAST(mobileno COLLATE Latin1_General_CI_AI AS VARCHAR(50))   
                     
                     
                     
                     
                     
                     
                     
                   NOT IN (SELECT fs.[value]  
                           FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)  
                   OR  CAST(mobileno1 COLLATE Latin1_General_CI_AI AS VARCHAR(50))   
                         
                         
                         
                         
                         
                         
                         
                       NOT IN (SELECT fs.[value]  
                               FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)  
                   OR  CAST(mobileno2 COLLATE Latin1_General_CI_AI AS VARCHAR(50))   
                         
                         
                         
                         
                         
                         
                         
                       NOT IN (SELECT fs.[value]  
                               FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
   IF (ISNULL(@SpecificEmail, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableenquiry  
            WHERE  CAST(emailid COLLATE Latin1_General_CI_AI AS VARCHAR(250))   
                     
                     
                     
                     
                     
                     
                     
                   NOT IN (SELECT fs.[value]  
                           FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)  
                   OR  CAST(emailid1 COLLATE Latin1_General_CI_AI AS VARCHAR(250))   
                         
                         
                         
                         
                         
                         
                         
                       NOT IN (SELECT fs.[value]  
                               FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)  
                   OR  CAST(emailid2 COLLATE Latin1_General_CI_AI AS VARCHAR(250))   
                         
                         
                         
                         
                         
                         
                         
                       NOT IN (SELECT fs.[value]  
                               FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@SpecificCity, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableenquiry  
            WHERE  city = @SpecificCity  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@SpecificCountry, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableenquiry  
            WHERE  country = @SpecificCountry  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@SpecificState, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableenquiry  
            WHERE  [state] = @SpecificState  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (  
               ISNULL(@CreatedBetweenFrom, '') <> ''  
               AND ISNULL(@CreatedBetweenTo, '') <> ''  
           )  
        BEGIN  
            DELETE   
            FROM   #temptableenquiry  
            WHERE  id NOT IN (SELECT ue.enquiryid  
                              FROM   userenquiry AS ue  
                              WHERE  DATEDIFF(d, ue.createddate, GETDATE())   
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                        
                                     BETWEEN   
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                     @CreatedBetweenFrom AND   
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                     @CreatedBetweenTo)  
        END  
    END   
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
    ---------------------------------- LEADS -------------------------    
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
    IF (LOWER(@SearchType) = 'le' OR LOWER(@SearchType) = 'al')  
    BEGIN  
        CREATE TABLE #temptableleads  
        (  
         id                     BIGINT,  
         personname             VARCHAR(200),  
         companyname            VARCHAR(200),  
         mobileno               VARCHAR(200),  
         mobileno1              VARCHAR(200),  
         mobileno2              VARCHAR(200),  
         emailid                VARCHAR(200),  
         emailid1               VARCHAR(200),  
         emailid2               VARCHAR(200),  
         city                   VARCHAR(200),  
         STATE                  VARCHAR(200),  
         country                VARCHAR(200),  
         countrycode            VARCHAR(200),  
         countrycode1           VARCHAR(200),  
         countrycode2           VARCHAR(200),  
         pincode                VARCHAR(200),  
         residentialaddress     VARCHAR(200),  
         officeaddress          VARCHAR(200),  
         sourcename             VARCHAR(200) COLLATE   
           
           
           
           
           
           
           
           
           
           
           
           
           
           
           
         sql_latin1_general_cp1_ci_as,  
         mediumname             VARCHAR(200) COLLATE   
           
           
           
           
           
           
           
           
           
           
           
           
           
           
           
         sql_latin1_general_cp1_ci_as,  
         campaignname           VARCHAR(200) COLLATE   
           
           
           
           
           
           
           
           
           
           
           
           
           
           
           
         sql_latin1_general_cp1_ci_as,  
         initialremarks         VARCHAR(1000),  
         datecreated            VARCHAR(50),  
         assignedto             VARCHAR(200),  
         followupstatus         VARCHAR(200),  
         nextfollowupdate       VARCHAR(200)  
        )    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
      
          
          
          
        INSERT INTO #temptableleads  
          (  
            id,  
            personname,  
            companyname,  
            mobileno,  
            mobileno1,  
            mobileno2,  
            emailid,  
            emailid1,  
            emailid2,  
            city,  
            [state],  
            country,  
            countrycode,  
            countrycode1,  
            countrycode2,  
            pincode,  
            residentialaddress,  
            officeaddress,  
            sourcename,  
            mediumname,  
            campaignname,  
            initialremarks,  
            datecreated,  
            assignedto,  
            followupstatus,  
            nextfollowupdate  
          )  
        SELECT ue.id,  
               ue.personname,  
               ue.companyname,  
               ue.mobileno,  
               ue.mobileno1,  
               ue.mobileno2,  
               ue.emailid,  
               ue.emailid1,  
               ue.emailid2,  
               ue.city,  
               ue.[state],  
               ue.country,  
               ue.countrycode,  
               ue.countrycode1,  
               ue.countrycode2,  
               ue.pincode,  
               ue.residentialaddress,  
               ue.officeaddress,  
               ue.sourcename,  
               ue.mediumname,  
               ue.campaignname,  
               ue.initialremarks,  
               ue.createdon,  
               ue.assignedto,  
               ue.followupstatus,  
               ue.nextstatusdate  
        FROM   UserLeads AS ue  
        WHERE  ue.ParentID = @ParentID    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@Medium, '') <> '' AND ISNULL(@Medium, '') <> '0')  
        BEGIN  
            DELETE   
            FROM   #temptableleads  
            WHERE  mediumname NOT IN (SELECT fs.[value]  
                                      FROM   dbo.Fn_split(@Medium, '#') AS fs)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@Source, '') <> '' AND ISNULL(@Source, '') <> '0')  
        BEGIN  
            DELETE   
            FROM   #temptableleads  
            WHERE  sourcename NOT IN (SELECT fs.[value]  
                                      FROM   dbo.Fn_split(@Source, '#') AS fs)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (  
               ISNULL(@Campaign, '') <> ''  
               AND ISNULL(@Campaign, '') <> '0'  
           )  
        BEGIN  
            DELETE   
            FROM   #temptableleads  
            WHERE  campaignname NOT IN (SELECT fs.[value]  
                                        FROM   dbo.Fn_split(@Campaign, '#') AS   
                                               fs)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@SpecificName, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableleads  
            WHERE  personname = @SpecificName  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@SpecificAddress, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableleads  
            WHERE  residentialaddress LIKE '%' + @SpecificAddress + '%'  
                   OR  officeaddress LIKE '%' + @SpecificAddress + '%'  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@SpecificMobileNo, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableleads  
            WHERE  CAST(mobileno COLLATE Latin1_General_CI_AI AS VARCHAR(50))   
                     
                     
                     
                     
                     
                     
                     
                   NOT IN (SELECT fs.[value]  
                           FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)  
                   OR  CAST(mobileno1 COLLATE Latin1_General_CI_AI AS VARCHAR(50))   
                         
                         
                         
                         
                         
                         
                         
                       NOT IN (SELECT fs.[value]  
                               FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)  
                   OR  CAST(mobileno2 COLLATE Latin1_General_CI_AI AS VARCHAR(50))   
                         
                         
                         
                         
                         
                         
                         
                       NOT IN (SELECT fs.[value]  
                               FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@SpecificEmail, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableleads  
            WHERE  CAST(emailid COLLATE Latin1_General_CI_AI AS VARCHAR(250))   
                     
                     
                     
                     
                     
                     
                     
                   NOT IN (SELECT fs.[value]  
                           FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)  
                   OR  CAST(emailid1 COLLATE Latin1_General_CI_AI AS VARCHAR(250))   
                         
                         
                         
                         
                         
                         
                         
                       NOT IN (SELECT fs.[value]  
                               FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)  
                   OR  CAST(emailid2 COLLATE Latin1_General_CI_AI AS VARCHAR(250))   
                         
                         
                         
                         
                         
                         
                         
                       NOT IN (SELECT fs.[value]  
                               FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
  
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@SpecificCity, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableleads  
            WHERE  city = @SpecificCity  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@SpecificCountry, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableleads  
            WHERE  country = @SpecificCountry  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@SpecificState, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableleads  
            WHERE  [state] = @SpecificState  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (  
               ISNULL(@CurrentlyAssignedTo, '') <> ''  
               AND ISNULL(@CurrentlyAssignedTo, '') <> '0'  
           )  
        BEGIN  
            DELETE   
            FROM   #temptableleads  
            WHERE  assignedto NOT IN (SELECT fs.[value]  
                                      FROM   dbo.Fn_split(@CurrentlyAssignedTo, ',') AS   
                                             fs)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (  
               ISNULL(@CreatedBetweenFrom, '') <> ''  
               AND ISNULL(@CreatedBetweenTo, '') <> ''  
           )  
        BEGIN  
            DELETE   
            FROM   #temptableleads  
            WHERE  id NOT IN (SELECT ue.id  
                              FROM   userleads AS ue  
                              WHERE  DATEDIFF(d, ue.createdon, GETDATE())   
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                     BETWEEN   
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                     @CreatedBetweenFrom AND   
                                       
                                     
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                     @CreatedBetweenTo  
                                     AND ue.parentid = @ParentID)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (  
               ISNULL(@NextFollowUpDateFrom, '') <> ''  
               AND ISNULL(@NextFollowUpDateTo, '') <> ''  
           )  
        BEGIN  
            DELETE   
            FROM   #temptableleads  
            WHERE  id NOT IN (SELECT ue.id  
                              FROM   userleads AS ue  
                                     INNER JOIN leadinteractionhistory lih  
                                          ON  lih.leadno = ue.leadno  
                              WHERE  DATEDIFF(d, GETDATE(), lih.nextstatusdate)   
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                     BETWEEN   
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                     @NextFollowUpDateFrom AND   
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                     @NextFollowUpDateTo  
                                     AND ue.parentid = @ParentID)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (  
               ISNULL(@FollowUpStatus, '') <> ''  
               AND ISNULL(@FollowUpStatus, '') <> '0'  
           )  
        BEGIN  
         DELETE   
            FROM   #temptableleads  
            WHERE  followupstatus NOT IN (SELECT fs.[value]  
                                          FROM   dbo.Fn_split(@FollowUpStatus, '#') AS   
                                                 fs)  
        END  
    END   
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
    ---------------------------------- Conversions -------------------------    
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
    IF (LOWER(@SearchType) = 'co' OR LOWER(@SearchType) = 'al')  
    BEGIN  
        CREATE TABLE #temptableconversion  
        (  
         id                     BIGINT,  
         personname             VARCHAR(200),  
         companyname            VARCHAR(200),  
         mobileno               VARCHAR(200),  
         mobileno1              VARCHAR(200),  
         mobileno2              VARCHAR(200),  
         emailid                VARCHAR(200),  
         emailid1               VARCHAR(200),  
         emailid2               VARCHAR(200),  
         city                   VARCHAR(200),  
         STATE                  VARCHAR(200),  
         country                VARCHAR(200),  
         countrycode            VARCHAR(200),  
         pincode                VARCHAR(200),  
         residentialaddress     VARCHAR(200),  
         officeaddress          VARCHAR(200),  
         sourcename             VARCHAR(200) COLLATE   
           
           
           
           
           
           
           
           
           
           
           
           
           
           
           
         sql_latin1_general_cp1_ci_as,  
         mediumname             VARCHAR(200) COLLATE   
           
           
           
           
           
           
           
           
           
           
           
           
           
           
           
         sql_latin1_general_cp1_ci_as,  
         campaignname           VARCHAR(200) COLLATE   
           
           
           
           
           
           
           
           
           
           
           
           
           
           
           
         sql_latin1_general_cp1_ci_as,  
         initialremarks         VARCHAR(1000),  
         datecreated            VARCHAR(50),  
         assignedto             VARCHAR(200),  
         followupstatus         VARCHAR(200),  
         nextfollowupdate       VARCHAR(200)  
        )    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        INSERT INTO #temptableconversion  
          (  
            id,  
            personname,  
            companyname,  
            mobileno,  
            mobileno1,  
            mobileno2,  
            emailid,  
            emailid1,  
            emailid2,  
            city,  
            [state],  
            country,  
            countrycode,  
            pincode,  
            residentialaddress,  
            officeaddress,  
            sourcename,  
            mediumname,  
            campaignname,  
            initialremarks,  
            datecreated,  
            assignedto,  
            followupstatus,  
            nextfollowupdate  
          )  
        SELECT ue.id,  
               ue.personname,  
               ue.companyname,  
               ue.mobileno,  
               ue.mobileno1,  
               ue.mobileno2,  
               ue.emailid,  
               ue.emailid1,  
               ue.emailid2,  
               ue.city,  
               ue.[state],  
               ue.country,  
               ue.countrycode,  
               ue.pincode,  
               ue.residentialaddress,  
               ue.officeaddress,  
   ue.sourcename,  
               ue.mediumname,  
               ue.campaignname,  
               ue.initialremarks,  
               ue.createdon,  
               ue.assignedto,  
               ue.followupstatus,  
               ue.nextstatusdate  
        FROM   UserLeads AS ue  
               INNER JOIN LeadInteractionHistory AS lih  
                    ON  lih.LeadNo = ue.LeadNo  
                    AND lih.ParentID = @ParentID  
                    AND ISNULL(NULLIF(lih.amountpaid, 0), 0) <> 0  
        WHERE  ue.ParentID = @ParentID    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@Medium, '') <> '' AND ISNULL(@Medium, '') <> '0')  
        BEGIN  
            DELETE   
            FROM   #temptableconversion  
            WHERE  mediumname NOT IN (SELECT fs.[value]  
                                      FROM   dbo.Fn_split(@Medium, '#') AS fs)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@Source, '') <> '' AND ISNULL(@Source, '') <> '0')  
        BEGIN  
            DELETE   
            FROM   #temptableconversion  
            WHERE  sourcename NOT IN (SELECT fs.[value]  
                                      FROM   dbo.Fn_split(@Source, '#') AS fs)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (  
               ISNULL(@Campaign, '') <> ''  
               AND ISNULL(@Campaign, '') <> '0'  
           )  
        BEGIN  
            DELETE   
            FROM   #temptableconversion  
            WHERE  campaignname NOT IN (SELECT fs.[value]  
                                        FROM   dbo.Fn_split(@Campaign, '#') AS   
                                               fs)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@SpecificName, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableconversion  
            WHERE  personname = @SpecificName  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@SpecificAddress, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableconversion  
            WHERE  residentialaddress LIKE '%' + @SpecificAddress + '%'  
                   OR  officeaddress LIKE '%' + @SpecificAddress + '%'  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@SpecificMobileNo, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableconversion  
            WHERE  CAST(mobileno COLLATE Latin1_General_CI_AI AS VARCHAR(50))   
                     
                     
                     
                     
                     
                     
                     
                   NOT IN (SELECT fs.[value]  
                           FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)  
                   OR  CAST(mobileno1 COLLATE Latin1_General_CI_AI AS VARCHAR(50))   
                         
                         
                         
                         
                         
                         
                         
                       NOT IN (SELECT fs.[value]  
                               FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)  
                   OR  CAST(mobileno2 COLLATE Latin1_General_CI_AI AS VARCHAR(50))   
                         
                         
                         
                         
                         
                         
                         
                       NOT IN (SELECT fs.[value]  
                               FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@SpecificEmail, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableconversion  
            WHERE  CAST(emailid COLLATE Latin1_General_CI_AI AS VARCHAR(250))   
                     
                     
                     
                     
                     
                     
                     
                   NOT IN (SELECT fs.[value]  
                           FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)  
                   OR  CAST(emailid1 COLLATE Latin1_General_CI_AI AS VARCHAR(250))   
                         
                         
                         
                         
                         
                         
                         
                       NOT IN (SELECT fs.[value]  
                               FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)  
                   OR  CAST(emailid2 COLLATE Latin1_General_CI_AI AS VARCHAR(250))   
                         
                         
                         
                         
                         
                         
                         
                       NOT IN (SELECT fs.[value]  
                               FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@SpecificCity, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableconversion  
            WHERE  city = @SpecificCity  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (ISNULL(@SpecificCountry, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableconversion  
            WHERE  country = @SpecificCountry  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
     
          
          
          
        IF (ISNULL(@SpecificState, '') <> '')  
        BEGIN  
            DELETE   
            FROM   #temptableconversion  
            WHERE  [state] = @SpecificState  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (  
               ISNULL(@CurrentlyAssignedTo, '') <> ''  
               AND ISNULL(@CurrentlyAssignedTo, '') <> '0'  
           )  
        BEGIN  
            DELETE   
            FROM   #temptableconversion  
            WHERE  assignedto NOT IN (SELECT fs.[value]  
                                      FROM   dbo.Fn_split(@CurrentlyAssignedTo, ',') AS   
                                             fs)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (  
               ISNULL(@CreatedBetweenFrom, '') <> ''  
               AND ISNULL(@CreatedBetweenTo, '') <> ''  
           )  
        BEGIN  
            DELETE   
            FROM   #temptableconversion  
            WHERE  id NOT IN (SELECT ue.id  
                              FROM   userleads AS ue  
                              WHERE  DATEDIFF(d, ue.createdon, GETDATE())   
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                     BETWEEN   
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                     @CreatedBetweenFrom AND   
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                     @CreatedBetweenTo  
                                     AND ue.parentid = @ParentID)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (  
  ISNULL(@NextFollowUpDateFrom, '') <> ''  
               AND ISNULL(@NextFollowUpDateTo, '') <> ''  
           )  
        BEGIN  
            DELETE   
            FROM   #temptableconversion  
            WHERE  id NOT IN (SELECT ue.id  
                              FROM   userleads AS ue  
                                     INNER JOIN leadinteractionhistory lih  
                                          ON  lih.leadno = ue.leadno  
                              WHERE  DATEDIFF(d, GETDATE(), lih.nextstatusdate)   
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                     BETWEEN   
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                     @NextFollowUpDateFrom AND   
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                     @NextFollowUpDateTo  
                                     AND ue.parentid = @ParentID)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (  
               ISNULL(@ConvertedWithinFrom, '') <> ''  
               AND ISNULL(@ConvertedWithinTo, '') <> ''  
           )  
        BEGIN  
            DELETE   
            FROM   #temptableconversion  
            WHERE  id NOT IN (SELECT ue.id  
                              FROM   userleads AS ue  
                                     INNER JOIN leadinteractionhistory lih  
                                          ON  lih.leadno = ue.leadno  
                                          AND ISNULL(NULLIF(lih.amountpaid, 0), 0)   
                                                
                                                
                                                
                                                
                                                
                                                
                                                
                                                
                                                
                                                
                                                
                                                
     
                                                
                                                
                                              <>  
                                                
                                                
                                                
                                                
                                                
                                                
                                                
                                                
                                                
                                                
                                                
                                                
                                                
                                                
                                                
                                              0  
                              WHERE  DATEDIFF(d, lih.createdon, GETDATE())   
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                     BETWEEN   
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                     @ConvertedWithinFrom AND   
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                       
                                     @ConvertedWithinTo  
                                     AND ue.parentid = @ParentID)  
        END    
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        IF (  
               ISNULL(@FollowUpStatus, '') <> ''  
               AND ISNULL(@FollowUpStatus, '') <> '0'  
           )  
        BEGIN  
            DELETE   
            FROM   #temptableconversion  
            WHERE  followupstatus NOT IN (SELECT fs.[value]  
                                          FROM   dbo.Fn_split(@FollowUpStatus, '#') AS   
                                                 fs)  
        END  
    END    
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
    IF (LOWER(@SearchType) = 'en')  
    BEGIN  
        SELECT tteq.personname,  
               tteq.companyname,  
               ISNULL(tteq.mobileno, '')  AS MobileNo,  
               ISNULL(tteq.mobileno1, '') AS MobileNo1,  
               ISNULL(tteq.mobileno2, '') AS MobileNo2,  
               ISNULL(tteq.emailid, '')   AS EMAILID,  
               ISNULL(tteq.emailid1, '')  AS EmailID1,  
               ISNULL(tteq.emailid2, '')  AS EmailID2,  
               tteq.country,  
               tteq.[state],  
               tteq.city,  
               tteq.pincode,  
               tteq.residentialaddress,  
               tteq.officeaddress,  
               uss.NAME                   AS SourceName,  
               ums.NAME                   AS MediumName,  
               ucs.NAME                   AS CampaignName,  
               tteq.initialremarks,  
               @SearchID                  AS SearchID,  
               @ParentID                  AS ParentID,  
               @CampaignID                AS CampaignID  
        FROM   #temptableenquiry          AS tteq  
               LEFT JOIN usermediumsettings ums  
                    ON  tteq.mediumname = ums.mediumid  
               LEFT JOIN usercampaignsettings ucs  
                    ON  tteq.campaignname = ucs.campaignid  
               LEFT JOIN usersourcesettings uss  
                    ON  tteq.sourcename = uss.sourceid   
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        DROP TABLE #temptableenquiry  
    END  
    ELSE     
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
    IF (LOWER(@SearchType) = 'le')  
    BEGIN  
        SELECT tteq.personname,  
               tteq.companyname,  
               ISNULL(tteq.mobileno, '')  AS MobileNo,  
               ISNULL(tteq.mobileno1, '') AS MobileNo1,  
               ISNULL(tteq.mobileno2, '') AS MobileNo2,  
               ISNULL(tteq.emailid, '')   AS EMAILID,  
               ISNULL(tteq.emailid1, '')  AS EmailID1,  
               ISNULL(tteq.emailid2, '')  AS EmailID2,  
               tteq.country,  
               tteq.[state],  
               tteq.city,  
               tteq.pincode,  
               tteq.residentialaddress,  
               tteq.officeaddress,  
               uss.NAME                   AS SourceName,  
               ums.NAME                   AS MediumName,  
               ucs.NAME                   AS CampaignName,  
               tteq.initialremarks,  
               @SearchID                  AS SearchID,  
               @ParentID                  AS ParentID,  
               @CampaignID                AS CampaignID  
        FROM   #temptableleads            AS tteq  
               LEFT JOIN usermediumsettings ums  
                    ON  CAST(  
                            CAST(tteq.mediumname AS VARCHAR(50)) COLLATE   
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                            Latin1_General_CI_AI AS VARCHAR(50)  
                        ) = CAST(  
                            CAST(ums.MediumID AS VARCHAR(50))   
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
   
                              
                              
                              
                            COLLATE   
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                            Latin1_General_CI_AI AS VARCHAR(50)  
                        )  
               LEFT JOIN usercampaignsettings ucs  
                    ON  CAST(  
                            CAST(tteq.campaignname AS VARCHAR(50)) COLLATE   
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                            Latin1_General_CI_AI AS VARCHAR(50)  
                        ) = CAST(  
                            CAST(ucs.CampaignID AS VARCHAR(50))   
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                            COLLATE   
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                            Latin1_General_CI_AI AS VARCHAR(50)  
                        )  
               LEFT JOIN usersourcesettings uss  
                    ON  CAST(  
                            CAST(tteq.sourcename AS VARCHAR(50)) COLLATE   
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                            Latin1_General_CI_AI AS VARCHAR(50)  
                        ) = CAST(  
                            CAST(uss.SourceID AS VARCHAR(50))   
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                            COLLATE   
                              
                              
                              
                              
                              
                              
                              
                              
     
                              
                              
                              
                              
                              
                              
                            Latin1_General_CI_AI AS VARCHAR(50)  
                        )  
               LEFT JOIN followup_status fus  
                    ON  CAST(  
                            CAST(tteq.followupstatus AS VARCHAR(50)) COLLATE   
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                            Latin1_General_CI_AI AS VARCHAR(50)  
                        ) = CAST(  
                            CAST(fus.followupstatus AS VARCHAR(50))   
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                            COLLATE   
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                            Latin1_General_CI_AI AS VARCHAR(50)  
                        )   
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        DROP TABLE #temptableleads  
    END  
    ELSE     
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
    IF (LOWER(@SearchType) = 'co')  
    BEGIN  
        SELECT tteq.personname,  
               tteq.companyname,  
               ISNULL(tteq.mobileno, '')  AS MobileNo,  
               ISNULL(tteq.mobileno1, '') AS MobileNo1,  
               ISNULL(tteq.mobileno2, '') AS MobileNo2,  
               ISNULL(tteq.emailid, '')   AS EMAILID,  
               ISNULL(tteq.emailid1, '')  AS EmailID1,  
               ISNULL(tteq.emailid2, '')  AS EmailID2,  
               tteq.country,  
               tteq.[state],  
               tteq.city,  
               tteq.pincode,  
               tteq.residentialaddress,  
               tteq.officeaddress,  
               uss.NAME                   AS SourceName,  
               ums.NAME                   AS MediumName,  
               ucs.NAME                   AS CampaignName,  
               tteq.initialremarks,  
               @SearchID                  AS SearchID,  
               @ParentID                  AS ParentID,  
               @CampaignID                AS CampaignID  
        FROM   #temptableconversion       AS tteq  
               LEFT JOIN usermediumsettings ums  
                    ON  CAST(  
                            CAST(tteq.mediumname AS VARCHAR(50)) COLLATE   
                              
                              
                              
                              
                              
                              
                              
               
                              
                              
                              
                              
                              
                              
                              
                            Latin1_General_CI_AI AS VARCHAR(50)  
                        ) = CAST(  
                            CAST(ums.MediumID AS VARCHAR(50))   
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                            COLLATE   
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                            Latin1_General_CI_AI AS VARCHAR(50)  
                        )  
               LEFT JOIN usercampaignsettings ucs  
                    ON  CAST(  
                            CAST(tteq.campaignname AS VARCHAR(50)) COLLATE   
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                            Latin1_General_CI_AI AS VARCHAR(50)  
                        ) = CAST(  
                            CAST(ucs.CampaignID AS VARCHAR(50))   
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                            COLLATE   
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                            Latin1_General_CI_AI AS VARCHAR(50)  
                        )  
               LEFT JOIN usersourcesettings uss  
                    ON  CAST(  
                            CAST(tteq.sourcename AS VARCHAR(50)) COLLATE   
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                            Latin1_General_CI_AI AS VARCHAR(50)  
                        ) = CAST(  
                            CAST(uss.SourceID AS VARCHAR(50))   
                       
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                            COLLATE   
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                              
                            Latin1_General_CI_AI AS VARCHAR(50)  
                        )   
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
        DROP TABLE #temptableconversion  
    END  
    ELSE     
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
    IF (LOWER(@SearchType) = 'al')  
    BEGIN  
        SELECT A.personname,  
               A.companyname,  
               A.MobileNo,  
               A.MobileNo1,  
               A.MobileNo2,  
               A.EMAILID,  
               A.EmailID1,  
               A.EmailID2,  
               A.country,  
               A.[state],  
               A.city,  
               A.pincode,  
               A.residentialaddress,  
               A.officeaddress,  
               A.SourceName,  
               A.MediumName,  
               A.CampaignName,  
               A.initialremarks,  
               A.SearchID,  
               A.ParentID,  
               A.CampaignID  
        FROM   (  
                   SELECT tteq.personname,  
                          tteq.companyname,  
                          ISNULL(tteq.mobileno, '') AS MobileNo,  
                          ISNULL(tteq.mobileno1, '') AS MobileNo1,  
                          ISNULL(tteq.mobileno2, '') AS MobileNo2,  
                          ISNULL(tteq.emailid, '') AS EMAILID,  
                          ISNULL(tteq.emailid1, '') AS EmailID1,  
                          ISNULL(tteq.emailid2, '') AS EmailID2,  
                          tteq.country,  
                          tteq.[state],  
                          tteq.city,  
                          tteq.pincode,  
                          tteq.residentialaddress,  
                          tteq.officeaddress,  
                          uss.NAME     AS SourceName,  
                          ums.NAME     AS MediumName,  
                          ucs.NAME     AS CampaignName,  
                          tteq.initialremarks,  
                          @SearchID    AS SearchID,  
                          @ParentID    AS ParentID,  
                          @CampaignID  AS CampaignID  
                   FROM   #temptableconversion AS tteq  
                          LEFT JOIN usermediumsettings ums  
                               ON  CAST(  
                                       CAST(tteq.mediumname AS VARCHAR(50))   
                                         
                                         
                                         
                                       COLLATE   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                         Latin1_General_CI_AI AS VARCHAR(50)  
                                   ) = CAST(  
                                       CAST(ums.MediumID AS VARCHAR(50))   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       COLLATE   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       Latin1_General_CI_AI AS VARCHAR(50)  
                                   )  
                          LEFT JOIN usercampaignsettings ucs  
                               ON  CAST(  
                                       CAST(tteq.campaignname AS VARCHAR(50))   
                                         
                                         
                                         
                                       COLLATE   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       Latin1_General_CI_AI AS VARCHAR(50)  
                                   ) = CAST(  
                                       CAST(ucs.CampaignID AS VARCHAR(50))   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       COLLATE   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       Latin1_General_CI_AI AS VARCHAR(50)  
                                   )  
                          LEFT JOIN usersourcesettings uss  
                               ON  CAST(  
                                       CAST(tteq.sourcename AS VARCHAR(50))   
                                         
                                         
                                         
                                       COLLATE   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       Latin1_General_CI_AI AS VARCHAR(50)  
                                   ) = CAST(  
                                       CAST(uss.SourceID AS VARCHAR(50))   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       COLLATE   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       Latin1_General_CI_AI AS VARCHAR(50)  
                                   )   
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                   UNION    
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                     
                   SELECT tteq.personname,  
                          tteq.companyname,  
                          ISNULL(tteq.mobileno, '') AS MobileNo,  
                          ISNULL(tteq.mobileno1, '') AS MobileNo1,  
                          ISNULL(tteq.mobileno2, '') AS MobileNo2,  
                          ISNULL(tteq.emailid, '') AS EMAILID,  
                          ISNULL(tteq.emailid1, '') AS EmailID1,  
                          ISNULL(tteq.emailid2, '') AS EmailID2,  
                          tteq.country,  
                          tteq.[state],  
                          tteq.city,  
                          tteq.pincode,  
                          tteq.residentialaddress,  
                          tteq.officeaddress,  
                          uss.NAME     AS SourceName,  
                          ums.NAME     AS MediumName,  
                          ucs.NAME     AS CampaignName,  
                          tteq.initialremarks,  
                          @SearchID    AS SearchID,  
                          @ParentID    AS ParentID,  
                          @CampaignID  AS CampaignID  
                   FROM   #temptableenquiry AS tteq  
                          LEFT JOIN usermediumsettings ums  
                               ON  CAST(  
                                       CAST(tteq.mediumname AS VARCHAR(50))   
                                         
                                         
                                         
                                       COLLATE   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       Latin1_General_CI_AI AS VARCHAR(50)  
                                   ) = CAST(  
                                       CAST(ums.MediumID AS VARCHAR(50))   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       COLLATE   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       Latin1_General_CI_AI AS VARCHAR(50)  
                                   )  
                          LEFT JOIN usercampaignsettings ucs  
                               ON  CAST(  
                                       CAST(tteq.campaignname AS VARCHAR(50))   
                                         
                                         
                                         
                                       COLLATE   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       Latin1_General_CI_AI AS VARCHAR(50)  
                                   ) = CAST(  
                                       CAST(ucs.CampaignID AS VARCHAR(50))   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       COLLATE   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       Latin1_General_CI_AI AS VARCHAR(50)  
                                   )  
                          LEFT JOIN usersourcesettings uss  
                               ON  CAST(  
                                       CAST(tteq.sourcename AS VARCHAR(50))   
                                         
                                         
                                         
                                       COLLATE   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       Latin1_General_CI_AI AS VARCHAR(50)  
                                   ) = CAST(  
                                       CAST(uss.SourceID AS VARCHAR(50))   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       COLLATE   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       Latin1_General_CI_AI AS VARCHAR(50)  
                                   )   
                     
                     
                     
                   UNION     
                     
                   SELECT tteq.personname,  
                          tteq.companyname,  
                          ISNULL(tteq.mobileno, '') AS MobileNo,  
                          ISNULL(tteq.mobileno1, '') AS MobileNo1,  
                          ISNULL(tteq.mobileno2, '') AS MobileNo2,  
                          ISNULL(tteq.emailid, '') AS EMAILID,  
                          ISNULL(tteq.emailid1, '') AS EmailID1,  
                          ISNULL(tteq.emailid2, '') AS EmailID2,  
                          tteq.country,  
                          tteq.[state],  
                          tteq.city,  
                          tteq.pincode,  
                          tteq.residentialaddress,  
                          tteq.officeaddress,  
                          uss.NAME     AS SourceName,  
                          ums.NAME     AS MediumName,  
                          ucs.NAME     AS CampaignName,  
                          tteq.initialremarks,  
                          @SearchID    AS SearchID,  
                          @ParentID    AS ParentID,  
       @CampaignID  AS CampaignID  
                   FROM   #temptableleads AS tteq  
                          LEFT JOIN usermediumsettings ums  
                               ON  CAST(  
                                       CAST(tteq.mediumname AS VARCHAR(50))   
                                         
                                         
                                         
                                       COLLATE   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       Latin1_General_CI_AI AS VARCHAR(50)  
                                   ) = CAST(  
                                       CAST(ums.MediumID AS VARCHAR(50))   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       COLLATE   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       Latin1_General_CI_AI AS VARCHAR(50)  
                                   )  
                          LEFT JOIN usercampaignsettings ucs  
                               ON  CAST(  
                                       CAST(tteq.campaignname AS VARCHAR(50))   
                                         
                                         
                                         
                                       COLLATE   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       Latin1_General_CI_AI AS VARCHAR(50)  
                                   ) = CAST(  
                                       CAST(ucs.CampaignID AS VARCHAR(50))   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       COLLATE   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       Latin1_General_CI_AI AS VARCHAR(50)  
                                   )  
                          LEFT JOIN usersourcesettings uss  
                               ON  CAST(  
                                       CAST(tteq.sourcename AS VARCHAR(50))   
                                         
                                         
                                         
                                       COLLATE   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       Latin1_General_CI_AI AS VARCHAR(50)  
                                   ) = CAST(  
                                      CAST(uss.SourceID AS VARCHAR(50))   
                                         
                                         
                                         
                                         
                                         
                                         
                                         
                                       COLLATE   
                                         
                                         
                                         
                                       Latin1_General_CI_AI AS VARCHAR(50)  
                                   )  
               ) A   
          
          
          
          
          
        DROP TABLE #temptableenquiry   
          
        DROP TABLE #temptableleads   
          
        DROP TABLE #temptableconversion  
    END  
END  
ELSE  
BEGIN   
    SELECT Contact_Name         AS NAME,  
           Contact_Mobile       AS Mobile,  
           Contact_Email        AS Email,  
           Contact_DOB          AS DOB,  
           Contact_Anniversary  AS Anniversary,  
           CompanyName          AS 'Company Name',  
           City,  
           STATE,  
           Country,  
           ADDRESS,  
           DateCreated          AS CreatedOn  
    FROM   Contact_Detail  
    WHERE  USER_ID = @ParentID  
           AND (  
                   Contact_Name IN (SELECT fs.[value]  
                                    FROM   dbo.Fn_split(ISNULL(@NameGRP, ''), ',') AS   
                                           fs)  
                   OR Contact_Mobile IN (SELECT fs.[value]  
                                         FROM   dbo.Fn_split(ISNULL(@MobileGRP, ''), ',') AS   
                                                fs)  
                   OR Contact_Email IN (SELECT fs.[value]  
                                        FROM   dbo.Fn_split(ISNULL(@EmailGRP, ''), ',') AS   
                                               fs)  
                   OR CompanyName LIKE '%' +  
                        
                      CASE   
                           WHEN ISNULL(@CompanyGRP, '') <> '' THEN @CompanyGRP  
                      END  
                        
                      + '%'  
                   OR City IN (SELECT fs.[value]  
                               FROM   dbo.Fn_split(ISNULL(@CityGRP, ''), ',') AS   
                                      fs)  
                   OR STATE IN (SELECT fs.[value]  
                                FROM   dbo.Fn_split(ISNULL(@StateGRP, ''), ',') AS   
                                       fs)  
                   OR Country IN (SELECT fs.[value]  
                                  FROM   dbo.Fn_split(ISNULL(@CountryGRP, ''), ',') AS   
                                         fs)  
                   OR ADDRESS LIKE '%' +  
                        
                      CASE   
                           WHEN ISNULL(@AddressGRP, '') <> '' THEN @AddressGRP  
                      END  
                        
                      + '%'  
                   OR DATEDIFF(d, DateCreated, GETDATE())   
                        
                      BETWEEN   
                        
                      @CreatedBetweenFromGRP AND   
                        
                      @CreatedBetweenToGRP  
                   OR DATEDIFF(  
                          d,  
                          CONVERT(  
                              DATETIME,  
                              CAST(DATEPART(DAY, CONVERT(DATETIME, Contact_DOB, 104)) AS VARCHAR(10))  
                              + '/' + CAST(DATEPART(MONTH, CONVERT(DATETIME, Contact_DOB, 104)) AS VARCHAR(10))  
                              + '/' + CAST(DATEPART(YEAR, GETDATE()) AS VARCHAR(10)),  
                              104  
                          ),  
                          GETDATE()  
                      )   
                        
                      BETWEEN   
                        
                      @BirthBetweenFromGRP AND   
                        
                      @BirthBetweenToGRP  
                   OR DATEDIFF(d, CONVERT(DATETIME, Contact_Anniversary, 104), GETDATE())   
                        
                      BETWEEN   
                        
                      @ANVBetweenFromGRP AND   
                        
                      @ANVBetweenToGRP  
               )  
END  
END 



GO

/* ============================================================
   Procedure: [dbo].[usp_ExecuteUserSearch_New2]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_ExecuteUserSearch_New2] --335,335,230264,NULL --335,152762,NULL      
  @ParentID BIGINT,    
  @UserID Bigint,     
  @SearchID BIGINT,      
  @CampaignID BIGINT = NULL      
 AS      
 BEGIN       
      
DECLARE @SearchType                VARCHAR(50),      
        @Medium                    VARCHAR(50),      
        @Source                    VARCHAR(50),      
        @Campaign                  VARCHAR(50),      
        @SpecificName              VARCHAR(50),      
        @SpecificAddress           VARCHAR(50),      
        @SpecificMobileNo          VARCHAR(50),      
        @SpecificEmail             VARCHAR(50),      
        @SpecificCity              VARCHAR(50),      
        @SpecificState             VARCHAR(50),      
        @SpecificCountry           VARCHAR(50),      
        @CurrentlyAssignedTo       VARCHAR(50),      
        @FollowUpStatus            VARCHAR(50),      
        @CreatedBetweenFrom        VARCHAR(50),      
        @CreatedBetweenTo          VARCHAR(50),      
        @NextFollowUpDateFrom      VARCHAR(50),      
        @NextFollowUpDateTo        VARCHAR(50),      
        @ConvertedWithinFrom       VARCHAR(50),      
        @ConvertedWithinTo         VARCHAR(50),      
        @NameGRP                   VARCHAR(5000),      
        @CompanyGRP                VARCHAR(500),      
        @MobileGRP                 VARCHAR(5000),      
        @EmailGRP                  VARCHAR(5000),      
        @CityGRP                   VARCHAR(5000),      
        @StateGRP                  VARCHAR(5000),      
        @CountryGRP                VARCHAR(5000),      
        @AddressGRP                VARCHAR(500),      
        @BirthBetweenFromGRP       VARCHAR(50),      
        @BirthBetweenToGRP         VARCHAR(50),      
        @ANVBetweenFromGRP         VARCHAR(50),      
        @ANVBetweenToGRP           VARCHAR(50),      
        @CreatedBetweenFromGRP     VARCHAR(50),      
        @CreatedBetweenToGRP       VARCHAR(50),  
        @Groups                 Varchar(5000),  
        @IsENQLeadCNV              BIT,      
        @IsGroup                   BIT        
       
       
       
SELECT @SearchType = usl.searchtype,      
       @Medium                    = usl.medium,      
       @Source                    = usl.source,      
       @Campaign                  = usl.campaign,      
       @SpecificName              = usl.specificname,      
       @SpecificAddress           = usl.specificaddress,      
       @SpecificMobileNo          = usl.specificmobileno,      
       @SpecificEmail             = usl.specificemail,      
       @SpecificCity              = usl.specificcity,      
       @SpecificState             = usl.specificstate,      
       @SpecificCountry           = usl.specificcountry,      
       @CurrentlyAssignedTo       = usl.currentlyassignedto,      
       @FollowUpStatus            = usl.followupstatus,      
       @CreatedBetweenFrom        = usl.createdbetweenfrom,      
       @CreatedBetweenTo          = usl.createdbetweento,      
       @NextFollowUpDateFrom      = usl.nextfollowupdatefrom,      
       @NextFollowUpDateTo        = usl.nextfollowupdateto,      
       @ConvertedWithinFrom       = usl.convertedwithinfrom,      
       @ConvertedWithinTo         = usl.convertedwithinto,      
       @NameGRP                   = usl.NameGRP,      
       @CompanyGRP                = usl.CompanyGRP,      
       @MobileGRP                 = usl.MobileGRP,      
       @EmailGRP                  = usl.EmailGRP,      
       @CityGRP                   = usl.CityGRP,      
       @StateGRP                  = usl.StateGRP,      
       @CountryGRP                = usl.CountryGRP,      
       @AddressGRP                = usl.AddressGRP,      
       @BirthBetweenFromGRP       = usl.BirthBetweenFromGRP,      
       @BirthBetweenToGRP         = usl.BirthBetweenToGRP,      
       @ANVBetweenFromGRP         = usl.ANVBetweenFromGRP,      
       @ANVBetweenToGRP           = usl.ANVBetweenToGRP,   
       @CreatedBetweenFromGRP     = usl.CreatedBetweenFromGRP,      
       @CreatedBetweenToGRP       = usl.CreatedBetweenToGRP,      
       @IsENQLeadCNV              = usl.IsENQLeadCNV,      
       @IsGroup                  = usl.IsGroup ,  
       @Groups                = usl.GroupsGRP    
FROM   usersearchlist AS usl      
WHERE  usl.id = @SearchID        
       
       
       
       
       
       
       
       
       
       
       
       
       
       
       
       
       
IF (isnull(@IsGroup,0) = 0)      
BEGIN      
    ----------------------------------Enquiry -------------------------        
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
    IF (LOWER(@SearchType) = 'en' OR LOWER(@SearchType) = 'al')      
    BEGIN      
        CREATE TABLE #temptableenquiry      
        (      
         id                     BIGINT,      
         personname             VARCHAR(200),      
         companyname            VARCHAR(200),      
         mobileno               VARCHAR(200),      
         mobileno1              VARCHAR(200),      
         mobileno2              VARCHAR(200),      
         emailid                VARCHAR(200),      
         emailid1               VARCHAR(200),      
         emailid2               VARCHAR(200),      
         city                   VARCHAR(200),      
         STATE                  VARCHAR(200),      
         country                VARCHAR(200),      
         countrycode            VARCHAR(200),      
         countrycode1           VARCHAR(200),      
         countrycode2           VARCHAR(200),      
         pincode                VARCHAR(200),      
         residentialaddress     VARCHAR(200),      
         officeaddress          VARCHAR(200),      
         sourcename             VARCHAR(200),      
         mediumname             VARCHAR(200),      
         campaignname           VARCHAR(200),      
         initialremarks         VARCHAR(1000),      
         datecreated            VARCHAR(50)      
        )        
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
        INSERT INTO #temptableenquiry      
          (      
            id,      
            personname,      
            companyname,      
            mobileno,      
            mobileno1,      
            mobileno2,      
            emailid,      
            emailid1,      
            emailid2,      
            city,      
            [state],      
            country,      
            countrycode,      
            countrycode1,      
            countrycode2,      
            pincode,      
            residentialaddress,      
            officeaddress,      
            sourcename,      
            mediumname,      
            campaignname,      
            initialremarks,      
            datecreated      
          )      
        SELECT ue.enquiryid,      
               ue.personname,      
               ue.companyname,      
               ue.mobileno,      
               ue.mobileno1,      
               ue.mobileno2,      
               ue.emailid,      
               ue.emailid1,      
               ue.emailid2,      
               ue.city,      
               ue.[state],      
               ue.country,      
               ue.countrycode,      
               ue.countrycode1,      
               ue.countrycode2,      
               ue.pincode,      
               ue.residentialaddress,      
               ue.officeaddress,      
               ue.sourcename,      
               ue.mediumname,      
               ue.campaignname,      
               ue.initialremarks,      
               ue.createddate      
        FROM   UserEnquiry AS ue      
        WHERE  ue.parentid = @ParentID        
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
        IF (ISNULL(@Medium, '') <> '' AND ISNULL(@Medium, '') <> '0')      
        BEGIN      
            DELETE       
            FROM   #temptableenquiry      
            WHERE  mediumname NOT IN (SELECT fs.[value]      
                                      FROM   dbo.Fn_split(@Medium, '#') AS fs)      
        END        
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
        
        IF (ISNULL(@Source, '') <> '' AND ISNULL(@Source, '') <> '0')      
        BEGIN      
            DELETE       
            FROM   #temptableenquiry      
            WHERE  sourcename NOT IN (SELECT fs.[value]      
                                      FROM   dbo.Fn_split(@Source, '#') AS fs)      
        END        
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
        IF (      
               ISNULL(@Campaign, '') <> ''      
               AND ISNULL(@Campaign, '') <> '0'      
           )      
        BEGIN      
            DELETE       
            FROM   #temptableenquiry      
            WHERE  campaignname NOT IN (SELECT fs.[value]      
                                        FROM   dbo.Fn_split(@Campaign, '#') AS       
                                               fs)      
        END        
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
        IF (ISNULL(@SpecificName, '') <> '')      
        BEGIN      
            DELETE       
            FROM   #temptableenquiry      
            WHERE  personname = @SpecificName      
        END        
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
        IF (ISNULL(@SpecificAddress, '') <> '')      
        BEGIN      
            DELETE       
            FROM   #temptableenquiry      
            WHERE  residentialaddress LIKE '%' + @SpecificAddress + '%'      
                   OR  officeaddress LIKE '%' + @SpecificAddress + '%'      
        END        
              
              
              
              
              
              
  
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
        IF (ISNULL(@SpecificMobileNo, '') <> '')      
        BEGIN      
            DELETE       
            FROM   #temptableenquiry      
            WHERE  CAST(mobileno COLLATE Latin1_General_CI_AI AS VARCHAR(50))       
                         
                         
                         
                         
                         
                         
                         
                   NOT IN (SELECT fs.[value]      
                           FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)      
                   OR  CAST(mobileno1 COLLATE Latin1_General_CI_AI AS VARCHAR(50))       
                             
                             
    
                             
                             
                             
                             
                       NOT IN (SELECT fs.[value]      
                               FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)      
                   OR  CAST(mobileno2 COLLATE Latin1_General_CI_AI AS VARCHAR(50))       
                             
                             
                             
                             
                             
                             
                             
                       NOT IN (SELECT fs.[value]      
                               FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)      
        END        
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
   IF (ISNULL(@SpecificEmail, '') <> '')      
        BEGIN      
            DELETE       
            FROM   #temptableenquiry      
            WHERE  CAST(emailid COLLATE Latin1_General_CI_AI AS VARCHAR(250))       
                         
                         
                         
                         
                         
                         
                         
                   NOT IN (SELECT fs.[value]      
                           FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)      
                   OR  CAST(emailid1 COLLATE Latin1_General_CI_AI AS VARCHAR(250))       
                             
                             
                             
                             
                             
                             
                             
                       NOT IN (SELECT fs.[value]      
                               FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)      
                   OR  CAST(emailid2 COLLATE Latin1_General_CI_AI AS VARCHAR(250))       
                             
                             
                             
                             
                             
                             
                             
                       NOT IN (SELECT fs.[value]      
                               FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)      
        END        
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
      IF (ISNULL(@SpecificCity, '') <> '')      
        BEGIN      
            DELETE       
            FROM   #temptableenquiry      
            WHERE  city = @SpecificCity      
        END        
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
        IF (ISNULL(@SpecificCountry, '') <> '')      
        BEGIN      
            DELETE       
            FROM   #temptableenquiry      
            WHERE  country = @SpecificCountry      
        END        
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
        IF (ISNULL(@SpecificState, '') <> '')      
        BEGIN      
            DELETE       
            FROM   #temptableenquiry      
            WHERE  [state] = @SpecificState      
        END        
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
              
        IF (      
               ISNULL(@CreatedBetweenFrom, '') <> ''      
               AND ISNULL(@CreatedBetweenTo, '') <> ''      
           )      
        BEGIN      
            DELETE       
            FROM   #temptableenquiry      
            WHERE  id NOT IN (SELECT ue.enquiryid      
                              FROM   userenquiry AS ue      
                              WHERE  DATEDIFF(d, ue.createddate, GETDATE())       
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                            
                                     BETWEEN       
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                                     @CreatedBetweenFrom AND       
                                           
                                           
                                           
                                           
                                           
  
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                                           
                                     @CreatedBetweenTo)      
        END      
    END       
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
    ---------------------------------- LEADS -------------------------        
          
          
          
          
          
          
          
          
          
          
          
          
          
          
          
    IF (LOWER(@SearchType) = 'le' OR LOWER(@SearchType) = 'al')      
    BEGIN      
        CREATE TABLE #temptableleads      
        (      
         id                     BIGINT,      
         personname             VARCHAR(200),      
         companyname            VARCHAR(200),      
         mobileno               VARCHAR(200),      
         mobileno1              VARCHAR(200),      
         mobileno2              VARCHAR(200),      
         emailid                VARCHAR(200),      
         emailid1               VARCHAR(200),      
         emailid2               VARCHAR(200),      
         city                   VARCHAR(200),      
         STATE                  VARCHAR(200),     
         country                VARCHAR(200),      
         countrycode            VARCHAR(200),      
         countrycode1           VARCHAR(200),      
         countrycode2           VARCHAR(200),      
         pincode                VARCHAR(200),      
         residentialaddress     VARCHAR(200),      
         officeaddress          VARCHAR(200),      
         sourcename             VARCHAR(200) COLLATE       
               
               
               
               
               
               
               
               
               
               
               
               
               
               
               
         sql_latin1_general_cp1_ci_as,      
         mediumname             VARCHAR(200) COLLATE       
               
               
               
               
               
               
               
               
               
               
               
               
               
               
               
         sql_latin1_general_cp1_ci_as,      
         campaignname           VARCHAR(200) COLLATE       
               
               
               
               
               
               
               
               
               
               
               
               
               
               
               
         sql_latin1_general_cp1_ci_as,      
         initialremarks         VARCHAR(1000),      
         datecreated            VARCHAR(50),      
         assignedto             VARCHAR(200),      
         followupstatus         VARCHAR(200),      
         nextfollowupdate       VARCHAR(200)      
