  @CampaignID varchar(50) = NULL,          
  @UserID varchar(50)= null             
 AS            
 BEGIN             
declare @isgroup int =(select isgroup FROM usersearchlist AS usl            
WHERE  usl.id = @SearchID)              
IF (isnull(@IsGroup,0) = 0)    
BEGIN    
exec usp_ExecuteUserSearchwithid  @ParentID,@SearchID,@CampaignID     
END            
ELSE if (@IsGroup = 1)           
BEGIN             
