/* ============================================================
   Procedure: [dbo].[usp_ExecuteUserSearch2]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_ExecuteUserSearch2] --27828,153539  
 @ParentID BIGINT,  
 @SearchID BIGINT,  
 @CampaignID BIGINT = NULL  
AS  
BEGIN  
 DECLARE @SearchType               VARCHAR(50),  
         @Medium                   VARCHAR(50),  
         @Source                   VARCHAR(50),  
         @Campaign                 VARCHAR(50),  
         @SpecificName             VARCHAR(50),  
         @SpecificAddress          VARCHAR(50),  
         @SpecificMobileNo         VARCHAR(50),  
         @SpecificEmail            VARCHAR(50),  
         @SpecificCity             VARCHAR(50),  
         @SpecificState            VARCHAR(50),  
         @SpecificCountry          VARCHAR(50),  
         @CurrentlyAssignedTo      VARCHAR(50),  
         @FollowUpStatus           VARCHAR(50),  
         @CreatedBetweenFrom       VARCHAR(50),  
         @CreatedBetweenTo         VARCHAR(50),  
         @NextFollowUpDateFrom     VARCHAR(50),  
         @NextFollowUpDateTo       VARCHAR(50),  
         @ConvertedWithinFrom      VARCHAR(50),  
         @ConvertedWithinTo        VARCHAR(50)  
   
   
   
 SELECT @SearchType = usl.searchtype,  
        @Medium                   = usl.medium,  
        @Source                   = usl.source,  
        @Campaign                 = usl.campaign,  
        @SpecificName             = usl.specificname,  
        @SpecificAddress          = usl.specificaddress,  
        @SpecificMobileNo         = usl.specificmobileno,  
        @SpecificEmail            = usl.specificemail,  
        @SpecificCity             = usl.specificcity,  
        @SpecificState            = usl.specificstate,  
        @SpecificCountry          = usl.specificcountry,  
        @CurrentlyAssignedTo      = usl.currentlyassignedto,  
        @FollowUpStatus           = usl.followupstatus,  
        @CreatedBetweenFrom       = usl.createdbetweenfrom,  
        @CreatedBetweenTo         = usl.createdbetweento,  
        @NextFollowUpDateFrom     = usl.nextfollowupdatefrom,  
        @NextFollowUpDateTo       = usl.nextfollowupdateto,  
        @ConvertedWithinFrom      = usl.convertedwithinfrom,  
        @ConvertedWithinTo        = usl.convertedwithinto  
 FROM   usersearchlist AS usl  
 WHERE  usl.id = @SearchID  
   
   
   
 ----------------------------------Enquiry -------------------------  
   
 IF (LOWER(@SearchType) = 'en' OR LOWER(@SearchType) = 'al')  
 BEGIN  
     CREATE TABLE #temptableenquiry  
     (  
      id                     BIGINT,  
      personname             VARCHAR(200),  
      companyname            VARCHAR(200),  
      mobileno               VARCHAR(200),  
      mobileno1              VARCHAR(200),  
      mobileno2              VARCHAR(200),  
      emailid                VARCHAR(200),  
      emailid1               VARCHAR(200),  
      emailid2               VARCHAR(200),  
      city                   VARCHAR(200),  
      STATE                  VARCHAR(200),  
      country                VARCHAR(200),  
      countrycode            VARCHAR(200),  
      countrycode1           VARCHAR(200),  
      countrycode2           VARCHAR(200),  
      pincode                VARCHAR(200),  
      residentialaddress     VARCHAR(200),  
      officeaddress          VARCHAR(200),  
      sourcename             VARCHAR(200),  
      mediumname             VARCHAR(200),  
      campaignname           VARCHAR(200),  
      initialremarks         VARCHAR(1000),  
      datecreated            VARCHAR(50)  
     )  
       
       
       
     INSERT INTO #temptableenquiry  
       (  
         id,  
         personname,  
         companyname,  
         mobileno,  
         mobileno1,  
         mobileno2,  
         emailid,  
         emailid1,  
         emailid2,  
         city,  
         [state],  
         country,  
         countrycode,  
         countrycode1,  
         countrycode2,  
         pincode,  
         residentialaddress,  
         officeaddress,  
         sourcename,  
         mediumname,  
         campaignname,  
         initialremarks,  
         datecreated  
       )  
     SELECT ue.enquiryid,  
            ue.personname,  
            ue.companyname,  
            ue.mobileno,  
            ue.mobileno1,  
            ue.mobileno2,  
            ue.emailid,  
            ue.emailid1,  
            ue.emailid2,  
            ue.city,  
            ue.[state],  
            ue.country,  
            ue.countrycode,  
            ue.countrycode1,  
            ue.countrycode2,  
            ue.pincode,  
            ue.residentialaddress,  
            ue.officeaddress,  
            ue.sourcename,  
            ue.mediumname,  
            ue.campaignname,  
            ue.initialremarks,  
            ue.createddate  
     FROM   UserEnquiry AS ue  
     WHERE  ue.parentid = @ParentID  
       
       
       
     IF (ISNULL(@Medium, '') <> '' AND ISNULL(@Medium, '') <> '0')  
     BEGIN  
         DELETE   
         FROM   #temptableenquiry  
         WHERE   CAST( mediumname COLLATE Latin1_General_CI_AI AS VARCHAR(500))  NOT IN (SELECT CAST( fs.[value] COLLATE Latin1_General_CI_AI AS VARCHAR(500))   
                                   FROM   dbo.Fn_split(@Medium, '#') AS fs)  
     END  
       
       
       
     IF (ISNULL(@Source, '') <> '' AND ISNULL(@Source, '') <> '0')  
     BEGIN  
         DELETE   
         FROM   #temptableenquiry  
         WHERE  CAST(  sourcename  COLLATE Latin1_General_CI_AI AS VARCHAR(500)) NOT IN (SELECT CAST( fs.[value] COLLATE Latin1_General_CI_AI AS VARCHAR(500))   
                                   FROM   dbo.Fn_split(@Source, '#') AS fs)  
     END  
       
       
       
     IF (  
            ISNULL(@Campaign, '') <> ''  
            AND ISNULL(@Campaign, '') <> '0'  
        )  
     BEGIN  
         DELETE   
         FROM   #temptableenquiry  
         WHERE  CAST(  campaignname COLLATE Latin1_General_CI_AI AS VARCHAR(500))  NOT IN (SELECT CAST( fs.[value] COLLATE Latin1_General_CI_AI AS VARCHAR(500))   
                                     FROM   dbo.Fn_split(@Campaign, '#') AS   
                                            fs)  
     END  
       
       
       
     IF (ISNULL(@SpecificName, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableenquiry  
         WHERE   CAST( personname COLLATE Latin1_General_CI_AI AS VARCHAR(500))  =CAST(  @SpecificName COLLATE Latin1_General_CI_AI AS VARCHAR(500))   
     END  
       
       
       
     IF (ISNULL(@SpecificAddress, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableenquiry  
         WHERE    CAST( residentialaddress COLLATE Latin1_General_CI_AI AS VARCHAR(500)) LIKE '%' +  CAST( @SpecificAddress COLLATE Latin1_General_CI_AI AS VARCHAR(500)) + '%'  
                OR  CAST(  officeaddress COLLATE Latin1_General_CI_AI AS VARCHAR(500)) LIKE '%' + CAST(  @SpecificAddress COLLATE Latin1_General_CI_AI AS VARCHAR(500)) + '%'  
     END  
       
       
       
     IF (ISNULL(@SpecificMobileNo, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableenquiry  
         WHERE  CAST(mobileno COLLATE Latin1_General_CI_AI AS VARCHAR(50))  
                  
                NOT  
                  
                IN (SELECT fs.[value]  
                    FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)  
                and  CAST(mobileno1 COLLATE Latin1_General_CI_AI AS VARCHAR(50))  
                      
                    NOT  
                      
                    IN (SELECT fs.[value]  
                        FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)  
                and  CAST(mobileno2 COLLATE Latin1_General_CI_AI AS VARCHAR(50))  
                      
                    NOT  
                      
                    IN (SELECT fs.[value]  
                        FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)  
     END  
       
       
       
     IF (ISNULL(@SpecificEmail, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableenquiry  
         WHERE  CAST(emailid COLLATE Latin1_General_CI_AI AS VARCHAR(250))  
                  
                NOT  
                  
                IN (SELECT fs.[value]  
                    FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)  
                and  CAST(emailid1 COLLATE Latin1_General_CI_AI AS VARCHAR(250))  
                      
                    NOT  
                      
                    IN (SELECT fs.[value]  
                        FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)  
                and  CAST(emailid2 COLLATE Latin1_General_CI_AI AS VARCHAR(250))  
                      
                    NOT  
                      
                    IN (SELECT fs.[value]  
                        FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)  
     END  
       
       
       
     IF (ISNULL(@SpecificCity, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableenquiry  
         WHERE  city = @SpecificCity  
     END  
       
       
       
     IF (ISNULL(@SpecificCountry, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableenquiry  
         WHERE  country = @SpecificCountry  
     END  
       
       
       
     IF (ISNULL(@SpecificState, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableenquiry  
         WHERE  [state] = @SpecificState  
     END  
       
       
       
     IF (  
            ISNULL(@CreatedBetweenFrom, '') <> ''  
            AND ISNULL(@CreatedBetweenTo, '') <> ''  
        )  
     BEGIN  
         DELETE   
         FROM   #temptableenquiry  
         WHERE  id NOT IN (SELECT ue.enquiryid  
                           FROM   userenquiry AS ue  
                           WHERE  DATEDIFF(d, ue.createddate, GETDATE())  
                                    
                                  BETWEEN  
                                    
                                  @CreatedBetweenFrom AND  
                                    
                                  @CreatedBetweenTo)  
     END  
 END  
   
   
   
 ---------------------------------- LEADS -------------------------  
   
 IF (LOWER(@SearchType) = 'le' OR LOWER(@SearchType) = 'al')  
 BEGIN  
     CREATE TABLE #temptableleads  
     (  
      id                     BIGINT,  
      personname             VARCHAR(200),  
      companyname            VARCHAR(200),  
      mobileno               VARCHAR(200),  
      mobileno1              VARCHAR(200),  
      mobileno2              VARCHAR(200),  
      emailid                VARCHAR(200),  
      emailid1               VARCHAR(200),  
      emailid2               VARCHAR(200),  
      city                   VARCHAR(200),  
      STATE                  VARCHAR(200),  
      country                VARCHAR(200),  
      countrycode            VARCHAR(200),  
      countrycode1           VARCHAR(200),  
      countrycode2           VARCHAR(200),  
      pincode                VARCHAR(200),  
      residentialaddress     VARCHAR(200),  
      officeaddress          VARCHAR(200),  
      sourcename             VARCHAR(200) COLLATE  
        
      sql_latin1_general_cp1_ci_as,  
      mediumname             VARCHAR(200) COLLATE  
        
      sql_latin1_general_cp1_ci_as,  
      campaignname           VARCHAR(200) COLLATE  
        
      sql_latin1_general_cp1_ci_as,  
      initialremarks         VARCHAR(1000),  
      datecreated            VARCHAR(50),  
      assignedto             VARCHAR(200),  
      followupstatus         VARCHAR(200),  
      nextfollowupdate       VARCHAR(200)  
     )  
       
       
       
     INSERT INTO #temptableleads  
       (  
         id,  
         personname,  
         companyname,  
         mobileno,  
         mobileno1,  
         mobileno2,  
         emailid,  
         emailid1,  
         emailid2,  
         city,  
         [state],  
         country,  
         countrycode,  
         countrycode1,  
         countrycode2,  
         pincode,  
         residentialaddress,  
         officeaddress,  
         sourcename,  
         mediumname,  
         campaignname,  
         initialremarks,  
         datecreated,  
         assignedto,  
         followupstatus,  
         nextfollowupdate  
       )  
     SELECT ue.id,  
        ue.personname,  
            ue.companyname,  
            ue.mobileno,  
            ue.mobileno1,  
            ue.mobileno2,  
            ue.emailid,  
            ue.emailid1,  
            ue.emailid2,  
            ue.city,  
            ue.[state],  
            ue.country,  
            ue.countrycode,  
            ue.countrycode1,  
            ue.countrycode2,  
            ue.pincode,  
            ue.residentialaddress,  
            ue.officeaddress,  
            ue.sourcename,  
            ue.mediumname,  
            ue.campaignname,  
            ue.initialremarks,  
            ue.createdon,  
            ue.assignedto,  
            ue.followupstatus,  
            ue.nextstatusdate  
     FROM   UserLeads AS ue  
     WHERE  ue.parentid = @ParentID  
       
       
       
     IF (ISNULL(@Medium, '') <> '' AND ISNULL(@Medium, '') <> '0')  
     BEGIN  
         DELETE   
         FROM   #temptableleads  
         WHERE  mediumname NOT IN (SELECT fs.[value]  
                                   FROM   dbo.Fn_split(@Medium, '#') AS fs)  
     END  
       
       
       
     IF (ISNULL(@Source, '') <> '' AND ISNULL(@Source, '') <> '0')  
     BEGIN  
         DELETE   
         FROM   #temptableleads  
         WHERE  sourcename NOT IN (SELECT fs.[value]  
                                   FROM   dbo.Fn_split(@Source, '#') AS fs)  
     END  
       
       
       
     IF (  
            ISNULL(@Campaign, '') <> ''  
            AND ISNULL(@Campaign, '') <> '0'  
        )  
     BEGIN  
         DELETE   
         FROM   #temptableleads  
         WHERE  campaignname NOT IN (SELECT fs.[value]  
                                     FROM   dbo.Fn_split(@Campaign, '#') AS   
                                            fs)  
     END  
       
       
       
     IF (ISNULL(@SpecificName, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableleads  
         WHERE  personname = @SpecificName  
     END  
       
       
       
     IF (ISNULL(@SpecificAddress, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableleads  
         WHERE CAST( residentialaddress COLLATE Latin1_General_CI_AI AS VARCHAR(500)) LIKE '%' + CAST(@SpecificAddress COLLATE Latin1_General_CI_AI AS VARCHAR(500)) + '%'  
                OR  CAST(officeaddress COLLATE Latin1_General_CI_AI AS VARCHAR(500)) LIKE '%' + CAST(@SpecificAddress COLLATE Latin1_General_CI_AI AS VARCHAR(500)) + '%'  
     END  
       
       
       
     IF (ISNULL(@SpecificMobileNo, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableleads  
         WHERE  CAST(mobileno COLLATE Latin1_General_CI_AI AS VARCHAR(50))  
                  
                NOT  
                  
                IN (SELECT fs.[value]  
                    FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)  
                and  CAST(mobileno1 COLLATE Latin1_General_CI_AI AS VARCHAR(50))  
                      
                    NOT  
                      
                    IN (SELECT fs.[value]  
                        FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)  
                and  CAST(mobileno2 COLLATE Latin1_General_CI_AI AS VARCHAR(50))  
                      
                    NOT  
                      
                    IN (SELECT fs.[value]  
                        FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)  
     END  
       
       
       
     IF (ISNULL(@SpecificEmail, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableleads  
         WHERE  CAST(emailid COLLATE Latin1_General_CI_AI AS VARCHAR(250))  
                  
                NOT  
                  
                IN (SELECT fs.[value]  
                    FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)  
                and  CAST(emailid1 COLLATE Latin1_General_CI_AI AS VARCHAR(250))  
                      
                    NOT  
                      
                    IN (SELECT fs.[value]  
                        FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)  
                and  CAST(emailid2 COLLATE Latin1_General_CI_AI AS VARCHAR(250))  
                      
                    NOT  
                      
                    IN (SELECT fs.[value]  
                        FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)  
     END  
       
       
       
     IF (ISNULL(@SpecificCity, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableleads  
         WHERE  city = @SpecificCity  
     END  
       
       
       
     IF (ISNULL(@SpecificCountry, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableleads  
         WHERE  country = @SpecificCountry  
     END  
       
       
       
     IF (ISNULL(@SpecificState, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableleads  
         WHERE  [state] = @SpecificState  
     END  
       
       
       
     IF (  
            ISNULL(@CurrentlyAssignedTo, '') <> ''  
            AND ISNULL(@CurrentlyAssignedTo, '') <> '0'  
        )  
     BEGIN  
         DELETE   
         FROM   #temptableleads  
         WHERE CAST(   assignedto COLLATE Latin1_General_CI_AI AS VARCHAR(250))NOT IN (SELECT  CAST( fs.[value]COLLATE Latin1_General_CI_AI AS VARCHAR(250))  
                                   FROM   dbo.Fn_split(@CurrentlyAssignedTo, ',') AS   
                                          fs)  
     END  
       
       
       
     IF (  
            ISNULL(@CreatedBetweenFrom, '') <> ''  
            AND ISNULL(@CreatedBetweenTo, '') <> ''  
        )  
     BEGIN  
         DELETE   
         FROM   #temptableleads  
         WHERE  id NOT IN (SELECT ue.id  
                           FROM   userleads AS ue  
                           WHERE  DATEDIFF(d, ue.createdon, GETDATE())  
                                    
                                  BETWEEN  
                                    
                                  @CreatedBetweenFrom AND  
                                    
                                  @CreatedBetweenTo  
                                  AND ue.parentid = @ParentID)  
     END  
       
       
       
     IF (  
            ISNULL(@NextFollowUpDateFrom, '') <> ''  
            AND ISNULL(@NextFollowUpDateTo, '') <> ''  
        )  
     BEGIN  
         DELETE   
         FROM   #temptableleads  
         WHERE  id NOT IN (SELECT ue.id  
                           FROM   userleads AS ue  
                                  INNER JOIN leadinteractionhistory lih  
                                       ON  lih.leadno = ue.leadno  
                           WHERE  DATEDIFF(d, GETDATE(), lih.nextstatusdate)  
                                    
                                  BETWEEN  
                                    
                                  @NextFollowUpDateFrom AND  
                                    
                                  @NextFollowUpDateTo  
                                  AND ue.parentid = @ParentID)  
     END  
       
       
       
     IF (  
            ISNULL(@FollowUpStatus, '') <> ''  
            AND ISNULL(@FollowUpStatus, '') <> '0'  
        )  
     BEGIN  
         DELETE   
         FROM   #temptableleads  
         WHERE  CAST(  
                    followupstatus COLLATE Latin1_General_CI_AI AS  
                      
                    VARCHAR(250)  
                )  
                  
                NOT  
                  
                IN (SELECT CAST(fs.[value] COLLATE Latin1_General_CI_AI AS VARCHAR(250))  
                    FROM   dbo.Fn_split(@FollowUpStatus, '#') AS fs)  
     END  
 END  
   
   
   
 ---------------------------------- Conversions -------------------------  
   
 IF (LOWER(@SearchType) = 'co' OR LOWER(@SearchType) = 'al')  
 BEGIN  
     CREATE TABLE #temptableconversion  
     (  
      id                     BIGINT,  
      personname             VARCHAR(200),  
      companyname            VARCHAR(200),  
      mobileno               VARCHAR(200),  
      mobileno1              VARCHAR(200),  
      mobileno2              VARCHAR(200),  
      emailid                VARCHAR(200),  
      emailid1      VARCHAR(200),  
      emailid2               VARCHAR(200),  
      city                   VARCHAR(200),  
      STATE                  VARCHAR(200),  
      country                VARCHAR(200),  
      countrycode            VARCHAR(200),  
      pincode                VARCHAR(200),  
      residentialaddress     VARCHAR(200),  
      officeaddress          VARCHAR(200),  
      sourcename             VARCHAR(200) COLLATE  
        
      sql_latin1_general_cp1_ci_as,  
      mediumname             VARCHAR(200) COLLATE  
        
      sql_latin1_general_cp1_ci_as,  
      campaignname           VARCHAR(200) COLLATE  
        
      sql_latin1_general_cp1_ci_as,  
      initialremarks         VARCHAR(1000),  
      datecreated            VARCHAR(50),  
      assignedto             VARCHAR(200),  
      followupstatus         VARCHAR(200),  
      nextfollowupdate       VARCHAR(200)  
     )  
       
       
       
     INSERT INTO #temptableconversion  
       (  
         id,  
         personname,  
         companyname,  
         mobileno,  
         mobileno1,  
         mobileno2,  
         emailid,  
         emailid1,  
         emailid2,  
         city,  
         [state],  
         country,  
         countrycode,  
         pincode,  
         residentialaddress,  
         officeaddress,  
         sourcename,  
         mediumname,  
         campaignname,  
         initialremarks,  
         datecreated,  
         assignedto,  
         followupstatus,  
         nextfollowupdate  
       )  
     SELECT ue.id,  
            ue.personname,  
            ue.companyname,  
            ue.mobileno,  
            ue.mobileno1,  
            ue.mobileno2,  
            ue.emailid,  
            ue.emailid1,  
            ue.emailid2,  
            ue.city,  
            ue.[state],  
            ue.country,  
            ue.countrycode,  
            ue.pincode,  
            ue.residentialaddress,  
            ue.officeaddress,  
            ue.sourcename,  
            ue.mediumname,  
            ue.campaignname,  
            ue.initialremarks,  
            ue.createdon,  
            ue.assignedto,  
            ue.followupstatus,  
            ue.nextstatusdate  
     FROM   UserLeads AS ue  
            INNER JOIN LeadInteractionHistory AS lih  
                 ON  lih.leadno = ue.leadno  
                 AND lih.parentid = @ParentID  
                 AND ISNULL(NULLIF(lih.amountpaid, 0), 0) <> 0  
     WHERE  ue.parentid = @ParentID  
       
       
       
     IF (ISNULL(@Medium, '') <> '' AND ISNULL(@Medium, '') <> '0')  
     BEGIN  
         DELETE   
         FROM   #temptableconversion  
         WHERE  mediumname NOT IN (SELECT fs.[value]  
                                   FROM   dbo.Fn_split(@Medium, '#') AS fs)  
     END  
       
       
       
     IF (ISNULL(@Source, '') <> '' AND ISNULL(@Source, '') <> '0')  
     BEGIN  
         DELETE   
         FROM   #temptableconversion  
         WHERE  sourcename NOT IN (SELECT fs.[value]  
                                   FROM   dbo.Fn_split(@Source, '#') AS fs)  
     END  
       
       
       
     IF (  
            ISNULL(@Campaign, '') <> ''  
            AND ISNULL(@Campaign, '') <> '0'  
        )  
     BEGIN  
         DELETE   
         FROM   #temptableconversion  
         WHERE  campaignname NOT IN (SELECT fs.[value]  
                                     FROM   dbo.Fn_split(@Campaign, '#') AS   
                                            fs)  
     END  
       
       
       
     IF (ISNULL(@SpecificName, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableconversion  
         WHERE  personname = @SpecificName  
     END  
       
       
       
     IF (ISNULL(@SpecificAddress, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableconversion  
         WHERE  CAST( residentialaddress COLLATE Latin1_General_CI_AI AS VARCHAR(500)) LIKE '%' + CAST(  @SpecificAddress COLLATE Latin1_General_CI_AI AS VARCHAR(500)) + '%'  
                OR  CAST(  officeaddress COLLATE Latin1_General_CI_AI AS VARCHAR(500)) LIKE '%' + CAST(  @SpecificAddress COLLATE Latin1_General_CI_AI AS VARCHAR(500)) + '%'  
     END  
       
       
       
     IF (ISNULL(@SpecificMobileNo, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableconversion  
         WHERE  CAST(mobileno COLLATE Latin1_General_CI_AI AS VARCHAR(50))  
                  
                NOT  
                  
                IN (SELECT fs.[value]  
                    FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)  
                and  CAST(mobileno1 COLLATE Latin1_General_CI_AI AS VARCHAR(50))  
                      
                    NOT  
                      
                    IN (SELECT fs.[value]  
                        FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)  
                and  CAST(mobileno2 COLLATE Latin1_General_CI_AI AS VARCHAR(50))  
                      
                    NOT  
                      
                    IN (SELECT fs.[value]  
                        FROM   dbo.Fn_split(@SpecificMobileNo, ',') AS fs)  
     END  
       
       
       
     IF (ISNULL(@SpecificEmail, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableconversion  
         WHERE  CAST(emailid COLLATE Latin1_General_CI_AI AS VARCHAR(250))  
                  
                NOT  
                  
                IN (SELECT fs.[value]  
                    FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)  
                and  CAST(emailid1 COLLATE Latin1_General_CI_AI AS VARCHAR(250))  
                      
                    NOT  
                      
                    IN (SELECT fs.[value]  
                        FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)  
                and  CAST(emailid2 COLLATE Latin1_General_CI_AI AS VARCHAR(250))  
                      
                    NOT  
                      
                    IN (SELECT fs.[value]  
                        FROM   dbo.Fn_split(@SpecificEmail, ',') AS fs)  
     END  
       
       
       
     IF (ISNULL(@SpecificCity, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableconversion  
         WHERE  city = @SpecificCity  
     END  
       
       
       
     IF (ISNULL(@SpecificCountry, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableconversion  
         WHERE  country = @SpecificCountry  
     END  
       
       
       
     IF (ISNULL(@SpecificState, '') <> '')  
     BEGIN  
         DELETE   
         FROM   #temptableconversion  
         WHERE  [state] = @SpecificState  
     END  
       
       
       
     IF (  
            ISNULL(@CurrentlyAssignedTo, '') <> ''  
            AND ISNULL(@CurrentlyAssignedTo, '') <> '0'  
        )  
     BEGIN  
         DELETE   
         FROM   #temptableconversion  
         WHERE  assignedto NOT IN (SELECT fs.[value]  
                                   FROM   dbo.Fn_split(@CurrentlyAssignedTo, ',') AS   
                                          fs)  
     END  
       
       
       
     IF (  
            ISNULL(@CreatedBetweenFrom, '') <> ''  
            AND ISNULL(@CreatedBetweenTo, '') <> ''  
        )  
     BEGIN  
         DELETE   
         FROM   #temptableconversion  
         WHERE  id NOT IN (SELECT ue.id  
                           FROM   userleads AS ue  
                           WHERE  DATEDIFF(d, ue.createdon, GETDATE())  
                                    
                                  BETWEEN  
                                    
                                  @CreatedBetweenFrom AND  
                                    
                                  @CreatedBetweenTo  
                                  AND ue.parentid = @ParentID)  
     END  
       
       
       
     IF (  
            ISNULL(@NextFollowUpDateFrom, '') <> ''  
            AND ISNULL(@NextFollowUpDateTo, '') <> ''  
        )  
     BEGIN  
         DELETE   
         FROM   #temptableconversion  
         WHERE  id NOT IN (SELECT ue.id  
                           FROM   userleads AS ue  
                                  INNER JOIN leadinteractionhistory lih  
                                       ON  lih.leadno = ue.leadno  
                           WHERE  DATEDIFF(d, GETDATE(), lih.nextstatusdate)  
                                    
                                  BETWEEN  
                                    
                                  @NextFollowUpDateFrom AND  
                                    
                                  @NextFollowUpDateTo  
                                  AND ue.parentid = @ParentID)  
     END  
       
       
       
     IF (  
            ISNULL(@ConvertedWithinFrom, '') <> ''  
            AND ISNULL(@ConvertedWithinTo, '') <> ''  
        )  
     BEGIN  
         DELETE   
         FROM   #temptableconversion  
         WHERE  id NOT IN (SELECT ue.id  
                           FROM   userleads AS ue  
                                  INNER JOIN leadinteractionhistory lih  
                                       ON  lih.leadno = ue.leadno  
                                       AND ISNULL(NULLIF(lih.amountpaid, 0), 0)  
                                             
                                           <>  
                                             
                                           0  
                           WHERE  DATEDIFF(d, lih.createdon, GETDATE())  
                                    
                                  BETWEEN  
                                    
                                  @ConvertedWithinFrom AND  
                                    
                                  @ConvertedWithinTo  
                                  AND ue.parentid = @ParentID)  
     END  
       
       
       
     IF (  
            ISNULL(@FollowUpStatus, '') <> ''  
            AND ISNULL(@FollowUpStatus, '') <> '0'  
        )  
     BEGIN  
         DELETE   
         FROM   #temptableconversion  
         WHERE  CAST(  
                    followupstatus COLLATE Latin1_General_CI_AI AS  
                      
                    VARCHAR(250)  
                ) NOT IN (SELECT CAST(fs.[value] COLLATE Latin1_General_CI_AI AS VARCHAR(250))  
                          FROM   dbo.Fn_split(@FollowUpStatus, '#') AS fs)  
     END  
 END  
   
   
   
 IF (LOWER(@SearchType) = 'en')  
 BEGIN  
     SELECT tteq.personname,  
            tteq.companyname,  
            ISNULL(tteq.mobileno, '')  AS MobileNo,  
            ISNULL(tteq.mobileno1, '') AS MobileNo1,  
            ISNULL(tteq.mobileno2, '') AS MobileNo2,  
            ISNULL(tteq.emailid, '')   AS EMAILID,  
            ISNULL(tteq.emailid1, '')  AS EmailID1,  
            ISNULL(tteq.emailid2, '')  AS EmailID2,  
            tteq.country,  
            tteq.[state],  
            tteq.city,  
            tteq.pincode,  
            tteq.residentialaddress,  
            tteq.officeaddress,  
            uss.NAME                   AS SourceName,  
            ums.NAME                   AS MediumName,  
            ucs.NAME                   AS CampaignName,  
            tteq.initialremarks,  
            @SearchID                  AS SearchID,  
            @ParentID                  AS ParentID,  
            @CampaignID                AS CampaignID  
     FROM   #temptableenquiry          AS tteq  
            LEFT JOIN usermediumsettings ums  
                 ON  tteq.mediumname = ums.mediumid  
            LEFT JOIN usercampaignsettings ucs  
                 ON  tteq.campaignname = ucs.campaignid  
            LEFT JOIN usersourcesettings uss  
                 ON  tteq.sourcename = uss.sourceid  
       
       
       
     DROP TABLE #temptableenquiry  
 END  
 ELSE   
   
 IF (LOWER(@SearchType) = 'le')  
 BEGIN  
     SELECT tteq.personname,  
            tteq.companyname,  
            ISNULL(tteq.mobileno, '')  AS MobileNo,  
            ISNULL(tteq.mobileno1, '') AS MobileNo1,  
            ISNULL(tteq.mobileno2, '') AS MobileNo2,  
            ISNULL(tteq.emailid, '')   AS EMAILID,  
            ISNULL(tteq.emailid1, '')  AS EmailID1,  
            ISNULL(tteq.emailid2, '')  AS EmailID2,  
            tteq.country,  
            tteq.[state],  
            tteq.city,  
            tteq.pincode,  
            tteq.residentialaddress,  
            tteq.officeaddress,  
            uss.NAME                   AS SourceName,  
            ums.NAME                   AS MediumName,  
            ucs.NAME                   AS CampaignName,  
            tteq.initialremarks,  
            @SearchID                  AS SearchID,  
            @ParentID                  AS ParentID,  
            @CampaignID                AS CampaignID  
     FROM   #temptableleads            AS tteq  
            LEFT JOIN usermediumsettings ums  
                 ON  CAST(  
                         CAST(tteq.mediumname AS VARCHAR(50)) COLLATE  
                           
                         Latin1_General_CI_AI  
                           
                         AS  
                           
                         VARCHAR(50)  
                     ) = CAST(  
                         CAST(ums.mediumid AS VARCHAR(50)) COLLATE  
                           
                         Latin1_General_CI_AI  
                           
                         AS  
                           
                         VARCHAR(50)  
                     )  
            LEFT JOIN usercampaignsettings ucs  
                 ON  CAST(  
                         CAST(tteq.campaignname AS VARCHAR(50)) COLLATE  
                           
                         Latin1_General_CI_AI AS  
                           
                         VARCHAR(50)  
                     ) = CAST(  
                         CAST(ucs.campaignid AS VARCHAR(50))  
                           
                         COLLATE  
                           
                         Latin1_General_CI_AI AS VARCHAR(50)  
                     )  
            LEFT JOIN usersourcesettings uss  
                 ON  CAST(  
                         CAST(tteq.sourcename AS VARCHAR(50)) COLLATE  
                           
                         Latin1_General_CI_AI  
                           
                         AS  
                           
                         VARCHAR(50)  
                     ) = CAST(  
                         CAST(uss.sourceid AS VARCHAR(50)) COLLATE  
                           
                         Latin1_General_CI_AI  
                           
                         AS  
                           
                         VARCHAR(50)  
                     )  
            LEFT JOIN followup_status fus  
                 ON  CAST(  
                         CAST(tteq.followupstatus AS VARCHAR(50))  
                           
                         COLLATE  
                           
                         Latin1_General_CI_AI AS  
                           
                         VARCHAR(50)  
                     ) = CAST(  
                         CAST(fus.followupstatus AS VARCHAR(50))  
                           
                         COLLATE Latin1_General_CI_AI  
                           
                         AS  
                           
                         VARCHAR(50)  
                     )  
       
       
       
     DROP TABLE #temptableleads  
 END  
 ELSE   
   
 IF (LOWER(@SearchType) = 'co')  
 BEGIN  
     SELECT tteq.personname,  
            tteq.companyname,  
            ISNULL(tteq.mobileno, '')  AS MobileNo,  
            ISNULL(tteq.mobileno1, '') AS MobileNo1,  
            ISNULL(tteq.mobileno2, '') AS MobileNo2,  
            ISNULL(tteq.emailid, '')   AS EMAILID,  
            ISNULL(tteq.emailid1, '')  AS EmailID1,  
            ISNULL(tteq.emailid2, '')  AS EmailID2,  
            tteq.country,  
            tteq.[state],  
            tteq.city,  
            tteq.pincode,  
            tteq.residentialaddress,  
            tteq.officeaddress,  
            uss.NAME                   AS SourceName,  
            ums.NAME                   AS MediumName,  
            ucs.NAME                   AS CampaignName,  
            tteq.initialremarks,  
            @SearchID                  AS SearchID,  
            @ParentID                  AS ParentID,  
            @CampaignID                AS CampaignID  
     FROM   #temptableconversion       AS tteq  
            LEFT JOIN usermediumsettings ums  
                 ON  CAST(  
                         CAST(tteq.mediumname AS VARCHAR(50)) COLLATE  
                           
                         Latin1_General_CI_AI  
                           
                         AS  
                           
                         VARCHAR(50)  
                     ) = CAST(  
                         CAST(ums.mediumid AS VARCHAR(50)) COLLATE  
                           
                         Latin1_General_CI_AI  
                           
                         AS  
                           
                         VARCHAR(50)  
                     )  
            LEFT JOIN usercampaignsettings ucs  
                 ON  CAST(  
                         CAST(tteq.campaignname AS VARCHAR(50)) COLLATE  
                           
                         Latin1_General_CI_AI AS  
                           
                         VARCHAR(50)  
                     ) = CAST(  
                         CAST(ucs.campaignid AS VARCHAR(50))  
                           
                         COLLATE  
                           
                         Latin1_General_CI_AI AS VARCHAR(50)  
                     )  
            LEFT JOIN usersourcesettings uss  
                 ON  CAST(  
                         CAST(tteq.sourcename AS VARCHAR(50)) COLLATE  
                           
                         Latin1_General_CI_AI  
                           
                         AS  
                           
                         VARCHAR(50)  
                     ) = CAST(  
                         CAST(uss.sourceid AS VARCHAR(50)) COLLATE  
                           
                         Latin1_General_CI_AI  
                           
                         AS  
                           
                         VARCHAR(50)  
                     )  
       
       
       
     DROP TABLE #temptableconversion  
 END  
 ELSE   
   
 IF (LOWER(@SearchType) = 'al')  
 BEGIN  
     SELECT A.personname,  
            A.companyname,  
            A.mobileno,  
            A.mobileno1,  
            A.mobileno2,  
            A.emailid,  
            A.emailid1,  
            A.emailid2,  
            A.country,  
            A.[state],  
            A.city,  
            A.pincode,  
            A.residentialaddress,  
            A.officeaddress,  
            A.sourcename,  
            A.mediumname,  
            A.campaignname,  
            A.initialremarks,  
            A.searchid,  
            A.parentid,  
            A.campaignid  
     FROM   (  
                SELECT tteq.personname,  
                       tteq.companyname,  
                       ISNULL(tteq.mobileno, '') AS MobileNo,  
                       ISNULL(tteq.mobileno1, '') AS MobileNo1,  
                       ISNULL(tteq.mobileno2, '') AS MobileNo2,  
                       ISNULL(tteq.emailid, '') AS EMAILID,  
                       ISNULL(tteq.emailid1, '') AS EmailID1,  
                       ISNULL(tteq.emailid2, '') AS EmailID2,  
                       tteq.country,  
                       tteq.[state],  
                       tteq.city,  
                       tteq.pincode,  
                       tteq.residentialaddress,  
                       tteq.officeaddress,  
                       uss.NAME     AS SourceName,  
                       ums.NAME     AS MediumName,  
                       ucs.NAME     AS CampaignName,  
                       tteq.initialremarks,  
                       @SearchID    AS SearchID,  
                       @ParentID    AS ParentID,  
                       @CampaignID  AS CampaignID  
                FROM   #temptableconversion AS tteq  
                       LEFT JOIN usermediumsettings ums  
                            ON  CAST(  
                                    CAST(tteq.mediumname AS VARCHAR(50))  
                                      
                                    COLLATE  
                                      
                                    Latin1_General_CI_AI  
                                      
                                    AS  
                                      
                                    VARCHAR(50)  
                                ) = CAST(  
                                    CAST(ums.mediumid AS VARCHAR(50)) COLLATE  
                                      
                                    Latin1_General_CI_AI  
                                      
                                    AS  
                                      
                                    VARCHAR(50)  
                                )  
                       LEFT JOIN usercampaignsettings ucs  
                            ON  CAST(  
                                    CAST(tteq.campaignname AS VARCHAR(50))  
                                      
                                    COLLATE  
                                      
                                    Latin1_General_CI_AI AS  
                                      
                                    VARCHAR(50)  
                                ) = CAST(  
                                    CAST(ucs.campaignid AS VARCHAR(50))  
                                      
                                    COLLATE  
                                      
                                    Latin1_General_CI_AI AS VARCHAR(50)  
                                )  
                       LEFT JOIN usersourcesettings uss  
                            ON  CAST(  
                                    CAST(tteq.sourcename AS VARCHAR(50))  
                                      
                                    COLLATE  
                                      
                                    Latin1_General_CI_AI  
                                      
                                    AS  
                                      
                                    VARCHAR(50)  
                                ) = CAST(  
                                    CAST(uss.sourceid AS VARCHAR(50)) COLLATE  
                                      
                                    Latin1_General_CI_AI  
                                      
                                    AS  
                                      
                                    VARCHAR(50)  
                                )  
                  
                UNION  
                  
                SELECT tteq.personname,  
                       tteq.companyname,  
                       ISNULL(tteq.mobileno, '') AS MobileNo,  
                       ISNULL(tteq.mobileno1, '') AS MobileNo1,  
                       ISNULL(tteq.mobileno2, '') AS MobileNo2,  
                       ISNULL(tteq.emailid, '') AS EMAILID,  
                       ISNULL(tteq.emailid1, '') AS EmailID1,  
                       ISNULL(tteq.emailid2, '') AS EmailID2,  
                       tteq.country,  
                       tteq.[state],  
                       tteq.city,  
                       tteq.pincode,  
                       tteq.residentialaddress,  
                       tteq.officeaddress,  
                       uss.NAME     AS SourceName,  
                       ums.NAME     AS MediumName,  
                       ucs.NAME     AS CampaignName,  
                       tteq.initialremarks,  
                       @SearchID    AS SearchID,  
                       @ParentID    AS ParentID,  
                       @CampaignID  AS CampaignID  
                FROM   #temptableenquiry AS tteq  
                       LEFT JOIN usermediumsettings ums  
                            ON  CAST(  
                                    CAST(tteq.mediumname AS VARCHAR(50))  
                                      
                                    COLLATE  
                                      
          Latin1_General_CI_AI  
                                      
                                    AS  
                                      
                                    VARCHAR(50)  
                                ) = CAST(  
                                    CAST(ums.mediumid AS VARCHAR(50)) COLLATE  
                                      
                                    Latin1_General_CI_AI  
                                      
                                    AS  
                                      
                                    VARCHAR(50)  
                                )  
                       LEFT JOIN usercampaignsettings ucs  
                            ON  CAST(  
                                    CAST(tteq.campaignname AS VARCHAR(50))  
                                      
                                    COLLATE  
                                      
                                    Latin1_General_CI_AI AS  
                                      
                                    VARCHAR(50)  
                                ) = CAST(  
                                    CAST(ucs.campaignid AS VARCHAR(50))  
                                      
                                    COLLATE  
                                      
                                    Latin1_General_CI_AI AS VARCHAR(50)  
                                )  
                       LEFT JOIN usersourcesettings uss  
                            ON  CAST(  
                                    CAST(tteq.sourcename AS VARCHAR(50))  
                                      
                                    COLLATE  
                                      
                                    Latin1_General_CI_AI  
                                      
                                    AS  
                                      
                                    VARCHAR(50)  
                                ) = CAST(  
                                    CAST(uss.sourceid AS VARCHAR(50)) COLLATE  
                                      
                                    Latin1_General_CI_AI  
                                      
                                    AS  
                                      
                                    VARCHAR(50)  
                                )  
                  
                UNION  
                  
                SELECT tteq.personname,  
                       tteq.companyname,  
                       ISNULL(tteq.mobileno, '') AS MobileNo,  
                       ISNULL(tteq.mobileno1, '') AS MobileNo1,  
                       ISNULL(tteq.mobileno2, '') AS MobileNo2,  
                       ISNULL(tteq.emailid, '') AS EMAILID,  
                       ISNULL(tteq.emailid1, '') AS EmailID1,  
                       ISNULL(tteq.emailid2, '') AS EmailID2,  
                       tteq.country,  
                       tteq.[state],  
                       tteq.city,  
                       tteq.pincode,  
                       tteq.residentialaddress,  
                       tteq.officeaddress,  
                       uss.NAME     AS SourceName,  
                       ums.NAME     AS MediumName,  
                       ucs.NAME     AS CampaignName,  
                       tteq.initialremarks,  
                       @SearchID    AS SearchID,  
                       @ParentID    AS ParentID,  
                       @CampaignID  AS CampaignID  
                FROM   #temptableleads AS tteq  
                       LEFT JOIN usermediumsettings ums  
                            ON  CAST(  
                                    CAST(tteq.mediumname AS VARCHAR(50))  
                                      
                                    COLLATE  
                                      
                                    Latin1_General_CI_AI  
                                      
                                    AS  
                                      
  VARCHAR(50)  
                                ) = CAST(  
                                    CAST(ums.mediumid AS VARCHAR(50)) COLLATE  
                                      
                                    Latin1_General_CI_AI  
                                      
                                    AS  
                                      
                                    VARCHAR(50)  
                                )  
                       LEFT JOIN usercampaignsettings ucs  
                            ON  CAST(  
                                    CAST(tteq.campaignname AS VARCHAR(50))  
                                      
                                    COLLATE  
                                      
                                    Latin1_General_CI_AI AS  
                                      
                                    VARCHAR(50)  
                                ) = CAST(  
                                    CAST(ucs.campaignid AS VARCHAR(50))  
                                      
                                    COLLATE  
                                      
                                    Latin1_General_CI_AI AS VARCHAR(50)  
                                )  
                       LEFT JOIN usersourcesettings uss  
                            ON  CAST(  
                                    CAST(tteq.sourcename AS VARCHAR(50))  
                                      
                                    COLLATE  
                                      
                                    Latin1_General_CI_AI  
                                      
                                    AS  
                                      
                                    VARCHAR(50)  
                                ) = CAST(  
                                    CAST(uss.sourceid AS VARCHAR(50)) COLLATE  
                                      
                                    Latin1_General_CI_AI  
                                      
                                    AS  
                                      
                                    VARCHAR(50)  
                                )  
            ) A  
       
       
       
     DROP TABLE #temptableenquiry  
       
       
       
     DROP TABLE #temptableleads  
       
       
       
     DROP TABLE #temptableconversion  
 END  
END 


GO

/* ============================================================
   Procedure: [dbo].[usp_ExecuteUserSearchGroup]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

            
CREATE   PROCEDURE [dbo].[usp_ExecuteUserSearchGroup] --34261,210919,6750 ,34261  --335,152762,NULL                  
  @ParentID BIGINT,                 
  @SearchID BIGINT,                  
  @CampaignID BIGINT = NULL,                
  @UserID Bigint =null                  
 AS                  
 BEGIN                   
 set @UserID = coalesce(@userid,@parentid)                 
DECLARE @SearchType                VARCHAR(50),                  
        @Medium                    VARCHAR(50),                  
        @Source                    VARCHAR(50),                  
        @Campaign                  VARCHAR(50),                  
        @SpecificName              VARCHAR(50),                  
        @SpecificAddress           VARCHAR(50),                  
        @SpecificMobileNo          VARCHAR(50),                  
        @SpecificEmail             VARCHAR(50),                  
        @SpecificCity              VARCHAR(50),                  
        @SpecificState             VARCHAR(50),                  
        @SpecificCountry           VARCHAR(50),                  
        @CurrentlyAssignedTo       VARCHAR(50),                  
        @FollowUpStatus            VARCHAR(50),                  
        @CreatedBetweenFrom        VARCHAR(50),                  
        @CreatedBetweenTo          VARCHAR(50),                  
        @NextFollowUpDateFrom      VARCHAR(50),                  
        @NextFollowUpDateTo        VARCHAR(50),                  
        @ConvertedWithinFrom       VARCHAR(50),                  
        @ConvertedWithinTo         VARCHAR(50),                  
        @NameGRP                   VARCHAR(5000),                  
        @CompanyGRP                VARCHAR(500),                  
        @MobileGRP                 VARCHAR(5000),                  
        @EmailGRP                  VARCHAR(5000),                  
        @CityGRP                   VARCHAR(5000),                  
        @StateGRP                  VARCHAR(5000),                  
        @CountryGRP                VARCHAR(5000),                  
        @AddressGRP                VARCHAR(500),                  
        @BirthBetweenFromGRP       VARCHAR(50),                  
        @BirthBetweenToGRP         VARCHAR(50),                  
        @ANVBetweenFromGRP         VARCHAR(50),                  
        @ANVBetweenToGRP           VARCHAR(50),                  
        @CreatedBetweenFromGRP     VARCHAR(50),                  
        @CreatedBetweenToGRP       VARCHAR(50),              
        @Groups                 Varchar(5000),              
        @IsENQLeadCNV              BIT,                  
        @IsGroup                   BIT                    
                   
                   
                   
SELECT @SearchType = usl.searchtype,                  
       @Medium                    = usl.medium,                  
       @Source                    = usl.source,                  
       @Campaign                  = usl.campaign,                  
       @SpecificName              = usl.specificname,                  
       @SpecificAddress           = usl.specificaddress,                  
       @SpecificMobileNo          = usl.specificmobileno,                  
       @SpecificEmail             = usl.specificemail,                  
       @SpecificCity              = usl.specificcity,                  
       @SpecificState             = usl.specificstate,                  
       @SpecificCountry           = usl.specificcountry,                  
       @CurrentlyAssignedTo       = usl.currentlyassignedto,                  
       @FollowUpStatus            = usl.followupstatus,                  
       @CreatedBetweenFrom        = usl.createdbetweenfrom,                  
       @CreatedBetweenTo          = usl.createdbetweento,                  
       @NextFollowUpDateFrom      = usl.nextfollowupdatefrom,                  
       @NextFollowUpDateTo        = usl.nextfollowupdateto,                  
  @ConvertedWithinFrom       = usl.convertedwithinfrom,                  
       @ConvertedWithinTo         = usl.convertedwithinto,        
       @NameGRP                   = usl.NameGRP,                  
       @CompanyGRP                = usl.CompanyGRP,                  
     @MobileGRP                 = usl.MobileGRP,                  
       @EmailGRP                  = usl.EmailGRP,                  
       @CityGRP                  = usl.CityGRP,                  
       @StateGRP                  = usl.StateGRP,                  
       @CountryGRP                = usl.CountryGRP,                  
       @AddressGRP                = usl.AddressGRP,                  
       @BirthBetweenFromGRP       = usl.BirthBetweenFromGRP,                 
       @BirthBetweenToGRP         = usl.BirthBetweenToGRP,                  
       @ANVBetweenFromGRP         = usl.ANVBetweenFromGRP,                  
       @ANVBetweenToGRP           = usl.ANVBetweenToGRP,               
       @CreatedBetweenFromGRP     = usl.CreatedBetweenFromGRP,                  
       @CreatedBetweenToGRP       = usl.CreatedBetweenToGRP,                  
       @IsENQLeadCNV              = usl.IsENQLeadCNV,                  
       @IsGroup                  = usl.IsGroup ,              
       @Groups                = usl.GroupsGRP                
FROM   usersearchlist AS usl                  
WHERE  usl.id = @SearchID                    
            
if (@IsGroup = 1)                 
BEGIN                   
                
   CREATE TABLE #tempTableContactDetails                  
        (                  
         Contact_ID             BIGINT,                  
         Contact_Name           VARCHAR(150),                  
         Contact_Mobile         VARCHAR(50),                  
         Contact_Email          VARCHAR(50),                  
         Contact_DOB            VARCHAR(50),                  
         Contact_Anniversary    VARCHAR(50),                  
         CompanyName            VARCHAR(100),                  
         City                   VARCHAR(100),                  
         STATE                  VARCHAR(100),                  
         Country                VARCHAR(100),                  
         ADDRESS                VARCHAR(200),                  
         DateCreated            VARCHAR(50)                  
                           
        )                    
                
         INSERT INTO #tempTableContactDetails                  
          (                  
            Contact_ID ,                  
         Contact_Name  ,                  
         Contact_Mobile ,                  
         Contact_Email ,                  
         Contact_DOB ,                  
         Contact_Anniversary ,                  
         CompanyName ,                  
         City ,                 
         STATE ,                  
         Country ,                  
         ADDRESS ,                  
         DateCreated                             
          )                  
        SELECT                 
          CD.Contact_ID,                
          CD.Contact_Name,                
          CD.Contact_Mobile ,                
          CD.Contact_Email,                
          CD.Contact_DOB,                
          CD.Contact_Anniversary,                
          CD.CompanyName,                
          CD.City,                
          CD.State,                
          CD.Country,                
          CD.Address,                
          CD.DateCreated                 
        FROM   Contact_Detail AS CD                  
        WHERE  CD.User_ID = @UserID                    
                
                
      IF (ISNULL(@NameGRP, '') <> '')                  
        BEGIN                  
            DELETE                   
            FROM   #tempTableContactDetails                  
            WHERE  Contact_Name NOT IN (SELECT fs.[value]                  
                                      FROM   dbo.Fn_split(@NameGRP, ',') AS fs)                  
        END                    
                
                      
      IF (ISNULL(@MobileGRP, '') <> '')                  
        BEGIN                  
            DELETE                   
            FROM   #tempTableContactDetails                  
            WHERE  Contact_Mobile NOT IN (SELECT fs.[value]                  
                                      FROM   dbo.Fn_split(@MobileGRP, ',') AS fs)                  
        END                    
                 
                
     IF (ISNULL(@EmailGRP, '') <> '')                  
        BEGIN                  
            DELETE         
            FROM   #tempTableContactDetails                  
            WHERE  Contact_Email NOT IN (SELECT fs.[value]                  
                                      FROM   dbo.Fn_split(@EmailGRP, ',') AS fs)                  
        END                    
                 
                     
     IF (ISNULL(@CityGRP, '') <> '')                    BEGIN                  
            DELETE                   
            FROM   #tempTableContactDetails                  
            WHERE  City NOT IN (SELECT fs.[value]                  
                                      FROM   dbo.Fn_split(@CityGRP, ',') AS fs)                  
        END                    
                  
     IF (ISNULL(@StateGRP, '') <> '')                  BEGIN                  
            DELETE                   
            FROM   #tempTableContactDetails                  
            WHERE  STATE NOT IN (SELECT fs.[value]                  
                                      FROM   dbo.Fn_split(@StateGRP, ',') AS fs)                  
        END                    
                  
     IF (ISNULL(@CountryGRP, '') <> '')                  
        BEGIN             
            DELETE                   
            FROM   #tempTableContactDetails                  
            WHERE  Country NOT IN (SELECT fs.[value]                  
                                      FROM   dbo.Fn_split(@CountryGRP, ',') AS fs)                  
        END                    
                        
                        
        IF (ISNULL(@CompanyGRP, '') <> '')                  
        BEGIN                  
            DELETE                   
            FROM   #tempTableContactDetails                  
            WHERE  CompanyName not LIKE '%' + @CompanyGRP + '%'                  
                                  
        END                    
                       
        IF (ISNULL(@AddressGRP, '') <> '')                  
        BEGIN                  
            DELETE                   
            FROM   #tempTableContactDetails                  
            WHERE  ADDRESS not LIKE '%' + @AddressGRP + '%'                  
                                  
        END                    
                       
                       
        IF(                  
               ISNULL(@BirthBetweenFromGRP, '') <> ''                  
               AND ISNULL(@BirthBetweenToGRP, '') <> ''                  
          )                  
        BEGIN                  
            update #tempTableContactDetails set contact_dob =null where contact_dob not like '%_/%_/____%'    
   --select * from #tempTableContactDetails where contact_dob not like '%_/__/____ %'    
   delete from #tempTableContactDetails where Contact_dob is null            
                        
            DELETE                   
            FROM   #tempTableContactDetails                  
            WHERE  Contact_ID NOT IN (SELECT cd.Contact_ID                  
                      FROM   #tempTableContactDetails AS cd                  
                      WHERE  DATEDIFF(                  
                       d,                  
                       CONVERT(                  
                              DATETIME,                  
                              CAST(DATEPART(DAY, CONVERT(DATETIME, cd.Contact_DOB, 104)) AS VARCHAR(10))                  
                       + '/' + CAST(DATEPART(MONTH, CONVERT(DATETIME, cd.Contact_DOB, 104)) AS VARCHAR(10))                  
                              + '/' + CAST(DATEPART(YEAR, GETDATE()) AS VARCHAR(10)),                  
                              104                  
                          ),                  
                          GETDATE()                  
                      )                   
                                        
                     BETWEEN                   
                                        
                      @BirthBetweenFromGRP AND                   
                                        
                      @BirthBetweenToGRP                  
                                    
                      and isnull(cd.Contact_DOB,'') <> '')                
                          
          End                
                
                    
     IF(                  
               ISNULL(@ANVBetweenFromGRP, '') <> ''                  
           AND ISNULL(@ANVBetweenToGRP, '') <> ''                  
          )                  
        BEGIN    
  update #tempTableContactDetails set Contact_Anniversary =null where Contact_Anniversary not like '%_/%_/____%'    
   --select * from #tempTableContactDetails where contact_dob not like '%_/__/____ %'    
   delete from #tempTableContactDetails where Contact_Anniversary is null                  
                        
                        
            DELETE                   
            FROM   #tempTableContactDetails                  
            WHERE  Contact_ID NOT IN (SELECT cd.Contact_ID                  
                      FROM   #tempTableContactDetails AS cd                  
                      WHERE  DATEDIFF(                  
                       d,                  
                       CONVERT(                  
                              DATETIME,                  
                              CAST(DATEPART(DAY, CONVERT(DATETIME, Contact_Anniversary, 104)) AS VARCHAR(10))                  
                    + '/' + CAST(DATEPART(MONTH, CONVERT(DATETIME, Contact_Anniversary, 104)) AS VARCHAR(10))                  
                              + '/' + CAST(DATEPART(YEAR, GETDATE()) AS VARCHAR(10)),104 ),GETDATE()                  
                              )                   
                                        
                      BETWEEN                   
                                        
                      @ANVBetweenFromGRP AND                   
                                        
                      @ANVBetweenToGRP                  
                                      
                      and isnull(cd.Contact_Anniversary,'') <> '')                
                          
          End                
                
                
                
         IF(                  
               ISNULL(@CreatedBetweenFromGRP, '') <> ''                  
               AND ISNULL(@CreatedBetweenToGRP, '') <> ''                  
          )                  
        BEGIN           
            DELETE                   
            FROM   #tempTableContactDetails                  
            WHERE  Contact_ID NOT IN (SELECT cd.Contact_ID                  
                      FROM   #tempTableContactDetails AS cd                  
                      WHERE                 
                                      
                      -- DATEDIFF(                  
                      -- d,                  
                      -- CONVERT(                  
                      --        DATETIME,                  
                      --        CAST(DATEPART(MONTH, CONVERT(DATETIME, DateCreated, 101)) AS VARCHAR(10))                  
                      --        + '/' + CAST(DATEPART(DAY, CONVERT(DATETIME, DateCreated, 101)) AS VARCHAR(10))                  
                      --        + '/' + CAST(DATEPART(YEAR, GETDATE()) AS VARCHAR(10)),101 ),GETDATE()                  
                --        )                   
                                        
                      DATEDIFF(d,cd.DateCreated, GETDATE())                
                      BETWEEN                   
                                        
                      @CreatedBetweenFromGRP AND                   
                                        
                      @CreatedBetweenToGRP  )                
                        
        End                
                  
IF @Groups <>'-1' --when it doesn't matter if contact belongs to a group or not            
       begin            
       select * into #Contact_Group_Detail from Contact_Group_Detail where user_id=@UserID        
       if @Groups='' --when contact belongs to any groups            
       begin            
       DELETE t                  
            FROM   #tempTableContactDetails t                  
            WHERE not exists (select 1 from #Contact_Group_Detail c (nolock)              
            where c.Contact_ID=t.Contact_ID)             
       end            
       else if @Groups='0' --when contact should not belong to any group            
       begin            
       DELETE t                  
            FROM   #tempTableContactDetails t                  
            WHERE  exists (select 1 from #Contact_Group_Detail c   (nolock)            
            where c.Contact_ID=t.Contact_ID)             
       end            
       else                   
        BEGIN                  
            DELETE  t                 
            FROM   #tempTableContactDetails  t                
            WHERE  not exists(              
            select 1 from #Contact_Group_Detail c (nolock)             
            where Group_ID in ( SELECT fs.[value] FROM   dbo.Fn_split(@Groups, ',') AS fs               
 ) and c.Contact_ID=t.Contact_ID                          
              )                   
              --and              
              --(  Contact_ID not in (              
              --    select distinct Contact_ID from Contact_Group_Detail              
              --   where Group_ID not in(              
              --   SELECT fs.[value] FROM   dbo.Fn_split(@Groups, ',') AS fs              
              --   )               
              --   and USER_ID = @UserID              
              --)              
                                              
               --)              
                           
             --and (Contact_ID not in (              
             --     select distinct Contact_ID from Contact_Group_Detail              
             --      where USER_ID = @UserID              
             --    )              
                           
             --)               
                                  
        END               
        end                 
        
                
                   
                    
                    
    SELECT CD.Contact_ID,                
          CD.Contact_Name,                
          CD.Contact_Mobile ,                
          CD.Contact_Email,                
          CD.Contact_DOB,                
          CD.Contact_Anniversary,                
          CD.CompanyName,                
       CD.City,                
          CD.State,                
          CD.Country,                
          CD.Address,                
          CD.DateCreated ,                
          @SearchID                  AS SearchID,                  
          @ParentID                  AS ParentID,                
          @CampaignID                AS CampaignID,                
          @UserID                    As UserID                   
        FROM   #tempTableContactDetails       AS CD                  
                    
                
     DROP TABLE #tempTableContactDetails        
     if OBJECT_ID('tempdb..#Contact_Group_Detail') is not null        
     begin      
     drop table #Contact_Group_Detail                 
     end      
                
END                  
END 


