FROM   usersearchlist AS usl                    
WHERE  usl.id = @SearchID                      
              
if (@IsGroup = 1)                   
BEGIN                     
                  
   CREATE TABLE #tempTableContactDetails                    
        (                    
         Contact_ID             BIGINT,                    
         Contact_Name           VARCHAR(150),                    
         Contact_Mobile         VARCHAR(50),                    
         Contact_Email          VARCHAR(50),                    
         Contact_DOB            VARCHAR(50),                    
