            FROM   #tempTableContactDetails                    
            WHERE  ADDRESS not LIKE '%' + @AddressGRP + '%'                    
                                    
        END                      
                         
                         
        IF(                    
               ISNULL(@BirthBetweenFromGRP, '') <> ''                    
               AND ISNULL(@BirthBetweenToGRP, '') <> ''                    
          )                    
        BEGIN                    
            update #tempTableContactDetails set contact_dob =null where contact_dob not like '%_/%_/____%'      
   --select * from #tempTableContactDetails where contact_dob not like '%_/__/____ %'      
   delete from #tempTableContactDetails where Contact_dob is null              
                          
            DELETE                     
            FROM   #tempTableContactDetails                    
            WHERE  Contact_ID NOT IN (SELECT cd.Contact_ID                    
                      FROM   #tempTableContactDetails AS cd                    
                      WHERE  DATEDIFF(                    
                       d,                    
                       CONVERT(                    
                              DATETIME,                    
                              CAST(DATEPART(DAY, CONVERT(DATETIME, cd.Contact_DOB, 104)) AS VARCHAR(10))                    
                       + '/' + CAST(DATEPART(MONTH, CONVERT(DATETIME, cd.Contact_DOB, 104)) AS VARCHAR(10))                    
                              + '/' + CAST(DATEPART(YEAR, GETDATE()) AS VARCHAR(10)),                    
                              104                    
                          ),                    
                          GETDATE()                    
