    SELECT 'Contacts' EntityName, CD.Contact_ID,                  
          CD.Contact_Name,                  
          CD.Contact_Mobile ,                  
          CD.Contact_Email,                  
          CD.Contact_DOB,                  
          CD.Contact_Anniversary,                  
          CD.CompanyName,                  
       CD.City,                  
          CD.State,                  
          CD.Country,                  
          CD.Address,                  
          CD.DateCreated ,                  
          @SearchID                  AS SearchID,                    
          @ParentID                  AS ParentID,                  
          @CampaignID                AS CampaignID,                  
          @UserID                    As UserID                     
        FROM   #tempTableContactDetails       AS CD                    
                      
                  
     DROP TABLE #tempTableContactDetails          
     if OBJECT_ID('tempdb..#Contact_Group_Detail') is not null          
