     )    
         
         
         
         
         
         
         
     INSERT INTO #temptableenquiry    
       (    
         id,    
         personname,    
         companyname,    
         mobileno,    
         mobileno1,    
         mobileno2,    
         emailid,    
 emailid1,    
         emailid2,    
         city,    
         [state],    
         country,    
         countrycode,    
         countrycode1,    
         countrycode2,    
         pincode,    
         residentialaddress,    
         officeaddress,    
         sourcename,    
         mediumname,    
         campaignname,    
         initialremarks,    
         datecreated    
       )    
     SELECT ue.enquiryid,    
            ue.personname,    
            ue.companyname,    
            ue.mobileno,    
            ue.mobileno1,    
            ue.mobileno2,    
            ue.emailid,    
            ue.emailid1,    
            ue.emailid2,    
            ue.city,    
            ue.[state],    
            ue.country,    
            ue.countrycode,    
            ue.countrycode1,    
            ue.countrycode2,    
            ue.pincode,    
            ue.residentialaddress,    
            ue.officeaddress,    
            ue.sourcename,    
            ue.mediumname,    
            ue.campaignname,    
            ue.initialremarks,    
            ue.createddate    
     FROM   UserEnquiry AS ue  with (nolock)  
     WHERE  ue.parentid = @ParentID    
         
         
         
         
         
         
         
     IF (ISNULL(@Medium, '') <> '' AND ISNULL(@Medium, '') <> '0')    
     BEGIN    
         DELETE     
         FROM   #temptableenquiry    
         WHERE  mediumname NOT IN (SELECT fs.[value]    
                                   FROM   dbo.Fn_split(@Medium, '#') AS fs)    
