 IF (LOWER(@SearchType) = 'co' OR LOWER(@SearchType) = 'al')    
 BEGIN    
     CREATE TABLE #temptableconversion    
     (    
      id                     BIGINT,    
      personname             VARCHAR(200),    
      companyname            VARCHAR(200),    
      mobileno               VARCHAR(200),    
      mobileno1              VARCHAR(200),    
      mobileno2              VARCHAR(200),    
