			-- end                
			DECLARE @FieldColumnText NVARCHAR(500)=' cast(' + @FieldName + ' as nvarchar(max)) ';
			IF( @DataType = 'varchar'
				OR @DataType = 'nvarchar' )
			BEGIN
				SET @FieldColumnText=' cast(' + @FieldName + ' as nvarchar(max)) ';
			END;
			ELSE
			BEGIN
				IF( @DataType = 'numeric' OR @DataType = 'float' OR @DataType = 'int' )
				BEGIN
					SET @FieldColumnText=' cast(cast(' + @FieldName + ' as nvarchar(max)) as numeric(18,4)) ';
				END;
				ELSE
				BEGIN
