			--print  @tempFilterQuery  
			DECLARE @EnquiryCount INT=(SELECT COUNT(1) FROM UserEnquiry(NOLOCK) WHERE [ParentID] = @ParentID);

			--create table #tblEnquiryData(ID bigint, PersonName varchar(200),CompanyName varchar(200),MobileNo VARCHAR(100), MobileNo1 VARCHAR(100), MobileNo2 VARCHAR(100),Countrycode VARCHAR(50),Countrycode1 VARCHAR(50),Countrycode2 VARCHAR(50), EmailID VARCHAR(100), EmailID1 VARCHAR(100), EmailID2 VARCHAR(100), City VARCHAR(100), [State] VARCHAR(100), Country VARCHAR(100), Pincode VARCHAR(50), Residentialaddress VARCHAR(500), Officeaddress VARCHAR(500), SourceName VARCHAR(200), MediumName VARCHAR(200), CampaignName VARCHAR(200), Initialremarks VARCHAR(1000),CreatedDate VARCHAR(50))        
			--insert into #tblEnquiryData    
			--  exec Usp_ViewUserEnquriyDetails_DynamicSearch @FilterQueryCustom,@Parentid,0,@FilterQuery,'',1,@EnquiryCount,''   
			DECLARE @tblEnquiryData TABLE
			(
				[ID]                 BIGINT,
