				[MobileNo2]          VARCHAR(100),
				[Countrycode]        VARCHAR(50),
				[Countrycode1]       VARCHAR(50),
				[Countrycode2]       VARCHAR(50),
				[EmailID]            VARCHAR(100),
				[EmailID1]           VARCHAR(100),
				[EmailID2]           VARCHAR(100),
				[City]               VARCHAR(100),
				[State]              VARCHAR(100),
				[Country]            VARCHAR(100),
				[Pincode]            VARCHAR(50),
				[Residentialaddress] VARCHAR(500),
				[Officeaddress]      VARCHAR(500),
				[SourceName]         VARCHAR(200),
				[MediumName]         VARCHAR(200),
				[CampaignName]       VARCHAR(200),
				[Initialremarks]     VARCHAR(1000),
				[CreatedDate]        VARCHAR(50)

			/*,IsduplicateEmail bit, IsduplicateMobile bit*/
			);

