			PRINT concat('Tempfilterquery: ', @tempFilterQuery, ', Filterquerycustom: ', @FilterQueryCustom);
			INSERT INTO @tblEnquiryData([ID], [PersonName], [CompanyName], [MobileNo], [MobileNo1],
			[MobileNo2], [Countrycode], [Countrycode1], [Countrycode2], [EmailID], [EmailID1], [EmailID2],
			[City], [State], [Country], [Pincode], [Residentialaddress], [Officeaddress], [SourceName],
			[MediumName], [CampaignName], [Initialremarks], [CreatedDate])
			--exec Usp_ViewUserEnquriyDetails_DynamicSearch @FilterQueryCustom,@Parentid,0,@FilterQuery,'',1,@EnquiryCount,''   
			EXEC Usp_ViewUserEnquriyDetails_DynamicSearch @FilterQueryCustom, @Parentid, @Parentid,
			@tempFilterQuery, '', 1, @EnquiryCount, '';

