				--tteq.IsduplicateEmail,  
				--tteq.IsduplicateMobile  
				FROM @tblEnquiryData AS tteq;
			END;

			--declare @Sqlcmd nvarchar(max)    
			--set @Sqlcmd='insert into #tblEnquiryData SELECT  ID, PersonName, CompanyName,MobileNo, MobileNo1, MobileNo2,Countrycode,Countrycode1,Countrycode2,EmailID, EmailID1, EmailID2, City, [State], Country, Pincode, Residentialaddress, Officeaddress, SourceName, MediumName, CampaignName, Initialremarks,CreatedDate    
			--FROM    
			--OPENROWSET(''SQLNCLI'',''Server=103.27.84.114;Database=mysms_dev;Uid=kit19;PWD=P@ssword3110;'',''Exec Usp_ViewUserEnquriyDetails_DynamicSearch '''+ @FilterQueryCustom + ''','+ Cast(@ParentId as nvarchar) + ',0,'''+@FilterQuery+''','''',1,'+CAST( @EnquiryCount as nvarchar)+','''')'''    
			--print @Sqlcmd    
			--Exec(@Sqlcmd)  
			--select * from #tblEnquiryData  
			--      drop table if exists #tblEnquiryData       
		END;

		IF( @SearchType = 'Lead' OR @SearchType = 'All' )
		BEGIN
			PRINT 'Criteria: Lead';
			SET @tempFilterQuery=replace(@FilterQuery, 'TagEntityId', 'ID');

			IF( @SearchType = 'All' )
			BEGIN
				SET @tempFilterQuery=replace(@tempFilterQuery, 'CreatedOn', 'CreatedOn1');
				SET @tempFilterQuery=replace(@tempFilterQuery, 'CreatedDate', 'CreatedOn1');
			END;

			DECLARE @LeadCount INT=(SELECT COUNT(1) FROM Userleads(NOLOCK) WHERE [ParentID] = @ParentID);

			-- create table #tblLeadData(ID bigint,LeadNo bigint ,PersonName VARCHAR(200), CompanyName VARCHAR(200),MobileNo VARCHAR(100) , MobileNo1 VARCHAR(100), MobileNo2 VARCHAR(100),Countrycode VARCHAR(50),Countrycode1 VARCHAR(50),Countrycode2 VARCHAR(50),EmailID VARCHAR(100), EmailID1 VARCHAR(100), EmailID2 VARCHAR(100), City VARCHAR(100), [State] VARCHAR(100), Country VARCHAR(100), Pincode VARCHAR(50), Residentialaddress VARCHAR(500), Officeaddress VARCHAR(500), SourceName VARCHAR(200), MediumName VARCHAR(200), CampaignName VARCHAR(200), Initialremarks VARCHAR(1000), datecreated VARCHAR(50) ,AssignedTo VARCHAR(200),followupstatus VARCHAR(200),nextfollowupdate VARCHAR(200),followupdate nvarchar(200),rownumber1 int ,currentscore int)        
			--insert into #tblLeadData    
			--exec Usp_ViewUserLeadDetails2_DynamicSearch @FilterQueryCustom,@ParentID,0,@FilterQuery,1,@LeadCount,'',0   
			DECLARE @tblLeadData TABLE
			(
				[ID]                 BIGINT,
				[LeadNo]             BIGINT,
				[PersonName]         VARCHAR(200),
				[CompanyName]        VARCHAR(200),
				[MobileNo]           VARCHAR(100),
				[MobileNo1]          VARCHAR(100),
				[MobileNo2]          VARCHAR(100),
				[Countrycode]        VARCHAR(50),
				[Countrycode1]       VARCHAR(50),
				[Countrycode2]       VARCHAR(50),
				[EmailID]            VARCHAR(100),
				[EmailID1]           VARCHAR(100),
				[EmailID2]           VARCHAR(100),
				[City]               VARCHAR(100),
				[State]              VARCHAR(100),
				[Country]            VARCHAR(100),
				[Pincode]            VARCHAR(50),
				[Residentialaddress] VARCHAR(500),
				[Officeaddress]      VARCHAR(500),
				[SourceName]         VARCHAR(200),
				[MediumName]         VARCHAR(200),
				[CampaignName]       VARCHAR(200),
				[Initialremarks]     VARCHAR(1000),
				[datecreated]        VARCHAR(50),
				[AssignedTo]         VARCHAR(200),
				[followupstatus]     VARCHAR(200),
				[nextfollowupdate]   VARCHAR(200),
				[followupdate]       NVARCHAR(200),
				[rownumber1]         INT,
				[currentscore]       INT
			);

			PRINT 'Filterquery: ' + @FilterQueryCustom + ', tempfilterquery: ' + @tempFilterQuery +
			', leadcount: ' + CAST(@LeadCount AS NVARCHAR);
			INSERT INTO @tblLeadData([ID], [LeadNo], [PersonName], [CompanyName], [MobileNo], [MobileNo1],
			[MobileNo2], [Countrycode], [Countrycode1], [Countrycode2], [EmailID], [EmailID1], [EmailID2],
			[City], [State], [Country], [Pincode], [Residentialaddress], [Officeaddress], [SourceName],
			[MediumName], [CampaignName], [Initialremarks], [datecreated], [AssignedTo], [followupstatus],
			[nextfollowupdate], [followupdate], [rownumber1], [currentscore])
			--exec Usp_ViewUserLeadDetails2_DynamicSearch @FilterQueryCustom,@ParentID,0,@FilterQuery,1,@LeadCount,'',0   
			EXEC Usp_ViewUserLeadDetails2_DynamicSearch_Replication$ @FilterQueryCustom, @ParentID, @Parentid, @tempFilterQuery, 1, @LeadCount, '', 0;

			IF( @SearchType = 'Lead' )
			BEGIN
				insert into tbl_SearchResult([EntityName], [EntityID], [personname],
				[companyname], [mobileno], [MobileNo1], [MobileNo2], [EMAILID], [EmailID1], [EmailID2],
				[country], [state], [city], [pincode], [residentialaddress], [officeaddress], [SourceName],
				[MediumName], [CampaignName], [initialremarks], [SearchID], [ParentID], [CampaignID])
				SELECT @EntityNameLead AS [EntityName], [tteq].[id] AS [EntityID], [tteq].[personname],
				[tteq].[companyname], ISNULL([tteq].[mobileno], '') AS [MobileNo], ISNULL([tteq].[mobileno1],
				'') AS [MobileNo1], ISNULL([tteq].[mobileno2], '') AS [MobileNo2], ISNULL([tteq].[emailid],
				'') AS [EMAILID], ISNULL([tteq].[emailid1], '') AS [EmailID1], ISNULL([tteq].[emailid2], '')
				AS [EmailID2], [tteq].[country], [tteq].[state], [tteq].[city], [tteq].[pincode], [tteq].
				[residentialaddress], [tteq].[officeaddress], [tteq].[SourceName], [tteq].[MediumName],
				[tteq].[CampaignName], [tteq].[initialremarks], @CriteriaID AS [SearchID], @ParentID AS
				[ParentID], @CampaignID AS [CampaignID]
				FROM @tblLeadData AS tteq;
			END;

		END;

		IF( @SearchType = 'Conversion' OR @SearchType = 'All' )
		BEGIN
			PRINT 'Criteria: Conversion';

			DECLARE @LeadCount_conv INT=(SELECT COUNT(1) FROM Userleads(NOLOCK) WHERE [ParentID] = @ParentID)

			--create table #tblLeadConversionData(ID bigint,LeadNo bigint ,PersonName VARCHAR(200), CompanyName VARCHAR(200),MobileNo VARCHAR(100) , MobileNo1 VARCHAR(100), MobileNo2 VARCHAR(100),Countrycode VARCHAR(50),Countrycode1 VARCHAR(50),Countrycode2 VARCHAR(50),EmailID VARCHAR(100), EmailID1 VARCHAR(100), EmailID2 VARCHAR(100), City VARCHAR(100), [State] VARCHAR(100), Country VARCHAR(100), Pincode VARCHAR(50), Residentialaddress VARCHAR(500), Officeaddress VARCHAR(500), SourceName VARCHAR(200), MediumName VARCHAR(200), CampaignName VARCHAR(200), Initialremarks VARCHAR(1000), datecreated VARCHAR(50) ,AssignedTo VARCHAR(200),followupstatus VARCHAR(200),nextfollowupdate VARCHAR(200),followupdate nvarchar(200),rownumber1 int ,currentscore int)        
			--set   @FilterQuery = '( ( FollowupStatus = ''Converted'' ) and  ' + '('+@FilterQuery +')'+ ')'    
			--insert into #tblLeadConversionData       
			-- exec Usp_ViewUserLeadDetails2_DynamicSearch @FilterQueryCustom,@ParentID,0,@FilterQuery,1,@LeadCount_conv,'',0     
			SET @tempFilterQuery=replace(@FilterQuery, 'TagEntityId', 'ID');

			--set @tempFilterQuery = replace(@tempFilterQuery, 'CreatedOn', 'CreatedOn1')  
			--set @tempFilterQuery = replace(@tempFilterQuery, 'CreatedDate', 'CreatedOn1')  
			IF( @SearchType = 'All' )
			BEGIN
				SET @tempFilterQuery=replace(@tempFilterQuery, 'CreatedOn', 'CreatedOn1');
				SET @tempFilterQuery=replace(@tempFilterQuery, 'CreatedDate', 'CreatedOn1');
			END;

			SET @tempFilterQuery=replace(@tempFilterQuery, 'FollowUpStatus  in  (''Call-Back'')', ' 1=1 ');
			SET @tempFilterQuery=replace(@tempFilterQuery, 'FollowUpStatus  in  (''Not-Interested'')',' 1=1 ');
			SET @tempFilterQuery=replace(@tempFilterQuery, 'FollowUpStatus  in  (''Dead Lead'')', ' 1=1 ');
			SET @tempFilterQuery=replace(@tempFilterQuery, 'FollowUpStatus  in  (''Wrong Number'')', ' 1=1 ');
			SET @tempFilterQuery=replace(@tempFilterQuery, 'FollowUpStatus  in  (''Merge lead'')', ' 1=1 ');

			DECLARE @tblLeadConversionData TABLE
			(
				[ID]                 BIGINT,
				[LeadNo]             BIGINT,
				[PersonName]         VARCHAR(200),
				[CompanyName]        VARCHAR(200),
				[MobileNo]           VARCHAR(100),
				[MobileNo1]          VARCHAR(100),
				[MobileNo2]          VARCHAR(100),
				[Countrycode]        VARCHAR(50),
				[Countrycode1]       VARCHAR(50),
				[Countrycode2]       VARCHAR(50),
				[EmailID]            VARCHAR(100),
				[EmailID1]           VARCHAR(100),
				[EmailID2]           VARCHAR(100),
				[City]               VARCHAR(100),
				[State]              VARCHAR(100),
				[Country]            VARCHAR(100),
				[Pincode]            VARCHAR(50),
				[Residentialaddress] VARCHAR(500),
				[Officeaddress]      VARCHAR(500),
				[SourceName]         VARCHAR(200),
				[MediumName]         VARCHAR(200),
				[CampaignName]       VARCHAR(200),
				[Initialremarks]     VARCHAR(1000),
				[datecreated]        VARCHAR(50),
				[AssignedTo]         VARCHAR(200),
				[followupstatus]     VARCHAR(200),
				[nextfollowupdate]   VARCHAR(200),
				[followupdate]       NVARCHAR(200),
				[rownumber1]         INT,
				[currentscore]       INT
			);

			PRINT 'Filterquery: ' + @FilterQueryCustom + ', tempfilterquery: ' + @tempFilterQuery +
			', leadcount: ' + CAST(@LeadCount_conv AS NVARCHAR);
			INSERT INTO @tblLeadConversionData([ID], [LeadNo], [PersonName], [CompanyName], [MobileNo],
			[MobileNo1], [MobileNo2], [Countrycode], [Countrycode1], [Countrycode2], [EmailID], [EmailID1],
			[EmailID2], [City], [State], [Country], [Pincode], [Residentialaddress], [Officeaddress],
			[SourceName], [MediumName], [CampaignName], [Initialremarks], [datecreated], [AssignedTo],
			[followupstatus], [nextfollowupdate], [followupdate], [rownumber1], [currentscore])
			--exec Usp_ViewUserLeadDetails2_DynamicSearch @FilterQueryCustom,@ParentID,0,@FilterQuery,1,@LeadCount_conv,'',0   
			EXEC Usp_ViewUserLeadDetails2_DynamicSearch_Converted_Replication$ @FilterQueryCustom, @ParentID,			@Parentid, @tempFilterQuery, 1, @LeadCount_conv, '', 0;

			IF( @SearchType = 'Conversion' )
			BEGIN
				INSERT INTO tbl_SearchResult([EntityName], [EntityID], [PersonName], [CompanyName],
				[MobileNo],	[MobileNo1], [MobileNo2], [EmailID], [EmailID1], [EmailID2], [City], [State],
				[Country], [Pincode], [Residentialaddress], [Officeaddress], [SourceName], [MediumName],
				[CampaignName], [Initialremarks], [SearchID], [ParentID], [CampaignID])
				SELECT @EntityNameLead AS [EntityName], [tteq].[id] AS [EntityID], [tteq].[personname],
				[tteq].[companyname], ISNULL([tteq].[mobileno], '') AS [MobileNo], ISNULL([tteq].[mobileno1],
				'') AS [MobileNo1], ISNULL([tteq].[mobileno2], '') AS [MobileNo2], ISNULL([tteq].[emailid],
				'') AS [EMAILID], ISNULL([tteq].[emailid1], '') AS [EmailID1], ISNULL([tteq].[emailid2], '')
				AS [EmailID2], [tteq].[country], [tteq].[state], [tteq].[city], [tteq].[pincode], [tteq].
				[residentialaddress], [tteq].[officeaddress], [tteq].[SourceName], [tteq].[MediumName],
				[tteq].[CampaignName], [tteq].[initialremarks], @CriteriaID AS [SearchID], @ParentID AS
				[ParentID], @CampaignID AS [CampaignID]
				--tteq.countrycode                                
				FROM @tblLeadConversionData AS tteq;
			END;

		END;

		--IF( @SearchType = 'All' )
		--BEGIN
			--SELECT [A].[EntityName], [A].[id] AS [EntityID], [A].[personname], [A].[companyname], [A].
			--[MobileNo], [A].[MobileNo1], [A].[MobileNo2], [A].[EMAILID], [A].[EmailID1], [A].[EmailID2], [A].
			--[country], [A].[state], [A].[city], [A].[pincode], [A].[residentialaddress], [A].[officeaddress],
			--[A].[SourceName], [A].[MediumName], [A].[CampaignName], [A].[initialremarks], [A].[SearchID], [A]
			--.[ParentID], [A].[CampaignID]
			----A.IsduplicateEmail,  
			----A.IsduplicateMobile  
			--FROM(SELECT @EntityNameLead AS [EntityName], [tteq].[id], [tteq].[personname], [tteq].
			--[companyname], ISNULL([tteq].[mobileno], '') AS [MobileNo], ISNULL([tteq].[mobileno1], '') AS
			--[MobileNo1], ISNULL([tteq].[mobileno2], '') AS [MobileNo2], ISNULL([tteq].[emailid], '') AS
			--[EMAILID], ISNULL([tteq].[emailid1], '') AS [EmailID1], ISNULL([tteq].[emailid2], '') AS
			--[EmailID2], [tteq].[country], [tteq].[state], [tteq].[city], [tteq].[pincode], [tteq].
			--[residentialaddress], [tteq].[officeaddress], [tteq].[SourceName], [tteq].[MediumName], [tteq].
			--[CampaignName], [tteq].[initialremarks], @CriteriaID AS [SearchID], @ParentID AS [ParentID],
			--@CampaignID AS [CampaignID]
			--	 -- 0 IsduplicateEmail,  
			--	 --0 IsduplicateMobile  
			--	 FROM @tblLeadConversionData AS tteq
			--	 UNION
			--	 SELECT @EntityNameEnquiry AS [EntityName], [tteq].[id], [tteq].[personname], [tteq].
			--	 [companyname], ISNULL([tteq].[mobileno], '') AS [MobileNo], ISNULL([tteq].[mobileno1], '')
			--	 AS [MobileNo1], ISNULL([tteq].[mobileno2], '') AS [MobileNo2], ISNULL([tteq].[emailid], '')
			--	 AS [EMAILID], ISNULL([tteq].[emailid1], '') AS [EmailID1], ISNULL([tteq].[emailid2], '') AS
			--	 [EmailID2], [tteq].[country], [tteq].[state], [tteq].[city], [tteq].[pincode], [tteq].
			--	 [residentialaddress], [tteq].[officeaddress], [tteq].[SourceName], [tteq].[MediumName],
			--	 [tteq].[CampaignName], [tteq].[initialremarks], @CriteriaID AS [SearchID], @ParentID AS
			--	 [ParentID], @CampaignID AS [CampaignID]
			--	 -- IsduplicateEmail,  
			--	 --IsduplicateMobile  
			--	 FROM @tblEnquiryData AS tteq
			--	 UNION
			--	 SELECT @EntityNameLead AS [EntityName], [tteq].[id], [tteq].[personname], [tteq].
			--	 [companyname], ISNULL([tteq].[mobileno], '') AS [MobileNo], ISNULL([tteq].[mobileno1], '')
			--	 AS [MobileNo1], ISNULL([tteq].[mobileno2], '') AS [MobileNo2], ISNULL([tteq].[emailid], '')
			--	 AS [EMAILID], ISNULL([tteq].[emailid1], '') AS [EmailID1], ISNULL([tteq].[emailid2], '') AS
			--	 [EmailID2], [tteq].[country], [tteq].[state], [tteq].[city], [tteq].[pincode], [tteq].
			--	 [residentialaddress], [tteq].[officeaddress], [tteq].[SourceName], [tteq].[MediumName],
			--	 [tteq].[CampaignName], [tteq].[initialremarks], @CriteriaID AS [SearchID], @ParentID AS
			--	 [ParentID], @CampaignID AS [CampaignID]
			--	 --, 0 IsduplicateEmail,  
			--	 --0 IsduplicateMobile  
			--	 FROM @tblLeadData AS tteq) AS A;

		--END; -- end of all  
		DROP TABLE IF EXISTS #tblEnquiryData;
		DROP TABLE IF EXISTS #tblLeadData;
		DROP TABLE IF EXISTS #tblLeadConversionData;
	END;
	ELSE
	BEGIN
		DECLARE @tblnoData TABLE
		(
			[ID]                 BIGINT,
			[LeadNo]             BIGINT,
			[PersonName]         NVARCHAR(200),
			[CompanyName]        NVARCHAR(200),
			[MobileNo]           NVARCHAR(200),
			[MobileNo1]          NVARCHAR(100),
			[MobileNo2]          NVARCHAR(200),
			[Countrycode]        NVARCHAR(200),
			[Countrycode1]       NVARCHAR(200),
			[Countrycode2]       NVARCHAR(200),
			[EmailID]            NVARCHAR(200),
			[EmailID1]           NVARCHAR(200),
			[EmailID2]           NVARCHAR(200),
			[City]               NVARCHAR(200),
			[State]              NVARCHAR(200),
			[Country]            NVARCHAR(200),
			[Pincode]            NVARCHAR(200),
			[Residentialaddress] NVARCHAR(500),
			[Officeaddress]      NVARCHAR(500),
			[SourceName]         NVARCHAR(200),
			[MediumName]         NVARCHAR(200),
			[CampaignName]       NVARCHAR(200),
			[Initialremarks]     NVARCHAR(1000),
			[rownumber1]         INT,
			[currentscore]       INT
		);

		SELECT CAST('' AS NVARCHAR(20)) AS [EntityName], [tteq].[id] AS [Entityid], [tteq].[personname],
		[tteq].[companyname], ISNULL([tteq].[mobileno], '') AS [MobileNo], ISNULL([tteq].[mobileno1], '') AS
		[MobileNo1], ISNULL([tteq].[mobileno2], '') AS [MobileNo2], ISNULL([tteq].[emailid], '') AS [EMAILID],
		ISNULL([tteq].[emailid1], '') AS [EmailID1], ISNULL([tteq].[emailid2], '') AS [EmailID2], [tteq].
		[country], [tteq].[state], [tteq].[city], [tteq].[pincode], [tteq].[residentialaddress], [tteq].
		[officeaddress], [tteq].[SourceName], [tteq].[MediumName], [tteq].[CampaignName], [tteq].
		[initialremarks], CAST(0 AS BIGINT) AS [SearchID], CAST(0 AS BIGINT) AS [ParentID], CAST(0 AS BIGINT)
		AS [CampaignID]
		--, 0 IsduplicateEmail,  
		--0 IsduplicateMobile  
		FROM @tblnoData AS tteq;

	END;
END;


GO

/* ============================================================
   Procedure: [dbo].[usp_ExecuteUserSearchwithid$$]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- Exec usp_ExecuteUserSearchwithid$$ @ParentID=32222,@CriteriaID=202248,@CampaignID=10352 
CREATE   PROCEDURE [dbo].[usp_ExecuteUserSearchwithid$$]
(
	@ParentID   BIGINT,
	@CriteriaID BIGINT,
	@CampaignID BIGINT=NULL
)
AS
BEGIN
	--declare @ParentID BIGINT =  32222 /*44372 37540*/,@CriteriaID BIGINT = 202248 /*247158 238646 226166*/, @CampaignID BIGINT = null --8954      
	--SET NOCOUNT ON;
	
	IF EXISTS(SELECT 1 FROM tbl_SearchCriteria(NOLOCK) WHERE [ID] = @CriteriaID AND [ParentID] = @Parentid)
	BEGIN
		DROP TABLE IF EXISTS #tblEnquiryData;
		DROP TABLE IF EXISTS #tblLeadData;
		DROP TABLE IF EXISTS #tblLeadConversionData;

		DECLARE @isevent INT=ISNULL((SELECT [iseventbased] FROM UserCampaignMaster(NOLOCK) WHERE [ID] =
		@campaignid AND [Parentid] = @ParentID),0);
		DECLARE @cmedium NVARCHAR(20)=(SELECT [medium] FROM UserCampaignMaster(NOLOCK) WHERE [ID] =
		@campaignid AND [Parentid] = @ParentID);
		DECLARE @LastExecutedTime DATETIME;
		DECLARE @retParamValue SQL_VARIANT, @ParmDefinition NVARCHAR(500)=
		N'@retValInnerOut sql_variant OUTPUT', @paramQuery NVARCHAR(MAX);
		--print 'line 30'                             
		-- if @isevent=1 and @cmedium is not  null                              
		-- begin                              
		-- select @LastExecutedTime = case when @cmedium='SMS'                 
		-- then isnull((select CampaignExecutedDatetime from UserCampaignExecution where issms=1 and isevent=1),getdate())                 
		-- else isnull((select CampaignExecutedDatetime from UserCampaignExecution where issms=0 and isevent=1),getdate()) end                              
		-- end        
		--if(@LastExecutedTime is null)    
		--  Begin    
		--     set @LastExecutedTime = getdate();    
		--  End    
		--Declare @CriteriaID bigint = 4                 
		-- declare @ParentID bigint = 0                
		DECLARE @IsAdmin BIT=0;
		DECLARE @ApplyTo NVARCHAR(50)='applyall';
		DECLARE @AndorOR NVARCHAR(10)='and';
		DECLARE @SearchType NVARCHAR(200)='Enquiry';
		DECLARE @EntityNameEnquiry NVARCHAR(20)='Enquiry';
		DECLARE @EntityNameLead NVARCHAR(20)='Lead';
		DECLARE @CriteriaName NVARCHAR(500)='';
		declare @MailTemplateFieldsJson nvarchar(max)=''
		declare @MailTemplateId bigint=0

		--select top 1 @ParentID = isnull(ParentID,USER_ID),@IsAdmin = isnull(IsAdmin,0) from User_Detail(nolock) where User_ID = @UserID                
		SELECT @ApplyTo=ISNULL([ApplyTo], ''), @SearchType=[CriteriaType], @CriteriaName=[CriteriaName]
		FROM tbl_SearchCriteria(NOLOCK)
		WHERE [ID] = @CriteriaID AND [ParentID] = @Parentid;

		IF( @ApplyTo = 'applyall' )
		BEGIN
			SET @AndorOR='and';
		END;
		ELSE
		BEGIN
			SET @AndorOR='or';
		END;

		DECLARE @tempConditions TABLE
		(
			[RowNum]    INT,
			[FieldName] NVARCHAR(200),
			[FieldType] NVARCHAR(200),
			[Operator]  NVARCHAR(200),
			Value       NVARCHAR(MAX)
		);

		select @MailTemplateId=isnull(TemplateID,0) from usercampaignMaster(nolock) where id=@CampaignID 

		--SELECT ROW_NUMBER() over(order by id asc) as RowNum,                
		--    [FieldName]                
		--    ,[FieldType]                
		--    ,[Operator]                
		--    ,[Value] into #tempConditions                      
		--FROM [tbl_SearchCriteriaConditions] where CriteriaID = @CriteriaID  and [FieldType] <> 'Custom'                 
		INSERT INTO @tempConditions([RowNum], [FieldName], [FieldType], [Operator], [Value])
		SELECT ROW_NUMBER() OVER(ORDER BY [id] ASC) AS [RowNum], [FieldName], [FieldType], [Operator], [Value]
		FROM [tbl_SearchCriteriaConditions](nolock)
		WHERE [CriteriaID] = @CriteriaID AND [FieldType] <> 'Custom';

		DECLARE @InvertedComma NVARCHAR(10)='''';
		--select @InvertedComma+'a'                
		DECLARE @Count INT=0;
		DECLARE @RowIndex INT=0;
		DECLARE @FieldName NVARCHAR(200)='';
		DECLARE @FieldOperator NVARCHAR(200)='';
		DECLARE @Value NVARCHAR(MAX)='';
		DECLARE @FieldType NVARCHAR(200)='';
		DECLARE @DataType NVARCHAR(200)='';
		SELECT @Count=COUNT(1) FROM @tempConditions;
		DECLARE @FilterQuery NVARCHAR(MAX)=' (';

		IF( @Count = 0 )
		BEGIN
			SET @FilterQuery=@FilterQuery + '1=1';
		END;

		WHILE( @Count > 0 )
		BEGIN
			SET @RowIndex=@RowIndex + 1;
			SELECT @FieldName=[FieldName], @FieldOperator=[Operator], @Value=Value, @FieldType=[FieldType]
			FROM @tempConditions
			WHERE [RowNum] = @RowIndex;
			PRINT '109: ' + @searchtype;
			SELECT @DataType=[dbo].[ufn_FetchDataType](@FieldName, @FieldType, @ParentID);
			-- select @DataType                
			IF(@FieldName = 'LeadID' AND @FieldType = 'Lead' AND @CriteriaName = 'All Leads')
			BEGIN
				SET @FieldName='ID';
			END;

			IF(@FieldName = 'IsOpen' AND @FieldType = 'Enquiry')
			BEGIN
				SET @FieldName='IsOpen';
				IF( @Value = 'True' )
				BEGIN
					SET @Value='''open''';
				END;
				ELSE
				BEGIN
					SET @Value='''lead''';
				END;
			END;

			IF( @FieldName = 'LeadNo' AND @FieldType = 'Enquiry' )
			BEGIN
				SET @FieldName=' cast( isnull(nullif(Leads,''''),''0'') as bigint ) ';
			END;
			--print '130: '+@fieldname            
			IF( @FieldName = 'LastFollowupCreatedBy' )
			BEGIN
				SET @FieldName='LastFollowupCreatedByName';
			END;

			IF(@FieldName = 'CreatedOn' AND @FieldType = 'Lead')
			BEGIN
				SET @FieldName='CreatedOn1';
			END;
			--print '141: '+@fieldname                       
			IF( @FieldName = 'CreatedBy' )
			BEGIN
				SET @FieldName='User_Login';
			END;
			--print '146: '+@fieldname                 
			IF( @FieldName = 'AssignedTo' AND @FieldType = 'Lead' )
			BEGIN
				SET @FieldName='assigneduser';
			END;
			--print '151: '+@fieldname             
			IF( @FieldName = 'GoogleLocation' )
			BEGIN
				SET @FieldName='whereAddress';
			END;
			--print '156: '+@fieldname              
			IF( @FieldOperator = '%[A]%' )
			BEGIN
				SET @FieldOperator=' like ';
				SET @Value=SUBSTRING(@Value, 2, LEN(@Value) - 2);
				SET @Value=@InvertedComma + REPLACE('%[A]%', '[A]', @Value) + @InvertedComma;
				PRINT '163: ' + @fieldname;
			END;
			ELSE
			BEGIN
