				[Country]            VARCHAR(100),
				[Pincode]            VARCHAR(50),
				[Residentialaddress] VARCHAR(500),
				[Officeaddress]      VARCHAR(500),
				[SourceName]         VARCHAR(200),
				[MediumName]         VARCHAR(200),
				[CampaignName]       VARCHAR(200),
				[Initialremarks]     VARCHAR(1000),
				[datecreated]        VARCHAR(50),
				[AssignedTo]         VARCHAR(200),
				[AssignedUser]       VARCHAR(200),
				[followupstatus]     VARCHAR(200),
				[nextfollowupdate]   VARCHAR(200),
				[followupdate]       NVARCHAR(200),
				[rownumber1]         INT,
				[currentscore]       INT,
				[MailTemplateFieldsJson] nvarchar(max)
			);

			PRINT 'Filterquery: ' + @FilterQueryCustom + ', tempfilterquery: ' + @tempFilterQuery +
			', leadcount: ' + CAST(@LeadCount AS NVARCHAR);
			INSERT INTO @tblLeadData([ID], [LeadNo], [PersonName], [CompanyName], [MobileNo], [MobileNo1],
			[MobileNo2], [Countrycode], [Countrycode1], [Countrycode2], [EmailID], [EmailID1], [EmailID2],
			[City], [State], [Country], [Pincode], [Residentialaddress], [Officeaddress], [SourceName],
			[MediumName], [CampaignName], [Initialremarks], [datecreated], [AssignedTo], [Assigneduser], [followupstatus], [nextfollowupdate], [followupdate], [rownumber1], [currentscore], [MailTemplateFieldsJson])
			--exec Usp_ViewUserLeadDetails2_DynamicSearch @FilterQueryCustom,@ParentID,0,@FilterQuery,1,@LeadCount,'',0   
			--EXEC Usp_ViewUserLeadDetails2_DynamicSearch_Replication$ @FilterQueryCustom, @ParentID, @Parentid, @tempFilterQuery, 1, @LeadCount, '', 0;
			EXEC Usp_ViewUserLeadDetails2_DynamicSearch_Replication$$ @FilterQueryCustom, @ParentID, @Parentid, @tempFilterQuery, 1, @LeadCount, '', 0, @MailTemplateId;

			IF( @SearchType = 'Lead' )
			BEGIN
				insert into tbl_SearchResult([EntityName], [EntityID], [personname],
				[companyname], [mobileno], [MobileNo1], [MobileNo2], [EMAILID], [EmailID1], [EmailID2],
				[country], [state], [city], [pincode], [residentialaddress], [officeaddress], [SourceName],
				[MediumName], [CampaignName], [initialremarks], [SearchID], [ParentID], [CampaignID], [MailTemplateFieldsJson])
				SELECT @EntityNameLead AS [EntityName], [tteq].[id] AS [EntityID], [tteq].[personname],
				[tteq].[companyname], ISNULL([tteq].[mobileno], '') AS [MobileNo], ISNULL([tteq].[mobileno1],
				'') AS [MobileNo1], ISNULL([tteq].[mobileno2], '') AS [MobileNo2], ISNULL([tteq].[emailid],
				'') AS [EMAILID], ISNULL([tteq].[emailid1], '') AS [EmailID1], ISNULL([tteq].[emailid2], '')
				AS [EmailID2], [tteq].[country], [tteq].[state], [tteq].[city], [tteq].[pincode], [tteq].
				[residentialaddress], [tteq].[officeaddress], [tteq].[SourceName], [tteq].[MediumName],
				[tteq].[CampaignName], [tteq].[initialremarks], @CriteriaID AS [SearchID], @ParentID AS
				[ParentID], @CampaignID AS [CampaignID], tteq.[MailTemplateFieldsJson]
				FROM @tblLeadData AS tteq;
			END;

		END;

		IF( @SearchType = 'Conversion' OR @SearchType = 'All' )
		BEGIN
			PRINT 'Criteria: Conversion';

			DECLARE @LeadCount_conv INT=(SELECT COUNT(1) FROM Userleads(NOLOCK) WHERE [ParentID] = @ParentID)

			--create table #tblLeadConversionData(ID bigint,LeadNo bigint ,PersonName VARCHAR(200), CompanyName VARCHAR(200),MobileNo VARCHAR(100) , MobileNo1 VARCHAR(100), MobileNo2 VARCHAR(100),Countrycode VARCHAR(50),Countrycode1 VARCHAR(50),Countrycode2 VARCHAR(50),EmailID VARCHAR(100), EmailID1 VARCHAR(100), EmailID2 VARCHAR(100), City VARCHAR(100), [State] VARCHAR(100), Country VARCHAR(100), Pincode VARCHAR(50), Residentialaddress VARCHAR(500), Officeaddress VARCHAR(500), SourceName VARCHAR(200), MediumName VARCHAR(200), CampaignName VARCHAR(200), Initialremarks VARCHAR(1000), datecreated VARCHAR(50) ,AssignedTo VARCHAR(200),followupstatus VARCHAR(200),nextfollowupdate VARCHAR(200),followupdate nvarchar(200),rownumber1 int ,currentscore int)        
			--set   @FilterQuery = '( ( FollowupStatus = ''Converted'' ) and  ' + '('+@FilterQuery +')'+ ')'    
			--insert into #tblLeadConversionData       
			-- exec Usp_ViewUserLeadDetails2_DynamicSearch @FilterQueryCustom,@ParentID,0,@FilterQuery,1,@LeadCount_conv,'',0     
			SET @tempFilterQuery=replace(@FilterQuery, 'TagEntityId', 'ID');

			--set @tempFilterQuery = replace(@tempFilterQuery, 'CreatedOn', 'CreatedOn1')  
			--set @tempFilterQuery = replace(@tempFilterQuery, 'CreatedDate', 'CreatedOn1')  
			IF( @SearchType = 'All' )
			BEGIN
				SET @tempFilterQuery=replace(@tempFilterQuery, 'CreatedOn', 'CreatedOn1');
				SET @tempFilterQuery=replace(@tempFilterQuery, 'CreatedDate', 'CreatedOn1');
			END;

			SET @tempFilterQuery=replace(@tempFilterQuery, 'FollowUpStatus  in  (''Call-Back'')', ' 1=1 ');
			SET @tempFilterQuery=replace(@tempFilterQuery, 'FollowUpStatus  in  (''Not-Interested'')',' 1=1 ');
			SET @tempFilterQuery=replace(@tempFilterQuery, 'FollowUpStatus  in  (''Dead Lead'')', ' 1=1 ');
			SET @tempFilterQuery=replace(@tempFilterQuery, 'FollowUpStatus  in  (''Wrong Number'')', ' 1=1 ');
			SET @tempFilterQuery=replace(@tempFilterQuery, 'FollowUpStatus  in  (''Merge lead'')', ' 1=1 ');

			DECLARE @tblLeadConversionData TABLE
			(
				[ID]                 BIGINT,
				[LeadNo]             BIGINT,
				[PersonName]         VARCHAR(200),
				[CompanyName]        VARCHAR(200),
				[MobileNo]           VARCHAR(100),
				[MobileNo1]          VARCHAR(100),
				[MobileNo2]          VARCHAR(100),
				[Countrycode]        VARCHAR(50),
				[Countrycode1]       VARCHAR(50),
				[Countrycode2]       VARCHAR(50),
				[EmailID]            VARCHAR(100),
				[EmailID1]           VARCHAR(100),
				[EmailID2]           VARCHAR(100),
				[City]               VARCHAR(100),
				[State]              VARCHAR(100),
				[Country]            VARCHAR(100),
				[Pincode]            VARCHAR(50),
				[Residentialaddress] VARCHAR(500),
				[Officeaddress]      VARCHAR(500),
				[SourceName]         VARCHAR(200),
				[MediumName]         VARCHAR(200),
				[CampaignName]       VARCHAR(200),
				[Initialremarks]     VARCHAR(1000),
				[datecreated]        VARCHAR(50),
				[AssignedTo]         VARCHAR(200),
				[AssignedUser]       VARCHAR(200),
				[followupstatus]     VARCHAR(200),
				[nextfollowupdate]   VARCHAR(200),
				[followupdate]       NVARCHAR(200),
				[rownumber1]         INT,
				[currentscore]       INT,
				[MailTemplateFieldsJson] nvarchar(max)
			);

			PRINT 'Filterquery: ' + @FilterQueryCustom + ', tempfilterquery: ' + @tempFilterQuery +
			', leadcount: ' + CAST(@LeadCount_conv AS NVARCHAR);
			INSERT INTO @tblLeadConversionData([ID], [LeadNo], [PersonName], [CompanyName], [MobileNo],
			[MobileNo1], [MobileNo2], [Countrycode], [Countrycode1], [Countrycode2], [EmailID], [EmailID1],
			[EmailID2], [City], [State], [Country], [Pincode], [Residentialaddress], [Officeaddress],
			[SourceName], [MediumName], [CampaignName], [Initialremarks], [datecreated], [AssignedTo],
			[AssignedUser], [followupstatus], [nextfollowupdate], [followupdate], [rownumber1], [currentscore], [MailTemplateFieldsJson])
			--exec Usp_ViewUserLeadDetails2_DynamicSearch @FilterQueryCustom,@ParentID,0,@FilterQuery,1,@LeadCount_conv,'',0   
			--EXEC Usp_ViewUserLeadDetails2_DynamicSearch_Converted_Replication$ @FilterQueryCustom, @ParentID,			@Parentid, @tempFilterQuery, 1, @LeadCount_conv, '', 0;
			EXEC Usp_ViewUserLeadDetails2_DynamicSearch_Converted_Replication$$ @FilterQueryCustom, @ParentID,			@Parentid, @tempFilterQuery, 1, @LeadCount_conv, '', 0, @MailTemplateId;

			IF( @SearchType = 'Conversion' )
			BEGIN
				INSERT INTO tbl_SearchResult([EntityName], [EntityID], [PersonName], [CompanyName],
				[MobileNo],	[MobileNo1], [MobileNo2], [EmailID], [EmailID1], [EmailID2], [City], [State],
				[Country], [Pincode], [Residentialaddress], [Officeaddress], [SourceName], [MediumName],
				[CampaignName], [Initialremarks], [SearchID], [ParentID], [CampaignID], [MailTemplateFieldsJson])
				SELECT @EntityNameLead AS [EntityName], [tteq].[id] AS [EntityID], [tteq].[personname],
				[tteq].[companyname], ISNULL([tteq].[mobileno], '') AS [MobileNo], ISNULL([tteq].[mobileno1],
				'') AS [MobileNo1], ISNULL([tteq].[mobileno2], '') AS [MobileNo2], ISNULL([tteq].[emailid],
				'') AS [EMAILID], ISNULL([tteq].[emailid1], '') AS [EmailID1], ISNULL([tteq].[emailid2], '')
				AS [EmailID2], [tteq].[country], [tteq].[state], [tteq].[city], [tteq].[pincode], [tteq].
				[residentialaddress], [tteq].[officeaddress], [tteq].[SourceName], [tteq].[MediumName],
				[tteq].[CampaignName], [tteq].[initialremarks], @CriteriaID AS [SearchID], @ParentID AS
				[ParentID], @CampaignID AS [CampaignID], tteq.MailTemplateFieldsJson
				--tteq.countrycode                                
				FROM @tblLeadConversionData AS tteq;
			END;

		END;

		--IF( @SearchType = 'All' )
		--BEGIN
			--SELECT [A].[EntityName], [A].[id] AS [EntityID], [A].[personname], [A].[companyname], [A].
			--[MobileNo], [A].[MobileNo1], [A].[MobileNo2], [A].[EMAILID], [A].[EmailID1], [A].[EmailID2], [A].
			--[country], [A].[state], [A].[city], [A].[pincode], [A].[residentialaddress], [A].[officeaddress],
			--[A].[SourceName], [A].[MediumName], [A].[CampaignName], [A].[initialremarks], [A].[SearchID], [A]
			--.[ParentID], [A].[CampaignID]
			----A.IsduplicateEmail,  
			----A.IsduplicateMobile  
			--FROM(SELECT @EntityNameLead AS [EntityName], [tteq].[id], [tteq].[personname], [tteq].
			--[companyname], ISNULL([tteq].[mobileno], '') AS [MobileNo], ISNULL([tteq].[mobileno1], '') AS
			--[MobileNo1], ISNULL([tteq].[mobileno2], '') AS [MobileNo2], ISNULL([tteq].[emailid], '') AS
			--[EMAILID], ISNULL([tteq].[emailid1], '') AS [EmailID1], ISNULL([tteq].[emailid2], '') AS
			--[EmailID2], [tteq].[country], [tteq].[state], [tteq].[city], [tteq].[pincode], [tteq].
			--[residentialaddress], [tteq].[officeaddress], [tteq].[SourceName], [tteq].[MediumName], [tteq].
			--[CampaignName], [tteq].[initialremarks], @CriteriaID AS [SearchID], @ParentID AS [ParentID],
			--@CampaignID AS [CampaignID]
			--	 -- 0 IsduplicateEmail,  
			--	 --0 IsduplicateMobile  
			--	 FROM @tblLeadConversionData AS tteq
			--	 UNION
			--	 SELECT @EntityNameEnquiry AS [EntityName], [tteq].[id], [tteq].[personname], [tteq].
			--	 [companyname], ISNULL([tteq].[mobileno], '') AS [MobileNo], ISNULL([tteq].[mobileno1], '')
			--	 AS [MobileNo1], ISNULL([tteq].[mobileno2], '') AS [MobileNo2], ISNULL([tteq].[emailid], '')
			--	 AS [EMAILID], ISNULL([tteq].[emailid1], '') AS [EmailID1], ISNULL([tteq].[emailid2], '') AS
			--	 [EmailID2], [tteq].[country], [tteq].[state], [tteq].[city], [tteq].[pincode], [tteq].
			--	 [residentialaddress], [tteq].[officeaddress], [tteq].[SourceName], [tteq].[MediumName],
			--	 [tteq].[CampaignName], [tteq].[initialremarks], @CriteriaID AS [SearchID], @ParentID AS
			--	 [ParentID], @CampaignID AS [CampaignID]
			--	 -- IsduplicateEmail,  
			--	 --IsduplicateMobile  
			--	 FROM @tblEnquiryData AS tteq
			--	 UNION
			--	 SELECT @EntityNameLead AS [EntityName], [tteq].[id], [tteq].[personname], [tteq].
			--	 [companyname], ISNULL([tteq].[mobileno], '') AS [MobileNo], ISNULL([tteq].[mobileno1], '')
			--	 AS [MobileNo1], ISNULL([tteq].[mobileno2], '') AS [MobileNo2], ISNULL([tteq].[emailid], '')
			--	 AS [EMAILID], ISNULL([tteq].[emailid1], '') AS [EmailID1], ISNULL([tteq].[emailid2], '') AS
			--	 [EmailID2], [tteq].[country], [tteq].[state], [tteq].[city], [tteq].[pincode], [tteq].
			--	 [residentialaddress], [tteq].[officeaddress], [tteq].[SourceName], [tteq].[MediumName],
			--	 [tteq].[CampaignName], [tteq].[initialremarks], @CriteriaID AS [SearchID], @ParentID AS
			--	 [ParentID], @CampaignID AS [CampaignID]
			--	 --, 0 IsduplicateEmail,  
			--	 --0 IsduplicateMobile  
			--	 FROM @tblLeadData AS tteq) AS A;

		--END; -- end of all  
		DROP TABLE IF EXISTS #tblEnquiryData;
		DROP TABLE IF EXISTS #tblLeadData;
		DROP TABLE IF EXISTS #tblLeadConversionData;
	END;
	ELSE
	BEGIN
		DECLARE @tblnoData TABLE
		(
			[ID]                 BIGINT,
			[LeadNo]             BIGINT,
			[PersonName]         NVARCHAR(200),
			[CompanyName]        NVARCHAR(200),
			[MobileNo]           NVARCHAR(200),
			[MobileNo1]          NVARCHAR(100),
			[MobileNo2]          NVARCHAR(200),
			[Countrycode]        NVARCHAR(200),
			[Countrycode1]       NVARCHAR(200),
			[Countrycode2]       NVARCHAR(200),
			[EmailID]            NVARCHAR(200),
			[EmailID1]           NVARCHAR(200),
			[EmailID2]           NVARCHAR(200),
			[City]               NVARCHAR(200),
			[State]              NVARCHAR(200),
			[Country]            NVARCHAR(200),
			[Pincode]            NVARCHAR(200),
			[Residentialaddress] NVARCHAR(500),
			[Officeaddress]      NVARCHAR(500),
			[SourceName]         NVARCHAR(200),
			[MediumName]         NVARCHAR(200),
			[CampaignName]       NVARCHAR(200),
			[Initialremarks]     NVARCHAR(1000),
			[rownumber1]         INT,
			[currentscore]       INT
		);

		SELECT CAST('' AS NVARCHAR(20)) AS [EntityName], [tteq].[id] AS [Entityid], [tteq].[personname],
		[tteq].[companyname], ISNULL([tteq].[mobileno], '') AS [MobileNo], ISNULL([tteq].[mobileno1], '') AS
		[MobileNo1], ISNULL([tteq].[mobileno2], '') AS [MobileNo2], ISNULL([tteq].[emailid], '') AS [EMAILID],
		ISNULL([tteq].[emailid1], '') AS [EmailID1], ISNULL([tteq].[emailid2], '') AS [EmailID2], [tteq].
		[country], [tteq].[state], [tteq].[city], [tteq].[pincode], [tteq].[residentialaddress], [tteq].
		[officeaddress], [tteq].[SourceName], [tteq].[MediumName], [tteq].[CampaignName], [tteq].
		[initialremarks], CAST(0 AS BIGINT) AS [SearchID], CAST(0 AS BIGINT) AS [ParentID], CAST(0 AS BIGINT)
		AS [CampaignID], '' as MailTemplateFieldsJson
		--, 0 IsduplicateEmail,  
		--0 IsduplicateMobile  
		FROM @tblnoData AS tteq;

	END;
END;



