	   end


    End             
       
	   
    if(@SearchType = 'All')
	 Begin
	     SELECT A.EntityName,A.id as EntityID,        
            A.personname,                              
            A.companyname,                              
            A.MobileNo,                            
            A.MobileNo1,                              
            A.MobileNo2,                              
            A.EMAILID,                              
            A.EmailID1,                              
            A.EmailID2,                   
            A.country,                              
            A.[state],                              
            A.city,                              
            A.pincode,                              
            A.residentialaddress,                              
            A.officeaddress,                              
            A.SourceName,                         
            A.MediumName,                              
            A.CampaignName,                              
            A.initialremarks,                              
            A.SearchID,                              
            A.ParentID,                              
            A.CampaignID
		--A.IsduplicateEmail,
			--A.IsduplicateMobile
     FROM   (                              
