                       tteq.officeaddress,                              
                       tteq.SourceName,                              
                       tteq.MediumName,                              
                       tteq.CampaignName,                              
                       tteq.initialremarks,                              
                       @CriteriaID    AS SearchID,                              
                       @ParentID    AS ParentID,                              
                       @CampaignID  AS CampaignID  
					   --, 0 IsduplicateEmail,
					   --0 IsduplicateMobile
                  FROM   @tblLeadData AS tteq                              
                                           
            ) A



	 End -- end of all
	   
	  drop table if exists #tblEnquiryData
	  drop table if exists #tblLeadData
	  drop table if exists #tblLeadConversionData
end
else
begin
Declare @tblnoData table
(ID bigint,LeadNo bigint ,PersonName NVARCHAR(200), CompanyName NVARCHAR(200),MobileNo NVARCHAR(200) , MobileNo1 NVARCHAR(100), 
MobileNo2 NVARCHAR(200),Countrycode NVARCHAR(200),Countrycode1 NVARCHAR(200),Countrycode2 NVARCHAR(200),EmailID NVARCHAR(200), 
EmailID1 NVARCHAR(200), EmailID2 NVARCHAR(200), City NVARCHAR(200), [State] NVARCHAR(200), Country NVARCHAR(200), 
Pincode NVARCHAR(200), Residentialaddress NVARCHAR(500), Officeaddress NVARCHAR(500), SourceName NVARCHAR(200), MediumName NVARCHAR(200), 
CampaignName NVARCHAR(200), Initialremarks NVARCHAR(1000),rownumber1 int ,currentscore int)      
SELECT cast('' as nvarchar(20))as EntityName,tteq.id as Entityid,tteq.personname,                              
                       tteq.companyname,                 
                       ISNULL(tteq.mobileno, '') AS MobileNo,                              
                       ISNULL(tteq.mobileno1, '') AS MobileNo1,                              
                       ISNULL(tteq.mobileno2, '') AS MobileNo2,                              
                       ISNULL(tteq.emailid, '') AS EMAILID,                              
