CREATE   PROCEDURE [dbo].[usp_ExecuteUserSearchwithid_WithPaginationMobileApp]  --34594, 241748, null
(              
   @ParentID BIGINT, 
   @UserId BIGINT = null,
   @CriteriaID BIGINT,                                  
   @CampaignID BIGINT = NULL,
   @srno NVARCHAR(100) = null,  
   @enno NVARCHAR(100) = null
)              
as              
Begin 
    
	--declare 
	--	@ParentID BIGINT =  46312,
	--	@UserId BIGINT =  0,
	--	@CriteriaID BIGINT = 249350,		
	--	@CampaignID BIGINT = null,
