	   print 'Filterquery: '+@FilterQueryCustom+', tempfilterquery: '+ @tempFilterQuery+ ', leadcount: '+cast(@LeadCount as nvarchar) 
	   
	   print concat('@UserId => ', @UserId)
	   
	   --insert into #tblLeadData  (ID ,LeadNo ,PersonName , CompanyName ,MobileNo  , MobileNo1 , MobileNo2 ,Countrycode ,Countrycode1 ,Countrycode2 ,EmailID , EmailID1 , EmailID2 , City , [State] , Country , Pincode , Residentialaddress , Officeaddress , SourceName , MediumName , CampaignName , Initialremarks , datecreated  ,AssignedTo ,followupstatus ,nextfollowupdate ,followupdate ,rownumber1  ,currentscore, rc1  )  
	   
		--exec Usp_ViewUserLeadDetails2_DynamicSearch @FilterQueryCustom,@ParentID,0,@FilterQuery,1,@LeadCount,'',0 
		--exec Usp_ViewUserLeadDetails2_DynamicSearch @FilterQueryCustom,@ParentID,@Parentid, @tempFilterQuery,1,@LeadCount,'',0 
		--exec Usp_ViewUserLeadDetails2_DynamicSearch @FilterQueryCustom,@ParentID,@UserId, @tempFilterQuery,@srno,@enno,'',0
		--exec Usp_ViewUserLeadDetails2_DynamicSearch_MobileApp @FilterQueryCustom,@ParentID,@UserId, @tempFilterQuery,@srno,@enno, '',0
		  
		 -- exec Usp_ViewUserLeadDetails2_New_withnofollowup$_Converted_Replication @FilterQueryCustom,@ParentID,@UserID,@FilterQuery,@srno,@enno,'',0  
		
		print concat('@FilterQueryCustom => ', @FilterQueryCustom)
		print concat('@FilterQuery = > ', @FilterQuery)

		print replace(Cast(@FilterQuery as nvarchar(max)), '''', '''''')

		SET NOCOUNT ON; 
		
		declare @sqlTempLead nvarchar(max) = ''
			set @sqlTempLead = ' insert into #tblLeadData(ID ,LeadNo ,PersonName , CompanyName ,MobileNo  , MobileNo1 , MobileNo2 ,Countrycode ,EmailID , EmailID1 , EmailID2 , City , [State] , Country , Pincode , Residentialaddress , Officeaddress , SourceName , MediumName , CampaignName , Initialremarks ,  AssignedTo ,followupstatus ,followupdate ,rownumber1  ,currentscore, rc1   )'
				+ ' SELECT  ID ,LeadNo ,PersonName , CompanyName ,MobileNo  , MobileNo1 , MobileNo2 ,Countrycode ,EmailID , EmailID1 , EmailID2 , City , [State] , Country , Pincode , Residentialaddress , Officeaddress , SourceName , MediumName , CampaignName, Initialremarks,  AssignedTo, followupstatus, followupdate, rownumber1, currentscore, rc1   
				FROM OPENROWSET (''SQLNCLI'',''Server=aznetpocdbs01;Database=MySMS;Uid=kit19;PWD=P@ssword3110;'',
				''SET NOCOUNT ON; Exec Usp_ViewUserLeadDetails2_New_withnofollowup$_Converted_Replication_mobileTesting ''''' + 
					replace(Cast(@FilterQueryCustom as nvarchar(max)), '''', '''''') + ''''', '
					+ CAST(@ParentID as nvarchar ) + ', '
					+ CAST(@UserID as nvarchar ) + ', ' +
					'''''' + replace(Cast(@FilterQuery as nvarchar(max)), '''', '''''''''') + ''''', ' +
					+ CAST(@srno as nvarchar ) + ', '
					+ CAST(@enno as nvarchar ) 
					+ ', '''''''', 0 WITH RESULT SETS ( ( ID bigint, LeadNo bigint, PersonName NVARCHAR(200), CompanyName NVARCHAR(200), MobileNo NVARCHAR(100), EmailID NVARCHAR(100), City NVARCHAR(100), [State] NVARCHAR(100), Country NVARCHAR(100), CountryCode NVARCHAR(50), PinCode NVARCHAR(50), ResidentialAddress NVARCHAR(500), OfficeAddress NVARCHAR(500), SourceName NVARCHAR(200), MediumName NVARCHAR(200), CampaignName NVARCHAR(200), InitialRemarks NVARCHAR(MAX), ParentID bigint, User_Login NVARCHAR(200), FollowupDate DATETIME, CreatedOn DATETIME, CreatedOn1New DATETIME, CreatedOn1 DATETIME, AssignedTo NVARCHAR(200), Remarks NVARCHAR(MAX), FollowUp NVARCHAR(200), MobileNo1 NVARCHAR(100), MobileNo2 NVARCHAR(100), MobileNo3 NVARCHAR(100), EmailID3 NVARCHAR(255), EmailID1 NVARCHAR(255), EmailID2 NVARCHAR(255), FollowupStatus NVARCHAR(200), assigneduser NVARCHAR(200), assignedUserloginOnly NVARCHAR(200), Img_Ext NVARCHAR(50), WhereAddress NVARCHAR(500), Products NVARCHAR(200), FollowupCreatedDate DATETIME, FollowupBy NVARCHAR(200), CurrentScore INT, Profit_Loss NVARCHAR(200), ThresholdColor NVARCHAR(50), RowNumber1 INT, rc1 INT, LastFollowupCreatedByName NVARCHAR(200), LastFollowupedOn DATETIME, WhatsAppNoColName NVARCHAR(200), CreatedBy NVARCHAR(200), ModifiedOn DATETIME, ModifiedBy NVARCHAR(200), AmountPaid DECIMAL(18, 2) ) )'')'          
          
			print @sqlTempLead         
			execute sp_executesql @sqlTempLead   
		
		insert into @tblLeadData(ID ,LeadNo ,PersonName , CompanyName ,MobileNo  , MobileNo1 , MobileNo2 ,Countrycode ,EmailID , EmailID1 , EmailID2 , City , [State] , Country , Pincode , Residentialaddress , Officeaddress , SourceName , MediumName , CampaignName , Initialremarks ,  AssignedTo ,followupstatus ,followupdate ,rownumber1  ,currentscore, rc1)
		 select ID ,LeadNo ,PersonName , CompanyName ,MobileNo  , MobileNo1 , MobileNo2 ,Countrycode ,EmailID , EmailID1 , EmailID2 , City , [State] , Country , Pincode , Residentialaddress , Officeaddress , SourceName , MediumName , CampaignName , Initialremarks ,  AssignedTo ,followupstatus ,followupdate ,rownumber1  ,currentscore, rc1 from #tblLeadData

	

	print concat('@FilterQueryCustom => ', @FilterQueryCustom, ' => @ParentID => ',
		@ParentID, ' => @UserId => ', @UserId, ' => @tempFilterQuery => ', @tempFilterQuery, ' => @srno => ', @srno, ' => @enno => ', @enno, ' '''' ', '0')

		
	   if(@SearchType = 'Lead')
		 Begin 
		 SELECT @EntityNameLead as EntityName,
		   tteq.id as EntityID,        
             tteq.personname,                              
            tteq.companyname,                              
            ISNULL(tteq.mobileno, '')  AS MobileNo,                              
            ISNULL(tteq.mobileno1, '') AS MobileNo1,                              
            ISNULL(tteq.mobileno2, '') AS MobileNo2,                              
            ISNULL(tteq.emailid, '')   AS EMAILID,                              
          ISNULL(tteq.emailid1, '')  AS EmailID1,                              
            ISNULL(tteq.emailid2, '')  AS EmailID2,                              
            tteq.country,                              
            tteq.[state],                              
            tteq.city,                              
            tteq.pincode,                              
            tteq.residentialaddress,                              
            tteq.officeaddress,                              
            tteq.SourceName,                              
            tteq.MediumName,                              
            tteq.CampaignName,                              
            tteq.initialremarks,                              
            @CriteriaID           AS SearchID,
			@ParentID             AS ParentID,                              
            @CampaignID           AS CampaignID, 
			rc1 as TotalRow                            
     FROM   @tblLeadData            AS tteq                              
          
		  end
		              
    End  
  
   if(@SearchType = 'Conversion'  or @SearchType = 'All' )              
    Begin
	
	   

	     declare @LeadCount_conv int =  (select count(1) from Userleads(nolock) where ParentID = @ParentID)
	  
       --create table #tblLeadConversionData(ID bigint,LeadNo bigint ,PersonName VARCHAR(200), CompanyName VARCHAR(200),MobileNo VARCHAR(100) , MobileNo1 VARCHAR(100), MobileNo2 VARCHAR(100),Countrycode VARCHAR(50),Countrycode1 VARCHAR(50),Countrycode2 VARCHAR(50),EmailID VARCHAR(100), EmailID1 VARCHAR(100), EmailID2 VARCHAR(100), City VARCHAR(100), [State] VARCHAR(100), Country VARCHAR(100), Pincode VARCHAR(50), Residentialaddress VARCHAR(500), Officeaddress VARCHAR(500), SourceName VARCHAR(200), MediumName VARCHAR(200), CampaignName VARCHAR(200), Initialremarks VARCHAR(1000), datecreated VARCHAR(50) ,AssignedTo VARCHAR(200),followupstatus VARCHAR(200),nextfollowupdate VARCHAR(200),followupdate nvarchar(200),rownumber1 int ,currentscore int)      
	 
	 
	
	
	  set   @FilterQuery = '( ( FollowupStatus = ''Converted'' ) and  ' + '('+@FilterQuery +')'+ ')'  

	    --insert into #tblLeadConversionData     
	    -- exec Usp_ViewUserLeadDetails2_DynamicSearch @FilterQueryCustom,@ParentID,0,@FilterQuery,1,@LeadCount_conv,'',0   

		set @tempFilterQuery = replace(@FilterQuery, 'TagEntityId', 'ID')

		--set @tempFilterQuery = replace(@tempFilterQuery, 'CreatedOn', 'CreatedOn1')
		--set @tempFilterQuery = replace(@tempFilterQuery, 'CreatedDate', 'CreatedOn1')
	
	     if(@SearchType = 'All')
		begin
		set @tempFilterQuery = replace(@tempFilterQuery, 'CreatedOn', 'CreatedOn1')
		set @tempFilterQuery = replace(@tempFilterQuery, 'CreatedDate', 'CreatedOn1')
		end  

		 set @tempFilterQuery = replace(@tempFilterQuery, 'FollowUpStatus  in  (''Call-Back'')', ' 1=1 ')
		 set @tempFilterQuery = replace(@tempFilterQuery, 'FollowUpStatus  in  (''Not-Interested'')', ' 1=1 ')
		 set @tempFilterQuery = replace(@tempFilterQuery, 'FollowUpStatus  in  (''Dead Lead'')', ' 1=1 ')
		 set @tempFilterQuery = replace(@tempFilterQuery, 'FollowUpStatus  in  (''Wrong Number'')', ' 1=1 ')
		 set @tempFilterQuery = replace(@tempFilterQuery, 'FollowUpStatus  in  (''Merge lead'')', ' 1=1 ')


		 if((trim(isnull(@srno,'')) = '') or (trim(isnull(@enno,'')) = '') ) 
		  begin
		      set @srno = '1'
			  set @enno = cast(@LeadCount_conv as nvarchar(100))
		  end



		   Declare @tblLeadConversionData table(ID bigint,LeadNo bigint ,PersonName VARCHAR(200), CompanyName VARCHAR(200),MobileNo VARCHAR(100) , MobileNo1 VARCHAR(100), MobileNo2 VARCHAR(100),Countrycode VARCHAR(50),Countrycode1 VARCHAR(50),Countrycode2 VARCHAR(50),EmailID VARCHAR(100), EmailID1 VARCHAR(100), EmailID2 VARCHAR(100), City VARCHAR(100), [State] VARCHAR(100), Country VARCHAR(100), Pincode VARCHAR(50), Residentialaddress VARCHAR(500), Officeaddress VARCHAR(500), SourceName VARCHAR(200), MediumName VARCHAR(200), CampaignName VARCHAR(200), Initialremarks VARCHAR(1000), datecreated VARCHAR(50) ,AssignedTo VARCHAR(200),followupstatus VARCHAR(200),nextfollowupdate VARCHAR(200),followupdate nvarchar(200),rownumber1 int ,currentscore int, rc1 int)      
	   
	   print 'Filterquery: '+@FilterQueryCustom+', tempfilterquery: '+ @tempFilterQuery+ ', leadcount: '+cast(@LeadCount_conv as nvarchar) 
	         insert into @tblLeadConversionData(ID ,LeadNo ,PersonName , CompanyName ,MobileNo  , MobileNo1 , MobileNo2 ,Countrycode ,Countrycode1 ,Countrycode2 ,EmailID , EmailID1 , EmailID2 , City , [State] , Country , Pincode , Residentialaddress , Officeaddress , SourceName , MediumName , CampaignName , Initialremarks , datecreated  ,AssignedTo ,followupstatus ,nextfollowupdate ,followupdate ,rownumber1  ,currentscore, rc1  )   
	     --exec Usp_ViewUserLeadDetails2_DynamicSearch @FilterQueryCustom,@ParentID,0,@FilterQuery,1,@LeadCount_conv,'',0 
		 --exec Usp_ViewUserLeadDetails2_DynamicSearch @FilterQueryCustom,@ParentID,@Parentid,@tempFilterQuery,1,@LeadCount_conv,'',0 
		 --exec Usp_ViewUserLeadDetails2_DynamicSearch  @FilterQueryCustom,@ParentID,@UserId,@tempFilterQuery,@srno,@enno,'',0 
		 exec Usp_ViewUserLeadDetails2_DynamicSearch_MobileApp @FilterQueryCustom,@ParentID,@UserId, @tempFilterQuery,@srno,@enno, '', 0



	

		if(@SearchType = 'Conversion')
		 Begin 
			 SELECT @EntityNameLead as EntityName,
				tteq.id as EntityID,        
				tteq.personname,                              
				tteq.companyname,                              
				ISNULL(tteq.mobileno, '')  AS MobileNo,                              
				ISNULL(tteq.mobileno1, '') AS MobileNo1,                              
				ISNULL(tteq.mobileno2, '') AS MobileNo2,                              
				ISNULL(tteq.emailid, '')   AS EMAILID,                              
				ISNULL(tteq.emailid1, '')  AS EmailID1,                              
				ISNULL(tteq.emailid2, '')  AS EmailID2,                              
				tteq.country,                              
				tteq.[state],                              
				tteq.city,                              
				tteq.pincode,                              
				tteq.residentialaddress,                              
				tteq.officeaddress,                              
				tteq.SourceName,                              
				tteq.MediumName,                              
				tteq.CampaignName,                              
				tteq.initialremarks,                              
				@CriteriaID           AS SearchID,
				@ParentID             AS ParentID,                              
				@CampaignID           AS CampaignID , 
				rc1 as TotalRow                             
				--tteq.countrycode                              
			FROM   @tblLeadConversionData            AS tteq  

	   end


    End             
       
	   
    if(@SearchType = 'All')
	 Begin
	     SELECT A.EntityName,A.id as EntityID,        
            A.personname,                              
            A.companyname,                              
            A.MobileNo,                            
            A.MobileNo1,                              
            A.MobileNo2,                              
            A.EMAILID,                              
            A.EmailID1,                              
            A.EmailID2,                   
            A.country,                              
            A.[state],                              
            A.city,                              
            A.pincode,                              
            A.residentialaddress,                              
            A.officeaddress,                              
            A.SourceName,                         
            A.MediumName,                              
            A.CampaignName,                              
            A.initialremarks,                              
            A.SearchID,                              
            A.ParentID,                              
            A.CampaignID, 
			A.TotalRow
		--A.IsduplicateEmail,
			--A.IsduplicateMobile
     FROM   (                              
                SELECT @EntityNameLead as EntityName,tteq.id,tteq.personname,                              
         tteq.companyname,                              
                       ISNULL(tteq.mobileno, '') AS MobileNo,                              
                       ISNULL(tteq.mobileno1, '') AS MobileNo1,                              
                       ISNULL(tteq.mobileno2, '') AS MobileNo2,                              
                       ISNULL(tteq.emailid, '') AS EMAILID,                              
                       ISNULL(tteq.emailid1, '') AS EmailID1,                              
                       ISNULL(tteq.emailid2, '') AS EmailID2,                              
                       tteq.country,                              
                       tteq.[state],                              
                       tteq.city,                              
                       tteq.pincode,                              
                       tteq.residentialaddress,                              
                       tteq.officeaddress,                              
                       tteq.SourceName,                              
                       tteq.MediumName,                              
                       tteq.CampaignName,                              
                       tteq.initialremarks,                              
                       @CriteriaID    AS SearchID,                              
                       @ParentID    AS ParentID,                              
                       @CampaignID  AS CampaignID, 
					   rc1 as TotalRow
					   -- 0 IsduplicateEmail,
					   --0 IsduplicateMobile
                FROM   @tblLeadConversionData AS tteq                                                 
                                              
            UNION                              
                       
                                              
                                              
                SELECT @EntityNameEnquiry as EntityName,tteq.id,tteq.personname,                              
                       tteq.companyname,                              
                       ISNULL(tteq.mobileno, '') AS MobileNo,                              
                       ISNULL(tteq.mobileno1, '') AS MobileNo1,                              
                       ISNULL(tteq.mobileno2, '') AS MobileNo2,                              
                       ISNULL(tteq.emailid, '') AS EMAILID,                              
                       ISNULL(tteq.emailid1, '') AS EmailID1,                              
                       ISNULL(tteq.emailid2, '') AS EmailID2,                              
                       tteq.country,           
                       tteq.[state],                              
                       tteq.city,                              
                       tteq.pincode,                              
                       tteq.residentialaddress,                              
                       tteq.officeaddress,                              
                       tteq.SourceName,                              
                       tteq.MediumName,                              
                       tteq.CampaignName,                              
                       tteq.initialremarks,                              
                       @CriteriaID    AS SearchID,                              
                       @ParentID    AS ParentID,                              
                       @CampaignID  AS CampaignID, 
					   rc1 as TotalRow  
					   -- IsduplicateEmail,
					   --IsduplicateMobile
                FROM   @tblEnquiryData AS tteq                              
                                            
                                              
                  
                                
                UNION                              
                                              
                     
                                              
                SELECT @EntityNameLead as EntityName,tteq.id,tteq.personname,                              
                       tteq.companyname,                 
                       ISNULL(tteq.mobileno, '') AS MobileNo,                              
                       ISNULL(tteq.mobileno1, '') AS MobileNo1,                              
                       ISNULL(tteq.mobileno2, '') AS MobileNo2,                              
                       ISNULL(tteq.emailid, '') AS EMAILID,                              
                       ISNULL(tteq.emailid1, '') AS EmailID1,                              
                       ISNULL(tteq.emailid2, '') AS EmailID2,                              
               tteq.country,                              
                       tteq.[state],                              
                       tteq.city,                              
                       tteq.pincode,                              
                       tteq.residentialaddress,                              
                       tteq.officeaddress,                              
                       tteq.SourceName,                              
                       tteq.MediumName,                              
                       tteq.CampaignName,                              
                       tteq.initialremarks,                              
                       @CriteriaID    AS SearchID,                              
                       @ParentID    AS ParentID,                              
                       @CampaignID  AS CampaignID , 
					   rc1 as TotalRow 
					   --, 0 IsduplicateEmail,
					   --0 IsduplicateMobile
                  FROM   @tblLeadData AS tteq                              
                                           
            ) A



	 End -- end of all
	   
	  drop table if exists #tblEnquiryData
	  drop table if exists #tblLeadData
	  drop table if exists #tblLeadConversionData

 End 



