   Procedure: [dbo].[usp_executevoicebot_Sequence]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_executevoicebot_Sequence] --'Lead',	108312013	,564
@context varchar(20),@activityid bigint,@botcampaignid bigint,@errormessage nvarchar(max) output 
as
begin
--declare @context varchar(20)='Lead',@activityid bigint=108312013,@botcampaignid bigint=564,@errormessage nvarchar(max)
DECLARE @NowTime TIME = CONVERT(TIME, GETDATE());
DECLARE @Today   VARCHAR(10) = DATENAME(WEEKDAY, GETDATE());
declare @parentid bigint,@activitycontext nvarchar(max),@entityid bigint,@entitycontext nvarchar(max),@mobile varchar(20),
@countrycode varchar(5),@mobile2 varchar(20),@mobile3 varchar(20),@fromnumber varchar(20),@mobilequeued int=0,
@botid bigint,@telephony_provider varchar(50)

select @parentid=parentid,@fromnumber=json_value(campaign_settings,'$.fromNumber'),@botid=json_value(campaign_settings,'$.botId') 
from voice_bot_campaigns(nolock) where id=@botcampaignid
select @telephony_provider=dbo.fn_getsipname(@fromnumber)
if exists(select 1 from Price_UserSubscriptionDetails(nolock) where UserID=@parentid and isnewplan=1 and planenddate>=CAST(getdate() as date) )
begin
if dbo.GetAvailableBalanceForService(@parentid,23)>=20
begin
drop table if exists #activitydata_r  
create table #activitydata_r(entitydata nvarchar(max),activitydata nvarchar(max),userdata nvarchar(max))  
insert into #activitydata_r(entitydata,activitydata,userdata)  
exec usp_getmetadata_foractivity @activityid,@context  
  
select top 1 @activitycontext=activitydata from #activitydata_r  
select @activitycontext=replace(replace(@activitycontext,'[',''),']','') 

--select 'activitycontext',@activitycontext

if @context='lead'
begin
select @entityid=leadid from tbl_LeadEventHistory(nolock) where historyid=@activityid
end
else if @context='enquiry'
begin
select @entityid=enquiryid from tbl_enquiryEventHistory(nolock) where historyid=@activityid
end

exec [dbo].[usp_replaceentityplaceholders_allfields_insert] @entityid,@context




select top 1 @entitycontext=entitydetails from entity_details_transition(nolock) where entity=@context
and entityid=@entityid

--select 'entitycontext',@entitycontext

select @mobile=JSON_VALUE(@entitycontext,'$.MobileNo'),@mobile2=JSON_VALUE(@entitycontext,'$.MobileNo1'),@mobile3=JSON_VALUE(@entitycontext,'$.MobileNo2'),@countrycode=JSON_VALUE(@entitycontext,'$.CountryCode')
--select @mobile='7840002738',@mobile2='',@mobile3=''

if ISNULL(nullif(@mobile,''),'0')='0' and ISNULL(nullif(@mobile2,''),'0')='0' and ISNULL(nullif(@mobile3,''),'0')='0'
begin
select @errormessage='No valid mobile number'
end
else if ISNULL(ltrim(rtrim(@countrycode)),'+91') not in ('+91','91') and isnull(@fromnumber,'')<>''
begin
select @errormessage='Country not supported for the campaign'
end
else 
begin
drop table if exists #audienceinserted 
create table #audienceinserted(id bigint,priority int,recipient_mobile varchar(20))

--select @mobile

begin try
insert into voice_bot_campaign_audience(parentid,vb_campaignid,created_on,recipient_mobile,recipient_countrycode,recipient_has_countrycode,entity,entityid,
entity_context,picked_on,priority,activityid,activity_context) output inserted.id,inserted.priority,inserted.recipient_mobile into #audienceinserted
select @parentid,@botcampaignid,GETDATE(),@mobile,@countrycode,0,@context,@entityid, @entitycontext,GETDATE(),9, @activityid, @activitycontext where ISNULL(nullif(@mobile,''),'0')<>'0'
union
select @parentid,@botcampaignid,GETDATE(),@mobile2,@countrycode,0,@context,@entityid, @entitycontext,GETDATE(),9, @activityid, @activitycontext where ISNULL(nullif(@mobile2,''),'0')<>'0'
union
select @parentid,@botcampaignid,GETDATE(),@mobile3,@countrycode,0,@context,@entityid, @entitycontext,GETDATE(),9, @activityid, @activitycontext where ISNULL(nullif(@mobile3,''),'0')<>'0'
select @mobilequeued=@@ROWCOUNT

--select * from #audienceinserted

if @mobilequeued>0
begin
select @errormessage='Bot Campaign queued for execution'
insert into tbl_ai_agent_execution_outbox(queuename,agentid,asstt_id,payload,createdon,priority)
select 'voice_bot_obd' as queuename,
  @botid as agentid,
  '' as asstt_id,
  j.payload,
  getutcdate() as createdon,
  isnull(priority,0)
from #audienceinserted b
cross apply (
  select
    b.id as audienceId,
    @botid as botid,
    @parentid as parentid,
    @botcampaignid as campaignId,
    @fromnumber as fromNumber,
    b.recipient_mobile as toNumber,
    @telephony_provider as telephonyProvider,
    case when b.recipient_mobile in ('7840002738') then cast(1 as bit) else cast(0 as bit) end as isTest
  for json path, without_array_wrapper
) j (payload) 
order by isnull(priority,0) desc;


end
end try
begin catch
select @errormessage=ERROR_MESSAGE()
end catch
end
  end
  else
  begin
  select @errormessage='Insufficient balance to execute campaign'
  end
end
else
begin
  select @errormessage='Parent has no active subscription'
end
--select 'errormessage',@errormessage

end



