/* ============================================================
   Procedure: [dbo].[Usp_ExporterKeyDetailsDisplay]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE dbo.Usp_ExporterKeyDetailsDisplay --335                 
 (      
   @UserID BIGINT      
 )        
AS        
BEGIN        
      Declare @ParentID bigint = ( Select top 1 isnull(ParentID,0) from User_Detail with(nolock) where User_ID = @UserID)       
      
 IF (@ParentID <> 335)        
 BEGIN        
  SELECT TEM.ExporterKey        
   ,TEM.ParentId        
   --,dbo.Func_toGetTotalRecordsCountWithDate(IMM.IndiamartId) AS Records        
    --, 0 as Records        
 ,dbo.Func_toGetTotalRecordsCountWithDate_Exporter(TEM.ExporterKey) AS Records        
   ,(        
    SELECT TOP 1 udn.User_Login        
    FROM User_Detail udn        
    WHERE udn.User_ID = TEM.ParentId        
    ) UserLogin        
   ,TEM.STATUS        
   ,TEM.Createdby        
   ,UD.User_Login AS CreatedByName        
   ,TEM.id        
   ,TEM.createdon        
   ,TEM.LastAPIHit        
   ,TEM.ExporterEmailID        
   ,TEM.LastDateFetched        
   ,TEM.ExpiredOn        
  FROM tbl_ExporterMapping as TEM with(nolock)        
  INNER JOIN User_Detail as UD with(nolock) ON TEM.Createdby = UD.User_ID        
  WHERE TEM.ParentId = @ParentID        
  ORDER BY createdon DESC        
 END        
 ELSE        
 BEGIN        
    SELECT TEM.ExporterKey        
   ,TEM.ParentId        
   --,dbo.Func_toGetTotalRecordsCountWithDate(IMM.IndiamartId) AS Records        
    --, 0 as Records   
 ,dbo.Func_toGetTotalRecordsCountWithDate_Exporter(TEM.ExporterKey) AS Records             
   ,(        
    SELECT TOP 1 udn.User_Login        
    FROM User_Detail udn        
    WHERE udn.User_ID = TEM.ParentId        
    ) UserLogin        
   ,TEM.STATUS        
   ,TEM.Createdby        
   ,UD.User_Login AS CreatedByName        
   ,TEM.id        
   ,TEM.createdon        
   ,TEM.LastAPIHit        
   ,TEM.ExporterEmailID        
   ,TEM.LastDateFetched        
   ,TEM.ExpiredOn        
  FROM tbl_ExporterMapping as TEM with(nolock)        
  INNER JOIN User_Detail as UD with(nolock) ON TEM.Createdby = UD.User_ID        
  ORDER BY createdon DESC        
 END        
        
 EXEC MySmsAudit.dbo.Usp_AuditTableDataByParentId @User_id = @UserID        
    ,@Activity_type = 'Fetch Exporter Mapping'        
    ,@ActionType = 'S'        
    ,@RowJson = ''        
    ,@Table_name = 'tbl_ExporterMapping'        
END        


