CREATE   PROC [dbo].[usp_exportExcelForApproveSenderName]
AS
BEGIN
select sender_name from senderid_detail
where rtrim(ltrim(sender_name)) not in(select rtrim(ltrim(f1)) from airtelsenderid)
and rtrim(ltrim(sender_name)) like '%[a-z]%' and len(sender_name)<9 and sender_id not in
( select sender_id from senderid_detail where rtrim(ltrim(sender_name)) like '%['']%')

END





