/*          
Creation Date: 24-03-2010          
Created by vinay:-           
Objective:- This procedure is used to select record from messagedeliverystatus and          
dnddirector and export into excel file.          
*/          
CREATE   PROC [dbo].[USP_EXPORTINTOEXCELFILE] --2,'',1,15         
@TABLENAME VARCHAR(10),          
@DATE VARCHAR(20)='',          
@INDEXFROM INT,          
@INDEXTO INT          
AS          
BEGIN          
  IF @TABLENAME='1'          
    BEGIN          
     SELECT DNDMobileNo FROM dbo.DndDirectory WHERE DNDID BETWEEN @INDEXFROM AND @INDEXTO          
    END          
    ELSE IF @TABLENAME='2'          
    BEGIN          
      SELECT  BlackMobileNo FROM dbo.BlacklistedNo WHERE BlackID BETWEEN @INDEXFROM AND @INDEXTO          
    END          
END  


