/* ============================================================
   Procedure: [dbo].[USP_EXPORTREPORT]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC [dbo].[USP_EXPORTREPORT] 
@USERID INT, -- From VARCHAR(30) by abhishek,
@SENDERID VARCHAR(30),
@FROMDATE VARCHAR(30),
@TODATE VARCHAR(30)
AS
BEGIN
-- IF USERID AND SENDERID NOT NULL
IF (@USERID<> '' AND @SENDERID<> '')
BEGIN
SELECT MOBILE,MESSAGE,MESSAGEINSERTDATE,ISNULL((CASE MESSAGESTATUS WHEN '3' THEN 'DND' WHEN '5' THEN 'BLACKLISTED' WHEN '6' THEN 'INVALID' ELSE MESSAGESTATUS END),'SENT') AS MESSAGESTATUS
,LASTERROR FROM SixDaysHistory WITH(NOLOCK)
WHERE SENDERID=@SENDERID AND U_ID=@USERID AND CONVERT(NVARCHAR,MESSAGEINSERTDATE,103) BETWEEN @FROMDATE AND @TODATE
END 
IF (@USERID <> '' AND @SENDERID = '')
BEGIN
SELECT MOBILE,MESSAGE,MESSAGEINSERTDATE,ISNULL((CASE MESSAGESTATUS WHEN '3' THEN 'DND' WHEN '5' THEN 'BLACKLISTED' WHEN '6' THEN 'INVALID' ELSE MESSAGESTATUS END),'SENT') AS MESSAGESTATUS
,LASTERROR FROM SixDaysHistory WITH(NOLOCK)
WHERE  U_ID=@USERID AND CONVERT(NVARCHAR,MESSAGEINSERTDATE,103) BETWEEN @FROMDATE AND @TODATE
END
IF (@SENDERID <> '' AND @USERID = '')
BEGIN
SELECT MOBILE,MESSAGE,MESSAGEINSERTDATE,ISNULL((CASE MESSAGESTATUS WHEN '3' THEN 'DND' WHEN '5' THEN 'BLACKLISTED' WHEN '6' THEN 'INVALID' ELSE MESSAGESTATUS END),'SENT') AS MESSAGESTATUS
,LASTERROR FROM SixDaysHistory WITH(NOLOCK)
WHERE SENDERID=@SENDERID AND CONVERT(NVARCHAR,MESSAGEINSERTDATE,103) BETWEEN @FROMDATE AND @TODATE
END
END



GO

/* ============================================================
   Procedure: [dbo].[usp_exportWidget_FollowUpListByUserId]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_exportWidget_FollowUpListByUserId] (
	@UserId BIGINT = 0,
	@FollowUpType nvarchar(max) = '0',
	@NextStatusFromDate DATETIME = NULL,
	@NextStatusToDate DATETIME = NULL,
	@CreatedFromDate DATETIME = NULL,
	@CreatedToDate DATETIME = NULL,
	@LeadId BIGINT = NULL,
	@Remarks NVARCHAR(500) = '',
	@Overdue BIT = 1,
	@DueToday BIT = 1,
	@Scheduled BIT = 1,
	@NoFollowUp BIT = 1,
	@AssignedTo BIGINT = 0,
	@CreatedBy BIGINT = 0,
	@IsReAssign BIT = NULL,
	@csvColumnList nvarchar(max) = ''
)
AS
BEGIN

	--declare	
	--	@UserId BIGINT = 31031,
	--	@FollowUpType nvarchar(max) = '0',        
	--	@NextStatusFromDate DATETIME = '',
	--	@NextStatusToDate DATETIME = '',
	--	@CreatedFromDate DATETIME = '',
	--	@CreatedToDate DATETIME = '',
	--	@LeadId BIGINT = '0',
	--	@Remarks NVARCHAR(500) = '',
	--	@Overdue BIT = 1,
	--	@DueToday BIT = 1,
	--	@Scheduled BIT = 1,
	--	@NoFollowUp BIT = 1,
	--	@AssignedTo BIGINT = 0,
	--	@CreatedBy BIGINT = 0,
	--	@IsReAssign BIT = 0,
	--	@csvColumnList nvarchar(max) = N'Lead.AmountPaid,Lead.LeadNo,Lead.MobileNo,Lead.MobileNo1,Lead.MobileNo2,Lead.PersonName'
	

	--select @UserId=50126,@csvColumnList=N'Lead.AmountPaid,Lead.LeadNo,Lead.MobileNo,Lead.MobileNo1,Lead.MobileNo2,Lead.PersonName',@FollowUpType=N'',@AssignedTo=N'',@CreatedBy=N'',@NextStatusFromDate=N'',@NextStatusToDate=N'',@CreatedFromDate=N'',@CreatedToDate=N'',@LeadId=N'',@Remarks=N'',@Overdue=1,@DueToday=1,@Scheduled=1,@NoFollowUp=1,@IsReAssign=N''


	set @csvColumnList = replace(replace(replace(
							@csvColumnList, 'Lead.Remarks', 'Lead.LeadRemarks'),
							'Lead.NextStatusDate', 'Lead.LeadNextStatusDate'),
							'Lead.CreatedOn', 'Lead.LeadCreatedOn')

	if(@NextStatusFromDate = '') begin set @NextStatusFromDate = null end
	if(@NextStatusToDate = '') begin set @NextStatusToDate = null end
	if(@CreatedFromDate = '') begin set @CreatedFromDate = null end
	if(@CreatedToDate = '') begin set @CreatedToDate = null end

	DECLARE @IsCallback INT = 0;
	DECLARE @IsConvert INT = 0;
	DECLARE @FollowUpName VARCHAR = '';

	
	/*
		SELECT @IsCallback = IsCallback
			,@IsConvert = IsConvert
		FROM FollowUp_Status(NOLOCK)
		WHERE Id = @FollowUpType
	*/

	Declare @flpIDsCount int = 0;
	set @flpIDsCount = isnull((select count(value) from fn_Split(@FollowUpType,',') where isnull(value,0) <> 0),0);

	DECLARE @ParentId BIGINT = 0
		,@IsAdmin BIT = 0
	DECLARE @tbluser TABLE (
		User_ID BIGINT
		,Name VARCHAR(100)
		,IMAGE VARCHAR(100)
		)

	SELECT @IsAdmin = IsAdmin, @ParentId = ParentID FROM User_Detail(NOLOCK) WHERE User_ID = @UserId

	DECLARE @TeamCode VARCHAR(10) = ''
	DECLARE @ScopeCode VARCHAR(10) = ''
	DECLARE @UserIdTeamLst VARCHAR(Max) = ''
	DECLARE @UserLoginTeamLst VARCHAR(Max) = ''

	INSERT INTO @tbluser EXEC Use_GetUserDetails @UserId

	SELECT @UserIdTeamLst = isnull(STRING_AGG(User_ID, ','), '') FROM @tbluser

	DECLARE @maxScore NUMERIC(18, 2) = isnull(( SELECT (max(currentscore) * 100) / 99 
		FROM lead_score_history(NOLOCK) e WHERE parentid = @ParentId ), 0)
	DECLARE @hot INT, @warm INT, @cold INT

	SELECT @hot = hot, @warm = warm, @cold = cold FROM lead_cateogy_thresholds(NOLOCK) WHERE parentid = @ParentID

	IF @hot IS NULL
	BEGIN
		SELECT @hot = hot, @warm = warm, @cold = cold FROM lead_cateogy_thresholds(NOLOCK) WHERE parentid = 0
	END

	PRINT @FollowUpType

	declare @Pivot_Column nvarchar(max), @PivotColumnCast nvarchar(max), @alterTableSql nvarchar(max) = ''
	select @Pivot_Column = coalesce(@Pivot_Column + ',', '') + quotename([fieldname]),
		@PivotColumnCast = concat( coalesce(@PivotColumnCast + ',', ''), 'TRY_CONVERT(',
		case datatype when 'd' then 'date' when 'f' then 'float' when 'v' then 'text' when 'r' then 'text' when 'm' then 'text' when 's' then 'text' when 'c' then 'text' when 'e' then 'text' when 'l' then 'text' end, ', ', quotename([fieldname]), ')'),
		@alterTableSql = concat(@alterTableSql, iif(len(@alterTableSql) = 0, 'add', ''), iif(len(@alterTableSql) > 0, ',', ''),
			' ', quotename([fieldname]),  ' ', ( case datatype when 'd' then 'date' when 'f' then 'float' when 'v' then 'text' when 'r' then 'text' when 'm' then 'text' when 's' then 'text' when 'c' then 'text' when 'e' then 'text' when 'l' then 'text' end ))
	from (select distinct [fieldname], [datatype] from customfields(nolock) where [ParentID] = @ParentId AND [isActive] = 1 ) AS Tab;

	drop table if exists #tempCustomField
	create table #tempCustomField( LeadID bigint )
	set @alterTableSql = concat('alter table ', '#tempCustomField ', @alterTableSql)

	print @alterTableSql

	execute sp_executesql @alterTableSql -- creating dynamic table for customfield


	declare @pvtQueryStr nvarchar(max) =  concat(N'insert into #tempCustomField ( LeadID, ', @Pivot_Column , ' )
select LeadID, ', @PivotColumnCast ,' from (select [x].LeadID, [y].[fieldname], cast([x].[fieldvalue] as nvarchar) as [fieldvalue] from customfieldLeadvalue(nolock) x inner join customfields(nolock) y ON x.fieldID=y.field_ID AND y.[ParentID] = ', @ParentId, '
AND y.[isActive] = 1 ) T1 PIVOT ( max(fieldvalue) FOR [fieldname] IN (', @Pivot_Column , N')) AS Tab2')

	print @pvtQueryStr
	execute sp_executesql @pvtQueryStr


	declare @followupSql1 nvarchar(max), @followupSql2 nvarchar(max), @followupSql3 nvarchar(max), @followupSqlFinal nvarchar(max)
	set @followupSql1 = concat(N'select * from ( select ',
		N'fs.followupstatus AS Title, lih.remarks AS Discription, ',
		N'( CASE ',
			N'WHEN cast(lih.followupdate AS DATE) = cast(getdate() AS DATE) THEN 0 ',
			N'WHEN cast(lih.followupdate AS DATE) < cast(getdate() AS DATE) THEN 1 ',
			N'WHEN cast(lih.followupdate AS DATE) > cast(getdate() AS DATE)THEN 2 ',
			N'WHEN cast(lih.followupdate AS DATE) IS NULL THEN 3 ',
		N'END ) AS [OrderSeq], ',
		N'lih.followupdate AS NextStatusDate, lih.CreatedOn,( CASE ', 
		N'WHEN cast(lih.followupdate AS DATE) = cast(getdate() AS DATE) THEN ''duetoday'' ',
		N'WHEN cast(lih.followupdate AS DATE) < cast(getdate() AS DATE) THEN ''overdue'' ',
		N'WHEN cast(lih.followupdate AS DATE) > cast(getdate() AS DATE) THEN ''scheduled'' ',
		N'WHEN cast(lih.followupdate AS DATE) IS NULL  THEN ''nofollowup'' ',
		N'END ) AS [FollowupDateStatus] ',
		iif( len(@csvColumnList) > 0 , concat(', ', @csvColumnList), ''),
		N' FROM leadinteractionhistory(NOLOCK) lih ')
	set @followupSql2 = concat(	N'INNER JOIN followup_status(NOLOCK) fs ON lih.followupstatus = fs.id ',
		N'INNER JOIN ( select * from eV_UserLeads(NOLOCK) UL left join #tempCustomField CF ON UL.ID = CF.LeadID  ',
			N'where ul.parentId = ', @ParentId, ' ) as [lead] on  lih.leadno = lead.leadno and lih.parentid = lead.parentid ',
		N'LEFT JOIN lead_score_history_latest(NOLOCK) ls ON ls.leadid = lead.id ',
		N'LEFT JOIN user_detail(NOLOCK) ud ON lih.assignedto = ud.user_id ')

	set @followupSql3 = concat(N'WHERE lih.IsReassign = CASE ',
			N'WHEN ''', isnull(@IsReAssign,'' ), ''' = '''' AND ', isnull(@CreatedBy, 0), ' <> 0 THEN 0 ',
			N'WHEN ''', isnull(@IsReAssign,'' ), ''' <> ''''  THEN ', isnull(@IsReAssign, 0), ' ELSE lih.IsReassign END ',
				N'AND lih.id = CASE ',
			N'WHEN isnull(''', @CreatedFromDate, ''', ''1900-01-01'') > ''1900-01-01'' THEN lih.id ',
				N'ELSE ( SELECT max(id) FROM leadinteractionhistory(NOLOCK) ',
					N'WHERE parentid = lih.parentid AND leadno = lih.leadno ) END ',
			N'AND lead.parentid = ', @ParentId, N' ',
			N'AND 1 = ( CASE ',
				N'WHEN ', isnull(@flpIDsCount, 0), ' = 0 AND ', isnull(@flpIDsCount, 0), ' = 1 AND ', 
					isnull(@Scheduled, 0), ' = 1 AND ', isnull(@DueToday, 0), ' = 1 AND ', isnull(@Overdue, 0), ' = 1 THEN 1 ',
				N'WHEN ', isnull(@flpIDsCount, 0), ' = 0 AND fs.IsCallback = 1 THEN 1 ',
				N'WHEN ', isnull(@flpIDsCount, 0), ' > 0 AND lih.FollowUpStatus in ( select value from fn_Split(''', 
					@FollowUpType,''', '','') ) THEN 1 ',
				N'ELSE 0 END ) ',
			N'AND 1 = ( CASE WHEN ', @isadmin, ' = 1 THEN 1 WHEN isnull(lead.AssignedTo, 0) ',
					N'IN ( SELECT [value] FROM dbo.fn_Split(''', @UserIdTeamLst, ''', '','')) THEN 1 ',
					N'WHEN isnull(lead.AssignedTo, 0) = ', @UserId, N'THEN 1 ELSE 0 END ) ',
			N'AND 1 = ( CASE ',
					N'WHEN isnull(', @AssignedTo, ', 0) = 0  THEN 1 ',
					N'WHEN isnull(', @AssignedTo, ', 0) > 0 ',
						N'AND lih.AssignedTo = ', @AssignedTo, ' THEN 1 ',
					N'ELSE 0 END ) ',
			N'AND 1 = ( CASE ',
					N'WHEN isnull(', @CreatedBy, ', 0) = 0 THEN 1 ',
					N'WHEN isnull(', @CreatedBy, ', 0) > 0 AND lih.CreatedBy = ', @CreatedBy, ' THEN 1 ',
					N'ELSE 0 END ) ',
			N'AND 1 = iif(Isnull(''', @NextStatusFromDate, ''', '''') <> '''' ',
				N'AND Isnull(''', @NextStatusFromDate, ''', '''') <> '''', ',
				N'iif(CAST(TRY_CONVERT(DATETIME, lih.FollowupDate) AS DATE) ',
					N'BETWEEN cast(''', @NextStatusFromDate, ''' AS DATE) ',
							N'AND cast(''', @NextStatusFromDate, ''' AS DATE), 1, 0), 1) ',
			N'AND 1 = iif(Isnull(''', @CreatedFromDate, ''', '''') <> '''' ',
				N'AND Isnull(''', @CreatedToDate, ''', '''') <> '''', iif(CAST(TRY_CONVERT(DATETIME, lih.CreatedOn) AS DATE) ',
					N'BETWEEN cast(''', @CreatedToDate, ''' AS DATE) AND cast(''', @CreatedToDate, ''' AS DATE) ,1 ,0), 1) ',
			N'AND 1 = ( CASE ',
					N'WHEN isnull(', isnull(@LeadId, 0), ', 0) = 0 THEN 1 ',
					N'WHEN isnull(', isnull(@LeadId, 0), ', 0) > 0 AND ', isnull(@LeadId, 0), ' = lead.ID THEN 1 ',
					N'WHEN isnull(', isnull(@LeadId, 0), ', 0) = 0 THEN 1 ',
					N'WHEN isnull(', isnull(@LeadId, 0), ', 0) > 0 AND ', isnull(@LeadId, 0), ' = lead.ID THEN 1 ',
					N'ELSE 0 END ) ',
			N'AND 1 = ( CASE ', 
					N'WHEN isnull(''', @Remarks, ''', '''') = '''' THEN 1 ',
					N'WHEN isnull(''', @Remarks, ''', '''') <> '''' AND lih.Remarks LIKE ''%',@Remarks, '%'' THEN 1 ',
						N'ELSE 0 END ) ',
			N'AND 1 = ( CASE ', 
					N'WHEN ', isnull(@flpIDsCount, 0), ' > 0 AND fs.IsConvert = 1 THEN 1 ',
					N'WHEN Isnull(''', @NextStatusFromDate, ''', '''') = '''' AND Isnull(''', 
						@NextStatusToDate, ''', '''') = '''' ',
						N'AND fs.IsConvert = 1 THEN 0 ',
					N'ELSE 1 END ) ) AS fu ',
	N'WHERE 1 = ( CASE ', 
		N'WHEN followupdatestatus = ''overdue'' AND ''', @Overdue, ''' = 1 THEN 1 ',
		N'WHEN followupdatestatus = ''duetoday'' AND ''', @DueToday, ''' = 1 THEN 1 ',
		N'WHEN followupdatestatus = ''scheduled'' AND ''', @Scheduled, ''' = 1 THEN 1 ',
		N'WHEN followupdatestatus = ''nofollowup'' AND ''', @NoFollowUp, ''' = 1 THEN 1 ',
		N'ELSE 0 END ) ',
	N'ORDER BY orderseq, cast(nextstatusdate AS DATETIME) ' )

	print @followupSql1
	print @followupSql2
	print @followupSql3

	set @followupSqlFinal = @followupSql1 + @followupSql2 + @followupSql3

	execute sp_executesql @followupSqlFinal

	
END



GO

/* ============================================================
   Procedure: [dbo].[usp_exportWidget_GetFollowUpListByUserIdWithSegment]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE usp_exportWidget_GetFollowUpListByUserIdWithSegment
(
	@UserId BIGINT = 0,
	@FollowUpType nvarchar(max) = '0',
	@NextStatusFromDate DATETIME = NULL,
	@NextStatusToDate DATETIME = NULL,
	@CreatedFromDate DATETIME = NULL,
	@CreatedToDate DATETIME = NULL,
	@LeadId BIGINT = NULL,
	@Remarks NVARCHAR(500) = '',
	@Overdue BIT = 1,
	@DueToday BIT = 1,
	@Scheduled BIT = 1,
	@NoFollowUp BIT = 1,
	@AssignedTo BIGINT = 0,
	@CreatedBy BIGINT = 0,
	@IsReAssign BIT = NULL,
	@CriteriaName nvarchar(500) = null,
	@csvColumnList nvarchar(max)  = ''
)
AS
BEGIN

	
	--declare 
	--	@UserId BIGINT = 34594,
	--	@FollowUpType nvarchar(max) = '0',
	--	@NextStatusFromDate DATETIME = '',
	--	@NextStatusToDate DATETIME = '',
	--	@CreatedFromDate DATETIME = '',
	--	@CreatedToDate DATETIME = '',
	--	@LeadId BIGINT = NULL,
	--	@Remarks NVARCHAR(500) = '',
	--	@Overdue BIT = 1,
	--	@DueToday BIT = 1,
	--	@Scheduled BIT = 1,
	--	@NoFollowUp BIT = 1,
	--	@AssignedTo BIGINT = 0,
	--	@CreatedBy BIGINT = 0,
	--	@IsReAssign BIT = null,
	--	@CriteriaName nvarchar(500) = 'All Leads',
	--	@csvColumnList nvarchar(max) = 'Lead.LeadNo,Lead.PersonName'

      if(trim(isnull(@CriteriaName,''))  = '')
	    begin
		    exec usp_exportWidget_FollowUpListByUserId
		         @UserId,@FollowUpType,@NextStatusFromDate,@NextStatusToDate 
	            ,@CreatedFromDate,@CreatedToDate,@LeadId,@Remarks 
	            ,@Overdue,@DueToday,@Scheduled,@NoFollowUp,@AssignedTo,@CreatedBy
				,@IsReAssign, @csvColumnList
		    return		   
		end
		
		if(year(@NextStatusToDate) = '1900')
		  begin
              set @NextStatusToDate = CAST('31-Dec-2123' as date)    
		  end

        if(year(@CreatedToDate) = '1900')
		  begin
              set @CreatedToDate = CAST('31-Dec-2123' as date)    
		  end


	DECLARE @IsCallback INT = 0;
	DECLARE @IsConvert INT = 0;
	DECLARE @FollowUpName VARCHAR = '';


	/*
	SELECT @IsCallback = IsCallback
		,@IsConvert = IsConvert
	FROM FollowUp_Status(NOLOCK)
	WHERE Id = @FollowUpType
	*/
	  
	Declare @flpIDsCount int = 0;
	set @flpIDsCount = isnull((select count(value) from fn_Split(@FollowUpType,',') where isnull(value,0) <> 0),0);


	DECLARE @ParentId BIGINT = 0
		,@IsAdmin BIT = 0
	DECLARE @tbluser TABLE (
		User_ID BIGINT
		,Name VARCHAR(100)
		,IMAGE VARCHAR(100)
		)

	SELECT @IsAdmin = IsAdmin
		,@ParentId = ParentID
	FROM User_Detail(NOLOCK)
	WHERE User_ID = @UserId

	-- start Segmentation handling

	 declare @SPID bigint = isnull((select @@SPID),0)
     delete from [tbl_LeadID_WithSPID] where SP_ID = @SPID  
	
	 drop table if exists  #userleadsBySegment 
    
     declare @LeadCount int =  (select count(1) from Userleads(nolock) where ParentID = @ParentID)

	  exec Usp_ViewLeadDetailsBySearchCriteria_IDSegment_SPID 1,@LeadCount,@Criterianame,@UserID ,0,'Name'
      select LeadID as ID into #userleadsBySegment from tbl_LeadID_WithSPID with(nolock) where SP_ID = @SPID
	 
	 delete from [tbl_LeadID_WithSPID] where SP_ID = @SPID
	  
     declare @QueryTotality nvarchar(max) = ''
	    
    -- end Segmentation handling

	DECLARE @TeamCode VARCHAR(10) = ''
	DECLARE @ScopeCode VARCHAR(10) = ''
	DECLARE @UserIdTeamLst VARCHAR(Max) = ''
	DECLARE @UserLoginTeamLst VARCHAR(Max) = ''

	INSERT INTO @tbluser
	EXEC Use_GetUserDetails @UserId

	SELECT @UserIdTeamLst = isnull(STRING_AGG(User_ID, ','), '')
	FROM @tbluser

	DECLARE @maxScore NUMERIC(18, 2) = isnull((
				SELECT (max(currentscore) * 100) / 99
				FROM lead_score_history(NOLOCK) e
				WHERE parentid = @ParentId
				), 0)
	DECLARE @hot INT
		,@warm INT
		,@cold INT

	SELECT @hot = hot
		,@warm = warm
		,@cold = cold
	FROM lead_cateogy_thresholds(NOLOCK)
	WHERE parentid = @ParentID

	IF @hot IS NULL
	BEGIN
		SELECT @hot = hot
			,@warm = warm
			,@cold = cold
		FROM lead_cateogy_thresholds(NOLOCK)
		WHERE parentid = 0
	END

	PRINT @FollowUpType

	declare @Pivot_Column nvarchar(max), @PivotColumnCast nvarchar(max), @alterTableSql nvarchar(max) = ''
	select @Pivot_Column = coalesce(@Pivot_Column + ',', '') + quotename([fieldname]),
		@PivotColumnCast = concat( coalesce(@PivotColumnCast + ',', ''), 'TRY_CONVERT(',
		case datatype when 'd' then 'date' when 'f' then 'double' when 'v' then 'text' when 'r' then 'text' when 'm' then 'text' when 's' then 'text' when 'c' then 'text' when 'e' then 'text' when 'l' then 'text' end, ', ', quotename([fieldname]), ')'),
		@alterTableSql = concat(@alterTableSql, iif(len(@alterTableSql) = 0, 'add', ''), iif(len(@alterTableSql) > 0, ',', ''),
			' ', fieldname,  ' ', ( case datatype when 'd' then 'date' when 'f' then 'double' when 'v' then 'text' when 'r' then 'text' when 'm' then 'text' when 's' then 'text' when 'c' then 'text' when 'e' then 'text' when 'l' then 'text' end ))
	from (select distinct [fieldname], [datatype] from customfields(nolock) where [ParentID] = @ParentId AND [isActive] = 1 ) AS Tab;

	drop table if exists #tempCustomField
	create table #tempCustomField( LeadID bigint )
	set @alterTableSql = concat('alter table ', '#tempCustomField ', @alterTableSql)
	execute sp_executesql @alterTableSql -- creating dynamic table for customfield

	declare @pvtQueryStr nvarchar(max) =  concat(N'insert into #tempCustomField ( LeadID, ', @Pivot_Column , ' )
select LeadID, ', @PivotColumnCast ,' from (select [x].LeadID, [y].[fieldname], cast([x].[fieldvalue] as nvarchar) as [fieldvalue] from customfieldLeadvalue(nolock) x inner join customfields(nolock) y ON x.fieldID=y.field_ID AND y.[ParentID] = ', @ParentId, '
AND y.[isActive] = 1 ) T1 PIVOT ( max(fieldvalue) FOR [fieldname] IN (', @Pivot_Column , N')) AS Tab2')

	print @pvtQueryStr
	execute sp_executesql @pvtQueryStr

	declare @followupSql nvarchar(max) = concat(N'select * from ( select ',
		N'fs.followupstatus AS Title, lih.remarks AS Discription, ',
		N'( CASE ',
			N'WHEN cast(lih.followupdate AS DATE) = cast(getdate() AS DATE) THEN 0 ',
			N'WHEN cast(lih.followupdate AS DATE) < cast(getdate() AS DATE) THEN 1 ',
			N'WHEN cast(lih.followupdate AS DATE) > cast(getdate() AS DATE)THEN 2 ',
			N'WHEN cast(lih.followupdate AS DATE) IS NULL THEN 3 ',
		N'END ) AS [OrderSeq], ',
		N'lih.followupdate AS NextStatusDate, lih.CreatedOn,( CASE ', 
		N'WHEN cast(lih.followupdate AS DATE) = cast(getdate() AS DATE) THEN ''duetoday'' ',
		N'WHEN cast(lih.followupdate AS DATE) < cast(getdate() AS DATE) THEN ''overdue'' ',
		N'WHEN cast(lih.followupdate AS DATE) > cast(getdate() AS DATE) THEN ''scheduled'' ',
		N'WHEN cast(lih.followupdate AS DATE) IS NULL  THEN ''nofollowup'' ',
		N'END ) AS [FollowupDateStatus] ',
		iif( len(@csvColumnList) > 0 , concat(', ', @csvColumnList), ''),
		N' FROM leadinteractionhistory(NOLOCK) lih ',
		N'INNER JOIN followup_status(NOLOCK) fs ON lih.followupstatus = fs.id ',
		N'INNER JOIN ( select * from eV_UserLeads(NOLOCK) UL  left join #tempCustomField CF ON UL.ID = CF.LeadID  ',
			N'where ul.parentId = ', @ParentId, ' ) as [lead] on  lih.leadno = lead.leadno and lih.parentid = lead.parentid ',
		N'inner join #userleadsBySegment as uls on lead.ID = uls.ID ',     
		N'LEFT JOIN lead_score_history_latest(NOLOCK) ls ON ls.leadid = lead.id ',
		N'LEFT JOIN user_detail(NOLOCK) ud ON lih.assignedto = ud.user_id ',
		N'WHERE lih.IsReassign = CASE ',
			N'WHEN ''', isnull(@IsReAssign,'' ), ''' = '''' AND ', isnull(@CreatedBy, 0), ' <> 0 THEN 0 ',
			N'WHEN ''', isnull(@IsReAssign,'' ), ''' <> ''''  THEN ', isnull(@IsReAssign, 0), ' ELSE lih.IsReassign END ',
				N'AND lih.id = CASE ',
			N'WHEN isnull(''', @CreatedFromDate, ''', ''1900-01-01'') > ''1900-01-01'' THEN lih.id ',
				N'ELSE ( SELECT max(id) FROM leadinteractionhistory(NOLOCK) ',
					N'WHERE parentid = lih.parentid AND leadno = lih.leadno ) END ',
			N'AND lead.parentid = ', @ParentId, N' ',
			N'AND 1 = ( CASE ',
				N'WHEN ', isnull(@flpIDsCount, 0), ' = 0 AND ', isnull(@flpIDsCount, 0), ' = 1 AND ', 
					isnull(@Scheduled, 0), ' = 1 AND ', isnull(@DueToday, 0), ' = 1 AND ', isnull(@Overdue, 0), ' = 1 THEN 1 ',
				N'WHEN ', isnull(@flpIDsCount, 0), ' = 0 AND fs.IsCallback = 1 THEN 1 ',
				N'WHEN ', isnull(@flpIDsCount, 0), ' > 0 AND lih.FollowUpStatus in ( select value from fn_Split(''', 
					@FollowUpType,''', '','') ) THEN 1 ',
				N'ELSE 0 END ) ',
			N'AND 1 = ( CASE WHEN ', @isadmin, ' = 1 THEN 1 WHEN isnull(lead.AssignedTo, 0) ',
					N'IN ( SELECT [value] FROM dbo.fn_Split(''', @UserIdTeamLst, ''', '','')) THEN 1 ',
					N'WHEN isnull(lead.AssignedTo, 0) = ', @UserId, N'THEN 1 ELSE 0 END ) ',
			N'AND 1 = ( CASE ',
					N'WHEN isnull(', @AssignedTo, ', 0) = 0  THEN 1 ',
					N'WHEN isnull(', @AssignedTo, ', 0) > 0 ',
						N'AND lih.AssignedTo = ', @AssignedTo, ' THEN 1 ',
					N'ELSE 0 END ) ',
			N'AND 1 = ( CASE ',
					N'WHEN isnull(', @CreatedBy, ', 0) = 0 THEN 1 ',
					N'WHEN isnull(', @CreatedBy, ', 0) > 0 AND lih.CreatedBy = ', @CreatedBy, ' THEN 1 ',
					N'ELSE 0 END ) ',
			N'AND 1 = iif(Isnull(''', @NextStatusFromDate, ''', '''') <> '''' ',
				N'AND Isnull(''', @NextStatusFromDate, ''', '''') <> '''', ',
				N'iif(CAST(TRY_CONVERT(DATETIME, lih.FollowupDate) AS DATE) ',
					N'BETWEEN cast(''', @NextStatusFromDate, ''' AS DATE) ',
							N'AND cast(''', @NextStatusFromDate, ''' AS DATE), 1, 0), 1) ',
			N'AND 1 = iif(Isnull(''', @CreatedFromDate, ''', '''') <> '''' ',
				N'AND Isnull(''', @CreatedToDate, ''', '''') <> '''', iif(CAST(TRY_CONVERT(DATETIME, lih.CreatedOn) AS DATE) ',
					N'BETWEEN cast(''', @CreatedToDate, ''' AS DATE) AND cast(''', @CreatedToDate, ''' AS DATE) ,1 ,0), 1) ',
			N'AND 1 = ( CASE ',
					N'WHEN isnull(', isnull(@LeadId, 0), ', 0) = 0 THEN 1 ',
					N'WHEN isnull(', isnull(@LeadId, 0), ', 0) > 0 AND ', isnull(@LeadId, 0), ' = lead.ID THEN 1 ',
					N'WHEN isnull(', isnull(@LeadId, 0), ', 0) = 0 THEN 1 ',
					N'WHEN isnull(', isnull(@LeadId, 0), ', 0) > 0 AND ', isnull(@LeadId, 0), ' = lead.ID THEN 1 ',
					N'ELSE 0 END ) ',
			N'AND 1 = ( CASE ', 
					N'WHEN isnull(''', @Remarks, ''', '''') = '''' THEN 1 ',
					N'WHEN isnull(''', @Remarks, ''', '''') <> '''' AND lih.Remarks LIKE ''%',@Remarks, '%'' THEN 1 ',
						N'ELSE 0 END ) ',
			N'AND 1 = ( CASE ', 
					N'WHEN ', isnull(@flpIDsCount, 0), ' > 0 AND fs.IsConvert = 1 THEN 1 ',
					N'WHEN Isnull(''', @NextStatusFromDate, ''', '''') = '''' AND Isnull(''', 
						@NextStatusToDate, ''', '''') = '''' ',
						N'AND fs.IsConvert = 1 THEN 0 ',
					N'ELSE 1 END ) ) AS fu ',
	N'WHERE 1 = ( CASE ', 
		N'WHEN followupdatestatus = ''overdue'' AND ''', @Overdue, ''' = 1 THEN 1 ',
		N'WHEN followupdatestatus = ''duetoday'' AND ''', @DueToday, ''' = 1 THEN 1 ',
		N'WHEN followupdatestatus = ''scheduled'' AND ''', @Scheduled, ''' = 1 THEN 1 ',
		N'WHEN followupdatestatus = ''nofollowup'' AND ''', @NoFollowUp, ''' = 1 THEN 1 ',
		N'ELSE 0 END ) ',
	N'ORDER BY orderseq, cast(nextstatusdate AS DATETIME) ' )

	print @followupSql

	execute sp_executesql @followupSql

	
		  
		
	EXEC MySmsAudit.dbo.Usp_AuditTableDataByParentId @User_id = @UserId
		,@Activity_type = 'View_flwup_exp'
		,@ActionType = 'S'
		,@RowJson = ''
		,@Table_name = 'leadinteractionhistory'

    drop table if exists  #userleadsBySegment   

END



