/* ============================================================
   Procedure: [dbo].[usp_exportWidget_GetPhysicalAppointmentHistoryListByUserIdWithSegment]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE [dbo].[usp_exportWidget_GetPhysicalAppointmentHistoryListByUserIdWithSegment]
  @FilterText nvarchar(500),
  @UserId bigint,
  @Mode nvarchar(20),
  @CriteriaName nvarchar(500) = '',
  @csvColumnList nvarchar(max) = ''
as  
begin
 
 declare 	@AType nvarchar(25) = '',	@OffsetValue int =0,	@PagingSize int =200,@uiId bigint = 0,	@FromDate date = null,	@EndDate date = null

	 --declare 
		--@OffsetValue int =0,
		--@PagingSize int =200,
		--@FilterText nvarchar(max) = '',
		--@UserId BIGINT = 34594,

		--@AType nvarchar(25) = 'missed',
		--@uiId bigint = 34594,
		--@FromDate date = '2023-01-01',
		--@EndDate date = '2023-05-20'

	if(isnull(@AType, '') <> '' and isnull(@AType, '') <> ''  and isnull(@AType, '') <> '' and isnull(@AType, '') <> '' )
	begin
		set @FilterText = concat(N' and 1 = ( case ',
		N' when ''', @AType, ''' = ''Visit'' and isnull(geci.GeoEntityCheckId, '''') <> '''' and A.AssignedTo = ', @uiId, '  THEN 1 ',
		N' when ''', @AType, ''' = ''Assigned'' and A.AssignedTo = ', @uiId, ' THEN 1 ',
		N' when ''', @AType, ''' = ''Missed'' and A.StartDate < GETDATE() and isnull(geci.GeoEntityCheckId, '''') = '''' and A.AssignedTo = ', @uiId, ' THEN 1 ',
		N' when ''', @AType, ''' = ''Pending'' and A.StartDate > GETDATE() and isnull(geci.GeoEntityCheckId, '''') = '''' and A.AssignedTo = ', @uiId, ' THEN 1',
		N' else 0 end ) and StartDate >= cast(''', @FromDate, ''' as date) and EndDate <= cast(''', @EndDate, ''' as date) ')
	end


	 DECLARE @ParentId BIGINT = 0, @iUserId bigint = @UserId
	 SELECT @ParentId = ParentID FROM User_Detail(nolock) WHERE User_ID = @UserId;                    
	 DECLARE @RoleType varchar(10);    


	 Declare @TeamCode varchar(10) = ''  
	 Declare @ScopeCode varchar(10) = ''   
	 Declare @UserIdTeamLst varchar(Max) = ''   
	 Declare @UserLoginTeamLst varchar(Max) = ''   

	  drop table if exists #tbluser
	 create table #tbluser (User_ID bigint,Name varchar(100), Image varchar(100),ParentID bigint)  
	 declare @IsAdmin bit = 0  
	 select @IsAdmin = IsAdmin from User_Detail(nolock) where User_ID = @UserId  
	 if(@IsAdmin = 1)  
	 begin  
	  set @UserId = 0;  
	  --insert into @tbluser  
	  insert into #tbluser  
	  exec usp_GetUserDetailWithParent @ParentId  
	 end  
	 else  
	 Begin  
	  --insert into @tbluser  
	  insert into #tbluser  
	  exec usp_GetUserDetailWithParent @UserId  
	 End  
  
	select @UserIdTeamLst = isnull(STRING_AGG(User_ID,','),'') From #tbluser  

	declare @FinalSql nvarchar(max), @ScriptPrefix nvarchar(max), @FirstSql nvarchar(max), @SecondSql nvarchar(max),
		@ThirdSql nvarchar(max), @FouthSql nvarchar(max), @ScriptSufix nvarchar(max), @StartPoint int, @Endpoint int

	set @StartPoint = @OffsetValue + 1;
	set @Endpoint = (@StartPoint + @PagingSize) - 1
	declare @Pivot_Column nvarchar(max), @PivotColumnCast nvarchar(max), @alterTableSql nvarchar(max) = ''
	select @Pivot_Column = coalesce(@Pivot_Column + ',', '') + quotename([fieldname]),
		@PivotColumnCast = concat( coalesce(@PivotColumnCast + ',', ''), 'TRY_CONVERT(',
		case datatype when 'd' then 'date' when 'f' then 'float' when 'v' then 'text' when 'r' then 'text' when 'm' then 'text' when 's' then 'text' when 'c' then 'text' when 'e' then 'text' when 'l' then 'text' end, ', ', quotename([fieldname]), ')'),
		@alterTableSql = concat(@alterTableSql, iif(len(@alterTableSql) = 0, 'add', ''), iif(len(@alterTableSql) > 0, ',', ''),
			' ', fieldname,  ' ', ( case datatype when 'd' then 'date' when 'f' then 'float' when 'v' then 'text' when 'r' then 'text' when 'm' then 'text' when 's' then 'text' when 'c' then 'text' when 'e' then 'text' when 'l' then 'text' end ))
	from (select distinct [fieldname], [datatype] from customfields(nolock) where [ParentID] = @ParentId AND [isActive] = 1 ) AS Tab;

	drop table if exists #tempCustomField
	create table #tempCustomField( LeadID bigint )
	set @alterTableSql = concat('alter table ', '#tempCustomField ', @alterTableSql)
	execute sp_executesql @alterTableSql -- creating dynamic table for customfield



declare @pvtQueryStr nvarchar(max) =  concat(N'insert into #tempCustomField ( LeadID, ', @Pivot_Column , ' )
select LeadID, ', @PivotColumnCast ,' from (select [x].LeadID, [y].[fieldname], cast([x].[fieldvalue] as nvarchar) as [fieldvalue] from customfieldLeadvalue(nolock) x inner join customfields(nolock) y ON x.fieldID=y.field_ID AND y.[ParentID] = ', @ParentId, '
AND y.[isActive] = 1 ) T1 PIVOT ( max(fieldvalue) FOR [fieldname] IN (', @Pivot_Column , N')) AS Tab2')

print @pvtQueryStr

execute sp_executesql @pvtQueryStr

--select * from #tempCustomField

	set @ScriptPrefix = concat( N'SELECT  Title, Description, Address, StartDate, EndDate, STATUS,  ',
		N' AssignedTo,CreatedBy as CreatorName, CompletedOn=format(CompletedOn,''dd-MMM-yyyy HH:mm:ss''), Remarks,Collaboraters,OwnerName,OutcomeName, TaskStatus,'''' as ThresholdColor ' + iif( len(@csvColumnList) > 0 , concat(', ', @csvColumnList), '')+ '
		FROM (SELECT ',
			N'ROW_NUMBER() OVER(partition by (select null) order by A.PhysicalAppointmentId desc) AS Sno, ',
			N'COUNT(A.PhysicalAppointmentId) OVER() AS TotalRow, ',
			N'A.PhysicalAppointmentId, A.Title, A.Description, A.Address, A.StartDate, A.EndDate,A.CompletedOn,  ',
			N'A.STATUS, A.TaskStatus, A.ParentID,A.CancelMeeting, A.CompleteAddress,A.task_deletedOn,dbo.udf_mk_GetTaskCreatorName(A.AssignedTo) AS AssignedTo,dbo.udf_mk_GetTaskCreatorName(A.CreatedBy) as CreatedBy, dbo.udf_tsk_GetCollaboratersNames(A.PhysicalAppointmentId) AS [Collaboraters], dbo.udf_mk_GetTaskCreatorName(A.AssignedTo) AS [OwnerName], A.UserId, A.OutcomesId, A.IsActive, ',
			N' A.TaskTypeId, A.Remarks, A.CreatedDate, A.UpdatedDate, A.GeoEntitySiteId, ',
			N'UOM.OutcomeName, SM.GeoEntitySiteName, GE.GeoEntityName, ISNULL(GE.GeoEntityType, ''location'') as [GeoEntityType], GE.EntityId, GE.Mobile, GE.EmailId, TM.TasKName, TM.IconClass, TM.has_view as [TmhHasView], TM.has_edit as [TmhHasEdit],  ',
			N'TM.has_remove as [TmhHasRemove], TM.has_completion as [TmhHasCompletion], TM.has_comment as [TmhHasComment], ',
			N'EP.has_view as [FepHasView], EP.has_edit as [FepHasEdit], EP.has_remove as [FephHasRemove], ',
			N'EP.has_completion as [FepHasCompletion], EP.has_comment as [FepHasComment], colb.Has_viewLead, colb.Has_editLead,colb.Has_fieldviewLead, colb.Has_fieldeditLead,  ',
			N'CASE WHEN A.Assignedto=',@iuserid,' THEN ''Owner''
				When 1= (Select distinct 1 from TBL_ET_PhyAppointCollaboratorUserMapping col where Userid=',@iUserId,' and col.PhysicalAppointmentId=A.PhysicalAppointmentId) THEN ''Collab''
				When 1= (Select distinct 1 from TBL_ET_PhyAppointUserMapping upm where Userid=',@iUserId,' and upm.PhysicalAppointmentId=A.PhysicalAppointmentId) THEN ''Field''
			END UserType,PersonName,LeadNo,img_ext,CompanyName,LeadCreatedOn,CountryCode,MobileNo,Countrycode1, Countrycode2,MobileNo1,MobileNo2,EmailID1,EmailID2,eul.City,eul.State,eul.Country,eul.PinCode,ResidentialAddress,OfficeAddress,
SourceName,MediumName,CampaignName,A.UpdatedBy,InitialRemarks,FollowupStatus,FollowupDate,LeadNextStatusDate,LeadRemarks,AmountPaid,FollowupCreatedDate,eul.CreatedBy
ModifiedOn,ModifiedBy,FollowupBy,assigneduser,Products,LastFollowupCreatedOn,eul.Latitude,eul.Longitude,WhereAddress,AssignedToName,AssignedToPhone,
AssignedToEmail,CF.*
		 FROM ( ' )


	set @FirstSql  = concat( N'	SELECT TH.PhysicalAppointmentId, TH.Title, TH.Description, TH.Address, TH.StartDate, TH.EndDate, TH.STATUS, (CASE  WHEN LOWER(TH.STATUS) = ''completed'' THEN ''Completed''
					ELSE (CASE WHEN CAST(TH.EndDate AS DATE) > CAST(GETDATE() AS DATE) THEN ''Scheduled''
                    WHEN CAST(TH.EndDate AS DATE) < CAST(GETDATE() AS DATE) THEN ''Over Due''
                    ELSE ''Due Today'' END) END) AS [TaskStatus],  UD.ParentID, th.CancelMeeting,th.CompleteAddress,th.task_deletedOn,th.UpdatedBy,',
		 N' th.AssignedTo AS AssignedTo,TH.CreatedBy, UD.User_ID AS [UserId], TH.OutcomesId, TH.IsActive, TH.CompletedOn, TH.TaskTypeId, TH.Remarks, ',
		 N'TH.CreatedDate, TH.UpdatedDate, TH.GeoEntitySiteId FROM TBL_ET_PhysicalAppointment(NOLOCK) TH  ',
					N'LEFT JOIN User_Detail(NOLOCK) UD ON TH.CreatedBy = UD.User_ID  ',
			N'WHERE UD.User_Id IN( ', @UserIdTeamLst, ' ) AND TH.IsActive = 1  ' )

	set @SecondSql  = concat( N' UNION SELECT TH.PhysicalAppointmentId, TH.Title, TH.Description, TH.Address, TH.StartDate, TH.EndDate, TH.STATUS, (CASE  WHEN LOWER(TH.STATUS) = ''completed'' THEN ''Completed''
					ELSE (CASE WHEN CAST(TH.EndDate AS DATE) > CAST(GETDATE() AS DATE) THEN ''Scheduled''
                    WHEN CAST(TH.EndDate AS DATE) < CAST(GETDATE() AS DATE) THEN ''Over Due''
                    ELSE ''Due Today'' END) END) AS [TaskStatus], ',
			N'UD.ParentID, th.CancelMeeting,th.CompleteAddress,th.task_deletedOn,th.UpdatedBy, th.AssignedTo AS AssignedTo, TH.CreatedBy, UD.User_ID AS [UserId], TH.OutcomesId, TH.IsActive, TH.CompletedOn, TH.TaskTypeId, ',
			N'TH.Remarks, TH.CreatedDate, TH.UpdatedDate, TH.GeoEntitySiteId FROM TBL_ET_PhysicalAppointment(NOLOCK) TH ',
			N'LEFT JOIN User_Detail(NOLOCK) UD ON TH.CreatedBy = UD.User_ID ',
			N'WHERE UD.User_Id IN( ', @UserIdTeamLst, ' ) AND TH.IsActive = 1  ' )
	
	set @ThirdSql  = concat( N' UNION SELECT TH.PhysicalAppointmentId, TH.Title, TH.Description, TH.Address, TH.StartDate, TH.EndDate, TH.STATUS, (CASE  WHEN LOWER(TH.STATUS) = ''completed'' THEN ''Completed''
					ELSE (CASE WHEN CAST(TH.EndDate AS DATE) > CAST(GETDATE() AS DATE) THEN ''Scheduled''
                    WHEN CAST(TH.EndDate AS DATE) < CAST(GETDATE() AS DATE) THEN ''Over Due''
                    ELSE ''Due Today'' END) END) AS [TaskStatus], ',
			N'TH.ParentID, th.CancelMeeting,th.CompleteAddress,th.task_deletedOn,th.UpdatedBy, th.AssignedTo AS AssignedTo, TH.CreatedBy, TCM.UserId AS [UserId], TH.OutcomesId, TH.IsActive, TH.CompletedOn, TH.TaskTypeId, ',
			N'TH.Remarks, TH.CreatedDate, TH.UpdatedDate, TH.GeoEntitySiteId FROM TBL_ET_PhysicalAppointment(NOLOCK) TH ',
			N'LEFT JOIN TBL_ET_PhyAppointCollaboratorUserMapping(NOLOCK) TCM ON TH.PhysicalAppointmentId = TCM.PhysicalAppointmentId ',
			N'WHERE TCM.UserId IN( ', @UserIdTeamLst, ' ) AND TH.IsActive = 1  ' )

	set @FouthSql  = concat( N' UNION SELECT TH.PhysicalAppointmentId, TH.Title, TH.Description, TH.Address, TH.StartDate, TH.EndDate, TH.STATUS, (CASE  WHEN LOWER(TH.STATUS) = ''completed'' THEN ''Completed''
					ELSE (CASE WHEN CAST(TH.EndDate AS DATE) > CAST(GETDATE() AS DATE) THEN ''Scheduled''
                    WHEN CAST(TH.EndDate AS DATE) < CAST(GETDATE() AS DATE) THEN ''Over Due''
                    ELSE ''Due Today'' END) END) AS [TaskStatus], ',
			N'Th.ParentID,th.CancelMeeting,th.CompleteAddress,th.task_deletedOn,th.UpdatedBy, TH.AssignedTo, TH.CreatedBy, TCM.UserId AS [UserId], TH.OutcomesId, TH.IsActive, TH.CompletedOn, TH.TaskTypeId, ',
			N'TH.Remarks, TH.CreatedDate, TH.UpdatedDate, TH.GeoEntitySiteId FROM TBL_ET_PhysicalAppointment(NOLOCK) TH ',
			N'LEFT JOIN TBL_ET_PhyAppointUserMapping(NOLOCK) TCM ON TH.PhysicalAppointmentId = TCM.PhysicalAppointmentId ',
			N'WHERE TCM.UserId IN( ', @UserIdTeamLst, ' ) AND TH.IsActive = 1  ' )


	set @ScriptSufix = concat( N' ) A ',
		N' LEFT JOIN TBL_ET_GeoEntitySiteMaster(NOLOCK) SM ON A.GeoEntitySiteId = SM.GeoEntitySiteId ',
		N' LEFT JOIN tbl_tsk_UserOutcomeMaster(NOLOCK) UOM ON UOM.Id = A.OutcomesId ',
		N' LEFT JOIN tbl_tsk_UserTaskMaster(NOLOCK) TM ON A.TaskTypeId = TM.Id ',
		N' LEFT JOIN TBL_ET_PhyApptTypeFieldExecutivePermission(NOLOCK) EP  ON A.TaskTypeId = EP.task_type_id ',
		N' LEFT JOIN TBL_ET_GeoEntityMaster(NOLOCK) GE ON SM.GeoEntityId = GE.GeoEntityId ',
		N' LEFT JOIN TBL_ET_GeoEntityCheckInOut(nolock) geci on A.PhysicalAppointmentId = geci.PhysicalAppointmentId ',
		N'LEFT JOIN eV_UserLeads eul on eul.ParentID=A.ParentID ',
		N'left join #tempCustomField CF ON eul.ID = CF.LeadID ',
		N' Outer APPLY dbo.udf_tsk_GetCollaboratersLeadEditView1(A.PhysicalAppointmentId,',@iUserId,',' +cast(@ParentId as nvarchar(100)),') colb',
		N' WHERE A.UserId = ', @iUserId, ' ', iif(isnull(@FilterText, '') <> '', @FilterText,  ''), ' ) Entity  WHERE Entity.Sno between ', @StartPoint, ' and ', @Endpoint )


	print @ScriptPrefix
	print @FirstSql
	print @SecondSql
	print @ThirdSql
	print @FouthSql
	print @ScriptSufix

	set @FinalSql = concat( @ScriptPrefix, @FirstSql, @SecondSql, @ThirdSql, @FouthSql, @ScriptSufix )

	execute sp_executesql @FinalSql

end




GO

/* ============================================================
   Procedure: [dbo].[usp_exportWidget_GetTaskHistoryListByUserId]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_exportWidget_GetTaskHistoryListByUserId]
	@FilterText VARCHAR(500),
	@UserId BIGINT, 
	@Mode VARCHAR(20), 
	@csvColumnList nvarchar(max)
AS  
BEGIN  




--declare 
--	@FilterText VARCHAR(500) = '',
--	@UserId BIGINT = 31871,
--	@Mode VARCHAR(20) = 'A', 
--	@csvColumnList nvarchar(max) = N'Lead.AmountPaid,Lead.AssignedTo,Lead.CampaignName,Lead.City,Lead.LeadNo,Lead.PersonName'



DECLARE @ParentId BIGINT = 0,@iUserId BIGINT = @UserId  
  
 SELECT @ParentId = ParentID  
 FROM User_Detail(NOLOCK)  
 WHERE User_ID = @UserId;  
  
 DECLARE @RoleType VARCHAR(10);  
  
 DROP TABLE IF EXISTS #tbluser  

 CREATE TABLE #tbluser (  
   User_ID BIGINT  
   ,Name VARCHAR(100)  
   ,IMAGE VARCHAR(100)  
   ,ParentID BIGINT  
   )  
  
 DECLARE @IsAdmin BIT = 0  
  
 SELECT @IsAdmin = IsAdmin  
 FROM User_Detail(NOLOCK)  
 WHERE User_ID = @UserId  
  
 IF (@IsAdmin = 1)  
 BEGIN  
  SET @UserId = 0;  
  
  --insert into @tbluser          
  INSERT INTO #tbluser  
  EXEC usp_GetUserDetailWithParent @ParentId  
 END  
 ELSE  
 BEGIN  
  --insert into @tbluser          
  INSERT INTO #tbluser  
  EXEC usp_GetUserDetailWithParent @UserId  
 END  
  
 DECLARE @TeamCode VARCHAR(10) = ''  
 DECLARE @ScopeCode VARCHAR(10) = ''  
 DECLARE @UserIdTeamLst VARCHAR(Max) = ''  
 DECLARE @UserLoginTeamLst VARCHAR(Max) = ''  
  
 -- select @TeamCode = TeamCode, @ScopeCode = ScopeCode, @UserIdTeamLst = UserIdTeamLst, @UserLoginTeamLst = UserLoginTeamLst from dbo.ufn_GetUserRoleScope(@UserId)           
 --if(trim(@UserIdTeamLst) ='')          
 --begin          
 --set @UserIdTeamLst = cast(@UserId as nvarchar)          
 --end          
 --select @TeamCode TeamCode, @ScopeCode ScopeCode, @UserIdTeamLst, @UserLoginTeamLst          
 --select @UserIdTeamLst=isnull(STRING_AGG(User_ID,','),'') From @tbluser          
 SELECT @UserIdTeamLst = isnull(STRING_AGG(User_ID, ','), '')  
 FROM #tbluser  
  
 DECLARE @maxScore NUMERIC(18, 2) = isnull((  
    SELECT (max(currentscore) * 100) / 99  
    FROM lead_score_history_latest(NOLOCK) e  
    WHERE parentid = @ParentId  
    ), 0)  
 DECLARE @hot INT,@warm INT,@cold INT  
  
 SELECT @hot = hot,@warm = warm,@cold = cold  
 FROM lead_cateogy_thresholds(NOLOCK)  
 WHERE parentid = @ParentId  
  
 IF @hot IS NULL  
 BEGIN  
  SELECT @hot = hot,@warm = warm,@cold = cold  
  FROM lead_cateogy_thresholds(NOLOCK)  
  WHERE parentid = 0  
 END  

	declare @Pivot_Column nvarchar(max), @PivotColumnCast nvarchar(max), @alterTableSql nvarchar(max) = ''
	select @Pivot_Column = coalesce(@Pivot_Column + ',', '') + quotename([fieldname]),
		@PivotColumnCast = concat( coalesce(@PivotColumnCast + ',', ''), 'TRY_CONVERT(',
		case datatype when 'd' then 'date' when 'f' then 'float' when 'v' then 'text' when 'r' then 'text' when 'm' then 'text' when 's' then 'text' when 'c' then 'text' when 'e' then 'text' when 'l' then 'text' end, ', ', quotename([fieldname]), ')'),
		@alterTableSql = concat(@alterTableSql, iif(len(@alterTableSql) = 0, 'add', ''), iif(len(@alterTableSql) > 0, ',', ''),
			' ', fieldname,  ' ', ( case datatype when 'd' then 'date' when 'f' then 'float' when 'v' then 'text' when 'r' then 'text' when 'm' then 'text' when 's' then 'text' when 'c' then 'text' when 'e' then 'text' when 'l' then 'text' end ))
	from (select distinct [fieldname], [datatype] from customfields(nolock) where [ParentID] = @ParentId AND [isActive] = 1 ) AS Tab;
	drop table if exists #tempCustomField
	create table #tempCustomField( LeadID bigint )
	set @alterTableSql = concat('alter table ', '#tempCustomField ', @alterTableSql)

	print @alterTableSql 
	print concat('@alterTableSql => ', @alterTableSql )

	execute sp_executesql @alterTableSql -- creating dynamic table for customfield


declare @pvtQueryStr nvarchar(max) =  concat(N'insert into #tempCustomField ( LeadID, ', @Pivot_Column , ' )
select LeadID, ', @PivotColumnCast ,' from (select [x].LeadID, [y].[fieldname], cast([x].[fieldvalue] as nvarchar) as [fieldvalue] from customfieldLeadvalue(nolock) x inner join customfields(nolock) y ON x.fieldID=y.field_ID AND y.[ParentID] = ', @ParentId, '
AND y.[isActive] = 1 ) T1 PIVOT ( max(fieldvalue) FOR [fieldname] IN (', @Pivot_Column , N')) AS Tab2')

print @pvtQueryStr

execute sp_executesql @pvtQueryStr

  
 DECLARE @Query NVARCHAR(MAX) =   
  N'SELECT * FROM ( SELECT A.Title, A.Description, A.Address, format(A.StartDate, ''dd-MMM-yyyy HH:mm'') as [StartDate], format(A.EndDate, ''dd-MMM-yyyy HH:mm'') as [EndDate], A.STATUS, dbo.udf_mk_GetTaskCreatorName(A.CreatedBy) AS [CreatorName],dbo.udf_mk_GetTaskCreatorName(A.ParentID) AS [Parent], format(A.CompletedOn, ''dd-MMM-yyyy HH:mm'') as [CompletedOn], dbo.udf_mk_GetTotalAttachment(A.Id) AS [TotalAttachments],  A.Remarks,  format(A.CreatedOn, ''dd-MMM-yyyy HH:mm'') as [CreatedOn], format(A.UpdatedOn, ''dd-MMM-yyyy HH:mm'') as [UpdatedOn], dbo.udf_tsk_GetCollaboratersNames(A.Id) AS [Collaboraters], dbo.udf_mk_GetTaskCreatorName(A.AssignedTo) AS [OwnerName], UOM.OutcomeName, UTM.IconClass,  
(CASE WHEN LOWER(A.STATUS) = ''completed'' THEN ''Completed'' ELSE( CASE WHEN CAST(A.EndDate AS DATE) > CAST(GETDATE() AS DATE) THEN ''Scheduled'' WHEN CAST(A.EndDate AS DATE) < CAST(GETDATE() AS DATE) THEN ''Over Due'' ELSE ''Due Today'' END) END ) AS TaskStatus ' + iif( len(@csvColumnList) > 0 , concat(', ', @csvColumnList), '')+ ' FROM ( SELECT TH.LeadId, TH.Id, TH.Title, TH.Description, TH.Address, TH.StartDate, TH.EndDate, TH.STATUS, UD.ParentID, TH.AssignedTo, TH.CreatedBy, 0 AS [UserId], TH.IsTask, TH.IsAppointment, TH.OutcomesId, TH.IsActive, TH.CompletedOn, TH.TaskId, TH.Remarks, TH.CreatedOn, TH.UpdatedOn FROM tbl_tsk_TaskHistory(NOLOCK) TH INNER JOIN UserLeads(NOLOCK) UL ON TH.LeadId = UL.ID AND th.taskid <> 4 LEFT JOIN User_Detail(NOLOCK) UD ON TH.CreatedBy = UD.User_ID OR UL.ParentID = UD.User_ID WHERE UD.User_Id ' + CASE WHEN (@ParentId > 0  AND @UserId = 0) THEN ' in (' + isnull(@UserIdTeamLst, '') + ')' ELSE ' = ' + CAST(@UserId AS NVARCHAR(MAX)) END + ' AND IsActive = 1 AND TH.IsAppointment = CASE WHEN ''' + @Mode + N''' = ''A'' THEN 1 ELSE TH.IsAppointment END AND TH.IsTask = CASE WHEN ''' + @Mode + N''' = ''T'' THEN 1 ELSE TH.IsTask END          
    UNION'  
 DECLARE @Query1 NVARCHAR(max) = N' SELECT TH.LeadId, TH.Id, TH.Title, TH.Description, TH.Address, TH.StartDate, TH.EndDate, TH.STATUS, UD.ParentID, TH.AssignedTo, TH.CreatedBy,0 AS [UserId], TH.IsTask, TH.IsAppointment, TH.OutcomesId, TH.IsActive, TH.CompletedOn, TH.TaskId, TH.Remarks, TH.CreatedOn, TH.UpdatedOn FROM tbl_tsk_TaskHistory(NOLOCK) TH LEFT JOIN User_Detail(NOLOCK) UD ON TH.AssignedTo = UD.User_ID LEFT JOIN tbl_tsk_UserTaskMaster(NOLOCK) UTM ON TH.TaskId = UTM.Id WHERE UD.User_Id ' + CASE WHEN (@ParentId > 0 AND @UserId = 0) THEN ' in (' + isnull(@UserIdTeamLst, '') + ')' ELSE ' = ' + CAST(@UserId AS NVARCHAR(MAX)) END + ' AND IsActive = 1 AND TH.IsAppointment = CASE WHEN ''' + @Mode + N''' = ''A'' THEN 1 ELSE TH.IsAppointment END AND TH.IsTask = CASE WHEN ''' + @Mode + N''' = ''T'' THEN 1 ELSE TH.IsTask END
   UNION 
   SELECT TH.LeadId, TH.Id, TH.Title,  TH.Description, TH.Address, TH.StartDate, TH.EndDate, TH.STATUS, UD.ParentID, TH.AssignedTo, TH.CreatedBy, 0 AS [UserId], TH.IsTask,  TH.IsAppointment,TH.OutcomesId, TH.IsActive, TH.CompletedOn, TH.TaskId, TH.Remarks, TH.CreatedOn, TH.UpdatedOn FROM tbl_tsk_TaskHistory(NOLOCK) TH JOIN User_Detail(NOLOCK) UD ON TH.CreatedBy = UD.User_ID AND th.taskid <> 4  LEFT JOIN tbl_tsk_CollaborationUserMapping(NOLOCK) TCM ON TH.Id = TCM.TaskHistoryId WHERE TCM.User_Id ' + CASE WHEN (@ParentId > 0 AND @UserId = 0)  
    THEN ' in (' + isnull(@UserIdTeamLst, '') + ')'  
   ELSE ' = ' + CAST(@UserId AS NVARCHAR(MAX))  
   END + ' AND IsActive = 1 AND TH.IsAppointment = CASE WHEN ''' + @Mode + N''' = ''A'' THEN 1 ELSE TH.IsAppointment END AND TH.IsTask = CASE WHEN ''' + @Mode + N''' = ''T'' THEN 1 ELSE TH.IsTask END ) A INNER JOIN (select * 
			from eV_UserLeads(NOLOCK) UL  left join #tempCustomField CF ON UL.ID = CF.LeadID where ul.parentId = ' + cast(@ParentId AS NVARCHAR) + ' ) as [lead] on A.LeadId = lead.ID LEFT JOIN lead_score_history_latest(NOLOCK) LS ON LS.leadid = lead.ID LEFT JOIN tbl_tsk_UserOutcomeMaster(NOLOCK) UOM ON UOM.Id = A.OutcomesId LEFT JOIN tbl_tsk_UserTaskMaster(NOLOCK) UTM ON A.TaskId = UTM.Id left join tbl_tsk_TaskActionPermission(NOLOCK) tap on tap.task_type_id = A.TaskId and tap.parent_id = ' + cast(@ParentId AS NVARCHAR) + ' ) T where 1 = 1 ';  
  
 IF (ISNULL(@FilterText, '') <> '')  
 BEGIN  
  SET @Query1 = @Query1 + ' ' + @FilterText;  
 END  
  
 DECLARE @OrderBy NVARCHAR(max) = ' order by EndDate desc  '  
  
 -- declare @PaginScript nvarchar(max) = ' offset ' +str(@OffsetValue) +' rows fetch next ' + str(@PagingSize)+' rows only '          
 IF (@FilterText NOT LIKE '%order by%')  
 BEGIN  
  SET @Query1 = @Query1 + @OrderBy  
 END  
  
 DECLARE @Query2 NVARCHAR(max) = @Query + @Query1 --+ @PaginScript          
  
 PRINT @Query  
 PRINT @Query1  
  
 -- print @PaginScript          
 --print @Query2           
 EXECUTE sp_executesql @Query2  
END  



GO

