execute sp_executesql @pvtQueryStr


  
 DECLARE @Query NVARCHAR(MAX) =   @QueryTotality  + ' ; ' + 
  N'SELECT * FROM ( SELECT A.LeadId, A.Id as [TaskHistoryId], A.Title, A.Description, A.Address, format(A.StartDate, ''dd-MMM-yyyy HH:mm'') as [StartDate], format(A.EndDate, ''dd-MMM-yyyy HH:mm'') as [EndDate], A.STATUS, dbo.udf_mk_GetTaskCreatorName(A.CreatedBy) AS [CreatorName], format(A.CompletedOn, ''dd-MMM-yyyy HH:mm'') as [CompletedOn], A.Remarks, format(A.CreatedOn, ''dd-MMM-yyyy HH:mm'') as [CreatedOn], format(A.UpdatedOn, ''dd-MMM-yyyy HH:mm'') as [UpdatedOn], dbo.udf_tsk_GetCollaboratersNames(A.Id) AS [Collaboraters], dbo.udf_mk_GetTaskCreatorName(A.AssignedTo) AS [OwnerName], UOM.OutcomeName, (CASE WHEN LOWER(A.STATUS) = ''completed'' THEN ''Completed'' ELSE( CASE WHEN CAST(A.EndDate AS DATE) > CAST(GETDATE() AS DATE) THEN ''Scheduled'' WHEN CAST(A.EndDate AS DATE) < CAST(GETDATE() AS DATE) THEN ''Over Due'' ELSE ''Due Today'' END) END ) AS TaskStatus' + iif( len(@csvColumnList) > 0 , concat(', ', @csvColumnList), '')+ ' FROM ( SELECT TH.LeadId, TH.Id, TH.Title, TH.Description, TH.Address, TH.StartDate, TH.EndDate, TH.STATUS, UD.ParentID, TH.AssignedTo, TH.CreatedBy, 0 AS [UserId], TH.IsTask, TH.IsAppointment, TH.OutcomesId, TH.IsActive, TH.CompletedOn, TH.TaskId, TH.Remarks, TH.CreatedOn, TH.UpdatedOn FROM tbl_tsk_TaskHistory(NOLOCK) TH  LEFT JOIN User_Detail(NOLOCK) UD ON TH.CreatedBy = UD.User_ID WHERE UD.User_Id ' + CASE WHEN (@ParentId > 0  AND @UserId = 0) THEN ' in (' + isnull(@UserIdTeamLst, '') + ')' ELSE ' = ' + CAST(@UserId AS NVARCHAR(MAX)) END + ' AND IsActive = 1 AND TH.IsAppointment = CASE WHEN ''' + @Mode + N''' = ''A'' THEN 1 ELSE TH.IsAppointment END AND TH.IsTask = CASE WHEN ''' + @Mode + N''' = ''T'' THEN 1 ELSE TH.IsTask END          
    UNION'  
 DECLARE @Query1 NVARCHAR(max) = N' SELECT TH.LeadId, TH.Id, TH.Title, TH.Description, TH.Address, TH.StartDate, TH.EndDate, TH.STATUS, UD.ParentID, TH.AssignedTo, TH.CreatedBy,0 AS [UserId], TH.IsTask, TH.IsAppointment, TH.OutcomesId, TH.IsActive, TH.CompletedOn, TH.TaskId, TH.Remarks, TH.CreatedOn, TH.UpdatedOn FROM tbl_tsk_TaskHistory(NOLOCK) TH LEFT JOIN User_Detail(NOLOCK) UD ON TH.AssignedTo = UD.User_ID LEFT JOIN tbl_tsk_UserTaskMaster(NOLOCK) UTM ON TH.TaskId = UTM.Id WHERE UD.User_Id ' + CASE WHEN (@ParentId > 0 AND @UserId = 0) THEN ' in (' + isnull(@UserIdTeamLst, '') + ')' ELSE ' = ' + CAST(@UserId AS NVARCHAR(MAX)) END + ' AND IsActive = 1 AND TH.IsAppointment = CASE WHEN ''' + @Mode + N''' = ''A'' THEN 1 ELSE TH.IsAppointment END AND TH.IsTask = CASE WHEN ''' + @Mode + N''' = ''T'' THEN 1 ELSE TH.IsTask END
   UNION 
   SELECT TH.LeadId, TH.Id, TH.Title,  TH.Description, TH.Address, TH.StartDate, TH.EndDate, TH.STATUS, UD.ParentID, TH.AssignedTo, TH.CreatedBy, 0 AS [UserId], TH.IsTask,  TH.IsAppointment,TH.OutcomesId, TH.IsActive, TH.CompletedOn, TH.TaskId, TH.Remarks, TH.CreatedOn, TH.UpdatedOn FROM tbl_tsk_TaskHistory(NOLOCK) TH JOIN User_Detail(NOLOCK) UD ON TH.CreatedBy = UD.User_ID AND th.taskid <> 4  LEFT JOIN tbl_tsk_CollaborationUserMapping(NOLOCK) TCM ON TH.Id = TCM.TaskHistoryId WHERE UD.User_Id ' + CASE WHEN (@ParentId > 0 AND @UserId = 0)  
    THEN ' in (' + isnull(@UserIdTeamLst, '') + ')'  
   ELSE ' = ' + CAST(@UserId AS NVARCHAR(MAX))  
   END + ' AND IsActive = 1 AND TH.IsAppointment = CASE WHEN ''' + @Mode + N''' = ''A'' THEN 1 ELSE TH.IsAppointment END AND TH.IsTask = CASE WHEN ''' + @Mode + N''' = ''T'' THEN 1 ELSE TH.IsTask END ) A INNER JOIN (select * 
			from eV_UserLeads(NOLOCK) UL  left join #tempCustomField CF ON UL.ID = CF.LeadID where ul.parentId = ' + cast(@ParentId AS NVARCHAR) + ' ) as [lead] on A.LeadId = lead.ID  join #userleadsBySegment as uls on lead.ID = uls.ID  LEFT JOIN lead_score_history_latest(NOLOCK) LS ON LS.leadid = lead.ID LEFT JOIN tbl_tsk_UserOutcomeMaster(NOLOCK) UOM ON UOM.Id = A.OutcomesId LEFT JOIN tbl_tsk_UserTaskMaster(NOLOCK) UTM ON A.TaskId = UTM.Id left join tbl_tsk_TaskActionPermission(NOLOCK) tap on tap.task_type_id = A.TaskId and tap.parent_id = ' + cast(@ParentId AS NVARCHAR) + ' ) T where 1 = 1 ';  
  
 IF (ISNULL(@FilterText, '') <> '')  
 BEGIN  
  SET @Query1 = @Query1 + ' ' + @FilterText;  
 END  
  
 DECLARE @OrderBy NVARCHAR(max) = ' order by EndDate desc  '  
  
 -- declare @PaginScript nvarchar(max) = ' offset ' +str(@OffsetValue) +' rows fetch next ' + str(@PagingSize)+' rows only '          
 IF (@FilterText NOT LIKE '%order by%')  
 BEGIN  
  SET @Query1 = @Query1 + @OrderBy  
 END  
  
 DECLARE @Query2 NVARCHAR(max) = @Query + @Query1 --+ @PaginScript          
  
 PRINT @Query  
 PRINT @Query1  
  
 -- print @PaginScript          
 --print @Query2           
 EXECUTE sp_executesql @Query2  

   drop table if exists #userleadsBySegment 

END  



