/* ============================================================
   Procedure: [dbo].[usp_exportWidget_MainWrapperProcedure]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE [dbo].[usp_exportWidget_MainWrapperProcedure](
	@UserId bigint,
	@EntityName nvarchar(50) = '',
	@PageMode nvarchar(50) = '',
	@PageSection nvarchar(50) = '',
	@Mode nvarchar(20) = '',
	@FilterText nvarchar(500) = '',
	@FollowUpType nvarchar(max) = '0',
	@NextStatusFromDate DATETIME = NULL,
	@NextStatusToDate DATETIME = NULL,
	@CreatedFromDate DATETIME = NULL,
	@CreatedToDate DATETIME = NULL,
	@LeadId BIGINT = NULL,
	@Remarks NVARCHAR(500) = '',
	@Overdue BIT = 1,
	@DueToday BIT = 1,
	@Scheduled BIT = 1,
	@NoFollowUp BIT = 1,
	@AssignedTo BIGINT = 0,
	@CreatedBy BIGINT = 0,
	@IsReAssign BIT = NULL,
	@CriteriaName nvarchar(500) = null,
	@csvColumnList nvarchar(max)  = ''
)
as
begin
	
	set @csvColumnList = replace(replace(replace(
							@csvColumnList, 'Lead.Remarks', 'Lead.LeadRemarks'),
							'Lead.NextStatusDate', 'Lead.LeadNextStatusDate'),
							'Lead.CreatedOn', 'Lead.LeadCreatedOn')

	if(@PageMode in ('task', 'appointment'))
	begin
		exec usp_exportWidget_GetTaskHistoryListByUserIdWithSegment 
			@FilterText, @UserId, @Mode, @CriteriaName, @csvColumnList
	end

	if(@PageMode in ('PhysicalAppointment'))
	begin
		exec usp_exportWidget_GetPhysicalAppointmentHistoryListByUserIdWithSegment 
			@FilterText, @UserId, @Mode, @CriteriaName, @csvColumnList
	end

	if(@PageMode = 'FollowUp')
	begin
		print 'FollowUp'
		print @csvColumnList
		exec usp_exportWidget_GetFollowUpListByUserIdWithSegment
			@UserId, @FollowUpType, @NextStatusFromDate, @NextStatusToDate, @CreatedFromDate, @CreatedToDate, @LeadId, @Remarks,  
			@Overdue, @DueToday, @Scheduled, @NoFollowUp, @AssignedTo, @CreatedBy, @IsReAssign, @CriteriaName, @csvColumnList
			
	end

end




