/* ============================================================
   Procedure: [dbo].[Usp_FacebookLeads]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE dbo.Usp_FacebookLeads  --'Daily','05-13-2019','05-13-2020'  
(    
  @Period nvarchar(200),    
  @FromDate nvarchar(50),    
  @ToDate nvarchar(50)     
)    
as    
Begin    
    
     Declare @FromDatetime datetime = convert(datetime,@FromDate)  
     Declare  @ToDatetime datetime = convert(datetime,@ToDate)  
  
 if(@Period = 'Monthly')  
  Begin  
   SELECT  
     --@Period as Period  
      'abc' as Ad  
   ,Cast(datepart(MM,MLE.CreatedDate) as nvarchar) +'-'+ CAST(datepart(YYYY,MLE.CreatedDate) as nvarchar) as Period  
  
   ,COUNT(MLE.LeadNo) as Lead  
   ,SUM(LIH.AmountPaid) as AmountPaid  
      ,datepart(YYYY,MLE.CreatedDate) as Year  
   ,datepart(MM,MLE.CreatedDate) as Month  
   FROM ParsedEnquiries as PE  (nolock) 
     join tbl_MergeLeadsEnquiry MLE  (nolock)
     on PE.EnquiryId = MLE.EnquiryNo  
     join LeadInteractionHistory LIH  (nolock)
     on ( PE.Parentid = Lih.ParentID and MLE.LeadNo = LIH.LeadNo)   
   where MLE.LeadNo <> 0  
     and MLE.CreatedDate between @FromDatetime and @ToDatetime  
   --and PE.EnquirySource like '%facebook%'  
     group by datepart(YYYY,MLE.CreatedDate),datepart(MM,MLE.CreatedDate)  
     order by datepart(YYYY,MLE.CreatedDate) desc ,datepart(MM,MLE.CreatedDate) desc  
     End  
     else if(@Period = 'Daily')   
      Begin  
    select  
   --@Period as Period  
     'abc' as Ad  
     ,COUNT(MLE.LeadNo) as Lead  
     ,SUM(LIH.AmountPaid) as AmountPaid  
     ,cast( Convert(date,MLE.CreatedDate) as nvarchar )   as Period   
     FROM ParsedEnquiries as PE   (nolock)
       join tbl_MergeLeadsEnquiry MLE  (nolock)
    on PE.EnquiryId = MLE.EnquiryNo  
    join LeadInteractionHistory LIH  (nolock)
    on ( PE.Parentid = Lih.ParentID and MLE.LeadNo = LIH.LeadNo)   
  where MLE.LeadNo <> 0  
     and MLE.CreatedDate between @FromDatetime and @ToDatetime  
     group by Convert(date,MLE.CreatedDate)    
  
  order by Convert(date,MLE.CreatedDate) desc  
  
   End    
  
  
  
End


GO

/* ============================================================
   Procedure: [dbo].[usp_fb_AutoSuggestUserId]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- EXEC usp_fb_AutoSuggestUserId 'kmukesh'

CREATE   PROCEDURE usp_fb_AutoSuggestUserId  
@FilterText VARCHAR(200)  
AS  
BEGIN  
SELECT  
 User_Id AS UserId,
 User_Login AS UserLogin,
 LTRIM(RTRIM(FName))+ ' ' + LTRIM(RTRIM(LName)) AS FullName,  
 Mobile AS MobileNo,  
 LTRIM(RTRIM(City)) + ' ' + LTRIM(RTRIM(State)) + ' '+ LTRIM(RTRIM(Country)) AS [Location] from User_Detail where ParentID = User_Id and Status = 1 and M_ID = 10043 
	AND (
			FName like @FilterText+ '%' or
			User_Id =  IIF(ISNUMERIC(@FilterText) = 1, @FilterText, 0 ) or
			User_Login like @FilterText+ '%'
		)  
END  


