/* ============================================================
   Procedure: [dbo].[usp_fb_EnquiryColumnList]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC [dbo].[usp_fb_EnquiryColumnList] @UserId BIGINT  
AS  
	declare @ParentId BIGINT;

	SELECT @ParentId  = ParentId from User_Detail where User_ID = @UserId


    BEGIN  
        SELECT column_name AS 'fieldname',   
               UPPER(   
     CASE column_name  
      WHEN 'CampaignName'   
       THEN 'VARCHAR'  
      WHEN 'MediumName'  
       THEN 'VARCHAR'  
      WHEN 'SourceName'  
       THEN 'VARCHAR'  
      ELSE  
       data_type  
      END  
    ) AS 'data_type'  
        FROM information_schema.columns  
        WHERE table_name = 'UserEnquiry'  
        UNION  
        SELECT fieldname,    
               UPPER((CASE datatype  
                    WHEN 'd'  
                    THEN 'DateTime'  
                    WHEN 'f'  
                    THEN 'Numeric'  
                    WHEN 'v'  
                    THEN 'VARCHAR'  
                END)) AS data_type  
        FROM customfields NOCOUNT  
        WHERE [ParentID] = @ParentId;  
    END;  


GO

