/* ============================================================
   Procedure: [dbo].[usp_fb_FacebookUserToken]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_fb_FacebookUserToken(
	@ParentId bigint = 0
)
as
begin
	
	--declare @ParentId bigint = 34594

	select 
		Id, FbUserId, LongAccessToken, ParentId,
		(select Id, FbPageLongToken, FbPageId from tbl_fb_FacebookPages(nolock) p
			where FbUserId = u.FbUserId for json path) as [PageTokens]
	from tbl_fb_FacebookUsers(nolock) u where isActive = 1 
		and 1 = ( case when isnull(u.TokenLastSynced, '') = '' then 1
			when isnull(@ParentId, 0) > 0 then 1
			when isnull(u.TokenLastSynced, '') <> '' 
				and cast(u.TokenLastSynced as date) < cast(getdate() as date) then 1 
			else 0 end) 
		and 1 = ( case when isnull(@ParentId, 0) = 0 then 1 
			when isnull(@ParentId, 0) > 0 and u.ParentId = @ParentId then 1 else 0 end )

end



