/* ============================================================
   Procedure: [dbo].[usp_fb_GetFbLeadByFormId]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- exec usp_fb_GetFbLeadByFormId 36790, '03-Oct-2020', '02-Nov-2020', '', '', '', '36790'            
-- go        
CREATE   PROCEDURE dbo.usp_fb_GetFbLeadByFormId (
	@UserId BIGINT
	,@StartDate VARCHAR(50) = ''
	,@EndDate VARCHAR(50) = ''
	,@FbPageId NVARCHAR(200) = ''
	,@FbFormId NVARCHAR(200) = ''
	,@ErrorText NVARCHAR(500) = ''
	,@UserIds VARCHAR(500) = ''
	)
AS
BEGIN
	DECLARE @ParentId BIGINT;

	IF (@UserIds = '')
	BEGIN
		SELECT @ParentId = ParentID
		FROM User_Detail
		WHERE User_ID = @UserId;
	END;

	DECLARE @FilterExp NVARCHAR(MAX) = '';

	IF (@StartDate <> '')
	BEGIN
		SET @FilterExp = @FilterExp + ' AND flj.ReceviedOn >= ''' + @StartDate + '''';
	END;

	IF (@EndDate <> '')
	BEGIN
		SET @FilterExp = @FilterExp + ' AND  flj.ReceviedOn <= ''' + REPLACE(CONVERT(VARCHAR(15), DATEADD(DD, 1, @EndDate), 106), ' ', '-') + '''';
	END;

	IF (@FbPageId <> '')
	BEGIN
		SET @FilterExp = @FilterExp + ' AND  fp.FbPageId = ''' + @FbPageId + '''';
	END;

	IF (@FbFormId <> '')
	BEGIN
		SET @FilterExp = @FilterExp + ' AND  fpf.FbFormId = ''' + @FbFormId + '''';
	END;

	IF (@ErrorText <> '')
	BEGIN
		SET @FilterExp = @FilterExp + ' AND  flj.FailedReason like ''' + @StartDate + '%''';
	END;

	DECLARE @sqlQuery NVARCHAR(MAX) = '';

	SET @sqlQuery = N'SELECT flj.Id as [LeadgenAutoId], fp.FbPageId, fpf.FbFormId, flj.LeadgenId, fp.FbPageName, fpf.FbFormTitle, flj.JsonData, ue.EnquiryID, ue.PersonName, ue.ProfileImgFileName, ue.InitialRemarks, flj.FailedReason,  flj.ReceviedOn, fpf.ParentId AS [ParentID], UD.User_Login       
	FROM tbl_fb_FacebookPages fp             
		inner join tbl_fb_FacebookPageForms(nolock) fpf on fp.FbPageId = fpf.FbPageId      
		inner join tbl_fb_WebhookJsonData(nolock) wjd on fpf.FbFormId = wjd.FbForm_Id            
		inner join tbl_fb_FacebookLeadJson(nolock) flj on wjd.Id = flj.WebhookJsonId       
		left JOIN User_Detail(nolock) UD  ON UD.User_ID = fpf.ParentId      
		left JOIN UserEnquiry(nolock) ue on flj.EnquiryId  = ue.EnquiryID             
		WHERE ' + IIF(@UserIds = '', IIF(@ParentId != 335, ' fp.ParentId = ' + CAST(@ParentId AS NVARCHAR), ' 1=1 '), ' fpf.ParentID IN (' + @UserIds + ') ') + @FilterExp + ' order by wjd.CreatedOn desc ';

	PRINT @sqlQuery

	EXECUTE sp_executesql @sqlQuery;

	EXEC MySmsAudit.dbo.Usp_AuditTableDataByParentId @User_id = @UserId
		,@Activity_type = 'View_FBLead'
		,@ActionType = 'S'
		,@RowJson = ''
		,@Table_name = 'tbl_fb_FacebookPages'
END



GO

/* ============================================================
   Procedure: [dbo].[usp_fb_GetFbLeadByFormIdPagging]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_fb_GetFbLeadByFormIdPagging](
	@UserId BIGINT ,
	@StartDate VARCHAR(50) = '',
	@EndDate VARCHAR(50) = '',
	@FbPageId NVARCHAR(200) = '',
	@FbFormId NVARCHAR(200) = '',
	@ErrorText NVARCHAR(500) = '',
	@UserIds VARCHAR(500) = '',
	@Offset int = 0,
	@PageSize int = 100
)
AS
BEGIN

	--declare 
	--	@UserId BIGINT = 46780,
	--	@StartDate VARCHAR(50) = N'19-Dec-2024',
	--	@EndDate VARCHAR(50) = N'18-Jan-2025',
	--	@FbPageId NVARCHAR(200) = '',
	--	@FbFormId NVARCHAR(200) = '',
	--	@ErrorText NVARCHAR(500) = '',
	--	@UserIds VARCHAR(500) = '',
	--	@Offset int = 0,
	--	@PageSize int = 100

	
	declare 
		@ParentId bigint = 0 

	select @ParentId = ParentID from User_Detail(nolock) where User_ID = @UserId

	PRINT CONCAT('@ParentId => ', @ParentId)

	declare @rStart int = 1, @rEnd int = 100

	select @rStart = (@Offset + 1), @rEnd = (@Offset + @PageSize)

	;with fbLead as(
		select 
			row_number() over ( order by flj.Id desc ) AS [rNo],
			1 as tRow, flj.Id as [LeadgenAutoId], fp.FbPageId, fpf.FbFormId, flj.LeadgenId, fp.FbPageName, fpf.FbFormTitle, flj.JsonData, 
			ue.EnquiryID, ue.PersonName, ue.ProfileImgFileName, ue.InitialRemarks, flj.FailedReason, flj.ReceviedOn, fpf.ParentId AS [ParentID], UD.User_Login
		from tbl_fb_FacebookLeadJson(nolock) flj 
			inner join User_Detail(nolock) UD  ON UD.User_ID = flj.ParentId
			left join tbl_fb_FacebookPageForms(nolock) fpf on fpf.FbFormId  = flj.FbFormId and flj.ParentId = fpf.ParentId
			left join tbl_fb_FacebookPages(nolock) fp on fpf.FbPageId = fp.FbPageId and fp.ParentId = fpf.ParentId
			left join UserEnquiry(nolock) ue on flj.EnquiryId  = ue.EnquiryID             
		where flj.ParentId = @ParentId
			and 1 = (case when isnull(@UserIds, '') = '' then 1
					when fpf.ParentID in ( select [value] from fn_Split(trim(@UserIds), ',')) then 1
					else 0 end )		
			and 1 = (case when isnull(@StartDate, '')  = '' and isnull(@EndDate, '')  = '' then 1
					when cast(flj.ReceviedOn as date) between cast(@StartDate as date) and @EndDate  then 1
						else 0 end ) 
			and 1 = (case when isnull(@FbPageId, '') = '' then 1
					when fp.FbPageId = @FbPageId then 1 else 0 end )
			and 1 = (case when isnull(@FbFormId, '') = '' then 1
					when fpf.FbFormId = @FbFormId then 1 else 0 end )
			and 1 = (case when isnull(@ErrorText, '') = '' then 1
					when flj.FailedReason like '%'+@ErrorText+'%' then 1 else 0 end )
		) 
		select  rNo, (select count(1) from fbLead) as [TotalRow], LeadgenAutoId, FbPageId, FbFormId, LeadgenId,
			FbPageName, FbFormTitle, JsonData, EnquiryID, PersonName, ProfileImgFileName, InitialRemarks, 
			FailedReason, ReceviedOn, ParentID, User_Login
		from fbLead where rNo between @rStart and @rEnd 

END



GO

