SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE [dbo].[usp_fb_GetFormsViewList]  
	@UserId BIGINT  
AS  
BEGIN  
	
 --declare @UserId BIGINT   = 48529

 DECLARE @ParentId BIGINT  
 SELECT @ParentId = ParentID FROM User_Detail WHERE User_ID = @UserId  
 select 
	fp.ParentId, 
		fp.FbUserId, 
		fp.FbPageId, 
		isnull(pf.FbFormId, 0) as [FbFormId], 
		fp.FbPageLongToken, 
		fp.FbPageName, 
		fp.FbPageCategory, 
		fp.IsAuthorized,
		fp.AuthErMessage,
		isnull(pf.FbFormTitle, 0) as [FbFormTitle],
		isnull(pf.CreatedOn, GETDATE()) as [CreatedOn],
		fr.RequestCount,
		fr.TotalFetchRecord,
		fr.LastIsProcessed,
		fr.LastRecordCount
	from  tbl_fb_FacebookPages(nolock) fp  
	inner join tbl_fb_FacebookUsers(nolock) fu on fp.FbUserId = fu.FbUserId
	left JOIN tbl_fb_FacebookPageForms(nolock) pf on fp.FbPageId = pf.FbPageId 
	left join v_FacebookLeadgenSummary(nolock) fr on pf.FbFormId = fr.FbFormId
	where  fp.ParentId = @ParentId 
	--LEFT JOIN tbl_fb_FacebookPageForms pf on fp.FbPageId = pf.FbPageId where  fp.ParentId = @ParentId  
END



