CREATE   PROCEDURE usp_fb_GetFormsViewListForAdmin    
@UserIds varchar(1000) = ''  
AS    
BEGIN    
 --DECLARE @ParentId BIGINT    
 --SELECT @ParentId = ParentID FROM User_Detail WHERE User_ID = @UserId   
  
 DECLARE @sql NVARCHAR(MAX) = N'select fp.ParentId, UD.User_Login as UserLogin, fp.FbUserId, fp.FbPageId, pf.FbFormId, fp.FbPageLongToken, fp.FbPageName, fp.FbPageCategory, pf.FbFormTitle, pf.CreatedOn from  tbl_fb_FacebookPages fp    
   INNER JOIN tbl_fb_FacebookPageForms pf on fp.FbPageId = pf.FbPageId  
   INNER JOIN User_Detail UD ON fp.ParentId = UD.User_ID  
 where  ' + IIF( @UserIds = '', ' fp.CreatedOn BETWEEN  ''' + CAST(DATEADD(DD, -30, GETDATE()) AS NVARCHAR(200)) +'''  AND ''' + CAST(GETDATE() AS NVARCHAR(200)) + '''' , 'fp.ParentId IN (' + @UserIds +')')  + ' ORDER BY CreatedOn DESC' 
  
EXECUTE sp_executesql @sql  
  
END


