/* ============================================================
   Procedure: [dbo].[usp_fb_GetLeadgenIds]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_fb_GetLeadgenIds]      
as      
begin      

	/*
	select distinct wjd.FbLeadgen_Id, wjd.FbPageId, fp.FbPageLongToken, fp.ParentId   
	 from tbl_fb_WebhookJsonData wjd  (nolock)   
	  inner join tbl_fb_FacebookPages fp  (nolock) on wjd.FbPageId = fp.FbPageId      
	  left join tbl_fb_FacebookLeadJson flj  (nolock) on wjd.FbLeadgen_Id = flj.LeadgenId  and wjd.ParentId = flj.ParentId  
	  join Price_UserSubscriptionDetails (nolock) p on p.UserID= fp.ParentId and isnewplan=1 and PlanEndDate>getdate()  
	 where flj.LeadgenId is null  and isnull(wjd.Retries,0)<5 and datediff(HOUR,wjd.CreatedOn,getdate())<=4    
	*/

	select distinct 
		wjd.Id, wjd.FbLeadgen_Id, wjd.FbPageId, fp.FbPageLongToken, fp.ParentId, fu.IsAuthorized, wjd.Retries
	from tbl_fb_WebhookJsonData(nolock) wjd    
		inner join tbl_fb_FacebookPages(nolock) fp on wjd.FbPageId = fp.FbPageId
		inner join tbl_fb_FacebookUsers(nolock) fu on fp.ParentId = fu.ParentId and  fp.FbUserId = fu.FbUserId and fu.isActive = 1
		left join tbl_fb_FacebookLeadJson flj  (nolock) on wjd.FbLeadgen_Id = flj.LeadgenId  and wjd.ParentId = flj.ParentId  
		join Price_UserSubscriptionDetails (nolock) p on p.UserID= fp.ParentId and isnewplan=1 and PlanEndDate>getdate() 
		
	where flj.LeadgenId is null 
		--and wjd.CreatedOn > '20240902' -- add for force retrive
		and isnull(wjd.Retries,0) < 5  

		and datediff(HOUR, wjd.CreatedOn, getdate()) <= 4
		and 1 = (case
			when wjd.IsAuthFailed = 1 and fu.IsAuthorized = 1 then 1
			when fu.IsAuthorized = 1 and isnull(wjd.Retries,0) < 5  
				and datediff(HOUR, wjd.CreatedOn, getdate()) <= 4 then 1
			else 0 end
		)
  
end  



GO

