/* ============================================================
   Procedure: [dbo].[usp_fb_GetUnprocessedLeadgenRequest]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_fb_GetUnprocessedLeadgenRequest
as
begin

	drop table if exists #tempRequest
	select r.Id, r.FbFormId, p.FbPageId, p.FbPageLongToken, r.isProcessed, r.ParentId  
		into #tempRequest from tbl_fb_FacebookLeadgenRequest(nolock) r
		inner join tbl_fb_FacebookPageForms(nolock) f on r.FbFormId = f.FbFormId and r.ParentId = f.ParentId
		inner join tbl_fb_FacebookPages(nolock) p on f.FbPageId = p.FbPageId and f.ParentId = p.ParentId
	where r.isProcessed = 0 --and r.Id = 1

	update r set r.isProcessed = 2, processStartOn = GETDATE() from #tempRequest t
		inner join tbl_fb_FacebookLeadgenRequest(nolock) r on t.Id = r.Id

	select * from #tempRequest
end



GO

/* ============================================================
   Procedure: [dbo].[usp_fb_InserPageDetails]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_fb_InserPageDetails
	@FbPageId VARCHAR(255),
	@FbPageName VARCHAR(2000),
	@FbPageCategory VARCHAR(200),
	@FbPageLongToken VARCHAR(MAX),
	@FbPageExpTimestamp BIGINT,
	@FbUserId VARCHAR(255),
	@ParentId BIGINT
AS
BEGIN
	IF(NOT EXISTS(SELECT * FROM tbl_fb_FacebookPages WHERE FbPageId = @FbPageId))
		BEGIN
			INSERT INTO tbl_fb_FacebookPages(FbPageId, FbPageName, FbPageCategory, FbPageLongToken, FbPageExpTimestamp, FbUserId, ParentId, CreatedOn)
				VALUES (@FbPageId, @FbPageName, @FbPageCategory, @FbPageLongToken, @FbPageExpTimestamp, @FbUserId, @ParentId, GETDATE())	
		END
	ELSE
		BEGIN
			UPDATE tbl_fb_FacebookPages SET 
					FbPageName = IIF(ISNULL(@FbPageName, '') = '', FbPageName, @FbPageName),
					FbPageCategory = IIF(ISNULL(@FbPageCategory, '') = '', FbPageCategory, @FbPageCategory),
					FbPageLongToken = IIF(ISNULL(@FbPageLongToken, '') = '', FbPageLongToken, @FbPageLongToken),
					FbPageExpTimestamp = IIF(ISNULL(@FbPageExpTimestamp, '') = '' , FbPageExpTimestamp, @FbPageExpTimestamp),
					FbUserId = IIF(ISNULL(@FbUserId , '') = '' , FbUserId, @FbUserId),
					ParentId = IIF(ISNULL(@ParentId , '') = '' , ParentId, @ParentId),
					UpdatedOn  = GETDATE()
						WHERE FbUserId = @FbUserId;
		END
END




