/* ============================================================
   Procedure: [dbo].[usp_fb_InsertFetchedLeadGen]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_fb_InsertFetchedLeadGen](
	@FacebookLeadgen FacebookLeadgen readonly
)
as
begin
	
	drop table if exists #tempFacebookLeadgen
	select * into #tempFacebookLeadgen from @FacebookLeadgen

	declare 
		@fetchedRecored int  = 0,
		@TotalRecord int = 0, 
		@Id bigint = 0,
		@FbFormId nvarchar(255) = ''
	select @fetchedRecored = count(1) from #tempFacebookLeadgen
	select top 1 @Id = Id from #tempFacebookLeadgen

	delete f from #tempFacebookLeadgen f
		inner join tbl_fb_FacebookLeadJson(nolock) l on f.LeadgenId = l.LeadgenId

	select @FbFormId = FbFormId from tbl_fb_FacebookLeadgenRequest(nolock) where id = @Id

	insert into tbl_fb_FacebookLeadJson(JsonData, LeadgenId, IsProccesed, FailedReason, ReceviedOn, CreatedOn, WebhookJsonId, ParentId, EnquiryId, FbFormId )
	select JsonData, LeadgenId, 0 as [IsProccesed] , '' as FailedReason,
		dbo.ConvertFBCreateTimeToIST(json_value(JsonData, '$.created_time')) as [ReceviedOn],
		getdate() as CreatedOn, 0 as [WebhookJsonId], ParentId, 0 as EnquiryId, @FbFormId as [FbFormId]   from #tempFacebookLeadgen



	select @TotalRecord =  count(Id) from #tempFacebookLeadgen
	print concat('@Id => ', @Id)
	print concat('@TotalRecord => ', @TotalRecord)
	print concat('@fetchedRecored => ', @fetchedRecored)


	update tbl_fb_FacebookLeadgenRequest set 
		isProcessed = ( case 
					when isnull(@fetchedRecored, 0) = 0 then 1 
					when @fetchedRecored = 100 then 3 
					when @fetchedRecored < 100 then 1 
				else isProcessed end),
		RecordCount = isnull(RecordCount, 0) + isnull(@TotalRecord, 0),
		processEndOn = getdate() 
	where id = @Id

end



GO

