SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE usp_fb_InsertFormFeildMapping   
                 @FbFormId             VARCHAR(200) ,   
                 @UserId               BIGINT ,   
                 @SourceSettingMapping FBSOURCEMAPPING READONLY ,   
                 @FormFeildMapping     FBFIELDMAP READONLY  
AS  
    BEGIN  
begin try  
        DECLARE @ParentId BIGINT;  
        SELECT @ParentId = ParentId  
        FROM User_Detail  
        WHERE User_ID = @UserId;  
        IF ( EXISTS ( SELECT * FROM tbl_MarketingApiSource WHERE FbFormId = @FbFormId  
                    ) )   
        BEGIN  
            DELETE tbl_MarketingApiSource  
            WHERE FbFormId = @FbFormId;  
        END;  
          
  INSERT INTO tbl_MarketingApiSource (LeadSource , EnquiryField , EnquiryFieldValue , FbFormId , ParentId )   
               SELECT LeadSource , EnquiryField , EnquiryFieldValue , @FbFormId , @ParentId FROM @SourceSettingMapping;  
        IF ( EXISTS ( SELECT * FROM @FormFeildMapping ) )   
  BEGIN  
   IF ( EXISTS ( SELECT * FROM tbl_fb_FormFeildMapping WHERE FbFormId = @FbFormId ) )   
   BEGIN  
    DELETE tbl_fb_FormFeildMapping  
    WHERE FbFormId = @FbFormId;  
   END;  
  
   INSERT INTO tbl_fb_FormFeildMapping ( FbFormId , FbFieldType , FbFieldName , EnquiryFieldName , ParentId, FbQuetions )   
       SELECT @FbFormId , FbFieldType , FbFieldName , EnquiryFieldName , @ParentId, FbQuetions  
       FROM @FormFeildMapping;  
  END  
  end try
  begin catch
  exec usp_InsertErrorInfo
  end catch
    END;


GO

/* ============================================================
   Procedure: [dbo].[usp_fb_InserTokenUpdaterError]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_fb_InserTokenUpdaterError(
	@ErrorString nvarchar(max),  
	@ParentId bigint,  
	@LeadgenId nvarchar(200)  
)
as  
begin  

	--declare 	
	--@ErrorString nvarchar(max) = N'{"Version":{"Major":1,"Minor":1,"Build":-1,"Revision":-1,"MajorRevision":-1,"MinorRevision":-1},"Content":{"Headers":[{"Key":"Content-Type","Value":["text/javascript; charset=UTF-8"]},{"Key":"Expires","Value":["Sat, 01 Jan 2000 00:00:00 GMT"]}]},"StatusCode":400,"ReasonPhrase":"Bad Request","Headers":[{"Key":"Vary","Value":["Origin","Accept-Encoding"]},{"Key":"Access-Control-Allow-Origin","Value":["*"]},{"Key":"x-app-usage","Value":["{\"call_count\":0,\"total_cputime\":0,\"total_time\":0}"]},{"Key":"x-fb-rlafr","Value":["0"]},{"Key":"Strict-Transport-Security","Value":["max-age=15552000; preload"]},{"Key":"Pragma","Value":["no-cache"]},{"Key":"x-fb-request-id","Value":["AH7S-KJ0t3NZr68WPiF42yR"]},{"Key":"x-fb-trace-id","Value":["GCWKUoRjM09"]},{"Key":"x-fb-rev","Value":["1004118546"]},{"Key":"X-FB-Debug","Value":["Cn8eSKYIInv6hNYRNCgqYC4SkqEQCO5oN/yDymw+kkVo50kKF+2DFVD+Z6TDRmBmH3OH+RQG8fs0pO0Et61afg=="]},{"Key":"Transfer-Encoding","Value":["chunked"]},{"Key":"Alt-Svc","Value":["h3-29=\":443\"; ma=3600,h3-27=\":443\"; ma=3600"]},{"Key":"Connection","Value":["keep-alive"]},{"Key":"Cache-Control","Value":["no-store"]},{"Key":"Date","Value":["Fri, 16 Jul 2021 04:55:58 GMT"]},{"Key":"WWW-Authenticate","Value":["OAuth \"Facebook Platform\" \"invalid_token\" \"Error validating access token: The session has been invalidated because the user changed their password or Facebook has changed the session for security reasons.\""]}],"RequestMessage":{"Version":{"Major":1,"Minor":1,"Build":-1,"Revision":-1,"MajorRevision":-1,"MinorRevision":-1},"Content":null,"Method":{"Method":"GET"},"RequestUri":"https://graph.facebook.com/v7.0/427632494958506?access_token=removedforsafetyconcernsJK","Headers":[],"Properties":{}},"IsSuccessStatusCode":false}',  
	--@ParentId bigint = 16491,  
	--@LeadgenId nvarchar(200)   = '872307643581728'
	

	declare @IsSuccessStatusCode  bit = 0,
		@StatusCode int = 0,
		@ReasonPhrase nvarchar(255) = '',
		@Headers nvarchar(max)  = ''

	select 
		@IsSuccessStatusCode= IsSuccessStatusCode, @StatusCode = StatusCode, @ReasonPhrase = ReasonPhrase, @Headers = Headers
	from openjson(@ErrorString) with (
		IsSuccessStatusCode bit '$.IsSuccessStatusCode',
		StatusCode int '$.StatusCode',
		ReasonPhrase nvarchar(255) '$.ReasonPhrase',
		Headers nvarchar(max) '$.Headers' as json,
		MessageStr nvarchar(max) 
	)

	declare @AuthMessage nvarchar(max) 
		= case when isnull(@Headers, '') <> ''
			then ( select hValue from openjson(@Headers) with( hKey nvarchar(255) '$.Key', hValue nvarchar(max) '$.Value[0]'
					) where hKey = 'WWW-Authenticate') 
			else '' end

	select @IsSuccessStatusCode, @StatusCode, @ReasonPhrase, @AuthMessage
		insert into tbl_fb_TokenUpdaterError(ErrorString, ParentId, LeadgenId)  
			values( @ErrorString, @ParentId, @LeadgenId ) 
	
	update tbl_fb_WebhookJsonData set IsLeadIDProcessed =0,LastAttemptedToProcess=getdate(),Retries=isnull(Retries,0)+1 where FbLeadgen_Id=@LeadgenId


	if(len(@AuthMessage) > 0 and @IsSuccessStatusCode = 0 )
	begin
		update tbl_fb_FacebookUsers set IsAuthorized = 0, UpdatedOn = GETDATE() where ParentId = @ParentId and isActive = 1
	end

end  



GO

/* ============================================================
   Procedure: [dbo].[usp_fb_InsertUpdateFacebookFormDetail]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_fb_InsertUpdateFacebookFormDetail
	@FbFormId VARCHAR(255),
	@FbFormTitle VARCHAR(200),
	@FbPageId VARCHAR(200),
	@ParentId BIGINT
AS
BEGIN
	IF(NOT EXISTS(SELECT * FROM tbl_fb_FacebookPageForms WHERE FbFormId = @FbFormId))
		BEGIN
			INSERT INTO tbl_fb_FacebookPageForms(FbFormId, FbFormTitle, FbPageId, ParentId)
				VALUES (@FbFormId, @FbFormTitle, @FbPageId, @ParentId)	
		END
	ELSE
		BEGIN
			UPDATE tbl_fb_FacebookPageForms SET 
					FbFormId = IIF(ISNULL(@FbFormId, '') = '', FbFormId, @FbFormId),
					FbFormTitle = IIF(ISNULL(@FbFormTitle, '') = '', FbFormTitle, @FbFormTitle),
					FbPageId = IIF(ISNULL(@FbPageId, '') = '', FbPageId, @FbPageId),
					UpdateOn = GETDATE()
						WHERE FbFormId = @FbFormId;
		END
END


GO

/* ============================================================
   Procedure: [dbo].[usp_fb_InsertWebhookJson]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_fb_InsertWebhookJson]
	@JsonData VARCHAR(MAX),
	@FbAd_Id VARCHAR(200) = null,
	@FbForm_Id VARCHAR(200),
	@FbLeadgen_Id VARCHAR(200),
	@FbPageId VARCHAR(200),
	@ReceviedOn  DATETIME,
	@WebhookId bigint = 0
AS
BEGIN
	declare @ParentId bigint = 0;
	select Top 1 @ParentId = ParentId from tbl_fb_FacebookPages(nolock) 
		where FbPageId = @FbPageId and isActive = 1 order by Id desc

	INSERT INTO tbl_fb_WebhookJsonData(JsonData, FbAd_Id, FbForm_Id, FbLeadgen_Id, FbPageId, ReceviedOn, ParentId, webhook_id)
		VALUES(@JsonData, @FbAd_Id, @FbForm_Id, @FbLeadgen_Id, @FbPageId, @ReceviedOn, @ParentId, @WebhookId)
	select SCOPE_IDENTITY()
END



GO

