/* ============================================================
   Procedure: [dbo].[usp_fb_MappedFacebookField]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_fb_MappedFacebookField(
	@ParentId bigint,
	@fbFormIds nvarchar(max)
)
as
begin

	--declare 
	--	@ParentId bigint =  45160,
	--	@fbFormIds nvarchar(max) = N'11774_61360235956,1545389432854992,848536810670082,850019240350691,458649026925516,470265198938313,304798029382632,1759652404442681,1523597461846607,1176875353460061,811675011138284,1172227203982297,706148938304318,751682690321198,406088098518423,1837905703374508,506065061849696,1216779189747236,8057087027689021,777700390913228,986302479867189,2210936342615929,1516084829332361,1715970875816849,392658210588543';

	drop table if exists #tempFbForm

	select 
		ROW_NUMBER() over (partition by (select null) order by (select null) asc ) as [Sno], 
		[value] as [FbFormId] into #tempFbForm	
	from string_split(@fbFormIds, ',')


	select t.FbFormId, f.FieldCount, 
		(case when isnull(f.FieldCount, 0) > 0 then 1 else 0 end) as IsMapped
	from #tempFbForm t left join (select 
				FbFormId, count(1) as [FieldCount] from tbl_fb_FormFeildMapping(nolock) 
			where ParentId = @ParentId group by FbFormId 
		) f on t.FbFormId = f.FbFormId

end



GO

/* ============================================================
   Procedure: [dbo].[usp_fb_MassGenerateEnquiry]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_fb_MassGenerateEnquiry(
	@autoIds nvarchar(max) = ''
)
as
begin
	--declare @autoIds nvarchar(max) = ''
	begin try
		drop table if exists #tempAutoIds
		select 
			[position] as id, 
			[value] as leadgenId,
			cast(0 as bit) isProcess into #tempAutoIds
		from fn_Split(trim(@autoIds), ',')

		while(exists(select * from #tempAutoIds where isProcess = 0 ))
		begin
			declare @leadgenId bigint = 0;
			select top 1 @leadgenId = leadgenId from #tempAutoIds where isProcess = 0
			begin try
				exec usp_ConvertLeadgenToEnquiry @leadgenId
			end try
			begin catch
				exec usp_InsertErrorInfo
			end catch
			update #tempAutoIds set isProcess = 1 where leadgenId = @leadgenId
		end
	end try
	begin catch
		exec usp_InsertErrorInfo
	end catch
end



GO

