CREATE   PROCEDURE usp_fb_RemoveOldIntegrationByParentId(  
 @ParentId bigint  
)  
as  
begin  
	delete from tbl_fb_FacebookUsers where ParentId = @ParentId and isnull(PlatformId, 0) = 0
	delete from tbl_fb_FacebookPages where ParentId = @ParentId
	delete from tbl_fb_FacebookPageForms where ParentId = @ParentId
