/* ============================================================
   Procedure: [dbo].[usp_fb_SaveEditedFieldMap]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE usp_fb_SaveEditedFieldMap
@MappedFieldData FbFieldMappingData READONLY
AS
BEGIN
	DECLARE @TotalRow BIGINT = 0, @Start BIGINT  = 1, @Id BIGINT = 0, @fbFieldName NVARCHAR(MAX) = '', @enquiryFieldName NVARCHAR(MAX) = '' ;
	SELECT @TotalRow = COUNT(*) from @MappedFieldData
	
	WHILE(@Start <= @TotalRow)
	BEGIN
		SELECT @Id = Id, @fbFieldName = fbFieldName, @enquiryFieldName = enquiryFieldName FROM @MappedFieldData where RowNo = @Start
		IF(EXISTS(SELECT * FROM  tbl_fb_FormFeildMapping WHERE Id = @Id))
		BEGIN
			UPDATE tbl_fb_FormFeildMapping
				SET 
					FbFieldType = IIF(ISNULL(@fbFieldName, '') = '', FbFieldType, @fbFieldName),
					FbFieldName = IIF(ISNULL(@fbFieldName, '') = '', FbFieldName, @fbFieldName),
					EnquiryFieldName = IIF(ISNULL(@enquiryFieldName, '') = '', FbFieldType, @enquiryFieldName)
				WHERE
					Id = @Id
		END
		SET @Start = @Start + 1
	END
END



GO

/* ============================================================
   Procedure: [dbo].[usp_fb_SaveFacebookLeadgenRequest]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_fb_SaveFacebookLeadgenRequest(
	@UserId bigint,
	@FbFormId nvarchar(255)
)
as
begin

	declare @ParentId bigint = 0

	select @ParentId = ParentID from User_Detail(nolock) where [User_ID] = @UserId and [Status] = 1

	if(exists(select 1 from tbl_fb_FacebookLeadgenRequest(nolock) 
		where ParentId = @ParentId and FbFormId = @FbFormId and isProcessed = 0 ))
	begin
		select 'requestExists'
	end
	else 
	begin
		insert into tbl_fb_FacebookLeadgenRequest(FbFormId, CreatedBy, CreatedOn, ParentId, isProcessed)
			select @FbFormId, @UserId, GETDATE(), @ParentId, 0
		select 'recoredInserted'
	end

end



GO

/* ============================================================
   Procedure: [dbo].[usp_fb_SaveFacebookWebhook]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_fb_SaveFacebookWebhook(  
 @webhookPayload nvarchar(max),  
 @webhookId bigint = 0,  
 @isActive int  = 0,  
 @Mode nvarchar(25) = 'INSERT'  
)  
as  
begin  
 --declare @webhookPayload nvarchar(max)  
  
 declare @fbWebhookId bigint = 0  
 if(@Mode = 'INSERT')  
 begin  
  insert into tbl_fb_Webhooks(json_payload)  
   values (@webhookPayload)  
  select @fbWebhookId = scope_identity()  
 end  
  
 if(@Mode  = 'UPDATE')  
 begin  
  update tbl_fb_Webhooks set is_active = @isActive, processed_at = GETDATE(), 
		internal_error = @webhookPayload
	where id = @webhookId  
  select @fbWebhookId = @webhookId  
 end  
  
 select @fbWebhookId as [fbWebhookId]  
end 



GO

/* ============================================================
   Procedure: [dbo].[usp_fb_UnprocessWebhooks]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_fb_UnprocessWebhooks
as
begin
	drop table if exists #temp
	select id, json_payload into #temp  from tbl_fb_Webhooks(nolock) where is_active = 2 
		and processed_at  < dateadd(mi,-10,getdate()) and created_on > dateadd(d,-1,getdate()) 
		update t set processed_at=getdate() from tbl_fb_Webhooks t join #temp p on t.id=p.id
		select * from #temp
end



GO

