CREATE   PROCEDURE usp_fb_UpdatePageLongAccessToken
@FbPageLongToken nvarchar(max),
@FbUserId nvarchar(200),
@FbPageId nvarchar(200)
AS
BEGIN
	UPDATE tbl_fb_FacebookPages SET
		FbPageLongToken = IIF(ISNULL(@FbPageLongToken, '') = '', FbPageLongToken, @FbPageLongToken),
		UpdatedOn = GETDATE()
			WHERE FbUserId = @FbUserId AND FbPageId = @FbPageId

	update tbl_fb_FacebookUsers set 
		IsAuthorized = 1,
		UpdatedOn = GETDATE()
	where FbUserId = @FbUserId 
END



