/* ============================================================
   Procedure: [dbo].[usp_fb_usp_fb_GetUnprocessedFacebookLeadJson]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_fb_usp_fb_GetUnprocessedFacebookLeadJson
as
begin
	
	drop table if exists #tF
	select top 10 * into #tF from tbl_fb_FacebookLeadJson(nolock) 
		where Id > 544595 and IsProccesed = 0 
			and WebhookJsonId = 0 order by id asc

	update l set l.IsProccesed = 2, LastProccessedOn = getdate() from #tF t
		inner join tbl_fb_FacebookLeadJson(nolock) l on t.Id = l.Id
	
	select Id, ParentId from #tF
end



