/* ============================================================
   Procedure: [dbo].[usp_fbAdcmpgn_InstUpdtPageDetails]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE usp_fbAdcmpgn_InstUpdtPageDetails @FbUserId VARCHAR(255)      
 ,@UserId BIGINT      
 ,@FbPageJson NVARCHAR(max)      
AS      
BEGIN      
 DECLARE @parentid BIGINT = (      
   SELECT ParentID      
   FROM User_Detail ud(NOLOCK)      
   WHERE ud.User_ID = @UserId      
   )      
 DECLARE @FbPageId VARCHAR(MAX)      
  ,@FbPageName NVARCHAR(max)      
  ,@FbPageCategory NVARCHAR(MAX)      
  ,@FbPageLongToken VARCHAR(max)      
  ,@modifiedDate Datetime = NULL    
  ,@createdDate datetime =getdate()    
      
 SELECT ROW_NUMBER() OVER (      
   ORDER BY FbPageId      
   ) RowNum      
  ,FbPageId      
  ,FbPageName      
  ,FbPageCategory      
  ,FbPageLongToken      
  ,@FbUserId AS FbUserid      
  ,@UserId AS Userid      
  ,@parentid AS parentid      
 INTO #temp      
 FROM OPENJSON(@FbPageJson) WITH (      
   FbPageId VARCHAR(max) '$.Id'      
   ,FbPageName VARCHAR(max) '$.Name'      
   ,FbPageCategory VARCHAR(max) '$.Category'      
   ,FbPageLongToken NVARCHAR(max) '$.AccessToken'      
   )      
       
      
  IF (      
     EXISTS (      
     SELECT 1      
     FROM tbl_FbAdCmpgn_FbPages      
     WHERE FbUserId = @FbUserId    
     )      
    )      
  BEGIN      
  Select @createdDate=CreatedOn from tbl_FbAdCmpgn_FbPages where FbUserId=@FbUserId    
 Delete from tbl_FbAdCmpgn_FbPages  where FbUserId=@FbUserId    
 set @modifiedDate=GETDATE();    
End    
   INSERT INTO tbl_FbAdCmpgn_FbPages (      
    FbPageId      
    ,FbPageName      
    ,FbPageCategory      
    ,FbPageLongToken      
    ,FbUserId      
    ,UserId      
    ,ParentId      
    ,CreatedOn      
 ,UpdatedOn    
    )      
   SELECT t.FbPageId      
    ,t.FbPageName      
    ,t.FbPageCategory      
    ,t.FbPageLongToken      
    ,t.FbUserid      
    ,t.Userid      
    ,t.parentid      
    ,@createdDate    
 ,@modifiedDate    
   FROM #temp t      
END 


GO

