   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON



CREATE   PROCEDURE usp_fetchall_UserheadersPlaceholder2  
AS  
BEGIN  
    DECLARE @sql NVARCHAR(MAX);  
  
    -- Build dynamic SQL to fetch column names  
    SET @sql = '  
    SELECT ''user.'' + COLUMN_NAME AS ColumnHeader  
    FROM INFORMATION_SCHEMA.COLUMNS  
    WHERE TABLE_NAME = ''User_Detail''  
      AND TABLE_SCHEMA = ''dbo''  
    ORDER BY ORDINAL_POSITION;';  
  
    -- Execute dynamic SQL  
    EXEC sp_executesql @sql;  
END;
-------------------------------------------------



