----------------------------

CREATE   PROCEDURE usp_fetchallleadheadersPlaceholder1  
AS  
BEGIN  
    DECLARE @sql NVARCHAR(MAX);  
  
    -- Build dynamic SQL to fetch column names from UserLeads and UserEnquiry tables  
    SET @sql = '  
    SELECT ''lead.'' + COLUMN_NAME AS ColumnHeader  
    FROM INFORMATION_SCHEMA.COLUMNS  
    WHERE TABLE_NAME = ''UserLeads''  
      AND TABLE_SCHEMA = ''dbo''  
    UNION ALL  
    SELECT ''enquiries.'' + COLUMN_NAME AS ColumnHeader  
    FROM INFORMATION_SCHEMA.COLUMNS  
    WHERE TABLE_NAME = ''UserEnquiry''  
      AND TABLE_SCHEMA = ''dbo''  
    ORDER BY ColumnHeader;';  
  
    -- Execute dynamic SQL  
    EXEC sp_executesql @sql;  
END;




