/* ============================================================
   Procedure: [dbo].[usp_fetchchilduser]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-------------------------------------------

CREATE   PROCEDURE usp_fetchchilduser  
    @UserId INT  
AS  
BEGIN  
    -- Variable declarations  
    DECLARE @ParentId INT;  
    DECLARE @IsAdmin BIT;  
  
    -- Fetch ParentID and IsAdmin status of the given user  
    SELECT @ParentId = ParentID, @IsAdmin = IsAdmin  
    FROM User_Detail (NOLOCK)  
    WHERE User_ID = @UserId;  
  
    -- Return the concatenation of first name and last name for each user with the fetched ParentID  
    SELECT   
        User_ID,  
        FName + ' ' + LName AS FullName,  
  ParentID  
    FROM User_Detail (NOLOCK)  
    WHERE ParentID = @ParentId;  
  
    -- If you need to return the fetched ParentId and IsAdmin status, you can do so like this:  
    -- SELECT @ParentId AS ParentId, @IsAdmin AS IsAdmin;  
END;  





GO

