CREATE   PROCEDURE dbo.Usp_FetchMicrositeMessageForMicrosite
	@Cname VARCHAR(50)
AS
BEGIN
	DECLARE @UserID BIGINT
	SELECT TOP 1 @UserID = cpd.[User_ID]
	FROM   ClientPageDetail AS cpd
	WHERE  cpd.PageName = 'www.kit19.com/' + @Cname
	 
	SELECT mm.MicrositeMessage
	FROM   MicrositeMessage AS mm
	WHERE  mm.UserID = @UserID
END



