/* ============================================================
   Procedure: [dbo].[usp_FetchWebHookDetails]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


--------------------------

CREATE   PROCEDURE usp_FetchWebHookDetails  
    @WebhookID BIGINT,  
    @UserId BIGINT  
AS  
BEGIN  
    SET NOCOUNT ON;  
  
    DECLARE @ParentId BIGINT;  
    DECLARE @ModuleCode VARCHAR(50);  
    DECLARE @UserType NVARCHAR(50);  
  
    BEGIN TRY  
        -- Get ParentId and ActionType from User_Detail table  
        SELECT @ParentId = ParentID, @UserType = UserType  
        FROM User_Detail (NOLOCK)  
        WHERE User_ID = @UserId;  
  
        IF @ParentId IS NULL OR @UserType IS NULL  
        BEGIN  
            -- User not found or ActionType not found, return error message  
            THROW 51000, 'User not found or ActionType is missing.', 1;  
        END;  
  
        -- Fetch webhook details based on UserId,WebhookId  
        SELECT   
      WebhookURL,  
            Params,   
            Method,   
            ContentType   
             
        FROM Tbl_CB_WebhookSummary (NOLOCK)  
        WHERE --UserId = @UserId  
          --AND   
    WebhookID = @WebhookID;  
  
    END TRY  
    BEGIN CATCH  
        -- Handle the error  
        DECLARE @ErrorMessage NVARCHAR(4000);  
        DECLARE @ErrorSeverity INT;  
        DECLARE @ErrorState INT;  
  
        SELECT   
            @ErrorMessage = ERROR_MESSAGE(),  
            @ErrorSeverity = ERROR_SEVERITY(),  
            @ErrorState = ERROR_STATE();  
  
        -- Return error message  
        RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState);  
    END CATCH  
END;




GO

