/* ============================================================
   Procedure: [dbo].[Usp_FilteredSpamMessagesInMessageSpam]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


/****************************************************************************      
SP_Name        : Usp_FilteredSpamMessagesInMessageSpam                         
Author         : Mukesh       
Created ON     : 24/12/2009 04:30 PM            
Version        : 1      
Alter by       :             
Alter Date    :        
Location       : PelSoftLab      
SP Description : This SP is Used to add records into MessageSpam table and delete from a ProcessTable table              
****************************************************************************/         
CREATE   PROC [dbo].[Usp_FilteredSpamMessagesInMessageSpam]          
@MsgID VARCHAR(MAX),                    
@ProcessTable VARCHAR(20),          
@IsDND BIT            
AS                    
SET NOCOUNT ON                 
DECLARE @sqlInsert NVARCHAR(MAX)                                      
DECLARE @sqlDelete NVARCHAR(MAX)                
SET @sqlInsert = 'insert into MessageSpam(MessageID,Mobile,[Message],SenderID,SmppID,Priority,U_ID,BatchID,IsDnd,Operator,Isallowdnd) select MessageID,Mobile,[Message],SenderID,SmppID,0,U_ID,BatchID,IsDND,
Operator,Isallowdnd from ' + @ProcessTable  + ' where MessageID in '      
    
       
SET @sqlInsert=@sqlInsert + '(' + @MsgID + ')'                
If (@IsDND = 0)            
BEGIN            
 SET @sqlInsert=@sqlInsert + ' and IsDND = 0'                
END            
SET @sqlDelete='delete from ' + @ProcessTable + ' where MessageID in '                
SET @sqlDelete=@sqlDelete + '(' + @MsgID + ')'         
--IF (@IsDND = 0)            
--BEGIN            
-- SET @sqlDelete=@sqlDelete + ' and IsDND = 0'                
--END                   
begin try 
begin transaction                 
EXEC (@sqlInsert)                  
EXEC (@sqlDelete)
if @@TRANCOUNT > 0 
commit ;    
end try 

begin catch 
if @@TRANCOUNT > 0 
rollback ;  
exec usp_InsertErrorInfo      
end catch 






GO

/* ============================================================
   Procedure: [dbo].[usp_filtermode_calculation]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC usp_filtermode_calculation --100000,10000,0    
@Quantity bigint,    
@Amount bigint,    
@DndRefund bit    
as    
Declare @A int,@B int,@C int,@D bigint,@E bigint,@F bigint,@G decimal,@H decimal,@I decimal,@J int    
set @A=@Quantity --Quantity    
if @DndRefund=1    
print '######## Filter Mode with DND Refund #######'    
else    
print '######## Filter Mode without DND Refund #######'    
print 'Quantity:'+ cast (@A as nvarchar)    
set @B=@Amount --Amount    
print 'Amount:'+ cast (@B as nvarchar)    
--Set @C=@B*100/112.36 --Deduct Service Tax    
Set @C=@B*100/118 --Deduct Service Tax    
print 'After Service Tax Deduction:'+ cast (@C as nvarchar)    
Set @D=@C-@C*30/100 --Deduct 30% for Profit    
Print 'After 30% Deduction for Profit:'+ cast (@D as nvarchar)    
--Set @E=123596 --Our Price with service tax    
Set @E=70000 --Our Price with service tax    
--Print 'Our Price with service tax:'+ cast (.123596 as nvarchar)    
Print 'Our Price with service tax:'+ cast (.70000 as nvarchar)    
Set @F=@D*1000000/@E --Total Quantity according to our price    
Print 'Total Quantity according to our price:'+ cast (@F as nvarchar)    
if @DndRefund=0    
begin    
Set @G=@F*25/100 --25% More credit to user    
Print '25% More credit to user:'+ cast (@G as nvarchar)    
end    
else if @DndRefund=1    
begin    
Set @G=@F*20/100 --25% More credit to user    
Print '20% More credit to user:'+ cast (@G as nvarchar)    
end    
Set @H=@F+@G --Total Credit    
Print 'Total Credit:'+ cast (@H as nvarchar)    
Set @I=@H*10/@A  --Filter Mode    
Print 'Filter Mode:'+cast(@I as nvarchar)    
Set @J=ROUND(@I,0)    
if @J>10    
set @J=10    
select @J    


GO

/* ============================================================
   Procedure: [dbo].[usp_Find_AccountType]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

        
CREATE   PROC [dbo].[usp_Find_AccountType]  --'MTIX_TR',11           
@UserFilter VARCHAR(50) = '',      
@Planid INT = 0 --  frm int acc. table 17-08-2010               
AS         
BEGIN      
    IF @UserFilter <> ''    
    BEGIN    
        SELECT *    
        FROM PlanMaster PM (NOLOCK)
        INNER JOIN User_Filter UF (NOLOCK) ON PM.UserFilter = UF.Code    
        WHERE PM.UserFilter = @UserFilter    
          AND PM.ID = @Planid    
    END    
    ELSE    
    BEGIN    
        -- Case 2: If @UserFilter is blank, first try to fetch with User_Filter join
        IF EXISTS (
            SELECT 1
            FROM PlanMaster PM (NOLOCK)
            INNER JOIN User_Filter UF (NOLOCK) ON PM.UserFilter = UF.Code
            WHERE PM.ID = @Planid
        )
        BEGIN
            -- Fetch using the join with User_Filter
            SELECT *
            FROM PlanMaster PM (NOLOCK)
            INNER JOIN User_Filter UF (NOLOCK) ON PM.UserFilter = UF.Code
            WHERE PM.ID = @Planid
        END
        ELSE
        BEGIN
            -- If no records found with the join, fetch only from PlanMaster using Planid
            SELECT TOP 1 *
            FROM PlanMaster PM (NOLOCK)
            WHERE PM.ID = @Planid
        END
    END
END 


