/* ============================================================
   Procedure: [dbo].[USP_find_UserFILTER]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC USP_find_UserFILTER  --'sms19','03/20/2005','04/22/2010',''    
(@username varchar(50),@fromdate varchar(50),@todate varchar(50),@filter varchar(5))        
as        
BEGIN        
DECLARE @whereClause varchar(500),@Query varchar(2000);        
set @whereClause=''        
If @username = ''        
Begin        
Set @whereClause = @whereClause+' 1=1 and '        
        
End        
Else        
Begin        
Set @whereClause =@whereClause+' user_login Like ''%'+@username+'%'' and'        
        
End      
If @filter = ''        
Begin        
Set @whereClause = @whereClause+' 1=1 and '        
        
End        
Else        
Begin        
Set @whereClause =@whereClause+' filtermode = '+@filter+' and'        
        
End       
if (@fromdate='' and @todate='')        
Begin        
set @whereClause=@whereClause +' 1=1 '        
End        
Else        
Begin        
Set @whereClause =@whereClause +' convert(nvarchar,datecreated,112) between convert(nvarchar,convert(datetime,'''+@fromdate+''',102),112) and convert(nvarchar,convert(datetime ,'''+@todate +''',102),112)'        
        
End        
SET @query='select USER_ID,M_ID,USER_LOGIN,case type when 0 Then ''User'' when 1 then ''Reseller'' else ''SubReseller'' end as TYPE,isnull(filtermode,3) as USERFILTER,convert(varchar,datecreated,103) as DATECREATED from user_detail where  user_id<>335 and  user_id<>1 and status=1 and '+@whereClause+' 
  
    
      
order by user_login'        
print(@Query)        
exec(@query)        
        
end



GO

