/* ============================================================
   Procedure: [dbo].[USP_findIntTrsanction]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC [dbo].[USP_findIntTrsanction]   --335,0,'2019-12-24','2019-12-30'                      
@userid bigint ,                        
@TUserid bigint='',                        
@fromdate varchar(50),                        
@todate varchar(50)                        
as                          
Begin

  Declare @ParentID bigint = ( select top 1 isnull(ParentID,0) from User_Detail with(nolock) where User_ID = @userid ) 
                          
Declare @whereClause1 nvarchar(300), @query nvarchar(3500)                        
set @whereClause1=''                              
create table #temptable                        
--declare @temptable table                        
(                 
Credit_ID bigint,                       
FromUser_ID bigint,                        
Debits float,                        
Credits float,                        
Balance float,                        
Fromdate datetime,                        
User_Login nvarchar(50),          
Remarks varchar(max),Cr_Type varchar(30)                   
                      
)                        
insert into #temptable (Credit_ID, FromUser_ID,Debits,Credits,Balance,Fromdate,u.User_Login,          
Remarks,Cr_Type)                  
select c.Credit_ID,FromUser_ID,Debits,Credits,Balance,Fromdate,u.User_Login,Remarks,          
isnull(p.CreditName,'')  
--(case when isnull(typecredit,0)=0 then 'Int SMS' else           
--(case when isnull(typecredit,0)=1 then 'Voice Brodcast' else           
--(case when isnull(typecredit,0)=2 then 'IVR Call' else           
--(case when isnull(typecredit,0)=3 then 'Google AdWord' else           
--(case when isnull(typecredit,0)=4 then 'Int Email' else '' end) end) end) end) end)           
 as Cr_Type          
 from  IntCredit_Details  c (nolock)  
 inner join user_detail u (nolock) on c.fromuser_id=u.user_id                           
 left join Price_Master_TypeCredit (nolock) p on c.typecredit=p.CreditTypeID  
where c.user_id=@ParentID and fromuser_id is not null                          
                        
if @TUserid='0'                        
begin                         
set @whereClause1=@whereClause1+' 1=1 and '                        
End                        
else                        
begin                        
set @whereClause1=@whereClause1+' FromUser_ID='+ convert(varchar,@TUserid)+' and '                        
End                        
                        
if (@fromdate='' and @todate='')                        
Begin                        
set @whereClause1=@whereClause1+' 1=1  '                        
End                        
Else                        
Begin                        
--set @whereClause1=@whereClause1+' (convert(nvarchar,convert(datetime,Fromdate,102),103) between convert(nvarchar,convert(datetime,'''+@fromdate+''',102),103) and convert(nvarchar,convert(datetime ,'''+@todate +''',102),103)) '                           
  
    
      
        
  select @todate =  convert(datetime,@todate) +1     
            
              
                
--set @whereClause1=@whereClause1+' (CONVERT(VARCHAR(10),Fromdate,103) between CONVERT(VARCHAR(10),'''+@fromdate+''',103) and CONVERT(VARCHAR(10),'''+@todate+''',103)) '                                           
set @whereClause1=@whereClause1+' Fromdate >= '''+@fromdate+''' and Fromdate <= '''+@todate+''''                  
                
set @whereClause1=@whereClause1+' order by Credit_ID desc'                
                
                                         
End                        
set @query='select FromUser_ID,cast(Debits as numeric(16,4)) Debits,              
cast(Credits as numeric(16,4)) Credits, cast(Balance as numeric(16,4)) Balance,           
Fromdate,User_Login, Remarks,Cr_Type from #temptable where  '              
+ @whereClause1+''                        
--select @query                        
exec (@query)                        
                        
End   
  
  
--select * from Price_Master_TypeCredit


GO

