   case when FromUser_ID = 335 and isnull(c.Debits,0) = 0 and isnull(c.Credits,0) > 0 and isnull(c.typecredit,0) = 15  
    then isnull(p.CreditName,'')      
    when FromUser_ID = 335 and isnull(c.Debits,0) = 0 and isnull(c.Credits,0) > 0  and isnull(c.typecredit,0) <> 15  
    then 'Purchased'  
 when isnull(p.CreditName,'') = ''  
