set @whereClause1=@whereClause1+' Fromdate >= '''+@fromdate+''' and Fromdate <= '''+@todate+''''                        
  
 if(@CreditType = '')                              
  Begin                              
      set @whereClause1=@whereClause1+' and 1=1  '                              
  End                              
  else    
   Begin    
     set @whereClause1=@whereClause1+' and Cr_Type = ''' + @CreditType + ''''        
   End    
                      
set @whereClause1=@whereClause1+' order by Credit_ID desc'                      
                      
                                               
