SP Description : This SP is Used to search Payment Details for KIT19                                   
                                                           
****************************************************************************/              
             
CREATE   PROC [dbo].[USP_findPaymentDetails]  --24795 ,'','','','',''                         
@userid BIGINT = NULL ,                        
@CustomerName NVARCHAR(100) = NULL,             
@CustomerNumber NVARCHAR(20) = NULL,                
@PlanName NVARCHAR(20) = NULL,                     
@fromdate VARCHAR(50) = NULL,                        
@todate VARCHAR(50) = NULL                        
AS                          
BEGIN
	DECLARE @whereClause1     NVARCHAR(300),
	        @query            NVARCHAR(3500)      
	
	SET @whereClause1 = ''                                          
	
	IF @CustomerName = ''
	BEGIN
	    SET @whereClause1 = @whereClause1 + ' 1=1 and '
	END
	ELSE
	BEGIN
	    SET @whereClause1 = @whereClause1 + ' CustomerName=''' + @CustomerName +
	        ''' and '
	END                      
	
	IF @CustomerNumber = ''
	BEGIN
	    SET @whereClause1 = @whereClause1 + ' 1=1 and '
	END
	ELSE
	BEGIN
	    SET @whereClause1 = @whereClause1 + ' CustomerNumber=''' + @CustomerNumber 
	        + ''' and '
	END                    
	
	IF @PlanName = ''
	BEGIN
	    SET @whereClause1 = @whereClause1 + ' 1=1 and '
	END
	ELSE
	BEGIN
	    SET @whereClause1 = @whereClause1 + ' PlanName=''' + @PlanName +
	        ''' and '
	END                
	
	IF (@fromdate = '' AND @todate = '')
	BEGIN
	    SET @whereClause1 = @whereClause1 + ' 1=1  '
	END
	ELSE
	BEGIN
	    SET @whereClause1 = @whereClause1 +
	        ' CONVERT(VARCHAR(10),PaymentDate,111) >= ''' + @fromdate +
	        ''' and CONVERT(VARCHAR(10),PaymentDate,111)<=''' + @todate + '''' 
	        
	        --set @whereClause1=@whereClause1+' order by Credit_ID desc'
	END                        
	SET @query = 
	    'select UserID,CustomerName,CustomerNumber,isnull(PD.AmountWithoutTax,0) as Actual_Amount,isnull(PD.Coupon_Code,'''') as CouponCode ,PM.PlanName,TotalAmount,isnull(pd.Quantity,0) as Quantity,isnull(CcAvenueOderNumber,'''') as CcAvenueOderNumber ,
	    BankTransactionId,Status,CONVERT(VARCHAR(10),PaymentDate,110) PaymentDate,PaymentMode,ISNULL(CouponCode,'''') as Coupon_Code ,isnull(DiscountAmount,0) as DiscountAmount ,isnull(OldSmsBalance,0) as OldSmsBalance ,isnull(NewSmsBalance,0) as NewSmsBalance  from 
	    Payment_Detail PD left join PlanMaster PM on PD.PlanID=PM.ID  where  ' + @whereClause1 + ' order by PaymentDate desc ' 
	
	PRINT (@query)                        
	EXEC (@query)
END 


GO

