CREATE   PROC [dbo].[Usp_findResellerDetails] --10001,3531    
@mid bigint,    
@user_id int    
as    
Declare @M_ID bigint, @User_IDTmp int ,@tmpBalance bigint  --user_IDTmp from bigint to int  
select @M_ID=M_ID,@User_IDTmp=User_ID from reseller_detail where reseller_id = (select m_id from user_detail where m_id=@mid and user_id=@user_id)    
select @tmpBalance=Max(Credit_ID) from credit_details where M_ID=@M_ID and User_ID=@User_IDTmp    
if(@tmpBalance!='')    
Begin    
select 'Record Found'    
select @M_ID as M_ID, @User_IDTmp as userid    
End    
Else    
Begin    
select 'Record not found'    
End    


GO

