   Procedure: [dbo].[Usp_findResellerDetailsForMail]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


CREATE   PROC [dbo].[Usp_findResellerDetailsForMail] --10001,3531      
@mid BIGINT,      
@user_id INT      
AS      
DECLARE @M_ID           BIGINT,
        @User_IDTmp     INT,
        @tmpBalance     BIGINT  --user_IDTmp from bigint to int    
SELECT @M_ID = M_ID,
       @User_IDTmp                = USER_ID
FROM   reseller_detail
WHERE  reseller_id                = (
           SELECT m_id
           FROM   user_detail
           WHERE  m_id            = @mid
                  AND USER_ID     = @user_id
       )
      
SELECT @tmpBalance = MAX(Credit_ID)
FROM   MailCreditDetails
WHERE  M_ID            = @M_ID
       AND USER_ID     = @User_IDTmp
      
IF (@tmpBalance != '')
BEGIN
    SELECT 'Record Found'      
    SELECT @M_ID        AS M_ID,
           @User_IDTmp  AS userid
END
ELSE
BEGIN
    SELECT 'Record not found'
END 



GO

