/* ============================================================
   Procedure: [dbo].[Usp_FindThroughputPermin]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
  
CREATE   PROC [dbo].[Usp_FindThroughputPermin]-- '2010-01-22 17:00:51.000' ,'2010-01-22 17:10:51.000'          
@Fdate datetime,              
@todate datetime              
as              
begin              
Declare @temptable table              
(              
gateway int,              
MessageDeliveredDate datetime,              
IsAirtel int              
)              
 insert into @temptable (gateway,MessageDeliveredDate)              
 SELECT  gateway,MessageDeliveredDate from MonitoreMessageDeliveryStatus where MessageDeliveredDate between  @Fdate and @todate   
 select count(gateway) as TATA from @temptable where gateway=1              
 select count(gateway) as Other from @temptable where gateway=2              
 select count(gateway) as Airtel from @temptable where IsAirtel=1              
 select max(MessageDeliveredDate)AS LASTUPDATEDAT from MonitoreMessageDeliveryStatus            
 SELECT * INTO #TEMPTHROUGHPUT FROM tblthroughput WHERE MessageDeliveredDate between  @Fdate and @todate    
 SELECT  gateway,MessageDeliveredDate,ThroughPut,IsAirtel from #TEMPTHROUGHPUT order by MessageDeliveredDate desc    
 DECLARE @THROUGHPUT  DECIMAL(18,5)   
 DECLARE @CNTTOTALMESSAGETATA BIGINT        
 SELECT @CNTTOTALMESSAGETATA=count(gateway)  from @temptable where gateway=1               
 DECLARE @TIMEDIFFINSECOND BIGINT    
 DECLARE @NOOFRECORDS INT        
 SELECT @NOOFRECORDS=count(*)  from #TEMPTHROUGHPUT where gateway=1    
    SELECT @NOOFRECORDS AS NOOFRECORDS   
 SELECT @TIMEDIFFINSECOND =DATEDIFF(SS,@Fdate,@todate)+1  
if  @NOOFRECORDS>0        
SELECT @THROUGHPUT= cast(@CNTTOTALMESSAGETATA as decimal(18,5))/cast(@NOOFRECORDS as decimal(18,5))
else         
SET  @THROUGHPUT=0     
SELECT   @THROUGHPUT AS THROUGHPUT      
SELECT  @TIMEDIFFINSECOND  AS TIMEDIFFINSECOND  
End     
  
           
        
--
--select * from tblthroughput order by messagedelivereddate desc
--
--select (1248/557)




GO

