--[USP_findTrsanction_MailCreditDetails]  335,0,'28/01/2016','29/01/2016'    
--[USP_findTrsanction_MailCreditDetails]  335,0,'2016/01/28','2016/01/29'    
/****************************************************************************          
SP_Name        : USP_findTrsanction_MailCreditDetails                             
Author         : Vishal Kumar Srivastava         
Created ON     : 29aug2017            
Version        : 1          
Alter BY       :                  
Alter Date     :           
SP Description : This SP is Used For Find All Transction record        
Paramater   : USP_findTrsanction_MailCreditDetails 1 ,'','2010-01-01','2010-02-27'           
                 
****************************************************************************/        
        
CREATE   PROCEDURE [dbo].[USP_findTrsanction_MailCreditDetails] 
(
    @userid       BIGINT,
    @TUserid      BIGINT = '',
    @fromdate     VARCHAR(50),
    @todate       VARCHAR(50)
)
AS
BEGIN
	DECLARE @whereClause1     NVARCHAR(300),
	        @query            NVARCHAR(3500)
	
	SET @whereClause1 = ''                
	CREATE TABLE #temptable
	(
		Credit_ID       BIGINT,
		FromUser_ID     BIGINT,
		Debits          BIGINT,
		Credits         BIGINT,
		Balance         BIGINT,
		Fromdate        DATETIME,
		User_Login      NVARCHAR(50)
	)          
	INSERT INTO #temptable
	  (
	    Credit_ID,
	    FromUser_ID,
	    Debits,
	    Credits,
	    Balance,
	    Fromdate,
	    u.User_Login
	  )
	SELECT c.Credit_ID,
	       FromUser_ID,
	       Debits,
	       Credits,
	       Balance,
	       Fromdate,
	       u.User_Login
	FROM   MailCreditDetails c
	       INNER JOIN user_detail u
	            ON  c.fromuser_id = u.user_id
	WHERE  c.user_id = @userid
	       AND fromuser_id IS NOT NULL            
	
	IF @TUserid = '0'
	BEGIN
	    SET @whereClause1 = @whereClause1 + ' 1=1 and '
	END
	ELSE
	BEGIN
	    SET @whereClause1 = @whereClause1 + ' FromUser_ID=' + CONVERT(VARCHAR, @TUserid)
	        + ' and '
	END          
	
	IF (@fromdate = '' AND @todate = '')
	BEGIN
	    SET @whereClause1 = @whereClause1 + ' 1=1  '
	END
	ELSE
	BEGIN
	    SET @whereClause1 = @whereClause1 +
	        ' CONVERT(VARCHAR(10),Fromdate,111) >= ''' + @fromdate +
	        ''' and CONVERT(VARCHAR(10),Fromdate,111)<=''' + @todate + ''''
	    
	    SET @whereClause1 = @whereClause1 + ' order by Credit_ID desc'
	END          
	
	SET @query = 
	    'select FromUser_ID,Debits,Credits,Balance, Fromdate,User_Login from #temptable where  '
	    + @whereClause1 + ''
	
	PRINT (@query)          
	EXEC (@query)
END



