CREATE   PROC dbo.USP_findTrsanction_new --1 ,'','2010-01-01','2010-02-27'               
	@userid BIGINT
	,@TUserid BIGINT = ''
	,@fromdate VARCHAR(50)
	,@todate VARCHAR(50)
AS
BEGIN
	DECLARE @ParentID BIGINT = (
			SELECT TOP 1 isnull(ParentID, 0)
			FROM User_Detail WITH (NOLOCK)
			WHERE User_ID = @userid
			)
	DECLARE @whereClause1 NVARCHAR(300)
		,@query NVARCHAR(3500)

	SET @whereClause1 = ''

	CREATE TABLE #temptable
		--declare @temptable table              
		(
		Credit_ID BIGINT
		,FromUser_ID BIGINT
		,Debits BIGINT
		,Credits BIGINT
		,Balance BIGINT
		,Fromdate DATETIME
		,User_Login NVARCHAR(50)
		,Remarks VARCHAR(10)
		,Cr_Type VARCHAR(10)
		)

	INSERT INTO #temptable (
		Credit_ID
		,FromUser_ID
		,Debits
		,Credits
		,Balance
		,Fromdate
		,u.User_Login
		,Remarks
		,Cr_Type
		)
	SELECT c.Credit_ID
		,FromUser_ID
		,Debits
		,Credits
		,Balance
		,Fromdate
		,u.User_Login
		,''
		,''
	FROM credit_details c(NOLOCK)
	INNER JOIN user_detail u(NOLOCK) ON c.fromuser_id = u.user_id
	WHERE c.user_id = @ParentID
		AND fromuser_id IS NOT NULL

	IF @TUserid = '0'
	BEGIN
		SET @whereClause1 = @whereClause1 + ' 1=1 and '
	END
	ELSE
	BEGIN
		SET @whereClause1 = @whereClause1 + ' FromUser_ID=' + convert(VARCHAR, @TUserid) + ' and '
	END

	IF (
			@fromdate = ''
			AND @todate = ''
			)
	BEGIN
		SET @whereClause1 = @whereClause1 + ' 1=1  '
	END
	ELSE
	BEGIN
		--set @whereClause1=@whereClause1+' (convert(nvarchar,convert(datetime,Fromdate,102),103) between convert(nvarchar,convert(datetime,'''+@fromdate+''',102),103) and convert(nvarchar,convert(datetime ,'''+@todate +''',102),103)) '                           
		--set @whereClause1=@whereClause1+' (CONVERT(VARCHAR(10),Fromdate,103) between CONVERT(VARCHAR(10),'''+@fromdate+''',103) and CONVERT(VARCHAR(10),'''+@todate+''',103)) '                                 
		SET @whereClause1 = @whereClause1 + ' CONVERT(VARCHAR(10),Fromdate,111) >= ''' + @fromdate + ''' and CONVERT(VARCHAR(10),Fromdate,111)<=''' + @todate + ''''
		SET @whereClause1 = @whereClause1 + ' order by Credit_ID desc'
	END

	SET @query = 'select FromUser_ID,Debits,Credits,Balance, Fromdate,User_Login, Remarks,Cr_Type    
 from #temptable where  ' + @whereClause1 + ''

	PRINT (@query)

	EXEC (@query)

	EXEC MySmsAudit.dbo.Usp_AuditTableDataByParentId @User_id = @userid
		,@Activity_type = 'View_emltran'
		,@ActionType = 'S'
		,@RowJson = ''
		,@Table_name = 'credit_details'
END



