/* ============================================================
   Procedure: [dbo].[Usp_FollowUp_EditFollowUpDetails]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- Usp_FollowUp_EditFollowUpDetails @followUpId  =1799118,@userid =34594,@mode ='edit'
CREATE   PROCEDURE [dbo].[Usp_FollowUp_EditFollowUpDetails]
	@followUpId bigint =0 ,
	@userid bigint =0,
	@NextStatusDate VARCHAR(50)=null,                           
    @Remarks        VARCHAR(500)=null, 
	@AssignTo BIGINT =0, 
    @Products       VARCHAR(500)=null,                           
    @AmountPaid     VARCHAR(50)=null,   
@mode nvarchar(20)
as
begin
	--declare @followUpId bigint =1799118,@userid bigint=34594,@mode nvarchar(20)='edit'
	declare @parentid bigint= (Select ParentID from User_Detail (NOLOCK) where User_ID = @userid)
	declare @sql nvarchar(max), @FollowUpData nvarchar(max)
	if @mode='edit'
	BEGIN
		drop table if exists #tempflwup
		Create Table #tempflwup (	
		FollowUpId bigint,
		LeadNo bigint,
		FollowUpStatusID bigint,
		FollowUpStatusName varchar(100),
		NextStatusDate Nvarchar(max),
		Remarks Nvarchar(max),
		ProductsId Nvarchar(max),
		Products Nvarchar(max), 
		AmountPaid Nvarchar(200),
		AssignedTo bigint,  
		FollowupDate Nvarchar(max),
		IsReassign bit 
		)
			set @sql ='Insert into #tempflwup(FollowUpId, LeadNo, FollowUpStatusID, FollowUpStatusName, NextStatusDate, Remarks,ProductsId, Products, AmountPaid, AssignedTo,FollowupDate,IsReassign)
			select lih.ID FollowUpId, LeadNo, lih.FollowUpStatus FollowUpStatusID,fs.FollowUpStatus FollowUpStatusName, NextStatusDate, Remarks, Products Productid, ISNULL(
			( SELECT ss.ProductID,ss.Name      
							   FROM   tbl_ProductMaster_'+cast( @ParentID as nvarchar(max))+' (nolock) AS ss          
									  INNER JOIN dbo.fn_Split(lih.Products, ''#'') AS           
										   fs          
										   ON  ss.ProductID = fs.[value]           
											 FOR JSON           
											   auto ),'''' ) AS Products,
			 AmountPaid, AssignedTo,   Convert(Nvarchar,FollowupDate,13) FollowupDate, IsReassign
			from LeadInteractionHistory (NOLOCK) lih join FollowUp_Status (NOLOCK) fs on lih.FollowUpStatus=fs.ID 
			where lih.ID= '+cast(@followUpId as varchar)
		print @sql
		Exec sp_executesql @sql
		set @FollowUpData =	(select * from #tempflwup FOR JSON AUTO, INCLUDE_NULL_VALUES)
		Select @FollowUpData FollowUpData
	END
	else if @mode ='update'
	BEGIN
		DECLARE @FollowupDate DATETIME= NULL; 
		IF(@NextStatusDate <> '')                          
		BEGIN                          
			SET @FollowupDate = @NextStatusDate;                          
			SELECT @FollowupDate = dbo.[fn_getISTtimefromusertime](@parentid, @FollowupDate);                          
			SELECT @NextStatusDate = CONVERT(NVARCHAR(100), @FollowupDate, 121);                          
		END;       
		DECLARE @NextStatusDate_Ldactv VARCHAR(50)=null, @Remarks_Ldactv VARCHAR(500)=null, @AssignTo_Ldactv BIGINT =0, @Products_Ldactv VARCHAR(500)=null, @AmountPaid_Ldactv VARCHAR(50)=null, 
				@evntMessage NVARCHAR(MAX)='', @EventTemplate NVARCHAR(MAX)='', @Username VARCHAR(50)='',@Leadno bigint , @LeadID Bigint

			Select @NextStatusDate_Ldactv=NextStatusDate,@Remarks_Ldactv=remarks , @AssignTo_Ldactv=AssignedTo , @AmountPaid_Ldactv=AmountPaid, @Products_Ldactv=Products,@Leadno=Leadno
			from LeadInteractionHistory (NOLOCK)
				where ID=@followUpId

		Update LeadInteractionHistory set NextStatusDate = @NextStatusDate, Remarks=@Remarks,Products=@Products ,AmountPaid=@AmountPaid, FollowupDate=@FollowupDate 
											,AssignedTo=@AssignTo
			where ID=@followUpId
		
		if @@ROWCOUNT >0
		BEGIN
			Update Tbl_ST_SalesActivityMaster set Amount=@AmountPaid where TblRefId=@followUpId and TblRefName='LeadInteractionHistory'
		END

		Select 'Data Updated'
		BEGIN TRY
			
			Select @LeadID=ID from UserLeads (NOLOCK) where Leadno = @Leadno and Parentid=@parentid
			Select @Username = User_login from User_detail (NOLOCK) where USER_ID=@userid

			Select @EventTemplate= EventTemplate from ActivityMaster (NOLOCK) where EventName='Conversion Updated'
			if(@NextStatusDate_Ldactv<>@NextStatusDate)
			BEGIN
				Set @evntMessage = 'FollowupDate from '+ @NextStatusDate_Ldactv +' to '+ Convert(varchar,@FollowupDate, 13)+', '
			END
			if(@Remarks<>@Remarks_Ldactv)
			BEGIN
				Set @evntMessage = @evntMessage + 'Remarks from '+@NextStatusDate_Ldactv+' to '+@NextStatusDate+', '
			 END
			 if(@AssignTo_Ldactv<>@AssignTo)
			BEGIN
				Set @evntMessage = @evntMessage + 'AssignTo from '+@AssignTo_Ldactv+' to '+@AssignTo+', '
			 END

			 if(@Products_Ldactv<>@Products)
			BEGIN
				Declare @OldProd nvarchar(3000), @NewProd nvarchar(max)

				Set @sql = ' SELECT @OldProdOut=String_agg( ss.Name, '' ,'') FROM   tbl_ProductMaster_'+Cast(@parentid as varchar)+' (nolock) AS ss  Join dbo.fn_Split( '''+@Products_Ldactv+''' , ''#'') AS    fs          
                                       ON  ss.ProductID = fs.[value]  '
				--print @sql
				Execute Sp_Executesql @sql, N'@OldProdOut nvarchar(3000) output', @OldProdOut=@OldProd output
				
				Set @sql = ' SELECT @NewProdOut=String_agg( ss.Name, '' ,'') FROM   tbl_ProductMaster_'+Cast(@parentid as varchar)+' (nolock) AS ss  Join dbo.fn_Split( '''+@Products_Ldactv+''' , ''#'') AS    fs          
                                       ON  ss.ProductID = fs.[value]  '
				--print @sql
				Execute Sp_Executesql @sql, N'@NewProdOut nvarchar(3000) output', @NewProdOut=@NewProd output

				Set @evntMessage = @evntMessage + 'Products from '+@OldProd+' to '+@NewProd+', '
			 END

			 if(@AmountPaid_Ldactv<>@AmountPaid)
			BEGIN
				Set @evntMessage = @evntMessage + 'Amount from '+@AmountPaid_Ldactv+' to '+@AmountPaid
			 END
			 Select @LeadID
			 --Select @EventTemplate
			Set @evntMessage = Replace(REPLACE(@EventTemplate,'#username#',@Username),'#followupcolumnname# from #oldvalue# to #newvalue#', @evntMessage)
			--select @evntMessage
			IF (@evntMessage <> '')
				BEGIN
					EXEC UspSaveLeadActivity_withid @LeadID
						,@userid
						,@parentid
						,@evntMessage
						,'Conversion Updated'
						,'LeadInteractionHistory'
						,@followUpId
				END

		END TRY
		BEGIN CATCH
			EXEC usp_InsertErrorInfo
		END CATCH
		declare @Rowjson nvarchar(max) = (Select * from LeadInteractionHistory where ID=@followUpId for Json Auto, Include_null_values)
	if(@Rowjson is not Null)
	Begin
		EXEC MySMSAudit.dbo.Usp_AuditTableDataByParentId @User_id = @UserId
			,@Activity_type = 'Updt_Convsn'
			,@ActionType = 'U'
			,@RowJson = @Rowjson
			,@Table_name = 'leadinteractionhistory'
		END
	END
end


GO

/* ============================================================
   Procedure: [dbo].[usp_followupalerts]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_followupalerts]
as
begin

select u.user_login,l.parentid,isnull(l.PersonName,'') Name,isnull(CompanyName,'') Company,isnull(MobileNo,'') + isnull(', '+nullif(MobileNo1,''),'') + isnull(', '+nullif(MobileNo2,''),'') MobileNo,isnull(emailid,'') + isnull(', '+nullif(emailid1,''),'') + isnull(', '+nullif(Emailid2,''),'') Email,cast(FollowUpDate as date) as FollowUpDate
,case when u.user_id=l.AssignedTo then u.user_login end as  AssignedTo 
,isnull(l.Remarks,'') Remarks into #temp from 
(select * from userleads 
where FollowUpDate is not null and FollowUpDate<>'') l join user_detail u on u.user_id=l.createdby 
where cast(FollowUpDate as date)=cast(getdate() as date)

select u.user_login,l.parentid,isnull(l.PersonName,'') Name,isnull(CompanyName,'') Company,isnull(MobileNo,'') + isnull(', '+nullif(MobileNo1,''),'') + isnull(', '+nullif(MobileNo2,''),'') MobileNo,isnull(emailid,'') + isnull(', '+nullif(emailid1,''),'') + isnull(', '+nullif(Emailid2,''),'') Email,cast(FollowUpDate as date) as FollowUpDate
,case when u.user_id=l.AssignedTo then u.user_login end as  AssignedTo 
,isnull(l.Remarks,'') Remarks into #temp1 from 
(select * from userleads 
where FollowUpDate is not null and FollowUpDate<>'') l join user_detail u on u.user_id=l.createdby 
where cast(FollowUpDate as date)<cast(getdate() as date)


select u.user_id,count(t.parentid) as TotalFollowups,case when r.domain like '%sms19.com%' then 'www.kit19.com' 
else r.domain end as resellerdomain,u.email as UEmail,u.User_login as
 User_login into #temp2
 from user_detail u (nolock) join #temp t on t.parentid=u.user_id
 left join reseller_detail r (nolock) on u.m_id=r.reseller_id 
 group by u.user_id,r.domain,u.email,u.user_login
 
 select u.user_id,count(t.parentid) as TotalFollowups,case when r.domain like '%sms19.com%' then 'www.kit19.com' 
else r.domain end as resellerdomain,u.email as UEmail,u.User_login as
 User_login into #temp3
 from user_detail u (nolock) join #temp1 t on t.parentid=u.user_id
 left join reseller_detail r (nolock) on u.m_id=r.reseller_id 
 group by u.user_id,r.domain,u.email,u.user_login
 
 

