CREATE   PROCEDURE [dbo].[usp_followupalerts1]  
as  
begin  
select a.user_login,a.parentid,Name,Company,MobileNo,a.Email,FollowUpDate  
,uu.user_login as AssignedTo ,Remarks into #temp from  
(select u.user_login,l.parentid,isnull(l.PersonName,'') Name,isnull(CompanyName,'') Company,isnull(MobileNo,'') + isnull(', '+nullif(MobileNo1,''),'') + isnull(', '+nullif(MobileNo2,''),'') MobileNo,isnull(emailid,'') + isnull(', '+nullif(emailid1,''),'')
 + isnull(', '+nullif(Emailid2,''),'') Email,cast(FollowUpDate as date) as FollowUpDate  
,AssignedTo   
,isnull(l.Remarks,'') Remarks from   
(select * from userleads   
where FollowUpDate is not null and FollowUpDate<>'') l join user_detail u on u.user_id=l.createdby   
where cast(FollowUpDate as date)=cast(getdate() as date)
) A  
join user_detail uu on a.AssignedTo=uu.user_id  where not exists(select 1 from tbl_subscription (nolock) t where t.userid=335 and t.emails=uu.email) 
  
select a.user_login,a.parentid,Name,Company,MobileNo,a.Email,FollowUpDate  
,uu.user_login as AssignedTo ,Remarks into #temp1 from  
(select u.user_login,l.parentid,isnull(l.PersonName,'') Name,isnull(CompanyName,'') Company,isnull(MobileNo,'') + isnull(', '+nullif(MobileNo1,''),'') + isnull(', '+nullif(MobileNo2,''),'') MobileNo,isnull(emailid,'') + isnull(', '+nullif(emailid1,''),'')
 + isnull(', '+nullif(Emailid2,''),'') Email,cast(FollowUpDate as date) as FollowUpDate  
,AssignedTo   
,isnull(l.Remarks,'') Remarks from   
(select * from userleads   
where FollowUpDate is not null and FollowUpDate<>'') l join user_detail u on u.user_id=l.createdby   
where cast(FollowUpDate as date)<cast(getdate() as date)) A  
join user_detail uu on a.AssignedTo=uu.user_id where not exists(select 1 from tbl_subscription (nolock) t where t.userid=335 and t.emails=uu.email) 
  
  
  
select u.user_id,sum(case when t.parentid is not null and t.parentid <>0 then 1 else  0 end) as TotalFollowups,sum(case when tt.parentid is not null and tt.parentid <>0 then 1 else  0 end) as TotalFollowupsOverDue,case when r.domain like '%sms19.com%' then 'www.kit19.com'   
else r.domain end as resellerdomain,u.email as UEmail,u.User_login as  
 User_login into #temp2  
 from user_detail u (nolock) left join #temp t on t.parentid=u.user_id  
 left join #temp1 tt on tt.parentid=u.user_id  
 left join reseller_detail r (nolock) on u.m_id=r.reseller_id 
 where not exists(select 1 from tbl_subscription (nolock) t where t.userid=335 and t.emails=u.email)
   
 group by u.user_id,r.domain,u.email,u.user_login  
   
 delete From #temp2 where TotalFollowups=0 and TotalFollowupsOverDue=0  
   
-- select u.user_id,count(t.parentid) as TotalFollowups,case when r.domain like '%sms19.com%' then 'www.kit19.com'   
--else r.domain end as resellerdomain,u.email as UEmail,u.User_login as  
