/* ============================================================
   Procedure: [dbo].[usp_force_run_taskid]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_force_run_taskid
as
begin
if exists (select 1 from temp_followupfailure_track where new_ownerid =0 and nullif(ownerid_force_run,0) is null and (force_run_at is null or datediff(mi,force_run_at,getdate())>2) and datediff(mi,createdon,getdate())< 15 )
begin
drop table if exists #t
select * into #t from temp_followupfailure_track where new_ownerid =0 and nullif(ownerid_force_run,0) is null and (force_run_at is null or datediff(mi,force_run_at,getdate())>2) and datediff(mi,createdon,getdate())< 15
declare @count int,@id bigint=0,@taskid bigint
select @count=count(1) from #t
while @count>0
begin
select @id=min(id) from #t where id>@id
select @taskid=taskid from #t where id=@id
exec usp_executeautomationactions @taskid
set @count=@count-1
end
end
end


GO

/* ============================================================
   Procedure: [dbo].[Usp_ForceInsert]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

 /****************************************************************************  
SP_Name        : [Usp_ForceInsert]                     
Author         : Mukesh   
Created ON     : 24/12/2009 04:30 PM        
Version        : 1  
Alter by       :         
Alter Date     :    
Location       : PelSoftLab  
SP Description : This SP is Used to Insert into MessageQueue   FROM MessageStorage 
                 and also delete from MESSAGESTORAGE        
****************************************************************************/   
CREATE   PROC [dbo].[Usp_ForceInsert]  
@User_ids varchar(100)='',  --must be int as per database --REPLY: Taking more than one User_id in the form of string seperated by (,)  
@sender_ids varchar(100) ='',  
@batch_ids varchar(100) ='',--check this batch id must be int value REPLY: Taking more than one Batch in the form of string seperated by (,)  
@mobiles varchar(100) ='' ,  
@flag int=0   
as    
BEGIN  
SET NOCOUNT ON  
Declare @SqlQ varchar(MAX) --dont use max use you can pass numbers like varchar(8000)  
  
IF @Flag=0  
 BEGIN  
  
   BEGIN TRANSACTION  
 SET @SqlQ='Insert Into MessageQueue (MessageID,Mobile,Message,SenderID,SmppID,MessageInsertDate,Priority,U_ID)  
    Select MessageID,Mobile,Message,SenderID,SmppID,MessageInsertDate,1,U_ID FROM MessageStorage WHERE U_ID in (' + @User_ids +');DELETE FROM MESSAGESTORAGE WHERE U_ID in('+ @User_ids +')'  
  
exec(@SqlQ)  
  
 IF @@ERROR <> 0  
   ROLLBACK TRANSACTION  
 ELSE  
   COMMIT TRANSACTION  
   END  
   
ELSE IF @Flag=1  
 BEGIN  
   BEGIN TRANSACTION  
 SET @SqlQ='Insert Into MessageQueue (MessageID,Mobile,Message,SenderID,SmppID,MessageInsertDate,Priority,U_ID)  
    Select MessageID,Mobile,Message,SenderID,SmppID,MessageInsertDate,1,U_ID FROM MessageStorage WHERE U_ID in (' + @User_ids +' ) AND senderid in ('+ @sender_ids +')  
    ;DELETE FROM MESSAGESTORAGE WHERE U_ID in('+ @User_ids +') AND senderid in ('+@sender_ids+')'  
print @SqlQ   
exec(@SqlQ)  
  
 IF @@ERROR <> 0  
   ROLLBACK TRANSACTION  
 ELSE  
   COMMIT TRANSACTION  
      
 END  
ELSE IF @Flag=2  
 BEGIN  
   BEGIN TRANSACTION  
 SET @SqlQ='Insert Into MessageQueue (MessageID,Mobile,Message,SenderID,SmppID,MessageInsertDate,Priority,U_ID)  
    Select MessageID,Mobile,Message,SenderID,SmppID,MessageInsertDate,1,U_ID FROM MessageStorage WHERE U_ID in (' + @User_ids +')   
    AND senderid in('+ @sender_ids +') AND MessageBatchID in('+ @batch_ids+')  
    ;DELETE FROM MESSAGESTORAGE WHERE U_ID in('+ @User_ids +') AND senderid in ('+@sender_ids+') AND MessageBatchID in('+ @batch_ids+')'  
 exec(@SqlQ)  
 IF @@ERROR <> 0  
   ROLLBACK TRANSACTION  
 ELSE  
   COMMIT TRANSACTION  
     
 END  
ELSE IF @Flag=3  
 BEGIN  
   BEGIN TRANSACTION  
 SET @SqlQ='Insert Into MessageQueue (MessageID,Mobile,Message,SenderID,SmppID,MessageInsertDate,Priority,U_ID)  
    Select MessageID,Mobile,Message,SenderID,SmppID,MessageInsertDate,1,U_ID  FROM MessageStorage WHERE U_ID in (' + @User_ids +')   
    AND senderid in ('+ @sender_ids +') AND MessageBatchID in('+ @batch_ids+') AND MOBILE in(' +@mobiles+')  
    ;DELETE FROM MESSAGESTORAGE WHERE U_ID in('+ @User_ids +') AND senderid in ('+@sender_ids+') AND MessageBatchID in('+ @batch_ids+') AND MOBILE in(' +@mobiles+')'  
print @SqlQ  
 exec(@SqlQ)  
print 'Yes'  
 IF @@ERROR <> 0  
   ROLLBACK TRANSACTION  
 ELSE  
   COMMIT TRANSACTION  
     
 END  
END  
  



