CREATE   PROCEDURE [dbo].[USP_ForgotPasswordForApp] --9717077554          
@mobile  nvarchar(50)            
as             
begin            
IF EXISTS(SELECT 'E' FROM DBO.User_Detail(NOLOCK) WHERE user_login=@Mobile)             
begin                    
select Fname,Pwd,'Password has been sent successfully on your registered mobile no.' as Msg,Mobile from User_Detail WHERE user_login=@Mobile            
end              
else            
begin             
SELECT 'Mobile Nodoes not Exist' as Msg            
end            
end 


