AS    
BEGIN 

    DECLARE @LeadgenAutoId NVARCHAR(200), @FbFormId nvarchar(255) = '';
    IF ( NOT EXISTS ( SELECT 1  FROM tbl_fb_FacebookLeadJson    WHERE LeadgenId = @LeadgenId  ) )     
    BEGIN    
  
		if(isnull(@WebhookJsonId, 0)  = 0)  
		begin  
			select top 1 @WebhookJsonId = id, @FbFormId = FbForm_Id from tbl_fb_WebhookJsonData(nolock)   
			where FbLeadgen_Id = @LeadgenId order by id desc  
		end  
		

		select @FbFormId = FbForm_Id from tbl_fb_WebhookJsonData(nolock) where id = @WebhookJsonId

		declare @FbPageId nvarchar(255), @ParentId bigint = 0;  
		select Top 1 @ParentId = ParentId from tbl_fb_FacebookPages(nolock) where FbPageId = (select top 1 FbPageId   
		from tbl_fb_WebhookJsonData(nolock) where FbLeadgen_Id = @LeadgenId   
		order by Id desc) and isActive = 1 order by Id desc  
    
		INSERT INTO tbl_fb_FacebookLeadJson ( JsonData , LeadgenId , IsProccesed , FailedReason , EnquiryId , ReceviedOn, WebhookJsonId, ParentId, FbFormId )     
		VALUES ( @JsonData , @LeadgenId , @IsProccesed , @FailedReason , @EnquiryId , @ReceviedOn, @WebhookJsonId, @ParentId, @FbFormId);    
		
		SELECT @LeadgenAutoId = SCOPE_IDENTITY();    
			
		update tbl_fb_WebhookJsonData set IsLeadIDProcessed =1,LastAttemptedToProcess=getdate(),Retries=isnull(Retries,0)+1 where FbLeadgen_Id=@LeadgenId  
		EXEC usp_ConvertLeadgenToEnquiry @LeadgenAutoId;    

	END;    
END



GO

