/* ============================================================
   Procedure: [dbo].[usp_ge_SaveSheetRule]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_ge_SaveSheetRule](
	@RuleId nvarchar(255),
	@WorkbookId nvarchar(255),
	@SheetName nvarchar(255),
	@RuleName nvarchar(255),
	@RuleJSON nvarchar(max),
	@ParentId bigint,
	@UserId bigint
)
as
begin
	
	declare @PGSAutoId bigint = 0, @GSMAutoId bigint = 0

	select @PGSAutoId = Id from tbl_ge_ParentGoogleSheets(nolock) 
		where WorkbookId = @WorkbookId and ParentId = @ParentId
	
	if(isnull(@PGSAutoId, 0) = 0)
	begin
		return;
	end

	select @GSMAutoId = Id from tbl_ge_GoogleSpreadSheetMapping(nolock) 
		where SheetName = @SheetName and WorkbookId = @WorkbookId and ParentId = @ParentId
	
	if(isnull(@GSMAutoId, 0) = 0)
	begin
		return;
	end	

	if(@RuleId > 0)
	begin
		update tbl_ge_SheetRules set
				RuleJSON = @RuleJSON,
				ModifiedBy = @UserId,
				ModifiedOn = GETDATE()
			where Id = @RuleId

	end
	else
	begin
		insert into tbl_ge_SheetRules(PGSAutoId, GSMAutoId, RuleName, RuleJSON, ParentId, CreatedBy, CreatedOn, IsActive, ModifiedBy, ModifiedOn)
			values ( @PGSAutoId, @GSMAutoId, @RuleName, @RuleJSON, @ParentId, @UserId, getdate(), 1, @UserId, GETDATE() )

		set @RuleId = SCOPE_IDENTITY();
	end

end



