/* ============================================================
   Procedure: [dbo].[usp_generate_incoming_bot_call]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_generate_incoming_bot_call
(@UniqueId nvarchar(50),@CallerId nvarchar(50), @Context nvarchar(50),@Channel nvarchar(50),@Dnid nvarchar(50),@Extension nvarchar(50),@call_logid bigint output,@botid bigint output)
as
begin
declare @kitcallid bigint,@Channelid int,@calllogid bigint
select @botid=voice_bot_id from Cloud_User_Phone(nolock) where phoneno=@Dnid

SELECT TOP 1 @Channelid=id FROM Kit19Channels WHERE ISNULL(channel_inuse, 'N') = 'N' ORDER BY ISNULL(channel_lastaccesstime, getdate()) DESC

INSERT INTO Kit19Calls(call_start_time, UniqueId,AccountCode, CallerId, CallerIdName, CallingAni2,CallingPres, CallingTns, CallingTon, Channel,
Context, Dnid, Enhanced, Extension, Language, Priority, RequestURL, channel_id)
VALUES(getdate(), @UniqueId, null, @CallerId, '', '','','','',@Channel,@Context,@Dnid,'False',
@Extension,'En',28,'',@ChannelId)
SELECT @kitcallid=scope_identity()

drop table if exists #call_logid 
create table #call_logid(call_logid bigint)



insert into #call_logid(call_logid)
exec usp_createcalllog 'kit19calls','id',@kitcallid,'Incoming'
select top 1 @calllogid=call_logid from #call_logid
select @call_logid=@calllogid
select @botid as Botid,@call_logid as CallLogId
update calllog set bot_id =@botid where id=@calllogid

end



GO

/* ============================================================
   Procedure: [dbo].[usp_GenerateActivityByRefTable]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_GenerateActivityByRefTable](
	@RefTable nvarchar(255),
	@RefTableId bigint = 0
)
as
begin

	--declare 
	--	@RefTableId bigint = 73060, 
	--	@RefTable nvarchar(255) = 'TBL_ET_PhysicalAppointment'

	declare 
		@entityname nvarchar(100), @EntityID BIGINT, @UserID BIGINT, @ParentID BIGINT, 
			@EventDescription NVARCHAR(MAX), @EventName NVARCHAR(500)

	begin try

		if(@RefTable = 'TBL_ET_PhysicalAppointment')
		begin
			declare @GeoEntityId bigint = 0, @GeoEntitySiteId bigint = 0, @CreatedBy bigint = 0, 
				@TaskTypeId bigint = 0, @UserLogin nvarchar(255), @TaskTypeTitle nvarchar(255) = '', @TaskTitle nvarchar(255) = ''

			select @TaskTitle = Title , @GeoEntitySiteId = GeoEntitySiteId, @CreatedBy = CreatedBy, @TaskTypeId = TaskTypeId, @ParentID = ParentId
				from TBL_ET_PhysicalAppointment(nolock) a where a.PhysicalAppointmentId = @RefTableId

			select @UserLogin = User_Login from User_Detail(nolock) where User_ID = @CreatedBy
			select @TaskTypeTitle = TasKName from tbl_tsk_UserTaskMaster(nolock) where id = @TaskTypeId
			select @GeoEntityId = GeoEntityId from TBL_ET_GeoEntitySiteMaster(nolock) where GeoEntitySiteId = @GeoEntitySiteId
			select @entityname = GeoEntityType, @entityId = EntityId from TBL_ET_GeoEntityMaster(nolock) where GeoEntityId = @GeoEntityId
			set @EventName = (case 
					when @entityname = 'enquiry' then 'Physical Appointment Fixed For Enquiry' 
					when @entityname = 'lead' then 'Physical Appointment Fixed For Lead' 
				else '' end )

			set @EventDescription = concat(@UserLogin, N' added Physical Appointment of type ', @TaskTypeTitle, N' with title ', @TaskTitle)
		end

		if(len(@EventName) > 0 and len(@entityId) > 0 and len(@CreatedBy) > 0 and len(@ParentID) > 0 and
			len(@EventDescription) > 0 and  len(@RefTable) > 0 and len(@RefTableId) > 0)
		begin

			exec UspSaveEntityActivity_withid @entityname, @entityId, @CreatedBy, @ParentID, @EventDescription, @EventName, @RefTable, @RefTableId	
		end

	end try
	begin catch
		exec Usp_InsertErrorInfo
	end catch

end



GO

/* ============================================================
   Procedure: [dbo].[usp_GenerateEnquiryFromCustomError]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE dbo.usp_GenerateEnquiryFromCustomError @PrentId BIGINT = 0
	,@FormName NVARCHAR(max) = ''
	,@Sourceid BIGINT = ''
	,@MediumID BIGINT = 0
	,@CampaignName BIGINT = 0
	,@entid BIGINT = 0
	,@userid BIGINT = 0
	,@PersonName NVARCHAR(max) = ''
	,@CompanyName NVARCHAR(max) = ''
	,@MobileNo NVARCHAR(max) = ''
	,@MobileNo1 NVARCHAR(max) = ''
	,@MobileNo2 NVARCHAR(max) = ''
	,@EmailID NVARCHAR(max) = ''
	,@EmailID1 NVARCHAR(max) = ''
	,@EmailID2 NVARCHAR(max) = ''
	,@City NVARCHAR(max) = ''
	,@State NVARCHAR(max) = ''
	,@Country NVARCHAR(max) = ''
	,@CountryCode NVARCHAR(max) = ''
	,@CountryCode1 NVARCHAR(max) = ''
	,@CountryCode2 NVARCHAR(max) = ''
	,@PinCode NVARCHAR(max) = ''
	,@ResidentialAddress NVARCHAR(max) = ''
	,@OfficeAddress NVARCHAR(max) = ''
	,@InitialRemarks NVARCHAR(max) = ''
	,@mail_body NVARCHAR(max) = ''
	,@msg_body NVARCHAR(max) = ''
	,@leadno BIGINT = 0
	,@EntityId BIGINT = 0
	--,@EntityName NVARCHAR(50) = ''                
	--,@AgentId BIGINT = 0                
	,@fieldvalues NVARCHAR(max) = ''
AS
BEGIN
	IF (@CountryCode = '')
	BEGIN
		SET @CountryCode = '+91'
	END

	DECLARE @mobileTemp NVARCHAR(max) = ''

	SET @mobileTemp = dbo.[fn_trimprefixes](@MobileNo, '0');
	SET @MobileNo = @mobileTemp

	DECLARE @formid BIGINT = 0;
	DECLARE @isenquery BIT = 0;
	DECLARE @EnquiryID BIGINT = 0;

	SELECT @formid = formid
		,@MediumID = MediumID
		,@Sourceid = Sourceid
		,@isenquery = isEnquiry
		,@userid = userid
	FROM WebFormTbl(NOLOCK)
	WHERE ParentId = @PrentId
		AND FormName = @FormName;

	DECLARE @SequenceNumber BIGINT = (
			SELECT ISNULL(SequenceNumber, 1)
			FROM WebFormTbl(NOLOCK)
			WHERE FormId = @formid
			)

	IF (
			EXISTS (
				SELECT 1
				FROM WebEntryTbl(NOLOCK)
				WHERE FormId = @formid
				)
			)
	BEGIN
		SET @SequenceNumber = (
				SELECT ISNULL(max(EntryNo), @SequenceNumber) + 1
				FROM WebEntryTbl(NOLOCK)
				WHERE FormId = @formid
				)
	END

	DECLARE @data NVARCHAR(max) = @fieldvalues

	DROP TABLE

	IF EXISTS #temp
		CREATE TABLE #temp (
			FieldCtrl VARCHAR(100)
			,FieldValue VARCHAR(100)
			,WebField VARCHAR(100)
			)

	INSERT INTO #temp (
		FieldCtrl
		,FieldValue
		,WebField
		)
	SELECT FieldCtrl
		,FieldValue
		,WebField
	FROM OPENJSON(@data) WITH (
			FieldCtrl VARCHAR(100) '$.lbltxt'
			,FieldValue VARCHAR(100) '$.value'
			,WebField VARCHAR(100) '$.field'
			)

	DROP TABLE

	IF EXISTS #temp2
		DECLARE @i INT = 1

	SELECT cf.*
		,(
			CASE 
				WHEN cf.datatype = 'f'
					THEN IIF(CAST(TP.FieldValue AS BIGINT) >= ISNULL(CAST(cf.minvalue AS BIGINT), - 2222222222222222)
							AND CAST(TP.FieldValue AS BIGINT) <= ISNULL(CAST(cf.maxvalue AS BIGINT), 2222222222222222), 1, 0)
				WHEN cf.datatype = 'd'
					THEN IIF(CAST(TP.FieldValue AS DATE) >= CAST(ISNULL(cf.minvalue, '') AS DATE)
							AND CAST(TP.FieldValue AS DATE) <= IIF(ISNULL(cf.maxvalue, '') <> '', cast(cf.maxvalue AS DATE), cast('9999-01-01' AS DATE)), 1, 0)
				WHEN cf.datatype IN (
						'r'
						,'s'
						,'l'
						)
					AND cf.choices IS NOT NULL
					THEN IIF(@i = (
								SELECT DISTINCT 1
								FROM dbo.fn_Split(cf.choices, ',')
								WHERE CAST(TP.FieldValue AS NVARCHAR(max)) = value
								), 1, 0)
				WHEN cf.datatype IN (
						'r'
						,'s'
						,'l'
						)
					AND cf.choices IS NULL
					THEN 1
				WHEN cf.datatype IN (
						'm'
						,'c'
						,'v'
						)
					THEN 1
				ELSE 0
				END
			) AS [status]
		,FieldCtrl
	INTO #temp2
	FROM #temp tp(NOLOCK)
	--join tbl_CustomFieldWebFormFieldMapping cfwf (nolock) on  tp.FieldCtrl = cfwf.CtrlName            
	JOIN customfields cf(NOLOCK) ON cast(cf.field_ID AS VARCHAR) = cast(tp.WebField AS VARCHAR)

	--where  cfwf.WebFormId = @formid                
	--AND cfwf.ParentId = @prentid                
	IF EXISTS (
			SELECT DISTINCT 1
			FROM #temp2
			WHERE STATUS = 0
			)
	BEGIN
		SELECT (
				CASE datatype
					WHEN 'd'
						THEN FieldCtrl + ' - Date not in Custom Field Range'
					WHEN 'f'
						THEN FieldCtrl + ' - Number not in Custom Field Range'
					WHEN 'r'
						THEN FieldCtrl + ' - Value not matches with Custom Field Choices'
					WHEN 's'
						THEN FieldCtrl + ' - Value not matches with Custom Field Choices'
					WHEN 'c'
						THEN FieldCtrl + ' - Value not matches with  Custom Field Choices'
					WHEN 'l'
						THEN FieldCtrl + ' - Value not matches with Custom Field Choices'
					ELSE 'Wrong Input Value'
					END
				) AS [Error Message]
		FROM #temp2
		WHERE STATUS = 0
	END
			-----------------------------------------------------------------------------------------------------------------------------------------------                
	ELSE
	BEGIN
		IF (@EntityId = 0)
		BEGIN
			--if (@isenquery =1 and @entid > 0)                                                     
			IF (
					@isenquery = 1
					AND @entid > 0
					)
			BEGIN
				DECLARE @leadn VARCHAR(max) = ''

				IF @leadno = 0
				BEGIN
					IF EXISTS (
							SELECT 1
							FROM UserLeads_mobile_email(NOLOCK)
							WHERE ParentID = @PrentId
								AND (
									(
										@MobileNo <> ''
										AND isnull(nullif(@MobileNo, ''), '1') = Mobile
										AND @CountryCode <> ''
										AND isnull(nullif(@CountryCode, ''), '3') = CountryCode
										)
									OR (
										@EmailID <> ''
										AND isnull(nullif(@Emailid, ''), '2') = Email
										)
									)
							)
					BEGIN
						SELECT TOP 1 @leadno = leadno
						FROM UserLeads_mobile_email(NOLOCK)
						WHERE ParentID = @PrentId
							AND (
								(
									@MobileNo <> ''
									AND isnull(nullif(@MobileNO, ''), '1') = Mobile
									AND @CountryCode <> ''
									AND isnull(nullif(@CountryCode, ''), '3') = CountryCode
									)
								OR (
									@EmailID <> ''
									AND isnull(nullif(@EmailID, ''), '2') = Email
									)
								)
						ORDER BY leadno
					END
				END

				INSERT INTO UserEnquiry (
					PersonName
					,CompanyName
					,MobileNo
					,MobileNo1
					,MobileNo2
					,EmailID
					,EmailID1
					,EmailID2
					,City
					,STATE
					,Country
					,CountryCode
					,CountryCode1
					,CountryCode2
					,PinCode
					,ResidentialAddress
					,OfficeAddress
					,InitialRemarks
					,SourceName
					,MediumName
					,CampaignName
					,ParentID
					,CreatedDate
					,CreatedBy
					,LeadNo
					,enquirysource
					)
				VALUES (
					@PersonName
					,@CompanyName
					,@MobileNo
					,@MobileNo1
					,@MobileNo2
					,@EmailID
					,@EmailID1
					,@EmailID2
					,@City
					,@State
					,@Country
					,@CountryCode
					,@CountryCode1
					,@CountryCode2
					,@PinCode
					,@ResidentialAddress
					,@OfficeAddress
					,@InitialRemarks
					,@Sourceid
					,@MediumID
					,@CampaignName
					,@PrentId
					,GETDATE()
					,@userid
					,@leadno
					,9
					)

				SET @EnquiryID = SCOPE_IDENTITY()

				INSERT INTO ParsedEnquiries (
					RawEnquiryId
					,EnquiryId
					,Parentid
					,Createddate
					,EnquirySource
					)
				SELECT @entid
					,@EnquiryID
					,@PrentId
					,getdate()
					,'Webform'

				UPDATE WebEntryTbl
				SET enqueryId = @EnquiryID
				WHERE EntryId = @entid

				INSERT INTO customfieldEnquiryvalue (
					EnquiryID
					,fieldID
					,fieldvalue
					)
				SELECT @EnquiryID
					,cfwf.FieldId
					,tp.FieldValue
				FROM #temp tp
					,tbl_CustomFieldWebFormFieldMapping cfwf
				WHERE tp.FieldCtrl = cfwf.CtrlName
					AND cfwf.WebFormId = @formid
					AND cfwf.ParentId = @PrentId

				UPDATE Errorlogcustomfield
				SET Active = 0
				WHERE EntryId = @entid

				DECLARE @AutoLeadDistribution BIT

				SELECT @AutoLeadDistribution = AutoLeadDistribution
				FROM CRMCampaignSettings(NOLOCK)
				WHERE UserID = @PrentId

				IF (
						@AutoLeadDistribution = 1
						AND @leadno = 0
						)
				BEGIN
					SELECT @Leadno = isnull((
								SELECT MAX(LeadNo)
								FROM UserLeads(NOLOCK)
								WHERE ParentID = @PrentId
								), 0) + 1

					INSERT INTO userleads (
						LeadNo
						,PersonName
						,MobileNo
						,EmailID
						,City
						,PinCode
						,CountryCode
						,OfficeAddress
						,AssignedTo
						,SourceName
						,MediumName
						,CampaignName
						,ParentID
						,Remarks
						,CreatedOn
						,CreatedBy
						,--FollowUpStatus,NextStatusDate,FollowupDate,                  
						enquirysource
						)
					SELECT @leadno
						,@personname
						,@MobileNo
						,@EmailID
						,''
						,''
						,@CountryCode
						,@ResidentialAddress
						,(
							SELECT TOP 1 value
							FROM fn_Split((
										SELECT agents
										FROM CRMCampaignSettings
										WHERE userid = @PrentId
										), '#')
							ORDER BY NEWID()
							)
						,@Sourceid
						,@MediumID
						,''
						,@PrentId
						,@InitialRemarks
						,GETDATE()
						,@PrentId
						,--1,GETDATE(),GETDATE(),                  
						9

					DECLARE @leadid BIGINT = SCOPE_IDENTITY()

					UPDATE UserEnquiry
					SET LeadNo = @LeadNo
						,IsOpen = 1
					WHERE EnquiryID = @EnquiryID

					INSERT INTO customfieldLeadvalue (
						LeadID
						,fieldID
						,fieldvalue
						)
					SELECT @leadid
						,cfwf.FieldId
						,tp.FieldValue
					FROM #temp tp
						,tbl_CustomFieldWebFormFieldMapping cfwf
					WHERE tp.FieldCtrl = cfwf.CtrlName
						AND cfwf.WebFormId = @formid
						AND cfwf.ParentId = @PrentId

					EXEC Usp_insertdefaultfollowup @prentid
						,@leadid

					INSERT INTO tbl_MergeLeadsEnquiry (
						EnquiryNo
						,LeadNo
						,IsOpen
						)
					VALUES (
						@EnquiryID
						,@Leadno
						,1
						)
				END
			END

			IF (@entid > 0)
			BEGIN
				IF (
						@isenquery = 0
						AND @MobileNo <> ''
						)
				BEGIN
					EXEC [Usp_insertDeliverySMS_WebFrom] @entid
						,@FormId
						,@msg_body
				END

				IF (
						@isenquery = 0
						AND @EmailID <> ''
						)
				BEGIN
					EXEC [Usp_insertDeliveryMails_WebFrom] @entid
						,@FormId
						,@mail_body
				END
			END
		END
		ELSE
		BEGIN
			SET @leadno = (
					SELECT LeadNo
					FROM UserLeads(NOLOCK)
					WHERE ID = @EntityId
					)
		END

		SELECT 'Enquiry Generated' AS [Message]
	END

	DECLARE @rowJson VARCHAR(MAX) = (
			SELECT *
			FROM UserEnquiry(NOLOCK)
			WHERE EnquiryID = @EnquiryID
			FOR JSON AUTO
				,INCLUDE_NULL_VALUES
			)

	IF @rowJson IS NOT NULL
	BEGIN
		EXEC MySmsAudit.dbo.Usp_AuditTableDataByParentId @User_id = @userid
			,@Activity_type = 'Inst_enry_weberr'
			,@ActionType = 'I'
			,@RowJson = @rowJson
			,@Table_name = 'UserEnquiry'
	END
END



GO

/* ============================================================
   Procedure: [dbo].[usp_get_agent_kb]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_get_agent_kb --19
@agentid bigint
as
begin

select t.agentid,t.name as agentname,c.title,c.category,c.content,  c.DetailsJson
from tbl_ai_Agents(nolock) t 
join tbl_ai_AgentKnowledgeBase k on t.AgentId=k.agentid
join tbl_ai_KnowledgeBase c on c.kbid=k.kbId
where predefined_agentid=2 and t.status='active' and [dbo].[fn_parent_hasactivesubscription](t.parentid)=1

end



