/* ============================================================
   Procedure: [dbo].[usp_Get_All_Activities]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_Get_All_Activities] --41181
@parentid bigint
as
begin
select leadid lead_id,eventdate event_date,event event_name,u.Description event_description,isnull(Score,0) event_score 
from 
(
select t.leadid,eventdate,a.eventname as event,t.EventDescription Description,isnull(l.ScoreAdded,0) as score from tbl_leadeventhistory(nolock) t 
join activitymaster(nolock) a on a.id=t.eventid
left join lead_score_history (nolock) l on l.lead_activity_id=t.Historyid where eventdate<= isnull(dbo.fn_getfirstenrollment(t.leadid),getdate())

) u 
join userleads (nolock) p on p.id=u.leadid 
where p.parentid=@parentid and
dbo.fn_getfirstenrollment(p.id) is not null 

end



