/* ============================================================
   Procedure: [dbo].[usp_get_allleads]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE [dbo].[usp_get_allleads]
@parentid bigint
as
begin
SELECT 
        p.id as lead_id,
        i.Name lead_source,
        --i.name lead_industry,
        p.CreatedOn lead_added_date,
        dbo.fn_getfirstenrollment(p.id) first_conversion_date,
        dbo.fn_getscorebeforenrollment(p.id) AS lead_cumulative_score_before_first_conversion,
        isnull(no_of_followups,0) AS total_followups_before_first_conversion,
        isnull(no_of_activities,0) AS total_activities_before_first_conversion,
        DATEDIFF(DAY, LastFollowupDate, GETDATE()) AS days_since_last_followup,
        DATEDIFF(DAY, LastActivityDate, GETDATE()) AS days_since_last_activity,
        CASE 
            WHEN dbo.fn_getfirstenrollment(p.id) IS NOT NULL THEN 1 
            ELSE 0 
        END AS is_converted
    FROM userleads p (nolock) 
	left join UserSourceSettings i (nolock) on i.SourceID=p.SourceName 
	left join (select id_lead,count(1) no_of_followups,max(cast(CreatedOn as date)) LastFollowupDate from leadinteractionhistory(nolock) where 
	cast(CreatedOn as date)<=isnull(dbo.[fn_getfirstenrollment](id_lead),getdate()) group by id_lead) f on f.id_lead=p.id
	left join (select leadid,count(1) as no_of_activities,max(cast(eventdate as date)) LastActivityDate from tbl_leadeventhistory(nolock) where 
	cast(eventdate as date)<isnull(dbo.[fn_getfirstenrollment](leadid),getdate()) group by leadid
	) u on u.leadid=p.id
	where p.parentid=@parentid
	

end



GO

/* ============================================================
   Procedure: [dbo].[usp_get_bot_webhooks]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


-- -----------------------------------------------------------------------------
-- 2) usp_get_bot_webhooks - return all enabled webhooks for a bot.
--    Joins webhook_definition + bot_webhook_mapping. One row per mapping.
--    Column names MUST match what SqlApiClient.ParseWebhookConfig reads.
-- -----------------------------------------------------------------------------
CREATE   PROCEDURE usp_get_bot_webhooks
    @bot_type VARCHAR(20),
    @bot_id   BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        d.webhook_id                AS webhook_id,
        m.bot_id                    AS bot_id,
        d.version                   AS version,
        m.webhook_slug              AS webhook_slug,
        d.description               AS description,
        m.is_enabled                AS is_enabled,
        m.trigger_type              AS trigger_type,
        m.trigger_config            AS trigger_config,
        d.http_method               AS http_method,
        d.url_template              AS url_template,
        d.query_template            AS query_template,
        d.header_template           AS header_template,
        d.body_template             AS body_template,
        d.auth_type                 AS auth_type,
        d.auth_config               AS auth_config,
        d.secret_ref                AS secret_ref,
        m.llm_parameters            AS llm_parameters,
        m.response_mode             AS response_mode,
        d.extract_slots             AS extract_slots,
        d.response_shaping          AS response_shaping,
        m.prompt_template           AS prompt_template,
        d.timeout_ms                AS timeout_ms,
        d.max_response_size_bytes   AS max_response_size_bytes,
        m.filler_while_waiting      AS filler_while_waiting,
        m.on_error_strategy         AS on_error_strategy,
        m.on_error_fallback_message AS on_error_fallback_message,
        d.is_idempotent             AS is_idempotent,
        m.confirmation_required     AS confirmation_required,
        d.retry_max_attempts        AS retry_max_attempts,
        d.retry_base_delay_ms       AS retry_base_delay_ms,
        d.extract_on_error          AS extract_on_error
    FROM bot_webhook_mapping m
    INNER JOIN webhook_definition d
        ON d.webhook_id = m.webhook_id
    WHERE m.bot_type   = @bot_type
      AND m.bot_id     = @bot_id
      AND m.is_enabled = 1
      AND m.deleted_on IS NULL
      AND d.deleted_on IS NULL
    ORDER BY m.webhook_slug;
END



GO

