   Procedure: [dbo].[usp_get_consumption_pattern]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC usp_get_consumption_pattern --2    
@Diff int    
as    
select user_id,balance into #temp from credit_details where credit_id in(select max(credit_id) from credit_details group by user_id)    
select distinct c.user_id,filtermode,userfilter,sum(debits) as SMSsent,user_login,t.balance from credit_details c join user_detail u on c.user_id=u.user_id join #temp t on u.user_id=t.user_id where datediff(d,c.DateUpdated,getdate())<=@Diff and c.user_id = c.fromuser_id group   
by c.user_id,u.user_login,t.balance,u.FilterMode,u.userfilter order by sum(debits) desc    
drop table #temp


