/* ============================================================
   Procedure: [dbo].[USP_Get_Custom_Enquiry]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[USP_Get_Custom_Enquiry]
 @enq bigint    
AS    
BEGIN    
  SET NOCOUNT ON;    
    
	--declare @enq bigint = 4583625

	drop table if exists #tpCF

	declare @ParentId bigint = 0;
	select @ParentId = ParentID from UserEnquiry(nolock) where EnquiryID = @enq

	select * into #tpCF from customfields(nolock) 
		where ParentID = @parentID and isActive = 1
  
    SELECT [c].[field_ID], [c].[ParentID], [c].[fieldname], (CASE [c].[datatype] 
		WHEN 'd' THEN 'Date' WHEN 'f' THEN 'Numeric'
		WHEN 'v' THEN 'Text' WHEN 'r' THEN 'Radio' WHEN 'm' THEN 'Multiline' WHEN 's' THEN 'Select'
		WHEN 'c' THEN 'Checkbox' WHEN 'e' THEN 'Expression' WHEN 'l' THEN 'List'
		END) AS [datatype],  [c].[sequence], 
		minvalue = CASE [c].[datatype] WHEN 'd'
            THEN IIF([c].[minvalue] = '0', '01-JAN-1900',  FORMAT(CAST (ISNULL([c].[minvalue], '01/01/1900') AS DATETIME), 'dd-MMM-yyyy' ))
                WHEN 'f' THEN ISNULL([c].[minvalue], -2222222222222222)
                WHEN 'v' THEN ISNULL([c].[minvalue], '')
                ELSE [c].[minvalue] END, 
        maxvalue = CASE [c].[datatype] WHEN 'd'
            THEN IIF([c].[maxvalue] = '0', '01-JAN-9999', FORMAT(CAST (ISNULL([c].[maxvalue], '01/01/9999') 
				AS DATETIME), 'dd-MMM-yyyy' ))
            WHEN 'f' THEN ISNULL([c].[maxvalue], 2222222222222222)
            WHEN 'v' THEN ISNULL([c].[maxvalue], '')
            ELSE [c].[maxvalue] END, 
        [c].[addedon], [c].[isActive], [c].[isMandatory], [c].[quickAdd], 
        defaultValue = CASE [c].[datatype] WHEN 'd'
            THEN IIF([c].[defaultValue] = '0', NULL, FORMAT(CAST ([c].[defaultValue] AS DATETIME), 'dd-MMM-yyyy' ))
			ELSE [c].[defaultValue] END, 
        [c].[currentDate], [c].[tooltip], [c].[choices], f.name AS [ExpressionName], 
		[c].[ParentFieldId],
		(
			select STRING_AGG(p.field_ID, ',') from #tpCF p where p.ParentFieldId = c.field_ID
		) as [ChildFieldId],
		d.fieldvalue,
		c.DependencyJson
		FROM  #tpCF c 
		left JOIN tbl_Formulas(NOLOCK) f ON c.formulaId = f.id
		left join ( select recordID, EnquiryID, fieldID, fieldvalue 
			from customfieldEnquiryvalue(nolock) where EnquiryID = @enq
		) d  on c.field_ID = d.fieldID
	ORDER BY [c].[sequence] ASC;
END 



GO

/* ============================================================
   Procedure: [dbo].[USP_Get_Custom_Fields]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[USP_Get_Custom_Fields] @parentID BIGINT  
AS  
    BEGIN  
        SET NOCOUNT ON;    
        --declare @parentID bigint = 34594    
        SELECT [field_ID],   
               [ParentID],   
               [fieldname],   
               (CASE datatype  
                    WHEN 'd'  
                    THEN 'Date'  
                    WHEN 'f'  
                    THEN 'Numeric'  
                    WHEN 'v'  
                    THEN 'Text'  
                    WHEN 'r'  
                    THEN 'Radio'  
                    WHEN 'm'  
                    THEN 'Multiline'  
                    WHEN 's'  
                    THEN 'Select'  
                    WHEN 'c'  
                    THEN 'Checkbox'  
                    WHEN 'e'  
                    THEN 'Expression'  
                    WHEN 'l'  
                    THEN 'List'  
                END) AS [datatype],   
               [sequence],   
               [minvalue] = CASE [datatype]  
                                WHEN 'd'  
                                THEN IIF([minvalue] IN('0', ''), '01/01/1900', ISNULL([minvalue], '01/01/1900'))  
                                WHEN 'f'  
                                THEN ISNULL([minvalue], -2222222222222222)  
                                WHEN 'v'  
                                THEN ISNULL([minvalue], '')  
                                ELSE [minvalue]  
                            END,   
               [maxvalue] = CASE [datatype]  
                                WHEN 'd'  
                                THEN IIF([maxvalue] IN('0', ''), '01/01/9999', ISNULL([maxvalue], '01/01/9999'))  
                                WHEN 'f'  
                                THEN ISNULL([maxvalue], 2222222222222222)  
                                WHEN 'v'  
                                THEN ISNULL([maxvalue], '')  
                                ELSE [maxvalue]  
                            END,   
               [addedon],   
               [isActive],   
               [isMandatory],   
               [defaultValue],   
               isnull([currentDate], 0) as [currentDate],
               tooltip,   
               choices,   
        (  
            SELECT m.id,   
                   m.fParamId,   
                   m.ParamName,   
                   m.ParamType,   
                   m.ParamValue,   
                   m.fieldId  
            FROM tbl_customFieldFormulaParamMapping(NOLOCK) m  
            WHERE m.fieldId = c.field_ID FOR JSON PATH  
        ) AS [ParamList]    
        -- FROM [customfields] where [ParentID]=@parentID and [isActive]='True' and ([quickAdd]='True' or [isMandatory]=1)    
        FROM [customfields](NOLOCK) c  
        WHERE [ParentID] = @parentID  
              AND [isActive] = 'True'  
              AND ([c].[quickAdd] = 'True'  
                   OR [c].[isMandatory] = 1  
                   OR [c].[isMandatory] = 0)  
        ORDER BY [sequence] ASC;  
    END;  



GO

/* ============================================================
   Procedure: [dbo].[USP_Get_Custom_Fields_all]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[USP_Get_Custom_Fields_all] @parentID BIGINT
AS
BEGIN

	--DECLARE 
	--	@parentID BIGINT = 34594

	drop table if exists #tpCF

	select * into #tpCF from customfields(nolock) 
		where ParentID = @parentID and isActive = 1

    SELECT [c].[field_ID], [c].[ParentID], [c].[fieldname], (CASE [c].[datatype] 
			WHEN 'd' THEN 'Date' WHEN 'f' THEN 'Numeric'
			WHEN 'v' THEN 'Text' WHEN 'r' THEN 'Radio' WHEN 'm' THEN 'Multiline' WHEN 's' THEN 'Select'
			WHEN 'c' THEN 'Checkbox' WHEN 'e' THEN 'Expression' WHEN 'l' THEN 'List'
			END) AS [datatype],  [c].[sequence], 
			minvalue = CASE [c].[datatype] WHEN 'd'
                THEN IIF([c].[minvalue] = '0', '01-JAN-1900',  FORMAT(CAST (ISNULL([c].[minvalue], '01/01/1900') AS DATETIME), 'dd-MMM-yyyy' ))
                    WHEN 'f' THEN ISNULL([c].[minvalue], -2222222222222222)
                    WHEN 'v' THEN ISNULL([c].[minvalue], '')
                    ELSE [c].[minvalue] END, 
            maxvalue = CASE [c].[datatype] WHEN 'd'
                THEN IIF([c].[maxvalue] = '0', '01-JAN-9999', FORMAT(CAST (ISNULL([c].[maxvalue], '01/01/9999') 
					AS DATETIME), 'dd-MMM-yyyy' ))
                WHEN 'f' THEN ISNULL([c].[maxvalue], 2222222222222222)
                WHEN 'v' THEN ISNULL([c].[maxvalue], '')
                ELSE [c].[maxvalue] END, 
            [c].[addedon], [c].[isActive], [c].[isMandatory], [c].[quickAdd], 
            
			defaultValue = CASE 
				WHEN [c].[datatype] = 'd' 
					THEN IIF([c].[defaultValue] = '0', NULL, FORMAT(CAST ([c].[defaultValue] AS DATETIME), 'dd-MMM-yyyy' ))
				WHEN [c].[datatype] = 'v'  
					THEN IIF([c].[defaultValue] = '0', '', [c].[defaultValue] )
				ELSE [c].[defaultValue] END,
				

            isnull([c].[currentDate], 0) as [currentDate], [c].[tooltip], [c].[choices], f.name AS [ExpressionName], 
			[c].[ParentFieldId],
			(
				select STRING_AGG(p.field_ID, ',') from #tpCF p where p.ParentFieldId = c.field_ID
			) as [ChildFieldId],
			(
				SELECT m.id, m.fParamId, m.ParamName, m.ParamType, m.ParamValue, m.fieldId
					FROM tbl_customFieldFormulaParamMapping(NOLOCK) m WHERE m.fieldId = [c].[field_ID] FOR JSON PATH
			) AS [ParamList]
    FROM #tpCF c
            left JOIN tbl_Formulas(NOLOCK) f ON c.formulaId = f.id
    WHERE [c].[ParentID] = @parentID
            AND c.isActive <> 0
    ORDER BY [c].[sequence] ASC;
END;



GO

/* ============================================================
   Procedure: [dbo].[USP_Get_Custom_Fields_all_ForCreationPage]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON




CREATE   PROCEDURE [dbo].[USP_Get_Custom_Fields_all_ForCreationPage] --36950
	@parentID BIGINT,
	@status nvarchar(50)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT [field_ID], 
            [ParentID], 
            [fieldname], 
			
            (CASE datatype
                WHEN 'd'
                THEN 'Date Field'
                WHEN 'f'
                THEN 'Numeric Field'
                WHEN 'v'
                THEN 'Text Field'
                WHEN 'r'
                THEN 'Radio Field'
                WHEN 'm'
                THEN 'MultiLine Field'
                WHEN 's'
                THEN 'Dropdown Field'
                WHEN 'c'
                THEN 'Checkbox Field'
                WHEN 'e'
                THEN 'Formula Field'
                WHEN 'l'
                THEN 'Multiple Select Field'
            END) AS [datatype], 
            [sequence], 
            [minvalue] = CASE [datatype]
                            WHEN 'd'
                            THEN IIF([minvalue] = '0', '01/01/1900', ISNULL([minvalue], '01/01/1900'))
                            WHEN 'f'
                            THEN ISNULL([minvalue], -2222222222222222)
                            WHEN 'v'
                            THEN ISNULL([minvalue], '')
                            ELSE [minvalue]
                        END, 
            [maxvalue] = CASE [datatype]
                            WHEN 'd'
                            THEN IIF([maxvalue] = '0', '01/01/9999', ISNULL([maxvalue], '01/01/9999'))
                            WHEN 'f'
                            THEN ISNULL([maxvalue], 2222222222222222)
                            WHEN 'v'
                            THEN ISNULL([maxvalue], '')
                            ELSE [maxvalue]
                        END, 
            [addedon], 
            [isActive], 
            [isMandatory], 
            [quickAdd], 
            [defaultValue] = CASE [datatype]
                                WHEN 'd'
                                THEN IIF([defaultValue] = '0', NULL, [defaultValue])
                                ELSE [defaultValue]
                            END, 
            [currentDate], 
            [tooltip], 
            [choices]
			,ParentFieldId,isnull(STUFF((SELECT ', ' + fieldname
              FROM customfields o2
              WHERE o2.ParentFieldId = o1.field_ID and ParentFieldId<>0
              FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, ''),'') AS Parent ,

			 isnull(( SELECT  fieldname FROM customfields o2
              WHERE o2.field_ID = o1.ParentFieldId --and ParentFieldId<>0
              ),'') AS Child  FROM [customfields](NOLOCK) o1
     WHERE [ParentID] = @parentID and isActive =@status
    ORDER BY [sequence] ASC;
END



GO

/* ============================================================
   Procedure: [dbo].[USP_Get_Custom_Fields_one]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE [dbo].[USP_Get_Custom_Fields_one] @parentID BIGINT, 
                                                        @fieldID  BIGINT
AS
declare @PDependencyJson nvarchar(max),@ParentofChildfield bigint,@ParentofChildfieldName nvarchar(max),@ParentofChildfieldID nvarchar(max),@ChildofParentfieldNameid bigint,@ChildofParentfieldName nvarchar(max)
--set @PDependencyJson=(select DependencyJson from customfields where ParentFieldId=@fieldID)
--set @ParentofChildfield=(select field_ID from customfields where ParentFieldId=@fieldID)
set @ParentofChildfieldName=(select distinct STUFF((SELECT ', ' + fieldname
              FROM customfields o2
              WHERE o2.ParentFieldId = o1.ParentFieldId
              FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS Products FROM customfields o1
        WHERE  ParentFieldId = @fieldID)

		SELECT @ParentofChildfieldID = STUFF((SELECT ', ' + CAST(field_ID AS NVARCHAR(MAX))
                                     FROM customfields o2
                                     WHERE o2.ParentFieldId = o1.ParentFieldId
                                     FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, '')
         FROM customfields o1
         WHERE ParentFieldId = @fieldID;


set @ChildofParentfieldNameid=(select ParentFieldId from customfields where field_ID=@fieldID)
set @ChildofParentfieldName=(select fieldname from customfields where field_ID=@ChildofParentfieldNameid)
    BEGIN
        SET NOCOUNT ON;
        SELECT field_ID, 
               ParentID, 
               fieldname,
               CASE datatype
                   WHEN 'd'
                   THEN 'Date'
                   WHEN 'f'
                   THEN 'Numeric'
                   WHEN 'v'
                   THEN 'Text'
                   WHEN 'r'
                   THEN 'Radio'
                   WHEN 'm'
                   THEN 'Multiline'
                   WHEN 's'
                   THEN 'Select'
                   WHEN 'c'
                   THEN 'Checkbox'
                   WHEN 'e'
                   THEN 'Expression'
                   WHEN 'l'
                   THEN 'List'
               END AS datatype, 
			    CASE datatype
                   WHEN 'd'
                THEN 'Date Field'
                WHEN 'f'
                THEN 'Numeric Field'
                WHEN 'v'
                THEN 'Text Field'
                WHEN 'r'
                THEN 'Radio Field'
                WHEN 'm'
                THEN 'MultiLine Field'
                WHEN 's'
                THEN 'Dropdown Field'
                WHEN 'c'
                THEN 'Checkbox Field'
                WHEN 'e'
                THEN 'Formula Field'
                WHEN 'l'
                THEN 'Multiple Select Field'
           END AS datatype1,
               [sequence], 
               minvalue, 
               maxvalue, 
               addedon, 
               isActive, 
               isMandatory, 
               defaultValue, 
               quickAdd, 
               currentDate, 
               tooltip, 
               choices, 
               formulaId,@PDependencyJson as PDependencyJson,
			   @ParentofChildfield as ParentofChildfield,
			   @ParentofChildfieldName as ParentofChildfieldName,
			   @ParentofChildfieldID as ParentofChildfieldID,
			   @ChildofParentfieldName as ChildofParentfieldName,
			   @ChildofParentfieldNameid as ChildofParentfieldNameid
        FROM customfields
        WHERE ParentID = @parentID
              AND field_ID = @fieldID
        ORDER BY [sequence] ASC;
    END;   


