   Procedure: [dbo].[USP_Get_Custom_leads]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE [dbo].[USP_Get_Custom_leads]  
 @leads bigint  
AS  
BEGIN  
  SET NOCOUNT ON;  

  	drop table if exists #tpCF

	declare @ParentId bigint = 0;
	select @ParentId = ParentID from UserLeads(nolock) where ID = @leads

	select * into #tpCF from customfields(nolock) 
		where ParentID = @parentID and isActive = 1
  
    SELECT [c].[field_ID], [c].[ParentID], [c].[fieldname], (CASE [c].[datatype] 
		WHEN 'd' THEN 'Date' WHEN 'f' THEN 'Numeric'
		WHEN 'v' THEN 'Text' WHEN 'r' THEN 'Radio' WHEN 'm' THEN 'Multiline' WHEN 's' THEN 'Select'
		WHEN 'c' THEN 'Checkbox' WHEN 'e' THEN 'Expression' WHEN 'l' THEN 'List'
		END) AS [datatype],  [c].[sequence], 
		minvalue = CASE [c].[datatype] WHEN 'd'
            THEN IIF([c].[minvalue] = '0', '01-JAN-1900',  FORMAT(CAST (ISNULL([c].[minvalue], '01/01/1900') AS DATETIME), 'dd-MMM-yyyy' ))
                WHEN 'f' THEN ISNULL([c].[minvalue], -2222222222222222)
                WHEN 'v' THEN ISNULL([c].[minvalue], '')
                ELSE [c].[minvalue] END, 
        maxvalue = CASE [c].[datatype] WHEN 'd'
            THEN IIF([c].[maxvalue] = '0', '01-JAN-9999', FORMAT(CAST (ISNULL([c].[maxvalue], '01/01/9999') 
				AS DATETIME), 'dd-MMM-yyyy' ))
            WHEN 'f' THEN ISNULL([c].[maxvalue], 2222222222222222)
            WHEN 'v' THEN ISNULL([c].[maxvalue], '')
            ELSE [c].[maxvalue] END, 
        [c].[addedon], [c].[isActive], [c].[isMandatory], [c].[quickAdd], 
        defaultValue = CASE [c].[datatype] WHEN 'd'
            THEN IIF([c].[defaultValue] = '0', NULL, FORMAT(CAST ([c].[defaultValue] AS DATETIME), 'dd-MMM-yyyy' ))
			ELSE [c].[defaultValue] END, 
        [c].[currentDate], [c].[tooltip], [c].[choices], f.name AS [ExpressionName], 
		[c].[ParentFieldId],
		(
			select STRING_AGG(p.field_ID, ',') from #tpCF p where p.ParentFieldId = c.field_ID
		) as [ChildFieldId],
		d.fieldvalue,
		c.DependencyJson
		FROM  #tpCF c 
		left JOIN tbl_Formulas(NOLOCK) f ON c.formulaId = f.id
		left join ( select recordID, LeadID, EnquiryID, fieldID, fieldvalue, CreatedDate 
			from customfieldLeadvalue(nolock) where LeadID = @leads 
		) d  on c.field_ID = d.fieldID
	ORDER BY [c].[sequence] ASC;
END  
--GO;



GO

/* ============================================================
   Procedure: [dbo].[usp_get_daily_operator_status]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC [dbo].[usp_get_daily_operator_status] --'17-03-2017','20-03-2017'
@FromDate varchar(20),
@ToDate varchar(20)
as
select 
isnull(sum(CustSentPro),0) TotalSentPro,
isnull(sum(CustSentTr),0) TotalSentTr,
isnull(sum(CustSentTrc),0)TotalSentTRC,
isnull(sum(CustSentCritical),0)TotalSentCritical,
isnull(sum(CustSentKitever),0) TotalSentKitever,
isnull(sum(VfSentPro),0)VfSentPro,isnull(sum(VfSentTr),0)VfSentTr,
isnull(sum(VfSentTRC),0)VfSentTRC,isnull(sum(VfSentCritical),0)VfSentCritical,isnull(sum(VfSentKitever),0)VfSentKitever,
isnull(sum(SpiceSentPro),0)SpiceSentPro,isnull(sum(SpiceSentTr),0)SpiceSentTr,isnull(sum(SpiceSentTRC),0)SpiceSentTRC,
isnull(sum(SpiceSentCritical),0)SpiceSentCritical,isnull(sum(SpiceSentKitever),0)SpiceSentKitever,isnull(sum(VfDeliveredPro),0)VfDeliveredPro,
isnull(sum(VfDeliveredTr),0)VfDeliveredTr,isnull(sum(VfDeliveredTRC),0)VfDeliveredTRC,isnull(sum(VfDeliveredCritical),0)VfDeliveredCritical,
isnull(sum(VfDeliveredKitever),0)VfDeliveredKitever,isnull(sum(SpiceDeliveredPro),0)SpiceDeliveredPro,isnull(sum(SpiceDeliveredTr),0)SpiceDeliveredTr,
isnull(sum(SpiceDeliveredTRC),0)SpiceDeliveredTRC,isnull(sum(SpiceDeliveredCritical),0)SpiceDeliveredCritical,
isnull(sum(SpiceDeliveredKitever),0)SpiceDeliveredKitever from daily_operator_status(nolock) where convert(nvarchar,convert(datetime,CreatedDate,103),112) between convert(nvarchar,convert(datetime,@FromDate,103),112) and convert(nvarchar,convert(datetime,@ToDate,103),112)


GO

/* ============================================================
   Procedure: [dbo].[usp_get_daily_operator_status2]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC [dbo].[usp_get_daily_operator_status2] --'17/03/2017','20/03/2017'    
as  
declare @FromDate varchar(20)    
declare @ToDate varchar(20)    
set @FromDate = Convert(varchar,dateadd(dd,-1,GETDATE()),103)  
set @ToDate = Convert(varchar,dateadd(dd,-1,GETDATE()),103)  
declare @startmonth varchar(20)  
declare @monthend varchar(20)  
SELECT @startmonth=DATEADD(month, DATEDIFF(month, 0, GETDATE()), 0)
--CAST(MIN(Convert(varchar,CreatedDate,103))as varchar)from daily_operator_status where Convert(varchar,DATEADD(month, DATEDIFF(month, 0, CreatedDate), 0),103)<=Convert(varchar,DATEADD(month, DATEDIFF(month, 0, GETDATE()), 0),103)  
SELECT @monthend=Convert(varchar,DATEADD(d, -1, DATEADD(m, DATEDIFF(m, 0, GETDATE()) + 1, 0)),103)  
declare @spicedeliveredyesterday bigint
declare @spicedeliveredthismonth bigint
declare @spicedeliveredcostyesterday bigint
declare @spicedeliveredcostthismonth bigint
declare @vfdeliveredyesterday bigint
declare @vfdeliveredthismonth bigint
declare @vfdeliveredcostyesterday bigint
declare @vfdeliveredcostthismonth bigint

select @vfdeliveredyesterday=isnull(VfDeliveredPro,0)+isnull(VfDeliveredTr,0)+isnull(VfDeliveredTRC,0)+isnull(VfDeliveredCritical,0)+isnull(VfDeliveredKitever,0) from daily_operator_status where convert(nvarchar,convert(datetime,CreatedDate,103),112) between convert(nvarchar,convert(datetime,@FromDate,103),112) and convert(nvarchar,convert(datetime,@ToDate,103),112) 
select @spicedeliveredyesterday=isnull(SpiceDeliveredPro,0)+isnull(SpiceDeliveredTr,0)+isnull(SpiceDeliveredTRC,0)+isnull(SpiceDeliveredCritical,0)+isnull(SpiceDeliveredKitever,0) from daily_operator_status where convert(nvarchar,convert(datetime,CreatedDate,103),112) between convert(nvarchar,convert(datetime,@FromDate,103),112) and convert(nvarchar,convert(datetime,@ToDate,103),112) 
--select @spicedeliveredyesterday=count(distinct SubmitRefID) from MySMSReport.dbo.ReceiveDeliveryDataHistory (nolock) where error='000' and convert(nvarchar,convert(datetime,CreatedDate,103),112) between convert(nvarchar,convert(datetime,@FromDate,103),112) and convert(nvarchar,convert(datetime,@ToDate,103),112) and Messagetext='Spice'
--select @vfdeliveredyesterday=count(distinct SubmitRefID) from MySMSReport.dbo.ReceiveDeliveryDataHistory (nolock) where error='000' and convert(nvarchar,convert(datetime,CreatedDate,103),112) between convert(nvarchar,convert(datetime,@FromDate,103),112) and convert(nvarchar,convert(datetime,@ToDate,103),112) and Messagetext='Vfirst'
--select @vfdeliveredyesterday=count(distinct Reference) from Deliver_Detail_Reference (nolock) where left(status,27)='SMPP_MESSAGESTATE_DELIVERED' and convert(nvarchar,convert(datetime,DateCreated,103),112) between convert(nvarchar,convert(datetime,@FromDate,103),112) and convert(nvarchar,convert(datetime,@ToDate,103),112)
--select @vfdeliveredthismonth=count(distinct Reference) from Deliver_Detail_Reference (nolock) where left(status,27)='SMPP_MESSAGESTATE_DELIVERED' and convert(nvarchar,convert(datetime,Datecreated,103),112) between convert(nvarchar,convert(datetime,@startmonth,103),112) and convert(nvarchar,convert(datetime,  
--@monthend,103),112)
select @vfdeliveredthismonth=sum(isnull(VfDeliveredPro,0)+isnull(VfDeliveredTr,0)+isnull(VfDeliveredTRC,0)+isnull(VfDeliveredCritical,0)+isnull(VfDeliveredKitever,0)) from daily_operator_status where convert(nvarchar,convert(datetime,CreatedDate,103),112) between convert(nvarchar,convert(datetime,@startmonth,103),112) and convert(nvarchar,convert(datetime,@monthend,103),112) 
select @spicedeliveredthismonth=sum(isnull(SpiceDeliveredPro,0)+isnull(SpiceDeliveredTr,0)+isnull(SpiceDeliveredTRC,0)+isnull(SpiceDeliveredCritical,0)+isnull(SpiceDeliveredKitever,0)) from daily_operator_status where convert(nvarchar,convert(datetime,CreatedDate,103),112) between convert(nvarchar,convert(datetime,@startmonth,103),112) and convert(nvarchar,convert(datetime,@monthend,103),112)
--select @vfdeliveredthismonth=count(distinct SubmitRefID) from MySMSReport.dbo.ReceiveDeliveryDataHistory (nolock) where error='000' and convert(nvarchar,convert(datetime,CreatedDate,103),112) between convert(nvarchar,convert(datetime,@startmonth,103),112) and convert(nvarchar,convert(datetime,@monthend,103),112) and Messagetext='Vfirst'
--select @spicedeliveredthismonth=count(distinct SubmitRefID) from MySMSReport.dbo.ReceiveDeliveryDataHistory (nolock) where error='000' and convert(nvarchar,convert(datetime,CreatedDate,103),112) between convert(nvarchar,convert(datetime,@startmonth,103),112) and convert(nvarchar,convert(datetime,@monthend,103),112) and Messagetext='Spice'
select @spicedeliveredcostyesterday=ceiling(ISNULL((.08625*@spicedeliveredyesterday),0))
select @spicedeliveredcostthismonth=ceiling(ISNULL((.08625*@spicedeliveredthismonth),0))
select @vfdeliveredcostyesterday=ceiling(ISNULL((.09775*@vfdeliveredyesterday),0))
select @vfdeliveredcostthismonth=ceiling(ISNULL((.09775*@vfdeliveredthismonth),0))

declare @tempt table(ConsumptionFor nvarchar(100),TotalSentbyCustomer bigint,TotalSentThroughVF bigint,TotalSentThroughSpice bigint, TotalSentByUs bigint,SpiceDelivered bigint, Vfdelivered bigint,SpicedeliveredCost bigint,VfdeliveredCost bigint,
VFSubmissionCost bigint,SpiceSubmissionCost bigint,TotalCostSubmission bigint,TotalCostDelivered bigint)
insert into @tempt(ConsumptionFor ,TotalSentbyCustomer,TotalSentThroughVF,TotalSentThroughSpice,TotalSentByUs,SpiceDelivered,Vfdelivered,SpicedeliveredCost,VfdeliveredCost,VFSubmissionCost,SpiceSubmissionCost,TotalCostSubmission,TotalCostDelivered)
(select     
Convert(varchar,dateadd(dd,-1,GETDATE()),103) as ConsumptionFor,isnull(sum(CustSentPro),0)+ isnull(sum(CustSentTr),0)+ isnull(sum(CustSentTrc),0)+isnull(sum(CustSentCritical),0)    
+isnull(sum(CustSentKitever),0) TotalSentbyCustomer,    
isnull(sum(VfSentPro),0)+isnull(sum(VfSentTr),0)+isnull(sum(VfSentTRC),0)+isnull(sum(VfSentCritical),0)+isnull(sum(VfSentKitever),0) as TotalSentThroughVF,    
isnull(sum(SpiceSentPro),0)+isnull(sum(SpiceSentTr),0)+isnull(sum(SpiceSentTRC),0)+isnull(sum(SpiceSentCritical),0)+isnull(sum(SpiceSentKitever),0) as TotalSentThroughSpice,  
isnull(sum(VfSentPro),0)+isnull(sum(VfSentTr),0)+isnull(sum(VfSentTRC),0)+isnull(sum(VfSentCritical),0)+isnull(sum(VfSentKitever),0)+  
isnull(sum(SpiceSentPro),0)+isnull(sum(SpiceSentTr),0)+isnull(sum(SpiceSentTRC),0)+isnull(sum(SpiceSentCritical),0)+isnull(sum(SpiceSentKitever),0) as TotalSentByUs, @spicedeliveredyesterday as SpiceDelivered, @vfdeliveredyesterday as vfdelivered,
@spicedeliveredcostyesterday as Spicedeliveredcost,@vfdeliveredcostyesterday as Vfdeliveredcost,
ceiling((.09775*(isnull(sum(VfSentPro),0)+isnull(sum(VfSentTr),0)+isnull(sum(VfSentTRC),0)+isnull(sum(VfSentCritical),0)  
+isnull(sum(VfSentKitever),0)))) as VFSubmissionCost,  
ceiling((.08625*(isnull(sum(SpiceSentPro),0)+isnull(sum(SpiceSentTr),0)+isnull(sum(SpiceSentTRC),0)+isnull(sum(SpiceSentCritical),0)+isnull(sum(SpiceSentKitever),0)))) as SpiceSubmissionCost,  
ceiling((.09775*(isnull(sum(VfSentPro),0)+isnull(sum(VfSentTr),0)+isnull(sum(VfSentTRC),0)+isnull(sum(VfSentCritical),0)  
+isnull(sum(VfSentKitever),0))) + (.08625*(isnull(sum(SpiceSentPro),0)+isnull(sum(SpiceSentTr),0)+isnull(sum(SpiceSentTRC),0)+isnull(sum(SpiceSentCritical),0)+isnull(sum(SpiceSentKitever),0)))) as TotalCost,@vfdeliveredcostyesterday + @spicedeliveredcostyesterday as TotalCostDelivered  
 from daily_operator_status(nolock) where   
convert(nvarchar,convert(datetime,CreatedDate,103),112) between convert(nvarchar,convert(datetime,@FromDate,103),112) and convert(nvarchar,convert(datetime,@ToDate,103),112)  
union  
select     
CAST(MIN(Convert(varchar,CreatedDate,103))as varchar) + ' To ' + CAST(@monthend as varchar)  as ConsumptionFor,isnull(sum(CustSentPro),0)+ isnull(sum(CustSentTr),0)+ isnull(sum(CustSentTrc),0)+isnull(sum(CustSentCritical),0)    
+isnull(sum(CustSentKitever),0) TotalSentbyCustomer,    
isnull(sum(VfSentPro),0)+isnull(sum(VfSentTr),0)+isnull(sum(VfSentTRC),0)+isnull(sum(VfSentCritical),0)+isnull(sum(VfSentKitever),0) as TotalSentThroughVF,    
isnull(sum(SpiceSentPro),0)+isnull(sum(SpiceSentTr),0)+isnull(sum(SpiceSentTRC),0)+isnull(sum(SpiceSentCritical),0)+isnull(sum(SpiceSentKitever),0) as TotalSentThroughSpice,  
isnull(sum(VfSentPro),0)+isnull(sum(VfSentTr),0)+isnull(sum(VfSentTRC),0)+isnull(sum(VfSentCritical),0)+isnull(sum(VfSentKitever),0)+  
isnull(sum(SpiceSentPro),0)+isnull(sum(SpiceSentTr),0)+isnull(sum(SpiceSentTRC),0)+isnull(sum(SpiceSentCritical),0)+isnull(sum(SpiceSentKitever),0) as TotalSentByUs, 
 @spicedeliveredthismonth as SpiceDelivered, @vfdeliveredthismonth as vfdelivered,
@spicedeliveredcostthismonth as Spicedeliveredcost,@vfdeliveredcostthismonth as Vfdeliveredcost,
ceiling((.09775*(isnull(sum(VfSentPro),0)+isnull(sum(VfSentTr),0)+isnull(sum(VfSentTRC),0)+isnull(sum(VfSentCritical),0)  
+isnull(sum(VfSentKitever),0)))) as VFSubmissionCost,  
ceiling((.08625*(isnull(sum(SpiceSentPro),0)+isnull(sum(SpiceSentTr),0)+isnull(sum(SpiceSentTRC),0)+isnull(sum(SpiceSentCritical),0)+isnull(sum(SpiceSentKitever),0)))) as SpiceSubmissionCost, 
ceiling((.09775*(isnull(sum(VfSentPro),0)+isnull(sum(VfSentTr),0)+isnull(sum(VfSentTRC),0)+isnull(sum(VfSentCritical),0)  
+isnull(sum(VfSentKitever),0))) + (.08625*(isnull(sum(SpiceSentPro),0)+isnull(sum(SpiceSentTr),0)+isnull(sum(SpiceSentTRC),0)+isnull(sum(SpiceSentCritical),0)+isnull(sum(SpiceSentKitever),0)))) as TotalCost,@vfdeliveredcostthismonth + @spicedeliveredcostthismonth as TotalCostDelivered    
 from daily_operator_status(nolock) where   
convert(nvarchar,convert(datetime,CreatedDate,103),112) between convert(nvarchar,convert(datetime,@startmonth,103),112) and convert(nvarchar,convert(datetime, 
@monthend,103),112))
--select * from @tempt

DECLARE @xml NVARCHAR(MAX)DECLARE @body NVARCHAR(MAX)
SET @xml =CAST(( SELECT ConsumptionFor AS 'td','',TotalSentbyCustomer AS 'td','',TotalSentByUs AS 'td','', TotalCostSubmission  AS 'td','',TotalCostDelivered as 'td','',TotalSentThroughVF  AS 'td','',TotalSentThroughSpice as 'td','',SpiceDelivered as 'td','',Vfdelivered as 'td','',SpicedeliveredCost as 'td','',VfdeliveredCost as 'td','',VFSubmissionCost AS 'td','',SpiceSubmissionCost AS 'td' from @tempt FOR XML PATH('tr'), ELEMENTS ) AS NVARCHAR(MAX))
SET @body ='<html><H1>SMS Consumption This Month</H1><body><table border = 2><tr><th>ConsumptionFor</th><th>TotalSentbyCustomer</th><th>TotalSentByUs</th><th>TotalCostSubmission</th><th>TotalCostDelivered</th><th>TotalSentThroughVF</th><th>TotalSentThroughSpice</th><th>SpiceDelivered</th><th>Vfdelivered</th><th>SpicedeliveredCost</th><th>VfdeliveredCost</th><th>VFSubmissionCost</th><th>SpiceSubmissionCost</th></tr>' 
SET @body = @body + @xml +'</table></body></html>'
select @body
EXEC msdb.dbo.sp_send_dbmail
@profile_name='Alerts', 
@recipients='karuna@pelsoftlabs.in',
@copy_recipients='csshukla@pelsoftlabs.in',  
@subject='SMS Consumption This Month',
@body = @body,
@body_format ='HTML'


GO

/* ============================================================
   Procedure: [dbo].[usp_get_dateisdue]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

--Dependency of this usp_get_dateisdue  
  
--1. MySMSConversations.dbo.convusers  -- called by clr  
  
   
  
-------------------------------------  
  
  
CREATE   PROCEDURE [dbo].[usp_get_dateisdue]        
as        
begin

DECLARE @sqlquery NVARCHAR(MAX);  

declare @datenow datetime,@tid bigint=0,@c int  ,@ddid bigint,@max_date datetime     
select @max_date=max(attempted) from dateisdue(nolock)  
select @datenow=dbo.[fn_Max_date]      
((select dbo.[fn_Min_date]      
(isnull(dateadd(mi,1,@max_date),getdate()),getdate())),(select dateadd(minute,-10,getdate()))    
--(select dateadd(hour,-4,getdate()))    
    
)      
      
print @datenow  
  
if @datenow<dateadd(mi,1,@max_date)  
Goto SKIP  
  
drop table if exists #tc_dateisdue      
select t.* into #tc_dateisdue from triggeredcampaigns t with (nolock) where eventid in (680,681) and isactive=1          
and dbo.fn_parent_hasactivesubscription(parentid)=1        
      
if exists (select * from #tc_dateisdue)      
begin      
print 1      
insert into Dateisdue(attempted,dd_parentid,dd_tcid)        
select @datenow,parentid,id  from #tc_dateisdue         
end      
else      
begin      
print 2      
insert into Dateisdue(attempted,dd_parentid,dd_tcid,totalrecipients)        
select @datenow,0,0,0      
end      
      
      
      
drop table if exists #tc      
drop table if exists #entityid      
drop table if exists #insertedid      
      
create table #tc(entityname varchar(20),entityid bigint,tcid bigint)        
create table #entityid(entityid bigint)        
create table #insertedid(historyid bigint,entityid bigint,activitytext nvarchar(2000))        
/*        
declare @parentid bigint=34594,@datefield varchar(100)='dob',@datefieldtype varchar(20)='custom',@dateformattomatch varchar(20)='MM',        
@tc_timeafterevent int=0,@tc_timeunit varchar(20)='Minute',@fixedtime varchar(20)='16:18'--format(getdate(),'H:mm')        
,@sql nvarchar(max),@fieldid bigint        
,@eventid bigint=680,@hour int,@min int        
*/        
declare @parentid bigint,@datefield varchar(100),@datefieldtype varchar(20),@dateformattomatch varchar(20),        
@tc_timeafterevent int,@tc_timeunit varchar(20),@fixedtime varchar(20),@sql nvarchar(max),@fieldid bigint        
,@eventid bigint,@hour int,@min int,@entityname varchar(20)        
        
select @c=count(1) from #tc_dateisdue         
while @c>0        
begin      
begin try      
select @tid=min(id) from #tc_dateisdue where id>@tid        
        
select @parentid=parentid,@datefield=replace(replace(datefield,'Enquiry.',''),'Lead.',''),@datefieldtype=datefieldtype,  
@dateformattomatch=dateformattomatch,        
@tc_timeafterevent=tc_timeafterevent,@tc_timeunit=tc_timeunit,@fixedtime=left(fixedtime,5),@sql='',@eventid=eventid,@entityname=        
case when eventid=680 then 'lead' else 'enquiry' end        
from #tc_dateisdue where id=@tid        
        
if isnull(@fixedtime,'')<>''        
begin        
select @hour=value from dbo.fn_Split(@fixedtime,':') where position=1        
select @min=value from dbo.fn_Split(@fixedtime,':') where position=2        
end        
       
print concat('parentid: ',@parentid,', Datefield: ',@datefield,', datefieldtype: ',@datefieldtype,', Dateformattomatch: ',@dateformattomatch,        
', tc_timeafterevent: ',@tc_timeafterevent,', tc_timeunit: ',@tc_timeunit,', fixedtime: ',@fixedtime,', Eventid: ',@eventid,  
' entityname: ',@entityname, ', Hour: ',@hour,', Min: ',@min )    
  
if @datefieldtype='Predefined'        
begin        
        
select @sql=        
'select '+case when @eventid =680 then ' id ' else ' enquiryid ' end +'as entityid from '+case when @eventid =680 then 'userleads ' else 'userenquiry ' end +'(nolock) where parentid='+cast(@parentid as nvarchar)+' and '+QUOTENAME(@datefield)+        
' is not null and isdate('+QUOTENAME(@datefield)+')=1 and '+        
case when @tc_timeafterevent<>0 then +        
        
'format(dateadd('+@tc_timeunit+','+cast(@tc_timeafterevent as nvarchar)+','+QUOTENAME(@datefield)+'),        
''H:mm'')=format(cast('''+cast(@datenow as nvarchar)+''' as datetime),''H:mm'') and        
format('+QUOTENAME(@datefield)+','''+@dateformattomatch+''')=format(cast('''+cast(@datenow as nvarchar)+''' as datetime),'''+@dateformattomatch+''')'         
        
when @fixedtime is not null then +        
        
'format('+QUOTENAME(@datefield)+','''+replace(replace(replace(@dateformattomatch,' H:mm',''),' hh:mm',''),' mm','')+''')        
=format(cast('''+cast(@datenow as nvarchar)+''' as datetime),'''+replace(replace(replace(@dateformattomatch,' H:mm',''),' hh:mm',''),' mm','')+''') and         
format(cast('''+cast(@datenow as nvarchar)+''' as datetime),''H:mm'')=format(convert(datetime,'''+@fixedtime+'''),''H:mm'')'        
        
else +        
        
'format('+QUOTENAME(@datefield)+','''+@dateformattomatch+''')=format('+cast(@datenow as nvarchar)+','''+@dateformattomatch+''') and format(        
'+QUOTENAME(@datefield)+',''H:mm'')=format(cast('''+cast(@datenow as nvarchar)+''' as datetime),''H:mm'')'         
        
end        
        
end        
else        
begin        
select @fieldid=field_id from customfields(nolock) where parentid=@parentid and isactive=1 and fieldname=ltrim(rtrim(@datefield))   
print concat('Fieldid: ',@fieldid)  
select @sql=        
case when @eventid=680 then         
'select leadid as entityid from customfieldLeadvalue(nolock) where fieldid='+cast(@fieldid as nvarchar)+' and fieldvalue is not null        
and isdate(isnull(try_cast(fieldvalue as datetime),''''))=''1'' and         
'+        
case when @tc_timeafterevent is not null and @tc_timeafterevent<>0 then +        
        
'format(dateadd('+@tc_timeunit+','+cast(@tc_timeafterevent as nvarchar)+',try_cast(fieldvalue as datetime)),        
''H:mm'')=format(cast('''+cast(@datenow as nvarchar)+''' as datetime),''H:mm'') and        
format(try_cast(fieldvalue as datetime),'''+@dateformattomatch+''')=format(cast('''+cast(@datenow as nvarchar)+''' as datetime),'''+@dateformattomatch+''')'         
        
when @fixedtime is not null then +        
        
'format(try_cast(fieldvalue as datetime),'''+replace(replace(replace(@dateformattomatch,' H:mm',''),' hh:mm',''),' mm','')+''')        
=format(cast('''+cast(@datenow as nvarchar)+''' as datetime),'''+replace(replace(replace(@dateformattomatch,' H:mm',''),' hh:mm',''),' mm','')+''') and         
format(cast('''+cast(@datenow as nvarchar)+''' as datetime),''H:mm'')=format(convert(datetime,'''+@fixedtime+'''),''H:mm'')'        
        
else +        
        
'format(try_cast(fieldvalue as datetime),'''+@dateformattomatch+''')=format(getdate(),'''+@dateformattomatch+''') and format(        
try_cast(fieldvalue as datetime),''H:mm'')=format(cast('''+cast(@datenow as nvarchar)+''' as datetime),''H:mm'')'        
end        
else         
'select enquiryid as entityid from customfieldenquiryvalue(nolock) where fieldid='+cast(@fieldid as nvarchar)+' and fieldvalue is not null        
and isdate(isnull(try_cast(fieldvalue as datetime),''''))=''1'' and         
'+        
case when @tc_timeafterevent is not null and @tc_timeafterevent<>0 then +        
        
'format(dateadd('+@tc_timeunit+','+cast(@tc_timeafterevent as nvarchar)+',try_cast(fieldvalue as datetime)),        
''H:mm'')=format(cast('''+cast(@datenow as nvarchar)+''' as datetime),''H:mm'') and        
format(try_cast(fieldvalue as datetime),'''+@dateformattomatch+''')=format('+cast(@datenow as nvarchar)+','''+@dateformattomatch+''')'         
        
when @fixedtime is not null then +        
        
'format(try_cast(fieldvalue as datetime),'''+replace(replace(replace(@dateformattomatch,' H:mm',''),' hh:mm',''),' mm','')+''')        
=format(cast('''+cast(@datenow as nvarchar)+''' as datetime),'''+replace(replace(replace(@dateformattomatch,' H:mm',''),' hh:mm',''),' mm','')+''') and         
format(cast('''+cast(@datenow as nvarchar)+''' as datetime),''H:mm'')=format(convert(datetime,'''+@fixedtime+'''),''H:mm'')'        
        
else +        
        
