/****** Script for SelectTopNRows command from SSMS  ******/  
CREATE   PROC [dbo].[usp_get_debit_details]  
as  
declare @total nvarchar(1000),@promo nvarchar(1000),@trans nvarchar(1000),@trc nvarchar(1000),@open nvarchar(1000),  
@promobatch nvarchar(1000),@transbatch nvarchar(1000),@trcbatch nvarchar(1000),@openbatch nvarchar(1000)  
SELECT @promo=sum(debits) FROM [MySMS].[dbo].[Credit_Details](nolock) where datediff(d,datecreated,getdate())=0 and credits=0 and fromuser_id=user_id   
and user_id in(select user_id from [MySMS].[dbo].User_Detail(nolock) where userfilter='mtix_pro' or userfilter='ROUTE_PRO')  
SELECT @trans=sum(debits) FROM [MySMS].[dbo].[Credit_Details](nolock) where datediff(d,datecreated,getdate())=0 and credits=0 and fromuser_id=user_id   
and user_id in(select user_id from [MySMS].[dbo].User_Detail(nolock) where userfilter='mtix_tr' or userfilter='route_tr')  
SELECT @trc=sum(debits) FROM [MySMS].[dbo].[Credit_Details](nolock) where datediff(d,datecreated,getdate())=0 and credits=0 and fromuser_id=user_id   
and user_id in(select user_id from [MySMS].[dbo].User_Detail(nolock) where userfilter='MTIX_TRC')  
SELECT @open=sum(debits) FROM [MySMS].[dbo].[Credit_Details](nolock) where datediff(d,datecreated,getdate())=0 and credits=0 and fromuser_id=user_id   
and user_id in(select user_id from [MySMS].[dbo].User_Detail(nolock) where userfilter='OPEN')  
SELECT @promobatch=sum([TotalRecords]) FROM [MySMS].[dbo].[BatchInfo] where datediff(d,scheduleddate,getdate())=0 and datediff(d,batchinserttime,getdate())<>0  and (userfilter='MTIX_PRO' or userfilter='route_pro')  
SELECT @transbatch=sum([TotalRecords]) FROM [MySMS].[dbo].[BatchInfo] where datediff(d,scheduleddate,getdate())=0 and datediff(d,batchinserttime,getdate())<>0  
and (userfilter='MTIX_TR' or userfilter='route_tr')
SELECT @trcbatch=sum([TotalRecords]) FROM [MySMS].[dbo].[BatchInfo] where datediff(d,scheduleddate,getdate())=0 and datediff(d,batchinserttime,getdate())<>0   
and userfilter='MTIX_TRC'  
SELECT @openbatch=sum([TotalRecords]) FROM [MySMS].[dbo].[BatchInfo] where datediff(d,scheduleddate,getdate())=0 and datediff(d,batchinserttime,getdate())<>0   
and userfilter='OPEN'  
set @promo=isnull(cast(@promo as int),0)+isnull(cast(@promobatch as int),0)  
set @trans=isnull(cast(@trans as int),0)+isnull(cast(@transbatch as int),0)  
set @trc=isnull(cast(@trc as int),0)+isnull(cast(@trcbatch as int),0)  
set @open=isnull(cast(@open as int),0)+isnull(cast(@openbatch as int),0)  
set @total=cast(@promo as int)+cast(@trans as int)+cast(@trc as int)+cast(@open as int)  
insert into [MySMS].[dbo].daily_credit_status(total,promo,trans,trc,[open])  
select @total as 'Total',@promo as 'Promo',@trans as 'Trans',@trc as 'TRC',@open as 'OPEN'  


GO

/* ============================================================
   Procedure: [dbo].[usp_get_demoReminders]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_get_demoReminders
as
begin
begin try
drop table if exists #temp_demo

create table #temp_demo(id bigint,demotime datetime,mobile nvarchar(20),enqpipelineid bigint,enqno bigint,customername nvarchar(100),stagename varchar(50),stageid bigint)

--BEGIN DISTRIBUTED TRANSACTION
--insert into #temp_demo(DemoTime,Mobile,Enqpipelineid,enqno,CustomerName,stagename,stageid)
--exec CRM.CRMDB.dbo.usp_get_demofixed_reminders
--COMMIT TRANSACTION

--EXEC sp_serveroption 'CRM', 'remote proc transaction promotion', 'false';
insert into #temp_demo(id,DemoTime,Mobile,Enqpipelineid,enqno,CustomerName,stagename,stageid)
select id,DemoTime,Mobile,Enqpipelineid,enqno,CustomerName,stage,stageid from CRM.CRMDB.dbo.CRM_Demo_Reminders with (nolock) where istransferred=0

update c set istransferred=1 from CRM.CRMDB.dbo.CRM_Demo_Reminders c join #temp_demo t on c.id=t.id

delete c from CRM_Demo_Reminders c
left join #temp_demo t on c.Enqpipelineid=t.enqpipelineid where c.isprocessed=0 and 
(t.enqpipelineid is null or cast(t.demotime as datetime)<>cast(c.demotime as datetime))


insert into CRM_Demo_Reminders(DemoTime,Mobile,Enqpipelineid,enqno,CustomerName,stage,stageid)
select DemoTime,Mobile,Enqpipelineid,enqno,CustomerName,stagename,stageid from #temp_demo t where not exists
(select 1 from CRM_Demo_Reminders(nolock) where enqpipelineid=t.Enqpipelineid and (isprocessed=0 or demotime <=dateadd(hh,1,getdate()))
and Demotime=t.demotime)


declare @c int=(select count(1) from CRM_Demo_Reminders(nolock) where isprocessed=0 and demotime <=dateadd(hh,1,getdate())),@id bigint=0,@tid bigint,@stageid bigint,@enqpipelineid bigint,@new_tid bigint,
@jsonpl nvarchar(4000),@cp int=0,@pl varchar(50),@cmobile nvarchar(20)

while @c>0
begin
 
select @id=min(id),@cp=0 from CRM_Demo_Reminders(nolock) where isprocessed=0 and demotime <=dateadd(hh,1,getdate())
select @stageid=stageid,@enqpipelineid=Enqpipelineid,@cmobile=mobile from CRM_Demo_Reminders(nolock) where id=@id
select top 1 @tid=templateid from CRM_Demo_Reminders(nolock) where Enqpipelineid=@enqpipelineid and isprocessed=1 and stageid=@stageid order by processedon desc

if isnull(@tid,0)=0 or not exists (select convtemplateid from CRM_Demo_Reminder_templates(nolock) where stageid=@stageid and convtemplateid>@tid)
begin
select @new_tid=min(convtemplateid) from CRM_Demo_Reminder_templates(nolock) where stageid=@stageid 
end
else
begin
select @new_tid=min(convtemplateid) from CRM_Demo_Reminder_templates(nolock) where stageid=@stageid and convtemplateid>@tid
end

select @jsonpl=templatejson   from CRM_Demo_Reminder_templates(nolock) where convtemplateid=@new_tid

declare @tbl as recursivereplace 

insert into @tbl(displaykey,value)
SELECT displaykey, value
FROM (
    SELECT 
        CONVERT(VARCHAR, DemoTime) AS DemoTime,
        CONVERT(VARCHAR, Mobile) AS Mobile,
        CONVERT(VARCHAR, Enqpipelineid) AS Enqpipelineid,
        CONVERT(VARCHAR, enqno) AS enqno,
        CONVERT(VARCHAR, CustomerName) AS CustomerName,
        CONVERT(VARCHAR, stage) AS stage,
        CONVERT(VARCHAR, stageid) AS stageid
    FROM CRM_Demo_Reminders(nolock)
    WHERE id=@id
) AS SourceTable
UNPIVOT (
    value FOR displaykey IN (
        DemoTime,Mobile,Enqpipelineid,enqno,CustomerName,stage,stageid
    )
) AS Unpivoted;

select @jsonpl=[dbo].[fn_recursivereplace](@tbl,@jsonpl)

--exec usp_sendwhatsapp_templateid  '919310000523',@cmobile,@new_tid,@jsonpl

update CRM_Demo_Reminders set isprocessed=1,processedon=getdate() where id=@id

set @c=@c-1
end
end try
begin catch
print error_message()
--exec mysms.dbo.usp_inserterrorinfo
end catch
end


/*
select * from CRM_Demo_Reminders(nolock)


create table CRM_Demo_Reminders(id bigint primary key identity(1,1),DemoTime datetime,Mobile Nvarchar(20),Enqpipelineid bigint,enqno bigint,CustomerName nvarchar(100),isprocessed int default 0,processedon datetime,TemplateSent nvarchar(50),ims_id bigint)

alter table CRM_Demo_Reminders add stage nvarchar(50),stageid bigint

select top 10 * from convtemplates(nolock) where templatename like 'dem%remind%'


select * from CRM_Demo_Reminder_templates
create table CRM_Demo_Reminder_templates (id int primary key identity(1,1),convtemplateid bigint,templatename nvarchar(50),stage nvarchar(50),stageid bigint,templatejson nvarchar(2000),isactive bit default 1)

insert into CRM_Demo_Reminder_templates(convtemplateid,templatename,stage,stageid,templatejson)
select id,templatename,   'Demo Fixed',34,'[{"SectionType":"BODY","FieldName":"CustomPlaceholder1","FieldValue":"#CustomerName#"},{"SectionType":"BODY","FieldName":"CustomPlaceholder2","FieldValue":"#DemoTIme#"}]' 
from convtemplates(nolock) where templatename like 'dem%remind%' and channeltokenid=2
union
select id,templatename,   'Partner Demo Fixed',128,'[{"SectionType":"BODY","FieldName":"CustomPlaceholder1","FieldValue":"#CustomerName#"},{"SectionType":"BODY","FieldName":"CustomPlaceholder2","FieldValue":"#DemoTIme#"}]' 
from convtemplates(nolock) where templatename like 'dem%remind%' and channeltokenid=2



