CREATE   PROC [dbo].[usp_get_DenominationMaster] --0
(
@id int
)     
as      
begin
if @id =0      
select *,(price_desc*.18) gst,(price_desc*.18)+price_desc Price from dbo.int_Denomination_master
 order by Price
else
