CREATE   PROCEDURE usp_get_DependentFieldData(  
 @ParentId bigint,  
 @CustomFieldIds nvarchar(255)  
)  
as  
begin  
 select field_ID, choices, formulaId, ParentFieldId, DependencyJson, defaultValue   
  from customfields(nolock)  where ParentID = @ParentId   
