/* ============================================================
   Procedure: [dbo].[usp_get_entity_details]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_get_entity_details --1  
@executionid bigint  
as  
begin  
begin try  
-- declare @executionid bigint=1287

declare @agentid bigint,@entityname varchar(20),@entityid bigint,@channel varchar(20),@assistantid bigint,@assistantguid nvarchar(200),@threadid nvarchar(200)  
select @agentid=agentid,@entityname=entityname,@entityid=entityid,@channel=channel,@assistantguid=assistantid  from tbl_ai_agent_entity_for_execution(nolock) where id=@executionid  
select @threadid=thread_id from tbl_ai_agent_entity_status(nolock) where entityname=@entityname and entityid=@entityid and agentid=@agentid  
declare @parentid bigint,@predefinedsettings nvarchar(max),@agentname nvarchar(200),@max_execution int,@additional_details nvarchar(max) ,@errorid int  
select @parentid=parentid,@agentname=Name ,@predefinedsettings=predefined_settings,@max_execution=JSON_VALUE(predefined_settings,'$.max_execution') from   
tbl_ai_Agents (nolock) where agentid=@agentid  and status='active' and isnull(dormant_till,dateadd(d,-1,getutcdate()))<getutcdate()  
  
if isnull(@parentid,0)<>0  
begin  
  print 'A'
declare @segments nvarchar(max),@Days nvarchar(max),@is_followup bit,@followup_depth_days int,@followup_depth_count int,  
@is_task bit,@task_depth_days int,@task_depth_count int,@is_appointment bit,@appointment_depth_days int,@appointment_depth_count int,  
@is_quotations bit,@quotation_depth_days int,@quotation_depth_count int,@is_invoice bit,@invoice_depth_days int,@invoice_depth_count int,  
@is_notes bit,@notes_depth_days int,@notes_depth_count int,@is_documents bit,@documents_depth_days int,@documents_depth_count int,  
@is_activities bit,@activities_depth_days int,@activities_depth_count int,@is_pipeline bit,@pipeline_depth_days int,@is_calls bit,  
@calls_depth_count int,@calls_depth_days int,  
@pipeline_depth_count int,  
@entity_columns nvarchar(max),@contactFrequency int,@primary_language nvarchar(200),@max_per_lead int,@retry_lead_after int,  
@entity_details nvarchar(max),@recent_calls nvarchar(max),  
@recent_followup nvarchar(max),@recent_tasks nvarchar(max),@recent_appointments nvarchar(max),@recent_quotations nvarchar(max),@recent_invoices nvarchar(max)  
,@recent_notes nvarchar(max),@recent_documents nvarchar(max),@recent_activities nvarchar(max),@recent_pipeline nvarchar(max)  
,@daytoday varchar(10)=datename(dw,getutcdate()),@segmentid bigint,@assistant_details nvarchar(1000),  
@sql_leads nvarchar(max),@batchcount int=50,@segment_count int, @entity_context nvarchar(max),@contact_details nvarchar(500),@mobile nvarchar(50),@email nvarchar(250),@FromEmail nvarchar(250),@ReplyToEmail nvarchar(250),@estimated_input_tokens int,@estimated_cost decimal(18,4),@balance decimal(18,4),@estimated_output_tokens int  
  
SELECT  
    @segments = segments,  
    @Days = days,  
    @is_followup = is_followup,  
    @followup_depth_days = followup_depth_days,  
    @followup_depth_count = followup_depth_count,  
    @is_task = is_task,  
    @task_depth_days = task_depth_days,  
    @task_depth_count = task_depth_count,  
    @is_appointment = is_appointment,  
    @appointment_depth_days = appointment_depth_days,  
    @appointment_depth_count = appointment_depth_count,  
    @is_quotations = is_quotations,  
    @quotation_depth_days = quotation_depth_days,  
    @quotation_depth_count = quotation_depth_count,  
    @is_invoice = is_invoice,  
    @invoice_depth_days = invoice_depth_days,  
    @invoice_depth_count = invoice_depth_count,  
    @is_notes = is_notes,  
    @notes_depth_days = notes_depth_days,  
    @notes_depth_count = notes_depth_count,  
    @is_documents = is_documents,  
    @documents_depth_days = documents_depth_days,  
    @documents_depth_count = documents_depth_count,  
    @is_activities = is_activities,  
    @activities_depth_days = activities_depth_days,  
    @activities_depth_count = activities_depth_count,  
 @is_calls =is_calls,  
    @calls_depth_count=calls_depth_count,  
 @calls_depth_days=calls_depth_days,  
    @is_pipeline = is_pipeline,  
    @pipeline_depth_days = pipeline_depth_days,  
    @pipeline_depth_count = pipeline_depth_count,  
    @entity_columns = lead_columns,  
    @contactFrequency = contactFrequency,  
    @primary_language = primary_language,  
    @max_per_lead = max_per_lead,  
    @retry_lead_after = retry_lead_after,  
    @FromEmail = from_email, 
    @ReplyToEmail = reply_to_email  
FROM OPENJSON(@predefinedsettings)  
WITH (  
    segments nvarchar(max) '$.segments' as json,  
    Days nvarchar(max) '$.days' as json,  
    is_followup bit '$.is_followup',  
    followup_depth_days int '$.followup_depth_days',  
    followup_depth_count int '$.followup_depth_count',  
    is_task bit '$.is_task',  
    task_depth_days int '$.task_depth_days',  
    task_depth_count int '$.task_depth_count',  
    is_appointment bit '$.is_appointment',  
    appointment_depth_days int '$.appointment_depth_days',  
    appointment_depth_count int '$.appointment_depth_count',  
    is_quotations bit '$.is_quotations',  
    quotation_depth_days int '$.quotation_depth_days',  
    quotation_depth_count int '$.quotation_depth_count',  
    is_invoice bit '$.is_invoice',  
    invoice_depth_days int '$.invoice_depth_days',  
    invoice_depth_count int '$.invoice_depth_count',  
    is_notes bit '$.is_notes',  
    notes_depth_days int '$.notes_depth_days',  
    notes_depth_count int '$.notes_depth_count',  
    is_documents bit '$.is_documents',  
    documents_depth_days int '$.documents_depth_days',  
    documents_depth_count int '$.documents_depth_count',  
    is_activities bit '$.is_activities',  
    activities_depth_days int '$.activities_depth_days',  
    activities_depth_count int '$.activities_depth_count',  
 is_calls bit,  
    calls_depth_count int,  
 calls_depth_days int,  
    is_pipeline bit '$.is_pipeline',  
    pipeline_depth_days int '$.pipeline_depth_days',  
    pipeline_depth_count int '$.pipeline_depth_count',  
    lead_columns nvarchar(max) '$.lead_columns',  
    contactFrequency int '$.contactFrequency',  
    primary_language nvarchar(200) '$.primary_language',  
    max_per_lead int '$.max_per_lead',  
    retry_lead_after int '$.retry_lead_after',
    from_email nvarchar(250) '$.from_email',
    reply_to_email nvarchar(250) '$.reply_to_email'    
)  
print 'usp_replaceentityplaceholders_allfields_insert is being called'  
exec usp_replaceentityplaceholders_allfields_insert @entityid,@entityname  
print 'usp_replaceentityplaceholders_allfields_insert done'  
select @entity_details=entitydetails from entity_details_transition(nolock) where entity=@entityname and entityid=@entityid  
  
  
select @assistant_details=concat('{"assistantid":"',isnull(@assistantguid,''),'","thread_id":"',@threadid,'"}')  
print concat('@assistant_details: ',@assistant_details)  
print concat('@channel: ',@channel)  
print concat('@entityname: ',@entityname)  
  
if @channel='whatsapp'  
begin  
select top 1 @mobile=channelprofileid from [10.0.0.135].Mysmsconversations.dbo.convusers with (nolock) where convuserparentid=@parentid and  entity=@entityname and entityid  =@entityid and isactive=1  
if @mobile is not null  
begin  
select @contact_details=concat('{"mobile":"',isnull(@mobile,''),'","channel":"',@channel,'"}')  
end  
end  
print concat('entity @contact_details: ',@contact_details)  
  
if @entityname='lead'  
begin  
print concat('@mobile: ',@mobile)  
  
if @mobile is null and @channel='whatsapp'  
begin  
select top 1 @mobile=replace(countrycode,'+','') +mobile from Userleads_Mobile_Email(nolock) where ulme_id=@entityid and mobile <>'0'  
if @mobile is not null  
begin  
select @contact_details=concat('{"mobile":"',isnull(@mobile,''),'","channel":"',@channel,'"}')  
end  
print concat('lead whatsapp @contact_details: ',@contact_details)  
  
end  
  
if @channel='email'  
begin  
select top 1 @email=email from Userleads_Mobile_Email(nolock) where ulme_id=@entityid and email <>'1' 
print concat('@email:',@email)
if @email is not null  
begin  
select @contact_details=concat('{"email":"',isnull(@email,''),'","channel":"',@channel,'","FromEmail":"',@FromEmail,'","ReplyToEmail":"',@ReplyToEmail,'"}')  
end  
print concat('lead email @contact_details: ',@contact_details)  
  
end  
  
if @contact_details is not null  
begin  
print 'contact details populated'  
if @is_followup=1  
begin  
select @recent_followup=(select top (case when @followup_depth_count<>0 then @followup_depth_count else 100 end) l.CreatedOn,u.user_login as FollowupBy , f.FollowupStatus,d.User_Login as AssignedTo,l.FollowupDate as NextFollowupdate,l.Remarks   
from LeadInteractionHistory l(nolock) join FollowUp_Status f(nolock) on l.FollowUpStatus=f.id   
join user_detail u on u.user_id=f.createdby left join user_detail d on d.user_id=l.AssignedTo   
where l.createdon> case when @followup_depth_days=0 then '20000101' else dateadd(d,0-@followup_depth_days,getutcdate()) end  
order by l.id desc  
FOR JSON PATH, INCLUDE_NULL_VALUES)   
print 'followup details populated'  
  
end  
  
if @is_activities=1  
begin  
select @recent_activities=(select top (case when @activities_depth_count<>0 then @activities_depth_count else 100 end) eventdate,u.User_Login as EventBy,a.EventName,replace(t.eventdescription,'""','') as eventdescription     
from tbl_LeadEventHistory(nolock) t join User_Detail u on t.userid=u.user_id  
join ActivityMaster(nolock) a on a.id=t.EventID   
where  t.LeadID=@entityid and t.eventdate> case when @activities_depth_days=0 then '20000101' else dateadd(d,0-@activities_depth_days,getutcdate()) end  
order by t.historyid desc FOR JSON PATH, INCLUDE_NULL_VALUES)  
print 'activity details populated'  
  
  
--select top (100) eventdate,u.User_Login as EventBy,a.EventName,t.eventdescription     
--from tbl_LeadEventHistory(nolock) t join User_Detail u on t.userid=u.user_id  
--join ActivityMaster(nolock) a on a.id=t.EventID   
--where  t.LeadID=3093379 and t.eventdate> '20000101'
--order by t.historyid
  

end  
  
if @is_calls=1  
begin  
select @recent_calls=(select top (case when @calls_depth_count<>0 then @calls_depth_count else 100 end) c.direction as Calldirection,callstarttime,callendtime,customercalldisposition,agentcalldisposition, u.User_Login as AgentLastAttempted,o.outcomename as CallOutcome,remarks as Callremarks    
from calllog(nolock) c left join user_detail u (nolock) on u.user_id=c.agentuserid  
left join calloutcomes (nolock) o on o.id=c.outcomeid  
where c.customerentity=@entityname and c.customerentityid=@entityid and c.parentid=@parentid   
and c.Callstarttime> case when @calls_depth_days=0 then '20000101' else dateadd(d,0-@calls_depth_days,getutcdate()) end  
order by c.id desc for json path, include_null_values)   
print 'call details populated'  
  
end  
  
if @is_appointment=1  
begin  
  
print 'app'  
end  
  
if @is_documents=1  
begin  
print 'app'  
end  
  
if @is_invoice=1  
begin  
print 'app'  
end  
  
if @is_quotations=1  
begin  
print 'app'  
end  
  
if @is_notes=1  
begin  
print 'app'  
end  
  
if @is_pipeline=1  
begin  
print 'app'  
end  
  
if @is_task=1  
begin  
print 'app'  
end  
end  
else  
begin  
print concat('contact details are null for leadid: ',@entityid)  
SELECT   
    0 as Success,  
    'No contact information available for this channel for entity '+ @entityname +' , entityid: ',cast(@entityid as nvarchar) as Message,  
    @executionid as ExecutionId,  
    'Ineligible for operation. No contact available for channel ' + @channel as ErrorMessage  
update tbl_ai_agent_entity_for_execution set isprocessed=1,processedat=getutcdate(),processing=0,lasterror='Ineligible for operation. No contact available for channel '+@channel where id=@executionid  
return;  
end  
  
end  
  
else if @entityname='enquiry'  
begin  
  
if @mobile is null  
begin  
select top 1 @mobile=replace(countrycode,'+','') +mobile from Userenquiry_Mobile_Email(nolock) where enquiryid=@entityid and mobile <>'0'  
if @mobile is not null  
begin  
select @contact_details=concat('{"mobile":"',isnull(@mobile,''),'","channel":"',@channel,'"}')  
end  
  
end  
if @channel='email'  
begin  
select top 1 @email=email from Userenquiry_Mobile_Email(nolock) where enquiryid=@entityid and email <>'1'  
if @email is not null  
begin  
select @contact_details=concat('{"email":"',isnull(@email,''),'","channel":"',@channel,'","FromEmail":"',@FromEmail,'","ReplyToEmail":"',@ReplyToEmail,'"}')  
end  
end  
  
if @contact_details is not null  
begin  
  
print 'contact details populated for enquiry'  
  
if @is_activities=1  
begin  
select @recent_activities=(select top (case when @activities_depth_count<>0 then @activities_depth_count else 100 end) eventdate,u.User_Login as EventBy,a.EventName,replace(t.eventdescription,'""','') as eventdescription     
from tbl_enquiryEventHistory(nolock) t join User_Detail u on t.userid=u.user_id  
join ActivityMaster(nolock) a on a.id=t.EventID   
where t.enquiryid=@entityid and t.eventdate> case when @activities_depth_days=0 then '20000101' else dateadd(d,0-@activities_depth_days,getutcdate()) end  
order by t.historyid desc FOR JSON PATH, INCLUDE_NULL_VALUES)  
print 'activity details populated'  
  
end  
  
if @is_calls=1  
begin  
select @recent_calls=(select top (case when @calls_depth_count<>0 then @calls_depth_count else 100 end) c.direction as Calldirection,callstarttime,callendtime,customercalldisposition,agentcalldisposition, u.User_Login as AgentLastAttempted,o.outcomename as CallOutcome,remarks as Callremarks    
from calllog(nolock) c left join user_detail u (nolock) on u.user_id=c.agentuserid  
left join calloutcomes (nolock) o on o.id=c.outcomeid  
where c.customerentity=@entityname and c.customerentityid=@entityid and c.parentid=@parentid   
and c.Callstarttime> case when @calls_depth_days=0 then '20000101' else dateadd(d,0-@calls_depth_days,getutcdate()) end  
order by c.id desc for json path, include_null_values)   
print 'call details populated'  
  
end  
  
if @is_appointment=1  
begin  
print 'app'  
  
end  
  
  
end  
else  
begin  
print concat('contact details null for channel ',@channel, ' for enquiryid: ',@entityid)  
SELECT   
    0 as Success,  
    'No contact information available for this channel for entity '+ @entityname +' , entityid: ',cast(@entityid as nvarchar) as Message,  
    @executionid as ExecutionId,  
    'Ineligible for operation. No contact available for channel ' + @channel as ErrorMessage  
update tbl_ai_agent_entity_for_execution set isprocessed=1,processedat=getutcdate(),processing=0, lasterror='Ineligible for operation. No contact available for channel '+@channel where id=@executionid  
return;  
end  
  
  
end  
  
drop table if exists #entitydetails  
  
create table #entitydetails(fieldnameexposed nvarchar(200),fieldvalue nvarchar(max))  
  
print 'now populating #entitydetails'  
insert into #entitydetails(fieldnameexposed,fieldvalue)  
select * from  
(  
select 'execution_id' fieldnameexposed,cast(@executionid as nvarchar(max)) fieldvalue where isnull(@entity_details,'')<>''  
union  
select 'entity_details' fieldnameexposed,@entity_details fieldvalue where isnull(@entity_details,'')<>''  
union  
select 'recent_followups',@recent_followup where isnull(@recent_followup,'')<>''  
union  
select 'recent_activities',@recent_activities where isnull(@recent_activities,'')<>''  
union  
select 'recent_appointments',@recent_appointments where isnull(@recent_appointments,'')<>''  
union  
select 'recent_calls',@recent_calls where isnull(@recent_calls,'')<>''  
union  
select 'recent_documents',@recent_documents where isnull(@recent_documents,'')<>''  
union  
select 'recent_invoices',@recent_invoices where isnull(@recent_invoices,'')<>''  
union  
select 'recent_quotations',@recent_quotations where isnull(@recent_quotations,'')<>''  
union  
select 'recent_notes',@recent_notes where isnull(@recent_notes,'')<>''  
union  
select 'recent_tasks',@recent_tasks where isnull(@recent_tasks,'')<>''  
union  
select 'recent_pipeline',@recent_pipeline where isnull(@recent_pipeline,'')<>''  
union  
select 'assistant_details',@assistant_details where isnull(@assistant_details,'')<>''  
union  
select 'contact_details',@contact_details where isnull(@contact_details,'')<>''  
) a  
  
  
--select * from #entitydetails;  declare @entity_context nvarchar(max)

select @entity_context=(SELECT '{' + STRING_AGG('"' + replace(replace(replace(fieldnameexposed,'lead.',''),'enquiry.',''),'user.','') + '":' +   
CASE WHEN ISNUMERIC(fieldvalue) = 1 and fieldvalue like '[0-9]' THEN fieldvalue ELSE '"' + REPLACE(fieldvalue, '"', '\"') + '"' END, ',' ) + '}'  
FROM #entitydetails)

--select @entity_context=replace(@entity_context,'\\"\\"','')
  
select @balance=[dbo].[GetAvailableBalanceForService_real](@parentid,23)  
select @estimated_input_tokens=count(*) from STRING_SPLIT(@entity_context, ' ') WHERE value <> '';  
select @estimated_output_tokens=200  
  
select top 1 @estimated_cost= priceperunit* cast(ceiling((@estimated_input_tokens+@estimated_output_tokens)/cast(Units_Per_Credit as float)) as int)   
from Price_Base_AICredits_Rate(nolock)    
where type='TextChat' and parentid in (@parentid,0) order by parentid desc  
  
if @balance>=@estimated_cost  
begin  
SELECT   
    1 as Success,  
    'Payload inserted successfully for entity: ',@entityname, ', entityid: ',cast(@entityid as nvarchar) as Message,  
    @executionid as ExecutionId,  
    NULL as ErrorMessage  
  
 SET XACT_ABORT ON;  
            BEGIN TRY  
                BEGIN TRANSACTION;  
                    INSERT INTO dbo.tbl_ai_agent_execution_outbox WITH (ROWLOCK)  
                        (agentid, queuename, asstt_id, payload, isprocessed, Processing, AttemptCount, createdon)  
                    VALUES (@agentid, 'Followup_agent', @assistantid, @entity_context, 0, 0, 0, GETUTCDATE());  
                COMMIT TRANSACTION;  
            END TRY  
            BEGIN CATCH  
                IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;  
                DECLARE @ErrMsg NVARCHAR(4000) = ERROR_MESSAGE();  
                RAISERROR('Outbox insert failed: %s',16,1,@ErrMsg);  
            END CATCH;  
  
UPDATE tbl_ai_agent_entity_for_execution  
            SET isprocessed = 1,  
                Processing = 0,  
                processedat = GETUTCDATE()  
            WHERE id = @executionid;  
end  
else  
begin  
SELECT   
    0 as Success,  
    'Cannot process this execution due to insufficient balance' as Message,  
    @executionid as ExecutionId,  
    'Insufficient balance for this execution' as ErrorMessage  
exec usp_ai_inserterror @agentid,3,'Agent has been marked dormant due to lack of funds. we will retry after 1 hour. Pl reactivate manually if recharged earlier'  
UPDATE tbl_ai_agent_entity_for_execution  
            SET Processing = 0,  
                AttemptCount = AttemptCount + 1,  
                NextRetryAt = DATEADD(HH, 1, GETUTCDATE())  
            WHERE id = @executionid;  
end  
end  

end try  
begin catch  
exec usp_inserterrorinfo  
UPDATE tbl_ai_agent_entity_for_execution SET Processing = 0, AttemptCount = AttemptCount + 1,  
NextRetryAt = DATEADD(mi, 5, GETUTCDATE()),Lasterror=ERROR_MESSAGE()  
            WHERE id = @executionid;  
  
end catch  
end  



GO

