/* ============================================================
   Procedure: [dbo].[Usp_Get_ImportReport]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[Usp_Get_ImportReport] 
@parentid bigint =0,
@date datetime = null
as 
begin
	--declare @date datetime = '2023-08-21',@parentid bigint =0
	
	drop table if exists #tempImpEnqP 
	drop table if exists #tempImpLeadP
	drop table if exists #tempUpdEnqP 
	drop table if exists #tempUpdLeadP
	drop table if exists #tempUpdLeadProcess
	drop table if exists #tempUpdEnqProcess
	drop table if exists #tempInstLeadProcess
	drop table if exists #tempInstEnqProcess

	CREATE table #tempImpEnqP(ROwNo int, ImportRow_Id bigint, importstart nvarchar(100), [importend] nvarchar(100))
	Create table #tempImpLeadP(ROwNo int, ImportRow_Id bigint, importstart nvarchar(100), [importend] nvarchar(100))
	Create table #tempUpdEnqP(ROwNo int, ImportRow_Id bigint, importstart nvarchar(100), [importend] nvarchar(100))
	Create table #tempUpdLeadP(ROwNo int, ImportRow_Id bigint, importstart nvarchar(100), [importend] nvarchar(100))
	Create table #tempUpdLeadProcess(ROwNo int, ImportRow_Id bigint, importstart nvarchar(100), [importend] nvarchar(100))
	Create table #tempUpdEnqProcess(ROwNo int, ImportRow_Id bigint, importstart nvarchar(100), [importend] nvarchar(100))
	Create table #tempInstLeadProcess(ROwNo int, ImportRow_Id bigint, importstart nvarchar(100), [importend] nvarchar(100))
	Create table #tempInstEnqProcess(ROwNo int, ImportRow_Id bigint, importstart nvarchar(100), [importend] nvarchar(100))

	 if(@date is null )
	 begin
		set @date=  DATEADD(Day,-1,CONVERT(date, GETDATE()))
	 end 
	declare @html nvarchar(max)=N'<html><head><title> </title><style>table, tr, th,td{border:1px solid;}</style></head>
									<body>##BodyData##</body></html>',
	@bodydata nvarchar(max)='',@ldUpdtProcess bigint , @ldUpdtUnProcess bigint,@ldUpdtTtl bigint , @ldUpdtProcessID nvarchar(max)='',@ldUpdtUnProcessID nvarchar(max),
	@enqUpdtProcess bigint , @enqUpdtUnProcess bigint,@enqUpdtTtl bigint , @enqUpdtProcessID nvarchar(max),@enqUpdtUnProcessID nvarchar(max) ,
	@ldInstProcess bigint , @ldInstUnProcess bigint,@ldInstTtl bigint , @ldInstProcessID nvarchar(max),@ldInstUnProcessID nvarchar(max) ,
	@enqInstProcess bigint , @enqInstUnProcess bigint,@enqInstTtl bigint , @enqInstProcessID nvarchar(max)='',@enqInstUnProcessID nvarchar(max),
	@BulkImport nvarchar(max),@BulkUpdate nvarchar(max), @Todate datetime, @UserMailid nvarchar(200), @ldUpdtTtlProcess bigint , @ldUpdtTtlUnProcess bigint , @enqUpdtTtlProcess bigint 
	, @enqUpdtTtlUnProcess bigint , @ldInstTtlProcess bigint , @ldInstTtlUnProcess bigint , @enqInstTtlProcess bigint , @enqInstTtlUnProcess bigint 
	,@min int=1, @max int,@importid bigint , @importstart nvarchar(100),@importend nvarchar(100),@insertleadprocesscnt bigint, @updateleadprocesscount  bigint 
	,@enqinsertprocesscnt bigint, @enqupdateprocesscount  bigint , @bulkprocessing nvarchar(max),@insertleadprocessID nvarchar(max), @updateleadprocessID  nvarchar(max) 
	,@enqinsertprocessID nvarchar(max), @enqupdateprocessID  nvarchar(max) 

	set @Todate = DATEADD(day,1,@date)
	--select @date , @Todate
	if(@parentid=0)
	Begin
		
		select @ldUpdtProcess= Count (Isprocessed) from Tbl_Lead_LeadUpdateImportData  (nolock) where  Isprocessed =1 and  ImportDate between @date and @Todate
		select @ldUpdtTtlProcess= Count (Isprocessed) from Tbl_Lead_LeadUpdateImportData (nolock) where Isprocessed =0 
		select @ldUpdtUnProcess= Count (Isprocessed) from Tbl_Lead_LeadUpdateImportData (nolock) where  Isprocessed =0 and  ImportDate between @date and @Todate
		select @ldUpdtTtlUnProcess= Count (Isprocessed) from Tbl_Lead_LeadUpdateImportData (nolock) where Isprocessed =0
		select @ldUpdtTtl=Sum(LeadCnt) from Tbl_Lead_LeadUpdateImportData (nolock) where ImportDate between @date and @Todate
		select @updateleadprocesscount=Count (Isprocessed)  from Tbl_Lead_LeadUpdateImportData (nolock) where ImportDate between @date and @Todate and Isprocessed =2 

		Insert into #tempUpdLeadP ( ROwNo, ImportRow_Id , importstart , [importend])
		select ROw_number() Over( Order by ImportRow_id desc ) ROwNo, ImportRow_Id , Convert ( varchar, importstart,13) importstart , Convert ( varchar, importend, 13) importend  from Tbl_Lead_LeadUpdateImportData (nolock) where Importdate between @date and @Todate and Isprocessed =1
		select @min=min(RowNo), @max=max(RowNo) from #tempUpdLeadP
		--select @ldUpdtTtl,* from #tempUpdLeadP
		if exists (select 1 from #tempUpdLeadP)
		begin
		set @ldUpdtProcessID='<table style="width:100%;border:0px;margin:0px;padding:0px;" cellpadding="0" cellspacing="0" border="none"><tr><th>Import Id</th><th>Import Start</th><th>Import End</th></tr>'
			while @min<=@max
			begin
				 select @importid=ImportRow_Id from #tempUpdLeadP where rowno=@min 
				 select @importstart=importstart from #tempUpdLeadP where rowno=@min 
				 select @importend=importend from #tempUpdLeadP where rowno=@min 
				 set @ldUpdtProcessID=@ldUpdtProcessID+'<tr><td>'+ISNULL(cast(@importid as varchar),'')+'</td><td>'+isnull(@importstart,'')+'</td><td>'+ISNULL(@importend,'')+'</td></tr>'
				set @min= @min+1
			end
			set @ldUpdtProcessID = @ldUpdtProcessID+'</table>'
		end

		Insert into #tempUpdLeadProcess ( ROwNo, ImportRow_Id , importstart , [importend])
		select ROw_number() Over( Order by ImportRow_id desc ) ROwNo, ImportRow_Id , Convert ( varchar, importstart,13) importstart , Convert ( varchar, importend, 13) importend  from Tbl_Lead_LeadUpdateImportData (nolock) where Importdate between @date and @Todate and Isprocessed =2
		select @min=min(RowNo), @max=max(RowNo) from #tempUpdLeadProcess
		--select @updateleadprocesscount,* from #tempUpdLeadProcess
		if exists (select 1 from #tempUpdLeadP)
		begin
		set @updateleadprocessID='<table style="width:100%;border:0px;margin:0px;padding:0px;" cellpadding="0" cellspacing="0" border="none"><tr><th>Import Id</th><th>Import Start</th><th>Import End</th></tr>'
			while @min<=@max
			begin
				 select @importid=ImportRow_Id,@importstart=importstart,@importend=importend from #tempUpdLeadProcess where rowno=@min 
				 set @updateleadprocessID=@updateleadprocessID+'<tr><td>'+ISNULL(cast(@importid as varchar),'')+'</td><td>'+isnull(@importstart,'')+'</td><td>'+ISNULL(@importend,'')+'</td></tr>'
				set @min= @min+1
			end
			set @updateleadprocessID = @updateleadprocessID+'</table>'
		end


		--select @ldUpdtProcessID
		--select @ldUpdtProcessID= String_agg( Convert(nvarchar(max),ImportRow_Id),', ') from Tbl_Lead_LeadUpdateImportData (nolock) where Importdate between @date and @Todate and Isprocessed =1
		select @ldUpdtUnProcessID= String_agg( Convert(nvarchar(max),ImportRow_Id),', ') from Tbl_Lead_LeadUpdateImportData (nolock) where Importdate between @date and @Todate and Isprocessed =0
		
		
		 select @enqUpdtProcess = Count (Isprocessed) from Tbl_Enquiry_EnquiryUpdateImportData (nolock) where  Isprocessed =1 and  ImportDate between @date and @Todate
		 select @enqUpdtUnProcess= Count (Isprocessed) from Tbl_Enquiry_EnquiryUpdateImportData (nolock) where Isprocessed =0 and ImportDate between @date and @Todate
		  select @enqUpdtTtlProcess = Count (Isprocessed) from Tbl_Enquiry_EnquiryUpdateImportData (nolock) where  Isprocessed =1 
		 select @enqUpdtTtlUnProcess= Count (Isprocessed) from Tbl_Enquiry_EnquiryUpdateImportData (nolock) where Isprocessed =0 
		 select @enqUpdtTtl= Sum(EnquiryCnt) from Tbl_Enquiry_EnquiryUpdateImportData (nolock) where ImportDate between @date and @Todate 
		select @enqupdateprocesscount=Count (Isprocessed)  from Tbl_Enquiry_EnquiryUpdateImportData (nolock) where ImportDate between @date and @Todate and Isprocessed =2 

		Insert into #tempUpdEnqP ( ROwNo, ImportRow_Id , importstart , [importend])
		select ROw_number() Over( Order by ImportRow_id desc ) ROwNo, ImportRow_Id , Convert ( varchar, importstart,13) importstart , Convert ( varchar, importend, 13) importend  from Tbl_Enquiry_EnquiryUpdateImportData (nolock) where Importdate between @date and @Todate and Isprocessed =1
		select @min=min(RowNo), @max=max(RowNo) from #tempUpdEnqP
		--select * from #tempImp
		if exists (select 1 from #tempUpdEnqP)
		begin
		set @enqUpdtProcessID='<table style="width:100%;border:0px;margin:0px;padding:0px;" cellpadding="0" cellspacing="0" border="none"><tr><th>Import Id</th><th>Import Start</th><th>Import End</th></tr>'
			while @min<=@max
			begin
				 select @importid=ImportRow_Id from #tempUpdEnqP where rowno=@min 
				 select @importstart=importstart from #tempUpdEnqP where rowno=@min 
				 select @importend=importend from #tempUpdEnqP where rowno=@min 
				 set @enqUpdtProcessID=@enqUpdtProcessID+'<tr><td>'+ISNULL(cast(@importid as varchar),'')+'</td><td>'+isnull(@importstart,'')+'</td><td>'+ISNULL(@importend,'')+'</td></tr>'
				set @min= @min+1
			end
			set @enqUpdtProcessID = @enqUpdtProcessID+'</table>'
		end

		Insert into #tempUpdEnqProcess ( ROwNo, ImportRow_Id , importstart , [importend])
		select ROw_number() Over( Order by ImportRow_id desc ) ROwNo, ImportRow_Id , Convert ( varchar, importstart,13) importstart , Convert ( varchar, importend, 13) importend  from Tbl_Enquiry_EnquiryUpdateImportData (nolock) where Importdate between @date and @Todate and Isprocessed =2
		select @min=min(RowNo), @max=max(RowNo) from #tempUpdEnqProcess
		--select @enqupdateprocesscount,* from #tempUpdEnqProcess
		if exists (select 1 from #tempUpdLeadP)
		begin
		set @enqupdateprocessID='<table style="width:100%;border:0px;margin:0px;padding:0px;" cellpadding="0" cellspacing="0" border="none"><tr><th>Import Id</th><th>Import Start</th><th>Import End</th></tr>'
			while @min<=@max
			begin
				 select @importid=ImportRow_Id,@importstart=importstart,@importend=importend from #tempUpdEnqProcess where rowno=@min 
				 set @enqupdateprocessID=@enqupdateprocessID+'<tr><td>'+ISNULL(cast(@importid as varchar),'')+'</td><td>'+isnull(@importstart,'')+'</td><td>'+ISNULL(@importend,'')+'</td></tr>'
				set @min= @min+1
			end
			set @enqupdateprocessID = @enqupdateprocessID+'</table>'
		end
		--select @enqUpdtProcessID=STRING_AGG( Convert(nvarchar(max),ImportRow_Id) ,', ')from Tbl_Enquiry_EnquiryUpdateImportData (nolock) where Importdate between @date and @Todate and Isprocessed =0
		select @enqUpdtUnProcessID=STRING_AGG( Convert(nvarchar(max),ImportRow_Id) ,', ')from Tbl_Enquiry_EnquiryUpdateImportData (nolock) where Importdate between @date and @Todate and Isprocessed =1
		
		 select @ldInstProcess= Count (Isprocessed) from tbl_LeadImportSummary (nolock) where  Isprocessed =1 and  ImportDate between @date and @Todate
		 select @ldInstUnProcess= Count (Isprocessed) from tbl_LeadImportSummary (nolock) where Isprocessed =0 and ImportDate between @date and @Todate
		  select @ldInstTtlProcess= Count (Isprocessed) from tbl_LeadImportSummary (nolock) where  Isprocessed =1 
		 select @ldInstTtlUnProcess= Count (Isprocessed) from tbl_LeadImportSummary (nolock) where Isprocessed =0 
		 select @ldInstTtl= Sum(LeadCnt) from tbl_LeadImportSummary where ImportDate between @date and @Todate 
		select @insertleadprocesscnt=Count (Isprocessed)  from tbl_LeadImportSummary (nolock) where ImportDate between @date and @Todate and Isprocessed =2 

		Insert into #tempImpLeadP ( ROwNo, ImportRow_Id , importstart , [importend])
		select ROw_number() Over( Order by ImportRow_id desc ) ROwNo, ImportRow_Id , Convert ( varchar, importstart,13) importstart , Convert ( varchar, importend, 13) importend  from tbl_LeadImportSummary (nolock) where Importdate between @date and @Todate and Isprocessed =1
		select @min=min(RowNo), @max=max(RowNo) from #tempImpLeadP
		--select * from #tempImp
		if exists (select 1 from #tempImpLeadP)
		begin
		set @ldInstProcessID='<table style="width:100%;border:0px;margin:0px;padding:0px;" cellpadding="0" cellspacing="0" border="none"><tr><th>Import Id</th><th>Import Start</th><th>Import End</th></tr>'
			while @min<=@max
			begin
				 select @importid=ImportRow_Id from #tempImpLeadP where rowno=@min 
				 select @importstart=importstart from #tempImpLeadP where rowno=@min 
				 select @importend=importend from #tempImpLeadP where rowno=@min 
				 set @ldInstProcessID=@ldInstProcessID+'<tr><td>'+ISNULL(cast(@importid as varchar),'')+'</td><td>'+isnull(@importstart,'')+'</td><td>'+ISNULL(@importend,'')+'</td></tr>'
				set @min= @min+1
			end
			set @ldInstProcessID = @ldInstProcessID+'</table>'
		end

		Insert into #tempInstLeadProcess ( ROwNo, ImportRow_Id , importstart , [importend])
		select ROw_number() Over( Order by ImportRow_id desc ) ROwNo, ImportRow_Id , Convert ( varchar, importstart,13) importstart , Convert ( varchar, importend, 13) importend  from Tbl_Enquiry_EnquiryUpdateImportData (nolock) where Importdate between @date and @Todate and Isprocessed =2
		select @min=min(RowNo), @max=max(RowNo) from #tempInstLeadProcess
		--select @enqupdateprocesscount,* from #tempInstLeadProcess
		if exists (select 1 from #tempUpdLeadP)
		begin
		set @insertleadprocessID='<table style="width:100%;border:0px;margin:0px;padding:0px;" cellpadding="0" cellspacing="0" border="none"><tr><th>Import Id</th><th>Import Start</th><th>Import End</th></tr>'
			while @min<=@max
			begin
				 select @importid=ImportRow_Id,@importstart=importstart,@importend=importend from #tempInstLeadProcess where rowno=@min 
				 set @insertleadprocessID=@insertleadprocessID+'<tr><td>'+ISNULL(cast(@importid as varchar),'')+'</td><td>'+isnull(@importstart,'')+'</td><td>'+ISNULL(@importend,'')+'</td></tr>'
				set @min= @min+1
			end
			set @insertleadprocessID = @insertleadprocessID+'</table>'
