/* ============================================================
   Procedure: [dbo].[usp_get_info_for_whatsapp_agent]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_get_info_for_whatsapp_agent
@agentid bigint
as
begin
declare @currenttemplates nvarchar(max),@pipelines nvarchar(max),@parentid bigint,@channeltokenid bigint
select @parentid=parentid from tbl_ai_agents(nolock) where agentid=@agentid

select @currenttemplates=(select top 10 templatebody from [10.0.0.135].mysmsconversations.dbo.convtemplates with (nolock) where parent_id=@parentid and 
templatestatus='APPROVED' and created_by_agent_id is null order by id desc FOR json path)
select @pipelines = 
(select p.name as Pipeline ,s.name as Stage  from Pipeline_Master p join PipelineStages s on p.id=s.PipelineID where parentid=@parentid and
p.IsDeleted=0 and s.isdeleted=0 
order by p.id,s.Sequence FOR json path)

select @pipelines as Pipelines,@currenttemplates CurrentWhatsappTemplates
end



GO

/* ============================================================
   Procedure: [dbo].[usp_Get_Int_smsprice_exc]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_Get_Int_smsprice_exc]            
(   
@User_id bigint  
)  
AS                        
BEGIN  
if @User_id > 0  
begin
select country_code, CountryName, Price, isnull((Select Price from Int_sms_price_exc 
where user_id = @User_id and country_code = cm.country_code),0) mPrice
from  IntSMSRateMast cm order by  CountryName 
end

else  
begin
select cm.CountryName, ex.* from dbo.Int_sms_price_exc ex inner  join    
 dbo.IntSMSRateMast cm on cm.country_code = ex.country_code  order by  cm.CountryName 
end
END


GO

/* ============================================================
   Procedure: [dbo].[usp_Get_IntSMSPrice]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

            
           
CREATE   PROCEDURE [dbo].[usp_Get_IntSMSPrice] --'A-D'           
(   
@opt varchar(3)  
)  
AS                        
BEGIN 
if @opt=''  
begin  
select CountryName,isnull(country_code,'')country_code ,Price, inr_Price from dbo.IntSMSRateMast   
 Order by  CountryName                            
end  
if @opt='A-D'  
begin  
  
select CountryName,isnull(country_code,'')country_code ,Price, inr_Price  from dbo.IntSMSRateMast   
where CountryName like 'A%' or CountryName like 'B%'  or CountryName like 'C%' or  
CountryName like 'D%' Order by  CountryName                            
end  
if @opt='E-H'  
begin  
  
select CountryName,isnull(country_code,'')country_code ,Price, inr_Price  from dbo.IntSMSRateMast   
where CountryName like 'E%' or CountryName like 'F%' or CountryName like 'G%' or  
CountryName like 'H%' Order by  CountryName                            
end   
if @opt='I-L'  
begin  
  
select CountryName,isnull(country_code,'')country_code ,Price, inr_Price  from dbo.IntSMSRateMast   
where CountryName like 'I%' or CountryName like 'J%' or CountryName like 'K%' or  
CountryName like 'L%' Order by  CountryName                            
end       
if @opt='M-P'  
begin  
  
select CountryName,isnull(country_code,'')country_code ,Price, inr_Price  from dbo.IntSMSRateMast   
where CountryName like 'M%' or CountryName like 'N%'  or CountryName like 'O%' or  
CountryName like 'P%' Order by  CountryName                            
end    
if @opt='Q-T'  
begin  
  
select CountryName,isnull(country_code,'')country_code ,Price, inr_Price  from dbo.IntSMSRateMast   
where CountryName like 'Q%' or CountryName like 'R%'  or CountryName like 'S%' or  
CountryName like 'T%' Order by  CountryName                            
end   
if @opt='U-Z'  
begin  
  
select CountryName,isnull(country_code,'')country_code ,Price, inr_Price  from dbo.IntSMSRateMast   
where CountryName like 'U%' or CountryName like 'V%'  or CountryName like 'W%' or  
CountryName like 'X%' or CountryName like 'Y%' or CountryName like 'Z%' Order by  CountryName                            
end                                     
END 


GO

/* ============================================================
   Procedure: [dbo].[Usp_Get_Kitever_ClientLeadDetails]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC Usp_Get_Kitever_ClientLeadDetails --25           
(
    @SearchID BIGINT,
    @SearchText VARCHAR(50) = NULL,
    @PageSize INT = 0
)            
AS                   
BEGIN
	BEGIN TRY
		SELECT DISTINCT fgun3.MicrositeName,
		       fgun3.FirstName,
		       fgun3.LastName,
		       fgun3.Email,
		       fgun3.Mobile,
		       fgun3.[ADDRESS],
		       fgun3.City,
		       fgun3.Zip,
		       fgun3.Remarks,
		       fgun3.Source
		FROM   SearchDetails AS sd
		       OUTER APPLY funcToGet_Kitever_LeadMicrosite_Datewise(sd.MicrositeName, sd.FromDate, sd.ToDate) AS 
		fgun3
		WHERE  sd.ID = @SearchID
		       AND fgun3.MicrositeName IS NOT NULL
	END TRY
	BEGIN CATCH
		SELECT ERROR_NUMBER()     AS ErrorNumber,
		       ERROR_SEVERITY()   AS ErrorSeverity,
		       ERROR_STATE()      AS ErrorState,
		       ERROR_PROCEDURE()  AS ErrorProcedure,
		       ERROR_LINE()       AS ErrorLine,
		       ERROR_MESSAGE()    AS ErrorMessage
	END CATCH
END 


GO

