/* ============================================================
   Procedure: [dbo].[usp_get_leadinteractionhistory]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC usp_get_leadinteractionhistory  -- 139,32222
(
@LeadNo bigint,
@ParentID bigint
)
as
begin
select l.CreatedOn, f.FollowupStatus, l.NextStatusDate, l.Products,l.AmountPaid, u.FName+' '+u.LName as UserName
from leadinteractionhistory l(nolock)  
inner join FollowUp_Status f(nolock)
on l.FollowUpStatus = f.id
inner join user_detail u(nolock)
on l.AssignedTo = u.User_ID
where l.ParentID = @ParentID and l.LeadNo = @LeadNo
and l.CreatedOn = (select max(CreatedOn) from LeadInteractionHistory (nolock) where ParentID = @ParentID and LeadNo = @LeadNo) 


end

--select * from tbl_LeadNotes (nolock) where ParentID = 32222 and LeadID = 327780


GO

