CREATE   PROCEDURE usp_get_leads_to_contact --7    
@agentid bigint    
as    
begin    
 --declare @agentid bigint=164 --108--107--105 --7    
declare @parentid bigint,@predefinedsettings nvarchar(max),@agentname nvarchar(200),@max_execution int,@additional_details nvarchar(max) ,@errorid int,@assistantid nvarchar(200),@contacts_inserted int=0    
  
select @parentid=parentid,@agentname=Name ,@predefinedsettings=predefined_settings,@max_execution=JSON_VALUE(predefined_settings,'$.max_execution')     
,@assistantid=AssistantId    
from tbl_ai_Agents (nolock) where agentid=@agentid  and status='active' and isnull(dormant_till,dateadd(d,-1,getutcdate()))<getutcdate()    
  
print concat(@parentid,'=parentid, ',@agentname,'=Name, ' ,@predefinedsettings,'=predefined_settings, ',@max_execution,'=max-execution, '     
,@assistantid,'=AssistantId')    
  
if isnull(@parentid,0)<>0    
begin    
print 'A'  
    
if @max_execution<>0 and @max_execution>(select count(1) from tbl_ai_agent_execution_outbox(nolock) where agentid=@agentid and cast(createdon as date)=cast(getutcdate() as date))    
begin    
print 'B'  
  
if @parentid>0    
begin    
print 'C'  
  
declare @segments nvarchar(max),@Days nvarchar(max),@contactFrequency int,@max_per_lead int,@retry_lead_after int,@lead_details nvarchar(max),    
@daytoday varchar(10)=datename(dw,getutcdate()),@segmentid bigint=0,@batchcount int=dbo.fn_min_no(500,@max_execution),@segment_count int,@primary_language varchar(100),@batchsize int=50,@channel varchar(20),@start_entityid bigint=0, @RowId int=1  
    
SELECT    
    @segments = segments,    
    @Days = days,    
    @contactFrequency = contactFrequency,    
    @primary_language = primary_language,    
    @max_per_lead = max_per_lead,    
    @retry_lead_after = retry_lead_after    
FROM OPENJSON(@predefinedsettings)    
WITH (    
    segments nvarchar(max) '$.segments' AS JSON,    
    Days nvarchar(max) '$.days' AS JSON,    
    contactFrequency int '$.contactFrequency',    
    primary_language nvarchar(200) '$.primary_language',    
    max_per_lead int '$.max_per_lead',    
    retry_lead_after int '$.retry_lead_after'    
)    
drop table if exists #segments    
drop table if exists #days    
    
create table #days(weekday nvarchar(10),fromtime time,totime time)    
    
    
insert into #days(weekday,fromtime,totime)    
SELECT *    
FROM OPENJSON(@days)    
WITH (    
    day varchar(10),    
    fromtime time,    
 totime time    
)    
    
print concat(    @segments,' = segments, ',    
    @Days,' = days, ',    
    @contactFrequency,' = contactFrequency, ',    
    @primary_language ,'= primary_language, ',    
    @max_per_lead ,'= max_per_lead, ',    
    @retry_lead_after,' = retry_lead_after'    
)    
    
--select * from #days    
  
    
    if exists(SELECT 1 FROM #days WHERE [weekday] = DATENAME(WEEKDAY, GETDATE()) AND CAST(GETUTCDATE() AS TIME) >= fromtime    AND CAST(GETUTCDATE() AS TIME) <= totime)    
    begin    
      print 'D'  
  
        create table #segments(rowid int identity(1,1),segmentid bigint,channel nvarchar(50))    
    
        insert into #segments(segmentid,channel)    
        SELECT *    
        FROM OPENJSON(@segments)    
        WITH (    
            segment_id bigint,    
            --segments bigint,    
            channel nvarchar(50)    
        )    
    
        --select * from #segments    
        select @segment_count=count(1) from #segments    
        Delete From tbl_SearchResult Where SPId=@@spid    
    
        while @segment_count>0 and (select count(1) from tbl_ai_agent_entity_for_execution(nolock) where agentid=@agentid and isprocessed=0)<@batchcount    
        begin    
            print 'while begin'    
            --select @segmentid=min(segmentid) from #segments where segmentid>@segmentid    
            select @segmentid=segmentid,@channel=channel from #segments where rowid=@RowId    
            --select @channel=channel from #segments where segmentid=@segmentid     
            select @start_entityid=max(entityid) from tbl_ai_agent_entity_for_execution(nolock)  where agentid=@agentid and searchid=@segmentid and     
            createdon>dateadd(d,0-@contactFrequency,getutcdate())    
            select @start_entityid=isnull(@start_entityid,0)    
            print concat('now getting data for segment id: ',@segmentid, ', parentid: ',@ParentId, ', channel: ',@channel, ', startentity', @start_entityid)    
            Exec [usp_conv_ExecuteCustomUserSearch_agent_batchsize_start_entityid_insert] @ParentId, @segmentid, @batchsize,@start_entityid,@channel    
    
            drop table if exists #tbl_ai_agent_entity_for_execution    
            select * into #tbl_ai_agent_entity_for_execution from tbl_ai_agent_entity_for_execution(nolock)    
            --where agentid=@agentid and createdon>dateadd(d,0-@contactFrequency,getutcdate())    
            where agentid=@agentid and searchid=@segmentid and createdon>dateadd(d,0-@contactFrequency,getutcdate()) and channel=@channel  
    
            delete t from tbl_SearchResult t where exists    
            (select 1 from #tbl_ai_agent_entity_for_execution a with (nolock)     
            where t.EntityID=a.entityid and t.EntityName=a.entityname and isprocessed=0) and t.spid=@@spid and t.SearchId=@segmentid  
    
            delete t from tbl_SearchResult t where exists     
            (select 1 from tbl_ai_agent_entity_status a (nolock) where      
            t.EntityID=a.entityid and t.EntityName=a.entityname and a.agentid=@agentid and     
            (a.dormant_till>getutcdate() or a.do_not_contact=1 or a.human_alert=1  or     
            dbo.fn_get_lastcontact_agent_entity(@agentid,t.entityname,t.entityid)>dateadd(d,0-@retry_lead_after,getutcdate()))) and t.spid=@@spid and t.SearchId=@segmentid  
            --((select count(1) from tbl_ai_agent_entity_for_execution e where e.entityname=t.EntityName and e.entityid=t.entityid) >=@max_per_lead    
    
    
    
            if (select count(1) from tbl_SearchResult(nolock) t  where SPID=@@spid and SearchId=@segmentid)>=@batchcount    
            begin    
                print 'E'  
                break;    
            end    
  
            set @RowId=@RowId+1  
            set @segment_count=@segment_count-1  
        end    
        
        --print 'return'
        --return
        insert into tbl_ai_agent_entity_for_execution(agentid,parentid,searchid,entityname,entityid,channel,assistantid)    
        select @agentid,parentid,@segmentid,entityname,entityid,@channel,@assistantid from tbl_SearchResult(nolock) where searchid=@segmentid and spid=@@spid    
        select @contacts_inserted=@contacts_inserted+@@ROWCOUNT    
        delete from tbl_SearchResult where searchid=@segmentid and spid=@@spid    
    
    end    
end    
else    
begin    
print 'F'  
  
select @additional_details =concat('Agent ',@agentname, ' is inactive and unable to run'),@errorid=1    
exec usp_ai_inserterror @agentid ,@errorid,@additional_details    
    
end    
end    
else    
begin    
print 'G'  
  
select @additional_details =concat('Agent ',@agentname, ' has reached max executions for the day'),@errorid=2    
exec usp_ai_inserterror @agentid ,@errorid,@additional_details    
    
end    
end    
  print 'H'  
  
select @contacts_inserted as Contacts_inserted    
  
end    



GO

/* ============================================================
   Procedure: [dbo].[Usp_get_linkUrl]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

    
CREATE   PROC [dbo].[Usp_get_linkUrl]     
(        
@surl_id bigint,         
@Parent_id bigint,         
@srchtxt varchar(100),        
@opt int        
)        
as         
begin        
declare @reslt as varchar(100)=''    
declare @totcount as bigint      
    
 select @totcount=max(id) from randomexp with (nolock)    
      
if @opt = 0        
begin        
if @surl_id =0        
begin        
if @srchtxt!=''        
 select um.*, ud.User_Login user_nm, isnull(us.User_Login,'') Created_nm ,        
 case when um.access_type = 0 then 'Private' else 'Public' end as Access_Lavel,    
 @totcount as totKey, @totcount-isnull(LastId,0) as avl_key,isnull(LastId,0) used_key       
 from  dbo.Link_urlMaster um  (nolock)       
 inner join user_detail ud    (nolock)    
 on ud.User_ID = um.Parent_id        
 left outer join user_detail us  (nolock)      
 on us.User_ID = um.CreatedBy        
 where um.Parent_id=@Parent_id and um.status= 1 and         
 (shorturl like '%'+@srchtxt+'%'        
 or ud.User_Login like '%'+@srchtxt+'%' or        
  access_type like '%'+@srchtxt+'%'        
  or us.User_Login like '%'+@srchtxt+'%')  order by user_nm        
else        
   select um.*, ud.User_Login user_nm, isnull(us.User_Login,'') Created_nm ,        
 case when um.access_type = 0 then 'Private' else 'Public' end as Access_Lavel,    
 @totcount as totKey, @totcount-isnull(LastId,0) as avl_key,isnull(LastId,0) used_key             
 from  dbo.Link_urlMaster um   (nolock)      
 inner join user_detail ud      (nolock)  
 on ud.User_ID = um.Parent_id        
 left outer join user_detail us       (nolock)  
 on us.User_ID = um.CreatedBy        
  where um.Parent_id=@Parent_id and um.status= 1 order by user_nm        
end        
else        
begin        
   select um.*, ud.User_Login user_nm, isnull(us.User_Login,'') Created_nm ,        
 case when um.access_type = 0 then 'Private' else 'Public' end as Access_Lavel,    
 @totcount as totKey, @totcount-isnull(LastId,0) as avl_key,isnull(LastId,0) used_key         
 from  dbo.Link_urlMaster um       (nolock)  
 inner join user_detail ud      (nolock)  
 on ud.User_ID = um.Parent_id        
 left outer join user_detail us      (nolock)  
 on us.User_ID = um.CreatedBy        
 where surl_id=@surl_id  order by user_nm        
end        
end        
else        
begin        
select um.*,case when um.access_type = 0 then 'Private' else 'Public' end as Access_Lavel  ,@totcount as totKey, @totcount-isnull(LastId,0) as avl_key,isnull(LastId,0) used_key       
 from  dbo.Link_urlMaster um  (nolock)       
 where (Parent_id=@Parent_id or access_type = 1) and status = 1        
end        
end 





GO

