/* ============================================================
   Procedure: [dbo].[usp_get_pending_leads_for_context_extraction]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE dbo.usp_get_pending_leads_for_context_extraction
    @BatchSize INT = 50
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Now DATETIME = GETUTCDATE();

    DECLARE @out TABLE (
        id BIGINT,
        agentid BIGINT,
        entityname NVARCHAR(200),
        entityid BIGINT,
        parentid BIGINT,
        searchid NVARCHAR(200),
        channel NVARCHAR(50),
        assistantid nvarchar(100),
        AttemptCount INT
    );

    -- Atomically claim up to @BatchSize rows for processing using UPDLOCK + READPAST
    UPDATE a
    SET Processing = 1,
        ProcessingStartedAt = @Now,
        AttemptCount = ISNULL(a.AttemptCount, 0) + 1
    OUTPUT inserted.id, inserted.agentid, inserted.entityname, inserted.entityid, inserted.parentid,
           inserted.searchid, inserted.channel, inserted.assistantid, ISNULL(inserted.AttemptCount,0)
    INTO @out (id, agentid, entityname, entityid, parentid, searchid, channel, assistantid, AttemptCount)
    FROM dbo.tbl_ai_agent_entity_for_execution AS a
    INNER JOIN (
        SELECT TOP (@BatchSize) id
        FROM dbo.tbl_ai_agent_entity_for_execution WITH (ROWLOCK, UPDLOCK, READPAST)
        WHERE isprocessed = 0
          AND (Processing = 0 OR Processing IS NULL)
          AND ISNULL(AttemptCount, 0) < 3
        ORDER BY id ASC
    ) AS c ON a.id = c.id;

    -- Return claimed rows
    SELECT id, agentid, entityname, entityid, parentid, searchid, channel, assistantid, AttemptCount
    FROM @out;
END;



GO

