as  
select isnull((select top 1 (case smppid when 4 then 'Spice' Else 'Vfirst' end) from user_detail(nolock) where (smppid=4 or smppid=7)), 'NQ') 
union all  
select isnull((select top 1 (case smppid when 5 then 'Spice' Else 'Vfirst' end) from user_detail(nolock) where (smppid=5 or smppid=8)), 'NQ')  
union all  
select isnull((select top 1 (case smppid when 6 then 'Spice' Else 'Vfirst' end) from user_detail(nolock) where (smppid=6 or smppid=9)), 'NQ')  
union all  
select top 1 (case smppid when 2 then 'Spice' Else 'Vfirst' end) from user_detail(nolock) where userfilter ='MTIX_PRO'  
union all  
select top 1 (case smppid when 2 then 'Spice' Else 'Vfirst' end) from user_detail(nolock) where userfilter ='MTIX_TR'  
union all  
select top 1 (case smppid when 2 then 'Spice' Else 'Vfirst' end) from user_detail(nolock) where userfilter ='MTIX_TRC'  
union all  
select isnull((select top 1 (case smppid when 4 then 'Spice' Else 'Vfirst' end) from MessageQueueTwo(nolock)),'NQ')  
union all  
select isnull((select top 1 (case smppid when 5 then 'Spice' Else 'Vfirst' end) from MESSAGEQUEUEDEMO_TRANS(nolock)),'NQ')  
union all  
select isnull((select top 1 (case smppid when 6 then 'Spice' Else 'Vfirst' end) from MESSAGEQUEUEDEMO_TRC(nolock)),'NQ')  
union all  
select isnull((select top 1 (case smppid when 2 then 'Spice' Else 'Vfirst' end) from MessageQueueProRoute(nolock)),'NQ')  
union all  
select isnull((select top 1 (case smppid when 2 then 'Spice' Else 'Vfirst' end) from MessageQueueNew(nolock)),'NQ')  
union all  
select isnull((select top 1 (case smppid when 2 then 'Spice' Else 'Vfirst' end) from MessageQueueTrcRoute(nolock)),'NQ')


