  ,(  
   SELECT SUBSTRING((  
      SELECT ',' + PersonName AS 'data()'  
      FROM tbl_location_territory_mapping  
      WHERE Territory_Id = t.ID  
       AND ROLE = 'Manager'  
      FOR XML PATH('')  
      ), 2, 9999) AS Manager  
   ) AS Manager  
  ,(  
   SELECT SUBSTRING((  
      SELECT ',' + PersonName AS 'data()'  
      FROM tbl_location_territory_mapping  
      WHERE Territory_Id = t.ID  
       AND ROLE = 'User'  
      FOR XML PATH('')  
      ), 2, 9999) AS Executive  
   ) AS Executive  
 FROM tbl_location_territory t(NOLOCK)  
 INNER JOIN tbl_location_territory_mapping m(NOLOCK) ON t.ID = m.Territory_Id  
 WHERE t.ParentID = @ParentID  
 AND (      
                ISNULL(@Territory, '') = ''      
                OR t.Name LIKE '%' + @Territory + '%'      
            )  
 --end        
 --else        
 --begin        
 --select distinct t.ID,t.Name, t.Description,t.ParentID,        
