 --(Select SUBSTRING(( SELECT ',' + PersonName AS 'data()' FROM tbl_location_territory_mapping where Territory_Id = t.ID and User_ID = @User_ID         
 --        and Role = 'User' FOR XML PATH('')), 2 , 9999) As Executive)  As Executive      
 --from tbl_location_territory t(nolock)         
 --inner join tbl_location_territory_mapping m(nolock)        
 --on t.ID = m.Territory_Id        
 --where m.User_ID = @User_ID  and t.ParentID = @ParentID       
 --end        
 EXEC MySmsAudit.dbo.Usp_AuditTableDataByParentId @User_id = @User_ID  
  ,@Activity_type = 'View_UsrTritory '  
  ,@ActionType = 'S'  
  ,@RowJson = ''  
  ,@Table_name = 'tbl_location_territory'  
