/* ============================================================
   Procedure: [dbo].[usp_Get_Unconverted_Leads]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].usp_Get_Unconverted_Leads-- 41181
@parentid bigint
as
begin
SELECT 
        p.id as lead_id,
        i.Name lead_source,
        --i.name lead_industry,
        p.CreatedOn lead_added_date,
        --dbo.fn_getfirstenrollment(p.id)
		null first_conversion_date,
        dbo.fn_getscorebeforenrollment(p.id) AS lead_cumulative_score_before_first_conversion,
        isnull(no_of_followups,0) AS total_followups_before_first_conversion,
        isnull(no_of_activities,0) AS total_activities_before_first_conversion,
        DATEDIFF(DAY, LastFollowupDate, GETDATE()) AS days_since_last_followup,
        DATEDIFF(DAY, LastActivityDate, GETDATE()) AS days_since_last_activity,
        --CASE 
        --    WHEN dbo.fn_getfirstenrollment(p.id) IS NOT NULL THEN 1 
        --    ELSE 0 
        --END
		0
		AS is_converted
    FROM userleads p (nolock) 
	left join UserSourceSettings i (nolock) on i.SourceID=p.SourceName 
	left join (select id_lead,count(1) no_of_followups,max(cast(CreatedOn as date)) LastFollowupDate from leadinteractionhistory(nolock)
	--where 	cast(CreatedOn as date)<=isnull(dbo.[fn_getfirstenrollment](id_lead),getdate()) 
	group by id_lead) f on f.id_lead=p.id
	left join (select leadid,count(1) as no_of_activities,max(cast(eventdate as date)) LastActivityDate from tbl_leadeventhistory(nolock) 
	--where 	cast(eventdate as date)<isnull(dbo.[fn_getfirstenrollment](leadid),getdate()) 
	group by leadid
	) u on u.leadid=p.id
	where p.parentid=@parentid and dbo.[fn_getfirstenrollment](p.id) is null
	

end



GO

