/* ============================================================
   Procedure: [dbo].[usp_get_webhook_secret]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON



-- -----------------------------------------------------------------------------
-- 3) usp_get_webhook_secret - fetch encrypted secret for a bot's webhook.
--    Resolves bot_type+bot_id -> parentid internally, then looks up by
--    (parentid, secret_ref). Returns 0 or 1 rows. Column [encrypted_value]
--    is VARBINARY; the API converts to base64.
-- -----------------------------------------------------------------------------
CREATE   PROCEDURE usp_get_webhook_secret
    @bot_type   VARCHAR(20),
    @bot_id     BIGINT,
    @secret_ref VARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @parentid BIGINT;

    IF @bot_type = 'voice'
    BEGIN
        SELECT @parentid = parentid
        FROM voice_bot_details (NOLOCK)
        WHERE id = @bot_id AND isactive = 1;
    END
    -- ELSE IF @bot_type = 'chat'  -- add chat_bot_details lookup when chat goes live
    -- BEGIN
    --     SELECT @parentid = parentid FROM chat_bot_details WHERE id = @bot_id;
    -- END

    IF @parentid IS NULL
    BEGIN
        -- Return zero rows; API will respond 404.
        RETURN;
    END

    SELECT TOP 1
        encrypted_value
    FROM webhook_secret (NOLOCK)
    WHERE parentid   = @parentid
      AND secret_ref = @secret_ref;
END



GO

