/* ============================================================
   Procedure: [dbo].[Usp_GetAccount_New]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE dbo.Usp_GetAccount_New --'income',335,'selling price'  
(  
 @AccountType nvarchar(20) ,  
 @UserID bigint,  
 @calledfor nvarchar(50)=null  
)   
as   
Begin  
       
   Declare  @ParentID bigint = 0,@accounttypeid int  
   select top 1 @accounttypeid=id from [MySMSInvoicing].[dbo].[accounttype](nolock) where isactive = 1 and pat_id=0 and accounttype=@AccountType  
   select top 1 @ParentID = isnull(ParentID,USER_ID) from mysms.dbo.user_Detail(nolock)  where USER_ID = @UserID    
  
  select a.id,name,accounttype,name + ' ( '+accounttype +' )' DisplayName  
   FROM [MySMSInvoicing].[dbo].[accounts](nolock) a  
   join (  
       select id,parentid,accounttype from [MySMSInvoicing].[dbo].[accounttype](nolock) where isactive = 1 and  pat_id = @AccountTypeID and parentid in (0,@ParentID)  
     ) t on a.accounttype_id=t.id  
     and enabled = 1 and a.parentid in (0,@ParentID)   
  order by case   
  when @calledfor ='cost price' and name='Cost of Goods sold' then 0   
  when @calledfor ='selling price' and name='Sales' then 0   
   else 1 end  
End  





GO

