-- Exec usp_GetActiveCustomFields 335  
CREATE   PROCEDURE usp_GetActiveCustomFields  
 @parentID bigint            
AS            
BEGIN
  SET NOCOUNT ON;            
            
    SELECT [field_ID]
      ,[ParentID]            
      ,[fieldname]            
      ,(case[datatype] when 'd' then 'Date' when 'f' then 'Numeric' when 'v' then 'Text' end) as [datatype]          
      ,[sequence]            
      ,[minvalue]            
      ,[maxvalue]            
      ,[addedon]            
      ,[isActive]            
      ,[isMandatory]            
      ,[defaultValue]      
      ,[currentDate]            
  FROM [customfields] where [ParentID]=@parentID and [isActive]='True' order by [sequence] asc            
END   



