/* ============================================================
   Procedure: [dbo].[Usp_getAdDetails]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE dbo.Usp_getAdDetails --335    
(    
 @ParentID bigint    
)    
as    
Begin    
       
    SELECT    
       ADR.ID    
      ,ADR.PageID  
  ,(  
    select top 1 isnull(PageName,'') from PageRequests where ID = ADR.PageID       
   )  
    as PageName  
       
   ,
   isnull( (    
      select isnull(URL,'') from DigitalMarketingEntities where PageRequestID = ADR.PageID
	   --in (select top 1 TypeID from PageRequests where ID = ADR.PageID)    
    ),'') as URL    
      ,ADR.AddName    
      ,ADR.RequestType    
      ,ADR.Content    
      ,ADR.Remarks    
      ,ADR.Amount    
      ,ADR.CreatedOn    
      ,ADR.CreatedBy    
      ,(Select user_login from User_Detail where User_ID = ADR.CreatedBy) as  CreatedByName    
   ,    
     STUFF((SELECT ';' + cast(AD.DocPath as nvarchar(max)) --Path                   
       FROM AdDocs AD inner join AdRequests AR1                  
       on AD.RequestID = AR1.ID                  
       where AD.RequestID = ADR.ID                  
      FOR XML PATH('')), 1, 1, '')  as AdDocPath     
       
   FROM AdRequests as ADR    
      
   where ADR.PageID in    
   (    
      select ID from PageRequests where ParentID = @ParentID    
   )    
   order by ADR.ID desc     
    
End 


GO

/* ============================================================
   Procedure: [dbo].[Usp_getAdDetails_ByID]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE dbo.Usp_getAdDetails_ByID --1    
(    
 @RequestID bigint    
)    
as    
Begin    
       
  SELECT    
     ADR.ID    
    ,ADR.PageID   
    ,(select top 1 isnull(PageName,'') from PageRequests where ID = ADR.PageID) as PageName  
      
   ,(    
   
     -- select isnull(URL,'') from DigitalMarketingEntities where TypeID in      
     --  (select top 1 TypeID from PageRequests where ID = ADR.PageID)    
   
    isnull((select top 1 isnull(URL,'') from DigitalMarketingEntities where PageRequestID = adr.PageID),'')
   
   ) as URL    
      ,ADR.AddName    
      ,ADR.RequestType    
      ,ADR.Content    
      ,ADR.Remarks    
      ,ADR.Amount    
      ,ADR.CreatedOn    
      ,ADR.CreatedBy   
     
  
   ,ISNULL(ARH.URL,'') as URL  
   ,isnull(ARH.AssignedTo,0) as AssignedTo  
   ,isnull(ARH.ScheduledDays,'') as ScheduledDays   
   ,StartDate  
   ,EndDate  
   ,ARH.Status  
  
      ,(Select user_login from User_Detail where User_ID = ADR.CreatedBy) as  CreatedByName    
   ,    
     STUFF((SELECT ';' + cast(AD.DocPath as nvarchar(max)) --Path                   
       FROM AdDocs AD inner join AdRequests AR1                  
       on AD.RequestID = AR1.ID                  
       where AD.RequestID = ADR.ID                  
      FOR XML PATH('')), 1, 1, '')  as AdDocPath     
       
   FROM AdRequests as ADR    
   join AdRequestHistory as ARH   
   on ADR.ID = ARH.RequestID  
   where ADR.ID = @RequestID   
   and  ARH.ID in ( select top 1 ID from AdRequestHistory where RequestID = @RequestID order by id desc )   
  
   --where ADR.PageID in    
   --(    
   --   select ID from PageRequests where ParentID = @ParentID    
   --)    
   -- order by ADR.ID desc     
    
End 


GO

