/* ============================================================
   Procedure: [dbo].[Usp_GetAdName]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE dbo.Usp_GetAdName
( 
   @TypeID bigint,
   @PageName nvarchar(500),
   @ParentID bigint
)
as
Begin
 	if(exists(select 1 from PageRequests where TypeID = @TypeID and PageName = @Pagename
	    and ParentID = @ParentID
	 ))
	  Begin
	   select * from AdRequests where PageID in
		 (
		   select isnull(ID,0) from PageRequests where TypeID = @TypeID and PageName = @Pagename
	        and ParentID = @ParentID
		 )
		    
	  End
	 else
	  Begin
	    select ''
	  End
	 

End


