CREATE   PROCEDURE [dbo].[usp_getagentforcalltransfer] --7428494948,31031--9811788044,39680          
(          
@mobile nvarchar(50),          
@parentid bigint          
)          
as          
begin          
declare @agent nvarchar(50),@agentmobile nvarchar(50)          
if exists (select top 1 cast(assignedto as nvarchar) as user_id from userleads(nolock) where parentid=@parentid and           
dbo.fn_trim0prefix(@mobile) in (isnull(mobileno,'0'),isnull(mobileno1,'0'),isnull(mobileno2,'0')) and assignedto<>0 order by id desc)          
begin      
select @agent=    (select top 1 cast(assignedto as nvarchar) as user_id from userleads(nolock) where parentid=@parentid and           
dbo.fn_trim0prefix(@mobile) in (isnull(mobileno,'0'),isnull(mobileno1,'0'),isnull(mobileno2,'0')) order by id desc)          
print 'Mobile in Lead, Assigned to userid '+cast(@agent as nvarchar)      
end      
else if exists (select top 1 cast(CreatedBy as nvarchar) as user_id from userenquiry(nolock) where parentid=@parentid and           
dbo.fn_trim0prefix(@mobile) in (isnull(mobileno,'0'),isnull(mobileno1,'0'),isnull(mobileno2,'0')) order by enquiryid desc)          
begin      
select @agent=      
(select top 1 cast(CreatedBy as nvarchar) as user_id from userenquiry(nolock) where parentid=@parentid and           
dbo.fn_trim0prefix(@mobile) in (isnull(mobileno,'0'),isnull(mobileno1,'0'),isnull(mobileno2,'0')) order by enquiryid desc)          
print 'Mobile in Enquiry, Created by userid '+cast(@agent as nvarchar)      
end      
else if exists(select top 1 cast(agentuserid as nvarchar) from calllog(nolock) where parentid=@parentid and agentuserid is not null        
and customernumber=dbo.fn_trim0prefix(@mobile) order by id desc)          
begin      
select @agent=(select top 1 cast(agentuserid as nvarchar) from calllog(nolock) where parentid=@parentid and agentuserid is not null        
and customernumber=dbo.fn_trim0prefix(@mobile) order by id desc)        
print 'Mobile in Call Log, Last userid '+cast(@agent as nvarchar)      
end      
--else      
--begin      
--select @agent=        
--(select top 1 case when agenttype='user' then agentnumber else           
--cast((select user_id from user_detail(nolock) where str(mobile)=dbo.fn_trim0prefix(d.agentnumber)) as nvarchar) end          
--from kit19callsdialled(nolock) d join kit19calls(nolock) k on d.puniqueid=k.uniqueid          
--where k.context='inbound' and dbo.fn_trim0prefix(k.callerid)=dbo.fn_trim0prefix(@mobile) and clientid=@parentid          
--and d.dialstatus='ANSWER'          
--order by d.id desc)      
--print 'Mobile in Dialled call, Last userid '+cast(@agent as nvarchar)      
      
--end      
select @agentmobile=str(mobile) from user_detail(nolock) where user_id=@agent and onduty=1 and       
--isnull(cloudrole,0)<>0 and   
status=1        
if isnull(@agent,'0') >'0' and @agentmobile is null      
print 'Last user either not active or not on duty'      
         
select isnull(@agentmobile,'No') as Agent          
end          
        
        
----select top 10 * from calllog(nolock) where customernumber='9315028189' and parentid=31031 order by id desc        
        
--select top 1 cast(agentuserid as nvarchar) from calllog(nolock) where parentid=31031 and agentuserid is not null        
--and customernumber=dbo.fn_trim0prefix('9315028189') order by id desc        
        
--select str(mobile) from user_detail(nolock) where user_id=42578 --and onduty=1 --and isnull(cloudrole,0)<>0         
