/* ============================================================
   Procedure: [dbo].[USP_GetAirtelMsgCount]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
/****************************************************************************  
SP_Name        : [USP_GetAirtelMsgCount]                     
Author         : vinay  
Created ON     : 24/12/2009 04:30 PM        
Version        : 1  
Alter BY       :          
Alter Date    :   
Location       : PELSOFT  
SP Description : This SP is Used to Get CreditCount and also selecting records from AirTelSeries
         
****************************************************************************/  
  
CREATE   PROCEDURE [dbo].[USP_GetAirtelMsgCount]  
@BatchID bigint=null,  
@Flag char(3),  
@MobSubSet varchar(5)=null  
as  
Begin  
Set NOCount On  
/*  
ALTER by:- varun Dated :- 21 Nov 2009  
Location :- CSVImport  
Proc is used for message count of Airtel numbers in a batch    
*/  
Declare @CreditCount bigint  
if @Flag='CSV'  
 BEGIN  
   SELECT @CreditCount=sum((len(Messages)-1)/160+1) FROM MessageStorageTemp tmp inner join AirTelSeries Air on tmp.MobileSubSet=Air.MobileSubSet where tmp.MessageBatchID=@BatchID            
   select  @CreditCount  
 END  
ELSE IF @Flag='COM'  
 BEGIN  
   SELECT @CreditCount=count(MobileNOS) FROM MessageStorageTemp tmp inner join AirTelSeries Air on tmp.MobileSubSet=Air.MobileSubSet where tmp.MessageBatchID=@BatchID            
   select  @CreditCount   
END   
ELSE IF @Flag='API'  
 BEGIN  
   SELECT * FROM AirTelSeries Air where Air.MobileSubSet= @MobSubSet            
 -- select  @CreditCount   
END   
End  
  




GO

/* ============================================================
   Procedure: [dbo].[USP_GetAllActiveUsers]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

/*
Live tracking

USP_GetAllActiveUsers  335 , 1,10

select top 10 * from tbl_user_engagement_track_details order by 1 desc

*/  

CREATE   PROCEDURE [dbo].[USP_GetAllActiveUsers]
@UserID NVARCHAR(50),  
@PageNumber INT,       @PageSize INT   
AS  
BEGIN      
   WITH LatestUserEntries AS (  
  SELECT   
   CONCAT(ud.User_ID, ' (', User_Login, ')') AS [User Login],  
   ted.Mode AS Mode,  
   tem.PageURL AS [Page url],  
  
   -- Calculate Total Active Time in hours, m inutes, and seconds  
   CONCAT(  
    FLOOR(SUM(ted.SpendTime) / 3600), ' h ',  
    FLOOR(CAST(SUM(ted.SpendTime) AS INT) % 3600 / 60), ' m ',  
    CAST(SUM(ted.SpendTime) AS INT) % 60, ' s'  
   ) AS [Duration],  
  
   ROW_NUMBER() OVER (PARTITION BY tem.UserID ORDER BY ted.CreatedDate DESC) AS RowNum  
      
  FROM tbl_user_engagement_track_master tem (NOLOCK)  
  LEFT JOIN User_Detail ud ON tem.UserID = ud.User_ID  
  INNER JOIN tbl_user_engagement_track_details ted ON ted.UserEngMasterId = tem.EngagementID  
  WHERE   
   ted.ModifiedDate >= DATEADD(MINUTE, -5, GETDATE())
    AND ud.M_ID  = (select rd.Reseller_ID from User_Detail ud join reseller_detail rd ON rd.User_ID = ud.User_ID where  ud.User_ID = @UserID)  
  GROUP BY   
   tem.UserID,  
   CONCAT(ud.User_ID, ' (', User_Login, ')'),  
   tem.PageURL,  
   ted.Mode,  
   ted.CreatedDate  
  HAVING       SUM(ted.SpendTime) > 0  
 )   
 SELECT   
  COUNT(*) OVER () AS TotalRecords,  
  [User Login],  
  Mode,  
  [Page url],  
  [Duration]  
 FROM LatestUserEntries  
 WHERE RowNum = 1  -- Only get the latest entry for each user  
 ORDER BY [Duration] DESC  
 OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY; END  





GO

/* ============================================================
   Procedure: [dbo].[USP_GetAllBatchInfoByUserID]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON


CREATE   PROCEDURE [dbo].[USP_GetAllBatchInfoByUserID] --'21483','BHOMKA','7586945' 
@UserID int,-- from Varchar(20), 
@SenderID Varchar(20), 
@BatchID bigint -- from Varchar(20) 
AS 
BEGIN 
 
 Declare @Time Varchar(10) 
 Declare @Pushed Varchar(10) 
 Declare @DNDBlack Varchar(10) 
 Declare @BlackList Varchar(10) 
 Declare @TotalSent Varchar(10) 
 Declare @DelUnDeliver Varchar(10) 
 Declare @SpamMsg Varchar(10) 
 Declare @Invalid Varchar(10) 
 
 Select @Time = Convert(varchar(8),MessageInsertDate,108) From MessageDeliveryStatus with (nolock) 
 where U_ID = @UserID AND SenderID = @SenderID AND BatchID = @BatchID 
 
 Select @Pushed = count(*) from MessageDeliveryStatus with (nolock) where U_ID = @UserID AND SenderID = @SenderID AND BatchID = @BatchID 
 
 Select @BlackList = count(*) from MessageDeliveryStatus with (nolock) Where IsNull(MessageStatus,0) in ('5','6') 
 AND U_ID = @UserID AND SenderID = @SenderID AND BatchID = @BatchID 
 
 Select @Invalid = count(*) from MessageDeliveryStatus with (nolock) Where IsNull(MessageStatus,0) ='9' 
 AND U_ID = @UserID AND SenderID = @SenderID AND BatchID = @BatchID 
 
 Select @DNDBlack = count(*) from MessageDND with (nolock) Where U_ID = @UserID AND SenderID = @SenderID AND BatchID = @BatchID 
 
 SET @DNDBlack = Cast(IsNull(@DNDBlack,0) as Int) + cast(IsNull(@BlackList,0) As Int) 
 
 --Select @TotalSent = count(*) from mysmstrans.dbo.MessageDeliveryStatusTemp with (nolock) WHERE U_ID = @UserID AND SenderID = @SenderID AND BatchID = @BatchID 
 Select @TotalSent = count(*) from mysms.dbo.MessageDeliveryStatusTemp with (nolock) WHERE U_ID = @UserID AND SenderID = @SenderID AND BatchID = @BatchID 

 SELECT @SpamMsg = count(*) FROM MessageSpam with (nolock) WHERE U_ID = @UserID AND SenderID = @SenderID AND BatchID = @BatchID 
 
 Select IsNull(@Time,'') As [Time], IsNull(@Pushed,0) As Pushed, IsNull(@DNDBlack,0) As DNDBlack, 
 IsNull(@TotalSent,0) As TotalSent , IsNull(@SpamMsg,0) As Spam , IsNull(@Invalid,0) As Invalid 
END 




GO

