/* ============================================================
   Procedure: [dbo].[USP_GetAllBatchInfoByUserIDOnDays1]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC [dbo].[USP_GetAllBatchInfoByUserIDOnDays1]   --  '8145','cititest','4305945'                  
@UserID int,-- from Varchar(20),                      
@SenderID Varchar(20),                      
@BatchID bigint -- from Varchar(20)                    
AS                      
BEGIN                      
                       
 Declare @Time Varchar(10)                      
 Declare @Pushed Varchar(10)           
 Declare @BlackList  Varchar(10)                  
 Declare @DNDBlack Varchar(10)                      
 Declare @TotalSent Varchar(10)                      
 Declare @DelUnDeliver Varchar(10)                     
 Declare @SpamMsg Varchar(10)         
 Declare @Invalid Varchar(10)            
                 
                    
 Select @Time = Convert(varchar(8),MessageInsertDate,108) From SixDaysHistory1                      
    where U_ID = @UserID AND SenderID = @SenderID AND BatchID = @BatchID                      
                      
 Select @Pushed = count(*) from SixDaysHistory1 where   U_ID = @UserID AND SenderID = @SenderID AND BatchID = @BatchID                      
       
 Select  @BlackList = count(*) from SixDaysHistory1 Where  IsNull(MessageStatus,'0') in ('5','6')       
 AND U_ID = @UserID AND SenderID = @SenderID AND BatchID = @BatchID         
      
 Select  @Invalid = count(*) from SixDaysHistory1 Where  IsNull(MessageStatus,'0') = '9'       
 AND U_ID = @UserID AND SenderID = @SenderID AND BatchID = @BatchID       
  
 Select  @DNDBlack = count(*) from MessageDND1 Where  datediff(d,messageinsertDate,getdate())=1 and        
 U_ID = @UserID AND SenderID = @SenderID AND BatchID = @BatchID            
            
 SET @DNDBlack = Cast(IsNull(@DNDBlack,0) as Int) + cast(IsNull(@BlackList,0) As Int)                    
               
                      
 Select @TotalSent = count(*) from MsgTempHistory1 WHERE U_ID = @UserID AND SenderID = @SenderID AND BatchID = @BatchID                      
                       
 SELECT @SpamMsg = count(*) FROM  MessageSpam WHERE  U_ID = @UserID AND SenderID = @SenderID AND BatchID = @BatchID                  
                     
 Select IsNull(@Time,'') As  [Time], IsNull(@Pushed,0) As Pushed, IsNull(@DNDBlack,0) As DNDBlack,                       
     IsNull(@TotalSent,0) As TotalSent  , IsNull(@SpamMsg,0) As Spam ,@Invalid As Invalid                 
END   


GO

