 U_ID = @UserID AND SenderID = @SenderID AND BatchID = @BatchID          
          
 SET @DNDBlack = Cast(IsNull(@DNDBlack,0) as Int) + cast(IsNull(@BlackList,0) As Int)                   
                    
 Select @TotalSent = count(*) from MsgTempHistory3 WHERE U_ID = @UserID AND SenderID = @SenderID AND BatchID = @BatchID                    
                     
 SELECT @SpamMsg = count(*) FROM  MessageSpam WHERE  U_ID = @UserID AND SenderID = @SenderID AND BatchID = @BatchID                
                   
 Select IsNull(@Time,'') As  [Time], IsNull(@Pushed,0) As Pushed, IsNull(@DNDBlack,0) As DNDBlack,                     
     IsNull(@TotalSent,0) As TotalSent  , IsNull(@SpamMsg,0) As Spam   ,@Invalid As Invalid             
END 


