   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC usp_GetAllEnquiryLeadFields  
(  
 @ParentId bigint  
)  
As  
Begin  
  
Select '#' + COLUMN_NAME + '#' as COLUMN_NAME  
From  
(  
 select 1 as A,COLUMN_NAME from INFORMATION_SCHEMA.COLUMNS where TABLE_NAME='UserEnquiry' and TABLE_CATALOG='MYSMS' and COLUMN_NAME not in ('EnquiryID','ParentID','CreatedDate','CreatedBy','IsOpen','LeadNo','img_ext','ProfileImgFileName','enquirysource','
CountryCode','CountryCode1','CountryCode2', 'WhatsAppNoColName')      
 union       
 select 1 as A,COLUMN_NAME from INFORMATION_SCHEMA.COLUMNS where TABLE_NAME='UserLeads' and TABLE_CATALOG='MYSMS' and COLUMN_NAME not in ('ID', 'LeadNo','ParentID','CreatedOn','CreatedBy','ModifiedOn','ModifiedBy','LeadImage','img_ext','temp_id','ProfileImgFileName','enquirysource','CountryCode','CountryCode1','CountryCode2','AssignedTo','FollowUpStatus','NextStatusDate','Remarks','Products','AmountPaid','FollowupDate','WhatsAppNoColName','LastFollowupCreatedOn')      
 --union       
 --select 2 as B,fieldname  
 --from customfields(nolock) where parentId=@ParentId and isActive=1      
) A  
  
End  



