/* ============================================================
   Procedure: [dbo].[USP_GetAllRecievedInfoByUserID]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
 
 
 
CREATE   PROCEDURE [dbo].[USP_GetAllRecievedInfoByUserID] --6673,'MADHYAM','4602370' 
@UserID int, 
@SenderID nvarchar(50), 
@BatchID bigint 
AS 
BEGIN 
 WITH CTE AS( 
 SELECT Count(*) As RecievedMobile 
 FROM mysmstrans.dbo.messagedeliverystatustemp md with (nolock) 
 left join mysmstrans.dbo.ReceiveDeliveryData rd with (nolock) 
 on md.mobile=rd.mobile and replace(md.senderid,'.',' ') =replace(rd.senderid,'AM-','') 
 WHERE md.senderid=@SenderID AND U_ID = @UserID AND BatchID = @BatchID 
 AND (rd.StatusWithErr like '%DELIVRD%' or rd.StatusWithErr like '%EXPIRED%' or rd.StatusWithErr like '%UNDELIV%') group by md.messageid 
 
 ) 
 SELECT count(RecievedMobile) FROM CTE 
END 



GO

