CREATE   PROC [dbo].[USP_GetAllRecievedInfoByUserIDOnDay]  --8316,'Property','4444583' ,6       
@UserID int,            
@SenderID nvarchar(50),        
@BatchID Varchar(20),    
@Day int              
AS        
BEGIN       
 IF (IsNull(@Day,0) = 1)    
 BEGIN    
    WITH CTE AS(             
    SELECT Count(*) As RecievedMobile        
    FROM SixDaysHistory1 md(nolock)         
    WHERE md.SenderID =@SenderID AND md.U_ID = @UserID AND md.BatchID = @BatchID        
 AND (md.MessageStatus ='DELIVRD' or md.MessageStatus = 'EXPIRED' or md.MessageStatus = 'UNDELIV')            
            
    )        
 SELECT RecievedMobile FROM CTE          
  END    
  ELSE IF (IsNull(@Day,0) = 2)    
  BEGIN    
 WITH CTE AS(             
    SELECT Count(*) As RecievedMobile        
    FROM SixDaysHistory2 md(nolock)         
    WHERE md.SenderID =@SenderID AND md.U_ID = @UserID AND md.BatchID = @BatchID        
 AND (md.MessageStatus ='DELIVRD' or md.MessageStatus = 'EXPIRED' or md.MessageStatus = 'UNDELIV')            
           
    )        
 SELECT RecievedMobile FROM CTE          
  END    
  ELSE IF (IsNull(@Day,0) = 3)    
  BEGIN    
 WITH CTE AS(             
    SELECT Count(*) As RecievedMobile        
    FROM SixDaysHistory3 md(nolock)         
    WHERE md.SenderID =@SenderID AND md.U_ID = @UserID AND md.BatchID = @BatchID        
 AND (md.MessageStatus ='DELIVRD' or md.MessageStatus = 'EXPIRED' or md.MessageStatus = 'UNDELIV')           
           
    )        
 SELECT RecievedMobile FROM CTE         
  END    
  ELSE IF (IsNull(@Day,0) = 4)    
  BEGIN    
 WITH CTE AS(             
    SELECT Count(*) As RecievedMobile        
    FROM SixDaysHistory4 md(nolock)         
    WHERE md.SenderID =@SenderID AND md.U_ID = @UserID AND md.BatchID = @BatchID        
 AND (md.MessageStatus ='DELIVRD' or md.MessageStatus = 'EXPIRED' or md.MessageStatus = 'UNDELIV')            
           
    )        
 SELECT RecievedMobile FROM CTE         
  END    
  ELSE IF (IsNull(@Day,0) = 5)    
  BEGIN    
 WITH CTE AS(             
    SELECT Count(*) As RecievedMobile        
    FROM SixDaysHistory5 md(nolock)         
    WHERE md.SenderID =@SenderID AND md.U_ID = @UserID AND md.BatchID = @BatchID        
 AND (md.MessageStatus ='DELIVRD' or md.MessageStatus = 'EXPIRED' or md.MessageStatus = 'UNDELIV')         
           
    )        
 SELECT RecievedMobile FROM CTE        
  END    
  ELSE IF (IsNull(@Day,0) = 6)    
  BEGIN    
 WITH CTE AS(             
    SELECT Count(*) As RecievedMobile        
    FROM SixDaysHistory6 md(nolock)         
    WHERE md.SenderID =@SenderID AND md.U_ID = @UserID AND md.BatchID = @BatchID        
 AND (md.MessageStatus ='DELIVRD' or md.MessageStatus = 'EXPIRED' or md.MessageStatus = 'UNDELIV')          
        
    )        
 SELECT RecievedMobile FROM CTE        
  END    
END        
  




GO

