CREATE   PROC [dbo].[usp_getAllUserList] --'Select','','Select'        
@type nvarchar(50),                                        
@name nvarchar(50),         
@provider nvarchar(50)            
As            
Declare @ErrNo Int,@Query varchar(2000),@whereClause varchar(500),@operator varchar(10)                                                                                                  
Set Nocount off                                                                                                  
                                                                                               
set @whereClause=''                                 
declare @cnt int                             
If @type = 'Select'                                                                                                  
 Begin                                                                                                  
  Set @whereClause = @whereClause+' 1=1 and '                                                                                                  
 End                                                                                                  
Else                                                                                                  
 Begin                                              
  Set @whereClause = @whereClause+ 'type ='''+@type+''' and '                                                                                           
 End           
        
If @name = ''                                                                                                  
 Begin                                                                                                  
  Set @whereClause = @whereClause+' 1=1 and '                                                                                                  
 End                                                                                                  
Else                                                                                                  
 Begin                                                                                                  
  Set @whereClause =@whereClause+'user_login Like ''%'+@name+'%'' and '                                                            
 End             
        
If @provider = 'Select'                                                                                                  
 Begin                                                                                                  
  Set @whereClause = @whereClause+' 1=1 '                                                                                                  
 End                                                                                                  
Else                                                                                                  
 Begin                                                                                                  
  Set @whereClause =@whereClause+'SMPPID='''+@provider+''''                                                           
 End                      
set @Query='Select  [USER_ID],[USER_Login],smppname=(select SmppName from SmppserverDetails where SMPPID=User_Detail.SmppID),case [type] when 1 then ''Reseller'' when 0 then ''user'' else ''SubReseller'' end  [userType]  from User_Detail where  '+@whereClause+''        
exec(@Query)




