/* ============================================================
   Procedure: [dbo].[usp_getApicustomfielderrorlog]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE dbo.usp_getApicustomfielderrorlog @userid BIGINT
	,@mode VARCHAR(10)
	,@fromdt DATETIME = NULL
	,@todate DATETIME = NULL
	,@apikey NVARCHAR(max) = NULL
	,@apiname NVARCHAR(max) = NULL
	,@errormsg NVARCHAR(max) = NULL
AS
BEGIN
	DECLARE @parentid BIGINT

	SELECT @parentid = parentid
	FROM User_Detail
	WHERE User_ID = @userid

	IF @mode = 'Data'
	BEGIN
		--  declare @parentid bigint =34594              
		SELECT err.ApiName
			,err.ApiKey
			,String_agg(cf.fieldname, ',') AS FieldName
			,String_agg(err.fieldid, ',') AS FieldId
			,String_agg(acm.ApileadField, ',') AS ApiField
			,String_agg(err.ErrorMsg, ',') AS ErrorMessage
			,err.EntryDate
			,STRING_AGG(err.fieldvalue, ',') AS FieldValue
			,err.ApiDataId
			,err.Active
		FROM ErrorLogApiCustomField err
		JOIN customfields cf ON err.fieldid = cf.Field_Id
		JOIN tbl_ApiCustomFieldMapping acm ON cast(acm.Field_id AS VARCHAR) = cast(err.Fieldid AS VARCHAR)
		WHERE err.UserId = @parentid
			AND err.ApiKey = acm.ApiKey
			AND err.ApiName = acm.ApiName
		GROUP BY err.apiname
			,err.ApiKey
			,err.EntryDate
			,err.ApiDataId
			,err.Active
		ORDER BY EntryDate DESC
	END
	ELSE IF @mode = 'Filter'
	BEGIN
		SELECT err.apiname
			,err.ApiKey
			,String_agg(cf.fieldname, ',') AS fieldname
			,String_agg(err.fieldid, ',') AS FieldId
			,String_agg(acm.ApileadField, ',') AS ApiField
			,String_agg(err.ErrorMsg, ',') AS ErrorMessage
			,err.EntryDate
			,STRING_AGG(err.fieldvalue, ',') AS FieldValue
			,err.ApiDataId
			,err.Active
		FROM ErrorLogApiCustomField err
		JOIN customfields cf ON err.fieldid = cf.Field_Id
		JOIN tbl_ApiCustomFieldMapping acm ON cast(acm.Field_id AS VARCHAR) = cast(err.Fieldid AS VARCHAR)
		WHERE err.UserId = @parentid
			AND err.ApiKey = acm.ApiKey
			AND err.ApiName = acm.ApiName
			AND (
				@apikey IS NULL
				OR err.ApiKey LIKE '%' + @apikey + '%'
				)
			AND (
				@apiname IS NULL
				OR err.ApiNAme LIKE '%' + @apiname + '%'
				)
			AND (
				@fromdt IS NULL
				OR err.EntryDate > @fromdt
				)
			AND (
				@todate IS NULL
				OR err.EntryDate < @todate
				)
			AND (
				@errormsg IS NULL
				OR err.Errormsg LIKE '%' + @errormsg + '%'
				)
			AND err.fieldvalue IS NOT NULL
		GROUP BY err.apiname
			,err.ApiKey
			,err.EntryDate
			,err.ApiDataId
			,err.Active
		ORDER BY err.EntryDate DESC
	END

	EXEC MySmsAudit.dbo.Usp_AuditTableDataByParentId @User_id = @userid
		,@Activity_type = 'View_errRpt_Api'
		,@ActionType = 'S'
		,@RowJson = ''
		,@Table_name = 'ErrorLogApiCustomField'
END
	--exec usp_getApicustomfielderrorlog 34594,'Filter'



GO

