   Procedure: [dbo].[Usp_getApiDataAsJson]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

   
  
CREATE   PROCEDURE Usp_getApiDataAsJson       
@apiname varchar(20) ,      
@apiid bigint      
      
AS       
BEGIN      
 IF @apiname='JustDial'      
 BEGIN      
  SELECT [Name],[mobile],[phone],[email],[category],[city],[Area],[brancharea],cast([dncmobile] as varchar) as dncmobile ,cast([dncphone] as varchar) as dncphone,[company],[pincode],      
    [time],[branchpin]  
  FROM justdialleads   
  WHERE id = @apiid FOR JSON PATH      
 END      
      
 IF @apiname='IndiaMart'      
 BEGIN      
  SELECT [SENDERNAME],[SENDEREMAIL],[MOB],[GLUSR_USR_COMPANYNAME],[ENQ_ADDRESS],[ENQ_CITY],[ENQ_STATE],[COUNTRY_ISO],[PRODUCT_NAME],      
    [ENQ_MESSAGE],[DATE_R],[DATE_TIME_RE],[LOG_TIME],[ENQ_CALL_DURATION],[ENQ_RECEIVER_MOB],[EMAIL_ALT],[MOBILE_ALT],[PHONE],[PHONE_ALT],      
    [SUBJECT]       
  FROM IndiamartLeads       
  WHERE id = @apiid FOR JSON PATH      
 END      
      
 IF @apiname='TradeIndia'      
 BEGIN      
  SELECT [sender_name],[sender_mobile],[sender_email],[sender_other_mobiles],[sender_other_emails],[sender_co],[address],[sender_city],[sender_state],[sender_country],    
  [ago_time],[att_data],[attachment_cnt],[fax_number],[generated],[generated_date],[generated_time],[inquiry_type],      
    [landline_number],[member_since],[message],[month_slot],[order_value_min],[pref_supp_location],[product_id],[product_name],[product_source]      
    ,[quantity],[receiver_co],[receiver_mobile],[receiver_name],[receiver_uid],[responded],[rfi_id],[sender],      
    [sender_uid],      
    [source],[subject],[unread_res_cnt],[view_status],[website]       
  FROM TradeIndiaData       
  WHERE id = @apiid FOR JSON PATH      
 END      
      
 IF @apiname='Sulekha'      
 BEGIN      
  SELECT [UserName],[Usermobile],[Useremail],[Usercity],[UserLocalities],[UserComments],[Keywords],[Sul_Lead],[Sul_Biz],[Sul_Customer]       
  FROM SulekhaLeads       
  WHERE id = @apiid FOR JSON PATH      
 END      
      
 IF @apiname='MagickBricks'      
 BEGIN      
  SELECT [Name],[RefID],[ISD],[Mobile],[EmailID],[MSG],[Locality],[City],[Loginid],[ph],[pid],[Project],[Subject]       
  FROM MagicBrickLeads       
  WHERE id = @apiid FOR JSON PATH      
 END      
      
 IF @apiname='99Acres'      
 BEGIN      
  SELECT [Name],[Email],[Phone] ,[ProjName],[ResType],[QueryID],[Address],[QryInfo],[SubUserName]      
    [PROPERTY_CODE],[ProductStatus],[ProductType]      
  FROM Acres99_Leads       
  WHERE id = @apiid FOR JSON PATH      
 END      
END 


