CREATE   PROCEDURE dbo.Usp_GetAPIKeyAndParentID  --'SIS946309'  
(  
  @Userlogin nvarchar(200)  
)  
as  
Begin  
     
    Declare  @ParentID bigint = isnull(( select top 1 isnull(ParentID,0) from user_detail with(nolock) where User_Login = @Userlogin),0) 
	Declare @APIKey nvarchar(500) = ''
	  
    select top 1 @APIKey = ApiKey  from tbl_ims_OnBoardRequest(nolock) where parentId = @ParentID  

