/* ============================================================
   Procedure: [dbo].[Usp_GetApiMappingKey]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

  
CREATE   PROCEDURE [dbo].[Usp_GetApiMappingKey]    
    
@apiname nvarchar(max) ,    
@parentId Bigint     
    
As    
Begin    
 if @apiname='IndiaMart'    
 begin    
  Select IndiamartId as Apikey from Indiamartmapping where Kit19ParentId=@parentId order by createdon desc    
 end    
    
 if @apiname='JustDial'    
 begin    
  Select JDParentId as Apikey from JDMapping where Kit19ParentId=@parentId and status=1 order by createdon desc    
 end    
    
 if @apiname='TradeIndia'    
 begin    
  Select TradeIndia_Key as Apikey from TradeIndia_Mapping where Kit19ParentId=@parentId and Status=1 order by CreatedOn desc    
 end    
 if @apiname='Sulekha'    
 begin    
  Select SulekhaId as Apikey from SulekhaMapping where Kit19ParentId=@parentId and status=1 order by createdon desc    
 end    
 if @apiname='MagicBricks'    
 begin    
  Select MagicBrickKey as Apikey from MagicBricks where Kit19ParentId=@parentId and status=1 order by createdon desc    
 end    
     
 if @apiname='99Acres'    
 begin    
  Select Acres_UserName as Apikey from Acres99_Mapping where Kit19ParentId=@parentId and status=1  order by createdon desc     
 end   
 
  if @apiname='Exporter'    
 begin    
  Select ExporterKey as Apikey from tbl_exporterMapping where ParentId=@parentId and status=1  order by createdon desc     
 end  
End    


GO

