/* ============================================================
   Procedure: [dbo].[Usp_getAppointmentLatLong]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

-- Usp_getEntityLatLong 'lead', 2725397, 28.594022, 77.30742, 6, 40584
CREATE   PROCEDURE [dbo].[Usp_getAppointmentLatLong]    
(    
@AppointmentId bigint,
@CurrentLatitude float,
@CurrentLongitude float,
@RadiusDistance bigint = 1000,
@TypeDistance varchar(10) = 'KM',
@UserId bigint    
)
as
Begin
Declare @ParentId bigint
select @ParentId = ParentID from User_detail (nolock) ud where ud.User_ID = @UserId
declare @newMeter float = ((@RadiusDistance * 1000) * 0.1 / 10000);
if(@TypeDistance = 'KM')
Begin
set @newMeter = ((@RadiusDistance * 1000) * 0.1 / 10000);
End
else if(@TypeDistance = 'MI')
Begin
set @newMeter = ((@RadiusDistance * 1.60934 * 1000) * 0.1 / 10000);
End
else
Begin
set @newMeter = ((@RadiusDistance * 1000) * 0.1 / 10000);
End
declare @lat1 float = @CurrentLatitude - @newMeter;
declare @lat2 float = @CurrentLatitude + @newMeter;
declare @lon1 float = @CurrentLongitude - @newMeter;
declare @lon2 float = @CurrentLongitude + @newMeter;

--select @lat1 lat1, @lon1 lon1, @lat2 lat2, @lon2 lon2

--select Id, LeadNo, PersonName, '' PersonImage, CompanyName, MobileNo, MobileNo1, MobileNo2, 
--CountryCode, CountryCode1, CountryCode2, EmailID, EmailID1, EmailID2, City, State, Country, 
--SourceName, MediumName, CampaignName, '' Source, '' Medium, '' Campaign, PinCode, InitialRemarks, 
--ResidentialAddress, OfficeAddress, latitude, longitude, isnull(LeadImage, '') LeadImage, isnull(img_ext, '') img_ext, isnull(ProfileImgFileName, '') ProfileImgFileName, ParentId, AssignedTo 
--from Userleads ul(nolock) 
--where ul.ParentID = @ParentId and (ul.latitude between @lat1 and @lat2 or ul.longitude between @lon1 and @lon2)


Select * from(
 select * from (
	Select Distinct papt.PhysicalAppointmentId Id, 'PhysicalApt' RecordType, papt.ParentId, papt.Title, papt.Description, papt.StartDate, papt.EndDate, papt.Address, papt.Status, --gecu.CheckIn, gecu.CheckOut, gecu.LatitudeIn, gecu.LongitudeIn,  gecu.LatitudeOut, gecu.LongitudeOut,
	gesm.Latitude, gesm.Longitude,
	(Case
       When gemr.GeoEntityType ='lead' Then (Select ud.PersonName from userLeads ud
       where ud.Id= gemr.EntityId)
       When gemr.GeoEntityType ='enquiry' Then (Select ue.PersonName from UserEnquiry ue
     where ue.EnquiryId= gemr.EntityId)
     End) PersonName, 
	 gemr.Mobile CsvMobileNo, gemr.EmailId CsvEmailId, '' LeadImage, '' img_ext, '' ProfileImgFileName, '' CompanyName, '' City, '' State, '' Country,
	 gemr.EntityId, gemr.GeoEntityType,
	--Concat(ud.FName, ' ', isnull(ud.LName, '')) OwnerName, 
	'' PersonImage,
	isnull(oc.OutcomeName, '') Outcome, '' Intent,
	(Case
       When gemr.GeoEntityType ='lead' Then (Select ud.LeadNo from userLeads ud
       where ud.Id= gemr.EntityId)
       When gemr.GeoEntityType ='enquiry' Then (Select ue.LeadNo from UserEnquiry ue
       where ue.EnquiryId= gemr.EntityId)
	   else
	   0
     End) LeadNo, '' AgentImage, '' AgentName
	 --,gesm.GeoEntitySiteId, gesm.GeoEntitySiteName SiteName, isnull(papt.OutcomesId, 0) OutcomesId
	 from TBL_ET_PhysicalAppointment(nolock) papt
	inner join TBL_ET_GeoEntitySiteMaster(nolock) gesm on papt.GeoEntitySiteId = gesm.GeoEntitySiteId
	inner join TBL_ET_GeoEntityMaster(nolock) gemr on gesm.GeoEntityId = gemr.GeoEntityId
	inner join TBL_ET_PhyAppointUserMapping(nolock) paum on papt.PhysicalAppointmentId = paum.PhysicalAppointmentId
	left join User_Detail(nolock) ud on papt.AssignedTo = ud.User_ID
	left join TBL_ET_GeoEntityCheckInOut (nolock) gecu on papt.PhysicalAppointmentId = gecu.PhysicalAppointmentId
	left join tbl_tsk_UserOutcomeMaster (nolock) oc on  papt.OutcomesId = oc.Id
	where papt.ParentId = @ParentId
	and (gesm.latitude between @lat1 and @lat2 or gesm.longitude between @lon1 and @lon2)
	)tt

Union

select * from (

select tsk.Id, 'VirtualApt' RecordType, ud.ParentID as ParentId, tsk.Title, tsk.Description, tsk.StartDate, tsk.EndDate, tsk.Address, tsk.Status,
 tsk.Latitude, tsk.Longitude,
ul.PersonName,
concat(ul.MobileNo, iif(ul.MobileNo1 <> '', concat('', '', ul.MobileNo1), ''''), iif(ul.MobileNo2 <> '''', concat('', '', ul.MobileNo2), '''')) as CsvMobileNo,concat(ul.EmailId, iif(ul.EmailId1 <> '''', concat('', '', ul.EmailId1), ''''), iif(ul.EmailId2 <> '''', concat('', '', ul.EmailId2), '')) as CsvEmailId, 
--ul.MobileNo, ul.MobileNo1, ul.MobileNo2, ul.CountryCode, ul.CountryCode1, ul.CountryCode2, ul.EmailID, ul.EmailID1, ul.EmailID2, 
isnull(LeadImage, '') LeadImage, isnull(img_ext, '') img_ext, isnull(ProfileImgFileName, '') ProfileImgFileName, ul.CompanyName,
 ul.City, ul.State, ul.Country, 
   tsk.LeadId EntityId, 'lead' GeoEntityType, ul.ProfileImgFileName as PersonImage, 
  o.OutcomeName as Outcome, o.Indent as Intent, 
  ul.LeadNo, ud.Image as AgentImage, concat(ud.FName, ' ', isnull(ud.LName, '')) AgentName
from tbl_tsk_TaskHistory(nolock) tsk 
inner join UserLeads(nolock) ul on tsk.LeadId = ul.ID 
 inner join User_Detail(nolock) ud on tsk.CreatedBy = ud.User_ID
	left join tbl_tsk_UserOutcomeMaster(nolock) o on tsk.OutcomesId = o.Id
where tsk.IsActive = 1 and --tsk.Id = @ID
ul.ParentID = @ParentId and (tsk.latitude between @lat1 and @lat2 or tsk.longitude between @lon1 and @lon2)
) ttt
)tttt
order by StartDate Asc

--select * from (

--select 'VirtualApt' RecordType, ud.ParentID as ParentId, ul.PersonName, isnull(LeadImage, '') LeadImage, isnull(img_ext, '') img_ext, isnull(ProfileImgFileName, '') ProfileImgFileName, ul.CompanyName, ul.MobileNo, ul.MobileNo1, ul.MobileNo2, ul.CountryCode, ul.CountryCode1, ul.CountryCode2, ul.EmailID, ul.EmailID1, ul.EmailID2, ul.City, ul.State, ul.Country, 
--  tsk.id, tsk.Title, tsk.StartDate, tsk.EndDate, tsk.LeadId, ul.ProfileImgFileName as PersonImage, 
--  o.OutcomeName as Outcome, o.Indent as Intent, 
--  ul.LeadNo, ud.Image as AgentImage, concat(ud.FName, ' ', isnull(ud.LName, '')) AgentName,
--concat(ul.MobileNo, iif(ul.MobileNo1 <> '', concat('', '', ul.MobileNo1), ''''), iif(ul.MobileNo2 <> '''', concat('', '', ul.MobileNo2), '''')) as CsvMobileNo,concat(ul.EmailId, iif(ul.EmailId1 <> '''', concat('', '', ul.EmailId1), ''''), iif(ul.EmailId2 <> '''', concat('', '', ul.EmailId2), '')) as CsvEmailId, tsk.Latitude, tsk.Longitude
--from tbl_tsk_TaskHistory(nolock) tsk 
--inner join UserLeads(nolock) ul on tsk.LeadId = ul.ID 
-- inner join User_Detail(nolock) ud on tsk.CreatedBy = ud.User_ID
--	left join tbl_tsk_UserOutcomeMaster(nolock) o on tsk.OutcomesId = o.Id
--where tsk.IsActive = 1 and --tsk.Id = @ID
--ul.ParentID = @ParentId and (tsk.latitude between @lat1 and @lat2 or tsk.longitude between @lon1 and @lon2)
--) tt

--exec usp_tbl_UA_PageFieldsList_UserId_PageCode 'S', @ParentId, @UserId, 'PAG10031'

end



