/* ============================================================
   Procedure: [dbo].[usp_GetAppointmentVisitSummary_ByDate]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_GetAppointmentVisitSummary_ByDate]
    @FromDate DATE = NULL,
    @ToDate   DATE = NULL,
	@UserId   BIGINT = NULL
AS
BEGIN
    SET NOCOUNT ON;

	--declare
	--@FromDate DATE = '04-Apr-2026',
 --   @ToDate   DATE = '04-Apr-2026',
	--@UserId   BIGINT = 32222

    IF @FromDate IS NULL
        SET @FromDate = CAST(GETDATE() AS DATE);
    IF @ToDate IS NULL
        SET @ToDate = CAST(GETDATE() AS DATE);

    DECLARE @StartOfRange DATETIME = @FromDate;
    DECLARE @EndOfRange DATETIME = DATEADD(DAY, 1, @ToDate);

	print concat('@StartOfRange >',@StartOfRange)
	print concat('@EndOfRange >',@EndOfRange)

    -- Calculate visit flags per appointment for the given date
    ;WITH AppointmentsInRange AS (
        SELECT
            p.PhysicalAppointmentId,
            p.Title,
            p.StartDate,
        --    p.EndDate
        --FROM dbo.TBL_ET_PhysicalAppointment p WITH (NOLOCK)
        --WHERE ISNULL(p.IsActive, 1) = 1
        --  AND p.StartDate < @EndOfRange
        --  AND p.EndDate >= @StartOfRange
		 p.EndDate
                FROM dbo.TBL_ET_PhysicalAppointment p WITH (NOLOCK)
                WHERE ISNULL(p.IsActive, 1) = 1
                    -- count appointments whose StartDate falls inside the requested date range
                    AND p.StartDate >= @StartOfRange
                    AND p.StartDate < @EndOfRange
					 AND (@UserId IS NULL OR p.AssignedTo = @UserId)
    ), VisitFlags AS (
        SELECT
            a.PhysicalAppointmentId,
            MAX(CASE WHEN g.CheckIn >= @StartOfRange AND g.CheckIn < @EndOfRange THEN 1 ELSE 0 END) AS HasCheckInInRange,
            MAX(CASE WHEN g.CheckOut >= @StartOfRange AND g.CheckOut < @EndOfRange THEN 1 ELSE 0 END) AS HasCheckOutInRange
        FROM AppointmentsInRange a
        LEFT JOIN dbo.TBL_ET_GeoEntityCheckInOut g WITH (NOLOCK)
            ON g.PhysicalAppointmentId = a.PhysicalAppointmentId
            AND (
                (g.CheckIn >= @StartOfRange AND g.CheckIn < @EndOfRange)
                OR (g.CheckOut >= @StartOfRange AND g.CheckOut < @EndOfRange)
            )
        GROUP BY a.PhysicalAppointmentId
    )

    -- Return aggregate counts
    SELECT
        COUNT(*) AS TotalAppointments,
        SUM(CASE WHEN HasCheckInInRange = 1 AND HasCheckOutInRange = 1 THEN 1 ELSE 0 END) AS Completed,
        SUM(CASE WHEN HasCheckInInRange = 1 AND HasCheckOutInRange = 0 THEN 1 ELSE 0 END) AS Ongoing,
        SUM(CASE WHEN HasCheckInInRange = 0 AND HasCheckOutInRange = 0 THEN 1 ELSE 0 END) AS NotVisited
    FROM VisitFlags;

	EXEC usp_TBL_ET_ExpenseClaimList_new1 'CL', 0, '', @FromDate, @ToDate, @UserId, 0, 100
END



GO

/* ============================================================
   Procedure: [dbo].[usp_GetAppUrlVersion]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

--------------------------------------------------

CREATE   PROCEDURE [dbo].[usp_GetAppUrlVersion]--'o','',''  --- latest
    @apktype NVARCHAR(100),         
    @version NVARCHAR(50) = NULL,   
    @projectname NVARCHAR(50) = NULL 
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        -- Check if @projectname is NULL or blank
        IF @projectname IS NULL OR LTRIM(RTRIM(@projectname)) = ''
        BEGIN
            -- Return rows where apktype is 'o' and the name field starts with 'kit19'
            SELECT TOP 1 *
            FROM tbl_App_UrlVersion
            WHERE apktype = 'o' AND name LIKE 'kit19%'
            ORDER BY createddate DESC;
        END
        ELSE
        BEGIN
            -- Handle cases where @version is NULL or blank
            IF @version IS NULL OR LTRIM(RTRIM(@version)) = ''
            BEGIN
                -- Get the last inserted row based on APK type and project name if version is not provided
                SELECT TOP 1 *
                FROM tbl_App_UrlVersion
                WHERE apktype = @apktype AND projectname = @projectname
                ORDER BY createddate DESC;
            END
            ELSE
            BEGIN
                -- Get the row(s) based on APK type, version, and project name if version is provided
                SELECT *
                FROM tbl_App_UrlVersion
                WHERE apktype = @apktype AND version = @version AND projectname = @projectname
                ORDER BY createddate DESC;
            END
        END
    END TRY
    BEGIN CATCH
        EXEC usp_InsertErrorInfo; -- Log the error details using your error logging procedure
    END CATCH
END;




GO

