/* ============================================================
   Procedure: [dbo].[usp_GetBannerDetailsOnMaster]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE [dbo].[usp_GetBannerDetailsOnMaster](
	@User_Id bigint
)
as
begin
	
	--declare @User_Id bigint = 32222

	declare @M_Id bigint
	select @M_Id=M_ID from User_Detail where User_ID = @User_Id

	declare @SegmentIds nvarchar(max) = '', @BannerId bigint = 0, @tBannerId int = 0;
	drop table if exists #tblBanner
	drop table if exists #segmentUserIds
	create table #segmentUserIds ( UserId bigint)
	
	
	select Id, UserSegment, 0 as [IsProcessed] into #tblBanner from tbl_Banner_Details(nolock) where M_Id=@M_Id and IsActive=1

	while(exists(select 1 from #tblBanner where IsProcessed = 0))
	begin
		select top 1 @BannerId = Id, @SegmentIds = UserSegment from #tblBanner where IsProcessed = 0 order by id desc
		begin try
			
			if(isnull(@SegmentIds, '') <> '')
			begin
				print concat('Processing @BannerId => ', @BannerId)
				print concat('Processing @User_Id => ', @User_Id)

				insert into #segmentUserIds
				exec usp_us_GetUserIdsBySegmentIds @userSegmentIds = @SegmentIds, @onlyParentId = 0

				if(exists(select 1 from #segmentUserIds where UserId = @User_Id))
				begin
					
					set @tBannerId = @BannerId
					update #tblBanner set IsProcessed = 1
				end
			end
		end try
		begin catch
			exec usp_InsertErrorInfo
		end catch
		update #tblBanner set IsProcessed = 1 where Id = @BannerId
		truncate table #segmentUserIds
	end

	print concat('selected banner @tBannerId => ', @tBannerId)

	if(isnull(@tBannerId, 0) = 0)
	begin
		select top 1 @tBannerId = Id from tbl_Banner_Details 
			where M_Id=@M_Id and IsActive=1 and isnull(UserSegment, '') = ''
	end

	print concat('selected banner @tBannerId => ', @tBannerId)

	select 
		ID, M_Id, ParentId, UserId, BannerName, BannerBackground, Contents, BannerType, DismissOption, LastModifiedDate, 
		CreatedDate, CreatedBy, BannerBehaviour, DisappearTime, DisappearTimeUnit, IsActive, DisplayTime
	from tbl_Banner_Details(nolock) where Id = @tBannerId


end



GO

/* ============================================================
   Procedure: [dbo].[USP_GetBatchDetails]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC [dbo].[USP_GetBatchDetails]   --'8145' ,'cititest' ,5,25     
@UserID int, -- change varchar to int by abhishek       
@SenderID Varchar(20)     
AS        
BEGIN    
    
  WITH CTE (BatchID , Isallowdnd )  
  AS  
  (    
 Select  BatchID , Isallowdnd   
    From MessageDeliveryStatus  (nolock) 
    where   U_ID =@UserID AND SenderID = @SenderID   And Isallowdnd is not null     
    Group by BatchID,Isallowdnd     
   )  
   SELECT BatchID , Isallowdnd AS Priority  FROM CTE   
END 


GO

/* ============================================================
   Procedure: [dbo].[USP_GetBatchDetailsOnDay]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
CREATE   PROC [dbo].[USP_GetBatchDetailsOnDay]   --'405' ,'GSB-MDWS' ,1        
@UserID int ,   -- frm varchar 19-08-2010
@SenderID Varchar(20),    
@Day int          
AS            
BEGIN        
  IF (IsNull(@Day,0) = 1)    
  BEGIN    
  WITH CTE (BatchID , IsAllowDND )      
  AS      
  (        
	Select  BatchID , IsAllowDND       
	From SixDaysHistory1       
	where   U_ID =@UserID AND SenderID = @SenderID    AND IsAllowDND Is Not Null          
	Group by BatchID,IsAllowDND         
   )      
   SELECT BatchID , IsAllowDND AS Priority  FROM CTE       
  END      
  ELSE IF (IsNull(@Day,0) = 2)    
  BEGIN    
  WITH CTE (BatchID , IsAllowDND )      
  AS      
  (        
 Select  BatchID , IsAllowDND       
 From SixDaysHistory2       
 where   U_ID =@UserID AND SenderID = @SenderID  AND IsAllowDND Is Not Null           
 Group by BatchID,IsAllowDND         
   )      
   SELECT BatchID , IsAllowDND AS Priority  FROM CTE       
  END     
  ELSE IF (IsNull(@Day,0) = 3)    
  BEGIN    
  WITH CTE (BatchID , IsAllowDND )      
  AS      
  (        
  Select  BatchID , IsAllowDND       
  From SixDaysHistory3       
  where   U_ID =@UserID AND SenderID = @SenderID AND IsAllowDND Is Not Null             
  Group by BatchID,IsAllowDND        
   )      
   SELECT BatchID , IsAllowDND AS Priority  FROM CTE     
  END    
  ELSE IF (IsNull(@Day,0) = 4)    
  BEGIN    
  WITH CTE (BatchID , IsAllowDND )      
  AS      
  (        
  Select  BatchID , IsAllowDND        
  From SixDaysHistory4       
  where   U_ID =@UserID AND SenderID = @SenderID AND IsAllowDND Is Not Null               
  Group by BatchID,IsAllowDND     
   )      
   SELECT BatchID , IsAllowDND AS Priority   FROM CTE     
  END    
  ELSE IF (IsNull(@Day,0) = 5)    
  BEGIN    
  WITH CTE (BatchID , IsAllowDND )      
  AS      
  (        
 Select  BatchID , IsAllowDND       
 From SixDaysHistory5       
 where   U_ID =@UserID AND SenderID = @SenderID  AND IsAllowDND Is Not Null               
 Group by BatchID,IsAllowDND     
   )      
   SELECT BatchID , IsAllowDND AS Priority  FROM CTE     
  END    
  ELSE IF (IsNull(@Day,0) = 6)    
  BEGIN    
  WITH CTE (BatchID , IsAllowDND )      
  AS      
  (        
  Select  BatchID , IsAllowDND        
  From SixDaysHistory6       
  where   U_ID =@UserID AND SenderID = @SenderID  AND IsAllowDND Is Not Null            
  Group by BatchID,IsAllowDND         
   )      
   SELECT BatchID , IsAllowDND AS Priority   FROM CTE     
  END      
END   




