CREATE   PROCEDURE USP_GetBatchDetailsSummery     @BatchID NVARCHAR(50) AS BEGIN     SELECT         s.BatchID,         s.MassOperationName,         s.UserID,         s.EntityType,         d.EntityID,         s.CreatedDate,         s.IsProcessed,         s.Remarks,         s.BatchStartTime,         s.BatchEndTime,   s.ScheduleDateTime,         s.IsValid,         s.Metadata,         s.ErrorDetails     FROM         Tbl_MassOperationSummary s (NOLOCK)     INNER JOIN         Tbl_MassOperationDetails d (NOLOCK)  
   ON         s.BatchID = d.summaryid     WHERE         s.BatchID = @BatchID   AND s.MassOperationName = 'Send InternationalSMS'   and  IsProcessed = 0          AND IsValid = 1 END







GO

/* ============================================================
   Procedure: [dbo].[USP_GetBatchDetailsSummeryWithPaging]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE USP_GetBatchDetailsSummeryWithPaging          
    @BatchID BIGINT,          
    @BatchSize INT,          
    @Offset INT,          
    @ProcessedEntityIds NVARCHAR(MAX) = NULL          
AS          
BEGIN          
    SET NOCOUNT ON;          
          
    -- Create a temporary table to store the processed entity IDs          
    CREATE TABLE #ProcessedEntityIds (EntityID BIGINT);          
          
    -- Insert the processed entity IDs into the temporary table from JSON          
    IF @ProcessedEntityIds IS NOT NULL          
    BEGIN          
        INSERT INTO #ProcessedEntityIds (EntityID)          
        SELECT value FROM OPENJSON(@ProcessedEntityIds) WITH (value BIGINT);          
    END;          
          
    -- Select the required data while excluding the processed entity IDs          
    SELECT DISTINCT          
        s.BatchID,          
        s.MassOperationName,          
        s.UserID,          
        s.EntityType,          
        d.EntityID,          
        s.CreatedDate,          
        s.IsProcessed,          
        s.Remarks,          
        s.BatchStartTime,          
        s.BatchEndTime,          
        s.ScheduleDateTime,          
        s.IsValid,          
        s.Metadata,          
        s.ErrorDetails,       
  s.Parentid,      
        ROW_NUMBER() OVER (ORDER BY d.EntityID) AS SerialNo          
    INTO #TempBatchDetails          
    FROM          
        Tbl_MassOperationSummary s WITH (NOLOCK)          
    INNER JOIN          
        Tbl_MassOperationDetails d WITH (NOLOCK)          
    ON          
        s.BatchID = d.SummaryID          
    WHERE          
        s.BatchID = @BatchID          
        AND s.MassOperationName = 'Send InternationalSMS'          
        AND s.IsProcessed = 0          
        AND s.IsValid = 1          
        AND (NOT EXISTS (SELECT 1 FROM #ProcessedEntityIds p WHERE p.EntityID = d.EntityID) OR @ProcessedEntityIds IS NULL);          
          
    -- Fetch the required page of data          
    SELECT          
        BatchID,          
        MassOperationName,          
        UserID,          
        EntityType,          
        EntityID,          
        CreatedDate,          
        IsProcessed,          
        Remarks,          
        BatchStartTime,          
        BatchEndTime,          
        ScheduleDateTime,          
        IsValid,          
        Metadata,          
        ErrorDetails,      
  Parentid,      
        SerialNo          
    FROM          
        #TempBatchDetails          
    ORDER BY          
        SerialNo          
    OFFSET @Offset ROWS          
    FETCH NEXT @BatchSize ROWS ONLY;          
          
    -- Drop the temporary tables          
    DROP TABLE #ProcessedEntityIds;          
    DROP TABLE #TempBatchDetails;          
END;   


GO

/* ============================================================
   Procedure: [dbo].[USP_GetBatchDetailsSummeryWithPagingCustomButton]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

--------------------------------------------------------------------------------------------
CREATE   PROCEDURE USP_GetBatchDetailsSummeryWithPagingCustomButton  
@WebhookURL NVARCHAR(MAX),  
@BatchID BIGINT,  
@BatchSize INT,  
@Offset INT,  
@ProcessedEntityIds NVARCHAR(MAX) = NULL  
AS  
BEGIN  
    SET NOCOUNT ON;  
  
    -- Create a temporary table to store the processed entity IDs  
    CREATE TABLE #ProcessedEntityIds (EntityId BIGINT);  
  
    -- Insert the processed entity IDs into the temporary table from JSON  
    IF @ProcessedEntityIds IS NOT NULL  
    BEGIN  
        INSERT INTO #ProcessedEntityIds (EntityId)  
        SELECT value FROM OPENJSON(@ProcessedEntityIds) WITH (value BIGINT);  
    END;  
  
    -- Select the required data while excluding the processed entity IDs  
    SELECT DISTINCT  
        s.BatchID,  
        s.WebHookID,  
        s.UserID,  
        s.WebhookURL,  
        s.EntityType,  
        s.EntityId,  
        s.CreatedDate,  
        s.IsProcessed,  
        s.Params,  
        s.ErrorDetails,  
        ROW_NUMBER() OVER (ORDER BY s.EntityId) AS SerialNo  
    INTO #TempBatchDetails  
    FROM  
        tbl_cb_webhook_restbl s WITH (NOLOCK)  
    WHERE  
        s.BatchID = @BatchID  
        AND s.WebhookURL = 'http://sipapidev.kit19.com/Enquiry/SendIntlSmsOneToMany'  
        AND s.IsProcessed = 0  
        AND (NOT EXISTS (SELECT 1 FROM #ProcessedEntityIds p WHERE p.EntityId = s.EntityId) OR @ProcessedEntityIds IS NULL);  
  
    -- Fetch the required page of data  
    SELECT  
        BatchID,  
        WebHookID,  
        UserID,  
        WebhookURL,  
        EntityType,  
        EntityId,  
        CreatedDate,  
        IsProcessed,  
        Params,  
        ErrorDetails,  
        SerialNo  
    FROM  
        #TempBatchDetails  
    ORDER BY  
        SerialNo  
    OFFSET @Offset ROWS  
    FETCH NEXT @BatchSize ROWS ONLY;  
  
    -- Drop the temporary tables  
    DROP TABLE #ProcessedEntityIds;  
    DROP TABLE #TempBatchDetails;  
END;  




GO

