   Procedure: [dbo].[usp_getbatchid_mod]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROCEDURE usp_getbatchid_mod  
(@mod int=null)
as      
begin      
select top 1 batchid from clonemessagedeliverystatusless(nolock) where MessageInsertDate > dateadd(d,-1,getdate())
and 
1=case when @mod is null then 1 
when @mod is not null and batchid%4=@mod then 1 else 0 end
order by MessageID       
end





