/* ============================================================
   Procedure: [dbo].[USP_GetBatchInfoForProcess]
   ============================================================ */

SET ANSI_NULLS ON
SET QUOTED_IDENTIFIER ON

CREATE   PROC  [dbo].[USP_GetBatchInfoForProcess]  --4                                                                                  
@PROCESSTABLE INT                                                                                            
AS                                                                                            
BEGIN                                                         
DECLARE @BATCHINFOID BIGINT -- CHANGED                                                                                           
DECLARE @BATCHID BIGINT     -- CHANGED                                                                                        
DECLARE @COUNT INT, @TOTALRECORD INT,@ISALLOWDND BIT,@MESSAGEINSERTDATE DATETIME,                                                                 
@DIFFDATE INT , @CURRENTDTTIME DATETIME ,@USERFILTER NVARCHAR(200)                                              
DECLARE @QUERY NVARCHAR(MAX)                                      
DECLARE @TABLENAMECLONE VARCHAR(150)                                      
DECLARE @PROCESSTABLE_NAME VARCHAR(50)                                    
DECLARE @PROCESS_TABLE_QUERY NVARCHAR(MAX)                                    
DECLARE @PROCESS_TABLE_COUNT BIGINT                                    
          
IF @PROCESSTABLE=1                                    
BEGIN                                    
SET @PROCESSTABLE_NAME='PROCESSTABLEFIRST'                                    
END                                    
ELSE IF @PROCESSTABLE=2                                     
BEGIN                                    
SET @PROCESSTABLE_NAME='PROCESSTABLETWO'                                    
END                                    
ELSE IF @PROCESSTABLE=3                                    
BEGIN                                    
SET @PROCESSTABLE_NAME='PROCESSTABLETHREE'                                    
END                                    
ELSE IF @PROCESSTABLE=4                                    
BEGIN                                    
SET @PROCESSTABLE_NAME='PROCESSTABLEFOUR'                                    
END                                          
--ELSE IF @PROCESSTABLE=10                                    
--BEGIN                                    
--SET @PROCESSTABLE_NAME='PROCESSTABLETWO'                                    
--END                                          
          
SET @PROCESS_TABLE_QUERY='SELECT @PROCESS_TABLE_COUNT=COUNT(BATCHID),@BATCHID=BATCHID FROM  '+@PROCESSTABLE_NAME+'  WITH(NOLOCK) GROUP BY BATCHID'             
EXEC SP_EXECUTESQL @PROCESS_TABLE_QUERY,N'@PROCESS_TABLE_COUNT BIGINT OUTPUT,@BATCHID BIGINT OUTPUT', @PROCESS_TABLE_COUNT OUTPUT,@BATCHID  OUTPUT;                                      
BEGIN TRY                                         
BEGIN TRANSACTION                       
IF ISNULL(@PROCESS_TABLE_COUNT,0)=0                                    
BEGIN                                          
-- EXEC USP_INSERTRECORDSINTOQUEUELESSTHAN5APIRAGHWTEST                  
SET   @CURRENTDTTIME = GETDATE()                    
SELECT TOP 1 @BATCHINFOID = BATCHINFOID , @BATCHID = BATCHID , @TOTALRECORD =  TOTALRECORDS,                                                            
@ISALLOWDND=ISALLOWDND,@MESSAGEINSERTDATE=BATCHINSERTTIME,@USERFILTER=USERFILTER                                                             
FROM BATCHINFO  WITH(NOLOCK)   WHERE                                                    
PROCESSTABLE = @PROCESSTABLE                                                             
AND SCHEDULEDDATE <= @CURRENTDTTIME                                                 
AND ( ISPROCESS = 0 OR ISPROCESS IS NULL ) and batchid <>28399023 and bmessage not like 'User dgsjdhgh%'
ORDER BY BATCHINFOID     -- CHANGED                                      
--Commenting insertion in mymds_compare since its no longer needed 050617          
--INSERT INTO MYMDS_COMPARE                                 
--(                                  
--MESSAGEID,BATCHID,MOBILE,MESSAGE,SENDERID,MESSAGEINSERTDATE                                                                           
--,SMPPID,U_ID,ISUNICODE,ISDND,OPERATOR,MESSAGESTATUS,ISALLOWDND,LASTERROR                                                                                                        
--)                                                                                                        
--SELECT MESSAGEID,BATCHID,MOBILE,[MESSAGE],SENDERID,MESSAGEINSERTDATE,                                                                                                        
--SMPPID,U_ID,ISUNICODE,ISDND,'',ISNULL(MESSAGESTATUS,(CASE ISDND WHEN 1 THEN '3' ELSE NULL END))                                                        
--AS MESSAGESTATUS,@ISALLOWDND,(CASE MESSAGESTATUS WHEN 9 THEN 001 ELSE NULL END) FROM CLONEMESSAGEDELIVERYSTATUS                                                   
--WHERE BATCHID=@BATCHID                              
          
--SELECT @COUNT=COUNT(MOBILE) FROM CLONEMESSAGEDELIVERYSTATUS WHERE  BATCHID=@BATCHID                                        
SELECT TOP(1) @TABLENAMECLONE=TABLENAME FROM BATCHINFO  WITH(NOLOCK)  WHERE BATCHID=@BATCHID                                  
SET @QUERY='SELECT @COUNT=COUNT(BATCHID) FROM  '+@TABLENAMECLONE+' WHERE BATCHID='+CONVERT(NVARCHAR,@BATCHID)+''               
EXEC SP_EXECUTESQL @QUERY,N'@COUNT BIGINT OUTPUT', @COUNT OUTPUT;                                                        
IF (@COUNT = @TOTALRECORD)                                                                                            
BEGIN                                         
UPDATE  BATCHINFO                                                                                            
SET ISPROCESS = 1                                                                                            
WHERE BATCHINFOID = @BATCHINFOID                                                             
AND ( ISPROCESS = 0 OR ISPROCESS IS NULL ) -- CHANGED               
          
--Commenting insertion in mymds_compare since its no longer needed 050617                                                   
--INSERT INTO MYMDS_COMPARE                                                                                            (                                                                                                            
--MESSAGEID,BATCHID,MOBILE,MESSAGE,SENDERID,MESSAGEINSERTDATE ,SMPPID,U_ID,ISUNICODE,ISDND,OPERATOR,MESSAGESTATUS,ISALLOWDND,LASTERROR                                             )                       
--SELECT MESSAGEID,BATCHID,MOBILE,[MESSAGE],SENDERID,MESSAGEINSERTDATE, SMPPID,U_ID,ISUNICODE,ISDND,'',ISNULL(MESSAGESTATUS,(CASE ISDND WHEN 1 THEN '3' ELSE NULL END))                          
--AS MESSAGESTATUS,@ISALLOWDND,(CASE MESSAGESTATUS WHEN 9 THEN 001 ELSE NULL END) FROM     CLONEMESSAGEDELIVERYSTATUS WHERE BATCHID=@BATCHID              
          
SELECT BATCHINFOID,USERID,BATCHID,TOTALRECORDS,PROCESSTABLE,case when userfilter='Critical' then 1 else ISPRORITY end as ISPRORITY,ISALLOWDND,USERFILTER+'-TRUE' AS USERFILTER,USERFILTER AS 'AC_TYPE' FROM BATCHINFO WITH(NOLOCK) WHERE BATCHINFOID =       
@BATCHINFOID                                                           
END                      
ELSE           
BEGIN                                                                
SET @DIFFDATE=(SELECT DATEDIFF(MINUTE, @MESSAGEINSERTDATE, @CURRENTDTTIME))                                          IF(@DIFFDATE>6)                                                  
BEGIN                                                                
UPDATE  BATCHINFO                                                                                            
SET ISPROCESS = 1                                                                                      
WHERE BATCHINFOID = @BATCHINFOID                                                             
AND ( ISPROCESS = 0 OR ISPROCESS IS NULL ) -- CHANGED                      
SELECT BATCHINFOID,USERID,BATCHID,TOTALRECORDS,PROCESSTABLE,case when userfilter='Critical' then 1 else ISPRORITY end as ISPRORITY,      
ISALLOWDND,USERFILTER+'-TRUE' AS USERFILTER,USERFILTER AS 'AC_TYPE' FROM BATCHINFO  WITH(NOLOCK)   WHERE BATCHINFOID = @BATCHINFOID                                                  END        
                          
          
          
END                    
END                            
ELSE  IF ISNULL(@PROCESS_TABLE_COUNT,0)<>0                                       
BEGIN                                    
SELECT BATCHINFOID,USERID,BATCHID,TOTALRECORDS,PROCESSTABLE,case when userfilter='Critical' then 1 else ISPRORITY end as ISPRORITY,      
ISALLOWDND,USERFILTER+'-FALSE' AS USERFILTER,USERFILTER AS 'AC_TYPE' FROM BATCHINFO  WITH(NOLOCK)   WHERE BATCHID = ISNULL(@BATCHID,0)                                    
END                                                                 
--UPDATE BATCHINFO SET ISPROCESS=NULL WHERE BATCHID IN(SELECT BATCHID FROM CLONEMESSAGEDELIVERYSTATUS  WITH(NOLOCK) WHERE DATEDIFF(MINUTE, MESSAGEINSERTDATE, @CURRENTDTTIME)>10 AND SCHEDULEDDATE<=@CURRENTDTTIME AND BATCHID<>@BATCHID GROUP BY BATCHID)    
  
    
       
        
          
          
          
IF @@TRANCOUNT > 0                                        
COMMIT;                                                                 
END TRY                                                      
BEGIN CATCH                                         
IF @@TRANCOUNT > 0                                         
ROLLBACK;                                                      
EXEC USP_INSERTERRORINFO                                                      
END CATCH                                                         
END       
      
      
      
                                   
